// Generated by scripts/build-word-enrichment.mjs from original bilingual teaching material.
export const wordEnrichment = {"abandon":[{"pos":"v.","meaning":"放弃；停止进行","definition":"to stop pursuing an activity or plan","examples":[{"en":"The team had to abandon the climb when the storm arrived.","zh":"暴风雨来临时，队伍不得不放弃攀登。"},{"en":"We should not abandon the search while there is still hope.","zh":"只要还有希望，我们就不应放弃搜寻。"}]},{"pos":"v.","meaning":"遗弃；抛弃","definition":"to leave someone or something without care","examples":[{"en":"It is cruel to abandon a pet by the roadside.","zh":"把宠物遗弃在路边很残忍。"},{"en":"The owner decided to abandon the damaged boat.","zh":"船主决定弃置那艘损坏的船。"}]}],"abate":[{"pos":"v.","meaning":"减弱；减轻；减少","definition":"to become less intense or make something smaller","examples":[{"en":"We waited indoors for the storm to abate.","zh":"我们待在屋内等待暴风雨减弱。"},{"en":"The new measures helped abate traffic noise.","zh":"新措施有助于减轻交通噪声。"}]}],"abhorrent":[{"pos":"adj.","meaning":"可憎的；令人厌恶的","definition":"causing strong moral disgust","examples":[{"en":"The judge described the cruelty as abhorrent.","zh":"法官称这种残忍行为令人憎恶。"},{"en":"Such discrimination is abhorrent to most people.","zh":"这种歧视令大多数人深恶痛绝。"}]}],"abide":[{"pos":"v.","meaning":"遵守；信守","definition":"to obey a rule or keep an agreement, usually with by","examples":[{"en":"All residents must abide by the building's safety rules.","zh":"所有住户都必须遵守楼宇安全规定。"},{"en":"We agreed to abide by the referee's decision.","zh":"我们同意服从裁判的决定。"}]},{"pos":"v.","meaning":"容忍；忍受","definition":"to tolerate someone or something, especially in cannot abide","examples":[{"en":"I cannot abide people who deliberately waste food.","zh":"我无法容忍故意浪费食物的人。"},{"en":"She cannot abide the smell of cigarette smoke.","zh":"她受不了香烟烟雾的气味。"}]},{"pos":"v.","meaning":"居住；停留（古旧或文学用法）","definition":"to remain or live in a place, in literary usage","examples":[{"en":"The travellers chose to abide in the valley until spring.","zh":"旅人们选择留在山谷里直到春天。"},{"en":"In the old tale, the spirits abide beneath the mountain.","zh":"在那个古老传说中，精灵居住在山下。"}]}],"ability":[{"pos":"n.","meaning":"能力；本领；才能","definition":"the skill or power needed to do something","examples":[{"en":"The course improved her ability to explain complex ideas.","zh":"这门课程提高了她解释复杂概念的能力。"},{"en":"Swimming is an ability that takes practice.","zh":"游泳是一项需要练习的本领。"}]}],"abode":[{"pos":"n.","meaning":"住所；家","definition":"the place where someone lives","examples":[{"en":"Their modest abode stood beside the river.","zh":"他们简朴的住所位于河边。"},{"en":"He invited us into his new abode.","zh":"他邀请我们进入他的新居。"}]}],"abolish":[{"pos":"v.","meaning":"废除；废止","definition":"to officially end a law, practice, or institution","examples":[{"en":"The government plans to abolish the outdated tax.","zh":"政府计划废除这项过时的税。"},{"en":"Campaigners demanded that the unfair rule be abolished.","zh":"活动人士要求废除这项不公平的规定。"}]}],"abound":[{"pos":"v.","meaning":"大量存在；充满","definition":"to exist in large numbers or amounts","examples":[{"en":"Wild flowers abound in the valley during spring.","zh":"春天山谷里开满了野花。"},{"en":"The report abounds with practical suggestions.","zh":"这份报告中有许多实用建议。"}]}],"absent":[{"pos":"adj.","meaning":"不在场的；缺席的","definition":"not present in a place","examples":[{"en":"Several pupils were absent from school yesterday.","zh":"昨天有几名学生缺课。"},{"en":"Her name was absent from the final list.","zh":"最终名单上没有她的名字。"}]},{"pos":"adj.","meaning":"心不在焉的","definition":"not paying attention because of other thoughts","examples":[{"en":"He gave an absent smile and continued reading.","zh":"他心不在焉地笑了笑，继续阅读。"},{"en":"Her absent expression suggested that she was thinking about something else.","zh":"她心不在焉的表情表明她在想别的事情。"}]}],"absenteeism":[{"pos":"n.","meaning":"旷工；旷课；经常无故缺席","definition":"the repeated failure to attend work or school","examples":[{"en":"Poor working conditions can contribute to absenteeism.","zh":"恶劣的工作条件可能导致经常旷工。"},{"en":"The school contacted families to reduce student absenteeism.","zh":"学校联系了各家庭，以减少学生旷课。"}]}],"absolute":[{"pos":"adj.","meaning":"完全的；绝对的","definition":"complete and not limited in any way","examples":[{"en":"The laboratory requires absolute silence during the recording.","zh":"录音时实验室要求绝对安静。"},{"en":"There is no absolute guarantee that the plan will work.","zh":"无法绝对保证这个计划会成功。"}]}],"absorb":[{"pos":"v.","meaning":"吸收","definition":"to take in liquid, heat, light, or information","examples":[{"en":"Dry soil can absorb a surprising amount of water.","zh":"干燥的土壤能吸收出人意料多的水。"},{"en":"Children absorb new vocabulary through conversation.","zh":"孩子们通过交谈吸收新词汇。"}]},{"pos":"v.","meaning":"吸引全部注意力；使专注","definition":"to hold someone's attention completely","examples":[{"en":"The puzzle began to absorb all his attention.","zh":"这道谜题开始吸引他的全部注意力。"},{"en":"An interesting novel can absorb me for hours.","zh":"一本有趣的小说能让我专注好几个小时。"}]},{"pos":"v.","meaning":"并入；兼并","definition":"to make a smaller organization part of a larger one","examples":[{"en":"The larger company plans to absorb its rival.","zh":"这家较大的公司计划兼并竞争对手。"},{"en":"The city grew until it began to absorb nearby villages.","zh":"城市不断扩展，开始将附近的村庄纳入其中。"}]}],"abstract":[{"pos":"adj.","meaning":"抽象的；概念性的","definition":"concerned with ideas rather than concrete objects","examples":[{"en":"Young children may find abstract concepts difficult to understand.","zh":"幼儿可能觉得抽象概念难以理解。"},{"en":"The discussion became too abstract to guide practical decisions.","zh":"讨论变得过于抽象，无法指导实际决策。"}],"ipa":"/ˈæbstrækt/"},{"pos":"adj.","meaning":"抽象派的","definition":"using shapes and colours rather than realistic representations","examples":[{"en":"An abstract painting hangs above the reception desk.","zh":"接待台上方挂着一幅抽象画。"},{"en":"She uses bold colours in her abstract art.","zh":"她在抽象艺术作品中使用鲜明的色彩。"}],"ipa":"/ˈæbstrækt/"},{"pos":"n.","meaning":"摘要；梗概","definition":"a short summary of a longer piece of writing","examples":[{"en":"Please submit an abstract before sending the full paper.","zh":"请先提交摘要，再提交全文。"},{"en":"The abstract outlines the study's methods and main findings.","zh":"摘要概述了研究方法和主要发现。"}],"ipa":"/ˈæbstrækt/"},{"pos":"n.","meaning":"抽象概念；抽象状态","definition":"an idea considered separately from particular examples","examples":[{"en":"Justice is an abstract that people interpret in different ways.","zh":"正义是一个人们有不同解读的抽象概念。"},{"en":"A policy may sound reasonable in the abstract but fail in practice.","zh":"一项政策在抽象层面听起来可能合理，却在实践中失败。"}],"ipa":"/ˈæbstrækt/"},{"pos":"v.","meaning":"提取；摘录；使抽象化","definition":"to extract key information or general ideas from something","examples":[{"en":"Researchers abstract relevant data from each medical record.","zh":"研究人员从每份病历中提取相关数据。"},{"en":"We can abstract a general principle from these examples.","zh":"我们可以从这些例子中抽象出一个一般原则。"}],"ipa":"/əbˈstrækt/"}],"abstraction":[{"pos":"n.","meaning":"抽象；抽象概念","definition":"an idea separated from particular physical examples","examples":[{"en":"Freedom can seem like an abstraction until it is lost.","zh":"自由在失去之前可能像一个抽象概念。"},{"en":"The diagram uses abstraction to hide unnecessary details.","zh":"这幅图通过抽象处理隐藏不必要的细节。"}]}],"absurd":[{"pos":"adj.","meaning":"荒谬的；不合理的","definition":"extremely unreasonable or ridiculous","examples":[{"en":"It is absurd to expect one person to finish all this today.","zh":"指望一个人今天做完这些事是荒谬的。"},{"en":"The committee rejected the absurd proposal.","zh":"委员会否决了这个荒唐的提议。"}]}],"abundance":[{"pos":"n.","meaning":"大量；丰富；充足","definition":"a plentiful supply of something","examples":[{"en":"The valley has an abundance of fresh water.","zh":"这个山谷有充足的淡水。"},{"en":"Wildflowers grow in abundance beside the path.","zh":"小路旁长着大量野花。"}]}],"abuse":[{"pos":"n.","meaning":"滥用；不当使用","definition":"the harmful or improper use of something","examples":[{"en":"The investigation revealed an abuse of public funds.","zh":"调查揭露了公共资金遭到滥用。"},{"en":"The rules aim to prevent the abuse of power.","zh":"这些规则旨在防止权力滥用。"}],"ipa":"/əˈbjuːs/"},{"pos":"n.","meaning":"虐待；辱骂","definition":"cruel treatment or insulting language","examples":[{"en":"The charity supports children who have suffered abuse.","zh":"这家慈善机构帮助遭受虐待的儿童。"},{"en":"The referee received verbal abuse from the crowd.","zh":"裁判遭到了人群的辱骂。"}],"ipa":"/əˈbjuːs/"},{"pos":"v.","meaning":"滥用","definition":"to use something improperly or harmfully","examples":[{"en":"Some employers abuse their authority over workers.","zh":"一些雇主滥用对工人的管理权。"},{"en":"Do not abuse the trust your colleagues place in you.","zh":"不要滥用同事对你的信任。"}],"ipa":"/əˈbjuːz/"},{"pos":"v.","meaning":"虐待；辱骂","definition":"to treat someone cruelly or speak to them insultingly","examples":[{"en":"The law protects animals from people who abuse them.","zh":"法律保护动物免受虐待。"},{"en":"Passengers must not abuse the station staff.","zh":"乘客不得辱骂车站工作人员。"}],"ipa":"/əˈbjuːz/"}],"academic":[{"pos":"adj.","meaning":"学术的；学校的","definition":"relating to education, study, or research","examples":[{"en":"The library subscribes to many academic journals.","zh":"这家图书馆订阅了许多学术期刊。"},{"en":"Her academic interests include language development.","zh":"她的学术兴趣包括语言发展。"}]},{"pos":"adj.","meaning":"纯理论的；没有实际意义的","definition":"theoretical rather than practically important","examples":[{"en":"With the deadline already past, the argument is purely academic.","zh":"截止日期已过，这场争论只是纸上谈兵。"},{"en":"Whether we could have won is now an academic question.","zh":"我们本来能否获胜现在已经没有实际意义了。"}]},{"pos":"n.","meaning":"学者；高校教师","definition":"a person who teaches or researches at a university","examples":[{"en":"The conference attracted an academic from each university.","zh":"这次会议吸引了每所大学的一位学者参加。"},{"en":"As an academic, she divides her time between teaching and research.","zh":"作为高校教师，她在教学和研究之间分配时间。"}]}],"accelerate":[{"pos":"v.","meaning":"加速","definition":"to move or happen more quickly","examples":[{"en":"The driver began to accelerate after leaving the village.","zh":"驶离村庄后，司机开始加速。"},{"en":"Population growth may accelerate over the next decade.","zh":"未来十年人口增长可能加快。"}]},{"pos":"v.","meaning":"促进；使加快","definition":"to cause a process to happen faster","examples":[{"en":"New equipment could accelerate the construction work.","zh":"新设备可能加快施工进度。"},{"en":"The grant will accelerate research into cleaner fuels.","zh":"这笔拨款将促进清洁燃料研究。"}]}],"acceptable":[{"pos":"adj.","meaning":"可接受的；合意的","definition":"good enough to be allowed or approved","examples":[{"en":"The committee found an acceptable solution to the dispute.","zh":"委员会找到了一个各方可以接受的争议解决方案。"},{"en":"A short delay is acceptable if the work is accurate.","zh":"只要工作准确，短暂延误是可以接受的。"}]}],"access":[{"pos":"n.","meaning":"进入或使用的机会；使用权","definition":"the opportunity or right to enter or use something","examples":[{"en":"All students have access to the online library.","zh":"所有学生都能使用在线图书馆。"},{"en":"The new ramp provides wheelchair access to the hall.","zh":"新坡道方便轮椅使用者进入大厅。"}]},{"pos":"n.","meaning":"入口；通道","definition":"a way of reaching or entering a place","examples":[{"en":"The only access to the beach is a narrow path.","zh":"通往海滩的唯一路径是一条小路。"},{"en":"Keep this access clear for emergency vehicles.","zh":"请保持这条通道畅通，以供应急车辆使用。"}]},{"pos":"v.","meaning":"进入；获取；使用","definition":"to enter a system or obtain information from it","examples":[{"en":"You can access your account from any computer.","zh":"你可以通过任何电脑访问自己的账户。"},{"en":"Researchers need permission to access these records.","zh":"研究人员需要获得许可才能查阅这些记录。"}]}],"accessible":[{"pos":"adj.","meaning":"可到达的；便于进入的","definition":"easy to reach or enter","examples":[{"en":"The museum is accessible by public transport.","zh":"乘坐公共交通可以到达博物馆。"},{"en":"All entrances are accessible to wheelchair users.","zh":"所有入口均方便轮椅使用者进入。"},{"en":"The village is only accessible by boat.","zh":"这个村庄只能乘船到达。"}]}],"accessory":[{"pos":"n.","meaning":"附件；配件","definition":"an extra item used with a larger object","examples":[{"en":"A waterproof case is a useful camera accessory.","zh":"防水套是一种实用的相机配件。"},{"en":"The shop sells every accessory needed for the bicycle.","zh":"这家商店出售这辆自行车所需的各种配件。"}]},{"pos":"n.","meaning":"服饰配件；装饰品","definition":"an item worn to complement clothing","examples":[{"en":"She chose a silver belt as her only accessory.","zh":"她只选了一条银色腰带作服饰配件。"},{"en":"A scarf can be a practical winter accessory.","zh":"围巾可以是实用的冬季服饰配件。"}]},{"pos":"n.","meaning":"从犯；帮凶","definition":"a person who helps another person commit a crime","examples":[{"en":"The driver was charged as an accessory to the robbery.","zh":"司机被指控为这起抢劫案的从犯。"},{"en":"Hiding the stolen goods made him an accessory.","zh":"他因藏匿赃物而成为帮凶。"}]}],"acclaim":[{"pos":"v.","meaning":"赞扬；为……喝彩","definition":"to praise someone or something enthusiastically","examples":[{"en":"Critics acclaim the director's latest film.","zh":"评论家们高度赞扬这位导演的最新电影。"},{"en":"The crowd began to acclaim the returning champion.","zh":"人群开始为归来的冠军喝彩。"}]},{"pos":"n.","meaning":"高度赞扬；喝彩","definition":"enthusiastic public praise","examples":[{"en":"Her first novel received international acclaim.","zh":"她的第一部小说赢得了国际赞誉。"},{"en":"The performance earned widespread acclaim.","zh":"这场演出获得了广泛赞扬。"}]}],"acclimatise":[{"pos":"v.","meaning":"适应新环境；使适应气候","definition":"to become accustomed to a new climate or environment","examples":[{"en":"Climbers need time to acclimatise to the high altitude.","zh":"登山者需要时间适应高海拔。"},{"en":"The plants must acclimatise before they are moved outdoors.","zh":"这些植物必须先适应环境，才能移到室外。"}]}],"accommodation":[{"pos":"n.","meaning":"住宿；住处；膳宿","definition":"a place where someone can stay or live","examples":[{"en":"The college provides accommodation for overseas students.","zh":"学院为海外学生提供住宿。"},{"en":"We need affordable accommodation near the station.","zh":"我们需要车站附近价格合理的住处。"},{"en":"The price includes accommodation but not meals.","zh":"价格包含住宿，但不含餐食。"}]},{"pos":"n.","meaning":"适应；调整；调节","definition":"An adjustment made to fit new conditions or needs.","examples":[{"en":"The school made an accommodation for her visual needs.","zh":"学校根据她的视觉需求作了调整。"},{"en":"Successful accommodation to a new climate takes time.","zh":"成功适应新气候需要时间。"}]},{"pos":"n.","meaning":"眼的调节作用","definition":"The adjustment of the eye's focus for different distances.","examples":[{"en":"The diagram explains accommodation when looking at a nearby object.","zh":"图解说明看近处物体时眼的调节作用。"},{"en":"The researcher measured changes in visual accommodation.","zh":"研究人员测量了视觉调节的变化。"}]}],"accompany":[{"pos":"v.","meaning":"陪伴；陪同","definition":"to go somewhere with someone","examples":[{"en":"A parent must accompany each young child.","zh":"每个幼童都必须由一名家长陪同。"},{"en":"May I accompany you to the station?","zh":"我可以陪你去车站吗？"}]},{"pos":"v.","meaning":"伴随；与……同时发生","definition":"to happen or exist together with something","examples":[{"en":"Fever may accompany the infection.","zh":"这种感染可能伴随发烧。"},{"en":"Clear instructions accompany every kit.","zh":"每套工具都附有清晰的说明。"}]},{"pos":"v.","meaning":"为……伴奏","definition":"to play music while someone sings or plays another instrument","examples":[{"en":"She will accompany the singer on the piano.","zh":"她将用钢琴为那位歌手伴奏。"},{"en":"Two guitarists accompany the choir.","zh":"两名吉他手为合唱团伴奏。"}]}],"accomplish":[{"pos":"v.","meaning":"完成；实现；达成","definition":"to succeed in doing or achieving something","examples":[{"en":"The volunteers accomplished the task before sunset.","zh":"志愿者们在日落前完成了任务。"},{"en":"With careful planning, we can accomplish more in less time.","zh":"通过周密规划，我们能在更短时间内完成更多事情。"}]}],"account":[{"pos":"n.","meaning":"账户；账目","definition":"a financial record or arrangement for holding money","examples":[{"en":"I opened a savings account at the local bank.","zh":"我在当地银行开了一个储蓄账户。"},{"en":"The accountant checked every entry in the account.","zh":"会计检查了账目中的每笔记录。"}]},{"pos":"n.","meaning":"叙述；说明","definition":"a spoken or written description of events","examples":[{"en":"The witness gave a clear account of the accident.","zh":"证人清楚地叙述了事故经过。"},{"en":"Her account of the journey included several useful maps.","zh":"她的旅行记述附有几幅实用地图。"}]},{"pos":"v.","meaning":"解释；说明原因；导致（account for）","definition":"to explain something or be the reason for it","examples":[{"en":"How do you account for the missing equipment?","zh":"你如何解释设备丢失这件事？"},{"en":"Heavy rain may account for the fall in visitor numbers.","zh":"大雨可能是游客人数下降的原因。"}]},{"pos":"v.","meaning":"占（一定比例）（account for）","definition":"to form a particular share of a total","examples":[{"en":"Rent and bills account for half of my monthly spending.","zh":"房租和账单占我每月开支的一半。"},{"en":"Online orders account for most of the company's sales.","zh":"网上订单占该公司销售额的大部分。"}]}],"accountancy":[{"pos":"n.","meaning":"会计工作；会计专业","definition":"the work or profession of keeping financial accounts","examples":[{"en":"He chose accountancy as his career.","zh":"他选择会计作为职业。"},{"en":"The course introduces the principles of accountancy.","zh":"这门课程介绍会计学的基本原理。"}]}],"accountant":[{"pos":"n.","meaning":"会计师；会计人员","definition":"a person who prepares or checks financial accounts","examples":[{"en":"Our accountant checks the company's expenses every month.","zh":"我们的会计师每月核查公司的开支。"},{"en":"She trained as an accountant after leaving university.","zh":"大学毕业后，她接受了会计师培训。"}]}],"accredit":[{"pos":"v.","meaning":"正式认可；授权","definition":"to officially recognize someone as qualified or authorized","examples":[{"en":"The board will accredit the training programme next year.","zh":"委员会将于明年正式认证这项培训计划。"},{"en":"The government can accredit new diplomatic representatives.","zh":"政府可以正式委任新的外交代表。"}]},{"pos":"v.","meaning":"把……归功于；认为……具有（accredit to/with）","definition":"to attribute an achievement or quality to someone","examples":[{"en":"Historians accredit the discovery to a local engineer.","zh":"历史学家把这项发现归功于一位当地工程师。"},{"en":"Several colleagues accredit her with saving the project.","zh":"几位同事认为是她挽救了这个项目。"}]}],"accreditation":[{"pos":"n.","meaning":"认证；正式认可","definition":"official recognition that required standards have been met","examples":[{"en":"The college applied for national accreditation.","zh":"这所学院申请了国家认证。"},{"en":"Accreditation confirms that the training meets agreed standards.","zh":"认证确认这项培训符合约定的标准。"}]}],"accumulate":[{"pos":"v.","meaning":"积累；积聚；堆积","definition":"to collect or increase gradually over time","examples":[{"en":"Dust can accumulate behind the computer.","zh":"电脑后面会积灰。"},{"en":"Small monthly savings accumulate into a useful emergency fund.","zh":"每月存下的小笔钱会逐渐积累成一笔实用的应急资金。"}]}],"accuracy":[{"pos":"n.","meaning":"准确性；精确性","definition":"the degree to which something is correct or exact","examples":[{"en":"We checked the accuracy of the survey results.","zh":"我们检查了调查结果的准确性。"},{"en":"The new instrument measures distance with greater accuracy.","zh":"新仪器测量距离更加精确。"}]}],"accurate":[{"pos":"adj.","meaning":"准确的；精确的","definition":"correct and free from mistakes","examples":[{"en":"We need an accurate measurement of the room.","zh":"我们需要房间的准确测量数据。"},{"en":"The report gives an accurate account of the incident.","zh":"这份报告准确描述了事件经过。"}]}],"accustom":[{"pos":"v.","meaning":"使习惯；使适应","definition":"to make someone familiar with a new situation","examples":[{"en":"The exercises help accustom students to speaking in public.","zh":"这些练习帮助学生习惯公开演讲。"},{"en":"He gradually accustomed himself to the colder climate.","zh":"他逐渐使自己适应了更寒冷的气候。"}]}],"achievement":[{"pos":"n.","meaning":"成就；成绩","definition":"something successfully accomplished through effort","examples":[{"en":"Completing the marathon was her greatest achievement.","zh":"跑完马拉松是她最大的成就。"},{"en":"The award recognizes outstanding achievement in science.","zh":"这个奖项表彰科学领域的杰出成就。"}]},{"pos":"n.","meaning":"实现；达到","definition":"the successful reaching of a goal or standard","examples":[{"en":"Regular feedback supports the achievement of learning goals.","zh":"定期反馈有助于实现学习目标。"},{"en":"The achievement of equal access remains a challenge.","zh":"实现平等的使用机会仍是一项挑战。"}]}],"acid":[{"pos":"n.","meaning":"酸","definition":"a substance that can react with a base to form a salt","examples":[{"en":"The technician added the acid slowly.","zh":"技术员缓慢地加入酸。"},{"en":"Lemon juice contains citric acid.","zh":"柠檬汁中含有柠檬酸。"}]},{"pos":"adj.","meaning":"酸性的；酸味的","definition":"having acidic properties or a sour taste","examples":[{"en":"Some plants grow best in acid soil.","zh":"有些植物在酸性土壤中生长得最好。"},{"en":"The sauce had a sharp, acid taste.","zh":"这种酱汁有强烈的酸味。"}]},{"pos":"adj.","meaning":"尖刻的；刻薄的","definition":"sharp and hurtful in tone","examples":[{"en":"His acid remark silenced the room.","zh":"他尖刻的话让整个房间安静下来。"},{"en":"She replied with an acid smile.","zh":"她带着刻薄的微笑作了回答。"}]}],"acknowledge":[{"pos":"v.","meaning":"承认；认可","definition":"to accept or recognise that something is true","examples":[{"en":"We must acknowledge the limits of this study.","zh":"我们必须承认这项研究的局限。"},{"en":"Employers should acknowledge the contribution of their staff.","zh":"雇主应该认可员工的贡献。"},{"en":"I acknowledge that the proposal has some disadvantages.","zh":"我承认这个提议有一些缺点。"}]},{"pos":"v.","meaning":"确认收到","definition":"to confirm that something has been received","examples":[{"en":"Please acknowledge receipt of this letter.","zh":"请确认已收到这封信。"},{"en":"The office will acknowledge your application by email.","zh":"办公室将通过电子邮件确认收到你的申请。"}]},{"pos":"v.","meaning":"致意；表示注意到","definition":"to show that one has noticed someone","examples":[{"en":"The speaker paused to acknowledge a colleague in the audience.","zh":"演讲者停下来向观众席中的一位同事致意。"},{"en":"She acknowledged the guard with a brief nod.","zh":"她轻轻点头，向警卫致意。"}]},{"pos":"v.","meaning":"感谢；鸣谢","definition":"to publicly recognise someone's contribution","examples":[{"en":"The authors acknowledge the volunteers who collected the data.","zh":"作者们感谢收集数据的志愿者。"},{"en":"We would like to acknowledge the support of local businesses.","zh":"我们希望向提供支持的当地企业致谢。"}]}],"acoustic":[{"pos":"adj.","meaning":"原声的；非电声的","definition":"producing sound without electronic amplification","examples":[{"en":"He played an acoustic guitar at the small concert.","zh":"他在小型音乐会上弹奏了一把原声吉他。"},{"en":"The singer released an acoustic version of the song.","zh":"这位歌手发行了这首歌的原声版本。"}]},{"pos":"adj.","meaning":"声音的；声学的；听觉的","definition":"relating to sound or the way it is heard","examples":[{"en":"The engineers tested the room's acoustic properties.","zh":"工程师测试了房间的声学特性。"},{"en":"The device uses an acoustic signal to measure depth.","zh":"这台设备利用声信号测量深度。"}]}],"acquaint":[{"pos":"v.","meaning":"使熟悉；使了解","definition":"to make someone familiar with something","examples":[{"en":"The guide will acquaint visitors with the museum's history.","zh":"导游将向游客介绍博物馆的历史。"},{"en":"Please acquaint yourself with the safety rules.","zh":"请熟悉这些安全规则。"}]}],"acquaintance":[{"pos":"n.","meaning":"熟人","definition":"a person one knows but not closely","examples":[{"en":"An acquaintance from university recommended the course.","zh":"一位大学时期的熟人推荐了这门课程。"},{"en":"He met several old acquaintances at the conference.","zh":"他在会议上遇见了几位老熟人。"}]},{"pos":"n.","meaning":"认识；了解","definition":"knowledge of or familiarity with someone or something","examples":[{"en":"The job requires some acquaintance with accounting software.","zh":"这份工作要求对会计软件有所了解。"},{"en":"Travel gave her a closer acquaintance with the region's history.","zh":"旅行让她更深入地了解了该地区的历史。"}]}],"acquire":[{"pos":"v.","meaning":"获得；取得；学到","definition":"to gain or obtain something over time","examples":[{"en":"Students acquire practical skills during the placement.","zh":"学生在实习期间获得实践技能。"},{"en":"The museum hopes to acquire the artist's early drawings.","zh":"博物馆希望购得这位艺术家的早期素描。"}]}],"acquisition":[{"pos":"n.","meaning":"获得；习得","definition":"the process of getting something or learning a skill","examples":[{"en":"Language acquisition begins long before a child's first words.","zh":"语言习得早在孩子说出第一个词之前就已开始。"},{"en":"The acquisition of new equipment improved productivity.","zh":"新设备的购入提高了生产率。"}]},{"pos":"n.","meaning":"获得的东西；收购的企业","definition":"something obtained or a company bought by another","examples":[{"en":"The painting is the museum's latest acquisition.","zh":"这幅画是博物馆最新收藏的作品。"},{"en":"The company announced a major acquisition overseas.","zh":"这家公司宣布了一项重大的海外收购。"}]}],"acrobat":[{"pos":"n.","meaning":"杂技演员；特技演员","definition":"a performer who does difficult balancing and gymnastic movements","examples":[{"en":"The acrobat balanced on a narrow wire.","zh":"杂技演员在细钢丝上保持平衡。"},{"en":"A skilled acrobat performed a series of flips.","zh":"一位技艺娴熟的杂技演员连续翻了几个跟头。"}]}],"acrobatic":[{"pos":"adj.","meaning":"杂技的；动作灵活高难的","definition":"involving skilful balancing or gymnastic movements","examples":[{"en":"The audience applauded the acrobatic performance.","zh":"观众为杂技表演鼓掌。"},{"en":"The goalkeeper made an acrobatic leap to reach the ball.","zh":"守门员以一个高难度跃起动作够到了球。"}]}],"activate":[{"pos":"v.","meaning":"激活；启动","definition":"to make something start working","examples":[{"en":"Press the green button to activate the alarm.","zh":"按下绿色按钮即可启动警报。"},{"en":"You must activate your card before using it.","zh":"使用银行卡前必须先激活。"}]}],"actual":[{"pos":"adj.","meaning":"实际的；真实的","definition":"existing in fact rather than imagined or expected","examples":[{"en":"The actual cost was lower than our estimate.","zh":"实际费用低于我们的估算。"},{"en":"The film is based on actual events.","zh":"这部电影根据真实事件改编。"}]}],"acumen":[{"pos":"n.","meaning":"敏锐的判断力；精明","definition":"the ability to make quick and effective judgements","examples":[{"en":"Her business acumen helped the small company survive.","zh":"她精明的商业判断帮助这家小公司生存下来。"},{"en":"The role requires political acumen as well as patience.","zh":"这项工作既需要政治判断力，也需要耐心。"}]}],"acupuncture":[{"pos":"n.","meaning":"针灸；针刺疗法","definition":"a treatment using thin needles placed at specific points on the body","examples":[{"en":"The clinic offers acupuncture alongside other services.","zh":"这家诊所在其他服务之外也提供针灸。"},{"en":"She asked the practitioner to explain how acupuncture is performed.","zh":"她请执业者解释针灸的操作方法。"}]}],"acute":[{"pos":"adj.","meaning":"敏锐的；灵敏的","definition":"very sensitive or able to notice small details","examples":[{"en":"Dogs have an acute sense of smell.","zh":"狗的嗅觉很灵敏。"},{"en":"Her acute observation revealed a flaw in the design.","zh":"她敏锐的观察发现了设计中的缺陷。"}]},{"pos":"adj.","meaning":"剧烈的；严重的；急性的","definition":"severe, intense, or developing quickly","examples":[{"en":"The region faces an acute shortage of affordable housing.","zh":"该地区面临严重的可负担住房短缺。"},{"en":"He sought medical help for acute abdominal pain.","zh":"他因剧烈腹痛寻求医疗帮助。"}]}],"adapt":[{"pos":"v.","meaning":"适应；使适合","definition":"to change in order to suit new conditions","examples":[{"en":"New students often need time to adapt to university life.","zh":"新生通常需要时间适应大学生活。"},{"en":"We must adapt the timetable to the new transport schedule.","zh":"我们必须调整时间表以适应新的交通班次。"}]},{"pos":"v.","meaning":"改编","definition":"to change a work into another form","examples":[{"en":"The director plans to adapt the novel for television.","zh":"导演打算把这部小说改编成电视剧。"},{"en":"They adapted the play for a younger audience.","zh":"他们为更年轻的观众改编了这部戏剧。"}]}],"adaptation":[{"pos":"n.","meaning":"适应；适应性变化","definition":"a change that makes something suited to new conditions","examples":[{"en":"Adaptation to a new climate can take time.","zh":"适应新的气候可能需要时间。"},{"en":"Thick fur is an adaptation to cold conditions.","zh":"浓密的皮毛是对寒冷环境的适应性变化。"}]},{"pos":"n.","meaning":"改编；改编作品","definition":"a version of a work changed for a different form or purpose","examples":[{"en":"The film is an adaptation of a popular novel.","zh":"这部电影改编自一部畅销小说。"},{"en":"Her stage adaptation preserves the original ending.","zh":"她的舞台改编作品保留了原作结局。"}]}],"addict":[{"pos":"n.","meaning":"成瘾者","definition":"a person unable to stop using a substance or doing an activity","examples":[{"en":"The centre offers support to recovering drug addicts.","zh":"该中心为正在戒毒的人提供支持。"},{"en":"A gambling addict may need professional treatment.","zh":"赌博成瘾者可能需要专业治疗。"}]},{"pos":"n.","meaning":"对某事入迷的人（非正式）","definition":"someone who enjoys an activity very much","examples":[{"en":"As a coffee addict, she rarely starts work without a cup.","zh":"作为一个咖啡迷，她很少不喝咖啡就开始工作。"},{"en":"The game attracted thousands of puzzle addicts.","zh":"这款游戏吸引了成千上万的解谜爱好者。"}]}],"addiction":[{"pos":"n.","meaning":"瘾；沉溺","definition":"a strong dependence on a substance or activity","examples":[{"en":"The clinic offers support for people with alcohol addiction.","zh":"这家诊所为酒精成瘾者提供帮助。"},{"en":"His addiction to online games began to affect his sleep.","zh":"他沉迷网络游戏，开始影响睡眠。"}]}],"addition":[{"pos":"n.","meaning":"增加；添加物","definition":"something added or the act of adding it","examples":[{"en":"The addition of a second entrance improved safety.","zh":"增设第二个入口提高了安全性。"},{"en":"The new garden is a welcome addition to the school.","zh":"这座新花园是学校令人欢迎的新设施。"}]},{"pos":"n.","meaning":"加法","definition":"the mathematical operation of combining numbers","examples":[{"en":"The children are practising addition and subtraction.","zh":"孩子们正在练习加减法。"},{"en":"Check the addition before submitting the invoice.","zh":"提交发票前请核对加法计算。"}]}],"additional":[{"pos":"adj.","meaning":"额外的；附加的；追加的","definition":"added to what already exists","examples":[{"en":"An additional fee is charged for express delivery.","zh":"加急配送需要额外收费。"},{"en":"The hospital needs additional staff during winter.","zh":"医院在冬季需要更多工作人员。"}]}],"address":[{"pos":"v.","meaning":"处理；应对问题","definition":"to deal with a problem or issue","examples":[{"en":"The council must address the shortage of housing.","zh":"地方议会必须处理住房短缺问题。"},{"en":"This proposal does not address the main concern.","zh":"这个提议没有回应主要担忧。"},{"en":"Schools need to address the causes of poor attendance.","zh":"学校需要处理出勤率低的原因。"}]},{"pos":"n.","meaning":"地址","definition":"information showing where a person or place can be found","ipa":"/əˈdres/","examples":[{"en":"Please write your home address on the form.","zh":"请在表格上填写家庭地址。"},{"en":"The parcel was sent to the wrong address.","zh":"包裹被寄到了错误的地址。"},{"en":"Have you updated your postal address?","zh":"你更新邮寄地址了吗？"}]},{"pos":"v.","meaning":"给……写地址；致函","definition":"To write a destination on mail or direct a message to someone.","examples":[{"en":"Address the envelope to the admissions office.","zh":"在信封上写明寄给招生办公室。"},{"en":"She addressed her complaint to the manager.","zh":"她把投诉信写给了经理。"}]},{"pos":"v.","meaning":"向……讲话；发表演说","definition":"To speak formally to a person or group.","examples":[{"en":"The mayor addressed the assembled crowd.","zh":"市长向聚集的人群发表讲话。"},{"en":"She addressed the conference on its opening day.","zh":"她在会议开幕当天致辞。"}]},{"pos":"n.","meaning":"演说；致辞","definition":"A formal speech delivered to an audience.","examples":[{"en":"His opening address lasted ten minutes.","zh":"他的开幕致辞持续了十分钟。"},{"en":"The graduation address encouraged students to remain curious.","zh":"毕业致辞鼓励学生保持好奇心。"}]}],"adequate":[{"pos":"adj.","meaning":"足够的；合乎需要的","definition":"sufficient or suitable for a particular purpose","examples":[{"en":"The village needs an adequate supply of clean water.","zh":"这个村庄需要充足的清洁水源。"},{"en":"Her training was adequate for the task.","zh":"她接受的培训足以应付这项任务。"}]}],"adhere":[{"pos":"v.","meaning":"黏附；附着","definition":"to stick firmly to a surface","examples":[{"en":"The label will not adhere to a wet surface.","zh":"标签无法粘在潮湿的表面上。"},{"en":"Fine particles adhere to the filter.","zh":"细小颗粒附着在过滤器上。"}]},{"pos":"v.","meaning":"遵守；坚持","definition":"to follow a rule, belief, or plan closely","examples":[{"en":"Contractors must adhere to the safety guidelines.","zh":"承包商必须遵守安全指南。"},{"en":"Despite the pressure, she adhered to her principles.","zh":"尽管面临压力，她仍坚持自己的原则。"}]}],"adjacent":[{"pos":"adj.","meaning":"邻近的；毗连的","definition":"next to or very close to something","examples":[{"en":"The laboratory is adjacent to the main library.","zh":"实验室紧挨着主图书馆。"},{"en":"We booked two adjacent rooms for the family.","zh":"我们为一家人订了两个相邻的房间。"}]}],"adjunct":[{"pos":"n.","meaning":"附属物；辅助事物","definition":"something added to another thing to help it","examples":[{"en":"The workbook is a useful adjunct to the course.","zh":"这本练习册是课程的有用辅助材料。"},{"en":"Exercise can be an adjunct to a broader treatment plan.","zh":"运动可以作为更全面治疗方案的辅助手段。"}]},{"pos":"n.","meaning":"附加语；修饰语","definition":"an optional element that adds information to a clause","examples":[{"en":"In this sentence, the time expression is an adjunct.","zh":"在这个句子中，时间短语是附加语。"},{"en":"An adjunct can tell us where an action happened.","zh":"附加语可以说明动作发生的地点。"}]}],"adjust":[{"pos":"v.","meaning":"调整；调节；校准","definition":"to change something slightly so that it works better","examples":[{"en":"You can adjust the height of the chair.","zh":"你可以调整椅子的高度。"},{"en":"The technician adjusted the instrument before taking measurements.","zh":"技术员在测量前校准了仪器。"}]},{"pos":"v.","meaning":"适应；使适应","definition":"to become or make someone comfortable with a new situation","examples":[{"en":"New students need time to adjust to university life.","zh":"新生需要时间适应大学生活。"},{"en":"She adjusted her routine to fit the new timetable.","zh":"她调整了日常安排，以适应新的时间表。"}]}],"administer":[{"pos":"v.","meaning":"管理；掌管","definition":"to manage an organization or system","examples":[{"en":"A small team will administer the scholarship programme.","zh":"一个小团队将管理这项奖学金计划。"},{"en":"The council administers several public housing schemes.","zh":"市政委员会管理着几项公共住房计划。"}]},{"pos":"v.","meaning":"给予；施用（药物或治疗）","definition":"to give a medicine or treatment","examples":[{"en":"Only trained staff may administer this medicine.","zh":"只有受过培训的工作人员才能给予这种药物。"},{"en":"The nurse prepared to administer the prescribed injection.","zh":"护士准备注射医嘱规定的药物。"}]}],"administration":[{"pos":"n.","meaning":"管理；行政事务","definition":"the organization and management of an institution","examples":[{"en":"The job involves the administration of research grants.","zh":"这份工作涉及科研经费的管理。"},{"en":"Good administration keeps the hospital running smoothly.","zh":"良好的管理使医院运转顺畅。"}]},{"pos":"n.","meaning":"行政部门；政府","definition":"the people who manage an institution or govern a country","examples":[{"en":"The university administration approved the new course.","zh":"大学管理部门批准了这门新课程。"},{"en":"The new administration promised to improve public transport.","zh":"新一届政府承诺改善公共交通。"}]}],"administrative":[{"pos":"adj.","meaning":"行政的；管理的","definition":"relating to organising and managing an institution","examples":[{"en":"The new system reduces administrative work.","zh":"新系统减少了行政工作。"},{"en":"She applied for an administrative position at the college.","zh":"她申请了学院的一个行政职位。"}]}],"administrator":[{"pos":"n.","meaning":"管理人员；行政人员","definition":"a person who manages an organization or its work","examples":[{"en":"The school administrator handles student records.","zh":"学校行政人员负责学生档案。"},{"en":"Ask the system administrator to reset your account.","zh":"请系统管理员重置你的账户。"}]}],"admission":[{"pos":"n.","meaning":"准许进入；入学资格","definition":"permission to enter a place or join an institution","examples":[{"en":"Admission to the programme requires an interview.","zh":"进入这个项目需要经过面试。"},{"en":"Admission to the museum is free on Sundays.","zh":"博物馆周日免费开放。"}]},{"pos":"n.","meaning":"入场费","definition":"the amount paid to enter a place","examples":[{"en":"The ticket price includes admission to the gardens.","zh":"票价包含花园的入场费。"},{"en":"Children under five pay no admission.","zh":"五岁以下儿童免收门票。"}]},{"pos":"n.","meaning":"承认；供认","definition":"a statement accepting that something is true","examples":[{"en":"His apology included an admission of responsibility.","zh":"他的道歉中包含对责任的承认。"},{"en":"The letter was not an admission of guilt.","zh":"这封信并不是认罪书。"}]}],"admit":[{"pos":"v.","meaning":"承认","definition":"to accept that something is true","examples":[{"en":"He admitted that he had made a mistake.","zh":"他承认自己犯了错误。"},{"en":"It is difficult to admit that a plan has failed.","zh":"承认一项计划失败是很难的。"}]},{"pos":"v.","meaning":"准许进入；接收","definition":"to allow someone to enter or join a place or organisation","examples":[{"en":"The museum admits children under five free of charge.","zh":"博物馆允许五岁以下儿童免费入场。"},{"en":"The university admitted her to its engineering programme.","zh":"大学录取她进入工程学课程。"}]}],"adobe":[{"pos":"n.","meaning":"土坯；泥砖","definition":"a building material made from earth dried in the sun","examples":[{"en":"The village houses were built from adobe.","zh":"村里的房屋是用土坯建成的。"},{"en":"Workers repaired the damaged adobe wall before winter.","zh":"工人们在入冬前修好了受损的泥砖墙。"}]}],"adolescence":[{"pos":"n.","meaning":"青春期","definition":"the period between childhood and adulthood","examples":[{"en":"Friendships often change during adolescence.","zh":"友谊常常在青春期发生变化。"},{"en":"The book explores the challenges of adolescence.","zh":"这本书探讨青春期面临的挑战。"}]}],"adolescent":[{"pos":"n.","meaning":"青少年","definition":"a young person between childhood and adulthood","examples":[{"en":"Many adolescents value time with their friends.","zh":"许多青少年重视与朋友相处的时间。"},{"en":"The survey asked adolescents about their sleeping habits.","zh":"这项调查询问了青少年的睡眠习惯。"}]},{"pos":"adj.","meaning":"青春期的；青少年的","definition":"relating to the period between childhood and adulthood","examples":[{"en":"Regular exercise supports adolescent health.","zh":"规律运动有助于青少年健康。"},{"en":"The study examines adolescent behaviour online.","zh":"这项研究考察青少年的网络行为。"}]}],"adopt":[{"pos":"v.","meaning":"采用","definition":"to begin using a method or idea","examples":[{"en":"Schools may adopt new teaching methods.","zh":"学校可能采用新的教学方法。"},{"en":"Businesses need time to adopt new technology.","zh":"企业需要时间来采用新技术。"},{"en":"The council agreed to adopt the proposed policy.","zh":"地方议会同意采用这项拟议政策。"}]},{"pos":"v.","meaning":"收养；领养","definition":"To legally take a child into one's family or take an animal into one's care.","examples":[{"en":"The couple adopted a young child.","zh":"这对夫妇收养了一个幼儿。"},{"en":"They adopted a dog from the local shelter.","zh":"他们从当地收容所领养了一只狗。"}]},{"pos":"v.","meaning":"正式通过；批准","definition":"To formally accept a proposal or resolution.","examples":[{"en":"The committee adopted the resolution unanimously.","zh":"委员会一致通过了决议。"},{"en":"The assembly adopted a revised constitution.","zh":"大会通过了修订后的章程。"}]}],"advance":[{"pos":"adj.","meaning":"预先的；事先的","definition":"done or provided before something happens","examples":[{"en":"Advance booking is essential for this tour.","zh":"参加这次旅行必须提前预订。"},{"en":"We received advance notice of the road closure.","zh":"我们提前收到了封路通知。"}]},{"pos":"v.","meaning":"前进；推进；取得进展","definition":"to move forward or make progress","examples":[{"en":"The hikers could not advance through the deep snow.","zh":"徒步者无法在深雪中继续前进。"},{"en":"The discovery may advance our understanding of memory.","zh":"这一发现可能推进我们对记忆的理解。"}]},{"pos":"v.","meaning":"预付；提前支付","definition":"to pay money before it is normally due","examples":[{"en":"The employer agreed to advance part of her salary.","zh":"雇主同意预付她的部分工资。"},{"en":"The bank may advance funds for the purchase.","zh":"银行可能为此次购买预先提供资金。"}]},{"pos":"n.","meaning":"进步；前进；增长","definition":"progress or movement forward","examples":[{"en":"The vaccine represents a major advance in medicine.","zh":"这种疫苗代表了医学上的重大进步。"},{"en":"There was a steady advance in the company's share price.","zh":"这家公司的股价稳步上涨。"}]},{"pos":"n.","meaning":"预付款","definition":"money paid before it is earned or due","examples":[{"en":"The writer received an advance for her next book.","zh":"这位作家收到了下一本书的预付稿酬。"},{"en":"He asked for an advance on next month's wages.","zh":"他请求预支下个月的工资。"}]}],"advanced":[{"pos":"adj.","meaning":"先进的；高级的","definition":"highly developed or at a high level","examples":[{"en":"The laboratory uses advanced imaging equipment.","zh":"实验室使用先进的成像设备。"},{"en":"This course is designed for advanced learners.","zh":"这门课程为高级学习者设计。"}]}],"advantage":[{"pos":"n.","meaning":"优势；好处","definition":"a useful or favourable feature","examples":[{"en":"One advantage of remote work is less commuting.","zh":"远程工作的一个好处是减少通勤。"},{"en":"Small classes offer an advantage for individual feedback.","zh":"小班教学在提供个别反馈方面有优势。"},{"en":"The main advantage of this option is its lower cost.","zh":"这个选项的主要优势是成本较低。"}]}],"advantageous":[{"pos":"adj.","meaning":"有利的；有益的","definition":"giving someone a benefit or advantage","examples":[{"en":"The new agreement is advantageous to both companies.","zh":"新协议对两家公司都有利。"},{"en":"An early start would be advantageous in hot weather.","zh":"天气炎热时早点出发会更有利。"}]}],"advent":[{"pos":"n.","meaning":"出现；到来","definition":"the arrival of a notable event, person, or development","examples":[{"en":"The advent of smartphones changed how people communicate.","zh":"智能手机的出现改变了人们的沟通方式。"},{"en":"The advent of spring brought visitors back to the gardens.","zh":"春天的到来使游客重新来到园林。"}]}],"adventure":[{"pos":"n.","meaning":"冒险；奇遇","definition":"an unusual and exciting experience","examples":[{"en":"Exploring the island became an unforgettable adventure.","zh":"探索这座岛成了一次难忘的冒险。"},{"en":"The children listened eagerly to her travel adventures.","zh":"孩子们热切地听她讲旅行中的奇遇。"}]}],"adventurous":[{"pos":"adj.","meaning":"爱冒险的；勇于尝试的","definition":"willing to take risks or try new things","examples":[{"en":"My adventurous sister enjoys exploring remote places.","zh":"我爱冒险的姐姐喜欢探索偏远地区。"},{"en":"Be more adventurous when choosing something to cook.","zh":"选择菜肴时可以更大胆地尝试新东西。"}]},{"pos":"adj.","meaning":"充满冒险的；刺激的","definition":"involving unusual experiences or danger","examples":[{"en":"They returned from an adventurous journey through the mountains.","zh":"他们结束了一次充满冒险的山区旅行。"},{"en":"The novel describes an adventurous life at sea.","zh":"这部小说描绘了充满惊险的海上生活。"}]}],"adverse":[{"pos":"adj.","meaning":"不利的；有害的","definition":"having an unfavourable or harmful effect","examples":[{"en":"Heavy rain had an adverse effect on the harvest.","zh":"大雨对收成产生了不利影响。"},{"en":"The project continued despite adverse economic conditions.","zh":"尽管经济条件不利，该项目仍继续进行。"}]}],"advertise":[{"pos":"v.","meaning":"做广告；宣传；公告","definition":"to make something publicly known in order to attract interest","examples":[{"en":"The shop will advertise its opening in the local paper.","zh":"这家商店将在当地报纸上刊登开业广告。"},{"en":"The university advertises research positions on its website.","zh":"这所大学在网站上公布科研岗位。"}]}],"advertisement":[{"pos":"n.","meaning":"广告；公告","definition":"a public message promoting something or announcing information","examples":[{"en":"I found the course through a newspaper advertisement.","zh":"我是通过报纸广告找到这门课程的。"},{"en":"The advertisement includes the shop's opening hours.","zh":"这则广告包含商店的营业时间。"}]}],"advice":[{"pos":"n.","meaning":"建议；忠告；意见","definition":"guidance about what someone should do","examples":[{"en":"The tutor gave me useful advice about revision.","zh":"导师给了我有关复习的实用建议。"},{"en":"You should seek medical advice before changing your treatment.","zh":"改变治疗方案前，你应该征求医生的意见。"}]}],"advisable":[{"pos":"adj.","meaning":"明智的；可取的；适当的","definition":"sensible and worth doing in the circumstances","examples":[{"en":"It is advisable to book a seat in advance.","zh":"提前订座是明智的。"},{"en":"Taking a paper map is advisable in this remote area.","zh":"在这片偏远地区携带纸质地图是适当的。"}]}],"advocate":[{"pos":"v.","meaning":"提倡；拥护；支持","definition":"to publicly support an idea or course of action","examples":[{"en":"Many teachers advocate smaller class sizes.","zh":"许多教师提倡缩小班级规模。"},{"en":"The group continues to advocate peaceful reform.","zh":"这个团体继续倡导和平改革。"}],"ipa":"/ˈædvəkeɪt/"},{"pos":"n.","meaning":"拥护者；提倡者","definition":"a person who publicly supports a cause","examples":[{"en":"She is an advocate for accessible public transport.","zh":"她是无障碍公共交通的倡导者。"},{"en":"A strong advocate of cycling spoke at the meeting.","zh":"一位积极支持骑行的人在会上发言。"}],"ipa":"/ˈædvəkət/"}],"aeration":[{"pos":"n.","meaning":"充气；曝气；通气","definition":"the introduction or circulation of air in a material","examples":[{"en":"Aeration helps oxygen reach the roots of the grass.","zh":"通气有助于氧气到达草根。"},{"en":"The tank uses aeration to increase oxygen in the water.","zh":"这个水箱通过曝气增加水中的氧气。"}]}],"aerobics":[{"pos":"n.","meaning":"有氧健身操","definition":"energetic exercises often performed to music","examples":[{"en":"She attends an aerobics class twice a week.","zh":"她每周上两次有氧健身操课。"},{"en":"The sports centre offers low-impact aerobics for beginners.","zh":"体育中心为初学者提供低冲击有氧健身操。"}]}],"aeronautics":[{"pos":"n.","meaning":"航空学","definition":"the study of aircraft and flight","examples":[{"en":"He hopes to study aeronautics at university.","zh":"他希望在大学学习航空学。"},{"en":"The exhibition explains basic principles of aeronautics.","zh":"这次展览介绍航空学的基本原理。"}]}],"aeroplane":[{"pos":"n.","meaning":"飞机","definition":"a powered aircraft with fixed wings","examples":[{"en":"The aeroplane circled the airport before landing.","zh":"飞机在降落前绕机场盘旋。"},{"en":"She watched an aeroplane disappear into the clouds.","zh":"她看着一架飞机消失在云层中。"}]}],"aerospace":[{"pos":"n.","meaning":"航空航天领域；大气层与外层空间","definition":"the field of aircraft and spacecraft technology","examples":[{"en":"Many aerospace companies recruit mechanical engineers.","zh":"许多航空航天企业招聘机械工程师。"},{"en":"The university opened a new aerospace research centre.","zh":"这所大学开设了新的航空航天研究中心。"}]}],"aesthetic":[{"pos":"adj.","meaning":"审美的；美学的","definition":"relating to beauty and the appreciation of it","examples":[{"en":"The architect considered both practical and aesthetic requirements.","zh":"建筑师兼顾了实用和审美要求。"},{"en":"The garden has considerable aesthetic appeal.","zh":"这座花园有很强的审美吸引力。"}]}],"affect":[{"pos":"v.","meaning":"影响","definition":"to cause a change in someone or something","examples":[{"en":"Poor sleep can affect your concentration.","zh":"睡眠不足会影响注意力。"},{"en":"The new road will affect several nearby villages.","zh":"新公路将影响附近的几个村庄。"}]},{"pos":"v.","meaning":"使感染；侵袭","definition":"to cause illness or damage in a body or organism","examples":[{"en":"The disease mainly affects young trees.","zh":"这种疾病主要侵袭幼树。"},{"en":"The infection can affect both lungs.","zh":"感染可能累及双肺。"}]},{"pos":"v.","meaning":"打动；使感动","definition":"to produce a strong emotional response","examples":[{"en":"Her account of the journey deeply affected the audience.","zh":"她对旅程的讲述深深打动了观众。"},{"en":"The loss affected him more than he expected.","zh":"这次损失对他的情绪影响超出了预期。"}]}],"afflict":[{"pos":"v.","meaning":"使苦恼；折磨","definition":"to cause serious trouble or suffering","examples":[{"en":"Drought continues to afflict farming communities.","zh":"干旱持续困扰着农业社区。"},{"en":"The illness can afflict people of any age.","zh":"这种疾病可能折磨任何年龄的人。"}]}],"afflicting":[{"pos":"adj.","meaning":"令人痛苦的；使人苦恼的","definition":"causing suffering or distress","examples":[{"en":"The letter brought afflicting news about their friend.","zh":"这封信带来了有关他们朋友的令人痛心的消息。"},{"en":"He wrote about the afflicting effects of prolonged isolation.","zh":"他写到了长期孤立带来的痛苦影响。"}]},{"pos":"v.","meaning":"使受折磨；困扰（afflict 的现在分词）","definition":"causing someone or something pain or difficulty","examples":[{"en":"The drought is afflicting farming communities across the region.","zh":"干旱正困扰着整个地区的农业社区。"},{"en":"Doctors discussed the illness afflicting the patient.","zh":"医生们讨论了折磨这名患者的疾病。"}]}],"affluent":[{"pos":"adj.","meaning":"富裕的；富足的","definition":"having a great deal of money or material resources","examples":[{"en":"The shop is in an affluent suburb.","zh":"这家商店位于一个富裕的郊区。"},{"en":"Even affluent societies can have serious inequality.","zh":"即使富裕的社会也可能存在严重的不平等。"}]}],"afford":[{"pos":"v.","meaning":"负担得起","definition":"to have enough money or time for something","examples":[{"en":"We cannot afford a larger apartment this year.","zh":"我们今年买不起更大的公寓。"},{"en":"Can you afford to take a whole week off?","zh":"你能抽出整整一周时间休假吗？"}]}],"affordable":[{"pos":"adj.","meaning":"负担得起的","definition":"not too expensive for someone to buy","examples":[{"en":"The town needs more affordable housing.","zh":"这个城镇需要更多人们负担得起的住房。"},{"en":"Public transport should be affordable for everyone.","zh":"公共交通应该让每个人都负担得起。"},{"en":"We found an affordable hotel close to the beach.","zh":"我们找到了一家靠近海滩且价格可承受的酒店。"}]}],"afield":[{"pos":"adv.","meaning":"到远处；在远方","definition":"at or to a distance from one's usual area","examples":[{"en":"We travelled further afield to find quieter beaches.","zh":"我们去了更远的地方，寻找更安静的海滩。"},{"en":"The festival attracts visitors from as far afield as Australia.","zh":"这个节日吸引了远至澳大利亚的游客。"}]},{"pos":"adv.","meaning":"离题地；偏离原有范围地","definition":"away from the original subject or area of activity","examples":[{"en":"The discussion wandered too far afield.","zh":"讨论偏离主题太远了。"},{"en":"Her research now ranges further afield than economic history.","zh":"她的研究现在拓展到了经济史以外更广的领域。"}]},{"pos":"adv.","meaning":"在田野；到野外或战场（文学或旧用）","definition":"in or into open country or a field of action","examples":[{"en":"The hunters were already afield at dawn.","zh":"黎明时猎人们已经到了野外。"},{"en":"With the army afield, the capital was poorly defended.","zh":"军队在外征战时，首都的防御很薄弱。"}]}],"agency":[{"pos":"n.","meaning":"机构；代理机构","definition":"an organization that provides a service","examples":[{"en":"A recruitment agency helped him find temporary work.","zh":"一家招聘机构帮他找到了临时工作。"},{"en":"The environmental agency published its annual report.","zh":"环保机构发布了年度报告。"}]},{"pos":"n.","meaning":"代理；作用；自主行动能力","definition":"the action or capacity of acting on someone's behalf or independently","examples":[{"en":"The agreement defines the terms of agency between the firms.","zh":"协议规定了两家公司之间的代理条款。"},{"en":"Giving pupils more choices can strengthen their sense of agency.","zh":"给学生更多选择能够增强他们的自主感。"}]}],"agenda":[{"pos":"n.","meaning":"议程；待办事项","definition":"a list of matters to be discussed or dealt with","examples":[{"en":"Housing is the first item on today's agenda.","zh":"住房问题是今天议程上的第一项。"},{"en":"Please send the agenda before the meeting.","zh":"请在开会前发出议程。"}]}],"aggravate":[{"pos":"v.","meaning":"加重；恶化","definition":"to make a bad situation or condition worse","examples":[{"en":"Dust may aggravate breathing problems.","zh":"灰尘可能加重呼吸问题。"},{"en":"Delays in delivering supplies aggravated the crisis.","zh":"物资运送延迟加剧了危机。"}]}],"aggravation":[{"pos":"n.","meaning":"加重；恶化","definition":"the act of making a problem more serious","examples":[{"en":"The report links the delay to an aggravation of the crisis.","zh":"报告指出延误使危机加剧。"},{"en":"Repeated strain may cause an aggravation of the old injury.","zh":"反复受力可能使旧伤加重。"}]},{"pos":"n.","meaning":"恼怒；烦心事","definition":"annoyance or something that causes it","examples":[{"en":"The broken printer caused endless aggravation.","zh":"坏掉的打印机让人烦恼不已。"},{"en":"She wanted to avoid the aggravation of another dispute.","zh":"她想避免再次争吵带来的烦恼。"}]}],"aggressive":[{"pos":"adj.","meaning":"挑衅的；好斗的；有侵略性的","definition":"ready to attack or behave with hostility","examples":[{"en":"The driver became aggressive when questioned.","zh":"被询问时，那名司机变得很有攻击性。"},{"en":"The country condemned its neighbour's aggressive actions.","zh":"这个国家谴责了邻国的侵略行为。"}]},{"pos":"adj.","meaning":"积极进取的；强有力的","definition":"acting with great energy and determination","examples":[{"en":"The company launched an aggressive marketing campaign.","zh":"这家公司发起了一场强势营销活动。"},{"en":"An aggressive approach helped the team recover lost sales.","zh":"积极进取的策略帮助团队挽回了销售损失。"}]}],"aggressiveness":[{"pos":"n.","meaning":"攻击性；好斗；侵略性","definition":"a tendency to attack or behave forcefully towards others","examples":[{"en":"The trainer looked for signs of aggressiveness in the dog.","zh":"训练员观察这只狗是否有攻击性迹象。"},{"en":"His aggressiveness made calm negotiation difficult.","zh":"他的好斗态度使平静协商变得困难。"}]},{"pos":"n.","meaning":"积极进取；强劲程度","definition":"determination to compete or act energetically","examples":[{"en":"The company's aggressiveness in entering new markets surprised rivals.","zh":"这家公司开拓新市场时的进取劲头令竞争对手惊讶。"},{"en":"The coach praised the team's controlled aggressiveness.","zh":"教练赞扬了球队有节制的进攻积极性。"}]}],"agile":[{"pos":"adj.","meaning":"敏捷的；灵活机敏的","definition":"able to move or think quickly and easily","examples":[{"en":"The agile cat climbed onto the narrow fence.","zh":"那只敏捷的猫爬上了狭窄的围栏。"},{"en":"An agile team can respond quickly to new evidence.","zh":"灵活的团队能够迅速回应新证据。"}]}],"agriculture":[{"pos":"n.","meaning":"农业；农学","definition":"the practice or study of farming","examples":[{"en":"Agriculture remains the region's largest employer.","zh":"农业仍是这个地区提供就业最多的行业。"},{"en":"She is studying agriculture and soil management.","zh":"她正在学习农学和土壤管理。"}]}],"ailment":[{"pos":"n.","meaning":"小病；轻微不适","definition":"an illness, especially a relatively minor one","examples":[{"en":"The clinic treats common ailments such as sore throats.","zh":"诊所治疗喉咙痛等常见小病。"},{"en":"Rest may ease a minor ailment, but persistent symptoms need attention.","zh":"休息可能缓解轻微不适，但持续症状需要重视。"}]}],"airtight":[{"pos":"adj.","meaning":"密不透气的","definition":"sealed so that air cannot pass through","examples":[{"en":"Keep the biscuits in an airtight container.","zh":"把饼干放在密封容器里。"},{"en":"The technician checked whether the chamber was airtight.","zh":"技术员检查了这个舱室是否气密。"}]},{"pos":"adj.","meaning":"无懈可击的","definition":"so well designed that it cannot easily be challenged","examples":[{"en":"The lawyer presented an airtight argument.","zh":"律师提出了无懈可击的论证。"},{"en":"We need an airtight plan for protecting the data.","zh":"我们需要一个严密可靠的数据保护计划。"}]}],"aisle":[{"pos":"n.","meaning":"过道；通道","definition":"a passage between rows of seats or shelves","examples":[{"en":"Please keep the aisle clear during the performance.","zh":"演出期间请保持过道畅通。"},{"en":"The cereal is in the next aisle.","zh":"谷物早餐食品在下一条货架通道。"}]},{"pos":"n.","meaning":"教堂的侧廊","definition":"a side passage in a church","examples":[{"en":"Sunlight fell across the church's narrow aisle.","zh":"阳光照在教堂狭窄的侧廊上。"},{"en":"Visitors walked quietly along the north aisle.","zh":"游客沿着北侧廊安静地行走。"}]}],"alarm":[{"pos":"n.","meaning":"惊恐；担忧","definition":"a feeling of fear or concern about danger","examples":[{"en":"The sudden cracking sound caused widespread alarm.","zh":"突然的断裂声引起了普遍的惊慌。"},{"en":"She watched with alarm as the water rose.","zh":"她惊恐地看着水位上涨。"}]},{"pos":"n.","meaning":"警报；报警器","definition":"a warning signal or a device that produces it","examples":[{"en":"The fire alarm sounded during the meeting.","zh":"会议期间，火警警报响了。"},{"en":"They installed an alarm to protect the shop.","zh":"他们安装了报警器来保护商店。"}]},{"pos":"n.","meaning":"闹钟","definition":"a clock or device that wakes someone at a set time","examples":[{"en":"I set the alarm for six o'clock.","zh":"我把闹钟设在六点。"},{"en":"My alarm failed to wake me this morning.","zh":"今天早晨闹钟没能叫醒我。"}]},{"pos":"v.","meaning":"使惊恐；使担心","definition":"to make someone frightened or worried","examples":[{"en":"The smell of gas alarmed the residents.","zh":"煤气味使住户们担心起来。"},{"en":"Do not be alarmed by the machine's normal clicking sound.","zh":"不要因为机器正常的咔嗒声而惊慌。"}]}],"albeit":[{"pos":"conj.","meaning":"虽然；尽管","definition":"although or even though","examples":[{"en":"The service is useful, albeit expensive.","zh":"这项服务很有用，尽管价格昂贵。"},{"en":"The team made progress, albeit more slowly than expected.","zh":"团队取得了进展，尽管比预期慢。"}]}],"alchemist":[{"pos":"n.","meaning":"炼金术士","definition":"a person who historically sought to transform substances, especially metals into gold","examples":[{"en":"The alchemist kept his experiments secret.","zh":"那位炼金术士对自己的实验保密。"},{"en":"A painting shows an alchemist working beside a furnace.","zh":"一幅画描绘了一名炼金术士在炉旁工作。"}]}],"alcohol":[{"pos":"n.","meaning":"酒精","definition":"the chemical substance in alcoholic drinks","examples":[{"en":"The solution contains a small amount of alcohol.","zh":"这种溶液含有少量酒精。"},{"en":"Alcohol evaporates faster than water under the same conditions.","zh":"在相同条件下，酒精比水蒸发得更快。"}]},{"pos":"n.","meaning":"酒；含酒精饮料","definition":"drinks that contain alcohol","examples":[{"en":"Alcohol is not sold in this restaurant.","zh":"这家餐厅不出售酒类。"},{"en":"He decided to avoid alcohol before the race.","zh":"他决定在比赛前不喝酒。"}]}],"alert":[{"pos":"adj.","meaning":"警觉的；留意的","definition":"quick to notice danger or changes","examples":[{"en":"Drivers must remain alert on this narrow road.","zh":"驾驶员在这条狭窄道路上必须保持警觉。"},{"en":"She was alert to the risks of sharing personal data.","zh":"她对分享个人数据的风险保持警惕。"}]},{"pos":"n.","meaning":"警报；警戒","definition":"a warning or a state of readiness for danger","examples":[{"en":"The weather alert warned of heavy snowfall.","zh":"天气警报提醒人们注意大雪。"},{"en":"The hospital remained on alert throughout the night.","zh":"医院整夜保持警戒状态。"}]},{"pos":"v.","meaning":"提醒；使警觉","definition":"to warn someone about a danger or problem","examples":[{"en":"The sensor will alert staff if the door opens.","zh":"如果门被打开，传感器会向工作人员报警。"},{"en":"Residents alerted the council to the damaged bridge.","zh":"居民提醒市政委员会注意桥梁损坏的问题。"}]}],"algebra":[{"pos":"n.","meaning":"代数","definition":"mathematics using symbols to represent numbers and relationships","examples":[{"en":"We use algebra to solve equations with unknown values.","zh":"我们用代数求解含未知数的方程。"},{"en":"The first chapter reviews elementary algebra.","zh":"第一章复习初等代数。"}]}],"algorithm":[{"pos":"n.","meaning":"算法","definition":"a set of steps for solving a problem","examples":[{"en":"The algorithm recommends videos based on viewing history.","zh":"该算法根据观看历史推荐视频。"},{"en":"An algorithm can help detect unusual transactions.","zh":"算法可以帮助发现异常交易。"},{"en":"A poorly designed algorithm may produce unfair results.","zh":"设计不良的算法可能产生不公平的结果。"}]}],"alienate":[{"pos":"v.","meaning":"使疏远；使不友好","definition":"to make someone feel excluded or hostile","examples":[{"en":"Ignoring complaints may alienate loyal customers.","zh":"无视投诉可能使忠实顾客疏远。"},{"en":"The policy risks alienating younger voters.","zh":"这项政策可能使年轻选民产生反感。"}]},{"pos":"v.","meaning":"转让（财产或权利）","definition":"to transfer ownership or a legal right","examples":[{"en":"The trust cannot alienate the land without approval.","zh":"未经批准，信托机构不得转让这片土地。"},{"en":"The agreement limits their power to alienate property.","zh":"协议限制了他们转让财产的权力。"}]}],"alienation":[{"pos":"n.","meaning":"疏离；疏远；离间","definition":"a feeling of separation from other people or society","examples":[{"en":"Moving repeatedly increased her sense of alienation.","zh":"反复搬家加深了她的疏离感。"},{"en":"The policy contributed to alienation between residents and officials.","zh":"这项政策加剧了居民与官员之间的疏远。"}]}],"alight":[{"pos":"adj.","meaning":"燃烧着的；点着的","definition":"burning or lit","examples":[{"en":"A candle was still alight in the window.","zh":"窗边的一支蜡烛仍燃着。"},{"en":"The dry grass was soon alight.","zh":"干草很快就燃烧起来。"}]},{"pos":"v.","meaning":"下车；下船","definition":"to get off a vehicle","examples":[{"en":"Passengers should alight at the next stop.","zh":"乘客应在下一站下车。"},{"en":"She alighted from the train carrying a small suitcase.","zh":"她提着一个小行李箱下了火车。"}]},{"pos":"v.","meaning":"飞落；停落","definition":"to land or settle on a surface","examples":[{"en":"A butterfly alighted on the flower.","zh":"一只蝴蝶落在花上。"},{"en":"The bird alighted on a branch above us.","zh":"那只鸟落在我们上方的一根树枝上。"}]}],"alignment":[{"pos":"n.","meaning":"排成直线；对齐","definition":"the arrangement of things in a straight line or correct position","examples":[{"en":"The mechanic checked the alignment of the wheels.","zh":"技工检查了车轮的定位。"},{"en":"The image shows the alignment of the planets.","zh":"这幅图展示了行星排列的位置。"}]},{"pos":"n.","meaning":"一致；结盟","definition":"agreement or cooperation between people or groups","examples":[{"en":"The strategy brings spending into alignment with our goals.","zh":"这项策略使支出与我们的目标保持一致。"},{"en":"A new political alignment emerged after the election.","zh":"选举后出现了新的政治联盟格局。"}]}],"allege":[{"pos":"v.","meaning":"声称；指控（尚未经证实）","definition":"to claim that something happened without proving it","examples":[{"en":"The workers allege that the company ignored safety warnings.","zh":"工人们声称公司无视了安全警告。"},{"en":"The documents allege misconduct by senior officials.","zh":"这些文件指控高级官员存在不当行为。"}]}],"allergic":[{"pos":"adj.","meaning":"过敏的","definition":"having an allergy to a substance","examples":[{"en":"She is allergic to peanuts.","zh":"她对花生过敏。"},{"en":"The doctor checked whether he was allergic to the medicine.","zh":"医生检查了他是否对这种药过敏。"}]}],"allergy":[{"pos":"n.","meaning":"过敏","definition":"a harmful physical reaction to a normally harmless substance","examples":[{"en":"Please tell the restaurant about your nut allergy.","zh":"请告诉餐厅你对坚果过敏。"},{"en":"She has an allergy to certain medicines.","zh":"她对某些药物过敏。"},{"en":"An allergy can cause a skin rash.","zh":"过敏可能引起皮疹。"}]}],"alleviate":[{"pos":"v.","meaning":"缓解","definition":"to make a problem or suffering less severe","examples":[{"en":"More affordable housing could alleviate financial pressure.","zh":"更多可负担住房可以缓解经济压力。"},{"en":"The new road may alleviate congestion in the centre.","zh":"新道路可能缓解市中心拥堵。"},{"en":"Financial support can help alleviate poverty.","zh":"经济支持可以帮助缓解贫困。"}]}],"alley":[{"pos":"n.","meaning":"小巷；胡同","definition":"a narrow passage between buildings","examples":[{"en":"A small café stands at the end of the alley.","zh":"巷子尽头有一家小咖啡馆。"},{"en":"They walked through the alley to reach the market.","zh":"他们穿过小巷到达市场。"}]}],"allocate":[{"pos":"v.","meaning":"分配","definition":"to give a share of something for a purpose","examples":[{"en":"The city should allocate more money to public transport.","zh":"这座城市应该为公共交通分配更多资金。"},{"en":"Managers allocate tasks according to staff experience.","zh":"经理根据员工经验分配任务。"},{"en":"We need to allocate enough time for revision.","zh":"我们需要为复习分配足够时间。"}]}],"allocate to":[{"pos":"phr.","meaning":"分配给；划拨给","definition":"to set aside resources for a person or purpose","examples":[{"en":"The council will allocate more money to public transport.","zh":"地方议会将给公共交通划拨更多资金。"},{"en":"We should allocate enough time to checking the final report.","zh":"我们应分配足够时间检查最终报告。"}]}],"allocation":[{"pos":"n.","meaning":"分配；配置","definition":"the act of distributing resources for particular purposes","examples":[{"en":"The committee oversees the allocation of research funding.","zh":"委员会监督科研经费的分配。"},{"en":"Fair allocation of housing is a major concern.","zh":"公平分配住房是一个重要问题。"}]},{"pos":"n.","meaning":"分配额；配给量","definition":"an amount assigned to someone or something","examples":[{"en":"Our department has used its annual allocation of paper.","zh":"我们部门已经用完了年度纸张配额。"},{"en":"Each village received an equal allocation of water.","zh":"每个村庄得到的供水配额相同。"}]}],"allowance":[{"pos":"n.","meaning":"津贴；补助；零用钱","definition":"money provided regularly for a particular purpose","examples":[{"en":"The scholarship includes a monthly living allowance.","zh":"奖学金包括每月生活补助。"},{"en":"The children receive a small weekly allowance.","zh":"孩子们每周收到少量零用钱。"}]},{"pos":"n.","meaning":"限额；允许量","definition":"an amount of something that is permitted","examples":[{"en":"Check your baggage allowance before packing.","zh":"打包行李前请查看行李限额。"},{"en":"The ticket includes a generous luggage allowance.","zh":"这张票包含较宽裕的行李额度。"}]},{"pos":"n.","meaning":"体谅；考虑；余量","definition":"an adjustment made for a circumstance or difficulty","examples":[{"en":"We should make allowance for her lack of experience.","zh":"我们应该体谅她经验不足。"},{"en":"The budget includes an allowance for unexpected repairs.","zh":"预算中留出了应对意外维修的余量。"}]}],"allure":[{"pos":"n.","meaning":"吸引力；诱惑","definition":"a quality that attracts or tempts people","examples":[{"en":"The island's quiet beaches have a special allure.","zh":"岛上宁静的海滩有一种特殊的吸引力。"},{"en":"The allure of fame drew him towards acting.","zh":"名气的诱惑使他走向演艺行业。"}]},{"pos":"v.","meaning":"诱惑；吸引","definition":"to attract someone strongly","examples":[{"en":"The promise of discovery continues to allure young explorers.","zh":"发现新事物的前景持续吸引着年轻探险者。"},{"en":"Bright displays allure visitors into the market.","zh":"明亮的陈列吸引游客走进市场。"}]}],"alluvial":[{"pos":"adj.","meaning":"冲积的；由流水沉积形成的","definition":"formed from material deposited by flowing water","examples":[{"en":"Farmers cultivate the rich alluvial soil beside the river.","zh":"农民耕种河边肥沃的冲积土壤。"},{"en":"The valley contains extensive alluvial deposits.","zh":"山谷中有大片冲积物。"}]},{"pos":"n.","meaning":"冲积物；冲积土","definition":"material deposited by flowing water","examples":[{"en":"The survey identified a layer of alluvial beneath the field.","zh":"勘测在田地下方发现了一层冲积物。"},{"en":"Samples of alluvial were collected near the old river channel.","zh":"研究者在旧河道附近采集了冲积物样本。"}]}],"almond":[{"pos":"n.","meaning":"扁桃仁；杏仁（常用商品名）","definition":"the edible seed of an almond tree","examples":[{"en":"She sprinkled chopped almonds over the salad.","zh":"她在沙拉上撒了些切碎的扁桃仁。"},{"en":"The biscuit contains almond flour.","zh":"这种饼干含有杏仁粉。"}]},{"pos":"n.","meaning":"扁桃树","definition":"a tree that produces edible almond seeds","examples":[{"en":"The almond blossoms early in spring.","zh":"扁桃树在早春开花。"},{"en":"Farmers planted almond trees on the dry hillside.","zh":"农民在干燥的山坡上种植了扁桃树。"}]}],"alter":[{"pos":"v.","meaning":"改变；改动","definition":"to make something different or become different","examples":[{"en":"We need to alter the design before construction begins.","zh":"开工前我们需要修改设计。"},{"en":"The new evidence may alter our understanding of the event.","zh":"新证据可能改变我们对这件事的理解。"}]}],"alternate":[{"pos":"v.","meaning":"交替；轮流","definition":"to happen or do things in turns","examples":[{"en":"We alternate between walking and running.","zh":"我们交替步行和跑步。"},{"en":"The two teachers alternate in supervising the club.","zh":"两位教师轮流指导这个社团。"}],"ipa":"/ˈɔːltəneɪt/"},{"pos":"adj.","meaning":"交替的；轮流的","definition":"occurring in turns with something else","examples":[{"en":"Paint the fence in alternate blue and white stripes.","zh":"把围栏刷成蓝白相间的条纹。"},{"en":"The schedule gives each worker alternate morning and evening shifts.","zh":"这份排班让每名工人轮流上早班和晚班。"}],"ipa":"/ɔːlˈtɜːnət/"},{"pos":"adj.","meaning":"每隔一个的","definition":"occurring every other time or item","examples":[{"en":"The class meets on alternate Mondays.","zh":"这门课每隔一个星期一上一次。"},{"en":"Place a marker beside every alternate row.","zh":"每隔一行放一个标记。"}],"ipa":"/ɔːlˈtɜːnət/"}],"alternative":[{"pos":"n.","meaning":"替代选择","definition":"another available choice","examples":[{"en":"Cycling is an alternative to driving for short journeys.","zh":"对于短途出行，骑行是开车之外的选择。"},{"en":"The council offered no practical alternative.","zh":"地方议会没有提供切实可行的替代方案。"},{"en":"We need an affordable alternative to private childcare.","zh":"我们需要私人托育之外价格可承受的选择。"}]},{"pos":"adj.","meaning":"可替代的；另一个可选的","definition":"available as another possible choice","examples":[{"en":"We need an alternative route because the bridge is closed.","zh":"由于大桥关闭，我们需要一条替代路线。"},{"en":"The report considers alternative sources of energy.","zh":"报告考察了替代能源。"}]},{"pos":"adj.","meaning":"非传统的；另类的","definition":"different from what is usual or conventional","examples":[{"en":"The festival celebrates alternative music and independent films.","zh":"这个节日展示另类音乐和独立电影。"},{"en":"They explored alternative approaches to education.","zh":"他们探索了非传统的教育方法。"}]}],"altitude":[{"pos":"n.","meaning":"海拔；高度","definition":"height above sea level or another reference point","examples":[{"en":"The village stands at an altitude of two thousand metres.","zh":"这个村庄位于海拔两千米处。"},{"en":"The pilot reduced altitude before approaching the runway.","zh":"飞行员在接近跑道前降低了高度。"}]}],"altruistic":[{"pos":"adj.","meaning":"无私的；利他的","definition":"concerned with helping others rather than benefiting oneself","examples":[{"en":"Her decision to donate was entirely altruistic.","zh":"她捐款的决定完全出于无私。"},{"en":"The study examines altruistic behaviour in communities.","zh":"这项研究考察社区中的利他行为。"}]}],"aluminium":[{"pos":"n.","meaning":"铝","definition":"a light silvery metal","examples":[{"en":"The window frames are made of aluminium.","zh":"这些窗框由铝制成。"},{"en":"Recycling aluminium uses less energy than producing it from ore.","zh":"回收铝比从矿石中生产铝耗能更少。"}]}],"amass":[{"pos":"v.","meaning":"积累；聚集","definition":"to gather a large amount of something","examples":[{"en":"The museum has amassed a valuable collection of maps.","zh":"这座博物馆积累了一批珍贵地图。"},{"en":"Over the years, she amassed enough savings to buy a home.","zh":"多年来，她攒够了买房的钱。"}]}],"amateur":[{"pos":"n.","meaning":"业余爱好者；非专业人士","definition":"someone who does an activity without being a paid professional","examples":[{"en":"The competition is open to any amateur.","zh":"任何业余爱好者都可以参加这项比赛。"},{"en":"As an amateur, he learns photography in his spare time.","zh":"作为业余爱好者，他在业余时间学习摄影。"}]},{"pos":"n.","meaning":"外行；缺乏技巧的人","definition":"someone who lacks professional skill","examples":[{"en":"The repairs looked as though an amateur had done them.","zh":"这些维修看起来像是外行做的。"},{"en":"Compared with her, I am still an amateur.","zh":"和她相比，我仍是个外行。"}]},{"pos":"adj.","meaning":"业余的","definition":"done for enjoyment rather than as a paid profession","examples":[{"en":"She plays in an amateur orchestra.","zh":"她在一个业余管弦乐团演奏。"},{"en":"Amateur astronomers helped identify the unusual object.","zh":"业余天文学家帮助辨认了这个异常天体。"}]}],"amaze":[{"pos":"v.","meaning":"使惊奇；使惊愕","definition":"to surprise someone greatly","examples":[{"en":"The speed of the rescue amazed everyone.","zh":"救援的速度让所有人惊叹。"},{"en":"It amazes me how much the town has changed.","zh":"这座城镇变化如此之大，令我惊讶。"}]}],"ambassador":[{"pos":"n.","meaning":"大使；使节；代表","definition":"an official representative of a country or organization","examples":[{"en":"The ambassador met local business leaders.","zh":"大使会见了当地商界领袖。"},{"en":"She became an ambassador for the children's charity.","zh":"她成为了这家儿童慈善机构的宣传大使。"}]}],"ambiguity":[{"pos":"n.","meaning":"歧义；模糊不清","definition":"the possibility of more than one meaning or interpretation","examples":[{"en":"The contract should avoid ambiguity about payment dates.","zh":"合同应避免在付款日期上产生歧义。"},{"en":"There is some ambiguity in the final sentence.","zh":"最后一句有些含糊不清。"}]}],"ambiguous":[{"pos":"adj.","meaning":"含糊的；有歧义的；模棱两可的","definition":"having more than one possible meaning or interpretation","examples":[{"en":"The ambiguous instructions confused several students.","zh":"含糊的说明让几名学生感到困惑。"},{"en":"Her reply was deliberately ambiguous.","zh":"她的回答故意含糊其辞。"}]}],"ambition":[{"pos":"n.","meaning":"雄心；抱负；志向","definition":"a strong wish to achieve something","examples":[{"en":"His ambition is to design affordable housing.","zh":"他的志向是设计价格可负担的住房。"},{"en":"Her ambition drove her to apply for the demanding course.","zh":"她的抱负促使她申请那门要求严格的课程。"}]}],"ambitious":[{"pos":"adj.","meaning":"有抱负的；有雄心的","definition":"having a strong desire to succeed","examples":[{"en":"The ambitious student hopes to lead her own laboratory.","zh":"这名有抱负的学生希望领导自己的实验室。"},{"en":"He is ambitious but willing to learn from others.","zh":"他有雄心，也愿意向别人学习。"}]},{"pos":"adj.","meaning":"宏大的；要求很高的","definition":"requiring considerable effort and determination","examples":[{"en":"The city has an ambitious plan to improve air quality.","zh":"这座城市制定了改善空气质量的宏大计划。"},{"en":"Finishing the project in one month is an ambitious target.","zh":"一个月内完成项目是个很有挑战性的目标。"}]}],"ambulance":[{"pos":"n.","meaning":"救护车","definition":"a vehicle that carries sick or injured people to medical care","examples":[{"en":"Someone called an ambulance after the accident.","zh":"事故发生后，有人叫了救护车。"},{"en":"The ambulance arrived within minutes.","zh":"救护车在几分钟内就到了。"}]},{"pos":"n.","meaning":"流动战地医院（历史用法）","definition":"a mobile medical unit treating wounded soldiers in the field","examples":[{"en":"In the historical account, an ambulance was established in a farmhouse to treat the wounded.","zh":"在这份历史记述中，一所流动战地医院设在农舍里，为伤员治疗。"},{"en":"The surgeon's diary describes his work in a field ambulance near the front.","zh":"外科医生的日记描述了他在前线附近流动战地医院的工作。"}]}],"amorphous":[{"pos":"adj.","meaning":"无固定形状的；无明确组织的","definition":"having no definite shape or clear structure","examples":[{"en":"The material cooled into an amorphous solid.","zh":"这种材料冷却后成为无定形固体。"},{"en":"The discussion began with an amorphous collection of ideas.","zh":"讨论从一堆尚未成形的想法开始。"}]}],"amount":[{"pos":"n.","meaning":"数量；总额","definition":"a quantity or total of something","examples":[{"en":"A small amount of salt improves the flavour.","zh":"少量盐可以改善味道。"},{"en":"The final amount includes delivery charges.","zh":"最终金额包含运费。"}]},{"pos":"v.","meaning":"总计达到；相当于","definition":"to reach a total or be equivalent to something","examples":[{"en":"The expenses amount to nearly two thousand pounds.","zh":"这些开支总计近两千英镑。"},{"en":"Ignoring the warning would amount to accepting the risk.","zh":"无视警告就相当于接受这一风险。"}]}],"amphibious":[{"pos":"adj.","meaning":"两栖的","definition":"able to live both on land and in water","examples":[{"en":"Frogs are amphibious animals.","zh":"青蛙是两栖动物。"},{"en":"The exhibition explains how amphibious creatures move between water and land.","zh":"展览解释了两栖生物如何在水陆之间活动。"}]},{"pos":"adj.","meaning":"水陆两用的","definition":"designed for use both on land and in water","examples":[{"en":"An amphibious vehicle carried supplies across the flooded road.","zh":"一辆水陆两用车运送物资穿过被淹的道路。"},{"en":"The rescue team tested an amphibious craft near the river.","zh":"救援队在河边测试了一艘水陆两用艇。"}]}],"amplify":[{"pos":"v.","meaning":"放大；增强","definition":"to make a sound or effect stronger","examples":[{"en":"The microphone amplifies even a quiet voice.","zh":"这个麦克风连轻声说话都能放大。"},{"en":"Social media can amplify the effects of a rumour.","zh":"社交媒体会放大谣言的影响。"}]},{"pos":"v.","meaning":"详述；补充说明","definition":"to add details to an explanation","examples":[{"en":"Could you amplify your final point with an example?","zh":"你能举例进一步说明最后一点吗？"},{"en":"The speaker amplified the argument in a later article.","zh":"演讲者在后来的文章中详细阐述了这个论点。"}]}],"analogous":[{"pos":"adj.","meaning":"类似的；可比拟的","definition":"similar in relevant respects","examples":[{"en":"The two systems perform analogous functions.","zh":"这两个系统发挥类似的作用。"},{"en":"Her situation is analogous to the case discussed earlier.","zh":"她的情况类似于前面讨论的案例。"}]}],"analogy":[{"pos":"n.","meaning":"类比；比拟","definition":"a comparison used to explain a similarity","examples":[{"en":"The teacher used an analogy with water pipes to explain electric circuits.","zh":"老师用水管作类比来解释电路。"},{"en":"That analogy is useful, but the two systems are not identical.","zh":"这个类比很有用，但两个系统并不相同。"}]},{"pos":"n.","meaning":"类推","definition":"reasoning from similarities between things","examples":[{"en":"We cannot establish the rule by analogy alone.","zh":"我们不能仅凭类推确立这条规则。"},{"en":"The researchers used analogy to develop a new hypothesis.","zh":"研究人员运用类推提出了新假说。"}]}],"analyse":[{"pos":"v.","meaning":"分析；分解研究","definition":"to examine something carefully by considering its parts","examples":[{"en":"The researchers will analyse the samples tomorrow.","zh":"研究人员明天将分析这些样本。"},{"en":"We analysed the interviews to identify common concerns.","zh":"我们分析了访谈，以找出共同的关切。"}]}],"analysis":[{"pos":"n.","meaning":"分析","definition":"careful examination of the parts of something","examples":[{"en":"The analysis revealed a clear difference between the groups.","zh":"分析揭示了组间的明显差异。"},{"en":"Careful analysis is needed to explain the results.","zh":"需要仔细分析来解释结果。"},{"en":"The report includes an analysis of transport costs.","zh":"报告包含对交通成本的分析。"}]},{"pos":"n.","meaning":"分解;成分分析","definition":"the separation or identification of constituent parts","examples":[{"en":"Chemical analysis identified the elements in the sample.","zh":"化学成分分析确定了样本中的元素。"},{"en":"The analysis separated the mixture into its components.","zh":"分解分析将混合物分成组成部分。"}]}],"anatomy":[{"pos":"n.","meaning":"解剖学","definition":"the study of the structure of living bodies","examples":[{"en":"Medical students study anatomy in their first year.","zh":"医学生在第一年学习解剖学。"},{"en":"The textbook introduces human anatomy with clear diagrams.","zh":"这本教材通过清晰的图示介绍人体解剖学。"}]},{"pos":"n.","meaning":"解剖结构；身体构造","definition":"the physical structure of a living body","examples":[{"en":"The anatomy of a bird is adapted for flight.","zh":"鸟的身体构造适于飞行。"},{"en":"The scan reveals details of the patient's anatomy.","zh":"扫描显示了患者身体结构的细节。"}]}],"ancestral":[{"pos":"adj.","meaning":"祖先的；祖传的","definition":"relating to ancestors or inherited from them","examples":[{"en":"The family returned to their ancestral village.","zh":"这家人回到了祖籍村。"},{"en":"She inherited an ancestral house near the coast.","zh":"她继承了海岸附近的一栋祖屋。"}]}],"anchor":[{"pos":"n.","meaning":"锚","definition":"a heavy object used to hold a boat in place","examples":[{"en":"The crew lowered the anchor before sunset.","zh":"船员在日落前放下了锚。"},{"en":"A broken anchor lay on the harbour floor.","zh":"一只断锚躺在港底。"}]},{"pos":"n.","meaning":"精神支柱；给人安全感的人或事物","definition":"someone or something providing stability","examples":[{"en":"Her family remained an anchor during the difficult years.","zh":"在那些艰难岁月里，家人始终是她的支柱。"},{"en":"The weekly meeting became an anchor in his routine.","zh":"每周的聚会成了他日常生活中的稳定依靠。"}]},{"pos":"v.","meaning":"抛锚；固定","definition":"to hold something firmly in position","examples":[{"en":"They anchor the boat in a sheltered bay.","zh":"他们把船停泊在一个避风海湾。"},{"en":"Use these bolts to anchor the shelf to the wall.","zh":"用这些螺栓把架子固定在墙上。"}]},{"pos":"v.","meaning":"使基于；使扎根于","definition":"to base something firmly on a principle or fact","examples":[{"en":"We should anchor our conclusions in reliable evidence.","zh":"我们应以可靠证据为结论的基础。"},{"en":"Shared values anchor the organisation's work.","zh":"共同价值观构成了这个组织工作的根基。"}]},{"pos":"v.","meaning":"主持新闻节目","definition":"to present and coordinate a news programme","examples":[{"en":"She will anchor the evening news tonight.","zh":"她今晚将主持晚间新闻。"},{"en":"He used to anchor a weekly current-affairs programme.","zh":"他过去主持一档每周播出的时事节目。"}]}],"ancient":[{"pos":"adj.","meaning":"古代的；古老的","definition":"belonging to the distant past or having existed for a very long time","examples":[{"en":"Archaeologists discovered an ancient settlement beside the river.","zh":"考古学家在河边发现了一处古代聚落。"},{"en":"The path winds through an ancient forest.","zh":"这条小路蜿蜒穿过一片古老的森林。"}]},{"pos":"adj.","meaning":"非常年老的；老旧的（非正式）","definition":"very old, often said humorously","examples":[{"en":"Our ancient computer takes several minutes to start.","zh":"我们那台老旧电脑启动需要好几分钟。"},{"en":"An ancient dog slept beside the fireplace.","zh":"一只十分年老的狗睡在壁炉旁。"}]}],"and so forth":[{"pos":"phrase","meaning":"等等；诸如此类","definition":"and other similar things","examples":[{"en":"The fee covers books, stationery, and so forth.","zh":"这笔费用包括书籍、文具等等。"},{"en":"We discussed transport, housing, employment, and so forth.","zh":"我们讨论了交通、住房、就业等问题。"}]}],"anecdotal":[{"pos":"adj.","meaning":"轶事的；基于个人经历的","definition":"based on personal accounts rather than systematic evidence","examples":[{"en":"The claim rests mainly on anecdotal evidence.","zh":"这一说法主要依赖个人经历提供的证据。"},{"en":"His anecdotal account made the lecture entertaining.","zh":"他穿插轶事的讲述让讲座很有趣。"}]}],"anecdote":[{"pos":"n.","meaning":"轶事；趣闻；短故事","definition":"a short account of an interesting or amusing incident","examples":[{"en":"She opened the speech with an anecdote about her first job.","zh":"她以一则关于第一份工作的趣闻开始演讲。"},{"en":"His travel diary is full of entertaining anecdotes.","zh":"他的旅行日记充满了有趣的轶事。"}]}],"angle":[{"pos":"n.","meaning":"角；角度","definition":"the space between two meeting lines or surfaces","examples":[{"en":"The triangle has one right angle.","zh":"这个三角形有一个直角。"},{"en":"Hold the camera at a lower angle.","zh":"把相机拿低一点，换一个较低的角度。"}]},{"pos":"n.","meaning":"观点；看待问题的角度","definition":"a particular way of considering something","examples":[{"en":"Try looking at the problem from another angle.","zh":"试着从另一个角度看这个问题。"},{"en":"The article explores the story from a financial angle.","zh":"这篇文章从财务角度探讨了这件事。"}]},{"pos":"v.","meaning":"使倾斜；从特定角度呈现","definition":"to position something at a slope or present it from a viewpoint","examples":[{"en":"Angle the lamp towards the page.","zh":"把灯斜着朝向书页。"},{"en":"The editor angled the report towards younger readers.","zh":"编辑从年轻读者关心的角度组织了这篇报道。"}]}],"animate":[{"pos":"adj.","meaning":"有生命的；活的","definition":"alive rather than lifeless","examples":[{"en":"The exercise asks pupils to distinguish animate from inanimate things.","zh":"这道练习要求学生区分有生命和无生命的事物。"},{"en":"The story gives every animate creature a voice.","zh":"这个故事让每一种生物都能够说话。"}],"ipa":"/ˈænɪmət/"},{"pos":"v.","meaning":"使生机勃勃；赋予活力","definition":"to make something lively or full of energy","examples":[{"en":"Her enthusiasm helped animate the discussion.","zh":"她的热情使讨论活跃起来。"},{"en":"Bright murals animate the otherwise plain corridor.","zh":"鲜艳的壁画使原本普通的走廊焕发生机。"}],"ipa":"/ˈænɪmeɪt/"},{"pos":"v.","meaning":"制作动画；使图像活动","definition":"to make drawings or models appear to move","examples":[{"en":"The students learned to animate a simple character.","zh":"学生们学会了给一个简单角色制作动画。"},{"en":"The software can animate each stage of the process.","zh":"这款软件可以用动画展示流程的每个阶段。"}],"ipa":"/ˈænɪmeɪt/"}],"announce":[{"pos":"v.","meaning":"宣布；公布","definition":"to make information known publicly","examples":[{"en":"The council will announce its decision tomorrow.","zh":"议会将在明天公布决定。"},{"en":"They announced the winner at the end of the ceremony.","zh":"他们在仪式结束时宣布了获胜者。"}]},{"pos":"v.","meaning":"声称；郑重表示","definition":"to state something clearly or confidently","examples":[{"en":"She announced that she would finish the project herself.","zh":"她郑重表示要独自完成项目。"},{"en":"He announced his intention to retire at the meeting.","zh":"他在会上宣布了退休的打算。"}]}],"annoy":[{"pos":"v.","meaning":"使烦恼；打扰","definition":"to make someone feel irritated","examples":[{"en":"The constant tapping began to annoy everyone.","zh":"不断的敲击声开始让每个人都心烦。"},{"en":"It annoys me when people interrupt the speaker.","zh":"别人打断发言者时，我会感到恼火。"}]}],"annual":[{"pos":"adj.","meaning":"每年的；年度的","definition":"happening once a year or relating to a year","examples":[{"en":"The annual festival takes place in June.","zh":"这个年度节日在六月举行。"},{"en":"The report compares annual rainfall across regions.","zh":"报告比较了不同地区的年降雨量。"}]},{"pos":"n.","meaning":"年刊；年鉴","definition":"a publication issued once each year","examples":[{"en":"The school annual contains photographs of every class.","zh":"学校年刊收录了每个班级的照片。"},{"en":"She keeps each annual on the same shelf.","zh":"她把每一册年鉴放在同一个书架上。"}]},{"pos":"n.","meaning":"一年生植物","definition":"a plant that completes its life cycle in one growing season","examples":[{"en":"This annual produces flowers throughout the summer.","zh":"这种一年生植物整个夏天都会开花。"},{"en":"Gardeners sow the annual again each spring.","zh":"园丁每年春天重新播种这种一年生植物。"}]}],"anthropologist":[{"pos":"n.","meaning":"人类学家","definition":"a researcher who studies human societies and cultures","examples":[{"en":"The anthropologist spent a year studying village life.","zh":"这位人类学家花了一年时间研究乡村生活。"},{"en":"An anthropologist interviewed families about their traditions.","zh":"一位人类学家就家庭传统采访了各家各户。"}]}],"antibiotic":[{"pos":"n.","meaning":"抗生素","definition":"a medicine that treats certain bacterial infections","examples":[{"en":"The doctor prescribed an antibiotic for the infection.","zh":"医生为这次感染开了抗生素。"},{"en":"Scientists are studying resistance to this antibiotic.","zh":"科学家正在研究对这种抗生素的耐药性。"}]},{"pos":"adj.","meaning":"抗菌的；抗生素的","definition":"relating to medicines that act against bacteria","examples":[{"en":"The laboratory tested the compound's antibiotic properties.","zh":"实验室检测了这种化合物的抗菌性质。"},{"en":"The study examined patterns of antibiotic use.","zh":"这项研究考察了抗生素的使用模式。"}]}],"anticipate":[{"pos":"v.","meaning":"预期；预料","definition":"to expect something to happen","examples":[{"en":"We anticipate a rise in demand during the holidays.","zh":"我们预计假日期间需求会上升。"},{"en":"The organisers did not anticipate such a large crowd.","zh":"组织者没有预料到会有这么多人。"}]},{"pos":"v.","meaning":"预先行动；事先应对","definition":"to act before an event or need arises","examples":[{"en":"Good designers anticipate users' needs.","zh":"优秀的设计师会预先考虑用户的需要。"},{"en":"The team tried to anticipate problems before construction began.","zh":"团队试图在施工开始前预先处理可能出现的问题。"}]}],"anticipation":[{"pos":"n.","meaning":"预期；预料","definition":"the act of expecting something to happen","examples":[{"en":"The shop ordered extra stock in anticipation of high demand.","zh":"商店预料需求会增加，因此多订了货。"},{"en":"Careful anticipation of problems made the event run smoothly.","zh":"对问题的周密预判使活动顺利进行。"}]},{"pos":"n.","meaning":"期待；期盼","definition":"excitement about something expected in the future","examples":[{"en":"The children waited in eager anticipation of the trip.","zh":"孩子们热切地期待着这次旅行。"},{"en":"There was a sense of anticipation before the concert began.","zh":"音乐会开始前，人们充满期待。"}]}],"antidote":[{"pos":"n.","meaning":"解毒剂","definition":"a substance that counteracts a poison","examples":[{"en":"The medical team identified the appropriate antidote.","zh":"医疗团队确定了合适的解毒剂。"},{"en":"The laboratory stores an antidote for the toxin.","zh":"实验室备有针对这种毒素的解毒剂。"}]},{"pos":"n.","meaning":"补救办法；消除不良影响的方法","definition":"something that counteracts a harmful feeling or situation","examples":[{"en":"A walk outside can be an antidote to a stressful day.","zh":"出去散步可以缓解一天的压力。"},{"en":"Good evidence is an antidote to unfounded rumours.","zh":"可靠证据是驳斥无根据谣言的良方。"}]}],"antiquated":[{"pos":"adj.","meaning":"陈旧的；过时的","definition":"old and no longer suitable for modern use","examples":[{"en":"The office still uses an antiquated filing system.","zh":"这间办公室仍在使用过时的归档系统。"},{"en":"They replaced the antiquated heating equipment.","zh":"他们更换了陈旧的供暖设备。"}]}],"antique":[{"pos":"adj.","meaning":"古老的；古董的","definition":"old and often valuable because of age or craftsmanship","examples":[{"en":"An antique clock stood in the hallway.","zh":"走廊里摆着一座古董钟。"},{"en":"She collects antique furniture from local markets.","zh":"她从当地市场收集古旧家具。"}]},{"pos":"n.","meaning":"古董；古物","definition":"an old object valued for its age or beauty","examples":[{"en":"The vase is a genuine antique.","zh":"这个花瓶是一件真正的古董。"},{"en":"A specialist examined the antique before the sale.","zh":"出售前，一位专家检查了这件古董。"}]}],"antiquity":[{"pos":"n.","meaning":"古代；古老","definition":"the distant past or the state of being very old","examples":[{"en":"The trade route was important in antiquity.","zh":"这条贸易路线在古代十分重要。"},{"en":"The antiquity of the manuscript surprised the researchers.","zh":"这份手稿年代之久让研究人员惊讶。"}]},{"pos":"n.","meaning":"古物；古迹（常用复数 antiquities）","definition":"an object or building surviving from ancient times","examples":[{"en":"The gallery displays antiquities from the Mediterranean.","zh":"这家美术馆陈列着地中海地区的古物。"},{"en":"Exporting these antiquities requires official permission.","zh":"出口这些古物需要官方许可。"}]}],"antiseptic":[{"pos":"adj.","meaning":"抗菌的；消毒的","definition":"used to prevent the growth of microorganisms","examples":[{"en":"The nurse cleaned the area with an antiseptic solution.","zh":"护士用消毒液清洁了该部位。"},{"en":"The cupboard contains antiseptic wipes.","zh":"柜子里放着消毒湿巾。"}]},{"pos":"n.","meaning":"消毒剂；抗菌剂","definition":"a substance used to reduce microorganisms on living tissue","examples":[{"en":"The label explains how the antiseptic should be used.","zh":"标签说明了这种消毒剂的使用方法。"},{"en":"A bottle of antiseptic was kept in the first-aid box.","zh":"急救箱里放着一瓶消毒剂。"}]}],"anxious":[{"pos":"adj.","meaning":"焦虑的；忧虑的","definition":"worried or nervous about something","examples":[{"en":"She felt anxious about the exam results.","zh":"她为考试结果感到焦虑。"},{"en":"Parents were anxious when the school bus was late.","zh":"校车晚点时，家长们很担心。"}]},{"pos":"adj.","meaning":"渴望的；急于的","definition":"very eager to do or obtain something","examples":[{"en":"The researchers are anxious to share their findings.","zh":"研究人员急于分享研究结果。"},{"en":"He was anxious for news of his missing suitcase.","zh":"他急切地盼望丢失行李箱的消息。"}]}],"apace":[{"pos":"adv.","meaning":"迅速地","definition":"at a fast and continuing rate","examples":[{"en":"Construction continued apace despite the cold weather.","zh":"尽管天气寒冷，施工仍迅速推进。"},{"en":"Technology in this field is developing apace.","zh":"这个领域的技术正在快速发展。"}]}],"apart":[{"pos":"adv.","meaning":"相隔；分开","definition":"separated by a distance or kept separate","examples":[{"en":"The two villages are ten kilometres apart.","zh":"这两个村庄相距十公里。"},{"en":"They have lived apart since last year.","zh":"他们从去年起就分开生活了。"}]},{"pos":"adv.","meaning":"除外；撇开","definition":"excepting or setting aside something","examples":[{"en":"Apart from one error, the report is accurate.","zh":"除了一处错误，这份报告是准确的。"},{"en":"Cost apart, the plan has several advantages.","zh":"撇开费用不谈，这个计划有几个优点。"}]},{"pos":"adj.","meaning":"与众不同的；分离的","definition":"separate or distinct from others","examples":[{"en":"Her extraordinary talent places her in a class apart.","zh":"她非凡的才华使她卓尔不群。"},{"en":"The remote community seemed a world apart.","zh":"这个偏远社区仿佛是一个独立的世界。"}]}],"ape":[{"pos":"n.","meaning":"猿；类人猿","definition":"a primate such as a gorilla or chimpanzee, without a tail","examples":[{"en":"The young ape clung to its mother.","zh":"幼猿紧紧抱住母亲。"},{"en":"The sanctuary provides a safe home for rescued apes.","zh":"保护区为获救的猿类提供了安全的家园。"}]},{"pos":"v.","meaning":"模仿；照搬","definition":"to copy someone's behaviour, often uncritically","examples":[{"en":"The child tried to ape the comedian's gestures.","zh":"孩子试着模仿喜剧演员的动作。"},{"en":"The design should express local character rather than ape foreign styles.","zh":"设计应体现当地特色，而非照搬外国风格。"}]}],"apologise":[{"pos":"v.","meaning":"道歉","definition":"to say that you are sorry","examples":[{"en":"I apologise for the delay in replying.","zh":"我为回复延迟而道歉。"},{"en":"We apologise for any inconvenience caused.","zh":"我们对造成的不便表示歉意。"},{"en":"You should apologise to your colleague for the mistake.","zh":"你应该为这个错误向同事道歉。"}]}],"apologize":[{"pos":"v.","meaning":"道歉；表示歉意","definition":"to say that one is sorry for a mistake or problem","examples":[{"en":"I apologize for sending you the wrong document.","zh":"很抱歉给你发错了文件。"},{"en":"The manager called to apologize for the delay.","zh":"经理打来电话为延误道歉。"}]}],"apparatus":[{"pos":"n.","meaning":"仪器；设备；器械","definition":"equipment used for a particular purpose","examples":[{"en":"The laboratory stores its measuring apparatus in locked cabinets.","zh":"实验室把测量仪器存放在上锁的柜子里。"},{"en":"Firefighters checked their breathing apparatus before entering.","zh":"消防员进入前检查了呼吸设备。"}]},{"pos":"n.","meaning":"机构；组织系统","definition":"the organization and machinery of a system","examples":[{"en":"The reforms changed the state's administrative apparatus.","zh":"这些改革改变了国家的行政机构。"},{"en":"A complex apparatus was needed to coordinate relief efforts.","zh":"协调救援工作需要一套复杂的组织体系。"}]}],"apparent":[{"pos":"adj.","meaning":"明显的；显而易见的","definition":"easy to see or understand","examples":[{"en":"The cause of the delay soon became apparent.","zh":"延误的原因很快就显而易见了。"},{"en":"There is an apparent difference between the two samples.","zh":"两个样本之间有明显差异。"}]},{"pos":"adj.","meaning":"表面上的；似乎的","definition":"seeming to be true but not necessarily so","examples":[{"en":"Despite its apparent simplicity, the task requires skill.","zh":"尽管表面上简单，这项任务仍需要技巧。"},{"en":"The apparent improvement disappeared when the data were checked.","zh":"核查数据后，表面上的改善消失了。"}]}],"apparently":[{"pos":"adv.","meaning":"看来；似乎","definition":"according to appearances or available information","examples":[{"en":"Apparently, the last train leaves at eleven.","zh":"看来，末班火车十一点出发。"},{"en":"The apparently simple task required careful planning.","zh":"这项看似简单的任务需要仔细规划。"}]}],"appeal":[{"pos":"v.","meaning":"呼吁；恳求","definition":"to make a serious request for help or support","examples":[{"en":"The charity will appeal for donations this weekend.","zh":"这家慈善机构将在本周末呼吁捐款。"},{"en":"Residents appeal to the council to repair the bridge.","zh":"居民恳请市议会修复这座桥。"}]},{"pos":"v.","meaning":"上诉；申诉","definition":"to ask a higher authority to review a decision","examples":[{"en":"She decided to appeal against the ruling.","zh":"她决定对裁决提出上诉。"},{"en":"Students may appeal if they believe a grade is unfair.","zh":"学生若认为成绩不公，可以提出申诉。"}]},{"pos":"v.","meaning":"吸引；引起兴趣","definition":"to seem attractive or interesting","examples":[{"en":"The quiet countryside does not appeal to everyone.","zh":"安静的乡村并非对所有人都有吸引力。"},{"en":"The course should appeal to beginners.","zh":"这门课程应该会吸引初学者。"}]},{"pos":"n.","meaning":"呼吁；恳求","definition":"a serious request for help or support","examples":[{"en":"The hospital launched an appeal for blood donors.","zh":"医院发出了招募献血者的呼吁。"},{"en":"Her appeal for patience was warmly received.","zh":"她呼吁大家耐心等待，得到了积极回应。"}]},{"pos":"n.","meaning":"上诉；申诉","definition":"a request for an official decision to be reviewed","examples":[{"en":"The court will hear the appeal next month.","zh":"法院将于下个月审理这起上诉。"},{"en":"He submitted an appeal against his dismissal.","zh":"他对被解雇一事提出了申诉。"}]},{"pos":"n.","meaning":"吸引力；感染力","definition":"the quality of being attractive or interesting","examples":[{"en":"The island's main appeal is its unspoilt coastline.","zh":"这座岛的主要吸引力在于其未经破坏的海岸线。"},{"en":"The story has a lasting appeal for children.","zh":"这个故事对孩子们有持久的吸引力。"}]}],"appear":[{"pos":"v.","meaning":"出现；显露","definition":"to become visible or present","examples":[{"en":"A rainbow appeared after the rain.","zh":"雨后出现了一道彩虹。"},{"en":"Small cracks began to appear in the wall.","zh":"墙上开始出现细小裂缝。"}]},{"pos":"v.","meaning":"登场；公开露面；出版","definition":"to perform, be seen publicly, or be published","examples":[{"en":"She will appear in a new television series.","zh":"她将出演一部新的电视剧。"},{"en":"His first article appeared in a local magazine.","zh":"他的第一篇文章发表在一本地方杂志上。"}]},{"pos":"v.","meaning":"似乎；好像","definition":"to seem to have a particular quality or state","examples":[{"en":"The solution appears to be effective.","zh":"这个解决办法似乎有效。"},{"en":"He appeared tired after the long journey.","zh":"长途旅行后，他看起来很疲惫。"}]}],"appearance":[{"pos":"n.","meaning":"外貌；外观","definition":"the way someone or something looks","examples":[{"en":"The renovation improved the building's appearance.","zh":"翻修改善了建筑的外观。"},{"en":"Do not judge the quality of fruit by appearance alone.","zh":"不要只凭外观判断水果的品质。"}]},{"pos":"n.","meaning":"出现；露面","definition":"the act of becoming visible or attending an event","examples":[{"en":"The sudden appearance of clouds changed our plans.","zh":"云层突然出现，改变了我们的计划。"},{"en":"The author made a brief appearance at the bookshop.","zh":"作者在书店短暂露面。"}]}],"appetite":[{"pos":"n.","meaning":"食欲；胃口","definition":"a desire to eat","examples":[{"en":"The long walk gave me a good appetite.","zh":"长时间步行让我胃口很好。"},{"en":"He lost his appetite during the illness.","zh":"他生病期间食欲不振。"}]},{"pos":"n.","meaning":"渴望；欲望","definition":"a strong desire for something","examples":[{"en":"The public has an appetite for reliable information.","zh":"公众渴望可靠的信息。"},{"en":"Her appetite for adventure has never faded.","zh":"她对冒险的渴望从未消退。"}]}],"applaud":[{"pos":"v.","meaning":"鼓掌；喝彩","definition":"to clap in approval or enjoyment","examples":[{"en":"The audience applauded when the musicians returned.","zh":"音乐家们返场时，观众鼓掌欢迎。"},{"en":"Parents applauded the children's performance.","zh":"家长们为孩子们的表演鼓掌。"}]},{"pos":"v.","meaning":"赞扬；赞同","definition":"to express strong approval of an action or idea","examples":[{"en":"We applaud the decision to protect the wetlands.","zh":"我们赞扬保护湿地的决定。"},{"en":"The report applauds the volunteers' commitment.","zh":"报告赞扬了志愿者们的投入。"}]}],"appliance":[{"pos":"n.","meaning":"家用电器；器具","definition":"a device used for a particular household task","examples":[{"en":"Choose an appliance that uses less electricity.","zh":"选择耗电更少的家用电器。"},{"en":"The kitchen has space for another small appliance.","zh":"厨房还有地方放一件小型电器。"}]}],"applicant":[{"pos":"n.","meaning":"申请人","definition":"a person who formally asks for a job or place","examples":[{"en":"Each applicant must provide two references.","zh":"每位申请人必须提供两位推荐人的信息。"},{"en":"The successful applicant will start work in June.","zh":"获录用的申请人将于六月开始工作。"},{"en":"We interviewed one applicant this morning.","zh":"我们今天上午面试了一位申请人。"}]}],"application":[{"pos":"n.","meaning":"申请","definition":"a formal request for something","examples":[{"en":"Please complete the application in black ink.","zh":"请用黑色墨水填写申请。"},{"en":"Your application will be reviewed within two weeks.","zh":"你的申请将在两周内审核。"},{"en":"The application requires proof of your address.","zh":"申请需要地址证明。"}]},{"pos":"n.","meaning":"软件应用程序","definition":"a computer program designed for a particular task","examples":[{"en":"This mobile application tracks your daily spending.","zh":"这款手机应用记录你的每日支出。"},{"en":"You can download the application from the official store.","zh":"你可以从官方商店下载这个应用程序。"},{"en":"The application needs an update before it can run.","zh":"这个应用程序需要更新后才能运行。"}]},{"pos":"n.","meaning":"应用；运用","definition":"the practical use of knowledge or a method","examples":[{"en":"The course explores the application of statistics to public health.","zh":"这门课程探讨统计学在公共卫生中的应用。"},{"en":"The new material has several industrial applications.","zh":"这种新材料有多种工业用途。"}]},{"pos":"n.","meaning":"涂抹；施用","definition":"the act of putting a substance on a surface","examples":[{"en":"Allow the first application of paint to dry.","zh":"先让第一遍涂上的油漆干透。"},{"en":"The instructions explain the correct application of the cream.","zh":"说明书解释了这种乳膏的正确涂抹方法。"}]}],"apply":[{"pos":"v.","meaning":"申请","definition":"to formally ask for a job, place, or permission","examples":[{"en":"She plans to apply for a research grant.","zh":"她计划申请一笔研究资助。"},{"en":"You must apply before the end of March.","zh":"你必须在三月底前提出申请。"}]},{"pos":"v.","meaning":"应用；使用；涂敷","definition":"to put something into use or onto a surface","examples":[{"en":"We can apply this method to other cities.","zh":"我们可以把这种方法应用于其他城市。"},{"en":"Apply a thin layer of paint to the wood.","zh":"在木头上涂一层薄薄的油漆。"}]},{"pos":"v.","meaning":"适用；涉及","definition":"to be relevant to a person or situation","examples":[{"en":"The discount does not apply to weekend bookings.","zh":"这个折扣不适用于周末预订。"},{"en":"These rules apply equally to every member.","zh":"这些规则同样适用于每位成员。"}]}],"appoint":[{"pos":"v.","meaning":"任命；委任","definition":"to choose someone officially for a position","examples":[{"en":"The board will appoint a new director next week.","zh":"董事会下周将任命一位新主管。"},{"en":"They decided to appoint her as team leader.","zh":"他们决定任命她为团队负责人。"}]},{"pos":"v.","meaning":"指定；约定时间或地点","definition":"to officially choose a time or place","examples":[{"en":"The judge will appoint a date for the hearing.","zh":"法官将指定听证日期。"},{"en":"They agreed to meet at the appointed hour.","zh":"他们同意在约定的时间见面。"}]}],"appointment":[{"pos":"n.","meaning":"预约","definition":"an arrangement to meet at a particular time","examples":[{"en":"I need to make an appointment with my doctor.","zh":"我需要预约看医生。"},{"en":"Please arrive ten minutes before your appointment.","zh":"请在预约时间前十分钟到达。"},{"en":"You can cancel the appointment online.","zh":"你可以在线取消预约。"}]}],"apportion":[{"pos":"v.","meaning":"分配；分摊","definition":"to divide something among people according to a plan","examples":[{"en":"The committee will apportion funds among the projects.","zh":"委员会将把资金分配给各个项目。"},{"en":"They agreed to apportion the costs equally.","zh":"他们同意平均分摊费用。"}]}],"appraisal":[{"pos":"n.","meaning":"评价；评估","definition":"an assessment of value, quality, or performance","examples":[{"en":"The bank requested an independent appraisal of the property.","zh":"银行要求对该房产进行独立评估。"},{"en":"Every employee receives an annual performance appraisal.","zh":"每名员工每年都会接受一次绩效评估。"}]}],"appreciate":[{"pos":"v.","meaning":"感谢；感激","definition":"to feel grateful for something","examples":[{"en":"I appreciate your help with the application.","zh":"我感谢你在申请方面提供的帮助。"},{"en":"We appreciate your patience during the repairs.","zh":"我们感谢你在维修期间的耐心。"},{"en":"I would appreciate it if you could reply soon.","zh":"如能尽快回复，我将不胜感激。"}]},{"pos":"v.","meaning":"欣赏；赏识","definition":"to recognise and enjoy the value or qualities of something","examples":[{"en":"I appreciate the quiet beauty of this landscape.","zh":"我欣赏这片风景宁静的美。"},{"en":"Visitors can appreciate the craftsmanship of the wooden furniture.","zh":"游客可以欣赏木制家具的精湛工艺。"}]},{"pos":"v.","meaning":"理解；意识到","definition":"to understand the importance or difficulty of something","examples":[{"en":"We appreciate how much work this will involve.","zh":"我们理解这将涉及多少工作。"},{"en":"She did not fully appreciate the risks at first.","zh":"她起初没有充分意识到风险。"}]},{"pos":"v.","meaning":"升值；增值","definition":"to increase in monetary value","examples":[{"en":"The property may appreciate over time.","zh":"这处房产可能随着时间升值。"},{"en":"The currency appreciated against the dollar.","zh":"这种货币相对于美元升值了。"}]}],"appreciate it if":[{"pos":"phr.","meaning":"如果……将不胜感激","definition":"a polite expression used to ask someone to do something","examples":[{"en":"I would appreciate it if you could reply by Friday.","zh":"如果你能在星期五之前回复，我将不胜感激。"},{"en":"We would appreciate it if visitors kept the entrance clear.","zh":"如果访客能保持入口畅通，我们将十分感谢。"}]}],"approach":[{"pos":"n.","meaning":"方法；处理方式","definition":"a way of dealing with something","examples":[{"en":"A flexible approach may produce better results.","zh":"灵活的方法可能产生更好的结果。"},{"en":"This approach focuses on prevention rather than treatment.","zh":"这种方法侧重预防而不是治疗。"},{"en":"The school adopted a new approach to reading instruction.","zh":"学校采用了新的阅读教学方法。"}]},{"pos":"v.","meaning":"接近；靠近；临近；即将到来","definition":"To move closer in distance or time.","examples":[{"en":"Please slow down as you approach the junction.","zh":"接近路口时请减速。"},{"en":"Visitors must not approach the wild animals.","zh":"游客不得靠近野生动物。"},{"en":"We could see the coast as we began to approach the island.","zh":"开始靠近小岛时，我们能看见海岸。"},{"en":"As winter approaches, the nights become longer.","zh":"随着冬天临近，夜晚变长。"},{"en":"The deadline is approaching faster than we expected.","zh":"截止日期比我们预想的更快地临近了。"}]},{"pos":"n.","meaning":"接近；靠近；来临","definition":"The act of getting nearer or the arrival of a time.","examples":[{"en":"The birds scattered at our approach.","zh":"我们靠近时，鸟儿四散飞走。"},{"en":"The approach of winter prompted urgent repairs.","zh":"冬季临近，促使人们赶紧维修。"}]}],"appropriate":[{"pos":"adj.","meaning":"适当的；合适的","definition":"suitable for a situation","examples":[{"en":"Choose an appropriate tone for a formal letter.","zh":"正式信件应选择合适语气。"},{"en":"The equipment must be appropriate for young children.","zh":"设备必须适合幼儿使用。"},{"en":"A solution that works here may not be appropriate elsewhere.","zh":"在这里有效的方案在别处可能并不合适。"}],"ipa":"/əˈprəʊpriət/"},{"pos":"v.","meaning":"侵占;挪用;擅自占有","definition":"to take something for one's own use without permission","examples":[{"en":"He appropriated public money for personal travel.","zh":"他挪用公款用于私人旅行。"},{"en":"The firm appropriated the artist's design without consent.","zh":"公司未经同意擅自使用艺术家的设计。"}],"ipa":"/əˈprəʊprieɪt/"},{"pos":"v.","meaning":"拨款;拨出供专用","definition":"to set aside money for a purpose","examples":[{"en":"The council appropriated funds for bridge repairs.","zh":"市议会拨款修桥。"},{"en":"Parliament appropriated money for disaster relief.","zh":"议会拨出救灾款。"}],"ipa":"/əˈprəʊprieɪt/"}],"approval":[{"pos":"n.","meaning":"赞同；认可","definition":"a favourable opinion of someone or something","examples":[{"en":"The plan won widespread public approval.","zh":"这项计划赢得了公众的广泛认可。"},{"en":"She nodded in approval when she heard the suggestion.","zh":"听到这个建议后，她赞许地点了点头。"}]},{"pos":"n.","meaning":"正式批准；许可","definition":"official permission for something","examples":[{"en":"Construction cannot begin without planning approval.","zh":"没有规划许可，施工不能开始。"},{"en":"The committee gave its approval to the proposal.","zh":"委员会批准了这项提案。"}]}],"approve":[{"pos":"v.","meaning":"赞成；认可","definition":"to think that something is good or acceptable","examples":[{"en":"Her parents approve of her decision to study abroad.","zh":"她的父母赞成她出国学习的决定。"},{"en":"Not everyone approved of the proposed changes.","zh":"并不是所有人都赞成拟议的调整。"}]},{"pos":"v.","meaning":"批准","definition":"to officially accept or permit something","examples":[{"en":"The council must approve the building plans.","zh":"市政委员会必须批准建筑方案。"},{"en":"The manager approved my request for leave.","zh":"经理批准了我的休假申请。"}]}],"approximate":[{"pos":"adj.","meaning":"大约的；近似的","definition":"close to the exact figure but not completely accurate","examples":[{"en":"Can you give me an approximate arrival time?","zh":"你能给我一个大致的到达时间吗？"},{"en":"The map shows the approximate location of the ruins.","zh":"地图标出了遗址的大概位置。"}],"ipa":"/əˈprɒksɪmət/"},{"pos":"v.","meaning":"接近；近似于","definition":"to be close to something in amount or quality","examples":[{"en":"These figures approximate the actual costs.","zh":"这些数字接近实际费用。"},{"en":"The artificial lighting should approximate natural daylight.","zh":"人工照明应尽量接近自然日光。"}],"ipa":"/əˈprɒksɪmeɪt/"}],"approximately":[{"pos":"adv.","meaning":"大约；近似地","definition":"close to a stated number or amount but not exact","examples":[{"en":"The journey takes approximately two hours.","zh":"这段旅程大约需要两小时。"},{"en":"Approximately half the participants completed the survey.","zh":"大约一半的参与者完成了调查。"}]}],"apt":[{"pos":"adj.","meaning":"恰当的；适宜的","definition":"especially suitable for a situation","examples":[{"en":"That is an apt description of the problem.","zh":"那是对这个问题的恰当描述。"},{"en":"She chose an apt quotation to open the speech.","zh":"她选了一句贴切的引语作为演讲开头。"}]},{"pos":"adj.","meaning":"易于……的；有……倾向的","definition":"likely to behave or happen in a particular way","examples":[{"en":"This old engine is apt to overheat.","zh":"这台旧发动机容易过热。"},{"en":"People are apt to forget details after a long delay.","zh":"时间久了，人们容易忘记细节。"}]},{"pos":"adj.","meaning":"聪明的；善于学习的","definition":"quick to learn and understand","examples":[{"en":"He proved an apt pupil in the workshop.","zh":"事实证明，他在实训课上是个悟性很好的学生。"},{"en":"The apt young musician mastered the passage quickly.","zh":"这位聪慧的年轻乐手很快掌握了这个乐段。"}]}],"aptitude":[{"pos":"n.","meaning":"天资；天赋；才能","definition":"a natural ability to learn or do something","examples":[{"en":"She showed an early aptitude for mathematics.","zh":"她很早就表现出了数学天赋。"},{"en":"The test measures aptitude rather than previous knowledge.","zh":"这项测试衡量的是潜在能力而非已有知识。"}]}],"aquarium":[{"pos":"n.","meaning":"水族箱；养鱼缸","definition":"a transparent container for keeping aquatic animals","examples":[{"en":"He cleans the aquarium every weekend.","zh":"他每周末清洗水族箱。"},{"en":"Several small fish swim around the plants in the aquarium.","zh":"几条小鱼绕着水族箱里的水草游动。"}]},{"pos":"n.","meaning":"水族馆","definition":"a public place where aquatic animals are displayed","examples":[{"en":"The class visited the aquarium to learn about marine life.","zh":"班级参观了水族馆，了解海洋生物。"},{"en":"The aquarium has an exhibition about coral reefs.","zh":"水族馆有一个关于珊瑚礁的展览。"}]}],"arable":[{"pos":"adj.","meaning":"可耕作的","definition":"suitable for growing crops","examples":[{"en":"Only a small part of the island is arable land.","zh":"岛上只有一小部分是可耕地。"},{"en":"The project aims to protect arable soil from erosion.","zh":"这个项目旨在保护可耕土壤免受侵蚀。"}]},{"pos":"n.","meaning":"耕地","definition":"land used or suitable for growing crops","examples":[{"en":"The estate includes woodland and arable.","zh":"这处庄园包括林地和耕地。"},{"en":"Some pasture was converted to arable.","zh":"一些牧场被改成了耕地。"}]}],"arboreal":[{"pos":"adj.","meaning":"树木的；栖于树上的","definition":"relating to trees or living in them","examples":[{"en":"The rainforest supports many arboreal mammals.","zh":"这片雨林养育着许多树栖哺乳动物。"},{"en":"The study examines arboreal habitats above the forest floor.","zh":"这项研究考察森林地面上方的树上栖息地。"}]}],"arcade":[{"pos":"n.","meaning":"拱廊；有拱顶的通道","definition":"a covered passage supported by arches","examples":[{"en":"The shops face a shaded arcade.","zh":"这些商店面向一条阴凉的拱廊。"},{"en":"We sheltered from the rain beneath the arcade.","zh":"我们在拱廊下避雨。"}]},{"pos":"n.","meaning":"室内商店街","definition":"a covered passage with shops along it","examples":[{"en":"A bookshop opened in the shopping arcade.","zh":"一家书店在室内商店街开业了。"},{"en":"The arcade contains several small cafés.","zh":"商店街内有几家小咖啡馆。"}]},{"pos":"n.","meaning":"电子游戏厅","definition":"a place with machines for playing games","examples":[{"en":"The children played racing games in the arcade.","zh":"孩子们在游戏厅里玩赛车游戏。"},{"en":"The seaside arcade was busy on Saturday.","zh":"周六，海边的游戏厅里很热闹。"}]}],"architect":[{"pos":"n.","meaning":"建筑师；设计师","definition":"a person who designs buildings","examples":[{"en":"The architect included a courtyard in the design.","zh":"建筑师在设计中加入了一个庭院。"},{"en":"We hired an architect to restore the old house.","zh":"我们聘请了一位建筑师修复这栋老房子。"}]},{"pos":"n.","meaning":"策划者；创造者","definition":"a person responsible for creating a plan or system","examples":[{"en":"She was the architect of the new training scheme.","zh":"她是这项新培训计划的设计者。"},{"en":"The programme's chief architect defended its aims.","zh":"该计划的主要策划者为其目标作了辩护。"}]}],"architecture":[{"pos":"n.","meaning":"建筑学；建筑设计或风格","definition":"the design of buildings and the style in which they are built","examples":[{"en":"She studied architecture before opening her own practice.","zh":"她在开设自己的事务所前学习了建筑学。"},{"en":"The town is famous for its medieval architecture.","zh":"这座城镇以中世纪建筑风格闻名。"}]},{"pos":"n.","meaning":"体系结构；系统架构","definition":"the overall structure and organization of a system","examples":[{"en":"The software uses a modular architecture.","zh":"这款软件采用模块化架构。"},{"en":"We need to review the network architecture before expanding it.","zh":"扩建网络前，我们需要审查其架构。"}]}],"archive":[{"pos":"n.","meaning":"档案；档案库；档案室","definition":"a collection of historical records or the place storing them","examples":[{"en":"The archive contains letters from local residents.","zh":"档案库保存了当地居民的信件。"},{"en":"Researchers can consult the newspaper archive online.","zh":"研究人员可以在线查阅报纸档案。"}]},{"pos":"v.","meaning":"存档；归档","definition":"to store records for future reference","examples":[{"en":"The library will archive all the photographs digitally.","zh":"图书馆将以数字形式保存所有照片。"},{"en":"Remember to archive the final version of the report.","zh":"记得把报告的最终版本存档。"}]}],"argue":[{"pos":"v.","meaning":"争论；争辩","definition":"to disagree with someone in words","examples":[{"en":"The neighbours argued about the boundary wall.","zh":"邻居们为界墙问题争论。"},{"en":"They argued for hours without reaching a decision.","zh":"他们争论了几个小时，仍未作出决定。"}]},{"pos":"v.","meaning":"论证；主张；说服","definition":"to give reasons supporting a position","examples":[{"en":"The report argues that public transport needs more funding.","zh":"报告主张公共交通需要更多资金。"},{"en":"She argued him into accepting the compromise.","zh":"她通过说理劝他接受了折中方案。"}]}],"argument":[{"pos":"n.","meaning":"争论；争吵","definition":"a disagreement expressed in words","examples":[{"en":"An argument broke out over the parking space.","zh":"人们为停车位发生了争吵。"},{"en":"They settled the argument without raising their voices.","zh":"他们没有提高嗓门就解决了争执。"}]},{"pos":"n.","meaning":"论据；论点；论证","definition":"a reason or set of reasons supporting a conclusion","examples":[{"en":"The report presents a strong argument for investment.","zh":"报告提出了支持投资的有力论据。"},{"en":"Her argument is based on evidence rather than opinion.","zh":"她的论证基于证据而非个人看法。"}]}],"aridity":[{"pos":"n.","meaning":"干旱；干燥","definition":"a lack of moisture or rainfall","examples":[{"en":"The region's aridity limits agricultural production.","zh":"该地区的干旱限制了农业生产。"},{"en":"These plants can survive extreme aridity.","zh":"这些植物能在极端干旱中存活。"}]},{"pos":"n.","meaning":"枯燥；乏味","definition":"a lack of interest, imagination, or emotional warmth","examples":[{"en":"Readers complained about the aridity of the report.","zh":"读者抱怨报告枯燥乏味。"},{"en":"The lecturer used stories to overcome the subject's apparent aridity.","zh":"讲师用故事消除了这个主题表面上的枯燥感。"}]}],"arithmetic":[{"pos":"n.","meaning":"算术","definition":"the use of numbers in calculations","examples":[{"en":"The children practised mental arithmetic every morning.","zh":"孩子们每天早上练习心算。"},{"en":"A simple arithmetic error changed the final total.","zh":"一个简单的算术错误改变了最终总数。"}]}],"arousal":[{"pos":"n.","meaning":"唤起；激发；兴奋状态","definition":"the act of producing a feeling or a state of alertness","examples":[{"en":"The experiment measured changes in emotional arousal.","zh":"实验测量了情绪唤起程度的变化。"},{"en":"Loud sounds can cause a sudden increase in arousal.","zh":"响亮的声音会突然提高警觉程度。"}]}],"arrange":[{"pos":"v.","meaning":"安排","definition":"to organise or plan something","examples":[{"en":"We can arrange a meeting next week.","zh":"我们可以安排下周开会。"},{"en":"Please arrange for someone to collect the parcel.","zh":"请安排人领取包裹。"},{"en":"The school will arrange transport for the visit.","zh":"学校会为此次参观安排交通。"}]},{"pos":"v.","meaning":"排列；整理","definition":"to put things in a particular order or position","examples":[{"en":"Please arrange the chairs in a circle.","zh":"请把椅子摆成一圈。"},{"en":"She arranged the photographs by date.","zh":"她按日期排列照片。"}]}],"arrangement":[{"pos":"n.","meaning":"安排；准备工作","definition":"a plan or action made to organize something","examples":[{"en":"We confirmed the travel arrangements by email.","zh":"我们通过电子邮件确认了旅行安排。"},{"en":"The arrangement allows both teams to share the room.","zh":"这项安排让两个团队能够共用房间。"}]},{"pos":"n.","meaning":"排列；布置","definition":"the way objects are positioned","examples":[{"en":"The seating arrangement encourages group discussion.","zh":"座位的排列有利于小组讨论。"},{"en":"She changed the arrangement of the flowers.","zh":"她改变了花朵的摆放方式。"}]}],"array":[{"pos":"n.","meaning":"一大批；一系列","definition":"a large or impressive collection of things","examples":[{"en":"The market offers an array of fresh vegetables.","zh":"市场供应种类繁多的新鲜蔬菜。"},{"en":"Visitors can choose from an array of activities.","zh":"游客可以从一系列活动中进行选择。"}]},{"pos":"n.","meaning":"整齐排列；阵列","definition":"an ordered arrangement of things","examples":[{"en":"An array of solar panels covers the roof.","zh":"屋顶上覆盖着一组太阳能电池板。"},{"en":"The telescope uses an array of linked sensors.","zh":"这台望远镜使用相互连接的传感器阵列。"}]},{"pos":"v.","meaning":"排列；部署","definition":"to arrange things or people in an ordered way","examples":[{"en":"The curator will array the objects along the wall.","zh":"策展人将把这些物品沿墙排列。"},{"en":"The soldiers were arrayed across the hillside.","zh":"士兵们部署在山坡上。"}]}],"arrival":[{"pos":"n.","meaning":"到达","definition":"the act of reaching a place","examples":[{"en":"Please confirm your arrival time with the hotel.","zh":"请向酒店确认你的到达时间。"},{"en":"A driver will meet you on arrival.","zh":"司机会在你到达时接你。"},{"en":"The screen shows the expected arrival of each train.","zh":"屏幕显示每班列车的预计到达时间。"}]}],"arrogance":[{"pos":"n.","meaning":"傲慢；自大","definition":"an attitude of believing oneself superior to others","examples":[{"en":"His arrogance made it difficult to work with him.","zh":"他的傲慢使别人很难与他共事。"},{"en":"Confidence should not turn into arrogance.","zh":"自信不应变成自大。"}]}],"artefact":[{"pos":"n.","meaning":"人工制品；历史器物","definition":"an object made by people, especially one of historical interest","examples":[{"en":"The museum displayed a bronze artefact from the site.","zh":"博物馆展出了在该遗址发现的一件青铜器物。"},{"en":"Each artefact was photographed before removal.","zh":"每件器物在移走之前都拍了照。"}]}],"artery":[{"pos":"n.","meaning":"动脉","definition":"a blood vessel carrying blood away from the heart","examples":[{"en":"The diagram shows the main artery leaving the heart.","zh":"这张图显示了离开心脏的主要动脉。"},{"en":"The surgeon repaired the damaged artery.","zh":"外科医生修复了受损的动脉。"}]},{"pos":"n.","meaning":"交通干线；要道","definition":"an important route carrying traffic or supplies","examples":[{"en":"The railway is a major artery of the region's transport system.","zh":"这条铁路是该地区交通系统的重要干线。"},{"en":"Flooding closed a vital artery into the city.","zh":"洪水封闭了一条通往城市的重要通道。"}]}],"arthritis":[{"pos":"n.","meaning":"关节炎","definition":"a condition involving painful inflammation of joints","examples":[{"en":"Arthritis made it difficult for her to open the jar.","zh":"关节炎使她难以打开罐子。"},{"en":"The clinic studies how arthritis affects daily movement.","zh":"这家诊所研究关节炎如何影响日常活动。"}]}],"artificial":[{"pos":"adj.","meaning":"人造的；人工的","definition":"made by people rather than occurring naturally","examples":[{"en":"The plants grow under artificial light.","zh":"这些植物在人工光照下生长。"},{"en":"The reservoir forms an artificial lake.","zh":"水库形成了一个人工湖。"}]},{"pos":"adj.","meaning":"假装的；不自然的","definition":"not sincere or natural","examples":[{"en":"Her artificial smile did not hide her disappointment.","zh":"她勉强的笑容掩饰不了失望。"},{"en":"The conversation felt stiff and artificial.","zh":"这次交谈显得拘谨而不自然。"}]},{"pos":"adj.","meaning":"模拟的；人为设置的","definition":"created to imitate real conditions","examples":[{"en":"The birds were studied in an artificial environment.","zh":"研究人员在模拟环境中观察这些鸟。"},{"en":"The test places drivers in an artificial traffic situation.","zh":"这项测试让驾驶者处于模拟交通情境中。"}]}],"as for/to":[{"pos":"phr.","meaning":"至于；关于","definition":"used to introduce a subject or refer to a particular matter","examples":[{"en":"As for the accommodation, we have already booked a room.","zh":"至于住宿，我们已经订好了房间。"},{"en":"There is some uncertainty as to the exact date.","zh":"关于确切日期，还有一些不确定之处。"}]}],"as if/though":[{"pos":"conj.","meaning":"好像；仿佛","definition":"in a way that suggests something is true","examples":[{"en":"He looked as if he had not slept.","zh":"他看起来好像没睡过觉。"},{"en":"She smiled as though she already knew the answer.","zh":"她微笑着，仿佛早已知道答案。"}]}],"ascend":[{"pos":"v.","meaning":"上升；攀登","definition":"to move upwards or climb","examples":[{"en":"Hot air begins to ascend through the chimney.","zh":"热空气开始沿烟囱上升。"},{"en":"We will ascend the mountain by the eastern path.","zh":"我们将沿东侧小径登山。"}]}],"ascertain":[{"pos":"v.","meaning":"查明；弄清；确定","definition":"to discover or establish a fact","examples":[{"en":"Investigators tried to ascertain the cause of the fire.","zh":"调查人员试图查明火灾原因。"},{"en":"Please ascertain whether the documents have arrived.","zh":"请确认文件是否已经送达。"}]}],"ascribe":[{"pos":"v.","meaning":"把……归因于；把……归属于","definition":"to consider something caused or created by someone or something","examples":[{"en":"Researchers ascribe the decline to habitat loss.","zh":"研究人员把这种下降归因于栖息地丧失。"},{"en":"The painting was once ascribed to a famous local artist.","zh":"这幅画曾被认为出自一位著名当地画家。"}]}],"ash":[{"pos":"n.","meaning":"灰；灰烬","definition":"the powder left after something burns","examples":[{"en":"A layer of ash covered the stove.","zh":"炉子上覆盖着一层灰。"},{"en":"Volcanic ash drifted over the nearby towns.","zh":"火山灰飘过附近的城镇。"}]},{"pos":"n.","meaning":"骨灰（通常用 ashes）","definition":"the remains of a body after cremation","examples":[{"en":"The family scattered his ashes at sea.","zh":"家人将他的骨灰撒入大海。"},{"en":"A small urn held her ashes.","zh":"一个小骨灰瓮装着她的骨灰。"}]}],"aspect":[{"pos":"n.","meaning":"方面；层面","definition":"one part or feature of a situation","examples":[{"en":"The report examines every aspect of the project.","zh":"报告考察了项目的各个方面。"},{"en":"Cost is only one aspect of the decision.","zh":"成本只是这项决定的一个方面。"}]},{"pos":"n.","meaning":"朝向","definition":"the direction in which a building or window faces","examples":[{"en":"The apartment has a southern aspect.","zh":"这套公寓朝南。"},{"en":"A sunny aspect makes the room warmer in winter.","zh":"朝阳的方位使房间在冬天更暖和。"}]},{"pos":"n.","meaning":"外观；样子","definition":"the appearance or character of something","examples":[{"en":"The garden takes on a different aspect in autumn.","zh":"花园在秋天呈现出不同的面貌。"},{"en":"Restoration changed the gloomy aspect of the building.","zh":"修复改变了这座建筑阴暗的外观。"}]}],"aspiration":[{"pos":"n.","meaning":"抱负；志向；强烈愿望","definition":"a strong hope of achieving something","examples":[{"en":"Her aspiration is to become a civil engineer.","zh":"她的志向是成为一名土木工程师。"},{"en":"The programme supports the career aspirations of young people.","zh":"这个项目支持年轻人的职业抱负。"}]}],"aspire":[{"pos":"v.","meaning":"渴望；有志于","definition":"to strongly hope to achieve something","examples":[{"en":"Many young researchers aspire to lead their own projects.","zh":"许多年轻研究人员希望主持自己的项目。"},{"en":"She does not aspire to fame, only to do useful work.","zh":"她不追求名气，只希望做有益的工作。"}]}],"assault":[{"pos":"n.","meaning":"攻击；袭击；侵犯人身罪","definition":"a violent attack or an offence involving threatening or harmful contact","examples":[{"en":"Police investigated the assault outside the station.","zh":"警方调查了车站外发生的袭击。"},{"en":"The witness described the assault in detail.","zh":"目击者详细描述了袭击经过。"}]},{"pos":"n.","meaning":"猛烈冲击；严厉抨击","definition":"a forceful attack on an idea or the senses","examples":[{"en":"The article launched an assault on the policy.","zh":"这篇文章猛烈抨击了该政策。"},{"en":"The loud music was an assault on our ears.","zh":"刺耳的音乐强烈刺激着我们的耳朵。"}]},{"pos":"v.","meaning":"袭击；攻击","definition":"to attack someone physically","examples":[{"en":"The man was arrested for assaulting a passenger.","zh":"这名男子因袭击乘客而被捕。"},{"en":"The guard intervened when a visitor tried to assault a worker.","zh":"一名访客试图袭击工作人员时，警卫介入了。"}]},{"pos":"v.","meaning":"猛烈冲击；使难受","definition":"to attack or overwhelm something forcefully","examples":[{"en":"Strong chemical smells assaulted our senses.","zh":"强烈的化学气味刺激着我们的感官。"},{"en":"Advertising messages assault commuters from every direction.","zh":"广告信息从四面八方冲击着通勤者。"}]}],"assemble":[{"pos":"v.","meaning":"集合；召集","definition":"to come together or bring people together","examples":[{"en":"The volunteers assembled outside the town hall.","zh":"志愿者们在市政厅外集合。"},{"en":"We assembled a team of engineers and designers.","zh":"我们组建了一支由工程师和设计师组成的团队。"}]},{"pos":"v.","meaning":"装配；组装","definition":"to fit parts together into a complete object","examples":[{"en":"It took an hour to assemble the bookshelf.","zh":"组装这个书架花了一个小时。"},{"en":"Workers assemble the bicycles in a nearby factory.","zh":"工人们在附近的一家工厂组装自行车。"}]}],"assert":[{"pos":"v.","meaning":"断言；声称","definition":"to state something confidently","examples":[{"en":"The authors assert that the method is reliable.","zh":"作者们断言这种方法可靠。"},{"en":"He continued to assert his innocence.","zh":"他继续声称自己无罪。"}]},{"pos":"v.","meaning":"坚持；维护；显示","definition":"to insist on a right or show authority clearly","examples":[{"en":"Workers must be able to assert their legal rights.","zh":"工人必须能够维护自己的合法权利。"},{"en":"She learned to assert herself in meetings.","zh":"她学会了在会议中坚持自己的意见。"}]}],"assess":[{"pos":"v.","meaning":"评估；评定","definition":"to judge the nature, quality, or importance of something","examples":[{"en":"The teacher will assess each student's progress.","zh":"老师会评估每个学生的进步。"},{"en":"Engineers assessed the damage after the storm.","zh":"暴风雨后，工程师评估了损坏情况。"}]},{"pos":"v.","meaning":"估价；核定金额","definition":"to calculate the value or amount of something","examples":[{"en":"The surveyor assessed the property's value.","zh":"测量师评估了房产价值。"},{"en":"The tax office assessed the amount owed.","zh":"税务机关核定了欠缴金额。"}]}],"assessment":[{"pos":"n.","meaning":"评估；考核；评价","definition":"the process of judging knowledge or performance","examples":[{"en":"The course includes continuous assessment.","zh":"这门课程包括持续性考核。"},{"en":"The assessment measures practical skills.","zh":"这项考核衡量实践技能。"},{"en":"Students receive feedback after each assessment.","zh":"学生每次考核后都会收到反馈。"}]},{"pos":"n.","meaning":"核定金额；核定税额","definition":"An officially calculated amount that must be paid.","examples":[{"en":"The owner disputed the tax assessment.","zh":"业主对核定税额提出了异议。"},{"en":"Each household received an assessment for the repair costs.","zh":"每户收到了核定的维修费用金额。"}]}],"asset":[{"pos":"n.","meaning":"资产；财产","definition":"something valuable that a person or organization owns","examples":[{"en":"The building is the company's most valuable asset.","zh":"这栋建筑是公司最有价值的资产。"},{"en":"Cash is a financial asset.","zh":"现金是一种金融资产。"}]},{"pos":"n.","meaning":"优点；有帮助的人或事物","definition":"a useful quality, person, or thing","examples":[{"en":"Her knowledge of local languages is a major asset.","zh":"她对当地语言的了解是一大优势。"},{"en":"He has become a real asset to the team.","zh":"他已经成为团队中真正有用的人才。"}]}],"assign":[{"pos":"v.","meaning":"分配；指派","definition":"to give someone a task, role, or resource","examples":[{"en":"The manager assigned a mentor to each new employee.","zh":"经理给每位新员工安排了一位导师。"},{"en":"Students were assigned different research topics.","zh":"学生们被分配了不同的研究题目。"}]},{"pos":"v.","meaning":"指定；确定","definition":"to give something a particular label or function","examples":[{"en":"The system assigns a number to each application.","zh":"系统给每份申请分配一个编号。"},{"en":"We assigned the spare room for storage.","zh":"我们把空房间指定为储藏室。"}]}],"assignment":[{"pos":"n.","meaning":"作业；学习任务；工作任务","definition":"A piece of work that someone is given to complete.","examples":[{"en":"The assignment must be submitted online.","zh":"作业必须在线提交。"},{"en":"Our final assignment is a short research report.","zh":"我们的期末作业是一篇简短的研究报告。"},{"en":"Ask your tutor if the assignment instructions are unclear.","zh":"如果作业要求不清楚，请询问导师。"},{"en":"Her first assignment was to interview the factory manager.","zh":"她的第一项工作任务是采访工厂经理。"},{"en":"The journalist completed a difficult overseas assignment.","zh":"这名记者完成了一项艰难的海外任务。"}]}],"assimilate":[{"pos":"v.","meaning":"吸收；理解并掌握","definition":"to take in and understand information or substances","examples":[{"en":"Students need time to assimilate new information.","zh":"学生需要时间来吸收新信息。"},{"en":"The body must assimilate nutrients from food.","zh":"身体必须从食物中吸收营养。"}]},{"pos":"v.","meaning":"同化；融入","definition":"to become or make someone part of a group or culture","examples":[{"en":"New arrivals should not be pressured to assimilate immediately.","zh":"不应要求新来者立即融入。"},{"en":"The policy tried to assimilate minority groups into a single culture.","zh":"这项政策试图将少数群体同化为单一文化。"}]}],"assimilation":[{"pos":"n.","meaning":"吸收；理解吸收","definition":"the process of taking in information or substances","examples":[{"en":"Regular practice helps the assimilation of new knowledge.","zh":"经常练习有助于吸收新知识。"},{"en":"The lesson includes time for the assimilation of difficult ideas.","zh":"这节课留出了消化难懂概念的时间。"}]},{"pos":"n.","meaning":"同化；融入","definition":"the process of becoming similar to or part of a larger group","examples":[{"en":"The study examines cultural assimilation among migrant families.","zh":"这项研究考察移民家庭的文化同化。"},{"en":"Assimilation does not always mean abandoning every tradition.","zh":"融入社会并不总意味着放弃所有传统。"}]}],"assist":[{"pos":"v.","meaning":"帮助；协助","definition":"to help someone do something","examples":[{"en":"A volunteer assisted the visitors with their luggage.","zh":"一名志愿者帮助游客搬运行李。"},{"en":"The software assists researchers in organizing references.","zh":"这款软件帮助研究人员整理参考文献。"}]}],"assistance":[{"pos":"n.","meaning":"帮助；援助","definition":"help or support","examples":[{"en":"Please contact the desk if you require assistance.","zh":"如果需要帮助，请联系服务台。"},{"en":"The charity provides financial assistance to families.","zh":"这家慈善机构向家庭提供经济援助。"}]}],"assistant":[{"pos":"n.","meaning":"助理；助手","definition":"a person who helps another person with work","examples":[{"en":"The assistant prepared the documents for the meeting.","zh":"助理准备了会议文件。"},{"en":"A laboratory assistant showed us how to use the equipment.","zh":"实验室助理向我们展示了如何使用设备。"}]},{"pos":"adj.","meaning":"助理的；副的","definition":"having a position below and helping a more senior person","examples":[{"en":"She became the assistant manager of the store.","zh":"她成为了商店的副经理。"},{"en":"The assistant coach organised the warm-up session.","zh":"助理教练组织了热身活动。"}]}],"assistantship":[{"pos":"n.","meaning":"助教或助研职位；相应助学资助","definition":"a university position that supports a graduate student through teaching or research work","examples":[{"en":"Her assistantship covers part of her tuition fees.","zh":"她的助教资助承担了部分学费。"},{"en":"He accepted a research assistantship in the physics department.","zh":"他接受了物理系的一份研究助理职位。"}]}],"associate":[{"pos":"v.","meaning":"联想；把……联系起来","definition":"to connect things in the mind","examples":[{"en":"Many people associate this song with their childhood.","zh":"许多人把这首歌与童年联系起来。"},{"en":"Do not automatically associate a high price with good quality.","zh":"不要自动把高价与优质联系起来。"}],"ipa":"/əˈsəʊsieɪt/"},{"pos":"v.","meaning":"交往；联合","definition":"to spend time with someone or join with others","examples":[{"en":"He prefers to associate with people who share his interests.","zh":"他更愿意和兴趣相投的人交往。"},{"en":"The two organisations associate to run the programme.","zh":"这两个组织联合开展该项目。"}],"ipa":"/əˈsəʊsieɪt/"},{"pos":"n.","meaning":"同事；伙伴","definition":"a person connected with someone through work or business","examples":[{"en":"She discussed the proposal with a business associate.","zh":"她与一位商业伙伴讨论了这项提议。"},{"en":"A former associate helped him find a new position.","zh":"一位以前的同事帮助他找到了新职位。"}],"ipa":"/əˈsəʊsiət/"},{"pos":"adj.","meaning":"副的；准的；联合的","definition":"having a related but sometimes lower-ranking position","examples":[{"en":"She was promoted to associate professor.","zh":"她晋升为副教授。"},{"en":"The association also admits associate members.","zh":"该协会也接纳准会员。"}],"ipa":"/əˈsəʊsiət/"}],"association":[{"pos":"n.","meaning":"协会；社团","definition":"an organised group with a shared purpose","examples":[{"en":"The residents' association meets every month.","zh":"居民协会每月开会。"},{"en":"She joined a professional association for translators.","zh":"她加入了一个翻译人员专业协会。"}]},{"pos":"n.","meaning":"关联；联系","definition":"a connection between people, ideas, or things","examples":[{"en":"The study found an association between sleep and concentration.","zh":"研究发现睡眠与注意力之间存在关联。"},{"en":"The song has a strong association with her childhood.","zh":"这首歌与她的童年有着紧密联系。"}]}],"assume":[{"pos":"v.","meaning":"假定；认为","definition":"to accept something as true without proof","examples":[{"en":"Do not assume that every household owns a car.","zh":"不要假定每个家庭都有汽车。"},{"en":"We assumed the library would remain open late.","zh":"我们以为图书馆会开放到很晚。"}]},{"pos":"v.","meaning":"承担；就任","definition":"to take on a responsibility or role","examples":[{"en":"She will assume responsibility for the project next month.","zh":"她下个月将承担这个项目的责任。"},{"en":"The new director assumed office in September.","zh":"新主任于九月就任。"}]}],"assumption":[{"pos":"n.","meaning":"假设；想当然的看法","definition":"something accepted as true without proof","examples":[{"en":"The argument rests on an untested assumption.","zh":"这个论点建立在未经验证的假设上。"},{"en":"We should question the assumption that longer hours mean better work.","zh":"我们应质疑工时更长就意味着工作更好的假设。"},{"en":"His assumption about the price turned out to be wrong.","zh":"他对价格的假设最终被证明错误。"}]},{"pos":"n.","meaning":"担任;承担;取得","definition":"the act of taking on a duty or power","examples":[{"en":"Her assumption of office was announced yesterday.","zh":"昨天宣布了她的就职。"},{"en":"The agreement requires assumption of existing debts.","zh":"协议要求承担现有债务。"}]}],"assurance":[{"pos":"n.","meaning":"保证；担保","definition":"a confident promise that something is true or will happen","examples":[{"en":"We received an assurance that the repairs would be completed.","zh":"我们得到保证，维修会完成。"},{"en":"The company gave assurances about the safety of its products.","zh":"公司对其产品安全作出了保证。"}]},{"pos":"n.","meaning":"自信；把握","definition":"confidence in one's ability or judgement","examples":[{"en":"She answered the questions with quiet assurance.","zh":"她沉着自信地回答了问题。"},{"en":"Experience gave him greater assurance in difficult situations.","zh":"经验使他在困难情况下更加自信。"}]},{"pos":"n.","meaning":"人寿保险（英式用法）","definition":"insurance providing payment after a person's death or a fixed period","examples":[{"en":"His employer offers a life assurance scheme.","zh":"他的雇主提供人寿保险计划。"},{"en":"They reviewed their assurance policy after having a child.","zh":"有了孩子后，他们重新审视了人寿保险保单。"}]}],"assure":[{"pos":"v.","meaning":"向……保证；使确信","definition":"to tell someone confidently that something is true","examples":[{"en":"The engineer assured us that the bridge was safe.","zh":"工程师向我们保证这座桥是安全的。"},{"en":"I can assure you that your comments will be considered.","zh":"我可以向你保证，你的意见会得到考虑。"}]},{"pos":"v.","meaning":"确保；保障","definition":"to make a desired result certain","examples":[{"en":"Regular maintenance helps assure the reliability of the system.","zh":"定期维护有助于保障系统的可靠性。"},{"en":"The agreement assures access to clean water for the village.","zh":"这份协议保障村民获得洁净水。"}]}],"asthma":[{"pos":"n.","meaning":"哮喘","definition":"a condition in which breathing can become difficult because airways narrow","examples":[{"en":"The school keeps an asthma care plan for the pupil.","zh":"学校为这名学生保存了一份哮喘照护计划。"},{"en":"He asked his doctor about managing asthma during exercise.","zh":"他向医生询问运动时如何管理哮喘。"}]}],"astonish":[{"pos":"v.","meaning":"使惊讶；使吃惊","definition":"to surprise someone very much","examples":[{"en":"The size of the ancient building astonished us.","zh":"古建筑的规模让我们惊叹。"},{"en":"Her quick recovery astonished everyone.","zh":"她恢复得如此快，让所有人都感到惊讶。"}]}],"astound":[{"pos":"v.","meaning":"使震惊；使十分惊讶","definition":"to surprise someone greatly","examples":[{"en":"The speed of the recovery astounded the doctors.","zh":"恢复速度让医生们十分惊讶。"},{"en":"The discovery continues to astound experienced researchers.","zh":"这一发现仍让经验丰富的研究人员震惊。"}]}],"astray":[{"pos":"adv.","meaning":"迷路地；误入歧途地","definition":"away from the correct path or proper course","examples":[{"en":"A misleading sign sent us astray.","zh":"一块误导性的标牌让我们走错了路。"},{"en":"Incomplete data can lead the investigation astray.","zh":"不完整的数据可能使调查偏离方向。"}]}],"astrology":[{"pos":"n.","meaning":"占星术；占星学","definition":"the belief that celestial positions influence human affairs","examples":[{"en":"The museum displays an old book about astrology.","zh":"博物馆展出了一本有关占星术的古书。"},{"en":"Astrology should not be confused with the science of astronomy.","zh":"占星术不应与天文学这门科学混淆。"}]}],"astronaut":[{"pos":"n.","meaning":"宇航员","definition":"a person trained to travel and work in space","examples":[{"en":"The astronaut practised repairs in a training pool.","zh":"宇航员在训练水池中练习维修。"},{"en":"Each astronaut carries out experiments during the mission.","zh":"每位宇航员都在任务期间开展实验。"}]}],"astronomy":[{"pos":"n.","meaning":"天文学","definition":"the study of stars, planets, and other objects in space","examples":[{"en":"Her interest in astronomy began with a small telescope.","zh":"她对天文学的兴趣始于一台小望远镜。"},{"en":"The museum offers an introductory astronomy course.","zh":"博物馆开设一门天文学入门课程。"}]}],"asymmetry":[{"pos":"n.","meaning":"不对称","definition":"a lack of equality or matching form between two sides","examples":[{"en":"The artist used asymmetry to make the design more dynamic.","zh":"艺术家利用不对称使设计更有动感。"},{"en":"The photograph reveals a slight asymmetry in the building.","zh":"照片显示建筑有轻微的不对称。"}]}],"at least":[{"pos":"phrase","meaning":"至少；起码","definition":"not less than a stated amount","examples":[{"en":"The walk takes at least forty minutes.","zh":"步行至少需要四十分钟。"},{"en":"At least three people must approve the decision.","zh":"这项决定至少需要三人批准。"}]}],"at random":[{"pos":"adv.","meaning":"随机地；任意地","definition":"without a fixed pattern or deliberate selection","examples":[{"en":"The names were selected at random.","zh":"这些名字是随机挑选的。"},{"en":"Choose a number at random and write it down.","zh":"随意选一个数字并写下来。"}]}],"athlete":[{"pos":"n.","meaning":"运动员","definition":"a person trained in sports or physical competition","examples":[{"en":"The athlete practises six days a week.","zh":"这名运动员每周训练六天。"},{"en":"Young athletes need time to rest as well as train.","zh":"年轻运动员除了训练也需要休息。"}]}],"atmosphere":[{"pos":"n.","meaning":"大气；大气层","definition":"the layer of gases surrounding a planet","examples":[{"en":"The atmosphere protects Earth from some harmful radiation.","zh":"大气层保护地球免受部分有害辐射。"},{"en":"The probe measured gases in the planet's atmosphere.","zh":"探测器测量了这颗行星大气中的气体。"}]},{"pos":"n.","meaning":"气氛；氛围","definition":"the mood or feeling of a place or situation","examples":[{"en":"Soft lighting created a relaxed atmosphere.","zh":"柔和的灯光营造了轻松的氛围。"},{"en":"The meeting took place in an atmosphere of trust.","zh":"会议在相互信任的气氛中进行。"}]}],"atmospheric":[{"pos":"adj.","meaning":"大气的；大气层的","definition":"relating to the Earth's atmosphere","examples":[{"en":"The station measures atmospheric pressure every hour.","zh":"这个站每小时测量一次大气压力。"},{"en":"Scientists tracked changes in atmospheric conditions.","zh":"科学家跟踪了大气状况的变化。"}]}],"atomic":[{"pos":"adj.","meaning":"原子的","definition":"relating to atoms","examples":[{"en":"The diagram illustrates atomic structure.","zh":"图示说明了原子结构。"},{"en":"Scientists studied the material at the atomic level.","zh":"科学家从原子层面研究了这种材料。"}]},{"pos":"adj.","meaning":"原子能的；核能的","definition":"relating to energy released from atomic nuclei","examples":[{"en":"The lecture traced the history of atomic energy.","zh":"讲座梳理了原子能的历史。"},{"en":"The treaty concerns the peaceful use of atomic power.","zh":"这项条约涉及原子能的和平利用。"}]}],"attach":[{"pos":"v.","meaning":"固定；贴；附上","definition":"to fasten or join something to another thing","examples":[{"en":"Attach the label to the outside of the parcel.","zh":"把标签贴在包裹外面。"},{"en":"Please attach a copy of your receipt to the form.","zh":"请在表格后附上一份收据副本。"}]},{"pos":"v.","meaning":"赋予（重要性、价值等）","definition":"to consider something to have particular importance or value","examples":[{"en":"The school attaches great importance to independent learning.","zh":"学校非常重视自主学习。"},{"en":"We should not attach too much significance to one result.","zh":"我们不应过分看重一个结果。"}]},{"pos":"v.","meaning":"使隶属；使附属","definition":"to assign someone or something to an organization","examples":[{"en":"Two advisers were attached to the research team.","zh":"两名顾问被派到研究团队协助工作。"},{"en":"The small laboratory is attached to the university.","zh":"这个小实验室隶属于大学。"}]}],"attack":[{"pos":"n.","meaning":"攻击；进攻","definition":"an act of trying to hurt or defeat someone","examples":[{"en":"The village survived the attack.","zh":"这个村庄在袭击中幸存下来。"},{"en":"The team launched an attack down the left side.","zh":"球队从左路发起进攻。"}]},{"pos":"v.","meaning":"攻击；进攻","definition":"to use force against someone or something","examples":[{"en":"The birds may attack if their nest is disturbed.","zh":"如果巢穴受到惊扰，这些鸟可能会攻击。"},{"en":"The army planned to attack at dawn.","zh":"军队计划黎明时发动进攻。"}]},{"pos":"n.","meaning":"抨击；批评","definition":"strong criticism","examples":[{"en":"The article was an attack on the government's policy.","zh":"这篇文章是对政府政策的抨击。"},{"en":"She responded calmly to the personal attack.","zh":"她冷静回应了人身攻击。"}]},{"pos":"v.","meaning":"抨击；批评","definition":"to criticize strongly","examples":[{"en":"Opponents attack the plan as wasteful.","zh":"反对者抨击该计划浪费资源。"},{"en":"It is unfair to attack her without hearing her explanation.","zh":"没有听她解释就攻击她是不公平的。"}]},{"pos":"n.","meaning":"疾病发作","definition":"a sudden period of illness or severe symptoms","examples":[{"en":"He suffered an asthma attack during the night.","zh":"他夜间哮喘发作。"},{"en":"The doctor asked when the first attack occurred.","zh":"医生询问首次发作是在什么时候。"}]},{"pos":"v.","meaning":"侵袭；损害","definition":"to damage or affect something harmfully","examples":[{"en":"The fungus can attack the roots.","zh":"这种真菌会侵害根部。"},{"en":"The disease tends to attack the nervous system.","zh":"这种疾病往往会侵袭神经系统。"}]}],"attain":[{"pos":"v.","meaning":"达到；获得；实现","definition":"to succeed in reaching a level, goal, or state","examples":[{"en":"She worked hard to attain the required standard.","zh":"她努力达到了要求的标准。"},{"en":"The programme aims to help learners attain greater independence.","zh":"该项目旨在帮助学习者获得更大的独立性。"}]}],"attainable":[{"pos":"adj.","meaning":"可达到的；可实现的","definition":"possible to achieve","examples":[{"en":"Set goals that are challenging but attainable.","zh":"设定有挑战性但能够实现的目标。"},{"en":"A lower energy bill is attainable with better insulation.","zh":"改善隔热后，降低能源账单是可以实现的。"}]}],"attempt":[{"pos":"n.","meaning":"尝试；努力","definition":"an effort to do something","examples":[{"en":"Her first attempt was unsuccessful.","zh":"她的第一次尝试没有成功。"},{"en":"The rescue attempt continued throughout the night.","zh":"救援行动持续了一整夜。"}]},{"pos":"v.","meaning":"尝试；试图","definition":"to try to do something","examples":[{"en":"They will attempt to repair the damaged bridge.","zh":"他们将尝试修复受损的桥梁。"},{"en":"Do not attempt this procedure without training.","zh":"未经培训不要尝试这一操作。"}]}],"attend":[{"pos":"v.","meaning":"出席；参加","definition":"to be present at an event or institution","examples":[{"en":"More than fifty people attended the workshop.","zh":"五十多人参加了研讨班。"},{"en":"She attends evening classes twice a week.","zh":"她每周上两次夜课。"}]},{"pos":"v.","meaning":"照料；陪同；服侍","definition":"to look after or provide a service to someone","examples":[{"en":"A nurse attended the injured passenger.","zh":"一名护士照料了受伤的乘客。"},{"en":"Two assistants attended the speaker throughout the visit.","zh":"两名助理在整个访问期间陪同发言人。"}]},{"pos":"v.","meaning":"注意；专心处理","definition":"to pay attention or deal with something, usually with to","examples":[{"en":"Please attend to the safety instructions.","zh":"请注意安全说明。"},{"en":"He had urgent business to attend to.","zh":"他有紧急事务要处理。"}]}],"attendance":[{"pos":"n.","meaning":"出勤；出席","definition":"being present at a class or event","examples":[{"en":"Regular attendance is required to complete the course.","zh":"完成这门课程需要定期出勤。"},{"en":"The teacher keeps a record of attendance.","zh":"老师记录出勤情况。"},{"en":"Poor attendance may affect your final grade.","zh":"出勤率低可能影响你的最终成绩。"}]},{"pos":"n.","meaning":"照料；侍候；陪护","definition":"The act of being present to care for someone.","examples":[{"en":"A nurse was in attendance throughout the night.","zh":"一名护士整夜在场照料。"},{"en":"The injured climber needed constant attendance.","zh":"受伤攀岩者需要持续陪护。"}]}],"attention":[{"pos":"n.","meaning":"注意；注意力","definition":"mental focus on something","examples":[{"en":"Please pay attention to the instructions.","zh":"请注意这些说明。"},{"en":"The unusual sound caught her attention.","zh":"这个不寻常的声音引起了她的注意。"}]},{"pos":"n.","meaning":"照料；关注","definition":"care or treatment directed towards someone or something","examples":[{"en":"The injured cyclist needed medical attention.","zh":"受伤的骑车人需要医疗照护。"},{"en":"This old house needs constant attention.","zh":"这栋老房子需要经常维护。"}]},{"pos":"n.","meaning":"立正姿势","definition":"a formal upright military position","examples":[{"en":"The soldiers stood at attention.","zh":"士兵们立正站好。"},{"en":"The officer called the group to attention.","zh":"军官下令全体立正。"}]}],"attentive":[{"pos":"adj.","meaning":"专心的；留意的","definition":"paying close attention","examples":[{"en":"The students were attentive during the demonstration.","zh":"演示期间，学生们十分专注。"},{"en":"Drivers must remain attentive even on quiet roads.","zh":"即使在安静的道路上，司机也必须保持注意力。"}]},{"pos":"adj.","meaning":"体贴的；周到的","definition":"careful to notice and meet another person's needs","examples":[{"en":"The staff were polite and attentive.","zh":"工作人员礼貌而周到。"},{"en":"He was attentive to his grandmother's comfort.","zh":"他细心照顾祖母，让她感到舒适。"}]}],"attitude":[{"pos":"n.","meaning":"态度；看法","definition":"a way of thinking or feeling about something","examples":[{"en":"Her attitude towards failure became more positive.","zh":"她对失败的态度变得更加积极。"},{"en":"The survey examined public attitudes to recycling.","zh":"这项调查研究了公众对回收利用的看法。"}]},{"pos":"n.","meaning":"姿态；姿势","definition":"a position of the body or an object's orientation","examples":[{"en":"The sculpture shows a figure in an attitude of prayer.","zh":"这座雕塑中的人物呈祈祷姿势。"},{"en":"The instruments display the aircraft's attitude during flight.","zh":"仪表显示飞机飞行时的姿态。"}]}],"attract":[{"pos":"v.","meaning":"吸引；引起注意","definition":"to draw someone or something towards oneself","examples":[{"en":"The exhibition is expected to attract many visitors.","zh":"预计这次展览会吸引许多游客。"},{"en":"Flowers attract insects with colour and scent.","zh":"花朵通过颜色和气味吸引昆虫。"}]}],"attraction":[{"pos":"n.","meaning":"吸引；吸引力；爱慕","definition":"a quality or feeling that draws interest or affection","examples":[{"en":"The city's main attraction is its lively cultural scene.","zh":"这座城市主要的吸引力是活跃的文化氛围。"},{"en":"She felt an immediate attraction to the peaceful village.","zh":"她立即被这个宁静的村庄吸引了。"}]},{"pos":"n.","meaning":"景点；有吸引力的事物","definition":"a place, person, or feature that draws visitors or attention","examples":[{"en":"The castle is a popular tourist attraction.","zh":"这座城堡是热门旅游景点。"},{"en":"The new exhibition has become the museum's biggest attraction.","zh":"新展览成了博物馆最吸引人的项目。"}]}],"attractive":[{"pos":"adj.","meaning":"有吸引力的；迷人的","definition":"pleasant or appealing to look at or consider","examples":[{"en":"The town offers attractive opportunities for young businesses.","zh":"这个城镇为新创企业提供了有吸引力的机会。"},{"en":"Trees made the courtyard more attractive.","zh":"树木让庭院更加美观。"}]}],"attribute":[{"pos":"v.","meaning":"把……归因于；认为……由某人所作","definition":"to regard something as caused or created by someone or something","examples":[{"en":"She attributes her success to years of practice.","zh":"她把成功归因于多年的练习。"},{"en":"Experts attribute the painting to an unknown local artist.","zh":"专家认为这幅画出自一位不知名的当地画家。"}],"ipa":"/əˈtrɪbjuːt/"},{"pos":"n.","meaning":"属性；品质；特征","definition":"a quality or characteristic","examples":[{"en":"Patience is an important attribute for a teacher.","zh":"耐心是教师的一项重要品质。"},{"en":"Each record includes an attribute for its creation date.","zh":"每条记录都包含一个创建日期属性。"}],"ipa":"/ˈætrɪbjuːt/"}],"audacious":[{"pos":"adj.","meaning":"大胆的；敢于冒险的","definition":"willing to take bold or unexpected risks","examples":[{"en":"The team proposed an audacious plan to restore the wetland.","zh":"团队提出了一个大胆的湿地修复计划。"},{"en":"Her audacious design won the competition.","zh":"她大胆的设计赢得了比赛。"}]},{"pos":"adj.","meaning":"放肆的；厚颜无耻的","definition":"showing a bold lack of respect","examples":[{"en":"It was an audacious attempt to take credit for someone else's work.","zh":"那是一次厚颜无耻地抢占他人功劳的尝试。"},{"en":"His audacious reply shocked the committee.","zh":"他放肆的回答令委员会震惊。"}]}],"audio":[{"pos":"adj.","meaning":"声音的；录音的","definition":"relating to sound or recorded sound","examples":[{"en":"The course includes audio exercises for every unit.","zh":"这门课程为每个单元配备了音频练习。"},{"en":"Please check the audio equipment before the presentation.","zh":"请在演示前检查音响设备。"}]}],"audit":[{"pos":"v.","meaning":"审计；查账","definition":"to examine financial records officially","examples":[{"en":"An independent firm will audit the accounts.","zh":"一家独立公司将审计这些账目。"},{"en":"The charity audits its finances every year.","zh":"这家慈善机构每年审计财务。"}]},{"pos":"v.","meaning":"旁听课程","definition":"to attend a course without receiving credit","examples":[{"en":"She plans to audit a course in art history.","zh":"她计划旁听一门艺术史课程。"},{"en":"Retired residents may audit some university lectures.","zh":"退休居民可以旁听部分大学课程。"}]},{"pos":"n.","meaning":"审计；正式检查","definition":"an official examination of records or procedures","examples":[{"en":"The annual audit found no major errors.","zh":"年度审计没有发现重大错误。"},{"en":"A safety audit identified several risks.","zh":"安全审查发现了几项风险。"}]}],"audition":[{"pos":"n.","meaning":"试演；试音；面试表演","definition":"a short performance used to judge suitability for a role","examples":[{"en":"She prepared two songs for the audition.","zh":"她为试音准备了两首歌。"},{"en":"The theatre held auditions for the new production.","zh":"剧院为新剧举行了试演。"}]}],"auditorium":[{"pos":"n.","meaning":"礼堂；观众厅；观众席","definition":"a large room or seating area for an audience","examples":[{"en":"The graduation ceremony filled the auditorium.","zh":"毕业典礼使礼堂坐满了人。"},{"en":"The auditorium has excellent views from every seat.","zh":"观众厅的每个座位都视野良好。"}]}],"augment":[{"pos":"v.","meaning":"增加；提高；扩大","definition":"to make something larger or more effective","examples":[{"en":"The grant will augment the library's resources.","zh":"这笔资助将增加图书馆的资源。"},{"en":"She took evening work to augment her income.","zh":"她做夜间工作来增加收入。"}]}],"authentic":[{"pos":"adj.","meaning":"真品的；真实的；可信的","definition":"genuine rather than copied or invented","examples":[{"en":"Experts confirmed that the painting was authentic.","zh":"专家确认这幅画是真迹。"},{"en":"The diary provides an authentic account of village life.","zh":"这本日记真实记录了乡村生活。"}]}],"authenticate":[{"pos":"v.","meaning":"鉴定真伪；验证身份","definition":"to prove that something or someone is genuine","examples":[{"en":"Experts were asked to authenticate the painting.","zh":"专家受邀鉴定这幅画的真伪。"},{"en":"The device uses a fingerprint to authenticate the user.","zh":"这个设备利用指纹验证用户身份。"}]}],"authorise":[{"pos":"v.","meaning":"授权；批准","definition":"to give official permission","examples":[{"en":"Only a manager can authorise the payment.","zh":"只有经理能批准这笔付款。"},{"en":"The owner must authorise access to the records.","zh":"查阅这些记录必须得到所有者的授权。"}]}],"authority":[{"pos":"n.","meaning":"权力；职权；管辖权","definition":"the power or right to make decisions and give orders","examples":[{"en":"Only the director has the authority to approve the payment.","zh":"只有主任有权批准这笔付款。"},{"en":"The dispute falls outside the committee's authority.","zh":"这起争议不属于委员会的管辖范围。"}]},{"pos":"n.","meaning":"当局；官方机构","definition":"an organisation or group with official power","examples":[{"en":"Local authorities maintain the public parks.","zh":"地方当局负责维护公共公园。"},{"en":"The transport authority announced changes to bus routes.","zh":"交通管理部门宣布调整公交线路。"}]},{"pos":"n.","meaning":"权威；专家","definition":"a person or source recognised as having expert knowledge","examples":[{"en":"She is an authority on medieval architecture.","zh":"她是中世纪建筑领域的权威。"},{"en":"The professor spoke with the authority of decades of research.","zh":"教授凭借数十年研究积累的权威发言。"}]}],"autobiography":[{"pos":"n.","meaning":"自传","definition":"a person's written account of their own life","examples":[{"en":"Her autobiography describes growing up in a coastal village.","zh":"她的自传描述了在沿海村庄长大的经历。"},{"en":"He began writing his autobiography after retiring.","zh":"他退休后开始写自传。"}]}],"autocratic":[{"pos":"adj.","meaning":"独裁的；专制的","definition":"controlling others with little regard for their opinions","examples":[{"en":"The workers objected to his autocratic management style.","zh":"工人们反对他专断的管理方式。"},{"en":"The country was ruled by an autocratic leader.","zh":"这个国家由一名独裁领导人统治。"}]}],"autoimmune":[{"pos":"adj.","meaning":"自身免疫的","definition":"involving an immune response against the body's own tissues","examples":[{"en":"The lecture explained the meaning of an autoimmune condition.","zh":"讲座解释了自身免疫性疾病这一概念。"},{"en":"Researchers are studying the causes of autoimmune disorders.","zh":"研究人员正在研究自身免疫性疾病的原因。"}]}],"automatically":[{"pos":"adv.","meaning":"自动地","definition":"without needing direct human control","examples":[{"en":"The lights switch off automatically after midnight.","zh":"午夜后灯会自动关闭。"},{"en":"The application automatically saves your work.","zh":"这个应用会自动保存你的工作。"}]},{"pos":"adv.","meaning":"不假思索地；无意识地","definition":"without consciously thinking about an action","examples":[{"en":"She automatically reached for her phone when it rang.","zh":"电话响起时，她下意识地伸手去拿。"},{"en":"I automatically smiled when I recognized him.","zh":"认出他时，我不由自主地笑了。"}]}],"automation":[{"pos":"n.","meaning":"自动化","definition":"the use of machines to carry out work automatically","examples":[{"en":"Automation can reduce repetitive manual work.","zh":"自动化可以减少重复性体力劳动。"},{"en":"Some workers fear losing their jobs to automation.","zh":"一些工人担心因自动化而失业。"},{"en":"Automation requires employees to learn new skills.","zh":"自动化要求员工学习新技能。"}]}],"autonomy":[{"pos":"n.","meaning":"自治；自治权","definition":"the right of a region or institution to govern itself","examples":[{"en":"The region was granted greater autonomy.","zh":"该地区被赋予了更大的自治权。"},{"en":"University autonomy allows institutions to design their own courses.","zh":"大学自治使各校能够自行设计课程。"}]},{"pos":"n.","meaning":"自主权；自主性","definition":"the ability to make one's own decisions","examples":[{"en":"The new role gives her considerable autonomy.","zh":"新职位给了她相当大的自主权。"},{"en":"Teachers encourage learners to develop autonomy.","zh":"教师鼓励学习者培养自主性。"}]}],"avail":[{"pos":"n.","meaning":"用处；效用","definition":"help or benefit, especially in a negative expression","examples":[{"en":"We searched the station to no avail.","zh":"我们搜遍了车站，却毫无结果。"},{"en":"Her repeated warnings were of little avail.","zh":"她反复的警告几乎没有起作用。"}]},{"pos":"v.","meaning":"有帮助；有益","definition":"to be useful or helpful","examples":[{"en":"Careful planning will avail us little without action.","zh":"没有行动，周密的计划也帮不了我们多少。"},{"en":"His experience did not avail him in the unfamiliar situation.","zh":"在这种陌生情境下，他的经验没能帮上忙。"}]},{"pos":"v.","meaning":"利用（avail oneself of）","definition":"to make use of an opportunity or service","examples":[{"en":"Students may avail themselves of the free advice service.","zh":"学生可以利用免费的咨询服务。"},{"en":"She availed herself of the chance to study abroad.","zh":"她利用了这次出国学习的机会。"}]}],"availability":[{"pos":"n.","meaning":"可获得性；可利用性；有空的时间","definition":"the state of being obtainable or ready for use","examples":[{"en":"The availability of clean water varies by region.","zh":"清洁水的可获得性因地区而异。"},{"en":"Please let us know your availability for an interview.","zh":"请告知我们你何时有空参加面试。"}]}],"available":[{"pos":"adj.","meaning":"可获得的；可用的","definition":"able to be obtained or used","examples":[{"en":"Free parking is available behind the building.","zh":"楼后有免费停车位。"},{"en":"Is the meeting room available this afternoon?","zh":"会议室今天下午空着吗？"},{"en":"Further information is available on our website.","zh":"我们的网站提供更多信息。"}]},{"pos":"adj.","meaning":"有空的；可与人见面的","definition":"not busy and able to meet or help someone","examples":[{"en":"The manager is available after lunch.","zh":"经理午饭后有空。"},{"en":"Are you available to help us on Friday?","zh":"你星期五有空帮我们吗？"}]}],"avalanche":[{"pos":"n.","meaning":"雪崩","definition":"a large mass of snow sliding down a mountain","examples":[{"en":"An avalanche blocked the mountain road.","zh":"一场雪崩堵住了山路。"},{"en":"The team studied the path of a recent avalanche.","zh":"团队研究了最近一次雪崩的路径。"}]},{"pos":"v.","meaning":"发生雪崩；大量倾泻","definition":"to move downward like a mass of falling snow","examples":[{"en":"Loose snow avalanched down the steep slope.","zh":"松散的积雪从陡坡上崩落。"},{"en":"Rocks and ice avalanched into the valley.","zh":"岩石和冰块大量坠入山谷。"}]}],"avenge":[{"pos":"v.","meaning":"为……报仇；报复","definition":"to punish someone for a wrong done to oneself or another","examples":[{"en":"The character vows to avenge his brother's death.","zh":"这个角色发誓要为哥哥之死报仇。"},{"en":"They sought to avenge the earlier defeat.","zh":"他们试图为先前的失败雪耻。"}]}],"avenue":[{"pos":"n.","meaning":"大街；林荫大道","definition":"a wide road, often lined with trees","examples":[{"en":"We walked along an avenue lined with oak trees.","zh":"我们沿着一条橡树成荫的大道散步。"},{"en":"The hotel is on a busy avenue near the station.","zh":"酒店位于车站附近一条繁忙的大街上。"}]},{"pos":"n.","meaning":"途径；方法","definition":"a possible way of achieving something","examples":[{"en":"The discovery opens a new avenue for research.","zh":"这个发现开辟了新的研究途径。"},{"en":"We explored every avenue before cancelling the project.","zh":"我们在取消项目前探索了所有可行途径。"}]}],"average":[{"pos":"n.","meaning":"平均数；平均水平","definition":"a number representing a typical value in a set","examples":[{"en":"The average of the three scores is seventy.","zh":"这三个分数的平均数是七十。"},{"en":"This month's rainfall was above average.","zh":"这个月的降雨量高于平均水平。"}]},{"pos":"adj.","meaning":"平均的","definition":"calculated by dividing a total by the number of items","examples":[{"en":"The average journey time is twenty minutes.","zh":"平均行程时间是二十分钟。"},{"en":"Average temperatures rose during the decade.","zh":"这十年间平均气温上升了。"}]},{"pos":"adj.","meaning":"普通的；一般的","definition":"typical or neither very good nor very bad","examples":[{"en":"The flat is too expensive for an average household.","zh":"这个公寓对普通家庭来说太贵了。"},{"en":"His first exam results were fairly average.","zh":"他第一次考试的成绩相当一般。"}]},{"pos":"v.","meaning":"平均达到；计算平均数","definition":"to have or calculate a particular mean value","examples":[{"en":"The cyclists averaged thirty kilometres an hour.","zh":"骑行者的平均时速为三十公里。"},{"en":"We averaged the readings from all five sensors.","zh":"我们计算了五个传感器读数的平均值。"}]}],"aviation":[{"pos":"n.","meaning":"航空；飞行；航空业","definition":"the operation and development of aircraft","examples":[{"en":"The museum traces the history of aviation.","zh":"博物馆展示了航空发展的历史。"},{"en":"New technology is changing the aviation industry.","zh":"新技术正在改变航空业。"}]}],"avoid":[{"pos":"v.","meaning":"避免；防止","definition":"to prevent an undesirable event from happening","examples":[{"en":"Plan your journey early to avoid delays.","zh":"提前规划行程，以避免延误。"},{"en":"Regular maintenance can help avoid costly repairs.","zh":"定期维护有助于避免昂贵的维修。"}]},{"pos":"v.","meaning":"躲开；回避","definition":"to keep away from someone or something","examples":[{"en":"We avoided the crowded shopping streets.","zh":"我们避开了拥挤的商业街。"},{"en":"He avoided answering the question directly.","zh":"他回避直接回答这个问题。"}]}],"award":[{"pos":"n.","meaning":"奖；裁定给予的款项","definition":"a prize or an amount granted by an official decision","examples":[{"en":"The film received an award for its photography.","zh":"这部电影获得了摄影奖。"},{"en":"The court approved an award of compensation.","zh":"法院批准了赔偿裁定。"}]},{"pos":"v.","meaning":"授予；判给","definition":"to officially give a prize or payment","examples":[{"en":"The university awarded her a scholarship.","zh":"大学授予她一笔奖学金。"},{"en":"The judge awarded damages to the injured cyclist.","zh":"法官判给受伤的骑行者损害赔偿金。"}]}],"aware":[{"pos":"adj.","meaning":"知道的；意识到的","definition":"knowing or noticing something","examples":[{"en":"Are you aware of the new regulations?","zh":"你知道这些新规定吗？"},{"en":"She became aware that someone was following her.","zh":"她意识到有人在跟着她。"}]}],"awful":[{"pos":"adj.","meaning":"糟糕的；令人不快的","definition":"very bad or unpleasant","examples":[{"en":"The weather was awful throughout the trip.","zh":"整个旅程天气都很糟糕。"},{"en":"An awful smell came from the broken drain.","zh":"坏掉的排水管散发出难闻的气味。"}]}],"axle":[{"pos":"n.","meaning":"车轴；轮轴","definition":"a shaft on which a wheel turns","examples":[{"en":"The mechanic replaced the damaged rear axle.","zh":"技工更换了损坏的后轴。"},{"en":"A heavy load can put extra pressure on the axle.","zh":"重物会给车轴增加压力。"}]}],"bachelor":[{"pos":"n.","meaning":"单身汉","definition":"a man who has not married","examples":[{"en":"He remained a bachelor throughout his life.","zh":"他终身未婚。"},{"en":"The novel follows the life of a young bachelor.","zh":"这部小说讲述一位年轻单身汉的生活。"}]},{"pos":"n.","meaning":"学士","definition":"a person who holds a first university degree","examples":[{"en":"She graduated as a Bachelor of Science.","zh":"她毕业时获得了理学学士学位。"},{"en":"He holds a bachelor's degree in economics.","zh":"他拥有经济学学士学位。"}]}],"backbone":[{"pos":"n.","meaning":"脊柱；脊椎","definition":"the line of bones supporting the back","examples":[{"en":"The model shows how the backbone supports the body.","zh":"模型展示了脊柱如何支撑身体。"},{"en":"The fossil includes part of the animal's backbone.","zh":"这块化石包含该动物的部分脊柱。"}]},{"pos":"n.","meaning":"骨干；支柱","definition":"the main support or strength of something","examples":[{"en":"Small businesses form the backbone of the local economy.","zh":"小企业是当地经济的支柱。"},{"en":"Volunteers are the backbone of the organisation.","zh":"志愿者是这个组织的骨干。"}]},{"pos":"n.","meaning":"骨气；勇气","definition":"strength of character and determination","examples":[{"en":"It takes backbone to defend an unpopular decision.","zh":"捍卫一项不受欢迎的决定需要勇气。"},{"en":"She showed backbone when she refused the unfair demand.","zh":"她拒绝不公平要求时表现出了骨气。"}]}],"background":[{"pos":"n.","meaning":"背景；不显眼的位置","definition":"the part behind the main subject or activity","examples":[{"en":"Mountains are visible in the background of the photograph.","zh":"照片的背景中可以看到群山。"},{"en":"Quiet music played in the background.","zh":"轻柔的音乐在背景中播放。"}]},{"pos":"n.","meaning":"经历；出身；背景知识","definition":"a person's experience or information needed to understand something","examples":[{"en":"Her background in engineering helped with the project.","zh":"她的工程学背景对这个项目很有帮助。"},{"en":"The first chapter provides background to the debate.","zh":"第一章提供了理解这场争论所需的背景信息。"}]},{"pos":"n.","meaning":"后台","definition":"computer activity running without direct user interaction","examples":[{"en":"The program checks for updates in the background.","zh":"这个程序在后台检查更新。"},{"en":"A background task continued after the window closed.","zh":"窗口关闭后，一项后台任务仍在继续运行。"}]}],"bacterial":[{"pos":"adj.","meaning":"细菌的；由细菌引起的","definition":"relating to bacteria or caused by them","examples":[{"en":"The laboratory tested the water for bacterial contamination.","zh":"实验室检测了水中的细菌污染。"},{"en":"The doctor suspected a bacterial infection.","zh":"医生怀疑是细菌感染。"}]}],"badge":[{"pos":"n.","meaning":"徽章；胸牌","definition":"a small sign worn to identify a person or organisation","examples":[{"en":"Visitors must wear an identification badge.","zh":"访客必须佩戴身份胸牌。"},{"en":"The guide wore a badge with the museum's name.","zh":"导游佩戴着印有博物馆名称的徽章。"}]},{"pos":"n.","meaning":"标志；象征","definition":"a visible sign of status or achievement","examples":[{"en":"The award became a badge of professional achievement.","zh":"该奖项成了专业成就的象征。"},{"en":"For him, muddy boots were a badge of hard work.","zh":"对他来说，沾满泥的靴子是辛勤工作的标志。"}]}],"badminton":[{"pos":"n.","meaning":"羽毛球运动","definition":"a game played by hitting a shuttlecock over a net","examples":[{"en":"We play badminton in the sports hall on Fridays.","zh":"我们每周五在体育馆打羽毛球。"},{"en":"She joined the university badminton club.","zh":"她加入了大学羽毛球俱乐部。"}]}],"baffle":[{"pos":"v.","meaning":"使困惑；难倒","definition":"to make someone unable to understand something","examples":[{"en":"The strange result continues to baffle researchers.","zh":"这个奇怪的结果仍让研究人员困惑。"},{"en":"Complicated instructions can baffle new users.","zh":"复杂的说明可能难倒新用户。"}]},{"pos":"n.","meaning":"挡板；隔板","definition":"a barrier used to control the flow of sound, gas, or liquid","examples":[{"en":"A metal baffle directs air towards the outlet.","zh":"一块金属挡板将空气导向出口。"},{"en":"The technician replaced the damaged baffle inside the tank.","zh":"技术员更换了水箱内损坏的隔板。"}]}],"baggage":[{"pos":"n.","meaning":"行李","definition":"bags and cases carried when travelling","examples":[{"en":"Please collect your baggage before leaving the airport.","zh":"离开机场前请领取行李。"},{"en":"The airline allows one small piece of hand baggage.","zh":"这家航空公司允许携带一件小型手提行李。"}]},{"pos":"n.","meaning":"过去经历带来的心理负担","definition":"emotional difficulties carried from past experiences","examples":[{"en":"He brought emotional baggage from his previous relationship.","zh":"他带着上一段感情留下的心理负担。"},{"en":"Talking to a counsellor helped her deal with that baggage.","zh":"与心理咨询师交谈帮助她处理了那份心理负担。"}]}],"balance":[{"pos":"n.","meaning":"平衡","definition":"a steady state or a suitable mixture of different things","examples":[{"en":"The gymnast kept her balance on the beam.","zh":"体操运动员在平衡木上保持平衡。"},{"en":"A healthy balance between work and rest is important.","zh":"工作与休息之间的健康平衡很重要。"}]},{"pos":"n.","meaning":"余额；余款","definition":"the amount remaining in an account or still to be paid","examples":[{"en":"You can check your account balance online.","zh":"你可以在线查询账户余额。"},{"en":"The balance must be paid before delivery.","zh":"余款必须在交货前付清。"}]},{"pos":"v.","meaning":"使平衡；权衡","definition":"to keep something steady or give suitable attention to competing things","examples":[{"en":"He balanced the tray on one hand.","zh":"他用一只手稳稳地托住托盘。"},{"en":"The policy must balance growth with environmental protection.","zh":"政策必须兼顾增长与环境保护。"}]}],"balcony":[{"pos":"n.","meaning":"阳台","definition":"a raised outdoor platform attached to a building","examples":[{"en":"We ate breakfast on the balcony overlooking the sea.","zh":"我们在面朝大海的阳台上吃早餐。"},{"en":"The flat has a small balcony for growing herbs.","zh":"这个公寓有一个可以种香草的小阳台。"}]},{"pos":"n.","meaning":"楼座","definition":"an upper seating area in a theatre","examples":[{"en":"Our seats were in the front row of the balcony.","zh":"我们的座位在楼座第一排。"},{"en":"The balcony offers a clear view of the stage.","zh":"楼座可以清楚地看到舞台。"}]}],"bamboo":[{"pos":"n.","meaning":"竹；竹子","definition":"a tall grass with hard hollow stems","examples":[{"en":"They built a fence from bamboo.","zh":"他们用竹子做了围栏。"},{"en":"Bamboo grows quickly in suitable conditions.","zh":"竹子在合适的条件下生长很快。"}]}],"band":[{"pos":"n.","meaning":"乐队","definition":"a group of musicians performing together","examples":[{"en":"A local band played at the festival.","zh":"一支本地乐队在节日上演出。"},{"en":"She joined a jazz band at college.","zh":"她在大学加入了一支爵士乐队。"}]},{"pos":"n.","meaning":"一伙；一群","definition":"a group of people sharing an activity or purpose","examples":[{"en":"A band of volunteers cleared the beach.","zh":"一群志愿者清理了海滩。"},{"en":"The story follows a small band of travellers.","zh":"故事讲述一小群旅行者的经历。"}]},{"pos":"n.","meaning":"带子；箍；环","definition":"a strip of material used to hold or surround something","examples":[{"en":"A rubber band held the papers together.","zh":"一根橡皮筋把文件扎在一起。"},{"en":"The lid is secured with a metal band.","zh":"盖子用一个金属箍固定。"}]},{"pos":"n.","meaning":"条纹；带状区域","definition":"a narrow strip of colour or material","examples":[{"en":"The rock contains a dark band of minerals.","zh":"这块岩石中有一条深色矿物带。"},{"en":"A band of cloud covered the mountains.","zh":"一条云带笼罩着群山。"}]},{"pos":"n.","meaning":"频段；波段；范围","definition":"a range of frequencies, values, or categories","examples":[{"en":"The radio can receive signals in this band.","zh":"收音机可以接收这个频段的信号。"},{"en":"Applicants were placed in different salary bands.","zh":"申请者被划入不同的薪资档次。"}]},{"pos":"v.","meaning":"用带捆扎；使联合","definition":"to fasten with a band or join together","examples":[{"en":"Workers banded the boxes before loading them.","zh":"工人在装货前用带子捆好了箱子。"},{"en":"Residents banded together to save the library.","zh":"居民们联合起来保护图书馆。"}]}],"bankrupt":[{"pos":"adj.","meaning":"破产的","definition":"unable to pay debts","examples":[{"en":"The company went bankrupt after losing its main contract.","zh":"这家公司失去主要合同后破产了。"},{"en":"Several small shops were left bankrupt by the crisis.","zh":"几家小商店因这场危机而破产。"}]}],"bankruptcy":[{"pos":"n.","meaning":"破产","definition":"a legal state of being unable to pay debts","examples":[{"en":"The company filed for bankruptcy after years of losses.","zh":"这家公司在连年亏损后申请破产。"},{"en":"The agreement helped the business avoid bankruptcy.","zh":"这项协议帮助企业避免了破产。"}]},{"pos":"n.","meaning":"彻底缺乏；破产性失败","definition":"a complete lack of a valuable quality or effective ideas","examples":[{"en":"The scandal exposed the moral bankruptcy of the leadership.","zh":"丑闻暴露了领导层道德上的彻底败坏。"},{"en":"Critics saw the policy as evidence of intellectual bankruptcy.","zh":"批评者认为这项政策体现了思想上的枯竭。"}]}],"banner":[{"pos":"n.","meaning":"横幅；旗帜","definition":"a large strip of cloth displaying a message or symbol","examples":[{"en":"A banner welcomed the new students.","zh":"一条横幅欢迎新生。"},{"en":"Protesters carried banners through the square.","zh":"抗议者举着横幅穿过广场。"}]}],"bar":[{"pos":"n.","meaning":"酒吧；吧台","definition":"a place or counter where drinks are served","examples":[{"en":"We met at a quiet bar near the station.","zh":"我们在车站附近一家安静的酒吧见面。"},{"en":"She ordered a juice at the bar.","zh":"她在吧台点了一杯果汁。"}]},{"pos":"n.","meaning":"条；棒；栅栏杆","definition":"a long narrow piece of solid material","examples":[{"en":"A metal bar reinforced the wooden door.","zh":"一根金属条加固了木门。"},{"en":"Sunlight came through the bars of the window.","zh":"阳光从窗户的栅栏杆之间照了进来。"}]},{"pos":"v.","meaning":"阻止；禁止；拦住","definition":"to prevent someone from doing or entering something","examples":[{"en":"The rules bar visitors from entering the laboratory alone.","zh":"规则禁止访客独自进入实验室。"},{"en":"Fallen trees barred the path through the forest.","zh":"倒下的树挡住了穿过森林的小路。"}]},{"pos":"v.","meaning":"闩住","definition":"to fasten a door with a bar","examples":[{"en":"They barred the door before the storm arrived.","zh":"暴风雨来临前，他们闩住了门。"},{"en":"The old gate was barred from the inside.","zh":"旧大门从里面闩住了。"}]}],"barbaric":[{"pos":"adj.","meaning":"残忍的；野蛮的","definition":"extremely cruel or uncivilized","examples":[{"en":"The prisoners were subjected to barbaric treatment.","zh":"囚犯遭受了残酷待遇。"},{"en":"Such barbaric violence cannot be justified.","zh":"这种野蛮暴力无法得到辩解。"}]},{"pos":"adj.","meaning":"粗野的；原始部族风格的（历史用语）","definition":"described historically as rough or outside the writer's idea of civilization","examples":[{"en":"The chronicler dismissed the unfamiliar ceremony as barbaric.","zh":"编年史作者把陌生仪式贬为粗野。"},{"en":"The conquerors branded the local customs barbaric.","zh":"征服者给当地习俗贴上了野蛮的标签。"}]}],"barbecue":[{"pos":"n.","meaning":"烧烤架","definition":"a device used to cook food outdoors over heat","examples":[{"en":"He cleaned the barbecue after lunch.","zh":"午餐后他清洗了烧烤架。"},{"en":"The garden has space for a small barbecue.","zh":"花园里有放置小型烧烤架的空间。"}]},{"pos":"n.","meaning":"烧烤聚餐；烧烤食物","definition":"an outdoor meal where food is cooked over direct heat","examples":[{"en":"We held a barbecue for our neighbours.","zh":"我们为邻居举办了烧烤聚餐。"},{"en":"Rain forced us to cancel the barbecue.","zh":"下雨迫使我们取消烧烤聚会。"}]}],"bare":[{"pos":"adj.","meaning":"赤裸的；无遮盖的","definition":"not covered by clothing or another layer","examples":[{"en":"She walked across the warm sand with bare feet.","zh":"她赤脚走过温暖的沙滩。"},{"en":"The wind stripped the branches bare.","zh":"风把树枝吹得光秃秃的。"}]},{"pos":"adj.","meaning":"空的；仅有最基本内容的","definition":"without furniture, decoration, or extra detail","examples":[{"en":"The room was bare except for a wooden chair.","zh":"房间里除了一把木椅外空无一物。"},{"en":"The report gave only the bare facts.","zh":"报告只提供了最基本的事实。"}]}],"barely":[{"pos":"adv.","meaning":"仅仅；勉强；几乎不","definition":"only just or almost not","examples":[{"en":"We barely caught the last train.","zh":"我们勉强赶上了末班火车。"},{"en":"The music was so quiet that I could barely hear it.","zh":"音乐声很轻，我几乎听不见。"}]}],"bargain":[{"pos":"v.","meaning":"讨价还价；商谈条件","definition":"to negotiate a price or agreement","examples":[{"en":"They bargained with the seller for a lower price.","zh":"他们与卖家讨价还价，希望降低价格。"},{"en":"Workers bargained for better conditions.","zh":"工人们为争取更好的条件进行谈判。"}]},{"pos":"n.","meaning":"协议；交易","definition":"an agreement between two parties","examples":[{"en":"Both sides agreed to keep their bargain.","zh":"双方同意履行约定。"},{"en":"The bargain gave each group access to the land.","zh":"这项协议使每个群体都能使用这片土地。"}]},{"pos":"n.","meaning":"便宜货；划算的买卖","definition":"something bought for less than its usual value","examples":[{"en":"This second-hand desk was a real bargain.","zh":"这张二手书桌真是便宜货。"},{"en":"You can find good bargains at the weekend market.","zh":"周末市场可以买到划算的东西。"}]}],"barge":[{"pos":"n.","meaning":"驳船","definition":"a flat-bottomed boat used to transport heavy goods","examples":[{"en":"A barge carried timber along the canal.","zh":"一艘驳船沿运河运送木材。"},{"en":"The workers unloaded sand from the barge.","zh":"工人们从驳船上卸下沙子。"}]},{"pos":"v.","meaning":"猛撞；闯入","definition":"to move forcefully and without care","examples":[{"en":"He barged past the queue and entered the hall.","zh":"他从队伍旁猛冲过去，闯进大厅。"},{"en":"Please knock rather than barge into the office.","zh":"请先敲门，不要直接闯进办公室。"}]}],"bark":[{"pos":"v.","meaning":"吠叫","definition":"to make the sharp sound of a dog","examples":[{"en":"The dog began to bark at the gate.","zh":"那条狗开始在门口吠叫。"},{"en":"Some dogs bark when they are left alone.","zh":"有些狗独处时会叫。"}]},{"pos":"n.","meaning":"吠叫声","definition":"the sharp sound made by a dog","examples":[{"en":"A sudden bark woke the baby.","zh":"一声突然的狗叫惊醒了婴儿。"},{"en":"We heard a bark from behind the fence.","zh":"我们听到围栏后传来一声狗叫。"}]},{"pos":"n.","meaning":"树皮","definition":"the outer covering of a tree trunk or branch","examples":[{"en":"The tree has thick, rough bark.","zh":"这棵树的树皮厚而粗糙。"},{"en":"Insects hid beneath the loose bark.","zh":"昆虫躲在松动的树皮下面。"}]}],"baron":[{"pos":"n.","meaning":"男爵","definition":"a member of a low rank of nobility","examples":[{"en":"The baron owned several estates.","zh":"这位男爵拥有几处庄园。"},{"en":"The portrait shows a baron in ceremonial dress.","zh":"肖像画描绘了一位穿礼服的男爵。"}]},{"pos":"n.","meaning":"大亨；巨头","definition":"a powerful person in a particular industry","examples":[{"en":"The newspaper was owned by a media baron.","zh":"这家报纸由一位传媒大亨拥有。"},{"en":"A shipping baron financed the new museum.","zh":"一位航运巨头出资建设了新博物馆。"}]}],"barrage":[{"pos":"n.","meaning":"密集炮火；大量接连不断的攻击或提问","definition":"a concentrated attack or a rapid series of things","examples":[{"en":"The troops advanced behind an artillery barrage.","zh":"部队在密集炮火掩护下推进。"},{"en":"The speaker faced a barrage of questions.","zh":"演讲者遭遇了一连串问题。"}]}],"barrel":[{"pos":"n.","meaning":"桶；圆筒","definition":"a large round container with curved sides","examples":[{"en":"Rainwater collects in a barrel beside the house.","zh":"雨水汇集在房子旁的一个桶里。"},{"en":"The wine was stored in an oak barrel.","zh":"葡萄酒储存在橡木桶中。"}]}],"barren":[{"pos":"adj.","meaning":"贫瘠的；荒芜的","definition":"unable to support much plant life","examples":[{"en":"Few crops grow on the barren hillside.","zh":"贫瘠的山坡上很少有作物生长。"},{"en":"The travellers crossed a barren plain.","zh":"旅人们穿过一片荒芜的平原。"}]},{"pos":"adj.","meaning":"不结果实的；不育的","definition":"not producing offspring or fruit","examples":[{"en":"The old tree remained barren that year.","zh":"那棵老树那年仍未结果。"},{"en":"The farmer removed the barren plants.","zh":"农民移除了不结果实的植株。"}]},{"pos":"adj.","meaning":"无成果的；缺乏内容的","definition":"producing no useful results or ideas","examples":[{"en":"Months of barren discussion achieved little.","zh":"数月毫无成果的讨论收效甚微。"},{"en":"The proposal was barren of practical detail.","zh":"提案缺少实际细节。"}]}],"barrier":[{"pos":"n.","meaning":"栅栏；屏障；关卡","definition":"a structure that blocks movement or separates areas","examples":[{"en":"A safety barrier kept visitors away from the cliff.","zh":"安全护栏让游客远离悬崖。"},{"en":"Passengers must show their tickets at the barrier.","zh":"乘客必须在检票闸口出示车票。"}]},{"pos":"n.","meaning":"障碍；隔阂","definition":"something that prevents progress or communication","examples":[{"en":"High fees create a barrier to further education.","zh":"高昂的费用构成了继续接受教育的障碍。"},{"en":"Shared activities helped break down the language barrier.","zh":"共同活动有助于消除语言隔阂。"}]}],"basis":[{"pos":"n.","meaning":"基础；根据；原则","definition":"the main support, reason, or method for something","examples":[{"en":"Trust is the basis of a good partnership.","zh":"信任是良好合作关系的基础。"},{"en":"Candidates are selected on the basis of experience.","zh":"候选人根据经验进行选拔。"}]}],"batch":[{"pos":"n.","meaning":"一批；一组；一批生产量","definition":"a group of items produced or handled together","examples":[{"en":"The bakery made a fresh batch of bread.","zh":"面包店新烤了一批面包。"},{"en":"Each batch of samples is tested separately.","zh":"每批样本都单独检测。"}]}],"battery":[{"pos":"n.","meaning":"电池；蓄电池","definition":"a device that stores and supplies electrical energy","examples":[{"en":"The camera battery needs charging.","zh":"相机电池需要充电。"},{"en":"The bus uses a large battery instead of diesel.","zh":"这辆公共汽车使用大型蓄电池而非柴油。"}]}],"bay":[{"pos":"n.","meaning":"海湾","definition":"an area of sea partly surrounded by land","examples":[{"en":"Fishing boats sheltered in the bay.","zh":"渔船在海湾中避风。"},{"en":"The hotel overlooks a quiet bay.","zh":"酒店俯瞰一个宁静的海湾。"}]}],"bead":[{"pos":"n.","meaning":"珠子","definition":"a small round object with a hole for threading","examples":[{"en":"She threaded a blue bead onto the string.","zh":"她把一颗蓝珠子穿到绳上。"},{"en":"The necklace is made of wooden beads.","zh":"这条项链由木珠制成。"}]},{"pos":"n.","meaning":"小滴；水珠","definition":"a small round drop of liquid","examples":[{"en":"A bead of sweat rolled down his forehead.","zh":"一滴汗珠从他额头滚落。"},{"en":"Beads of water formed on the cold glass.","zh":"冰冷的玻璃上凝结出小水珠。"}]}],"beam":[{"pos":"n.","meaning":"光束；波束","definition":"a narrow stream of light or radiation","examples":[{"en":"A beam of sunlight entered through the roof.","zh":"一束阳光从屋顶照了进来。"},{"en":"The scanner directs a beam towards the surface.","zh":"扫描仪把一束射线对准表面。"}]},{"pos":"n.","meaning":"梁","definition":"a long support in a building","examples":[{"en":"A wooden beam supports the ceiling.","zh":"一根木梁支撑着天花板。"},{"en":"The engineer inspected the damaged steel beam.","zh":"工程师检查了损坏的钢梁。"}]},{"pos":"n.","meaning":"灿烂的笑容","definition":"a broad and happy smile","examples":[{"en":"A beam of delight lit up her face.","zh":"她的脸上绽放出喜悦的笑容。"},{"en":"He greeted the children with a cheerful beam.","zh":"他满面笑容地迎接孩子们。"}]},{"pos":"v.","meaning":"满面笑容","definition":"to smile broadly with happiness","examples":[{"en":"She beamed when her name was announced.","zh":"听到自己的名字被宣布时，她笑容满面。"},{"en":"The proud parents beamed at their daughter.","zh":"自豪的父母对着女儿灿烂地微笑。"}]},{"pos":"v.","meaning":"发射；播送","definition":"to send a signal or light in a particular direction","examples":[{"en":"The satellite beams weather data to the station.","zh":"卫星向地面站传送天气数据。"},{"en":"They beamed the concert to audiences around the world.","zh":"他们向世界各地的观众播送了这场音乐会。"}]}],"beehive":[{"pos":"n.","meaning":"蜂巢；蜂箱","definition":"a structure where bees live and store honey","examples":[{"en":"The beekeeper inspected each beehive.","zh":"养蜂人检查了每一个蜂箱。"},{"en":"A beehive stood at the edge of the orchard.","zh":"果园边放着一个蜂箱。"}]}],"beforehand":[{"pos":"adv.","meaning":"事先；预先","definition":"before a particular action or event","examples":[{"en":"Read the instructions beforehand.","zh":"事先阅读说明。"},{"en":"Please let us know beforehand if you need assistance.","zh":"如果需要帮助，请提前告诉我们。"}]}],"begrimed":[{"pos":"adj.","meaning":"满是污垢的","definition":"covered with dirt or soot","examples":[{"en":"His begrimed coat showed a long day in the workshop.","zh":"他满是污垢的外套表明他在车间忙了一整天。"},{"en":"They cleaned the begrimed windows of the abandoned shop.","zh":"他们擦洗了废弃商店满是污垢的窗户。"}]}],"begrudge":[{"pos":"v.","meaning":"嫉妒；对……心怀不满","definition":"to resent someone having or enjoying something","examples":[{"en":"I do not begrudge her success.","zh":"我并不嫉妒她的成功。"},{"en":"He seemed to begrudge every compliment she received.","zh":"她每得到一句赞扬，他似乎都心怀不满。"}]},{"pos":"v.","meaning":"不情愿地给予；舍不得","definition":"to give or spend something unwillingly","examples":[{"en":"She did not begrudge the time spent helping him.","zh":"她不吝惜帮助他所花的时间。"},{"en":"Some employers begrudge the cost of staff training.","zh":"有些雇主不愿承担员工培训的费用。"}]}],"behalf":[{"pos":"n.","meaning":"代表；为了某人的利益（用于固定搭配）","definition":"used in phrases referring to representation or someone's interests","examples":[{"en":"I thanked the volunteers on behalf of the school.","zh":"我代表学校感谢志愿者。"},{"en":"She spoke on behalf of the residents.","zh":"她代表住户发言。"}]}],"behave":[{"pos":"v.","meaning":"表现；举止得体","definition":"to act in a particular way or act politely","examples":[{"en":"The children behaved well during the visit.","zh":"孩子们参观时表现很好。"},{"en":"People may behave differently when they know they are watched.","zh":"人们知道有人观察时，行为可能有所不同。"}]},{"pos":"v.","meaning":"运转；作出反应","definition":"to operate or respond in a particular way","examples":[{"en":"The engine behaves strangely in very cold weather.","zh":"发动机在严寒天气下运行异常。"},{"en":"Scientists studied how the material behaves under pressure.","zh":"科学家研究了这种材料在压力下的表现。"}]}],"belief":[{"pos":"n.","meaning":"信念；信仰；看法","definition":"an idea accepted as true or an attitude of trust","examples":[{"en":"Her belief in the project never weakened.","zh":"她对这个项目的信心从未减弱。"},{"en":"People should be free to express their religious beliefs.","zh":"人们应有自由表达自己的宗教信仰。"}]}],"belt":[{"pos":"n.","meaning":"腰带；带子","definition":"a strip worn around the waist or used to hold something","examples":[{"en":"He tightened his belt before the walk.","zh":"散步前，他系紧了腰带。"},{"en":"The mechanic replaced the worn drive belt.","zh":"机械师更换了磨损的传动带。"}]},{"pos":"n.","meaning":"地带；区域","definition":"a long area with a shared feature","examples":[{"en":"The town lies in the industrial belt.","zh":"该镇位于工业地带。"},{"en":"A green belt surrounds the city.","zh":"一条绿化带环绕着城市。"}]}],"beneath":[{"pos":"prep.","meaning":"在……下方","definition":"in a lower position than something","examples":[{"en":"A narrow stream runs beneath the bridge.","zh":"一条窄溪从桥下流过。"},{"en":"She found the missing key beneath a pile of papers.","zh":"她在一堆文件下面找到了丢失的钥匙。"}]},{"pos":"adv.","meaning":"在下面","definition":"in a lower place","examples":[{"en":"The upper layer was dry, but the soil beneath was wet.","zh":"表层很干，但下面的土壤是湿的。"},{"en":"A glass floor revealed the ancient foundations beneath.","zh":"玻璃地板显露出下方古老的地基。"}]}],"beneficial":[{"pos":"adj.","meaning":"有益的","definition":"having a helpful effect","examples":[{"en":"Regular exercise is beneficial to mental health.","zh":"经常锻炼有益心理健康。"},{"en":"The changes could be beneficial for small businesses.","zh":"这些变化可能有利于小企业。"},{"en":"Constructive feedback is beneficial to learners.","zh":"建设性反馈对学习者有益。"}]}],"benefit":[{"pos":"v.","meaning":"受益；使受益","definition":"to gain or provide an advantage","examples":[{"en":"Students benefit from regular feedback.","zh":"学生从定期反馈中受益。"},{"en":"The new park will benefit the whole community.","zh":"新公园将使整个社区受益。"}]},{"pos":"n.","meaning":"好处；益处","definition":"an advantage or useful effect","examples":[{"en":"Exercise has many benefits for health.","zh":"运动对健康有许多益处。"},{"en":"One benefit of cycling is lower travel costs.","zh":"骑自行车的一个好处是出行费用更低。"}]},{"pos":"n.","meaning":"福利金；津贴；保险金","definition":"money or support paid by a government, employer, or insurer","examples":[{"en":"The scheme provides benefits for unemployed workers.","zh":"该计划为失业工人提供补助。"},{"en":"Employees receive health benefits as part of the package.","zh":"员工待遇中包括医疗福利。"}]}],"benevolent":[{"pos":"adj.","meaning":"仁慈的；乐善好施的","definition":"kind and willing to help others","examples":[{"en":"A benevolent donor paid for the library repairs.","zh":"一位慷慨的捐赠者出资修缮图书馆。"},{"en":"The story describes a benevolent ruler who protects the poor.","zh":"故事描述了一位保护穷人的仁慈统治者。"}]}],"bent":[{"pos":"adj.","meaning":"弯曲的；被弄弯的","definition":"no longer straight","examples":[{"en":"The bicycle had a bent wheel.","zh":"这辆自行车有一个弯曲的轮子。"},{"en":"He tried to straighten the bent nail.","zh":"他试图把弯钉子弄直。"}]},{"pos":"n.","meaning":"天赋；爱好；倾向","definition":"a natural skill or tendency","examples":[{"en":"She has a bent for languages.","zh":"她有语言天赋。"},{"en":"His artistic bent was evident from childhood.","zh":"他从小就显露出艺术倾向。"}]}],"bereave":[{"pos":"v.","meaning":"使丧失亲人；使失去所爱之人","definition":"to deprive someone of a loved one through death","examples":[{"en":"The support group helps people bereaved of a partner.","zh":"这个互助小组帮助失去伴侣的人。"},{"en":"Families bereaved by the accident gathered for a memorial.","zh":"在事故中失去亲人的家庭聚在一起参加纪念活动。"}]}],"besides":[{"pos":"prep.","meaning":"除……之外还有","definition":"in addition to something","examples":[{"en":"Besides English, she speaks two other languages.","zh":"除了英语，她还会说另外两种语言。"},{"en":"Who besides the manager can approve this request?","zh":"除了经理，还有谁能批准这项请求？"}]},{"pos":"adv.","meaning":"而且；此外","definition":"used to add another reason or fact","examples":[{"en":"The route is shorter; besides, it avoids the busy road.","zh":"这条路线更短，而且避开了繁忙的道路。"},{"en":"I do not need another bag, and besides, it is expensive.","zh":"我不需要另一个包，而且它很贵。"}]}],"bet":[{"pos":"v.","meaning":"打赌；下注","definition":"to risk money on the result of something","examples":[{"en":"He refused to bet on the race.","zh":"他拒绝对这场比赛下注。"},{"en":"I bet you cannot guess the answer.","zh":"我打赌你猜不出答案。"}]},{"pos":"n.","meaning":"赌注；打赌","definition":"money risked or an agreement based on a prediction","examples":[{"en":"She placed a small bet on the match.","zh":"她为这场比赛下了一笔小赌注。"},{"en":"The bet was that he could finish before noon.","zh":"他们打赌他能否在中午前完成。"}]}],"betray":[{"pos":"v.","meaning":"背叛；出卖；辜负","definition":"to be disloyal to someone who trusts you","examples":[{"en":"He promised never to betray his friends.","zh":"他承诺绝不背叛朋友。"},{"en":"Publishing the private letter betrayed her trust.","zh":"公开私人信件辜负了她的信任。"}]},{"pos":"v.","meaning":"泄露；暴露","definition":"to reveal something that was intended to remain hidden","examples":[{"en":"His trembling voice betrayed his fear.","zh":"他颤抖的声音暴露了恐惧。"},{"en":"The map betrayed the location of the hidden entrance.","zh":"地图泄露了隐蔽入口的位置。"}]}],"beverage":[{"pos":"n.","meaning":"饮料","definition":"a drink other than plain water in formal usage","examples":[{"en":"Hot beverages are available near the entrance.","zh":"入口附近供应热饮。"},{"en":"The café offers several sugar-free beverages.","zh":"这家咖啡馆提供多种无糖饮料。"}]}],"beware":[{"pos":"v.","meaning":"当心；提防","definition":"to be careful about a possible danger","examples":[{"en":"Beware of loose stones on the path.","zh":"当心路上的松动石块。"},{"en":"Travellers should beware of unofficial ticket sellers.","zh":"旅客应提防非官方售票者。"}]}],"bewilder":[{"pos":"v.","meaning":"使迷惑；使不知所措","definition":"to confuse someone greatly","examples":[{"en":"The complicated timetable bewildered the visitors.","zh":"复杂的时刻表让游客困惑不已。"},{"en":"The sudden change of plan bewildered everyone.","zh":"计划突然改变，让所有人不知所措。"}]}],"beyond":[{"pos":"prep.","meaning":"在……的更远处","definition":"on the far side of something","examples":[{"en":"There is a small village beyond the hills.","zh":"山的那边有一个小村庄。"},{"en":"The footpath continues beyond the old bridge.","zh":"这条步道越过旧桥继续向前延伸。"}]},{"pos":"prep.","meaning":"超出；非……所能及","definition":"outside the limits of something","examples":[{"en":"The repairs are beyond our current budget.","zh":"修理费用超出了我们目前的预算。"},{"en":"The full effects are beyond what the study can measure.","zh":"全部影响超出了这项研究能够测量的范围。"}]},{"pos":"prep.","meaning":"除……之外","definition":"apart from or in addition to something","examples":[{"en":"She knew little about the city beyond its name.","zh":"除了名字，她对这座城市几乎一无所知。"},{"en":"The offer includes nothing beyond basic accommodation.","zh":"除基本住宿外，这项优惠不包括其他服务。"}]}],"bias":[{"pos":"n.","meaning":"偏见；偏向","definition":"a preference or prejudice that affects judgement","examples":[{"en":"Recruitment procedures should reduce bias against older applicants.","zh":"招聘流程应该减少对年长申请人的偏见。"},{"en":"We must consider possible bias in the source.","zh":"我们必须考虑来源可能存在的偏见。"}]},{"pos":"n.","meaning":"系统偏差；偏差；偏倚","definition":"a systematic distortion in measurements or results","examples":[{"en":"The survey design may introduce bias.","zh":"调查设计可能引入偏差。"},{"en":"Calibration reduced the instrument's measurement bias.","zh":"校准减少了仪器的测量偏差。"}]}],"biased":[{"pos":"adj.","meaning":"有偏见的；片面的","definition":"unfairly favouring one side or opinion","examples":[{"en":"The article gives a biased account of the dispute.","zh":"文章对争议作了片面的描述。"},{"en":"A biased sample can distort the results.","zh":"有偏差的样本会使结果失真。"}]}],"bibliography":[{"pos":"n.","meaning":"参考书目；书目","definition":"a list of books and other sources on a subject","examples":[{"en":"Include a bibliography at the end of your essay.","zh":"请在文章末尾附上参考书目。"},{"en":"The librarian compiled a bibliography of local history.","zh":"图书管理员编制了一份地方史书目。"}]},{"pos":"n.","meaning":"文献学；书目学","definition":"the study and description of books as publications","examples":[{"en":"Her research combines bibliography with literary history.","zh":"她的研究结合了文献学与文学史。"},{"en":"The course introduces methods used in analytical bibliography.","zh":"这门课程介绍分析书目学使用的方法。"}]}],"bid":[{"pos":"n.","meaning":"出价；投标","definition":"an offer of a price or proposal to do work","examples":[{"en":"The auctioneer accepted her bid.","zh":"拍卖师接受了她的出价。"},{"en":"The company submitted a bid for the contract.","zh":"这家公司提交了合同投标书。"}]},{"pos":"v.","meaning":"出价；投标","definition":"to offer a price or compete for a contract","examples":[{"en":"Three firms will bid for the construction project.","zh":"三家公司将竞标这个建筑项目。"},{"en":"She decided not to bid any higher.","zh":"她决定不再加价。"}]}],"bilateral":[{"pos":"adj.","meaning":"双方的；双边的","definition":"involving two sides, groups, or countries","examples":[{"en":"The two countries signed a bilateral agreement.","zh":"两国签署了双边协议。"},{"en":"Bilateral talks resumed after the meeting.","zh":"会议后双边谈判恢复了。"}]}],"bilingual":[{"pos":"adj.","meaning":"双语的；会说两种语言的","definition":"using or able to use two languages","examples":[{"en":"The museum provides bilingual signs throughout the building.","zh":"博物馆各处都设有双语标识。"},{"en":"Growing up in two countries made him bilingual.","zh":"在两个国家成长使他能说两种语言。"}]}],"bin":[{"pos":"n.","meaning":"箱；桶；储物仓","definition":"a container used for storing or discarding things","examples":[{"en":"Put the empty bottles in the recycling bin.","zh":"把空瓶放进回收箱。"},{"en":"The grain was transferred to a storage bin.","zh":"谷物被转移到储存仓中。"}]}],"bind":[{"pos":"v.","meaning":"捆绑；系；装订","definition":"to tie, fasten, or hold things together","examples":[{"en":"Use string to bind the branches together.","zh":"用绳子把树枝绑在一起。"},{"en":"The printer binds the pages into a booklet.","zh":"印刷商把书页装订成小册子。"}]},{"pos":"v.","meaning":"约束；使负有义务","definition":"to impose a duty or legal obligation","examples":[{"en":"The contract binds both parties to the agreement.","zh":"合同约束双方遵守协议。"},{"en":"We are bound by the same professional rules.","zh":"我们受到相同职业规则的约束。"}]},{"pos":"v.","meaning":"使结合；凝结","definition":"to cause materials or ingredients to stick together","examples":[{"en":"Egg helps bind the ingredients.","zh":"鸡蛋有助于使配料黏合。"},{"en":"The mixture will bind as it cools.","zh":"混合物冷却时会凝结。"}]}],"binoculars":[{"pos":"n.","meaning":"双筒望远镜","definition":"a device with two lenses for viewing distant objects","examples":[{"en":"We used binoculars to watch birds across the lake.","zh":"我们用双筒望远镜观察湖对面的鸟。"},{"en":"She packed a pair of binoculars for the hiking trip.","zh":"她为徒步旅行装了一副双筒望远镜。"}]}],"biodiversity":[{"pos":"n.","meaning":"生物多样性","definition":"the variety of living things in an area","examples":[{"en":"The destruction of forests threatens biodiversity.","zh":"森林破坏威胁生物多样性。"},{"en":"Urban gardens can support local biodiversity.","zh":"城市花园能支持当地生物多样性。"},{"en":"Protecting biodiversity helps maintain healthy ecosystems.","zh":"保护生物多样性有助于维持健康的生态系统。"}]}],"biography":[{"pos":"n.","meaning":"传记","definition":"the written story of someone's life","examples":[{"en":"She is reading a biography of a famous scientist.","zh":"她正在读一位著名科学家的传记。"},{"en":"The biography draws on letters and interviews.","zh":"这本传记以书信和访谈为素材。"}]}],"biological":[{"pos":"adj.","meaning":"生物的；生物学的","definition":"relating to living things or their study","examples":[{"en":"The river supports a rich biological community.","zh":"这条河养育着丰富的生物群落。"},{"en":"The samples were sent for biological analysis.","zh":"样本被送去进行生物学分析。"}]}],"biometrics":[{"pos":"n.","meaning":"生物识别技术；生物特征测量","definition":"the measurement of physical or behavioural characteristics, especially for identification","examples":[{"en":"The security system uses biometrics to verify identity.","zh":"这套安全系统使用生物识别技术验证身份。"},{"en":"The course introduces biometrics through fingerprint and facial measurements.","zh":"这门课程通过指纹和面部测量介绍生物特征测量。"}]}],"bistro":[{"pos":"n.","meaning":"小餐馆；小酒馆","definition":"a small informal restaurant","examples":[{"en":"We had lunch at a bistro near the station.","zh":"我们在车站附近的一家小餐馆吃午饭。"},{"en":"The family-run bistro serves simple seasonal dishes.","zh":"这家家庭经营的小餐馆供应简单的时令菜肴。"}]}],"bit":[{"pos":"n.","meaning":"少量；小片；小块","definition":"a small amount or piece","examples":[{"en":"Could you move the chair a bit closer?","zh":"你能把椅子挪近一点吗？"},{"en":"A small bit of glass remained on the floor.","zh":"地板上还留着一小片玻璃。"}]}],"bizarre":[{"pos":"adj.","meaning":"古怪的；奇异的","definition":"very strange or unusual","examples":[{"en":"The film has a bizarre ending.","zh":"这部电影的结局很离奇。"},{"en":"She described a bizarre encounter on the train.","zh":"她描述了在火车上的一次奇怪遭遇。"}]}],"blade":[{"pos":"n.","meaning":"刀刃；刀片","definition":"the flat cutting part of a tool","examples":[{"en":"The blade needs sharpening.","zh":"刀刃需要磨利。"},{"en":"Replace the blade when it becomes damaged.","zh":"刀片损坏时应更换。"}]},{"pos":"n.","meaning":"叶片；桨叶","definition":"a flat rotating part of a machine","examples":[{"en":"One fan blade was bent.","zh":"一片风扇叶片弯了。"},{"en":"The turbine blades turn in the wind.","zh":"涡轮叶片在风中转动。"}]},{"pos":"n.","meaning":"草叶；叶片","definition":"a long narrow leaf of grass or a similar plant","examples":[{"en":"A drop of dew hung from a blade of grass.","zh":"一滴露珠挂在一片草叶上。"},{"en":"The sunlight caught the green blades of grass.","zh":"阳光照在绿色草叶上。"}]}],"blame":[{"pos":"v.","meaning":"责怪；归咎于","definition":"to hold someone responsible for something bad","examples":[{"en":"Do not blame the driver before checking the evidence.","zh":"查看证据前不要责怪司机。"},{"en":"They blamed the delay on a signal failure.","zh":"他们把延误归咎于信号故障。"}]}],"blank":[{"pos":"adj.","meaning":"空白的；未填写的","definition":"without writing, pictures, or information","examples":[{"en":"Please sign on the blank line.","zh":"请在空白横线上签名。"},{"en":"He stared at the blank screen.","zh":"他盯着空白屏幕。"}]}],"blanket":[{"pos":"n.","meaning":"毯子","definition":"a thick covering used to keep someone warm","examples":[{"en":"She wrapped the child in a blanket.","zh":"她用毯子裹住孩子。"},{"en":"An extra blanket lay at the end of the bed.","zh":"床尾放着一条备用毯子。"}]},{"pos":"n.","meaning":"覆盖层；大片覆盖物","definition":"a thick layer covering an area","examples":[{"en":"A blanket of snow covered the fields.","zh":"厚厚的积雪覆盖了田野。"},{"en":"The city disappeared beneath a blanket of fog.","zh":"城市消失在浓雾之中。"}]}],"blast":[{"pos":"v.","meaning":"爆破；炸毁","definition":"to break or destroy something with an explosion","examples":[{"en":"Engineers blasted a tunnel through the rock.","zh":"工程师在岩石中炸出了一条隧道。"},{"en":"The old chimney was blasted into small pieces.","zh":"旧烟囱被炸成了碎块。"}]},{"pos":"n.","meaning":"爆炸；冲击波","definition":"an explosion or its sudden force","examples":[{"en":"The blast shattered windows in nearby buildings.","zh":"爆炸震碎了附近建筑的窗户。"},{"en":"Workers heard a distant blast from the quarry.","zh":"工人听见远处采石场传来爆炸声。"}]},{"pos":"n.","meaning":"一阵强风或强烈气流","definition":"a sudden strong movement of air","examples":[{"en":"A blast of cold air entered when the door opened.","zh":"门一开，一阵冷风吹了进来。"},{"en":"The heater sent a blast of warm air across the room.","zh":"暖气机向房间里吹出一股热风。"}]}],"blaze":[{"pos":"v.","meaning":"熊熊燃烧；发出强光","definition":"to burn or shine very strongly","examples":[{"en":"The fire continued to blaze through the night.","zh":"大火整夜熊熊燃烧。"},{"en":"The midday sun blazed overhead.","zh":"正午的太阳在头顶强烈照耀。"}]},{"pos":"v.","meaning":"突然表现强烈情绪；迸发","definition":"to show a strong feeling suddenly","examples":[{"en":"Her eyes blazed with anger.","zh":"她的眼中迸发出怒火。"},{"en":"The argument blazed up again after dinner.","zh":"晚饭后争论再次激烈起来。"}]},{"pos":"n.","meaning":"大火；强烈火光","definition":"a large strong fire or bright light","examples":[{"en":"Firefighters brought the blaze under control.","zh":"消防员控制住了大火。"},{"en":"The windows reflected the blaze of the setting sun.","zh":"窗户映照着落日的强光。"}]}],"bleak":[{"pos":"adj.","meaning":"寒冷的；荒凉的；阴沉的","definition":"cold, exposed, and lacking comfort or shelter","examples":[{"en":"We crossed a bleak stretch of moorland.","zh":"我们穿过一片荒凉的荒原。"},{"en":"It was a bleak winter morning.","zh":"那是一个阴冷的冬日早晨。"}]},{"pos":"adj.","meaning":"暗淡的；无望的","definition":"offering little hope or encouragement","examples":[{"en":"The report paints a bleak picture of job prospects.","zh":"报告描绘了暗淡的就业前景。"},{"en":"Without new funding, the project's future looks bleak.","zh":"没有新资金，项目的未来显得黯淡。"}]}],"blend":[{"pos":"v.","meaning":"混合；融合","definition":"to mix together smoothly","examples":[{"en":"Blend the fruit with milk until smooth.","zh":"把水果和牛奶搅拌至均匀顺滑。"},{"en":"The extension blends well with the older building.","zh":"扩建部分与旧建筑融合得很好。"}]},{"pos":"n.","meaning":"混合物；交融","definition":"a mixture of different things","examples":[{"en":"The fabric is a blend of wool and cotton.","zh":"这种织物是羊毛与棉的混纺。"},{"en":"The festival offers a blend of music and storytelling.","zh":"这个节日将音乐与讲故事结合在一起。"}]}],"block":[{"pos":"n.","meaning":"街区；一排建筑","definition":"an area of buildings bounded by streets or a group of buildings","examples":[{"en":"The library is two blocks from here.","zh":"图书馆离这里有两个街区。"},{"en":"They live in a new apartment block.","zh":"他们住在一幢新公寓楼里。"}]},{"pos":"n.","meaning":"大块材料","definition":"a solid piece of material","examples":[{"en":"The sculptor worked on a block of marble.","zh":"雕刻家在一大块大理石上进行创作。"},{"en":"Place a wooden block under the wheel.","zh":"在车轮下放一块木头。"}]},{"pos":"n.","meaning":"阻塞；障碍","definition":"something that prevents movement or progress","examples":[{"en":"A block in the pipe stopped the water flow.","zh":"管道中的堵塞物阻断了水流。"},{"en":"Fear can become a block to learning.","zh":"恐惧可能成为学习的障碍。"}]},{"pos":"v.","meaning":"阻塞；阻挡；封锁","definition":"to stop movement, access, or progress","examples":[{"en":"Do not block the emergency exit.","zh":"不要堵塞紧急出口。"},{"en":"The wall blocks our view of the sea.","zh":"这堵墙挡住了我们的海景。"}]}],"blonde":[{"pos":"adj.","meaning":"金发的；浅黄色的","definition":"having pale yellow or golden hair","examples":[{"en":"She has long blonde hair.","zh":"她有一头金色长发。"},{"en":"A blonde actor played the leading role.","zh":"一位金发演员饰演主角。"}]},{"pos":"n.","meaning":"金发女子","definition":"a woman or girl with blonde hair","examples":[{"en":"The blonde in the photograph is my aunt.","zh":"照片中的金发女子是我姑妈。"},{"en":"A tall blonde answered the door.","zh":"一位高个金发女子开了门。"}]}],"bloom":[{"pos":"n.","meaning":"花；开花状态","definition":"a flower or the condition of flowering","examples":[{"en":"The rose produced its first bloom in May.","zh":"这株玫瑰五月开出了第一朵花。"},{"en":"The orchard is in bloom every spring.","zh":"果园每年春天都花开满园。"}]},{"pos":"n.","meaning":"青春焕发的状态","definition":"a healthy and fresh appearance","examples":[{"en":"The fresh air brought a bloom to her cheeks.","zh":"新鲜空气使她双颊泛起健康的红晕。"},{"en":"The portrait captures the bloom of youth.","zh":"这幅肖像捕捉到了青春焕发的神采。"}]},{"pos":"v.","meaning":"开花；繁荣发展","definition":"to produce flowers or develop successfully","examples":[{"en":"The cherry trees bloom early in a warm spring.","zh":"春天天暖时，樱桃树会提早开花。"},{"en":"Her confidence bloomed after the successful presentation.","zh":"演示成功后，她的信心大增。"}]}],"blueprint":[{"pos":"n.","meaning":"蓝图；详细方案","definition":"a detailed plan or technical drawing","examples":[{"en":"The engineer checked the blueprint before work began.","zh":"工程师在开工前检查了蓝图。"},{"en":"The report provides a blueprint for future development.","zh":"这份报告提供了未来发展的详细方案。"}]}],"blunt":[{"pos":"adj.","meaning":"钝的；不锋利的","definition":"having an edge or point that is not sharp","examples":[{"en":"A blunt knife makes cutting difficult.","zh":"钝刀会使切东西变得困难。"},{"en":"The scissors are too blunt to cut the fabric.","zh":"剪刀太钝，剪不动布料。"}]},{"pos":"adj.","meaning":"直言不讳的；生硬的","definition":"speaking directly without trying to be polite","examples":[{"en":"Her blunt reply surprised the interviewer.","zh":"她直言不讳的回答让采访者惊讶。"},{"en":"To be blunt, the proposal is not ready.","zh":"直说吧，这份提案还没准备好。"}]},{"pos":"v.","meaning":"使变钝；削弱","definition":"to make an edge less sharp or an effect less strong","examples":[{"en":"Cutting on stone will blunt the blade.","zh":"在石头上切割会使刀刃变钝。"},{"en":"Repeated warnings can blunt people's response.","zh":"反复警告可能削弱人们的反应。"}]}],"board":[{"pos":"n.","meaning":"木板；板","definition":"a flat piece of solid material","examples":[{"en":"They placed a board across the muddy path.","zh":"他们在泥泞的小路上铺了一块木板。"},{"en":"Write your name on the board near the entrance.","zh":"请把名字写在入口附近的板上。"}]},{"pos":"n.","meaning":"委员会；董事会","definition":"a group responsible for managing an organization","examples":[{"en":"The board approved the new budget.","zh":"董事会批准了新预算。"},{"en":"She joined the hospital board last year.","zh":"她去年加入了医院管理委员会。"}]}],"boast":[{"pos":"v.","meaning":"自夸；夸耀","definition":"to speak with excessive pride","examples":[{"en":"He likes to boast about his achievements.","zh":"他喜欢吹嘘自己的成就。"},{"en":"She never boasts, despite her many awards.","zh":"尽管获奖很多，她从不自夸。"}]},{"pos":"v.","meaning":"拥有值得自豪的事物","definition":"to have something impressive","examples":[{"en":"The town boasts a fine public library.","zh":"这个城镇拥有一座出色的公共图书馆。"},{"en":"The hotel boasts views across the whole valley.","zh":"酒店拥有可以俯瞰整个山谷的美景。"}]},{"pos":"n.","meaning":"夸口；自夸的话","definition":"a proud or exaggerated statement","examples":[{"en":"His boast proved to be empty.","zh":"事实证明他的夸口只是空话。"},{"en":"Winning the race gave some substance to her earlier boast.","zh":"赢得比赛让她先前的豪言有了些依据。"}]}],"bold":[{"pos":"adj.","meaning":"大胆的；勇敢的；冒险的","definition":"willing to take risks or act confidently","examples":[{"en":"They made a bold decision to change direction.","zh":"他们大胆决定改变方向。"},{"en":"The child was bold enough to ask a difficult question.","zh":"孩子勇敢地提出了一个难题。"}]},{"pos":"adj.","meaning":"醒目的；鲜明的","definition":"strong and noticeable in appearance","examples":[{"en":"The poster uses bold colours.","zh":"海报使用鲜明的色彩。"},{"en":"A bold pattern covers the wall.","zh":"墙上布满醒目的图案。"}]},{"pos":"adj.","meaning":"粗体的","definition":"printed with thick dark lines","examples":[{"en":"Write the headings in bold type.","zh":"用粗体书写标题。"},{"en":"The key terms appear in bold letters.","zh":"关键词以粗体显示。"}]}],"bolster":[{"pos":"v.","meaning":"支持；加强；改善","definition":"to support something and make it stronger","examples":[{"en":"The grant will bolster research in renewable energy.","zh":"这笔资助将加强可再生能源研究。"},{"en":"Positive feedback helped bolster her confidence.","zh":"积极反馈帮助她增强了信心。"}]},{"pos":"n.","meaning":"长枕；垫枕","definition":"a long firm pillow used for support","examples":[{"en":"She placed a bolster behind her back.","zh":"她在背后放了一个长垫枕。"},{"en":"The sofa came with two cylindrical bolsters.","zh":"这张沙发配有两个圆柱形长枕。"}]}],"bonus":[{"pos":"n.","meaning":"奖金；额外报酬","definition":"extra money paid in addition to normal earnings","examples":[{"en":"Staff received a small bonus at the end of the year.","zh":"员工在年底收到了一笔小额奖金。"},{"en":"The contract includes a performance bonus.","zh":"合同包含一项绩效奖金。"}]},{"pos":"n.","meaning":"额外好处；意外收获","definition":"an additional benefit","examples":[{"en":"The sea view was an unexpected bonus.","zh":"海景是一个意外的额外好处。"},{"en":"Being close to the station is a real bonus.","zh":"靠近车站确实是一大便利。"}]}],"booking":[{"pos":"n.","meaning":"预订；预约","definition":"an arrangement to reserve a service or place","examples":[{"en":"I received an email confirming my hotel booking.","zh":"我收到一封确认酒店预订的邮件。"},{"en":"You can change the booking up to two days before departure.","zh":"你可以在出发前两天之前修改预订。"}]}],"booklet":[{"pos":"n.","meaning":"小册子","definition":"a small thin book containing information","examples":[{"en":"The museum gave us an information booklet.","zh":"博物馆给了我们一本资料小册子。"},{"en":"The booklet explains how to use the equipment.","zh":"小册子解释了如何使用设备。"}]}],"bookrest":[{"pos":"n.","meaning":"阅书架；书本支架","definition":"a support that holds a book open for reading","examples":[{"en":"The bookrest keeps the recipe visible while I cook.","zh":"我做饭时，书本支架让食谱保持清楚可见。"},{"en":"She adjusted the bookrest to a comfortable angle.","zh":"她把阅书架调到了舒适的角度。"}]}],"booming":[{"pos":"adj.","meaning":"迅速发展的；繁荣的","definition":"growing rapidly and successfully","examples":[{"en":"The city has a booming technology sector.","zh":"这座城市的科技行业发展迅速。"},{"en":"A booming economy attracted workers from other regions.","zh":"繁荣的经济吸引了其他地区的工人。"}]}],"boost":[{"pos":"v.","meaning":"促进；提高；使增加","definition":"to increase or improve something","examples":[{"en":"The new service may boost sales.","zh":"新服务可能促进销售。"},{"en":"A short break can boost concentration.","zh":"短暂休息可以提高注意力。"}]},{"pos":"v.","meaning":"宣传；推介","definition":"to promote something enthusiastically","examples":[{"en":"Local businesses helped boost the festival.","zh":"当地企业帮助宣传这个节日。"},{"en":"The campaign boosts the town as a tourist destination.","zh":"这场宣传活动把该镇作为旅游目的地进行推介。"}]},{"pos":"n.","meaning":"增加；推动；激励","definition":"an increase or helpful encouragement","examples":[{"en":"The award gave her confidence a boost.","zh":"获奖增强了她的信心。"},{"en":"The investment provides a welcome boost to the economy.","zh":"这笔投资为经济提供了可喜的推动。"}]}],"boot":[{"pos":"n.","meaning":"靴子","definition":"a shoe that covers the foot and part of the leg","examples":[{"en":"Wear a waterproof boot on each foot in the marsh.","zh":"在沼泽地里要穿上防水靴。"},{"en":"He cleaned the mud from his walking boots.","zh":"他清除了徒步靴上的泥。"}]},{"pos":"n.","meaning":"汽车后备箱（英式）","definition":"the enclosed storage space at the back of a car","examples":[{"en":"Put the suitcase in the boot.","zh":"把行李箱放进汽车后备箱。"},{"en":"The boot has enough space for two folding chairs.","zh":"后备箱有足够空间放两把折叠椅。"}]},{"pos":"n.","meaning":"解雇（give/get the boot）","definition":"dismissal from a job or position","examples":[{"en":"He got the boot after repeatedly missing work.","zh":"他多次旷工后被解雇了。"},{"en":"The manager gave the unreliable contractor the boot.","zh":"经理解雇了那个不可靠的承包商。"}]}],"booth":[{"pos":"n.","meaning":"小隔间；电话亭；售货亭","definition":"a small enclosed or partly enclosed space for a particular activity","examples":[{"en":"She stepped into a booth to make the call.","zh":"她走进电话亭打电话。"},{"en":"Tickets are sold at the booth near the entrance.","zh":"门票在入口附近的售票亭出售。"}]}],"border":[{"pos":"n.","meaning":"边缘；边饰","definition":"an edge or decorative strip around something","examples":[{"en":"A narrow border surrounds the photograph.","zh":"照片周围有一道窄边框。"},{"en":"She planted flowers along the garden border.","zh":"她沿花园边缘种了花。"}]},{"pos":"n.","meaning":"国界；边界","definition":"the line separating two countries or areas","examples":[{"en":"The river forms the border between the regions.","zh":"这条河构成了两个地区的边界。"},{"en":"We crossed the border before noon.","zh":"我们在中午前越过了边境。"}]},{"pos":"v.","meaning":"与……接壤；毗邻","definition":"to share a boundary with a place","examples":[{"en":"The village borders a large forest.","zh":"村庄毗邻一大片森林。"},{"en":"Several farms border the river.","zh":"几座农场紧邻这条河。"}]},{"pos":"v.","meaning":"接近；近乎","definition":"to be almost a particular quality or condition, usually with on","examples":[{"en":"His confidence borders on arrogance.","zh":"他的自信近乎傲慢。"},{"en":"The delay bordered on the ridiculous.","zh":"这种延误简直荒唐。"}]}],"bore":[{"pos":"v.","meaning":"使厌烦","definition":"to make someone feel uninterested","examples":[{"en":"The repetitive lecture bored the students.","zh":"重复乏味的讲课让学生们感到厌烦。"},{"en":"I will not bore you with every detail.","zh":"我不会用每个细节来烦你。"}]},{"pos":"v.","meaning":"钻孔","definition":"to make a hole by drilling","examples":[{"en":"Workers bored a hole through the concrete wall.","zh":"工人在混凝土墙上钻了一个孔。"},{"en":"The machine can bore through hard rock.","zh":"这台机器能够钻穿坚硬的岩石。"}]},{"pos":"n.","meaning":"令人厌烦的人或事","definition":"a person or activity that is dull and tedious","examples":[{"en":"Sorting those old receipts was a terrible bore.","zh":"整理那些旧收据真是件无聊的事。"},{"en":"He becomes a bore when he repeats the same story.","zh":"他一遍遍讲同一个故事时就让人厌烦。"}]}],"bother":[{"pos":"v.","meaning":"打扰；使烦恼","definition":"to annoy, worry, or interrupt someone","examples":[{"en":"Does the noise bother you?","zh":"这些噪声让你烦恼吗？"},{"en":"I am sorry to bother you during lunch.","zh":"很抱歉在午餐时打扰你。"}]},{"pos":"v.","meaning":"费心；花工夫","definition":"to make an effort to do something","examples":[{"en":"Do not bother carrying the box; I can manage it.","zh":"不用费心搬箱子，我自己能行。"},{"en":"She always bothers to check the details.","zh":"她总会花心思核对细节。"}]},{"pos":"n.","meaning":"麻烦；烦扰","definition":"trouble or inconvenience","examples":[{"en":"Finding a replacement was a lot of bother.","zh":"寻找替代品费了不少周折。"},{"en":"He fixed the problem without any bother.","zh":"他毫不费劲就解决了问题。"}]}],"boulder":[{"pos":"n.","meaning":"巨石；大圆石","definition":"a very large rock","examples":[{"en":"A boulder blocked the mountain path.","zh":"一块巨石挡住了山路。"},{"en":"Waves crashed against the boulders below.","zh":"海浪拍打着下面的巨石。"}]}],"bounce":[{"pos":"v.","meaning":"弹起；反弹；上下晃动","definition":"to spring back after hitting a surface or move up and down","examples":[{"en":"The ball bounced off the wall.","zh":"球撞到墙后弹了回来。"},{"en":"The bus bounced along the uneven road.","zh":"公共汽车在崎岖的道路上颠簸前行。"}]},{"pos":"n.","meaning":"弹跳；反弹力","definition":"an upward movement after hitting a surface","examples":[{"en":"The ball took an unexpected bounce.","zh":"球出人意料地弹了一下。"},{"en":"This old mattress has lost its bounce.","zh":"这张旧床垫失去了弹性。"}]},{"pos":"n.","meaning":"活力；精神","definition":"energy and enthusiasm","examples":[{"en":"The holiday put the bounce back in her step.","zh":"假期让她的步伐重新充满活力。"},{"en":"The young presenter brought bounce to the programme.","zh":"这位年轻主持人为节目带来了活力。"}]}],"bouncing":[{"pos":"adj.","meaning":"健壮活泼的（尤指婴儿）","definition":"healthy and energetic, especially of a baby","examples":[{"en":"Their bouncing baby girl kept everyone busy.","zh":"他们活泼健壮的女婴让大家忙个不停。"},{"en":"The photograph shows a bouncing toddler with bright eyes.","zh":"照片上是一个眼睛明亮、健壮活泼的幼童。"}]}],"bound":[{"pos":"adj.","meaning":"有义务的；受约束的","definition":"required by duty or agreement","examples":[{"en":"We are bound to respect the agreement.","zh":"我们有义务遵守协议。"},{"en":"She felt bound to help her colleague.","zh":"她觉得自己有责任帮助同事。"}]},{"pos":"adj.","meaning":"必然的；一定会的","definition":"certain or very likely to happen","examples":[{"en":"Mistakes are bound to happen occasionally.","zh":"错误偶尔总会发生。"},{"en":"Your confidence is bound to improve with practice.","zh":"随着练习，你的信心一定会提高。"}]},{"pos":"adj.","meaning":"开往；驶向","definition":"travelling towards a stated destination","examples":[{"en":"We boarded a train bound for London.","zh":"我们登上一列开往伦敦的火车。"},{"en":"The ship was homeward bound.","zh":"船正驶向家乡。"}]}],"boundary":[{"pos":"n.","meaning":"边界；分界线","definition":"a line separating areas or limits","examples":[{"en":"A stone wall marks the boundary between the farms.","zh":"一道石墙标明两座农场的分界线。"},{"en":"The discussion crossed the boundary between science and ethics.","zh":"这场讨论跨越了科学与伦理的界限。"}]}],"bow":[{"pos":"v.","meaning":"鞠躬；低头；弯腰","definition":"to bend the head or upper body as a greeting or sign of respect","examples":[{"en":"The performers bow at the end of the show.","zh":"表演者在演出结束时鞠躬。"},{"en":"He had to bow his head to enter the low doorway.","zh":"他不得不低头进入低矮的门口。"}],"ipa":"/baʊ/"},{"pos":"n.","meaning":"弓","definition":"a curved weapon used to shoot arrows","examples":[{"en":"The archer raised her bow.","zh":"弓箭手举起了弓。"},{"en":"The museum displays an ancient wooden bow.","zh":"博物馆展出一张古代木弓。"}],"ipa":"/bəʊ/"}],"branch":[{"pos":"n.","meaning":"树枝","definition":"a part of a tree growing from its trunk","examples":[{"en":"A bird landed on the lowest branch.","zh":"一只鸟落在最低的树枝上。"},{"en":"The wind broke a large branch.","zh":"风折断了一根大树枝。"}]},{"pos":"n.","meaning":"分支；分部；分科","definition":"a division of an organisation or subject","examples":[{"en":"The bank opened a new branch nearby.","zh":"银行在附近开了一家新分行。"},{"en":"Botany is a branch of biology.","zh":"植物学是生物学的一个分支。"}]}],"brand":[{"pos":"n.","meaning":"品牌；商标","definition":"a name identifying a company's product","examples":[{"en":"This brand is known for reliable outdoor clothing.","zh":"这个品牌以可靠的户外服装著称。"},{"en":"The shop sells several local brands of cheese.","zh":"这家店出售几个本地品牌的奶酪。"}]},{"pos":"v.","meaning":"打烙印；留下标记","definition":"to mark something permanently with a hot tool or symbol","examples":[{"en":"The farmer branded the cattle for identification.","zh":"农场主给牛打上烙印以便识别。"},{"en":"The maker's initials were branded into the wooden handle.","zh":"制作者姓名的首字母被烙在木柄上。"}]},{"pos":"v.","meaning":"给……贴上负面标签","definition":"to publicly describe someone in a strongly negative way","examples":[{"en":"Critics branded the proposal unrealistic.","zh":"批评者将这项提议斥为不切实际。"},{"en":"She was unfairly branded a troublemaker.","zh":"她被不公正地扣上了惹事者的帽子。"}]}],"brass":[{"pos":"n.","meaning":"黄铜；黄铜制品","definition":"a yellow metal made mainly from copper and zinc, or objects made from it","examples":[{"en":"The door has a polished brass handle.","zh":"门上有一个擦亮的黄铜把手。"},{"en":"She cleaned the brass on the old fireplace.","zh":"她清洁了旧壁炉上的黄铜制品。"}]},{"pos":"n.","meaning":"铜管乐器；铜管乐器组","definition":"metal wind instruments or the musicians playing them","examples":[{"en":"The brass enters after the strings.","zh":"弦乐之后铜管乐器加入。"},{"en":"He plays brass in the school band.","zh":"他在学校乐队中演奏铜管乐器。"}]}],"brazen":[{"pos":"adj.","meaning":"厚颜无耻的；肆无忌惮的","definition":"showing no shame about bad behaviour","examples":[{"en":"It was a brazen attempt to cheat the customers.","zh":"那是一次肆无忌惮欺骗顾客的企图。"},{"en":"The official denied the accusation with brazen confidence.","zh":"那名官员厚颜无耻、自信满满地否认指控。"}]},{"pos":"adj.","meaning":"黄铜制的；黄铜色的（文学用法）","definition":"made of brass or resembling its colour","examples":[{"en":"The ancient gate had brazen fittings.","zh":"古门上有黄铜配件。"},{"en":"The sunset gave the clouds a brazen glow.","zh":"夕阳使云层泛出黄铜色的光。"}]}],"breakdown":[{"pos":"n.","meaning":"故障；失败；破裂","definition":"a failure of a machine, system, or relationship","examples":[{"en":"A mechanical breakdown delayed the train.","zh":"机械故障使火车晚点。"},{"en":"The talks ended in a breakdown of trust.","zh":"会谈最终导致信任破裂。"}]},{"pos":"n.","meaning":"精神或身体崩溃","definition":"a serious collapse in someone's health or ability to function","examples":[{"en":"Months of pressure led to a nervous breakdown.","zh":"数月的压力导致精神崩溃。"},{"en":"She took time off after a breakdown in her health.","zh":"健康严重恶化后，她休了一段时间假。"}]},{"pos":"n.","meaning":"分类明细；细分","definition":"a division of a total into separate parts","examples":[{"en":"Please provide a breakdown of the travel costs.","zh":"请提供旅行费用的分类明细。"},{"en":"The chart gives a breakdown of students by age.","zh":"这张图表按年龄细分了学生人数。"}]}],"breakthrough":[{"pos":"n.","meaning":"突破；重大进展","definition":"an important discovery or advance","examples":[{"en":"The experiment led to a breakthrough in the research.","zh":"这项实验带来了研究上的突破。"},{"en":"Negotiators finally achieved a breakthrough.","zh":"谈判者终于取得了重大进展。"}]}],"breakwater":[{"pos":"n.","meaning":"防波堤","definition":"a structure protecting a harbour or shore from waves","examples":[{"en":"The fishing boats sheltered behind the breakwater.","zh":"渔船在防波堤后避浪。"},{"en":"Waves broke over the outer wall of the breakwater.","zh":"海浪冲上防波堤的外墙。"}]}],"breed":[{"pos":"v.","meaning":"繁殖；饲养；培育","definition":"to produce young animals or raise particular varieties","examples":[{"en":"These birds breed on remote islands.","zh":"这些鸟在偏远岛屿上繁殖。"},{"en":"The farm breeds sheep for their fine wool.","zh":"这个农场培育绵羊以获取细羊毛。"}]},{"pos":"v.","meaning":"滋生；酿成","definition":"to cause a feeling or problem to develop","examples":[{"en":"Long delays can breed resentment.","zh":"长时间延误可能滋生怨恨。"},{"en":"A lack of clear information breeds confusion.","zh":"缺乏清楚的信息会造成混乱。"}]},{"pos":"n.","meaning":"品种；类型","definition":"a particular variety of an animal or group","examples":[{"en":"This breed of dog needs plenty of exercise.","zh":"这个品种的狗需要大量运动。"},{"en":"The exhibition features several rare cattle breeds.","zh":"展览展示了几个稀有的牛品种。"}]}],"breeze":[{"pos":"n.","meaning":"微风；和风","definition":"a light wind","examples":[{"en":"A cool breeze came through the open window.","zh":"一阵凉风从敞开的窗户吹进来。"},{"en":"The flags moved gently in the breeze.","zh":"旗帜在微风中轻轻飘动。"}]}],"brew":[{"pos":"v.","meaning":"酿造","definition":"to make beer or another drink by a controlled process","examples":[{"en":"The company brews beer using local ingredients.","zh":"这家公司用当地原料酿啤酒。"},{"en":"He learned to brew cider at the farm.","zh":"他在农场学会了酿苹果酒。"}]},{"pos":"v.","meaning":"冲泡；沏","definition":"to make tea or coffee by adding hot water","examples":[{"en":"She brewed a pot of tea for the guests.","zh":"她为客人泡了一壶茶。"},{"en":"Let the coffee brew for a few minutes.","zh":"让咖啡冲泡几分钟。"}]},{"pos":"v.","meaning":"酝酿；逐渐形成","definition":"to begin developing, especially something troublesome","examples":[{"en":"A storm was brewing over the hills.","zh":"山丘上空正酝酿着一场暴风雨。"},{"en":"Trouble had been brewing for weeks.","zh":"问题已经酝酿了数周。"}]}],"brief":[{"pos":"adj.","meaning":"简短的；短暂的","definition":"lasting for a short time or using few words","examples":[{"en":"We took a brief break before the next session.","zh":"我们在下一场开始前短暂休息。"},{"en":"The guide gave a brief explanation of the building.","zh":"导游简要介绍了这栋建筑。"}]},{"pos":"n.","meaning":"任务说明；概要","definition":"a concise description of a task or case","examples":[{"en":"The designer received a detailed project brief.","zh":"设计师收到了一份详细的项目任务说明。"},{"en":"The legal team prepared a brief for the hearing.","zh":"法律团队为听证准备了一份案情摘要。"}]},{"pos":"v.","meaning":"介绍情况；提供必要资讯","definition":"to give someone essential information","examples":[{"en":"The leader briefed the volunteers before they left.","zh":"负责人在志愿者出发前向他们介绍了情况。"},{"en":"Please brief the new colleague on the safety procedure.","zh":"请向新同事介绍安全流程。"}]}],"briefcase":[{"pos":"n.","meaning":"公文包","definition":"a flat case for carrying documents","examples":[{"en":"He left his briefcase under the desk.","zh":"他把公文包留在了桌子下面。"},{"en":"She put the signed papers in her briefcase.","zh":"她把签好的文件放进了公文包。"}]}],"briefly":[{"pos":"adv.","meaning":"短暂地；暂时地","definition":"for a short time","examples":[{"en":"We spoke briefly after the meeting.","zh":"会后我们短暂交谈了。"},{"en":"The sun appeared briefly between the clouds.","zh":"太阳从云层之间短暂露面。"}]},{"pos":"adv.","meaning":"简要地；简短地","definition":"using few words","examples":[{"en":"Please explain your proposal briefly.","zh":"请简要解释你的提案。"},{"en":"The report briefly outlines the main problems.","zh":"报告简要概述了主要问题。"}]}],"brilliant":[{"pos":"adj.","meaning":"灿烂的；明亮的","definition":"shining with strong light or colour","examples":[{"en":"Brilliant sunlight flooded the courtyard.","zh":"灿烂的阳光洒满庭院。"},{"en":"The bird had brilliant blue feathers.","zh":"这只鸟有鲜亮的蓝色羽毛。"}]},{"pos":"adj.","meaning":"杰出的；有才华的","definition":"extremely clever or impressive","examples":[{"en":"She proposed a brilliant solution to the problem.","zh":"她提出了一个解决问题的绝妙办法。"},{"en":"The brilliant young pianist won a scholarship.","zh":"这位才华横溢的年轻钢琴家获得了奖学金。"}]}],"bring around/round":[{"pos":"phr.v.","meaning":"说服；使改变看法","definition":"to persuade someone to agree","examples":[{"en":"We hope to bring her round to our point of view.","zh":"我们希望说服她接受我们的观点。"},{"en":"More evidence may bring the committee around.","zh":"更多证据可能使委员会改变看法。"}]},{"pos":"phr.v.","meaning":"使恢复知觉；使苏醒","definition":"to help someone regain consciousness","examples":[{"en":"The medical team worked to bring the patient round.","zh":"医护团队努力使患者恢复知觉。"},{"en":"It took several minutes to bring him around after the procedure.","zh":"治疗结束后过了几分钟，他才恢复知觉。"}]}],"bring out":[{"pos":"phr.v.","meaning":"出版；推出","definition":"to publish or release something","examples":[{"en":"The publisher will bring out a new edition next year.","zh":"出版社明年将推出新版。"},{"en":"They brought out a smaller version of the device.","zh":"他们推出了这款设备的缩小版。"}]},{"pos":"phr.v.","meaning":"使显现；激发；衬托出","definition":"to make a quality noticeable or encourage it to appear","examples":[{"en":"The course helps bring out students' creativity.","zh":"这门课程有助于激发学生的创造力。"},{"en":"The blue scarf brings out the colour of her eyes.","zh":"蓝色围巾衬托出她眼睛的颜色。"}]}],"brittle":[{"pos":"adj.","meaning":"易碎的；脆弱的","definition":"hard but easily broken or damaged","examples":[{"en":"The old paper was yellow and brittle.","zh":"旧纸张已经发黄发脆。"},{"en":"Cold weather made the plastic brittle.","zh":"寒冷天气使塑料变脆了。"}]},{"pos":"adj.","meaning":"情绪脆弱的；生硬紧张的","definition":"appearing controlled but nervous or easily upset","examples":[{"en":"Her brittle confidence disappeared after the criticism.","zh":"受到批评后，她脆弱的自信消失了。"},{"en":"His brittle smile did little to hide his anxiety.","zh":"他生硬的微笑几乎掩盖不了焦虑。"}]},{"pos":"adj.","meaning":"尖利而紧张的（声音）","definition":"sharp and tense in sound","examples":[{"en":"A brittle laugh broke the uncomfortable silence.","zh":"一声尖利而紧张的笑打破了尴尬的沉默。"},{"en":"Her voice became brittle as the interview continued.","zh":"随着访谈继续，她的声音变得尖利紧张。"}]}],"brochure":[{"pos":"n.","meaning":"宣传册；小册子","definition":"a small booklet giving information about a product, place, or service","examples":[{"en":"The hotel sent us a brochure.","zh":"酒店给我们寄来了一本宣传册。"},{"en":"Read the brochure before choosing a course.","zh":"选择课程之前先阅读这本小册子。"}]}],"bronchitis":[{"pos":"n.","meaning":"支气管炎","definition":"inflammation of the bronchial tubes","examples":[{"en":"The doctor diagnosed bronchitis.","zh":"医生诊断为支气管炎。"},{"en":"He missed several days of work because of bronchitis.","zh":"他因支气管炎缺勤了几天。"}]}],"brood":[{"pos":"v.","meaning":"闷闷不乐地反复想","definition":"to dwell unhappily on something","examples":[{"en":"He brooded over the mistake all evening.","zh":"他整个晚上都为那个错误耿耿于怀。"},{"en":"Try not to brood on comments that cannot be changed.","zh":"尽量不要一直为那些无法改变的评论烦恼。"}]},{"pos":"v.","meaning":"孵蛋；护雏","definition":"to keep eggs or young birds warm","examples":[{"en":"The hen brooded quietly in the nesting box.","zh":"母鸡在巢箱里安静地孵蛋。"},{"en":"The parent birds take turns brooding the chicks.","zh":"亲鸟轮流给雏鸟保温。"}]},{"pos":"n.","meaning":"一窝幼鸟或幼崽","definition":"young animals born or hatched together","examples":[{"en":"A brood of ducklings followed the mother across the pond.","zh":"一窝小鸭跟着母鸭游过池塘。"},{"en":"The researchers counted the chicks in each brood.","zh":"研究人员清点了每窝雏鸟的数量。"}]}],"broom":[{"pos":"n.","meaning":"扫帚","definition":"a long-handled tool used for sweeping","examples":[{"en":"She used a broom to clear the fallen leaves.","zh":"她用扫帚清理落叶。"},{"en":"A broom stood beside the kitchen door.","zh":"厨房门旁放着一把扫帚。"}]}],"browse":[{"pos":"v.","meaning":"浏览；随意翻阅","definition":"to look through things casually","examples":[{"en":"You can browse the catalogue online.","zh":"你可以在线浏览目录。"},{"en":"She browsed the shelves for a new novel.","zh":"她随意翻看书架，寻找一本新小说。"}]},{"pos":"v.","meaning":"吃嫩枝叶；放牧觅食","definition":"to feed on leaves and young shoots","examples":[{"en":"Deer browse on the young leaves.","zh":"鹿以嫩叶为食。"},{"en":"Goats browsed among the shrubs.","zh":"山羊在灌木间啃食枝叶。"}]},{"pos":"n.","meaning":"浏览；随意翻看","definition":"an act of looking through things casually","examples":[{"en":"I had a quick browse through the guide.","zh":"我快速翻看了指南。"},{"en":"There is time for a browse in the bookshop.","zh":"还有时间到书店随意看看。"}]},{"pos":"n.","meaning":"嫩枝叶；饲用枝叶","definition":"leaves and shoots eaten by certain animals","examples":[{"en":"The deer found fresh browse near the stream.","zh":"鹿在溪边找到了新鲜嫩枝叶。"},{"en":"Farmers provided leafy browse for the goats.","zh":"农民为山羊提供了多叶的枝条饲料。"}]}],"brunt":[{"pos":"n.","meaning":"最主要的冲击；最沉重的负担","definition":"the greatest force or worst part of something","examples":[{"en":"Coastal villages bore the brunt of the storm.","zh":"沿海村庄承受了风暴最猛烈的冲击。"},{"en":"Small businesses took the brunt of the sudden price rise.","zh":"小企业承受了价格骤涨的主要冲击。"}]}],"brutal":[{"pos":"adj.","meaning":"残忍的；野蛮的","definition":"extremely cruel or violent","examples":[{"en":"The report described the prisoners' brutal treatment.","zh":"报告描述了囚犯遭受的残酷对待。"},{"en":"The brutal attack shocked the community.","zh":"这场野蛮袭击震惊了整个社区。"}]},{"pos":"adj.","meaning":"无情的；严酷的","definition":"harsh and without kindness","examples":[{"en":"The team faced brutal criticism after the defeat.","zh":"球队失败后遭到严厉批评。"},{"en":"The winter was brutal and unusually long.","zh":"这个冬天严酷而且异常漫长。"}]}],"bubble":[{"pos":"n.","meaning":"气泡；泡沫","definition":"a small ball of gas within liquid or surrounded by a thin film","examples":[{"en":"A bubble rose to the surface.","zh":"一个气泡升到水面。"},{"en":"The children blew soap bubbles in the garden.","zh":"孩子们在花园里吹肥皂泡。"}]},{"pos":"n.","meaning":"泡沫；不稳固的繁荣或幻想","definition":"an unstable situation based on unrealistic expectations","examples":[{"en":"The housing bubble eventually burst.","zh":"房地产泡沫最终破裂。"},{"en":"The disappointing results burst their bubble of optimism.","zh":"令人失望的结果打破了他们乐观的幻想。"}]},{"pos":"v.","meaning":"冒泡；发出咕嘟声","definition":"to produce bubbles or make their sound","examples":[{"en":"The soup bubbled gently in the pot.","zh":"汤在锅里轻轻冒泡。"},{"en":"Water bubbled up through the sand.","zh":"水从沙中冒着泡涌出。"}]}],"bucket":[{"pos":"n.","meaning":"桶；水桶","definition":"an open container with a handle","examples":[{"en":"She filled a bucket with water from the tap.","zh":"她从水龙头接满了一桶水。"},{"en":"We used two buckets to collect rainwater.","zh":"我们用两个桶收集雨水。"}]}],"buckle":[{"pos":"n.","meaning":"带扣；扣环","definition":"a fastening that joins the ends of a belt or strap","examples":[{"en":"The buckle on my bag is broken.","zh":"我包上的带扣坏了。"},{"en":"She polished the silver buckle on the belt.","zh":"她擦亮了皮带上的银色带扣。"}]},{"pos":"v.","meaning":"扣紧；用扣环扣住","definition":"to fasten with a buckle","examples":[{"en":"Please buckle your seat belt before we leave.","zh":"出发前请系好安全带。"},{"en":"He stopped to buckle the straps on his boots.","zh":"他停下来扣紧靴子上的带子。"}]},{"pos":"v.","meaning":"弯曲；变形；屈曲","definition":"to bend or collapse under pressure","examples":[{"en":"The metal began to buckle in the intense heat.","zh":"金属在高温下开始变形。"},{"en":"Her knees seemed to buckle from exhaustion.","zh":"她累得双膝仿佛要弯倒了。"}]}],"bud":[{"pos":"n.","meaning":"芽；花蕾","definition":"a small growth that develops into a leaf or flower","examples":[{"en":"The rose has several unopened buds.","zh":"玫瑰有几个未开的花蕾。"},{"en":"Green buds appeared on the branches.","zh":"枝头出现了绿色的芽。"}]},{"pos":"v.","meaning":"发芽；萌芽","definition":"to produce buds or begin developing","examples":[{"en":"The trees begin to bud in spring.","zh":"树木在春天开始发芽。"},{"en":"A friendship was budding between the neighbours.","zh":"邻居之间的友谊正在萌芽。"}]}],"budget":[{"pos":"n.","meaning":"预算","definition":"a plan for how much money to spend","examples":[{"en":"We need to stay within our monthly budget.","zh":"我们需要将开支控制在月度预算内。"},{"en":"The council increased the budget for libraries.","zh":"地方议会增加了图书馆预算。"},{"en":"Prepare a detailed budget before starting the project.","zh":"项目开始前请准备详细预算。"}]},{"pos":"v.","meaning":"编制预算；规划支出","definition":"To plan how money or time will be used.","examples":[{"en":"We budgeted carefully for the renovation.","zh":"我们为翻修仔细编制了预算。"},{"en":"She budgets a fixed amount each month for travel.","zh":"她每月为旅行安排固定金额。"}]}],"buffalo":[{"pos":"n.","meaning":"水牛；野牛","definition":"a large wild or domesticated bovine animal","examples":[{"en":"A water buffalo stood in the muddy field.","zh":"一头水牛站在泥泞的田里。"},{"en":"The guide explained why American bison are often called buffalo.","zh":"导游解释了为什么美洲野牛常被称为 buffalo。"}]}],"bulb":[{"pos":"n.","meaning":"灯泡","definition":"a device that produces light using electricity","examples":[{"en":"The bulb in the hallway needs replacing.","zh":"走廊里的灯泡需要更换。"},{"en":"An energy-efficient bulb uses less electricity.","zh":"节能灯泡耗电更少。"}]},{"pos":"n.","meaning":"球茎；鳞茎","definition":"an underground plant part storing food and producing new growth","examples":[{"en":"Plant the bulbs before the first frost.","zh":"在初霜前种下这些球茎。"},{"en":"A tulip bulb lay beside the gardening tools.","zh":"园艺工具旁放着一个郁金香球茎。"}]}],"bulge":[{"pos":"v.","meaning":"鼓起；凸出；装得鼓鼓的","definition":"to swell outward or be very full","examples":[{"en":"The bag bulged with library books.","zh":"包里装满了图书馆的书，鼓鼓囊囊的。"},{"en":"The damaged wall began to bulge outward.","zh":"受损的墙开始向外鼓起。"}]},{"pos":"n.","meaning":"鼓包；凸起；激增","definition":"a rounded swelling or temporary increase","examples":[{"en":"The doctor examined the small bulge under the skin.","zh":"医生检查了皮肤下面的小肿块。"},{"en":"The school prepared for a bulge in enrolment.","zh":"学校为入学人数激增作好了准备。"}]}],"bulk":[{"pos":"n.","meaning":"大部分；大批；体积","definition":"the main part, a large quantity, or large size","examples":[{"en":"The bulk of our work is now complete.","zh":"我们的大部分工作现已完成。"},{"en":"Buying rice in bulk can reduce the cost.","zh":"大批量购买大米可以降低成本。"}]}],"bullet":[{"pos":"n.","meaning":"子弹；枪弹","definition":"a small metal projectile fired from a gun","examples":[{"en":"The museum displays a bullet recovered from the battlefield.","zh":"博物馆展出了一颗从战场找到的子弹。"},{"en":"A bullet had damaged the wooden door.","zh":"一颗子弹打坏了木门。"}]}],"bulletin":[{"pos":"n.","meaning":"新闻简报；公告","definition":"a short official report or announcement","examples":[{"en":"The radio bulletin reported a road closure.","zh":"广播新闻简报报道了一条道路封闭的消息。"},{"en":"A safety bulletin was sent to every department.","zh":"一份安全公告被发送到每个部门。"}]},{"pos":"n.","meaning":"会刊；学报","definition":"a periodical issued by an organization","examples":[{"en":"Her article appeared in the society's quarterly bulletin.","zh":"她的文章发表在该学会的季度会刊上。"},{"en":"The museum bulletin describes recent discoveries.","zh":"博物馆刊物介绍了近期的发现。"}]}],"bully":[{"pos":"n.","meaning":"恃强凌弱者","definition":"someone who repeatedly intimidates weaker people","examples":[{"en":"The school took action against the bully.","zh":"学校对那名欺凌者采取了措施。"},{"en":"She refused to let a bully control her choices.","zh":"她拒绝让一个恃强凌弱者左右自己的选择。"}]},{"pos":"v.","meaning":"欺负；恐吓；胁迫","definition":"to intimidate or mistreat someone repeatedly","examples":[{"en":"No one has the right to bully a colleague.","zh":"没有人有权欺负同事。"},{"en":"They tried to bully him into signing the document.","zh":"他们试图胁迫他签署文件。"}]}],"bump":[{"pos":"v.","meaning":"碰撞；撞上","definition":"to hit something accidentally","examples":[{"en":"I bumped my knee against the table.","zh":"我的膝盖撞到了桌子。"},{"en":"The boat bumped against the dock.","zh":"船碰到了码头。"}]},{"pos":"v.","meaning":"颠簸着行进","definition":"to move with repeated jolts","examples":[{"en":"The bus bumped along the rough road.","zh":"公交车沿崎岖的道路颠簸前进。"},{"en":"Our bags bumped against the seats during the ride.","zh":"途中，我们的包不断撞到座位。"}]},{"pos":"n.","meaning":"碰撞；撞击声","definition":"a light collision or its sound","examples":[{"en":"We heard a bump upstairs.","zh":"我们听到楼上有一声碰撞。"},{"en":"The car stopped with a sudden bump.","zh":"汽车猛地一颠停了下来。"}]},{"pos":"n.","meaning":"肿块；隆起物","definition":"a raised area on a surface or body","examples":[{"en":"There was a bump on his forehead.","zh":"他的额头上有一个肿包。"},{"en":"Slow down for the bump in the road.","zh":"路上有凸起，减速慢行。"}]}],"bump into":[{"pos":"phrasal v.","meaning":"偶遇；不期而遇","definition":"to meet someone unexpectedly","examples":[{"en":"I bumped into an old teacher at the market.","zh":"我在市场偶遇了以前的一位老师。"},{"en":"You may bump into colleagues at the conference.","zh":"你可能会在会议上偶遇同事。"}]}],"bunch":[{"pos":"n.","meaning":"束；串；一群","definition":"a group of things held together or people gathered together","examples":[{"en":"She carried a bunch of flowers.","zh":"她拿着一束花。"},{"en":"A bunch of students waited outside.","zh":"一群学生在外面等候。"}]},{"pos":"v.","meaning":"聚拢；挤在一起；捆成束","definition":"to gather or be gathered closely together","examples":[{"en":"The runners began to bunch near the narrow gate.","zh":"跑步者开始在狭窄的门口挤成一团。"},{"en":"Bunch the stems together before tying them.","zh":"扎起来之前先把花茎拢在一起。"}]}],"bungalow":[{"pos":"n.","meaning":"平房；单层住宅","definition":"a house built on one main level","examples":[{"en":"They moved into a bungalow near the coast.","zh":"他们搬进了海边的一栋平房。"},{"en":"The bungalow has a small garden at the back.","zh":"平房后面有一个小花园。"}]}],"bureau":[{"pos":"n.","meaning":"局；处；机构；办事处","definition":"an office or organization providing a service","examples":[{"en":"The tourism bureau supplied a map of the city.","zh":"旅游局提供了一张城市地图。"},{"en":"She contacted the local advice bureau.","zh":"她联系了当地咨询机构。"}]}],"bureaucracy":[{"pos":"n.","meaning":"官僚机构；行政体系","definition":"a system of administration with officials and rules","examples":[{"en":"The reforms aim to modernise the bureaucracy.","zh":"这些改革旨在使行政机构现代化。"},{"en":"The ministry has a large bureaucracy.","zh":"这个部有一套庞大的行政体系。"}]},{"pos":"n.","meaning":"官僚主义；繁琐手续","definition":"excessive official rules and procedures","examples":[{"en":"Small businesses often struggle with bureaucracy.","zh":"小企业常常疲于应付繁琐手续。"},{"en":"The new service reduces unnecessary bureaucracy.","zh":"这项新服务减少了不必要的繁文缛节。"}]}],"burgeon":[{"pos":"v.","meaning":"迅速增长；蓬勃发展","definition":"to grow or develop quickly","examples":[{"en":"Demand for online courses continues to burgeon.","zh":"在线课程的需求继续迅速增长。"},{"en":"Small technology firms burgeoned in the city.","zh":"小型科技公司在这座城市蓬勃发展。"}]}],"burglar":[{"pos":"n.","meaning":"入室窃贼","definition":"a person who enters a building to steal","examples":[{"en":"A burglar entered through the unlocked window.","zh":"一名窃贼从未锁的窗户进入。"},{"en":"The police found the burglar carrying stolen jewellery.","zh":"警方发现窃贼携带着偷来的珠宝。"}]}],"burrow":[{"pos":"n.","meaning":"洞穴；地洞","definition":"a hole or tunnel dug by an animal","examples":[{"en":"The rabbit disappeared into its burrow.","zh":"兔子钻进地洞不见了。"},{"en":"The burrow has several entrances.","zh":"这个洞穴有几个入口。"}]},{"pos":"v.","meaning":"挖洞；钻进","definition":"to dig a tunnel or push into something","examples":[{"en":"Some insects burrow into wood.","zh":"有些昆虫会钻入木头。"},{"en":"He tried to burrow deeper under the blankets.","zh":"他试图往毯子下面钻得更深。"}]},{"pos":"v.","meaning":"翻找；深入搜寻","definition":"to search deeply through something","examples":[{"en":"She began to burrow through the old papers.","zh":"她开始翻找那些旧文件。"},{"en":"The researcher burrowed into the archive for evidence.","zh":"研究人员深入档案中搜寻证据。"}]}],"burst":[{"pos":"v.","meaning":"爆裂；破裂；使爆炸","definition":"to break open suddenly with force","examples":[{"en":"A pipe burst during the cold weather.","zh":"寒冷天气里，一根水管爆裂了。"},{"en":"The balloon burst with a loud pop.","zh":"气球砰的一声爆了。"}]},{"pos":"v.","meaning":"突然发作；突然开始","definition":"to begin doing something suddenly and strongly","examples":[{"en":"The audience burst into applause.","zh":"观众突然爆发出掌声。"},{"en":"She burst out laughing at the joke.","zh":"听到笑话，她突然笑了起来。"}]},{"pos":"n.","meaning":"爆发；突然的一阵","definition":"a sudden short period of an activity or sound","examples":[{"en":"A burst of sunlight lit the room.","zh":"一阵突然照入的阳光照亮了房间。"},{"en":"We heard a burst of laughter from the hall.","zh":"我们听到大厅里传来一阵笑声。"}]}],"bury":[{"pos":"v.","meaning":"埋葬；掩埋","definition":"to put someone or something under the ground","examples":[{"en":"They buried the seeds in moist soil.","zh":"他们把种子埋进湿润的土壤。"},{"en":"The family chose to bury him in his home village.","zh":"家人决定把他安葬在家乡的村庄。"}]},{"pos":"v.","meaning":"隐藏；埋头于","definition":"to hide something deeply or become absorbed in it","examples":[{"en":"The key was buried beneath a pile of letters.","zh":"钥匙藏在一堆信件下面。"},{"en":"She buried herself in work after the move.","zh":"搬家后，她埋头工作。"}]}],"buy":[{"pos":"v.","meaning":"购买；买","definition":"to obtain something by paying money for it","examples":[{"en":"We need to buy a ticket before boarding the train.","zh":"我们需要先买票再上火车。"},{"en":"She decided to buy fresh vegetables at the market.","zh":"她决定去市场买新鲜蔬菜。"}]},{"pos":"n.","meaning":"购买的东西；合算的购买","definition":"something bought, especially when judged by its value","examples":[{"en":"This second-hand bicycle was a good buy.","zh":"这辆二手自行车买得很划算。"},{"en":"At that price, the larger packet is the better buy.","zh":"按那个价格，买大包装更划算。"}]}],"bypass":[{"pos":"n.","meaning":"绕城道路；旁道","definition":"a road that allows traffic to avoid a town or congested area","examples":[{"en":"The bypass has reduced traffic in the town centre.","zh":"这条绕城道路减少了市中心的交通流量。"},{"en":"Take the bypass to avoid the roadworks.","zh":"走旁道避开道路施工区。"}]},{"pos":"v.","meaning":"绕过；避开","definition":"to go around or avoid something","examples":[{"en":"The path will bypass the flooded area.","zh":"这条小径将绕过淹水地区。"},{"en":"You cannot bypass the usual approval process.","zh":"你不能绕过正常的审批程序。"}]}],"cable":[{"pos":"n.","meaning":"缆绳；钢索","definition":"a thick strong rope or wire","examples":[{"en":"A steel cable supports the bridge.","zh":"一根钢索支撑着桥。"},{"en":"The lift is attached to a heavy cable.","zh":"升降机连着一根粗缆绳。"}]},{"pos":"n.","meaning":"电缆；通信电缆","definition":"an insulated wire or group of wires carrying electricity or signals","examples":[{"en":"The cable connects the monitor to the computer.","zh":"这根电缆连接显示器和电脑。"},{"en":"Workers laid a new cable beneath the street.","zh":"工人在街道下铺设了一条新电缆。"}]},{"pos":"n.","meaning":"电报（旧式用法）","definition":"a message sent by cable telegraph","examples":[{"en":"A cable arrived announcing the ship's safe arrival.","zh":"一封电报送来，告知船已安全抵达。"},{"en":"The archive contains a cable sent during the expedition.","zh":"档案中保存着探险期间发出的一封电报。"}]},{"pos":"v.","meaning":"发电报","definition":"to send a message by telegraph","examples":[{"en":"The captain cabled the office from the port.","zh":"船长从港口给办公室发了电报。"},{"en":"She cabled her family with news of the journey.","zh":"她给家人发电报，告知旅程消息。"}]}],"cafeteria":[{"pos":"n.","meaning":"自助餐厅；食堂","definition":"a restaurant where people collect food at a counter","examples":[{"en":"We had lunch in the school cafeteria.","zh":"我们在学校食堂吃了午饭。"},{"en":"The cafeteria offers a vegetarian meal every day.","zh":"食堂每天提供素食餐。"}]}],"calcium":[{"pos":"n.","meaning":"钙","definition":"a chemical element important in bones and teeth","examples":[{"en":"The laboratory measured calcium in the sample.","zh":"实验室测量了样本中的钙含量。"},{"en":"The label lists the calcium content of the drink.","zh":"标签列出了这种饮料的钙含量。"}]}],"calculate":[{"pos":"v.","meaning":"计算；推算","definition":"to find a number using mathematics","examples":[{"en":"We calculated the total cost of the trip.","zh":"我们算出了旅行的总费用。"},{"en":"The software calculates the average automatically.","zh":"软件会自动计算平均值。"}]},{"pos":"v.","meaning":"估计；推测","definition":"to make a reasoned estimate","examples":[{"en":"They calculated that the repairs would take a week.","zh":"他们估计维修需要一周。"},{"en":"I calculated how long the walk might take.","zh":"我估算了步行可能需要多长时间。"}]},{"pos":"v.","meaning":"筹划；有意使……发生","definition":"to plan something to produce a particular effect","examples":[{"en":"The announcement was calculated to reassure investors.","zh":"这份公告旨在让投资者放心。"},{"en":"Her remark was carefully calculated to change the mood.","zh":"她的话经过精心考虑，意在改变气氛。"}]}],"calendar":[{"pos":"n.","meaning":"日历；月历","definition":"a chart showing days, weeks, and months","examples":[{"en":"Mark the deadline on your calendar.","zh":"在日历上标出截止日期。"},{"en":"The wall calendar features photographs of local wildlife.","zh":"墙上的月历印有当地野生动物的照片。"}]},{"pos":"n.","meaning":"日程表","definition":"a schedule of planned events","examples":[{"en":"The conference calendar is available online.","zh":"会议日程可以在线查看。"},{"en":"She added the meeting to her shared calendar.","zh":"她把会议加入了共享日程表。"}]}],"calf":[{"pos":"n.","meaning":"牛犊；大型哺乳动物的幼崽","definition":"a young cow or the young of certain large mammals","examples":[{"en":"The calf stayed close to its mother.","zh":"小牛紧紧跟着母亲。"},{"en":"A young elephant calf played beside the herd.","zh":"一头小象在象群旁玩耍。"}]}],"calibrate":[{"pos":"v.","meaning":"校准；标定；划分刻度","definition":"to check or adjust a measuring instrument against a standard","examples":[{"en":"Technicians calibrate the scales every month.","zh":"技术员每月校准秤。"},{"en":"The thermometer must be calibrated before the experiment.","zh":"实验前必须校准温度计。"}]}],"calibre":[{"pos":"n.","meaning":"水平；才干；能力","definition":"the quality or ability of a person or thing","examples":[{"en":"The scholarship attracts researchers of a high calibre.","zh":"这项奖学金吸引了高水平的研究人员。"},{"en":"We need candidates of the right calibre for this role.","zh":"这个职位需要能力合适的候选人。"}]},{"pos":"n.","meaning":"口径","definition":"the internal diameter of a gun barrel","examples":[{"en":"The museum label identifies the weapon's calibre.","zh":"博物馆标签标明了这件武器的口径。"},{"en":"The two historic cannon differ in calibre.","zh":"这两门古炮口径不同。"}]}],"calm":[{"pos":"adj.","meaning":"镇静的；平静的","definition":"not agitated, worried, or rough","examples":[{"en":"She remained calm during the emergency.","zh":"紧急情况下她仍然保持镇静。"},{"en":"The sea was calm at sunrise.","zh":"日出时海面很平静。"}]},{"pos":"v.","meaning":"使镇静；使平静","definition":"to become or make someone less upset","examples":[{"en":"His gentle voice helped calm the child.","zh":"他温柔的声音帮助孩子平静下来。"},{"en":"The wind began to calm towards evening.","zh":"临近傍晚，风开始平息。"}]}],"calorie":[{"pos":"n.","meaning":"卡；热量单位","definition":"a unit used to measure energy, especially in food","examples":[{"en":"The label lists the number of calories per serving.","zh":"标签列出了每份食品的热量。"},{"en":"The lesson explains how a calorie measures energy.","zh":"这节课解释了卡如何用于计量能量。"}]}],"camel":[{"pos":"n.","meaning":"骆驼","definition":"a large desert animal with one or two humps","examples":[{"en":"The camel carried supplies across the dry plain.","zh":"骆驼载着物资穿过干旱的平原。"},{"en":"A camel can close its nostrils against blowing sand.","zh":"骆驼能闭合鼻孔以阻挡风沙。"}]}],"cameral":[{"pos":"adj.","meaning":"议院的；立法机构议室的","definition":"relating to a legislative chamber","examples":[{"en":"The report compares the two countries' cameral structures.","zh":"报告比较了两国的议院结构。"},{"en":"The reform would alter the legislature's cameral organisation.","zh":"这项改革将改变立法机构的议院组织形式。"}]}],"camouflage":[{"pos":"n.","meaning":"伪装；掩饰；保护色","definition":"concealment achieved by blending into the surroundings","examples":[{"en":"The insect's camouflage makes it difficult to see.","zh":"昆虫的保护色使它很难被发现。"},{"en":"The net provided camouflage for the equipment.","zh":"网为设备提供了伪装。"}]},{"pos":"v.","meaning":"伪装；掩饰","definition":"to hide something by making it blend with its surroundings","examples":[{"en":"They camouflaged the camera with leaves.","zh":"他们用树叶伪装摄像机。"},{"en":"The design camouflages the building among the trees.","zh":"这种设计让建筑隐藏在树木之间。"}]}],"campaign":[{"pos":"n.","meaning":"运动；有计划的活动","definition":"an organized effort to achieve a goal","examples":[{"en":"The campaign encourages people to use less plastic.","zh":"这项活动鼓励人们减少塑料使用。"},{"en":"The election campaign lasted six weeks.","zh":"竞选活动持续了六周。"}]},{"pos":"n.","meaning":"战役","definition":"a series of connected military operations","examples":[{"en":"The historian studied the campaign in the northern region.","zh":"这位历史学家研究了北部地区的战役。"},{"en":"The campaign ended when the opposing armies withdrew.","zh":"对立军队撤退后，这场战役结束了。"}]},{"pos":"v.","meaning":"开展活动；参加运动","definition":"to work actively towards a public goal","examples":[{"en":"Students campaigned for safer cycle routes.","zh":"学生们发起活动争取更安全的自行车道。"},{"en":"The group has campaigned against river pollution for years.","zh":"这个团体多年来一直开展反对河流污染的活动。"}]},{"pos":"v.","meaning":"参加军事行动","definition":"to take part in a series of military operations","examples":[{"en":"The army campaigned through the winter.","zh":"这支军队整个冬天都在作战。"},{"en":"The general had campaigned in several distant regions.","zh":"这位将军曾在几个遥远地区参加战役。"}]}],"camper":[{"pos":"n.","meaning":"露营者","definition":"a person who stays outdoors in a tent or temporary shelter","examples":[{"en":"Each camper must keep the site clean.","zh":"每名露营者都必须保持营地清洁。"},{"en":"The camper packed her tent before sunrise.","zh":"那位露营者在日出前收好了帐篷。"}]}],"campfire":[{"pos":"n.","meaning":"营火；篝火","definition":"an outdoor fire at a campsite","examples":[{"en":"We sat around the campfire after dinner.","zh":"晚饭后，我们围坐在营火旁。"},{"en":"The campers put out the campfire before leaving.","zh":"露营者离开前熄灭了营火。"}]}],"campus":[{"pos":"n.","meaning":"校园","definition":"the grounds and buildings of a university or college","examples":[{"en":"The library stands at the centre of the campus.","zh":"图书馆位于校园中央。"},{"en":"Bicycles are a popular way to travel around campus.","zh":"自行车是校园内常见的出行方式。"}]}],"cancel":[{"pos":"v.","meaning":"取消；撤销","definition":"to decide that a planned event or arrangement will not happen","examples":[{"en":"They had to cancel the outdoor concert.","zh":"他们不得不取消露天音乐会。"},{"en":"You can cancel the booking without a fee.","zh":"你可以免费取消预订。"}]},{"pos":"v.","meaning":"抵消；使无效","definition":"to balance or remove the effect of something","examples":[{"en":"The two forces cancel each other out.","zh":"这两种力量相互抵消。"},{"en":"Higher transport costs may cancel the savings.","zh":"更高的运输成本可能抵消节省下来的费用。"}]},{"pos":"v.","meaning":"划去；删去","definition":"to mark something so that it is no longer valid","examples":[{"en":"Cancel the incorrect figure and write the correct one beside it.","zh":"划去错误数字，在旁边写上正确数字。"},{"en":"The clerk cancelled the old stamp with a black mark.","zh":"办事员用黑色记号把旧邮票盖销了。"}]}],"candidate":[{"pos":"n.","meaning":"候选人；应聘者","definition":"a person being considered for a position or award","examples":[{"en":"Each candidate will be interviewed separately.","zh":"每位候选人将单独接受面试。"},{"en":"The committee selected three candidates for the prize.","zh":"委员会选出了三位奖项候选人。"}]},{"pos":"n.","meaning":"考生；应试者","definition":"a person taking an examination","examples":[{"en":"Candidates must bring identification to the examination.","zh":"考生必须携带身份证明参加考试。"},{"en":"The examiner explained the task to the candidate.","zh":"考官向考生解释了任务。"}]}],"cannon":[{"pos":"n.","meaning":"大炮；加农炮","definition":"a large heavy gun","examples":[{"en":"An old cannon stood beside the castle gate.","zh":"城堡门旁立着一门古炮。"},{"en":"The museum restored the bronze cannon.","zh":"博物馆修复了这门青铜炮。"}]}],"canoe":[{"pos":"n.","meaning":"独木舟；轻型划艇","definition":"a narrow boat moved with a paddle","examples":[{"en":"They crossed the lake in a canoe.","zh":"他们乘独木舟穿过湖泊。"},{"en":"The canoe was light enough for two people to carry.","zh":"这艘划艇很轻，两个人就能搬动。"}]}],"canteen":[{"pos":"n.","meaning":"食堂；餐厅","definition":"a place providing meals in a school or workplace","examples":[{"en":"The staff canteen serves lunch until two.","zh":"员工食堂供应午餐到两点。"},{"en":"Students queued outside the canteen.","zh":"学生们在食堂外排队。"}]}],"cantonese":[{"pos":"n.","meaning":"粤语；广东人","definition":"the Cantonese language or a person from Guangdong","examples":[{"en":"She speaks Cantonese with her grandparents.","zh":"她和祖父母说粤语。"},{"en":"Many Cantonese settled in the city during that period.","zh":"那个时期许多广东人在这座城市定居。"}]},{"pos":"adj.","meaning":"粤语的；广东的","definition":"relating to Guangdong or its language and culture","examples":[{"en":"The programme includes Cantonese dialogue.","zh":"这个节目包含粤语对话。"},{"en":"We tried traditional Cantonese dishes at the restaurant.","zh":"我们在餐馆品尝了传统粤菜。"}]}],"cap":[{"pos":"n.","meaning":"帽子；便帽","definition":"a soft hat, often with a peak","examples":[{"en":"He wore a blue cap to keep off the sun.","zh":"他戴着一顶蓝帽子遮阳。"},{"en":"She hung her cap beside the door.","zh":"她把帽子挂在门边。"}]},{"pos":"v.","meaning":"盖住；覆盖顶部","definition":"to cover the top of something","examples":[{"en":"Snow began to cap the distant peaks.","zh":"白雪开始覆盖远处的山顶。"},{"en":"Remember to cap the bottle after use.","zh":"用完后记得盖好瓶盖。"}]}],"capable":[{"pos":"adj.","meaning":"有能力的；能干的","definition":"having the ability to do something well","examples":[{"en":"She is capable of managing a large team.","zh":"她有能力管理大型团队。"},{"en":"The school needs a capable administrator.","zh":"学校需要一位能干的管理人员。"}]}],"capacity":[{"pos":"n.","meaning":"容量；容积；容纳能力","definition":"the maximum amount something can hold","examples":[{"en":"The hall has a capacity of three hundred people.","zh":"大厅可容纳三百人。"},{"en":"The reservoir is operating at half its capacity.","zh":"水库目前蓄水量为容量的一半。"}]},{"pos":"n.","meaning":"能力；生产能力","definition":"the power or ability to do something","examples":[{"en":"The brain has a remarkable capacity to learn.","zh":"大脑具有惊人的学习能力。"},{"en":"The factory increased its production capacity.","zh":"工厂提高了生产能力。"}]}],"capsize":[{"pos":"v.","meaning":"使船翻覆；倾覆","definition":"to turn a boat upside down or on its side","examples":[{"en":"A sudden wave caused the small boat to capsize.","zh":"突如其来的浪使小船翻覆。"},{"en":"Standing up can capsize a narrow canoe.","zh":"站起来可能使狭窄的独木舟倾覆。"}]}],"capsule":[{"pos":"n.","meaning":"胶囊","definition":"a small case containing a measured substance, often medicine","examples":[{"en":"The medicine comes in a capsule.","zh":"这种药装在胶囊中。"},{"en":"The pharmacist checked the capsule packaging.","zh":"药剂师检查了胶囊包装。"}]},{"pos":"n.","meaning":"航天舱；密封小舱","definition":"a small enclosed compartment, especially in a spacecraft","examples":[{"en":"The capsule returned safely to Earth.","zh":"返回舱安全回到了地球。"},{"en":"Engineers tested the capsule's protective shell.","zh":"工程师测试了太空舱的防护外壳。"}]}],"captive":[{"pos":"adj.","meaning":"被俘的；被圈养的","definition":"kept confined and unable to leave","examples":[{"en":"Researchers observed the behaviour of captive birds.","zh":"研究人员观察了圈养鸟类的行为。"},{"en":"The captive soldiers waited for news of their release.","zh":"被俘士兵等待获释的消息。"}]},{"pos":"adj.","meaning":"受控制的；无法自由选择的","definition":"unable to choose an alternative or avoid something","examples":[{"en":"Commuters on the only bus form a captive market.","zh":"只能乘坐这条公交线路的通勤者构成了被垄断的市场。"},{"en":"The long journey gave the speaker a captive audience.","zh":"漫长旅程让演讲者有了一群无法离开的听众。"}]},{"pos":"n.","meaning":"俘虏；被囚禁的人或动物","definition":"a person or animal kept confined","examples":[{"en":"The captives were released after negotiations.","zh":"谈判后，俘虏被释放了。"},{"en":"The injured captive was moved to a larger enclosure.","zh":"那只受伤的圈养动物被移到更大的围栏中。"}]}],"captivity":[{"pos":"n.","meaning":"囚禁；圈养","definition":"the state of being kept confined and unable to leave","examples":[{"en":"The animals were born in captivity.","zh":"这些动物出生于圈养环境。"},{"en":"He wrote about his years in captivity.","zh":"他写到了被囚禁的那些年。"}]}],"capture":[{"pos":"v.","meaning":"捕获；俘获；夺取","definition":"to catch or take control of someone or something","examples":[{"en":"The rangers captured the escaped deer.","zh":"护林员捕获了逃走的鹿。"},{"en":"The team tried to capture the escaped animal safely.","zh":"团队试图安全捕获逃出的动物。"}]},{"pos":"v.","meaning":"赢得；吸引","definition":"to gain attention, interest, or support","examples":[{"en":"The opening scene captured the audience's attention.","zh":"开场吸引了观众的注意。"},{"en":"Her proposal captured the support of the committee.","zh":"她的提议赢得了委员会的支持。"}]},{"pos":"v.","meaning":"记录；准确表现","definition":"to record or express something effectively","examples":[{"en":"The photograph captures the village's peaceful atmosphere.","zh":"照片捕捉到了村庄宁静的氛围。"},{"en":"The device captures data every second.","zh":"该设备每秒记录一次数据。"}]},{"pos":"n.","meaning":"捕获；俘获；夺取","definition":"the act of catching or gaining control of something","examples":[{"en":"The capture of the escaped animal took several hours.","zh":"捕获逃出的动物用了几个小时。"},{"en":"The article describes the capture of the fortress.","zh":"文章描述了攻占要塞的过程。"}]}],"cardiovascular":[{"pos":"adj.","meaning":"心血管的","definition":"relating to the heart and blood vessels","examples":[{"en":"The study examined cardiovascular health in older adults.","zh":"这项研究考察了老年人的心血管健康。"},{"en":"The hospital has a specialist cardiovascular research unit.","zh":"这家医院设有专门的心血管研究部门。"}]}],"career":[{"pos":"n.","meaning":"职业；职业生涯","definition":"a person's working life or chosen profession","examples":[{"en":"She began her career as a teacher.","zh":"她以教师身份开始了职业生涯。"},{"en":"He is considering a career in engineering.","zh":"他正在考虑从事工程方面的职业。"}]}],"carousel":[{"pos":"n.","meaning":"行李转盘；旋转传送带","definition":"a rotating conveyor for luggage or goods","examples":[{"en":"Our bags appeared on the carousel.","zh":"我们的行李出现在行李转盘上。"},{"en":"Passengers waited beside the baggage carousel.","zh":"乘客在行李转盘旁等待。"}]},{"pos":"n.","meaning":"旋转木马","definition":"a fairground ride with seats moving in a circle","examples":[{"en":"The children rode the carousel twice.","zh":"孩子们坐了两次旋转木马。"},{"en":"Music played as the carousel began to turn.","zh":"旋转木马开始转动时，音乐响了起来。"}]}],"carry":[{"pos":"v.","meaning":"搬运；携带；运送","definition":"to take something from one place to another","examples":[{"en":"Could you carry this box upstairs?","zh":"你能把这个箱子搬上楼吗？"},{"en":"The ferry carries passengers to the island.","zh":"渡船把乘客运到岛上。"}]},{"pos":"v.","meaning":"传播；传送","definition":"to transmit a signal, sound, or substance","examples":[{"en":"Water can carry pollutants into the river.","zh":"水会把污染物带入河流。"},{"en":"The wind carried their voices across the field.","zh":"风把他们的声音传过田野。"}]},{"pos":"n.","meaning":"搬运过程或距离","definition":"the act or distance of transporting something by hand","examples":[{"en":"There was a long carry from the car park to the campsite.","zh":"从停车场到营地需要搬运很长一段路。"},{"en":"The final carry took the equipment over a rocky path.","zh":"最后一段搬运需要把设备运过岩石小路。"}]},{"pos":"n.","meaning":"飞行距离；射程","definition":"the distance travelled by a ball or projectile before landing","examples":[{"en":"The golfer needed a carry of two hundred metres.","zh":"这位高尔夫球手需要打出两百米的空中距离。"},{"en":"The wind reduced the carry of the shot.","zh":"风缩短了这一击的飞行距离。"}]}],"carve":[{"pos":"v.","meaning":"雕刻；刻制","definition":"to shape something by cutting material away","examples":[{"en":"The artist will carve a bird from wood.","zh":"艺术家将用木头雕刻一只鸟。"},{"en":"Their initials were carved into the stone.","zh":"他们姓名的首字母被刻在石头上。"}]},{"pos":"v.","meaning":"切开；切成片","definition":"to cut cooked meat into pieces","examples":[{"en":"He offered to carve the turkey.","zh":"他主动提出把火鸡切好。"},{"en":"Use a sharp knife to carve thin slices.","zh":"用锋利的刀切出薄片。"}]}],"cascade":[{"pos":"n.","meaning":"小瀑布；瀑布状落下的东西","definition":"a waterfall or a stream of things falling","examples":[{"en":"A cascade flowed over the rocks.","zh":"一道小瀑布从岩石上流下。"},{"en":"A cascade of flowers hung over the wall.","zh":"一片瀑布般的花朵垂在墙上。"}]},{"pos":"n.","meaning":"连续发生的一系列事件","definition":"a sequence in which one event causes another","examples":[{"en":"The failure triggered a cascade of delays.","zh":"故障引发了一连串延误。"},{"en":"The discovery led to a cascade of further questions.","zh":"这一发现引出了接连不断的新问题。"}]}],"cash":[{"pos":"n.","meaning":"现金","definition":"money in the form of notes and coins","examples":[{"en":"The market stall accepts only cash.","zh":"这个市场摊位只收现金。"},{"en":"I keep a little cash for emergencies.","zh":"我留了一点现金应急。"}]},{"pos":"v.","meaning":"兑现","definition":"to exchange a cheque or similar document for money","examples":[{"en":"She went to the bank to cash the cheque.","zh":"她到银行兑现支票。"},{"en":"You can cash the voucher at the reception desk.","zh":"你可以在前台兑现这张凭券。"}]}],"cassette":[{"pos":"n.","meaning":"盒式录音带；盒式录像带","definition":"a small case containing magnetic tape for recording","examples":[{"en":"She found an old cassette of family songs.","zh":"她找到了一盘录有家人唱歌的旧磁带。"},{"en":"The machine damaged the tape inside the cassette.","zh":"机器损坏了盒内的磁带。"}]}],"cast":[{"pos":"v.","meaning":"投射；投下","definition":"to direct light, a shadow, or a look","examples":[{"en":"The lamp cast a warm light over the table.","zh":"灯在桌上投下温暖的光。"},{"en":"She cast a quick glance at the clock.","zh":"她迅速看了一眼钟。"}]},{"pos":"v.","meaning":"投；抛；扔","definition":"to throw something","examples":[{"en":"The fisherman cast his line into the river.","zh":"渔夫把鱼线抛入河中。"},{"en":"They cast stones across the water.","zh":"他们把石子抛过水面。"}]},{"pos":"v.","meaning":"使产生；把……加于","definition":"to cause a particular feeling, doubt, or influence","examples":[{"en":"The mistake cast doubt on the results.","zh":"这个错误使结果受到质疑。"},{"en":"The closure cast a shadow over the town's future.","zh":"关闭事件给城镇的未来蒙上阴影。"}]},{"pos":"v.","meaning":"抛弃；脱去；蜕落","definition":"to discard something or shed a natural covering","examples":[{"en":"She cast aside her doubts and began.","zh":"她抛开疑虑，开始行动。"},{"en":"The snake cast its old skin.","zh":"蛇蜕去了旧皮。"}]},{"pos":"v.","meaning":"浇铸；铸造","definition":"to form an object by pouring material into a mould","examples":[{"en":"The artist cast the statue in bronze.","zh":"艺术家用青铜铸造了雕像。"},{"en":"The factory casts metal components for engines.","zh":"工厂铸造发动机金属部件。"}]},{"pos":"v.","meaning":"选派演员","definition":"to choose an actor for a role","examples":[{"en":"They cast her as the lead scientist.","zh":"他们选她饰演女科学家主角。"},{"en":"The director is casting the new play.","zh":"导演正在为新剧挑选演员。"}]},{"pos":"n.","meaning":"全体演员；演员阵容","definition":"all the actors in a production","examples":[{"en":"The cast rehearsed every afternoon.","zh":"全体演员每天下午排练。"},{"en":"The film has an international cast.","zh":"这部电影拥有国际演员阵容。"}]},{"pos":"n.","meaning":"石膏固定；石膏绷带","definition":"a hard covering supporting a broken limb","examples":[{"en":"Her arm was in a cast.","zh":"她的手臂打着石膏。"},{"en":"The doctor removed the cast after the bone healed.","zh":"骨头愈合后，医生拆除了石膏。"}]},{"pos":"n.","meaning":"铸件；铸模；复制模型","definition":"an object made in a mould or a moulded copy","examples":[{"en":"The museum displays a plaster cast of the sculpture.","zh":"博物馆展出这座雕像的石膏复制品。"},{"en":"The cast was removed from the mould.","zh":"铸件被从模具中取出。"}]},{"pos":"n.","meaning":"特征；倾向；样子","definition":"a particular quality or appearance","examples":[{"en":"His thinking has a practical cast.","zh":"他的思维带有务实的倾向。"},{"en":"The light gave the room a bluish cast.","zh":"光线使房间带上了一层蓝色调。"}]}],"casual":[{"pos":"adj.","meaning":"随意的；不经意的","definition":"relaxed or done without much thought","examples":[{"en":"A casual remark led to a useful discussion.","zh":"一句随口的评论引出了一场有益的讨论。"},{"en":"He gave the timetable a casual glance.","zh":"他随意瞥了一眼时刻表。"}]},{"pos":"adj.","meaning":"非正式的；临时的","definition":"informal or not arranged on a permanent basis","examples":[{"en":"The office allows casual clothing on Fridays.","zh":"办公室允许员工周五穿便装。"},{"en":"She found casual work during the summer.","zh":"她在夏天找到了临时工作。"}]}],"casualty":[{"pos":"n.","meaning":"伤亡人员；死伤者","definition":"someone killed or injured in an accident or conflict","examples":[{"en":"Each casualty was taken to the nearest hospital.","zh":"每名伤员都被送往最近的医院。"},{"en":"The report gave the total number of casualties.","zh":"报告给出了伤亡人员的总数。"}]},{"pos":"n.","meaning":"受害者；遭损失的事物","definition":"someone or something harmed by an event or situation","examples":[{"en":"The village shop was a casualty of the recession.","zh":"这家乡村商店成为经济衰退的受害者。"},{"en":"Public trust became another casualty of the scandal.","zh":"公众信任成了这场丑闻的另一个牺牲品。"}]}],"catalogue":[{"pos":"n.","meaning":"目录；一系列","definition":"a list of items or a series of events","examples":[{"en":"The catalogue lists every book in the collection.","zh":"目录列出了馆藏中的每本书。"},{"en":"The report describes a catalogue of errors.","zh":"报告列举了一连串错误。"}]},{"pos":"v.","meaning":"编目；记录","definition":"to make an organised list or record of things","examples":[{"en":"Volunteers helped catalogue the photographs.","zh":"志愿者帮助为照片编目。"},{"en":"The study catalogues changes in local wildlife.","zh":"研究记录了当地野生动物的变化。"}]}],"catastrophe":[{"pos":"n.","meaning":"灾难；惨祸","definition":"an event causing great damage or suffering","examples":[{"en":"The flood was a catastrophe for local farms.","zh":"这场洪水对当地农场而言是一场灾难。"},{"en":"Early warnings helped prevent a major catastrophe.","zh":"提前预警有助于避免一场重大灾难。"}]}],"catastrophic":[{"pos":"adj.","meaning":"灾难性的；造成巨大损失的","definition":"causing very great damage or suffering","examples":[{"en":"The floods had catastrophic effects on local farms.","zh":"洪水对当地农场造成了灾难性的影响。"},{"en":"A catastrophic engine failure forced the plane to land.","zh":"严重的发动机故障迫使飞机降落。"}]}],"category":[{"pos":"n.","meaning":"类别；种类；范畴","definition":"a group of things sharing particular features","examples":[{"en":"The entries are divided into three categories.","zh":"这些条目分为三类。"},{"en":"Which category does this expense belong to?","zh":"这笔费用属于哪个类别？"}]}],"cater":[{"pos":"v.","meaning":"提供餐饮","definition":"to supply food and drink for an event","examples":[{"en":"The restaurant will cater for the conference.","zh":"这家餐馆将为会议提供餐饮。"},{"en":"Her business caters weddings and private parties.","zh":"她的公司承办婚礼和私人聚会的餐饮。"}]},{"pos":"v.","meaning":"满足需要；迎合","definition":"to provide what a group needs or wants","examples":[{"en":"The course caters for learners with different backgrounds.","zh":"这门课程满足不同背景学习者的需要。"},{"en":"The website caters to people planning independent travel.","zh":"这个网站面向计划自由行的人提供服务。"}]}],"caustic":[{"pos":"adj.","meaning":"腐蚀性的","definition":"able to chemically burn or destroy material","examples":[{"en":"Workers wore gloves when handling the caustic solution.","zh":"工人处理腐蚀性溶液时戴着手套。"},{"en":"Store caustic chemicals in clearly labelled containers.","zh":"将腐蚀性化学品存放在标识清楚的容器中。"}]},{"pos":"adj.","meaning":"尖刻的；挖苦的","definition":"harshly critical or sarcastic","examples":[{"en":"Her caustic comments upset the speaker.","zh":"她尖刻的评论令发言者不快。"},{"en":"The review was witty but caustic.","zh":"这篇评论诙谐但尖刻。"}]},{"pos":"n.","meaning":"腐蚀剂","definition":"a substance capable of chemically burning tissue or material","examples":[{"en":"The laboratory keeps each caustic in secure storage.","zh":"实验室将每种腐蚀剂妥善存放。"},{"en":"The container was labelled as a strong caustic.","zh":"容器上标注着强腐蚀剂。"}]}],"caution":[{"pos":"n.","meaning":"谨慎；小心","definition":"care taken to avoid danger or mistakes","examples":[{"en":"Proceed with caution on the slippery path.","zh":"在湿滑的小路上要谨慎前行。"},{"en":"The findings should be treated with caution.","zh":"这些发现应谨慎对待。"}]},{"pos":"v.","meaning":"警告；提醒","definition":"to warn someone to be careful","examples":[{"en":"The guide cautioned us against leaving the marked trail.","zh":"导游提醒我们不要离开标记的路线。"},{"en":"Experts caution that the evidence is still limited.","zh":"专家提醒，证据仍然有限。"}]}],"cautious":[{"pos":"adj.","meaning":"谨慎的；小心的","definition":"careful to avoid danger or mistakes","examples":[{"en":"Investors remained cautious after the sudden price fall.","zh":"价格突然下跌后，投资者仍保持谨慎。"},{"en":"Take a cautious approach when interpreting a small sample.","zh":"解释小样本时要采取谨慎态度。"}]}],"cavort":[{"pos":"v.","meaning":"欢跃；嬉戏","definition":"to jump or move about playfully","examples":[{"en":"The children cavort in the shallow water.","zh":"孩子们在浅水里嬉戏。"},{"en":"Young goats cavorted across the hillside.","zh":"小山羊在山坡上跳跃玩耍。"}]}],"cease":[{"pos":"v.","meaning":"停止；终止","definition":"to stop or bring something to an end","examples":[{"en":"The rain ceased before dawn.","zh":"雨在黎明前停了。"},{"en":"The company ceased production at the old factory.","zh":"公司停止了旧工厂的生产。"}]}],"celebrate":[{"pos":"v.","meaning":"庆祝","definition":"to mark a happy event with special activities","examples":[{"en":"We held a picnic to celebrate the end of term.","zh":"我们举行野餐庆祝学期结束。"},{"en":"The town celebrated the opening of its new library.","zh":"全镇庆祝新图书馆开馆。"}]},{"pos":"v.","meaning":"颂扬；赞美","definition":"to publicly honour something admirable","examples":[{"en":"The exhibition celebrates the achievements of local artists.","zh":"这场展览颂扬当地艺术家的成就。"},{"en":"Her poems celebrate the beauty of ordinary places.","zh":"她的诗歌赞美平凡地方的美。"}]}],"celebrity":[{"pos":"n.","meaning":"名人；知名人士","definition":"a person who is widely known","examples":[{"en":"A local celebrity opened the new library.","zh":"一位当地名人为新图书馆揭幕。"},{"en":"The celebrity spoke about protecting personal privacy.","zh":"这位名人谈到了保护个人隐私。"}]},{"pos":"n.","meaning":"名气；名望","definition":"the state of being famous","examples":[{"en":"The success of the novel brought her sudden celebrity.","zh":"小说的成功使她突然成名。"},{"en":"He found celebrity less satisfying than he had expected.","zh":"他发现名望并没有预想的那么令人满足。"}]}],"celestial":[{"pos":"adj.","meaning":"天体的；天空的","definition":"relating to the sky or outer space","examples":[{"en":"The telescope tracks celestial objects.","zh":"望远镜追踪天体。"},{"en":"Ancient sailors used celestial navigation.","zh":"古代水手使用天文导航。"}]}],"cell":[{"pos":"n.","meaning":"细胞","definition":"the smallest basic unit of living organisms","examples":[{"en":"The microscope revealed changes inside the cell.","zh":"显微镜显示了细胞内部的变化。"},{"en":"Each cell contains structures that perform different tasks.","zh":"每个细胞都含有承担不同任务的结构。"}]},{"pos":"n.","meaning":"小房间；牢房","definition":"a small room, especially in a prison","examples":[{"en":"The prisoner returned to his cell.","zh":"囚犯回到了牢房。"},{"en":"The old monastery has a tiny cell for each monk.","zh":"这座旧修道院为每位修士设有一间小房间。"}]},{"pos":"n.","meaning":"电池单元","definition":"a unit that produces electrical energy","examples":[{"en":"The battery contains six separate cells.","zh":"这组电池含有六个独立电池单元。"},{"en":"A solar cell converts light into electricity.","zh":"太阳能电池把光转化为电。"}]}],"censor":[{"pos":"v.","meaning":"审查并删改","definition":"to examine material and remove parts judged unacceptable","examples":[{"en":"The authorities tried to censor the newspaper.","zh":"当局试图审查并删改这家报纸的内容。"},{"en":"The broadcast was censored before release.","zh":"这段广播在发布前经过了审查删改。"}]},{"pos":"n.","meaning":"审查员","definition":"an official who examines material and may remove parts of it","examples":[{"en":"The censor demanded changes to the script.","zh":"审查员要求修改剧本。"},{"en":"A censor reviewed every outgoing letter.","zh":"一名审查员检查了每一封寄出的信。"}]}],"censure":[{"pos":"n.","meaning":"谴责；指责","definition":"strong formal disapproval","examples":[{"en":"The decision attracted public censure.","zh":"这一决定招致公众谴责。"},{"en":"The committee issued a formal censure.","zh":"委员会作出了正式谴责。"}]},{"pos":"v.","meaning":"谴责；责难","definition":"to express strong formal disapproval","examples":[{"en":"The board censured the manager for misconduct.","zh":"董事会因不当行为谴责了经理。"},{"en":"The report censures the failure to follow safety rules.","zh":"报告谴责了不遵守安全规定的行为。"}]}],"centennial":[{"pos":"n.","meaning":"百年纪念","definition":"the hundredth anniversary of an event","examples":[{"en":"The school celebrated its centennial with an exhibition.","zh":"学校通过展览庆祝百年校庆。"},{"en":"A new garden was planted for the town's centennial.","zh":"为纪念建镇一百周年，人们建了一座新花园。"}]},{"pos":"adj.","meaning":"百年的；百年纪念的","definition":"relating to a hundredth anniversary","examples":[{"en":"The centennial ceremony brought former students together.","zh":"百年校庆仪式让昔日学生欢聚一堂。"},{"en":"The museum issued a centennial collection of photographs.","zh":"博物馆出版了一本百年纪念摄影集。"}]}],"centigrade":[{"pos":"adj.","meaning":"摄氏的；百分度的","definition":"using a temperature scale with one hundred degrees between water's freezing and boiling points","examples":[{"en":"The temperature reached thirty degrees centigrade.","zh":"温度达到了摄氏三十度。"},{"en":"The thermometer has a centigrade scale.","zh":"这支温度计使用摄氏刻度。"}]}],"centrifugal force":[{"pos":"n.","meaning":"离心力","definition":"the apparent outward force experienced in a rotating frame","examples":[{"en":"The lesson used a rotating model to explain centrifugal force.","zh":"课堂用旋转模型解释离心力。"},{"en":"The diagram shows the direction of centrifugal force in the rotating frame.","zh":"图示显示了旋转参考系中离心力的方向。"}]}],"ceramic":[{"pos":"adj.","meaning":"陶瓷的","definition":"made from clay hardened by heat","examples":[{"en":"The floor is covered with ceramic tiles.","zh":"地面铺着陶瓷砖。"},{"en":"Ceramic cups retain heat well.","zh":"陶瓷杯保温效果不错。"}]},{"pos":"n.","meaning":"陶瓷制品；陶瓷材料","definition":"an object or material made by firing clay","examples":[{"en":"The gallery displays ceramics by local makers.","zh":"这家画廊展出当地工匠的陶瓷作品。"},{"en":"This technical ceramic can withstand high temperatures.","zh":"这种工业陶瓷能够耐受高温。"}]}],"cereal":[{"pos":"n.","meaning":"谷物；谷类作物","definition":"a plant grown for its edible grain or the grain itself","examples":[{"en":"Wheat is an important cereal crop.","zh":"小麦是一种重要的谷类作物。"},{"en":"The farm grows several types of cereal.","zh":"这个农场种植几种谷物。"}]},{"pos":"n.","meaning":"谷物早餐食品","definition":"food made from grain and commonly eaten for breakfast","examples":[{"en":"He eats cereal with milk each morning.","zh":"他每天早上吃加牛奶的谷物早餐。"},{"en":"This cereal contains dried fruit.","zh":"这种谷物早餐食品含有果干。"}]}],"ceremony":[{"pos":"n.","meaning":"典礼；仪式","definition":"a formal event following established customs","examples":[{"en":"The graduation ceremony begins at ten.","zh":"毕业典礼十点开始。"},{"en":"A short ceremony marked the opening of the library.","zh":"一个简短仪式标志着图书馆开馆。"}]}],"certificate":[{"pos":"n.","meaning":"证书；证明；执照","definition":"an official document confirming a fact or qualification","examples":[{"en":"She received a certificate after completing the course.","zh":"完成课程后，她获得了证书。"},{"en":"Bring your birth certificate when you register.","zh":"登记时请带上出生证明。"}]}],"certify":[{"pos":"v.","meaning":"证明；认证","definition":"to confirm officially that something is true or meets a standard","examples":[{"en":"An inspector must certify that the lift is safe.","zh":"检查员必须证明电梯安全。"},{"en":"The document certifies her completion of the course.","zh":"这份文件证明她完成了课程。"}]}],"cervical":[{"pos":"adj.","meaning":"颈部的","definition":"relating to the neck","examples":[{"en":"The diagram labels the cervical vertebrae.","zh":"图中标出了颈椎。"},{"en":"The specialist examined the patient's cervical spine.","zh":"专科医生检查了患者的颈椎。"}]},{"pos":"adj.","meaning":"子宫颈的","definition":"relating to the cervix of the uterus","examples":[{"en":"The leaflet explains cervical screening.","zh":"宣传单介绍了宫颈筛查。"},{"en":"The study concerns cervical health.","zh":"该研究关注宫颈健康。"}]}],"chain":[{"pos":"n.","meaning":"链条；锁链","definition":"connected metal links used for fastening or restraint","examples":[{"en":"A heavy chain secured the gate.","zh":"一条粗链锁住了大门。"},{"en":"The prisoner was freed from his chains.","zh":"囚犯被解除了镣铐。"}]},{"pos":"n.","meaning":"一系列；连锁店","definition":"a connected series of events or businesses","examples":[{"en":"One error triggered a chain of delays.","zh":"一个错误引发了一连串延误。"},{"en":"The bakery belongs to a regional chain.","zh":"这家面包店属于一个地区连锁品牌。"}]},{"pos":"v.","meaning":"用链条拴住","definition":"to fasten something with a chain","examples":[{"en":"He chained his bicycle to the railing.","zh":"他用链条把自行车锁在栏杆上。"},{"en":"The boats were chained together during the storm.","zh":"暴风雨期间，船只被用链条连在一起。"}]}],"challenge":[{"pos":"n.","meaning":"挑战；难题","definition":"a difficult task requiring effort or skill","examples":[{"en":"Learning to manage the team was a major challenge.","zh":"学会管理团队是一项重大挑战。"},{"en":"The bridge presents a serious engineering challenge.","zh":"这座桥提出了一个重大的工程难题。"}]},{"pos":"n.","meaning":"质疑；异议","definition":"a statement or action questioning something","examples":[{"en":"The policy faces a legal challenge.","zh":"这项政策面临法律挑战。"},{"en":"Her evidence was a challenge to the accepted theory.","zh":"她的证据对公认理论提出了质疑。"}]},{"pos":"v.","meaning":"挑战；要求竞争","definition":"to invite someone to compete or test their abilities","examples":[{"en":"He challenged his friend to a game of chess.","zh":"他向朋友发出下棋的挑战。"},{"en":"The course will challenge even experienced learners.","zh":"这门课程甚至会让经验丰富的学习者感到挑战。"}]},{"pos":"v.","meaning":"质疑；反对","definition":"to question whether something is correct or acceptable","examples":[{"en":"Researchers challenge the claim that the effect is universal.","zh":"研究人员质疑该效应普遍存在的说法。"},{"en":"Employees should be able to challenge unfair decisions.","zh":"员工应当能够对不公平的决定提出异议。"}]}],"chamber":[{"pos":"n.","meaning":"室；房间；腔室","definition":"an enclosed room or space","examples":[{"en":"The council meets in the main chamber.","zh":"议会在主议事厅开会。"},{"en":"Gas enters a sealed chamber.","zh":"气体进入一个密封腔室。"}]},{"pos":"n.","meaning":"洞穴；洞室","definition":"an enclosed space inside a cave or natural formation","examples":[{"en":"The passage opens into a large underground chamber.","zh":"通道通向一个巨大的地下洞室。"},{"en":"Water dripped from the roof of the chamber.","zh":"水从洞室顶部滴落。"}]},{"pos":"n.","meaning":"枪膛；弹膛","definition":"the part of a firearm that holds a cartridge before firing","examples":[{"en":"The display explains the shape of the rifle's chamber.","zh":"展品说明了步枪弹膛的形状。"},{"en":"The damaged chamber was examined by an expert.","zh":"受损的弹膛由专家检查。"}]}],"champion":[{"pos":"n.","meaning":"冠军","definition":"the winner of a competition","examples":[{"en":"The local champion qualified for the national race.","zh":"本地冠军取得了全国比赛的资格。"},{"en":"She became world champion at the age of twenty.","zh":"她二十岁时成为世界冠军。"}]}],"chancellor":[{"pos":"n.","meaning":"总理；大臣；司法官（依国家和职位而定）","definition":"a senior political or legal official whose role depends on the country","examples":[{"en":"The German chancellor addressed parliament.","zh":"德国总理向议会发表讲话。"},{"en":"The Chancellor of the Exchequer announced the budget.","zh":"英国财政大臣公布了预算。"}]},{"pos":"n.","meaning":"大学校长；大学名誉校长","definition":"the head or ceremonial head of a university","examples":[{"en":"The university chancellor presented the degrees.","zh":"大学校长颁发了学位。"},{"en":"The chancellor welcomed graduates and their families.","zh":"校长欢迎毕业生及其家人。"}]}],"channel":[{"pos":"n.","meaning":"频道","definition":"a television or radio station or signal band","examples":[{"en":"The documentary is on a science channel.","zh":"这部纪录片在科学频道播出。"},{"en":"She changed the channel to hear the news.","zh":"她换了频道收听新闻。"}]},{"pos":"n.","meaning":"途径；渠道","definition":"a means of communicating or distributing something","examples":[{"en":"Use the official channel to submit complaints.","zh":"请通过官方渠道提交投诉。"},{"en":"The charity developed new channels for delivering aid.","zh":"慈善机构开辟了运送援助物资的新渠道。"}]},{"pos":"n.","meaning":"沟渠；水道；航道","definition":"a passage through which water or ships move","examples":[{"en":"Rainwater flows through a narrow channel.","zh":"雨水沿一条狭窄的沟渠流动。"},{"en":"The ship stayed within the marked channel.","zh":"船保持在标出的航道内。"}]},{"pos":"n.","meaning":"海峡","definition":"a stretch of water separating two areas of land","examples":[{"en":"The ferry crossed the channel overnight.","zh":"渡轮夜间穿过海峡。"},{"en":"Strong winds delayed travel across the channel.","zh":"大风延误了穿越海峡的行程。"}]}],"chaos":[{"pos":"n.","meaning":"混乱；无秩序","definition":"a state of complete disorder","examples":[{"en":"The power failure caused chaos at the station.","zh":"停电使车站陷入混乱。"},{"en":"Clear signs restored order after the initial chaos.","zh":"清楚的指示牌让最初的混乱恢复了秩序。"}]}],"chapel":[{"pos":"n.","meaning":"小教堂；祈祷室","definition":"a small building or room used for Christian worship","examples":[{"en":"A small chapel stands beside the hospital.","zh":"医院旁有一座小教堂。"},{"en":"Visitors sat quietly in the chapel.","zh":"游客安静地坐在祈祷室里。"}]}],"character":[{"pos":"n.","meaning":"性格；品格","definition":"the qualities that make a person distinctive","examples":[{"en":"Her calm character helped the team.","zh":"她沉着的性格帮助了团队。"},{"en":"The experience revealed his strength of character.","zh":"这段经历显示了他坚强的品格。"}]},{"pos":"n.","meaning":"特征；性质","definition":"the distinctive nature of a place or thing","examples":[{"en":"The renovation preserved the building's character.","zh":"翻修保留了建筑的特色。"},{"en":"Tourism has changed the character of the village.","zh":"旅游业改变了村庄的面貌。"}]},{"pos":"n.","meaning":"人物；角色","definition":"a person represented in a story or performance","examples":[{"en":"The main character is a young teacher.","zh":"主角是一位年轻教师。"},{"en":"Each character has a different reason for leaving.","zh":"每个角色都有不同的离开理由。"}]},{"pos":"n.","meaning":"字符；文字；汉字","definition":"a written or printed symbol","examples":[{"en":"The password must contain at least eight characters.","zh":"密码必须至少包含八个字符。"},{"en":"She learned to write the Chinese character carefully.","zh":"她认真学习书写这个汉字。"}]}],"characteristic":[{"pos":"n.","meaning":"特征；特性","definition":"a distinguishing feature","examples":[{"en":"Flexibility is an important characteristic of this material.","zh":"柔韧性是这种材料的一个重要特性。"},{"en":"The study compared the characteristics of different habitats.","zh":"研究比较了不同栖息地的特征。"}]},{"pos":"adj.","meaning":"典型的；特有的","definition":"typical of a particular person or thing","examples":[{"en":"The bird has a characteristic yellow stripe.","zh":"这种鸟有一道特有的黄色条纹。"},{"en":"She answered with her characteristic patience.","zh":"她以一贯的耐心作答。"}]}],"charcoal":[{"pos":"n.","meaning":"木炭；炭","definition":"a black fuel or drawing material made by heating wood with little air","examples":[{"en":"They cooked over a charcoal fire.","zh":"他们用炭火做饭。"},{"en":"She sketched the trees in charcoal.","zh":"她用炭笔画了树木的素描。"}]}],"charge":[{"pos":"n.","meaning":"费用；收费","definition":"an amount of money requested for a service","examples":[{"en":"There is no charge for admission.","zh":"入场不收费。"},{"en":"The delivery charge is included in the price.","zh":"配送费包含在价格内。"}]},{"pos":"n.","meaning":"管理；照管；责任","definition":"responsibility for someone or something","examples":[{"en":"She is in charge of the library.","zh":"她负责管理图书馆。"},{"en":"The children were left in his charge.","zh":"孩子们被交给他照管。"}]},{"pos":"n.","meaning":"指控；控告","definition":"an official accusation of wrongdoing","examples":[{"en":"He denied the charge against him.","zh":"他否认了对他的指控。"},{"en":"The charge was dropped after further investigation.","zh":"进一步调查后，指控被撤销了。"}]},{"pos":"n.","meaning":"电荷；电量","definition":"an electrical property or stored electrical energy","examples":[{"en":"The battery has very little charge left.","zh":"电池剩余电量很少。"},{"en":"The experiment demonstrates electric charge.","zh":"实验展示了电荷现象。"}]},{"pos":"v.","meaning":"收费；索价","definition":"to ask a price for goods or services","examples":[{"en":"The hotel charges extra for breakfast.","zh":"酒店额外收取早餐费。"},{"en":"They charge a small fee for repairs.","zh":"他们收取少量维修费。"}]},{"pos":"v.","meaning":"指控","definition":"to officially accuse someone of an offence","examples":[{"en":"Police charged the driver with dangerous driving.","zh":"警方指控司机危险驾驶。"},{"en":"She was charged with damaging public property.","zh":"她被指控损坏公共财产。"}]},{"pos":"v.","meaning":"委托；责成；指示","definition":"to give someone a duty or responsibility","examples":[{"en":"The committee was charged with reviewing the rules.","zh":"委员会受命审查这些规则。"},{"en":"She charged her assistant with organising the meeting.","zh":"她责成助理组织会议。"}]},{"pos":"v.","meaning":"充电","definition":"to store electrical energy in a battery","examples":[{"en":"I need to charge my phone.","zh":"我需要给手机充电。"},{"en":"The vehicle can be charged overnight.","zh":"车辆可以在夜间充电。"}]}],"charity":[{"pos":"n.","meaning":"慈善机构","definition":"an organization that helps people in need","examples":[{"en":"The charity runs a shelter for homeless families.","zh":"这家慈善机构运营着一家无家可归家庭收容所。"},{"en":"We donated the proceeds to a local charity.","zh":"我们把收益捐给了当地一家慈善机构。"}]},{"pos":"n.","meaning":"慈善；救济；施舍","definition":"help given to people in need","examples":[{"en":"The concert raised money for charity.","zh":"这场音乐会为慈善事业筹款。"},{"en":"The family preferred paid work to living on charity.","zh":"这个家庭宁愿靠工作挣钱，也不愿靠救济生活。"}]}],"chart":[{"pos":"n.","meaning":"图表","definition":"a visual display of information","examples":[{"en":"The chart shows how prices changed over time.","zh":"图表展示了价格随时间的变化。"},{"en":"Use a chart to compare the three groups.","zh":"用图表比较这三个群体。"}]},{"pos":"n.","meaning":"海图；航图","definition":"a map used for navigation","examples":[{"en":"The captain checked the nautical chart.","zh":"船长查看了海图。"},{"en":"The chart marks rocks near the harbour entrance.","zh":"海图标出了港口入口附近的岩石。"}]},{"pos":"v.","meaning":"记录；绘制图表或地图","definition":"to record progress or show information on a chart","examples":[{"en":"The study charts changes in public attitudes.","zh":"这项研究记录了公众态度的变化。"},{"en":"The expedition helped chart the previously unmapped coast.","zh":"这次探险帮助绘制了此前未被测绘的海岸地图。"}]}],"charter":[{"pos":"n.","meaning":"宪章；章程；纲领","definition":"a formal statement of rights, aims, or rules","examples":[{"en":"The organisation adopted a new charter.","zh":"组织通过了新章程。"},{"en":"The charter sets out the rights of residents.","zh":"宪章阐明了居民的权利。"}]},{"pos":"n.","meaning":"包租；租用","definition":"an arrangement to hire a whole vehicle","examples":[{"en":"The group arranged a boat charter.","zh":"团队安排了包船。"},{"en":"The flight was operated under a private charter.","zh":"该航班是私人包机。"}]},{"pos":"v.","meaning":"包租","definition":"to hire a whole aircraft, ship, or vehicle","examples":[{"en":"They chartered a bus for the school trip.","zh":"他们为学校旅行包了一辆公交车。"},{"en":"The researchers chartered a boat to reach the island.","zh":"研究人员包船前往小岛。"}]},{"pos":"v.","meaning":"特许设立；授予特许状","definition":"to formally establish an institution by granting a charter","examples":[{"en":"The college was chartered in the nineteenth century.","zh":"这所学院于十九世纪获得特许设立。"},{"en":"The state chartered the new public institution.","zh":"州政府特许设立了这家新公共机构。"}]}],"chase":[{"pos":"v.","meaning":"追赶；追捕；追求","definition":"to follow in order to catch or obtain something","examples":[{"en":"The dog chased a ball across the grass.","zh":"狗追着球跑过草地。"},{"en":"The company is chasing new business overseas.","zh":"这家公司正在海外争取新业务。"}]},{"pos":"v.","meaning":"在金属上雕镂","definition":"to decorate metal by cutting or pressing a design","examples":[{"en":"The silversmith chased a floral pattern into the bowl.","zh":"银匠在碗上雕出了花卉图案。"},{"en":"Fine lines were chased into the surface of the plate.","zh":"盘子表面被雕上了细线纹样。"}]}],"cheat":[{"pos":"v.","meaning":"欺骗；作弊","definition":"to act dishonestly to gain an advantage","examples":[{"en":"Students who cheat will face disciplinary action.","zh":"作弊的学生将受到纪律处分。"},{"en":"The seller tried to cheat him out of his deposit.","zh":"卖家试图骗走他的定金。"}]},{"pos":"n.","meaning":"骗子；作弊者","definition":"a person who acts dishonestly","examples":[{"en":"The referee warned the cheat.","zh":"裁判警告了那个作弊者。"},{"en":"No one wants to do business with a cheat.","zh":"没有人愿意与骗子做生意。"}]},{"pos":"n.","meaning":"骗局；欺骗手段","definition":"a dishonest trick or act","examples":[{"en":"The offer was a cheat: there was no prize.","zh":"那项优惠是个骗局，根本没有奖品。"},{"en":"Selling empty boxes as genuine products was a blatant cheat.","zh":"把空盒子当成真品出售是赤裸裸的欺骗。"}]}],"check":[{"pos":"v.","meaning":"检查；核对","definition":"to examine something for accuracy or condition","examples":[{"en":"Please check the dates before booking.","zh":"预订前请核对日期。"},{"en":"The engineer checked the wiring.","zh":"工程师检查了线路。"}]},{"pos":"v.","meaning":"阻止；抑制","definition":"to stop or slow the progress of something","examples":[{"en":"The barrier helped check the spread of the fire.","zh":"屏障有助于阻止火势蔓延。"},{"en":"He struggled to check his impatience.","zh":"他努力克制自己的不耐烦。"}]},{"pos":"n.","meaning":"检查；核对","definition":"an examination to confirm accuracy or condition","examples":[{"en":"The equipment needs a safety check.","zh":"设备需要安全检查。"},{"en":"We carried out a final check before leaving.","zh":"离开前我们做了最后一次检查。"}]},{"pos":"n.","meaning":"制约；抑制","definition":"something that limits or controls another thing","examples":[{"en":"The system provides a check on excessive spending.","zh":"制度对过度开支起到制约作用。"},{"en":"Public scrutiny acts as a check on power.","zh":"公众监督是对权力的制约。"}]},{"pos":"n.","meaning":"支票（美式）","definition":"a written order instructing a bank to pay money","examples":[{"en":"She paid by check.","zh":"她用支票付款。"},{"en":"He wrote a check for the rent.","zh":"他写了一张支付租金的支票。"}]},{"pos":"n.","meaning":"餐馆账单（美式）","definition":"a restaurant bill","examples":[{"en":"We asked the waiter for the check.","zh":"我们请服务员拿来账单。"},{"en":"The check included a service charge.","zh":"账单包含了服务费。"}]}],"check-up":[{"pos":"n.","meaning":"检查；体检","definition":"a routine examination to assess health or condition","examples":[{"en":"I booked a dental check-up for next week.","zh":"我预约了下周的牙科检查。"},{"en":"The machine receives a safety check-up every month.","zh":"这台机器每月接受一次安全检查。"}]}],"chef":[{"pos":"n.","meaning":"厨师；主厨","definition":"a professional cook, especially one in charge of a kitchen","examples":[{"en":"The chef prepared a vegetarian menu.","zh":"厨师准备了一份素食菜单。"},{"en":"She trained as a chef in a busy restaurant.","zh":"她在一家繁忙的餐厅接受厨师培训。"}]}],"chemical":[{"pos":"adj.","meaning":"化学的","definition":"relating to chemistry or changes in substances","examples":[{"en":"The process involves a chemical reaction.","zh":"这一过程涉及化学反应。"},{"en":"The factory stores chemical materials securely.","zh":"工厂妥善存放化学材料。"}]},{"pos":"n.","meaning":"化学品；化学物质","definition":"a substance with a particular chemical composition","examples":[{"en":"Each chemical is labelled clearly.","zh":"每种化学品都标有清晰标签。"},{"en":"The laboratory tests water for harmful chemicals.","zh":"实验室检测水中的有害化学物质。"}]}],"cherry":[{"pos":"n.","meaning":"樱桃；樱桃树","definition":"a small red fruit or the tree producing it","examples":[{"en":"She placed a cherry on top of the cake.","zh":"她在蛋糕上放了一颗樱桃。"},{"en":"The cherry tree beside the gate flowers in spring.","zh":"门旁的樱桃树春天开花。"}]}],"chest":[{"pos":"n.","meaning":"胸部；胸膛","definition":"the front part of the body between the neck and stomach","examples":[{"en":"He held the parcel against his chest.","zh":"他把包裹抱在胸前。"},{"en":"The doctor examined her chest.","zh":"医生检查了她的胸部。"}]},{"pos":"n.","meaning":"箱子；柜子；资金储备","definition":"a large strong box, or a reserve of money","examples":[{"en":"The letters were kept in a wooden chest.","zh":"信件保存在一个木箱里。"},{"en":"The party built up a campaign war chest.","zh":"该党积累了一笔竞选资金。"}]}],"chew":[{"pos":"v.","meaning":"咀嚼","definition":"to crush food with the teeth before swallowing","examples":[{"en":"Chew your food slowly.","zh":"慢慢咀嚼食物。"},{"en":"The dog chewed a piece of dry food.","zh":"狗嚼了一块干粮。"}]},{"pos":"v.","meaning":"仔细考虑；反复思考（常与 over 连用）","definition":"to think about a matter carefully","examples":[{"en":"I need time to chew over the offer.","zh":"我需要时间仔细考虑这个提议。"},{"en":"They chewed over the problem during lunch.","zh":"他们在午餐时反复讨论这个问题。"}]}],"chief":[{"pos":"adj.","meaning":"主要的；首要的","definition":"most important or highest in rank","examples":[{"en":"The chief reason for the move was lower rent.","zh":"搬迁的主要原因是租金更低。"},{"en":"She was appointed chief engineer of the project.","zh":"她被任命为项目总工程师。"}]}],"chill":[{"pos":"v.","meaning":"使变冷；冷藏","definition":"to make something cold","examples":[{"en":"Chill the juice before serving.","zh":"饮用前先把果汁冷藏。"},{"en":"The evening wind chilled our hands.","zh":"晚风把我们的双手吹冷了。"}]},{"pos":"n.","meaning":"寒冷；寒意；寒战","definition":"an unpleasant feeling of cold","examples":[{"en":"There was a chill in the morning air.","zh":"清晨空气中带着寒意。"},{"en":"He felt a sudden chill and reached for his coat.","zh":"他突然感到一阵寒冷，伸手去拿外套。"}]},{"pos":"n.","meaning":"恐惧或不安的感觉","definition":"a sudden feeling of fear or unease","examples":[{"en":"The empty house gave her a chill.","zh":"空房子让她感到一阵寒意。"},{"en":"His warning sent a chill through the room.","zh":"他的警告使屋内的人都感到不安。"}]},{"pos":"adj.","meaning":"寒冷的；冷淡的","definition":"cold in temperature or manner","examples":[{"en":"A chill wind blew across the lake.","zh":"一阵寒风吹过湖面。"},{"en":"Her suggestion received a chill response.","zh":"她的建议得到了冷淡的回应。"}]}],"chink":[{"pos":"n.","meaning":"裂缝；缝隙","definition":"a small narrow opening","examples":[{"en":"Light entered through a chink in the curtain.","zh":"光线从窗帘缝隙透进来。"},{"en":"The cold air found a chink in the wall.","zh":"冷空气从墙上的缝隙钻了进来。"}]},{"pos":"n.","meaning":"一丝；一线","definition":"a small amount of light or opportunity","examples":[{"en":"A chink of sunlight reached the floor.","zh":"一线阳光照到了地板上。"},{"en":"The new evidence offered a chink of hope.","zh":"新证据带来了一线希望。"}]},{"pos":"n.","meaning":"叮当声","definition":"a light ringing sound made by small hard objects","examples":[{"en":"We heard the chink of glasses.","zh":"我们听到玻璃杯相碰的叮当声。"},{"en":"The chink of coins came from his pocket.","zh":"他的口袋里传来硬币的叮当声。"}]},{"pos":"v.","meaning":"发出叮当声","definition":"to make a light ringing sound","examples":[{"en":"The glasses chinked as they toasted.","zh":"他们举杯祝酒时，杯子叮当相碰。"},{"en":"Keys chinked against the metal rail.","zh":"钥匙碰到金属栏杆，发出叮当声。"}]}],"chip":[{"pos":"n.","meaning":"碎片；缺口","definition":"a small piece broken off or the place left by it","examples":[{"en":"A chip of stone fell from the wall.","zh":"一小块石头从墙上掉落。"},{"en":"There is a chip in the rim of the bowl.","zh":"碗沿有一个缺口。"}]},{"pos":"n.","meaning":"芯片","definition":"a small electronic component containing circuits","examples":[{"en":"The chip processes signals from the sensor.","zh":"这块芯片处理来自传感器的信号。"},{"en":"A new chip reduced the device's power use.","zh":"一款新芯片降低了设备的耗电量。"}]},{"pos":"v.","meaning":"削下；凿下；使缺损","definition":"to remove small pieces from a hard surface","examples":[{"en":"Workers chipped away the damaged plaster.","zh":"工人们凿掉了损坏的灰泥。"},{"en":"Be careful not to chip the glass edge.","zh":"小心不要把玻璃边缘碰缺。"}]}],"cholesterol":[{"pos":"n.","meaning":"胆固醇","definition":"a fatty substance present in the body and some foods","examples":[{"en":"The test measured cholesterol in his blood.","zh":"这项检测测量了他血液中的胆固醇。"},{"en":"She asked the clinician to explain her cholesterol results.","zh":"她请医生解释胆固醇检查结果。"}]}],"chorus":[{"pos":"n.","meaning":"合唱队；合唱","definition":"a group singing together or their singing","examples":[{"en":"The school chorus performed at the ceremony.","zh":"学校合唱队在典礼上演出。"},{"en":"The song ends with a powerful chorus.","zh":"歌曲以有力的合唱结束。"}]},{"pos":"n.","meaning":"副歌；叠句","definition":"the repeated section of a song","examples":[{"en":"Everyone joined in during the chorus.","zh":"副歌响起时，所有人都跟着唱。"},{"en":"The chorus is easier to remember than the verses.","zh":"副歌比主歌更容易记住。"}]},{"pos":"n.","meaning":"齐声；一致的表达","definition":"many voices expressing the same thing","examples":[{"en":"The plan met a chorus of criticism.","zh":"计划遭到一片批评声。"},{"en":"A chorus of cheers greeted the players.","zh":"一片欢呼声迎接球员们。"}]},{"pos":"v.","meaning":"齐声说；齐声唱","definition":"to say or sing together","examples":[{"en":"The children chorused their answer.","zh":"孩子们齐声回答。"},{"en":"They chorused a welcome as she entered.","zh":"她进来时，大家齐声欢迎。"}]}],"chronic":[{"pos":"adj.","meaning":"慢性的；长期持续的","definition":"lasting for a long time or recurring","examples":[{"en":"The clinic specializes in chronic pain.","zh":"这家诊所专门诊治慢性疼痛。"},{"en":"The region faces a chronic shortage of affordable housing.","zh":"这个地区长期缺乏价格可负担的住房。"}]},{"pos":"adj.","meaning":"积习难改的","definition":"persistently displaying an undesirable habit","examples":[{"en":"He is a chronic latecomer to morning meetings.","zh":"他参加早会总是迟到，积习难改。"},{"en":"A chronic worrier may find uncertainty especially difficult.","zh":"习惯性忧虑的人可能尤其难以面对不确定性。"}]}],"chunk":[{"pos":"n.","meaning":"大块；相当大的部分","definition":"a thick piece or a substantial part of something","examples":[{"en":"He cut a chunk of bread for each guest.","zh":"他给每位客人切了一大块面包。"},{"en":"Rent takes a large chunk of her income.","zh":"房租占了她收入的很大一部分。"}]}],"churn":[{"pos":"n.","meaning":"搅乳器","definition":"a container or device used to make butter","examples":[{"en":"The old churn stands in the dairy museum.","zh":"旧搅乳器陈列在乳业博物馆。"},{"en":"Milk was poured into the churn.","zh":"牛奶被倒进搅乳器。"}]},{"pos":"v.","meaning":"搅乳；搅制黄油","definition":"to stir cream until it becomes butter","examples":[{"en":"They churned the cream by hand.","zh":"他们用手工搅打奶油制作黄油。"},{"en":"The machine churns butter in large quantities.","zh":"机器大量搅制黄油。"}]},{"pos":"v.","meaning":"猛烈搅动；翻滚","definition":"to move or stir violently","examples":[{"en":"The boat's propeller churned the water.","zh":"船的螺旋桨猛烈搅动水面。"},{"en":"Dark waves churned below the cliff.","zh":"暗色海浪在悬崖下翻滚。"}]},{"pos":"v.","meaning":"反胃；翻腾","definition":"to feel an unpleasant movement in the stomach","examples":[{"en":"Her stomach churned with nerves.","zh":"她紧张得胃里翻腾。"},{"en":"The rough journey left his stomach churning.","zh":"颠簸的旅程使他胃里一阵翻腾。"}]}],"cinematography":[{"pos":"n.","meaning":"电影摄影术","definition":"the art and technique of recording moving images for films","examples":[{"en":"The film won praise for its cinematography.","zh":"这部电影的摄影受到赞扬。"},{"en":"She studied cinematography before directing her first film.","zh":"她导演第一部电影前学习了电影摄影。"}]}],"circle":[{"pos":"n.","meaning":"圆；圆圈；环状物","definition":"a round shape or arrangement","examples":[{"en":"Draw a circle around the correct answer.","zh":"在正确答案周围画一个圆圈。"},{"en":"The children sat in a circle.","zh":"孩子们围坐成一圈。"}]},{"pos":"n.","meaning":"圈子；群体","definition":"a group of people connected socially or professionally","examples":[{"en":"She has a wide circle of friends.","zh":"她交友广泛。"},{"en":"The idea is popular in scientific circles.","zh":"这一想法在科学界很受欢迎。"}]},{"pos":"n.","meaning":"循环；周而复始的过程","definition":"a sequence that returns to its starting point","examples":[{"en":"The story has come full circle.","zh":"这个故事又回到了起点。"},{"en":"Poor health and poverty can form a vicious circle.","zh":"健康状况差与贫困可能形成恶性循环。"}]},{"pos":"v.","meaning":"围绕移动；盘旋；圈出","definition":"to move around something or draw a ring around it","examples":[{"en":"Birds began to circle above the field.","zh":"鸟儿开始在田野上方盘旋。"},{"en":"Circle the date on your calendar.","zh":"把日期在日历上圈出来。"}]}],"circulation":[{"pos":"n.","meaning":"循环；流通","definition":"continuous movement of blood, air, or another substance","examples":[{"en":"Walking helps keep the circulation active.","zh":"步行有助于保持血液循环活跃。"},{"en":"Open windows improve air circulation.","zh":"打开窗户能改善空气流通。"}]},{"pos":"n.","meaning":"传播；流传","definition":"the movement of information or items among people","examples":[{"en":"The document is for internal circulation only.","zh":"文件仅供内部传阅。"},{"en":"The old coins are no longer in circulation.","zh":"这些旧硬币已不再流通。"}]},{"pos":"n.","meaning":"发行；发行量","definition":"the distribution or number of copies of a publication","examples":[{"en":"The magazine has a circulation of fifty thousand.","zh":"这本杂志的发行量是五万份。"},{"en":"Online news has affected newspaper circulation.","zh":"网络新闻影响了报纸发行量。"}]}],"circumscribe":[{"pos":"v.","meaning":"限制；划定界限","definition":"to restrict something within limits","examples":[{"en":"The agreement circumscribes the committee's powers.","zh":"协议限制了委员会的权力。"},{"en":"Lack of funding circumscribed the scope of the research.","zh":"资金不足限制了研究范围。"}]},{"pos":"v.","meaning":"画外接线；围绕画线","definition":"to draw a figure around another so that they touch","examples":[{"en":"Draw a circle that circumscribes the triangle.","zh":"画一个这个三角形的外接圆。"},{"en":"The students circumscribed a square around the small circle.","zh":"学生们围绕小圆画了一个外切正方形。"}]}],"circumstance":[{"pos":"n.","meaning":"情况；条件；境况","definition":"a fact or condition affecting a situation","examples":[{"en":"The decision depends on the particular circumstance.","zh":"这一决定取决于具体情况。"},{"en":"Their financial circumstances have improved.","zh":"他们的经济状况已有改善。"}]}],"circus":[{"pos":"n.","meaning":"马戏团；马戏表演","definition":"a travelling group giving acrobatic and other performances","examples":[{"en":"The circus arrived in town yesterday.","zh":"马戏团昨天来到镇上。"},{"en":"The children enjoyed the circus performance.","zh":"孩子们喜欢这场马戏表演。"}]},{"pos":"n.","meaning":"环形广场；圆形交叉口（英式）","definition":"a circular open area where roads meet","examples":[{"en":"Several streets lead into the circus.","zh":"几条街道通向这个环形广场。"},{"en":"The café stands near a busy circus.","zh":"咖啡馆位于繁忙的环形广场附近。"}]}],"cite":[{"pos":"v.","meaning":"引用；援引","definition":"to mention a source or example as evidence","examples":[{"en":"Always cite the source of a quotation.","zh":"引用时一定要注明来源。"},{"en":"The report cites three studies supporting the proposal.","zh":"报告援引了三项支持这项提议的研究。"}]}],"civil":[{"pos":"adj.","meaning":"公民的；民用的；非军事的","definition":"relating to ordinary citizens rather than the military","examples":[{"en":"The organisation campaigns for civil rights.","zh":"这个组织致力于争取公民权利。"},{"en":"The airport serves both civil and military aircraft.","zh":"机场同时为民用和军用飞机提供服务。"}]},{"pos":"adj.","meaning":"政府行政的；民事的","definition":"relating to public administration or private legal disputes","examples":[{"en":"She works in the civil service.","zh":"她在政府行政部门工作。"},{"en":"The dispute became a civil case.","zh":"这起纠纷成了民事案件。"}]}],"civilization":[{"pos":"n.","meaning":"文明；文明社会","definition":"an organised human society with developed institutions and culture","examples":[{"en":"The exhibition explores an ancient civilization.","zh":"展览探索一个古代文明。"},{"en":"Writing played an important role in the development of civilization.","zh":"文字在文明发展中起了重要作用。"}]}],"claim":[{"pos":"v.","meaning":"声称；断言","definition":"to state that something is true","examples":[{"en":"The supplier claims that the battery lasts longer.","zh":"供应商声称这款电池更耐用。"},{"en":"She claimed to have seen the missing document.","zh":"她声称见过丢失的文件。"}]},{"pos":"v.","meaning":"要求；认领；索赔","definition":"to demand something believed to be due","examples":[{"en":"Passengers can claim compensation for the cancellation.","zh":"乘客可以因取消行程申请赔偿。"},{"en":"Nobody came forward to claim the lost bag.","zh":"没有人出面认领丢失的包。"}]},{"pos":"n.","meaning":"主张；断言","definition":"a statement presented as true","examples":[{"en":"The evidence does not support that claim.","zh":"证据不支持那个说法。"},{"en":"The advertisement makes a bold claim about the product.","zh":"这则广告对产品作出了大胆的宣称。"}]},{"pos":"n.","meaning":"要求；索赔","definition":"a formal demand for money or something owed","examples":[{"en":"The company rejected her insurance claim.","zh":"公司拒绝了她的保险索赔。"},{"en":"Several people made a claim to the land.","zh":"几个人声称对这片土地拥有权利。"}]}],"clamp":[{"pos":"n.","meaning":"夹具；夹钳","definition":"a device that holds things tightly together","examples":[{"en":"Use a clamp to hold the pieces in place.","zh":"用夹具把这些部件固定住。"},{"en":"The clamp keeps the pipe from moving.","zh":"夹钳使管子不再移动。"}]},{"pos":"v.","meaning":"夹紧；固定","definition":"to hold something tightly with a clamp","examples":[{"en":"Clamp the wood before drilling.","zh":"钻孔前先夹紧木头。"},{"en":"He clamped the lamp to the edge of the desk.","zh":"他把灯夹在了桌边。"}]}],"clarify":[{"pos":"v.","meaning":"澄清；说明清楚","definition":"to make something easier to understand","examples":[{"en":"Could you clarify what the fee includes?","zh":"你能说明费用包含哪些项目吗？"},{"en":"The manager called to clarify the new procedure.","zh":"经理打电话来说明新流程。"},{"en":"Please clarify whether attendance is compulsory.","zh":"请明确出席是否为强制要求。"}]}],"clarity":[{"pos":"n.","meaning":"清晰；清楚","definition":"the quality of being easy to see, hear, or understand","examples":[{"en":"The diagrams improved the clarity of the explanation.","zh":"这些图表让解释更清楚了。"},{"en":"The recording captured her voice with remarkable clarity.","zh":"录音非常清晰地记录了她的声音。"}]}],"clash":[{"pos":"v.","meaning":"冲突；发生争执","definition":"to disagree strongly or come into conflict","examples":[{"en":"The two leaders clash over education policy.","zh":"两位领导人在教育政策上发生冲突。"},{"en":"The demonstration clashed with a rival march.","zh":"这场示威与对立方的游行发生冲突。"}]},{"pos":"v.","meaning":"不协调；时间冲突","definition":"to look unsuitable together or happen at incompatible times","examples":[{"en":"The bright curtains clash with the carpet.","zh":"鲜艳的窗帘与地毯不协调。"},{"en":"The exam dates clash with her work schedule.","zh":"考试日期与她的工作安排冲突。"}]},{"pos":"v.","meaning":"碰撞并发出刺耳声","definition":"to strike together with a loud harsh sound","examples":[{"en":"The swords clashed in the performance.","zh":"表演中的刀剑相碰，发出铿锵声。"},{"en":"Metal trays clashed together in the kitchen.","zh":"厨房里的金属托盘碰在一起，发出刺耳声。"}]},{"pos":"n.","meaning":"冲突；争执","definition":"a serious disagreement or confrontation","examples":[{"en":"The clash between the two groups delayed the meeting.","zh":"两组之间的冲突推迟了会议。"},{"en":"There was a clash of opinions about the budget.","zh":"人们在预算问题上发生了意见冲突。"}]},{"pos":"n.","meaning":"不协调；时间冲突","definition":"a mismatch or conflict in timing","examples":[{"en":"The clash of colours made the room uncomfortable.","zh":"颜色的不协调让房间显得不舒适。"},{"en":"A timetable clash prevented him from attending both classes.","zh":"课表冲突使他无法同时参加两门课。"}]},{"pos":"n.","meaning":"刺耳的撞击声","definition":"a loud harsh sound from things striking together","examples":[{"en":"A clash of metal came from the workshop.","zh":"车间传来一阵金属撞击声。"},{"en":"The clash of cymbals marked the end of the piece.","zh":"钹的撞击声标志着乐曲结束。"}]}],"classical":[{"pos":"adj.","meaning":"古典的；古希腊罗马的","definition":"relating to ancient Greek and Roman culture","examples":[{"en":"The building uses classical columns.","zh":"这座建筑使用古典柱式。"},{"en":"She studies classical literature at university.","zh":"她在大学学习古典文学。"}]},{"pos":"adj.","meaning":"古典音乐的","definition":"relating to the established tradition of formal art music","examples":[{"en":"The station broadcasts classical music.","zh":"电台播放古典音乐。"},{"en":"He prefers classical concerts to pop festivals.","zh":"相比流行音乐节，他更喜欢古典音乐会。"}]},{"pos":"adj.","meaning":"传统的；经典的","definition":"following established principles or a recognised standard model","examples":[{"en":"The course introduces classical mechanics.","zh":"课程介绍经典力学。"},{"en":"The argument follows a classical pattern.","zh":"这个论证遵循传统模式。"}]}],"classification":[{"pos":"n.","meaning":"分类；类别；级别","definition":"the arrangement of things into groups or a group assigned","examples":[{"en":"The classification of species changes as evidence improves.","zh":"物种分类会随着证据完善而变化。"},{"en":"This document has a confidential classification.","zh":"这份文件被列为机密级别。"}]}],"classify":[{"pos":"v.","meaning":"分类；分级","definition":"to arrange things into groups according to shared features","examples":[{"en":"The researchers classify the plants by leaf shape.","zh":"研究人员按叶形给植物分类。"},{"en":"The library classifies books by subject.","zh":"图书馆按主题对书籍分类。"}]}],"clay":[{"pos":"n.","meaning":"黏土；陶土","definition":"a fine earth material that can be shaped when wet","examples":[{"en":"The potter shaped the wet clay.","zh":"陶工塑造湿陶土。"},{"en":"Clay soil holds water for a long time.","zh":"黏土能长时间保水。"}]}],"clench":[{"pos":"v.","meaning":"握紧；咬紧；紧紧抓住","definition":"to close or hold something very tightly","examples":[{"en":"He clenched his fists but remained silent.","zh":"他握紧拳头，却保持沉默。"},{"en":"She clenched her teeth during the difficult climb.","zh":"艰难攀登时，她咬紧牙关。"}]}],"clerk":[{"pos":"n.","meaning":"职员；办事员","definition":"a person who handles records, accounts, or routine office work","examples":[{"en":"The clerk checked the application form.","zh":"办事员检查了申请表。"},{"en":"A bank clerk explained the charges.","zh":"银行职员解释了各项费用。"}]}],"client":[{"pos":"n.","meaning":"客户；委托人","definition":"a person or organisation receiving a professional service","examples":[{"en":"The architect met the client to discuss the plans.","zh":"建筑师与客户见面讨论设计。"},{"en":"The lawyer keeps each client's information private.","zh":"律师对每位委托人的信息保密。"}]}],"clientele":[{"pos":"n.","meaning":"顾客群；客户群","definition":"the customers of a business or professional","examples":[{"en":"The café attracts a varied clientele.","zh":"这家咖啡馆吸引着不同类型的顾客。"},{"en":"The lawyer built a loyal clientele over many years.","zh":"这位律师多年来积累了一群忠实客户。"}]}],"climate":[{"pos":"n.","meaning":"气候","definition":"the usual weather conditions of a place","examples":[{"en":"The island has a mild climate.","zh":"这座岛的气候温和。"},{"en":"Changes in climate affect farming patterns.","zh":"气候变化影响农业种植模式。"}]},{"pos":"n.","meaning":"氛围；风气；环境","definition":"the general mood or conditions affecting an activity","examples":[{"en":"The policy created a climate of uncertainty.","zh":"这项政策造成了不确定的氛围。"},{"en":"A supportive climate helps students ask questions.","zh":"支持性的环境有助于学生提问。"}]}],"climatic":[{"pos":"adj.","meaning":"气候的","definition":"relating to climate","examples":[{"en":"The plants suit the local climatic conditions.","zh":"这些植物适应当地气候条件。"},{"en":"The study examines long-term climatic changes.","zh":"研究考察长期气候变化。"}]}],"clinic":[{"pos":"n.","meaning":"诊所；门诊部","definition":"a place providing medical consultation or treatment","examples":[{"en":"The clinic opens early for working patients.","zh":"这家诊所很早开门，方便上班的患者。"},{"en":"She made an appointment at the eye clinic.","zh":"她预约了眼科门诊。"}]}],"clinical":[{"pos":"adj.","meaning":"临床的","definition":"relating to examining and treating patients","examples":[{"en":"The course combines laboratory work with clinical training.","zh":"这门课程结合了实验室工作与临床培训。"},{"en":"The drug is undergoing clinical trials.","zh":"这种药物正在进行临床试验。"}]},{"pos":"adj.","meaning":"冷静客观的；不感情用事的","definition":"detached, precise, and unemotional","examples":[{"en":"She gave a clinical account of the accident.","zh":"她冷静客观地叙述了事故经过。"},{"en":"The report takes a clinical approach to the evidence.","zh":"这份报告以客观冷静的方式分析证据。"}]},{"pos":"adj.","meaning":"冷清简洁的；缺乏温馨感的","definition":"plain, very clean, and lacking warmth","examples":[{"en":"The room looked clinical with its bare white walls.","zh":"房间四壁洁白空荡，显得冷清。"},{"en":"A rug softened the office's clinical appearance.","zh":"一块地毯缓和了办公室冷冰冰的外观。"}]}],"clip":[{"pos":"n.","meaning":"夹子；回形针","definition":"a small device used to hold things together","examples":[{"en":"Use a clip to keep the papers together.","zh":"用夹子把文件夹在一起。"},{"en":"She fastened her hair with a clip.","zh":"她用发夹固定头发。"}]},{"pos":"n.","meaning":"弹夹","definition":"a device holding cartridges together for loading","examples":[{"en":"The museum label describes the empty ammunition clip.","zh":"博物馆标签介绍了这个空弹夹。"},{"en":"The historical display includes a metal clip.","zh":"历史展览包括一个金属弹夹。"}]},{"pos":"n.","meaning":"剪辑片段；摘录","definition":"a short section of a film, recording, or text","examples":[{"en":"The teacher played a short video clip.","zh":"老师播放了一段短视频。"},{"en":"We watched a clip from the documentary.","zh":"我们看了一段纪录片片段。"}]},{"pos":"n.","meaning":"修剪","definition":"an act of cutting a small amount off something","examples":[{"en":"The hedge needs a quick clip.","zh":"树篱需要稍作修剪。"},{"en":"He gave the dog's fur a careful clip.","zh":"他仔细修剪了狗的毛。"}]},{"pos":"v.","meaning":"夹住；扣住","definition":"to fasten with a clip","examples":[{"en":"Clip the microphone to your jacket.","zh":"把麦克风夹在夹克上。"},{"en":"She clipped the notes together.","zh":"她把笔记夹在一起。"}]},{"pos":"v.","meaning":"剪；修剪","definition":"to cut off small amounts or cut out a piece","examples":[{"en":"They clipped the hedge into a neat shape.","zh":"他们把树篱修剪成整齐的形状。"},{"en":"She clipped the article from the newspaper.","zh":"她从报纸上剪下那篇文章。"}]}],"cloakroom":[{"pos":"n.","meaning":"衣帽间","definition":"a room where coats and bags can be left","examples":[{"en":"Leave your coat in the cloakroom before entering.","zh":"进入前请把外套放在衣帽间。"},{"en":"The cloakroom attendant gave me a numbered ticket.","zh":"衣帽间工作人员给了我一张号码牌。"}]},{"pos":"n.","meaning":"洗手间（英式委婉用语）","definition":"a room containing a toilet","examples":[{"en":"There is a small cloakroom under the stairs.","zh":"楼梯下有一个小洗手间。"},{"en":"The guest cloakroom is beside the entrance hall.","zh":"客用洗手间在门厅旁边。"}]}],"clockwise":[{"pos":"adj.","meaning":"顺时针方向的","definition":"moving in the same direction as clock hands","examples":[{"en":"The handle requires a clockwise turn.","zh":"这个把手需要顺时针转动。"},{"en":"The diagram shows clockwise motion.","zh":"图示展示了顺时针运动。"}]},{"pos":"adv.","meaning":"顺时针地","definition":"in the same direction as clock hands","examples":[{"en":"Turn the dial clockwise.","zh":"顺时针转动旋钮。"},{"en":"The wheel rotates clockwise when viewed from the front.","zh":"从正面看，轮子顺时针旋转。"}]}],"clot":[{"pos":"n.","meaning":"血块；凝块","definition":"a thick mass formed when liquid solidifies","examples":[{"en":"The test identified a blood clot.","zh":"检查发现了血凝块。"},{"en":"A clot formed in the sample.","zh":"样本中形成了凝块。"}]},{"pos":"v.","meaning":"凝结成块","definition":"to form a thick or solid mass","examples":[{"en":"Blood begins to clot after an injury.","zh":"受伤后，血液开始凝结。"},{"en":"The sample clotted before it could be examined.","zh":"样本在检查前就凝固了。"}]}],"clue":[{"pos":"n.","meaning":"线索；提示","definition":"information that helps solve a problem","examples":[{"en":"The footprint provided a clue to the animal's identity.","zh":"脚印为辨认动物提供了线索。"},{"en":"The teacher gave us a clue without revealing the answer.","zh":"老师给了我们提示，却没有透露答案。"}]}],"clumsy":[{"pos":"adj.","meaning":"笨拙的；动作不灵活的","definition":"moving awkwardly and often dropping or damaging things","examples":[{"en":"His clumsy movements knocked the cup over.","zh":"他笨拙的动作打翻了杯子。"},{"en":"The gloves made her fingers feel clumsy.","zh":"手套让她的手指显得不灵活。"}]},{"pos":"adj.","meaning":"不得体的；拙劣的","definition":"awkwardly expressed or poorly handled","examples":[{"en":"His clumsy apology made matters worse.","zh":"他不得体的道歉让事情更糟。"},{"en":"The paragraph needs revision because the wording is clumsy.","zh":"这段文字措辞生硬，需要修改。"}]}],"cluster":[{"pos":"n.","meaning":"簇；群；串","definition":"a group of similar things close together","examples":[{"en":"A cluster of houses stood beside the river.","zh":"河边聚着一簇房屋。"},{"en":"The telescope revealed a cluster of stars.","zh":"望远镜显现出一群恒星。"}]},{"pos":"v.","meaning":"聚集；成群","definition":"to gather closely together","examples":[{"en":"Visitors clustered around the guide.","zh":"游客聚集在导游周围。"},{"en":"Small shops cluster near the station.","zh":"小商店聚集在车站附近。"}]}],"clutch":[{"pos":"n.","meaning":"离合器","definition":"a mechanism connecting or disconnecting an engine and transmission","examples":[{"en":"Press the clutch before changing gear.","zh":"换挡前先踩离合器。"},{"en":"The mechanic replaced the worn clutch.","zh":"技工更换了磨损的离合器。"}]},{"pos":"n.","meaning":"控制；掌握（常用复数 clutches）","definition":"power over someone or something","examples":[{"en":"The rescued bird escaped the cat's clutches.","zh":"获救的小鸟逃出了猫的爪子。"},{"en":"She wanted to escape the clutches of the dishonest lender.","zh":"她想摆脱那个不诚实放贷人的控制。"}]},{"pos":"v.","meaning":"紧抓；抓住","definition":"to hold tightly or try to seize something","examples":[{"en":"The child clutched his mother's hand.","zh":"孩子紧紧抓住母亲的手。"},{"en":"She clutched at the railing as the boat moved.","zh":"船晃动时，她伸手抓住栏杆。"}]}],"coach":[{"pos":"n.","meaning":"教练；指导者","definition":"someone who trains people in a sport or skill","examples":[{"en":"The coach planned a new training routine.","zh":"教练制定了新的训练安排。"},{"en":"A language coach helped her prepare for the interview.","zh":"一位语言指导老师帮助她准备面试。"}]},{"pos":"n.","meaning":"长途客车","definition":"a comfortable bus used for longer journeys","examples":[{"en":"We travelled to the coast by coach.","zh":"我们乘长途客车去了海边。"},{"en":"The coach leaves from bay six.","zh":"这班长途客车从六号车位发车。"}]},{"pos":"v.","meaning":"训练；辅导","definition":"to train or teach someone in a skill","examples":[{"en":"She coaches the junior swimming team.","zh":"她训练少年游泳队。"},{"en":"He offered to coach me for the oral examination.","zh":"他提出辅导我准备口试。"}]}],"coarse":[{"pos":"adj.","meaning":"粗的；粗糙的","definition":"having a rough texture or large particles","examples":[{"en":"The sack is made of coarse fabric.","zh":"袋子用粗布制成。"},{"en":"Coarse sand covered the path.","zh":"粗沙铺满了小路。"}]},{"pos":"adj.","meaning":"粗劣的；粗俗的","definition":"lacking refinement or good manners","examples":[{"en":"His coarse language offended the guests.","zh":"他粗俗的语言冒犯了客人。"},{"en":"The performance relied on coarse humour.","zh":"表演依赖粗俗的幽默。"}]}],"code":[{"pos":"n.","meaning":"代码；密码","definition":"symbols used to represent information or conceal a message","examples":[{"en":"Enter the access code shown on your card.","zh":"输入卡片上显示的访问代码。"},{"en":"The message was written in a secret code.","zh":"这条信息是用秘密密码写的。"}]},{"pos":"v.","meaning":"编码","definition":"to convert information into a system of symbols","examples":[{"en":"Researchers coded the interviews by topic.","zh":"研究人员按主题给访谈内容编码。"},{"en":"The data must be coded before analysis.","zh":"这些数据必须先编码再分析。"}]}],"coexist":[{"pos":"v.","meaning":"共存","definition":"to exist together at the same time or place","examples":[{"en":"Several languages coexist in this city.","zh":"几种语言在这座城市中并存。"},{"en":"Industry and wildlife can coexist with careful planning.","zh":"通过周密规划，工业与野生动物可以共存。"}]}],"coffer":[{"pos":"n.","meaning":"钱箱；保险柜","definition":"a strong chest used to keep money or valuables","examples":[{"en":"The coins were stored in a wooden coffer.","zh":"硬币存放在一个木制钱箱中。"},{"en":"The museum displays a medieval coffer.","zh":"博物馆展出一个中世纪的钱箱。"}]},{"pos":"n.","meaning":"资金；财库（常用复数）","definition":"the money available to an organisation","examples":[{"en":"The repairs drained the council's coffers.","zh":"维修耗尽了市政资金。"},{"en":"Donations helped refill the charity's coffers.","zh":"捐款帮助补充了慈善机构的资金。"}]}],"cognition":[{"pos":"n.","meaning":"认知；认识能力","definition":"mental processes involved in knowing and understanding","examples":[{"en":"The study examines links between sleep and cognition.","zh":"这项研究考察睡眠与认知之间的联系。"},{"en":"Language is one aspect of human cognition.","zh":"语言是人类认知的一个方面。"}]}],"coherence":[{"pos":"n.","meaning":"连贯性；条理性；一致性","definition":"the quality of ideas or parts fitting together in a clear and logical way","examples":[{"en":"Clear topic sentences improve the coherence of an essay.","zh":"清晰的主题句能改善文章的连贯性。"},{"en":"The report lacks coherence because its sections contradict one another.","zh":"这份报告各部分相互矛盾，因此缺乏一致性。"}]}],"coherent":[{"pos":"adj.","meaning":"连贯的；条理清楚的","definition":"clear, logically connected, and understandable","examples":[{"en":"The essay presents a coherent argument.","zh":"这篇文章提出了条理清楚的论证。"},{"en":"She gave a coherent explanation of the process.","zh":"她连贯地解释了整个过程。"}]},{"pos":"adj.","meaning":"协调一致的","definition":"working together as a unified whole","examples":[{"en":"The separate proposals form a coherent plan.","zh":"这些单独的提议构成了一项协调一致的计划。"},{"en":"The government needs a coherent transport policy.","zh":"政府需要一项相互协调的交通政策。"}]}],"cohesion":[{"pos":"n.","meaning":"团结；凝聚力；社会凝聚力","definition":"the strength that keeps a group united","examples":[{"en":"Shared public spaces can strengthen social cohesion.","zh":"共享公共空间可以增强社会凝聚力。"},{"en":"Inequality may weaken community cohesion.","zh":"不平等可能削弱社区凝聚力。"},{"en":"The project builds cohesion through cooperation.","zh":"该项目通过合作增强凝聚力。"}]},{"pos":"n.","meaning":"内聚力；凝聚（物理）","definition":"attraction that holds particles of the same substance together","examples":[{"en":"Cohesion helps water form rounded droplets.","zh":"内聚力使水容易形成圆形水滴。"},{"en":"The experiment compared cohesion in different liquids.","zh":"实验比较了不同液体的内聚力。"}]}],"coincide":[{"pos":"v.","meaning":"同时发生","definition":"to happen at the same time","examples":[{"en":"The festival coincides with the school holiday.","zh":"节日恰好与学校假期同时到来。"},{"en":"Their visits happened to coincide.","zh":"他们的来访恰好在同一时间。"}]},{"pos":"v.","meaning":"一致；相符","definition":"to agree or occupy the same position","examples":[{"en":"Our interests coincide on several important issues.","zh":"我们在几个重要问题上利益一致。"},{"en":"The two lines coincide on this part of the graph.","zh":"这两条线在图的这一部分重合。"}]}],"collaboration":[{"pos":"n.","meaning":"合作；协作","definition":"working together to achieve a shared aim","examples":[{"en":"The research involved close collaboration between universities.","zh":"这项研究涉及大学之间的密切合作。"},{"en":"The exhibition was produced in collaboration with local artists.","zh":"这次展览与当地艺术家合作举办。"}]},{"pos":"n.","meaning":"勾结；通敌","definition":"cooperation with an enemy or occupying force","examples":[{"en":"The inquiry examined allegations of collaboration with the occupying army.","zh":"调查审查了与占领军勾结的指控。"},{"en":"The novel explores the consequences of wartime collaboration.","zh":"这部小说探讨了战时通敌的后果。"}]}],"collapse":[{"pos":"v.","meaning":"坍塌；倒塌","definition":"to fall down suddenly","examples":[{"en":"The old roof collapsed during the storm.","zh":"旧屋顶在暴风雨中倒塌了。"},{"en":"The tent collapsed when a pole broke.","zh":"一根支柱断裂后，帐篷塌了。"}]},{"pos":"v.","meaning":"崩溃；失败","definition":"to fail completely or stop functioning","examples":[{"en":"The negotiations collapsed after several weeks.","zh":"谈判持续数周后破裂了。"},{"en":"The company collapsed under heavy debt.","zh":"公司因沉重债务而倒闭。"}]},{"pos":"v.","meaning":"晕倒；瘫倒","definition":"to fall down because of weakness or illness","examples":[{"en":"He collapsed from exhaustion after the race.","zh":"比赛后，他因筋疲力尽而瘫倒。"},{"en":"A passenger collapsed and staff called for help.","zh":"一名乘客晕倒，工作人员呼叫救援。"}]},{"pos":"n.","meaning":"倒塌；坍塌","definition":"the sudden falling down of a structure","examples":[{"en":"The collapse of the bridge blocked the road.","zh":"桥梁倒塌堵住了道路。"},{"en":"Engineers investigated the roof collapse.","zh":"工程师调查了屋顶坍塌事件。"}]},{"pos":"n.","meaning":"崩溃；失败","definition":"a complete failure of a system or arrangement","examples":[{"en":"The economic collapse led to job losses.","zh":"经济崩溃导致失业。"},{"en":"The collapse of the talks disappointed both sides.","zh":"谈判破裂令双方失望。"}]},{"pos":"n.","meaning":"虚脱；晕倒","definition":"a sudden loss of physical strength or consciousness","examples":[{"en":"The heat contributed to his collapse.","zh":"高温促成了他的虚脱。"},{"en":"After her collapse, the doctor examined her.","zh":"她晕倒后，医生为她进行了检查。"}]}],"collate":[{"pos":"v.","meaning":"核对；整理","definition":"to compare and arrange information or pages in order","examples":[{"en":"We collated the responses before writing the report.","zh":"写报告前，我们整理了回复。"},{"en":"The assistant collated the pages into complete sets.","zh":"助手把各页整理成了完整的文件套装。"}]}],"collateral":[{"pos":"adj.","meaning":"附带的；间接的","definition":"secondary or additional to the main thing","examples":[{"en":"The factory closure had collateral effects on local shops.","zh":"工厂关闭对当地商店产生了附带影响。"},{"en":"The assessment considers both direct and collateral costs.","zh":"评估同时考虑直接成本和间接成本。"}]},{"pos":"adj.","meaning":"并列的；旁系的","definition":"lying alongside or descending from a related family branch","examples":[{"en":"The genealogist traced the family's collateral branches.","zh":"族谱研究者追溯了这个家族的旁系分支。"},{"en":"The diagram shows collateral lines of descent.","zh":"图示展示了旁系血统关系。"}]}],"colleague":[{"pos":"n.","meaning":"同事","definition":"someone you work with","examples":[{"en":"A colleague helped me prepare the presentation.","zh":"一位同事帮助我准备了演示。"},{"en":"Please discuss the schedule with your colleague.","zh":"请与你的同事讨论日程。"},{"en":"My new colleague used to work in a hospital.","zh":"我的新同事曾在医院工作。"}]}],"collect":[{"pos":"v.","meaning":"收集；搜集","definition":"to gather things together","examples":[{"en":"The team collected samples from six rivers.","zh":"团队从六条河流采集了样本。"},{"en":"She collects postcards from places she visits.","zh":"她收集自己去过的地方的明信片。"}]},{"pos":"v.","meaning":"领取；接走；收取","definition":"to go and get something or receive money owed","examples":[{"en":"I will collect the tickets this afternoon.","zh":"我今天下午去取票。"},{"en":"The council collects a fee for bulky waste.","zh":"市政部门收取大件垃圾处理费。"}]},{"pos":"v.","meaning":"聚集；积累；集中","definition":"to come together or bring thoughts under control","examples":[{"en":"Rainwater collects in the hollow after a storm.","zh":"暴风雨后，雨水积在洼地里。"},{"en":"He paused to collect his thoughts before answering.","zh":"回答前，他停下来整理了一下思路。"}]}],"collection":[{"pos":"n.","meaning":"收集；收取","definition":"the act of gathering things or receiving money","examples":[{"en":"The collection of data took several months.","zh":"数据收集花了几个月。"},{"en":"Rubbish collection takes place on Tuesdays.","zh":"垃圾收运安排在星期二。"}]},{"pos":"n.","meaning":"收藏品；收集物","definition":"a group of objects gathered together","examples":[{"en":"The museum has a fine collection of ceramics.","zh":"博物馆收藏了一批精美的陶器。"},{"en":"Her collection of maps fills two shelves.","zh":"她收藏的地图占满了两个书架。"}]}],"college":[{"pos":"n.","meaning":"学院；高等专科学校；大学","definition":"an institution or part of a university that provides further or higher education","examples":[{"en":"She studies graphic design at a local college.","zh":"她在当地一所学院学习平面设计。"},{"en":"The college offers evening courses for working adults.","zh":"这所学院为在职成年人提供夜间课程。"}]}],"collision":[{"pos":"n.","meaning":"碰撞","definition":"an event in which moving objects hit each other","examples":[{"en":"The collision damaged both vehicles.","zh":"碰撞损坏了两辆车。"},{"en":"A collision with a rock stopped the boat.","zh":"船撞上岩石后停了下来。"}]},{"pos":"n.","meaning":"冲突；抵触","definition":"a clash between opposing ideas or interests","examples":[{"en":"The proposal caused a collision of interests.","zh":"提案引发了利益冲突。"},{"en":"The debate revealed a collision between tradition and innovation.","zh":"辩论显现了传统与创新之间的冲突。"}]}],"colony":[{"pos":"n.","meaning":"殖民地","definition":"a territory governed by another country","examples":[{"en":"The island was once a trading colony.","zh":"这座岛曾是一个贸易殖民地。"},{"en":"The exhibition traces the history of the former colony.","zh":"展览追溯了这个昔日殖民地的历史。"}]},{"pos":"n.","meaning":"群体；群落","definition":"a group of animals or organisms living together","examples":[{"en":"A colony of seabirds nests on the cliff.","zh":"一群海鸟在悬崖上筑巢。"},{"en":"The scientist examined a colony of bacteria.","zh":"科学家检查了一个细菌菌落。"}]}],"colossal":[{"pos":"adj.","meaning":"巨大的；庞大的","definition":"extremely large","examples":[{"en":"The project required a colossal amount of work.","zh":"这个项目需要完成极其庞大的工作量。"},{"en":"A colossal statue stood at the entrance.","zh":"入口处矗立着一座巨型雕像。"}]}],"colour-blind":[{"pos":"adj.","meaning":"色盲的；辨色能力异常的","definition":"unable to distinguish some colours normally","examples":[{"en":"The chart includes symbols for colour-blind users.","zh":"图表包含便于色盲使用者识别的符号。"},{"en":"A colour-blind person may find some maps difficult to read.","zh":"色盲人士可能觉得某些地图难以阅读。"}]}],"column":[{"pos":"n.","meaning":"柱；柱状物","definition":"a tall vertical support or formation","examples":[{"en":"Stone columns support the entrance roof.","zh":"石柱支撑着入口的屋顶。"},{"en":"A column of smoke rose above the trees.","zh":"一柱烟升到了树木上方。"}]},{"pos":"n.","meaning":"专栏；栏目","definition":"a regular section of a newspaper or page","examples":[{"en":"She writes a weekly column about urban wildlife.","zh":"她每周撰写关于城市野生动物的专栏。"},{"en":"The answer appears in the right-hand column.","zh":"答案出现在右侧一栏。"}]}],"comb":[{"pos":"n.","meaning":"梳子","definition":"a tool with teeth used to arrange hair","examples":[{"en":"She ran a comb through her hair.","zh":"她用梳子梳理头发。"},{"en":"I keep a small comb in my bag.","zh":"我在包里放了一把小梳子。"}]},{"pos":"n.","meaning":"蜂巢；蜂房结构","definition":"the wax structure in which bees store honey and raise young","examples":[{"en":"The beekeeper removed a frame of comb.","zh":"养蜂人取出了一框蜂巢。"},{"en":"The comb was heavy with honey.","zh":"蜂巢装满蜂蜜，很沉。"}]},{"pos":"n.","meaning":"鸡冠；肉冠","definition":"a fleshy crest on a bird's head","examples":[{"en":"The rooster had a bright red comb.","zh":"公鸡长着鲜红的鸡冠。"},{"en":"A healthy comb can help distinguish the bird in a photograph.","zh":"健康的鸡冠有助于在照片中辨认这只鸟。"}]},{"pos":"v.","meaning":"梳理","definition":"to arrange hair with a comb","examples":[{"en":"He stopped to comb his hair.","zh":"他停下来梳头。"},{"en":"Comb the dog's coat gently.","zh":"轻轻梳理狗的毛。"}]},{"pos":"v.","meaning":"仔细搜寻；彻底搜索","definition":"to search carefully through an area or material","examples":[{"en":"Volunteers comb the beach for litter.","zh":"志愿者仔细搜寻海滩上的垃圾。"},{"en":"Investigators combed the records for evidence.","zh":"调查人员仔细查阅记录寻找证据。"}]}],"combat":[{"pos":"n.","meaning":"战斗；搏斗","definition":"fighting, especially in war","examples":[{"en":"The soldiers were trained for combat.","zh":"士兵们接受了战斗训练。"},{"en":"The museum describes the conditions of naval combat.","zh":"博物馆介绍了海战环境。"}]},{"pos":"v.","meaning":"与……作战；抗击","definition":"to fight against an opponent","examples":[{"en":"The forces prepared to combat the advancing enemy.","zh":"部队准备抗击推进的敌军。"},{"en":"The defenders fought to combat the attack.","zh":"防守者奋力抗击进攻。"}]},{"pos":"v.","meaning":"遏制；防止；对抗","definition":"to take action against a problem","examples":[{"en":"The campaign aims to combat food waste.","zh":"运动旨在遏制食物浪费。"},{"en":"Better lighting can help combat accidents.","zh":"更好的照明有助于防止事故。"}]}],"combination":[{"pos":"n.","meaning":"结合；组合；混合体","definition":"a mixture or joining of different elements","examples":[{"en":"Success required a combination of skill and patience.","zh":"成功需要技巧与耐心的结合。"},{"en":"This combination of materials makes the frame lighter.","zh":"这种材料组合使框架更轻。"}]}],"combine":[{"pos":"v.","meaning":"结合；联合","definition":"to join things together or use them together","examples":[{"en":"The course combines theory with practice.","zh":"这门课程将理论与实践结合起来。"},{"en":"Several small farms combined to buy equipment.","zh":"几家小农场联合起来购买设备。"}]}],"combustion":[{"pos":"n.","meaning":"燃烧；燃烧过程","definition":"the process of burning a substance","examples":[{"en":"The experiment measures heat released during combustion.","zh":"实验测量燃烧过程中释放的热量。"},{"en":"An internal combustion engine burns fuel inside a cylinder.","zh":"内燃机在气缸内燃烧燃料。"}]}],"comedy":[{"pos":"n.","meaning":"喜剧","definition":"a work intended to make people laugh","examples":[{"en":"The theatre is staging a new comedy.","zh":"剧院正在上演一部新喜剧。"},{"en":"She prefers comedy to horror films.","zh":"与恐怖片相比，她更喜欢喜剧。"}]},{"pos":"n.","meaning":"喜剧性；滑稽场面","definition":"the humorous aspect of a situation","examples":[{"en":"There was unexpected comedy in their confused introductions.","zh":"他们混乱的自我介绍产生了意想不到的喜剧效果。"},{"en":"The writer finds comedy in ordinary family life.","zh":"这位作家从普通家庭生活中发掘喜剧性。"}]}],"comet":[{"pos":"n.","meaning":"彗星","definition":"a small object orbiting the Sun that may develop a bright tail","examples":[{"en":"The comet was visible before dawn.","zh":"黎明前可以看到那颗彗星。"},{"en":"Astronomers tracked the comet as it approached the Sun.","zh":"天文学家追踪了逐渐接近太阳的彗星。"}]}],"comic":[{"pos":"adj.","meaning":"滑稽的；喜剧的","definition":"funny or intended to make people laugh","examples":[{"en":"The actor has excellent comic timing.","zh":"演员对喜剧节奏把握得很好。"},{"en":"A comic misunderstanding drives the story.","zh":"一个滑稽的误会推动着故事。"}]},{"pos":"n.","meaning":"喜剧演员","definition":"a performer who tells jokes or acts humorously","examples":[{"en":"The comic entertained the audience for an hour.","zh":"喜剧演员逗乐观众一个小时。"},{"en":"A local comic opened the show.","zh":"一位当地喜剧演员为演出开场。"}]},{"pos":"n.","meaning":"漫画书；连环画","definition":"a publication telling stories through pictures","examples":[{"en":"She borrowed a comic from the library.","zh":"她从图书馆借了一本漫画书。"},{"en":"The comic follows the adventures of two friends.","zh":"漫画讲述两个朋友的冒险。"}]}],"commence":[{"pos":"v.","meaning":"开始；着手","definition":"to begin","examples":[{"en":"Construction will commence in early June.","zh":"施工将于六月初开始。"},{"en":"Please be seated before the lecture commences.","zh":"请在讲座开始前入座。"}]}],"commencement":[{"pos":"n.","meaning":"开始；开端","definition":"the beginning of something","examples":[{"en":"The payment is due before the commencement of work.","zh":"这笔款项应在开工前支付。"},{"en":"The document records the commencement date of the contract.","zh":"文件记录了合同的生效日期。"}]},{"pos":"n.","meaning":"毕业典礼（尤美）","definition":"a ceremony at which students receive degrees","examples":[{"en":"Her parents attended the commencement ceremony.","zh":"她的父母参加了毕业典礼。"},{"en":"The novelist gave the commencement address.","zh":"这位小说家发表了毕业典礼演讲。"}]}],"comment":[{"pos":"n.","meaning":"评论；意见；注释","definition":"a spoken or written remark about something","examples":[{"en":"The tutor wrote a helpful comment on my essay.","zh":"导师在我的作文上写了有帮助的评语。"},{"en":"The report includes comments from residents.","zh":"报告包含居民的意见。"}]},{"pos":"v.","meaning":"评论；发表意见","definition":"to express an opinion or observation","examples":[{"en":"The manager declined to comment on the decision.","zh":"经理拒绝评论这项决定。"},{"en":"Several readers commented on the article.","zh":"几位读者评论了这篇文章。"}]}],"commentary":[{"pos":"n.","meaning":"现场解说；实况报道","definition":"a spoken account of an event as it happens","examples":[{"en":"The radio commentary described the final minutes of the match.","zh":"广播解说描述了比赛的最后几分钟。"},{"en":"Visitors can choose an audio commentary in several languages.","zh":"游客可以选择多种语言的语音解说。"}]},{"pos":"n.","meaning":"评论；评注；解释","definition":"discussion explaining or evaluating something","examples":[{"en":"Her commentary explains the poem's historical references.","zh":"她的评注解释了诗中的历史典故。"},{"en":"The article offers a thoughtful commentary on city planning.","zh":"这篇文章对城市规划作出了深入评论。"}]}],"commerce":[{"pos":"n.","meaning":"商业；贸易","definition":"the buying and selling of goods and services","examples":[{"en":"The port became a centre of international commerce.","zh":"这个港口成为国际贸易中心。"},{"en":"Online commerce has changed shopping habits.","zh":"电子商务改变了购物习惯。"}]},{"pos":"n.","meaning":"交往；交流（正式或旧式）","definition":"social or intellectual exchange","examples":[{"en":"The letters reveal a lively commerce of ideas.","zh":"这些信件体现了活跃的思想交流。"},{"en":"The academy encouraged intellectual commerce across disciplines.","zh":"这所学术机构鼓励跨学科思想交流。"}]}],"commercial":[{"pos":"adj.","meaning":"商业的；贸易的","definition":"relating to buying, selling, or business","examples":[{"en":"The building is used for commercial purposes.","zh":"这栋建筑用于商业用途。"},{"en":"Commercial activity increased near the port.","zh":"港口附近的商业活动增加了。"}]},{"pos":"adj.","meaning":"商业化的；以营利为目的的","definition":"intended mainly to make money","examples":[{"en":"The film was a commercial success.","zh":"这部电影在商业上获得了成功。"},{"en":"Critics considered the exhibition too commercial.","zh":"评论者认为展览过于商业化。"}]},{"pos":"n.","meaning":"商业广告","definition":"an advertisement on television or radio","examples":[{"en":"The programme paused for a commercial.","zh":"节目暂停，播放了一则广告。"},{"en":"A short commercial promoted the new service.","zh":"一则简短广告推广了新服务。"}]}],"commiserate":[{"pos":"v.","meaning":"表示同情；怜悯","definition":"to express sympathy for someone's disappointment","examples":[{"en":"We commiserated with her after the unsuccessful interview.","zh":"面试失败后，我们向她表示同情。"},{"en":"They met to commiserate over the cancelled holiday.","zh":"他们见面互相安慰取消假期的失落。"}]}],"commission":[{"pos":"n.","meaning":"委托；委托任务","definition":"an instruction to create something or perform a service","examples":[{"en":"The artist received a commission to paint a portrait.","zh":"这位艺术家受委托画一幅肖像。"},{"en":"The architect's first major commission was a public library.","zh":"这位建筑师的第一项重大委托是设计公共图书馆。"}]},{"pos":"n.","meaning":"佣金","definition":"money paid to someone for arranging a sale or transaction","examples":[{"en":"The agent earns a commission on every sale.","zh":"代理人每完成一笔销售都会获得佣金。"},{"en":"Ask whether the price includes commission.","zh":"问清楚价格是否包含佣金。"}]},{"pos":"v.","meaning":"委托；授权制作","definition":"to formally ask someone to make or do something","examples":[{"en":"The council will commission a study of traffic patterns.","zh":"市议会将委托开展交通模式研究。"},{"en":"They commissioned a local artist to design the mural.","zh":"他们委托一位当地艺术家设计壁画。"}]}],"commit":[{"pos":"v.","meaning":"犯；干（坏事或错误）","definition":"to do something wrong or illegal","examples":[{"en":"The report found that no crime had been committed.","zh":"报告认定没有犯罪行为发生。"},{"en":"He admitted committing a serious error.","zh":"他承认犯了严重错误。"}]},{"pos":"v.","meaning":"交付；托付；送交","definition":"to entrust someone or something to another's care","examples":[{"en":"The documents were committed to the archive for safekeeping.","zh":"文件被交给档案馆妥善保存。"},{"en":"She committed the details to memory.","zh":"她把细节牢记在心。"}]},{"pos":"v.","meaning":"承诺；投入","definition":"to promise to do something or devote resources to it","examples":[{"en":"The council committed funds to the project.","zh":"议会为项目投入了资金。"},{"en":"She committed herself to completing the course.","zh":"她承诺要完成课程。"}]}],"commitment":[{"pos":"n.","meaning":"承诺；承担的义务","definition":"a promise or responsibility that must be fulfilled","examples":[{"en":"The company made a commitment to reduce waste.","zh":"公司承诺减少废弃物。"},{"en":"Family commitments prevent him from travelling this month.","zh":"家庭责任使他这个月无法出行。"}]},{"pos":"n.","meaning":"投入；奉献","definition":"strong dedication to a person or activity","examples":[{"en":"Her commitment to teaching impressed the interviewers.","zh":"她对教学的投入打动了面试官。"},{"en":"The project requires a long-term commitment of time and money.","zh":"这个项目需要长期投入时间和资金。"}]}],"committee":[{"pos":"n.","meaning":"委员会；全体委员","definition":"a group appointed to consider or manage a matter","examples":[{"en":"The committee meets once a month.","zh":"委员会每月开会一次。"},{"en":"A committee reviewed all the applications.","zh":"一个委员会审核了所有申请。"}]}],"commodity":[{"pos":"n.","meaning":"商品；货物；大宗商品","definition":"a product or raw material that can be traded","examples":[{"en":"Coffee is an important export commodity.","zh":"咖啡是一种重要的出口商品。"},{"en":"The price of this commodity changes frequently.","zh":"这种商品的价格经常变化。"}]}],"commonwealth":[{"pos":"n.","meaning":"英联邦；政治联合体","definition":"an association of states sharing certain interests or a political community","examples":[{"en":"The Commonwealth includes countries on several continents.","zh":"英联邦包括几个大洲的国家。"},{"en":"The lecture compared different ideas of a commonwealth.","zh":"讲座比较了关于政治共同体的不同理念。"}]}],"communal":[{"pos":"adj.","meaning":"共用的；公共的","definition":"shared by a group of people","examples":[{"en":"The building has a communal kitchen.","zh":"这栋楼有一个共用厨房。"},{"en":"Residents share a communal garden.","zh":"居民共用一个花园。"},{"en":"Communal spaces can encourage neighbours to meet.","zh":"公共空间可以促进邻里相识。"}]}],"community":[{"pos":"n.","meaning":"社区；群体","definition":"a group of people sharing a place or interests","examples":[{"en":"The new centre serves the local community.","zh":"新中心服务当地社区。"},{"en":"Members of the community helped clean the park.","zh":"社区成员帮忙清理了公园。"},{"en":"A strong community can reduce social isolation.","zh":"紧密的社区联系可以减轻社会孤立。"}]},{"pos":"n.","meaning":"生物群落","definition":"a group of organisms living and interacting in an area","examples":[{"en":"The pond supports a diverse community of organisms.","zh":"池塘维持着多样的生物群落。"},{"en":"Pollution can change the whole plant community.","zh":"污染会改变整个植物群落。"}]}],"commute":[{"pos":"v.","meaning":"通勤","definition":"to travel regularly between home and work","examples":[{"en":"I commute to work by train.","zh":"我乘火车通勤。"},{"en":"Many nurses commute from nearby towns.","zh":"许多护士从附近城镇通勤。"},{"en":"Would you commute an hour each way for a better job?","zh":"你会为了一份更好的工作每天单程通勤一小时吗？"}]},{"pos":"n.","meaning":"通勤路程；上下班往返","definition":"A regular journey between home and work.","examples":[{"en":"My daily commute takes forty minutes.","zh":"我每天通勤需要四十分钟。"},{"en":"A shorter commute gives him more time with his family.","zh":"更短的通勤让他有更多时间陪家人。"}]},{"pos":"v.","meaning":"减刑；改判较轻刑罚","definition":"To replace a punishment with a less severe one.","examples":[{"en":"The governor commuted the prison sentence.","zh":"州长减轻了监禁刑罚。"},{"en":"Her sentence was commuted after new evidence emerged.","zh":"新证据出现后，她获得了减刑。"}]},{"pos":"v.","meaning":"交换；折抵；改变支付方式","definition":"To exchange one form of payment or obligation for another.","examples":[{"en":"He commuted part of his pension into a lump sum.","zh":"他把部分养老金折换为一次性领取的款项。"},{"en":"The agreement allowed rent payments to be commuted into a single settlement.","zh":"协议允许把租金付款折抵成一次性结清。"}]}],"compact":[{"pos":"adj.","meaning":"紧凑的；小巧的","definition":"small and efficiently arranged","examples":[{"en":"The flat has a compact kitchen.","zh":"这套公寓有一个紧凑的小厨房。"},{"en":"This compact camera fits in a pocket.","zh":"这台小巧的相机可以放进口袋。"}]},{"pos":"adj.","meaning":"紧密的；结实的；简明的","definition":"closely packed or expressed with few unnecessary details","examples":[{"en":"The soil formed a compact layer.","zh":"土壤形成了一个密实层。"},{"en":"The book offers a compact account of the period.","zh":"这本书简明地叙述了那个时期。"}]},{"pos":"v.","meaning":"压实；使紧密","definition":"to press material into a smaller, denser space","examples":[{"en":"The machine will compact the waste.","zh":"机器将把垃圾压实。"},{"en":"Workers compacted the ground before laying the road.","zh":"工人在铺路前压实了地面。"}]}],"companion":[{"pos":"n.","meaning":"同伴；伙伴","definition":"someone who shares an activity or spends time with another","examples":[{"en":"Her travelling companion knew the city well.","zh":"她的旅伴很熟悉这座城市。"},{"en":"The dog was a faithful companion.","zh":"这只狗是一位忠实的伙伴。"}]}],"comparable":[{"pos":"adj.","meaning":"可比较的；相似的；比得上的","definition":"similar enough to compare or equal in quality","examples":[{"en":"The two studies used comparable samples.","zh":"这两项研究使用了可比较的样本。"},{"en":"We found a cheaper product of comparable quality.","zh":"我们找到了一种质量相当但更便宜的产品。"}]}],"comparative":[{"pos":"adj.","meaning":"比较的；通过比较得到的","definition":"involving comparison","examples":[{"en":"The study uses a comparative approach.","zh":"这项研究采用比较方法。"},{"en":"She teaches comparative literature.","zh":"她教授比较文学。"}]},{"pos":"adj.","meaning":"相对的；比较而言的","definition":"considered in relation to something else","examples":[{"en":"They enjoyed comparative peace after months of conflict.","zh":"数月冲突后，他们享受到了相对的平静。"},{"en":"The area has the comparative advantage of lower transport costs.","zh":"该地区具有运输成本较低的比较优势。"}]}],"comparatively":[{"pos":"adv.","meaning":"比较地；相对地","definition":"in comparison with something else","examples":[{"en":"The new model is comparatively light.","zh":"相比之下，新型号较轻。"},{"en":"The village remained comparatively quiet during the festival.","zh":"节日期间，村庄仍比较安静。"}]}],"compare":[{"pos":"v.","meaning":"比较；对照","definition":"to examine similarities and differences","examples":[{"en":"Compare the two maps before choosing a route.","zh":"选择路线前，比较一下这两张地图。"},{"en":"The study compares rural and urban living costs.","zh":"这项研究比较城乡生活成本。"}]}],"comparison":[{"pos":"n.","meaning":"比较；对比","definition":"the process of examining similarities and differences","examples":[{"en":"The table allows a direct comparison of prices.","zh":"表格便于直接比较价格。"},{"en":"In comparison with last year, demand has increased.","zh":"与去年相比，需求有所增加。"}]},{"pos":"n.","meaning":"比喻；比拟","definition":"a statement likening one thing to another","examples":[{"en":"Her comparison of the city to a living organism was effective.","zh":"她把城市比作生物体的比喻很贴切。"},{"en":"The poet uses a comparison between memory and water.","zh":"诗人把记忆与水作了比拟。"}]}],"compass":[{"pos":"n.","meaning":"罗盘；指南针","definition":"an instrument indicating direction","examples":[{"en":"We used a compass to find north.","zh":"我们用指南针找北。"},{"en":"The compass helped them stay on course.","zh":"指南针帮助他们保持方向。"}]},{"pos":"n.","meaning":"范围；界限","definition":"the range or scope of something","examples":[{"en":"The issue lies within the compass of this study.","zh":"这个问题属于本研究的范围。"},{"en":"The book has a wide geographical compass.","zh":"这本书覆盖的地理范围很广。"}]},{"pos":"n.","meaning":"圆规（通常为 compasses）","definition":"an instrument with two arms used to draw circles","examples":[{"en":"Use compasses to draw a circle.","zh":"用圆规画一个圆。"},{"en":"She adjusted the compasses before marking the paper.","zh":"她调整圆规后在纸上作图。"}]}],"compassionate":[{"pos":"adj.","meaning":"有同情心的；体恤的","definition":"showing concern for suffering people","examples":[{"en":"The nurse gave a compassionate response to his fears.","zh":"护士体恤地回应了他的恐惧。"},{"en":"The policy aims to make the system more compassionate.","zh":"这项政策旨在使制度更有人情味。"}]}],"compatible":[{"pos":"adj.","meaning":"兼容的；可以共存的","definition":"able to work or exist together without problems","examples":[{"en":"The printer is compatible with this computer.","zh":"这台打印机与这台电脑兼容。"},{"en":"The two proposals are not entirely compatible.","zh":"这两项提议并非完全相容。"}]},{"pos":"adj.","meaning":"合得来的；志趣相投的","definition":"able to have a good relationship because of shared characteristics","examples":[{"en":"They are compatible despite their different backgrounds.","zh":"尽管背景不同，他们相处融洽。"},{"en":"The agency tries to match compatible housemates.","zh":"中介努力为人们匹配合得来的室友。"}]}],"compatriot":[{"pos":"n.","meaning":"同胞；同国人","definition":"a person from the same country as another","examples":[{"en":"She met a compatriot while studying abroad.","zh":"留学时，她遇到了一位同胞。"},{"en":"The athlete congratulated his compatriots after the race.","zh":"比赛后，运动员祝贺了他的同胞们。"}]}],"compel":[{"pos":"v.","meaning":"强迫；迫使","definition":"to force someone to act","examples":[{"en":"The evidence compelled us to reconsider the conclusion.","zh":"证据迫使我们重新考虑结论。"},{"en":"No student should be compelled to discuss private matters.","zh":"不应强迫任何学生讨论私人事情。"}]}],"compendium":[{"pos":"n.","meaning":"概要；简编","definition":"a concise collection of information on a subject","examples":[{"en":"The book is a compendium of local history.","zh":"这本书是地方史概要。"},{"en":"She compiled a useful compendium of teaching methods.","zh":"她编写了一本实用的教学方法简编。"}]}],"compensate":[{"pos":"v.","meaning":"赔偿；补偿","definition":"to pay or give something in return for loss or injury","examples":[{"en":"The company compensated passengers for the delay.","zh":"公司赔偿了被延误的乘客。"},{"en":"The scheme compensates farmers for damaged crops.","zh":"该计划补偿作物受损的农民。"}]},{"pos":"v.","meaning":"弥补；抵消","definition":"to make up for a disadvantage","examples":[{"en":"Extra practice can compensate for limited experience.","zh":"额外练习可以弥补经验不足。"},{"en":"The view compensates for the small size of the room.","zh":"风景弥补了房间较小的不足。"}]}],"compensation":[{"pos":"n.","meaning":"补偿；赔偿；赔偿金","definition":"money or another benefit given for loss or harm","examples":[{"en":"Passengers received compensation for the cancelled flight.","zh":"乘客因航班取消获得了赔偿。"},{"en":"A shorter commute provided some compensation for the lower salary.","zh":"通勤时间缩短在一定程度上弥补了工资降低。"}]}],"compete":[{"pos":"v.","meaning":"竞争；参加比赛","definition":"to try to win or do better than others","examples":[{"en":"Small shops must compete with large chains.","zh":"小商店必须与大型连锁店竞争。"},{"en":"Athletes from twenty countries will compete.","zh":"来自二十个国家的运动员将参加比赛。"}]}],"competent":[{"pos":"adj.","meaning":"有能力的；能胜任的","definition":"having sufficient skill or ability","examples":[{"en":"She is a competent and reliable technician.","zh":"她是一位能干而可靠的技术员。"},{"en":"The task requires a competent translator.","zh":"这项任务需要一名胜任的译员。"}]}],"competition":[{"pos":"n.","meaning":"竞争","definition":"a situation in which people try to do better than others","examples":[{"en":"Competition between suppliers helped reduce prices.","zh":"供应商之间的竞争有助于降低价格。"},{"en":"There is strong competition for research funding.","zh":"科研经费的竞争很激烈。"}]},{"pos":"n.","meaning":"比赛；竞赛","definition":"an organized event to select a winner","examples":[{"en":"She entered a national design competition.","zh":"她参加了全国设计比赛。"},{"en":"The photography competition attracted hundreds of entries.","zh":"摄影比赛吸引了数百件参赛作品。"}]}],"compile":[{"pos":"v.","meaning":"汇编；编纂","definition":"to collect information and arrange it into a work","examples":[{"en":"The team will compile a list of available services.","zh":"团队将汇编一份可用服务清单。"},{"en":"She compiled the dictionary over many years.","zh":"她花了多年时间编纂这本词典。"}]}],"complain":[{"pos":"v.","meaning":"抱怨","definition":"to express dissatisfaction","examples":[{"en":"Residents complained about the noise.","zh":"居民抱怨噪声。"},{"en":"He never complains about the long walk.","zh":"他从不抱怨路程远。"}]},{"pos":"v.","meaning":"投诉","definition":"to formally report dissatisfaction or a problem","examples":[{"en":"You can complain to the regulator.","zh":"你可以向监管机构投诉。"},{"en":"Several customers complained that the product was faulty.","zh":"几位顾客投诉产品有故障。"}]}],"complaint":[{"pos":"n.","meaning":"投诉；抱怨；控告","definition":"a statement that something is wrong or unsatisfactory","examples":[{"en":"I am writing to make a complaint about your service.","zh":"我写信是为了投诉你们的服务。"},{"en":"The manager responded to my complaint promptly.","zh":"经理迅速回应了我的投诉。"},{"en":"Please submit your complaint in writing.","zh":"请以书面形式提交投诉。"}]},{"pos":"n.","meaning":"疾病；小病；不适","definition":"An illness or medical problem, often affecting a particular part.","examples":[{"en":"She visited the clinic with a stomach complaint.","zh":"她因胃部不适到诊所就诊。"},{"en":"The report lists common skin complaints.","zh":"报告列出了常见皮肤疾患。"}]}],"complementary":[{"pos":"adj.","meaning":"互补的；补充的","definition":"combining to improve or complete each other","examples":[{"en":"The partners have complementary skills.","zh":"两位合伙人的技能互补。"},{"en":"The two studies provide complementary evidence.","zh":"这两项研究提供了相互补充的证据。"}]}],"complete":[{"pos":"adj.","meaning":"完整的；全部的","definition":"containing all required parts","examples":[{"en":"The library has a complete collection of the journal.","zh":"图书馆收藏了这份期刊的全套。"},{"en":"Please provide your complete address.","zh":"请提供完整地址。"}]},{"pos":"adj.","meaning":"完成的","definition":"finished and ready","examples":[{"en":"The repairs are now complete.","zh":"维修现在已经完成。"},{"en":"Her application was complete before the deadline.","zh":"她的申请在截止日前完成了。"}]},{"pos":"adj.","meaning":"彻底的；完全的","definition":"total or absolute","examples":[{"en":"The result came as a complete surprise.","zh":"这个结果完全出乎意料。"},{"en":"There was complete silence in the room.","zh":"房间里一片寂静。"}]},{"pos":"v.","meaning":"完成；结束","definition":"to finish making or doing something","examples":[{"en":"They completed the bridge on time.","zh":"他们按时完成了桥梁。"},{"en":"Please complete the form in black ink.","zh":"请用黑色墨水填写表格。"}]}],"complex":[{"pos":"adj.","meaning":"复杂的；难懂的；综合的","definition":"made of many connected parts and difficult to understand","examples":[{"en":"The report explains a complex legal problem.","zh":"报告解释了一个复杂的法律问题。"},{"en":"The human brain is a highly complex system.","zh":"人脑是一个高度复杂的系统。"}]},{"pos":"n.","meaning":"建筑群；综合体","definition":"a connected group of buildings or elements","examples":[{"en":"The sports complex includes a pool and two gyms.","zh":"体育中心包括一个游泳池和两个健身房。"},{"en":"The town developed around a large industrial complex.","zh":"这座城镇围绕一个大型工业综合体发展起来。"}]},{"pos":"n.","meaning":"情结；心理上的过度顾虑","definition":"a deeply rooted set of feelings about something","examples":[{"en":"He developed an inferiority complex at school.","zh":"他在学校里产生了自卑情结。"},{"en":"She tried to overcome her complex about speaking in public.","zh":"她努力克服对公开演讲的心理障碍。"}]}],"complexity":[{"pos":"n.","meaning":"复杂性；复杂之处","definition":"the state of having many connected parts or details","examples":[{"en":"The diagram reveals the complexity of the network.","zh":"图示揭示了网络的复杂性。"},{"en":"We underestimated the legal complexities of the agreement.","zh":"我们低估了这项协议在法律方面的复杂之处。"}]}],"complicate":[{"pos":"v.","meaning":"使复杂化","definition":"to make something harder to understand or do","examples":[{"en":"The missing document complicated the application.","zh":"缺少的文件使申请复杂化了。"},{"en":"Heavy rain could complicate the rescue.","zh":"大雨可能使救援复杂化。"}]}],"complicated":[{"pos":"adj.","meaning":"复杂的；难懂的","definition":"having many parts that are difficult to understand","examples":[{"en":"The instructions were more complicated than we expected.","zh":"说明书比我们预想的更复杂。"},{"en":"A complicated series of transfers delayed the payment.","zh":"一连串复杂的转账延误了付款。"}]}],"compliment":[{"pos":"n.","meaning":"赞美；恭维","definition":"a remark expressing admiration","examples":[{"en":"She accepted the compliment with a smile.","zh":"她微笑着接受了赞美。"},{"en":"His comment was intended as a compliment.","zh":"他的话本意是赞美。"}]},{"pos":"n.","meaning":"问候；致意（常用复数 compliments）","definition":"polite greetings or good wishes","examples":[{"en":"Please give my compliments to the chef.","zh":"请代我向主厨致意。"},{"en":"The flowers arrived with the company's compliments.","zh":"鲜花随附着公司的问候送到了。"}]}],"comply":[{"pos":"v.","meaning":"遵守；服从；照办","definition":"to act according to a rule or request","examples":[{"en":"All buildings must comply with safety standards.","zh":"所有建筑都必须符合安全标准。"},{"en":"The company agreed to comply with the request.","zh":"公司同意照办这一要求。"}]}],"component":[{"pos":"n.","meaning":"组成部分；零部件","definition":"one part of a larger whole","examples":[{"en":"The battery is the heaviest component of the device.","zh":"电池是这台设备最重的部件。"},{"en":"Listening is an essential component of language learning.","zh":"听力是语言学习的重要组成部分。"}]},{"pos":"adj.","meaning":"构成的；组成的","definition":"forming part of a larger whole","examples":[{"en":"The diagram labels the component parts of the engine.","zh":"图中标出了发动机的组成部件。"},{"en":"Each component element contributes to the final design.","zh":"每个组成要素都对最终设计有所贡献。"}]}],"compose":[{"pos":"v.","meaning":"组成；构成","definition":"to make up something as its parts","examples":[{"en":"The committee is composed of five members.","zh":"委员会由五名成员组成。"},{"en":"Several short sections compose the final chapter.","zh":"几个短小的部分构成了最后一章。"}]},{"pos":"v.","meaning":"创作；写作；作曲","definition":"to create music or written material","examples":[{"en":"She began to compose music as a child.","zh":"她从小就开始作曲。"},{"en":"He took time to compose a careful reply.","zh":"他花时间认真写了一封回信。"}]},{"pos":"v.","meaning":"使镇静；使安定","definition":"to make oneself calm and controlled","examples":[{"en":"She paused to compose herself before speaking.","zh":"她停下来镇定自己，然后发言。"},{"en":"He needed a moment to compose his thoughts.","zh":"他需要片刻来整理思绪。"}]}],"composition":[{"pos":"n.","meaning":"作品；作文；乐曲","definition":"a piece of writing, music, or art","examples":[{"en":"The orchestra played a new composition.","zh":"乐团演奏了一首新作品。"},{"en":"Students wrote a short composition about their hometown.","zh":"学生写了一篇关于家乡的短文。"}]},{"pos":"n.","meaning":"创作；写作；作曲","definition":"the act of creating writing, music, or art","examples":[{"en":"She studies musical composition.","zh":"她学习作曲。"},{"en":"The course develops skills in essay composition.","zh":"课程培养文章写作能力。"}]},{"pos":"n.","meaning":"组成；成分；结构","definition":"the parts that make up a whole","examples":[{"en":"The scientists analysed the soil's composition.","zh":"科学家分析了土壤成分。"},{"en":"The composition of the committee changed last year.","zh":"委员会的人员组成去年发生了变化。"}]}],"compound":[{"pos":"v.","meaning":"加重；使恶化","definition":"to make a problem worse","examples":[{"en":"The delay compounded the shortage of supplies.","zh":"延误加剧了物资短缺。"},{"en":"Poor communication can compound an already difficult situation.","zh":"沟通不畅会使本已困难的局面更加恶化。"}],"ipa":"/kəmˈpaʊnd/"},{"pos":"v.","meaning":"混合；使化合","definition":"to combine substances into a new mixture","examples":[{"en":"The pharmacist compounds the ingredients into an ointment.","zh":"药剂师把这些成分配制成药膏。"},{"en":"Several materials were compounded to create the coating.","zh":"几种材料被混合制成涂层。"}],"ipa":"/kəmˈpaʊnd/"},{"pos":"n.","meaning":"化合物；复合物","definition":"a substance or thing made by combining elements","examples":[{"en":"Water is a compound of hydrogen and oxygen.","zh":"水是氢和氧的化合物。"},{"en":"The researchers tested a newly developed compound.","zh":"研究人员测试了一种新研发的化合物。"}],"ipa":"/ˈkɒmpaʊnd/"},{"pos":"n.","meaning":"有围墙的大院；围起来的建筑群","definition":"an enclosed area containing buildings","examples":[{"en":"Visitors waited outside the school compound.","zh":"访客在学校大院外等候。"},{"en":"A wall surrounds the residential compound.","zh":"一道墙围着这片住宅院落。"}],"ipa":"/ˈkɒmpaʊnd/"},{"pos":"adj.","meaning":"复合的；由多个部分组成的","definition":"made up of two or more elements","examples":[{"en":"The students learned to write compound sentences.","zh":"学生们学习写并列复合句。"},{"en":"The device uses a compound lens to improve focus.","zh":"这台设备使用复合透镜改善聚焦。"}],"ipa":"/ˈkɒmpaʊnd/"}],"comprehension":[{"pos":"n.","meaning":"理解；理解力","definition":"the ability or process of understanding","examples":[{"en":"The questions test reading comprehension.","zh":"这些问题测试阅读理解能力。"},{"en":"The scale of the problem was beyond his comprehension.","zh":"问题的规模超出了他的理解范围。"}]}],"comprehensive":[{"pos":"adj.","meaning":"全面的；综合的；详尽的","definition":"covering all or nearly all relevant aspects","examples":[{"en":"The report provides a comprehensive overview.","zh":"报告提供了全面概述。"},{"en":"Students receive comprehensive training in the equipment.","zh":"学生接受设备使用的全面培训。"}]}],"compress":[{"pos":"v.","meaning":"压缩；压紧","definition":"to reduce size by pressing or processing","examples":[{"en":"Compress the packing material before closing the box.","zh":"关箱前把包装材料压紧。"},{"en":"The software compresses large images for the website.","zh":"这款软件为网站压缩大幅图片。"}],"ipa":"/kəmˈpres/"},{"pos":"n.","meaning":"敷布","definition":"a cloth applied to part of the body","examples":[{"en":"The nurse prepared a warm compress.","zh":"护士准备了一块热敷布。"},{"en":"A clean compress lay beside the treatment tray.","zh":"治疗盘旁放着一块干净的敷布。"}],"ipa":"/ˈkɒmpres/"}],"comprise":[{"pos":"v.","meaning":"包含；由……组成","definition":"to consist of or include specified parts","examples":[{"en":"The course comprises six modules.","zh":"这门课程由六个模块组成。"},{"en":"Women comprise more than half of the committee.","zh":"女性占委员会成员的一半以上。"}]}],"compromise":[{"pos":"n.","meaning":"妥协；折中办法","definition":"an agreement in which each side gives up something","examples":[{"en":"Both groups accepted the compromise.","zh":"两个群体都接受了折中方案。"},{"en":"We found a compromise between cost and quality.","zh":"我们在成本与质量之间找到了折中办法。"}]},{"pos":"v.","meaning":"妥协；让步","definition":"to reach agreement by accepting less than originally wanted","examples":[{"en":"Both sides must be willing to compromise.","zh":"双方都必须愿意妥协。"},{"en":"She refused to compromise on safety.","zh":"她拒绝在安全问题上让步。"}]},{"pos":"v.","meaning":"损害；危及","definition":"to weaken or put something at risk","examples":[{"en":"Poor storage can compromise food safety.","zh":"储存不当会危及食品安全。"},{"en":"The leak compromised the confidentiality of the records.","zh":"泄露损害了记录的保密性。"}]}],"compulsively":[{"pos":"adv.","meaning":"强迫性地；无法自制地","definition":"in a way that is difficult to stop or control","examples":[{"en":"He checked the door lock compulsively.","zh":"他无法自制地反复检查门锁。"},{"en":"She noticed that she was refreshing the page compulsively.","zh":"她发现自己在不由自主地反复刷新页面。"}]}],"compulsory":[{"pos":"adj.","meaning":"强制的；必须的；必修的","definition":"required by a rule or law","examples":[{"en":"Attendance at the safety session is compulsory.","zh":"必须参加安全培训。"},{"en":"Mathematics is a compulsory subject in this programme.","zh":"数学是这个项目的必修课。"}]}],"computerize":[{"pos":"v.","meaning":"使计算机化；用计算机处理或储存","definition":"to use computers to manage a process or information","examples":[{"en":"The library plans to computerize its records.","zh":"图书馆计划用计算机管理记录。"},{"en":"The company computerized its payroll system.","zh":"公司将工资系统计算机化了。"}]}],"conceal":[{"pos":"v.","meaning":"隐藏；隐瞒；掩盖","definition":"to keep something out of sight or prevent it being known","examples":[{"en":"Thick curtains concealed the damaged wall.","zh":"厚窗帘遮住了受损的墙。"},{"en":"The report did not conceal the project's weaknesses.","zh":"报告没有掩盖这个项目的缺点。"}]}],"concede":[{"pos":"v.","meaning":"不情愿地承认","definition":"to admit something, often reluctantly","examples":[{"en":"He had to concede that her answer was correct.","zh":"他不得不承认她的答案是正确的。"},{"en":"The company concedes that mistakes were made.","zh":"公司承认存在失误。"}]},{"pos":"v.","meaning":"让步；让出","definition":"to give up something or allow an opponent to have it","examples":[{"en":"Neither side would concede any ground in the talks.","zh":"谈判双方都不愿作出让步。"},{"en":"The team conceded a goal in the final minute.","zh":"球队在最后一分钟丢了一球。"}]}],"conceive":[{"pos":"v.","meaning":"构想；设想；想出","definition":"to form an idea or plan","examples":[{"en":"The engineer conceived a simpler design.","zh":"工程师想出了更简单的设计。"},{"en":"It is hard to conceive of a world without electricity.","zh":"很难想象没有电的世界。"}]},{"pos":"v.","meaning":"受孕；怀孕","definition":"to become pregnant","examples":[{"en":"The book explains what it means to conceive.","zh":"这本书解释了受孕的含义。"},{"en":"The couple sought advice because they had difficulty conceiving.","zh":"这对夫妇因受孕困难而寻求咨询。"}]}],"concentrate":[{"pos":"v.","meaning":"集中注意力；全神贯注","definition":"to direct attention or effort towards one thing","examples":[{"en":"I find it easier to concentrate in a quiet room.","zh":"我发现自己在安静房间里更容易集中注意力。"},{"en":"The team concentrated on improving the final section.","zh":"团队集中精力改进最后一部分。"}]},{"pos":"v.","meaning":"集中；聚集","definition":"to bring things together in one place","examples":[{"en":"Most jobs are concentrated in the city centre.","zh":"大多数工作岗位集中在市中心。"},{"en":"The charity concentrates its resources in the poorest districts.","zh":"这家慈善机构把资源集中在最贫困的地区。"}]},{"pos":"v.","meaning":"浓缩","definition":"to increase the strength of a substance by removing liquid","examples":[{"en":"Heating the solution slowly will concentrate it.","zh":"缓慢加热溶液会使其浓缩。"},{"en":"The process concentrates the juice without adding sugar.","zh":"这个过程在不加糖的情况下浓缩果汁。"}]},{"pos":"n.","meaning":"浓缩液；浓缩物","definition":"a substance made stronger by removing water","examples":[{"en":"Add water to the orange concentrate.","zh":"往橙汁浓缩液中加水。"},{"en":"The factory produces fruit concentrate for beverage makers.","zh":"这家工厂为饮料制造商生产水果浓缩液。"}]}],"concentration":[{"pos":"n.","meaning":"专注；注意力集中","definition":"the ability or effort to focus attention","examples":[{"en":"The task requires intense concentration.","zh":"这项任务需要高度专注。"},{"en":"Noise makes concentration difficult.","zh":"噪声让人难以集中注意力。"}]},{"pos":"n.","meaning":"集中；聚集","definition":"a large amount gathered in one place","examples":[{"en":"There is a high concentration of shops near the station.","zh":"车站附近商店高度集中。"},{"en":"The policy reduced the concentration of power.","zh":"这项政策减少了权力的集中。"}]},{"pos":"n.","meaning":"浓度；浓缩","definition":"the amount of a substance in a mixture, or making it stronger","examples":[{"en":"The concentration of salt was measured carefully.","zh":"盐的浓度经过了仔细测量。"},{"en":"Evaporation increases the concentration of the solution.","zh":"蒸发会提高溶液的浓度。"}]}],"concept":[{"pos":"n.","meaning":"概念；观念","definition":"a general idea about something","examples":[{"en":"The lesson introduces the concept of probability.","zh":"课程介绍概率概念。"},{"en":"Children develop a concept of time gradually.","zh":"孩子逐渐形成时间概念。"}]},{"pos":"n.","meaning":"构想；设计理念","definition":"an idea for a plan or product","examples":[{"en":"The team tested a new concept for public transport.","zh":"团队测试了公共交通的新构想。"},{"en":"The design concept combines comfort and simplicity.","zh":"设计理念结合了舒适与简洁。"}]}],"conception":[{"pos":"n.","meaning":"概念；观念；构想","definition":"an idea about something or the forming of an idea","examples":[{"en":"The course challenged my conception of intelligence.","zh":"这门课程挑战了我对智力的看法。"},{"en":"She guided the project from its original conception.","zh":"她从项目最初构想阶段就一直指导它。"}]}],"conceptual":[{"pos":"adj.","meaning":"概念的；观念的","definition":"relating to ideas or concepts","examples":[{"en":"The paper develops a conceptual framework.","zh":"这篇论文建立了一个概念框架。"},{"en":"The disagreement is conceptual rather than practical.","zh":"分歧在于观念层面，而非实际操作。"}]}],"concern":[{"pos":"v.","meaning":"涉及；与……有关","definition":"to relate to or affect someone or something","examples":[{"en":"The rules concern everyone in the building.","zh":"这些规则涉及楼里的每个人。"},{"en":"The article concerns changes in education.","zh":"文章涉及教育变化。"}]},{"pos":"v.","meaning":"使担心","definition":"to make someone worried","examples":[{"en":"The declining water level concerns local farmers.","zh":"水位下降令当地农民担忧。"},{"en":"What concerns me most is the lack of evidence.","zh":"最令我担心的是缺乏证据。"}]},{"pos":"n.","meaning":"担忧；关切","definition":"a feeling of worry or care","examples":[{"en":"Residents expressed concern about traffic.","zh":"居民表达了对交通的担忧。"},{"en":"Their main concern is the children's welfare.","zh":"他们主要关心孩子们的福祉。"}]},{"pos":"n.","meaning":"相关事务；关注点","definition":"a matter of importance or responsibility","examples":[{"en":"Safety is our first concern.","zh":"安全是我们最重视的事项。"},{"en":"That matter is not the committee's concern.","zh":"那件事不属于委员会职责范围。"}]}],"concert":[{"pos":"n.","meaning":"音乐会；演奏会","definition":"a public performance of music","examples":[{"en":"The orchestra gave a concert in the town square.","zh":"乐团在镇广场举办了一场音乐会。"},{"en":"Tickets for the concert sold out quickly.","zh":"音乐会门票很快售罄。"}]}],"concession":[{"pos":"n.","meaning":"让步；迁就","definition":"something given up to reach an agreement","examples":[{"en":"Both sides made a concession during the negotiations.","zh":"双方在谈判中各作了一项让步。"},{"en":"The change was a concession to public concerns.","zh":"这项变化是对公众关切作出的妥协。"}]},{"pos":"n.","meaning":"特许权；经营许可","definition":"a special right to operate a business or use a resource","examples":[{"en":"The company won a concession to operate the railway.","zh":"这家公司获得了铁路运营特许权。"},{"en":"The contract grants a ten-year mining concession.","zh":"合同授予十年的采矿特许权。"}]},{"pos":"n.","meaning":"承认；认可","definition":"an admission that something is true or reasonable","examples":[{"en":"Her statement was a concession that the plan had failed.","zh":"她的声明等于承认计划已经失败。"},{"en":"The apology included a concession of responsibility.","zh":"道歉中包含对责任的承认。"}]}],"conclude":[{"pos":"v.","meaning":"得出结论","definition":"to reach a judgement after considering information","examples":[{"en":"We cannot conclude that one factor caused the change.","zh":"我们不能断定某一个因素造成了这种变化。"},{"en":"The researchers conclude that more evidence is needed.","zh":"研究人员得出结论，认为还需要更多证据。"},{"en":"It would be premature to conclude that the policy has failed.","zh":"现在就断定政策失败还为时过早。"}]}],"conclusion":[{"pos":"n.","meaning":"结论；推论","definition":"a judgement reached after considering evidence","examples":[{"en":"We cannot draw a conclusion from one example.","zh":"我们不能从一个例子得出结论。"},{"en":"The data support a different conclusion.","zh":"数据支持另一种结论。"}]},{"pos":"n.","meaning":"结束；结尾；缔结","definition":"the final part or completion of something","examples":[{"en":"The report's conclusion summarizes the main findings.","zh":"报告的结尾总结了主要发现。"},{"en":"The conclusion of the agreement ended months of negotiations.","zh":"协议的缔结结束了数月谈判。"}]}],"concrete":[{"pos":"n.","meaning":"混凝土","definition":"a hard building material made from cement, aggregate, and water","examples":[{"en":"The workers poured concrete into the mould.","zh":"工人把混凝土倒入模具。"},{"en":"The floor is made of reinforced concrete.","zh":"地板由钢筋混凝土制成。"}]},{"pos":"adj.","meaning":"混凝土制的","definition":"made of concrete","examples":[{"en":"A concrete wall separates the two gardens.","zh":"一堵混凝土墙将两个花园隔开。"},{"en":"The bridge rests on concrete pillars.","zh":"这座桥由混凝土桥墩支撑。"}]},{"pos":"adj.","meaning":"具体的；确实的；有形的","definition":"specific and real rather than abstract","examples":[{"en":"We need concrete evidence before making a decision.","zh":"作出决定前，我们需要确凿证据。"},{"en":"Please give a concrete example of the problem.","zh":"请给出这个问题的一个具体例子。"}]}],"concur":[{"pos":"v.","meaning":"同意；意见一致","definition":"to share the same opinion","examples":[{"en":"I concur with the report's main conclusion.","zh":"我同意报告的主要结论。"},{"en":"The two experts concurred on the need for more data.","zh":"两位专家都认为需要更多数据。"}]},{"pos":"v.","meaning":"同时发生；共同作用","definition":"to happen together or combine in effect","examples":[{"en":"Several factors concurred to produce the result.","zh":"几个因素共同促成了这个结果。"},{"en":"These events rarely concur.","zh":"这些事件很少同时发生。"}]}],"condemn":[{"pos":"v.","meaning":"谴责；声讨","definition":"to express strong disapproval","examples":[{"en":"Residents condemned the dumping of waste in the river.","zh":"居民谴责向河里倾倒废物的行为。"},{"en":"The committee condemned the deliberate misuse of data.","zh":"委员会强烈谴责蓄意滥用数据。"}]},{"pos":"v.","meaning":"判刑；宣判","definition":"to impose a punishment by an official judgement","examples":[{"en":"The court condemned the offender to a prison term.","zh":"法院判处罪犯有期徒刑。"},{"en":"The historical account describes prisoners condemned without a fair trial.","zh":"这份历史记述描述了未经公正审判便被定罪的囚犯。"}]}],"condensation":[{"pos":"n.","meaning":"凝结；冷凝水","definition":"the change of vapour into liquid, or liquid formed in this way","examples":[{"en":"Condensation formed on the cold window.","zh":"冷玻璃上凝结了水珠。"},{"en":"The experiment demonstrates condensation of water vapour.","zh":"这个实验演示水蒸气的凝结。"}]},{"pos":"n.","meaning":"浓缩；缩写","definition":"the process of making a text more concise","examples":[{"en":"The editor's condensation preserved the main argument.","zh":"编辑的缩写保留了主要论点。"},{"en":"The booklet is a condensation of the longer report.","zh":"这本小册子是长篇报告的缩写本。"}]}],"condense":[{"pos":"v.","meaning":"精简；浓缩；压缩","definition":"to make something shorter or more compact","examples":[{"en":"She condensed the report into two pages.","zh":"她把报告浓缩成了两页。"},{"en":"The course condenses a year's material into six months.","zh":"课程将一年的内容压缩到六个月。"}]},{"pos":"v.","meaning":"凝结；使凝结","definition":"to change from gas into liquid","examples":[{"en":"Steam condenses on the cold window.","zh":"蒸汽在冷窗上凝结。"},{"en":"The cooling system condenses the vapour.","zh":"冷却系统使蒸气凝结。"}]}],"condition":[{"pos":"n.","meaning":"状态；状况","definition":"the state something or someone is in","examples":[{"en":"The bicycle is still in excellent condition.","zh":"这辆自行车仍然状态极好。"},{"en":"The nurse checked the patient's condition regularly.","zh":"护士定期检查患者的状况。"}]},{"pos":"n.","meaning":"环境；条件","definition":"circumstances affecting an activity or life","examples":[{"en":"Working conditions improved after the inspection.","zh":"检查后，工作条件改善了。"},{"en":"The plants grow well in dry conditions.","zh":"这些植物在干燥环境中生长良好。"}]},{"pos":"n.","meaning":"前提；条款","definition":"a requirement that must be met","examples":[{"en":"The loan has one important condition.","zh":"这笔贷款有一个重要条件。"},{"en":"You may use the room on condition that you leave it clean.","zh":"你可以使用房间，条件是离开时保持干净。"}]},{"pos":"v.","meaning":"使习惯于；训练","definition":"to train someone to respond in a certain way","examples":[{"en":"Repeated practice conditions the body for longer exercise.","zh":"反复练习使身体适应更长时间的运动。"},{"en":"The animals were conditioned to respond to a signal.","zh":"这些动物经过训练，学会了对信号作出反应。"}]},{"pos":"v.","meaning":"影响；制约","definition":"to shape or determine something","examples":[{"en":"Our choices are conditioned by past experience.","zh":"我们的选择受到过往经历的影响。"},{"en":"Local geography conditions the design of the roads.","zh":"当地地理条件制约着道路设计。"}]}],"conditioner":[{"pos":"n.","meaning":"护发素","definition":"a product used to make hair softer and easier to manage","examples":[{"en":"Apply conditioner after washing your hair.","zh":"洗发后使用护发素。"},{"en":"This conditioner is intended for dry hair.","zh":"这种护发素适用于干性发质。"}]},{"pos":"n.","meaning":"调节剂；调节装置","definition":"a substance or device that improves or controls a condition","examples":[{"en":"The gardener added soil conditioner to the flower bed.","zh":"园丁向花坛加入了土壤调理剂。"},{"en":"The air conditioner kept the room cool.","zh":"空调使房间保持凉爽。"}]}],"condone":[{"pos":"v.","meaning":"容忍；纵容；宽恕","definition":"to accept or overlook behaviour considered wrong","examples":[{"en":"The school does not condone bullying.","zh":"学校不容忍欺凌。"},{"en":"Understanding the motive does not mean condoning the action.","zh":"理解动机并不意味着纵容行为。"}]}],"conduce":[{"pos":"v.","meaning":"有助于；导致","definition":"to help bring about a result","examples":[{"en":"A quiet environment conduces to careful thought.","zh":"安静的环境有助于认真思考。"},{"en":"Clear rules can conduce to better cooperation.","zh":"清楚的规则能够促进更好的合作。"}]}],"conduct":[{"pos":"n.","meaning":"行为；举止","definition":"the way someone behaves","examples":[{"en":"The school has a clear code of conduct.","zh":"学校有明确的行为准则。"},{"en":"Her conduct during the crisis was admirable.","zh":"她在危机期间的举止令人钦佩。"}],"ipa":"/ˈkɒndʌkt/"},{"pos":"n.","meaning":"管理；实施","definition":"the way an activity is organized and carried out","examples":[{"en":"The inquiry examined the conduct of the election.","zh":"调查审查了选举的实施过程。"},{"en":"He is responsible for the conduct of the study.","zh":"他负责这项研究的实施。"}],"ipa":"/ˈkɒndʌkt/"},{"pos":"v.","meaning":"组织；实施；进行","definition":"to organize or carry out an activity","examples":[{"en":"The team will conduct interviews next week.","zh":"团队下周将进行访谈。"},{"en":"Scientists conduct the experiment under controlled conditions.","zh":"科学家在受控条件下开展实验。"}],"ipa":"/kənˈdʌkt/"},{"pos":"v.","meaning":"指挥；引导","definition":"to direct musicians or guide someone","examples":[{"en":"She will conduct the orchestra tonight.","zh":"她今晚将指挥管弦乐团。"},{"en":"A guide conducted the visitors through the building.","zh":"一位导游带领游客参观了大楼。"}],"ipa":"/kənˈdʌkt/"}],"conductive":[{"pos":"adj.","meaning":"导电的；导热的","definition":"able to transmit electricity or heat","examples":[{"en":"Copper is highly conductive.","zh":"铜的导电性很强。"},{"en":"The experiment compares conductive and insulating materials.","zh":"实验比较导电材料与绝缘材料。"}]}],"conference":[{"pos":"n.","meaning":"会议；大会","definition":"a formal meeting for discussion","examples":[{"en":"The conference brings together researchers from several countries.","zh":"会议汇集了来自多个国家的研究人员。"},{"en":"She presented her findings at a medical conference.","zh":"她在医学会议上介绍了自己的研究发现。"}]}],"confidence":[{"pos":"n.","meaning":"信心；自信","definition":"belief in one's ability or in a positive outcome","examples":[{"en":"Practice helped her gain confidence.","zh":"练习帮助她建立了信心。"},{"en":"He spoke with confidence during the interview.","zh":"他在面试中自信地发言。"}]},{"pos":"n.","meaning":"信任；信赖","definition":"trust in someone or something","examples":[{"en":"The public has confidence in the rescue team.","zh":"公众信任救援队。"},{"en":"The incident damaged confidence in the system.","zh":"这起事件损害了人们对系统的信任。"}]}],"configuration":[{"pos":"n.","meaning":"配置；排列；结构","definition":"the arrangement of parts in a system","examples":[{"en":"The room has a flexible seating configuration.","zh":"房间的座位排列灵活。"},{"en":"Check the network configuration before connecting.","zh":"连接前检查网络配置。"}]},{"pos":"n.","meaning":"外形；轮廓","definition":"the overall shape or form of something","examples":[{"en":"The map shows the configuration of the coastline.","zh":"地图显示了海岸线的轮廓。"},{"en":"The unusual configuration of the rocks attracted attention.","zh":"岩石独特的形状引起了注意。"}]}],"confine":[{"pos":"v.","meaning":"限制；使局限于","definition":"to keep something within particular limits","examples":[{"en":"Please confine your answer to the main issue.","zh":"请把回答限定在主要问题上。"},{"en":"The study was confined to three coastal towns.","zh":"研究范围限于三个沿海城镇。"}]},{"pos":"v.","meaning":"禁闭；使不能离开","definition":"to prevent someone from leaving a place","examples":[{"en":"The injury confined him to bed for several days.","zh":"伤势使他卧床数日。"},{"en":"The rescued animals were confined to a secure enclosure.","zh":"获救动物暂时被安置在安全围栏内，不得外出。"}]},{"pos":"n.","meaning":"界限；范围（常用复数 confines）","definition":"the boundaries of an area or activity","examples":[{"en":"The question lies outside the confines of this study.","zh":"这个问题超出了本研究的范围。"},{"en":"They worked within the confines of a very small office.","zh":"他们在一间十分狭小的办公室范围内工作。"}]}],"confirm":[{"pos":"v.","meaning":"确认","definition":"to establish that something is correct or definite","examples":[{"en":"Please confirm that you received my application.","zh":"请确认你已收到我的申请。"},{"en":"Could you confirm the date of the appointment?","zh":"你能确认预约日期吗？"},{"en":"We will confirm your booking by email.","zh":"我们会通过邮件确认你的预订。"}]},{"pos":"v.","meaning":"批准;使正式生效","definition":"to formally approve an appointment or decision","examples":[{"en":"The board confirmed her appointment.","zh":"董事会批准了她的任命。"},{"en":"The court confirmed the earlier ruling.","zh":"法院维持了先前裁决。"}]}],"confirmation":[{"pos":"n.","meaning":"确认；证实","definition":"evidence or a message showing that something is true or settled","examples":[{"en":"You will receive confirmation by email.","zh":"你会通过电子邮件收到确认。"},{"en":"The test provided confirmation of the discovery.","zh":"检测证实了这个发现。"}]},{"pos":"n.","meaning":"正式批准；认可","definition":"formal approval of an appointment or arrangement","examples":[{"en":"The appointment requires parliamentary confirmation.","zh":"这项任命需要议会批准。"},{"en":"The agreement is awaiting official confirmation.","zh":"协议正在等待正式批准。"}]}],"conflict":[{"pos":"n.","meaning":"冲突；矛盾","definition":"a serious disagreement or incompatibility","examples":[{"en":"The proposal created a conflict between the two departments.","zh":"这项提议引发了两个部门之间的冲突。"},{"en":"There is a conflict between cost and quality.","zh":"成本与质量之间存在矛盾。"}],"ipa":"/ˈkɒnflɪkt/"},{"pos":"v.","meaning":"冲突；抵触","definition":"to be incompatible or disagree","examples":[{"en":"The meeting conflicts with my teaching schedule.","zh":"会议与我的授课安排冲突。"},{"en":"Their statements conflict with the recorded evidence.","zh":"他们的说法与记录的证据相抵触。"}],"ipa":"/kənˈflɪkt/"}],"conform":[{"pos":"v.","meaning":"遵守；服从；符合","definition":"to behave according to rules or match a standard","examples":[{"en":"All products must conform to safety standards.","zh":"所有产品都必须符合安全标准。"},{"en":"She refused to conform to unfair expectations.","zh":"她拒绝服从不公平的期望。"}]}],"conformity":[{"pos":"n.","meaning":"符合；一致；遵从","definition":"agreement with rules, standards, or common behaviour","examples":[{"en":"The design was checked for conformity with regulations.","zh":"设计接受检查，以确认符合规定。"},{"en":"The school values creativity rather than strict conformity.","zh":"学校重视创造力，而非一味遵从。"}]}],"confront":[{"pos":"v.","meaning":"面对；正视；遭遇","definition":"to face a difficult situation or person directly","examples":[{"en":"We must confront the shortage of trained staff.","zh":"我们必须正视受训员工短缺的问题。"},{"en":"Visitors are confronted by a steep climb at the entrance.","zh":"游客一到入口就面临陡峭的上坡路。"}]}],"confuse":[{"pos":"v.","meaning":"使困惑；使糊涂","definition":"to make someone unable to understand clearly","examples":[{"en":"The conflicting instructions confuse new staff.","zh":"相互矛盾的说明让新员工感到困惑。"},{"en":"Too many technical terms can confuse readers.","zh":"过多的技术术语可能使读者糊涂。"}]},{"pos":"v.","meaning":"混淆；认错","definition":"to mistake one thing for another","examples":[{"en":"Do not confuse price with value.","zh":"不要把价格和价值混为一谈。"},{"en":"I often confuse the twins' names.","zh":"我经常弄混这对双胞胎的名字。"}]}],"confusion":[{"pos":"n.","meaning":"困惑；糊涂","definition":"a state of not understanding clearly","examples":[{"en":"The conflicting signs caused confusion.","zh":"相互矛盾的标志引起了困惑。"},{"en":"She looked at the instructions in confusion.","zh":"她困惑地看着说明。"}]},{"pos":"n.","meaning":"混淆；误认","definition":"a failure to distinguish between different things","examples":[{"en":"Clear labels prevent confusion between the samples.","zh":"清晰标签可防止样本混淆。"},{"en":"There was confusion over the two similar names.","zh":"两个相似的名字引起了混淆。"}]},{"pos":"n.","meaning":"混乱；无序","definition":"a disorganised state","examples":[{"en":"The announcement threw the room into confusion.","zh":"公告使房间里陷入混乱。"},{"en":"During the confusion, several bags were misplaced.","zh":"混乱中，几个包被放错了地方。"}]}],"congested":[{"pos":"adj.","meaning":"拥堵的；充塞的","definition":"too full of traffic, people, or fluid","examples":[{"en":"The roads become congested during the evening rush hour.","zh":"晚高峰时道路变得拥堵。"},{"en":"The station was congested with holiday travellers.","zh":"车站挤满了假日旅客。"}]}],"congestion":[{"pos":"n.","meaning":"交通拥堵","definition":"a condition in which traffic cannot move freely","examples":[{"en":"Traffic congestion increases journey times.","zh":"交通拥堵增加出行时间。"},{"en":"A congestion charge may encourage people to use buses.","zh":"拥堵费可能鼓励人们乘公交。"},{"en":"Flexible working hours can reduce peak-time congestion.","zh":"弹性工时可以减少高峰期拥堵。"}]},{"pos":"n.","meaning":"充血;充塞;鼻塞","definition":"a build-up of blood, mucus, or fluid","examples":[{"en":"The cold caused nasal congestion.","zh":"感冒引起了鼻塞。"},{"en":"The examination revealed congestion in the lungs.","zh":"检查发现肺部淤积。"}]}],"congratulate":[{"pos":"v.","meaning":"祝贺","definition":"to express pleasure at someone's success","examples":[{"en":"I congratulated her on passing the exam.","zh":"我祝贺她通过考试。"},{"en":"The coach congratulated the whole team.","zh":"教练向全队表示祝贺。"}]}],"congress":[{"pos":"n.","meaning":"代表大会；国会","definition":"a formal assembly of representatives","examples":[{"en":"Scientists gathered for an international congress.","zh":"科学家们参加了国际大会。"},{"en":"The bill was debated in Congress.","zh":"这项法案在国会进行了辩论。"}]}],"conjunction":[{"pos":"n.","meaning":"结合；共同发生","definition":"a combination or occurrence together","examples":[{"en":"The programme runs in conjunction with local schools.","zh":"这个项目与当地学校联合开展。"},{"en":"A conjunction of favourable conditions made success possible.","zh":"多种有利条件的结合使成功成为可能。"}]},{"pos":"n.","meaning":"连词","definition":"a word that joins words, phrases, or clauses","examples":[{"en":"The word although is a conjunction.","zh":"although 是一个连词。"},{"en":"Choose a conjunction that expresses contrast.","zh":"选择一个表示转折的连词。"}]}],"connect":[{"pos":"v.","meaning":"连接；接通","definition":"to join things physically or electronically","examples":[{"en":"Connect the cable to the monitor.","zh":"把电缆接到显示器上。"},{"en":"Could you connect me to the accounts department?","zh":"你能把电话转接到财务部吗？"}]},{"pos":"v.","meaning":"联系；关联；联想","definition":"to establish or recognise a relationship","examples":[{"en":"The study connects diet with health outcomes.","zh":"研究把饮食与健康结果联系起来。"},{"en":"She connected the smell with memories of home.","zh":"她把这种气味与家乡的记忆联系起来。"}]},{"pos":"v.","meaning":"衔接；接续","definition":"to arrive in time for a further stage of travel","examples":[{"en":"The bus connects with the afternoon train.","zh":"这班公交与下午的火车衔接。"},{"en":"Passengers connect in Singapore before flying onward.","zh":"乘客在新加坡转机后继续飞行。"}]}],"connection":[{"pos":"n.","meaning":"连接；联系","definition":"a link between people, things, or ideas","examples":[{"en":"Check the connection between the cable and the screen.","zh":"检查电缆和屏幕之间的连接。"},{"en":"The study found a connection between sleep and memory.","zh":"研究发现睡眠与记忆之间存在联系。"}]}],"conquer":[{"pos":"v.","meaning":"征服；攻占；战胜","definition":"to defeat and take control by force","examples":[{"en":"The army failed to conquer the island.","zh":"军队未能攻占这座岛。"},{"en":"The empire sought to conquer neighbouring territories.","zh":"这个帝国试图征服邻近领土。"}]},{"pos":"v.","meaning":"克服；战胜困难","definition":"to overcome a problem or fear","examples":[{"en":"She worked hard to conquer her fear of public speaking.","zh":"她努力克服公开演讲的恐惧。"},{"en":"The climbers finally conquered the difficult route.","zh":"登山者终于征服了这条艰难路线。"}]}],"conquest":[{"pos":"n.","meaning":"征服；攻占","definition":"the act of taking control by force","examples":[{"en":"The book describes the conquest of the region.","zh":"书中描述了对该地区的征服。"},{"en":"The fortress resisted conquest for many years.","zh":"要塞抵抗了多年攻占。"}]},{"pos":"n.","meaning":"征服所得之地或成果","definition":"something gained through conquest or determined effort","examples":[{"en":"The empire struggled to govern its distant conquests.","zh":"帝国难以统治远方征服的领土。"},{"en":"The climbers celebrated their latest mountain conquest.","zh":"登山者庆祝最新的登顶成果。"}]}],"conscious":[{"pos":"adj.","meaning":"意识到的；自觉的","definition":"aware of something or deliberately chosen","examples":[{"en":"She was conscious of the need to speak clearly.","zh":"她意识到需要说清楚。"},{"en":"We made a conscious effort to reduce waste.","zh":"我们有意识地努力减少浪费。"}]},{"pos":"adj.","meaning":"神志清醒的","definition":"awake and able to notice what is happening","examples":[{"en":"The patient was conscious when the ambulance arrived.","zh":"救护车到达时，患者神志清醒。"},{"en":"He remained conscious throughout the examination.","zh":"检查期间，他一直保持清醒。"}]}],"consecutive":[{"pos":"adj.","meaning":"连续的；不间断的","definition":"following one after another without a gap","examples":[{"en":"It rained for five consecutive days.","zh":"雨连续下了五天。"},{"en":"The team won three consecutive matches.","zh":"球队连续赢了三场比赛。"}]}],"consensus":[{"pos":"n.","meaning":"共识；一致意见","definition":"general agreement among a group","examples":[{"en":"The committee reached a consensus.","zh":"委员会达成了共识。"},{"en":"There is a broad consensus on the need for change.","zh":"对于需要变革，人们有广泛共识。"}]}],"consequence":[{"pos":"n.","meaning":"后果；结果","definition":"a result of an action or situation","examples":[{"en":"One consequence of rising rents is longer commutes.","zh":"租金上涨的一个后果是通勤变长。"},{"en":"The policy had an unexpected consequence for small shops.","zh":"该政策给小商店带来了意外后果。"},{"en":"Poor health may be a consequence of inadequate housing.","zh":"健康不佳可能是住房条件不足的结果。"}]},{"pos":"n.","meaning":"重要性；重大意义","definition":"Importance or significance.","examples":[{"en":"The missing detail is of little consequence.","zh":"遗漏的细节并不重要。"},{"en":"She became a person of consequence in local affairs.","zh":"她成了当地事务中举足轻重的人物。"}]}],"consequent":[{"pos":"adj.","meaning":"随之发生的；作为结果的","definition":"happening as a result of something","examples":[{"en":"The factory closed, with consequent job losses.","zh":"工厂关闭，随之出现了岗位流失。"},{"en":"The storm and consequent flooding damaged the crops.","zh":"风暴及其引发的洪水损坏了庄稼。"}]}],"consequential":[{"pos":"adj.","meaning":"随之发生的；结果性的","definition":"resulting from an earlier event","examples":[{"en":"The closure caused consequential losses for suppliers.","zh":"关闭给供应商造成了随之而来的损失。"},{"en":"The report discusses the accident and its consequential effects.","zh":"报告讨论了事故及其后续影响。"}]},{"pos":"adj.","meaning":"重要的；影响重大的","definition":"having significant consequences","examples":[{"en":"It was a consequential decision for the city.","zh":"这是对城市影响重大的决定。"},{"en":"The researchers made a consequential discovery.","zh":"研究人员有了一项重要发现。"}]}],"consequently":[{"pos":"adv.","meaning":"因此；所以","definition":"as a result","examples":[{"en":"The bridge was damaged; consequently, buses were diverted.","zh":"桥梁受损，因此公交车改道了。"},{"en":"Demand fell, and consequently production slowed.","zh":"需求下降，生产因而放缓。"}]}],"conservation":[{"pos":"n.","meaning":"保护；节约","definition":"the protection and careful use of natural resources","examples":[{"en":"Wildlife conservation requires long-term funding.","zh":"野生动物保护需要长期资金支持。"},{"en":"Water conservation is essential during a drought.","zh":"干旱期间节约用水至关重要。"},{"en":"Local residents support the conservation of the forest.","zh":"当地居民支持保护这片森林。"}]}],"conservative":[{"pos":"adj.","meaning":"保守的；守旧的；传统的","definition":"preferring established practices and gradual change","examples":[{"en":"The organisation takes a conservative approach to reform.","zh":"这个组织对改革采取保守态度。"},{"en":"He comes from a conservative family.","zh":"他来自一个传统保守的家庭。"}]},{"pos":"adj.","meaning":"谨慎的；保守估计的","definition":"deliberately avoiding optimistic assumptions","examples":[{"en":"This is a conservative estimate of the cost.","zh":"这是对成本的保守估计。"},{"en":"The forecast uses conservative assumptions.","zh":"预测采用谨慎的假设。"}]},{"pos":"n.","meaning":"保守派；保守的人","definition":"a person favouring traditional values or limited change","examples":[{"en":"A conservative may prefer gradual reform.","zh":"保守者可能更倾向于渐进改革。"},{"en":"The debate included both conservatives and reformers.","zh":"辩论包括保守派和改革派。"}]}],"conserve":[{"pos":"v.","meaning":"保护；保存；节约","definition":"to protect something from loss or avoid wasting it","examples":[{"en":"The project aims to conserve the wetland habitat.","zh":"这个项目旨在保护湿地栖息地。"},{"en":"Turn off unused lights to conserve energy.","zh":"关掉不用的灯以节约能源。"}]}],"considerable":[{"pos":"adj.","meaning":"相当大的；可观的；重要的","definition":"large enough in amount or importance to be noticeable","examples":[{"en":"The repairs required considerable effort.","zh":"维修需要付出相当大的努力。"},{"en":"Her research has had considerable influence.","zh":"她的研究产生了重要影响。"}]}],"consideration":[{"pos":"n.","meaning":"考虑；思考","definition":"careful thought about something","examples":[{"en":"The proposal needs further consideration.","zh":"提案需要进一步考虑。"},{"en":"After careful consideration, she accepted the offer.","zh":"经过认真考虑，她接受了邀请。"}]},{"pos":"n.","meaning":"体谅；关心","definition":"care for the feelings or needs of others","examples":[{"en":"Please show consideration for your neighbours.","zh":"请体谅邻居。"},{"en":"He treated the newcomers with consideration.","zh":"他体贴地对待新来者。"}]},{"pos":"n.","meaning":"需要考虑的因素","definition":"a factor influencing a decision","examples":[{"en":"Cost is an important consideration.","zh":"成本是重要的考虑因素。"},{"en":"Safety considerations shaped the design.","zh":"安全因素影响了设计。"}]}],"consignment":[{"pos":"n.","meaning":"托运的货物","definition":"a quantity of goods sent to a person or place","examples":[{"en":"A consignment of books arrived at the school.","zh":"一批托运图书送到了学校。"},{"en":"The warehouse checked the consignment for damage.","zh":"仓库检查了这批货物是否损坏。"}]},{"pos":"n.","meaning":"托运；寄售；委托销售","definition":"the sending of goods or entrusting them for sale","examples":[{"en":"The paintings were offered to the gallery on consignment.","zh":"这些画交给了画廊寄售。"},{"en":"The documents record the consignment of equipment overseas.","zh":"文件记录了设备向海外托运的情况。"}]}],"consist":[{"pos":"v.","meaning":"由……组成","definition":"to be formed from specified parts","examples":[{"en":"The team consists of six researchers.","zh":"团队由六名研究人员组成。"},{"en":"The meal consisted mainly of rice and vegetables.","zh":"这顿饭主要由米饭和蔬菜组成。"}]},{"pos":"v.","meaning":"在于；存在于","definition":"to have a particular thing as its essential feature","examples":[{"en":"The difficulty consists in finding reliable data.","zh":"困难在于寻找可靠的数据。"},{"en":"True cooperation consists in sharing both work and responsibility.","zh":"真正的合作在于共同承担工作和责任。"}]}],"consistent":[{"pos":"adj.","meaning":"一致的；相符的","definition":"in agreement or without contradiction","examples":[{"en":"The results are consistent with the theory.","zh":"结果与理论相符。"},{"en":"Her account remained consistent throughout the interview.","zh":"她在整个访谈中的陈述始终一致。"}]},{"pos":"adj.","meaning":"始终如一的；稳定的","definition":"maintaining the same standard over time","examples":[{"en":"The team needs more consistent performance.","zh":"团队需要更稳定的表现。"},{"en":"Consistent practice improves fluency.","zh":"持续规律的练习能提高流利程度。"}]}],"consolation":[{"pos":"n.","meaning":"安慰；慰藉","definition":"comfort after loss or disappointment","examples":[{"en":"Her friends' support was a great consolation.","zh":"朋友们的支持给了她很大安慰。"},{"en":"He took consolation in knowing that the work had helped others.","zh":"知道自己的工作帮助了别人，他感到欣慰。"}]}],"consolidation":[{"pos":"n.","meaning":"合并；整合","definition":"the process of combining separate things into a whole","examples":[{"en":"The consolidation of several offices reduced costs.","zh":"几个办公室的合并降低了成本。"},{"en":"Data consolidation made the records easier to search.","zh":"数据整合使记录更容易搜索。"}]},{"pos":"n.","meaning":"巩固；加强","definition":"the process of making something stronger or more secure","examples":[{"en":"The next phase involves consolidation of earlier gains.","zh":"下一阶段涉及巩固此前取得的成果。"},{"en":"Regular practice supports the consolidation of new skills.","zh":"经常练习有助于巩固新技能。"}]}],"consortium":[{"pos":"n.","meaning":"财团；联合体；联盟","definition":"a group of organisations cooperating on a project","examples":[{"en":"A consortium of banks funded the project.","zh":"一个银行财团为项目提供了资金。"},{"en":"The universities formed a research consortium.","zh":"这些大学组成了研究联盟。"}]}],"constant":[{"pos":"adj.","meaning":"不断的；频繁的","definition":"happening repeatedly or continuously","examples":[{"en":"The constant noise made it hard to study.","zh":"持续的噪声让人难以学习。"},{"en":"The device needs constant monitoring.","zh":"这台设备需要持续监测。"}]},{"pos":"adj.","meaning":"不变的；稳定的；忠实的","definition":"remaining the same or dependable","examples":[{"en":"The temperature remained constant throughout the experiment.","zh":"整个实验过程中温度保持不变。"},{"en":"She has been a constant friend during difficult times.","zh":"在困难时期，她一直是可靠的朋友。"}]},{"pos":"n.","meaning":"常数；恒量","definition":"a quantity that does not change","examples":[{"en":"The equation contains a constant and two variables.","zh":"方程含有一个常数和两个变量。"},{"en":"The speed limit is treated as a constant in the model.","zh":"模型把速度限制视为恒量。"}]}],"constantly":[{"pos":"adv.","meaning":"不断地；经常地","definition":"all the time or very frequently","examples":[{"en":"The temperature is constantly monitored.","zh":"温度受到持续监测。"},{"en":"She is constantly looking for ways to improve.","zh":"她总在寻找改进方法。"}]}],"constituent":[{"pos":"n.","meaning":"组成部分；成分；要素","definition":"one of the parts forming a whole","examples":[{"en":"Water is a major constituent of living cells.","zh":"水是活细胞的主要组成部分。"},{"en":"The analysis identified the material's constituents.","zh":"分析确定了材料的各个成分。"}]},{"pos":"n.","meaning":"选民；选区居民","definition":"a person represented by an elected official","examples":[{"en":"The representative met several constituents.","zh":"这位代表会见了几位选民。"},{"en":"Constituents wrote to ask for better transport.","zh":"选区居民来信要求改善交通。"}]},{"pos":"adj.","meaning":"组成的","definition":"forming part of a larger whole","examples":[{"en":"The machine was separated into its constituent parts.","zh":"机器被拆成了组成部件。"},{"en":"Each constituent organisation has a vote.","zh":"每个组成机构都有一票。"}]},{"pos":"adj.","meaning":"制宪的","definition":"having the power to establish or revise a constitution","examples":[{"en":"A constituent assembly drafted the constitution.","zh":"制宪会议起草了宪法。"},{"en":"The constituent body debated the proposed framework.","zh":"制宪机构讨论了拟议框架。"}]}],"constitute":[{"pos":"v.","meaning":"构成；组成","definition":"to form or make up something","examples":[{"en":"Volunteers constitute half of the project team.","zh":"志愿者占项目团队的一半。"},{"en":"These findings constitute strong evidence for the theory.","zh":"这些发现构成了支持该理论的有力证据。"}]},{"pos":"v.","meaning":"设立；组成机构","definition":"to establish an organization formally","examples":[{"en":"A panel was constituted to review the complaints.","zh":"一个小组被正式设立来审查投诉。"},{"en":"The members voted to constitute a new advisory body.","zh":"成员投票决定成立新的咨询机构。"}]}],"constitution":[{"pos":"n.","meaning":"宪法；章程","definition":"the fundamental rules governing a state or organization","examples":[{"en":"The constitution protects freedom of expression.","zh":"宪法保障言论自由。"},{"en":"Members voted to amend the club's constitution.","zh":"会员投票修改了俱乐部章程。"}]},{"pos":"n.","meaning":"体质；体格","definition":"the physical condition and general health of a person","examples":[{"en":"He has a strong constitution.","zh":"他的体质很好。"},{"en":"The illness tested her normally robust constitution.","zh":"这场病考验了她一贯强健的体质。"}]},{"pos":"n.","meaning":"组成；构成","definition":"the structure or composition of something","examples":[{"en":"The chemical constitution of the material was analysed.","zh":"研究人员分析了这种材料的化学组成。"},{"en":"The committee's constitution changed after the election.","zh":"选举后委员会的组成发生了变化。"}]}],"constrain":[{"pos":"v.","meaning":"限制；约束","definition":"to restrict what someone or something can do","examples":[{"en":"Limited space constrains the design.","zh":"空间有限制约了设计。"},{"en":"The budget constrained our choice of materials.","zh":"预算限制了我们对材料的选择。"}]},{"pos":"v.","meaning":"迫使；强使","definition":"to force someone to act in a particular way","examples":[{"en":"Circumstances constrained them to postpone the journey.","zh":"形势迫使他们推迟旅程。"},{"en":"She felt constrained to accept the decision.","zh":"她觉得不得不接受这一决定。"}]}],"construct":[{"pos":"v.","meaning":"建造；构建；构思","definition":"to build something physical or develop an idea","examples":[{"en":"Workers constructed a temporary bridge over the stream.","zh":"工人在溪流上搭建了一座临时桥。"},{"en":"Students learned to construct a clear argument.","zh":"学生们学习构建清晰的论证。"}],"ipa":"/kənˈstrʌkt/"},{"pos":"n.","meaning":"构想；概念结构","definition":"an idea created to explain or organize experience","examples":[{"en":"The researchers treated motivation as a psychological construct.","zh":"研究人员把动机视为一个心理学构念。"},{"en":"The categories are social constructs rather than fixed natural divisions.","zh":"这些类别是社会构建的概念，而非固定的自然分界。"}],"ipa":"/ˈkɒnstrʌkt/"}],"construction":[{"pos":"n.","meaning":"建造；施工","definition":"the process of building something","examples":[{"en":"Construction of the new station begins in May.","zh":"新车站将于五月开始施工。"},{"en":"The building is still under construction.","zh":"这栋建筑仍在施工。"}]},{"pos":"n.","meaning":"建筑物；结构","definition":"something built or the way it is put together","examples":[{"en":"The bridge is a complex steel construction.","zh":"这座桥是一个复杂的钢结构。"},{"en":"The chair's sturdy construction makes it durable.","zh":"这把椅子构造坚固，因此很耐用。"}]}],"consulate":[{"pos":"n.","meaning":"领事馆","definition":"the office of a consul in a foreign country","examples":[{"en":"She contacted the consulate about her lost passport.","zh":"她就丢失护照联系了领事馆。"},{"en":"The consulate is closed on public holidays.","zh":"领事馆在公共假日关闭。"}]},{"pos":"n.","meaning":"领事职位；领事任期","definition":"the office or period of service of a consul","examples":[{"en":"The archive records the beginning of his consulate.","zh":"档案记载了他领事任期的开始。"},{"en":"During her consulate, trade links expanded.","zh":"在她担任领事期间，贸易联系扩大了。"}]}],"consult":[{"pos":"v.","meaning":"咨询；请教","definition":"to seek advice from someone","examples":[{"en":"Consult the supervisor before changing the method.","zh":"改变方法前请先咨询导师。"},{"en":"They consulted local residents about the new park.","zh":"他们就新公园征求了当地居民的意见。"}]},{"pos":"v.","meaning":"查阅","definition":"to look at a source for information","examples":[{"en":"Consult the timetable for the last departure.","zh":"请查阅时刻表，了解末班车的发车时间。"},{"en":"She consulted several dictionaries while translating the text.","zh":"翻译文章时，她查阅了几本词典。"}]},{"pos":"v.","meaning":"商议","definition":"to discuss something before deciding","examples":[{"en":"The partners consulted before signing the contract.","zh":"合伙人在签合同前进行了商议。"},{"en":"We need to consult with the design team.","zh":"我们需要与设计团队商议。"}]}],"consultant":[{"pos":"n.","meaning":"顾问","definition":"a person who gives expert advice professionally","examples":[{"en":"The company hired a consultant to review its strategy.","zh":"公司聘请了一位顾问审查战略。"},{"en":"An environmental consultant assessed the site.","zh":"一位环境顾问评估了场地。"}]},{"pos":"n.","meaning":"专科顾问医生（英）","definition":"a senior hospital doctor specializing in a field","examples":[{"en":"Her doctor referred her to a consultant.","zh":"她的医生将她转诊给了一位专科医生。"},{"en":"The consultant discussed the results with the patient.","zh":"专科医生与患者讨论了检查结果。"}]}],"consume":[{"pos":"v.","meaning":"消耗；耗费","definition":"to use a resource such as energy or time","examples":[{"en":"Older refrigerators often consume more electricity.","zh":"旧式冰箱通常更耗电。"},{"en":"The repairs will consume most of our available budget.","zh":"维修将耗去我们大部分可用预算。"}]},{"pos":"v.","meaning":"吃；喝；摄入","definition":"to eat or drink something","examples":[{"en":"Many people consume too much salt without noticing it.","zh":"许多人在不知不觉中摄入了过多的盐。"},{"en":"The survey asked how often participants consume fresh fruit.","zh":"该调查询问参与者多久吃一次新鲜水果。"}]},{"pos":"v.","meaning":"使充满强烈感情；使沉浸于","definition":"to fill a person with a strong feeling that takes all their attention","examples":[{"en":"Fear can consume a person who has no one to talk to.","zh":"无人倾诉的人可能被恐惧完全占据。"},{"en":"She refused to let anger consume her after the argument.","zh":"争吵之后，她不让愤怒完全控制自己。"}]}],"consumer":[{"pos":"n.","meaning":"消费者；用户","definition":"a person who buys or uses goods or services","examples":[{"en":"Consumers can compare prices online.","zh":"消费者可以在线比较价格。"},{"en":"The regulation aims to protect the consumer.","zh":"法规旨在保护消费者。"}]}],"consumption":[{"pos":"n.","meaning":"消耗；消费","definition":"the use of goods or resources","examples":[{"en":"Better insulation reduces energy consumption.","zh":"更好的隔热能减少能源消耗。"},{"en":"The government wants to limit plastic consumption.","zh":"政府希望限制塑料消费。"},{"en":"Water consumption rises during hot weather.","zh":"炎热天气期间用水量上升。"}]}],"contact":[{"pos":"n.","meaning":"接触；碰触","definition":"the state of physically touching","examples":[{"en":"Avoid direct contact with the hot surface.","zh":"避免直接接触高温表面。"},{"en":"The wire lost contact with the terminal.","zh":"电线与接线端失去了接触。"}]},{"pos":"n.","meaning":"联系；往来","definition":"communication or a connection with someone","examples":[{"en":"We have kept in contact since university.","zh":"大学毕业后我们一直保持联系。"},{"en":"The charity put her in contact with a local adviser.","zh":"慈善机构帮她联系了一位当地顾问。"}]},{"pos":"v.","meaning":"联系；联络","definition":"to communicate with someone","examples":[{"en":"Please contact the office for further information.","zh":"如需更多信息，请联系办公室。"},{"en":"She contacted the supplier about the delay.","zh":"她就延误问题联系了供应商。"}]}],"contain":[{"pos":"v.","meaning":"含有；容纳；装有","definition":"to have something inside or as part of a whole","examples":[{"en":"The box contains six glass bottles.","zh":"盒子里装着六个玻璃瓶。"},{"en":"The report contains useful statistics.","zh":"报告包含有用的统计数据。"}]},{"pos":"v.","meaning":"控制；遏制；阻止蔓延","definition":"to keep something within limits","examples":[{"en":"Firefighters worked to contain the fire.","zh":"消防员努力控制火势。"},{"en":"The measures helped contain the spread of the problem.","zh":"措施有助于遏制问题蔓延。"}]}],"contaminate":[{"pos":"v.","meaning":"污染；使不纯","definition":"to make something dirty or unsafe by adding harmful material","examples":[{"en":"The leak could contaminate the nearby stream.","zh":"泄漏可能污染附近的溪流。"},{"en":"Clean gloves prevent handlers from contaminating the samples.","zh":"干净的手套防止操作人员污染样本。"}]}],"contemplate":[{"pos":"v.","meaning":"考虑；深思","definition":"to think carefully about something","examples":[{"en":"We need time to contemplate the proposal.","zh":"我们需要时间仔细考虑这项提议。"},{"en":"He sat quietly, contemplating his future.","zh":"他静静坐着，思考自己的未来。"}]},{"pos":"v.","meaning":"凝视；注视","definition":"to look at something thoughtfully","examples":[{"en":"She paused to contemplate the painting.","zh":"她停下来凝视那幅画。"},{"en":"He stood at the window contemplating the dark sea.","zh":"他站在窗边凝望漆黑的大海。"}]},{"pos":"v.","meaning":"打算；预期","definition":"to consider doing something or imagine a possibility","examples":[{"en":"They are contemplating a move to another city.","zh":"他们正在考虑搬到另一座城市。"},{"en":"No one wanted to contemplate another failure.","zh":"没有人愿意设想再次失败。"}]}],"contemporary":[{"pos":"adj.","meaning":"当代的；现代的","definition":"belonging to the present time","examples":[{"en":"The gallery exhibits contemporary art.","zh":"画廊展出当代艺术。"},{"en":"The book examines contemporary social issues.","zh":"书中考察当代社会问题。"}]},{"pos":"adj.","meaning":"同时代的","definition":"existing at the same time as something else","examples":[{"en":"The two writers were contemporary figures.","zh":"这两位作家是同时代的人物。"},{"en":"Contemporary records describe the storm.","zh":"当时的记录描述了这场风暴。"}]},{"pos":"n.","meaning":"同代人；同辈","definition":"a person living at the same time or of a similar age","examples":[{"en":"She was respected by her contemporaries.","zh":"她受到同代人的尊敬。"},{"en":"His contemporaries took very different approaches.","zh":"他的同辈采取了截然不同的方法。"}]}],"contempt":[{"pos":"n.","meaning":"轻蔑；鄙视；不尊重","definition":"a strong feeling that someone or something is unworthy","examples":[{"en":"He spoke with contempt about the dishonest proposal.","zh":"他以轻蔑的口吻谈论那项不诚实的提议。"},{"en":"Ignoring the order showed contempt for the court.","zh":"无视这项命令表明了对法庭的蔑视。"}]}],"content":[{"pos":"n.","meaning":"内容；所含之物","definition":"the information or material contained in something","examples":[{"en":"The course content is updated every year.","zh":"课程内容每年更新。"},{"en":"Check the contents of the parcel before signing.","zh":"签收前请检查包裹内的物品。"}],"ipa":"/ˈkɒntent/"},{"pos":"n.","meaning":"含量","definition":"the amount of a substance contained in something","examples":[{"en":"The drink has a high sugar content.","zh":"这种饮料的含糖量很高。"},{"en":"The test measures the water content of the soil.","zh":"这项测试测量土壤的含水量。"}],"ipa":"/ˈkɒntent/"},{"pos":"n.","meaning":"满足；满意（常见于固定表达）","definition":"a state of satisfaction","examples":[{"en":"The children played to their hearts' content.","zh":"孩子们尽情玩耍。"},{"en":"She could browse the shelves to her heart's content.","zh":"她可以尽情浏览书架上的书。"}],"ipa":"/kənˈtent/"},{"pos":"adj.","meaning":"满意的；知足的","definition":"satisfied with what one has or with a situation","examples":[{"en":"He is content with his present job.","zh":"他对目前的工作很满意。"},{"en":"She seemed content to stay at home.","zh":"她似乎很愿意待在家里。"}],"ipa":"/kənˈtent/"},{"pos":"v.","meaning":"使满足；使满意","definition":"to satisfy someone","examples":[{"en":"A brief explanation did not content the committee.","zh":"简短的解释未能使委员会满意。"},{"en":"We had to content ourselves with a short visit.","zh":"我们只能满足于一次短暂拜访。"}],"ipa":"/kənˈtent/"}],"context":[{"pos":"n.","meaning":"上下文；语境","definition":"the surrounding words that help explain meaning","examples":[{"en":"The meaning becomes clear in context.","zh":"放在上下文中，意思就清楚了。"},{"en":"Do not quote the sentence out of context.","zh":"不要断章取义地引用这句话。"}]},{"pos":"n.","meaning":"背景；环境","definition":"the circumstances in which something happens","examples":[{"en":"The event must be understood in its historical context.","zh":"必须在历史背景中理解这个事件。"},{"en":"The report explains the social context of the change.","zh":"报告解释了变化的社会背景。"}]}],"continent":[{"pos":"n.","meaning":"洲；大陆","definition":"one of the Earth's large land masses","examples":[{"en":"The project involves researchers from every inhabited continent.","zh":"这个项目有来自每个有人居住大洲的研究人员参与。"},{"en":"A narrow sea separates the island from the continent.","zh":"一片狭窄海域把岛屿与大陆隔开。"}]}],"continental":[{"pos":"adj.","meaning":"大陆的；大陆性的","definition":"relating to a continent","examples":[{"en":"The species occurs across the continental landmass.","zh":"这个物种分布在整片大陆上。"},{"en":"The region has a continental climate with cold winters.","zh":"这个地区属大陆性气候，冬季寒冷。"}]},{"pos":"adj.","meaning":"欧洲大陆的","definition":"relating to mainland Europe, especially from a British viewpoint","examples":[{"en":"The shop sells continental cheeses.","zh":"这家店销售欧洲大陆的奶酪。"},{"en":"She travelled through several continental countries.","zh":"她游历了几个欧洲大陆国家。"}]},{"pos":"n.","meaning":"欧洲大陆人（旧式英式用法）","definition":"a person from mainland Europe","examples":[{"en":"In the old memoir, the visitor is described as a continental.","zh":"在那部旧回忆录中，访客被称作欧洲大陆人。"},{"en":"The novel contrasts an English traveller with a continental.","zh":"小说对比了一位英国旅行者和一位欧洲大陆人。"}]}],"contingency":[{"pos":"n.","meaning":"可能发生的意外；突发情况","definition":"a possible future event that may require action","examples":[{"en":"The team prepared for every contingency.","zh":"团队为各种可能的意外作了准备。"},{"en":"We need a contingency plan in case of rain.","zh":"我们需要一个应对下雨的应急计划。"}]},{"pos":"n.","meaning":"偶然性；依赖条件而发生的性质","definition":"the quality of being uncertain or dependent on conditions","examples":[{"en":"The essay explores contingency in historical events.","zh":"文章探讨历史事件中的偶然性。"},{"en":"The plan recognises the contingency of future demand.","zh":"计划考虑到了未来需求的不确定性。"}]}],"continually":[{"pos":"adv.","meaning":"不断地；反复地","definition":"repeatedly over a period of time","examples":[{"en":"The programme is continually updated with new information.","zh":"这个节目不断更新信息。"},{"en":"He continually interrupted the discussion.","zh":"他反复打断讨论。"}]}],"continuity":[{"pos":"n.","meaning":"连续性；持续性","definition":"the state of continuing without interruption","examples":[{"en":"The service provides continuity of care.","zh":"这项服务提供持续的照护。"},{"en":"Frequent staff changes can disrupt continuity.","zh":"人员频繁变动可能破坏工作的连续性。"}]}],"continuous":[{"pos":"adj.","meaning":"连续的；不间断的","definition":"continuing without stopping","examples":[{"en":"The machine requires a continuous supply of water.","zh":"机器需要不间断供水。"},{"en":"Continuous noise made concentration difficult.","zh":"持续的噪声使人难以集中注意力。"}]}],"contract":[{"pos":"n.","meaning":"合同","definition":"a formal agreement between people or organisations","examples":[{"en":"Read your employment contract before accepting the job.","zh":"接受工作前请阅读劳动合同。"},{"en":"My contract includes twenty days of annual leave.","zh":"我的合同包含二十天年假。"},{"en":"Both parties must sign the contract.","zh":"双方必须签署合同。"}],"ipa":"/ˈkɒntrækt/"},{"pos":"v.","meaning":"收缩；缩小","definition":"To become or make smaller.","examples":[{"en":"Metal contracts as it cools.","zh":"金属冷却时收缩。"},{"en":"The local economy contracted after the closures.","zh":"工厂关闭后，当地经济萎缩了。"}],"ipa":"/kənˈtrækt/"},{"pos":"v.","meaning":"签约；订立合同","definition":"To make a formal agreement to provide or receive something.","examples":[{"en":"The company contracted to supply the equipment.","zh":"公司签约供应设备。"},{"en":"We contracted with a local builder for the repairs.","zh":"我们与当地建筑商签订了维修合同。"}],"ipa":"/kənˈtrækt/"}],"contradict":[{"pos":"v.","meaning":"反驳；否认某人的话","definition":"to say that a statement is wrong","examples":[{"en":"She did not wish to contradict her colleague in public.","zh":"她不想当众反驳同事。"},{"en":"The witness contradicted the earlier account.","zh":"证人否认了先前的说法。"}]},{"pos":"v.","meaning":"相矛盾；相抵触","definition":"to be inconsistent with something","examples":[{"en":"The new evidence contradicts our original theory.","zh":"新证据与我们最初的理论相矛盾。"},{"en":"His actions contradict his promises.","zh":"他的行为与承诺相抵触。"}]}],"contradiction":[{"pos":"n.","meaning":"矛盾；不一致","definition":"a conflict between statements or facts","examples":[{"en":"There is a contradiction between the two accounts.","zh":"两份叙述之间有矛盾。"},{"en":"The result stands in contradiction to the prediction.","zh":"结果与预测相矛盾。"}]},{"pos":"n.","meaning":"反驳；否认","definition":"a statement opposing another statement","examples":[{"en":"His claim met an immediate contradiction.","zh":"他的说法立即遭到反驳。"},{"en":"She would not tolerate contradiction.","zh":"她不容许别人反驳。"}]}],"contrary":[{"pos":"adj.","meaning":"相反的；相违背的","definition":"opposite in nature or direction","examples":[{"en":"The evidence points to a contrary conclusion.","zh":"证据指向相反的结论。"},{"en":"Her actions were contrary to the agreement.","zh":"她的行为违背了协议。"}]},{"pos":"n.","meaning":"相反的情况","definition":"the opposite of what has been stated","examples":[{"en":"I am not disappointed; on the contrary, I am relieved.","zh":"我并不失望，恰恰相反，我松了一口气。"},{"en":"There is no evidence to the contrary.","zh":"没有相反的证据。"}]}],"contrast":[{"pos":"n.","meaning":"对比；差异","definition":"a noticeable difference between things","examples":[{"en":"There is a striking contrast between the two designs.","zh":"这两种设计之间有鲜明差异。"},{"en":"In contrast to last year, this summer was very wet.","zh":"与去年相反，今年夏天雨水很多。"}],"ipa":"/ˈkɒntrɑːst/"},{"pos":"v.","meaning":"比较不同之处","definition":"to compare things in order to show differences","examples":[{"en":"The essay contrasts urban and rural life.","zh":"这篇文章对比了城市和乡村生活。"},{"en":"We contrasted the results from the two groups.","zh":"我们对比了两组的结果。"}],"ipa":"/kənˈtrɑːst/"},{"pos":"v.","meaning":"形成对照；显出差异","definition":"to be noticeably different","examples":[{"en":"The dark roof contrasts with the white walls.","zh":"深色屋顶与白墙形成对照。"},{"en":"Her calm manner contrasts sharply with his excitement.","zh":"她的平静与他的兴奋形成鲜明对比。"}],"ipa":"/kənˈtrɑːst/"}],"contribute":[{"pos":"v.","meaning":"促成；贡献","definition":"to help bring about a result","examples":[{"en":"Regular exercise can contribute to better health.","zh":"经常锻炼有助于改善健康。"},{"en":"Several factors contribute to traffic congestion.","zh":"多个因素促成交通拥堵。"},{"en":"Volunteers contribute their time to local projects.","zh":"志愿者为当地项目贡献时间。"}]},{"pos":"v.","meaning":"捐助；捐赠","definition":"to give money, time, or resources to a shared purpose","examples":[{"en":"Local businesses contributed money to the project.","zh":"当地企业为项目捐了款。"},{"en":"Several families contributed food to the event.","zh":"几个家庭为活动捐赠了食物。"}]}],"contribute to":[{"pos":"phr.","meaning":"促成；有助于","definition":"to be one of the causes of a result","examples":[{"en":"Regular exercise can contribute to better sleep.","zh":"经常锻炼有助于改善睡眠。"},{"en":"Poor drainage may contribute to flooding after heavy rain.","zh":"排水不畅可能是暴雨后发生洪水的原因之一。"}]},{"pos":"phr.","meaning":"向……捐助；向……提供支持","definition":"to give money, time or resources to support something","examples":[{"en":"Local businesses contribute to the school breakfast programme.","zh":"当地企业资助学校早餐计划。"},{"en":"Anyone can contribute to the fund with a small donation.","zh":"任何人都可以通过小额捐款为该基金出力。"}]},{"pos":"phr.","meaning":"向……投稿","definition":"to write material for a publication","examples":[{"en":"She hopes to contribute to the college newspaper this term.","zh":"她希望这学期能给校报投稿。"},{"en":"Several scientists contribute to the magazine's monthly research column.","zh":"几位科学家为该杂志的每月研究专栏撰稿。"}]}],"contrive":[{"pos":"v.","meaning":"设法做到；筹划","definition":"to manage to do something, often with difficulty","examples":[{"en":"They contrived to finish the repairs before dark.","zh":"他们设法在天黑前完成了修理。"},{"en":"She contrived a way to visit without disrupting work.","zh":"她想出了一个既能拜访又不耽误工作的办法。"}]},{"pos":"v.","meaning":"设计；发明","definition":"to devise or create something cleverly","examples":[{"en":"The inventor contrived a simple water filter.","zh":"发明者设计了一个简单的滤水器。"},{"en":"They contrived a shelter from branches and old cloth.","zh":"他们用树枝和旧布搭出了一个掩蔽处。"}]}],"contrived":[{"pos":"adj.","meaning":"不自然的；刻意安排的","definition":"artificially arranged rather than natural or convincing","examples":[{"en":"The ending felt contrived.","zh":"这个结局显得很牵强。"},{"en":"The photograph's carefully contrived pose lacked warmth.","zh":"照片中精心摆出的姿势缺乏温暖感。"}]}],"controversial":[{"pos":"adj.","meaning":"有争议的；引起争论的","definition":"causing strong disagreement","examples":[{"en":"The proposal remains controversial.","zh":"提案仍有争议。"},{"en":"The newspaper published a controversial editorial.","zh":"报纸发表了一篇引起争论的社论。"}]}],"controversy":[{"pos":"n.","meaning":"争议；论战","definition":"a prolonged public disagreement","examples":[{"en":"The building proposal caused considerable controversy.","zh":"这项建设提议引起了很大争议。"},{"en":"The article examines the controversy surrounding the experiment.","zh":"文章研究了围绕该实验的争议。"}]}],"convection":[{"pos":"n.","meaning":"对流；通过流体运动传热","definition":"heat transfer caused by movement within a liquid or gas","examples":[{"en":"Convection carries warm air towards the ceiling.","zh":"对流将暖空气带向天花板。"},{"en":"The experiment shows convection in a tank of water.","zh":"这个实验展示水箱中的对流。"}]}],"convenience":[{"pos":"n.","meaning":"方便；便利","definition":"the quality of being easy or suitable to use","examples":[{"en":"Online booking offers considerable convenience.","zh":"在线预订提供了很大便利。"},{"en":"We chose the location for convenience.","zh":"我们为了方便选择了这个地点。"}]},{"pos":"n.","meaning":"便利设施；方便用品","definition":"something that makes life easier","examples":[{"en":"The apartment has all the modern conveniences.","zh":"公寓有各种现代便利设施。"},{"en":"A nearby shop is a useful convenience.","zh":"附近有商店是很有用的便利条件。"}]}],"convenient":[{"pos":"adj.","meaning":"方便的","definition":"suitable and easy to use","examples":[{"en":"Please suggest a convenient time for our meeting.","zh":"请提议一个方便开会的时间。"},{"en":"The station is in a convenient location.","zh":"车站的位置很方便。"},{"en":"Online booking is convenient for busy customers.","zh":"在线预订对忙碌的顾客很方便。"}]}],"convention":[{"pos":"n.","meaning":"大会；会议","definition":"a large formal meeting of people with shared interests","examples":[{"en":"The city hosted a convention for teachers.","zh":"这座城市举办了一场教师大会。"},{"en":"Delegates arrived for the annual convention.","zh":"代表们到达会场参加年会。"}]},{"pos":"n.","meaning":"惯例；习俗；常规","definition":"a widely accepted way of behaving or doing something","examples":[{"en":"By convention, the chair speaks last.","zh":"按照惯例，主席最后发言。"},{"en":"The artist challenged established conventions.","zh":"这位艺术家挑战了既有常规。"}]},{"pos":"n.","meaning":"公约；协定","definition":"a formal agreement between countries","examples":[{"en":"Several countries signed the environmental convention.","zh":"几个国家签署了环境公约。"},{"en":"The convention sets standards for protecting children.","zh":"这项公约规定了儿童保护标准。"}]}],"conventional":[{"pos":"adj.","meaning":"传统的；常规的；习惯的","definition":"following established or usual methods","examples":[{"en":"The design differs from conventional housing.","zh":"设计不同于传统住宅。"},{"en":"Conventional methods proved too slow.","zh":"常规方法被证明太慢。"}]},{"pos":"adj.","meaning":"守旧的；遵循习俗的","definition":"preferring socially accepted behaviour","examples":[{"en":"Their family has fairly conventional views.","zh":"他们家的观念比较传统。"},{"en":"He led a conventional life in the suburbs.","zh":"他在郊区过着循规蹈矩的生活。"}]}],"conversation":[{"pos":"n.","meaning":"谈话；交谈","definition":"an informal exchange of spoken ideas","examples":[{"en":"We had a long conversation about travel.","zh":"我们就旅行进行了一次长谈。"},{"en":"The noisy café made conversation difficult.","zh":"嘈杂的咖啡馆让交谈变得困难。"}]}],"converse":[{"pos":"v.","meaning":"交谈；谈话","definition":"to talk with someone","examples":[{"en":"She can converse comfortably in three languages.","zh":"她能流利地用三种语言交谈。"},{"en":"The guests continued to converse after dinner.","zh":"客人们饭后继续交谈。"}],"ipa":"/kənˈvɜːs/"},{"pos":"adj.","meaning":"相反的；逆向的","definition":"opposite in direction or relation","examples":[{"en":"The converse situation requires a different explanation.","zh":"相反的情况需要不同的解释。"},{"en":"We also tested the converse relationship.","zh":"我们也测试了逆向关系。"}],"ipa":"/ˈkɒnvɜːs/"},{"pos":"n.","meaning":"相反的情况；反面","definition":"the opposite of a statement or situation","examples":[{"en":"The converse is not necessarily true.","zh":"反过来并不一定成立。"},{"en":"Her experience was the converse of mine.","zh":"她的经历与我的情况相反。"}],"ipa":"/ˈkɒnvɜːs/"}],"conversely":[{"pos":"adv.","meaning":"相反地；反过来说","definition":"introducing an opposite or reversed situation","examples":[{"en":"High demand can raise prices; conversely, low demand can lower them.","zh":"高需求会推高价格；反之，低需求会压低价格。"},{"en":"The route is fast but costly; conversely, the bus is cheap but slow.","zh":"这条路线快但贵；相反，公交便宜但慢。"}]}],"conversion":[{"pos":"n.","meaning":"转变；改造；兑换","definition":"the process of changing from one form or use to another","examples":[{"en":"The conversion of the warehouse into flats took a year.","zh":"把仓库改造成公寓花了一年。"},{"en":"The bank charges a fee for currency conversion.","zh":"银行收取货币兑换手续费。"}]},{"pos":"n.","meaning":"改变信仰；皈依","definition":"a change to a different religion or belief","examples":[{"en":"Her memoir describes a gradual religious conversion.","zh":"她的回忆录描述了逐渐改变宗教信仰的过程。"},{"en":"The historian studied conversion in the region.","zh":"这位历史学家研究了该地区改变信仰的历史。"}]}],"convert":[{"pos":"v.","meaning":"转换；转化","definition":"to change from one form or use to another","examples":[{"en":"The device converts sunlight into electricity.","zh":"这个装置将阳光转化为电能。"},{"en":"We need to convert the measurements into metres.","zh":"我们需要把这些测量值换算成米。"}]},{"pos":"v.","meaning":"改装；改建","definition":"to change something so it can serve a new purpose","examples":[{"en":"They converted the barn into a small theatre.","zh":"他们把谷仓改建成了一个小剧院。"},{"en":"The bus was converted for wheelchair access.","zh":"这辆公交车经过改装，便于轮椅通行。"}]},{"pos":"v.","meaning":"改变信仰；说服接受新观念","definition":"to adopt or persuade someone to adopt a different belief","examples":[{"en":"He chose to convert to another religion.","zh":"他选择改信另一种宗教。"},{"en":"The experience converted her to the idea of car-free travel.","zh":"这次经历使她接受了不依赖汽车出行的理念。"}]}],"convey":[{"pos":"v.","meaning":"运送；输送","definition":"to transport something from one place to another","examples":[{"en":"Pipes convey water to the fields.","zh":"管道把水输送到田地。"},{"en":"The belt conveys packages through the warehouse.","zh":"传送带把包裹送过仓库。"}]},{"pos":"v.","meaning":"表达；传达","definition":"to communicate an idea or feeling","examples":[{"en":"The diagram conveys the main idea clearly.","zh":"图示清楚地传达了主要意思。"},{"en":"Her voice conveyed a sense of relief.","zh":"她的声音流露出宽慰。"}]}],"conviction":[{"pos":"n.","meaning":"定罪","definition":"a legal finding that someone is guilty","examples":[{"en":"The conviction was overturned after new evidence emerged.","zh":"新证据出现后，原来的定罪被撤销了。"},{"en":"The records include the date of the conviction.","zh":"记录包括定罪日期。"}]},{"pos":"n.","meaning":"坚定信念；确信","definition":"a strong belief or confidence","examples":[{"en":"She spoke with conviction about equal access to education.","zh":"她坚定地谈论平等受教育的机会。"},{"en":"His conviction that the work mattered kept him motivated.","zh":"他坚信这项工作有意义，这使他保持动力。"}]}],"convince":[{"pos":"v.","meaning":"使确信；说服","definition":"to make someone believe something or agree to act","examples":[{"en":"The evidence convinced the jury.","zh":"这些证据使陪审团信服。"},{"en":"She convinced him to apply for the course.","zh":"她说服他申请这门课程。"}]}],"cookery":[{"pos":"n.","meaning":"烹饪；烹调方法","definition":"the skill or practice of preparing food","examples":[{"en":"He enrolled in a cookery course.","zh":"他报名参加了烹饪课程。"},{"en":"The book introduces traditional regional cookery.","zh":"书中介绍传统地方烹饪。"}]}],"cooperate":[{"pos":"v.","meaning":"合作；协作","definition":"to work together towards a shared purpose","examples":[{"en":"The schools cooperated to organize the science fair.","zh":"几所学校合作举办了科学展。"},{"en":"Residents were asked to cooperate with the survey team.","zh":"居民被请求配合调查团队。"}]}],"cooperation":[{"pos":"n.","meaning":"合作；协作；配合","definition":"working together or helping willingly","examples":[{"en":"The project depends on international cooperation.","zh":"这个项目依赖国际合作。"},{"en":"Thank you for your cooperation during the repairs.","zh":"感谢你在维修期间的配合。"}]}],"cooperative":[{"pos":"adj.","meaning":"合作的；乐于协作的","definition":"willing to work together or help","examples":[{"en":"The staff were friendly and cooperative.","zh":"工作人员友好而乐于配合。"},{"en":"The task requires a cooperative approach.","zh":"任务需要合作的方式。"}]},{"pos":"adj.","meaning":"合作经营的","definition":"owned and managed jointly by its members","examples":[{"en":"They established a cooperative business.","zh":"他们建立了一家合作经营企业。"},{"en":"The farmers developed a cooperative marketing system.","zh":"农民建立了合作营销体系。"}]},{"pos":"n.","meaning":"合作社","definition":"an organisation owned and run by its members","examples":[{"en":"The cooperative sells local produce.","zh":"合作社出售当地农产品。"},{"en":"Each member has a vote in the cooperative.","zh":"每个社员在合作社里都有投票权。"}]}],"coordinate":[{"pos":"v.","meaning":"协调；统筹","definition":"to organize separate activities so they work together","examples":[{"en":"She coordinates transport for the visiting teams.","zh":"她协调来访团队的交通安排。"},{"en":"The two offices need to coordinate their schedules.","zh":"两个办公室需要协调日程。"}],"ipa":"/kəʊˈɔːdɪneɪt/"},{"pos":"n.","meaning":"坐标","definition":"a value locating a point in space","examples":[{"en":"Enter the coordinates of the campsite into the map.","zh":"把营地坐标输入地图。"},{"en":"The first coordinate gives the horizontal position.","zh":"第一个坐标给出水平位置。"}],"ipa":"/kəʊˈɔːdɪnət/"},{"pos":"adj.","meaning":"同等的；并列的","definition":"equal in rank or joined on the same level","examples":[{"en":"The sentence contains two coordinate clauses.","zh":"这个句子包含两个并列分句。"},{"en":"The agreement created coordinate branches of government.","zh":"协议设立了地位同等的政府分支。"}],"ipa":"/kəʊˈɔːdɪnət/"}],"coordinator":[{"pos":"n.","meaning":"协调者；统筹人员","definition":"someone who organizes people and activities so they work together","examples":[{"en":"The coordinator arranged the volunteers' schedules.","zh":"协调员安排了志愿者的时间表。"},{"en":"Contact the course coordinator if you need advice.","zh":"如果需要建议，请联系课程协调员。"}]}],"cope":[{"pos":"v.","meaning":"应付；处理；应对","definition":"to manage a difficult situation successfully","examples":[{"en":"She learned to cope with pressure.","zh":"她学会了应对压力。"},{"en":"The system can cope with increased demand.","zh":"系统能应对需求增长。"}]}],"coral":[{"pos":"n.","meaning":"珊瑚；珊瑚虫","definition":"small marine animals and the hard structures they form","examples":[{"en":"The divers observed coral without touching it.","zh":"潜水者观察珊瑚，但没有触碰它。"},{"en":"Warm seas support many species of coral.","zh":"温暖海域养育着许多种珊瑚。"}]},{"pos":"adj.","meaning":"珊瑚红的","definition":"having a pinkish-orange colour","examples":[{"en":"She chose a coral scarf for the performance.","zh":"她为演出选了一条珊瑚红围巾。"},{"en":"The room has pale coral walls.","zh":"房间的墙壁是浅珊瑚色的。"}]}],"cord":[{"pos":"n.","meaning":"绳；线；带","definition":"a strong thin rope or a flexible electrical cable","examples":[{"en":"Tie the parcel with a piece of cord.","zh":"用一段绳子把包裹扎好。"},{"en":"The power cord is too short to reach the socket.","zh":"电源线太短，够不到插座。"}]}],"core":[{"pos":"n.","meaning":"果核；果心","definition":"the central seed-containing part of a fruit","examples":[{"en":"He threw the apple core into the compost.","zh":"他把苹果核扔进堆肥。"},{"en":"Remove the core before slicing the pear.","zh":"切梨前去掉果核。"}]},{"pos":"n.","meaning":"中心；内核","definition":"the central part of an object","examples":[{"en":"The earth has a very hot core.","zh":"地球有一个非常热的内核。"},{"en":"The cable contains a copper core.","zh":"电缆内部有铜芯。"}]},{"pos":"n.","meaning":"核心；要点；精髓","definition":"the most important part of something","examples":[{"en":"Trust is at the core of the relationship.","zh":"信任是这段关系的核心。"},{"en":"The report identifies the core of the problem.","zh":"报告指出了问题的核心。"}]},{"pos":"v.","meaning":"去掉果核","definition":"to remove the central seed-containing part of a fruit","examples":[{"en":"Core the apples before baking.","zh":"烘烤前去掉苹果核。"},{"en":"She carefully cored each pear.","zh":"她仔细去掉每个梨的果核。"}]}],"cork":[{"pos":"n.","meaning":"软木；软木塞","definition":"a light bark material or a stopper made from it","examples":[{"en":"Remove the cork before pouring the juice.","zh":"倒果汁前先拔出软木塞。"},{"en":"The noticeboard is made from cork.","zh":"告示板是软木做的。"}]},{"pos":"v.","meaning":"用软木塞封住","definition":"to close a container with a cork","examples":[{"en":"Cork the bottle tightly before storing it.","zh":"存放瓶子前用软木塞塞紧。"},{"en":"The jars were corked and labelled.","zh":"罐子被塞上软木塞并贴好标签。"}]}],"corporal":[{"pos":"adj.","meaning":"身体的；肉体的","definition":"relating to the body","examples":[{"en":"The debate concerned the use of corporal punishment.","zh":"争论涉及体罚的使用。"},{"en":"The historical text distinguishes spiritual from corporal suffering.","zh":"这篇历史文献区分了精神痛苦和身体痛苦。"}]},{"pos":"n.","meaning":"下士","definition":"a military rank below sergeant in certain armed forces","examples":[{"en":"The corporal supervised the new recruits.","zh":"下士监督新兵训练。"},{"en":"She was promoted to corporal after completing the course.","zh":"完成课程后，她晋升为下士。"}]}],"corporate":[{"pos":"adj.","meaning":"公司的；法人的","definition":"relating to a company or legally recognised organisation","examples":[{"en":"The policy forms part of corporate strategy.","zh":"政策是公司战略的一部分。"},{"en":"The lawyer specialises in corporate law.","zh":"这名律师专攻公司法。"}]},{"pos":"adj.","meaning":"共同的；团体的","definition":"shared by members of a group","examples":[{"en":"The team accepted corporate responsibility for the decision.","zh":"团队共同承担了决定的责任。"},{"en":"The ceremony strengthened the organisation's corporate identity.","zh":"仪式增强了组织的共同认同。"}]}],"corps":[{"pos":"n.","meaning":"军团；部队；专业团体","definition":"an organized military or professional group","examples":[{"en":"The medical corps set up a field hospital.","zh":"医疗部队建立了一所野战医院。"},{"en":"She joined the diplomatic corps after university.","zh":"大学毕业后，她加入了外交使团。"}]}],"corpus":[{"pos":"n.","meaning":"文集；资料汇编","definition":"a collection of written works or records","examples":[{"en":"The scholar studied the author's entire corpus.","zh":"这位学者研究了该作者的全部作品。"},{"en":"The archive contains a large corpus of letters.","zh":"档案馆收藏了大量书信文献。"}]},{"pos":"n.","meaning":"语料库","definition":"a collection of language used for linguistic analysis","examples":[{"en":"The team built a corpus of spoken English.","zh":"团队建立了一个英语口语语料库。"},{"en":"Researchers searched the corpus for common phrases.","zh":"研究人员在语料库中搜索常用短语。"}]}],"correlation":[{"pos":"n.","meaning":"相关性；相互关系","definition":"a relationship in which two things vary together","examples":[{"en":"The study found a correlation between the variables.","zh":"研究发现变量之间存在相关性。"},{"en":"Correlation alone does not establish causation.","zh":"仅有相关性并不能证明因果关系。"}]}],"correspond":[{"pos":"v.","meaning":"符合；相一致","definition":"to match or agree","examples":[{"en":"The figures do not correspond with the earlier report.","zh":"这些数字与先前报告不一致。"},{"en":"The map corresponds closely to the actual coastline.","zh":"地图与实际海岸线十分吻合。"}]},{"pos":"v.","meaning":"通信","definition":"to exchange letters or messages","examples":[{"en":"The two researchers corresponded for many years.","zh":"两位研究人员通信了多年。"},{"en":"We still correspond by email after moving abroad.","zh":"搬到国外后，我们仍通过电子邮件联系。"}]},{"pos":"v.","meaning":"相当于；相对应","definition":"to have a similar role or position","examples":[{"en":"This qualification corresponds to a first university degree.","zh":"这项资格相当于大学本科学位。"},{"en":"Each symbol corresponds to a particular sound.","zh":"每个符号对应一个特定声音。"}]}],"correspondence":[{"pos":"n.","meaning":"通信；往来信件","definition":"communication by letters or the letters themselves","examples":[{"en":"They maintained a regular correspondence for years.","zh":"他们多年来一直定期通信。"},{"en":"The archive preserves her private correspondence.","zh":"档案馆保存了她的私人信件。"}]},{"pos":"n.","meaning":"一致；对应关系","definition":"a close similarity or connection","examples":[{"en":"There is a clear correspondence between the two patterns.","zh":"这两种模式之间存在清晰的对应关系。"},{"en":"The results show little correspondence with our predictions.","zh":"结果与我们的预测几乎不符。"}]}],"corridor":[{"pos":"n.","meaning":"走廊；过道","definition":"a long passage connecting rooms","examples":[{"en":"The office is at the end of the corridor.","zh":"办公室在走廊尽头。"},{"en":"Please keep the corridor clear.","zh":"请保持走廊畅通。"}]}],"corrode":[{"pos":"v.","meaning":"腐蚀；侵蚀","definition":"to damage gradually by chemical action or harmful influence","examples":[{"en":"Salt water can corrode exposed metal.","zh":"盐水会腐蚀裸露的金属。"},{"en":"Repeated dishonesty corrodes trust within a team.","zh":"反复的不诚实会侵蚀团队内部的信任。"}]}],"corrupt":[{"pos":"adj.","meaning":"腐败的；贪污的；堕落的","definition":"dishonest or morally wrong, especially through misuse of power","examples":[{"en":"The investigation exposed corrupt officials.","zh":"调查揭露了腐败官员。"},{"en":"The law aims to prevent corrupt business practices.","zh":"这部法律旨在防止腐败的商业行为。"}]},{"pos":"v.","meaning":"使腐化；使堕落","definition":"to make someone dishonest or morally worse","examples":[{"en":"Unaccountable power can corrupt leaders.","zh":"不受制约的权力会使领导者腐化。"},{"en":"The story shows how greed corrupted the family.","zh":"故事展示了贪婪如何使这个家庭堕落。"}]},{"pos":"v.","meaning":"破坏；损坏数据","definition":"to damage information so it cannot be used correctly","examples":[{"en":"A sudden power loss can corrupt the file.","zh":"突然断电可能损坏文件。"},{"en":"The error corrupted several records in the database.","zh":"这个错误损坏了数据库中的几条记录。"}]}],"cosmic":[{"pos":"adj.","meaning":"宇宙的","definition":"relating to the universe","examples":[{"en":"The telescope detects cosmic radiation.","zh":"望远镜探测宇宙辐射。"},{"en":"The lecture explored events on a cosmic scale.","zh":"讲座探讨宇宙尺度上的事件。"}]}],"cosmopolitan":[{"pos":"adj.","meaning":"国际化的；世界性的","definition":"including influences and people from many countries","examples":[{"en":"The port has a lively cosmopolitan culture.","zh":"这座港口拥有活跃的国际化文化。"},{"en":"She enjoys living in a cosmopolitan city.","zh":"她喜欢住在国际化城市。"}]},{"pos":"n.","meaning":"世界公民；四海为家的人","definition":"a person comfortable with many countries and cultures","examples":[{"en":"Years of travel made him a true cosmopolitan.","zh":"多年的旅行使他成为真正的世界公民。"},{"en":"The novelist portrays a cosmopolitan who feels at home in several cities.","zh":"小说家描绘了一个在几座城市都能安居的四海为家者。"}]}],"cosset":[{"pos":"v.","meaning":"宠爱；娇惯；过度呵护","definition":"to care for someone with excessive comfort and protection","examples":[{"en":"They tend to cosset their youngest child.","zh":"他们往往过分宠爱最小的孩子。"},{"en":"The luxury hotel cossets its guests.","zh":"这家豪华酒店对客人照顾得无微不至。"}]},{"pos":"n.","meaning":"宠儿；人工饲养的羔羊（少见）","definition":"a pampered person or a hand-reared lamb","examples":[{"en":"The orphaned lamb became the farmer's cosset.","zh":"那只失去母亲的羔羊成了农夫手养的宠物。"},{"en":"As the family's cosset, he was protected from every inconvenience.","zh":"作为全家的宠儿，他受到百般呵护，连一点不便都不必承受。"}]}],"costume":[{"pos":"n.","meaning":"戏服；表演服装","definition":"clothing worn to portray a character","examples":[{"en":"The actor changed into a period costume.","zh":"演员换上了时代戏服。"},{"en":"The theatre stores its costumes upstairs.","zh":"剧院把戏服存放在楼上。"}]},{"pos":"n.","meaning":"特定场合的成套服装；传统服饰","definition":"clothing associated with a place, group, or occasion","examples":[{"en":"Dancers wore traditional costume.","zh":"舞者穿着传统服饰。"},{"en":"The festival includes a costume parade.","zh":"节日包括服装游行。"}]}],"cosy":[{"pos":"adj.","meaning":"舒适温暖的；惬意的","definition":"warm, comfortable, and pleasant","examples":[{"en":"The cottage has a cosy reading corner.","zh":"小屋里有一个舒适的阅读角。"},{"en":"We spent a cosy evening beside the fire.","zh":"我们在炉火旁度过了惬意的一晚。"}]}],"council":[{"pos":"n.","meaning":"理事会；委员会；地方议会","definition":"a group responsible for decisions or administration","examples":[{"en":"The council approved the housing plan.","zh":"地方议会批准了住房计划。"},{"en":"The student council meets every Friday.","zh":"学生委员会每周五开会。"}]}],"counsel":[{"pos":"n.","meaning":"律师；法律顾问","definition":"a lawyer representing or advising someone","examples":[{"en":"The defendant consulted legal counsel.","zh":"被告咨询了法律顾问。"},{"en":"Counsel asked the witness to clarify the statement.","zh":"律师请证人澄清陈述。"}]},{"pos":"n.","meaning":"劝告；忠告","definition":"careful advice","examples":[{"en":"She valued her mentor's wise counsel.","zh":"她珍视导师明智的忠告。"},{"en":"He sought counsel before making the decision.","zh":"作决定前，他寻求了建议。"}]},{"pos":"v.","meaning":"劝告；提供咨询","definition":"to advise someone carefully","examples":[{"en":"The tutor counselled patience.","zh":"导师劝大家耐心等待。"},{"en":"Trained staff counsel students about their options.","zh":"受训人员为学生提供选择方面的咨询。"}]},{"pos":"v.","meaning":"商议；讨论","definition":"to discuss something in order to make a decision","examples":[{"en":"The elders counselled together before responding.","zh":"长者们先商议，再作回应。"},{"en":"They counselled with their advisers about the proposal.","zh":"他们与顾问商议提案。"}]}],"counsellor":[{"pos":"n.","meaning":"顾问；辅导员","definition":"a person trained to offer advice and support","examples":[{"en":"The school counsellor helps students manage stress.","zh":"学校辅导员帮助学生应对压力。"},{"en":"She discussed her options with a careers counsellor.","zh":"她与职业顾问讨论了自己的选择。"}]}],"counter":[{"pos":"n.","meaning":"柜台","definition":"a long surface used for serving customers or displaying goods","examples":[{"en":"Please pay at the counter.","zh":"请到柜台付款。"},{"en":"The clerk placed the parcel on the counter.","zh":"店员把包裹放在柜台上。"}]},{"pos":"adv.","meaning":"相反地；逆向地","definition":"in an opposing direction or manner","examples":[{"en":"The proposal runs counter to our original aims.","zh":"这项提议与我们最初的目标背道而驰。"},{"en":"Her findings run counter to the accepted view.","zh":"她的研究发现与公认观点相反。"}]}],"counterpart":[{"pos":"n.","meaning":"对应的人或物；职位相当者","definition":"a person or thing with a similar role elsewhere","examples":[{"en":"The minister met her foreign counterpart.","zh":"部长会见了外国的对应部长。"},{"en":"The device is lighter than its older counterpart.","zh":"该设备比它的旧型号轻。"}]},{"pos":"n.","meaning":"副本；对应文本","definition":"one of two matching copies of a document","examples":[{"en":"Each party kept a signed counterpart of the agreement.","zh":"各方保留了一份已签字的协议副本。"},{"en":"The archive holds the counterpart of the original deed.","zh":"档案馆保存了原契据的副本。"}]}],"counterproductive":[{"pos":"adj.","meaning":"适得其反的","definition":"having the opposite effect from the one intended","examples":[{"en":"Too many reminders can be counterproductive.","zh":"提醒太多可能适得其反。"},{"en":"Punishing every small mistake proved counterproductive.","zh":"惩罚每一个小错误，结果反而起了相反作用。"}]}],"county":[{"pos":"n.","meaning":"郡；县","definition":"an administrative area within a country or state","examples":[{"en":"The county maintains the rural roads.","zh":"县政府维护乡村道路。"},{"en":"They moved to a neighbouring county.","zh":"他们搬到了邻县。"}]}],"couple":[{"pos":"n.","meaning":"一对；两个","definition":"two people or things considered together","examples":[{"en":"We stayed for a couple of days.","zh":"我们住了两天。"},{"en":"A couple of chairs stood near the window.","zh":"窗边放着两把椅子。"}]},{"pos":"n.","meaning":"夫妻；情侣","definition":"two people in a romantic or marital relationship","examples":[{"en":"The couple moved into their first home.","zh":"这对夫妇搬进了他们的第一个家。"},{"en":"An elderly couple sat beside the lake.","zh":"一对老夫妇坐在湖边。"}]},{"pos":"v.","meaning":"连接；结合","definition":"to join two things or link them in effect","examples":[{"en":"The engine is coupled to the generator.","zh":"发动机与发电机相连。"},{"en":"Practical training is coupled with classroom study.","zh":"实践培训与课堂学习相结合。"}]},{"pos":"v.","meaning":"配对；结合成伴侣（较旧用法）","definition":"to join or pair people or animals as partners","examples":[{"en":"The story couples the two characters at its end.","zh":"故事结尾使这两个角色结为伴侣。"},{"en":"The ceremony coupled the pair in marriage.","zh":"仪式使这对新人结为夫妻。"}]}],"coupon":[{"pos":"n.","meaning":"优惠券；票券；配给券","definition":"a document giving a discount or entitlement to goods","examples":[{"en":"Use this coupon to get a discount on your meal.","zh":"使用这张优惠券可以享受餐费折扣。"},{"en":"The museum displays food coupons from the wartime period.","zh":"博物馆展出了战争时期的食品配给券。"}]},{"pos":"n.","meaning":"报名或订购剪条","definition":"a form cut from a publication for an order or competition","examples":[{"en":"Complete the coupon and post it with your payment.","zh":"填写订购单，并连同付款一起寄出。"},{"en":"Readers could enter the contest by returning the coupon.","zh":"读者可以寄回报名剪条参加比赛。"}]}],"courageous":[{"pos":"adj.","meaning":"勇敢的；有胆量的","definition":"showing courage in a difficult situation","examples":[{"en":"It was a courageous decision to speak out.","zh":"公开发声是一个勇敢的决定。"},{"en":"The rescuers made a courageous effort to reach the village.","zh":"救援人员勇敢地努力赶往村庄。"}]}],"course":[{"pos":"n.","meaning":"过程；进程","definition":"the progress or development of events","examples":[{"en":"The river changed during the course of the century.","zh":"这条河在一个世纪的发展过程中发生了变化。"},{"en":"The discovery altered the course of the investigation.","zh":"发现改变了调查进程。"}]},{"pos":"n.","meaning":"路线；方向；方针","definition":"a route or chosen way of acting","examples":[{"en":"The ship changed course to avoid the storm.","zh":"船改变航向避开风暴。"},{"en":"We must choose the best course of action.","zh":"我们必须选择最佳行动方案。"}]},{"pos":"n.","meaning":"课程","definition":"a planned series of lessons","examples":[{"en":"She is taking a course in photography.","zh":"她正在上摄影课程。"},{"en":"The course includes practical assignments.","zh":"课程包括实践作业。"}]},{"pos":"n.","meaning":"比赛场地；跑道","definition":"an area or route used for a sporting event","examples":[{"en":"The runners inspected the course.","zh":"跑步选手查看了赛道。"},{"en":"The golf course was closed after heavy rain.","zh":"大雨后，高尔夫球场关闭了。"}]},{"pos":"v.","meaning":"奔流；流动","definition":"to move or flow quickly","examples":[{"en":"Water coursed through the narrow channel.","zh":"水流过狭窄的沟渠。"},{"en":"Excitement coursed through the crowd.","zh":"激动的情绪在人群中涌动。"}]},{"pos":"v.","meaning":"追猎（传统上指用猎犬）","definition":"to hunt an animal by pursuing it with dogs","examples":[{"en":"The historical account describes dogs coursing hares.","zh":"历史记述描述了猎犬追逐野兔。"},{"en":"The old painting shows a pair of hounds coursing a hare.","zh":"这幅古画展现了两只猎犬追猎一只野兔。"}]}],"courtship":[{"pos":"n.","meaning":"求爱；追求期","definition":"the period or behaviour of seeking a romantic partner","examples":[{"en":"Their courtship lasted several years.","zh":"他们的恋爱追求阶段持续了几年。"},{"en":"The birds perform an elaborate courtship dance.","zh":"这种鸟会表演复杂的求偶舞。"}]}],"cover":[{"pos":"v.","meaning":"覆盖；遮盖","definition":"to place something over a surface or object","examples":[{"en":"Cover the food with a clean cloth.","zh":"用干净的布盖住食物。"},{"en":"Snow covered the road overnight.","zh":"雪在一夜之间覆盖了道路。"}]},{"pos":"v.","meaning":"包括；涉及","definition":"to include or deal with a subject","examples":[{"en":"The course covers basic research methods.","zh":"这门课程涵盖基本研究方法。"},{"en":"The report covers events from the past five years.","zh":"报告涉及过去五年的事件。"}]},{"pos":"v.","meaning":"走过路程；占据面积","definition":"to travel a distance or extend over an area","examples":[{"en":"We hope to cover twenty kilometres today.","zh":"我们希望今天走二十公里。"},{"en":"The forest covers much of the island.","zh":"森林覆盖了岛上的大部分地区。"}]},{"pos":"v.","meaning":"报道；采访","definition":"to report on events for the media","examples":[{"en":"She was sent to cover the election.","zh":"她被派去报道选举。"},{"en":"Local journalists cover the council meetings.","zh":"当地记者报道市议会会议。"}]},{"pos":"v.","meaning":"足够支付；承担费用","definition":"to provide enough money for a cost","examples":[{"en":"The grant will cover travel expenses.","zh":"这笔资助将支付差旅费用。"},{"en":"His wages barely cover the rent.","zh":"他的工资勉强够付房租。"}]},{"pos":"v.","meaning":"保险承保；适用于","definition":"to provide insurance protection or apply to a situation","examples":[{"en":"The policy covers accidental damage.","zh":"这份保单承保意外损坏。"},{"en":"These regulations cover all permanent employees.","zh":"这些规定适用于所有正式员工。"}]},{"pos":"v.","meaning":"掩护；用武器保护","definition":"to protect someone by threatening or shooting at danger","examples":[{"en":"One soldier covered the others as they crossed.","zh":"一名士兵掩护其他人通过。"},{"en":"The guards covered the doorway during the escape.","zh":"守卫在撤离时掩护了门口。"}]},{"pos":"n.","meaning":"盖子；套子；封面","definition":"something placed over or around an object","examples":[{"en":"The book has a bright blue cover.","zh":"这本书有一个亮蓝色封面。"},{"en":"Put the cover back on the container.","zh":"把盖子重新盖到容器上。"}]},{"pos":"n.","meaning":"遮蔽物；掩护","definition":"shelter or protection from danger or observation","examples":[{"en":"The hikers took cover beneath a rock ledge.","zh":"徒步者躲到岩石突出部分下面避雨。"},{"en":"The trees provided cover from the wind.","zh":"树木提供了挡风的屏障。"}]}],"coverage":[{"pos":"n.","meaning":"新闻报道","definition":"the reporting of an event in the media","examples":[{"en":"The election received extensive coverage.","zh":"选举得到了广泛报道。"},{"en":"Live coverage begins at noon.","zh":"现场报道中午开始。"}]},{"pos":"n.","meaning":"覆盖范围；涉及范围","definition":"the area or subjects included in a service or account","examples":[{"en":"Mobile coverage is poor in the mountains.","zh":"山区移动通信覆盖较差。"},{"en":"The course offers broad coverage of the topic.","zh":"课程广泛涉及这个主题。"}]}],"crack":[{"pos":"n.","meaning":"裂缝","definition":"a narrow break in a surface","examples":[{"en":"A crack appeared in the kitchen ceiling.","zh":"厨房天花板出现了一道裂缝。"},{"en":"Cold air entered through a crack in the window frame.","zh":"冷空气从窗框的一道缝里吹进来。"}]},{"pos":"n.","meaning":"爆裂声；重击","definition":"a sudden sharp sound or blow","examples":[{"en":"We heard the crack of a branch breaking.","zh":"我们听到了树枝断裂的咔嚓声。"},{"en":"The falling beam gave the wall a hard crack.","zh":"落下的横梁重重撞了一下墙。"}]},{"pos":"v.","meaning":"破裂；发出爆裂声","definition":"to break without fully separating or make a sharp sound","examples":[{"en":"The glass cracked when hot water touched it.","zh":"玻璃碰到热水时裂了。"},{"en":"A dry twig cracked beneath his foot.","zh":"一根干树枝在他脚下发出咔嚓声。"}]},{"pos":"v.","meaning":"崩溃；瓦解；攻破","definition":"to fail under pressure or solve something difficult","examples":[{"en":"The tired team began to crack under pressure.","zh":"疲惫的团队在压力下开始崩溃。"},{"en":"The researchers finally cracked the difficult code.","zh":"研究人员最终破解了这个难解的密码。"}]}],"craft":[{"pos":"n.","meaning":"工艺；手艺","definition":"skill in making things, especially by hand","examples":[{"en":"She learned the craft of pottery from her father.","zh":"她向父亲学习了制陶手艺。"},{"en":"The exhibition celebrates traditional craft.","zh":"这次展览颂扬传统工艺。"}]},{"pos":"n.","meaning":"船；航空器","definition":"a boat, ship, or aircraft","examples":[{"en":"A small craft approached the harbour.","zh":"一艘小船驶近港口。"},{"en":"The rescue craft carried medical supplies.","zh":"救援船运载着医疗物资。"}]}],"crank":[{"pos":"n.","meaning":"曲柄；摇把","definition":"a bent handle used to turn a mechanism","examples":[{"en":"The old machine has a hand crank.","zh":"旧机器有一个手摇曲柄。"},{"en":"He turned the crank slowly.","zh":"他慢慢转动摇把。"}]},{"pos":"v.","meaning":"用曲柄转动","definition":"to turn or start something with a crank","examples":[{"en":"She cranked the handle to raise the cover.","zh":"她摇动把手，把盖子升起来。"},{"en":"The operator cranked the old engine into life.","zh":"操作员用曲柄启动了旧发动机。"}]}],"crash":[{"pos":"v.","meaning":"碰撞；坠毁；轰然倒下","definition":"to hit violently or fall with force","examples":[{"en":"The car crashed into a roadside barrier.","zh":"汽车撞上了路边护栏。"},{"en":"A large branch crashed to the ground.","zh":"一根大树枝轰然落地。"}]},{"pos":"v.","meaning":"崩溃；暴跌；破产","definition":"to fail suddenly or lose value rapidly","examples":[{"en":"The computer crashed before the file was saved.","zh":"文件保存前，电脑崩溃了。"},{"en":"Prices crashed after demand disappeared.","zh":"需求消失后，价格暴跌。"}]},{"pos":"n.","meaning":"碰撞；坠毁；巨响","definition":"a violent collision or sudden loud noise","examples":[{"en":"The crash closed the road for several hours.","zh":"撞车事故使道路封闭了几个小时。"},{"en":"A loud crash came from the kitchen.","zh":"厨房传来一声巨响。"}]},{"pos":"adj.","meaning":"速成的；紧急集中的","definition":"intensive and designed to achieve results quickly","examples":[{"en":"She took a crash course in basic accounting.","zh":"她上了一门基础会计速成课。"},{"en":"The team launched a crash programme to repair the network.","zh":"团队启动了紧急集中修复网络的计划。"}]}],"crater":[{"pos":"n.","meaning":"火山口；撞击坑","definition":"a large hollow formed by a volcano, impact, or explosion","examples":[{"en":"Steam rose from the volcanic crater.","zh":"蒸汽从火山口升起。"},{"en":"The impact left a deep crater.","zh":"撞击留下了一个深坑。"}]}],"crawl":[{"pos":"v.","meaning":"爬；爬行","definition":"to move on hands and knees or close to the ground","examples":[{"en":"The baby crawled across the carpet.","zh":"婴儿爬过地毯。"},{"en":"A beetle crawled under the leaf.","zh":"一只甲虫爬到叶子下面。"}]},{"pos":"v.","meaning":"缓慢行进","definition":"to move very slowly","examples":[{"en":"Traffic crawled through the town.","zh":"车辆缓慢穿过城镇。"},{"en":"The queue crawled towards the entrance.","zh":"队伍缓慢地向入口移动。"}]},{"pos":"n.","meaning":"缓慢的前进","definition":"a very slow movement","examples":[{"en":"The roadworks reduced traffic to a crawl.","zh":"道路施工使交通变得极其缓慢。"},{"en":"Progress slowed to a crawl.","zh":"进展慢得像爬行。"}]},{"pos":"n.","meaning":"爬泳；自由泳泳姿","definition":"a swimming stroke with alternating arm movements","examples":[{"en":"She swims front crawl confidently.","zh":"她自信地游爬泳。"},{"en":"The lesson focused on improving his crawl.","zh":"课程着重改善他的自由泳泳姿。"}]}],"create":[{"pos":"v.","meaning":"创造；创作；产生","definition":"to bring something new into existence","examples":[{"en":"The new park will create space for outdoor activities.","zh":"新公园将为户外活动创造空间。"},{"en":"Students created posters explaining water conservation.","zh":"学生们创作了说明节水的海报。"}]}],"creation":[{"pos":"n.","meaning":"创造；创立","definition":"the act of bringing something into existence","examples":[{"en":"The policy encouraged the creation of new jobs.","zh":"这项政策鼓励创造新岗位。"},{"en":"The creation of the park took several years.","zh":"这座公园的建成花了几年时间。"}]},{"pos":"n.","meaning":"作品；创造物","definition":"something made or invented","examples":[{"en":"The sculpture is her latest creation.","zh":"这座雕塑是她最新的作品。"},{"en":"The children proudly displayed their creations.","zh":"孩子们自豪地展示了自己的作品。"}]}],"creative":[{"pos":"adj.","meaning":"创造性的；有创意的","definition":"able to produce original ideas or work","examples":[{"en":"The problem needs a creative solution.","zh":"这个问题需要有创意的解决办法。"},{"en":"The course encourages creative writing.","zh":"课程鼓励创意写作。"}]}],"credential":[{"pos":"n.","meaning":"资格证明；证书；证件","definition":"a document or qualification proving identity or ability","examples":[{"en":"The course provides a recognized professional credential.","zh":"这门课程提供受认可的职业资格证明。"},{"en":"Please show your credentials at the registration desk.","zh":"请在登记台出示证件。"}]}],"credibility":[{"pos":"n.","meaning":"可信度；可靠性","definition":"the quality of being believable and trustworthy","examples":[{"en":"The error damaged the report's credibility.","zh":"这个错误损害了报告的可信度。"},{"en":"Independent evidence adds credibility to the claim.","zh":"独立证据增加了这一说法的可信度。"}]}],"credible":[{"pos":"adj.","meaning":"可信的；可靠的","definition":"believable or deserving trust","examples":[{"en":"The witness gave a credible account.","zh":"证人作出了可信的叙述。"},{"en":"We need credible evidence before drawing conclusions.","zh":"得出结论前，我们需要可靠证据。"}]}],"credit":[{"pos":"n.","meaning":"信用贷款；赊购","definition":"an arrangement allowing payment later","examples":[{"en":"The shop offers credit to regular business customers.","zh":"这家商店为经常往来的企业客户提供赊购。"},{"en":"Access to affordable credit helped the business expand.","zh":"获得成本较低的贷款帮助企业扩大经营。"}]},{"pos":"n.","meaning":"功劳；赞誉；信任","definition":"recognition or belief that someone deserves","examples":[{"en":"She gave the whole team credit for the success.","zh":"她把成功的功劳归于整个团队。"},{"en":"The explanation deserves more credit than it received.","zh":"这个解释值得获得比目前更多的信任。"}]},{"pos":"n.","meaning":"学分","definition":"a unit representing completed academic work","examples":[{"en":"The module is worth ten credits.","zh":"这门课程模块计十个学分。"},{"en":"She needs one more credit to complete the programme.","zh":"她还需要一个学分才能完成课程。"}]},{"pos":"n.","meaning":"贷方金额；入账款项","definition":"money added to an account or recorded on its credit side","examples":[{"en":"The refund appeared as a credit on my statement.","zh":"退款作为一笔入账款项显示在我的账单上。"},{"en":"The accountant entered the amount in the credit column.","zh":"会计把金额记入贷方栏。"}]},{"pos":"v.","meaning":"记入账户贷方；入账","definition":"to add money to an account","examples":[{"en":"The bank credited the refund to my account.","zh":"银行把退款记入了我的账户。"},{"en":"Your payment will be credited within two days.","zh":"你的付款将在两天内入账。"}]},{"pos":"v.","meaning":"归功于；认为……具有","definition":"to attribute an achievement or quality to someone","examples":[{"en":"She credits her teacher with inspiring her career.","zh":"她认为是老师启发了自己的职业选择。"},{"en":"The discovery is credited to a team of local researchers.","zh":"这项发现被归功于一个当地研究团队。"}]}],"creep":[{"pos":"v.","meaning":"悄悄移动；爬行","definition":"to move slowly and quietly or close to the ground","examples":[{"en":"The cat began to creep towards the bird.","zh":"猫开始悄悄靠近那只鸟。"},{"en":"The child crept under the table.","zh":"孩子爬到了桌子下面。"}]},{"pos":"v.","meaning":"缓慢发展；渐渐出现","definition":"to develop or move very gradually","examples":[{"en":"Prices continue to creep upwards.","zh":"价格继续缓慢上涨。"},{"en":"Doubt began to creep into her mind.","zh":"疑虑开始悄悄浮现在她心中。"}]}],"crescent":[{"pos":"n.","meaning":"新月；月牙形","definition":"the curved shape of a thin moon","examples":[{"en":"A crescent hung above the rooftops.","zh":"一弯新月悬在屋顶上方。"},{"en":"The beach forms a wide crescent.","zh":"海滩呈宽阔的月牙形。"}]},{"pos":"adj.","meaning":"新月形的","definition":"shaped like a thin curved moon","examples":[{"en":"The lake has a crescent shape.","zh":"湖呈新月形。"},{"en":"A crescent moon appeared at dusk.","zh":"黄昏时，一轮新月出现了。"}]}],"crew":[{"pos":"n.","meaning":"全体船员；机组；工作团队","definition":"a group operating a vehicle or doing practical work","examples":[{"en":"The crew prepared the ship for departure.","zh":"全体船员为船只启航作准备。"},{"en":"A film crew arrived to record the ceremony.","zh":"一个摄制组前来拍摄仪式。"}]}],"cricket":[{"pos":"n.","meaning":"板球","definition":"a sport played with a bat, ball, and wickets","examples":[{"en":"They play cricket in the park on Sundays.","zh":"他们星期日在公园打板球。"},{"en":"The cricket match lasted all afternoon.","zh":"这场板球比赛持续了整个下午。"}]},{"pos":"n.","meaning":"蟋蟀","definition":"a jumping insect whose males make a chirping sound","examples":[{"en":"A cricket chirped outside the window.","zh":"一只蟋蟀在窗外鸣叫。"},{"en":"We found a cricket among the dry leaves.","zh":"我们在干叶子中发现了一只蟋蟀。"}]}],"crime":[{"pos":"n.","meaning":"罪行；犯罪","definition":"an illegal act or illegal activity generally","examples":[{"en":"The police investigated the crime.","zh":"警方调查了这起犯罪。"},{"en":"The programme aims to reduce crime.","zh":"该项目旨在减少犯罪。"}]}],"criminal":[{"pos":"adj.","meaning":"犯罪的；刑事的","definition":"relating to crime or its prosecution","examples":[{"en":"The police began a criminal investigation.","zh":"警方展开了刑事调查。"},{"en":"The course introduces basic principles of criminal law.","zh":"这门课程介绍刑法的基本原则。"}]},{"pos":"n.","meaning":"罪犯","definition":"a person who has committed a crime","examples":[{"en":"The criminal was arrested after a lengthy investigation.","zh":"经过长时间调查，罪犯被逮捕了。"},{"en":"The programme supports former criminals seeking employment.","zh":"这个项目帮助有犯罪前科的人找工作。"}]}],"crisis":[{"pos":"n.","meaning":"危机；紧要关头","definition":"a time of serious danger, difficulty, or decisive change","examples":[{"en":"The drought caused a water crisis.","zh":"干旱引发了水资源危机。"},{"en":"The organisation responded quickly to the crisis.","zh":"这个组织迅速应对了危机。"}]}],"crisp":[{"pos":"adj.","meaning":"脆的；酥脆的","definition":"firm and breaking with a sharp sound","examples":[{"en":"The apples are fresh and crisp.","zh":"苹果新鲜爽脆。"},{"en":"Bake the pastry until it is crisp.","zh":"把酥皮烤到酥脆。"}]},{"pos":"adj.","meaning":"利落的；清晰的","definition":"neat, clear, and well defined","examples":[{"en":"She gave a crisp explanation.","zh":"她作了简明利落的解释。"},{"en":"The photograph has crisp detail.","zh":"照片细节清晰。"}]},{"pos":"n.","meaning":"炸薯片（英式，常用复数）","definition":"a thin fried slice of potato","examples":[{"en":"He bought a packet of crisps.","zh":"他买了一包薯片。"},{"en":"The crisps were served in a small bowl.","zh":"薯片盛在一个小碗里。"}]}],"criterion":[{"pos":"n.","meaning":"标准；准则","definition":"a principle used to judge something","examples":[{"en":"Cost is not the only criterion for choosing a supplier.","zh":"成本并不是选择供应商的唯一标准。"},{"en":"The main criterion was the reliability of the evidence.","zh":"主要标准是证据的可靠性。"}]}],"critic":[{"pos":"n.","meaning":"评论家；批评者","definition":"someone who evaluates works or expresses disapproval","examples":[{"en":"The theatre critic praised the performance.","zh":"这位戏剧评论家赞扬了演出。"},{"en":"She is a vocal critic of the policy.","zh":"她是这项政策的公开批评者。"}]},{"pos":"n.","meaning":"爱挑剔的人","definition":"a person who often finds fault","examples":[{"en":"He can be his own harshest critic.","zh":"他可能是对自己最苛刻的人。"},{"en":"Even the family's toughest critic enjoyed the meal.","zh":"就连家里最挑剔的人也喜欢这顿饭。"}]}],"critical":[{"pos":"adj.","meaning":"批判性的；分析评判的","definition":"involving careful examination and judgement","examples":[{"en":"The course develops critical thinking.","zh":"课程培养批判性思维。"},{"en":"She wrote a critical review of the argument.","zh":"她对这个论证写了分析性的评论。"}]},{"pos":"adj.","meaning":"批评的；挑剔的","definition":"expressing disapproval or finding faults","examples":[{"en":"The report was critical of the management.","zh":"报告批评了管理层。"},{"en":"He was too critical of his own work.","zh":"他对自己的作品过于苛刻。"}]},{"pos":"adj.","meaning":"关键的；至关重要的","definition":"extremely important to an outcome","examples":[{"en":"Timing is critical to the experiment.","zh":"时间把握对实验至关重要。"},{"en":"The talks reached a critical stage.","zh":"会谈进入关键阶段。"}]},{"pos":"adj.","meaning":"危急的；严重的","definition":"in a dangerous or very serious condition","examples":[{"en":"The situation became critical overnight.","zh":"局势一夜间变得危急。"},{"en":"The hospital said his condition was critical.","zh":"医院表示他的情况危急。"}]},{"pos":"adj.","meaning":"临界的","definition":"at a point where a significant change occurs","examples":[{"en":"The material changes at a critical temperature.","zh":"材料在临界温度发生变化。"},{"en":"The experiment measured the critical pressure.","zh":"实验测量了临界压力。"}]}],"criticise":[{"pos":"v.","meaning":"批评；责备","definition":"to express disapproval","examples":[{"en":"Residents criticised the lack of consultation.","zh":"居民批评没有征求他们的意见。"},{"en":"It is easy to criticise a plan without suggesting alternatives.","zh":"只批评计划而不提出替代方案是很容易的。"}]},{"pos":"v.","meaning":"评论；分析评价","definition":"to assess the qualities and faults of a work","examples":[{"en":"Students learned to criticise arguments using evidence.","zh":"学生们学习用证据分析评价论点。"},{"en":"The essay criticises the novel's treatment of history.","zh":"这篇文章评论了小说处理历史的方式。"}]}],"crockery":[{"pos":"n.","meaning":"陶瓷餐具","definition":"plates, cups, and other dishes, especially ceramic ones","examples":[{"en":"The cupboard holds the everyday crockery.","zh":"橱柜里放着日常使用的陶瓷餐具。"},{"en":"Pack the crockery carefully before moving.","zh":"搬家前仔细包装陶瓷餐具。"}]}],"crocodile":[{"pos":"n.","meaning":"鳄鱼","definition":"a large reptile with a long tail and powerful jaws","examples":[{"en":"A crocodile lay on the riverbank.","zh":"一条鳄鱼趴在河岸上。"},{"en":"The guide warned us to keep away from crocodiles.","zh":"导游提醒我们远离鳄鱼。"}]},{"pos":"n.","meaning":"鳄鱼皮","definition":"leather made from crocodile skin","examples":[{"en":"The museum displays an old crocodile bag.","zh":"博物馆展出一个旧鳄鱼皮包。"},{"en":"The label identified the material as crocodile.","zh":"标签注明材料为鳄鱼皮。"}]}],"crossword":[{"pos":"n.","meaning":"纵横填字游戏","definition":"a puzzle in which words are written across and down a grid","examples":[{"en":"She solves a crossword on the train each morning.","zh":"她每天早上在火车上做填字游戏。"},{"en":"One clue in the crossword required a botanical term.","zh":"这道填字游戏有一条线索需要填写植物学术语。"}]}],"crowded":[{"pos":"adj.","meaning":"拥挤的；挤满的","definition":"full of people or things with little space remaining","examples":[{"en":"The train was crowded during rush hour.","zh":"高峰时段火车很拥挤。"},{"en":"Her desk was crowded with books and papers.","zh":"她的桌上堆满了书和文件。"}]}],"crown":[{"pos":"n.","meaning":"王冠；桂冠","definition":"a ceremonial head covering symbolising rank or achievement","examples":[{"en":"The crown is displayed in a glass case.","zh":"王冠陈列在玻璃柜中。"},{"en":"The champion wore a symbolic crown.","zh":"冠军戴上象征性的桂冠。"}]},{"pos":"n.","meaning":"花冠；花环头饰","definition":"a circular head covering made of flowers or leaves","examples":[{"en":"She made a crown of wildflowers.","zh":"她用野花编了一个花冠。"},{"en":"The dancer wore a crown of leaves.","zh":"舞者戴着树叶编成的花冠。"}]},{"pos":"n.","meaning":"齿冠；牙冠","definition":"the visible part of a tooth or an artificial covering for it","examples":[{"en":"The dentist examined the crown of the tooth.","zh":"牙医检查了牙齿的齿冠。"},{"en":"The damaged tooth needed a crown.","zh":"受损的牙齿需要安装牙冠。"}]}],"crucial":[{"pos":"adj.","meaning":"至关重要的；决定性的","definition":"extremely important to an outcome","examples":[{"en":"Accurate measurements are crucial to the experiment.","zh":"准确测量对实验至关重要。"},{"en":"The final interview played a crucial role in the decision.","zh":"最后一次面试在决定中起了关键作用。"}]}],"crude":[{"pos":"adj.","meaning":"未经加工的；天然的","definition":"in a raw or unrefined state","examples":[{"en":"The refinery processes crude oil.","zh":"炼油厂加工原油。"},{"en":"The sample contained crude mineral deposits.","zh":"样本含有未经加工的矿物沉积物。"}]},{"pos":"adj.","meaning":"粗糙的；简陋的","definition":"simple and lacking precision or refinement","examples":[{"en":"They built a crude shelter from branches.","zh":"他们用树枝搭了一个简陋的避难棚。"},{"en":"The diagram gives only a crude estimate.","zh":"这张图只提供了粗略估计。"}]},{"pos":"adj.","meaning":"粗俗的；冒犯的","definition":"rude or offensive in expression","examples":[{"en":"His crude joke offended several guests.","zh":"他粗俗的笑话冒犯了几位客人。"},{"en":"The wall was covered with crude insults.","zh":"墙上写满了粗俗的辱骂。"}]}],"cruel":[{"pos":"adj.","meaning":"残忍的；残酷的","definition":"causing pain or suffering without concern","examples":[{"en":"It is cruel to neglect an animal.","zh":"忽视动物的需要是残忍的。"},{"en":"The story describes a cruel ruler.","zh":"故事描述了一位残暴的统治者。"}]}],"cruise":[{"pos":"v.","meaning":"巡航；乘船游览；缓慢行驶","definition":"to travel smoothly, often for pleasure","examples":[{"en":"The boat cruised along the quiet river.","zh":"小船沿着宁静的河流航行。"},{"en":"Taxis cruised the streets looking for passengers.","zh":"出租车缓缓驶过街道寻找乘客。"}]},{"pos":"n.","meaning":"游轮旅行；巡航","definition":"a journey by ship, often for pleasure","examples":[{"en":"They booked a short cruise around the islands.","zh":"他们预订了一次环岛短途游轮旅行。"},{"en":"The research vessel completed a month-long cruise.","zh":"科研船完成了为期一个月的巡航。"}]}],"crusade":[{"pos":"n.","meaning":"十字军东征","definition":"one of the medieval Christian military expeditions to the eastern Mediterranean","examples":[{"en":"The chapter examines the motives behind the First Crusade.","zh":"这一章考察了第一次十字军东征的动机。"},{"en":"The museum displays objects associated with the Crusades.","zh":"博物馆展示了与十字军东征有关的物品。"}]},{"pos":"n.","meaning":"持续的社会运动；斗争","definition":"an energetic campaign for a cause","examples":[{"en":"She began a crusade against illiteracy.","zh":"她发起了一场反文盲运动。"},{"en":"The newspaper launched a crusade for cleaner rivers.","zh":"这家报纸发起了清洁河流的宣传运动。"}]},{"pos":"v.","meaning":"投身运动；为某事而斗争","definition":"to campaign energetically for a cause","examples":[{"en":"The group continues to crusade for housing reform.","zh":"这个团体继续积极争取住房改革。"},{"en":"He crusaded against corruption throughout his career.","zh":"他在整个职业生涯中都在反对腐败。"}]}],"crush":[{"pos":"v.","meaning":"压碎；碾碎；压坏","definition":"to break or damage with pressure","examples":[{"en":"Crush the nuts before adding them.","zh":"加入坚果前，先把它们压碎。"},{"en":"The falling branch crushed the fence.","zh":"落下的树枝压坏了围栏。"}]},{"pos":"v.","meaning":"镇压；击败；压服","definition":"to overcome or defeat completely","examples":[{"en":"The army crushed the rebellion.","zh":"军队镇压了叛乱。"},{"en":"Their team was crushed in the final.","zh":"他们的队伍在决赛中惨败。"}]},{"pos":"v.","meaning":"使沮丧；压垮","definition":"to destroy someone's hope or confidence","examples":[{"en":"The rejection crushed his confidence.","zh":"拒绝打击了他的信心。"},{"en":"She refused to let disappointment crush her hopes.","zh":"她拒绝让失望摧毁希望。"}]}],"crushing":[{"pos":"adj.","meaning":"毁灭性的；压倒性的；惨重的","definition":"extremely severe or decisive","examples":[{"en":"The team suffered a crushing defeat.","zh":"球队遭受了惨败。"},{"en":"The rent placed a crushing burden on the family.","zh":"房租给这个家庭带来了沉重负担。"}]}],"crust":[{"pos":"n.","meaning":"硬外层；地壳","definition":"a hard outer layer, including the Earth's outer solid layer","examples":[{"en":"A thin crust formed on the cooling lava.","zh":"冷却的熔岩表面形成了一层薄壳。"},{"en":"The earthquake occurred within the Earth's crust.","zh":"这次地震发生在地壳内。"}]},{"pos":"n.","meaning":"面包皮；糕点外皮","definition":"the firm outer part of bread or pastry","examples":[{"en":"The bread has a crisp crust.","zh":"这块面包有酥脆的外皮。"},{"en":"She trimmed the crust from the sandwich.","zh":"她切掉了三明治的面包皮。"}]}],"crystallize":[{"pos":"v.","meaning":"结晶；使结晶","definition":"to form or cause crystals to form","examples":[{"en":"The salt crystallized as the water evaporated.","zh":"水蒸发时，盐结晶了。"},{"en":"Cooling the solution helps the substance crystallize.","zh":"冷却溶液有助于物质结晶。"}]},{"pos":"v.","meaning":"明确化；使成形","definition":"to become or make an idea clear and definite","examples":[{"en":"Her plans began to crystallize after the visit.","zh":"访问后，她的计划逐渐明确。"},{"en":"The discussion crystallized our main concerns.","zh":"讨论使我们的主要关切变得清晰。"}]}],"cube":[{"pos":"n.","meaning":"立方体；方块","definition":"a solid with six equal square faces","examples":[{"en":"The children built a tower from wooden cubes.","zh":"孩子们用木方块搭了一座塔。"},{"en":"Add one ice cube to the drink.","zh":"往饮料里加一块冰。"}]},{"pos":"n.","meaning":"立方；三次方","definition":"the result of multiplying a number by itself twice","examples":[{"en":"The cube of three is twenty-seven.","zh":"三的立方是二十七。"},{"en":"The volume changes with the cube of the length.","zh":"体积随长度的三次方变化。"}]}],"cucumber":[{"pos":"n.","meaning":"黄瓜","definition":"a long green vegetable commonly eaten raw","examples":[{"en":"Slice the cucumber for the salad.","zh":"把黄瓜切片做沙拉。"},{"en":"The garden produced its first cucumber today.","zh":"菜园今天结出了第一根黄瓜。"}]}],"cue":[{"pos":"n.","meaning":"暗示；提示；信号","definition":"a signal indicating what to do or say","examples":[{"en":"The actor waited for his cue.","zh":"演员等待出场提示。"},{"en":"The change in music was our cue to leave.","zh":"音乐的变化是我们离开的信号。"}]}],"cuisine":[{"pos":"n.","meaning":"烹饪风格；菜肴","definition":"a style of cooking associated with a place or tradition","examples":[{"en":"The restaurant specializes in regional cuisine.","zh":"这家餐馆专营地方菜。"},{"en":"Travel introduced her to several unfamiliar cuisines.","zh":"旅行让她接触到几种陌生的烹饪风格。"}]}],"culminate":[{"pos":"v.","meaning":"达到顶点；以……告终","definition":"to reach a final or highest point","examples":[{"en":"The festival will culminate in a concert.","zh":"节日将以一场音乐会结束。"},{"en":"Years of research culminated in the new book.","zh":"多年的研究最终结晶为这本新书。"}]}],"cultivate":[{"pos":"v.","meaning":"耕种；种植","definition":"to prepare land or grow plants","examples":[{"en":"Farmers cultivate rice in the valley.","zh":"农民在山谷种植水稻。"},{"en":"The soil has been cultivated for generations.","zh":"这片土壤已耕种了数代。"}]},{"pos":"v.","meaning":"培养；发展","definition":"to develop a skill, quality, or relationship","examples":[{"en":"Reading helps cultivate curiosity.","zh":"阅读有助于培养好奇心。"},{"en":"She cultivated a network of supportive colleagues.","zh":"她建立了互相支持的同事关系网。"}]}],"cultivation":[{"pos":"n.","meaning":"耕作；栽培","definition":"the preparation of land and growing of crops","examples":[{"en":"The soil is suitable for rice cultivation.","zh":"这种土壤适合种植水稻。"},{"en":"Continuous cultivation can reduce soil fertility.","zh":"连续耕作可能降低土壤肥力。"}]},{"pos":"n.","meaning":"培养；发展","definition":"the careful development of a quality or relationship","examples":[{"en":"The cultivation of critical thinking begins with asking questions.","zh":"批判性思维的培养始于提问。"},{"en":"The project depends on the cultivation of local trust.","zh":"这个项目依赖于建立当地信任。"}]}],"cultural":[{"pos":"adj.","meaning":"文化的；与文化有关的","definition":"relating to the customs, arts, or beliefs of a society","examples":[{"en":"The programme encourages cultural exchange.","zh":"这个项目鼓励文化交流。"},{"en":"The city protects its cultural heritage.","zh":"这座城市保护其文化遗产。"}]}],"cumulative":[{"pos":"adj.","meaning":"累积的；渐增的","definition":"increasing through successive additions","examples":[{"en":"The damage has a cumulative effect.","zh":"损害具有累积效应。"},{"en":"The chart shows cumulative rainfall.","zh":"图表显示累计降雨量。"}]}],"curative":[{"pos":"adj.","meaning":"有疗效的；治疗的","definition":"intended or able to cure an illness","examples":[{"en":"Researchers examined the plant's claimed curative properties.","zh":"研究人员考察了这种植物被宣称具有的治疗功效。"},{"en":"The report distinguishes preventive care from curative treatment.","zh":"报告区分了预防性保健与治疗性处理。"}]}],"curb":[{"pos":"v.","meaning":"控制；抑制；约束","definition":"to limit or restrain something","examples":[{"en":"The measures aim to curb unnecessary spending.","zh":"这些措施旨在控制不必要的开支。"},{"en":"She tried to curb her impatience.","zh":"她努力克制不耐烦的情绪。"}]},{"pos":"n.","meaning":"路缘；路边石（美式拼写）","definition":"the raised edge between a road and a pavement","examples":[{"en":"The car stopped beside the curb.","zh":"汽车停在路边。"},{"en":"He stepped off the curb carefully.","zh":"他小心地走下路缘。"}]},{"pos":"n.","meaning":"限制；约束物；马勒","definition":"something that restrains or controls","examples":[{"en":"The law places a curb on excessive noise.","zh":"这部法律对过度噪声加以限制。"},{"en":"The rider adjusted the horse's curb.","zh":"骑手调整了马的勒具。"}]}],"curiosity":[{"pos":"n.","meaning":"好奇心","definition":"a desire to know or learn","examples":[{"en":"The experiment aroused the children's curiosity.","zh":"实验激发了孩子们的好奇心。"},{"en":"She opened the box out of curiosity.","zh":"她出于好奇打开了盒子。"}]},{"pos":"n.","meaning":"奇物；珍奇的事物","definition":"something unusual or interesting","examples":[{"en":"The old device is now a museum curiosity.","zh":"这个旧装置如今成了博物馆里的奇物。"},{"en":"The shop sells antiques and curiosities.","zh":"商店出售古董和奇珍异品。"}]}],"curious":[{"pos":"adj.","meaning":"好奇的","definition":"eager to know or learn","examples":[{"en":"The children were curious about the unfamiliar machine.","zh":"孩子们对这台陌生机器很好奇。"},{"en":"I am curious to see how the experiment ends.","zh":"我很好奇实验最终会怎样。"}]},{"pos":"adj.","meaning":"奇怪的；不寻常的","definition":"unusual and interesting","examples":[{"en":"There was a curious smell in the empty room.","zh":"空房间里有一股奇怪的气味。"},{"en":"The records reveal a curious pattern.","zh":"记录显示出一种奇特的规律。"}]}],"curly":[{"pos":"adj.","meaning":"卷曲的；有卷的","definition":"forming curls or curved shapes","examples":[{"en":"She has naturally curly hair.","zh":"她天生头发卷曲。"},{"en":"The plant has curly leaves.","zh":"这种植物有卷曲的叶子。"}]}],"currency":[{"pos":"n.","meaning":"货币","definition":"the money used in a country","examples":[{"en":"You can exchange currency at the bank.","zh":"你可以在银行兑换货币。"},{"en":"The country introduced a new currency.","zh":"该国引入了一种新货币。"}]},{"pos":"n.","meaning":"流传；通用；广泛接受","definition":"general acceptance or use of an idea or expression","examples":[{"en":"The theory gained currency in the last century.","zh":"这个理论在上个世纪广为流行。"},{"en":"The phrase has lost much of its currency.","zh":"这个短语已不那么通用了。"}]}],"current":[{"pos":"adj.","meaning":"当前的；现行的；通行的","definition":"existing or in use at the present time","examples":[{"en":"The current timetable will remain in force until June.","zh":"现行时刻表将持续使用到六月。"},{"en":"That expression is still current in informal speech.","zh":"那个表达在非正式口语中仍通行。"}]},{"pos":"n.","meaning":"水流；气流；电流","definition":"a flow of water, air, or electricity","examples":[{"en":"A strong current carried the boat downstream.","zh":"强劲的水流把船带向下游。"},{"en":"The instrument measures electric current.","zh":"这台仪器测量电流。"}]},{"pos":"n.","meaning":"潮流；趋势","definition":"a general movement of ideas or opinions","examples":[{"en":"The book examines currents in modern political thought.","zh":"这本书考察现代政治思想中的潮流。"},{"en":"A current of optimism ran through the meeting.","zh":"会议中涌动着一股乐观情绪。"}]}],"currently":[{"pos":"adv.","meaning":"目前；现在","definition":"at the present time","examples":[{"en":"The museum is currently closed for repairs.","zh":"博物馆目前因维修而关闭。"},{"en":"She is currently working on a new project.","zh":"她目前正在做一个新项目。"}]}],"curriculum":[{"pos":"n.","meaning":"课程体系","definition":"the subjects and content taught in a course","examples":[{"en":"The school has added coding to its curriculum.","zh":"学校已将编程加入课程体系。"},{"en":"A balanced curriculum includes arts and science.","zh":"均衡的课程体系包括艺术和科学。"},{"en":"Teachers helped design the new curriculum.","zh":"教师参与设计了新的课程体系。"}]}],"curry":[{"pos":"n.","meaning":"咖喱；咖喱菜肴","definition":"a dish cooked in a sauce with spices","examples":[{"en":"She served a vegetable curry with rice.","zh":"她端上了蔬菜咖喱配米饭。"},{"en":"The curry had a mild coconut flavour.","zh":"这道咖喱有淡淡的椰子味。"}]},{"pos":"v.","meaning":"用咖喱烹调","definition":"to cook food with curry spices","examples":[{"en":"They curried the remaining vegetables for lunch.","zh":"他们把剩下的蔬菜做成咖喱当午饭。"},{"en":"The recipe explains how to curry chicken gently.","zh":"这份食谱介绍了如何用温和火候烹制咖喱鸡。"}]},{"pos":"v.","meaning":"梳刷（马毛）","definition":"to groom an animal with a special comb","examples":[{"en":"The groom curried the horse before the ride.","zh":"马夫在骑行前梳刷了马毛。"},{"en":"She learned to curry the pony carefully.","zh":"她学会了小心地梳刷小马的毛。"}]}],"curtail":[{"pos":"v.","meaning":"缩减；缩短；限制","definition":"to reduce or limit something","examples":[{"en":"Lack of funds forced them to curtail the programme.","zh":"资金不足迫使他们缩减项目。"},{"en":"The storm curtailed our visit to the island.","zh":"暴风雨缩短了我们在岛上的停留。"}]}],"curtain":[{"pos":"n.","meaning":"窗帘；门帘；帷幕","definition":"a hanging piece of fabric used as a covering or divider","examples":[{"en":"She drew the curtains to block the sun.","zh":"她拉上窗帘遮住阳光。"},{"en":"A curtain separates the changing area.","zh":"帘子隔开了更衣区域。"}]}],"cylinder":[{"pos":"n.","meaning":"圆柱体；圆筒","definition":"a solid or container with circular ends and straight sides","examples":[{"en":"The tank is shaped like a cylinder.","zh":"这个储罐形状像圆柱体。"},{"en":"Roll the sheet into a hollow cylinder.","zh":"把这张纸卷成一个空心圆筒。"}]},{"pos":"n.","meaning":"汽缸","definition":"a chamber in which an engine piston moves","examples":[{"en":"The mechanic inspected each cylinder.","zh":"技工检查了每个汽缸。"},{"en":"The engine has four cylinders.","zh":"这台发动机有四个汽缸。"}]}],"dairy":[{"pos":"n.","meaning":"乳制品","definition":"foods made from milk","examples":[{"en":"She avoids dairy because of an allergy.","zh":"她因过敏不吃乳制品。"},{"en":"The chilled aisle contains meat and dairy.","zh":"冷藏区有肉类和乳制品。"}]},{"pos":"n.","meaning":"乳品厂;乳品店","definition":"a place where milk products are made or sold","examples":[{"en":"The dairy delivers fresh milk every morning.","zh":"这家乳品店每天早晨送鲜奶。"},{"en":"Milk from nearby farms goes to the dairy.","zh":"附近农场的奶被送往乳品厂。"}]},{"pos":"adj.","meaning":"乳制品的;产奶的","definition":"relating to milk production or milk products","examples":[{"en":"Keep dairy products in the fridge.","zh":"把乳制品放进冰箱。"},{"en":"The farm has sixty dairy cows.","zh":"这个农场养着六十头奶牛。"}]}],"damage":[{"pos":"n.","meaning":"损害；损坏","definition":"harm that reduces quality or value","examples":[{"en":"The storm caused serious damage to the roof.","zh":"暴风雨严重损坏了屋顶。"},{"en":"The report examined the environmental damage caused by mining.","zh":"报告考察了采矿造成的环境损害。"}]},{"pos":"n.","meaning":"损害赔偿金（用复数 damages）","definition":"money awarded as compensation for harm","examples":[{"en":"The court awarded damages to the injured worker.","zh":"法院判给受伤工人损害赔偿金。"},{"en":"The company paid damages for breaking the contract.","zh":"公司因违约支付了赔偿金。"}]},{"pos":"v.","meaning":"损害；损坏","definition":"to harm something or make it less effective","examples":[{"en":"Salt water can damage electronic equipment.","zh":"盐水会损坏电子设备。"},{"en":"The scandal damaged public trust in the council.","zh":"丑闻损害了公众对议会的信任。"}]}],"damp":[{"pos":"adj.","meaning":"潮湿的","definition":"slightly wet","examples":[{"en":"The towels were still damp after an hour.","zh":"一个小时后，毛巾仍然潮湿。"},{"en":"Avoid storing books in a damp room.","zh":"避免把书存放在潮湿的房间里。"}]},{"pos":"n.","meaning":"湿气；潮湿","definition":"moisture in the air or a building","examples":[{"en":"Damp had damaged the wallpaper.","zh":"湿气损坏了墙纸。"},{"en":"The old house smelled of damp.","zh":"这栋旧房子有一股潮湿的气味。"}]},{"pos":"v.","meaning":"使潮湿","definition":"to make something slightly wet","examples":[{"en":"Damp the cloth before wiping the surface.","zh":"擦拭表面前把布弄湿。"},{"en":"A light rain damped the dusty road.","zh":"一阵小雨把尘土飞扬的道路润湿了。"}]},{"pos":"v.","meaning":"减弱；抑制；使扫兴","definition":"to reduce force, activity, or enthusiasm","examples":[{"en":"Rubber pads damp the vibration of the machine.","zh":"橡胶垫减弱了机器的振动。"},{"en":"The poor weather did not damp their enthusiasm.","zh":"糟糕的天气没有削弱他们的热情。"}]}],"darkroom":[{"pos":"n.","meaning":"暗室","definition":"a room kept dark for developing photographs","examples":[{"en":"She developed the film in a darkroom.","zh":"她在暗室里冲洗胶卷。"},{"en":"Red light illuminated the photographer's darkroom.","zh":"红光照亮了摄影师的暗室。"}]}],"dash":[{"pos":"v.","meaning":"飞奔；猛冲","definition":"to move somewhere very quickly","examples":[{"en":"She dashed upstairs to answer the phone.","zh":"她飞奔上楼接电话。"},{"en":"We dashed for shelter when the rain began.","zh":"开始下雨时我们急忙冲向避雨处。"}]},{"pos":"v.","meaning":"猛掷；猛撞","definition":"to throw or strike something violently","examples":[{"en":"Waves dashed the boat against the rocks.","zh":"海浪把船猛撞在礁石上。"},{"en":"In anger, he dashed the cup to the floor.","zh":"他愤怒地把杯子摔向地板。"}]},{"pos":"v.","meaning":"使希望破灭；使沮丧","definition":"to destroy a hope or expectation","examples":[{"en":"The injury dashed her hopes of competing.","zh":"受伤使她参赛的希望破灭了。"},{"en":"Their confidence was dashed by the sudden defeat.","zh":"突如其来的失败使他们信心全失。"}]},{"pos":"n.","meaning":"飞奔；猛冲","definition":"a sudden rapid movement","examples":[{"en":"He made a dash for the last train.","zh":"他飞奔去赶最后一班火车。"},{"en":"A quick dash across the courtyard left us soaked.","zh":"我们飞快穿过院子，还是淋透了。"}]},{"pos":"n.","meaning":"破折号","definition":"a punctuation mark separating parts of a sentence","examples":[{"en":"Put a dash before the final explanation.","zh":"在最后的解释前加一个破折号。"},{"en":"The editor replaced the comma with a dash.","zh":"编辑把逗号改成了破折号。"}]},{"pos":"n.","meaning":"冲劲；潇洒的活力","definition":"energy and confident style","examples":[{"en":"The young captain led the team with dash.","zh":"年轻队长朝气十足地带领球队。"},{"en":"Her performance had remarkable dash and confidence.","zh":"她的表演活力非凡，充满自信。"}]}],"data":[{"pos":"n.","meaning":"数据；资料","definition":"facts or measurements collected for analysis","examples":[{"en":"The survey collected data from two thousand households.","zh":"调查收集了两千户家庭的数据。"},{"en":"Keep a backup of all important data.","zh":"为所有重要数据保留备份。"}]}],"database":[{"pos":"n.","meaning":"数据库","definition":"an organized collection of electronically stored information","examples":[{"en":"The database stores every customer's address.","zh":"数据库存有每位顾客的地址。"},{"en":"Researchers searched the database for relevant studies.","zh":"研究人员在数据库中检索相关研究。"}]}],"daunt":[{"pos":"v.","meaning":"使气馁；使胆怯","definition":"to make someone feel unable to face a difficulty","examples":[{"en":"The steep climb did not daunt the experienced hikers.","zh":"陡峭的山路没有吓倒经验丰富的徒步者。"},{"en":"She refused to be daunted by the complicated application.","zh":"她不愿因复杂的申请手续而退缩。"}]}],"dazzle":[{"pos":"v.","meaning":"使目眩","definition":"to temporarily impair sight with bright light","examples":[{"en":"The headlights dazzled the approaching driver.","zh":"车头灯使迎面驶来的司机目眩。"},{"en":"Sunlight reflecting off the snow can dazzle walkers.","zh":"雪面反射的阳光会让步行者眼花。"}]},{"pos":"v.","meaning":"使赞叹；使倾倒","definition":"to impress someone greatly","examples":[{"en":"Her performance dazzled the audience.","zh":"她的表演令观众赞叹不已。"},{"en":"The display was designed to dazzle potential investors.","zh":"这场展示旨在给潜在投资者留下惊艳印象。"}]},{"pos":"n.","meaning":"耀眼的光；令人眼花缭乱的效果","definition":"a bright or impressive display","examples":[{"en":"The dazzle of the stage lights hid the audience.","zh":"舞台灯光耀眼，使人看不见观众。"},{"en":"The exhibition mixed quiet detail with visual dazzle.","zh":"展览把宁静的细节与耀眼的视觉效果结合起来。"}]}],"deadline":[{"pos":"n.","meaning":"截止日期","definition":"the latest time by which something must be completed","examples":[{"en":"The deadline for applications is Friday.","zh":"申请截止日期是周五。"},{"en":"We need more time to meet the deadline.","zh":"我们需要更多时间才能赶上截止日期。"},{"en":"Missing the deadline may delay the whole project.","zh":"错过截止日期可能拖延整个项目。"}]}],"dealer":[{"pos":"n.","meaning":"经销商；商人","definition":"a person or business buying and selling goods","examples":[{"en":"The dealer offered a warranty on the used car.","zh":"经销商为这辆二手车提供了保修。"},{"en":"We bought the painting from a local art dealer.","zh":"我们从当地艺术品商人那里买了这幅画。"}]}],"dean":[{"pos":"n.","meaning":"学院院长；系主任","definition":"the head of a faculty or division in a university","examples":[{"en":"The dean welcomed the new medical students.","zh":"院长欢迎新入学的医学生。"},{"en":"She arranged a meeting with the dean of engineering.","zh":"她安排了与工程学院院长的会面。"}]},{"pos":"n.","meaning":"教长；座堂主任牧师","definition":"a senior church official, especially at a cathedral","examples":[{"en":"The dean led the cathedral service.","zh":"教长主持了座堂礼拜。"},{"en":"The cathedral dean announced plans to restore the roof.","zh":"座堂教长宣布了修缮屋顶的计划。"}]}],"dearth":[{"pos":"n.","meaning":"缺乏;短缺","definition":"a lack of something needed","examples":[{"en":"There is a dearth of affordable housing.","zh":"可负担住房十分短缺。"},{"en":"A dearth of evidence weakened the argument.","zh":"证据不足削弱了这一论点。"}]}],"debate":[{"pos":"n.","meaning":"辩论；争论","definition":"a discussion involving different views","examples":[{"en":"The proposal sparked a debate about housing costs.","zh":"该提议引发了关于住房成本的争论。"},{"en":"Students held a debate on renewable energy.","zh":"学生们就可再生能源进行了辩论。"}]},{"pos":"v.","meaning":"辩论；讨论","definition":"to discuss opposing ideas or consider choices","examples":[{"en":"The committee debated whether to extend the deadline.","zh":"委员会讨论了是否延长截止日期。"},{"en":"Researchers continue to debate the cause of the decline.","zh":"研究人员仍在争论下降的原因。"}]}],"debris":[{"pos":"n.","meaning":"碎片；残骸；岩屑","definition":"scattered pieces left after damage or destruction","examples":[{"en":"Workers cleared debris from the road.","zh":"工人清除了道路上的碎片。"},{"en":"The stream carried rocky debris down the mountain.","zh":"溪流把岩屑带下了山。"}]}],"debt":[{"pos":"n.","meaning":"债务","definition":"money that is owed","examples":[{"en":"He hopes to pay off his debt this year.","zh":"他希望今年还清债务。"},{"en":"High interest rates can make debt harder to repay.","zh":"高利率会使债务更难偿还。"},{"en":"The business avoided taking on additional debt.","zh":"这家企业避免了新增债务。"}]}],"decade":[{"pos":"n.","meaning":"十年；十年期","definition":"a period of ten years","examples":[{"en":"The town has doubled in size over a decade.","zh":"这个镇十年来规模扩大了一倍。"},{"en":"She spent a decade studying marine ecosystems.","zh":"她花了十年研究海洋生态系统。"}]}],"decapitate":[{"pos":"v.","meaning":"斩首；切去头部","definition":"to remove the head from a body or object","examples":[{"en":"The historical document describes prisoners who were decapitated.","zh":"这份历史文献描述了被斩首的囚犯。"},{"en":"The storm decapitated the stone statue in the garden.","zh":"暴风雨把花园石像的头部毁掉了。"}]}],"decay":[{"pos":"n.","meaning":"腐烂;腐朽","definition":"the process of rotting or being destroyed gradually","examples":[{"en":"The dentist found signs of tooth decay.","zh":"牙医发现了蛀牙的迹象。"},{"en":"Damp wood is vulnerable to decay.","zh":"潮湿木材容易腐烂。"}]},{"pos":"n.","meaning":"衰败;衰退","definition":"a gradual decline in quality or strength","examples":[{"en":"Empty factories showed the town's economic decay.","zh":"空置工厂显示出该镇经济的衰退。"},{"en":"The report describes decades of urban decay.","zh":"报告描述了数十年的城市衰败。"}]},{"pos":"v.","meaning":"腐烂;腐朽","definition":"to rot or break down gradually","examples":[{"en":"Leaves decay on the forest floor.","zh":"树叶在森林地面上腐烂。"},{"en":"The wooden beams had begun to decay.","zh":"木梁已经开始腐朽。"}]},{"pos":"v.","meaning":"衰败;衰退","definition":"to lose quality or strength gradually","examples":[{"en":"Public institutions decayed under years of neglect.","zh":"公共机构因多年疏于管理而衰败。"},{"en":"The old trading port slowly decayed.","zh":"这座旧贸易港逐渐衰落。"}]}],"deceive":[{"pos":"v.","meaning":"欺骗；蒙骗","definition":"to cause someone to believe something untrue","examples":[{"en":"The seller deceived customers about the product's origin.","zh":"卖家在产品产地上欺骗顾客。"},{"en":"Appearances can deceive even experienced observers.","zh":"即使有经验的观察者也可能被表象蒙骗。"}]}],"decent":[{"pos":"adj.","meaning":"像样的；体面的；合乎需要的","definition":"of an acceptable or satisfactory standard","examples":[{"en":"Everyone deserves a decent place to live.","zh":"每个人都应有一个像样的住所。"},{"en":"The café serves a decent lunch at a reasonable price.","zh":"这家咖啡馆以合理价格供应不错的午餐。"}]},{"pos":"adj.","meaning":"正派的；合乎礼仪的","definition":"honest, kind, and socially appropriate","examples":[{"en":"It was decent of her to offer help.","zh":"她主动提供帮助，真是个厚道人。"},{"en":"Please use decent language during the meeting.","zh":"开会时请使用文明的语言。"}]}],"deception":[{"pos":"n.","meaning":"欺骗;骗局;诡计","definition":"the act of making someone believe something false","examples":[{"en":"The investigation exposed years of deliberate deception.","zh":"调查揭露了多年的蓄意欺骗。"},{"en":"His forged certificate was an elaborate deception.","zh":"他伪造的证书是一场精心策划的骗局。"}]}],"decibel":[{"pos":"n.","meaning":"分贝","definition":"a unit used to express sound levels and certain ratios","examples":[{"en":"The meter measures noise levels in decibels.","zh":"这台仪表以分贝测量噪声水平。"},{"en":"The report compared the decibel readings from two streets.","zh":"报告比较了两条街的分贝读数。"}]}],"decipher":[{"pos":"v.","meaning":"破译；辨认；解释","definition":"to work out the meaning of difficult writing or a code","examples":[{"en":"Experts tried to decipher the ancient inscription.","zh":"专家们试图解读这段古代铭文。"},{"en":"I could hardly decipher his hurried handwriting.","zh":"我几乎无法辨认他匆忙写下的字迹。"}]}],"decisive":[{"pos":"adj.","meaning":"决定性的","definition":"having a major effect on a result","examples":[{"en":"Her testimony provided the decisive evidence.","zh":"她的证词提供了决定性证据。"},{"en":"The goalkeeper made a decisive save.","zh":"守门员作出了一次决定性的扑救。"}]},{"pos":"adj.","meaning":"果断的","definition":"able to make decisions quickly and confidently","examples":[{"en":"A decisive leader took control during the emergency.","zh":"一位果断的领导者在紧急情况下掌控了局面。"},{"en":"She was decisive about rejecting the offer.","zh":"她果断地拒绝了这个提议。"}]}],"declaration":[{"pos":"n.","meaning":"声明；宣布；宣言","definition":"a formal public statement or announcement","examples":[{"en":"The mayor issued a declaration of support.","zh":"市长发表了支持声明。"},{"en":"The declaration called for equal access to education.","zh":"这份宣言呼吁平等的受教育机会。"}]},{"pos":"n.","meaning":"申报；申报单","definition":"an official statement of information","examples":[{"en":"Travellers must complete a customs declaration.","zh":"旅客必须填写海关申报单。"},{"en":"She checked the income figures on her tax declaration.","zh":"她核对了纳税申报表上的收入数字。"}]}],"declare":[{"pos":"v.","meaning":"宣布；声明；申报","definition":"to state something officially or clearly","examples":[{"en":"The council declared the building unsafe.","zh":"市政委员会宣布这栋建筑不安全。"},{"en":"Travellers must declare certain goods at customs.","zh":"旅客必须在海关申报某些货物。"}]}],"decline":[{"pos":"n.","meaning":"下降;减少;衰退","definition":"a reduction in amount or strength","examples":[{"en":"The survey recorded a decline in smoking.","zh":"调查记录了吸烟人数的下降。"},{"en":"The factory closed after years of decline.","zh":"这家工厂多年衰落后关闭了。"}]},{"pos":"v.","meaning":"下降;减少;衰退","definition":"to become smaller or weaker","examples":[{"en":"Sales declined during the winter.","zh":"销量在冬季下降了。"},{"en":"His health declined after the operation.","zh":"手术后他的健康状况恶化了。"}]},{"pos":"v.","meaning":"婉拒;拒绝","definition":"to refuse politely","examples":[{"en":"She declined an invitation to dinner.","zh":"她婉拒了晚餐邀请。"},{"en":"The witness declined to comment.","zh":"证人拒绝发表评论。"}]}],"decompose":[{"pos":"v.","meaning":"腐烂；分解","definition":"to break down into simpler substances","examples":[{"en":"Fallen leaves decompose on the forest floor.","zh":"落叶在森林地面腐烂。"},{"en":"The analysis decomposes the signal into separate frequencies.","zh":"该分析将信号分解为不同频率的成分。"}]}],"decompression":[{"pos":"n.","meaning":"减压；解压缩","definition":"a reduction in pressure or restoration of compressed data","examples":[{"en":"The crew practised procedures for sudden cabin decompression.","zh":"机组人员演练了机舱突然失压时的流程。"},{"en":"The archive needs decompression before the files can be opened.","zh":"这个压缩包需要解压后才能打开文件。"}]}],"decorate":[{"pos":"v.","meaning":"装饰;布置","definition":"to make something attractive by adding ornaments or colour","examples":[{"en":"They decorated the hall with paper flowers.","zh":"他们用纸花装饰大厅。"},{"en":"We decorated the bedroom in pale green.","zh":"我们把卧室装饰成了浅绿色。"}]},{"pos":"v.","meaning":"授勋;嘉奖","definition":"to award someone a medal or honour","examples":[{"en":"The pilot was decorated for bravery.","zh":"这位飞行员因英勇表现获得勋章。"},{"en":"The government decorated three rescue workers.","zh":"政府授勋表彰了三名救援人员。"}]}],"decoration":[{"pos":"n.","meaning":"装饰；装潢","definition":"the process or effect of making something attractive","examples":[{"en":"The hall needs decoration before the celebration.","zh":"庆典前大厅需要装饰。"},{"en":"They chose pale colours for the interior decoration.","zh":"他们选择浅色进行室内装潢。"}]},{"pos":"n.","meaning":"装饰品","definition":"an object used to make something attractive","examples":[{"en":"Paper decorations hung above the tables.","zh":"纸装饰品挂在餐桌上方。"},{"en":"She placed a small glass decoration on the shelf.","zh":"她在架上摆了一件小玻璃饰品。"}]}],"decouple":[{"pos":"v.","meaning":"使分离；使脱钩；减弱联系","definition":"to separate things that were connected","examples":[{"en":"The policy aims to decouple growth from carbon emissions.","zh":"这项政策旨在使经济增长与碳排放脱钩。"},{"en":"The engineers decoupled the motor from the test rig.","zh":"工程师把电动机与测试台分离了。"}]}],"decrease":[{"pos":"v.","meaning":"减少;降低","definition":"to become or make smaller in amount","examples":[{"en":"Rainfall decreased sharply in July.","zh":"七月降雨量急剧下降。"},{"en":"Better insulation decreases energy use.","zh":"更好的隔热措施能减少能源消耗。"}],"ipa":"/dɪˈkriːs/"},{"pos":"n.","meaning":"减少;减少量","definition":"a reduction in amount or size","examples":[{"en":"The figures show a decrease in unemployment.","zh":"这些数据表明失业率下降了。"},{"en":"A ten percent decrease saved considerable fuel.","zh":"减少百分之十节省了大量燃料。"}],"ipa":"/ˈdiːkriːs/"}],"decrepit":[{"pos":"adj.","meaning":"破旧的；年久失修的","definition":"worn out and in very poor condition","examples":[{"en":"They replaced the decrepit bridge with a safer structure.","zh":"他们用更安全的桥替换了那座破旧的桥。"},{"en":"A decrepit bus waited outside the station.","zh":"一辆破旧的巴士停在车站外。"}]},{"pos":"adj.","meaning":"衰老体弱的","definition":"physically weakened by old age","examples":[{"en":"The novel describes a decrepit king clinging to power.","zh":"小说描写了一位衰老体弱却紧抓权力的国王。"},{"en":"The decrepit horse could no longer pull the cart.","zh":"那匹衰老的马已无法拉车。"}]}],"dedicate":[{"pos":"v.","meaning":"奉献；投入","definition":"to give time or effort to a purpose","examples":[{"en":"She dedicated her career to improving rural education.","zh":"她把职业生涯奉献给了改善乡村教育。"},{"en":"We dedicate two hours each week to training.","zh":"我们每周投入两个小时训练。"}]},{"pos":"v.","meaning":"题献；把作品献给","definition":"to name someone as the person a work honours","examples":[{"en":"The author dedicated the book to his parents.","zh":"作者把这本书献给父母。"},{"en":"She dedicated the final song to the volunteers.","zh":"她把最后一首歌献给志愿者们。"}]}],"deduce":[{"pos":"v.","meaning":"推断;演绎","definition":"to reach a conclusion from known facts","examples":[{"en":"We deduced his route from the footprints.","zh":"我们根据脚印推断出他的路线。"},{"en":"She deduced that the figures were incomplete.","zh":"她推断这些数据并不完整。"}]}],"deem":[{"pos":"v.","meaning":"认为；视为","definition":"to consider or judge something to be","examples":[{"en":"The building was deemed unsafe after the inspection.","zh":"检查后，这栋建筑被认定不安全。"},{"en":"We may request further evidence if deemed necessary.","zh":"如认为有必要，我们可能要求更多证据。"}]}],"defeat":[{"pos":"v.","meaning":"击败；使受挫","definition":"to win against or prevent success","examples":[{"en":"The local team defeated the visiting champions.","zh":"本地队击败了来访的冠军队。"},{"en":"A lack of funding defeated their plans.","zh":"资金不足使他们的计划受挫。"}]},{"pos":"n.","meaning":"失败；战败","definition":"the state or event of losing","examples":[{"en":"The narrow defeat encouraged them to train harder.","zh":"这场惜败促使他们更加努力训练。"},{"en":"He accepted defeat without blaming the other players.","zh":"他接受了失败，没有责怪其他队员。"}]}],"defect":[{"pos":"n.","meaning":"缺陷","definition":"a fault in something","examples":[{"en":"The engineer found a defect in the door.","zh":"工程师发现了门上的一个缺陷。"},{"en":"A small defect caused the machine to stop.","zh":"一个小缺陷导致机器停止运转。"},{"en":"They checked the product for a defect.","zh":"他们检查产品是否存在缺陷。"}],"ipa":"/ˈdiːfekt/"},{"pos":"v.","meaning":"叛离;投奔另一方","definition":"to leave one side and join another","examples":[{"en":"Several members defected to the opposition.","zh":"几位成员转投反对派。"},{"en":"The officer defected during the conflict.","zh":"军官在冲突期间叛离。"}],"ipa":"/dɪˈfekt/"}],"defence":[{"pos":"n.","meaning":"防御；保护","definition":"protection against attack or harm","examples":[{"en":"The sea wall provides a defence against flooding.","zh":"海堤提供了防洪保护。"},{"en":"The team strengthened its defence after conceding two goals.","zh":"球队丢了两球后加强了防守。"}]},{"pos":"n.","meaning":"辩护；答辩","definition":"arguments or evidence supporting a person or position","examples":[{"en":"She presented a strong defence of the policy.","zh":"她对这项政策作了有力辩护。"},{"en":"The lawyer prepared the defendant's defence.","zh":"律师准备了被告的答辩。"}]},{"pos":"n.","meaning":"防御工事（常用复数）","definition":"structures or systems used to resist attack","examples":[{"en":"The castle's outer defences are still visible.","zh":"城堡外围的防御工事仍然可见。"},{"en":"Workers repaired the coastal defences before winter.","zh":"工人在冬季前修复了海岸防御设施。"}]}],"defendant":[{"pos":"n.","meaning":"被告","definition":"a person or organization accused in a legal case","examples":[{"en":"The defendant denied the allegation.","zh":"被告否认了这项指控。"},{"en":"The court heard evidence from the defendant.","zh":"法庭听取了被告的证词。"}]},{"pos":"adj.","meaning":"被告方的","definition":"being the party defending a legal action","examples":[{"en":"The defendant company supplied its financial records.","zh":"被告公司提供了财务记录。"},{"en":"The defendant party requested more time to respond.","zh":"被告方请求更多答辩时间。"}]}],"deficiency":[{"pos":"n.","meaning":"缺乏;不足;缺陷","definition":"a shortage or weakness in something","examples":[{"en":"The tests revealed an iron deficiency.","zh":"检测显示存在缺铁情况。"},{"en":"The review identified deficiencies in staff training.","zh":"审查发现了员工培训的不足。"}]}],"deficit":[{"pos":"n.","meaning":"赤字；不足额","definition":"an amount by which something falls short","examples":[{"en":"The city faces a large budget deficit.","zh":"该市面临巨额预算赤字。"},{"en":"The team recovered from a two-goal deficit.","zh":"球队扳回了落后两球的劣势。"}]}],"define":[{"pos":"v.","meaning":"下定义；解释含义","definition":"to state the precise meaning of something","examples":[{"en":"The introduction defines the key terms.","zh":"引言解释了关键术语。"},{"en":"How would you define a successful project?","zh":"你会如何定义一个成功的项目？"}]},{"pos":"v.","meaning":"界定；限定","definition":"to establish clear limits or features","examples":[{"en":"The contract defines each partner's responsibilities.","zh":"合同界定了每位合伙人的责任。"},{"en":"A river defines the western boundary of the park.","zh":"一条河界定了公园的西边界。"}]}],"definite":[{"pos":"adj.","meaning":"明确的;确定的","definition":"clear and certain","examples":[{"en":"We need a definite answer by Friday.","zh":"我们需要在周五之前得到明确答复。"},{"en":"There has been a definite improvement.","zh":"情况有了明确的改善。"}]}],"definition":[{"pos":"n.","meaning":"定义；释义","definition":"an explanation of the meaning of a word or concept","examples":[{"en":"The textbook gives a clear definition of inflation.","zh":"教材给出了通货膨胀的清晰定义。"},{"en":"Researchers must agree on a definition of success.","zh":"研究人员必须就成功的定义达成一致。"}]},{"pos":"n.","meaning":"清晰度；鲜明程度","definition":"the sharpness of an image or outline","examples":[{"en":"The new screen displays images with greater definition.","zh":"新屏幕显示的图像更清晰。"},{"en":"Side lighting gave the sculpture's edges more definition.","zh":"侧面照明使雕塑的轮廓更加鲜明。"}]}],"deflect":[{"pos":"v.","meaning":"使偏转；转移","definition":"to change the direction of movement or attention","examples":[{"en":"The shield deflects small particles away from the sensor.","zh":"防护罩使小颗粒偏离传感器。"},{"en":"He tried to deflect attention from the missing report.","zh":"他试图把人们的注意力从丢失的报告上转移开。"}]}],"degenerate":[{"pos":"v.","meaning":"退化;恶化","definition":"to become worse in quality or condition","examples":[{"en":"The discussion degenerated into personal insults.","zh":"讨论恶化成了人身攻击。"},{"en":"Unused muscle tissue can degenerate over time.","zh":"长期不用的肌肉组织会逐渐退化。"}],"ipa":"/dɪˈdʒenəreɪt/"},{"pos":"adj.","meaning":"退化的;堕落的","definition":"having declined in quality or moral standards","examples":[{"en":"The scan showed degenerate tissue around the joint.","zh":"扫描显示关节周围有退化组织。"},{"en":"The novel portrays a cruel, degenerate aristocracy.","zh":"小说描绘了一个残酷而堕落的贵族阶层。"}],"ipa":"/dɪˈdʒenərət/"}],"degrade":[{"pos":"v.","meaning":"贬低；使受辱；使堕落","definition":"to reduce someone's dignity or moral standing","examples":[{"en":"Public insults degrade both speaker and listener.","zh":"公开辱骂有损说者和听者的尊严。"},{"en":"The story shows how unchecked power can degrade a person.","zh":"故事表现了不受约束的权力如何使人堕落。"}]},{"pos":"v.","meaning":"降级；降低地位","definition":"to reduce someone or something in rank","examples":[{"en":"The officer was degraded for serious misconduct.","zh":"该军官因严重不当行为被降职。"},{"en":"The old classification degraded local languages to mere dialects.","zh":"旧的分类把当地语言降格为方言。"}]},{"pos":"v.","meaning":"降解；退化；降低质量","definition":"to break down or become worse in quality","examples":[{"en":"Sunlight can degrade some plastics over time.","zh":"阳光会使某些塑料随时间降解。"},{"en":"Repeated copying degraded the quality of the recording.","zh":"反复复制降低了录音质量。"}]}],"delay":[{"pos":"n.","meaning":"延误","definition":"a period of waiting beyond the expected time","examples":[{"en":"There was a two-hour delay because of fog.","zh":"由于大雾，出现了两小时延误。"},{"en":"Passengers received a refund after the long delay.","zh":"长时间延误后，乘客获得了退款。"},{"en":"Please allow extra time in case of a delay.","zh":"请预留额外时间，以防延误。"}]},{"pos":"v.","meaning":"推迟；耽搁；使延误","definition":"To make something happen later or move more slowly.","examples":[{"en":"Heavy snow delayed the flight.","zh":"大雪延误了航班。"},{"en":"They delayed the decision until more evidence arrived.","zh":"他们推迟了决定，等待更多证据。"}]}],"delegate":[{"pos":"n.","meaning":"代表;代表团成员","definition":"a person chosen to represent a group","examples":[{"en":"Each district elected a delegate.","zh":"每个区选出了一名代表。"},{"en":"The delegates approved the revised proposal.","zh":"代表们批准了修改后的提案。"}],"ipa":"/ˈdelɪɡət/"},{"pos":"v.","meaning":"委托;授权;委派","definition":"to give someone a duty or authority","examples":[{"en":"Managers should delegate routine tasks.","zh":"管理者应把日常工作委派给他人。"},{"en":"She was delegated to negotiate the agreement.","zh":"她被委派去谈判这项协议。"}],"ipa":"/ˈdelɪɡeɪt/"}],"deliberate":[{"pos":"adj.","meaning":"故意的；蓄意的","definition":"done intentionally","examples":[{"en":"The damage was a deliberate act of vandalism.","zh":"这些损坏是蓄意破坏造成的。"},{"en":"She made a deliberate effort to include everyone.","zh":"她有意识地努力让所有人都参与。"}],"ipa":"/dɪˈlɪbərət/"},{"pos":"adj.","meaning":"深思熟虑的","definition":"carefully considered before being done","examples":[{"en":"Closing the branch was a deliberate decision.","zh":"关闭分部是一个经过深思熟虑的决定。"},{"en":"Their deliberate approach reduced costly mistakes.","zh":"他们审慎的方法减少了代价高昂的错误。"}],"ipa":"/dɪˈlɪbərət/"},{"pos":"adj.","meaning":"从容的；不慌不忙的","definition":"slow and careful in movement or speech","examples":[{"en":"He spoke in a calm, deliberate voice.","zh":"他说话语气平静，不慌不忙。"},{"en":"She crossed the room with deliberate steps.","zh":"她从容地迈步穿过房间。"}],"ipa":"/dɪˈlɪbərət/"},{"pos":"v.","meaning":"仔细考虑；审议","definition":"to consider something carefully before deciding","examples":[{"en":"The jury deliberated for several hours.","zh":"陪审团审议了数小时。"},{"en":"We need time to deliberate on the alternatives.","zh":"我们需要时间仔细考虑各个方案。"}],"ipa":"/dɪˈlɪbəreɪt/"}],"delicate":[{"pos":"adj.","meaning":"纤细的；精巧的；易损的","definition":"fine in structure and easily damaged","examples":[{"en":"The necklace has a delicate silver chain.","zh":"这条项链有一根纤细的银链。"},{"en":"Handle the delicate instrument with care.","zh":"小心操作这台精密易损的仪器。"}]},{"pos":"adj.","meaning":"微妙的；需要谨慎处理的","definition":"requiring sensitivity and careful judgement","examples":[{"en":"The talks reached a delicate stage.","zh":"谈判进入了微妙阶段。"},{"en":"Discussing the error with her required a delicate approach.","zh":"和她讨论这个错误需要谨慎得体的方式。"}]}],"delinquency":[{"pos":"n.","meaning":"青少年违法行为;行为不良","definition":"illegal or antisocial behaviour, especially by young people","examples":[{"en":"The programme aims to reduce juvenile delinquency.","zh":"该项目旨在减少青少年违法行为。"},{"en":"Researchers examined links between exclusion and delinquency.","zh":"研究人员考察了排斥与不良行为之间的联系。"}]},{"pos":"n.","meaning":"失职;未履行义务","definition":"failure to do a required duty or make required payments","examples":[{"en":"The audit revealed serious delinquency in collecting taxes.","zh":"审计发现征税工作存在严重失职。"},{"en":"Mortgage delinquency rose after the factory closed.","zh":"工厂关闭后房贷拖欠情况增加了。"}]}],"delinquent":[{"pos":"adj.","meaning":"违法的；有犯罪行为的","definition":"involved in illegal behaviour, especially when young","examples":[{"en":"The programme offers support to delinquent teenagers.","zh":"该项目向有违法行为的青少年提供支持。"},{"en":"The study examined factors behind delinquent behaviour.","zh":"研究考察了违法行为背后的因素。"}]},{"pos":"adj.","meaning":"失职的；未尽职责的","definition":"failing to fulfil a duty","examples":[{"en":"The board was delinquent in supervising the accounts.","zh":"董事会在监督账目方面失职。"},{"en":"Officials who are delinquent in their duties face investigation.","zh":"未履行职责的官员面临调查。"}]},{"pos":"adj.","meaning":"拖欠的；逾期未付的","definition":"not paid or completed by the due date","examples":[{"en":"The bank contacted borrowers with delinquent loans.","zh":"银行联系了拖欠贷款的借款人。"},{"en":"A fee applies to delinquent accounts.","zh":"逾期账户会被收取费用。"}]},{"pos":"n.","meaning":"违法者；少年犯","definition":"a person, especially a young person, who breaks the law","examples":[{"en":"The centre helps young delinquents return to education.","zh":"该中心帮助少年违法者重返校园。"},{"en":"The judge referred the delinquent to a rehabilitation programme.","zh":"法官将这名违法少年转介到康复项目。"}]}],"deliver":[{"pos":"v.","meaning":"递送；交付","definition":"to take something to its intended destination","examples":[{"en":"The courier will deliver the parcel tomorrow.","zh":"快递员明天将送来包裹。"},{"en":"The team delivered the completed design on time.","zh":"团队按时交付了完成的设计。"}]},{"pos":"v.","meaning":"发表；表达","definition":"to give a speech or message","examples":[{"en":"She delivered a clear presentation of the findings.","zh":"她清楚地发表了研究结果介绍。"},{"en":"The actor delivered the final line quietly.","zh":"演员轻声说出了最后一句台词。"}]},{"pos":"v.","meaning":"接生；分娩","definition":"to assist a birth or give birth","examples":[{"en":"The doctor delivered the baby safely.","zh":"医生安全地接生了婴儿。"},{"en":"She delivered a healthy daughter at the local hospital.","zh":"她在当地医院生下了一个健康的女儿。"}]},{"pos":"v.","meaning":"解救；使摆脱（deliver from）","definition":"to rescue someone from danger or difficulty","examples":[{"en":"The rescue team delivered the climbers from danger.","zh":"救援队使登山者脱离了危险。"},{"en":"The story tells of villagers delivered from oppression.","zh":"故事讲述村民摆脱压迫的经历。"}]}],"delivery":[{"pos":"n.","meaning":"配送；交付","definition":"the act of bringing goods to someone","examples":[{"en":"Delivery is free for orders over fifty pounds.","zh":"订单超过五十英镑可免费配送。"},{"en":"Please arrange delivery for Friday afternoon.","zh":"请安排在周五下午送货。"},{"en":"The delivery address is different from my billing address.","zh":"收货地址与我的账单地址不同。"}]},{"pos":"n.","meaning":"分娩","definition":"the process of giving birth","examples":[{"en":"The hospital has a dedicated delivery ward.","zh":"医院设有专门产房。"},{"en":"The midwife assisted with a difficult delivery.","zh":"助产士协助了一次困难分娩。"}]}],"delta":[{"pos":"n.","meaning":"三角洲","definition":"land formed by river sediment near its mouth","examples":[{"en":"Farmers cultivate fertile land in the river delta.","zh":"农民耕种河流三角洲的肥沃土地。"},{"en":"The delta supports a wide variety of wetland birds.","zh":"这片三角洲养育着多种湿地鸟类。"}]},{"pos":"n.","meaning":"德尔塔；希腊字母表第四个字母","definition":"the fourth letter of the Greek alphabet","examples":[{"en":"The diagram uses delta to represent a change.","zh":"图中用德尔塔表示变化量。"},{"en":"She wrote a capital delta beside the equation.","zh":"她在方程旁写了一个大写德尔塔。"}]}],"demand":[{"pos":"n.","meaning":"要求","definition":"a firm request","examples":[{"en":"The workers presented their demands to management.","zh":"工人向管理层提出了要求。"},{"en":"The letter contained a demand for an explanation.","zh":"信中要求对方作出解释。"}]},{"pos":"n.","meaning":"需求；需求量","definition":"the amount of something people need or want","examples":[{"en":"Demand for affordable housing continues to grow.","zh":"对可负担住房的需求持续增长。"},{"en":"The factory increased output to meet demand.","zh":"工厂增加产量以满足需求。"}]},{"pos":"v.","meaning":"要求；追问","definition":"to ask firmly for something or an answer","examples":[{"en":"Residents demanded action on the polluted river.","zh":"居民要求采取行动治理受污染的河流。"},{"en":"She demanded to know why the appointment was cancelled.","zh":"她追问预约为什么被取消。"}]},{"pos":"v.","meaning":"需要","definition":"to require effort, skill, or resources","examples":[{"en":"The task demands careful attention to detail.","zh":"这项任务需要细致关注细节。"},{"en":"Caring for the garden demands time and patience.","zh":"照料花园需要时间和耐心。"}]}],"demerit":[{"pos":"n.","meaning":"缺点;过失;记过","definition":"a fault or a mark given for bad behaviour","examples":[{"en":"The committee weighed the scheme's merits and demerits.","zh":"委员会权衡了方案的优缺点。"},{"en":"Repeated lateness earned him three demerits.","zh":"屡次迟到使他被记了三次过。"}]}],"democratic":[{"pos":"adj.","meaning":"民主的；有民主精神的","definition":"based on equal participation or government by the people","examples":[{"en":"The association elects its leaders through a democratic vote.","zh":"协会通过民主投票选举领导人。"},{"en":"The teacher encouraged a democratic discussion of classroom rules.","zh":"老师鼓励大家民主讨论课堂规则。"}]}],"demographic":[{"pos":"adj.","meaning":"人口的；人口统计学的","definition":"relating to the characteristics of a population","examples":[{"en":"The report examines demographic changes in rural areas.","zh":"报告考察了农村地区的人口变化。"},{"en":"We compared the demographic profiles of the two districts.","zh":"我们比较了两个地区的人口特征。"}]}],"demolish":[{"pos":"v.","meaning":"拆毁;摧毁","definition":"to destroy a building or other structure","examples":[{"en":"Workers demolished the unsafe bridge.","zh":"工人拆除了不安全的桥。"},{"en":"The earthquake demolished several houses.","zh":"地震摧毁了几座房屋。"}]},{"pos":"v.","meaning":"驳倒;推翻","definition":"to show that an argument is completely wrong","examples":[{"en":"New evidence demolished the prosecution's case.","zh":"新证据彻底推翻了检方的论证。"},{"en":"Her analysis demolished their central assumption.","zh":"她的分析驳倒了他们的核心假设。"}]}],"demolition":[{"pos":"n.","meaning":"拆除；摧毁","definition":"the deliberate destruction of a building or structure","examples":[{"en":"Demolition of the old factory begins next month.","zh":"旧工厂的拆除工作下月开始。"},{"en":"Residents opposed the demolition of the historic cinema.","zh":"居民反对拆除这座历史悠久的电影院。"}]},{"pos":"n.","meaning":"彻底击败；彻底驳倒","definition":"a complete defeat or destruction of an argument","examples":[{"en":"The final became a demolition of the defending champions.","zh":"决赛中卫冕冠军遭到了惨败。"},{"en":"Her article offered a careful demolition of the theory.","zh":"她的文章缜密地彻底驳倒了该理论。"}]}],"demonstrate":[{"pos":"v.","meaning":"证明；显示","definition":"to show clearly that something is true","examples":[{"en":"The results demonstrate the value of early planning.","zh":"结果证明了提前规划的价值。"},{"en":"Her work demonstrates a strong understanding of the topic.","zh":"她的作品显示出对主题的深刻理解。"}]},{"pos":"v.","meaning":"演示；示范","definition":"to show how something works","examples":[{"en":"The instructor demonstrated how to use the equipment.","zh":"教师演示了设备的使用方法。"},{"en":"He demonstrated the new application to the team.","zh":"他向团队演示了新应用。"}]},{"pos":"v.","meaning":"示威；举行抗议活动","definition":"to join a public protest","examples":[{"en":"Residents demonstrated against the closure of the hospital.","zh":"居民举行示威，反对关闭医院。"},{"en":"Students demonstrated peacefully outside the main building.","zh":"学生在主楼外和平示威。"}]}],"demonstration":[{"pos":"n.","meaning":"示范;演示","definition":"an explanation showing how something works","examples":[{"en":"The chef gave a demonstration of knife skills.","zh":"厨师演示了刀工。"},{"en":"We watched a demonstration of the software.","zh":"我们观看了软件演示。"}]},{"pos":"n.","meaning":"证明;显示;表露","definition":"evidence or an act showing something clearly","examples":[{"en":"The result was a demonstration of teamwork.","zh":"这个结果体现了团队合作。"},{"en":"Her visit was a public demonstration of support.","zh":"她的到访公开表达了支持。"}]},{"pos":"n.","meaning":"示威;示威游行","definition":"a public gathering to express a political opinion","examples":[{"en":"Thousands joined the peaceful demonstration.","zh":"数千人参加了和平示威。"},{"en":"The demonstration demanded safer working conditions.","zh":"示威要求改善工作安全条件。"}]}],"denomination":[{"pos":"n.","meaning":"宗教派别；教派","definition":"a religious group within a larger faith","examples":[{"en":"Several Christian denominations share the building.","zh":"几个基督教教派共用这栋建筑。"},{"en":"The school welcomes pupils from every denomination.","zh":"这所学校欢迎各教派的学生。"}]},{"pos":"n.","meaning":"面额；计量单位","definition":"a named unit of money or measurement","examples":[{"en":"The machine accepts coins of several denominations.","zh":"这台机器接受几种面额的硬币。"},{"en":"She sorted the banknotes by denomination.","zh":"她按面额把纸币分类。"}]},{"pos":"n.","meaning":"名称；命名（正式或少见用法）","definition":"a name or the act of giving a name","examples":[{"en":"The wine is sold under a regional denomination.","zh":"这种葡萄酒以一个地区名称销售。"},{"en":"The document uses an older denomination for the region.","zh":"这份文件使用了该地区的一个旧名称。"}]}],"denote":[{"pos":"v.","meaning":"表示；指示；意味着","definition":"to represent or be a sign of something","examples":[{"en":"A red line denotes the old city boundary.","zh":"红线表示旧城边界。"},{"en":"The symbol denotes a protected natural area.","zh":"这个符号表示受保护的自然区域。"}]}],"dense":[{"pos":"adj.","meaning":"密集的;浓厚的","definition":"containing many things close together","examples":[{"en":"A dense forest covered the hillside.","zh":"茂密的森林覆盖着山坡。"},{"en":"Dense fog delayed the morning flights.","zh":"浓雾使早班航班延误了。"}]}],"density":[{"pos":"n.","meaning":"密度；密集程度；分布密度","definition":"the amount of something in a given space","examples":[{"en":"Population density is high in the city centre.","zh":"市中心人口密度很高。"},{"en":"Higher housing density can make public transport more viable.","zh":"更高的住宅密度可以提高公共交通的可行性。"},{"en":"The study compared traffic density on several roads.","zh":"这项研究比较了几条道路的车流密度。"}]},{"pos":"n.","meaning":"密度（单位体积的质量）","definition":"the mass of a substance per unit of volume","examples":[{"en":"We calculated the metal's density from its mass and volume.","zh":"我们根据金属的质量和体积计算其密度。"},{"en":"The density of ice is lower than that of liquid water.","zh":"冰的密度小于液态水的密度。"}]}],"deny":[{"pos":"v.","meaning":"否认","definition":"to state that something is not true","examples":[{"en":"He denied causing the damage.","zh":"他否认造成了损坏。"},{"en":"The company denied that any records were missing.","zh":"公司否认有任何记录丢失。"}]},{"pos":"v.","meaning":"拒绝给予；不允许","definition":"to refuse someone something","examples":[{"en":"The request for additional funding was denied.","zh":"追加资金的申请被拒绝了。"},{"en":"Nobody should be denied access to basic education.","zh":"不应剥夺任何人接受基础教育的机会。"}]}],"depart":[{"pos":"v.","meaning":"离开;启程","definition":"to leave a place","examples":[{"en":"Our train departs at six.","zh":"我们的火车六点出发。"},{"en":"The visitors departed before sunset.","zh":"访客们在日落前离开了。"}]}],"departmental":[{"pos":"adj.","meaning":"部门的；院系的","definition":"relating to a department","examples":[{"en":"Departmental budgets will be reviewed next week.","zh":"各部门预算将在下周审查。"},{"en":"She presented her research at a departmental seminar.","zh":"她在院系研讨会上介绍了自己的研究。"}]}],"departure":[{"pos":"n.","meaning":"出发；离开","definition":"the act of leaving a place","examples":[{"en":"Check the departure time before leaving home.","zh":"离家前请查看出发时间。"},{"en":"The departure gate is shown on your boarding pass.","zh":"登机牌上标有登机口。"},{"en":"Passengers must arrive thirty minutes before departure.","zh":"乘客须在出发前三十分钟到达。"}]},{"pos":"n.","meaning":"背离；违反；偏离惯例","definition":"A change away from an established practice or standard.","examples":[{"en":"The design is a departure from the firm's usual style.","zh":"这个设计有别于公司一贯风格。"},{"en":"Any departure from the safety procedure must be reported.","zh":"任何违反安全程序的情况都必须报告。"}]}],"depend":[{"pos":"v.","meaning":"依靠;信赖","definition":"to need or trust someone or something","examples":[{"en":"Young children depend on their parents.","zh":"年幼的孩子依靠父母。"},{"en":"You can depend on her to keep a promise.","zh":"你可以相信她会遵守承诺。"}]},{"pos":"v.","meaning":"取决于;视情况而定","definition":"to be determined by something","examples":[{"en":"The price depends on the room size.","zh":"价格取决于房间大小。"},{"en":"Whether we go depends on the weather.","zh":"我们是否去取决于天气。"}]}],"depict":[{"pos":"v.","meaning":"描绘；描述","definition":"to represent something in words or images","examples":[{"en":"The mural depicts everyday life in the harbour.","zh":"壁画描绘了港口的日常生活。"},{"en":"The novel depicts the tensions within a large family.","zh":"小说描写了一个大家庭内部的矛盾。"}]}],"deplete":[{"pos":"v.","meaning":"消耗；使枯竭","definition":"to reduce a supply greatly","examples":[{"en":"Years of drought depleted the reservoir.","zh":"多年干旱使水库几近枯竭。"},{"en":"Repeated repairs depleted our savings.","zh":"反复维修耗尽了我们的积蓄。"}]}],"depletion":[{"pos":"n.","meaning":"消耗;耗尽;减少","definition":"a reduction in the available supply","examples":[{"en":"Overfishing causes the depletion of fish stocks.","zh":"过度捕捞导致鱼类资源减少。"},{"en":"The report warns of groundwater depletion.","zh":"报告警告地下水资源正在耗竭。"}]}],"deploy":[{"pos":"v.","meaning":"部署；调动","definition":"to move people or equipment into position","examples":[{"en":"Extra staff were deployed at the station.","zh":"车站增派了工作人员。"},{"en":"The agency deployed rescue teams after the storm.","zh":"风暴过后该机构部署了救援队。"}]},{"pos":"v.","meaning":"使用；运用","definition":"to use something effectively for a purpose","examples":[{"en":"The writer deploys humour to challenge prejudice.","zh":"作者运用幽默来挑战偏见。"},{"en":"Engineers deployed new sensors to monitor the bridge.","zh":"工程师使用了新传感器监测这座桥。"}]}],"deposit":[{"pos":"n.","meaning":"押金","definition":"money paid as security and sometimes returned later","examples":[{"en":"You must pay a deposit before moving into the flat.","zh":"入住公寓前必须交押金。"},{"en":"Your deposit will be returned if nothing is damaged.","zh":"如果没有物品损坏，押金会退还。"},{"en":"The rental deposit equals one month's rent.","zh":"租房押金相当于一个月的租金。"}]},{"pos":"v.","meaning":"存入款项","definition":"to put money into a bank account","ipa":"/dɪˈpɒzɪt/","examples":[{"en":"You can deposit cash at this branch.","zh":"你可以在这家分行存入现金。"},{"en":"Please deposit the money into your savings account.","zh":"请将钱存入储蓄账户。"},{"en":"Customers can deposit cheques using the banking app.","zh":"顾客可以使用银行应用存入支票。"}]},{"pos":"n.","meaning":"存款；存入的钱","definition":"Money placed in a bank or similar account.","examples":[{"en":"The bank recorded a deposit of five hundred pounds.","zh":"银行记录了一笔五百英镑存款。"},{"en":"Her savings account receives regular deposits.","zh":"她的储蓄账户定期有资金存入。"}]},{"pos":"n.","meaning":"沉积物；矿床","definition":"Material that settles or accumulates naturally.","examples":[{"en":"The flood left a deposit of fine sand.","zh":"洪水留下了细沙沉积层。"},{"en":"The survey located a copper deposit.","zh":"勘查发现了一处铜矿床。"}]},{"pos":"v.","meaning":"放置；存放","definition":"To put something down or leave it somewhere.","examples":[{"en":"She deposited her bag beside the door.","zh":"她把包放在门旁。"},{"en":"Visitors may deposit valuables in the hotel safe.","zh":"访客可把贵重物品存放在酒店保险柜里。"}]},{"pos":"v.","meaning":"使沉积；沉淀","definition":"To leave a layer of material through a natural process.","examples":[{"en":"The river deposits silt on the floodplain.","zh":"河流把淤泥沉积在洪泛平原上。"},{"en":"Minerals were deposited inside the cave.","zh":"矿物质沉积在洞穴内。"}]},{"pos":"v.","meaning":"缴付保证金；支付押金","definition":"To pay money as security or an advance.","examples":[{"en":"They deposited ten per cent of the price to reserve the boat.","zh":"他们支付价款的百分之十作为定金来预订船只。"},{"en":"The tenant deposited the required security before moving in.","zh":"租客入住前缴付了所需押金。"}]}],"depress":[{"pos":"v.","meaning":"使沮丧","definition":"to make someone sad or hopeless","examples":[{"en":"The gloomy news depressed everyone.","zh":"这条令人忧心的消息使大家都很沮丧。"},{"en":"Months of isolation had depressed her.","zh":"几个月的隔离使她情绪低落。"}]},{"pos":"v.","meaning":"压低;减少;使不景气","definition":"to reduce an amount, level, or activity","examples":[{"en":"Weak demand depressed house prices.","zh":"需求疲软压低了房价。"},{"en":"The long drought depressed agricultural output.","zh":"持续干旱减少了农业产量。"}]},{"pos":"v.","meaning":"按下;压下","definition":"to push something down","examples":[{"en":"Depress the brake pedal gently.","zh":"轻轻踩下刹车踏板。"},{"en":"The lever must be depressed to release the catch.","zh":"必须压下手柄才能松开卡扣。"}]}],"depression":[{"pos":"n.","meaning":"抑郁；消沉","definition":"a state of deep sadness or a mental health condition","examples":[{"en":"The memoir describes her experience of depression.","zh":"回忆录描述了她的抑郁经历。"},{"en":"He felt a period of depression after the business failed.","zh":"生意失败后，他有一段时间情绪消沉。"}]},{"pos":"n.","meaning":"经济萧条","definition":"a prolonged period of seriously reduced economic activity","examples":[{"en":"Many factories closed during the depression.","zh":"经济萧条期间许多工厂倒闭了。"},{"en":"The book examines unemployment in an economic depression.","zh":"这本书研究经济萧条时期的失业问题。"}]},{"pos":"n.","meaning":"低气压；低压区","definition":"an area of low atmospheric pressure","examples":[{"en":"A depression is moving across the Atlantic.","zh":"一个低压系统正在横穿大西洋。"},{"en":"The weather map shows a deep depression offshore.","zh":"天气图显示近海有一个强低压区。"}]}],"deprive":[{"pos":"v.","meaning":"剥夺；使丧失","definition":"to prevent someone from having something needed","examples":[{"en":"The noise deprived residents of sleep.","zh":"噪声让居民无法睡觉。"},{"en":"Closing the route would deprive the village of its only bus service.","zh":"关闭这条线路会使村庄失去唯一的公交服务。"}]}],"deputy":[{"pos":"n.","meaning":"副职;代理人;代表","definition":"a person authorized to act for another or represent others","examples":[{"en":"The deputy chaired the meeting in her absence.","zh":"她缺席时由副手主持会议。"},{"en":"Voters elected a new deputy to parliament.","zh":"选民选出了一名新议员。"}]}],"derelict":[{"pos":"adj.","meaning":"被遗弃的；破败的","definition":"abandoned and in poor condition","examples":[{"en":"The derelict warehouse has become an arts centre.","zh":"废弃的仓库已变为艺术中心。"},{"en":"We passed a row of derelict houses.","zh":"我们经过了一排破败的房屋。"}]},{"pos":"n.","meaning":"遗弃物；废弃船只","definition":"property or a vessel abandoned by its owner","examples":[{"en":"The drifting derelict posed a danger to shipping.","zh":"漂流的废船对航运构成危险。"},{"en":"Divers examined the derelict near the harbour entrance.","zh":"潜水员检查了港口入口附近的废弃船只。"}]},{"pos":"n.","meaning":"无家可归者（旧式且含贬义）","definition":"an old, often offensive term for a homeless person","examples":[{"en":"The old article dismissed homeless people as derelicts.","zh":"那篇旧文章轻蔑地把无家可归者称为流浪汉。"},{"en":"The novelist portrays the so-called derelict with sympathy.","zh":"小说家同情地描写了这个所谓的流浪汉。"}]}],"derive":[{"pos":"v.","meaning":"获得；取得","definition":"to obtain something from a source","examples":[{"en":"The community derives income from tourism.","zh":"社区从旅游业获得收入。"},{"en":"She derives great satisfaction from teaching.","zh":"她从教学中获得极大满足。"}]},{"pos":"v.","meaning":"源于；起源于","definition":"to come from a particular origin","examples":[{"en":"The word derives from an ancient language.","zh":"这个词源于一种古代语言。"},{"en":"Much of the evidence derives from household surveys.","zh":"大部分证据来自家庭调查。"}]}],"descend":[{"pos":"v.","meaning":"下降;下来","definition":"to move to a lower place","examples":[{"en":"The plane began to descend through the clouds.","zh":"飞机开始穿过云层下降。"},{"en":"We descended the steep staircase carefully.","zh":"我们小心地下了陡峭的楼梯。"}]},{"pos":"v.","meaning":"传承;由祖先传下;为后裔","definition":"to come from an ancestor or pass through generations","examples":[{"en":"The title descended to his eldest daughter.","zh":"这个头衔传给了他的长女。"},{"en":"These horses descend from a small founding herd.","zh":"这些马是一小群原始种马的后代。"}]}],"describe":[{"pos":"v.","meaning":"描述；描写；形容","definition":"to give an account of what something is like","examples":[{"en":"Please describe the route from the station.","zh":"请描述从车站出发的路线。"},{"en":"The witness described the missing bag in detail.","zh":"目击者详细描述了丢失的包。"}]}],"desert":[{"pos":"n.","meaning":"沙漠；荒漠","definition":"a dry region with little rainfall and sparse vegetation","examples":[{"en":"The road crosses a vast desert.","zh":"道路横穿一片广阔的沙漠。"},{"en":"Some desert animals are active mainly at night.","zh":"有些沙漠动物主要在夜间活动。"}],"ipa":"/ˈdezət/"},{"pos":"adj.","meaning":"沙漠的；荒凉的","definition":"relating to a desert or a deserted place","examples":[{"en":"The researchers studied desert plants.","zh":"研究人员研究了沙漠植物。"},{"en":"They found shelter on a desert island.","zh":"他们在一座荒岛上找到了庇护处。"}],"ipa":"/ˈdezət/"},{"pos":"v.","meaning":"遗弃；抛弃；擅离","definition":"to abandon someone or leave a duty","examples":[{"en":"The villagers refused to desert their homes.","zh":"村民拒绝抛弃自己的家园。"},{"en":"He deserted his post during the crisis.","zh":"危机期间，他擅离了岗位。"}],"ipa":"/dɪˈzɜːt/"}],"deserve":[{"pos":"v.","meaning":"应得;值得","definition":"to be worthy of a particular treatment","examples":[{"en":"The volunteers deserve our thanks.","zh":"志愿者值得我们感谢。"},{"en":"Your proposal deserves careful consideration.","zh":"你的提议值得认真考虑。"}]}],"design":[{"pos":"n.","meaning":"设计；构思","definition":"the planning of how something will work or look","examples":[{"en":"Good design makes the tool easy to use.","zh":"良好的设计使这件工具容易使用。"},{"en":"The bridge won an award for its innovative design.","zh":"这座桥因创新设计获奖。"}]},{"pos":"n.","meaning":"图样；图案","definition":"a drawing or pattern showing an arrangement","examples":[{"en":"The fabric has a simple floral design.","zh":"这块布上有简单的花卉图案。"},{"en":"She showed us the design for the new library.","zh":"她给我们看了新图书馆的设计图。"}]},{"pos":"n.","meaning":"企图；图谋（常用复数）","definition":"a secret plan or intention","examples":[{"en":"They suspected the company had designs on the land.","zh":"他们怀疑公司对这块土地有所图谋。"},{"en":"His ambitious designs were defeated by public opposition.","zh":"他的野心计划因公众反对而失败。"}]},{"pos":"v.","meaning":"设计；构思","definition":"to plan how something will look or function","examples":[{"en":"They designed a chair that folds flat.","zh":"他们设计了一把可以折平的椅子。"},{"en":"The course is designed to build speaking confidence.","zh":"这门课程旨在增强口语表达信心。"}]}],"desirable":[{"pos":"adj.","meaning":"值得拥有的；理想的；可取的","definition":"worth having or likely to bring benefits","examples":[{"en":"Good public transport makes the area a desirable place to live.","zh":"便利的公共交通使这里成为理想居住地。"},{"en":"A smaller sample may be desirable for the pilot study.","zh":"初步研究采用较小样本可能更合适。"}]}],"desire":[{"pos":"v.","meaning":"想要;渴望;要求","definition":"to want or wish for something strongly","examples":[{"en":"Most workers desire greater job security.","zh":"大多数工人希望工作更有保障。"},{"en":"The director desires a written explanation.","zh":"主管要求提供书面解释。"}]},{"pos":"n.","meaning":"渴望;愿望;要求","definition":"a strong wish for something","examples":[{"en":"She has a desire to study abroad.","zh":"她有出国学习的愿望。"},{"en":"The letter expressed his desire for privacy.","zh":"信中表达了他对隐私的要求。"}]}],"desperate":[{"pos":"adj.","meaning":"绝望的","definition":"having little hope and feeling extreme distress","examples":[{"en":"She became desperate after weeks without news.","zh":"数周杳无音讯后，她陷入了绝望。"},{"en":"The trapped climbers faced a desperate situation.","zh":"被困的登山者面临令人绝望的处境。"}]},{"pos":"adj.","meaning":"拼命的；不顾一切的","definition":"willing to take extreme action because of urgent need","examples":[{"en":"They made a desperate attempt to save the boat.","zh":"他们不顾一切地试图救下船。"},{"en":"His desperate search continued through the night.","zh":"他拼命搜寻，整夜未停。"}]},{"pos":"adj.","meaning":"极度渴望的","definition":"wanting or needing something very badly","examples":[{"en":"After the long hike, we were desperate for water.","zh":"长途徒步后，我们极度渴望喝水。"},{"en":"She is desperate to return to her research.","zh":"她非常渴望重返研究工作。"}]},{"pos":"adj.","meaning":"危急的；极严重的","definition":"extremely serious or dangerous","examples":[{"en":"The village faces a desperate shortage of food.","zh":"村庄面临极严重的食物短缺。"},{"en":"Conditions in the damaged hospital were desperate.","zh":"受损医院的情况十分危急。"}]}],"despite":[{"pos":"prep.","meaning":"尽管；不管","definition":"without being prevented by something","examples":[{"en":"They completed the walk despite the rain.","zh":"尽管下雨，他们仍完成了徒步。"},{"en":"Despite careful planning, the opening was delayed.","zh":"尽管仔细规划了，开幕仍被推迟。"}]}],"despoil":[{"pos":"v.","meaning":"掠夺;破坏;蹂躏","definition":"to rob a place of valuable things or ruin its beauty","examples":[{"en":"Invading soldiers despoiled the monastery.","zh":"入侵士兵洗劫了修道院。"},{"en":"Illegal mining has despoiled the valley.","zh":"非法采矿破坏了山谷。"}]}],"destination":[{"pos":"n.","meaning":"目的地；终点","definition":"the place to which someone or something is going","examples":[{"en":"Our final destination is a village by the lake.","zh":"我们的最终目的地是湖边的一个村庄。"},{"en":"The parcel reached its destination on Friday.","zh":"包裹于星期五到达目的地。"}]}],"destiny":[{"pos":"n.","meaning":"命运；定数","definition":"the future believed to be determined for someone","examples":[{"en":"She wanted to take control of her own destiny.","zh":"她想掌握自己的命运。"},{"en":"The novel follows the destinies of three families.","zh":"小说追踪了三个家庭的命运。"}]}],"destruction":[{"pos":"n.","meaning":"破坏;毁灭","definition":"the act or result of destroying something","examples":[{"en":"The fire caused widespread destruction.","zh":"火灾造成了大范围破坏。"},{"en":"Habitat destruction threatens many species.","zh":"栖息地破坏威胁着许多物种。"}]}],"destructive":[{"pos":"adj.","meaning":"破坏性的；有害的","definition":"causing serious damage","examples":[{"en":"The island experienced a destructive storm.","zh":"岛上遭遇了一场破坏性风暴。"},{"en":"Constant criticism can be destructive to confidence.","zh":"不断批评会损害自信心。"}]}],"detach":[{"pos":"v.","meaning":"拆下；分离","definition":"to separate something from what it is joined to","examples":[{"en":"Detach the label before washing the garment.","zh":"清洗衣服前先取下标签。"},{"en":"The cable can be detached for storage.","zh":"电缆可以拆下以便存放。"}]},{"pos":"v.","meaning":"派遣；分遣","definition":"to assign a smaller group to a separate task","examples":[{"en":"Two officers were detached to assist the search.","zh":"两名警官被调派去协助搜寻。"},{"en":"A small team was detached from the main unit.","zh":"一个小队从主队中分遣出去。"}]}],"detail":[{"pos":"n.","meaning":"细节;详情;琐事","definition":"a small fact or feature of something","examples":[{"en":"Check every detail before signing.","zh":"签字之前检查每个细节。"},{"en":"She remembers the room in remarkable detail.","zh":"她对那个房间的细节记得格外清楚。"}]},{"pos":"v.","meaning":"详述;详细说明","definition":"to describe something fully","examples":[{"en":"The report details the cost of repairs.","zh":"报告详细说明了维修费用。"},{"en":"He detailed each stage of the experiment.","zh":"他详细讲述了实验的每个阶段。"}]}],"detect":[{"pos":"v.","meaning":"发现；察觉；探测","definition":"to discover something difficult to notice","examples":[{"en":"The sensor can detect very small movements.","zh":"传感器能够探测到极小的运动。"},{"en":"She detected a change in his tone.","zh":"她察觉到他的语气变了。"}]}],"detective":[{"pos":"n.","meaning":"侦探；刑警","definition":"a person who investigates crimes or mysteries","examples":[{"en":"The detective interviewed the witnesses separately.","zh":"侦探分别询问了证人。"},{"en":"A private detective was hired to find the missing documents.","zh":"有人聘请了私家侦探寻找丢失的文件。"}]},{"pos":"adj.","meaning":"侦探的；侦查的","definition":"relating to investigating crimes","examples":[{"en":"She enjoys reading detective fiction.","zh":"她喜欢阅读侦探小说。"},{"en":"The case required patient detective work.","zh":"这个案件需要耐心的侦查工作。"}]}],"deter":[{"pos":"v.","meaning":"威慑;阻止;使打消念头","definition":"to discourage someone from doing something","examples":[{"en":"High fees deter some students from applying.","zh":"高昂费用使一些学生打消申请的念头。"},{"en":"Visible cameras may deter theft.","zh":"显眼的摄像头可能震慑盗窃行为。"}]}],"detergent":[{"pos":"n.","meaning":"洗涤剂；清洁剂","definition":"a substance used for cleaning","examples":[{"en":"Use a mild detergent to wash the fabric.","zh":"用温和的洗涤剂清洗这种布料。"},{"en":"The bottle contains concentrated laundry detergent.","zh":"瓶里装着浓缩洗衣液。"}]},{"pos":"adj.","meaning":"去污的；清洁的","definition":"having the ability to clean","examples":[{"en":"The solution has strong detergent properties.","zh":"这种溶液具有很强的去污性。"},{"en":"Researchers compared the detergent action of several compounds.","zh":"研究人员比较了几种化合物的清洁作用。"}]}],"deteriorate":[{"pos":"v.","meaning":"恶化；变坏","definition":"to become worse in condition or quality","examples":[{"en":"The road surface deteriorated after the harsh winter.","zh":"严冬过后，路面状况恶化了。"},{"en":"Relations between the two groups began to deteriorate.","zh":"两个群体之间的关系开始恶化。"}]}],"deterioration":[{"pos":"n.","meaning":"恶化;衰退","definition":"the process of becoming worse","examples":[{"en":"The doctor noticed a deterioration in her condition.","zh":"医生注意到她的病情恶化了。"},{"en":"Poor maintenance led to the building's deterioration.","zh":"维护不善导致建筑状况恶化。"}]}],"determine":[{"pos":"v.","meaning":"确定；查明","definition":"to establish something through investigation","examples":[{"en":"Tests will determine the strength of the material.","zh":"测试将确定材料的强度。"},{"en":"We need to determine what caused the delay.","zh":"我们需要查明延误原因。"}]},{"pos":"v.","meaning":"决定；影响结果","definition":"to control or decide an outcome","examples":[{"en":"Rainfall largely determines the size of the harvest.","zh":"降雨量在很大程度上决定收成。"},{"en":"The committee will determine the final schedule.","zh":"委员会将决定最终日程。"}]},{"pos":"v.","meaning":"下决心；决意","definition":"to decide firmly to do something","examples":[{"en":"She determined to finish the course despite the difficulties.","zh":"她决心克服困难完成课程。"},{"en":"His early failure determined him to work harder.","zh":"早期的失败使他决心更加努力。"}]}],"detour":[{"pos":"n.","meaning":"绕路；迂回路线","definition":"a longer route taken to avoid an obstacle","examples":[{"en":"A detour added twenty minutes to our journey.","zh":"绕路让旅程多了二十分钟。"},{"en":"Follow the signs for the temporary detour.","zh":"请沿临时绕行指示牌行驶。"}]},{"pos":"v.","meaning":"绕道","definition":"to travel by an indirect route","examples":[{"en":"We detoured through the village to avoid the flooded road.","zh":"我们绕道村庄，避开被淹的道路。"},{"en":"The bus detoured around the construction site.","zh":"公交车绕过了施工现场。"}]}],"detract":[{"pos":"v.","meaning":"减损;贬低","definition":"to reduce the value or appeal of something","examples":[{"en":"Traffic noise detracts from the hotel's appeal.","zh":"交通噪声降低了这家酒店的吸引力。"},{"en":"One mistake should not detract from her achievement.","zh":"一次错误不应减损她的成就。"}]}],"detrimental":[{"pos":"adj.","meaning":"有害的；不利的","definition":"causing harm","examples":[{"en":"Air pollution is detrimental to public health.","zh":"空气污染有害公众健康。"},{"en":"Excessive overtime can be detrimental to family life.","zh":"过度加班可能不利于家庭生活。"},{"en":"The policy may have a detrimental effect on small shops.","zh":"该政策可能对小商店产生不利影响。"}]}],"devalue":[{"pos":"v.","meaning":"使货币贬值","definition":"to reduce a currency's official value","examples":[{"en":"The government decided to devalue the currency.","zh":"政府决定使本国货币贬值。"},{"en":"The proposal would devalue the currency against its neighbours.","zh":"这项提议将使本币相对邻国货币贬值。"}]},{"pos":"v.","meaning":"贬低；降低价值","definition":"to make something seem less important or valuable","examples":[{"en":"Ignoring practical skills can devalue vocational education.","zh":"忽视实践技能会贬低职业教育的价值。"},{"en":"The damage devalued the antique table.","zh":"损坏降低了这张古董桌的价值。"}]}],"devastate":[{"pos":"v.","meaning":"摧毁;严重破坏","definition":"to damage a place very badly","examples":[{"en":"Floods devastated the coastal villages.","zh":"洪水严重破坏了沿海村庄。"},{"en":"The disease devastated the potato crop.","zh":"病害毁坏了马铃薯作物。"}]},{"pos":"v.","meaning":"使极度悲痛;使震惊","definition":"to make someone extremely upset","examples":[{"en":"The sudden loss devastated the family.","zh":"突如其来的丧失使全家悲痛欲绝。"},{"en":"She was devastated by the examination result.","zh":"考试结果让她备受打击。"}]}],"devastating":[{"pos":"adj.","meaning":"毁灭性的；极具破坏力的","definition":"causing very great damage or distress","examples":[{"en":"The flood had a devastating effect on local farms.","zh":"洪水给当地农场造成了毁灭性影响。"},{"en":"Losing the archive was devastating for the researchers.","zh":"档案丢失对研究人员打击巨大。"}]},{"pos":"adj.","meaning":"极有力的；令人难以招架的","definition":"extremely powerful or effective","examples":[{"en":"She delivered a devastating criticism of the proposal.","zh":"她对提案作出了极有力的批评。"},{"en":"The striker scored with a devastating shot.","zh":"前锋以一记势不可挡的射门得分。"}]}],"develop":[{"pos":"v.","meaning":"发展；成长；形成","definition":"to grow or gradually become more advanced","examples":[{"en":"The town developed around the railway station.","zh":"这座城镇围绕火车站发展起来。"},{"en":"Children develop language skills at different rates.","zh":"儿童语言能力发展的速度各不相同。"}]},{"pos":"v.","meaning":"开发；研制","definition":"to create or improve something through planned work","examples":[{"en":"The team developed a new method for filtering water.","zh":"团队开发了一种新的滤水方法。"},{"en":"They plan to develop the empty site into a park.","zh":"他们计划把空地开发成公园。"}]}],"deviance":[{"pos":"n.","meaning":"偏常行为;异常","definition":"behaviour that differs from accepted social standards","examples":[{"en":"The study examines social responses to deviance.","zh":"这项研究考察社会对偏常行为的反应。"},{"en":"Different cultures define deviance in different ways.","zh":"不同文化对偏常行为有不同界定。"}]}],"device":[{"pos":"n.","meaning":"装置；设备","definition":"an object made for a particular purpose","examples":[{"en":"This device measures the temperature of the water.","zh":"这个装置测量水温。"},{"en":"Turn off electronic devices before the performance.","zh":"演出前请关闭电子设备。"}]},{"pos":"n.","meaning":"方法；手段；策略","definition":"a technique used to achieve an effect","examples":[{"en":"Flashbacks are a common narrative device.","zh":"倒叙是常见的叙事手法。"},{"en":"The discount was a device to attract new customers.","zh":"这次折扣是吸引新顾客的手段。"}]},{"pos":"n.","meaning":"图案；徽记","definition":"a symbolic design displayed on an object","examples":[{"en":"The shield bore the device of a golden eagle.","zh":"盾牌上有一只金鹰的徽记。"},{"en":"A floral device decorated the centre of the plate.","zh":"盘子中央装饰着花卉图案。"}]}],"devise":[{"pos":"v.","meaning":"设计；想出；发明","definition":"to invent or plan a method or system","examples":[{"en":"We devised a simple way to compare the samples.","zh":"我们想出了一种比较样本的简单方法。"},{"en":"The students devised their own experiment.","zh":"学生们设计了自己的实验。"}]}],"devote":[{"pos":"v.","meaning":"奉献;投入;致力于","definition":"to give time or effort to a person or purpose","examples":[{"en":"She devotes an hour daily to reading.","zh":"她每天投入一小时阅读。"},{"en":"He devoted his career to wildlife conservation.","zh":"他把职业生涯奉献给了野生动物保护。"}]}],"diagnose":[{"pos":"v.","meaning":"诊断；查明问题","definition":"to identify an illness or the cause of a problem","examples":[{"en":"The specialist diagnosed the illness after further tests.","zh":"专科医生进一步检查后诊断了病情。"},{"en":"The mechanic diagnosed a fault in the cooling system.","zh":"技工查明冷却系统有故障。"}]}],"diagram":[{"pos":"n.","meaning":"图解；示意图","definition":"a drawing explaining structure or relationships","examples":[{"en":"The diagram shows how water moves through the system.","zh":"示意图展示了水如何流经系统。"},{"en":"Draw a diagram to explain your design.","zh":"画一张示意图来解释你的设计。"}]}],"dialect":[{"pos":"n.","meaning":"方言;地方话","definition":"a regional or social variety of a language","examples":[{"en":"Her grandparents speak a local dialect.","zh":"她的祖父母说一种地方方言。"},{"en":"The novel includes dialogue in a northern dialect.","zh":"小说中有用北方方言写成的对话。"}]}],"diameter":[{"pos":"n.","meaning":"直径","definition":"the distance across a circle through its centre","examples":[{"en":"The pipe has a diameter of ten centimetres.","zh":"管子的直径为十厘米。"},{"en":"Measure the diameter of the circular opening.","zh":"测量这个圆形开口的直径。"}]}],"dictation":[{"pos":"n.","meaning":"听写；口述","definition":"spoken words that someone writes down","examples":[{"en":"The class began with a short dictation.","zh":"课程以一段简短听写开始。"},{"en":"She took dictation while the manager described the letter.","zh":"经理口述信件时，她作了笔录。"}]}],"diesel":[{"pos":"n.","meaning":"柴油","definition":"a fuel used in certain engines","examples":[{"en":"The truck runs on diesel.","zh":"这辆卡车使用柴油。"},{"en":"Diesel leaked from the damaged tank.","zh":"柴油从破损油箱中漏了出来。"}]},{"pos":"n.","meaning":"柴油机;柴油车","definition":"an engine or vehicle powered by diesel fuel","examples":[{"en":"An old diesel pulled the freight train.","zh":"一辆旧柴油机车牵引着货运列车。"},{"en":"They replaced the boat's diesel last winter.","zh":"他们去年冬天更换了船上的柴油机。"}]}],"dietary":[{"pos":"adj.","meaning":"饮食的；膳食的","definition":"relating to food and eating habits","examples":[{"en":"Please tell us about any dietary requirements.","zh":"请告知我们任何饮食方面的要求。"},{"en":"The survey examined changes in dietary habits.","zh":"调查研究了饮食习惯的变化。"}]}],"differ":[{"pos":"v.","meaning":"不同；有差异","definition":"to be unlike something else","examples":[{"en":"The two materials differ in strength and weight.","zh":"这两种材料在强度和重量上不同。"},{"en":"Local customs differ from region to region.","zh":"各地习俗因地区而异。"}]},{"pos":"v.","meaning":"意见不一","definition":"to disagree","examples":[{"en":"The researchers differ on how to interpret the evidence.","zh":"研究人员在如何解释证据方面意见不同。"},{"en":"We differ in our views but can still cooperate.","zh":"我们观点不同，但仍能合作。"}]}],"differentiate":[{"pos":"v.","meaning":"区分;区别","definition":"to recognize or show a difference","examples":[{"en":"The test differentiates bacterial infections from viral ones.","zh":"这项检测能区分细菌感染和病毒感染。"},{"en":"Price alone does not differentiate these products.","zh":"仅凭价格无法区分这些产品。"}]},{"pos":"v.","meaning":"区别对待","definition":"to treat different groups differently","examples":[{"en":"The school differentiates instruction according to ability.","zh":"学校根据能力实施差异化教学。"},{"en":"The law differentiates between adults and children.","zh":"法律对成年人和儿童作出区别对待。"}]}],"diffuse":[{"pos":"v.","meaning":"扩散；传播","definition":"to spread through a wider area or group","examples":[{"en":"The scent slowly diffused through the room.","zh":"香味慢慢扩散到整个房间。"},{"en":"New ideas diffused through trading networks.","zh":"新思想通过贸易网络传播。"}],"ipa":"/dɪˈfjuːz/"},{"pos":"v.","meaning":"使光漫射","definition":"to scatter light in many directions","examples":[{"en":"The frosted glass diffuses the sunlight.","zh":"磨砂玻璃使阳光漫射。"},{"en":"A thin curtain diffused the light entering the studio.","zh":"一层薄窗帘使进入工作室的光线变得柔和。"}],"ipa":"/dɪˈfjuːz/"},{"pos":"adj.","meaning":"分散的；弥漫的","definition":"spread out rather than concentrated","examples":[{"en":"The lamp produced a soft, diffuse glow.","zh":"灯发出柔和而分散的光。"},{"en":"The organisation has a diffuse network of local groups.","zh":"该组织拥有一个分布广泛的地方团体网络。"}],"ipa":"/dɪˈfjuːs/"},{"pos":"adj.","meaning":"冗长散漫的","definition":"using too many words without clear focus","examples":[{"en":"The essay was too diffuse to make its argument clear.","zh":"文章过于冗长散漫，论点不够清晰。"},{"en":"The editor shortened several diffuse passages.","zh":"编辑删短了几段散漫冗长的文字。"}],"ipa":"/dɪˈfjuːs/"}],"digest":[{"pos":"v.","meaning":"消化","definition":"to break down food in the body","examples":[{"en":"Some people find this food difficult to digest.","zh":"一些人觉得这种食物不易消化。"},{"en":"The animal takes several hours to digest its meal.","zh":"这种动物需要几个小时消化食物。"}],"ipa":"/daɪˈdʒest/"},{"pos":"v.","meaning":"理解；吸收信息","definition":"to understand and absorb information","examples":[{"en":"I need time to digest the report.","zh":"我需要时间理解这份报告。"},{"en":"The course gives students space to digest new ideas.","zh":"课程为学生留出时间吸收新思想。"}],"ipa":"/daɪˈdʒest/"},{"pos":"n.","meaning":"文摘；摘要","definition":"a collection or summary of important information","examples":[{"en":"The newsletter offers a weekly digest of research news.","zh":"通讯每周提供科研新闻摘要。"},{"en":"She read a digest of the main arguments.","zh":"她阅读了主要论点的摘要。"}],"ipa":"/ˈdaɪdʒest/"}],"digestive":[{"pos":"adj.","meaning":"消化的;与消化有关的","definition":"relating to the digestion of food","examples":[{"en":"Digestive enzymes break food into smaller molecules.","zh":"消化酶把食物分解成更小的分子。"},{"en":"Stress can affect the digestive system.","zh":"压力会影响消化系统。"}]}],"digital":[{"pos":"adj.","meaning":"数字化的","definition":"using electronic data represented by numbers","examples":[{"en":"Digital skills are essential in many workplaces.","zh":"数字技能在许多工作场所必不可少。"},{"en":"The library offers access to digital newspapers.","zh":"图书馆提供数字报纸阅读服务。"},{"en":"Digital exclusion can disadvantage older people.","zh":"无法使用数字技术可能使老年人处于不利地位。"}]}],"dimension":[{"pos":"n.","meaning":"尺寸；长宽高","definition":"a measurement of size","examples":[{"en":"Check the dimensions of the table before ordering.","zh":"订购前检查桌子的尺寸。"},{"en":"The room's narrow dimensions limited the layout.","zh":"房间狭窄的尺寸限制了布局。"}]},{"pos":"n.","meaning":"方面；层面","definition":"an aspect of a situation","examples":[{"en":"The debate has an important ethical dimension.","zh":"这场争论有一个重要的伦理层面。"},{"en":"The interviews added a personal dimension to the study.","zh":"访谈为研究增加了个人经历的层面。"}]},{"pos":"n.","meaning":"维；维度","definition":"an independent direction or variable used to describe space or data","examples":[{"en":"A flat map represents the landscape in two dimensions.","zh":"平面地图用二维呈现地形。"},{"en":"The model reduces the data to three dimensions.","zh":"模型把数据简化为三个维度。"}]}],"dimensional":[{"pos":"adj.","meaning":"维度的;空间维数的","definition":"relating to dimensions or measurable extent","examples":[{"en":"Dimensional analysis helped us check the equation.","zh":"量纲分析帮助我们检查方程。"},{"en":"The technician checked the component's dimensional accuracy.","zh":"技术员检查了零件的尺寸精度。"}]}],"diminish":[{"pos":"v.","meaning":"减少；减弱；降低","definition":"to become or make smaller or less strong","examples":[{"en":"The noise diminished as the train moved away.","zh":"火车驶远后噪声减弱了。"},{"en":"Better insulation diminishes heat loss.","zh":"更好的隔热能减少热量流失。"}]},{"pos":"v.","meaning":"贬低；轻视","definition":"to make someone or something seem less important","examples":[{"en":"One mistake should not diminish her achievement.","zh":"一个错误不应贬低她的成就。"},{"en":"He felt that the remark diminished his contribution.","zh":"他觉得那番话贬低了他的贡献。"}]}],"dioxide":[{"pos":"n.","meaning":"二氧化物","definition":"a compound containing two oxygen atoms for each atom of another element","examples":[{"en":"Carbon dioxide is measured by the sensor.","zh":"传感器测量二氧化碳。"},{"en":"Titanium dioxide is used in some white coatings.","zh":"二氧化钛用于一些白色涂料。"}]}],"diploma":[{"pos":"n.","meaning":"毕业证书;资格证书","definition":"an official document showing completion of a course","examples":[{"en":"She received a diploma in graphic design.","zh":"她获得了平面设计文凭。"},{"en":"He framed his college diploma.","zh":"他把大学毕业证书装进了相框。"}]}],"direction":[{"pos":"n.","meaning":"方向","definition":"the way in which something moves or faces","examples":[{"en":"The wind changed direction during the night.","zh":"风在夜间改变了方向。"},{"en":"The station lies in the opposite direction.","zh":"车站在相反方向。"}]},{"pos":"n.","meaning":"趋势；发展方向","definition":"the course in which something develops","examples":[{"en":"The discussion took an unexpected direction.","zh":"讨论朝意想不到的方向发展。"},{"en":"The project needs a clearer sense of direction.","zh":"这个项目需要更明确的发展方向。"}]},{"pos":"n.","meaning":"说明；指示（常用复数）","definition":"instructions explaining what to do or how to get somewhere","examples":[{"en":"Read the directions before assembling the shelf.","zh":"组装架子前请阅读说明。"},{"en":"She gave us directions to the museum.","zh":"她告诉了我们去博物馆的路线。"}]},{"pos":"n.","meaning":"指导；管理","definition":"the act of guiding or controlling work","examples":[{"en":"The choir improved under her direction.","zh":"合唱团在她的指导下取得了进步。"},{"en":"The research is carried out under the professor's direction.","zh":"这项研究在教授的指导下进行。"}]}],"directory":[{"pos":"n.","meaning":"名录；电话号码簿","definition":"an organized list of names and contact details","examples":[{"en":"The business directory lists local suppliers.","zh":"企业名录列出了当地供应商。"},{"en":"Her number was not in the telephone directory.","zh":"电话号码簿里没有她的号码。"}]}],"disable":[{"pos":"v.","meaning":"使伤残;使丧失能力","definition":"to limit someone's physical or mental abilities","examples":[{"en":"The injury disabled him for several months.","zh":"这次受伤使他数月无法正常活动。"},{"en":"The illness can severely disable affected children.","zh":"这种疾病可使患病儿童严重残障。"}]},{"pos":"v.","meaning":"使失效;禁用","definition":"to stop a device or function from working","examples":[{"en":"Disable the alarm before replacing the battery.","zh":"更换电池前先停用警报器。"},{"en":"The attack disabled the payment system.","zh":"这次攻击使支付系统瘫痪了。"}]}],"disadvantage":[{"pos":"n.","meaning":"缺点；不利条件","definition":"a condition that makes success more difficult","examples":[{"en":"The main disadvantage is the lack of storage space.","zh":"主要缺点是储物空间不足。"},{"en":"Students without internet access are at a disadvantage.","zh":"无法上网的学生处于不利地位。"}]}],"disagree":[{"pos":"v.","meaning":"不同意；意见不合","definition":"to have a different opinion","examples":[{"en":"I disagree with the conclusion but respect the argument.","zh":"我不同意这个结论，但尊重其论证。"},{"en":"The committee disagreed about the best location.","zh":"委员会对最佳地点意见不一。"}]},{"pos":"v.","meaning":"不一致；不符","definition":"to fail to match","examples":[{"en":"The two accounts disagree on the timing of the event.","zh":"两份记述对事件发生时间的说法不一致。"},{"en":"The measurements disagree by several millimetres.","zh":"测量结果相差几毫米。"}]}],"disappointing":[{"pos":"adj.","meaning":"令人失望的","definition":"less good than expected or hoped","examples":[{"en":"The team's performance was disappointing.","zh":"球队的表现令人失望。"},{"en":"We received disappointing news about the funding.","zh":"我们收到了令人失望的资助消息。"}]}],"disapprove":[{"pos":"v.","meaning":"不赞成；反对","definition":"to consider something wrong or unacceptable","examples":[{"en":"Her parents disapprove of the plan.","zh":"她父母不赞成这个计划。"},{"en":"Most residents disapproved of closing the playground.","zh":"大多数居民反对关闭游乐场。"}]}],"disastrous":[{"pos":"adj.","meaning":"灾难性的；极糟的","definition":"causing great harm or failure","examples":[{"en":"The flood had disastrous effects on local agriculture.","zh":"洪水对当地农业造成了灾难性影响。"},{"en":"Rushing the decision proved disastrous.","zh":"匆忙作决定导致了极糟的结果。"}]}],"discard":[{"pos":"v.","meaning":"丢弃;抛弃","definition":"to get rid of something unwanted","examples":[{"en":"Discard any fruit with visible mould.","zh":"丢弃所有明显发霉的水果。"},{"en":"The team discarded its original design.","zh":"团队放弃了最初的设计。"}]}],"discerning":[{"pos":"adj.","meaning":"有鉴别力的；眼光敏锐的","definition":"good at judging quality or noticing differences","examples":[{"en":"The shop attracts discerning buyers of antique furniture.","zh":"这家店吸引了眼光敏锐的古董家具买家。"},{"en":"A discerning reader will notice the change in tone.","zh":"有鉴赏力的读者会注意到语气的变化。"}]}],"discharge":[{"pos":"v.","meaning":"排出；放出；放电","definition":"to release a substance or stored energy","examples":[{"en":"The pipe discharges treated water into the river.","zh":"这根管道把处理过的水排入河流。"},{"en":"The battery discharged overnight.","zh":"电池一夜之间放完了电。"}],"ipa":"/dɪsˈtʃɑːdʒ/"},{"pos":"v.","meaning":"准予离开；解除职务","definition":"to release someone from hospital, service, or an obligation","examples":[{"en":"The hospital discharged her after the examination.","zh":"医院在检查后准许她离院。"},{"en":"He was discharged from military service.","zh":"他退伍了。"}],"ipa":"/dɪsˈtʃɑːdʒ/"},{"pos":"v.","meaning":"履行；清偿","definition":"to carry out a duty or pay what is owed","examples":[{"en":"The trustee must discharge her responsibilities carefully.","zh":"受托人必须谨慎履行职责。"},{"en":"The loan was discharged before the agreed date.","zh":"贷款在约定日期之前还清了。"}],"ipa":"/dɪsˈtʃɑːdʒ/"},{"pos":"n.","meaning":"排放；排出物；放电","definition":"the release of a substance or electrical energy","examples":[{"en":"The factory monitors its wastewater discharge.","zh":"工厂监测废水排放。"},{"en":"A sudden electrical discharge damaged the circuit.","zh":"突然放电损坏了电路。"}],"ipa":"/ˈdɪstʃɑːdʒ/"},{"pos":"n.","meaning":"出院；退伍；解除","definition":"official permission to leave an institution or duty","examples":[{"en":"Her discharge from hospital was delayed.","zh":"她的出院被推迟了。"},{"en":"The document records his discharge from the army.","zh":"文件记录了他的退伍情况。"}],"ipa":"/ˈdɪstʃɑːdʒ/"},{"pos":"n.","meaning":"履行；清偿","definition":"the completion of a duty or payment of a debt","examples":[{"en":"The agreement requires the full discharge of the debt.","zh":"协议要求全额清偿债务。"},{"en":"The audit reviewed the discharge of official duties.","zh":"审计检查了公务职责的履行情况。"}],"ipa":"/ˈdɪstʃɑːdʒ/"}],"discipline":[{"pos":"v.","meaning":"训练;训导","definition":"to train someone to behave in a controlled way","examples":[{"en":"The coach disciplined the players to stay focused.","zh":"教练训练球员保持专注。"},{"en":"She disciplines herself to write every morning.","zh":"她严格要求自己每天早晨写作。"}]},{"pos":"v.","meaning":"处分;惩戒","definition":"to punish someone for breaking rules","examples":[{"en":"The school disciplined students who damaged equipment.","zh":"学校处分了损坏设备的学生。"},{"en":"The employee was disciplined for repeated misconduct.","zh":"这名员工因屡次违规受到处分。"}]},{"pos":"n.","meaning":"纪律;自律","definition":"controlled behaviour and obedience to rules","examples":[{"en":"Military training requires strict discipline.","zh":"军事训练要求严格的纪律。"},{"en":"Learning an instrument takes patience and discipline.","zh":"学习乐器需要耐心和自律。"}]},{"pos":"n.","meaning":"学科","definition":"a branch of knowledge or study","examples":[{"en":"Psychology is a relatively young discipline.","zh":"心理学是一门相对年轻的学科。"},{"en":"The project brings together several academic disciplines.","zh":"该项目汇集了数个学科。"}]},{"pos":"n.","meaning":"惩戒;处分","definition":"punishment intended to correct behaviour","examples":[{"en":"The policy sets out procedures for staff discipline.","zh":"政策规定了员工处分程序。"},{"en":"She believed discipline should be fair and consistent.","zh":"她认为惩戒应当公平一致。"}]}],"disclose":[{"pos":"v.","meaning":"揭露；透露；公开","definition":"to make previously secret information known","examples":[{"en":"The report disclosed serious errors in the accounts.","zh":"报告揭露了账目中的严重错误。"},{"en":"She declined to disclose the buyer's identity.","zh":"她拒绝透露买家的身份。"}]}],"discontinue":[{"pos":"v.","meaning":"停止；中断；终止","definition":"to stop an activity or supply","examples":[{"en":"The company discontinued the unpopular service.","zh":"公司终止了不受欢迎的服务。"},{"en":"The study was discontinued when funding ended.","zh":"资金结束后，研究停止了。"}]}],"discount":[{"pos":"n.","meaning":"折扣","definition":"a reduction in the usual price","examples":[{"en":"Students receive a ten per cent discount.","zh":"学生享有百分之十的折扣。"},{"en":"The shop offers a discount on damaged packaging.","zh":"商店对包装破损的商品提供折扣。"},{"en":"Ask whether a group discount is available.","zh":"询问是否有团体折扣。"}],"ipa":"/ˈdɪskaʊnt/"},{"pos":"v.","meaning":"打折;减价","definition":"to reduce the selling price","examples":[{"en":"The shop discounted winter coats.","zh":"商店给冬季外套打折。"},{"en":"Tickets are discounted for students.","zh":"学生票享受优惠。"}],"ipa":"/dɪˈskaʊnt/"},{"pos":"v.","meaning":"不予考虑;低估","definition":"to treat as unimportant or unlikely","examples":[{"en":"Do not discount her experience.","zh":"不要低估她的经验。"},{"en":"The investigators discounted the rumour.","zh":"调查者未把谣言纳入考虑。"}],"ipa":"/dɪˈskaʊnt/"}],"discourage":[{"pos":"v.","meaning":"使灰心；使泄气","definition":"to reduce someone's confidence or enthusiasm","examples":[{"en":"The poor results discouraged the team.","zh":"糟糕的结果使团队感到气馁。"},{"en":"Do not let one rejection discourage you.","zh":"不要让一次拒绝使你灰心。"}]},{"pos":"v.","meaning":"劝阻；阻止","definition":"to try to prevent an action","examples":[{"en":"High parking charges discourage unnecessary car journeys.","zh":"高昂的停车费能减少不必要的驾车出行。"},{"en":"The guide discouraged visitors from feeding the animals.","zh":"导游劝阻游客给动物喂食。"}]}],"discourteous":[{"pos":"adj.","meaning":"无礼的；粗鲁的","definition":"impolite and inconsiderate","examples":[{"en":"Interrupting every answer was discourteous.","zh":"打断每次回答是无礼的。"},{"en":"The receptionist apologized for the discourteous response.","zh":"接待员为无礼的回应道了歉。"}]}],"discover":[{"pos":"v.","meaning":"发现","definition":"to find something previously unknown","examples":[{"en":"We discover a quiet garden behind the museum.","zh":"我们发现博物馆后面有一个安静的花园。"},{"en":"Scientists discover new species every year.","zh":"科学家每年都会发现新物种。"},{"en":"You may discover a new way to learn.","zh":"你也许会发现一种新的学习方式。"}]}],"discovery":[{"pos":"n.","meaning":"发现；发现的事物","definition":"finding something previously unknown","examples":[{"en":"The discovery of the cave attracted researchers.","zh":"洞穴的发现吸引了研究人员。"},{"en":"The team announced a major archaeological discovery.","zh":"团队宣布了一项重大的考古发现。"}]}],"discredit":[{"pos":"v.","meaning":"使丧失信誉；使受怀疑","definition":"to damage trust in a person or idea","examples":[{"en":"The fabricated evidence discredited the entire report.","zh":"伪造的证据使整份报告失去了可信度。"},{"en":"Critics tried to discredit the researcher rather than address her findings.","zh":"批评者试图诋毁研究者，而非回应她的发现。"}]}],"discrepancy":[{"pos":"n.","meaning":"差异;不一致;矛盾","definition":"a difference between things that should agree","examples":[{"en":"We found a discrepancy between the two totals.","zh":"我们发现两个总数不一致。"},{"en":"The witness could not explain the discrepancy.","zh":"证人无法解释这一矛盾。"}]}],"discretion":[{"pos":"n.","meaning":"谨慎；审慎","definition":"care in handling sensitive matters","examples":[{"en":"Please treat this information with discretion.","zh":"请谨慎处理这些信息。"},{"en":"Her discretion made her a trusted adviser.","zh":"她的谨慎使她成为受信任的顾问。"}]},{"pos":"n.","meaning":"自行判断权；酌情处理权","definition":"freedom to decide according to one's judgement","examples":[{"en":"The manager has discretion to extend the deadline.","zh":"经理有权酌情延长期限。"},{"en":"Refunds are granted at the organiser's discretion.","zh":"退款由组织者酌情决定。"}]}],"discriminate":[{"pos":"v.","meaning":"歧视","definition":"to treat a group unfairly","examples":[{"en":"Employers must not discriminate against older applicants.","zh":"雇主不得歧视年长申请人。"},{"en":"The policy aims to prevent schools from discriminating on financial grounds.","zh":"这项政策旨在防止学校因经济条件而区别对待学生。"}]},{"pos":"v.","meaning":"辨别；区分","definition":"to recognize differences","examples":[{"en":"The instrument can discriminate between similar signals.","zh":"这台仪器能够区分相似信号。"},{"en":"Experienced listeners discriminate subtle changes in pitch.","zh":"有经验的听者能辨别音高的细微变化。"}]}],"disdain":[{"pos":"n.","meaning":"鄙视;蔑视","definition":"a feeling that someone or something is unworthy","examples":[{"en":"He spoke with disdain about the proposal.","zh":"他以轻蔑的口气谈论这项提议。"},{"en":"She showed complete disdain for the rules.","zh":"她对规则表现出十足的蔑视。"}]},{"pos":"v.","meaning":"鄙视;不屑于","definition":"to consider something unworthy of respect or attention","examples":[{"en":"They disdained any offer of help.","zh":"他们对任何帮助都不屑一顾。"},{"en":"The proud scholar disdained to answer the accusation.","zh":"这位骄傲的学者不屑回应指控。"}]}],"disempower":[{"pos":"v.","meaning":"使失去权力或影响力","definition":"to reduce someone's ability to control events","examples":[{"en":"The new rules disempowered local councils.","zh":"新规则削弱了地方议会的权力。"},{"en":"Excluding staff from decisions can disempower them.","zh":"把员工排除在决策之外会削弱他们的影响力。"}]}],"disenchantment":[{"pos":"n.","meaning":"失望；幻想破灭","definition":"a loss of enthusiasm or belief","examples":[{"en":"The delays led to widespread disenchantment with the project.","zh":"延误使人们普遍对项目感到失望。"},{"en":"Her early excitement gradually turned into disenchantment.","zh":"她最初的兴奋逐渐变成了失望。"}]}],"disfigure":[{"pos":"v.","meaning":"使毁容;破坏外观","definition":"to spoil the appearance of someone or something","examples":[{"en":"The accident disfigured his face.","zh":"事故使他的面部毁容。"},{"en":"Ugly advertisements disfigure the historic square.","zh":"难看的广告破坏了历史广场的外观。"}]}],"disharmony":[{"pos":"n.","meaning":"不和谐；不一致","definition":"a lack of agreement or harmony","examples":[{"en":"Unequal workloads created disharmony within the team.","zh":"工作量不均造成团队内部不和。"},{"en":"The bright extension introduced visual disharmony.","zh":"鲜艳的扩建部分造成了视觉上的不协调。"}]}],"disillusion":[{"pos":"v.","meaning":"使幻想破灭；使醒悟","definition":"to show someone that a belief or hope is unrealistic","examples":[{"en":"The poor conditions disillusioned many new employees.","zh":"恶劣的条件使许多新员工幻想破灭。"},{"en":"He was disillusioned by the gap between promises and action.","zh":"承诺与行动之间的差距使他醒悟并失望。"}]}],"disillusionment":[{"pos":"n.","meaning":"幻灭;醒悟","definition":"disappointment after discovering that something is not as good as believed","examples":[{"en":"Repeated scandals caused widespread disillusionment with politics.","zh":"接连的丑闻使公众普遍对政治感到幻灭。"},{"en":"Her initial enthusiasm gradually turned to disillusionment.","zh":"她最初的热情逐渐变成了幻灭感。"}]}],"disinformation":[{"pos":"n.","meaning":"故意传播的虚假信息；蓄意误导的信息","definition":"false information spread deliberately to mislead people","examples":[{"en":"The campaign used disinformation to confuse voters.","zh":"那场活动利用蓄意传播的虚假信息迷惑选民。"},{"en":"Researchers traced the disinformation to several coordinated accounts.","zh":"研究人员发现那些虚假信息来自几个协同行动的账号。"}]}],"disintegrate":[{"pos":"v.","meaning":"碎裂；瓦解；解体","definition":"to break into pieces or lose unity","examples":[{"en":"The ancient cloth disintegrated when touched.","zh":"古老的布料一碰就碎了。"},{"en":"The alliance began to disintegrate after the election.","zh":"联盟在选举后开始瓦解。"}]}],"dismantle":[{"pos":"v.","meaning":"拆开；拆除","definition":"to take a structure or device apart","examples":[{"en":"Workers dismantled the temporary stage.","zh":"工人拆除了临时舞台。"},{"en":"The engine must be dismantled before inspection.","zh":"检查前必须拆开引擎。"}]},{"pos":"v.","meaning":"逐步废除；撤销","definition":"to end a system by removing its parts","examples":[{"en":"The reforms dismantled several outdated procedures.","zh":"改革废除了几项过时流程。"},{"en":"The agreement began to dismantle trade barriers.","zh":"协议开始逐步消除贸易壁垒。"}]}],"dismiss":[{"pos":"v.","meaning":"解雇;让离开;解散","definition":"to remove someone from a job or tell people to leave","examples":[{"en":"The company dismissed three senior managers.","zh":"公司解雇了三位高级经理。"},{"en":"The teacher dismissed the class early.","zh":"老师提前让全班下课了。"}]},{"pos":"v.","meaning":"驳回;不予考虑","definition":"to reject a claim or consider something unimportant","examples":[{"en":"The judge dismissed the case.","zh":"法官驳回了这起诉讼。"},{"en":"Do not dismiss her concerns as foolish.","zh":"不要把她的担忧当成傻话而置之不理。"}]}],"disobey":[{"pos":"v.","meaning":"违抗；不服从","definition":"to refuse to follow an order or rule","examples":[{"en":"The driver disobeyed the police officer's signal.","zh":"司机违抗了警察的指示。"},{"en":"Workers were punished for disobeying safety rules.","zh":"工人因违反安全规定受到处罚。"}]}],"disorder":[{"pos":"n.","meaning":"混乱；失序","definition":"a lack of organization or public order","examples":[{"en":"The files were in complete disorder.","zh":"文件完全乱了套。"},{"en":"The sudden closure caused disorder at the entrance.","zh":"突然关闭使入口处陷入混乱。"}]},{"pos":"n.","meaning":"疾病；机能失调","definition":"a condition affecting normal bodily or mental function","examples":[{"en":"The clinic treats a range of sleep disorders.","zh":"这家诊所诊治多种睡眠障碍。"},{"en":"Researchers studied a rare genetic disorder.","zh":"研究人员研究了一种罕见遗传病。"}]}],"disorientate":[{"pos":"v.","meaning":"使失去方向感;使迷茫","definition":"to make someone confused about their location or situation","examples":[{"en":"The maze quickly disorientated the visitors.","zh":"迷宫很快使游客失去了方向感。"},{"en":"Frequent policy changes disorientated the staff.","zh":"频繁的政策变化使员工无所适从。"}]}],"disparage":[{"pos":"v.","meaning":"贬低；轻视","definition":"to speak about something as having little value","examples":[{"en":"He should not disparage work he has never read.","zh":"他不该贬低自己从未读过的作品。"},{"en":"Her colleagues refused to disparage the junior researcher's contribution.","zh":"同事们拒绝轻视这位年轻研究员的贡献。"}]}],"dispense":[{"pos":"v.","meaning":"分发；配给；提供","definition":"to give out something in portions","examples":[{"en":"The machine dispenses drinking water.","zh":"这台机器提供饮用水。"},{"en":"The pharmacist dispensed the prescribed medicine.","zh":"药剂师配发了处方药。"}]}],"dispenser":[{"pos":"n.","meaning":"分配器;自动售货机","definition":"a device that supplies a substance or item","examples":[{"en":"The soap dispenser is empty.","zh":"皂液器空了。"},{"en":"A ticket dispenser stands by the entrance.","zh":"入口旁放着一台自动售票机。"}]},{"pos":"n.","meaning":"配药员;药剂师","definition":"a person who prepares and supplies medicines","examples":[{"en":"The dispenser checked the prescription carefully.","zh":"配药员仔细核对了处方。"},{"en":"A trained dispenser labelled the medicine bottles.","zh":"受过培训的配药员给药瓶贴上标签。"}]},{"pos":"n.","meaning":"分配者;提供者","definition":"someone or something that supplies a resource","examples":[{"en":"The charity became a dispenser of emergency grants.","zh":"慈善机构成为紧急补助的发放者。"},{"en":"Grandfather was a generous dispenser of advice.","zh":"祖父总是乐于给人建议。"}]}],"dispersal":[{"pos":"n.","meaning":"散布；分散；疏散","definition":"the spreading or movement of things away from one place","examples":[{"en":"Wind assists the dispersal of these seeds.","zh":"风有助于这些种子的散播。"},{"en":"The station was designed for rapid dispersal of crowds.","zh":"车站的设计便于人群迅速疏散。"}]}],"dispiriting":[{"pos":"adj.","meaning":"令人沮丧的；使人气馁的","definition":"making someone lose hope or enthusiasm","examples":[{"en":"It was dispiriting to see the same problem return.","zh":"看到同一个问题再次出现令人沮丧。"},{"en":"The long wait was a dispiriting start to the trip.","zh":"漫长等待让旅程有了一个令人泄气的开头。"}]}],"displace":[{"pos":"v.","meaning":"取代;使失去职位","definition":"to take the place of something or someone","examples":[{"en":"Digital cameras displaced film cameras.","zh":"数码相机取代了胶片相机。"},{"en":"Automation displaced many factory workers.","zh":"自动化使许多工厂工人失去了工作。"}]},{"pos":"v.","meaning":"迫使离开家园;使移位","definition":"to force someone or something away from its usual place","examples":[{"en":"The floods displaced thousands of residents.","zh":"洪水迫使数千居民离开家园。"},{"en":"The impact displaced several roof tiles.","zh":"撞击使几片屋瓦移了位。"}]}],"display":[{"pos":"v.","meaning":"陈列；展示","definition":"to arrange something so people can see it","examples":[{"en":"The museum displays tools from the Bronze Age.","zh":"博物馆展示青铜时代的工具。"},{"en":"Local artists displayed their paintings in the hall.","zh":"当地艺术家在大厅陈列了画作。"}]},{"pos":"v.","meaning":"显示；表现出","definition":"to show information or a quality","examples":[{"en":"The screen displays the current temperature.","zh":"屏幕显示当前温度。"},{"en":"She displayed great patience with the children.","zh":"她对孩子们表现出极大的耐心。"}]},{"pos":"n.","meaning":"陈列；展览","definition":"an arrangement of objects for people to see","examples":[{"en":"A display of old photographs filled the foyer.","zh":"门厅里陈列着许多老照片。"},{"en":"The shop changed its window display.","zh":"商店更换了橱窗陈列。"}]},{"pos":"n.","meaning":"显示屏；显示内容","definition":"a screen or the information shown on it","examples":[{"en":"The digital display is easy to read.","zh":"数字显示屏容易辨读。"},{"en":"Check the battery level on the display.","zh":"查看显示屏上的电池电量。"}]},{"pos":"n.","meaning":"表现；展示","definition":"an occasion showing skill, feeling, or strength","examples":[{"en":"The match was a remarkable display of teamwork.","zh":"这场比赛出色地展示了团队协作。"},{"en":"His public display of anger surprised everyone.","zh":"他当众发怒让所有人吃惊。"}]}],"disposable":[{"pos":"adj.","meaning":"一次性的；用后丢弃的","definition":"designed to be thrown away after use","examples":[{"en":"The café replaced disposable cups with reusable ones.","zh":"咖啡馆用可重复使用的杯子替代了一次性杯子。"},{"en":"Workers wore disposable gloves for the task.","zh":"工作人员完成这项任务时戴着一次性手套。"}]},{"pos":"adj.","meaning":"可支配的；可动用的","definition":"available to use after necessary expenses","examples":[{"en":"Higher rent reduced their disposable income.","zh":"房租上涨减少了他们的可支配收入。"},{"en":"The survey measures disposable household resources.","zh":"调查衡量家庭可支配资源。"}]}],"disposal":[{"pos":"n.","meaning":"处理;处置","definition":"the act of getting rid of something","examples":[{"en":"Safe waste disposal requires careful planning.","zh":"安全处理废物需要周密规划。"},{"en":"The company arranged the disposal of obsolete equipment.","zh":"公司安排处理过时设备。"}]},{"pos":"n.","meaning":"支配;安排;使用权","definition":"the availability or arrangement of resources for use","examples":[{"en":"A car is at your disposal all day.","zh":"你全天都可使用一辆车。"},{"en":"The general planned the disposal of his forces.","zh":"将军规划了兵力部署。"}]}],"dispute":[{"pos":"n.","meaning":"争论；争端","definition":"a serious disagreement","examples":[{"en":"The neighbours resolved their dispute over the fence.","zh":"邻居们解决了关于围栏的争端。"},{"en":"The pay dispute lasted several weeks.","zh":"工资争议持续了数周。"}]},{"pos":"v.","meaning":"对……提出异议；质疑","definition":"to challenge the truth or validity of something","examples":[{"en":"Several experts disputed the study's conclusions.","zh":"几位专家质疑了研究结论。"},{"en":"She disputes the claim that costs have fallen.","zh":"她对成本已经下降的说法提出异议。"}]},{"pos":"v.","meaning":"争论；争夺","definition":"to argue about or compete for something","examples":[{"en":"The two towns disputed ownership of the land.","zh":"两镇争夺这块土地的所有权。"},{"en":"Researchers still dispute how the monument was built.","zh":"研究人员仍在争论这座纪念碑如何建成。"}]}],"disqualify":[{"pos":"v.","meaning":"取消资格；使不合格","definition":"to make someone ineligible","examples":[{"en":"Breaking the rule will disqualify the competitor.","zh":"违反规则会使参赛者被取消资格。"},{"en":"A missing document may disqualify an application.","zh":"缺少文件可能使申请不合格。"}]}],"disregard":[{"pos":"v.","meaning":"忽视;不理会","definition":"to pay no attention to something","examples":[{"en":"The driver disregarded the warning signs.","zh":"司机无视警告标志。"},{"en":"Disregard the earlier version of the timetable.","zh":"请忽略较早版本的时间表。"}]},{"pos":"n.","meaning":"漠视;忽视","definition":"a lack of attention or respect","examples":[{"en":"The report shows a disregard for basic facts.","zh":"这份报告漠视基本事实。"},{"en":"Their disregard for safety alarmed the inspector.","zh":"他们对安全的漠视使检查员震惊。"}]}],"disrespectful":[{"pos":"adj.","meaning":"无礼的；不尊重人的","definition":"showing a lack of respect","examples":[{"en":"Interrupting the speaker repeatedly was disrespectful.","zh":"反复打断发言者是无礼的。"},{"en":"She objected to his disrespectful tone.","zh":"她反对他那不尊重人的语气。"}]}],"disrupt":[{"pos":"v.","meaning":"扰乱；使中断","definition":"to interrupt normal activity","examples":[{"en":"The storm disrupted rail services.","zh":"暴风雨扰乱了铁路服务。"},{"en":"Frequent messages disrupted her concentration.","zh":"频繁的消息打断了她的专注。"}]}],"disruption":[{"pos":"n.","meaning":"扰乱;中断;破坏","definition":"a disturbance that prevents normal activity","examples":[{"en":"The strike caused major transport disruption.","zh":"罢工造成交通严重中断。"},{"en":"Builders kept disruption to a minimum.","zh":"施工人员把干扰降到了最低。"}]}],"disruptive":[{"pos":"adj.","meaning":"扰乱性的；破坏性的","definition":"causing interruption or disorder","examples":[{"en":"Construction work was disruptive to nearby businesses.","zh":"施工扰乱了附近商家的经营。"},{"en":"The teacher addressed the disruptive behaviour calmly.","zh":"老师冷静地处理了扰乱课堂的行为。"}]}],"dissatisfied":[{"pos":"adj.","meaning":"不满意的；不满足的","definition":"unhappy with something's quality or result","examples":[{"en":"Residents were dissatisfied with the bus timetable.","zh":"居民对公交时刻表不满意。"},{"en":"She remained dissatisfied with the final explanation.","zh":"她对最终解释仍不满意。"}]}],"disseminate":[{"pos":"v.","meaning":"传播;散布","definition":"to spread information widely","examples":[{"en":"Libraries disseminate knowledge throughout the community.","zh":"图书馆在社区中传播知识。"},{"en":"The team disseminated its findings online.","zh":"团队在网上发布了研究结果。"}]}],"dissemination":[{"pos":"n.","meaning":"传播；散布","definition":"the wide distribution of information or ideas","examples":[{"en":"The internet speeds up the dissemination of research.","zh":"互联网加快了研究成果的传播。"},{"en":"The project supports the dissemination of farming knowledge.","zh":"该项目支持农业知识的传播。"}]}],"dissertation":[{"pos":"n.","meaning":"学位论文；专题论文","definition":"a long research paper written for an academic qualification","examples":[{"en":"Her dissertation examines migration patterns.","zh":"她的学位论文研究迁移模式。"},{"en":"He submitted the dissertation after three revisions.","zh":"经过三次修改，他提交了论文。"}]}],"dissolve":[{"pos":"v.","meaning":"溶解","definition":"to become or make part of a liquid solution","examples":[{"en":"Dissolve the sugar in warm water.","zh":"把糖溶解在温水中。"},{"en":"The tablet dissolved within a minute.","zh":"药片在一分钟内溶解了。"}]},{"pos":"v.","meaning":"解散;结束","definition":"to formally end a group, agreement, or relationship","examples":[{"en":"Parliament was dissolved before the election.","zh":"选举前议会被解散。"},{"en":"They agreed to dissolve the partnership.","zh":"他们同意结束合伙关系。"}]}],"distance":[{"pos":"n.","meaning":"距离；间距","definition":"the amount of space between things","examples":[{"en":"What is the distance between the two stations?","zh":"这两个车站之间相距多远？"},{"en":"Keep a safe distance from the edge.","zh":"与边缘保持安全距离。"}]},{"pos":"n.","meaning":"远方；远处","definition":"a place far away","examples":[{"en":"A church tower appeared in the distance.","zh":"远处出现了一座教堂塔楼。"},{"en":"We could hear thunder in the distance.","zh":"我们能听到远处的雷声。"}]},{"pos":"n.","meaning":"时间的间隔","definition":"the separation between events in time","examples":[{"en":"Time gave her some distance from the painful experience.","zh":"时间使她与那段痛苦经历渐渐拉开了距离。"},{"en":"At this distance, the details of the meeting seem unimportant.","zh":"时隔这么久，那次会议的细节已显得不重要。"}]}],"distill":[{"pos":"v.","meaning":"蒸馏；提取","definition":"to separate substances through heating and cooling","examples":[{"en":"The laboratory distilled water for the experiment.","zh":"实验室为实验蒸馏了水。"},{"en":"The plant's oils are distilled from its leaves.","zh":"这种植物的精油通过蒸馏叶子提取。"}]},{"pos":"v.","meaning":"提炼；浓缩要点","definition":"to extract the essential part","examples":[{"en":"She distilled years of research into a short guide.","zh":"她把多年的研究提炼成一本简短指南。"},{"en":"The summary distills the main lessons from the project.","zh":"摘要提炼了项目的主要经验。"}]}],"distinct":[{"pos":"adj.","meaning":"清楚的;明显的","definition":"easy to notice or recognize","examples":[{"en":"There was a distinct smell of smoke.","zh":"有一股明显的烟味。"},{"en":"We heard three distinct knocks.","zh":"我们听到了三下清晰的敲门声。"}]},{"pos":"adj.","meaning":"不同的;有区别的","definition":"separate and different from something else","examples":[{"en":"The project has two distinct phases.","zh":"该项目分为两个不同的阶段。"},{"en":"These are distinct species with similar markings.","zh":"这些是斑纹相似但不同的物种。"}]}],"distinctive":[{"pos":"adj.","meaning":"有特色的；容易识别的","definition":"having a quality that makes something recognisable","examples":[{"en":"The bird has a distinctive red crest.","zh":"这种鸟有独特的红色冠羽。"},{"en":"Her distinctive voice is easy to recognise.","zh":"她独特的嗓音很容易辨认。"}]}],"distinguish":[{"pos":"v.","meaning":"区分；辨别","definition":"to recognize a difference","examples":[{"en":"It can be hard to distinguish fact from opinion.","zh":"有时很难区分事实与观点。"},{"en":"The two species are distinguished by their markings.","zh":"这两个物种可以通过斑纹区分。"}]},{"pos":"v.","meaning":"辨认出","definition":"to see or hear something clearly","examples":[{"en":"I could just distinguish a figure in the fog.","zh":"我在雾中勉强辨认出一个人影。"},{"en":"She distinguished his voice among the crowd.","zh":"她从人群中辨认出了他的声音。"}]},{"pos":"v.","meaning":"使出众；表现突出","definition":"to make someone notably different or excellent","examples":[{"en":"Her careful reasoning distinguished her from the other candidates.","zh":"她严密的推理使她在候选人中脱颖而出。"},{"en":"He distinguished himself through years of public service.","zh":"他通过多年的公共服务赢得了声誉。"}]}],"distort":[{"pos":"v.","meaning":"扭曲;使变形","definition":"to change the natural shape or sound","examples":[{"en":"Heat distorted the plastic frame.","zh":"热量使塑料框架变形。"},{"en":"The cheap microphone distorted her voice.","zh":"廉价麦克风使她的声音失真。"}]},{"pos":"v.","meaning":"歪曲;曲解","definition":"to present facts in a misleading way","examples":[{"en":"The headline distorted the research findings.","zh":"标题歪曲了研究结论。"},{"en":"Selective quotations can distort an author's argument.","zh":"选择性引用会曲解作者的论点。"}]}],"distortion":[{"pos":"n.","meaning":"扭曲；变形；失真","definition":"a change that spoils the original shape or sound","examples":[{"en":"The curved mirror produces amusing distortion.","zh":"曲面镜产生了有趣的变形效果。"},{"en":"The recording has noticeable sound distortion.","zh":"这段录音有明显的声音失真。"}]},{"pos":"n.","meaning":"歪曲；曲解","definition":"a misleading alteration of facts or meaning","examples":[{"en":"The headline was a distortion of what she said.","zh":"标题歪曲了她的话。"},{"en":"Selective quotation can lead to serious distortion.","zh":"选择性引用会造成严重曲解。"}]}],"distract":[{"pos":"v.","meaning":"使分心；转移注意力","definition":"to draw attention away from something","examples":[{"en":"Loud music distracts me when I am reading.","zh":"阅读时，响亮的音乐会让我分心。"},{"en":"The guide distracted the children from the long wait.","zh":"导游转移了孩子们对漫长等待的注意力。"}]}],"distraction":[{"pos":"n.","meaning":"分心的事物;注意力分散","definition":"something that takes attention away from a task","examples":[{"en":"Turn off your phone to avoid distraction.","zh":"关闭手机以免分心。"},{"en":"Construction noise was a constant distraction.","zh":"施工噪声不断让人分心。"}]},{"pos":"n.","meaning":"消遣;娱乐","definition":"an enjoyable activity that takes the mind off worries","examples":[{"en":"Gardening provided a welcome distraction from work.","zh":"园艺成为暂时忘却工作的愉快消遣。"},{"en":"The children needed a distraction during the journey.","zh":"孩子们在旅途中需要些娱乐。"}]}],"distribute":[{"pos":"v.","meaning":"分发；分配；分送","definition":"to give or deliver things to several people or places","examples":[{"en":"Volunteers distributed blankets to the families.","zh":"志愿者向这些家庭分发了毯子。"},{"en":"The publisher distributes books throughout the region.","zh":"出版商在整个地区发行图书。"}]},{"pos":"v.","meaning":"分布；散布；分类安排","definition":"to spread or arrange things across an area or categories","examples":[{"en":"Trees are unevenly distributed across the island.","zh":"树木在岛上的分布不均匀。"},{"en":"Distribute the samples into groups according to size.","zh":"按大小把样本分成几组。"}]}],"distribution":[{"pos":"n.","meaning":"分配；分发；配送","definition":"the process of giving or delivering things to people","examples":[{"en":"The charity organized the distribution of winter clothing.","zh":"慈善机构组织了冬衣分发。"},{"en":"The warehouse handles distribution to local shops.","zh":"仓库负责向当地商店配送。"}]},{"pos":"n.","meaning":"分布","definition":"the way things are spread over an area or group","examples":[{"en":"The map shows the distribution of rainfall.","zh":"地图显示了降雨分布。"},{"en":"The age distribution differs between the two towns.","zh":"两座城镇的年龄分布不同。"}]}],"district":[{"pos":"n.","meaning":"区;地区","definition":"an area with particular boundaries or features","examples":[{"en":"The school serves a rural district.","zh":"这所学校服务于一个乡村地区。"},{"en":"We stayed in the city's historic district.","zh":"我们住在城市的历史街区。"}]}],"disturb":[{"pos":"v.","meaning":"打扰；扰乱","definition":"to interrupt peace or activity","examples":[{"en":"Please do not disturb the sleeping baby.","zh":"请不要打扰睡着的婴儿。"},{"en":"Aircraft noise disturbed the meeting.","zh":"飞机噪声打断了会议。"}]},{"pos":"v.","meaning":"弄乱；移动原有位置","definition":"to change the arrangement or position of something","examples":[{"en":"Avoid disturbing the roots when planting the tree.","zh":"栽树时避免弄动根系。"},{"en":"Someone had disturbed the papers on her desk.","zh":"有人弄乱了她桌上的文件。"}]},{"pos":"v.","meaning":"使不安；使烦恼","definition":"to make someone worried or upset","examples":[{"en":"The report's findings deeply disturbed the residents.","zh":"报告的发现令居民深感不安。"},{"en":"She was disturbed by the sudden silence.","zh":"突然的寂静让她心神不宁。"}]}],"disturbance":[{"pos":"n.","meaning":"打扰；干扰","definition":"an interruption of normal activity","examples":[{"en":"The construction caused considerable disturbance to residents.","zh":"施工对居民造成了相当大的干扰。"},{"en":"Please keep noise low to avoid disturbance.","zh":"请降低音量，避免打扰。"}]},{"pos":"n.","meaning":"骚乱；动乱","definition":"a public outbreak of disorder","examples":[{"en":"Police were called after a disturbance outside the stadium.","zh":"体育场外发生骚乱后，有人报警。"},{"en":"The report examined the causes of the disturbances.","zh":"报告分析了这些骚乱的原因。"}]},{"pos":"n.","meaning":"不安；机能紊乱","definition":"an upsetting change in feelings or bodily function","examples":[{"en":"The move caused some emotional disturbance.","zh":"搬迁引起了一些情绪不安。"},{"en":"The study recorded disturbances in sleep patterns.","zh":"研究记录了睡眠模式的紊乱。"}]}],"diverge":[{"pos":"v.","meaning":"分岔;分开","definition":"to move or extend in different directions","examples":[{"en":"The paths diverge beyond the bridge.","zh":"小路在桥后分岔。"},{"en":"Light rays diverge after passing through the lens.","zh":"光线穿过透镜后发散。"}]},{"pos":"v.","meaning":"产生分歧;偏离","definition":"to differ or move away from a standard or route","examples":[{"en":"Their opinions diverge on education policy.","zh":"他们在教育政策上存在分歧。"},{"en":"Actual spending diverged from the budget.","zh":"实际支出偏离了预算。"}]}],"diverse":[{"pos":"adj.","meaning":"多种多样的；不同的","definition":"including many different types","examples":[{"en":"The city has a diverse population.","zh":"这座城市的人口构成多元。"},{"en":"The festival offers a diverse programme of music.","zh":"音乐节提供了多样的音乐节目。"}]}],"diversify":[{"pos":"v.","meaning":"使多样化；扩大经营范围","definition":"to introduce greater variety","examples":[{"en":"The farm diversified into fruit production.","zh":"农场扩大经营范围，开始种植水果。"},{"en":"The library aims to diversify its collection.","zh":"图书馆旨在使馆藏更多样化。"}]}],"diversion":[{"pos":"n.","meaning":"转向;改道;转移","definition":"a change in the direction of movement or use","examples":[{"en":"A diversion takes drivers around the roadworks.","zh":"一条绕行路线使司机避开了道路施工。"},{"en":"The diversion of water reduced the river's flow.","zh":"引水工程减少了河流流量。"}]},{"pos":"n.","meaning":"转移注意力的事物","definition":"something intended to draw attention away","examples":[{"en":"The loud argument was a diversion for the thieves.","zh":"大声争吵是小偷转移注意力的手段。"},{"en":"She created a diversion while her friend escaped.","zh":"她制造了干扰以便朋友逃走。"}]},{"pos":"n.","meaning":"消遣;娱乐","definition":"an activity done for enjoyment","examples":[{"en":"Chess was his favourite evening diversion.","zh":"国际象棋是他最喜欢的晚间消遣。"},{"en":"The village offers few diversions for teenagers.","zh":"村里供青少年娱乐的活动很少。"}]}],"diversity":[{"pos":"n.","meaning":"多样性","definition":"the existence of different kinds of people or things","examples":[{"en":"Cultural diversity can enrich a community.","zh":"文化多样性可以丰富社区生活。"},{"en":"The festival celebrates the diversity of local traditions.","zh":"这个节日庆祝当地传统的多样性。"},{"en":"Workplace diversity can bring different perspectives.","zh":"职场多样性可以带来不同视角。"}]}],"divert":[{"pos":"v.","meaning":"使改道；转移","definition":"to change the direction or use of something","examples":[{"en":"Traffic was diverted around the damaged bridge.","zh":"车辆绕过损坏的桥梁改道行驶。"},{"en":"The emergency diverted resources from other projects.","zh":"紧急情况使资源从其他项目转移过来。"}]},{"pos":"v.","meaning":"使娱乐；消遣","definition":"to amuse or entertain","examples":[{"en":"The storyteller diverted the children during the delay.","zh":"延误期间，讲故事的人给孩子们解闷。"},{"en":"She read a light novel to divert herself from work.","zh":"她读了一本轻松的小说，让自己从工作中放松一下。"}]}],"divide":[{"pos":"v.","meaning":"分开;分隔","definition":"to separate something into parts or groups","examples":[{"en":"Divide the dough into six pieces.","zh":"把面团分成六份。"},{"en":"A fence divides the two gardens.","zh":"篱笆把两个花园隔开。"}]},{"pos":"v.","meaning":"分配;分享","definition":"to share something among people","examples":[{"en":"They divided the profits equally.","zh":"他们平分了利润。"},{"en":"We divided the work among four teams.","zh":"我们把工作分配给四个团队。"}]},{"pos":"v.","meaning":"除以","definition":"to calculate how many times one number fits into another","examples":[{"en":"Divide twelve by three to get four.","zh":"十二除以三得四。"},{"en":"The calculator can multiply and divide.","zh":"这台计算器能做乘法和除法。"}]},{"pos":"n.","meaning":"分歧;鸿沟","definition":"a major difference between groups","examples":[{"en":"Education can bridge the digital divide.","zh":"教育可以缩小数字鸿沟。"},{"en":"A deep political divide separated the neighbours.","zh":"深刻的政治分歧使邻居们产生隔阂。"}]},{"pos":"n.","meaning":"分界线;分水岭","definition":"a boundary separating areas, especially river basins","examples":[{"en":"The ridge forms a divide between two valleys.","zh":"山脊构成两个山谷的分界线。"},{"en":"Snow covered the continental divide.","zh":"雪覆盖了大陆分水岭。"}]}],"dividend":[{"pos":"n.","meaning":"股息；红利","definition":"a payment to shareholders from company profits","examples":[{"en":"The company paid a dividend to its shareholders.","zh":"公司向股东支付了股息。"},{"en":"She reinvested the dividends in more shares.","zh":"她将股息再投资于更多股票。"}]},{"pos":"n.","meaning":"回报；好处","definition":"a benefit resulting from an action","examples":[{"en":"Early investment in training paid dividends later.","zh":"早期的培训投入后来带来了回报。"},{"en":"Better communication brings dividends in staff morale.","zh":"改善沟通能带来员工士气提升的好处。"}]},{"pos":"n.","meaning":"被除数","definition":"the number being divided","examples":[{"en":"In twelve divided by three, twelve is the dividend.","zh":"十二除以三中，十二是被除数。"},{"en":"Write the dividend inside the long-division bracket.","zh":"把被除数写在竖式除号里面。"}]}],"divine":[{"pos":"adj.","meaning":"神的；神圣的；天赐的","definition":"relating to a god or believed to come from one","examples":[{"en":"The temple was dedicated to a divine protector.","zh":"这座庙宇供奉一位神圣的守护者。"},{"en":"The poem describes music as a divine gift.","zh":"诗歌把音乐描述为天赐的礼物。"}]}],"division":[{"pos":"n.","meaning":"分割;划分;分配","definition":"the act of separating or sharing something","examples":[{"en":"The division of land caused arguments.","zh":"土地分配引发了争论。"},{"en":"Clear division of responsibilities improved efficiency.","zh":"明确划分职责提高了效率。"}]},{"pos":"n.","meaning":"分歧;分裂","definition":"disagreement separating people into groups","examples":[{"en":"The proposal exposed divisions within the party.","zh":"这项提案暴露了党内分歧。"},{"en":"Economic hardship deepened social division.","zh":"经济困难加深了社会分裂。"}]},{"pos":"n.","meaning":"除法","definition":"the mathematical operation of dividing numbers","examples":[{"en":"The children are learning long division.","zh":"孩子们正在学习长除法。"},{"en":"Check your division by multiplying the answer.","zh":"用乘法检查你的除法答案。"}]},{"pos":"n.","meaning":"部门;分部;师","definition":"a major section of an organization or army","examples":[{"en":"She leads the company's research division.","zh":"她领导公司的研究部门。"},{"en":"An infantry division guarded the border.","zh":"一个步兵师守卫着边境。"}]}],"divisional":[{"pos":"adj.","meaning":"部门的；分区的","definition":"relating to a division of an organisation","examples":[{"en":"The divisional manager approved the budget.","zh":"部门经理批准了预算。"},{"en":"Divisional offices report to the central team.","zh":"各分区办事处向中央团队汇报。"}]}],"dizziness":[{"pos":"n.","meaning":"眩晕；头昏","definition":"a feeling of losing balance or surroundings spinning","examples":[{"en":"The patient reported dizziness after standing up.","zh":"患者说站起来后感到眩晕。"},{"en":"The sudden movement caused a moment of dizziness.","zh":"突然移动引起了短暂眩晕。"}]}],"dizzy":[{"pos":"adj.","meaning":"头晕的;令人眩晕的","definition":"feeling or causing a sensation of spinning","examples":[{"en":"Standing up suddenly made me dizzy.","zh":"突然站起来使我头晕。"},{"en":"The view from that dizzy height frightened him.","zh":"从那令人眩晕的高处俯瞰让他害怕。"}]}],"dock":[{"pos":"v.","meaning":"靠码头；停靠","definition":"to bring a vessel into a dock","examples":[{"en":"The ferry docked shortly after noon.","zh":"渡轮在中午过后不久靠岸。"},{"en":"They docked the boat beside the warehouse.","zh":"他们把船停靠在仓库旁。"}]},{"pos":"n.","meaning":"码头；船坞","definition":"an area where boats stop or are repaired","examples":[{"en":"Passengers waited on the dock.","zh":"乘客们在码头等候。"},{"en":"The ship entered a dry dock for repairs.","zh":"船驶入干船坞维修。"}]}],"doctoral":[{"pos":"adj.","meaning":"博士的","definition":"relating to the highest university research degree","examples":[{"en":"She began her doctoral research in environmental history.","zh":"她开始了环境史方面的博士研究。"},{"en":"The seminar is open to doctoral students.","zh":"研讨会对博士生开放。"}]}],"doctorate":[{"pos":"n.","meaning":"博士学位","definition":"the highest university research degree","examples":[{"en":"She earned a doctorate in chemistry.","zh":"她取得了化学博士学位。"},{"en":"His doctorate took four years to complete.","zh":"他用了四年完成博士学位。"}]}],"document":[{"pos":"n.","meaning":"文件；证件；公文","definition":"a written or electronic record containing information","examples":[{"en":"Keep a copy of every signed document.","zh":"每份签署的文件都要留一份副本。"},{"en":"The officer checked our travel documents.","zh":"工作人员检查了我们的旅行证件。"}],"ipa":"/ˈdɒkjumənt/"},{"pos":"v.","meaning":"记载；用证据证明","definition":"to record something or provide evidence for it","examples":[{"en":"The photographs document changes in the coastline.","zh":"照片记录了海岸线的变化。"},{"en":"The researcher carefully documented each experiment.","zh":"研究人员仔细记录了每次实验。"}],"ipa":"/ˈdɒkjument/"}],"documentation":[{"pos":"n.","meaning":"文件资料；书面证明","definition":"written records or instructions supporting something","examples":[{"en":"Keep all documentation related to the purchase.","zh":"保留与购买有关的所有文件。"},{"en":"The software comes with detailed documentation.","zh":"这款软件附带详细文档。"}]}],"dolphin":[{"pos":"n.","meaning":"海豚","definition":"an intelligent aquatic mammal with a long snout","examples":[{"en":"A dolphin surfaced beside the boat.","zh":"一只海豚在船旁浮出水面。"},{"en":"The children watched dolphins swimming offshore.","zh":"孩子们看着海豚在近海游动。"}]}],"dome":[{"pos":"n.","meaning":"穹顶；圆屋顶","definition":"a rounded roof shaped like half a sphere","examples":[{"en":"The cathedral's dome dominates the skyline.","zh":"大教堂的穹顶在天际线上十分醒目。"},{"en":"Visitors looked up at the painted dome.","zh":"游客们仰望彩绘穹顶。"}]}],"domestic":[{"pos":"adj.","meaning":"国内的；本国的","definition":"relating to one's own country","examples":[{"en":"Domestic tourism increased during the holiday.","zh":"假期期间国内旅游增长了。"},{"en":"The company serves both domestic and overseas markets.","zh":"这家公司同时面向国内和海外市场。"}]},{"pos":"adj.","meaning":"家庭的；家务的","definition":"relating to the home or family","examples":[{"en":"The survey measured time spent on domestic tasks.","zh":"调查测量了家务劳动所花的时间。"},{"en":"Domestic life became easier after the move.","zh":"搬家后，家庭生活变得更便利。"}]},{"pos":"adj.","meaning":"驯养的","definition":"kept by humans rather than living wild","examples":[{"en":"Domestic cats sometimes hunt local wildlife.","zh":"家猫有时会捕猎当地野生动物。"},{"en":"The farm raises several kinds of domestic animals.","zh":"这个农场饲养几种家畜。"}]}],"domesticate":[{"pos":"v.","meaning":"驯养;驯化","definition":"to breed or train wild animals or plants for human use","examples":[{"en":"Humans domesticated sheep thousands of years ago.","zh":"人类数千年前就驯养了羊。"},{"en":"Early farmers domesticated wild cereals.","zh":"早期农民驯化了野生谷物。"}]},{"pos":"v.","meaning":"使习惯家庭生活","definition":"to make someone accustomed to home life","examples":[{"en":"Years of family life had domesticated the restless traveller.","zh":"多年的家庭生活使这位不安分的旅行者习惯了居家。"},{"en":"No comfortable cottage could domesticate her adventurous spirit.","zh":"再舒适的小屋也无法让她冒险的心安于居家。"}]}],"dominant":[{"pos":"adj.","meaning":"占优势的；支配的","definition":"more powerful or influential than others","examples":[{"en":"One company holds a dominant position in the market.","zh":"一家公司在市场中占据支配地位。"},{"en":"Blue is the dominant colour in the painting.","zh":"蓝色是这幅画的主色调。"}]},{"pos":"adj.","meaning":"俯临的；高踞的","definition":"overlooking surrounding land from a high position","examples":[{"en":"The castle occupies a dominant position above the valley.","zh":"城堡高踞山谷之上。"},{"en":"The fortress stood on a dominant hill.","zh":"堡垒坐落在俯临四周的山丘上。"}]}],"dominate":[{"pos":"v.","meaning":"支配；占主导地位","definition":"to have the most power or influence","examples":[{"en":"A few large firms dominate the market.","zh":"几家大公司主导着市场。"},{"en":"Transport costs dominate the project's budget.","zh":"交通费用占项目预算的主要部分。"}]},{"pos":"v.","meaning":"耸立于；俯瞰","definition":"to be much taller or more visible than surrounding things","examples":[{"en":"The cathedral dominates the town's skyline.","zh":"大教堂高耸在城镇的天际线上。"},{"en":"A rocky peak dominates the valley.","zh":"一座岩石山峰耸立在山谷之上。"}]}],"domination":[{"pos":"n.","meaning":"控制;统治;支配","definition":"the exercise of strong power over others","examples":[{"en":"The movement opposed colonial domination.","zh":"这场运动反对殖民统治。"},{"en":"One firm's market domination worried regulators.","zh":"一家公司的市场垄断让监管机构担忧。"}]}],"donate":[{"pos":"v.","meaning":"捐赠；捐献","definition":"to give something to help a person or organisation","examples":[{"en":"Local shops donated food to the shelter.","zh":"当地商店向收容所捐赠了食物。"},{"en":"She donated her collection to the museum.","zh":"她把自己的藏品捐给了博物馆。"}]}],"donation":[{"pos":"n.","meaning":"捐赠；捐款；捐赠物","definition":"something given to support a cause","examples":[{"en":"The library received a donation of rare books.","zh":"图书馆收到了一批珍贵图书的捐赠。"},{"en":"Every donation helps fund the shelter.","zh":"每笔捐款都有助于资助收容所。"}]}],"doom":[{"pos":"v.","meaning":"注定失败;使遭殃","definition":"to make failure or disaster certain","examples":[{"en":"Lack of funding doomed the project.","zh":"缺乏资金注定了项目的失败。"},{"en":"The damaged ship was doomed to sink.","zh":"受损的船注定要沉没。"}]},{"pos":"n.","meaning":"毁灭;厄运","definition":"an unavoidable terrible fate","examples":[{"en":"The trapped sailors feared their doom.","zh":"被困的水手害怕灾难降临。"},{"en":"The crisis seemed to spell doom for the business.","zh":"这场危机似乎预示着企业的灭亡。"}]}],"dorm":[{"pos":"n.","meaning":"宿舍（dormitory 的简称）","definition":"a dormitory building or room","examples":[{"en":"My dorm is five minutes from the library.","zh":"我的宿舍距离图书馆五分钟路程。"},{"en":"Students decorated the dorm's common room.","zh":"学生们装饰了宿舍的公共休息室。"}]}],"dormancy":[{"pos":"n.","meaning":"休眠；蛰伏状态","definition":"a period of reduced activity or suspended growth","examples":[{"en":"The seeds can survive a long period of dormancy.","zh":"这些种子能够度过长期休眠。"},{"en":"The volcano showed signs of activity after centuries of dormancy.","zh":"休眠数百年后，这座火山显现出活动迹象。"}]}],"dormant":[{"pos":"adj.","meaning":"休眠的;暂不活动的;潜伏的","definition":"inactive for a time but capable of becoming active","examples":[{"en":"The seeds remain dormant through winter.","zh":"种子整个冬季处于休眠状态。"},{"en":"The investigation revived a dormant controversy.","zh":"这次调查重新引发了沉寂已久的争议。"}]}],"dormitory":[{"pos":"n.","meaning":"集体宿舍；学生宿舍","definition":"a shared sleeping room or student residence","examples":[{"en":"The hostel has a dormitory with eight beds.","zh":"旅舍有一间八张床的集体宿舍。"},{"en":"A new dormitory opened beside the campus.","zh":"校园旁新建成了一栋宿舍。"}]}],"dose":[{"pos":"n.","meaning":"一剂；剂量","definition":"a measured amount of a medicine or other substance","examples":[{"en":"The label states the amount in each dose.","zh":"标签说明了每剂的含量。"},{"en":"The study compared responses to different doses.","zh":"研究比较了对不同剂量的反应。"}]}],"dot":[{"pos":"n.","meaning":"点;小圆点","definition":"a small round mark","examples":[{"en":"Place a dot beside each completed task.","zh":"在每项已完成的任务旁画一个点。"},{"en":"The island appeared as a dot on the map.","zh":"岛屿在地图上看起来只是一个小点。"}]},{"pos":"v.","meaning":"打点;散布;点缀","definition":"to mark with dots or be scattered across","examples":[{"en":"Remember to dot your lowercase i.","zh":"记得在小写字母 i 上加点。"},{"en":"Small villages dot the valley.","zh":"小村庄散布在山谷中。"}]}],"download":[{"pos":"v.","meaning":"下载","definition":"to transfer data from a remote system to one's device","examples":[{"en":"You can download the timetable from the website.","zh":"你可以从网站下载时刻表。"},{"en":"She downloaded the lecture before leaving home.","zh":"她出门前下载了讲座。"}]}],"downpour":[{"pos":"n.","meaning":"暴雨；倾盆大雨","definition":"a sudden heavy fall of rain","examples":[{"en":"A downpour forced us to shelter in the station.","zh":"一场暴雨迫使我们到车站避雨。"},{"en":"The path flooded after the afternoon downpour.","zh":"下午的倾盆大雨过后，小路被淹了。"}]}],"downsize":[{"pos":"v.","meaning":"缩减;裁员;换住较小房屋","definition":"to reduce the size of an organization or living space","examples":[{"en":"The firm downsized after losing a major contract.","zh":"公司失去一份重要合同后缩减了规模。"},{"en":"After retirement, they downsized to a small flat.","zh":"退休后，他们换住了一套小公寓。"}]}],"draft":[{"pos":"n.","meaning":"草稿；草案","definition":"an early version of a piece of writing","examples":[{"en":"The first draft needs a clearer introduction.","zh":"初稿需要一个更清晰的引言。"},{"en":"Members discussed the draft of the new rules.","zh":"成员们讨论了新规则的草案。"}]},{"pos":"n.","meaning":"汇票","definition":"a written order for a bank to pay money","examples":[{"en":"The buyer paid by bank draft.","zh":"买家用银行汇票付款。"},{"en":"She obtained a draft in the required currency.","zh":"她办理了一张所需币种的汇票。"}]},{"pos":"n.","meaning":"征兵；征召","definition":"the compulsory recruitment of people into military service","examples":[{"en":"The novel follows a family during the military draft.","zh":"小说讲述了征兵时期一个家庭的故事。"},{"en":"The proposal to restore the draft prompted debate.","zh":"恢复征兵的提议引起了争论。"}]},{"pos":"n.","meaning":"穿堂风；气流（美式拼写）","definition":"a current of air in an enclosed space","examples":[{"en":"A cold draft came through the window.","zh":"冷风从窗户吹进来。"},{"en":"She moved her chair out of the draft.","zh":"她把椅子移出了穿堂风吹到的地方。"}]},{"pos":"v.","meaning":"起草；草拟","definition":"to write a preliminary version","examples":[{"en":"The lawyer drafted a new agreement.","zh":"律师起草了一份新协议。"},{"en":"She is drafting a letter to the council.","zh":"她正在草拟一封给议会的信。"}]},{"pos":"v.","meaning":"抽调；选派","definition":"to select people for a particular task","examples":[{"en":"Extra nurses were drafted in for the weekend.","zh":"周末抽调了额外的护士。"},{"en":"He was drafted onto the organising committee.","zh":"他被选派到组委会。"}]},{"pos":"v.","meaning":"征召入伍","definition":"to require someone to join the armed forces","examples":[{"en":"Her grandfather was drafted during the war.","zh":"她祖父在战争期间被征召入伍。"},{"en":"The records list men drafted from the district.","zh":"档案列出了该地区被征召入伍的男子。"}]}],"drainage":[{"pos":"n.","meaning":"排水；排水系统","definition":"the removal of excess water or the system doing it","examples":[{"en":"Poor drainage left the field waterlogged.","zh":"排水不良使田地积水。"},{"en":"The new road includes a modern drainage system.","zh":"新路配有现代排水系统。"}]}],"dramatic":[{"pos":"adj.","meaning":"显著的;戏剧性的;激动人心的","definition":"striking or exciting in effect","examples":[{"en":"The city has seen a dramatic rise in rents.","zh":"这座城市的租金大幅上涨。"},{"en":"A dramatic rescue saved the climbers.","zh":"一次惊心动魄的救援救下了登山者。"}]},{"pos":"adj.","meaning":"戏剧的","definition":"relating to plays or acting","examples":[{"en":"She joined the university's dramatic society.","zh":"她加入了大学戏剧社。"},{"en":"The course teaches dramatic techniques.","zh":"这门课程教授戏剧技巧。"}]}],"drawback":[{"pos":"n.","meaning":"缺点；不利条件","definition":"a disadvantage or problem","examples":[{"en":"The main drawback is the high initial cost.","zh":"主要缺点是初始成本高。"},{"en":"A possible drawback of online learning is isolation.","zh":"在线学习的一个潜在缺点是孤立感。"},{"en":"We should consider each drawback before deciding.","zh":"我们应该在决定前考虑每个缺点。"}]}],"dreadful":[{"pos":"adj.","meaning":"可怕的；极糟的","definition":"very unpleasant or frightening","examples":[{"en":"We heard dreadful news about the storm damage.","zh":"我们听到了关于风灾的可怕消息。"},{"en":"The room was in a dreadful state.","zh":"房间状况糟透了。"}]}],"dredge":[{"pos":"v.","meaning":"疏浚;挖掘;捞取","definition":"to remove material from the bottom of water","examples":[{"en":"They dredged the harbour to admit larger ships.","zh":"他们疏浚港口以便更大的船进入。"},{"en":"Workers dredged mud from the canal.","zh":"工人从运河里挖出淤泥。"}]},{"pos":"v.","meaning":"重提不快的往事","definition":"to bring back unpleasant memories or information","examples":[{"en":"Please do not dredge up old arguments.","zh":"请不要重提过去的争吵。"},{"en":"The article dredged up a long-forgotten scandal.","zh":"文章翻出了一个早已被遗忘的丑闻。"}]}],"drill":[{"pos":"n.","meaning":"钻；钻机","definition":"a tool that makes holes","examples":[{"en":"The carpenter used a drill to make the holes.","zh":"木匠用钻机打孔。"},{"en":"This drill runs on a rechargeable battery.","zh":"这把钻使用充电电池。"}]},{"pos":"n.","meaning":"训练；演习","definition":"repeated practice of a skill or procedure","examples":[{"en":"The school held a fire drill.","zh":"学校进行了消防演习。"},{"en":"Short pronunciation drills helped the learners.","zh":"简短的发音训练帮助了学习者。"}]},{"pos":"v.","meaning":"钻孔","definition":"to make a hole with a drill","examples":[{"en":"They drilled through the concrete wall.","zh":"他们在混凝土墙上钻了孔。"},{"en":"Drill two holes near the edge of the board.","zh":"在木板边缘附近钻两个孔。"}]},{"pos":"v.","meaning":"训练；反复操练","definition":"to teach by repeated practice","examples":[{"en":"The coach drilled the players in basic movements.","zh":"教练让队员反复练习基本动作。"},{"en":"We were drilled in emergency procedures.","zh":"我们反复训练应急程序。"}]}],"droplet":[{"pos":"n.","meaning":"小滴；液滴","definition":"a very small drop of liquid","examples":[{"en":"Tiny droplets formed on the cold glass.","zh":"冷玻璃上形成了细小水滴。"},{"en":"The camera captured a droplet falling into the pool.","zh":"相机拍到了一个液滴落入水池的画面。"}]}],"drought":[{"pos":"n.","meaning":"干旱;旱灾","definition":"a long period with little or no rain","examples":[{"en":"The drought destroyed much of the harvest.","zh":"干旱毁掉了大部分收成。"},{"en":"Reservoir levels fell during the prolonged drought.","zh":"持续干旱期间水库水位下降了。"}]}],"drum":[{"pos":"n.","meaning":"鼓","definition":"a musical instrument struck to produce sound","examples":[{"en":"The parade began with the beat of a drum.","zh":"游行在鼓声中开始。"},{"en":"She plays the drums in a local band.","zh":"她在当地乐队打鼓。"}]},{"pos":"n.","meaning":"桶；鼓状部件","definition":"a large cylindrical container or machine part","examples":[{"en":"Oil was stored in metal drums.","zh":"油储存在金属桶中。"},{"en":"The washing machine's drum stopped turning.","zh":"洗衣机的滚筒停止了转动。"}]}],"dubious":[{"pos":"adj.","meaning":"怀疑的；不确定的","definition":"not convinced that something is true or worthwhile","examples":[{"en":"She was dubious about the promised savings.","zh":"她对承诺的节省金额持怀疑态度。"},{"en":"I remain dubious whether the timetable is realistic.","zh":"我仍怀疑这个时间表是否现实。"}]},{"pos":"adj.","meaning":"靠不住的；可疑的","definition":"unlikely to be trustworthy or acceptable","examples":[{"en":"The article relied on dubious sources.","zh":"文章依赖了不可靠的来源。"},{"en":"The proposal offered benefits of dubious value.","zh":"这项提议提供的好处价值可疑。"}]}],"due":[{"pos":"adj.","meaning":"到期的;预定的","definition":"expected or required at a particular time","examples":[{"en":"The rent is due on Monday.","zh":"房租周一到期。"},{"en":"The train is due at ten.","zh":"火车预计十点到达。"}]},{"pos":"adj.","meaning":"应得的;应有的;适当的","definition":"owed to someone or appropriate in the circumstances","examples":[{"en":"Give the volunteers the credit they are due.","zh":"给予志愿者应得的肯定。"},{"en":"The committee considered the proposal with due care.","zh":"委员会给予提案应有的认真考虑。"}]}],"dull":[{"pos":"adj.","meaning":"乏味的；无趣的","definition":"not interesting or exciting","examples":[{"en":"The lecture was dull despite its promising title.","zh":"讲座标题虽吸引人，内容却乏味。"},{"en":"A dull journey became enjoyable when we started chatting.","zh":"我们开始聊天后，乏味的旅途变得有趣。"}]},{"pos":"adj.","meaning":"阴沉的；暗淡的","definition":"lacking brightness or sunshine","examples":[{"en":"It was a dull afternoon with low clouds.","zh":"那天下午阴沉沉的，云层很低。"},{"en":"The old brass had a dull surface.","zh":"旧黄铜表面暗淡无光。"}]}],"dump":[{"pos":"v.","meaning":"倾倒；丢弃","definition":"to unload or discard something carelessly","examples":[{"en":"Do not dump waste beside the road.","zh":"不要把废物倾倒在路边。"},{"en":"The truck dumped sand onto the building site.","zh":"卡车把沙子卸在工地上。"}]},{"pos":"n.","meaning":"垃圾场；堆放场","definition":"a place where unwanted material is left","examples":[{"en":"The old dump has been converted into a park.","zh":"旧垃圾场已经改建为公园。"},{"en":"They took the broken furniture to the dump.","zh":"他们把坏家具运到了垃圾场。"}]}],"dupe":[{"pos":"n.","meaning":"受骗者","definition":"a person who has been tricked","examples":[{"en":"He was an innocent dupe in the scheme.","zh":"他是这场阴谋中无辜的受骗者。"},{"en":"The fraudsters searched for another wealthy dupe.","zh":"诈骗者在寻找另一个有钱的受骗者。"}]},{"pos":"v.","meaning":"欺骗;愚弄","definition":"to trick someone into believing or doing something","examples":[{"en":"The email duped users into revealing passwords.","zh":"这封邮件诱骗用户泄露密码。"},{"en":"She was duped by a forged certificate.","zh":"她被一张伪造的证书骗了。"}]}],"duplicate":[{"pos":"v.","meaning":"复制；重复","definition":"to make an identical copy or do something again","examples":[{"en":"Please duplicate the file before editing it.","zh":"编辑前请复制这个文件。"},{"en":"The new study duplicated the earlier experiment.","zh":"新研究重复了之前的实验。"}],"ipa":"/ˈdjuːplɪkeɪt/"},{"pos":"adj.","meaning":"完全相同的；副本的","definition":"exactly like another item","examples":[{"en":"Keep a duplicate key in a safe place.","zh":"把备用钥匙放在安全的地方。"},{"en":"The database contained several duplicate records.","zh":"数据库里有几条重复记录。"}],"ipa":"/ˈdjuːplɪkət/"},{"pos":"n.","meaning":"复制品；副本","definition":"an exact copy","examples":[{"en":"She gave me a duplicate of the receipt.","zh":"她给了我一份收据副本。"},{"en":"The museum displays a duplicate while the original is restored.","zh":"原件修复期间，博物馆展示复制品。"}],"ipa":"/ˈdjuːplɪkət/"}],"durable":[{"pos":"adj.","meaning":"耐用的；持久的","definition":"able to last a long time","examples":[{"en":"The bag is made from a durable fabric.","zh":"这个包由耐用面料制成。"},{"en":"We need a durable solution rather than a temporary repair.","zh":"我们需要持久的解决办法，而非临时修补。"}]},{"pos":"n.","meaning":"耐用品（常用复数 durables）","definition":"a product expected to last for years","examples":[{"en":"Spending on consumer durables fell last quarter.","zh":"上一季度耐用消费品支出下降了。"},{"en":"Refrigerators and washing machines are household durables.","zh":"冰箱和洗衣机是家用耐用品。"}]}],"duration":[{"pos":"n.","meaning":"持续时间;期间","definition":"the length of time something lasts","examples":[{"en":"The treatment's duration varies between patients.","zh":"不同患者的治疗时长各不相同。"},{"en":"Keep your seat belt fastened for the flight's duration.","zh":"整个飞行期间请系好安全带。"}]}],"dusk":[{"pos":"n.","meaning":"黄昏；薄暮","definition":"the time when daylight is fading","examples":[{"en":"We reached the village at dusk.","zh":"我们在黄昏时到达村庄。"},{"en":"Bats emerged from the roof as dusk fell.","zh":"暮色降临时，蝙蝠从屋顶飞出。"}]}],"dwell":[{"pos":"v.","meaning":"居住；栖身","definition":"to live in a place","examples":[{"en":"Several bird species dwell in the marsh.","zh":"几种鸟类栖息在这片沼泽。"},{"en":"The story describes families dwelling beside the river.","zh":"故事描写了住在河边的家庭。"}]}],"dweller":[{"pos":"n.","meaning":"居民;居住者","definition":"a person or animal living in a particular place","examples":[{"en":"City dwellers often lack access to gardens.","zh":"城市居民往往缺少使用花园的机会。"},{"en":"Cave dwellers left paintings on the walls.","zh":"洞穴居民在洞壁上留下了绘画。"}]}],"dwindle":[{"pos":"v.","meaning":"逐渐减少；逐渐缩小","definition":"to become steadily smaller or fewer","examples":[{"en":"Food supplies dwindled during the journey.","zh":"旅途中食物储备逐渐减少。"},{"en":"The crowd dwindled as the evening grew colder.","zh":"夜间越来越冷，人群渐渐散去。"}]}],"dynamic":[{"pos":"adj.","meaning":"充满活力的；不断变化的","definition":"energetic or continually developing","examples":[{"en":"The city has a dynamic arts scene.","zh":"这座城市的艺术领域充满活力。"},{"en":"A dynamic leader helped the team adapt.","zh":"一位充满活力的领导帮助团队适应变化。"}]},{"pos":"adj.","meaning":"动力的；动态的","definition":"relating to forces or motion","examples":[{"en":"The engineers tested the bridge under dynamic loads.","zh":"工程师在动态负载下测试了桥梁。"},{"en":"The model describes the dynamic behaviour of the system.","zh":"模型描述了系统的动态行为。"}]}],"dystrophy":[{"pos":"n.","meaning":"营养障碍;营养不良性病变","definition":"a condition in which body tissue progressively weakens or develops abnormally","examples":[{"en":"The specialist diagnosed a form of muscular dystrophy.","zh":"专科医生诊断出一种肌营养不良症。"},{"en":"The study follows families affected by retinal dystrophy.","zh":"该研究跟踪患有视网膜营养不良的家庭。"}]}],"earthquake":[{"pos":"n.","meaning":"地震","definition":"a sudden shaking of the ground","examples":[{"en":"The earthquake damaged several roads.","zh":"地震损坏了几条道路。"},{"en":"Engineers studied how the bridge behaved during the earthquake.","zh":"工程师研究了大桥在地震中的表现。"}]}],"earthwork":[{"pos":"n.","meaning":"土方工程；土筑工事","definition":"construction involving moving earth or a structure made of earth","examples":[{"en":"Earthwork began before the road surface was laid.","zh":"铺设路面之前，土方工程就开始了。"},{"en":"The hilltop earthworks date from an ancient settlement.","zh":"山顶的土筑工事源自一处古代聚落。"}]}],"earthworm":[{"pos":"n.","meaning":"蚯蚓","definition":"a worm that lives in soil","examples":[{"en":"An earthworm wriggled beneath the wet leaves.","zh":"一条蚯蚓在湿树叶下蠕动。"},{"en":"Earthworms help mix organic matter into soil.","zh":"蚯蚓帮助把有机物混入土壤。"}]},{"pos":"n.","meaning":"卑微的人;俗人（旧式贬义）","definition":"an insignificant or worldly person in old-fashioned insulting usage","examples":[{"en":"To the arrogant duke, the poor clerk was an earthworm.","zh":"在傲慢的公爵眼中，穷职员不过是个卑微小人。"},{"en":"The poet refused to flatter the wealthy earthworms at court.","zh":"诗人拒绝奉承宫廷里那些富有的俗人。"}]}],"easy-going":[{"pos":"adj.","meaning":"随和的；不拘小节的","definition":"relaxed and not easily upset","examples":[{"en":"Our easy-going host made everyone feel welcome.","zh":"随和的主人让大家感到宾至如归。"},{"en":"She has an easy-going attitude towards minor delays.","zh":"她对小小的延误并不计较。"}]}],"eccentric":[{"pos":"adj.","meaning":"古怪的；不合常规的","definition":"unusual in behaviour or style","examples":[{"en":"His eccentric clothing made him easy to recognize.","zh":"他古怪的衣着使人很容易认出他。"},{"en":"The artist was known for her eccentric habits.","zh":"这位艺术家以古怪的习惯出名。"}]},{"pos":"n.","meaning":"古怪的人","definition":"a person with unusual habits or ideas","examples":[{"en":"The village eccentric collected broken clocks.","zh":"村里那个怪人收集坏钟。"},{"en":"The memoir portrays him as a lovable eccentric.","zh":"回忆录把他描绘成一个可爱的怪人。"}]}],"ecliptic":[{"pos":"n.","meaning":"黄道","definition":"the Sun's apparent annual path across the celestial sphere","examples":[{"en":"The chart marks the ecliptic with a yellow line.","zh":"星图用黄线标出黄道。"},{"en":"Most planets appear close to the ecliptic.","zh":"大多数行星看起来接近黄道。"}]},{"pos":"adj.","meaning":"黄道的","definition":"relating to the Sun's apparent annual path or Earth's orbital plane","examples":[{"en":"The diagram shows the ecliptic plane.","zh":"图中显示了黄道平面。"},{"en":"The catalogue lists each star's ecliptic coordinates.","zh":"星表列出了每颗恒星的黄道坐标。"}]},{"pos":"adj.","meaning":"日食的;月食的（专业用语）","definition":"relating to an eclipse","examples":[{"en":"The astronomer compared several ecliptic observations.","zh":"天文学家比较了数次食象观测。"},{"en":"Ancient records contain dates of ecliptic events.","zh":"古代记录中包含发生食象的日期。"}]}],"eco-friendly":[{"pos":"adj.","meaning":"环保的；对环境友好的","definition":"designed to cause less environmental harm","examples":[{"en":"The shop uses eco-friendly packaging.","zh":"这家店使用环保包装。"},{"en":"Cycling is an eco-friendly way to travel locally.","zh":"骑自行车是环保的本地出行方式。"}]}],"ecological":[{"pos":"adj.","meaning":"生态的；生态学的","definition":"relating to interactions between organisms and their environment","examples":[{"en":"The dam caused significant ecological changes.","zh":"大坝造成了显著的生态变化。"},{"en":"The survey assessed the ecological value of the woodland.","zh":"调查评估了这片林地的生态价值。"}]}],"ecology":[{"pos":"n.","meaning":"生态学","definition":"the study of relationships between organisms and their surroundings","examples":[{"en":"She teaches ecology at the university.","zh":"她在大学教授生态学。"},{"en":"Ecology connects the study of organisms and environments.","zh":"生态学把生物与环境的研究联系起来。"}]},{"pos":"n.","meaning":"生态;生态环境","definition":"the relationships and conditions within a natural environment","examples":[{"en":"Pollution altered the lake's ecology.","zh":"污染改变了湖泊生态。"},{"en":"The reserve protects the ecology of the wetlands.","zh":"保护区保护着湿地的生态环境。"}]}],"economic":[{"pos":"adj.","meaning":"经济的；经济学的","definition":"relating to an economy or economics","examples":[{"en":"The report examines economic growth in rural areas.","zh":"报告研究农村地区的经济增长。"},{"en":"She studies the economic effects of tourism.","zh":"她研究旅游业的经济影响。"}]},{"pos":"adj.","meaning":"有经济效益的；合算的","definition":"producing enough benefit to justify the cost","examples":[{"en":"The small deposit was not economic to mine.","zh":"这个小矿床开采起来不合算。"},{"en":"The company must find an economic way to transport the goods.","zh":"公司必须找到合算的货物运输方法。"}]}],"economical":[{"pos":"adj.","meaning":"节约的；经济实惠的","definition":"using little money, energy, or material","examples":[{"en":"This heater is more economical to run.","zh":"这台取暖器运行起来更省钱。"},{"en":"Her economical use of words made the message clear.","zh":"她用词简练，使信息很清楚。"}]}],"ecosystem":[{"pos":"n.","meaning":"生态系统","definition":"organisms and their physical environment interacting as a system","examples":[{"en":"Coral reefs support a complex ecosystem.","zh":"珊瑚礁支撑着复杂的生态系统。"},{"en":"Removing predators can disturb an entire ecosystem.","zh":"移除捕食者会扰乱整个生态系统。"}]}],"edible":[{"pos":"adj.","meaning":"可食用的","definition":"safe or suitable to eat","examples":[{"en":"Only some of the berries are edible.","zh":"只有部分浆果可以食用。"},{"en":"The cake was decorated with edible flowers.","zh":"蛋糕用可食用花朵装饰。"}]}],"edify":[{"pos":"v.","meaning":"教化；启迪；陶冶","definition":"to improve someone's understanding or moral awareness","examples":[{"en":"The lecture aimed to edify rather than merely entertain.","zh":"这场讲座旨在启迪听众，而不只是提供娱乐。"},{"en":"The exhibition both delighted and edified its visitors.","zh":"这场展览既愉悦了参观者，也启发了他们。"}]}],"effect":[{"pos":"n.","meaning":"影响;作用;结果;效果","definition":"a change or result produced by something","examples":[{"en":"The medicine had little effect on the pain.","zh":"药物对疼痛作用不大。"},{"en":"We measured the effect of temperature on growth.","zh":"我们测量了温度对生长的影响。"}]},{"pos":"v.","meaning":"实现;促成","definition":"to bring something about","examples":[{"en":"The reforms effected a lasting change.","zh":"改革带来了持久的变化。"},{"en":"The negotiators effected a compromise.","zh":"谈判者促成了妥协。"}]}],"effective":[{"pos":"adj.","meaning":"有效的；起作用的","definition":"producing the intended result","examples":[{"en":"The new method proved effective in reducing waste.","zh":"新方法证明能有效减少浪费。"},{"en":"Regular feedback is an effective teaching tool.","zh":"定期反馈是一种有效的教学工具。"}]},{"pos":"adj.","meaning":"生效的","definition":"officially in force from a particular time","examples":[{"en":"The new agreement is effective from Monday.","zh":"新协议从星期一起生效。"},{"en":"The revised prices become effective next month.","zh":"调整后的价格下月生效。"}]},{"pos":"adj.","meaning":"给人深刻印象的；效果出色的","definition":"creating a strong or striking impression","examples":[{"en":"The simple lighting created an effective stage image.","zh":"简单的灯光营造了出色的舞台画面。"},{"en":"Her quiet ending was surprisingly effective.","zh":"她平静的结尾出人意料地令人印象深刻。"}]}],"efficiency":[{"pos":"n.","meaning":"效率；效能","definition":"the ability to achieve results with little waste","examples":[{"en":"Better insulation improves energy efficiency.","zh":"更好的隔热能提高能源利用效率。"},{"en":"The changes increased the efficiency of the booking system.","zh":"这些调整提高了预订系统的效率。"}]}],"efficient":[{"pos":"adj.","meaning":"高效的；能胜任的","definition":"working well without wasting time or resources","examples":[{"en":"The new system is more efficient than the old one.","zh":"新系统比旧系统更高效。"},{"en":"An efficient bus service saves commuters time.","zh":"高效的公交服务能节省通勤者的时间。"},{"en":"We need an efficient way to process applications.","zh":"我们需要高效处理申请的方法。"}]}],"effort":[{"pos":"n.","meaning":"努力；费力的尝试","definition":"the physical or mental energy used to do something","examples":[{"en":"Learning the instrument requires patience and effort.","zh":"学习这种乐器需要耐心和努力。"},{"en":"She made an effort to remember every name.","zh":"她努力记住每个人的名字。"}]},{"pos":"n.","meaning":"努力的成果；作品","definition":"something produced through an attempt","examples":[{"en":"His latest novel is his best effort so far.","zh":"他最新的小说是目前最好的作品。"},{"en":"The children's artistic efforts covered the classroom walls.","zh":"孩子们的艺术作品贴满了教室墙壁。"}]}],"eject":[{"pos":"v.","meaning":"弹出；喷出","definition":"to force something out","examples":[{"en":"Press this button to eject the disc.","zh":"按这个按钮弹出光盘。"},{"en":"The volcano ejected ash into the air.","zh":"火山向空中喷出了火山灰。"}]},{"pos":"v.","meaning":"驱逐；赶出","definition":"to force someone to leave","examples":[{"en":"The disruptive spectator was ejected from the stadium.","zh":"扰乱秩序的观众被赶出了体育场。"},{"en":"The tenant was not ejected without a formal hearing.","zh":"没有正式听证，该租客并未被驱逐。"}]}],"ejection":[{"pos":"n.","meaning":"喷出;排出;驱逐","definition":"the act of forcing something or someone out","examples":[{"en":"The pilot survived the emergency ejection.","zh":"飞行员在紧急弹射后生还。"},{"en":"Violent behaviour led to his ejection from the stadium.","zh":"暴力行为导致他被驱逐出体育场。"}]},{"pos":"n.","meaning":"喷出物;排出物","definition":"material forced out of something","examples":[{"en":"Volcanic ejections covered the nearby slopes.","zh":"火山喷出物覆盖了附近山坡。"},{"en":"The laboratory examined solid ejections from the vent.","zh":"实验室检查了喷口排出的固体物质。"}]}],"elaborate":[{"pos":"adj.","meaning":"复杂的；精心制作的；详尽的","definition":"containing many carefully arranged details","examples":[{"en":"The wedding involved elaborate preparations.","zh":"婚礼需要精心而复杂的准备。"},{"en":"The ceiling was covered with elaborate carvings.","zh":"天花板上布满精雕细刻的图案。"}],"ipa":"/ɪˈlæbərət/"},{"pos":"v.","meaning":"详述；详细阐述","definition":"to explain something with more detail","examples":[{"en":"Could you elaborate on the reasons for your choice?","zh":"你能详细说明选择的理由吗？"},{"en":"The speaker elaborated her argument with examples.","zh":"发言者用例子详细阐述了论点。"}],"ipa":"/ɪˈlæbəreɪt/"},{"pos":"v.","meaning":"详细制定；精心发展","definition":"to develop something in detail","examples":[{"en":"The team elaborated a plan for restoring the wetlands.","zh":"团队详细制定了恢复湿地的计划。"},{"en":"The composer elaborated the theme in the final movement.","zh":"作曲家在最后一个乐章中深入发展了这一主题。"}],"ipa":"/ɪˈlæbəreɪt/"}],"elaboration":[{"pos":"n.","meaning":"详细阐述；发挥","definition":"the addition of detailed explanation","examples":[{"en":"The proposal needs further elaboration.","zh":"这项提议需要进一步阐述。"},{"en":"Her answer was clear and required no elaboration.","zh":"她的回答很清楚，无须展开说明。"}]},{"pos":"n.","meaning":"精心设计的作品；扩展成果","definition":"something developed by adding careful detail","examples":[{"en":"The final design is an elaboration of the original sketch.","zh":"最终设计是对原始草图的精心扩展。"},{"en":"The sculpture is an intricate elaboration of a simple theme.","zh":"这座雕塑是对一个简单主题的复杂演绎。"}]}],"elastic":[{"pos":"adj.","meaning":"有弹性的","definition":"able to stretch and return to its original shape","examples":[{"en":"The elastic fabric moves with your body.","zh":"弹性织物会随身体动作伸缩。"},{"en":"A rubber band is highly elastic.","zh":"橡皮筋很有弹性。"}]},{"pos":"adj.","meaning":"灵活的;可伸缩的","definition":"able to change or adapt","examples":[{"en":"The schedule is elastic enough to allow delays.","zh":"时间安排灵活，能够容纳延误。"},{"en":"Demand for luxury goods is often elastic.","zh":"对奢侈品的需求往往富有弹性。"}]},{"pos":"n.","meaning":"松紧带;橡皮筋","definition":"a stretchy band or material","examples":[{"en":"The elastic in these trousers has worn out.","zh":"这条裤子的松紧带失去弹性了。"},{"en":"Secure the papers with a piece of elastic.","zh":"用一根橡皮筋捆好这些纸。"}]}],"elbow":[{"pos":"n.","meaning":"肘；手肘","definition":"the joint in the middle of the arm","examples":[{"en":"He rested his elbows on the table.","zh":"他把双肘放在桌上。"},{"en":"She bent her elbow to lift the cup.","zh":"她屈肘拿起杯子。"}]},{"pos":"n.","meaning":"衣服的肘部","definition":"the part of a sleeve covering the elbow","examples":[{"en":"The jacket has leather patches at the elbows.","zh":"夹克的肘部有皮革补丁。"},{"en":"One elbow of his sweater was worn thin.","zh":"他毛衣的一侧肘部磨薄了。"}]}],"electrical":[{"pos":"adj.","meaning":"电的；电学的","definition":"relating to electricity","examples":[{"en":"The building needs new electrical wiring.","zh":"这栋建筑需要重新布置电线。"},{"en":"She is studying electrical engineering.","zh":"她正在学习电气工程。"}]}],"electronic":[{"pos":"adj.","meaning":"电子的","definition":"using or relating to electronic circuits","examples":[{"en":"The shop sells electronic components.","zh":"这家店出售电子元件。"},{"en":"Keep an electronic copy of the receipt.","zh":"保存一份收据的电子副本。"}]}],"element":[{"pos":"n.","meaning":"要素；组成部分","definition":"one part of a larger whole","examples":[{"en":"Trust is an essential element of teamwork.","zh":"信任是团队协作的重要要素。"},{"en":"The design combines traditional and modern elements.","zh":"设计结合了传统和现代元素。"}]},{"pos":"n.","meaning":"元素","definition":"a substance consisting of one type of atom","examples":[{"en":"Oxygen is an element found in water.","zh":"氧是水中含有的一种元素。"},{"en":"The students learned to identify chemical elements.","zh":"学生们学习辨认化学元素。"}]},{"pos":"n.","meaning":"基本原理；基础知识（用复数）","definition":"the basic principles of a subject","examples":[{"en":"The course introduces the elements of music theory.","zh":"这门课程介绍乐理基础。"},{"en":"She taught herself the elements of geometry.","zh":"她自学了几何学的基本原理。"}]}],"elevate":[{"pos":"v.","meaning":"提高；提升","definition":"to raise a position, level, or status","examples":[{"en":"The platform can be elevated for a better view.","zh":"平台可以升高，以获得更好视野。"},{"en":"The promotion elevated her to a senior role.","zh":"这次晋升使她进入了高级职位。"}]},{"pos":"v.","meaning":"提升修养；使高尚","definition":"to improve the quality of thought or experience","examples":[{"en":"The museum aims to elevate public appreciation of design.","zh":"博物馆旨在提升公众对设计的欣赏能力。"},{"en":"The discussion elevated the debate beyond personal complaints.","zh":"讨论使辩论超越了个人抱怨的层次。"}]}],"elicitation":[{"pos":"n.","meaning":"引出;诱出","definition":"the process of obtaining a response or information","examples":[{"en":"The interview used pictures for memory elicitation.","zh":"访谈借助图片唤起记忆。"},{"en":"Careful questioning improved the elicitation of useful details.","zh":"仔细提问有助于获取有用细节。"}]}],"eligible":[{"pos":"adj.","meaning":"符合资格的","definition":"meeting the conditions required for something","examples":[{"en":"Students are eligible for a reduced bus fare.","zh":"学生有资格享受优惠公交票价。"},{"en":"You may be eligible for financial support.","zh":"你可能符合获得经济援助的条件。"},{"en":"Only local residents are eligible to apply.","zh":"只有当地居民有资格申请。"}]},{"pos":"adj.","meaning":"适宜婚配的；理想的（常修饰 bachelor）","definition":"considered a desirable marriage partner","examples":[{"en":"The novel introduces a wealthy, eligible bachelor.","zh":"小说介绍了一位富有的理想单身男士。"},{"en":"Her aunt regarded the young lawyer as highly eligible.","zh":"她姑母认为那位年轻律师是非常合适的结婚对象。"}]}],"eligible for":[{"pos":"phr.","meaning":"有资格获得；符合……的条件","definition":"meeting the conditions needed to receive or apply for something","examples":[{"en":"Full-time students are eligible for a travel discount.","zh":"全日制学生可以享受交通优惠。"},{"en":"You may be eligible for financial support during the course.","zh":"你在修读这门课程期间可能符合获得经济资助的条件。"}]}],"eliminate":[{"pos":"v.","meaning":"消除；排除；淘汰","definition":"to remove completely","examples":[{"en":"The filter eliminates most visible particles.","zh":"过滤器清除了大多数可见颗粒。"},{"en":"One error eliminated the team from the contest.","zh":"一个错误使团队被淘汰出比赛。"}]}],"elite":[{"pos":"n.","meaning":"精英;上层集团","definition":"a small group with exceptional power, wealth, or ability","examples":[{"en":"The school once served only the social elite.","zh":"这所学校过去只招收社会上层人士。"},{"en":"A scientific elite advised the government.","zh":"一群科学精英为政府提供建议。"}]},{"pos":"adj.","meaning":"精锐的;杰出的","definition":"belonging to a highly skilled or powerful group","examples":[{"en":"Elite athletes train for many hours daily.","zh":"顶尖运动员每天训练许多小时。"},{"en":"An elite rescue unit entered the building.","zh":"一支精锐救援队进入了建筑物。"}]}],"elucidate":[{"pos":"v.","meaning":"阐明；解释清楚","definition":"to make something clear by explaining it","examples":[{"en":"The diagram elucidates the flow of water.","zh":"示意图阐明了水的流动过程。"},{"en":"Further research may elucidate the causes of the change.","zh":"进一步研究或许能阐明变化的原因。"}]}],"elusive":[{"pos":"adj.","meaning":"难以找到的；难以捉摸的","definition":"difficult to catch, find, or understand","examples":[{"en":"The researchers searched for the elusive animal.","zh":"研究人员寻找那种难觅踪迹的动物。"},{"en":"A clear explanation remained elusive.","zh":"清楚的解释仍难以找到。"}]}],"embankment":[{"pos":"n.","meaning":"堤岸;路基;筑堤","definition":"a raised bank of earth or stone or the making of one","examples":[{"en":"The river burst through the embankment.","zh":"河水冲破了堤岸。"},{"en":"The railway runs along a high embankment.","zh":"铁路沿着高高的路基延伸。"}]}],"embark":[{"pos":"v.","meaning":"上船；登机","definition":"to go aboard a ship or aircraft","examples":[{"en":"Passengers embarked at the northern terminal.","zh":"乘客在北航站楼登机。"},{"en":"We embarked on the ferry before sunrise.","zh":"我们日出前登上了渡轮。"}]},{"pos":"v.","meaning":"着手；开始从事","definition":"to begin a new project or activity","examples":[{"en":"She embarked on a study of local history.","zh":"她开始研究地方历史。"},{"en":"The company is embarking on a major expansion.","zh":"公司正着手进行大规模扩张。"}]}],"embassy":[{"pos":"n.","meaning":"大使馆；使馆人员","definition":"the office and staff representing a country abroad","examples":[{"en":"She contacted the embassy about the lost passport.","zh":"她就丢失护照的事联系了大使馆。"},{"en":"The embassy issued a statement after the meeting.","zh":"会后，大使馆发表了声明。"}]}],"embed":[{"pos":"v.","meaning":"嵌入;埋入;插入","definition":"to fix something firmly within a surrounding material","examples":[{"en":"A shard of glass was embedded in the tyre.","zh":"一块玻璃碎片嵌在轮胎里。"},{"en":"You can embed a video in the webpage.","zh":"你可以在网页中嵌入视频。"}]},{"pos":"v.","meaning":"使深植;使牢固存在","definition":"to establish something deeply in thought or practice","examples":[{"en":"These values are embedded in the school culture.","zh":"这些价值观深植于学校文化之中。"},{"en":"The frightening image remained embedded in his memory.","zh":"那幅可怕的画面深深留在他的记忆中。"}]}],"embezzlement":[{"pos":"n.","meaning":"贪污；挪用公款","definition":"the dishonest taking of money entrusted to one's care","examples":[{"en":"The audit uncovered evidence of embezzlement.","zh":"审计发现了挪用公款的证据。"},{"en":"The treasurer faced an investigation into alleged embezzlement.","zh":"财务主管因涉嫌贪污接受调查。"}]}],"embody":[{"pos":"v.","meaning":"体现；具体表现","definition":"to express an idea in a clear or physical form","examples":[{"en":"The design embodies the principle of simplicity.","zh":"这个设计体现了简洁原则。"},{"en":"Her work embodies a deep concern for social justice.","zh":"她的作品体现了对社会公正的深切关怀。"}]},{"pos":"v.","meaning":"包含；纳入","definition":"to include something as part of a whole","examples":[{"en":"The final report embodies suggestions from local residents.","zh":"最终报告纳入了当地居民的建议。"},{"en":"The agreement embodies several earlier commitments.","zh":"协议包含了几项先前的承诺。"}]}],"emboss":[{"pos":"v.","meaning":"压花;使图案凸起","definition":"to create a raised design on a surface","examples":[{"en":"The cover was embossed with silver letters.","zh":"封面上压印着凸起的银色字母。"},{"en":"Craft workers emboss floral patterns onto leather.","zh":"手工艺人把花卉图案压印在皮革上。"}]}],"embrace":[{"pos":"v.","meaning":"拥抱","definition":"to hold someone closely in one's arms","examples":[{"en":"She embraced her sister at the station.","zh":"她在车站拥抱了妹妹。"},{"en":"The two friends embraced after years apart.","zh":"分别多年后，两位朋友拥抱在一起。"}]},{"pos":"v.","meaning":"欣然接受；拥护","definition":"to accept an idea or change willingly","examples":[{"en":"The school embraced new teaching methods.","zh":"学校欣然采用了新的教学方法。"},{"en":"Residents embraced the plan for a community garden.","zh":"居民们热情支持建设社区花园的计划。"}]},{"pos":"v.","meaning":"包括；涵盖","definition":"to include a range of things","examples":[{"en":"The course embraces literature, history, and philosophy.","zh":"课程涵盖文学、历史和哲学。"},{"en":"Their research embraces several different approaches.","zh":"他们的研究涵盖几种不同方法。"}]},{"pos":"n.","meaning":"拥抱","definition":"an act of holding someone closely","examples":[{"en":"He greeted his mother with a warm embrace.","zh":"他热情拥抱母亲以示问候。"},{"en":"The child relaxed in her father's embrace.","zh":"孩子在父亲的怀抱中放松下来。"}]}],"embryo":[{"pos":"n.","meaning":"胚胎","definition":"an organism in an early stage of development","examples":[{"en":"The microscope revealed the developing embryo.","zh":"显微镜显示了正在发育的胚胎。"},{"en":"The seed protects a tiny plant embryo.","zh":"种子保护着一个微小的植物胚。"}]},{"pos":"n.","meaning":"事物的初始阶段；雏形","definition":"something at a very early stage","examples":[{"en":"The plan is still in embryo.","zh":"这个计划还处于萌芽阶段。"},{"en":"The diary contains the embryo of her later novel.","zh":"日记中包含了她后来小说的雏形。"}]}],"emerge":[{"pos":"v.","meaning":"出现;显露","definition":"to come into view or become known","examples":[{"en":"A deer emerged from the forest.","zh":"一只鹿从森林中走了出来。"},{"en":"New evidence emerged during the trial.","zh":"审判期间出现了新证据。"}]}],"emergency":[{"pos":"n.","meaning":"紧急情况；突发事件","definition":"a serious unexpected situation requiring immediate action","examples":[{"en":"Keep the exits clear in case of an emergency.","zh":"保持出口畅通，以备紧急情况。"},{"en":"The crew practised responding to an engine emergency.","zh":"机组人员演练了发动机突发故障的应对程序。"}]}],"emeritus":[{"pos":"adj.","meaning":"荣誉退休的；退休后保留头衔的","definition":"retired while retaining an honorary professional title","examples":[{"en":"He continues to teach as professor emeritus.","zh":"他以荣休教授身份继续教学。"},{"en":"The university honoured its emeritus librarian.","zh":"大学向荣誉退休的图书馆馆长致敬。"}]}],"eminent":[{"pos":"adj.","meaning":"杰出的;著名的","definition":"highly respected for achievements in a field","examples":[{"en":"An eminent historian delivered the lecture.","zh":"一位杰出的历史学家作了讲座。"},{"en":"She sought advice from an eminent surgeon.","zh":"她向一位著名外科医生征求意见。"}]}],"emission":[{"pos":"n.","meaning":"排放；排放物","definition":"the release of gas or other substances","examples":[{"en":"The factory reduced its emission of harmful gases.","zh":"工厂减少了有害气体排放。"},{"en":"The emission of carbon dioxide contributes to climate change.","zh":"二氧化碳排放促成气候变化。"},{"en":"The new engine meets strict emission standards.","zh":"新发动机符合严格的排放标准。"}]},{"pos":"n.","meaning":"散发；发射（光、热或辐射等）","definition":"the sending out of energy such as light or heat","examples":[{"en":"The instrument measures light emission from the sample.","zh":"仪器测量样本发出的光。"},{"en":"Researchers recorded the emission of heat from the surface.","zh":"研究人员记录了表面散发的热量。"}]}],"emit":[{"pos":"v.","meaning":"发出；排放；散发","definition":"to release light, heat, sound, or a substance","examples":[{"en":"The sensor emits a short pulse of light.","zh":"传感器发出一个短光脉冲。"},{"en":"Older vehicles may emit more pollutants.","zh":"旧车辆可能排放更多污染物。"}]}],"emotion":[{"pos":"n.","meaning":"情感;情绪","definition":"a strong feeling such as joy, anger, or fear","examples":[{"en":"His voice trembled with emotion.","zh":"他的声音因激动而颤抖。"},{"en":"Music can express complex emotions.","zh":"音乐能够表达复杂的情感。"}]}],"emotional":[{"pos":"adj.","meaning":"情感的；情绪的","definition":"relating to feelings","examples":[{"en":"The course explores children's emotional development.","zh":"课程探讨儿童的情感发展。"},{"en":"Moving home can have an emotional impact.","zh":"搬家可能带来情绪上的影响。"}]},{"pos":"adj.","meaning":"情绪激动的；动人的","definition":"showing or causing strong feelings","examples":[{"en":"The reunion was an emotional occasion.","zh":"这次重聚令人激动。"},{"en":"She became emotional while thanking her teachers.","zh":"感谢老师时，她激动起来。"}]}],"emperor":[{"pos":"n.","meaning":"皇帝","definition":"the ruler of an empire","examples":[{"en":"The emperor ordered a new road across the province.","zh":"皇帝下令修建一条贯穿该省的新路。"},{"en":"The museum displays coins bearing the emperor's portrait.","zh":"博物馆陈列着印有皇帝肖像的钱币。"}]}],"emphasis":[{"pos":"n.","meaning":"强调;重视","definition":"special attention or importance given to something","examples":[{"en":"The course places emphasis on practical skills.","zh":"课程注重实践技能。"},{"en":"She repeated the warning for emphasis.","zh":"她重复警告以加强语气。"}]}],"emphasize":[{"pos":"v.","meaning":"强调；着重说明","definition":"to give special importance or attention to something","examples":[{"en":"The guide emphasized the importance of keeping together.","zh":"导游强调了大家保持同行的重要性。"},{"en":"The report emphasizes prevention rather than repair.","zh":"报告着重强调预防而非修复。"}]}],"empire":[{"pos":"n.","meaning":"帝国","definition":"a group of territories governed by one ruler or state","examples":[{"en":"The map shows the empire at its greatest extent.","zh":"地图展示了帝国疆域最广阔时的范围。"},{"en":"Trade routes connected distant parts of the empire.","zh":"贸易路线连接着帝国遥远的地区。"}]}],"empirical":[{"pos":"adj.","meaning":"以经验或观察为依据的;实证的","definition":"based on observation or experiment rather than theory alone","examples":[{"en":"The claim lacks empirical evidence.","zh":"这一主张缺乏实证证据。"},{"en":"We tested the model against empirical data.","zh":"我们用实测数据检验了模型。"}]}],"employ":[{"pos":"v.","meaning":"雇用","definition":"to pay someone to work","examples":[{"en":"The bakery employs six local residents.","zh":"面包店雇用了六位当地居民。"},{"en":"They employed an architect to redesign the house.","zh":"他们聘请建筑师重新设计房屋。"}]},{"pos":"v.","meaning":"使用；运用","definition":"to make use of a method or resource","examples":[{"en":"The study employed interviews and questionnaires.","zh":"研究使用了访谈和问卷。"},{"en":"She employed humour to ease the tension.","zh":"她用幽默缓和紧张气氛。"}]},{"pos":"n.","meaning":"雇用；受雇状态（常用于 in someone's employ）","definition":"the state of working for someone","examples":[{"en":"He remained in the family's employ for many years.","zh":"他受雇于这家人多年。"},{"en":"Several gardeners were in the estate's employ.","zh":"庄园雇用了几位园丁。"}]}],"employment":[{"pos":"n.","meaning":"就业","definition":"the state of having paid work","examples":[{"en":"Tourism creates employment in coastal towns.","zh":"旅游业为沿海城镇创造就业。"},{"en":"The programme helps young people find employment.","zh":"该项目帮助年轻人就业。"},{"en":"Stable employment can improve living standards.","zh":"稳定就业可以提高生活水平。"}]}],"emulate":[{"pos":"v.","meaning":"效仿;努力赶上","definition":"to try to equal or surpass someone by following their example","examples":[{"en":"Young players hope to emulate their heroes.","zh":"年轻球员希望效仿并赶上偶像。"},{"en":"Other cities tried to emulate the successful scheme.","zh":"其他城市试图效仿这个成功方案。"}]},{"pos":"v.","meaning":"仿真;模拟","definition":"to reproduce the behaviour of another system","examples":[{"en":"This program emulates an older computer.","zh":"该程序模拟了一台旧式计算机。"},{"en":"The simulator emulates real flight conditions.","zh":"模拟器仿真真实飞行条件。"}]}],"enable":[{"pos":"v.","meaning":"使能够；使成为可能","definition":"to make an action possible","examples":[{"en":"The grant enabled her to complete the research.","zh":"这笔资助使她能够完成研究。"},{"en":"Wide doors enable wheelchair users to enter easily.","zh":"宽门让轮椅使用者容易进入。"}]}],"enact":[{"pos":"v.","meaning":"制定；通过（法律）","definition":"to make a proposal into law","examples":[{"en":"The government enacted new safety legislation.","zh":"政府制定了新的安全法规。"},{"en":"The law was enacted after public consultation.","zh":"这部法律经过公众咨询后获得通过。"}]},{"pos":"v.","meaning":"扮演；表演","definition":"to perform a role or scene","examples":[{"en":"The students enacted a scene from the play.","zh":"学生们表演了剧中的一场戏。"},{"en":"The film enacts events from the writer's childhood.","zh":"影片再现了作家童年的事件。"}]}],"encapsulate":[{"pos":"v.","meaning":"概括;浓缩表达","definition":"to express the essential features briefly","examples":[{"en":"The title encapsulates the book's central idea.","zh":"书名概括了全书的核心思想。"},{"en":"One photograph encapsulated the joy of the occasion.","zh":"一张照片浓缩了那一刻的喜悦。"}]},{"pos":"v.","meaning":"装入胶囊;包封","definition":"to enclose something within a protective covering","examples":[{"en":"The drug is encapsulated for controlled release.","zh":"药物被包封以控制释放。"},{"en":"Resin encapsulates the delicate electronic components.","zh":"树脂包封着精密电子元件。"}]}],"encase":[{"pos":"v.","meaning":"包住；装入盒内","definition":"to enclose completely in a covering","examples":[{"en":"The specimen was encased in clear resin.","zh":"标本被包裹在透明树脂中。"},{"en":"A metal shell encases the motor.","zh":"一个金属外壳包住电动机。"}]}],"enclose":[{"pos":"v.","meaning":"围住；封闭","definition":"to surround something","examples":[{"en":"A wooden fence encloses the garden.","zh":"木栅栏围着花园。"},{"en":"The courtyard is enclosed by three buildings.","zh":"庭院被三栋建筑围住。"}]},{"pos":"v.","meaning":"附上；装入信封","definition":"to put something inside an envelope or package","examples":[{"en":"Please enclose a copy of your receipt.","zh":"请附上一份收据副本。"},{"en":"She enclosed the photographs with her letter.","zh":"她把照片随信装入信封。"}]}],"enclosure":[{"pos":"n.","meaning":"围场;围起来的区域","definition":"an area surrounded by a fence or wall","examples":[{"en":"The deer remained inside their enclosure.","zh":"鹿留在围场内。"},{"en":"Visitors entered the garden through a stone enclosure.","zh":"游客穿过石墙围起来的区域进入花园。"}]},{"pos":"n.","meaning":"信件附件","definition":"a document or item included with a letter","examples":[{"en":"Please read the enclosure before replying.","zh":"回复前请阅读随信附件。"},{"en":"The letter arrived without its promised enclosure.","zh":"信到了，却没有附上提及的附件。"}]}],"encode":[{"pos":"v.","meaning":"编码；把……转换为代码","definition":"to convert information into a coded form","examples":[{"en":"The software encodes audio for transmission.","zh":"软件将音频编码以便传输。"},{"en":"The message was encoded before it was sent.","zh":"信息在发送前经过了编码。"}]}],"encompass":[{"pos":"v.","meaning":"包含；涵盖；围绕","definition":"to include a wide range or surround something","examples":[{"en":"The course encompasses history, politics, and economics.","zh":"这门课程涵盖历史、政治和经济学。"},{"en":"The national park encompasses the lake and surrounding hills.","zh":"国家公园包含湖泊及周围山丘。"}]}],"encounter":[{"pos":"v.","meaning":"遇到;遭遇","definition":"to meet someone or experience something unexpectedly","examples":[{"en":"We encountered heavy traffic near the airport.","zh":"我们在机场附近遇到了严重堵车。"},{"en":"She encountered an old friend on the train.","zh":"她在火车上偶遇一位老朋友。"}]},{"pos":"n.","meaning":"相遇;遭遇","definition":"an unexpected meeting or experience","examples":[{"en":"The encounter changed his career plans.","zh":"这次相遇改变了他的职业规划。"},{"en":"Our first encounter with snow was unforgettable.","zh":"我们第一次遇见雪的经历令人难忘。"}]}],"encourage":[{"pos":"v.","meaning":"鼓励；支持","definition":"to give someone confidence or support","examples":[{"en":"Her teacher encouraged her to enter the competition.","zh":"老师鼓励她参加比赛。"},{"en":"Friends encouraged him during the difficult months.","zh":"朋友们在艰难的几个月里鼓励他。"}]},{"pos":"v.","meaning":"促进；激发","definition":"to make something more likely to happen","examples":[{"en":"Warm weather encourages plant growth.","zh":"温暖天气促进植物生长。"},{"en":"Lower fares may encourage greater use of buses.","zh":"降低票价可能促进更多人乘坐公交车。"}]}],"encroach":[{"pos":"v.","meaning":"侵占；侵犯；逐渐侵入","definition":"to gradually take over space or rights","examples":[{"en":"New buildings encroached on the wetland.","zh":"新建筑逐渐侵占了湿地。"},{"en":"The rule must not encroach upon personal privacy.","zh":"这项规则不得侵犯个人隐私。"}]}],"endanger":[{"pos":"v.","meaning":"危及;危害","definition":"to put someone or something at risk","examples":[{"en":"Speeding endangers other road users.","zh":"超速危及其他道路使用者。"},{"en":"Pollution endangers the river's wildlife.","zh":"污染危及河中的野生生物。"}]}],"endeavour":[{"pos":"n.","meaning":"努力；尝试","definition":"a serious attempt to achieve something","examples":[{"en":"The restoration was a remarkable collective endeavour.","zh":"修复工程是一次非凡的集体努力。"},{"en":"We wish her success in her future endeavours.","zh":"我们祝她未来的事业取得成功。"}]},{"pos":"v.","meaning":"努力；尽力","definition":"to try hard to do something","examples":[{"en":"We endeavour to answer all enquiries promptly.","zh":"我们尽力及时答复所有询问。"},{"en":"The team endeavoured to reduce unnecessary delays.","zh":"团队努力减少不必要的延误。"}]}],"endorse":[{"pos":"v.","meaning":"支持；赞同；认可","definition":"to publicly approve or support","examples":[{"en":"The committee endorsed the revised proposal.","zh":"委员会支持修改后的提议。"},{"en":"Several researchers endorsed the call for open data.","zh":"几位研究人员赞同公开数据的呼吁。"}]}],"endure":[{"pos":"v.","meaning":"忍受;承受","definition":"to suffer something difficult without giving up","examples":[{"en":"The hikers endured extreme cold.","zh":"徒步者忍受了严寒。"},{"en":"She endured years of unfair criticism.","zh":"她忍受了多年的不公批评。"}]},{"pos":"v.","meaning":"持续;持久","definition":"to continue existing over time","examples":[{"en":"Their friendship endured for decades.","zh":"他们的友谊持续了数十年。"},{"en":"These traditions endure despite rapid change.","zh":"尽管变化迅速，这些传统仍然延续。"}]}],"energetic":[{"pos":"adj.","meaning":"精力充沛的；积极有力的","definition":"having or showing plenty of energy","examples":[{"en":"Our energetic guide led us up the hill.","zh":"精力充沛的导游带我们登上山。"},{"en":"The charity launched an energetic fundraising campaign.","zh":"慈善机构积极开展筹款活动。"}]}],"enforce":[{"pos":"v.","meaning":"执行；强制实施；迫使服从","definition":"to make sure a rule is obeyed","examples":[{"en":"The police enforce traffic laws.","zh":"警察执行交通法规。"},{"en":"Schools need to enforce their safety rules consistently.","zh":"学校需要始终如一地执行安全规定。"},{"en":"A law has little effect if officials do not enforce it.","zh":"如果官员不执行，一项法律就很难奏效。"}]}],"enfranchise":[{"pos":"v.","meaning":"给予选举权;给予公民权","definition":"to grant voting or citizenship rights","examples":[{"en":"The reform enfranchised millions of workers.","zh":"改革赋予了数百万工人选举权。"},{"en":"Campaigners demanded that women be enfranchised.","zh":"活动人士要求赋予女性选举权。"}]},{"pos":"v.","meaning":"解放;使摆脱奴役","definition":"to release someone from slavery or servitude","examples":[{"en":"The decree enfranchised the enslaved workers.","zh":"法令解放了被奴役的工人。"},{"en":"The ruler promised to enfranchise the serfs.","zh":"统治者承诺解放农奴。"}]}],"engage":[{"pos":"v.","meaning":"吸引；引起兴趣","definition":"to attract and hold attention","examples":[{"en":"The opening story engaged the audience immediately.","zh":"开场故事立即吸引了观众。"},{"en":"Interactive exhibits engage younger visitors.","zh":"互动展品吸引年轻游客。"}]},{"pos":"v.","meaning":"使参与；忙于；占用","definition":"to involve someone in an activity or occupy their time","examples":[{"en":"The project engages students in practical research.","zh":"项目让学生参与实际研究。"},{"en":"Preparing the exhibition engaged her for several weeks.","zh":"筹备展览占用了她几周时间。"}]},{"pos":"v.","meaning":"雇用；聘请","definition":"to hire someone's services","examples":[{"en":"They engaged a translator for the meeting.","zh":"他们为会议聘请了翻译。"},{"en":"The owner engaged an engineer to inspect the roof.","zh":"业主请工程师检查屋顶。"}]},{"pos":"v.","meaning":"交战；与……作战","definition":"to enter combat with an opponent","examples":[{"en":"The ships engaged the enemy near the coast.","zh":"舰船在近海与敌方交战。"},{"en":"The account describes how the two armies engaged at dawn.","zh":"记载描述了两军如何在黎明交战。"}]},{"pos":"v.","meaning":"啮合；接合","definition":"to connect mechanical parts so they operate","examples":[{"en":"The gears engage when the lever is pushed.","zh":"推动操纵杆时齿轮就会啮合。"},{"en":"Release the pedal slowly to engage the clutch.","zh":"慢慢松开踏板使离合器接合。"}]}],"engrave":[{"pos":"v.","meaning":"雕刻；刻写","definition":"to cut a design or words into a hard surface","examples":[{"en":"The jeweller engraved her initials on the ring.","zh":"珠宝匠把她名字的首字母刻在戒指上。"},{"en":"The date is engraved above the doorway.","zh":"门口上方刻着日期。"}]},{"pos":"v.","meaning":"铭刻；深深印在心中","definition":"to fix something firmly in memory","examples":[{"en":"The farewell scene remained engraved in her memory.","zh":"告别的场景深深刻在她的记忆里。"},{"en":"His advice was engraved on my mind.","zh":"他的建议铭刻在我的心中。"}]}],"engross":[{"pos":"v.","meaning":"使全神贯注","definition":"to occupy someone's attention completely","examples":[{"en":"The puzzle engrossed her for hours.","zh":"这个谜题使她专注了数小时。"},{"en":"He was engrossed in a fascinating biography.","zh":"他全神贯注于一本引人入胜的传记。"}]}],"enhance":[{"pos":"v.","meaning":"提高；增强；增进","definition":"to improve the quality or value of something","examples":[{"en":"Trees enhance the appearance of the street.","zh":"树木改善了街道的面貌。"},{"en":"The new lighting enhances visibility at night.","zh":"新照明提高了夜间能见度。"}]}],"enhancer":[{"pos":"n.","meaning":"增强剂；增强装置","definition":"something that improves or strengthens an effect","examples":[{"en":"The food label lists a flavour enhancer.","zh":"食品标签列出了一种增味剂。"},{"en":"The software includes an image enhancer.","zh":"这款软件包含图像增强工具。"}]}],"enigma":[{"pos":"n.","meaning":"谜;难以理解的人或事","definition":"someone or something difficult to understand","examples":[{"en":"The cause of the disappearance remains an enigma.","zh":"失踪原因仍是个谜。"},{"en":"Her quiet neighbour was an enigma to everyone.","zh":"她那安静的邻居令所有人都难以捉摸。"}]}],"enjoyable":[{"pos":"adj.","meaning":"令人愉快的；有趣的","definition":"giving pleasure","examples":[{"en":"The walk was enjoyable despite the rain.","zh":"尽管下雨，这次散步仍然令人愉快。"},{"en":"She found the course challenging but enjoyable.","zh":"她觉得课程有挑战性，也很有趣。"}]}],"enlarge":[{"pos":"v.","meaning":"扩大；放大；扩充","definition":"to make something bigger","examples":[{"en":"The school plans to enlarge the library.","zh":"学校计划扩建图书馆。"},{"en":"Enlarge the photograph to examine the details.","zh":"放大照片以查看细节。"}]}],"enlighten":[{"pos":"v.","meaning":"启发;开导;说明","definition":"to give someone clearer knowledge or understanding","examples":[{"en":"Could you enlighten us about the procedure?","zh":"你能向我们说明一下程序吗？"},{"en":"The documentary enlightened viewers about local history.","zh":"纪录片帮助观众了解地方历史。"}]}],"enlist":[{"pos":"v.","meaning":"参军；征募入伍","definition":"to join or recruit people into the armed forces","examples":[{"en":"He enlisted in the navy after leaving school.","zh":"他毕业后加入了海军。"},{"en":"The army enlisted volunteers from nearby towns.","zh":"军队在附近城镇征募志愿者。"}]},{"pos":"v.","meaning":"争取；获得帮助或支持","definition":"to obtain someone's help or support","examples":[{"en":"We enlisted local artists to paint the mural.","zh":"我们请当地艺术家帮忙绘制壁画。"},{"en":"She enlisted her neighbours' support for the garden project.","zh":"她争取到邻居们对花园项目的支持。"}]}],"enormous":[{"pos":"adj.","meaning":"巨大的；庞大的","definition":"extremely large","examples":[{"en":"The project requires an enormous amount of data.","zh":"这个项目需要海量数据。"},{"en":"An enormous tree stood at the entrance.","zh":"入口处矗立着一棵巨树。"}]}],"enquire":[{"pos":"v.","meaning":"询问；咨询","definition":"to ask for information","examples":[{"en":"I am writing to enquire about evening courses.","zh":"我写信咨询晚间课程。"},{"en":"Please enquire at reception about available rooms.","zh":"请到前台咨询空房情况。"},{"en":"You can enquire by telephone or email.","zh":"你可以通过电话或邮件咨询。"}]},{"pos":"v.","meaning":"调查;查究","definition":"to investigate formally","examples":[{"en":"The committee enquired into the causes of the accident.","zh":"委员会调查了事故原因。"},{"en":"The inspector enquired into conditions at the factory.","zh":"检查员调查了工厂状况。"}]}],"enquiry":[{"pos":"n.","meaning":"询问；咨询","definition":"a request for information","examples":[{"en":"The receptionist answered my enquiry about opening hours.","zh":"接待员回答了我关于开放时间的询问。"},{"en":"Send course enquiries to the admissions office.","zh":"课程咨询请发给招生办公室。"}]},{"pos":"n.","meaning":"调查；探究","definition":"a systematic search for facts","examples":[{"en":"An independent enquiry examined the accident.","zh":"一项独立调查审查了这起事故。"},{"en":"Scientific enquiry begins with a clear question.","zh":"科学探究始于明确的问题。"}]}],"enrich":[{"pos":"v.","meaning":"使丰富；充实","definition":"to improve quality by adding something valuable","examples":[{"en":"Travel can enrich our understanding of other cultures.","zh":"旅行能丰富我们对其他文化的理解。"},{"en":"The archive was enriched by a donation of old letters.","zh":"一批旧信件的捐赠充实了档案馆馆藏。"}]},{"pos":"v.","meaning":"使富裕","definition":"to make someone wealthier","examples":[{"en":"The trade enriched several coastal towns.","zh":"贸易使几个沿海城镇富裕起来。"},{"en":"The investigation asked whether the contract had enriched officials.","zh":"调查询问这份合同是否让官员从中获利。"}]}],"enroll":[{"pos":"v.","meaning":"登记;注册;入学;招收","definition":"to join or register someone for a course or organization","examples":[{"en":"She enrolled in an evening language course.","zh":"她报名参加了一门夜间语言课。"},{"en":"The college enrolled two hundred new students.","zh":"学院招收了两百名新生。"}]}],"enrolment":[{"pos":"n.","meaning":"登记；注册；入学","definition":"the process of officially joining a course or organisation","examples":[{"en":"Enrolment for evening classes opens in September.","zh":"夜校课程九月开始报名。"},{"en":"Proof of identity is required at enrolment.","zh":"注册时需要身份证明。"}]},{"pos":"n.","meaning":"注册人数；在校人数","definition":"the number of people officially registered","examples":[{"en":"School enrolment rose sharply this year.","zh":"今年学校的在校人数大幅上升。"},{"en":"The college reported an enrolment of two thousand students.","zh":"学院报告在校生有两千人。"}]},{"pos":"n.","meaning":"登记簿；名册（较少用）","definition":"a list or record of people who have enrolled","examples":[{"en":"The archivist found her name in the old enrolment.","zh":"档案管理员在旧名册中找到了她的姓名。"},{"en":"The historical enrolment lists each student's birthplace.","zh":"历史登记簿列出了每位学生的出生地。"}]}],"enslave":[{"pos":"v.","meaning":"奴役；使受控制","definition":"to force into slavery or make completely dependent","examples":[{"en":"The museum tells the stories of people who were enslaved.","zh":"博物馆讲述了遭受奴役者的故事。"},{"en":"The debt had effectively enslaved the workers.","zh":"债务实际上把工人置于奴役之中。"}]}],"ensue":[{"pos":"v.","meaning":"接着发生;随之而来","definition":"to happen as a result of something","examples":[{"en":"A heated debate ensued after the announcement.","zh":"公告发布后爆发了激烈辩论。"},{"en":"The lights failed, and confusion ensued.","zh":"灯熄灭了，混乱随之而来。"}]}],"ensure":[{"pos":"v.","meaning":"确保；保证","definition":"to make certain that something happens","examples":[{"en":"Check the seal to ensure the container is closed.","zh":"检查密封处，确保容器已关好。"},{"en":"Regular maintenance ensures reliable operation.","zh":"定期维护确保设备可靠运行。"}]}],"entail":[{"pos":"v.","meaning":"需要；必然涉及；牵涉","definition":"to involve something as a necessary consequence","examples":[{"en":"The role entails frequent travel.","zh":"这个职位需要经常出差。"},{"en":"Changing the design would entail additional costs.","zh":"改变设计必然会产生额外费用。"}]}],"enterprise":[{"pos":"n.","meaning":"企业;公司","definition":"a business organization","examples":[{"en":"The family runs a small manufacturing enterprise.","zh":"这家人经营一家小型制造企业。"},{"en":"Several local enterprises sponsored the festival.","zh":"几家本地企业赞助了节庆活动。"}]},{"pos":"n.","meaning":"事业;艰巨项目","definition":"a difficult or important undertaking","examples":[{"en":"Restoring the castle was an ambitious enterprise.","zh":"修复城堡是一项雄心勃勃的事业。"},{"en":"The expedition was a joint scientific enterprise.","zh":"这次考察是一项联合科学项目。"}]},{"pos":"n.","meaning":"进取心;创业精神","definition":"initiative and willingness to take risks","examples":[{"en":"Her enterprise turned an idea into a business.","zh":"她的进取心把想法变成了企业。"},{"en":"The award recognizes creativity and enterprise.","zh":"这个奖项表彰创造力和进取精神。"}]}],"entertain":[{"pos":"v.","meaning":"使快乐；提供娱乐","definition":"to amuse or interest people","examples":[{"en":"The magician entertained the children with simple tricks.","zh":"魔术师用简单的戏法逗孩子们开心。"},{"en":"The radio programme entertains commuters every morning.","zh":"广播节目每天早晨为通勤者带来乐趣。"}]},{"pos":"v.","meaning":"招待；款待","definition":"to receive guests and provide food or hospitality","examples":[{"en":"They entertained friends at their new home.","zh":"他们在新家招待朋友。"},{"en":"The club entertained visiting players after the match.","zh":"俱乐部在赛后款待了客队球员。"}]}],"entertainment":[{"pos":"n.","meaning":"娱乐；消遣；娱乐节目","definition":"Activities or performances that people enjoy.","examples":[{"en":"The hotel offers live entertainment every Friday.","zh":"这家酒店每周五提供现场娱乐演出。"},{"en":"Reading is her favourite form of entertainment.","zh":"阅读是她最喜欢的消遣方式。"}]},{"pos":"n.","meaning":"招待；款待","definition":"The act of providing hospitality for guests.","examples":[{"en":"The company reduced its budget for client entertainment.","zh":"公司削减了招待客户的预算。"},{"en":"Meals and entertainment for visiting delegates were included in the fee.","zh":"费用包括来访代表的餐饮和接待。"}]}],"enthusiasm":[{"pos":"n.","meaning":"热情;积极性","definition":"strong excitement and interest","examples":[{"en":"The students showed enthusiasm for the project.","zh":"学生们对项目表现出热情。"},{"en":"Her enthusiasm encouraged the whole team.","zh":"她的热情鼓舞了整个团队。"}]},{"pos":"n.","meaning":"热衷的事物","definition":"an activity or subject that greatly interests someone","examples":[{"en":"Photography is his latest enthusiasm.","zh":"摄影是他最近热衷的事情。"},{"en":"She shares her father's enthusiasm for sailing.","zh":"她和父亲都热衷帆船运动。"}]}],"enthusiastic":[{"pos":"adj.","meaning":"热情的；热心的","definition":"showing strong interest and excitement","examples":[{"en":"The proposal received an enthusiastic response.","zh":"提议得到了热烈回应。"},{"en":"She is enthusiastic about learning to sail.","zh":"她对学习帆船运动很有热情。"}]}],"entice":[{"pos":"v.","meaning":"引诱；诱使；吸引","definition":"To persuade someone to do something by offering something appealing.","examples":[{"en":"The bakery enticed customers inside with the smell of fresh bread.","zh":"面包店用新鲜面包的香味吸引顾客进店。"},{"en":"A higher salary enticed her to accept the overseas job.","zh":"较高的薪水吸引她接受了那份海外工作。"}]}],"entire":[{"pos":"adj.","meaning":"全部的;整个的","definition":"complete and including every part","examples":[{"en":"We spent the entire afternoon reading.","zh":"我们整个下午都在阅读。"},{"en":"The fire destroyed the entire warehouse.","zh":"大火烧毁了整座仓库。"}]}],"entitle":[{"pos":"v.","meaning":"使有权；给予资格","definition":"to give someone a right to something","examples":[{"en":"This ticket entitles you to one free drink.","zh":"这张票让你可以免费获得一杯饮料。"},{"en":"Membership entitles students to use the workshop.","zh":"会员资格使学生有权使用工作室。"}]},{"pos":"v.","meaning":"给……题名；给……称号","definition":"to give a title or name","examples":[{"en":"She entitled the exhibition 'Changing Shores'.","zh":"她把展览题名为《变化的海岸》。"},{"en":"The final chapter is entitled 'A New Beginning'.","zh":"最后一章题为《新的开始》。"}]}],"entrepreneur":[{"pos":"n.","meaning":"企业家；创业者；商业项目经营者","definition":"A person who starts or manages a business and takes financial risks.","examples":[{"en":"The young entrepreneur opened a repair shop with her savings.","zh":"这位年轻创业者用积蓄开了一家修理店。"},{"en":"Local entrepreneurs are developing tours that support village businesses.","zh":"当地企业家正在开发能支持乡村商家的旅游项目。"}]}],"entrepreneurial":[{"pos":"adj.","meaning":"创业的;具有企业家精神的","definition":"relating to starting and developing businesses","examples":[{"en":"The course develops entrepreneurial skills.","zh":"这门课程培养创业技能。"},{"en":"Her entrepreneurial spirit inspired a new venture.","zh":"她的创业精神催生了一项新事业。"}]}],"entrust":[{"pos":"v.","meaning":"委托；托付","definition":"to give someone responsibility for something valuable","examples":[{"en":"She entrusted the documents to her assistant.","zh":"她把文件托付给助手。"},{"en":"The committee entrusted him with organising the event.","zh":"委员会委托他组织活动。"}]}],"entwine":[{"pos":"v.","meaning":"使缠绕；使交织","definition":"To twist things together or connect them closely.","examples":[{"en":"Climbing roses entwined the wooden arch.","zh":"攀缘玫瑰缠绕着木拱门。"},{"en":"Their family histories became entwined through several marriages.","zh":"几次联姻使他们的家族历史交织在一起。"}]}],"environment":[{"pos":"n.","meaning":"环境;周围状况","definition":"the surroundings and conditions in which something exists","examples":[{"en":"Children need a supportive learning environment.","zh":"儿童需要一个支持性的学习环境。"},{"en":"Plastic pollution harms the marine environment.","zh":"塑料污染损害海洋环境。"}]}],"envisage":[{"pos":"v.","meaning":"想象；设想；展望","definition":"to imagine a possible future situation","examples":[{"en":"They envisage a town centre with fewer cars.","zh":"他们设想一个车辆更少的市中心。"},{"en":"I had not envisaged working abroad.","zh":"我没有想过会在国外工作。"}]},{"pos":"v.","meaning":"面对；正视（较正式）","definition":"to face or contemplate a situation","examples":[{"en":"The planners had to envisage the difficulties ahead.","zh":"规划者必须正视前方的困难。"},{"en":"She calmly envisaged the possibility of failure.","zh":"她平静地面对失败的可能性。"}]}],"epidemic":[{"pos":"n.","meaning":"流行病；某种疾病的流行","definition":"An unusually large number of cases of a disease in a community.","examples":[{"en":"The epidemic forced several schools to close temporarily.","zh":"这场流行病迫使几所学校暂时关闭。"},{"en":"Researchers traced the epidemic to contaminated water.","zh":"研究人员查明这场疾病流行源于受污染的水。"}]},{"pos":"adj.","meaning":"流行性的；广泛蔓延的","definition":"Affecting many people within a short period.","examples":[{"en":"Doctors were concerned about the epidemic spread of the infection.","zh":"医生担心这种感染大规模传播。"},{"en":"The report described epidemic levels of loneliness among older residents.","zh":"报告指出老年居民的孤独现象已十分普遍。"}]}],"episodic":[{"pos":"adj.","meaning":"偶尔发生的;间歇性的","definition":"happening occasionally rather than continuously","examples":[{"en":"The patient reported episodic headaches.","zh":"患者说自己间歇性头痛。"},{"en":"Water shortages were episodic rather than constant.","zh":"缺水是间歇性的，并非持续不断。"}]},{"pos":"adj.","meaning":"由片段组成的;分集的","definition":"made up of loosely connected separate episodes","examples":[{"en":"The novel has an episodic structure.","zh":"小说采用了片段式结构。"},{"en":"The series tells an episodic story of village life.","zh":"剧集以分段故事讲述乡村生活。"}]}],"epitomise":[{"pos":"v.","meaning":"集中体现；是……的典型","definition":"to be a perfect example of something","examples":[{"en":"The small cafe epitomises the town's relaxed atmosphere.","zh":"这家小咖啡馆体现了小镇悠闲的氛围。"},{"en":"Her response epitomised the team's determination.","zh":"她的回应集中体现了团队的决心。"}]},{"pos":"v.","meaning":"概括；摘要","definition":"to express the main points briefly","examples":[{"en":"The final paragraph epitomises the argument.","zh":"最后一段概括了论点。"},{"en":"The short report epitomised years of research.","zh":"这份简短报告概括了多年的研究。"}]}],"equal":[{"pos":"adj.","meaning":"相等的；平等的","definition":"The same in amount, value, status, or rights.","examples":[{"en":"Cut the cake into six equal pieces.","zh":"把蛋糕切成六块等大的。"},{"en":"All applicants should have an equal chance of being interviewed.","zh":"所有申请者都应有平等的面试机会。"}]},{"pos":"v.","meaning":"等于；比得上","definition":"To have the same value or achieve the same standard.","examples":[{"en":"Three plus five equals eight.","zh":"三加五等于八。"},{"en":"No other runner could equal her best time.","zh":"没有其他跑步选手能达到她的最佳成绩。"}]}],"equality":[{"pos":"n.","meaning":"平等；同等地位","definition":"the state of having the same rights or opportunities","examples":[{"en":"The law aims to promote equality in the workplace.","zh":"这项法律旨在促进职场平等。"},{"en":"Equality of opportunity does not guarantee identical outcomes.","zh":"机会平等并不保证结果完全相同。"}]},{"pos":"n.","meaning":"相等；等同","definition":"the condition of two amounts or values being the same","examples":[{"en":"The equation expresses the equality of the two values.","zh":"这个等式表示两个数值相等。"},{"en":"The proof relies on equality between the corresponding lengths.","zh":"这个证明依赖于对应长度相等。"}]}],"equation":[{"pos":"n.","meaning":"方程式;等式","definition":"a mathematical statement that two expressions are equal","examples":[{"en":"Solve the equation for x.","zh":"解这个方程求出 x。"},{"en":"She wrote the equation on the board.","zh":"她把等式写在黑板上。"}]},{"pos":"n.","meaning":"等同;综合局势;平衡关系","definition":"the act of treating things as equal or a balance of factors","examples":[{"en":"His equation of wealth with happiness was simplistic.","zh":"他把财富等同于幸福的看法过于简单。"},{"en":"Cost is only one part of the equation.","zh":"成本只是整体考量中的一个因素。"}]}],"equator":[{"pos":"n.","meaning":"赤道","definition":"the imaginary line around Earth's middle","examples":[{"en":"The island lies just south of the equator.","zh":"该岛位于赤道稍南处。"},{"en":"The expedition crossed the equator by ship.","zh":"探险队乘船穿过赤道。"}]}],"equip":[{"pos":"v.","meaning":"装备；配备","definition":"To provide the tools or equipment needed for a purpose.","examples":[{"en":"The rescue boat was equipped with powerful searchlights.","zh":"救援船配备了强力探照灯。"},{"en":"The school plans to equip every classroom with a projector.","zh":"学校计划为每间教室配备投影仪。"}]},{"pos":"v.","meaning":"使具备能力；使有准备","definition":"To give someone the skills or knowledge needed for a task.","examples":[{"en":"The course equips graduates to manage small businesses.","zh":"这门课程使毕业生具备经营小企业的能力。"},{"en":"Reading different viewpoints equips students for informed debate.","zh":"阅读不同观点能让学生做好有理有据地辩论的准备。"}]}],"equipment":[{"pos":"n.","meaning":"设备;装备","definition":"tools and machines needed for an activity","examples":[{"en":"The laboratory needs new equipment.","zh":"实验室需要新设备。"},{"en":"Check your climbing equipment before leaving.","zh":"出发前检查登山装备。"}]}],"equity":[{"pos":"n.","meaning":"公平；公正","definition":"fairness in the way people are treated","examples":[{"en":"The policy aims to improve equity in education.","zh":"政策旨在促进教育公平。"},{"en":"The committee considered both efficiency and equity.","zh":"委员会同时考虑效率与公平。"}]}],"equivalent":[{"pos":"adj.","meaning":"等值的；相当的；等量的","definition":"Having the same value, meaning, or effect.","examples":[{"en":"Applicants need a diploma or an equivalent qualification.","zh":"申请者需要文凭或同等资格。"},{"en":"The two medicines contain equivalent amounts of the active ingredient.","zh":"这两种药物所含有效成分的量相同。"}]},{"pos":"n.","meaning":"等价物；对应物","definition":"Something with the same value or function as another thing.","examples":[{"en":"The phrase has no exact equivalent in Chinese.","zh":"这个短语在中文里没有完全对应的说法。"},{"en":"She paid the equivalent of fifty euros in local currency.","zh":"她用当地货币支付了相当于五十欧元的钱。"}]}],"era":[{"pos":"n.","meaning":"时代;纪元","definition":"a period of history with particular characteristics","examples":[{"en":"Steam power transformed transport in that era.","zh":"蒸汽动力改变了那个时代的交通。"},{"en":"The invention marked the beginning of a new era.","zh":"这项发明标志着新时代的开始。"}]}],"erode":[{"pos":"v.","meaning":"侵蚀；磨损","definition":"to wear away gradually through natural forces","examples":[{"en":"Waves eroded the base of the cliff.","zh":"海浪侵蚀了悬崖底部。"},{"en":"Heavy rain can erode exposed soil.","zh":"暴雨会侵蚀裸露的土壤。"}]},{"pos":"v.","meaning":"逐渐削弱；损害","definition":"to gradually reduce strength or confidence","examples":[{"en":"Repeated delays eroded public trust.","zh":"一再延误逐渐削弱了公众信任。"},{"en":"Inflation eroded the value of their savings.","zh":"通货膨胀逐渐侵蚀了他们储蓄的价值。"}]}],"erosion":[{"pos":"n.","meaning":"侵蚀；腐蚀；磨损","definition":"The gradual removal of soil, rock, or material.","examples":[{"en":"Tree roots help prevent soil erosion on steep slopes.","zh":"树根有助于防止陡坡上的水土流失。"},{"en":"The survey measured erosion along the exposed coastline.","zh":"调查测量了这段无遮蔽海岸的侵蚀程度。"}]},{"pos":"n.","meaning":"逐渐削弱；损耗","definition":"A gradual reduction in strength, value, or confidence.","examples":[{"en":"Repeated broken promises led to an erosion of trust.","zh":"一再违背承诺导致信任逐渐消失。"},{"en":"Inflation caused a steady erosion of their savings.","zh":"通货膨胀使他们的积蓄不断贬值。"}]}],"erroneous":[{"pos":"adj.","meaning":"错误的;不正确的","definition":"containing or based on an error","examples":[{"en":"The report contained an erroneous figure.","zh":"报告中有一个错误数字。"},{"en":"Their conclusion rested on erroneous assumptions.","zh":"他们的结论基于错误假设。"}]}],"eruption":[{"pos":"n.","meaning":"爆发；喷发","definition":"a sudden violent release or outbreak","examples":[{"en":"The volcanic eruption covered the village in ash.","zh":"火山喷发使村庄被火山灰覆盖。"},{"en":"The decision triggered an eruption of public anger.","zh":"这一决定引发了民愤爆发。"}]},{"pos":"n.","meaning":"皮疹；出疹","definition":"the appearance of a rash or spots on the skin","examples":[{"en":"The doctor examined the skin eruption on his arm.","zh":"医生检查了他手臂上的皮疹。"},{"en":"The report described a sudden eruption of red spots.","zh":"报告描述了红色疹点的突然出现。"}]}],"escalate":[{"pos":"v.","meaning":"逐步升级；加剧；不断增加","definition":"To become or make something greater or more serious.","examples":[{"en":"The argument escalated into a dispute between the departments.","zh":"这场争论升级为部门之间的纠纷。"},{"en":"Construction costs escalated after steel prices rose.","zh":"钢材涨价后，建筑成本不断攀升。"}]}],"escalator":[{"pos":"n.","meaning":"自动扶梯","definition":"moving stairs that carry people between levels","examples":[{"en":"Take the escalator to the second floor.","zh":"乘自动扶梯到二楼。"},{"en":"The broken escalator forced shoppers to use the stairs.","zh":"自动扶梯坏了，购物者只得走楼梯。"}]}],"essay":[{"pos":"n.","meaning":"短文；论文；评论文","definition":"a short piece of writing developing an idea","examples":[{"en":"Students must submit an essay on urban transport.","zh":"学生须提交一篇关于城市交通的短文。"},{"en":"Her essay explores the relationship between art and memory.","zh":"她的文章探讨艺术与记忆的关系。"}]}],"essence":[{"pos":"n.","meaning":"本质；精髓","definition":"The most important quality or central nature of something.","examples":[{"en":"The essay captures the essence of village life.","zh":"这篇文章抓住了乡村生活的精髓。"},{"en":"Trust is the essence of a successful partnership.","zh":"信任是成功合作关系的核心。"}]}],"essential":[{"pos":"adj.","meaning":"必不可少的","definition":"absolutely necessary","examples":[{"en":"Reliable information is essential for sound decisions.","zh":"可靠信息对明智决策必不可少。"},{"en":"Clean water is essential to public health.","zh":"清洁用水对公共健康至关重要。"},{"en":"It is essential to consider the long-term costs.","zh":"考虑长期成本是必要的。"}]},{"pos":"adj.","meaning":"本质的;基本的","definition":"relating to the fundamental nature of something","examples":[{"en":"The two methods share essential features.","zh":"两种方法具有共同基本特征。"},{"en":"The essay examines the essential nature of friendship.","zh":"文章考察友谊的本质。"}]},{"pos":"n.","meaning":"必需品;要素;要点","definition":"something necessary or fundamental","examples":[{"en":"Pack only the essentials for the hike.","zh":"徒步只携带必需品。"},{"en":"The first lesson explains the essentials of grammar.","zh":"第一课解释语法要点。"}]}],"establish":[{"pos":"v.","meaning":"建立；创立","definition":"to start an organisation or system","examples":[{"en":"They established a wildlife reserve near the river.","zh":"他们在河边建立了野生动物保护区。"},{"en":"The university established a new research centre.","zh":"大学成立了新的研究中心。"}]},{"pos":"v.","meaning":"确立；查明；证实","definition":"to make something accepted or prove it true","examples":[{"en":"The investigation established the cause of the fire.","zh":"调查查明了火灾原因。"},{"en":"She quickly established a reputation for reliability.","zh":"她很快树立了可靠的声誉。"}]},{"pos":"v.","meaning":"使安顿；使定居","definition":"to settle someone in a place or position","examples":[{"en":"The grant helped establish her in a small studio.","zh":"这笔资助帮助她在一个小工作室安顿下来。"},{"en":"The family established themselves in a coastal town.","zh":"这家人在一座海滨小镇定居。"}]}],"estate":[{"pos":"n.","meaning":"地产；庄园","definition":"A large area of land owned by one person or organisation.","examples":[{"en":"The family estate includes woodland and several farms.","zh":"这处家族庄园包括林地和几座农场。"},{"en":"Visitors can walk through the gardens of the old estate.","zh":"游客可以漫步于这座古老庄园的花园中。"}]},{"pos":"n.","meaning":"全部财产；遗产","definition":"All the money and property a person owns, especially after death.","examples":[{"en":"She left most of her estate to an educational charity.","zh":"她把大部分遗产留给了一家教育慈善机构。"},{"en":"The lawyer prepared an inventory of his estate.","zh":"律师列出了他的全部财产清单。"}]}],"esteem":[{"pos":"n.","meaning":"尊重;敬重","definition":"respect and admiration for someone","examples":[{"en":"Her colleagues hold her in high esteem.","zh":"同事们十分敬重她。"},{"en":"The award reflects the esteem of his peers.","zh":"这个奖项体现了同行对他的尊重。"}]},{"pos":"v.","meaning":"尊重;敬重","definition":"to respect and admire someone","examples":[{"en":"Students esteemed the patient teacher.","zh":"学生们敬重这位耐心的老师。"},{"en":"She is widely esteemed for her integrity.","zh":"她因正直而广受尊敬。"}]}],"estimate":[{"pos":"v.","meaning":"估计；估价；估量","definition":"to judge an amount or value approximately","examples":[{"en":"We estimate that repairs will take three days.","zh":"我们估计维修需要三天。"},{"en":"The surveyor estimated the value of the property.","zh":"测量师估算了房产价值。"}],"ipa":"/ˈestɪmeɪt/"},{"pos":"n.","meaning":"估计；估价","definition":"an approximate judgement of amount or value","examples":[{"en":"The builder provided an estimate for the repairs.","zh":"建筑工提供了维修估价。"},{"en":"Our first estimate of attendance was too low.","zh":"我们最初对出席人数的估计过低。"}],"ipa":"/ˈestɪmət/"}],"estrange":[{"pos":"v.","meaning":"使疏远；使关系破裂","definition":"To cause people to become distant or unfriendly.","examples":[{"en":"Years of disagreement had estranged him from his brother.","zh":"多年的分歧使他与哥哥疏远了。"},{"en":"The decision threatened to estrange the organisation from its supporters.","zh":"这个决定可能使该组织与支持者疏远。"}]}],"estuary":[{"pos":"n.","meaning":"河口;河口湾","definition":"the tidal area where a river meets the sea","examples":[{"en":"Migrating birds feed in the estuary.","zh":"候鸟在河口觅食。"},{"en":"Salt water moves upstream through the estuary.","zh":"咸水通过河口向上游流动。"}]}],"eternal":[{"pos":"adj.","meaning":"永恒的；永不结束的","definition":"lasting forever or seeming endless","examples":[{"en":"The poem explores the idea of eternal love.","zh":"诗歌探讨永恒爱情的理念。"},{"en":"The mountain appeared to stand in eternal silence.","zh":"那座山仿佛永远静默地矗立着。"}]}],"ethereal":[{"pos":"adj.","meaning":"轻盈的；精致飘逸的；空灵的","definition":"Delicate and light in a way that seems almost unreal.","examples":[{"en":"An ethereal melody floated through the quiet hall.","zh":"一段空灵的旋律飘荡在安静的大厅里。"},{"en":"The pale curtains gave the room an ethereal beauty.","zh":"浅色窗帘使房间呈现出一种轻盈缥缈的美。"}]},{"pos":"adj.","meaning":"天上的；超凡脱俗的；苍穹的","definition":"Relating to the heavens or to a world beyond ordinary physical life.","examples":[{"en":"The poem imagines an ethereal realm above the clouds.","zh":"这首诗想象了云层之上的天界。"},{"en":"The painting surrounds the angels with ethereal light.","zh":"这幅画用天国般的光芒环绕着天使。"}]}],"ethical":[{"pos":"adj.","meaning":"道德的;伦理的","definition":"relating to moral principles or behaving according to them","examples":[{"en":"The study raised serious ethical questions.","zh":"这项研究引发了严肃的伦理问题。"},{"en":"The company adopted ethical sourcing standards.","zh":"公司采用了符合道德的采购标准。"}]}],"evacuate":[{"pos":"v.","meaning":"疏散；撤离","definition":"to move people away from danger","examples":[{"en":"Residents were evacuated before the river overflowed.","zh":"河流漫堤前，居民已被疏散。"},{"en":"The alarm told everyone to evacuate the building.","zh":"警报通知所有人撤离大楼。"}]}],"evaluate":[{"pos":"v.","meaning":"评估；评价","definition":"to judge the quality or value of something","examples":[{"en":"We should evaluate the policy after one year.","zh":"我们应该在一年后评估这项政策。"},{"en":"Teachers evaluate students' progress throughout the course.","zh":"教师在整个课程期间评估学生进度。"},{"en":"It is important to evaluate both costs and benefits.","zh":"评估成本和收益都很重要。"}]}],"evaluation":[{"pos":"n.","meaning":"评估;评价;估价","definition":"a judgement about quality, value, or performance","examples":[{"en":"The course ends with a practical evaluation.","zh":"课程以实践评估结束。"},{"en":"An independent evaluation found the programme effective.","zh":"独立评估发现该项目有效。"}]}],"evaporate":[{"pos":"v.","meaning":"蒸发","definition":"to change from liquid into gas","examples":[{"en":"Water evaporates from the surface of the lake.","zh":"水从湖面蒸发。"},{"en":"The heat evaporated the remaining moisture.","zh":"热量使剩余水分蒸发了。"}]},{"pos":"v.","meaning":"消失；不复存在","definition":"to disappear gradually or suddenly","examples":[{"en":"Her doubts evaporated when she saw the results.","zh":"看到结果后，她的疑虑消失了。"},{"en":"Their savings seemed to evaporate during the move.","zh":"搬家期间，他们的积蓄似乎迅速耗尽了。"}]}],"event":[{"pos":"n.","meaning":"事件；活动","definition":"Something that happens or an organised occasion.","examples":[{"en":"The storm was the most disruptive event of the winter.","zh":"这场暴风雨是那个冬天破坏性最大的事件。"},{"en":"The library is hosting a community event on Saturday.","zh":"图书馆周六将举办社区活动。"}]},{"pos":"n.","meaning":"比赛项目","definition":"A particular contest in a sports competition.","examples":[{"en":"She entered three swimming events at the championship.","zh":"她报名参加了锦标赛中的三个游泳项目。"},{"en":"The final event of the afternoon was the relay.","zh":"下午最后一个比赛项目是接力赛。"}]}],"evidence":[{"pos":"n.","meaning":"证据；迹象","definition":"information that supports a belief or conclusion","examples":[{"en":"There is little evidence to support this claim.","zh":"几乎没有证据支持这一说法。"},{"en":"The researchers collected evidence from several schools.","zh":"研究人员从几所学校收集证据。"},{"en":"Policy decisions should be based on reliable evidence.","zh":"政策决策应以可靠证据为基础。"}]}],"evoke":[{"pos":"v.","meaning":"唤起；引起","definition":"to bring a feeling or memory to mind","examples":[{"en":"The smell of bread evoked childhood memories.","zh":"面包的香味唤起了童年回忆。"},{"en":"The painting evokes a sense of calm.","zh":"这幅画使人产生平静的感觉。"}]}],"evolution":[{"pos":"n.","meaning":"进化；演化","definition":"The process through which living things change over generations.","examples":[{"en":"The exhibit explains the evolution of whales from land mammals.","zh":"这场展览介绍鲸类从陆生哺乳动物演化而来的过程。"},{"en":"Fossils provide evidence about the evolution of early birds.","zh":"化石提供了有关早期鸟类进化的证据。"}]},{"pos":"n.","meaning":"逐步发展；演变","definition":"The gradual development of a system, idea, or object.","examples":[{"en":"The book traces the evolution of public transport in the city.","zh":"这本书追溯了这座城市公共交通的演变。"},{"en":"Digital cameras marked an important stage in the evolution of photography.","zh":"数码相机标志着摄影技术发展中的重要阶段。"}]}],"evolve":[{"pos":"v.","meaning":"演变;进化;逐渐形成","definition":"to develop or change gradually","examples":[{"en":"The design evolved through several prototypes.","zh":"设计经过几版原型逐步形成。"},{"en":"Species evolve over many generations.","zh":"物种经过许多世代演化。"}]}],"exacerbate":[{"pos":"v.","meaning":"加剧；使恶化","definition":"to make a problem worse","examples":[{"en":"A lack of sleep can exacerbate stress.","zh":"睡眠不足可能加剧压力。"},{"en":"Rising prices may exacerbate existing inequality.","zh":"物价上涨可能加剧现有不平等。"},{"en":"Building on flood plains can exacerbate flood damage.","zh":"在洪泛区建设可能加重洪灾损失。"}]}],"exact":[{"pos":"adj.","meaning":"精确的；准确的；确切的","definition":"Correct in every detail.","examples":[{"en":"Please give the exact time of your arrival.","zh":"请告知你到达的确切时间。"},{"en":"The model is an exact copy of the original bridge.","zh":"这个模型是原桥的精确复制品。"}]}],"exaggerate":[{"pos":"v.","meaning":"夸大;夸张","definition":"to describe something as greater than it really is","examples":[{"en":"Do not exaggerate the risks.","zh":"不要夸大风险。"},{"en":"He exaggerated his role in the rescue.","zh":"他夸大了自己在救援中的作用。"}]}],"examine":[{"pos":"v.","meaning":"检查；调查；研究","definition":"to look at something carefully to understand it","examples":[{"en":"The engineer examined the damaged wheel.","zh":"工程师检查了损坏的车轮。"},{"en":"The study examines the causes of migration.","zh":"研究考察移民的原因。"}]},{"pos":"v.","meaning":"考核；测验","definition":"to test someone's knowledge or skill","examples":[{"en":"Students will be examined on the whole course.","zh":"学生将接受整门课程的考核。"},{"en":"The panel examined candidates in spoken English.","zh":"评审组考核了应试者的英语口语。"}]}],"excavate":[{"pos":"v.","meaning":"挖掘；发掘；开凿","definition":"To remove earth in order to uncover something or make a hole.","examples":[{"en":"Archaeologists excavated a Roman courtyard beneath the street.","zh":"考古学家在街道下面发掘出一个罗马庭院。"},{"en":"Workers excavated a trench for the new water pipe.","zh":"工人挖了一条沟来铺设新水管。"}]}],"excavation":[{"pos":"n.","meaning":"挖掘;发掘","definition":"the act of digging out soil or buried objects","examples":[{"en":"Excavation revealed the foundations of a temple.","zh":"发掘揭示了一座寺庙的地基。"},{"en":"Construction stopped during the archaeological excavation.","zh":"考古发掘期间施工暂停了。"}]},{"pos":"n.","meaning":"挖掘处;坑;发掘遗址","definition":"a hole or site produced by digging","examples":[{"en":"A fence surrounds the deep excavation.","zh":"深坑四周围着篱笆。"},{"en":"Tourists viewed the Roman excavations from a walkway.","zh":"游客从步道上观看罗马遗址发掘区。"}]},{"pos":"n.","meaning":"出土物（较少用）","definition":"an object brought to light by digging","examples":[{"en":"The museum displayed recent excavations from the tomb.","zh":"博物馆展出了墓中近期出土的文物。"},{"en":"The excavations included pottery and bronze tools.","zh":"出土物包括陶器和青铜工具。"}]}],"exceed":[{"pos":"v.","meaning":"超过；胜过","definition":"to be greater than a limit or expectation","examples":[{"en":"Demand exceeded the available supply.","zh":"需求超过了现有供应。"},{"en":"Her results exceeded everyone's expectations.","zh":"她的成绩超出了所有人的预期。"}]}],"excellent":[{"pos":"adj.","meaning":"极好的；优秀的；杰出的","definition":"Extremely good in quality or performance.","examples":[{"en":"The restaurant serves excellent seafood at reasonable prices.","zh":"这家餐厅提供物美价廉的海鲜。"},{"en":"Her excellent research earned her a scholarship.","zh":"她出色的研究为她赢得了奖学金。"}]}],"except":[{"pos":"prep.","meaning":"除……之外","definition":"not including","examples":[{"en":"Everyone arrived except Daniel.","zh":"除丹尼尔外所有人都到了。"},{"en":"The shop opens daily except Sunday.","zh":"这家店除星期日外每天营业。"}]},{"pos":"v.","meaning":"把……除外","definition":"to leave someone or something out","examples":[{"en":"The rule excepts emergency vehicles.","zh":"这条规定将紧急救援车辆除外。"},{"en":"No department was excepted from the review.","zh":"没有部门被排除在审查之外。"}]}],"exceptional":[{"pos":"adj.","meaning":"异常的；罕见的；例外的","definition":"unusual and different from the normal case","examples":[{"en":"The delay was caused by exceptional weather conditions.","zh":"延误是异常天气造成的。"},{"en":"Only exceptional circumstances justify an extension.","zh":"只有特殊情况才有理由延期。"}]},{"pos":"adj.","meaning":"杰出的；出色的","definition":"unusually good","examples":[{"en":"The young pianist showed exceptional talent.","zh":"这位年轻钢琴家展现出非凡天赋。"},{"en":"The hotel is known for exceptional service.","zh":"这家酒店以出色的服务闻名。"}]}],"excess":[{"pos":"n.","meaning":"过量；超额；多余部分","definition":"An amount greater than is needed or allowed.","examples":[{"en":"Wipe away any excess glue before it dries.","zh":"在胶水干透之前擦去多余的部分。"},{"en":"An excess of salt can spoil the flavour of the soup.","zh":"盐放得过多会破坏汤的味道。"}]},{"pos":"adj.","meaning":"过量的；额外的；超额的","definition":"Greater than the necessary or permitted amount.","examples":[{"en":"Passengers must pay for excess baggage.","zh":"乘客必须为超重行李付费。"},{"en":"The tank has a valve to release excess pressure.","zh":"这个罐子有一个释放过高压力的阀门。"}]}],"excessive":[{"pos":"adj.","meaning":"过多的;过分的","definition":"greater than necessary or reasonable","examples":[{"en":"Excessive noise disturbed the neighbours.","zh":"过大的噪声打扰了邻居。"},{"en":"The proposal was rejected because of excessive costs.","zh":"提案因成本过高而被否决。"}]}],"exchange":[{"pos":"v.","meaning":"交换；调换","definition":"to give something and receive something else","examples":[{"en":"The students exchanged contact details.","zh":"学生们交换了联系方式。"},{"en":"Can I exchange this shirt for a larger size?","zh":"我能把这件衬衫换成大一号的吗？"}]},{"pos":"v.","meaning":"兑换","definition":"to change money into another currency","examples":[{"en":"We exchanged some cash before the trip.","zh":"我们在旅行前兑换了一些现金。"},{"en":"The bank exchanges dollars for euros.","zh":"这家银行把美元兑换成欧元。"}]},{"pos":"v.","meaning":"交流；互相说出","definition":"to share words or ideas with another person","examples":[{"en":"Researchers exchanged ideas after the lecture.","zh":"研究人员在讲座后交流了想法。"},{"en":"The drivers exchanged angry words.","zh":"司机们相互说了些气话。"}]},{"pos":"n.","meaning":"交换；交流","definition":"an act of giving and receiving things or ideas","examples":[{"en":"The school arranged an exchange of teaching materials.","zh":"学校安排了教学材料交换。"},{"en":"The meeting allowed a useful exchange of views.","zh":"会议使大家进行了有益的观点交流。"}]},{"pos":"n.","meaning":"兑换；兑换率","definition":"conversion between currencies or its rate","examples":[{"en":"The hotel offers currency exchange.","zh":"酒店提供货币兑换服务。"},{"en":"Changes in foreign exchange affected the import price.","zh":"外汇汇率变化影响了进口价格。"}]},{"pos":"n.","meaning":"交易所","definition":"a market where financial assets or goods are traded","examples":[{"en":"The company's shares are listed on the exchange.","zh":"公司的股票在交易所上市。"},{"en":"Traders gathered at the commodity exchange.","zh":"交易员聚集在商品交易所。"}]}],"excitement":[{"pos":"n.","meaning":"兴奋；激动","definition":"A feeling of strong enthusiasm or eager interest.","examples":[{"en":"The children could hardly contain their excitement before the trip.","zh":"旅行前孩子们几乎抑制不住兴奋。"},{"en":"Her voice shook with excitement when she announced the result.","zh":"她宣布结果时激动得声音发颤。"}]},{"pos":"n.","meaning":"令人兴奋的事；刺激的活动","definition":"Something that produces a strong feeling of interest or pleasure.","examples":[{"en":"After all the excitement of the wedding, they needed a quiet day.","zh":"经历婚礼的种种热闹之后，他们需要安静一天。"},{"en":"The town offers little excitement once the summer visitors leave.","zh":"夏季游客离开后，小镇就没多少令人兴奋的活动了。"}]}],"exclude":[{"pos":"v.","meaning":"排除;不包括;拒绝参加","definition":"to leave out or prevent from entering","examples":[{"en":"The price excludes delivery charges.","zh":"价格不含运费。"},{"en":"The club excluded him for breaking its rules.","zh":"俱乐部因他违反规定而将其除名。"}]}],"exclusive":[{"pos":"adj.","meaning":"奢华而高档的；仅供少数人使用的","definition":"expensive and limited to selected people","examples":[{"en":"They stayed at an exclusive seaside hotel.","zh":"他们住在一家高档海滨酒店。"},{"en":"The club has an exclusive membership.","zh":"这家俱乐部只接纳少数会员。"}]},{"pos":"adj.","meaning":"独有的；专有的","definition":"available only to one person or group","examples":[{"en":"The newspaper obtained an exclusive interview.","zh":"报社获得了独家采访。"},{"en":"Members have exclusive access to the archive.","zh":"会员享有档案的专属访问权。"}]},{"pos":"adj.","meaning":"排他的；不相容的","definition":"excluding others or unable to occur together","examples":[{"en":"The two explanations are not mutually exclusive.","zh":"这两种解释并不相互排斥。"},{"en":"An exclusive policy may isolate potential supporters.","zh":"排他的政策可能疏远潜在支持者。"}]},{"pos":"n.","meaning":"独家新闻","definition":"a news story published by only one organisation","examples":[{"en":"The reporter secured an exclusive about the discovery.","zh":"记者获得了关于这项发现的独家新闻。"},{"en":"The magazine promoted its interview as an exclusive.","zh":"杂志把这次采访作为独家报道宣传。"}]}],"exclusively":[{"pos":"adv.","meaning":"专门地；仅仅；独有地","definition":"Only for a particular person, group, or purpose.","examples":[{"en":"The study focused exclusively on urban households.","zh":"这项研究仅关注城市家庭。"},{"en":"This room is reserved exclusively for staff.","zh":"这个房间专供员工使用。"}]}],"excreta":[{"pos":"n.","meaning":"排泄物","definition":"waste substances discharged from the body","examples":[{"en":"Animal excreta can contaminate drinking water.","zh":"动物排泄物可能污染饮用水。"},{"en":"The samples contained traces of bird excreta.","zh":"样本中有鸟类排泄物的痕迹。"}]}],"excursion":[{"pos":"n.","meaning":"短途旅行；远足","definition":"a short journey for pleasure or study","examples":[{"en":"The class went on an excursion to the coast.","zh":"全班去海边进行了一次短途旅行。"},{"en":"We booked an afternoon excursion to the ruins.","zh":"我们预订了下午前往遗址的短途游。"}]},{"pos":"n.","meaning":"偏移；偏离平衡位置的运动（物理）","definition":"movement away from a mean or neutral position","examples":[{"en":"The sensor measured the pendulum's maximum excursion.","zh":"传感器测量了摆的最大偏移量。"},{"en":"The graph shows each excursion from the baseline.","zh":"图表显示了每次相对基线的偏移。"}]}],"excusable":[{"pos":"adj.","meaning":"可原谅的；可谅解的","definition":"Having a reason that makes a mistake or fault understandable.","examples":[{"en":"Her confusion was excusable because the instructions contradicted each other.","zh":"说明前后矛盾，所以她的困惑可以理解。"},{"en":"A short delay is excusable when the roads are flooded.","zh":"道路被淹时，短暂延误是可以谅解的。"}]}],"execute":[{"pos":"v.","meaning":"执行;实施","definition":"to carry out a plan, order, or action","examples":[{"en":"The team executed the plan successfully.","zh":"团队成功执行了计划。"},{"en":"The computer executes these instructions in sequence.","zh":"计算机按顺序执行这些指令。"}]},{"pos":"v.","meaning":"处死;处决","definition":"to kill someone as a legal punishment or deliberate act","examples":[{"en":"The regime executed several political prisoners.","zh":"该政权处决了数名政治犯。"},{"en":"The condemned man was executed at dawn.","zh":"被判死刑的男子在黎明时被处决。"}]}],"execution":[{"pos":"n.","meaning":"执行；实施","definition":"the process of carrying out a plan or action","examples":[{"en":"Careful execution turned the design into a success.","zh":"精细实施使设计取得了成功。"},{"en":"The contract specifies a deadline for execution.","zh":"合同规定了执行期限。"}]},{"pos":"n.","meaning":"处决","definition":"the official killing of a person as punishment","examples":[{"en":"The novel describes the prisoner's final days before execution.","zh":"小说描写了囚犯被处决前的最后几天。"},{"en":"The historian examined records of public executions.","zh":"历史学家研究了公开处决的记录。"}]}],"exemplify":[{"pos":"v.","meaning":"是……的典型；体现","definition":"To be a clear example of a quality or type.","examples":[{"en":"The restored station exemplifies the elegance of nineteenth-century architecture.","zh":"修复后的车站体现了十九世纪建筑的典雅。"},{"en":"Her careful planning exemplifies the professionalism of the whole team.","zh":"她周密的规划体现了整个团队的专业精神。"}]},{"pos":"v.","meaning":"举例说明；例证","definition":"To explain or demonstrate something with examples.","examples":[{"en":"The lecturer exemplified the principle with a simple experiment.","zh":"讲师用一个简单实验说明了这个原理。"},{"en":"The report exemplifies each category with a short case study.","zh":"报告用一个简短案例来说明每个类别。"}]}],"exhale":[{"pos":"v.","meaning":"呼出;散发","definition":"to breathe out or give off gas or vapour","examples":[{"en":"Exhale slowly through your mouth.","zh":"用嘴缓慢呼气。"},{"en":"The flowers exhaled a delicate perfume.","zh":"花朵散发着淡淡的香气。"}]}],"exhaust":[{"pos":"v.","meaning":"使筋疲力尽","definition":"to make someone extremely tired","examples":[{"en":"The long climb exhausted the hikers.","zh":"漫长的攀登使徒步者筋疲力尽。"},{"en":"Constant travel had exhausted her.","zh":"不断出差使她疲惫不堪。"}]},{"pos":"v.","meaning":"用尽；耗尽","definition":"to use all of a resource or possibility","examples":[{"en":"The project exhausted the available funds.","zh":"项目耗尽了现有资金。"},{"en":"We have exhausted every possible explanation.","zh":"我们已经考虑了所有可能的解释。"}]},{"pos":"n.","meaning":"废气；排气","definition":"gases released by an engine","examples":[{"en":"Vehicle exhaust contributes to street-level pollution.","zh":"车辆尾气加剧了街道污染。"},{"en":"Dark exhaust poured from the old engine.","zh":"黑色废气从旧发动机中冒出。"}]}],"exhaustible":[{"pos":"adj.","meaning":"可耗尽的；会枯竭的","definition":"Existing in a limited supply that can be used up.","examples":[{"en":"Coal is an exhaustible source of energy.","zh":"煤是一种会枯竭的能源。"},{"en":"The island depends on exhaustible groundwater reserves.","zh":"这座岛依赖可能耗尽的地下水储备。"}]}],"exhaustion":[{"pos":"n.","meaning":"精疲力竭","definition":"extreme physical or mental tiredness","examples":[{"en":"She collapsed from exhaustion after the race.","zh":"赛后她累得倒了下去。"},{"en":"Long shifts left the nurses near exhaustion.","zh":"长时间轮班使护士们几乎精疲力竭。"}]},{"pos":"n.","meaning":"耗尽;用尽","definition":"the complete use of a supply","examples":[{"en":"The mine closed after exhaustion of its reserves.","zh":"矿藏耗尽后矿场关闭了。"},{"en":"Exhaustion of the emergency fund forced spending cuts.","zh":"应急资金用尽迫使支出削减。"}]}],"exhaustive":[{"pos":"adj.","meaning":"详尽的；彻底的","definition":"covering every relevant detail","examples":[{"en":"The team conducted an exhaustive search of the archive.","zh":"团队对档案进行了全面搜查。"},{"en":"This is an illustrative list, not an exhaustive one.","zh":"这是一份示例清单，并未穷尽所有情况。"}]}],"exhibit":[{"pos":"n.","meaning":"展品；陈列品","definition":"An object displayed for public viewing.","examples":[{"en":"The museum's oldest exhibit is a carved stone tool.","zh":"博物馆里最古老的展品是一件雕制石器。"},{"en":"Visitors must not touch the fragile exhibits.","zh":"游客不得触摸这些易损的展品。"}]},{"pos":"v.","meaning":"展览；陈列","definition":"To display objects or work publicly.","examples":[{"en":"The gallery will exhibit her photographs next month.","zh":"画廊下个月将展出她的摄影作品。"},{"en":"Local designers exhibited their furniture at the trade fair.","zh":"当地设计师在贸易展上展示了他们的家具。"}]},{"pos":"v.","meaning":"显示；表现出","definition":"To show a particular quality, behaviour, or symptom.","examples":[{"en":"The animals exhibited signs of stress in the smaller enclosure.","zh":"这些动物在较小的围栏内表现出了压力迹象。"},{"en":"The new material exhibits remarkable resistance to heat.","zh":"这种新材料表现出很强的耐热性。"}]}],"exhibition":[{"pos":"n.","meaning":"展览;展览会;展示","definition":"a public display of objects or skills","examples":[{"en":"The gallery hosts an exhibition of local paintings.","zh":"美术馆举办当地画作展。"},{"en":"His performance was an impressive exhibition of skill.","zh":"他的表演是一次令人赞叹的技艺展示。"}]}],"exhilaration":[{"pos":"n.","meaning":"兴奋；振奋；欢欣","definition":"a feeling of great excitement and happiness","examples":[{"en":"Winning the race filled her with exhilaration.","zh":"赢得比赛使她兴奋不已。"},{"en":"We felt exhilaration as the balloon rose.","zh":"气球升空时，我们感到无比振奋。"}]}],"exile":[{"pos":"v.","meaning":"流放；使流亡","definition":"To force someone to leave their country or home.","examples":[{"en":"The ruler exiled several political opponents.","zh":"统治者流放了几名政敌。"},{"en":"The poet was exiled after criticising the government.","zh":"这位诗人因批评政府而被迫流亡。"}]},{"pos":"n.","meaning":"流亡；流放","definition":"The condition of being forced to live away from one's country.","examples":[{"en":"She spent ten years in exile before returning home.","zh":"她流亡十年后回到了故乡。"},{"en":"His letters describe the loneliness of exile.","zh":"他的书信描述了流亡生活的孤独。"}]},{"pos":"n.","meaning":"流亡者；被流放者","definition":"A person forced to live away from their home country.","examples":[{"en":"The city became a refuge for political exiles.","zh":"这座城市成了政治流亡者的避难所。"},{"en":"Several exiles established a newspaper in their new country.","zh":"几名流亡者在新的居住国创办了一份报纸。"}]}],"exist":[{"pos":"v.","meaning":"存在","definition":"to be real or present","examples":[{"en":"No reliable record of the event exists.","zh":"这件事没有可靠记录留存。"},{"en":"Similar customs exist in many countries.","zh":"许多国家都有类似习俗。"}]},{"pos":"v.","meaning":"生存;勉强维持生活","definition":"to remain alive, often with difficulty","examples":[{"en":"The family exists on a tiny income.","zh":"这家人靠微薄收入维生。"},{"en":"Desert plants exist with very little water.","zh":"沙漠植物靠极少的水生存。"}]}],"existence":[{"pos":"n.","meaning":"存在","definition":"the state of being real or present","examples":[{"en":"Scientists questioned the existence of the proposed particle.","zh":"科学家质疑所提出的粒子是否存在。"},{"en":"The charity came into existence in 1985.","zh":"该慈善机构成立于1985年。"}]},{"pos":"n.","meaning":"生活；生活方式","definition":"a particular way of living","examples":[{"en":"The family led a quiet existence.","zh":"这家人过着平静的生活。"},{"en":"He described his lonely existence on the island.","zh":"他描述了自己在岛上的孤独生活。"}]}],"exodus":[{"pos":"n.","meaning":"大批离去；集体迁离","definition":"The departure of a large number of people from a place.","examples":[{"en":"The factory closure triggered an exodus of young workers.","zh":"工厂关闭引发了年轻工人的大量外流。"},{"en":"Roads were crowded during the holiday exodus from the city.","zh":"假期人们大批离城时，道路十分拥挤。"}]}],"exorbitant":[{"pos":"adj.","meaning":"高得离谱的;过分的","definition":"unreasonably high, especially in price","examples":[{"en":"The hotel charged an exorbitant fee.","zh":"这家酒店收取了高得离谱的费用。"},{"en":"Exorbitant rents pushed workers out of the centre.","zh":"过高的租金迫使工人迁出市中心。"}]}],"exotic":[{"pos":"adj.","meaning":"异国的；外来的；奇异迷人的","definition":"unusual and interesting because of a foreign origin","examples":[{"en":"The greenhouse contains many exotic plants.","zh":"温室里有许多外来植物。"},{"en":"The market offered exotic spices and unfamiliar fruits.","zh":"市场上有异国香料和不熟悉的水果。"}]}],"expand":[{"pos":"v.","meaning":"扩大；扩展；膨胀；展开","definition":"to become or make something larger","examples":[{"en":"The council plans to expand the cycle network.","zh":"地方议会计划扩大自行车道网络。"},{"en":"Small firms often need loans to expand.","zh":"小企业通常需要贷款来扩大规模。"},{"en":"The hospital will expand its emergency department.","zh":"医院将扩建急诊科。"}]},{"pos":"v.","meaning":"详述；展开说明","definition":"To explain something in greater detail.","examples":[{"en":"Could you expand on your final point?","zh":"你能详细说明最后一点吗？"},{"en":"The author expands the argument in the next chapter.","zh":"作者在下一章展开论证。"}]}],"expansion":[{"pos":"n.","meaning":"扩大;扩张;膨胀","definition":"an increase in size, amount, or activity","examples":[{"en":"The company plans further expansion overseas.","zh":"公司计划进一步拓展海外业务。"},{"en":"Heating causes the expansion of most metals.","zh":"加热会使大多数金属膨胀。"}]}],"expectancy":[{"pos":"n.","meaning":"期待；期盼","definition":"a feeling that something exciting will happen","examples":[{"en":"The audience waited in silent expectancy.","zh":"观众静静地满怀期待地等着。"},{"en":"A sense of expectancy filled the room.","zh":"房间里充满了期待的气氛。"}]},{"pos":"n.","meaning":"预期数值（常指寿命）","definition":"an expected amount or length of time","examples":[{"en":"The study compared life expectancy across regions.","zh":"研究比较了各地区的预期寿命。"},{"en":"The material's service expectancy depends on maintenance.","zh":"材料的预期使用寿命取决于维护情况。"}]}],"expectation":[{"pos":"n.","meaning":"期待；预期；期望","definition":"A belief about what will happen or how well something should perform.","examples":[{"en":"The results exceeded our expectations.","zh":"结果超出了我们的预期。"},{"en":"There is an expectation that every member will contribute.","zh":"大家期待每位成员都能作出贡献。"}]},{"pos":"n.","meaning":"成功的前景；前程（常用复数）","definition":"Prospects of future achievement or advantage.","examples":[{"en":"She arrived in the capital with high expectations for her career.","zh":"她怀着对事业前景的厚望来到首都。"},{"en":"Despite modest beginnings, he had great expectations of future success.","zh":"尽管起点不高，他对未来的成功仍抱有远大期望。"}]}],"expedition":[{"pos":"n.","meaning":"远征;探险;考察;旅行","definition":"an organized journey for a particular purpose","examples":[{"en":"They planned an expedition to the Arctic.","zh":"他们计划去北极探险。"},{"en":"Our shopping expedition lasted all afternoon.","zh":"我们的购物之行持续了整个下午。"}]},{"pos":"n.","meaning":"探险队;考察队","definition":"a group making an organized journey","examples":[{"en":"The expedition returned with valuable samples.","zh":"考察队带着珍贵样本归来。"},{"en":"Bad weather trapped the expedition on the mountain.","zh":"恶劣天气把探险队困在了山上。"}]}],"expel":[{"pos":"v.","meaning":"开除；驱逐；排出","definition":"to force someone or something to leave","examples":[{"en":"The club expelled members who repeatedly broke its rules.","zh":"俱乐部开除了屡次违规的会员。"},{"en":"The pump expels water from the tank.","zh":"泵把水从水箱排出。"}]}],"expense":[{"pos":"n.","meaning":"费用；开支","definition":"money spent on something","examples":[{"en":"Rent is our biggest monthly expense.","zh":"房租是我们每月最大的开支。"},{"en":"The company paid the travel expense.","zh":"公司支付了差旅费用。"},{"en":"Repairing the roof was an unexpected expense.","zh":"修屋顶是一笔意外开支。"}]},{"pos":"n.","meaning":"代价；损失；牺牲","definition":"A disadvantage or loss incurred to gain something else.","examples":[{"en":"The shortcut saved time at the expense of safety.","zh":"这条捷径节省了时间，却以牺牲安全为代价。"},{"en":"He pursued success at the expense of his health.","zh":"他以健康为代价追求成功。"}]}],"expensive":[{"pos":"adj.","meaning":"昂贵的；价格高的","definition":"costing a large amount of money","examples":[{"en":"Rent is more expensive near the city centre.","zh":"市中心附近的房租更贵。"},{"en":"We chose a less expensive hotel to stay within our budget.","zh":"为了不超出预算，我们选了一家较便宜的酒店。"}]}],"experience":[{"pos":"n.","meaning":"工作或实践经验","definition":"knowledge gained by doing work or activities","examples":[{"en":"Previous retail experience is desirable.","zh":"有零售工作经验者优先。"},{"en":"He has ten years of experience in nursing.","zh":"他有十年护理经验。"},{"en":"Volunteering can help you gain useful experience.","zh":"做志愿者可以帮助你获得有用的经验。"}]},{"pos":"n.","meaning":"一次经历；体验","definition":"an event that someone has lived through","examples":[{"en":"Living abroad was a valuable experience.","zh":"在国外生活是一次宝贵的经历。"},{"en":"The trip was an unforgettable experience.","zh":"这次旅行是一次难忘的经历。"},{"en":"She described her first experience of travelling alone.","zh":"她描述了第一次独自旅行的经历。"}]}],"expire":[{"pos":"v.","meaning":"到期；失效；终止","definition":"to reach the end of a period of validity","examples":[{"en":"My passport expires next summer.","zh":"我的护照明年夏天到期。"},{"en":"The offer expires at midnight.","zh":"该优惠于午夜失效。"}]}],"expiry":[{"pos":"n.","meaning":"到期；期满；失效","definition":"The end of the period during which something is valid.","examples":[{"en":"Check the expiry date before using the pass.","zh":"使用通行证前请检查有效期。"},{"en":"We renewed the contract a month before its expiry.","zh":"我们在合同到期前一个月续签了合同。"}]}],"explode":[{"pos":"v.","meaning":"爆炸;使爆炸","definition":"to burst violently or cause a violent burst","examples":[{"en":"The gas cylinder exploded in the fire.","zh":"煤气罐在火中爆炸了。"},{"en":"Engineers exploded the old bridge safely.","zh":"工程师安全地爆破了旧桥。"}]},{"pos":"v.","meaning":"突然爆发;激增","definition":"to increase or begin suddenly and forcefully","examples":[{"en":"Demand for the product exploded overnight.","zh":"产品需求一夜之间激增。"},{"en":"The crowd exploded with joy.","zh":"人群突然爆发出欢呼。"}]}],"exploit":[{"pos":"v.","meaning":"剥削；不公平地利用","definition":"to use someone unfairly for one's benefit","examples":[{"en":"The investigation found that the employer exploited migrant workers.","zh":"调查发现雇主剥削移民工人。"},{"en":"Dishonest sellers exploit customers' lack of knowledge.","zh":"不诚实的卖家利用顾客知识不足牟利。"}],"ipa":"/ɪkˈsplɔɪt/"},{"pos":"v.","meaning":"开发；利用","definition":"to make practical use of a resource or opportunity","examples":[{"en":"The island hopes to exploit its wind resources.","zh":"该岛希望开发风力资源。"},{"en":"The team exploited a gap in the defence.","zh":"球队利用了防守中的漏洞。"}],"ipa":"/ɪkˈsplɔɪt/"},{"pos":"n.","meaning":"英勇事迹；功绩","definition":"a brave or remarkable achievement","examples":[{"en":"The book recounts the explorer's exploits.","zh":"这本书讲述了探险家的壮举。"},{"en":"His sporting exploits made him famous.","zh":"他在体育上的出色表现使他成名。"}],"ipa":"/ˈeksplɔɪt/"}],"exploitation":[{"pos":"n.","meaning":"开发；开采；利用","definition":"The use of resources to obtain a benefit.","examples":[{"en":"Commercial exploitation of the forest began in the last century.","zh":"这片森林的商业开发始于上个世纪。"},{"en":"The agreement limits the exploitation of offshore mineral deposits.","zh":"这份协议限制了近海矿藏的开采。"}]},{"pos":"n.","meaning":"剥削；榨取；不正当利用","definition":"The unfair use of people or situations for personal benefit.","examples":[{"en":"The investigation uncovered the exploitation of migrant workers.","zh":"调查揭露了对外来工人的剥削。"},{"en":"The campaign opposed the commercial exploitation of children's fears.","zh":"这场活动反对为了商业利益而利用儿童的恐惧。"}]}],"exploitative":[{"pos":"adj.","meaning":"剥削的;不公平利用的","definition":"taking unfair advantage of people or resources","examples":[{"en":"Workers protested against exploitative contracts.","zh":"工人抗议剥削性的合同。"},{"en":"The investigation exposed exploitative lending practices.","zh":"调查揭露了盘剥借款人的放贷做法。"}]},{"pos":"adj.","meaning":"开发利用的","definition":"concerned with using a resource for advantage","examples":[{"en":"The study compared protective and exploitative forest management.","zh":"研究比较了保护型与开发利用型森林管理。"},{"en":"An exploitative strategy focuses on known profitable opportunities.","zh":"利用型策略侧重已知的有利机会。"}]}],"exploratory":[{"pos":"adj.","meaning":"探索性的；勘探的","definition":"intended to discover or investigate something","examples":[{"en":"The companies held exploratory talks.","zh":"两家公司进行了探索性会谈。"},{"en":"Exploratory drilling revealed a layer of sandstone.","zh":"勘探钻探发现了一层砂岩。"}]}],"explore":[{"pos":"v.","meaning":"探险；探索；勘探","definition":"To travel through an unfamiliar place to discover what it is like.","examples":[{"en":"They spent the morning exploring caves along the coast.","zh":"他们整个上午都在探索海岸边的洞穴。"},{"en":"A research vessel is exploring the deep ocean.","zh":"一艘科考船正在探索深海。"}]},{"pos":"v.","meaning":"探究；仔细研究；考察","definition":"To examine an idea, question, or possibility carefully.","examples":[{"en":"The committee will explore alternatives to closing the school.","zh":"委员会将研究除关闭学校之外的其他方案。"},{"en":"Her essay explores the relationship between language and identity.","zh":"她的文章探讨语言与身份认同的关系。"}]}],"explorer":[{"pos":"n.","meaning":"探险者;勘探者","definition":"someone who travels to investigate unfamiliar places","examples":[{"en":"The explorer mapped an unknown valley.","zh":"探险者绘制了一个未知山谷的地图。"},{"en":"Early explorers relied on local guides.","zh":"早期探险者依靠当地向导。"}]}],"explosive":[{"pos":"n.","meaning":"爆炸物；炸药","definition":"a substance capable of exploding","examples":[{"en":"Only trained specialists handled the explosives.","zh":"只有受过训练的专家处理这些爆炸物。"},{"en":"The mine stores explosives in a secure facility.","zh":"矿山把炸药存放在安全设施内。"}]},{"pos":"adj.","meaning":"会爆炸的；爆炸性的","definition":"capable of exploding or expanding suddenly","examples":[{"en":"The container held an explosive mixture.","zh":"容器里装着易爆混合物。"},{"en":"The town experienced explosive population growth.","zh":"小镇经历了人口爆炸性增长。"}]},{"pos":"adj.","meaning":"易激怒的；引发强烈反应的","definition":"likely to cause sudden anger or conflict","examples":[{"en":"He struggled to control his explosive temper.","zh":"他努力控制自己暴躁的脾气。"},{"en":"The report raised an explosive political issue.","zh":"报告提出了一个极易引发争议的政治问题。"}]}],"export":[{"pos":"v.","meaning":"出口","definition":"To send goods or services to another country for sale.","examples":[{"en":"The cooperative exports coffee to several European countries.","zh":"这家合作社向几个欧洲国家出口咖啡。"},{"en":"Small firms often need help to export their products.","zh":"小企业通常需要帮助才能出口产品。"}],"ipa":"/ɪkˈspɔːt/"},{"pos":"v.","meaning":"输出；传播；导出","definition":"To send ideas, practices, or data to another place or system.","examples":[{"en":"The company exported its business model to neighbouring markets.","zh":"公司把自己的商业模式推广到邻近市场。"},{"en":"You can export the chart as an image.","zh":"你可以将图表导出为图片。"}],"ipa":"/ɪkˈspɔːt/"},{"pos":"n.","meaning":"出口；出口商品","definition":"The selling of goods abroad, or goods sold abroad.","examples":[{"en":"Tea remains one of the region's main exports.","zh":"茶叶仍是该地区的主要出口商品之一。"},{"en":"The new port is expected to increase agricultural exports.","zh":"新港口预计将增加农产品出口。"}],"ipa":"/ˈekspɔːt/"}],"expose":[{"pos":"v.","meaning":"暴露;使接触","definition":"to leave uncovered or subject to an influence","examples":[{"en":"The storm exposed the tree's roots.","zh":"暴风雨使树根露了出来。"},{"en":"The job exposed workers to harmful dust.","zh":"这份工作使工人接触有害粉尘。"}]},{"pos":"v.","meaning":"揭露;揭发","definition":"to reveal something hidden or dishonest","examples":[{"en":"The journalist exposed corruption in the agency.","zh":"记者揭露了机构内部的腐败。"},{"en":"The audit exposed serious accounting errors.","zh":"审计揭示了严重的会计错误。"}]}],"exposure":[{"pos":"n.","meaning":"暴露；接触","definition":"the state of being subjected to something","examples":[{"en":"Repeated exposure to moisture damaged the wood.","zh":"反复受潮损坏了木材。"},{"en":"The exchange gave students exposure to another culture.","zh":"交换活动使学生接触了另一种文化。"}]},{"pos":"n.","meaning":"揭露；公开","definition":"the act of making hidden facts known","examples":[{"en":"The exposure of the fraud led to resignations.","zh":"欺诈行为被揭露后，有人辞职。"},{"en":"She feared the exposure of private correspondence.","zh":"她担心私人信件被公开。"}]},{"pos":"n.","meaning":"曝光；曝光时间","definition":"the amount of light reaching a photographic sensor or film","examples":[{"en":"A longer exposure captured the stars clearly.","zh":"较长的曝光清楚地拍下了星星。"},{"en":"The photographer adjusted the exposure for the bright snow.","zh":"摄影师为明亮的雪景调整了曝光。"}]}],"express":[{"pos":"v.","meaning":"表达；表示","definition":"To communicate a thought, feeling, or idea.","examples":[{"en":"She found it difficult to express her disappointment politely.","zh":"她觉得很难礼貌地表达自己的失望。"},{"en":"The diagram expresses the relationship between the two variables.","zh":"这幅图表示两个变量之间的关系。"}]},{"pos":"adj.","meaning":"特快的；快速运送的","definition":"Providing a faster journey or delivery service.","examples":[{"en":"We took an express train to the airport.","zh":"我们乘坐特快列车前往机场。"},{"en":"Express delivery costs more than standard shipping.","zh":"快递比普通邮寄收费更高。"}]},{"pos":"adj.","meaning":"明确的；明白表示的","definition":"Clearly stated rather than merely implied.","examples":[{"en":"The photographs cannot be published without her express permission.","zh":"未经她明确许可，不得发表这些照片。"},{"en":"He travelled with the express purpose of finding his relatives.","zh":"他此行的明确目的是寻找亲属。"}]},{"pos":"n.","meaning":"快车；快递服务","definition":"A fast train or delivery service.","examples":[{"en":"The overnight express reaches the capital before breakfast.","zh":"这班夜间快车在早餐前抵达首都。"},{"en":"Send the documents by express if they must arrive tomorrow.","zh":"如果文件必须明天送达，就用快递寄送。"}]}],"extend":[{"pos":"v.","meaning":"延长;延伸;扩大","definition":"to make longer or larger or reach further","examples":[{"en":"We extended the deadline by one week.","zh":"我们把截止日期延长了一周。"},{"en":"The forest extends beyond the river.","zh":"森林延伸到河的另一边。"}]}],"extendable":[{"pos":"adj.","meaning":"可延伸的；可扩展的","definition":"able to be made longer or larger","examples":[{"en":"The dining table is extendable.","zh":"这张餐桌可以伸展。"},{"en":"The camera sits on an extendable pole.","zh":"摄像机装在一根伸缩杆上。"}]}],"extension":[{"pos":"n.","meaning":"延长；延伸；扩展","definition":"An increase in length, time, or scope.","examples":[{"en":"Students can request an extension of the deadline.","zh":"学生可以申请延长截止期限。"},{"en":"The extension of the rail network will connect more villages.","zh":"铁路网的扩展将连接更多村庄。"}]},{"pos":"n.","meaning":"扩建部分；延长部分","definition":"An added part that makes a building or object larger.","examples":[{"en":"The family built an extension behind the kitchen.","zh":"这家人在厨房后面加盖了一部分房屋。"},{"en":"An extension to the handle makes the tool easier to reach.","zh":"手柄上的延长部分使工具更容易够到目标。"}]},{"pos":"n.","meaning":"电话分机；分机号码","definition":"An internal telephone line or its number.","examples":[{"en":"Ask the receptionist for extension 204.","zh":"请让接待员转分机二〇四。"},{"en":"Every office has its own telephone extension.","zh":"每间办公室都有自己的电话分机。"}]}],"extensive":[{"pos":"adj.","meaning":"广大的;广泛的;大量的","definition":"covering a large area or range","examples":[{"en":"The library holds an extensive collection of maps.","zh":"图书馆收藏了大量地图。"},{"en":"The storm caused extensive damage.","zh":"风暴造成了广泛损失。"}]}],"extent":[{"pos":"n.","meaning":"范围；面积；长度","definition":"the size or reach of something","examples":[{"en":"The survey mapped the extent of the forest.","zh":"调查绘制了森林的范围。"},{"en":"We could not see the full extent of the cave.","zh":"我们看不到洞穴的全部范围。"}]},{"pos":"n.","meaning":"程度","definition":"the degree to which something occurs","examples":[{"en":"To what extent did costs influence your choice?","zh":"成本在多大程度上影响了你的选择？"},{"en":"I agree with her to some extent.","zh":"我在一定程度上同意她的观点。"}]}],"exterior":[{"pos":"adj.","meaning":"外部的；外表的","definition":"On or relating to the outside of something.","examples":[{"en":"The exterior walls need a fresh coat of paint.","zh":"外墙需要重新粉刷。"},{"en":"Only the exterior lighting stays on after midnight.","zh":"午夜过后只有室外照明还亮着。"}]},{"pos":"n.","meaning":"外部；外表","definition":"The outside surface or outward appearance of something.","examples":[{"en":"The building's plain exterior hides a beautiful courtyard.","zh":"大楼朴素的外表下藏着一座美丽的庭院。"},{"en":"Beneath her confident exterior, she felt nervous.","zh":"在自信的外表下，她其实感到紧张。"}]}],"external":[{"pos":"adj.","meaning":"外部的;表面的;外界的","definition":"outside something or coming from outside","examples":[{"en":"The external walls need repainting.","zh":"外墙需要重新粉刷。"},{"en":"The project received external funding.","zh":"项目获得了外部资助。"}]}],"externally":[{"pos":"adv.","meaning":"从外部；在外表上","definition":"on the outside or from an outside source","examples":[{"en":"Externally, the building appears unchanged.","zh":"从外表看，这栋建筑似乎没有变化。"},{"en":"The research was funded externally.","zh":"这项研究由外部提供资金。"}]}],"extinct":[{"pos":"adj.","meaning":"灭绝的；不复存在的；废弃的","definition":"No longer existing or in use.","examples":[{"en":"Several species became extinct after their habitat disappeared.","zh":"栖息地消失后，几个物种灭绝了。"},{"en":"The researchers are reconstructing an extinct language from inscriptions.","zh":"研究人员正通过铭文重建一种已经消亡的语言。"}]}],"extinction":[{"pos":"n.","meaning":"灭绝;绝种","definition":"the disappearance of every member of a species","examples":[{"en":"Habitat loss can lead to extinction.","zh":"栖息地丧失可能导致物种灭绝。"},{"en":"The bird was saved from extinction.","zh":"这种鸟获救，免于灭绝。"}]},{"pos":"n.","meaning":"熄灭;消灭","definition":"the process of putting an end to something","examples":[{"en":"Firefighters confirmed the extinction of the last flames.","zh":"消防员确认最后的火焰已经熄灭。"},{"en":"The treaty led to the extinction of the old claim.","zh":"条约使旧有权利主张归于消灭。"}]}],"extinguish":[{"pos":"v.","meaning":"熄灭；扑灭","definition":"to put out a fire or light","examples":[{"en":"Firefighters extinguished the blaze before dawn.","zh":"消防员在黎明前扑灭了大火。"},{"en":"She extinguished the candle before leaving.","zh":"她离开前熄灭了蜡烛。"}]},{"pos":"v.","meaning":"使破灭；消除","definition":"to bring a feeling or possibility to an end","examples":[{"en":"The defeat did not extinguish their ambition.","zh":"失败没有使他们的雄心破灭。"},{"en":"No criticism could extinguish her curiosity.","zh":"任何批评都无法消除她的好奇心。"}]}],"extinguisher":[{"pos":"n.","meaning":"灭火器；灭火装置","definition":"A device used to put out a fire.","examples":[{"en":"A fire extinguisher hangs beside the kitchen door.","zh":"厨房门旁挂着一个灭火器。"},{"en":"The instructor demonstrated how to operate the extinguisher.","zh":"教员演示了如何操作灭火器。"}]}],"extol":[{"pos":"v.","meaning":"赞美;颂扬","definition":"to praise enthusiastically","examples":[{"en":"The guide extolled the beauty of the coast.","zh":"导游盛赞海岸的美丽。"},{"en":"Reviewers extolled the novel's elegant prose.","zh":"评论者赞美小说优雅的文笔。"}]}],"extra":[{"pos":"adj.","meaning":"额外的；附加的","definition":"added to the usual amount","examples":[{"en":"We need an extra chair.","zh":"我们需要一把额外的椅子。"},{"en":"Allow extra time for the journey.","zh":"为旅程多留些时间。"}]},{"pos":"adv.","meaning":"额外地；另外","definition":"in addition to the normal amount","examples":[{"en":"Delivery costs extra.","zh":"送货需要另外付费。"},{"en":"We paid extra for a larger room.","zh":"我们额外付费换了更大的房间。"}]},{"pos":"adv.","meaning":"特别地；格外地","definition":"more than usual","examples":[{"en":"Be extra careful on the wet steps.","zh":"在湿台阶上要格外小心。"},{"en":"She woke up extra early for the trip.","zh":"她为旅行起得特别早。"}]}],"extract":[{"pos":"n.","meaning":"摘录；选段","definition":"A short passage taken from a longer text.","examples":[{"en":"We read an extract from the travel diary.","zh":"我们读了这本旅行日记的一段摘录。"},{"en":"The exam includes an extract from a nineteenth-century novel.","zh":"试卷包含一段十九世纪小说的选文。"}],"ipa":"/ˈekstrækt/"},{"pos":"n.","meaning":"提取物；精；汁","definition":"A concentrated substance obtained from another material.","examples":[{"en":"Add a teaspoon of vanilla extract to the mixture.","zh":"在混合物中加入一茶匙香草精。"},{"en":"The cream contains a plant extract.","zh":"这款面霜含有一种植物提取物。"}],"ipa":"/ˈekstrækt/"},{"pos":"v.","meaning":"取出；提取；提炼","definition":"To remove or obtain something from a source.","examples":[{"en":"The dentist extracted the damaged tooth.","zh":"牙医拔掉了那颗损坏的牙齿。"},{"en":"The software can extract dates from scanned documents.","zh":"这个软件可以从扫描文件中提取日期。"}],"ipa":"/ɪkˈstrækt/"}],"extracurricular":[{"pos":"adj.","meaning":"课外的","definition":"outside the usual school curriculum","examples":[{"en":"She enjoys several extracurricular activities.","zh":"她喜欢参加几项课外活动。"},{"en":"The school offers extracurricular music lessons.","zh":"学校提供课外音乐课。"}]}],"extraordinary":[{"pos":"adj.","meaning":"非凡的；不同寻常的","definition":"very unusual or remarkable","examples":[{"en":"She has an extraordinary memory for faces.","zh":"她记人的面孔有非凡的能力。"},{"en":"The expedition made an extraordinary discovery.","zh":"探险队有了一项不同寻常的发现。"}]}],"extravagance":[{"pos":"n.","meaning":"奢侈；挥霍；奢侈品","definition":"Spending or using more than is necessary, or an unnecessary luxury.","examples":[{"en":"They criticised the extravagance of the official banquet.","zh":"他们批评官方宴会的铺张浪费。"},{"en":"Buying fresh flowers every week is her one extravagance.","zh":"每周买鲜花是她唯一的奢侈消费。"}]},{"pos":"n.","meaning":"过分；夸张的言行","definition":"Speech or behaviour that goes beyond reasonable limits.","examples":[{"en":"The extravagance of his promises made voters suspicious.","zh":"他过分的承诺让选民产生了怀疑。"},{"en":"The critic objected to the emotional extravagance of the final scene.","zh":"评论家不赞同最后一幕过度煽情的表现。"}]}],"extravagant":[{"pos":"adj.","meaning":"奢侈的;铺张的","definition":"spending more money than necessary","examples":[{"en":"They planned an extravagant wedding.","zh":"他们策划了一场奢华的婚礼。"},{"en":"His extravagant lifestyle exhausted his savings.","zh":"他挥霍的生活方式耗尽了积蓄。"}]},{"pos":"adj.","meaning":"过分的;夸张的;无节制的","definition":"going beyond reasonable limits","examples":[{"en":"The advertisement made extravagant promises.","zh":"广告作出了夸张的承诺。"},{"en":"She dismissed his extravagant claims of success.","zh":"她不理会他对成功的过分吹嘘。"}]}],"extreme":[{"pos":"adj.","meaning":"极度的；极端的","definition":"very great in degree or far from usual","examples":[{"en":"The plants can survive extreme heat.","zh":"这些植物能在酷热中生存。"},{"en":"The proposal met with extreme opposition.","zh":"提案遭到了极强烈的反对。"}]},{"pos":"adj.","meaning":"最远的；末端的","definition":"farthest from a centre or nearest an outer end","examples":[{"en":"The village lies at the extreme north of the island.","zh":"村庄位于岛的最北端。"},{"en":"A small label sits at the extreme edge of the page.","zh":"一个小标签位于页面的最边缘。"}]},{"pos":"n.","meaning":"极端；极限","definition":"one of two opposite limits or excessive conditions","examples":[{"en":"The region experiences extremes of temperature.","zh":"该地区经历极端温度。"},{"en":"Avoid going to extremes when changing your routine.","zh":"改变日常习惯时避免走极端。"}]}],"extremely":[{"pos":"adv.","meaning":"极其；非常","definition":"To a very great degree.","examples":[{"en":"The path becomes extremely slippery after rain.","zh":"这条小路雨后会变得非常滑。"},{"en":"She was extremely patient with the new students.","zh":"她对新生极有耐心。"}]}],"extrovert":[{"pos":"n.","meaning":"外向的人;爱交际的人","definition":"an outgoing person who enjoys social contact","examples":[{"en":"An extrovert, she quickly made new friends.","zh":"她性格外向，很快交到了新朋友。"},{"en":"The quiet office needed an extrovert to start conversations.","zh":"安静的办公室需要一个外向的人来开启话题。"}]}],"extrusion":[{"pos":"n.","meaning":"挤出；挤压成形","definition":"the process of forcing material through an opening","examples":[{"en":"The factory shapes plastic pipes by extrusion.","zh":"工厂通过挤出工艺制造塑料管。"},{"en":"Extrusion produces a continuous strip of metal.","zh":"挤压成形产生连续的金属条。"}]}],"exuberant":[{"pos":"adj.","meaning":"热情洋溢的；精力充沛的","definition":"Full of energy, joy, and enthusiasm.","examples":[{"en":"The exuberant crowd cheered when the band appeared.","zh":"乐队出现时，热情洋溢的人群欢呼起来。"},{"en":"His exuberant personality made the workshop lively.","zh":"他活力十足的个性使研讨会充满生气。"}]},{"pos":"adj.","meaning":"繁茂的；丰富旺盛的","definition":"Growing or appearing in great abundance.","examples":[{"en":"Exuberant vegetation covered the abandoned walls.","zh":"繁茂的植物覆盖了废弃的墙壁。"},{"en":"The garden's exuberant growth soon concealed the narrow path.","zh":"花园中旺盛的植物很快掩盖了狭窄的小路。"}]},{"pos":"adj.","meaning":"过分华丽的；繁复的；极度的","definition":"Lavish or unusually elaborate in expression or decoration.","examples":[{"en":"The palace ceiling is covered in exuberant ornament.","zh":"宫殿天花板布满了繁复华丽的装饰。"},{"en":"The review praised the novel's exuberant imagination.","zh":"书评赞扬了小说极为丰富的想象力。"}]}],"eyesight":[{"pos":"n.","meaning":"视力","definition":"the ability to see","examples":[{"en":"His eyesight has improved with new glasses.","zh":"戴上新眼镜后他的视力改善了。"},{"en":"Good eyesight is essential for this precision work.","zh":"这项精细工作要求良好的视力。"}]}],"fabrication":[{"pos":"n.","meaning":"捏造；伪造","definition":"inventing false information","examples":[{"en":"The witness admitted that the story was a fabrication.","zh":"证人承认这个故事是编造的。"},{"en":"The inquiry found evidence of data fabrication.","zh":"调查发现了伪造数据的证据。"}]},{"pos":"n.","meaning":"制造；构建","definition":"the process of making or assembling something","examples":[{"en":"The workshop specialises in metal fabrication.","zh":"这家车间专门从事金属制造。"},{"en":"Fabrication of the bridge sections took six months.","zh":"桥梁各段的制造历时六个月。"}]}],"fabulous":[{"pos":"adj.","meaning":"极好的；绝妙的","definition":"Exceptionally good or enjoyable.","examples":[{"en":"We had a fabulous meal overlooking the harbour.","zh":"我们一边俯瞰港口，一边享用了一顿美味佳肴。"},{"en":"The actor gave a fabulous performance in the final scene.","zh":"演员在最后一幕中的表演精彩极了。"}]},{"pos":"adj.","meaning":"巨额的；惊人的","definition":"Extremely large or impressive in amount.","examples":[{"en":"The painting sold for a fabulous sum.","zh":"这幅画以惊人的高价售出。"},{"en":"Stories circulated about the merchant's fabulous wealth.","zh":"关于这位商人惊人财富的故事四处流传。"}]},{"pos":"adj.","meaning":"传说中的；神话般的","definition":"Existing in myths or imaginative stories.","examples":[{"en":"The tapestry depicts fabulous creatures with golden wings.","zh":"挂毯描绘了长着金色翅膀的神话生物。"},{"en":"The traveller told stories of fabulous cities beneath the sea.","zh":"旅行者讲述了海底传说之城的故事。"}]}],"facade":[{"pos":"n.","meaning":"建筑正面","definition":"the front of a building","examples":[{"en":"Workers restored the theatre's ornate facade.","zh":"工人修复了剧院华丽的正面。"},{"en":"Ivy covered the stone facade.","zh":"常春藤覆盖了石砌外墙。"}]},{"pos":"n.","meaning":"假象;虚假的外表","definition":"an outward appearance hiding the truth","examples":[{"en":"Her cheerful facade concealed deep anxiety.","zh":"她愉快的外表掩盖着深深的焦虑。"},{"en":"The company maintained a facade of success.","zh":"公司维持着成功的假象。"}]}],"facial":[{"pos":"adj.","meaning":"面部的；面部用的","definition":"relating to the face","examples":[{"en":"Facial expressions can communicate emotion without words.","zh":"面部表情可以不用语言表达情绪。"},{"en":"She applied a gentle facial cleanser.","zh":"她用了温和的面部洁肤产品。"}]}],"facilitate":[{"pos":"v.","meaning":"促进；使便利；使容易","definition":"To make a process easier or help it happen.","examples":[{"en":"Clear signs facilitate movement through the station.","zh":"清晰的标识方便乘客在车站通行。"},{"en":"The mediator helped facilitate a discussion between the neighbours.","zh":"调解员帮助促成了邻居之间的讨论。"}]}],"facility":[{"pos":"n.","meaning":"设施；场所","definition":"a place or piece of equipment provided for a purpose","examples":[{"en":"The sports facility is open to the public.","zh":"这处运动设施向公众开放。"},{"en":"A new recycling facility will open next year.","zh":"一处新的回收设施将于明年启用。"},{"en":"The town needs a better healthcare facility.","zh":"这个城镇需要更好的医疗设施。"}]}],"facsimile":[{"pos":"n.","meaning":"复制品；摹本","definition":"an exact reproduction of a document or image","examples":[{"en":"The library displayed a facsimile of the manuscript.","zh":"图书馆展出了一份手稿摹本。"},{"en":"Students examined a facsimile of the ancient map.","zh":"学生们查看了古地图的复制品。"}]}],"fact sheet":[{"pos":"n.","meaning":"资料页；情况说明书","definition":"A short document presenting key facts about a subject.","examples":[{"en":"The nurse gave us a fact sheet about the vaccination programme.","zh":"护士给了我们一份有关疫苗接种计划的资料页。"},{"en":"Each apartment comes with a fact sheet listing its size and facilities.","zh":"每套公寓都配有一张列明面积和设施的情况说明书。"}]}],"factor":[{"pos":"n.","meaning":"因素","definition":"something that influences a result","examples":[{"en":"Cost is a major factor in choosing accommodation.","zh":"费用是选择住处的重要因素。"},{"en":"Age is not the only factor affecting health.","zh":"年龄不是影响健康的唯一因素。"},{"en":"The study examined each factor separately.","zh":"研究分别考察了每个因素。"}]}],"factual":[{"pos":"adj.","meaning":"事实的；符合事实的","definition":"based on facts rather than invention","examples":[{"en":"The editor checked the article for factual errors.","zh":"编辑检查文章中的事实错误。"},{"en":"Please give a factual account of the event.","zh":"请如实叙述事件经过。"}]}],"faculty":[{"pos":"n.","meaning":"能力；官能；才能","definition":"A natural mental or physical ability.","examples":[{"en":"She retained her faculty of speech after the operation.","zh":"手术后她保留了说话能力。"},{"en":"The exercise develops children's faculty for observation.","zh":"这项练习培养孩子们的观察能力。"}]},{"pos":"n.","meaning":"学院；系；学部","definition":"A division of a university covering related subjects.","examples":[{"en":"He enrolled in the faculty of engineering.","zh":"他进入了工程学院学习。"},{"en":"The faculty of arts occupies the oldest building on campus.","zh":"文学院位于校园中最古老的建筑里。"}]},{"pos":"n.","meaning":"全体教员；全体教学人员","definition":"The teaching staff of a college or university.","examples":[{"en":"Students and faculty attended the opening lecture.","zh":"学生和全体教员出席了开场讲座。"},{"en":"The university has recruited several new faculty members.","zh":"大学招聘了几位新教师。"}]}],"fade":[{"pos":"v.","meaning":"褪色;变暗;逐渐消失;凋谢","definition":"to lose colour, strength, or visibility gradually","examples":[{"en":"The curtains faded in the sunlight.","zh":"窗帘在阳光下褪色了。"},{"en":"His anger faded as they talked.","zh":"随着交谈，他的怒气渐渐消退。"}]}],"fair":[{"pos":"adj.","meaning":"公平的；公正的","definition":"treating people equally and reasonably","examples":[{"en":"Both teams deserve a fair chance.","zh":"两支队伍都应得到公平的机会。"},{"en":"The judge made a fair decision.","zh":"裁判作出了公正的决定。"}]},{"pos":"adv.","meaning":"公平地；按规则地","definition":"in an honest and equal way","examples":[{"en":"We expect everyone to play fair.","zh":"我们希望每个人都公平竞赛。"},{"en":"The boxers agreed to fight fair.","zh":"拳击手们同意公平比赛。"}]}],"fairly":[{"pos":"adv.","meaning":"相当地；颇","definition":"To a moderate but noticeable degree.","examples":[{"en":"The instructions are fairly easy to follow.","zh":"这些说明相当容易理解。"},{"en":"We reached the summit fairly early.","zh":"我们相当早就到达了山顶。"}]},{"pos":"adv.","meaning":"公平地；公正地","definition":"In a just and impartial way.","examples":[{"en":"The prize money was divided fairly among the winners.","zh":"奖金在获胜者之间公平分配。"},{"en":"A judge must treat both sides fairly.","zh":"法官必须公平对待双方。"}]},{"pos":"adv.","meaning":"简直；完全（用于强调）","definition":"Used to emphasise that something happens strongly or completely.","examples":[{"en":"Her eyes fairly sparkled when she saw the puppy.","zh":"她看到小狗时，眼睛简直闪闪发亮。"},{"en":"The hall fairly shook with applause.","zh":"大厅简直被掌声震动了。"}]}],"faith":[{"pos":"n.","meaning":"信任;信心","definition":"strong trust or confidence","examples":[{"en":"I have faith in your judgement.","zh":"我相信你的判断。"},{"en":"The failed project shook investors' faith.","zh":"项目失败动摇了投资者的信心。"}]},{"pos":"n.","meaning":"宗教信仰;信条","definition":"belief in a religion or its teachings","examples":[{"en":"Her faith gives her strength.","zh":"宗教信仰给予她力量。"},{"en":"People of different faiths attended the ceremony.","zh":"不同信仰的人参加了仪式。"}]}],"fake":[{"pos":"adj.","meaning":"假的；伪造的","definition":"made to look genuine when it is not","examples":[{"en":"The shop sold fake designer bags.","zh":"商店出售仿冒名牌包。"},{"en":"The detective recognised the fake signature.","zh":"侦探认出了伪造的签名。"}]},{"pos":"n.","meaning":"假货；赝品","definition":"an object that is not genuine","examples":[{"en":"The painting turned out to be a fake.","zh":"这幅画结果是赝品。"},{"en":"An expert examined the coin and identified it as a fake.","zh":"专家检查硬币后认定它是假货。"}]},{"pos":"n.","meaning":"骗子；冒充者","definition":"a person pretending to be something they are not","examples":[{"en":"The supposed doctor was a fake.","zh":"那个所谓的医生是个骗子。"},{"en":"The audience discovered that the expert was a fake.","zh":"观众发现那位专家是冒充的。"}]},{"pos":"v.","meaning":"伪装；假装；伪造","definition":"to pretend or create a false version","examples":[{"en":"He faked enthusiasm for the proposal.","zh":"他假装对提案很热情。"},{"en":"Someone had faked the certificate.","zh":"有人伪造了证书。"}]}],"fallow":[{"pos":"adj.","meaning":"休耕的；暂不使用的","definition":"Left without crops or temporarily inactive.","examples":[{"en":"The farmer left one field fallow to restore the soil.","zh":"农民让一块田休耕以恢复地力。"},{"en":"After a fallow period, the writer began a new novel.","zh":"经过一段创作停滞期，作家开始写一部新小说。"}]}],"familiarise":[{"pos":"v.","meaning":"使熟悉;使通晓","definition":"to help someone know something well","examples":[{"en":"The tour familiarised students with the campus.","zh":"参观使学生熟悉了校园。"},{"en":"Familiarise yourself with the controls before driving.","zh":"开车前先熟悉各项控制装置。"}]}],"fancy":[{"pos":"adj.","meaning":"精致花哨的；别致的","definition":"decorative or elaborate","examples":[{"en":"She wore a fancy hat to the party.","zh":"她戴了顶别致的帽子去参加聚会。"},{"en":"The cake had fancy icing around the edges.","zh":"蛋糕边缘有精致的糖霜装饰。"}]},{"pos":"v.","meaning":"想象；以为","definition":"to imagine something or suppose it true","examples":[{"en":"She fancied herself a great detective.","zh":"她自认为是一位了不起的侦探。"},{"en":"I fancied I heard footsteps outside.","zh":"我以为听到了外面的脚步声。"}]},{"pos":"n.","meaning":"想象；想象力","definition":"the ability to imagine things","examples":[{"en":"The story blends fact with fancy.","zh":"这个故事将事实与想象结合。"},{"en":"The strange shape caught the artist's fancy.","zh":"奇特的形状激发了艺术家的想象。"}]}],"fantastic":[{"pos":"adj.","meaning":"极好的；出色的","definition":"Extremely good or enjoyable.","examples":[{"en":"The balcony offers a fantastic view of the bay.","zh":"从阳台可以欣赏到海湾的绝佳景色。"},{"en":"You did a fantastic job organising the exhibition.","zh":"你把这次展览组织得非常出色。"}]},{"pos":"adj.","meaning":"奇异的；荒诞的；不切实际的","definition":"Imaginary, strange, or difficult to believe.","examples":[{"en":"The story is filled with fantastic beasts and impossible journeys.","zh":"故事充满了奇异的野兽和不可能的旅程。"},{"en":"Their fantastic plan depended on discovering gold in the garden.","zh":"他们不切实际的计划指望在花园里发现金子。"}]}],"fantasy":[{"pos":"n.","meaning":"幻想;想象;幻想作品","definition":"an imagined situation unlikely to be real","examples":[{"en":"Living in a castle was her childhood fantasy.","zh":"住在城堡里是她童年的幻想。"},{"en":"The novel blends fantasy with historical detail.","zh":"小说把幻想与历史细节结合起来。"}]}],"fare":[{"pos":"n.","meaning":"交通票价","definition":"the price of a journey on public transport","examples":[{"en":"The bus fare has increased this year.","zh":"今年公交票价上涨了。"},{"en":"Children under five do not pay a fare.","zh":"五岁以下儿童无需付车费。"},{"en":"The taxi fare includes a small airport charge.","zh":"出租车费包含一小笔机场附加费。"}]},{"pos":"v.","meaning":"进展；过活","definition":"to perform or get along in a situation","examples":[{"en":"How did you fare in the interview?","zh":"你面试表现如何？"},{"en":"Small shops fared badly during the closure.","zh":"封路期间小商店经营不佳。"}]}],"farewell":[{"pos":"n.","meaning":"告别；辞行；欢送会","definition":"An occasion or expression of saying goodbye.","examples":[{"en":"They gathered at the station to say their farewells.","zh":"他们聚集在车站告别。"},{"en":"The department organised a farewell for its retiring head.","zh":"部门为即将退休的负责人举办了欢送会。"}]}],"fascinate":[{"pos":"v.","meaning":"使着迷;强烈吸引","definition":"to attract someone's interest intensely","examples":[{"en":"Space travel has always fascinated him.","zh":"太空旅行一直令他着迷。"},{"en":"The tiny mechanical clock fascinated the children.","zh":"小巧的机械钟使孩子们着迷。"}]}],"fascinating":[{"pos":"adj.","meaning":"迷人的；极有趣的","definition":"extremely interesting","examples":[{"en":"The guide told a fascinating story about the castle.","zh":"导游讲了一个关于城堡的迷人故事。"},{"en":"Watching the bees at work was fascinating.","zh":"观察蜜蜂工作十分有趣。"}]}],"fashion":[{"pos":"n.","meaning":"时尚；流行款式；时装","definition":"A popular style, especially in clothing, or the clothing industry.","examples":[{"en":"Loose jackets are back in fashion.","zh":"宽松夹克又流行起来了。"},{"en":"She hopes to work in fashion after graduating.","zh":"她希望毕业后从事时装行业。"}]},{"pos":"n.","meaning":"方式；方法","definition":"The manner in which something is done.","examples":[{"en":"The files were arranged in an orderly fashion.","zh":"文件排列得井然有序。"},{"en":"He answered in his usual cautious fashion.","zh":"他用惯有的谨慎方式作答。"}]}],"fasten":[{"pos":"v.","meaning":"扣紧;系牢;固定","definition":"to close or attach something securely","examples":[{"en":"Fasten your seat belt before takeoff.","zh":"起飞前系好安全带。"},{"en":"She fastened the notice to the door.","zh":"她把通知固定在门上。"}]}],"fatal":[{"pos":"adj.","meaning":"致命的","definition":"causing death","examples":[{"en":"The crash caused a fatal injury.","zh":"撞车造成了一处致命伤。"},{"en":"The report examined factors behind fatal accidents.","zh":"报告研究了致命事故背后的因素。"}]},{"pos":"adj.","meaning":"灾难性的；导致失败的","definition":"causing complete failure or ruin","examples":[{"en":"Ignoring the warning proved a fatal mistake.","zh":"忽视警告成了致命的错误。"},{"en":"A fatal flaw undermined the whole argument.","zh":"一个致命缺陷削弱了整个论证。"}]},{"pos":"adj.","meaning":"命中注定的（文学用法）","definition":"determined by fate","examples":[{"en":"The tragedy moves towards its fatal conclusion.","zh":"悲剧朝着命定的结局发展。"},{"en":"The poem describes a fatal meeting beneath the trees.","zh":"诗歌描述了树下那次命定的相遇。"}]}],"fate":[{"pos":"n.","meaning":"命运；结局；天命","definition":"The course of someone's life or the final outcome of events.","examples":[{"en":"The court will decide the fate of the historic building.","zh":"法院将决定这座历史建筑的命运。"},{"en":"A chance meeting changed the fate of both families.","zh":"一次偶遇改变了两个家庭的命运。"}]}],"fatigue":[{"pos":"n.","meaning":"疲劳;劳累","definition":"extreme tiredness","examples":[{"en":"Long shifts caused severe fatigue.","zh":"长时间轮班导致严重疲劳。"},{"en":"The runner withdrew because of fatigue.","zh":"跑步者因疲劳退出了比赛。"}]},{"pos":"v.","meaning":"使疲劳;感到疲劳","definition":"to make or become very tired","examples":[{"en":"The long climb fatigued the older hikers.","zh":"长途攀登使年长的徒步者筋疲力尽。"},{"en":"Her muscles fatigued during the final set.","zh":"做最后一组动作时她的肌肉疲劳了。"}]}],"fault":[{"pos":"n.","meaning":"缺点；故障；瑕疵","definition":"an imperfection or problem","examples":[{"en":"The electrician found a fault in the wiring.","zh":"电工发现线路有故障。"},{"en":"The vase has a small fault in the glaze.","zh":"花瓶的釉面有一处小瑕疵。"}]}],"faulty":[{"pos":"adj.","meaning":"有故障的；有缺陷的；错误的","definition":"Not working correctly or based on an error.","examples":[{"en":"A faulty cable caused the lights to flicker.","zh":"一根有故障的电缆导致灯光闪烁。"},{"en":"The conclusion rests on faulty assumptions.","zh":"这个结论建立在错误假设之上。"}]}],"fauna":[{"pos":"n.","meaning":"动物群;某地区或时期的动物","definition":"all the animals of a region or period","examples":[{"en":"The island has unusual native fauna.","zh":"这个岛有独特的本土动物群。"},{"en":"Pollution threatens the river's fauna.","zh":"污染威胁着河流中的动物。"}]}],"favour":[{"pos":"n.","meaning":"帮忙；恩惠","definition":"a helpful act done for someone","examples":[{"en":"Could you do me a favour?","zh":"你能帮我个忙吗？"},{"en":"She returned the favour by helping him move.","zh":"她帮他搬家，以此回报他的帮助。"}]},{"pos":"n.","meaning":"偏爱；赞同；支持","definition":"approval or preferential treatment","examples":[{"en":"The plan won favour with local residents.","zh":"计划赢得了当地居民的支持。"},{"en":"The manager showed no favour to relatives.","zh":"经理没有偏袒亲属。"}]},{"pos":"v.","meaning":"支持；赞同","definition":"to prefer or support an option","examples":[{"en":"Most members favour an earlier start.","zh":"多数成员赞成早点开始。"},{"en":"She favours improving the existing station.","zh":"她支持改善现有车站。"}]},{"pos":"v.","meaning":"偏袒；更喜欢","definition":"to treat someone or something with preference","examples":[{"en":"The teacher was accused of favouring certain pupils.","zh":"这位教师被指偏袒某些学生。"},{"en":"The selection process should not favour wealthy applicants.","zh":"选拔程序不应偏向富裕申请者。"}]},{"pos":"v.","meaning":"有利于","definition":"to provide helpful conditions for something","examples":[{"en":"The weather favours an early harvest.","zh":"天气有利于提早收获。"},{"en":"The rules favour teams with larger squads.","zh":"规则有利于阵容更大的球队。"}]}],"favourite":[{"pos":"adj.","meaning":"最喜欢的；特别喜爱的","definition":"Liked more than others of the same kind.","examples":[{"en":"This is my favourite place to watch the sunset.","zh":"这是我最喜欢的看日落的地方。"},{"en":"She packed her favourite sweater for the trip.","zh":"她把最喜欢的毛衣装进行李准备旅行。"}]},{"pos":"n.","meaning":"最喜欢的人或物；宠儿；亲信","definition":"A person or thing preferred above others.","examples":[{"en":"Of all the desserts, the lemon tart is my favourite.","zh":"在所有甜点中，柠檬挞是我的最爱。"},{"en":"The king's favourite was given control of the port.","zh":"国王的宠臣获得了港口的管理权。"}]}],"feasible":[{"pos":"adj.","meaning":"可行的","definition":"possible to do successfully","examples":[{"en":"The plan is technically feasible but expensive.","zh":"这个计划在技术上可行，但成本高。"},{"en":"We need a feasible solution before the winter.","zh":"我们需要在冬季前提出可行方案。"},{"en":"Daily flights may not be feasible without enough passengers.","zh":"如果乘客不足，每日航班可能不可行。"}]}],"feather":[{"pos":"n.","meaning":"羽毛；翎毛","definition":"one of the light structures covering a bird","examples":[{"en":"A white feather floated on the pond.","zh":"一根白色羽毛浮在池塘上。"},{"en":"The bird spread its bright tail feathers.","zh":"鸟展开了鲜艳的尾羽。"}]}],"feature":[{"pos":"n.","meaning":"特征；特色","definition":"A noticeable quality or characteristic.","examples":[{"en":"Large windows are a distinctive feature of the house.","zh":"大窗户是这栋房屋的鲜明特色。"},{"en":"The app's most useful feature is its offline map.","zh":"这个应用最有用的功能是离线地图。"}]},{"pos":"n.","meaning":"面部特征；五官（常用复数）","definition":"A part of a person's face or their overall facial appearance.","examples":[{"en":"The portrait captures her delicate features.","zh":"这幅肖像抓住了她精致的五官。"},{"en":"His most striking feature is his unusually high forehead.","zh":"他最突出的面部特征是特别高的额头。"}]},{"pos":"n.","meaning":"专题文章；专题节目","definition":"A substantial article or broadcast about a particular subject.","examples":[{"en":"The newspaper ran a feature on urban gardening.","zh":"这家报纸刊登了一篇关于城市园艺的专题文章。"},{"en":"Tonight's feature examines the future of public libraries.","zh":"今晚的专题节目探讨公共图书馆的未来。"}]},{"pos":"n.","meaning":"故事片；长片","definition":"A full-length film shown as the main attraction.","examples":[{"en":"The director's first feature won a regional award.","zh":"这位导演的首部长片获得了地区奖项。"},{"en":"A short documentary will be shown before the feature.","zh":"长片放映前会播放一部短纪录片。"}]},{"pos":"v.","meaning":"以……为特色；由……主演；占重要位置","definition":"To include or present something prominently.","examples":[{"en":"The festival features music from five continents.","zh":"这个音乐节以五大洲的音乐为特色。"},{"en":"Local history features prominently in her latest novel.","zh":"地方历史在她最新的小说中占据重要位置。"}]}],"federal":[{"pos":"adj.","meaning":"联邦的;联邦政府的","definition":"relating to a union of states or its central government","examples":[{"en":"The programme receives federal funding.","zh":"这个项目获得联邦资金。"},{"en":"Power is shared under the federal system.","zh":"联邦制度下权力由各级政府分享。"}]}],"federation":[{"pos":"n.","meaning":"联邦；联合会；同盟","definition":"a union of states or organisations","examples":[{"en":"The country is a federation of several states.","zh":"这个国家是由几个州组成的联邦。"},{"en":"The sports federation announced new competition rules.","zh":"体育联合会公布了新的比赛规则。"}]}],"fee":[{"pos":"n.","meaning":"服务费；费用","definition":"money charged for a service","examples":[{"en":"The membership fee is paid annually.","zh":"会费每年缴纳。"},{"en":"There is no fee for cancelling within twenty-four hours.","zh":"二十四小时内取消不收费。"},{"en":"The course fee includes all learning materials.","zh":"课程费用包含所有学习材料。"}]}],"feeble":[{"pos":"adj.","meaning":"虚弱的;微弱的","definition":"lacking strength","examples":[{"en":"The patient spoke in a feeble voice.","zh":"患者用微弱的声音说话。"},{"en":"A feeble light shone through the curtain.","zh":"微弱的光透过窗帘照进来。"}]},{"pos":"adj.","meaning":"无效的;无说服力的","definition":"unconvincing or ineffective","examples":[{"en":"He offered a feeble excuse for being late.","zh":"他为迟到找了一个牵强的借口。"},{"en":"Their feeble resistance soon collapsed.","zh":"他们无力的抵抗很快瓦解了。"}]}],"feed":[{"pos":"v.","meaning":"喂养；提供食物","definition":"to give food to a person or animal","examples":[{"en":"She feeds the chickens every morning.","zh":"她每天早晨喂鸡。"},{"en":"The kitchen can feed a hundred guests.","zh":"厨房能为一百位客人供餐。"}]},{"pos":"v.","meaning":"进食；以……为食","definition":"to eat or obtain food","examples":[{"en":"The birds feed on insects.","zh":"这些鸟以昆虫为食。"},{"en":"Deer were feeding in the meadow.","zh":"鹿正在草地上觅食。"}]},{"pos":"n.","meaning":"饲料","definition":"food given to farm animals","examples":[{"en":"The farmer bought feed for the cattle.","zh":"农民买了牛饲料。"},{"en":"Store animal feed in a dry place.","zh":"把动物饲料储存在干燥处。"}]}],"feedback":[{"pos":"n.","meaning":"反馈；反馈意见","definition":"Information about a performance or result used to improve it.","examples":[{"en":"The teacher gave detailed feedback on my essay.","zh":"老师对我的作文给出了详细反馈。"},{"en":"Customer feedback led the company to redesign the packaging.","zh":"顾客的反馈促使公司重新设计包装。"}]}],"female":[{"pos":"adj.","meaning":"女性的;雌性的","definition":"relating to women or the sex that produces eggs","examples":[{"en":"The team appointed its first female captain.","zh":"球队任命了首位女队长。"},{"en":"The female bird stayed near the nest.","zh":"雌鸟留在巢边。"}]},{"pos":"n.","meaning":"雌性动物;女性","definition":"a female animal or person","examples":[{"en":"The female guards her eggs closely.","zh":"雌性动物小心守护着卵。"},{"en":"Females made up half the study participants.","zh":"女性占研究参与者的一半。"}]}],"feminism":[{"pos":"n.","meaning":"女权主义；性别平等主义及运动","definition":"support for equal rights and opportunities for women","examples":[{"en":"The course traces the history of feminism.","zh":"课程追溯女权主义的历史。"},{"en":"Her essays explore feminism in contemporary literature.","zh":"她的文章探讨当代文学中的女权主义。"}]}],"ferry":[{"pos":"n.","meaning":"渡船；轮渡","definition":"A boat or service carrying people or vehicles across water.","examples":[{"en":"The last ferry leaves the island at six.","zh":"最后一班渡船六点离岛。"},{"en":"We crossed the river by ferry.","zh":"我们乘渡船过了河。"}]},{"pos":"v.","meaning":"渡运；运送","definition":"To carry people or goods across water or repeatedly between places.","examples":[{"en":"Small boats ferried residents to higher ground.","zh":"小船把居民运送到了高地。"},{"en":"A shuttle bus ferries guests between the hotel and airport.","zh":"接驳巴士往返于酒店和机场之间运送客人。"}]}],"fertile":[{"pos":"adj.","meaning":"肥沃的;富饶的","definition":"able to support abundant plant growth","examples":[{"en":"Crops thrive in the fertile soil.","zh":"庄稼在肥沃土壤中茁壮生长。"},{"en":"The river floods leave fertile farmland.","zh":"河水泛滥后留下肥沃农田。"}]},{"pos":"adj.","meaning":"能繁殖的;可受精的","definition":"able to reproduce or develop into an organism","examples":[{"en":"Only fertile eggs will hatch.","zh":"只有受精卵才能孵化。"},{"en":"The breeding programme relies on fertile adults.","zh":"繁育计划依赖具有繁殖能力的成年个体。"}]},{"pos":"adj.","meaning":"富有创造力的;多产的","definition":"producing many useful ideas or results","examples":[{"en":"Her fertile imagination created a vivid world.","zh":"她丰富的想象力创造了一个鲜活世界。"},{"en":"The discovery opened a fertile field of research.","zh":"这项发现开辟了富有潜力的研究领域。"}]}],"fertilise":[{"pos":"v.","meaning":"施肥；使肥沃","definition":"to add nutrients that help plants grow","examples":[{"en":"Farmers fertilise the soil before planting.","zh":"农民在播种前给土壤施肥。"},{"en":"Compost can fertilise the vegetable beds.","zh":"堆肥能使菜畦肥沃。"}]},{"pos":"v.","meaning":"使受精","definition":"to join a male reproductive cell with a female one","examples":[{"en":"Pollen can fertilise an ovule in a flower.","zh":"花粉能使花中的胚珠受精。"},{"en":"The diagram shows how sperm fertilise an egg.","zh":"图示说明精子如何使卵子受精。"}]}],"fibre":[{"pos":"n.","meaning":"纤维；纤维状物","definition":"A thin thread forming part of a natural or manufactured material.","examples":[{"en":"The rope is made from coconut fibre.","zh":"这条绳子是用椰子纤维做的。"},{"en":"Scientists examined a tiny fibre found on the jacket.","zh":"科学家检查了夹克上发现的一根细小纤维。"}]},{"pos":"n.","meaning":"膳食纤维","definition":"The part of plant food that passes through the body largely undigested.","examples":[{"en":"Whole grains are a useful source of fibre.","zh":"全谷物是膳食纤维的良好来源。"},{"en":"The label shows how much fibre each serving contains.","zh":"标签标明每份食物含有多少膳食纤维。"}]}],"fickle":[{"pos":"adj.","meaning":"易变的;反复无常的","definition":"changing opinions or loyalties frequently","examples":[{"en":"The island's fickle weather disrupted our plans.","zh":"岛上变化无常的天气打乱了计划。"},{"en":"Fashion depends on fickle consumer tastes.","zh":"时尚取决于消费者多变的品味。"}]}],"fiction":[{"pos":"n.","meaning":"小说；虚构文学","definition":"stories about imagined people and events","examples":[{"en":"She prefers historical fiction to detective novels.","zh":"相比侦探小说，她更喜欢历史小说。"},{"en":"The library has a large fiction section.","zh":"图书馆有很大的小说区。"}]}],"fieldwork":[{"pos":"n.","meaning":"实地调查；野外考察","definition":"Research carried out in a natural or real-world setting.","examples":[{"en":"Her fieldwork involved interviewing fishermen along the coast.","zh":"她的实地调查包括采访沿海渔民。"},{"en":"Students collected soil samples during their geology fieldwork.","zh":"学生在地质野外考察中采集了土壤样本。"}]}],"fierce":[{"pos":"adj.","meaning":"凶猛的;猛烈的;强烈的","definition":"aggressive or very intense","examples":[{"en":"A fierce dog guarded the gate.","zh":"一条凶猛的狗守着大门。"},{"en":"Fierce competition drove prices down.","zh":"激烈竞争压低了价格。"}]}],"figure":[{"pos":"n.","meaning":"数字；数额","definition":"a number or numerical amount","examples":[{"en":"The sales figures exceeded our forecast.","zh":"销售数字超过了预测。"},{"en":"Write the total figure at the bottom.","zh":"在底部写下总数。"}]},{"pos":"n.","meaning":"人物","definition":"a person of a particular kind or importance","examples":[{"en":"She became a leading figure in the movement.","zh":"她成为运动中的领军人物。"},{"en":"The biography explores a controversial political figure.","zh":"传记探讨了一位有争议的政治人物。"}]},{"pos":"n.","meaning":"身材；人影；轮廓","definition":"a person's body shape or visible outline","examples":[{"en":"A tall figure appeared at the gate.","zh":"一个高高的人影出现在门口。"},{"en":"The long coat concealed her figure.","zh":"长外套遮住了她的身形。"}]},{"pos":"n.","meaning":"图；图表","definition":"an illustration in a text","examples":[{"en":"Figure two shows the experimental equipment.","zh":"图二展示实验设备。"},{"en":"Refer to the figure beside the paragraph.","zh":"请参阅段落旁的图。"}]},{"pos":"n.","meaning":"雕像；塑像","definition":"a representation of a person or animal","examples":[{"en":"A bronze figure stood in the square.","zh":"广场上矗立着一座青铜塑像。"},{"en":"The child made a clay figure of a horse.","zh":"孩子捏了一匹泥马。"}]},{"pos":"v.","meaning":"是重要部分；出现","definition":"to have a role or appear in something","examples":[{"en":"Transport costs figure prominently in the budget.","zh":"运输成本在预算中占重要地位。"},{"en":"His childhood figures in many of his stories.","zh":"他的童年出现在许多故事中。"}]},{"pos":"v.","meaning":"认为；估计","definition":"to think or calculate","examples":[{"en":"I figured the journey would take an hour.","zh":"我估计旅程要花一小时。"},{"en":"We figured the total cost before booking.","zh":"预订前我们算出了总费用。"}]}],"filter":[{"pos":"n.","meaning":"过滤器；滤层","definition":"A device or material that removes unwanted substances.","examples":[{"en":"Replace the air filter every six months.","zh":"每六个月更换一次空气过滤器。"},{"en":"The coffee machine needs a fresh paper filter.","zh":"咖啡机需要换一张新滤纸。"}]},{"pos":"v.","meaning":"过滤；筛选","definition":"To remove unwanted material or select information.","examples":[{"en":"The system filters dust from the air.","zh":"这个系统过滤空气中的灰尘。"},{"en":"You can filter the results by date.","zh":"你可以按日期筛选结果。"}]},{"pos":"v.","meaning":"逐渐传开；慢慢渗入","definition":"To pass or become known gradually.","examples":[{"en":"News of the closure filtered through to the workers.","zh":"关闭的消息逐渐传到工人耳中。"},{"en":"Sunlight filtered through the leaves.","zh":"阳光透过树叶洒落下来。"}]}],"finale":[{"pos":"n.","meaning":"终曲;终场;结尾","definition":"the final part of a performance","examples":[{"en":"Fireworks accompanied the concert's grand finale.","zh":"烟花伴随着音乐会盛大的终曲。"},{"en":"The series finale resolved the mystery.","zh":"电视剧大结局解开了谜团。"}]}],"finance":[{"pos":"v.","meaning":"为……提供资金","definition":"to provide money for an activity","examples":[{"en":"The grant financed the restoration.","zh":"这笔资助为修复工程提供了资金。"},{"en":"The council financed a new sports centre.","zh":"议会出资建造了新体育中心。"}]},{"pos":"n.","meaning":"财政；金融；资金管理","definition":"the provision and management of money","examples":[{"en":"She works in finance.","zh":"她从事金融工作。"},{"en":"The project is delayed by a lack of finance.","zh":"项目因缺乏资金而延误。"}]},{"pos":"n.","meaning":"财务状况；财力（常用复数）","definition":"the money available to a person or organisation","examples":[{"en":"Their finances improved after the loan was repaid.","zh":"还清贷款后，他们的财务状况改善了。"},{"en":"The charity publishes an annual report on its finances.","zh":"慈善机构发布年度财务报告。"}]}],"fingerprint":[{"pos":"n.","meaning":"指纹；指印","definition":"The distinctive pattern on a fingertip or a mark left by it.","examples":[{"en":"The technician compared the fingerprint with the records.","zh":"技术人员将这个指纹与档案作了比对。"},{"en":"A greasy fingerprint remained on the glass.","zh":"玻璃上留下了一个油腻的指印。"}]}],"finite":[{"pos":"adj.","meaning":"有限的;有限度的","definition":"having a limit or end","examples":[{"en":"Fresh water is a finite resource.","zh":"淡水是有限资源。"},{"en":"The experiment used a finite number of samples.","zh":"实验使用的样本数量有限。"}]}],"finitude":[{"pos":"n.","meaning":"有限性；界限","definition":"the state of having limits","examples":[{"en":"The essay reflects on the finitude of human life.","zh":"文章思考了人类生命的有限性。"},{"en":"Resource finitude shapes the debate about consumption.","zh":"资源的有限性影响着关于消费的讨论。"}]}],"firm":[{"pos":"n.","meaning":"公司；商行","definition":"A business organisation.","examples":[{"en":"She works for an engineering firm.","zh":"她在一家工程公司工作。"},{"en":"The firm opened a second office near the station.","zh":"这家公司在车站附近开设了第二间办事处。"}]},{"pos":"adj.","meaning":"坚实的；稳固的","definition":"Solid and not easily moved or changed in shape.","examples":[{"en":"Place the ladder on firm ground.","zh":"把梯子放在坚实的地面上。"},{"en":"This mattress is too firm for me.","zh":"这张床垫对我来说太硬了。"}]},{"pos":"adj.","meaning":"坚定的；坚决的","definition":"Showing strong determination or a settled opinion.","examples":[{"en":"She remained firm in her decision to resign.","zh":"她坚持辞职的决定。"},{"en":"The teacher gave a firm but polite refusal.","zh":"老师坚定而礼貌地拒绝了。"}]}],"fitness":[{"pos":"n.","meaning":"健康;体能","definition":"physical health and strength","examples":[{"en":"Regular swimming improves fitness.","zh":"经常游泳能增强体能。"},{"en":"The coach assessed each player's fitness.","zh":"教练评估了每位球员的体能。"}]},{"pos":"n.","meaning":"适合;胜任","definition":"suitability for a particular purpose","examples":[{"en":"The interview tested her fitness for leadership.","zh":"面试考察了她担任领导的适合程度。"},{"en":"Engineers checked the bridge's fitness for use.","zh":"工程师检查了桥梁是否适合使用。"}]}],"fitting":[{"pos":"n.","meaning":"试衣；试穿","definition":"an appointment to adjust clothing to fit","examples":[{"en":"She returned for a final dress fitting.","zh":"她回来进行最后一次礼服试穿。"},{"en":"The tailor arranged a fitting for Tuesday.","zh":"裁缝安排星期二试衣。"}]},{"pos":"n.","meaning":"配件；固定装置","definition":"a small part attached to equipment or a building","examples":[{"en":"The plumber replaced a damaged pipe fitting.","zh":"水管工更换了损坏的管件。"},{"en":"The room still has its original light fittings.","zh":"房间仍保留原来的灯具。"}]},{"pos":"adj.","meaning":"合适的；恰当的","definition":"suitable for the occasion","examples":[{"en":"The concert was a fitting tribute to the composer.","zh":"音乐会是对作曲家恰当的致敬。"},{"en":"A quiet ceremony seemed a fitting conclusion.","zh":"安静的仪式似乎是合适的结尾。"}]}],"flame":[{"pos":"n.","meaning":"火焰","definition":"The visible burning part of a fire.","examples":[{"en":"A blue flame appeared beneath the pan.","zh":"锅底下出现了蓝色火焰。"},{"en":"The wind blew the candle flame sideways.","zh":"风把蜡烛的火焰吹向一边。"}]},{"pos":"n.","meaning":"强烈的情感；激情","definition":"A powerful feeling compared to a burning fire.","examples":[{"en":"Their letters kept the flame of friendship alive.","zh":"他们的书信使友谊之火长存。"},{"en":"The victory rekindled a flame of hope among the supporters.","zh":"这场胜利在支持者中重新燃起了希望之火。"}]},{"pos":"v.","meaning":"燃烧；冒火焰","definition":"To burn with visible flames.","examples":[{"en":"Dry branches flamed in the fireplace.","zh":"干树枝在壁炉里燃起火焰。"},{"en":"The abandoned shed flamed brightly against the night sky.","zh":"废弃棚屋的火焰在夜空下显得格外明亮。"}]}],"flap":[{"pos":"v.","meaning":"拍打;拍动","definition":"to move up and down repeatedly","examples":[{"en":"The bird flapped its wings.","zh":"鸟拍动翅膀。"},{"en":"A loose curtain flapped in the wind.","zh":"松开的窗帘在风中拍动。"}]},{"pos":"n.","meaning":"盖片;垂片","definition":"a flat piece attached along one edge","examples":[{"en":"Seal the envelope's flap with glue.","zh":"用胶水封住信封封口。"},{"en":"He lifted the tent flap to look outside.","zh":"他掀开帐篷门帘向外看。"}]},{"pos":"n.","meaning":"拍动;拍打","definition":"a single movement of something broad and flat","examples":[{"en":"One flap of its wings lifted the bird.","zh":"鸟翅膀一拍就飞了起来。"},{"en":"We heard the flap of sails overhead.","zh":"我们听到头顶船帆拍动的声音。"}]},{"pos":"n.","meaning":"慌乱;激动","definition":"a state of nervous excitement","examples":[{"en":"The missing keys put her in a flap.","zh":"钥匙丢了使她慌了神。"},{"en":"There was a flap over the unexpected inspection.","zh":"突如其来的检查引起一阵慌乱。"}]}],"flash":[{"pos":"v.","meaning":"闪光；闪耀","definition":"to shine suddenly or briefly","examples":[{"en":"Lightning flashed above the hills.","zh":"闪电在山丘上方闪过。"},{"en":"A warning light flashed on the dashboard.","zh":"仪表盘上的警示灯闪烁起来。"}]},{"pos":"n.","meaning":"闪光；闪烁","definition":"a sudden brief burst of light","examples":[{"en":"We saw a flash in the distance.","zh":"我们看见远处闪了一道光。"},{"en":"A flash of lightning lit the room.","zh":"一道闪电照亮了房间。"}]},{"pos":"n.","meaning":"闪光灯","definition":"a device producing light for photography","examples":[{"en":"Turn off the flash in the museum.","zh":"在博物馆里请关闭闪光灯。"},{"en":"The photographer used a flash indoors.","zh":"摄影师在室内用了闪光灯。"}]}],"flask":[{"pos":"n.","meaning":"烧瓶；细颈瓶","definition":"A container with a narrow neck used for liquids, especially in laboratories.","examples":[{"en":"The student poured the solution into a glass flask.","zh":"学生把溶液倒进玻璃烧瓶。"},{"en":"Steam rose from the flask as the water heated.","zh":"水受热时，烧瓶中冒出了蒸汽。"}]}],"flat":[{"pos":"adj.","meaning":"平坦的;平的","definition":"level and without raised areas","examples":[{"en":"Place the tray on a flat surface.","zh":"把托盘放在平面上。"},{"en":"The path crosses flat farmland.","zh":"小路穿过平坦农田。"}]},{"pos":"adj.","meaning":"固定的;统一的","definition":"remaining the same regardless of amount or circumstances","examples":[{"en":"The taxi charges a flat airport fare.","zh":"出租车到机场收取统一票价。"},{"en":"Members pay a flat monthly fee.","zh":"会员每月支付固定费用。"}]},{"pos":"n.","meaning":"公寓;单元住宅","definition":"a set of rooms within a larger building","examples":[{"en":"They rented a small flat near campus.","zh":"他们在校园附近租了一套小公寓。"},{"en":"Her flat overlooks the river.","zh":"她的公寓俯瞰河流。"}]}],"flavour":[{"pos":"n.","meaning":"味道；风味","definition":"the taste of a food or drink","examples":[{"en":"Fresh herbs add flavour to the soup.","zh":"新鲜香草给汤增添风味。"},{"en":"The tea has a delicate floral flavour.","zh":"这种茶有淡淡的花香味。"}]},{"pos":"v.","meaning":"给……调味","definition":"to add something that gives a particular taste","examples":[{"en":"She flavoured the rice with lemon.","zh":"她用柠檬给米饭调味。"},{"en":"The sauce is flavoured with garlic.","zh":"酱汁用大蒜调味。"}]}],"flaw":[{"pos":"n.","meaning":"缺点；瑕疵；缺陷","definition":"A fault that makes something imperfect.","examples":[{"en":"A small flaw in the glass caused it to crack.","zh":"玻璃中的一处小瑕疵导致它开裂。"},{"en":"The reviewer identified a serious flaw in the argument.","zh":"评论者指出了论证中的一个严重缺陷。"}]}],"flee":[{"pos":"v.","meaning":"逃离;逃避","definition":"to run away from danger or difficulty","examples":[{"en":"Residents fled the approaching wildfire.","zh":"居民逃离逼近的野火。"},{"en":"The thief fled through a side door.","zh":"小偷从侧门逃走了。"}]}],"fleet":[{"pos":"n.","meaning":"舰队；船队；车队","definition":"a group of ships or vehicles under one control","examples":[{"en":"The fishing fleet returned before the storm.","zh":"渔船队在风暴前返航。"},{"en":"The company replaced its delivery fleet.","zh":"公司更换了送货车队。"}]},{"pos":"adj.","meaning":"快速的；敏捷的（文学用法）","definition":"moving very quickly","examples":[{"en":"The fleet deer vanished into the woods.","zh":"敏捷的鹿消失在树林里。"},{"en":"Her fleet steps carried her across the courtyard.","zh":"她步履轻快地穿过院子。"}]},{"pos":"v.","meaning":"疾驰；飞逝（文学用法）","definition":"to move or pass swiftly","examples":[{"en":"Clouds fleeted across the moon.","zh":"云朵从月前飞快掠过。"},{"en":"The happy hours fleeted by.","zh":"快乐的时光飞逝。"}]}],"flexibility":[{"pos":"n.","meaning":"柔韧性；弹性","definition":"The ability to bend without breaking.","examples":[{"en":"Stretching can improve the flexibility of stiff muscles.","zh":"伸展可以改善僵硬肌肉的柔韧性。"},{"en":"The flexibility of the cable allows it to fit into narrow spaces.","zh":"电缆的柔韧性使其可以放进狭窄空间。"}]},{"pos":"n.","meaning":"灵活性；适应性；变通能力","definition":"The ability or willingness to change according to circumstances.","examples":[{"en":"Remote working gives employees greater flexibility.","zh":"远程办公让员工拥有更大的灵活性。"},{"en":"The school showed flexibility when arranging her examination date.","zh":"学校在安排她的考试日期时作出了灵活调整。"}]}],"flexible":[{"pos":"adj.","meaning":"灵活的","definition":"able to change to suit different needs","examples":[{"en":"Flexible working hours help parents manage childcare.","zh":"灵活工时有助于父母安排育儿。"},{"en":"We need a flexible approach to the new schedule.","zh":"我们需要灵活处理新的日程安排。"},{"en":"The booking policy is flexible enough to allow changes.","zh":"预订政策足够灵活，允许更改。"}]},{"pos":"adj.","meaning":"易弯曲的;柔韧的","definition":"able to bend without breaking","examples":[{"en":"The flexible hose bends around the corner.","zh":"柔性软管绕过拐角。"},{"en":"Young branches are usually flexible.","zh":"嫩枝通常柔韧。"}]}],"flexitime":[{"pos":"n.","meaning":"弹性工作制","definition":"working hours with flexible starting and finishing times","examples":[{"en":"Flexitime allows her to avoid rush-hour trains.","zh":"弹性工作制使她能避开高峰期列车。"},{"en":"The office introduced flexitime for all staff.","zh":"办公室对全体员工实行弹性工作制。"}]}],"flicker":[{"pos":"v.","meaning":"闪烁；忽明忽暗；一闪而过","definition":"To shine unsteadily or appear briefly.","examples":[{"en":"The lights flickered during the storm.","zh":"暴风雨中灯光忽明忽暗。"},{"en":"A smile flickered across his face.","zh":"他的脸上掠过一丝微笑。"}]},{"pos":"n.","meaning":"闪光；闪烁；一丝","definition":"A brief or unsteady light, movement, or feeling.","examples":[{"en":"We saw the flicker of a distant campfire.","zh":"我们看见远处营火的闪光。"},{"en":"There was a flicker of doubt in her expression.","zh":"她的神情中闪过一丝怀疑。"}]}],"flight":[{"pos":"n.","meaning":"航班;飞行","definition":"a journey through the air","examples":[{"en":"Our flight was delayed by fog.","zh":"我们的航班因大雾延误了。"},{"en":"The bird changed direction during flight.","zh":"鸟在飞行中改变了方向。"}]}],"flint":[{"pos":"n.","meaning":"燧石；打火石","definition":"a hard stone that can produce sparks","examples":[{"en":"Prehistoric tools were often made of flint.","zh":"史前工具常用燧石制成。"},{"en":"A spark flew when the steel struck the flint.","zh":"钢击中燧石时飞出了一点火星。"}]}],"flip":[{"pos":"v.","meaning":"轻抛；快速翻转；轻弹","definition":"To turn something over quickly or move it with a short sharp action.","examples":[{"en":"He flipped a coin to decide who would start.","zh":"他抛硬币决定谁先开始。"},{"en":"She flipped the pancake with a quick movement of the pan.","zh":"她迅速晃动平底锅，把薄饼翻了面。"}]}],"flora":[{"pos":"n.","meaning":"植物群;某地或时期的植物","definition":"all the plants of a region or period","examples":[{"en":"The guide describes the island's flora.","zh":"指南介绍了岛上的植物群。"},{"en":"Warming may change the mountain's native flora.","zh":"变暖可能改变山区的本土植物群。"}]}],"floral":[{"pos":"adj.","meaning":"花的；花卉图案的","definition":"relating to flowers or decorated with flower patterns","examples":[{"en":"She chose curtains with a floral pattern.","zh":"她选了有花卉图案的窗帘。"},{"en":"A floral scent drifted from the garden.","zh":"花香从花园飘来。"}]},{"pos":"adj.","meaning":"植物群的","definition":"relating to the plants of a region","examples":[{"en":"The survey documented the island's floral diversity.","zh":"调查记录了该岛的植物多样性。"},{"en":"Researchers compared floral communities on the two slopes.","zh":"研究人员比较了两处山坡的植物群落。"}]}],"flourish":[{"pos":"v.","meaning":"繁荣；茁壮成长；兴旺","definition":"To grow well or become successful.","examples":[{"en":"These plants flourish in warm, damp conditions.","zh":"这些植物在温暖潮湿的环境中茁壮生长。"},{"en":"Small cafés began to flourish around the new station.","zh":"新车站周边的小咖啡馆开始兴旺起来。"}]},{"pos":"n.","meaning":"夸张动作；显眼的挥动","definition":"A bold movement intended to attract attention.","examples":[{"en":"The magician removed his hat with a flourish.","zh":"魔术师夸张地挥动手臂脱下帽子。"},{"en":"She signed the final page with a theatrical flourish.","zh":"她用戏剧化的大幅动作签下最后一页。"}]},{"pos":"n.","meaning":"装饰性的笔画；华丽修饰","definition":"A decorative detail added for effect.","examples":[{"en":"The invitation ended with an elegant handwritten flourish.","zh":"邀请函以一个优雅的手写花饰收尾。"},{"en":"A brief musical flourish introduced the final movement.","zh":"一段短促华丽的乐句引出了最后一个乐章。"}]}],"fluctuate":[{"pos":"v.","meaning":"波动;涨落;变化","definition":"to rise and fall irregularly","examples":[{"en":"Fuel prices fluctuate throughout the year.","zh":"燃料价格全年波动。"},{"en":"Her temperature fluctuated during the night.","zh":"她的体温在夜间上下变化。"}]}],"fluctuation":[{"pos":"n.","meaning":"波动；起伏","definition":"a repeated change in level or amount","examples":[{"en":"Seasonal fluctuations affect demand for heating.","zh":"季节性波动影响取暖需求。"},{"en":"The graph shows fluctuations in river depth.","zh":"图表显示了河流水深的波动。"}]}],"fluency":[{"pos":"n.","meaning":"流利；流畅；熟练表达","definition":"The ability to speak, write, or perform smoothly and easily.","examples":[{"en":"Regular conversation helped improve her fluency in English.","zh":"经常交谈帮助她提高了英语流利程度。"},{"en":"The pianist played the difficult passage with remarkable fluency.","zh":"钢琴家极其流畅地演奏了那段困难乐句。"}]}],"flush":[{"pos":"v.","meaning":"冲洗;冲掉","definition":"to wash or remove with a flow of liquid","examples":[{"en":"Flush the pipe with clean water.","zh":"用清水冲洗管道。"},{"en":"Remember to flush the toilet.","zh":"记得冲厕所。"}]},{"pos":"v.","meaning":"脸红;使发红","definition":"to become or make red","examples":[{"en":"She flushed with embarrassment.","zh":"她尴尬得脸红了。"},{"en":"The cold wind flushed his cheeks.","zh":"冷风吹红了他的脸颊。"}]},{"pos":"v.","meaning":"奔流;涌流","definition":"to flow suddenly and strongly","examples":[{"en":"Water flushed through the opened channel.","zh":"水奔涌通过打开的水道。"},{"en":"Rainwater flushed down the steep gutter.","zh":"雨水沿陡峭的水槽倾泻而下。"}]},{"pos":"n.","meaning":"脸红;红光","definition":"a sudden red colour, especially in the face","examples":[{"en":"A flush spread across her cheeks.","zh":"她双颊泛起红晕。"},{"en":"The sunset cast a rosy flush over the snow.","zh":"落日在雪上洒下玫瑰色红光。"}]},{"pos":"adj.","meaning":"齐平的","definition":"level with an adjacent surface","examples":[{"en":"The screw head should be flush with the wood.","zh":"螺钉头应与木面齐平。"},{"en":"The cabinet sits flush against the wall.","zh":"橱柜紧贴墙壁。"}]}],"flutter":[{"pos":"v.","meaning":"拍打翅膀；振翅","definition":"to move wings quickly and lightly","examples":[{"en":"The trapped bird fluttered against the window.","zh":"被困的鸟扑打着翅膀撞向窗户。"},{"en":"Butterflies fluttered above the flowers.","zh":"蝴蝶在花朵上方振翅飞舞。"}]},{"pos":"v.","meaning":"飘动；轻轻摆动","definition":"to move lightly and irregularly in the air","examples":[{"en":"Flags fluttered in the breeze.","zh":"旗帜在微风中飘动。"},{"en":"A loose page fluttered to the floor.","zh":"一张散页飘落到地上。"}]},{"pos":"v.","meaning":"急促而不规则地跳动","definition":"to beat quickly and unevenly","examples":[{"en":"Her heart fluttered as the results appeared.","zh":"结果出现时，她心跳加速。"},{"en":"His eyelids fluttered before he woke.","zh":"他醒来前眼皮轻轻颤动。"}]}],"foam":[{"pos":"n.","meaning":"泡沫","definition":"A mass of small bubbles on or in a liquid.","examples":[{"en":"White foam gathered around the breaking waves.","zh":"碎浪周围聚起白色泡沫。"},{"en":"The milk formed a thick layer of foam.","zh":"牛奶形成了一层厚厚的泡沫。"}]},{"pos":"n.","meaning":"泡沫材料","definition":"A lightweight material containing many small air spaces.","examples":[{"en":"The parcel was protected by a layer of foam.","zh":"包裹外有一层泡沫材料保护。"},{"en":"The seat cushions are made of firm foam.","zh":"座垫由较硬的泡沫材料制成。"}]},{"pos":"v.","meaning":"起泡沫","definition":"To produce a mass of small bubbles.","examples":[{"en":"The detergent foamed as she stirred the water.","zh":"她搅动水时，洗涤剂起了泡沫。"},{"en":"Waves foamed against the rocks.","zh":"海浪撞击岩石，泛起泡沫。"}]}],"focus":[{"pos":"v.","meaning":"聚焦;集中","definition":"to direct light or attention toward a point","examples":[{"en":"Focus the camera on the nearest flower.","zh":"把相机焦点对准最近的花。"},{"en":"We must focus on the main problem.","zh":"我们必须集中处理主要问题。"}]},{"pos":"n.","meaning":"焦点;聚焦状态","definition":"the point where light converges or an image is sharp","examples":[{"en":"Adjust the lens until the image is in focus.","zh":"调整镜头直到图像清晰。"},{"en":"The diagram shows the mirror's focus.","zh":"图中标出了镜子的焦点。"}]},{"pos":"n.","meaning":"重点;中心","definition":"the main subject of attention or activity","examples":[{"en":"Safety is the focus of the meeting.","zh":"安全是会议重点。"},{"en":"The new library became a focus for community life.","zh":"新图书馆成为社区生活的中心。"}]}],"foetus":[{"pos":"n.","meaning":"胎儿","definition":"an unborn developing baby after the embryonic stage","examples":[{"en":"The scan showed the position of the foetus.","zh":"扫描显示了胎儿的位置。"},{"en":"The chapter describes growth of the foetus.","zh":"本章描述胎儿的生长。"}]}],"foil":[{"pos":"n.","meaning":"箔；金属箔纸","definition":"Metal made into a very thin sheet.","examples":[{"en":"Wrap the potatoes in foil before baking them.","zh":"烤土豆前先用箔纸包好。"},{"en":"The chocolate was covered in gold-coloured foil.","zh":"巧克力外面包着金色箔纸。"}]}],"fold":[{"pos":"v.","meaning":"折叠","definition":"to bend something so one part covers another","examples":[{"en":"Fold the paper in half.","zh":"把纸对折。"},{"en":"She folded the blanket neatly.","zh":"她把毯子叠得整整齐齐。"}]},{"pos":"n.","meaning":"褶皱;折痕","definition":"a bend or crease in a material","examples":[{"en":"Dust collected in the curtain's folds.","zh":"灰尘积在窗帘褶皱里。"},{"en":"Press along the fold with your finger.","zh":"用手指沿折痕按压。"}]}],"for instance":[{"pos":"phrase","meaning":"例如；比如","definition":"used to introduce an example","examples":[{"en":"Some birds, for instance swallows, migrate seasonally.","zh":"一些鸟类，例如燕子，会季节性迁徙。"},{"en":"You could reuse containers, for instance by storing seeds in them.","zh":"你可以重复利用容器，例如用它们储存种子。"}]}],"for the sake of":[{"pos":"prep.","meaning":"为了；为了……的利益","definition":"For the purpose or benefit of someone or something.","examples":[{"en":"They postponed the argument for the sake of the children.","zh":"为了孩子，他们暂时搁置了争论。"},{"en":"For the sake of clarity, the report uses simple diagrams.","zh":"为了表达清楚，报告使用了简单图示。"}]}],"force":[{"pos":"v.","meaning":"强迫;迫使","definition":"to make someone act against their wishes","examples":[{"en":"They forced him to leave.","zh":"他们强迫他离开。"},{"en":"Heavy rain forced the match indoors.","zh":"大雨迫使比赛移至室内。"}]},{"pos":"n.","meaning":"力;力量;武力","definition":"physical power or an influence causing movement","examples":[{"en":"The impact's force broke the window.","zh":"撞击的力量打碎了窗户。"},{"en":"The police used force to enter.","zh":"警察使用强力破门进入。"}]},{"pos":"n.","meaning":"影响力;推动力","definition":"power that shapes events or behaviour","examples":[{"en":"She became a force for educational reform.","zh":"她成为推动教育改革的力量。"},{"en":"Economic forces changed the town's character.","zh":"经济力量改变了这个镇的面貌。"}]},{"pos":"n.","meaning":"军队;部队","definition":"an organized military group","examples":[{"en":"The armed forces evacuated the village.","zh":"军队疏散了村民。"},{"en":"A peacekeeping force guarded the border.","zh":"一支维和部队守卫着边境。"}]}],"forecast":[{"pos":"n.","meaning":"预报；预测","definition":"a statement of what is likely to happen","examples":[{"en":"The weather forecast predicts heavy rain.","zh":"天气预报预测有大雨。"},{"en":"The sales forecast proved too optimistic.","zh":"销售预测结果过于乐观。"}]},{"pos":"v.","meaning":"预测；预报","definition":"to say what is likely to happen","examples":[{"en":"Experts forecast a rise in demand.","zh":"专家预测需求会上升。"},{"en":"The system forecasts river levels.","zh":"该系统预测河流水位。"}]}],"foreland":[{"pos":"n.","meaning":"岬角；伸入水中的陆地","definition":"A piece of land extending into the sea or a lake.","examples":[{"en":"The lighthouse stands on a rocky foreland.","zh":"灯塔矗立在岩石岬角上。"},{"en":"From the boat, we could see waves breaking around the foreland.","zh":"从船上可以看见海浪在岬角周围破碎。"}]},{"pos":"n.","meaning":"前陆；山脉前缘地区","definition":"The land lying in front of a mountain range or other raised region.","examples":[{"en":"The expedition crossed the glacial foreland before reaching the ice.","zh":"探险队穿过冰川前缘地区后抵达冰面。"},{"en":"Several rivers carry sediment across the mountain foreland.","zh":"几条河流携带泥沙流经山脉前陆地区。"}]}],"foremost":[{"pos":"adj.","meaning":"最重要的;最优秀的","definition":"leading in importance or achievement","examples":[{"en":"Safety is our foremost concern.","zh":"安全是我们最重要的考虑。"},{"en":"She is one of the country's foremost scientists.","zh":"她是这个国家最杰出的科学家之一。"}]}],"foresee":[{"pos":"v.","meaning":"预见；预知","definition":"to know or imagine something before it happens","examples":[{"en":"Nobody foresaw the sudden change.","zh":"没有人预见到这场突然的变化。"},{"en":"We foresee difficulties in obtaining the materials.","zh":"我们预见到获取材料会有困难。"}]}],"foreseeable":[{"pos":"adj.","meaning":"可预见的；可预测的","definition":"Able to be reasonably expected in advance.","examples":[{"en":"The bridge will remain closed for the foreseeable future.","zh":"在可预见的未来，这座桥仍将关闭。"},{"en":"The company failed to prepare for foreseeable delays.","zh":"公司没有为可预见的延误做好准备。"}]}],"forfeit":[{"pos":"v.","meaning":"被没收;丧失","definition":"to lose something as a penalty or consequence","examples":[{"en":"Late cancellation means you forfeit the deposit.","zh":"逾期取消意味着押金被没收。"},{"en":"His dishonesty forfeited the team's trust.","zh":"他的不诚实使他失去了团队信任。"}]},{"pos":"n.","meaning":"罚金;罚物;代价","definition":"something surrendered as a penalty","examples":[{"en":"The losing player paid a small forfeit.","zh":"输掉的玩家交了一点罚金。"},{"en":"The deposit served as a forfeit for cancellation.","zh":"押金在取消时充当罚金。"}]}],"forgo":[{"pos":"v.","meaning":"放弃；舍弃","definition":"to choose to do without something","examples":[{"en":"She decided to forgo the expensive trip.","zh":"她决定放弃这次昂贵的旅行。"},{"en":"We forwent dessert to catch the train.","zh":"我们没吃甜点，以便赶上火车。"}]}],"form":[{"pos":"n.","meaning":"形式；类型","definition":"A particular kind or way in which something exists.","examples":[{"en":"Cycling is a convenient form of exercise.","zh":"骑自行车是一种方便的锻炼方式。"},{"en":"The data can be presented in several forms.","zh":"这些数据可以用几种形式呈现。"}]},{"pos":"n.","meaning":"外形；形状","definition":"The visible shape or structure of something.","examples":[{"en":"A dark form moved behind the curtain.","zh":"一个黑色身影在窗帘后移动。"},{"en":"The sculpture follows the natural form of the stone.","zh":"这座雕塑顺应了石材的自然形状。"}]},{"pos":"n.","meaning":"表格","definition":"A document with spaces for information.","examples":[{"en":"Please complete the registration form in capital letters.","zh":"请用大写字母填写登记表。"},{"en":"She attached a photograph to the application form.","zh":"她在申请表上附了一张照片。"}]},{"pos":"v.","meaning":"形成；构成；组建","definition":"To come into existence or arrange parts into a whole.","examples":[{"en":"Ice began to form on the surface of the pond.","zh":"池塘表面开始结冰。"},{"en":"The students formed a group to clean up the beach.","zh":"学生们组建了一个小组来清理海滩。"}]}],"formal":[{"pos":"adj.","meaning":"正式的;正规的;合乎礼仪的","definition":"following established rules or official procedures","examples":[{"en":"We received a formal invitation.","zh":"我们收到了正式邀请。"},{"en":"He wore a dark suit to the formal dinner.","zh":"他穿深色西装出席正式晚宴。"}]}],"formality":[{"pos":"n.","meaning":"礼节；拘礼；正式性","definition":"careful observance of accepted rules or manners","examples":[{"en":"The meeting began without much formality.","zh":"会议开始时没有太多礼节。"},{"en":"The occasion demanded a degree of formality.","zh":"这个场合要求一定的正式程度。"}]},{"pos":"n.","meaning":"例行手续；必须履行的程序","definition":"an action required by rules or custom","examples":[{"en":"Signing the form is a necessary formality.","zh":"签署表格是必要手续。"},{"en":"We completed the border formalities quickly.","zh":"我们很快办完了过境手续。"}]}],"format":[{"pos":"n.","meaning":"格式；版式；安排方式","definition":"The layout or structure in which something is organised.","examples":[{"en":"The magazine has adopted a larger format.","zh":"这本杂志采用了更大的版式。"},{"en":"The interview followed a question-and-answer format.","zh":"面试采用问答形式。"}]},{"pos":"v.","meaning":"设置格式；格式化","definition":"To arrange data or prepare a storage device for use.","examples":[{"en":"Please format the headings consistently throughout the document.","zh":"请统一整篇文档中的标题格式。"},{"en":"The technician formatted the empty drive before installing the software.","zh":"技术人员在安装软件之前格式化了空硬盘。"}]}],"former":[{"pos":"adj.","meaning":"以前的;从前的","definition":"belonging to an earlier time","examples":[{"en":"The former factory is now a museum.","zh":"以前的工厂现在是一座博物馆。"},{"en":"I met a former colleague yesterday.","zh":"我昨天遇到了一位以前的同事。"}]},{"pos":"pron.","meaning":"前者","definition":"the first of two things already mentioned","examples":[{"en":"Tea and coffee are available; I prefer the former.","zh":"茶和咖啡都有，我更喜欢前者。"},{"en":"Of speed and accuracy, the former matters less here.","zh":"在速度与准确性两者中，这里前者较不重要。"}]}],"formidable":[{"pos":"adj.","meaning":"难对付的；令人生畏的","definition":"very difficult or impressive enough to cause fear","examples":[{"en":"The team faces a formidable opponent.","zh":"球队面临强大的对手。"},{"en":"Restoring the entire archive is a formidable task.","zh":"修复整个档案库是一项艰巨的任务。"}]}],"formula":[{"pos":"n.","meaning":"公式","definition":"A mathematical expression showing a rule or relationship.","examples":[{"en":"Use this formula to calculate the area of the circle.","zh":"用这个公式计算圆的面积。"},{"en":"The engineer checked the formula before entering the values.","zh":"工程师在代入数值前检查了公式。"}]},{"pos":"n.","meaning":"配方","definition":"A list of ingredients and their required amounts.","examples":[{"en":"The company keeps its perfume formula secret.","zh":"公司对香水配方保密。"},{"en":"The baker adjusted the formula to reduce the sugar content.","zh":"面包师调整配方以减少糖分。"}]},{"pos":"n.","meaning":"准则；成功方法；惯用模式","definition":"An established method or set of rules for achieving a result.","examples":[{"en":"There is no single formula for a successful career.","zh":"事业成功没有单一秘诀。"},{"en":"The programme repeats the same formula every week.","zh":"这个节目每周都重复同一种模式。"}]}],"formulate":[{"pos":"v.","meaning":"制定;构想","definition":"to develop a plan or method carefully","examples":[{"en":"The team formulated a recovery plan.","zh":"团队制定了恢复计划。"},{"en":"Scientists formulated a new hypothesis.","zh":"科学家提出了一个新假设。"}]},{"pos":"v.","meaning":"明确表达;系统阐述","definition":"to express an idea precisely","examples":[{"en":"She struggled to formulate her objections.","zh":"她难以明确表达自己的反对意见。"},{"en":"Please formulate the question more clearly.","zh":"请把问题表述得更清楚。"}]}],"formulation":[{"pos":"n.","meaning":"制定；构想；公式化表达","definition":"the process of creating a plan or expressing an idea precisely","examples":[{"en":"Residents contributed to the formulation of the policy.","zh":"居民参与了政策制定。"},{"en":"The mathematical formulation simplifies the problem.","zh":"用数学公式表达使问题简化了。"}]},{"pos":"n.","meaning":"表述方式；确切表述","definition":"a particular way of expressing an idea","examples":[{"en":"Her formulation of the question was unusually clear.","zh":"她对问题的表述格外清晰。"},{"en":"The committee preferred a more cautious formulation.","zh":"委员会偏好更审慎的措辞。"}]}],"forth":[{"pos":"adv.","meaning":"向前；向外；离去","definition":"Forward or outward from a place.","examples":[{"en":"The explorers set forth at sunrise.","zh":"探险者在日出时出发了。"},{"en":"The fountain sent forth a stream of clear water.","zh":"喷泉喷出一股清水。"}]}],"forthcoming":[{"pos":"adj.","meaning":"即将到来的","definition":"due to happen soon","examples":[{"en":"The forthcoming conference will address climate policy.","zh":"即将召开的会议将讨论气候政策。"},{"en":"Details appear in his forthcoming book.","zh":"详细内容见他即将出版的书。"}]}],"fortnight":[{"pos":"n.","meaning":"两星期；十四天","definition":"a period of two weeks","examples":[{"en":"The exhibition runs for a fortnight.","zh":"展览持续两周。"},{"en":"We meet every fortnight to review progress.","zh":"我们每两周开会检查进展。"}]}],"forum":[{"pos":"n.","meaning":"论坛；讨论会；讨论平台","definition":"A meeting or place where ideas and opinions are exchanged.","examples":[{"en":"The school held a forum on student wellbeing.","zh":"学校举办了一场关于学生身心健康的讨论会。"},{"en":"Members share practical advice on the online forum.","zh":"会员在网络论坛上分享实用建议。"}]}],"fossil":[{"pos":"n.","meaning":"化石","definition":"preserved remains or traces of ancient organisms","examples":[{"en":"The fossil revealed the animal's teeth.","zh":"化石显露出这种动物的牙齿。"},{"en":"Children searched the rocks for fossils.","zh":"孩子们在岩石中寻找化石。"}]},{"pos":"n.","meaning":"老顽固;思想陈旧的人","definition":"a person considered old-fashioned and resistant to change","examples":[{"en":"The young artists dismissed him as an old fossil.","zh":"年轻艺术家把他视为老顽固。"},{"en":"He refused to become a fossil who rejected new ideas.","zh":"他不愿成为拒绝新思想的老顽固。"}]}],"foster":[{"pos":"v.","meaning":"培养；促进","definition":"to encourage the development of something","examples":[{"en":"Shared projects foster cooperation.","zh":"共同项目促进合作。"},{"en":"The teacher fosters curiosity through experiments.","zh":"教师通过实验培养好奇心。"}]},{"pos":"v.","meaning":"寄养；代为抚养","definition":"to care for a child who is not one's own, usually temporarily","examples":[{"en":"The couple fostered two children.","zh":"这对夫妇寄养了两个孩子。"},{"en":"She began fostering after training with the agency.","zh":"她接受机构培训后开始承担寄养工作。"}]},{"pos":"adj.","meaning":"寄养的；代养的","definition":"relating to the care of a child by nonparents","examples":[{"en":"The child stayed with a foster family.","zh":"孩子住在寄养家庭。"},{"en":"His foster parents supported his education.","zh":"他的寄养父母支持他接受教育。"}]}],"foul":[{"pos":"adj.","meaning":"恶臭的；污秽的","definition":"Very unpleasant in smell, taste, or cleanliness.","examples":[{"en":"A foul smell came from the blocked drain.","zh":"堵塞的排水沟散发出恶臭。"},{"en":"The river was foul with untreated waste.","zh":"河流被未经处理的废物污染得污秽不堪。"}]},{"pos":"adj.","meaning":"邪恶的；卑劣的；令人厌恶的","definition":"Morally bad or extremely unpleasant.","examples":[{"en":"The detective suspected foul play.","zh":"侦探怀疑有人实施了犯罪行为。"},{"en":"His foul language upset the other passengers.","zh":"他的污言秽语令其他乘客不快。"}]},{"pos":"n.","meaning":"犯规","definition":"An action that breaks the rules of a sport.","examples":[{"en":"The referee awarded a penalty after the foul.","zh":"裁判在这次犯规后判罚了点球。"},{"en":"She was sent off for a second serious foul.","zh":"她因第二次严重犯规被罚下场。"}]}],"foundation":[{"pos":"n.","meaning":"基础;根据","definition":"the basis supporting an idea or activity","examples":[{"en":"Trust is the foundation of their partnership.","zh":"信任是他们合作的基础。"},{"en":"The accusation has no foundation in fact.","zh":"这项指控毫无事实依据。"}]},{"pos":"n.","meaning":"地基;基础结构","definition":"the structure supporting a building","examples":[{"en":"Workers poured concrete for the foundations.","zh":"工人浇筑混凝土地基。"},{"en":"Cracks appeared in the house's foundation.","zh":"房屋地基出现了裂缝。"}]},{"pos":"n.","meaning":"创建;成立","definition":"the act of establishing an organization","examples":[{"en":"The college celebrated its foundation a century ago.","zh":"学院纪念一百年前的创立。"},{"en":"The archive records the foundation of the society.","zh":"档案记录了协会的成立。"}]},{"pos":"n.","meaning":"基金会","definition":"an organization supporting charitable or educational work","examples":[{"en":"The foundation funds medical research.","zh":"这家基金会资助医学研究。"},{"en":"She applied to a foundation for a grant.","zh":"她向一家基金会申请了资助。"}]}],"fountain":[{"pos":"n.","meaning":"喷泉","definition":"a structure that sends water into the air","examples":[{"en":"Children gathered around the fountain.","zh":"孩子们聚集在喷泉周围。"},{"en":"The fountain is illuminated at night.","zh":"喷泉在夜间有灯光照明。"}]}],"fraction":[{"pos":"n.","meaning":"小部分；少量","definition":"A small part of a larger amount.","examples":[{"en":"Only a fraction of the tickets remained unsold.","zh":"只有少量门票尚未售出。"},{"en":"The repair cost a fraction of the price of a new machine.","zh":"维修费用仅相当于新机器价格的一小部分。"}]},{"pos":"n.","meaning":"分数","definition":"A number representing part of a whole.","examples":[{"en":"Write one quarter as a fraction.","zh":"把四分之一写成分数。"},{"en":"The teacher showed us how to add fractions with different denominators.","zh":"老师教我们如何将不同分母的分数相加。"}]}],"fracture":[{"pos":"n.","meaning":"断裂;骨折","definition":"a break in a hard material or bone","examples":[{"en":"The X-ray revealed a wrist fracture.","zh":"X 光片显示手腕骨折。"},{"en":"A small fracture weakened the metal frame.","zh":"一道小裂缝削弱了金属框架。"}]},{"pos":"v.","meaning":"断裂;折断","definition":"to break or cause to break","examples":[{"en":"She fractured her ankle while skiing.","zh":"她滑雪时脚踝骨折了。"},{"en":"The rock fractured under pressure.","zh":"岩石在压力下断裂。"}]}],"fragile":[{"pos":"adj.","meaning":"易碎的；脆弱的","definition":"easily broken or damaged","examples":[{"en":"Wrap the fragile glasses carefully.","zh":"仔细包好易碎的玻璃杯。"},{"en":"The peace agreement remains fragile.","zh":"和平协议仍然脆弱。"}]},{"pos":"adj.","meaning":"虚弱的；易受伤害的","definition":"physically or emotionally delicate","examples":[{"en":"She felt fragile after the illness.","zh":"病后她感到身体虚弱。"},{"en":"The young plants were too fragile to move.","zh":"幼苗太脆弱，不能移植。"}]}],"fragment":[{"pos":"n.","meaning":"碎片；片段","definition":"A small piece broken off or separated from something.","examples":[{"en":"Fragments of pottery lay beside the old wall.","zh":"旧墙旁散落着陶器碎片。"},{"en":"Only a fragment of the recording survived.","zh":"只有一小段录音保存了下来。"}],"ipa":"/ˈfræɡmənt/"},{"pos":"v.","meaning":"使分裂；破碎","definition":"To break or divide into smaller parts.","examples":[{"en":"The rock fragmented when it struck the ground.","zh":"岩石落地时碎裂了。"},{"en":"The movement fragmented into several competing groups.","zh":"这场运动分裂成几个相互竞争的团体。"}],"ipa":"/fræɡˈment/"}],"fragrance":[{"pos":"n.","meaning":"芳香;香味","definition":"a pleasant smell","examples":[{"en":"The fragrance of roses filled the room.","zh":"玫瑰的芳香充满房间。"},{"en":"Fresh bread gives off a warm fragrance.","zh":"新鲜面包散发着温暖的香气。"}]},{"pos":"n.","meaning":"香水;香料产品","definition":"a scented product worn on the body","examples":[{"en":"She chose a light citrus fragrance.","zh":"她选了一款清淡的柑橘香水。"},{"en":"The shop sells several luxury fragrances.","zh":"这家店出售几种高档香水。"}]}],"frame":[{"pos":"n.","meaning":"框架；边框","definition":"a supporting or surrounding structure","examples":[{"en":"The bicycle has a lightweight frame.","zh":"自行车有轻巧的车架。"},{"en":"The photograph sits in a wooden frame.","zh":"照片装在木框里。"}]},{"pos":"v.","meaning":"给……镶框","definition":"to put something inside a frame","examples":[{"en":"She framed the old family photograph.","zh":"她给老家庭照片镶了框。"},{"en":"The gallery will frame the drawings.","zh":"画廊将给这些画装框。"}]}],"frank":[{"pos":"adj.","meaning":"坦率的；直言不讳的","definition":"Honest and direct in expressing an opinion.","examples":[{"en":"We had a frank discussion about the project's weaknesses.","zh":"我们坦诚地讨论了项目的不足。"},{"en":"To be frank, I do not think this proposal is affordable.","zh":"坦白说，我认为这项提议的费用难以承受。"}]}],"fraud":[{"pos":"n.","meaning":"诈骗;欺诈","definition":"dishonest action intended to gain money or advantage","examples":[{"en":"The accountant was convicted of fraud.","zh":"会计被判犯有诈骗罪。"},{"en":"Banks monitor transactions for signs of fraud.","zh":"银行监控交易中的欺诈迹象。"}]},{"pos":"n.","meaning":"骗子;冒牌货","definition":"a person or thing falsely presented as genuine","examples":[{"en":"The supposed expert turned out to be a fraud.","zh":"所谓的专家原来是个骗子。"},{"en":"The valuable painting was exposed as a fraud.","zh":"那幅珍贵画作被揭穿是赝品。"}]}],"fraught":[{"pos":"adj.","meaning":"充满……的（常接 with）","definition":"filled with problems or risks","examples":[{"en":"The journey was fraught with danger.","zh":"旅程充满危险。"},{"en":"The negotiations were fraught with difficulties.","zh":"谈判困难重重。"}]},{"pos":"adj.","meaning":"焦虑的；紧张的","definition":"anxious or emotionally tense","examples":[{"en":"It had been a fraught morning.","zh":"那是一个令人紧张的早晨。"},{"en":"Their conversation became increasingly fraught.","zh":"他们的交谈越来越紧张。"}]}],"freefone":[{"pos":"n.","meaning":"免费电话服务；免费电话号码","definition":"A telephone service in which the receiver pays for the call.","examples":[{"en":"Customers can contact the company on its freefone number.","zh":"顾客可以拨打公司的免费电话号码联系公司。"},{"en":"The leaflet gives a freefone number for ordering information packs.","zh":"宣传单上提供了索取资料包的免费电话号码。"}]}],"freight":[{"pos":"n.","meaning":"货物;货运","definition":"goods transported in bulk or their transport","examples":[{"en":"The railway carries heavy freight.","zh":"铁路运输重型货物。"},{"en":"Air freight costs more than sea transport.","zh":"航空货运比海运贵。"}]},{"pos":"v.","meaning":"货运;运送货物","definition":"to transport goods","examples":[{"en":"The equipment was freighted across the ocean.","zh":"设备被运过大洋。"},{"en":"They freight fresh flowers to overseas markets.","zh":"他们把鲜花运往海外市场。"}]}],"frequency":[{"pos":"n.","meaning":"频繁程度；发生率","definition":"how often something happens","examples":[{"en":"The frequency of bus services has increased.","zh":"公交班次增加了。"},{"en":"Researchers recorded the frequency of each error.","zh":"研究人员记录了每种错误的发生频率。"}]},{"pos":"n.","meaning":"频率（每秒振动或波动次数）","definition":"the rate of repeated vibrations or waves","examples":[{"en":"The radio receives signals at this frequency.","zh":"收音机接收这一频率的信号。"},{"en":"Higher frequency produces a higher musical pitch.","zh":"更高频率产生更高的音调。"}]}],"frequent":[{"pos":"adj.","meaning":"频繁的；经常发生的；常见的","definition":"Happening often or appearing regularly.","examples":[{"en":"Frequent interruptions made it hard to concentrate.","zh":"频繁的打断让人难以集中注意力。"},{"en":"She is a frequent visitor to the local museum.","zh":"她经常参观当地博物馆。"}]}],"friction":[{"pos":"n.","meaning":"摩擦;摩擦力","definition":"resistance when surfaces move against each other","examples":[{"en":"Oil reduces friction between moving parts.","zh":"润滑油减少运动部件之间的摩擦。"},{"en":"Friction warmed her hands as she rubbed them.","zh":"她搓手时摩擦使双手暖了起来。"}]},{"pos":"n.","meaning":"冲突;不和","definition":"disagreement or tension between people","examples":[{"en":"Money caused friction between the partners.","zh":"钱的问题导致合伙人之间产生矛盾。"},{"en":"Clear responsibilities reduced friction within the team.","zh":"明确职责减少了团队内部摩擦。"}]}],"frightened":[{"pos":"adj.","meaning":"害怕的；受惊的","definition":"feeling fear","examples":[{"en":"The frightened child held her mother's hand.","zh":"受惊的孩子握住母亲的手。"},{"en":"He was frightened by the sudden noise.","zh":"他被突如其来的噪声吓到了。"}]}],"frock":[{"pos":"n.","meaning":"连衣裙（旧式用语）","definition":"A dress, especially in old-fashioned usage.","examples":[{"en":"The little girl wore a yellow frock to the party.","zh":"小女孩穿着黄色连衣裙参加聚会。"},{"en":"She found her grandmother's silk frock in an old trunk.","zh":"她在旧箱子里找到了祖母的丝绸连衣裙。"}]},{"pos":"n.","meaning":"宽松罩衫；长袍（旧式服装）","definition":"A loose outer garment formerly worn by workers or monks.","examples":[{"en":"The museum displays a shepherd's coarse linen frock.","zh":"博物馆展出了一件牧羊人的粗麻罩衫。"},{"en":"In the painting, the monk wears a plain brown frock.","zh":"画中的修士穿着朴素的棕色长袍。"}]}],"front-line":[{"pos":"adj.","meaning":"前线的;一线的","definition":"directly involved in fighting or delivering a service","examples":[{"en":"Front-line troops received additional supplies.","zh":"前线部队获得了额外补给。"},{"en":"Front-line nurses helped design the new procedure.","zh":"一线护士参与制定了新流程。"}]}],"frontier":[{"pos":"n.","meaning":"边境；边界","definition":"a border between countries","examples":[{"en":"The train crossed the frontier at dawn.","zh":"列车在黎明时越过边境。"},{"en":"A checkpoint stood near the frontier.","zh":"边境附近有一个检查站。"}]},{"pos":"n.","meaning":"开发地区的边缘地带","definition":"the outer edge of settled or developed land","examples":[{"en":"The museum explores life on the frontier.","zh":"博物馆探讨边疆拓殖地的生活。"},{"en":"Settlements spread along the western frontier.","zh":"定居点沿着西部边疆扩展。"}]},{"pos":"n.","meaning":"前沿；新领域","definition":"the limit of knowledge or achievement","examples":[{"en":"The laboratory works at the frontiers of neuroscience.","zh":"实验室从事神经科学前沿研究。"},{"en":"Ocean exploration is opening new frontiers.","zh":"海洋探索正在开辟新领域。"}]}],"frown":[{"pos":"v.","meaning":"皱眉","definition":"To draw the eyebrows together because of worry, anger, or concentration.","examples":[{"en":"She frowned when she read the unexpected bill.","zh":"她读到这张意外的账单时皱起了眉。"},{"en":"He frowned at the confusing instructions.","zh":"他看着令人费解的说明皱起了眉头。"}]}],"fruitful":[{"pos":"adj.","meaning":"富有成效的;多产的","definition":"producing useful results or abundant growth","examples":[{"en":"The discussion proved fruitful.","zh":"讨论取得了成果。"},{"en":"The orchard enjoyed a fruitful season.","zh":"果园迎来了丰收季。"}]}],"frustrate":[{"pos":"v.","meaning":"使沮丧；使懊恼","definition":"to make someone upset by preventing progress","examples":[{"en":"Repeated cancellations frustrated the passengers.","zh":"反复取消让乘客感到懊恼。"},{"en":"The slow connection frustrated her.","zh":"缓慢的网络连接令她烦恼。"}]},{"pos":"v.","meaning":"挫败；阻碍","definition":"to prevent a plan from succeeding","examples":[{"en":"Bad weather frustrated their plans.","zh":"坏天气使他们的计划受挫。"},{"en":"Security measures frustrated the attempted theft.","zh":"安全措施挫败了盗窃企图。"}]}],"frustrating":[{"pos":"adj.","meaning":"令人沮丧的；使人受挫的","definition":"Causing annoyance because progress or success is prevented.","examples":[{"en":"It is frustrating to lose work because of a power cut.","zh":"因停电而丢失工作成果令人沮丧。"},{"en":"The team endured a frustrating series of delays.","zh":"团队经历了一连串令人泄气的延误。"}]}],"frustration":[{"pos":"n.","meaning":"沮丧;挫败感;不满","definition":"annoyance caused by difficulty or blocked progress","examples":[{"en":"She sighed in frustration at the error.","zh":"面对错误她沮丧地叹了口气。"},{"en":"Long delays caused widespread frustration.","zh":"长时间延误引发普遍不满。"}]}],"fuel":[{"pos":"n.","meaning":"燃料","definition":"a substance burned to produce energy","examples":[{"en":"The generator needs more fuel.","zh":"发电机需要更多燃料。"},{"en":"Wood was the village's main cooking fuel.","zh":"木材是村庄主要的烹饪燃料。"}]},{"pos":"v.","meaning":"给……加燃料","definition":"to supply fuel to something","examples":[{"en":"Workers fuelled the aircraft before departure.","zh":"工作人员在起飞前给飞机加油。"},{"en":"Dry branches fuelled the campfire.","zh":"干树枝为篝火提供了燃料。"}]}],"fulfil":[{"pos":"v.","meaning":"实现；完成；履行","definition":"To achieve something or carry out an obligation.","examples":[{"en":"The scholarship helped her fulfil her ambition to study abroad.","zh":"奖学金帮助她实现了出国留学的志向。"},{"en":"The supplier failed to fulfil the contract.","zh":"供应商未能履行合同。"}]},{"pos":"v.","meaning":"满足；符合","definition":"To meet a need, condition, or requirement.","examples":[{"en":"The course fulfils the entry requirements for the degree.","zh":"这门课程满足该学位的入学要求。"},{"en":"The new centre fulfils an urgent need for childcare.","zh":"新中心满足了迫切的托儿需求。"}]}],"fulfillment":[{"pos":"n.","meaning":"履行;实现","definition":"the completion of a duty or achievement of a wish","examples":[{"en":"The contract requires fulfillment of several conditions.","zh":"合同要求履行几项条件。"},{"en":"Graduation marked the fulfillment of a childhood dream.","zh":"毕业标志着童年梦想的实现。"}]},{"pos":"n.","meaning":"满足感;成就感","definition":"deep satisfaction from meaningful achievement","examples":[{"en":"Teaching gives him a sense of fulfillment.","zh":"教学给他带来成就感。"},{"en":"She found fulfillment in helping others.","zh":"她在帮助别人中获得满足感。"}]}],"fumes":[{"pos":"n.","meaning":"烟气；有害气体","definition":"strong-smelling or harmful gases","examples":[{"en":"Paint fumes filled the room.","zh":"油漆气味充满了房间。"},{"en":"The fan removes fumes from the workshop.","zh":"风扇排出车间的烟气。"}]}],"function":[{"pos":"v.","meaning":"运转；起作用","definition":"To work or operate in the intended way.","examples":[{"en":"The lift is functioning normally again.","zh":"电梯又恢复正常运行了。"},{"en":"The old hall now functions as a community cinema.","zh":"旧礼堂现在用作社区影院。"}]},{"pos":"n.","meaning":"功能；作用；职责","definition":"The purpose or job of a person or thing.","examples":[{"en":"The main function of the roots is to absorb water.","zh":"根的主要功能是吸收水分。"},{"en":"Organising the meeting is one of my administrative functions.","zh":"组织会议是我的行政职责之一。"}]},{"pos":"n.","meaning":"函数","definition":"A mathematical relationship assigning an output to each input.","examples":[{"en":"The graph represents a function of time.","zh":"这张图表示一个以时间为变量的函数。"},{"en":"We calculated the value of the function at zero.","zh":"我们计算了这个函数在零点的值。"}]}],"fund":[{"pos":"n.","meaning":"基金;专款","definition":"money saved or collected for a particular purpose","examples":[{"en":"They established a scholarship fund.","zh":"他们设立了奖学金基金。"},{"en":"The emergency fund covered the repairs.","zh":"应急基金支付了维修费用。"}]},{"pos":"n.","meaning":"资金;存款","definition":"money available for use","examples":[{"en":"The project ran out of funds.","zh":"项目耗尽了资金。"},{"en":"We lack the funds to expand.","zh":"我们缺少扩张所需的资金。"}]},{"pos":"n.","meaning":"储备;蕴藏","definition":"a large supply of something useful","examples":[{"en":"She has a fund of amusing stories.","zh":"她有说不完的有趣故事。"},{"en":"His experience gave him a fund of practical knowledge.","zh":"经验让他积累了丰富实用知识。"}]},{"pos":"v.","meaning":"资助;拨款","definition":"to provide money for something","examples":[{"en":"Local businesses funded the playground.","zh":"当地企业资助了游乐场。"},{"en":"The charity funds research into rare diseases.","zh":"慈善机构资助罕见病研究。"}]}],"fundamental":[{"pos":"adj.","meaning":"基本的；根本的","definition":"forming an essential basis","examples":[{"en":"Trust is fundamental to the partnership.","zh":"信任是合作关系的基础。"},{"en":"The discovery raised fundamental questions.","zh":"这一发现提出了根本问题。"}]},{"pos":"n.","meaning":"基本原理；基础知识（常用复数）","definition":"a basic principle or skill","examples":[{"en":"The course teaches the fundamentals of accounting.","zh":"课程教授会计基础知识。"},{"en":"Master the fundamentals before attempting complex designs.","zh":"在尝试复杂设计前掌握基本原理。"}]}],"furious":[{"pos":"adj.","meaning":"狂怒的；极其愤怒的","definition":"Extremely angry.","examples":[{"en":"She was furious when she discovered the damage.","zh":"她发现损坏情况后怒不可遏。"},{"en":"The customers grew furious after waiting for two hours.","zh":"等了两个小时后，顾客们变得非常愤怒。"}]},{"pos":"adj.","meaning":"猛烈的；激烈的","definition":"Involving great force, speed, or intensity.","examples":[{"en":"A furious storm battered the coast.","zh":"一场猛烈的风暴袭击了海岸。"},{"en":"The decision sparked a furious debate in parliament.","zh":"这个决定在议会中引发了激烈辩论。"}]}],"furnace":[{"pos":"n.","meaning":"熔炉;锅炉","definition":"an enclosed structure producing intense heat","examples":[{"en":"The furnace melts scrap metal.","zh":"熔炉熔化废金属。"},{"en":"A gas furnace heats the building.","zh":"燃气炉为大楼供暖。"}]}],"furnish":[{"pos":"v.","meaning":"为……配备家具","definition":"to supply furniture for a room or building","examples":[{"en":"They furnished the flat with second-hand furniture.","zh":"他们用二手家具布置公寓。"},{"en":"The landlord furnished the bedroom simply.","zh":"房东简单布置了卧室家具。"}]},{"pos":"v.","meaning":"提供；供应；装备","definition":"to provide something needed","examples":[{"en":"Please furnish us with further details.","zh":"请向我们提供更多细节。"},{"en":"The archive furnished evidence for her argument.","zh":"档案为她的论点提供了证据。"}]}],"furnished":[{"pos":"adj.","meaning":"配备家具的","definition":"provided with furniture","examples":[{"en":"We rented a furnished flat near the office.","zh":"我们在办公室附近租了一套带家具的公寓。"},{"en":"Is the room furnished or empty?","zh":"这个房间带家具还是空的？"},{"en":"A furnished apartment can save you the cost of buying a bed.","zh":"带家具的公寓可以省去买床的费用。"}]}],"furniture":[{"pos":"n.","meaning":"家具","definition":"movable objects such as chairs and tables","examples":[{"en":"The room contains very little furniture.","zh":"房间里家具很少。"},{"en":"They make furniture from recycled wood.","zh":"他们用回收木材制作家具。"}]}],"fuse":[{"pos":"n.","meaning":"保险丝；熔断器","definition":"a safety device that interrupts excessive electric current","examples":[{"en":"A blown fuse stopped the lights working.","zh":"保险丝熔断导致灯不亮了。"},{"en":"The electrician checked the fuse box.","zh":"电工检查了保险丝盒。"}]},{"pos":"v.","meaning":"熔合；融合","definition":"to join together through heat or combine closely","examples":[{"en":"Heat fused the glass pieces together.","zh":"热量使玻璃片熔合在一起。"},{"en":"The music fuses jazz with folk traditions.","zh":"这种音乐融合爵士与民间传统。"}]},{"pos":"v.","meaning":"熔化；因保险丝熔断而断电","definition":"to melt or stop working when a fuse fails","examples":[{"en":"The wire fused under the excessive current.","zh":"过大的电流使导线熔化了。"},{"en":"The lights fused when the old heater was switched on.","zh":"打开旧暖气时，保险丝熔断，灯灭了。"}]}],"fusion":[{"pos":"n.","meaning":"熔合；融合","definition":"The joining of things into a single whole.","examples":[{"en":"The design is a fusion of traditional and modern styles.","zh":"这个设计融合了传统与现代风格。"},{"en":"Heat caused the fusion of the two metal surfaces.","zh":"高温使两个金属表面熔合在一起。"}]},{"pos":"n.","meaning":"核聚变","definition":"The joining of light atomic nuclei to form heavier nuclei.","examples":[{"en":"The Sun releases energy through nuclear fusion.","zh":"太阳通过核聚变释放能量。"},{"en":"The laboratory is studying ways to control fusion reactions.","zh":"实验室正在研究控制聚变反应的方法。"}]}],"futile":[{"pos":"adj.","meaning":"无用的;徒劳的;无意义的","definition":"unable to produce a useful result","examples":[{"en":"Further attempts to repair it were futile.","zh":"进一步修理的尝试是徒劳的。"},{"en":"They wasted hours in futile arguments.","zh":"他们在无意义的争论上浪费了数小时。"}]}],"gadget":[{"pos":"n.","meaning":"小巧器械；小装置","definition":"a small useful mechanical or electronic device","examples":[{"en":"This gadget peels apples quickly.","zh":"这个小器械削苹果皮很快。"},{"en":"Her bag contained several electronic gadgets.","zh":"她的包里有几样电子小装置。"}]}],"galaxy":[{"pos":"n.","meaning":"星系；银河系","definition":"A vast group of stars, gas, and dust held together by gravity.","examples":[{"en":"The telescope detected a distant galaxy.","zh":"望远镜探测到了一个遥远的星系。"},{"en":"Our Solar System lies within the galaxy called the Milky Way.","zh":"我们的太阳系位于称为银河系的星系内。"}]},{"pos":"n.","meaning":"群英；一大批杰出人物","definition":"A large collection of famous or impressive people.","examples":[{"en":"The concert brought together a galaxy of musical talent.","zh":"音乐会汇聚了众多杰出音乐人才。"},{"en":"A galaxy of film stars attended the awards ceremony.","zh":"众多电影明星出席了颁奖典礼。"}]}],"gallery":[{"pos":"n.","meaning":"美术馆;画廊","definition":"a place where works of art are displayed","examples":[{"en":"The gallery exhibits modern sculpture.","zh":"美术馆展出现代雕塑。"},{"en":"Her photographs were sold through a small gallery.","zh":"她的照片通过一家小画廊售出。"}]}],"gallop":[{"pos":"v.","meaning":"奔驰；飞跑","definition":"to move at a horse's fastest pace","examples":[{"en":"The horses galloped across the field.","zh":"马匹飞奔穿过田野。"},{"en":"He galloped back to the farm.","zh":"他策马疾驰回农场。"}]},{"pos":"n.","meaning":"奔驰；疾驰","definition":"the fastest pace of a horse","examples":[{"en":"The rider urged the horse into a gallop.","zh":"骑手催马疾驰。"},{"en":"We heard the gallop of approaching horses.","zh":"我们听到奔近的马蹄声。"}]}],"gamble":[{"pos":"v.","meaning":"赌博；打赌","definition":"To risk money on the result of a game or uncertain event.","examples":[{"en":"He used to gamble on horse races.","zh":"他过去常赌赛马。"},{"en":"The club prohibits members from gambling for money.","zh":"俱乐部禁止会员用金钱赌博。"}]},{"pos":"v.","meaning":"冒险；投机","definition":"To take a risky action in the hope of gaining an advantage.","examples":[{"en":"The company gambled on an untested technology.","zh":"公司冒险采用了一项未经验证的技术。"},{"en":"We gambled that the weather would improve before the climb.","zh":"我们冒险期待攀登前天气会好转。"}]}],"gang":[{"pos":"n.","meaning":"一帮;团伙;一组人","definition":"a group acting together, sometimes criminally","examples":[{"en":"A gang stole bicycles from the station.","zh":"一个团伙偷了车站的自行车。"},{"en":"A gang of workers repaired the track.","zh":"一队工人修理了轨道。"}]},{"pos":"v.","meaning":"结伙;联合对付","definition":"to form a group, often against someone","examples":[{"en":"The children ganged up on the newcomer.","zh":"孩子们结伙欺负新来的孩子。"},{"en":"Several rivals ganged together to block the proposal.","zh":"几个竞争者联合起来阻挠提案。"}]}],"gather":[{"pos":"v.","meaning":"聚集；集合","definition":"to come or bring together","examples":[{"en":"Crowds gathered outside the theatre.","zh":"人群聚集在剧院外。"},{"en":"She gathered the children around the table.","zh":"她把孩子们召集到桌旁。"}]},{"pos":"v.","meaning":"收集；采集","definition":"to collect things or information","examples":[{"en":"The researchers gathered samples from the lake.","zh":"研究人员从湖中采集样本。"},{"en":"We gathered fallen branches for the fire.","zh":"我们收集落枝生火。"}]},{"pos":"v.","meaning":"逐渐增加；积聚","definition":"to increase in strength or amount","examples":[{"en":"The train gathered speed.","zh":"火车逐渐加速。"},{"en":"The campaign is gathering support.","zh":"这场运动正在获得越来越多的支持。"}]},{"pos":"v.","meaning":"推测；得知","definition":"to understand from available information","examples":[{"en":"I gather that the meeting has been cancelled.","zh":"我得知会议取消了。"},{"en":"From her expression, he gathered she was disappointed.","zh":"从她的表情，他猜出她很失望。"}]}],"gauge":[{"pos":"n.","meaning":"测量仪表；计量器","definition":"An instrument that measures a quantity.","examples":[{"en":"The pressure gauge showed an unusually high reading.","zh":"压力计显示的读数异常偏高。"},{"en":"Check the fuel gauge before starting the journey.","zh":"出发前检查一下油量表。"}]},{"pos":"n.","meaning":"规格；口径；轨距","definition":"A standard width or thickness, especially of rails or metal.","examples":[{"en":"The two railway systems use different gauges.","zh":"这两个铁路系统使用不同的轨距。"},{"en":"Choose wire of the correct gauge for the circuit.","zh":"为电路选择规格合适的电线。"}]},{"pos":"v.","meaning":"测量；估计；判断","definition":"To measure or form an estimate of something.","examples":[{"en":"We gauged the depth of the stream with a stick.","zh":"我们用木棍测量溪水深度。"},{"en":"The survey aims to gauge public support for the proposal.","zh":"调查旨在了解公众对这项提议的支持程度。"}]}],"gear":[{"pos":"n.","meaning":"齿轮;传动装置;挡位","definition":"a toothed mechanism or setting controlling transmitted motion","examples":[{"en":"A broken gear stopped the machine.","zh":"一个坏齿轮使机器停了。"},{"en":"Shift into a lower gear on the hill.","zh":"上坡时换低挡。"}]},{"pos":"n.","meaning":"用具;装备;服装","definition":"equipment needed for an activity","examples":[{"en":"Pack your camping gear tonight.","zh":"今晚收好露营装备。"},{"en":"The firefighters checked their protective gear.","zh":"消防员检查了防护装备。"}]},{"pos":"v.","meaning":"使适合;调整以适应","definition":"to design or adjust for a purpose","examples":[{"en":"The course is geared to beginners.","zh":"这门课程面向初学者。"},{"en":"Production was geared to seasonal demand.","zh":"生产根据季节性需求作了调整。"}]}],"gelatin":[{"pos":"n.","meaning":"明胶","definition":"a substance used to make liquids set","examples":[{"en":"The recipe uses gelatin to set the dessert.","zh":"配方用明胶使甜点凝固。"},{"en":"The laboratory tested the strength of the gelatin film.","zh":"实验室测试了明胶薄膜的强度。"}]}],"gender":[{"pos":"n.","meaning":"性别","definition":"The category of being male, female, or another gender identity.","examples":[{"en":"The form asks applicants to state their gender.","zh":"表格要求申请者填写性别。"},{"en":"The school aims to offer equal opportunities regardless of gender.","zh":"学校旨在提供不分性别的平等机会。"}]},{"pos":"n.","meaning":"语法性","definition":"A grammatical category of nouns and related words in some languages.","examples":[{"en":"French nouns have grammatical gender.","zh":"法语名词具有语法性。"},{"en":"The adjective changes to match the gender of the noun.","zh":"形容词要变化，以配合名词的性。"}]}],"gene":[{"pos":"n.","meaning":"基因","definition":"a unit of inherited biological information","examples":[{"en":"The researchers identified a gene linked to colour.","zh":"研究人员发现了一个与颜色有关的基因。"},{"en":"Children inherit genes from both parents.","zh":"孩子从父母双方继承基因。"}]}],"general":[{"pos":"adj.","meaning":"一般的；普通的","definition":"not specialised or limited to a particular case","examples":[{"en":"The doctor gave some general advice.","zh":"医生给了一些一般性建议。"},{"en":"The book is intended for the general reader.","zh":"这本书面向普通读者。"}]},{"pos":"adj.","meaning":"普遍的；全体的","definition":"affecting or involving most people or things","examples":[{"en":"There was general agreement on the proposal.","zh":"大家普遍同意这一提议。"},{"en":"The announcement caused general excitement.","zh":"公告引起了普遍的兴奋。"}]},{"pos":"adj.","meaning":"大体的；概括的","definition":"covering main points without detail","examples":[{"en":"She gave a general outline of the plan.","zh":"她概述了计划。"},{"en":"I understand the general idea.","zh":"我理解大意。"}]},{"pos":"adj.","meaning":"首席的；总的","definition":"having overall authority or responsibility","examples":[{"en":"The general manager approved the purchase.","zh":"总经理批准了购买。"},{"en":"The secretary-general opened the conference.","zh":"秘书长宣布会议开始。"}]},{"pos":"n.","meaning":"将军","definition":"a high-ranking military officer","examples":[{"en":"The general inspected the camp.","zh":"将军视察了营地。"},{"en":"The historian interviewed a retired general.","zh":"历史学家采访了一位退役将军。"}]}],"generalise":[{"pos":"v.","meaning":"概括；归纳；作笼统判断","definition":"To form a broad statement from particular examples.","examples":[{"en":"It is risky to generalise from such a small sample.","zh":"从这样小的样本进行概括有风险。"},{"en":"The article generalises about young people without considering their differences.","zh":"这篇文章笼统地谈论年轻人，没有考虑他们的差异。"}]},{"pos":"v.","meaning":"推广；使普遍适用","definition":"To extend a result or rule to a wider range of situations.","examples":[{"en":"Researchers cannot generalise these findings to every age group.","zh":"研究人员不能将这些发现推广到所有年龄组。"},{"en":"The method was generalised to handle three-dimensional problems.","zh":"这种方法得到推广，可以处理三维问题。"}]}],"generate":[{"pos":"v.","meaning":"产生;生产;引起","definition":"to produce or bring about","examples":[{"en":"Wind turbines generate electricity.","zh":"风力涡轮机发电。"},{"en":"The announcement generated considerable interest.","zh":"这项公告引起了广泛兴趣。"}]}],"generation":[{"pos":"n.","meaning":"一代人","definition":"people born around the same time","examples":[{"en":"Each generation faces different challenges.","zh":"每一代人都面临不同挑战。"},{"en":"The younger generation often uses technology differently.","zh":"年轻一代使用技术的方式往往不同。"},{"en":"We should preserve these resources for the next generation.","zh":"我们应为下一代保护这些资源。"}]}],"generative":[{"pos":"adj.","meaning":"产生的；生成的；有生产能力的","definition":"Able to produce or bring something into existence.","examples":[{"en":"The workshop encouraged generative discussion that produced new ideas.","zh":"研讨会鼓励能够产生新想法的讨论。"},{"en":"The artist used a generative system to create changing visual patterns.","zh":"艺术家用一个生成系统创作不断变化的视觉图案。"}]},{"pos":"adj.","meaning":"生殖的；生育的","definition":"Relating to the production of offspring or reproductive cells.","examples":[{"en":"The diagram labels the plant's generative organs.","zh":"图中标出了植物的生殖器官。"},{"en":"The course compares generative processes in different organisms.","zh":"这门课程比较不同生物的生殖过程。"}]}],"generic":[{"pos":"adj.","meaning":"通用的;一般的;非专有品牌的","definition":"relating to a whole class rather than a specific item","examples":[{"en":"The guide gives generic advice for travellers.","zh":"指南提供通用旅行建议。"},{"en":"The pharmacy offers a cheaper generic medicine.","zh":"药房提供一种更便宜的仿制药。"}]},{"pos":"adj.","meaning":"属的;种类的","definition":"relating to a biological genus or a class","examples":[{"en":"The botanist checked the plant's generic name.","zh":"植物学家核对了该植物的属名。"},{"en":"Generic classification groups related species together.","zh":"属级分类把亲缘相近的物种归在一起。"}]}],"generous":[{"pos":"adj.","meaning":"慷慨的；宽厚的","definition":"willing to give or forgive freely","examples":[{"en":"She was generous with her time.","zh":"她很愿意付出自己的时间帮助别人。"},{"en":"His generous donation helped repair the library.","zh":"他的慷慨捐款帮助修复了图书馆。"}]},{"pos":"adj.","meaning":"大量的；充足的","definition":"larger than usual or sufficient","examples":[{"en":"The cafe serves generous portions.","zh":"咖啡馆供应的餐食分量很足。"},{"en":"Leave a generous margin around the drawing.","zh":"在画的四周留出充裕的边距。"}]}],"genetic":[{"pos":"adj.","meaning":"遗传的；基因的","definition":"Relating to genes or inherited biological characteristics.","examples":[{"en":"The researchers compared genetic variation among the populations.","zh":"研究人员比较了各群体之间的遗传变异。"},{"en":"The twins share much of the same genetic information.","zh":"这对双胞胎共享大量相同的遗传信息。"}]}],"genuine":[{"pos":"adj.","meaning":"真正的;真实的;真诚的","definition":"real or sincere rather than false","examples":[{"en":"The necklace contains genuine pearls.","zh":"项链上是真珍珠。"},{"en":"She showed genuine concern for his welfare.","zh":"她真诚地关心他的健康和生活。"}]}],"geographical":[{"pos":"adj.","meaning":"地理的；地理学的","definition":"relating to places and their physical features","examples":[{"en":"Geographical barriers limited trade.","zh":"地理障碍限制了贸易。"},{"en":"The study compared geographical patterns of rainfall.","zh":"研究比较了降雨的地理分布模式。"}]}],"geological":[{"pos":"adj.","meaning":"地质的；地质学的","definition":"Relating to the Earth's rocks, structure, and history.","examples":[{"en":"The valley contains several unusual geological formations.","zh":"这个山谷有几种不寻常的地质构造。"},{"en":"A geological survey was carried out before the tunnel was built.","zh":"修建隧道之前进行了地质勘查。"}]}],"geology":[{"pos":"n.","meaning":"地质学","definition":"the study of Earth's rocks and structure","examples":[{"en":"He studied geology before joining the survey.","zh":"参加勘测前他学习了地质学。"},{"en":"Geology helps explain how mountains form.","zh":"地质学帮助解释山脉如何形成。"}]},{"pos":"n.","meaning":"地质状况","definition":"the rocks and structure of a particular area","examples":[{"en":"The tunnel design reflects the local geology.","zh":"隧道设计考虑了当地地质状况。"},{"en":"A map shows the geology of the coastline.","zh":"地图展示了海岸线的地质结构。"}]}],"geometric":[{"pos":"adj.","meaning":"几何的；几何学的","definition":"relating to geometry or simple regular shapes","examples":[{"en":"The tiles form a geometric pattern.","zh":"瓷砖形成了几何图案。"},{"en":"Students used geometric principles to calculate the area.","zh":"学生利用几何原理计算面积。"}]}],"geometry":[{"pos":"n.","meaning":"几何；几何学","definition":"The study of shapes, sizes, angles, and spatial relationships.","examples":[{"en":"In geometry, we learned to calculate the area of a triangle.","zh":"在几何课上，我们学习了如何计算三角形面积。"},{"en":"The architect used simple geometry to design the roof.","zh":"建筑师运用简单的几何原理设计屋顶。"}]}],"germ":[{"pos":"n.","meaning":"病菌;微生物","definition":"a microorganism, especially one causing disease","examples":[{"en":"Soap helps remove germs from hands.","zh":"肥皂有助于清除手上的病菌。"},{"en":"The surface carried harmful germs.","zh":"表面带有有害病菌。"}]},{"pos":"n.","meaning":"萌芽;起源","definition":"the earliest beginning of an idea","examples":[{"en":"That conversation contained the germ of a novel.","zh":"那次谈话孕育了一部小说的雏形。"},{"en":"A small observation became the germ of her theory.","zh":"一个小发现成为她理论的萌芽。"}]}],"germinate":[{"pos":"v.","meaning":"发芽","definition":"to begin growing from a seed","examples":[{"en":"The seeds germinated within a week.","zh":"种子在一周内发芽了。"},{"en":"Warmth helps these seeds germinate.","zh":"温暖有助于这些种子发芽。"}]},{"pos":"v.","meaning":"萌生；开始发展","definition":"to begin developing in the mind","examples":[{"en":"The idea germinated during a train journey.","zh":"这个想法在一次火车旅途中萌生。"},{"en":"A new partnership was germinating within the community.","zh":"一种新合作关系正在社区中萌芽。"}]}],"gesture":[{"pos":"n.","meaning":"手势；姿态；示意动作","definition":"A movement of the hands or body that communicates something.","examples":[{"en":"With a quick gesture, she invited us to sit down.","zh":"她迅速做了个手势，示意我们坐下。"},{"en":"He raised both hands in a gesture of surrender.","zh":"他举起双手，做出投降的姿态。"}]},{"pos":"v.","meaning":"做手势；示意","definition":"To communicate through a movement of the body.","examples":[{"en":"The guide gestured towards the exit.","zh":"导游朝出口做了个手势。"},{"en":"She gestured for the children to remain quiet.","zh":"她做手势示意孩子们安静。"}]}],"get off track":[{"pos":"v. phr.","meaning":"离题;偏离目标","definition":"to move away from the intended subject or plan","examples":[{"en":"We got off track while discussing the budget.","zh":"我们讨论预算时跑题了。"},{"en":"Unexpected repairs made the project get off track.","zh":"意外维修使项目偏离了原计划。"}]}],"gigantic":[{"pos":"adj.","meaning":"巨大的；庞大的","definition":"extremely large","examples":[{"en":"A gigantic crane towered over the site.","zh":"一架巨型起重机耸立在工地上。"},{"en":"The museum houses a gigantic dinosaur skeleton.","zh":"博物馆收藏了一具巨大的恐龙骨架。"}]}],"gill":[{"pos":"n.","meaning":"鳃","definition":"An organ that allows fish and some other animals to obtain oxygen from water.","examples":[{"en":"Water passes over the fish's gills as it breathes.","zh":"鱼呼吸时，水流经它的鳃。"},{"en":"The diagram shows the position of the gills behind the head.","zh":"图中显示了头部后方鳃的位置。"}]}],"given":[{"pos":"adj.","meaning":"规定的;特定的","definition":"specified or already established","examples":[{"en":"Complete the task within the given time.","zh":"在规定时间内完成任务。"},{"en":"The answer depends on the given conditions.","zh":"答案取决于特定条件。"}]},{"pos":"adj.","meaning":"假设的;作为前提的","definition":"assumed to be true for reasoning","examples":[{"en":"The given assumptions simplify the calculation.","zh":"这些假设前提简化了计算。"},{"en":"We tested the model against a given scenario.","zh":"我们以一个假设情境检验模型。"}]}],"glacial":[{"pos":"adj.","meaning":"冰川的；冰期的","definition":"relating to glaciers or ice ages","examples":[{"en":"Glacial erosion shaped the valley.","zh":"冰川侵蚀塑造了山谷。"},{"en":"The rocks preserve evidence of a glacial period.","zh":"岩石保存了冰期的证据。"}]},{"pos":"adj.","meaning":"冰冷的；极冷的","definition":"extremely cold","examples":[{"en":"A glacial wind swept through the valley.","zh":"冰冷的风掠过山谷。"},{"en":"The lake's glacial water numbed his feet.","zh":"湖里冰冷的水使他的双脚麻木。"}]},{"pos":"adj.","meaning":"冷若冰霜的","definition":"unfriendly and emotionally cold","examples":[{"en":"She responded with a glacial stare.","zh":"她以冷冰冰的目光回应。"},{"en":"His glacial tone ended the discussion.","zh":"他冰冷的语气结束了讨论。"}]}],"glacier":[{"pos":"n.","meaning":"冰川；冰河","definition":"A large mass of ice that moves slowly over land.","examples":[{"en":"The glacier has retreated far up the valley.","zh":"冰川已经退缩到山谷深处。"},{"en":"A river of meltwater flowed from beneath the glacier.","zh":"一条融水河流从冰川下方流出。"}]}],"glamor":[{"pos":"n.","meaning":"魅力;吸引力","definition":"an exciting or attractive quality associated with luxury","examples":[{"en":"The film captures the glamor of old Hollywood.","zh":"影片捕捉了旧好莱坞的魅力。"},{"en":"Behind the glamor lay years of hard work.","zh":"光鲜背后是多年的辛勤劳动。"}]}],"gland":[{"pos":"n.","meaning":"腺；腺体","definition":"an organ that produces and releases substances","examples":[{"en":"Sweat glands help regulate body temperature.","zh":"汗腺帮助调节体温。"},{"en":"The diagram labels the salivary glands.","zh":"图中标出了唾液腺。"}]}],"gleam":[{"pos":"v.","meaning":"闪烁；发微光","definition":"To shine with a soft or reflected light.","examples":[{"en":"The silver necklace gleamed in the sunlight.","zh":"银项链在阳光下闪闪发亮。"},{"en":"A light gleamed through the upstairs window.","zh":"楼上的窗户透出一丝灯光。"}]},{"pos":"v.","meaning":"流露；闪现","definition":"To show a feeling briefly in the eyes or face.","examples":[{"en":"Excitement gleamed in her eyes.","zh":"她眼中流露出兴奋。"},{"en":"A hint of amusement gleamed in his expression.","zh":"他的表情中闪过一丝笑意。"}]},{"pos":"n.","meaning":"微光；闪光；一线希望","definition":"A small or brief light, or a slight sign of a feeling.","examples":[{"en":"We followed the gleam of the distant lighthouse.","zh":"我们循着远处灯塔的微光前进。"},{"en":"The news offered a gleam of hope.","zh":"这个消息带来了一线希望。"}]}],"glide":[{"pos":"v.","meaning":"滑行;滑翔","definition":"to move smoothly and quietly","examples":[{"en":"Swans glided across the lake.","zh":"天鹅在湖面上轻盈滑行。"},{"en":"The aircraft glided toward the runway.","zh":"飞机向跑道滑翔。"}]},{"pos":"n.","meaning":"滑行;滑翔","definition":"a smooth continuous movement","examples":[{"en":"The eagle began a long glide.","zh":"鹰开始了长距离滑翔。"},{"en":"One push sent the skater into a graceful glide.","zh":"滑冰者一蹬脚便优雅地滑行起来。"}]}],"glimpse":[{"pos":"v.","meaning":"瞥见","definition":"to see briefly or incompletely","examples":[{"en":"We glimpsed the sea between the trees.","zh":"我们从树间瞥见了大海。"},{"en":"She glimpsed a fox crossing the road.","zh":"她瞥见一只狐狸穿过马路。"}]},{"pos":"n.","meaning":"一瞥；短暂的看见","definition":"a brief or incomplete view","examples":[{"en":"I caught a glimpse of the singer.","zh":"我瞥见了那位歌手。"},{"en":"The letters offer a glimpse into daily life.","zh":"这些信让人得以一窥日常生活。"}]}],"glitter":[{"pos":"v.","meaning":"闪闪发光","definition":"To shine with many small bright flashes.","examples":[{"en":"Frost glittered on the grass.","zh":"草地上的霜闪闪发亮。"},{"en":"The city lights glittered across the bay.","zh":"城市灯火在海湾彼岸闪烁。"}]},{"pos":"n.","meaning":"闪光；闪烁","definition":"Bright flashes of reflected light.","examples":[{"en":"The glitter of the jewels caught her eye.","zh":"珠宝的闪光吸引了她的目光。"},{"en":"We admired the glitter of sunlight on the river.","zh":"我们欣赏着河面上闪烁的阳光。"}]}],"global":[{"pos":"adj.","meaning":"全球的;世界性的","definition":"relating to the whole world","examples":[{"en":"The disease became a global concern.","zh":"这种疾病成为全球关注的问题。"},{"en":"Global trade connects distant economies.","zh":"全球贸易把相距遥远的经济体连接起来。"}]},{"pos":"adj.","meaning":"整体的;全面的","definition":"considering every part of something","examples":[{"en":"We need a global view of the problem.","zh":"我们需要全面看待这个问题。"},{"en":"The software performs a global search across all files.","zh":"软件对所有文件进行全局搜索。"}]}],"glorious":[{"pos":"adj.","meaning":"光荣的；辉煌的","definition":"deserving great honour or admiration","examples":[{"en":"The team celebrated a glorious victory.","zh":"球队庆祝了辉煌的胜利。"},{"en":"The exhibition recalls the theatre's glorious past.","zh":"展览回顾了剧院辉煌的过去。"}]},{"pos":"adj.","meaning":"壮丽的；极美好的","definition":"very beautiful or enjoyable","examples":[{"en":"We watched a glorious sunset.","zh":"我们观看了壮丽的日落。"},{"en":"It was a glorious day for walking.","zh":"那是一个特别适合散步的好天气。"}]}],"gloss":[{"pos":"n.","meaning":"光泽；亮光","definition":"A smooth shine on a surface.","examples":[{"en":"Polishing restored the gloss of the wooden table.","zh":"抛光恢复了木桌的光泽。"},{"en":"The fabric has a soft gloss under bright light.","zh":"这种织物在强光下带有柔和的光泽。"}]},{"pos":"n.","meaning":"虚饰；假象；粉饰的解释","definition":"An attractive surface appearance or interpretation that hides faults.","examples":[{"en":"The brochure puts a cheerful gloss on the company's poor results.","zh":"宣传册把公司糟糕的业绩粉饰得令人乐观。"},{"en":"Behind the gloss of luxury, the hotel was badly maintained.","zh":"在豪华的表象背后，酒店的维护很差。"}]},{"pos":"n.","meaning":"注释；解释","definition":"A short explanation of a word or passage.","examples":[{"en":"A gloss in the margin explains the unfamiliar term.","zh":"页边的一条注释解释了这个陌生术语。"},{"en":"The edition includes glosses for difficult passages.","zh":"这个版本为难懂的段落配有注释。"}]},{"pos":"v.","meaning":"使有光泽；发亮","definition":"To give or acquire a shiny surface.","examples":[{"en":"She glossed the wooden frame with clear varnish.","zh":"她给木框涂上透明清漆，使其发亮。"},{"en":"The freshly coated surface glossed as it dried.","zh":"新涂覆的表面在干燥过程中变得有光泽。"}]},{"pos":"v.","meaning":"粉饰；掩饰；曲解","definition":"To make something seem better by hiding or distorting its defects.","examples":[{"en":"The report glossed over the project's serious delays.","zh":"报告掩饰了项目严重延误的问题。"},{"en":"He tried to gloss his refusal as an act of kindness.","zh":"他试图把自己的拒绝粉饰成一种善举。"}]},{"pos":"v.","meaning":"作注释；解释","definition":"To supply an explanation of words or a text.","examples":[{"en":"The editor glossed the dialect expressions for modern readers.","zh":"编辑为现代读者注释了那些方言表达。"},{"en":"Students glossed the unfamiliar phrases in the poem.","zh":"学生们为诗中不熟悉的短语作了注释。"}]}],"glossary":[{"pos":"n.","meaning":"术语表;词汇表","definition":"a list explaining unfamiliar words","examples":[{"en":"A glossary appears at the back of the book.","zh":"书末附有术语表。"},{"en":"Use the glossary to check technical terms.","zh":"用术语表核对专业词汇。"}]}],"glossy":[{"pos":"adj.","meaning":"有光泽的；光滑的","definition":"having a smooth shiny surface","examples":[{"en":"The plant has thick, glossy leaves.","zh":"这株植物有厚实光亮的叶子。"},{"en":"The photograph was printed on glossy paper.","zh":"照片印在有光泽的相纸上。"}]}],"glove":[{"pos":"n.","meaning":"手套","definition":"A covering for the hand with separate parts for the fingers.","examples":[{"en":"She put on thick gloves before clearing the snow.","zh":"清雪前她戴上了厚手套。"},{"en":"I found a single glove under the bus seat.","zh":"我在公交车座位下找到了一只手套。"}]}],"glue":[{"pos":"n.","meaning":"胶水","definition":"a sticky substance used to join things","examples":[{"en":"Apply a thin layer of glue.","zh":"涂一层薄胶水。"},{"en":"The glue needs an hour to dry.","zh":"胶水需要一小时才能干。"}]},{"pos":"v.","meaning":"粘合;胶合","definition":"to attach with glue","examples":[{"en":"She glued the broken handle back on.","zh":"她把断掉的把手粘了回去。"},{"en":"Glue the photograph onto the card.","zh":"把照片粘在卡片上。"}]}],"glutamate":[{"pos":"n.","meaning":"谷氨酸盐；谷氨酸根（生物语境中亦称谷氨酸）","definition":"a form or salt of glutamic acid, involved in flavour and nerve signalling","examples":[{"en":"Tomatoes contain naturally occurring glutamate.","zh":"番茄含有天然存在的谷氨酸盐。"},{"en":"The study measured glutamate levels in the samples.","zh":"研究测量了样本中的谷氨酸水平。"}]}],"goal":[{"pos":"n.","meaning":"目标；目的","definition":"Something that a person or organisation aims to achieve.","examples":[{"en":"Her goal is to become a qualified interpreter.","zh":"她的目标是成为一名合格的口译员。"},{"en":"The project achieved its main goal of reducing waste.","zh":"这个项目实现了减少浪费的主要目标。"}]},{"pos":"n.","meaning":"球门","definition":"The area or frame into which a ball must go to score.","examples":[{"en":"The goalkeeper stood in front of the goal.","zh":"守门员站在球门前。"},{"en":"The ball struck the side of the goal.","zh":"球击中了球门侧边。"}]},{"pos":"n.","meaning":"进球；进球得分","definition":"A point scored by sending a ball into a goal.","examples":[{"en":"She scored the winning goal in the final minute.","zh":"她在最后一分钟打入了制胜球。"},{"en":"The match ended with three goals for each team.","zh":"比赛结束时两队各进了三个球。"}]}],"goggles":[{"pos":"n.","meaning":"护目镜;风镜;泳镜","definition":"protective glasses fitting closely around the eyes","examples":[{"en":"Wear goggles while cutting metal.","zh":"切割金属时戴护目镜。"},{"en":"His swimming goggles kept the water out.","zh":"他的泳镜挡住了水。"}]}],"goodwill":[{"pos":"n.","meaning":"善意；友好","definition":"friendly feelings and a willingness to help","examples":[{"en":"The visit was intended to build goodwill.","zh":"这次访问旨在增进友好。"},{"en":"The project depends on volunteers' goodwill.","zh":"项目依靠志愿者的善意支持。"}]},{"pos":"n.","meaning":"商誉；信誉","definition":"the value of a business's good reputation","examples":[{"en":"Poor service damaged the company's goodwill.","zh":"糟糕的服务损害了公司的商誉。"},{"en":"The purchase price included the shop's goodwill.","zh":"购买价格包括商店的商誉价值。"}]}],"gorge":[{"pos":"n.","meaning":"峡谷；山峡","definition":"A deep narrow valley with steep sides.","examples":[{"en":"A suspension bridge crosses the gorge.","zh":"一座吊桥横跨峡谷。"},{"en":"The river carved a narrow gorge through the limestone.","zh":"河流在石灰岩中冲刷出了一条狭窄的峡谷。"}]},{"pos":"v.","meaning":"狼吞虎咽；大吃","definition":"To eat a large amount greedily.","examples":[{"en":"The children gorged on fresh strawberries.","zh":"孩子们大口吃着新鲜草莓。"},{"en":"He gorged himself at the buffet and skipped dinner.","zh":"他在自助餐上吃得太多，晚餐便没吃。"}]}],"gorgeous":[{"pos":"adj.","meaning":"漂亮的;华丽的;极好的","definition":"very beautiful or enjoyable","examples":[{"en":"The garden looks gorgeous in spring.","zh":"花园在春天美极了。"},{"en":"We enjoyed a gorgeous meal by the sea.","zh":"我们在海边享用了一顿美餐。"}]}],"gorilla":[{"pos":"n.","meaning":"大猩猩","definition":"a large African ape","examples":[{"en":"The documentary follows a family of gorillas.","zh":"纪录片追踪了一群大猩猩的生活。"},{"en":"The sanctuary provides space for rescued gorillas.","zh":"保护区为获救的大猩猩提供栖息空间。"}]}],"govern":[{"pos":"v.","meaning":"统治；治理；管理","definition":"To exercise authority over a country, group, or institution.","examples":[{"en":"A small council governs the island.","zh":"一个小型委员会治理这座岛。"},{"en":"The university is governed by an independent board.","zh":"这所大学由独立理事会管理。"}]},{"pos":"v.","meaning":"支配；控制；决定","definition":"To influence or determine how something happens.","examples":[{"en":"Safety considerations govern every stage of the design.","zh":"安全因素决定设计的每个阶段。"},{"en":"The movement of the tides is governed largely by gravity.","zh":"潮汐运动主要受引力支配。"}]}],"grab":[{"pos":"v.","meaning":"抓住;夺取","definition":"to take hold of something suddenly","examples":[{"en":"She grabbed the rail to steady herself.","zh":"她抓住栏杆站稳。"},{"en":"He grabbed the last seat on the bus.","zh":"他抢到了公交车上最后一个座位。"}]},{"pos":"n.","meaning":"抓取;抢夺","definition":"a sudden attempt to take something","examples":[{"en":"He made a grab for the falling cup.","zh":"他伸手猛抓掉落的杯子。"},{"en":"The merger was seen as a grab for power.","zh":"这次合并被视为夺权行为。"}]}],"graduate":[{"pos":"n.","meaning":"毕业生","definition":"a person who has completed a course or degree","examples":[{"en":"The company recruits engineering graduates.","zh":"公司招聘工程专业毕业生。"},{"en":"She is a graduate of the local university.","zh":"她毕业于当地大学。"}],"ipa":"/ˈɡrædʒuət/"},{"pos":"adj.","meaning":"研究生阶段的（主要用于美式英语）","definition":"relating to study after a first university degree","examples":[{"en":"He applied to graduate school.","zh":"他申请了研究生院。"},{"en":"The university offers several graduate programmes.","zh":"这所大学提供几项研究生课程。"}],"ipa":"/ˈɡrædʒuət/"},{"pos":"v.","meaning":"毕业；获得学位；准予毕业","definition":"to complete a course or award a degree","examples":[{"en":"She graduated in chemistry last year.","zh":"她去年取得了化学学位。"},{"en":"The college graduates hundreds of nurses annually.","zh":"学院每年培养数百名毕业护士。"}],"ipa":"/ˈɡrædʒueɪt/"}],"grand":[{"pos":"adj.","meaning":"宏伟的；壮丽的；大规模的","definition":"Large, impressive, or ambitious.","examples":[{"en":"A grand staircase leads to the ballroom.","zh":"一道宏伟的楼梯通向舞厅。"},{"en":"They announced a grand plan to restore the waterfront.","zh":"他们宣布了一项修复滨水地区的宏大计划。"}]}],"granite":[{"pos":"n.","meaning":"花岗岩","definition":"a hard rock containing quartz and other minerals","examples":[{"en":"The monument is carved from granite.","zh":"纪念碑由花岗岩雕成。"},{"en":"Granite cliffs rise above the harbour.","zh":"花岗岩峭壁耸立在港口上方。"}]}],"grant":[{"pos":"n.","meaning":"补助金；助学金","definition":"money given for a particular purpose","examples":[{"en":"The grant paid for fieldwork.","zh":"补助金支付了实地研究费用。"},{"en":"She received a grant to study abroad.","zh":"她获得了出国留学助学金。"}]},{"pos":"n.","meaning":"授予；授予物；授权","definition":"an official act of giving a right or property","examples":[{"en":"The archive contains an ancient land grant.","zh":"档案馆藏有一份古代土地授予文书。"},{"en":"The grant of a licence took several weeks.","zh":"许可证的授予用了几周。"}]},{"pos":"v.","meaning":"给予；授予；准许","definition":"to formally give or allow something","examples":[{"en":"The council granted permission for the extension.","zh":"议会批准了扩建。"},{"en":"The foundation granted funds for the project.","zh":"基金会向项目拨款。"}]},{"pos":"v.","meaning":"承认；同意某一点","definition":"to accept that something is true","examples":[{"en":"I grant that the plan has risks.","zh":"我承认这个计划有风险。"},{"en":"She granted his point but questioned his conclusion.","zh":"她认同他的观点，却质疑他的结论。"}]}],"graph":[{"pos":"n.","meaning":"图表；曲线图","definition":"A diagram showing relationships between quantities.","examples":[{"en":"The graph shows a steady rise in temperatures.","zh":"这张图显示气温持续上升。"},{"en":"Plot the monthly sales figures on a graph.","zh":"把每月销售数据绘制成图表。"}]}],"graphic":[{"pos":"adj.","meaning":"生动的;逼真的;露骨的","definition":"describing something in clear and vivid detail","examples":[{"en":"She gave a graphic account of the storm.","zh":"她生动描述了那场风暴。"},{"en":"The report contains graphic descriptions of injuries.","zh":"报告包含对伤势的详细逼真描述。"}]},{"pos":"adj.","meaning":"图像的;绘画的;图表的","definition":"relating to pictures, design, or diagrams","examples":[{"en":"He studies graphic design at college.","zh":"他在大学学习平面设计。"},{"en":"A graphic representation makes the trend clearer.","zh":"图表呈现使趋势更清楚。"}]},{"pos":"adj.","meaning":"文字的;书写的","definition":"relating to written signs or symbols","examples":[{"en":"The researchers compared spoken and graphic forms of language.","zh":"研究人员比较了语言的口头形式与书写形式。"},{"en":"Ancient graphic symbols were carved into the stone.","zh":"古代书写符号刻在石头上。"}]}],"graphology":[{"pos":"n.","meaning":"笔迹学；笔相学","definition":"the study of handwriting, especially to infer character","examples":[{"en":"The book discusses claims made by graphology.","zh":"这本书讨论了笔相学的主张。"},{"en":"She compared graphology with forensic handwriting analysis.","zh":"她把笔相学与法庭笔迹分析进行了比较。"}]}],"grasp":[{"pos":"v.","meaning":"抓紧；握住","definition":"To take and hold something firmly.","examples":[{"en":"She grasped the railing as the boat tilted.","zh":"船倾斜时，她紧抓住栏杆。"},{"en":"He grasped the rope with both hands.","zh":"他用双手抓紧绳子。"}]},{"pos":"v.","meaning":"理解；领会；掌握","definition":"To understand something clearly.","examples":[{"en":"It took me a while to grasp the main argument.","zh":"我花了一些时间才理解主要论点。"},{"en":"The students quickly grasped how the machine worked.","zh":"学生们很快掌握了这台机器的工作原理。"}]},{"pos":"n.","meaning":"紧握；掌握；控制","definition":"A firm hold or power to control something.","examples":[{"en":"The cup slipped from his grasp.","zh":"杯子从他手中滑落了。"},{"en":"The leadership of the party was finally within her grasp.","zh":"她终于有望掌握该党的领导权。"}]},{"pos":"n.","meaning":"理解；领悟","definition":"The extent to which someone understands something.","examples":[{"en":"She has a good grasp of basic statistics.","zh":"她很好地掌握了基础统计学。"},{"en":"The lecture tested my grasp of the subject.","zh":"这堂讲座考验了我对该学科的理解。"}]}],"grassy":[{"pos":"adj.","meaning":"长满草的","definition":"covered with grass","examples":[{"en":"We sat on a grassy bank.","zh":"我们坐在长满草的岸边。"},{"en":"A grassy path leads to the cottage.","zh":"一条草径通向小屋。"}]},{"pos":"adj.","meaning":"似草的;草绿色的","definition":"resembling grass in appearance, colour, or smell","examples":[{"en":"The tea had a fresh, grassy aroma.","zh":"茶有清新的青草香。"},{"en":"She chose a grassy green paint for the walls.","zh":"她选了草绿色墙漆。"}]}],"grateful":[{"pos":"adj.","meaning":"感激的；感谢的","definition":"feeling thankful","examples":[{"en":"We are grateful for your help.","zh":"我们感谢你的帮助。"},{"en":"She gave the volunteer a grateful smile.","zh":"她向志愿者报以感激的微笑。"}]}],"gravel":[{"pos":"n.","meaning":"砾石；沙砾","definition":"Small stones used for paths, roads, or construction.","examples":[{"en":"The tyres crunched over the gravel.","zh":"轮胎碾过砾石，发出嘎吱声。"},{"en":"They spread gravel along the garden path.","zh":"他们沿着花园小路铺上砾石。"}]}],"gravity":[{"pos":"n.","meaning":"重力;引力","definition":"the force attracting masses toward each other","examples":[{"en":"Gravity pulls the ball back to Earth.","zh":"重力把球拉回地面。"},{"en":"The Moon's gravity affects ocean tides.","zh":"月球引力影响海洋潮汐。"}]}],"greasy":[{"pos":"adj.","meaning":"油腻的；沾油的；油滑的","definition":"covered with or containing too much grease","examples":[{"en":"The plate was still greasy after washing.","zh":"盘子洗后仍然油腻。"},{"en":"His greasy hands slipped on the handle.","zh":"他沾满油的手在把手上滑了一下。"}]}],"greatly":[{"pos":"adv.","meaning":"非常；极大地；大大地","definition":"To a large extent.","examples":[{"en":"The new bridge greatly reduced travel time.","zh":"新桥大大缩短了出行时间。"},{"en":"Your help is greatly appreciated.","zh":"非常感谢你的帮助。"}]}],"gregarious":[{"pos":"adj.","meaning":"爱交际的;合群的","definition":"enjoying the company of others","examples":[{"en":"Our gregarious host introduced everyone.","zh":"爱交际的主人把大家互相介绍了一遍。"},{"en":"She is too gregarious to enjoy working alone.","zh":"她很合群，不喜欢独自工作。"}]},{"pos":"adj.","meaning":"群居的","definition":"living in groups","examples":[{"en":"These gregarious birds gather in large flocks.","zh":"这些群居鸟类聚成大群。"},{"en":"The species becomes more gregarious in winter.","zh":"这一物种冬季更倾向于群居。"}]}],"grid":[{"pos":"n.","meaning":"网格；栅格；坐标网","definition":"a pattern of crossing lines or bars","examples":[{"en":"Draw the design on a square grid.","zh":"在方格网中画出设计。"},{"en":"Use the map grid to locate the campsite.","zh":"用地图坐标网找到营地。"}]},{"pos":"n.","meaning":"电网；输送网","definition":"a network supplying electricity or another resource","examples":[{"en":"The wind farm supplies power to the grid.","zh":"风电场向电网供电。"},{"en":"The storm damaged the national grid.","zh":"风暴损坏了全国电网。"}]}],"grieve":[{"pos":"v.","meaning":"悲伤；哀悼；使伤心","definition":"To feel or cause deep sadness, especially after a death.","examples":[{"en":"The family needed time to grieve after their loss.","zh":"遭受丧亲之痛后，这家人需要时间哀悼。"},{"en":"It grieved her to see the old garden neglected.","zh":"看到旧花园无人照料，她十分伤心。"}]}],"grill":[{"pos":"v.","meaning":"烧烤;炙烤","definition":"to cook using strong direct heat","examples":[{"en":"Grill the peppers until their skins darken.","zh":"烤甜椒直到表皮变黑。"},{"en":"We grilled fish over hot coals.","zh":"我们在热炭上烤鱼。"}]},{"pos":"v.","meaning":"盘问;追问","definition":"to question someone intensely","examples":[{"en":"Reporters grilled the minister about the delay.","zh":"记者追问部长延误的原因。"},{"en":"The detective grilled him for an hour.","zh":"侦探盘问了他一小时。"}]},{"pos":"n.","meaning":"烤架;烤炉","definition":"a rack or device used for direct-heat cooking","examples":[{"en":"Place the burgers on the grill.","zh":"把汉堡肉饼放在烤架上。"},{"en":"Clean the grill after it cools.","zh":"烤架冷却后再清洗。"}]}],"grim":[{"pos":"adj.","meaning":"严肃的；冷峻的","definition":"very serious and unsmiling","examples":[{"en":"He answered with a grim expression.","zh":"他表情冷峻地回答。"},{"en":"The team showed grim determination.","zh":"团队展现了坚定严肃的决心。"}]},{"pos":"adj.","meaning":"严峻的；可怕的；令人不快的","definition":"very unpleasant or worrying","examples":[{"en":"The report painted a grim picture.","zh":"报告描绘了一幅严峻的景象。"},{"en":"Conditions in the abandoned building were grim.","zh":"废弃建筑里的条件很糟糕。"}]}],"grimy":[{"pos":"adj.","meaning":"肮脏的；积满污垢的","definition":"Covered with ingrained dirt.","examples":[{"en":"The mechanic wiped his grimy hands on a cloth.","zh":"机械师用布擦了擦沾满油污的手。"},{"en":"Sunlight barely passed through the grimy windows.","zh":"阳光几乎照不透满是污垢的窗户。"}]}],"grin":[{"pos":"v.","meaning":"咧嘴笑","definition":"to smile broadly","examples":[{"en":"The child grinned at her father.","zh":"孩子对着父亲咧嘴笑。"},{"en":"He grinned when he saw the surprise.","zh":"看到惊喜时他咧嘴笑了。"}]},{"pos":"n.","meaning":"咧嘴的笑","definition":"a broad smile","examples":[{"en":"A delighted grin spread across her face.","zh":"她脸上绽开了欣喜的笑容。"},{"en":"He greeted us with a mischievous grin.","zh":"他带着淘气的笑迎接我们。"}]}],"grind":[{"pos":"n.","meaning":"苦差事；枯燥的工作","definition":"hard and repetitive work","examples":[{"en":"The daily grind left her exhausted.","zh":"每天的苦差事使她疲惫不堪。"},{"en":"He wanted a break from the office grind.","zh":"他想暂时摆脱办公室的枯燥工作。"}]},{"pos":"v.","meaning":"磨碎；碾碎","definition":"to crush into small particles","examples":[{"en":"Grind the spices just before cooking.","zh":"烹饪前把香料磨碎。"},{"en":"The mill grinds wheat into flour.","zh":"磨坊把小麦磨成面粉。"}]},{"pos":"v.","meaning":"折磨；压垮（常与 down 连用）","definition":"to wear someone down through prolonged pressure","examples":[{"en":"Years of uncertainty ground him down.","zh":"多年的不确定性使他备受折磨。"},{"en":"Constant criticism can grind down confidence.","zh":"不断的批评会消磨信心。"}]}],"grip":[{"pos":"v.","meaning":"紧握；抓牢","definition":"To hold something tightly.","examples":[{"en":"Grip the handle firmly before lifting the case.","zh":"抬箱子前要牢牢抓住把手。"},{"en":"The frightened child gripped her father's sleeve.","zh":"受惊的孩子紧抓着父亲的衣袖。"}]},{"pos":"v.","meaning":"吸引住；使着迷；强烈影响","definition":"To hold someone's attention or affect them powerfully.","examples":[{"en":"The mystery gripped me from the opening page.","zh":"这个悬疑故事从第一页就吸引住了我。"},{"en":"Fear gripped the crowd when the lights went out.","zh":"灯熄灭时，恐惧笼罩了人群。"}]},{"pos":"n.","meaning":"紧握；抓牢；抓握力","definition":"A firm hold on something.","examples":[{"en":"He loosened his grip on the rope.","zh":"他松了松握绳子的手。"},{"en":"The textured surface provides a better grip.","zh":"有纹理的表面让人握得更牢。"}]},{"pos":"n.","meaning":"控制；掌握","definition":"Power or control over a situation.","examples":[{"en":"The company began to lose its grip on the market.","zh":"公司开始失去对市场的控制。"},{"en":"She soon got a grip on the complicated timetable.","zh":"她很快掌握了复杂的时刻安排。"}]}],"groan":[{"pos":"v.","meaning":"呻吟;叹息;抱怨","definition":"to make a low sound of pain or disappointment","examples":[{"en":"The injured climber groaned in pain.","zh":"受伤的登山者痛苦地呻吟。"},{"en":"The students groaned at the extra homework.","zh":"学生们因额外作业而叹气。"}]},{"pos":"n.","meaning":"呻吟声;叹息声","definition":"a low sound expressing pain or dismay","examples":[{"en":"We heard a groan from the next room.","zh":"我们听见隔壁传来呻吟声。"},{"en":"The announcement drew a collective groan.","zh":"这项公告引来众人的叹息。"}]}],"grocery":[{"pos":"n.","meaning":"食品杂货店","definition":"a shop selling food and household supplies","examples":[{"en":"A small grocery opened on the corner.","zh":"街角开了一家小杂货店。"},{"en":"She stopped at the grocery on her way home.","zh":"她回家途中去了杂货店。"}]},{"pos":"n.","meaning":"食品；日用杂货（常用复数）","definition":"food and household items bought from a shop","examples":[{"en":"We carried the groceries upstairs.","zh":"我们把食品杂货搬上楼。"},{"en":"Their weekly groceries cost more this month.","zh":"这个月他们每周买食品杂货花费更多。"}]}],"grope":[{"pos":"v.","meaning":"摸索；探索","definition":"To feel for something that cannot be seen, or search uncertainly for an idea.","examples":[{"en":"He groped for the light switch in the dark.","zh":"他在黑暗中摸索电灯开关。"},{"en":"She paused, groping for the right words.","zh":"她停了一下，努力寻找恰当的措辞。"}]}],"gross":[{"pos":"adj.","meaning":"总的;毛的;未扣除的","definition":"calculated before deductions","examples":[{"en":"Her gross salary includes several allowances.","zh":"她的税前总工资包含几项津贴。"},{"en":"The truck exceeded its permitted gross weight.","zh":"卡车超过了允许的总重量。"}]}],"grove":[{"pos":"n.","meaning":"小树林；树丛","definition":"a small group of trees","examples":[{"en":"A grove of olive trees shaded the path.","zh":"一片橄榄树林为小路遮阴。"},{"en":"We rested in a quiet grove.","zh":"我们在安静的小树林里休息。"}]}],"grudge":[{"pos":"n.","meaning":"怨恨；积怨；不满","definition":"A lasting feeling of resentment about unfair treatment.","examples":[{"en":"He still holds a grudge over the unfair decision.","zh":"他仍对那个不公正的决定怀恨在心。"},{"en":"They put aside their old grudges and worked together.","zh":"他们放下旧怨，共同合作。"}]},{"pos":"v.","meaning":"不情愿地给；吝惜；嫉妒","definition":"To resent giving something or seeing someone have it.","examples":[{"en":"She never grudged the time spent helping her neighbours.","zh":"她从不吝惜帮助邻居的时间。"},{"en":"I do not grudge him his success after so much hard work.","zh":"他付出了如此多的努力，我并不嫉妒他的成功。"}]}],"guarantee":[{"pos":"v.","meaning":"保证;担保","definition":"to promise that something will happen or be reliable","examples":[{"en":"We cannot guarantee delivery by Friday.","zh":"我们无法保证周五前送达。"},{"en":"The manufacturer guarantees the motor for five years.","zh":"厂家为电机提供五年保修。"}]},{"pos":"n.","meaning":"保证;担保;保修承诺","definition":"a firm promise or assurance","examples":[{"en":"The appliance comes with a two-year guarantee.","zh":"电器附带两年保修。"},{"en":"Hard work is no guarantee of success.","zh":"努力工作并不保证成功。"}]},{"pos":"n.","meaning":"担保物;保证措施","definition":"something providing security for an obligation","examples":[{"en":"The house served as a guarantee for the loan.","zh":"房子作为贷款担保。"},{"en":"The deposit offers a guarantee against unpaid rent.","zh":"押金为欠租风险提供保障。"}]}],"guidance":[{"pos":"n.","meaning":"指导；指引","definition":"advice or help in deciding what to do","examples":[{"en":"The tutor offered guidance on choosing a topic.","zh":"导师就选题提供了指导。"},{"en":"New volunteers work under experienced staff's guidance.","zh":"新志愿者在资深员工的指导下工作。"}]}],"guideline":[{"pos":"n.","meaning":"指导方针；准则","definition":"Advice or rules that guide decisions and behaviour.","examples":[{"en":"The department issued new guidelines for handling complaints.","zh":"部门发布了处理投诉的新准则。"},{"en":"Use these guidelines when planning your presentation.","zh":"准备演讲时请参考这些指导原则。"}]}],"guilty":[{"pos":"adj.","meaning":"有罪的","definition":"responsible for an offence or wrongdoing","examples":[{"en":"The jury found him guilty.","zh":"陪审团认定他有罪。"},{"en":"Anyone guilty of cheating will be disqualified.","zh":"作弊者将被取消资格。"}]},{"pos":"adj.","meaning":"内疚的","definition":"feeling bad about having done something wrong","examples":[{"en":"She felt guilty about forgetting his birthday.","zh":"她因忘记他的生日而内疚。"},{"en":"His guilty expression revealed the truth.","zh":"他内疚的表情暴露了真相。"}]}],"guinea":[{"pos":"n.","meaning":"几尼（英国旧金币及计价单位，相当于21先令）","definition":"an old British coin or unit worth one pound and one shilling","examples":[{"en":"The old invoice lists the fee as ten guineas.","zh":"旧发票把费用列为十几尼。"},{"en":"The portrait was priced in guineas.","zh":"那幅肖像以几尼计价。"}]}],"gullibly":[{"pos":"adv.","meaning":"轻信地；容易受骗地","definition":"In a way that too readily accepts what others say.","examples":[{"en":"He gullibly believed the promise of instant wealth.","zh":"他轻信了能够立刻发财的承诺。"},{"en":"She gullibly accepted the stranger's story without checking it.","zh":"她没有核实便轻信了陌生人的故事。"}]}],"guzzle":[{"pos":"v.","meaning":"狂饮;大量消耗","definition":"to drink greedily or use large quantities","examples":[{"en":"He guzzled water after the race.","zh":"比赛后他大口喝水。"},{"en":"The old truck guzzles fuel.","zh":"这辆旧卡车很耗油。"}]}],"habitable":[{"pos":"adj.","meaning":"适宜居住的；可居住的","definition":"suitable for people to live in","examples":[{"en":"Repairs made the house habitable again.","zh":"维修使这栋房子重新适合居住。"},{"en":"The explorers searched for a habitable valley.","zh":"探险者寻找适宜居住的山谷。"}]}],"habitat":[{"pos":"n.","meaning":"栖息地","definition":"the natural home of an animal or plant","examples":[{"en":"The wetland provides a habitat for rare birds.","zh":"这片湿地为珍稀鸟类提供栖息地。"},{"en":"Road construction can destroy natural habitat.","zh":"道路建设可能破坏自然栖息地。"},{"en":"Restoring the habitat helped the species recover.","zh":"修复栖息地帮助这一物种恢复了数量。"}]}],"habitual":[{"pos":"adj.","meaning":"惯常的;习惯性的","definition":"done regularly as a habit","examples":[{"en":"He took his habitual seat by the window.","zh":"他坐到惯常的靠窗座位。"},{"en":"Habitual lateness disrupted the morning meetings.","zh":"习惯性迟到打乱了晨会。"}]}],"hall":[{"pos":"n.","meaning":"门厅；走廊","definition":"an entrance space or passage inside a building","examples":[{"en":"Leave your coat in the hall.","zh":"把外套留在门厅。"},{"en":"The bedrooms open onto a narrow hall.","zh":"卧室通向一条狭窄的走廊。"}]},{"pos":"n.","meaning":"礼堂；大厅","definition":"a large room or building for meetings and events","examples":[{"en":"The concert filled the village hall.","zh":"音乐会吸引了满满一礼堂的人。"},{"en":"Students gathered in the assembly hall.","zh":"学生们聚集在集会大厅。"}]}],"hallowed":[{"pos":"adj.","meaning":"神圣的；受崇敬的","definition":"Regarded as sacred or deeply respected.","examples":[{"en":"Visitors spoke quietly within the hallowed temple.","zh":"游客在这座神圣的庙宇中轻声交谈。"},{"en":"The university's hallowed halls have welcomed generations of scholars.","zh":"这所大学备受尊崇的殿堂迎来过一代又一代学者。"}]}],"halt":[{"pos":"v.","meaning":"停下;中止","definition":"to stop or cause to stop","examples":[{"en":"The guard halted the approaching car.","zh":"卫兵拦停了驶近的汽车。"},{"en":"Rain halted construction for two days.","zh":"大雨使施工中断了两天。"}]},{"pos":"v.","meaning":"踌躇;迟疑（较少用）","definition":"to hesitate or waver","examples":[{"en":"She halted between two conflicting loyalties.","zh":"她在两种冲突的忠诚之间犹豫。"},{"en":"He halted in his reply, unsure whom to trust.","zh":"他回答得迟疑，不确定该信任谁。"}]},{"pos":"n.","meaning":"暂停;停止","definition":"an interruption or end of movement or activity","examples":[{"en":"The train came to a halt.","zh":"火车停了下来。"},{"en":"They called a halt to the negotiations.","zh":"他们要求停止谈判。"}]}],"halve":[{"pos":"v.","meaning":"平分为二；减半","definition":"to divide into two equal parts or reduce by half","examples":[{"en":"Halve the tomatoes before roasting them.","zh":"烘烤前把番茄切成两半。"},{"en":"The new route halved our travel time.","zh":"新路线使我们的出行时间减半。"}]}],"hamlet":[{"pos":"n.","meaning":"小村庄","definition":"A very small village.","examples":[{"en":"The road ends at a hamlet beside the lake.","zh":"公路的尽头是湖边的一个小村庄。"},{"en":"Only a dozen families live in the remote hamlet.","zh":"这个偏远小村庄只住着十来户人家。"}]}],"hamper":[{"pos":"v.","meaning":"妨碍;阻碍","definition":"to make progress more difficult","examples":[{"en":"Heavy snow hampered rescue efforts.","zh":"大雪阻碍了救援。"},{"en":"Lack of data hampered the investigation.","zh":"数据不足妨碍了调查。"}]},{"pos":"n.","meaning":"有盖大篮子;食品礼篮","definition":"a large basket, often holding food or laundry","examples":[{"en":"She packed a picnic hamper.","zh":"她装好一个野餐篮。"},{"en":"They sent us a hamper of local delicacies.","zh":"他们寄来一篮当地美食。"}]}],"hamster":[{"pos":"n.","meaning":"仓鼠","definition":"a small rodent often kept as a pet","examples":[{"en":"The hamster filled its cheeks with food.","zh":"仓鼠把食物塞满颊囊。"},{"en":"Their hamster sleeps during much of the day.","zh":"他们的仓鼠白天大部分时间都在睡觉。"}]}],"handicapped":[{"pos":"adj.","meaning":"有残疾的（旧称，今常被视为不尊重）","definition":"Having a disability; an old-fashioned term often considered offensive.","examples":[{"en":"The old report described the building as unsuitable for physically handicapped visitors.","zh":"那份旧报告称，这栋建筑不适合身体有残疾的游客。"},{"en":"The charity's early records mention a school for handicapped children.","zh":"这家慈善机构的早期档案提到一所为残疾儿童设立的学校。"}]}],"handle":[{"pos":"v.","meaning":"处理;应付","definition":"to deal with a situation or responsibility","examples":[{"en":"She handles customer complaints patiently.","zh":"她耐心处理顾客投诉。"},{"en":"Can you handle the extra workload?","zh":"你能应付增加的工作量吗？"}]},{"pos":"v.","meaning":"操作;触摸;搬动","definition":"to control or touch something with the hands","examples":[{"en":"Only trained staff may handle the equipment.","zh":"只有受过培训的员工才能操作设备。"},{"en":"Handle the glass ornaments carefully.","zh":"小心拿放玻璃饰品。"}]},{"pos":"n.","meaning":"把手;柄","definition":"a part used for holding or moving something","examples":[{"en":"The suitcase handle snapped.","zh":"手提箱把手断了。"},{"en":"Turn the handle to open the door.","zh":"转动把手开门。"}]}],"handout":[{"pos":"n.","meaning":"讲义；分发的印刷品；传单","definition":"printed information given to people","examples":[{"en":"The lecturer distributed a handout with key dates.","zh":"讲师分发了列有重要日期的讲义。"},{"en":"Keep the handout for future reference.","zh":"留好这份资料，以后查阅。"}]},{"pos":"n.","meaning":"救济品；救济金","definition":"money or goods given to people in need","examples":[{"en":"The shelter organised food handouts.","zh":"收容所组织发放救济食品。"},{"en":"The grant was intended as support, not a permanent handout.","zh":"这笔资助旨在提供支持，而不是永久救济。"}]}],"handy":[{"pos":"adj.","meaning":"方便的；有用的","definition":"Useful and convenient.","examples":[{"en":"This pocket dictionary is handy when travelling.","zh":"这本袖珍词典旅行时很方便。"},{"en":"A folding chair is handy for outdoor concerts.","zh":"折叠椅在户外音乐会上很实用。"}]},{"pos":"adj.","meaning":"手边的；近便的","definition":"Nearby and easy to reach.","examples":[{"en":"Keep a torch handy in case the power fails.","zh":"把手电筒放在手边，以防停电。"},{"en":"The flat is handy for the railway station.","zh":"这套公寓离火车站很近。"}]},{"pos":"adj.","meaning":"手巧的；善于使用工具的","definition":"Skilled at practical tasks or using tools.","examples":[{"en":"She is handy with a sewing machine.","zh":"她很会使用缝纫机。"},{"en":"My uncle is handy at repairing old bicycles.","zh":"我叔叔很擅长修理旧自行车。"}]}],"hang":[{"pos":"v.","meaning":"悬挂;垂下","definition":"to suspend or be suspended from above","examples":[{"en":"Hang your coat on the hook.","zh":"把外套挂在钩子上。"},{"en":"Branches hung over the narrow path.","zh":"树枝垂在狭窄的小路上方。"}]},{"pos":"v.","meaning":"绞死;吊死","definition":"to kill by suspension with a rope around the neck","examples":[{"en":"The prisoner was hanged after the trial.","zh":"犯人在审判后被绞死。"},{"en":"The old law allowed judges to sentence thieves to hang.","zh":"旧法律允许法官判盗贼绞刑。"}]}],"hang on":[{"pos":"phrasal v.","meaning":"抓紧；抓住","definition":"to hold firmly","examples":[{"en":"Hang on to the rail as the boat moves.","zh":"船动起来时抓紧栏杆。"},{"en":"The climber hung on until help arrived.","zh":"登山者一直紧抓不放，直到救援到来。"}]},{"pos":"phrasal v.","meaning":"坚持下去","definition":"to continue despite difficulty","examples":[{"en":"The team hung on and eventually won.","zh":"球队坚持下来，最终获胜。"},{"en":"She hung on through a difficult winter.","zh":"她熬过了艰难的冬天。"}]},{"pos":"phrasal v.","meaning":"等一下；别挂电话","definition":"to wait briefly, especially on the phone","examples":[{"en":"Hang on while I find the number.","zh":"等一下，我找找号码。"},{"en":"Please hang on; I will transfer your call.","zh":"请别挂断，我为您转接。"}]}],"haphazard":[{"pos":"adj.","meaning":"无计划的；杂乱的；随意的","definition":"Lacking clear order or planning.","examples":[{"en":"Books were piled in a haphazard arrangement on the floor.","zh":"书杂乱无章地堆在地板上。"},{"en":"Haphazard sampling made the results unreliable.","zh":"随意取样导致结果不可靠。"}]}],"harbour":[{"pos":"n.","meaning":"港湾;港口","definition":"a sheltered area where ships can stay","examples":[{"en":"Fishing boats returned to the harbour.","zh":"渔船返回了港湾。"},{"en":"A lighthouse guards the harbour entrance.","zh":"灯塔守护着港口入口。"}]},{"pos":"v.","meaning":"庇护;窝藏;停泊","definition":"to give shelter to someone or something","examples":[{"en":"The village harboured refugees during the conflict.","zh":"冲突期间村庄庇护了难民。"},{"en":"The sheltered bay harboured several small boats.","zh":"避风海湾停泊着几艘小船。"}]},{"pos":"v.","meaning":"怀有;心存","definition":"to keep a feeling or thought privately","examples":[{"en":"She harboured doubts about the plan.","zh":"她心里对计划存有疑虑。"},{"en":"He still harbours resentment over the decision.","zh":"他仍对这个决定怀恨在心。"}]}],"harmony":[{"pos":"n.","meaning":"和谐；融洽；一致","definition":"agreement and peaceful cooperation","examples":[{"en":"The neighbours lived in harmony.","zh":"邻居们和睦相处。"},{"en":"The colours work together in harmony.","zh":"这些颜色搭配和谐。"}]},{"pos":"n.","meaning":"和声","definition":"musical notes sounded together pleasantly","examples":[{"en":"The choir sang in close harmony.","zh":"合唱团以密集和声演唱。"},{"en":"She added a harmony above the melody.","zh":"她在旋律上方加了一条和声。"}]}],"harness":[{"pos":"n.","meaning":"马具；挽具；安全带","definition":"Straps used to control an animal or secure a person.","examples":[{"en":"The horse stood still while its harness was fitted.","zh":"装挽具时，马静静地站着。"},{"en":"The climber checked her safety harness before ascending.","zh":"攀岩者在攀登前检查了安全带。"}]},{"pos":"v.","meaning":"给……套上挽具","definition":"To attach straps to an animal for pulling.","examples":[{"en":"They harnessed the horses to the carriage.","zh":"他们把马套在马车上。"},{"en":"The farmer harnessed the mule before loading the cart.","zh":"农民先给骡子套上挽具，然后往车上装货。"}]},{"pos":"v.","meaning":"控制并利用","definition":"To bring a natural force or ability into useful service.","examples":[{"en":"The turbines harness the power of moving water.","zh":"涡轮机利用流动水的能量。"},{"en":"The project harnesses local knowledge to protect the forest.","zh":"这个项目利用当地知识来保护森林。"}]}],"harridan":[{"pos":"n.","meaning":"凶悍的女人（侮辱用语）","definition":"an insulting term for an angry, unpleasant woman","examples":[{"en":"The villain called his formidable neighbour a harridan.","zh":"反派把强硬的女邻居骂作泼妇。"},{"en":"The memoir unfairly portrays the landlady as a harridan.","zh":"回忆录不公地把女房东描绘成凶悍女人。"}]}],"harsh":[{"pos":"adj.","meaning":"严厉的；刻薄的","definition":"severe or unkind","examples":[{"en":"The punishment seemed unusually harsh.","zh":"惩罚似乎异常严厉。"},{"en":"His harsh criticism upset the students.","zh":"他苛刻的批评使学生难过。"}]},{"pos":"adj.","meaning":"恶劣的；严酷的","definition":"very difficult to live in or endure","examples":[{"en":"The crops survived a harsh winter.","zh":"作物熬过了严冬。"},{"en":"Workers faced harsh conditions underground.","zh":"工人们在地下承受恶劣条件。"}]},{"pos":"adj.","meaning":"粗糙刺人的；刺耳的；刺目的","definition":"unpleasantly rough, bright, or loud","examples":[{"en":"The fabric felt harsh against her skin.","zh":"布料贴在皮肤上感觉粗糙刺人。"},{"en":"A harsh alarm interrupted the silence.","zh":"刺耳的警报打破了寂静。"}]}],"hassle":[{"pos":"n.","meaning":"麻烦；困难；烦琐之事","definition":"An annoying difficulty or inconvenient task.","examples":[{"en":"Booking online saved us the hassle of queuing.","zh":"网上预订省去了我们排队的麻烦。"},{"en":"Moving all the furniture upstairs was a real hassle.","zh":"把所有家具搬上楼真是一件麻烦事。"}]},{"pos":"n.","meaning":"争执；口角","definition":"An irritating disagreement or argument.","examples":[{"en":"We had a hassle with the landlord over the repairs.","zh":"我们与房东就维修问题发生了争执。"},{"en":"She left early to avoid another hassle with her colleagues.","zh":"她提前离开，以免再次与同事争吵。"}]}],"hasty":[{"pos":"adj.","meaning":"匆忙的;草率的","definition":"done too quickly or without enough thought","examples":[{"en":"Do not make a hasty decision.","zh":"不要草率决定。"},{"en":"She ate a hasty breakfast before leaving.","zh":"她匆匆吃了早饭就走了。"}]}],"hatch":[{"pos":"v.","meaning":"孵化；孵出","definition":"to emerge or cause young to emerge from eggs","examples":[{"en":"The eggs hatched after three weeks.","zh":"三周后蛋孵化了。"},{"en":"The hen hatched six chicks.","zh":"母鸡孵出了六只小鸡。"}]},{"pos":"v.","meaning":"策划；秘密筹划","definition":"to develop a plan, often secretly","examples":[{"en":"They hatched a plan to surprise their teacher.","zh":"他们策划了一个给老师惊喜的计划。"},{"en":"The plot was hatched in a small back room.","zh":"阴谋是在一间小后屋里策划的。"}]},{"pos":"n.","meaning":"舱门；盖板开口","definition":"an opening with a door or cover","examples":[{"en":"The crew closed the hatch before departure.","zh":"船员在出发前关上舱门。"},{"en":"A ceiling hatch leads to the attic.","zh":"天花板上的活动盖口通往阁楼。"}]}],"haul":[{"pos":"v.","meaning":"用力拖；拉；搬运","definition":"To pull something heavy or transport a large load.","examples":[{"en":"The fishermen hauled the net onto the deck.","zh":"渔民把渔网拖上甲板。"},{"en":"Trucks hauled stone from the quarry to the building site.","zh":"卡车把石料从采石场运到工地。"}]}],"hawk":[{"pos":"n.","meaning":"鹰;隼类猛禽","definition":"a bird of prey with sharp claws and keen sight","examples":[{"en":"A hawk circled above the field.","zh":"一只鹰在田野上空盘旋。"},{"en":"The hawk dived toward its prey.","zh":"鹰俯冲向猎物。"}]}],"hazard":[{"pos":"n.","meaning":"危险；危险因素","definition":"something that can cause harm","examples":[{"en":"Loose cables create a trip hazard.","zh":"松散的电缆构成绊倒危险。"},{"en":"The survey identified several environmental hazards.","zh":"调查发现了几种环境危险因素。"}]},{"pos":"v.","meaning":"冒险提出；试着猜测","definition":"to suggest something despite uncertainty","examples":[{"en":"I would hazard a guess that she is late.","zh":"我冒昧猜测她迟到了。"},{"en":"He hesitated to hazard an opinion.","zh":"他犹豫着不敢轻易发表意见。"}]},{"pos":"v.","meaning":"冒……风险","definition":"to put something valuable at risk","examples":[{"en":"They hazarded their lives to reach the trapped miners.","zh":"他们冒生命危险接近被困矿工。"},{"en":"She would not hazard her reputation on doubtful evidence.","zh":"她不会为可疑的证据拿自己的名誉冒险。"}]}],"hazardous":[{"pos":"adj.","meaning":"危险的；有害的","definition":"Involving a serious risk of harm.","examples":[{"en":"Heavy rain made the mountain road hazardous.","zh":"大雨使山路变得危险。"},{"en":"Workers must wear protection when handling hazardous chemicals.","zh":"工人处理危险化学品时必须穿戴防护装备。"}]}],"headline":[{"pos":"n.","meaning":"大字标题;头条新闻","definition":"a title of a news report or a major news story","examples":[{"en":"The headline caught my attention.","zh":"标题吸引了我的注意。"},{"en":"The rescue dominated the evening headlines.","zh":"救援占据了晚间新闻头条。"}]}],"headmaster":[{"pos":"n.","meaning":"男校长（尤指中小学）","definition":"the male head of a school","examples":[{"en":"The headmaster welcomed the new pupils.","zh":"校长欢迎新生。"},{"en":"Parents met the headmaster to discuss the changes.","zh":"家长与校长会面讨论这些变化。"}]}],"headquarters":[{"pos":"n.","meaning":"总部；总公司；司令部","definition":"The main office or command centre of an organisation.","examples":[{"en":"The organisation moved its headquarters to a larger building.","zh":"该组织把总部迁到了一栋更大的楼里。"},{"en":"All field reports were sent to headquarters.","zh":"所有现场报告都送到了总部。"}]}],"heal":[{"pos":"v.","meaning":"治愈;愈合;康复","definition":"to become or make healthy again","examples":[{"en":"The cut healed without leaving a scar.","zh":"伤口愈合后没有留下疤痕。"},{"en":"Rest helped her injured shoulder heal.","zh":"休息帮助她受伤的肩膀康复。"}]},{"pos":"v.","meaning":"修复关系;调解","definition":"to end a disagreement or emotional hurt","examples":[{"en":"The meeting helped heal the division.","zh":"这次会面有助于消除分歧。"},{"en":"It took years to heal their damaged friendship.","zh":"他们用了多年才修复受损的友谊。"}]}],"healing":[{"pos":"n.","meaning":"愈合；康复；恢复","definition":"the process of becoming healthy or whole again","examples":[{"en":"The wound showed signs of healing.","zh":"伤口出现了愈合迹象。"},{"en":"The meeting began a process of healing within the community.","zh":"会议开启了社区内部的关系修复过程。"}]},{"pos":"adj.","meaning":"有助康复的；有疗愈作用的","definition":"helping recovery or emotional repair","examples":[{"en":"She valued the healing effect of quiet conversation.","zh":"她看重平静交谈带来的疗愈效果。"},{"en":"The story describes the healing power of friendship.","zh":"故事描写了友谊的疗愈力量。"}]}],"heap":[{"pos":"n.","meaning":"一堆；大量","definition":"A pile or a large amount of something.","examples":[{"en":"A heap of wet clothes lay beside the washing machine.","zh":"洗衣机旁放着一堆湿衣服。"},{"en":"We still have heaps of work to do.","zh":"我们还有大量工作要做。"}]},{"pos":"v.","meaning":"堆积；大量给予","definition":"To put things in a pile or give something in large amounts.","examples":[{"en":"She heaped the fallen leaves into a corner.","zh":"她把落叶堆到一个角落里。"},{"en":"Critics heaped praise on the young pianist.","zh":"评论家对这位年轻钢琴家赞不绝口。"}]}],"heartless":[{"pos":"adj.","meaning":"无情的;狠心的","definition":"showing no sympathy or kindness","examples":[{"en":"It was a heartless response to her distress.","zh":"面对她的痛苦，那回应十分无情。"},{"en":"The landlord's heartless decision left them homeless.","zh":"房东狠心的决定使他们无家可归。"}]},{"pos":"adj.","meaning":"灰心的;没精打采的（古义）","definition":"lacking courage or enthusiasm in archaic usage","examples":[{"en":"After repeated defeats, the heartless soldiers abandoned hope.","zh":"屡遭败绩后，灰心的士兵们放弃了希望。"},{"en":"He returned heartless and weary from his fruitless quest.","zh":"他寻觅无果，灰心疲惫地归来。"}]}],"hectare":[{"pos":"n.","meaning":"公顷（10000平方米）","definition":"a unit of area equal to ten thousand square metres","examples":[{"en":"The farm covers fifty hectares.","zh":"农场占地五十公顷。"},{"en":"One hectare of land was set aside for a park.","zh":"一公顷土地被划作公园。"}]}],"height":[{"pos":"n.","meaning":"高度；身高；海拔","definition":"The distance from the bottom to the top, or above a reference level.","examples":[{"en":"The nurse measured the child's height.","zh":"护士测量了孩子的身高。"},{"en":"The aircraft maintained a height of three thousand metres.","zh":"飞机保持在三千米的高度。"}]}],"heighten":[{"pos":"v.","meaning":"增强;加剧","definition":"to make or become more intense","examples":[{"en":"The music heightened the sense of suspense.","zh":"音乐增强了悬念感。"},{"en":"The warning heightened public concern.","zh":"警告加剧了公众的担忧。"}]}],"heir":[{"pos":"n.","meaning":"继承人；后继者","definition":"a person entitled to inherit property or a position","examples":[{"en":"She was named heir to the estate.","zh":"她被指定为遗产继承人。"},{"en":"The museum considers itself an heir to that artistic tradition.","zh":"博物馆自视为那一艺术传统的继承者。"}]}],"helicopter":[{"pos":"n.","meaning":"直升机","definition":"An aircraft supported and moved by rotating blades above it.","examples":[{"en":"A helicopter carried supplies to the isolated village.","zh":"一架直升机把补给运到了与外界隔绝的村庄。"},{"en":"We heard the helicopter before we saw it above the trees.","zh":"我们还没看见树梢上的直升机，就先听到了声音。"}]}],"helix":[{"pos":"n.","meaning":"螺旋;螺旋结构","definition":"a curve winding around an axis","examples":[{"en":"The staircase forms a graceful helix.","zh":"楼梯呈优美的螺旋形。"},{"en":"DNA has a double-helix structure.","zh":"DNA 具有双螺旋结构。"}]}],"hemisphere":[{"pos":"n.","meaning":"半球；地球半球","definition":"one half of a sphere or of Earth","examples":[{"en":"Australia lies in the Southern Hemisphere.","zh":"澳大利亚位于南半球。"},{"en":"The model separates the globe into two hemispheres.","zh":"模型把地球分成两个半球。"}]},{"pos":"n.","meaning":"大脑半球","definition":"either half of the cerebrum","examples":[{"en":"The scan showed activity in both hemispheres.","zh":"扫描显示两个大脑半球都有活动。"},{"en":"The diagram labels the brain's left hemisphere.","zh":"图中标出了大脑左半球。"}]}],"hence":[{"pos":"adv.","meaning":"因此；所以","definition":"For this reason.","examples":[{"en":"The roads were flooded, hence the delay.","zh":"道路被淹了，因此发生了延误。"},{"en":"The sample was too small; hence the need for further research.","zh":"样本太小，因此需要进一步研究。"}]},{"pos":"adv.","meaning":"从现在起；今后","definition":"From the present time.","examples":[{"en":"The building should be complete two years hence.","zh":"这栋楼应该在两年后竣工。"},{"en":"A decade hence, the coastline may look quite different.","zh":"十年之后，海岸线可能会大不相同。"}]}],"herbal":[{"pos":"adj.","meaning":"草本的;药草制成的","definition":"relating to or made from herbs","examples":[{"en":"She ordered a cup of herbal tea.","zh":"她点了一杯花草茶。"},{"en":"The garden contains many herbal plants.","zh":"花园种有许多药草植物。"}]},{"pos":"n.","meaning":"草本植物志;药草书","definition":"a book describing plants and their uses","examples":[{"en":"The library owns a medieval herbal.","zh":"图书馆藏有一本中世纪药草书。"},{"en":"Detailed drawings fill the pages of the herbal.","zh":"药草书中满是精细插图。"}]}],"herbivore":[{"pos":"n.","meaning":"食草动物；植食性动物","definition":"an animal that eats plants","examples":[{"en":"A rabbit is a small herbivore.","zh":"兔子是一种小型植食动物。"},{"en":"Large herbivores graze on the open plain.","zh":"大型食草动物在开阔平原上吃草。"}]}],"herdsman":[{"pos":"n.","meaning":"牧人；牧民","definition":"A person who looks after a herd of animals.","examples":[{"en":"The herdsman led his cattle towards the river.","zh":"牧人带着牛群向河边走去。"},{"en":"A young herdsman showed us the path across the grassland.","zh":"一位年轻牧民给我们指了穿过草原的路。"}]}],"hereditary":[{"pos":"adj.","meaning":"遗传的","definition":"passed biologically from parents to children","examples":[{"en":"The clinic studies hereditary disorders.","zh":"诊所研究遗传性疾病。"},{"en":"Eye colour has a hereditary component.","zh":"眼睛颜色具有遗传因素。"}]},{"pos":"adj.","meaning":"世袭的;可继承的","definition":"passed through a family by inheritance","examples":[{"en":"The title was hereditary.","zh":"这个头衔是世袭的。"},{"en":"The reform abolished hereditary privileges.","zh":"改革废除了世袭特权。"}]}],"heritage":[{"pos":"n.","meaning":"文化遗产；传承","definition":"traditions and valued things passed down from the past","examples":[{"en":"Old buildings are part of the city's heritage.","zh":"古老建筑是城市文化遗产的一部分。"},{"en":"The museum helps preserve local heritage.","zh":"博物馆有助于保护当地文化遗产。"},{"en":"Tourism can provide funds to protect cultural heritage.","zh":"旅游业可以为保护文化遗产提供资金。"}]}],"hesitate":[{"pos":"v.","meaning":"犹豫；迟疑；不情愿","definition":"To pause because of uncertainty or reluctance.","examples":[{"en":"She hesitated before answering the difficult question.","zh":"回答这个难题前，她犹豫了一下。"},{"en":"Do not hesitate to ask for help if you need it.","zh":"如果需要帮助，请不要犹豫。"}]}],"hesitation":[{"pos":"n.","meaning":"犹豫;迟疑","definition":"a pause caused by uncertainty","examples":[{"en":"She accepted the offer without hesitation.","zh":"她毫不犹豫地接受了提议。"},{"en":"A brief hesitation suggested he was unsure.","zh":"短暂的迟疑表明他并不确定。"}]}],"hiccup":[{"pos":"n.","meaning":"打嗝；呃逆","definition":"a sudden involuntary breath with a short sound","examples":[{"en":"A hiccup interrupted his sentence.","zh":"一个嗝打断了他的话。"},{"en":"The baby had a bout of hiccups.","zh":"婴儿打了一阵嗝。"}]},{"pos":"n.","meaning":"小故障；暂时的挫折","definition":"a minor temporary problem","examples":[{"en":"A technical hiccup delayed the presentation.","zh":"一个技术小故障推迟了演示。"},{"en":"The launch went well apart from a few hiccups.","zh":"除了几个小问题，发布进行得很顺利。"}]},{"pos":"v.","meaning":"打嗝","definition":"to make the sound of a hiccup","examples":[{"en":"She began to hiccup after drinking quickly.","zh":"她喝得太快后开始打嗝。"},{"en":"The child hiccupped during the story.","zh":"孩子听故事时打了嗝。"}]}],"hide":[{"pos":"v.","meaning":"隐藏；躲藏；隐瞒","definition":"To put or keep something out of sight or knowledge.","examples":[{"en":"The children hid behind the curtains.","zh":"孩子们躲在窗帘后面。"},{"en":"He tried to hide his disappointment.","zh":"他试图掩饰自己的失望。"}]},{"pos":"n.","meaning":"兽皮；皮革","definition":"The skin of a large animal, especially when used to make leather.","examples":[{"en":"The tent was traditionally covered with animal hides.","zh":"这种帐篷传统上用兽皮覆盖。"},{"en":"The tanner soaked the hides before processing them.","zh":"制革工人在加工前把兽皮浸泡起来。"}]}],"hierarchy":[{"pos":"n.","meaning":"等级体系;层级","definition":"a system arranged in levels of authority or importance","examples":[{"en":"The company has a rigid hierarchy.","zh":"公司有严格的等级体系。"},{"en":"The diagram shows a hierarchy of needs.","zh":"图表展示了需求层次。"}]},{"pos":"n.","meaning":"领导层","definition":"the people holding high positions in an organization","examples":[{"en":"The church hierarchy approved the change.","zh":"教会高层批准了这项变动。"},{"en":"Workers appealed directly to the corporate hierarchy.","zh":"工人直接向公司领导层申诉。"}]}],"high-tech":[{"pos":"n.","meaning":"高科技","definition":"advanced technology","examples":[{"en":"The region invests heavily in high-tech.","zh":"该地区大力投资高科技。"},{"en":"High-tech has changed how the factory operates.","zh":"高科技改变了工厂的运作方式。"}]},{"pos":"adj.","meaning":"高科技的","definition":"using advanced technology","examples":[{"en":"The hospital installed high-tech equipment.","zh":"医院安装了高科技设备。"},{"en":"A high-tech sensor monitors the water level.","zh":"一个高科技传感器监测水位。"}]}],"highland":[{"pos":"n.","meaning":"高地；高原地区","definition":"An area of land that is higher than the surrounding land.","examples":[{"en":"She grew up in the highlands far from the coast.","zh":"她在远离海岸的高地长大。"},{"en":"The northern highlands are covered with forests.","zh":"北部高地覆盖着森林。"}]}],"highlight":[{"pos":"v.","meaning":"突出;强调;使显眼","definition":"to draw special attention to something","examples":[{"en":"The report highlights gaps in training.","zh":"报告强调了培训的不足。"},{"en":"Soft lighting highlights the sculpture's curves.","zh":"柔和灯光突出了雕塑的曲线。"}]},{"pos":"n.","meaning":"最精彩部分;最重要事件","definition":"the best or most important part","examples":[{"en":"The waterfall was the highlight of our trip.","zh":"瀑布是我们旅程中最精彩的部分。"},{"en":"The programme showed highlights of the match.","zh":"节目播放了比赛集锦。"}]}],"highway":[{"pos":"n.","meaning":"公路；干道","definition":"a major public road","examples":[{"en":"The highway connects the two cities.","zh":"这条公路连接两个城市。"},{"en":"We stopped at a cafe beside the highway.","zh":"我们在公路旁的咖啡馆停留。"}]}],"hike":[{"pos":"v.","meaning":"徒步旅行；远足","definition":"To walk a long distance, especially in the countryside.","examples":[{"en":"We hiked along the ridge until sunset.","zh":"我们沿着山脊徒步走到日落。"},{"en":"They plan to hike through the national park.","zh":"他们计划徒步穿越国家公园。"}]},{"pos":"v.","meaning":"大幅提高；猛增","definition":"To increase a price or amount sharply.","examples":[{"en":"The landlord hiked the rent after renovating the flat.","zh":"房东翻修公寓后大幅提高了租金。"},{"en":"The airline hiked fares during the holiday period.","zh":"航空公司在假期大幅提高了票价。"}]},{"pos":"n.","meaning":"徒步旅行；远足","definition":"A long walk in the countryside.","examples":[{"en":"The hike took us through pine forests and open meadows.","zh":"这次远足带我们穿过松林和开阔草地。"},{"en":"Take plenty of water on a summer hike.","zh":"夏季远足时要带足饮用水。"}]},{"pos":"n.","meaning":"大幅上涨；猛增","definition":"A sudden or substantial increase.","examples":[{"en":"The price hike forced customers to reconsider their plans.","zh":"价格大涨迫使顾客重新考虑计划。"},{"en":"Workers objected to the hike in transport charges.","zh":"工人反对交通费用的大幅上涨。"}]}],"hinder":[{"pos":"v.","meaning":"阻碍","definition":"to make progress or an action more difficult","examples":[{"en":"Heavy rain can hinder our progress.","zh":"大雨会阻碍我们的进展。"},{"en":"A lack of sleep may hinder learning.","zh":"睡眠不足可能会妨碍学习。"},{"en":"Do not let fear hinder your plans.","zh":"不要让恐惧阻碍你的计划。"}]}],"hinge":[{"pos":"n.","meaning":"铰链","definition":"a joint that allows a door to swing open","examples":[{"en":"The door made a noise because the hinge was rusty.","zh":"门因为铰链生锈而发出声响。"},{"en":"We put some oil on the hinge.","zh":"我们给铰链上了一些油。"},{"en":"A broken hinge made the door hard to close.","zh":"坏掉的铰链让门很难关上。"}]},{"pos":"v.","meaning":"取决于；以……为转移（常与 on 连用）","definition":"to depend entirely on something","examples":[{"en":"Success hinges on careful preparation.","zh":"成功取决于周密准备。"},{"en":"The decision hinges on the survey results.","zh":"决定取决于调查结果。"}]}],"hinterland":[{"pos":"n.","meaning":"腹地；内陆；内地","definition":"The inland region behind a coast, port, or city.","examples":[{"en":"The railway connects the port with its agricultural hinterland.","zh":"铁路把港口与农业腹地连接起来。"},{"en":"Few tourists venture into the rugged hinterland.","zh":"很少有游客深入崎岖的内陆地区。"}]}],"hire":[{"pos":"v.","meaning":"租用","definition":"to pay for temporary use","examples":[{"en":"We hired bicycles for the afternoon.","zh":"我们租了自行车用一下午。"},{"en":"The club hired a hall for its meeting.","zh":"俱乐部租了大厅开会。"}]},{"pos":"v.","meaning":"雇用","definition":"to employ someone for payment","examples":[{"en":"The restaurant hired two new cooks.","zh":"餐厅雇了两名新厨师。"},{"en":"They hired a guide to lead the trek.","zh":"他们雇了一名向导带队徒步。"}]},{"pos":"n.","meaning":"租用;租金","definition":"temporary use in exchange for payment","examples":[{"en":"The price includes equipment hire.","zh":"价格包含设备租赁费。"},{"en":"Boats are available for hire at the lake.","zh":"湖边有船可租。"}]},{"pos":"n.","meaning":"雇用;新雇员","definition":"the act of employing or a newly employed person","examples":[{"en":"The new hire starts work on Monday.","zh":"新雇员周一上班。"},{"en":"The manager approved the hire of another engineer.","zh":"经理批准再雇一位工程师。"}]}],"historian":[{"pos":"n.","meaning":"历史学家；历史研究者","definition":"a person who studies or writes about history","examples":[{"en":"The historian examined letters from the period.","zh":"历史学家研究了那个时期的信件。"},{"en":"Local historians helped identify the building.","zh":"地方历史研究者帮助辨认了这栋建筑。"}]}],"historic":[{"pos":"adj.","meaning":"有重大历史意义的；历史性的","definition":"Important in history or likely to be remembered.","examples":[{"en":"The two countries signed a historic peace agreement.","zh":"两国签署了一份具有历史意义的和平协议。"},{"en":"Visitors can tour the city's historic buildings.","zh":"游客可以参观这座城市的历史建筑。"}]}],"hitherto":[{"pos":"adv.","meaning":"迄今;此前","definition":"until now or until the time mentioned","examples":[{"en":"The document revealed hitherto unknown details.","zh":"文件披露了此前不为人知的细节。"},{"en":"Hitherto, all payments had been made in cash.","zh":"在此之前，所有付款都使用现金。"}]}],"hive":[{"pos":"n.","meaning":"蜂箱；蜂巢","definition":"a structure in which bees live","examples":[{"en":"The beekeeper inspected the hive.","zh":"养蜂人检查了蜂箱。"},{"en":"Bees returned to the hive at dusk.","zh":"蜜蜂在黄昏返回蜂巢。"}]},{"pos":"n.","meaning":"一群蜜蜂","definition":"a colony of bees living together","examples":[{"en":"The hive produced less honey this year.","zh":"这群蜜蜂今年产蜜较少。"},{"en":"A healthy hive survived the winter.","zh":"一群健康的蜜蜂度过了冬天。"}]},{"pos":"n.","meaning":"忙碌场所（常用于 a hive of activity）","definition":"a place full of busy activity","examples":[{"en":"The kitchen was a hive of activity.","zh":"厨房里一片忙碌。"},{"en":"The station became a hive of activity before dawn.","zh":"天未亮车站就忙碌起来。"}]},{"pos":"v.","meaning":"使进入蜂箱；群居","definition":"to place bees in a hive or gather together","examples":[{"en":"The beekeeper hived the new swarm.","zh":"养蜂人把新蜂群放进蜂箱。"},{"en":"The bees hived in a hollow tree.","zh":"蜜蜂在一棵空心树里聚居。"}]}],"hockey":[{"pos":"n.","meaning":"曲棍球","definition":"A team sport played on a field with curved sticks and a small ball.","examples":[{"en":"She joined the school hockey team.","zh":"她加入了学校曲棍球队。"},{"en":"The hockey match was postponed because the field was flooded.","zh":"由于场地被淹，曲棍球比赛延期了。"}]},{"pos":"n.","meaning":"冰球（尤其用于北美）","definition":"A team sport played on ice with sticks and a puck.","examples":[{"en":"The hockey players stepped onto the ice for practice.","zh":"冰球运动员踏上冰面开始训练。"},{"en":"We watched a hockey game at the indoor rink.","zh":"我们在室内冰场观看了一场冰球比赛。"}]}],"holistic":[{"pos":"adj.","meaning":"整体的;全面的","definition":"considering all interconnected parts of something","examples":[{"en":"The school takes a holistic approach to education.","zh":"学校采取整体教育方法。"},{"en":"We need a holistic assessment of the neighbourhood.","zh":"我们需要对社区作全面评估。"}]}],"holistically":[{"pos":"adv.","meaning":"整体地；全盘地","definition":"by considering all parts together","examples":[{"en":"The team assessed the neighbourhood holistically.","zh":"团队从整体上评估了这个街区。"},{"en":"We must view transport and housing holistically.","zh":"我们必须把交通和住房放在一起全盘考虑。"}]}],"hollow":[{"pos":"adj.","meaning":"空心的；空洞的","definition":"Having an empty space inside.","examples":[{"en":"The bird nested inside a hollow tree.","zh":"鸟在一棵空心树里筑巢。"},{"en":"The sculpture is hollow, so it is lighter than it looks.","zh":"雕塑是空心的，因此比看起来轻。"}]},{"pos":"adj.","meaning":"低沉而空洞的；闷响的","definition":"Having a deep sound like that produced in an empty space.","examples":[{"en":"A hollow knock came from behind the wall.","zh":"墙后传来空洞的敲击声。"},{"en":"His footsteps made a hollow sound on the wooden floor.","zh":"他的脚步在木地板上发出空洞的声响。"}]},{"pos":"adj.","meaning":"空虚的；虚伪的；无实质的","definition":"Lacking sincerity, value, or emotional satisfaction.","examples":[{"en":"Their promise of reform sounded hollow.","zh":"他们改革的承诺听起来很空洞。"},{"en":"The victory felt hollow without her teammates there.","zh":"没有队友在场，这场胜利让她觉得空虚。"}]},{"pos":"v.","meaning":"挖空；凿空","definition":"To remove the inside of something.","examples":[{"en":"They hollowed out a log to make a canoe.","zh":"他们把一根原木挖空做成独木舟。"},{"en":"The sculptor hollowed the centre of the block.","zh":"雕刻家把石块的中心凿空了。"}]}],"homesick":[{"pos":"adj.","meaning":"想家的;思乡的","definition":"sad because of being away from home","examples":[{"en":"She felt homesick during her first week abroad.","zh":"出国第一周她很想家。"},{"en":"A familiar song made him homesick.","zh":"一首熟悉的歌勾起了他的思乡之情。"}]}],"homestay":[{"pos":"n.","meaning":"寄宿当地家庭；家庭寄宿期","definition":"a stay in the home of local residents","examples":[{"en":"Her homestay helped her practise English daily.","zh":"她寄宿当地家庭的经历帮助她每天练习英语。"},{"en":"The school arranged a two-week homestay.","zh":"学校安排了两周的家庭寄宿。"}]}],"homogeneous":[{"pos":"adj.","meaning":"同质的；同种类的；由相似成员组成的","definition":"Consisting of parts or people that are similar throughout.","examples":[{"en":"Stir until the mixture is homogeneous.","zh":"搅拌至混合物均匀一致。"},{"en":"The survey should not treat all rural communities as homogeneous.","zh":"调查不应把所有农村社区视为完全同质。"}]}],"honour":[{"pos":"n.","meaning":"尊敬;荣誉;光荣","definition":"respect or public recognition of achievement","examples":[{"en":"The award is a great honour.","zh":"这个奖项是一项很大的荣誉。"},{"en":"They held a dinner in her honour.","zh":"他们设宴向她致敬。"}]},{"pos":"v.","meaning":"向……致敬;表彰","definition":"to show respect or give recognition","examples":[{"en":"The town honoured its rescue workers.","zh":"镇上表彰了救援人员。"},{"en":"The ceremony honours those who served.","zh":"仪式向服役者致敬。"}]},{"pos":"v.","meaning":"遵守;履行","definition":"to keep a promise or agreement","examples":[{"en":"The company honoured its warranty.","zh":"公司履行了保修承诺。"},{"en":"Both sides agreed to honour the ceasefire.","zh":"双方同意遵守停火协议。"}]}],"hook":[{"pos":"n.","meaning":"钩；挂钩","definition":"a curved piece used for hanging or catching","examples":[{"en":"Hang the coat on the hook.","zh":"把外套挂在钩上。"},{"en":"The crane lifted the beam with a large hook.","zh":"起重机用大吊钩吊起横梁。"}]},{"pos":"v.","meaning":"钩住；挂住","definition":"to attach with a hook","examples":[{"en":"She hooked the bag over the chair.","zh":"她把包挂在椅子上。"},{"en":"The cable hooked onto the metal ring.","zh":"缆绳钩住了金属环。"}]},{"pos":"v.","meaning":"用钩钓住","definition":"to catch a fish with a hook","examples":[{"en":"He hooked a large trout.","zh":"他钓住了一条大鳟鱼。"},{"en":"The angler hooked two fish before noon.","zh":"钓鱼者中午前钓到了两条鱼。"}]}],"horizon":[{"pos":"n.","meaning":"地平线","definition":"The line where the sky seems to meet the land or sea.","examples":[{"en":"A ship appeared on the horizon.","zh":"一艘船出现在地平线上。"},{"en":"The sun sank below the western horizon.","zh":"太阳沉到了西边的地平线以下。"}]},{"pos":"n.","meaning":"眼界；见识范围；视野","definition":"The limits of a person's knowledge or experience.","examples":[{"en":"Studying abroad broadened her horizons.","zh":"出国留学开阔了她的眼界。"},{"en":"The course encourages students to look beyond their usual horizons.","zh":"这门课程鼓励学生超越自己惯常的认知范围。"}]}],"horizontal":[{"pos":"adj.","meaning":"水平的;横向的","definition":"parallel to the horizon or level ground","examples":[{"en":"Draw a horizontal line across the page.","zh":"横穿纸页画一条水平线。"},{"en":"Keep the shelf horizontal during installation.","zh":"安装时保持架子水平。"}]}],"horrify":[{"pos":"v.","meaning":"使惊骇；使震惊；使厌恶","definition":"to cause great shock, fear, or disgust","examples":[{"en":"The photographs horrified the investigators.","zh":"照片令调查人员震惊。"},{"en":"She was horrified by the waste of food.","zh":"她对浪费食物感到极为反感。"}]}],"horror":[{"pos":"n.","meaning":"恐怖；惊恐；厌恶","definition":"A strong feeling of fear, shock, or disgust.","examples":[{"en":"They watched in horror as the roof collapsed.","zh":"屋顶倒塌时，他们惊恐地看着。"},{"en":"She has a horror of being trapped in a lift.","zh":"她非常害怕被困在电梯里。"}]}],"hose":[{"pos":"n.","meaning":"软管","definition":"a flexible tube carrying liquid or gas","examples":[{"en":"The hose carries water to the garden.","zh":"软管把水送到花园。"},{"en":"A leak developed in the fuel hose.","zh":"燃油软管出现了泄漏。"}]},{"pos":"v.","meaning":"用软管冲洗","definition":"to wash or spray using a hose","examples":[{"en":"They hosed mud off the bicycles.","zh":"他们用软管冲掉自行车上的泥。"},{"en":"Hose the patio before the guests arrive.","zh":"客人来之前用软管冲洗露台。"}]}],"hospitable":[{"pos":"adj.","meaning":"好客的；热情友好的","definition":"welcoming and generous to guests","examples":[{"en":"Our hosts were exceptionally hospitable.","zh":"主人格外热情好客。"},{"en":"The village is known for its hospitable residents.","zh":"村庄以居民好客而闻名。"}]},{"pos":"adj.","meaning":"适宜生活的；宜人的","definition":"offering favourable living conditions","examples":[{"en":"The valley has a hospitable climate.","zh":"山谷气候宜人。"},{"en":"The soil is hospitable to many plants.","zh":"这种土壤适宜许多植物生长。"}]},{"pos":"adj.","meaning":"乐于接受的；开通的（常与 to 连用）","definition":"receptive to new ideas or influences","examples":[{"en":"The department is hospitable to new approaches.","zh":"这个部门乐于接受新方法。"},{"en":"She found a community hospitable to creative experiments.","zh":"她找到了一个欢迎创造性实验的群体。"}]}],"hospitality":[{"pos":"n.","meaning":"好客；热情款待；招待","definition":"Friendly and generous treatment of guests.","examples":[{"en":"We thanked the family for their warm hospitality.","zh":"我们感谢这家人的热情款待。"},{"en":"The village is known for its hospitality to travellers.","zh":"这个村庄以热情招待旅行者而闻名。"}]}],"host":[{"pos":"n.","meaning":"主人;东道主;主持人","definition":"a person or organization receiving guests or presenting an event","examples":[{"en":"Our host welcomed us warmly.","zh":"主人热情欢迎我们。"},{"en":"The radio host introduced the speaker.","zh":"电台主持人介绍了发言者。"}]},{"pos":"n.","meaning":"许多;大量","definition":"a large number of people or things","examples":[{"en":"The change created a host of problems.","zh":"变化产生了一大堆问题。"},{"en":"A host of volunteers offered help.","zh":"许多志愿者主动提供帮助。"}]},{"pos":"v.","meaning":"主办;招待","definition":"to organize an event or receive guests","examples":[{"en":"The city will host the tournament.","zh":"这座城市将主办锦标赛。"},{"en":"They hosted a dinner for the visiting scholars.","zh":"他们设宴招待来访学者。"}]}],"hostel":[{"pos":"n.","meaning":"廉价旅舍；青年旅舍；集体宿舍","definition":"inexpensive shared accommodation","examples":[{"en":"We booked beds in a youth hostel.","zh":"我们在青年旅舍订了床位。"},{"en":"The students stayed in a hostel near campus.","zh":"学生们住在校园附近的集体宿舍。"}]}],"hostile":[{"pos":"adj.","meaning":"敌对的；不友善的","definition":"Unfriendly or strongly opposed.","examples":[{"en":"The proposal received a hostile response from residents.","zh":"居民对这个提案作出了强烈反对的回应。"},{"en":"The two armies faced each other across hostile territory.","zh":"两支军队在敌对地区隔地相望。"}]},{"pos":"adj.","meaning":"不利的；恶劣的","definition":"Difficult or dangerous for life or an activity.","examples":[{"en":"Few plants survive in this hostile environment.","zh":"很少有植物能在这种恶劣环境中生存。"},{"en":"The new business faced a hostile economic climate.","zh":"这家新企业面临不利的经济环境。"}]}],"hostility":[{"pos":"n.","meaning":"敌意;反对;抵制","definition":"strong opposition or unfriendly feelings","examples":[{"en":"She faced hostility from some colleagues.","zh":"她遭到一些同事的敌视。"},{"en":"The proposal met widespread hostility.","zh":"提案遭到广泛反对。"}]},{"pos":"n.","meaning":"战事;交战（常用复数）","definition":"acts of warfare","examples":[{"en":"Hostilities ceased after the treaty was signed.","zh":"条约签署后战事停止。"},{"en":"Both sides prepared for renewed hostilities.","zh":"双方准备再次交战。"}]}],"household":[{"pos":"n.","meaning":"家庭；一户人家","definition":"all the people living together in one home","examples":[{"en":"Each household received a survey form.","zh":"每户人家都收到一份调查表。"},{"en":"There are four people in our household.","zh":"我们家有四口人。"}]},{"pos":"adj.","meaning":"家用的；家庭的","definition":"relating to a home and its daily needs","examples":[{"en":"The shop sells household appliances.","zh":"商店出售家用电器。"},{"en":"Rising household costs concern many families.","zh":"家庭开支上涨令许多家庭担忧。"}]},{"pos":"adj.","meaning":"家喻户晓的（常用于 household name）","definition":"widely known by the public","examples":[{"en":"The programme made her a household name.","zh":"这个节目使她家喻户晓。"},{"en":"The brand became a household word.","zh":"这个品牌成了家喻户晓的名字。"}]}],"hover":[{"pos":"v.","meaning":"悬停；盘旋","definition":"To remain in the air over one place.","examples":[{"en":"A helicopter hovered above the damaged bridge.","zh":"一架直升机悬停在受损桥梁上方。"},{"en":"A hummingbird hovered beside the flowers.","zh":"一只蜂鸟在花旁悬停。"}]},{"pos":"v.","meaning":"徘徊；逗留在近旁","definition":"To stay close by, often while waiting or feeling uncertain.","examples":[{"en":"The waiter hovered near our table.","zh":"服务员在我们桌子附近徘徊。"},{"en":"She hovered by the door, unsure whether to enter.","zh":"她在门边徘徊，不确定是否该进去。"}]},{"pos":"v.","meaning":"犹豫；在某一水平附近波动","definition":"To remain uncertain between choices or close to a particular level.","examples":[{"en":"He hovered between accepting the offer and staying at home.","zh":"他在接受邀请和留在家中之间犹豫不决。"},{"en":"Temperatures hovered around freezing all night.","zh":"气温整夜在冰点附近徘徊。"}]}],"however":[{"pos":"adv.","meaning":"然而;不过","definition":"used to introduce a contrasting point","examples":[{"en":"The room is small; however, it is comfortable.","zh":"房间虽小，不过很舒适。"},{"en":"She was tired. However, she kept working.","zh":"她很累，然而仍继续工作。"}]},{"pos":"adv.","meaning":"无论多么;不管怎样","definition":"to whatever extent or in whatever way","examples":[{"en":"However hard he tried, the door would not open.","zh":"无论他多么用力，门都打不开。"},{"en":"Arrange the chairs however you prefer.","zh":"按你喜欢的方式摆放椅子。"}]}],"huddle":[{"pos":"v.","meaning":"挤在一起；聚拢","definition":"to crowd closely together","examples":[{"en":"The children huddled under one umbrella.","zh":"孩子们挤在一把伞下。"},{"en":"We huddled around the small fire.","zh":"我们围拢在小火堆旁。"}]},{"pos":"n.","meaning":"挤在一起的人群或物品","definition":"a closely packed group","examples":[{"en":"The players formed a huddle before the match.","zh":"队员们赛前围成一团。"},{"en":"A huddle of cottages stood by the stream.","zh":"一簇拥挤的小屋立在溪边。"}]}],"hug":[{"pos":"v.","meaning":"拥抱；紧抱","definition":"To hold someone closely in one's arms.","examples":[{"en":"She hugged her brother when he arrived.","zh":"哥哥到达时，她拥抱了他。"},{"en":"The child hugged a soft toy during the journey.","zh":"旅途中，孩子紧抱着一个毛绒玩具。"}]},{"pos":"n.","meaning":"拥抱","definition":"An act of holding someone closely in the arms.","examples":[{"en":"He gave his daughter a long hug.","zh":"他长久地拥抱了女儿。"},{"en":"A hug from a friend helped her feel less alone.","zh":"朋友的一个拥抱让她不再那么孤独。"}]}],"hum":[{"pos":"n.","meaning":"嗡嗡声;低沉嘈杂声","definition":"a continuous low sound","examples":[{"en":"The hum of traffic kept him awake.","zh":"车流的低沉噪声使他无法入睡。"},{"en":"A soft hum came from the refrigerator.","zh":"冰箱传出轻微的嗡嗡声。"}]},{"pos":"v.","meaning":"哼唱","definition":"to sing with closed lips","examples":[{"en":"She hummed a familiar tune.","zh":"她哼着熟悉的曲子。"},{"en":"He hummed quietly while washing dishes.","zh":"他洗碗时轻声哼唱。"}]},{"pos":"v.","meaning":"发嗡嗡声","definition":"to make a continuous low sound","examples":[{"en":"Bees hummed among the flowers.","zh":"蜜蜂在花间嗡嗡飞舞。"},{"en":"The engine hummed steadily.","zh":"发动机平稳地嗡嗡作响。"}]}],"humane":[{"pos":"adj.","meaning":"人道的；仁慈的","definition":"showing compassion and avoiding cruelty","examples":[{"en":"The shelter promotes humane treatment of animals.","zh":"收容所提倡人道对待动物。"},{"en":"They called for a more humane approach.","zh":"他们呼吁采取更人道的方式。"}]},{"pos":"adj.","meaning":"人文学科的；陶冶人文素养的（正式用法）","definition":"relating to learning that develops human culture","examples":[{"en":"The university awarded her a doctorate of humane letters.","zh":"大学授予她人文学荣誉博士学位。"},{"en":"The college defended the value of humane studies.","zh":"学院捍卫人文研究的价值。"}]}],"humanistic":[{"pos":"adj.","meaning":"人文主义的；重视人的价值与需要的","definition":"Emphasising human dignity, interests, and potential.","examples":[{"en":"The course takes a humanistic approach to education.","zh":"这门课程采取重视人的价值的教育方式。"},{"en":"Her research explores the humanistic ideas of Renaissance writers.","zh":"她的研究探讨文艺复兴时期作家的人文主义思想。"}]}],"humanity":[{"pos":"n.","meaning":"人类","definition":"all human beings","examples":[{"en":"Climate change presents a challenge to humanity.","zh":"气候变化给人类带来挑战。"},{"en":"The discovery could benefit all humanity.","zh":"这项发现可能造福全人类。"}]},{"pos":"n.","meaning":"人性;仁慈;人道","definition":"human qualities, especially kindness","examples":[{"en":"The judge treated him with humanity.","zh":"法官以人道方式对待他。"},{"en":"The novel explores our shared humanity.","zh":"小说探索我们共同的人性。"}]},{"pos":"n.","meaning":"人文学科（复数 humanities）","definition":"subjects studying human culture and thought","examples":[{"en":"She teaches courses in the humanities.","zh":"她教授人文学科课程。"},{"en":"The university supports both sciences and humanities.","zh":"大学同时支持自然科学和人文学科。"}]}],"humble":[{"pos":"adj.","meaning":"谦虚的；谦逊的","definition":"not proud or boastful","examples":[{"en":"Despite her success, she remained humble.","zh":"尽管成功，她仍保持谦逊。"},{"en":"He offered a humble apology.","zh":"他谦恭地道歉。"}]},{"pos":"adj.","meaning":"地位低微的；简陋的","definition":"low in social status or modest in size and quality","examples":[{"en":"The artist came from humble beginnings.","zh":"艺术家出身寒微。"},{"en":"They welcomed us into their humble home.","zh":"他们请我们进入简陋的家。"}]},{"pos":"v.","meaning":"使谦逊；使感到卑微","definition":"to make someone less proud","examples":[{"en":"The defeat humbled the champions.","zh":"失败使冠军队变得谦逊。"},{"en":"I was humbled by their generosity.","zh":"他们的慷慨令我自感渺小。"}]}],"humid":[{"pos":"adj.","meaning":"潮湿的；湿热的","definition":"Containing a large amount of water vapour in the air.","examples":[{"en":"The air felt hot and humid before the storm.","zh":"暴风雨来临前，空气又热又湿。"},{"en":"These plants thrive in a humid greenhouse.","zh":"这些植物在潮湿的温室里生长旺盛。"}]}],"humidity":[{"pos":"n.","meaning":"湿度;潮湿","definition":"the amount of water vapour in the air","examples":[{"en":"High humidity made the heat uncomfortable.","zh":"高湿度使炎热更难忍受。"},{"en":"The museum controls humidity to protect paintings.","zh":"博物馆控制湿度以保护画作。"}]}],"humour":[{"pos":"n.","meaning":"幽默；幽默感","definition":"the quality of being funny or appreciating comedy","examples":[{"en":"His humour eased the tension.","zh":"他的幽默缓解了紧张气氛。"},{"en":"She has a dry sense of humour.","zh":"她有一种冷面幽默感。"}]}],"hurdle":[{"pos":"n.","meaning":"障碍；难关","definition":"A difficulty that must be overcome.","examples":[{"en":"Finding affordable housing was the biggest hurdle.","zh":"找到负担得起的住房是最大的难关。"},{"en":"The team overcame several technical hurdles.","zh":"团队克服了几项技术障碍。"}]},{"pos":"n.","meaning":"跨栏架；跨栏项目","definition":"A barrier jumped over in a race, or the race itself.","examples":[{"en":"She clipped the final hurdle but kept running.","zh":"她碰到了最后一道栏，但仍继续奔跑。"},{"en":"He competes in the four-hundred-metre hurdles.","zh":"他参加四百米跨栏比赛。"}]},{"pos":"v.","meaning":"跨越；越过障碍","definition":"To jump over a barrier or overcome an obstacle.","examples":[{"en":"The athlete hurdled the barrier effortlessly.","zh":"运动员轻松越过栏架。"},{"en":"She hurdled a fallen branch on the path.","zh":"她跨过了小路上的一根断枝。"}]}],"hurl":[{"pos":"v.","meaning":"猛投;猛摔","definition":"to throw with great force","examples":[{"en":"He hurled the ball across the field.","zh":"他把球猛掷过球场。"},{"en":"The storm hurled debris against the windows.","zh":"风暴把碎片猛砸向窗户。"}]},{"pos":"v.","meaning":"大声叫骂;抛出指责","definition":"to shout insults or accusations forcefully","examples":[{"en":"The angry crowd hurled insults at the speaker.","zh":"愤怒的人群大声辱骂发言者。"},{"en":"They hurled accusations across the table.","zh":"他们隔着桌子互相指责。"}]}],"hurricane":[{"pos":"n.","meaning":"飓风","definition":"a powerful tropical storm with very strong winds","examples":[{"en":"The hurricane damaged the coastal road.","zh":"飓风损坏了海岸公路。"},{"en":"Residents prepared their homes before the hurricane arrived.","zh":"居民在飓风到来前为房屋做好准备。"}]}],"hybrid":[{"pos":"n.","meaning":"杂交动植物；杂交种","definition":"An organism produced from parents of different varieties or species.","examples":[{"en":"The gardener planted a disease-resistant tomato hybrid.","zh":"园丁种了一种抗病的番茄杂交品种。"},{"en":"A mule is a hybrid of a horse and a donkey.","zh":"骡子是马和驴的杂交后代。"}]},{"pos":"n.","meaning":"混合物；混合型事物","definition":"Something combining elements of different kinds.","examples":[{"en":"The building is a hybrid of a library and a community centre.","zh":"这栋建筑兼具图书馆和社区中心的功能。"},{"en":"Their music is a hybrid of jazz and folk traditions.","zh":"他们的音乐融合了爵士乐与民间音乐传统。"}]},{"pos":"adj.","meaning":"杂交的；混合的","definition":"Produced by combining different types or varieties.","examples":[{"en":"Hybrid crops may combine useful traits from both parents.","zh":"杂交作物可能结合双亲的有益特征。"},{"en":"The course uses a hybrid format with online and classroom sessions.","zh":"课程采用线上和课堂教学相结合的混合形式。"}]}],"hypnotic":[{"pos":"adj.","meaning":"催眠的;令人恍惚的","definition":"causing hypnosis or sleep-like fascination","examples":[{"en":"The music had a hypnotic rhythm.","zh":"音乐有催眠般的节奏。"},{"en":"The therapist used hypnotic suggestion during the session.","zh":"治疗师在治疗中使用了催眠暗示。"}]},{"pos":"n.","meaning":"催眠药","definition":"a drug used to induce sleep","examples":[{"en":"The study compared two hypnotics.","zh":"研究比较了两种催眠药。"},{"en":"The pharmacist checked the label on the hypnotic.","zh":"药剂师检查了催眠药的标签。"}]}],"hypothesis":[{"pos":"n.","meaning":"假说；假设","definition":"a proposed explanation that can be tested","examples":[{"en":"The experiment tested her hypothesis.","zh":"实验检验了她的假说。"},{"en":"The results support the original hypothesis.","zh":"结果支持最初的假设。"}]}],"hypothetical":[{"pos":"adj.","meaning":"假设的；假定的","definition":"Based on an imagined possibility rather than an established fact.","examples":[{"en":"The students discussed a hypothetical emergency at sea.","zh":"学生们讨论了一个假设的海上紧急情况。"},{"en":"The model assumes a hypothetical city with no private cars.","zh":"这个模型假设存在一座没有私家车的城市。"}]},{"pos":"adj.","meaning":"倾向于作假设的；爱推测的","definition":"Inclined to reason through imagined or assumed possibilities.","examples":[{"en":"His hypothetical approach produced many ideas but few tested conclusions.","zh":"他偏重假设的研究方式产生了许多想法，却少有经过检验的结论。"},{"en":"The discussion became increasingly hypothetical as evidence ran out.","zh":"随着证据用尽，讨论越来越偏向推测。"}]}],"id card":[{"pos":"n.","meaning":"身份证;身份识别卡","definition":"an official card showing a person's identity","examples":[{"en":"Show your ID card at the entrance.","zh":"入口处请出示身份证。"},{"en":"She reported her lost ID card.","zh":"她报告了身份证遗失。"}]}],"ideal":[{"pos":"adj.","meaning":"理想的；最合适的","definition":"perfectly suitable","examples":[{"en":"The flat is ideal for a small family.","zh":"这套公寓很适合小家庭。"},{"en":"Cool weather provided ideal running conditions.","zh":"凉爽天气提供了理想的跑步条件。"}]},{"pos":"adj.","meaning":"理想化的；仅存在于观念中的","definition":"existing as a perfect idea rather than reality","examples":[{"en":"The model assumes an ideal gas.","zh":"模型假设存在理想气体。"},{"en":"The novel imagines an ideal society.","zh":"小说想象了一个理想社会。"}]},{"pos":"adj.","meaning":"观念的；唯心的（哲学用语）","definition":"relating to ideas rather than material objects","examples":[{"en":"The philosopher contrasted ideal reality with material reality.","zh":"哲学家将观念实在与物质实在作了对比。"},{"en":"The essay examines the ideal nature of mathematical objects.","zh":"文章考察数学对象的观念性质。"}]},{"pos":"n.","meaning":"理想；典范；理想的人或事物","definition":"a principle or perfect example one hopes to achieve","examples":[{"en":"She remained faithful to her ideals.","zh":"她始终忠于自己的理想。"},{"en":"The school represents his ideal of education.","zh":"这所学校体现了他的教育理想。"}]}],"identical":[{"pos":"adj.","meaning":"完全相同的；同一的","definition":"Exactly the same in every relevant detail.","examples":[{"en":"The two keys look identical.","zh":"这两把钥匙看起来完全一样。"},{"en":"Every participant received an identical set of instructions.","zh":"每位参与者收到的说明都完全相同。"}]}],"identifiable":[{"pos":"adj.","meaning":"可识别的;可确定的","definition":"able to be recognized or established","examples":[{"en":"The bird is identifiable by its red beak.","zh":"这种鸟可凭红色鸟喙识别。"},{"en":"There was no identifiable cause of the failure.","zh":"故障没有可确定的原因。"}]}],"identification":[{"pos":"n.","meaning":"身份证明；身份证件","definition":"proof of who someone is","examples":[{"en":"Visitors must show identification.","zh":"访客必须出示身份证明。"},{"en":"The clerk asked for a second form of identification.","zh":"办事员要求第二种身份证明。"}]},{"pos":"n.","meaning":"识别；鉴定","definition":"the act of recognising or naming something","examples":[{"en":"The guide helps with bird identification.","zh":"这本指南有助于识别鸟类。"},{"en":"Accurate identification of the fault saved time.","zh":"准确鉴定故障节省了时间。"}]}],"identify":[{"pos":"v.","meaning":"识别；认出；确定；查明","definition":"To recognise someone or establish what something is.","examples":[{"en":"The witness identified the missing bicycle.","zh":"目击者认出了丢失的自行车。"},{"en":"The study identified three main causes of delay.","zh":"研究查明了延误的三个主要原因。"}]},{"pos":"v.","meaning":"把……视为同一；使密切联系","definition":"To regard someone or something as closely connected or the same.","examples":[{"en":"Some readers identify the narrator with the author.","zh":"有些读者把叙述者等同于作者。"},{"en":"The brand is closely identified with outdoor adventure.","zh":"这个品牌与户外探险紧密联系在一起。"}]}],"identity":[{"pos":"n.","meaning":"身份认同；认同；个性；特性","definition":"who someone is or how they understand themselves","examples":[{"en":"Language is closely linked to cultural identity.","zh":"语言与文化认同紧密相连。"},{"en":"Moving abroad can change a person's sense of identity.","zh":"移居国外可能改变一个人的身份认同感。"},{"en":"The town wants to preserve its distinct identity.","zh":"这个城镇希望保留独特的地方特色。"}]},{"pos":"n.","meaning":"身份;确切是谁","definition":"who a particular person is","examples":[{"en":"The police checked his identity.","zh":"警方核查了他的身份。"},{"en":"She concealed her identity during the interview.","zh":"她在采访中隐瞒了身份。"}]},{"pos":"n.","meaning":"同一性;完全相同","definition":"the state of being the same","examples":[{"en":"The analysis established the identity of the two substances.","zh":"分析确定两种物质是同一种。"},{"en":"An identity of interests united the partners.","zh":"共同利益使合伙人团结起来。"}]}],"ignorance":[{"pos":"n.","meaning":"无知；不了解","definition":"a lack of knowledge or information","examples":[{"en":"The mistake arose from ignorance of the rules.","zh":"错误源于不了解规则。"},{"en":"She admitted her ignorance of local history.","zh":"她承认自己不了解地方历史。"}]}],"ignorant":[{"pos":"adj.","meaning":"无知的；不了解的","definition":"Lacking knowledge or awareness.","examples":[{"en":"I was ignorant of the local customs when I arrived.","zh":"我刚到时不了解当地风俗。"},{"en":"His comments revealed how ignorant he was about farming.","zh":"他的评论暴露出他对农业有多么无知。"}]}],"ignore":[{"pos":"v.","meaning":"忽视;不理会","definition":"to pay no attention to something","examples":[{"en":"Do not ignore the warning light.","zh":"不要忽视警示灯。"},{"en":"She ignored his rude remark.","zh":"她没有理会他粗鲁的话。"}]}],"illegal":[{"pos":"adj.","meaning":"违法的；不合法的","definition":"not allowed by law","examples":[{"en":"The waste was dumped at an illegal site.","zh":"废物被倾倒在非法地点。"},{"en":"The investigation uncovered illegal trading.","zh":"调查发现了非法交易。"}]}],"illuminate":[{"pos":"v.","meaning":"照亮","definition":"To provide light for something.","examples":[{"en":"Lanterns illuminated the narrow street.","zh":"灯笼照亮了狭窄的街道。"},{"en":"The display is illuminated from behind.","zh":"展品由后方的灯光照亮。"}]},{"pos":"v.","meaning":"阐明；解释；启发","definition":"To make something easier to understand.","examples":[{"en":"The diary illuminates everyday life during the period.","zh":"这本日记帮助人们了解那个时期的日常生活。"},{"en":"A simple diagram can illuminate a complicated process.","zh":"一张简单的图可以阐明复杂过程。"}]}],"illusion":[{"pos":"n.","meaning":"错觉;假象","definition":"a misleading appearance or perception","examples":[{"en":"The mirrors create an illusion of space.","zh":"镜子制造出空间宽大的错觉。"},{"en":"The magician produced the illusion of floating.","zh":"魔术师制造了漂浮的假象。"}]},{"pos":"n.","meaning":"幻想;错误观念","definition":"a mistaken belief","examples":[{"en":"He abandoned the illusion that success was easy.","zh":"他放弃了成功很容易的幻想。"},{"en":"We are under no illusion about the difficulty.","zh":"我们对困难程度没有不切实际的想法。"}]}],"illustrate":[{"pos":"v.","meaning":"说明；举例阐明","definition":"to make something clear with examples or images","examples":[{"en":"The chart illustrates the change in demand.","zh":"图表说明了需求变化。"},{"en":"She used a story to illustrate her point.","zh":"她用故事阐明自己的观点。"}]},{"pos":"v.","meaning":"给……画插图","definition":"to provide pictures for a text","examples":[{"en":"He illustrated the children's book.","zh":"他为这本儿童读物画了插图。"},{"en":"The guide is illustrated with watercolours.","zh":"这本指南配有水彩插图。"}]}],"illustration":[{"pos":"n.","meaning":"插图；图解","definition":"A picture used to explain or decorate a text.","examples":[{"en":"Each chapter begins with a full-page illustration.","zh":"每章都以一幅整页插图开头。"},{"en":"The illustration shows how the parts fit together.","zh":"图解展示了这些部件如何装配在一起。"}]},{"pos":"n.","meaning":"说明；例证；实例","definition":"An example that makes a point clear.","examples":[{"en":"The incident provides a clear illustration of the problem.","zh":"这一事件清楚地说明了该问题。"},{"en":"For illustration, consider a household with two children.","zh":"举例来说，考虑一个有两个孩子的家庭。"}]}],"image":[{"pos":"n.","meaning":"图像;映像","definition":"a visual representation","examples":[{"en":"The screen displayed a sharp image.","zh":"屏幕显示出清晰图像。"},{"en":"Her image was reflected in the lake.","zh":"她的映像倒映在湖中。"}]},{"pos":"n.","meaning":"形象;印象","definition":"the way someone or something is perceived","examples":[{"en":"The campaign improved the company's image.","zh":"宣传活动改善了公司形象。"},{"en":"That image of him as shy is misleading.","zh":"认为他害羞的印象并不准确。"}]}],"imagination":[{"pos":"n.","meaning":"想象力；想象","definition":"the ability to form ideas or images of absent things","examples":[{"en":"The story captured the children's imagination.","zh":"故事激发了孩子们的想象力。"},{"en":"Designing small spaces requires imagination.","zh":"设计小空间需要想象力。"}]},{"pos":"n.","meaning":"想象出来的事物；臆想","definition":"something existing only in the mind","examples":[{"en":"The footsteps were only her imagination.","zh":"脚步声只是她的臆想。"},{"en":"The supposed danger was a product of his imagination.","zh":"所谓的危险是他想象出来的。"}]}],"imaginative":[{"pos":"adj.","meaning":"富有想象力的；有创意的","definition":"Able to produce original and interesting ideas.","examples":[{"en":"The children proposed imaginative uses for recycled materials.","zh":"孩子们提出了回收材料的各种创意用途。"},{"en":"The restaurant serves imaginative dishes made from local ingredients.","zh":"餐厅用当地食材制作富有创意的菜肴。"}]}],"imagine":[{"pos":"v.","meaning":"想象","definition":"to form a mental picture","examples":[{"en":"Imagine a city without traffic noise.","zh":"想象一座没有交通噪声的城市。"},{"en":"She imagined herself living by the sea.","zh":"她想象自己住在海边。"}]},{"pos":"v.","meaning":"猜想;认为","definition":"to suppose that something is true","examples":[{"en":"I imagine the shop is closed now.","zh":"我猜商店现在关门了。"},{"en":"He imagined that everyone agreed with him.","zh":"他以为所有人都赞同他。"}]}],"imitate":[{"pos":"v.","meaning":"模仿；仿效","definition":"to copy behaviour, appearance, or a method","examples":[{"en":"Children often imitate adults.","zh":"孩子们经常模仿成年人。"},{"en":"The material imitates the appearance of stone.","zh":"这种材料模仿了石材的外观。"}]}],"imitation":[{"pos":"n.","meaning":"模仿；仿效","definition":"The act of copying someone or something.","examples":[{"en":"Young children learn many skills through imitation.","zh":"幼儿通过模仿学习许多技能。"},{"en":"His imitation of the headteacher made everyone laugh.","zh":"他对校长的模仿让大家大笑。"}]},{"pos":"n.","meaning":"仿制品；赝品；假货","definition":"A copy intended to resemble something else.","examples":[{"en":"The necklace is an imitation rather than a genuine antique.","zh":"这条项链是仿制品，而不是真正的古董。"},{"en":"Cheap imitations of the designer bag appeared online.","zh":"网上出现了这款设计师手袋的廉价仿品。"}]}],"immediately":[{"pos":"adv.","meaning":"立即;马上","definition":"without delay","examples":[{"en":"The alarm sounded, and everyone left immediately.","zh":"警报响起，大家立即离开。"},{"en":"Please call me immediately after the meeting.","zh":"请在会议后马上给我打电话。"}]},{"pos":"adv.","meaning":"紧接地;紧邻地;直接地","definition":"with nothing between in time or place","examples":[{"en":"The pharmacy is immediately opposite the station.","zh":"药房就在车站正对面。"},{"en":"Read the paragraph immediately before the diagram.","zh":"阅读图表前紧接着的段落。"}]}],"immense":[{"pos":"adj.","meaning":"巨大的；极大的","definition":"extremely large in size or degree","examples":[{"en":"The project required immense patience.","zh":"项目需要极大的耐心。"},{"en":"An immense glacier filled the valley.","zh":"巨大的冰川充满了山谷。"}]}],"immigrant":[{"pos":"n.","meaning":"移民；外来定居者","definition":"A person who moves to another country to live there.","examples":[{"en":"The centre offers language classes for recent immigrants.","zh":"该中心为新移民开设语言课程。"},{"en":"Her parents were immigrants who settled near the port.","zh":"她的父母是定居在港口附近的移民。"}]}],"immigration":[{"pos":"n.","meaning":"移居入境;外来移民","definition":"the movement of people into a country to live","examples":[{"en":"Immigration changed the city's cultural life.","zh":"移民改变了城市的文化生活。"},{"en":"The report examines patterns of immigration.","zh":"报告研究了移民入境的模式。"}]}],"immune":[{"pos":"adj.","meaning":"免疫的；具有免疫力的","definition":"protected against a particular disease","examples":[{"en":"The test examined whether the animals were immune to the virus.","zh":"测试检查了动物是否对该病毒有免疫力。"},{"en":"The study investigated how cells become immune to infection.","zh":"研究调查了细胞如何获得抵抗感染的能力。"}]},{"pos":"adj.","meaning":"不受影响的；有抵抗力的","definition":"unaffected by something harmful or unpleasant","examples":[{"en":"No business is immune to economic change.","zh":"没有企业能不受经济变化影响。"},{"en":"She seemed immune to his criticism.","zh":"她似乎不受他的批评影响。"}]},{"pos":"adj.","meaning":"豁免的；免受追究的","definition":"legally exempt from a duty or penalty","examples":[{"en":"Certain officials are immune from prosecution in specified circumstances.","zh":"某些官员在特定情况下享有免于起诉的豁免权。"},{"en":"The agreement made those goods immune from the new charge.","zh":"协议使那些商品免于新收费。"}]}],"impact":[{"pos":"n.","meaning":"影响","definition":"a strong effect on something","examples":[{"en":"The closure had a major impact on local employment.","zh":"关闭对当地就业造成了重大影响。"},{"en":"We need to assess the environmental impact of the project.","zh":"我们需要评估项目的环境影响。"},{"en":"Small changes can have a positive impact on wellbeing.","zh":"小改变可以对身心健康产生积极影响。"}],"ipa":"/ˈɪmpækt/"},{"pos":"v.","meaning":"影响","definition":"to affect something","ipa":"/ɪmˈpækt/","examples":[{"en":"The new rules may impact small businesses.","zh":"新规则可能影响小企业。"},{"en":"Long commutes can impact family life.","zh":"长时间通勤可能影响家庭生活。"},{"en":"The change will impact how we manage the budget.","zh":"这一变化将影响我们管理预算的方式。"}]},{"pos":"n.","meaning":"碰撞；冲击","definition":"The force produced when objects hit one another.","examples":[{"en":"The helmet absorbed much of the impact.","zh":"头盔吸收了大部分冲击力。"},{"en":"The door burst open on impact.","zh":"门受到撞击后猛地打开了。"}],"ipa":"/ˈɪmpækt/"}],"impair":[{"pos":"v.","meaning":"损害;削弱","definition":"to reduce quality or ability","examples":[{"en":"Poor lighting can impair concentration.","zh":"照明不足会削弱注意力。"},{"en":"The injury impaired his hearing.","zh":"这次受伤损害了他的听力。"}]}],"impart":[{"pos":"v.","meaning":"赋予；给予","definition":"to give a quality to something","examples":[{"en":"The wood imparts a smoky flavour.","zh":"木材赋予了烟熏风味。"},{"en":"The lighting imparted warmth to the room.","zh":"灯光给房间增添了温暖感。"}]},{"pos":"v.","meaning":"传授；告知；透露","definition":"to communicate knowledge or information","examples":[{"en":"The instructor imparted practical skills.","zh":"教练传授了实用技能。"},{"en":"She quietly imparted the news to her colleague.","zh":"她悄悄把消息告诉同事。"}]}],"impede":[{"pos":"v.","meaning":"阻碍；妨碍","definition":"To slow down or prevent progress.","examples":[{"en":"Fallen trees impeded the rescue operation.","zh":"倒下的树木阻碍了救援行动。"},{"en":"Poor communication can impede teamwork.","zh":"沟通不畅可能妨碍团队合作。"}]}],"imperil":[{"pos":"v.","meaning":"危及;使陷入危险","definition":"to put at serious risk","examples":[{"en":"The delay could imperil the entire rescue.","zh":"延误可能危及整个救援行动。"},{"en":"Pollution imperils fragile coastal habitats.","zh":"污染危及脆弱的沿海栖息地。"}]}],"impetus":[{"pos":"n.","meaning":"动力；推动力；促进","definition":"a force or influence that encourages progress","examples":[{"en":"The grant gave fresh impetus to the research.","zh":"资助给研究注入了新动力。"},{"en":"Public support provided the impetus for reform.","zh":"公众支持为改革提供了推动力。"}]}],"implement":[{"pos":"v.","meaning":"实施；执行","definition":"to put a plan into action","examples":[{"en":"The company will implement the new policy next month.","zh":"公司将于下个月实施新政策。"},{"en":"Schools need funding to implement these changes.","zh":"学校需要资金来实施这些改变。"},{"en":"It takes time to implement an effective recycling scheme.","zh":"实施有效的回收方案需要时间。"}],"ipa":"/ˈɪmplɪment/"},{"pos":"n.","meaning":"工具；器具","definition":"A tool used for a practical purpose.","examples":[{"en":"The museum displays old farming implements.","zh":"博物馆展出古代农具。"},{"en":"Use a blunt implement to lift the lid.","zh":"用钝头工具撬起盖子。"}],"ipa":"/ˈɪmplɪmənt/"}],"implication":[{"pos":"n.","meaning":"含意;暗示","definition":"an indirect meaning or suggestion","examples":[{"en":"I disliked the implication that I was dishonest.","zh":"我不喜欢那种暗示我不诚实的说法。"},{"en":"Her silence carried an obvious implication.","zh":"她的沉默有明显的言外之意。"}]},{"pos":"n.","meaning":"可能的后果;影响","definition":"a likely effect of a decision or action","examples":[{"en":"We considered the financial implications.","zh":"我们考虑了财务方面的影响。"},{"en":"The discovery has implications for future research.","zh":"这项发现对未来研究有影响。"}]},{"pos":"n.","meaning":"牵连;卷入","definition":"involvement in a crime or wrongdoing","examples":[{"en":"His implication in the scandal ended his career.","zh":"他卷入丑闻后事业终结。"},{"en":"The evidence suggested her implication in the fraud.","zh":"证据表明她可能牵涉这起诈骗。"}]}],"impose":[{"pos":"v.","meaning":"强加；强迫接受","definition":"to force a rule or belief on others","examples":[{"en":"The manager imposed a strict deadline.","zh":"经理强行规定了严格的期限。"},{"en":"They resisted attempts to impose a single teaching method.","zh":"他们抵制强加单一教学方法的尝试。"}]},{"pos":"v.","meaning":"征收；处以","definition":"to officially introduce a tax or punishment","examples":[{"en":"The council imposed a parking charge.","zh":"议会征收了停车费。"},{"en":"The court imposed a fine.","zh":"法院处以罚款。"}]}],"impossible":[{"pos":"adj.","meaning":"不可能的；办不到的","definition":"Unable to happen or be done.","examples":[{"en":"It is impossible to finish this work in ten minutes.","zh":"不可能在十分钟内完成这项工作。"},{"en":"The heavy snow made travel impossible.","zh":"大雪使出行成为不可能。"}]}],"impoverish":[{"pos":"v.","meaning":"使贫困","definition":"to make someone poor","examples":[{"en":"Years of war impoverished the population.","zh":"多年战争使人民陷入贫困。"},{"en":"Medical bills impoverished the family.","zh":"医疗账单使这家人变穷。"}]},{"pos":"v.","meaning":"使贫瘠;使枯竭;使贫乏","definition":"to reduce richness or quality","examples":[{"en":"Repeated cropping impoverished the soil.","zh":"反复耕种使土壤贫瘠。"},{"en":"Cutting arts funding impoverishes cultural life.","zh":"削减艺术经费使文化生活贫乏。"}]}],"impoverished":[{"pos":"adj.","meaning":"贫困的；赤贫的","definition":"having very little money","examples":[{"en":"The charity works in impoverished villages.","zh":"慈善机构在贫困村庄开展工作。"},{"en":"The war left many families impoverished.","zh":"战争使许多家庭陷入贫困。"}]},{"pos":"adj.","meaning":"贫乏的；贫瘠的；枯竭的","definition":"lacking necessary richness or resources","examples":[{"en":"Overuse left the soil impoverished.","zh":"过度利用使土壤变得贫瘠。"},{"en":"The simplified version offers an impoverished account of history.","zh":"简化版本对历史的叙述十分贫乏。"}]}],"imprecise":[{"pos":"adj.","meaning":"不精确的；不严密的","definition":"Not exact or clearly defined.","examples":[{"en":"The directions were too imprecise to follow.","zh":"指引太不明确，无法照着走。"},{"en":"Early instruments gave relatively imprecise measurements.","zh":"早期仪器给出的测量结果比较不精确。"}]}],"impress":[{"pos":"v.","meaning":"使印象深刻;使铭记","definition":"to affect strongly or stress the importance of something","examples":[{"en":"Her calm confidence impressed the interviewers.","zh":"她沉着自信，给面试官留下了深刻印象。"},{"en":"He impressed the need for accuracy on the team.","zh":"他向团队强调准确性的重要性。"}]},{"pos":"v.","meaning":"压印;盖印","definition":"to press a mark onto a surface","examples":[{"en":"She impressed a seal into the soft wax.","zh":"她在软蜡上压下印章。"},{"en":"The pattern was impressed on wet clay.","zh":"图案被压印在湿黏土上。"}]},{"pos":"n.","meaning":"印记;印痕","definition":"a mark or lasting influence","examples":[{"en":"The clay retained the impress of a leaf.","zh":"黏土保留了叶片印痕。"},{"en":"The city still bears the impress of its industrial past.","zh":"这座城市仍带有工业往昔的印记。"}]}],"impression":[{"pos":"n.","meaning":"印象；感想","definition":"an idea or feeling formed about something","examples":[{"en":"The city made a strong impression on her.","zh":"这座城市给她留下了深刻印象。"},{"en":"My first impression was favourable.","zh":"我的第一印象很好。"}]},{"pos":"n.","meaning":"印痕；压痕","definition":"a mark made by pressing something into a surface","examples":[{"en":"The boot left an impression in the mud.","zh":"靴子在泥中留下了印痕。"},{"en":"The dentist took an impression of her teeth.","zh":"牙医取了她的牙模。"}]}],"impressive":[{"pos":"adj.","meaning":"令人赞叹的；给人深刻印象的","definition":"Causing admiration because of quality, size, or skill.","examples":[{"en":"The team made impressive progress in just a month.","zh":"团队在仅仅一个月内取得了令人赞叹的进展。"},{"en":"The museum holds an impressive collection of ceramics.","zh":"博物馆收藏了数量可观的陶瓷作品。"}]}],"improve":[{"pos":"v.","meaning":"改善;改进;提高","definition":"to become or make better","examples":[{"en":"Practice will improve your pronunciation.","zh":"练习会改善你的发音。"},{"en":"The weather improved during the afternoon.","zh":"下午天气好转了。"}]}],"improvement":[{"pos":"n.","meaning":"改进；进步","definition":"the process or result of becoming better","examples":[{"en":"Her pronunciation shows steady improvement.","zh":"她的发音稳步进步。"},{"en":"The change brought an improvement in efficiency.","zh":"改变提高了效率。"}]},{"pos":"n.","meaning":"改进措施；改善之处","definition":"a change that makes something better","examples":[{"en":"The landlord made several improvements to the flat.","zh":"房东对公寓进行了几项改进。"},{"en":"Better lighting is a welcome improvement.","zh":"更好的照明是一项受欢迎的改善。"}]}],"impulse":[{"pos":"n.","meaning":"冲动；一时的念头","definition":"A sudden strong wish to do something.","examples":[{"en":"She bought the ticket on impulse.","zh":"她一时冲动买下了票。"},{"en":"He resisted the impulse to interrupt.","zh":"他克制住了打断别人的冲动。"}]},{"pos":"n.","meaning":"推动力；刺激；驱动力","definition":"A force or influence that causes action or change.","examples":[{"en":"The discovery gave a new impulse to research in the field.","zh":"这一发现为该领域的研究注入了新的动力。"},{"en":"The desire for independence was the main impulse behind the movement.","zh":"对独立的渴望是这场运动背后的主要驱动力。"}]},{"pos":"n.","meaning":"脉冲；冲量","definition":"A brief electrical signal or a short application of force.","examples":[{"en":"Nerve cells transmit electrical impulses.","zh":"神经细胞传递电脉冲。"},{"en":"The sensor records the impulse produced when the ball strikes the plate.","zh":"传感器记录球撞击板面时产生的冲量。"}]}],"in accordance with":[{"pos":"prep. phr.","meaning":"按照;依据","definition":"following a rule or agreement","examples":[{"en":"The work proceeded in accordance with the plan.","zh":"工作按计划推进。"},{"en":"Payments are made in accordance with the contract.","zh":"款项按合同支付。"}]}],"in addition":[{"pos":"phrase","meaning":"另外；此外","definition":"used to add another point","examples":[{"en":"The room is spacious; in addition, it has a balcony.","zh":"房间宽敞，另外还有阳台。"},{"en":"In addition to teaching, she writes textbooks.","zh":"除了教学，她还编写教材。"}]}],"in addition to":[{"pos":"prep.","meaning":"除……之外还；此外","definition":"As well as something already mentioned.","examples":[{"en":"In addition to English, she speaks Arabic.","zh":"除了英语，她还会说阿拉伯语。"},{"en":"The fee covers meals in addition to accommodation.","zh":"费用除了住宿，还包括餐饮。"}]}],"in comparison with":[{"pos":"prep. phr.","meaning":"与……相比","definition":"when compared with something else","examples":[{"en":"The flat is small in comparison with our old house.","zh":"与旧房子相比，这套公寓很小。"},{"en":"Costs fell in comparison with last year.","zh":"与去年相比，成本下降了。"}]}],"in favour of":[{"pos":"phrase","meaning":"赞成；支持","definition":"supporting or preferring something","examples":[{"en":"Most members voted in favour of the proposal.","zh":"多数成员投票支持提案。"},{"en":"She spoke in favour of keeping the library open.","zh":"她发言支持保持图书馆开放。"}]}],"in vain":[{"pos":"adv.","meaning":"徒劳地；无效地；白费力气地","definition":"Without achieving the intended result.","examples":[{"en":"We searched in vain for the missing receipt.","zh":"我们寻找丢失的收据，却毫无结果。"},{"en":"She tried in vain to restart the engine.","zh":"她徒劳地尝试重新启动发动机。"}]}],"inactive":[{"pos":"adj.","meaning":"不活动的;闲置的;不活跃的","definition":"not active or being used","examples":[{"en":"The account has been inactive for years.","zh":"这个账户多年未使用。"},{"en":"The animals remain inactive during the hottest hours.","zh":"动物在最热的时段不活动。"}]}],"inadequate":[{"pos":"adj.","meaning":"不足的；不够好的","definition":"not enough or not suitable for the purpose","examples":[{"en":"The explanation was inadequate.","zh":"这个解释不充分。"},{"en":"Inadequate drainage caused repeated flooding.","zh":"排水设施不足导致反复积水。"}]}],"inalienable":[{"pos":"adj.","meaning":"不可剥夺的；不可转让的","definition":"Unable to be taken away or given up.","examples":[{"en":"The declaration recognises education as an inalienable right.","zh":"宣言承认教育是一项不可剥夺的权利。"},{"en":"They argued that human dignity is inalienable.","zh":"他们主张人的尊严不可剥夺。"}]}],"inaugurate":[{"pos":"v.","meaning":"开创;启动","definition":"to begin something important","examples":[{"en":"The agreement inaugurated a new era of cooperation.","zh":"协议开创了合作的新时代。"},{"en":"The museum inaugurated a programme for young artists.","zh":"博物馆启动了一项青年艺术家计划。"}]},{"pos":"v.","meaning":"举行就职典礼","definition":"to formally install someone in office","examples":[{"en":"The new president was inaugurated in January.","zh":"新总统在一月举行了就职典礼。"},{"en":"Thousands gathered to see the governor inaugurated.","zh":"数千人聚集观看州长就职。"}]},{"pos":"v.","meaning":"为……举行开幕或落成仪式","definition":"to formally open a place or institution","examples":[{"en":"The mayor inaugurated the new library.","zh":"市长为新图书馆主持了落成仪式。"},{"en":"A concert inaugurated the restored theatre.","zh":"一场音乐会为修复后的剧院揭幕。"}]}],"inborn":[{"pos":"adj.","meaning":"天生的；与生俱来的","definition":"existing from birth","examples":[{"en":"The story contrasts training with inborn ability.","zh":"故事对比了训练和天生能力。"},{"en":"She seemed to have an inborn sense of rhythm.","zh":"她似乎具有天生的节奏感。"}]}],"incapacitate":[{"pos":"v.","meaning":"使失去能力；使不能工作；使伤残","definition":"To make someone unable to act or work normally.","examples":[{"en":"The injury incapacitated him for several weeks.","zh":"伤势使他数周无法正常活动。"},{"en":"A severe power failure incapacitated the entire network.","zh":"严重停电使整个网络瘫痪。"}]},{"pos":"v.","meaning":"使无资格；使不具备法定能力","definition":"To make someone legally unable or unqualified to act.","examples":[{"en":"The ruling incapacitated the official from holding public office.","zh":"这项裁决使该官员失去了担任公职的资格。"},{"en":"The statute specified circumstances that could incapacitate a person from serving as a trustee.","zh":"该法规列明了可能使一个人失去受托人资格的情形。"}]}],"incendiary":[{"pos":"adj.","meaning":"纵火的;能引起燃烧的","definition":"designed or able to start fires","examples":[{"en":"The investigators found an incendiary device.","zh":"调查人员发现了燃烧装置。"},{"en":"Incendiary bombs damaged the warehouses.","zh":"燃烧弹损坏了仓库。"}]},{"pos":"adj.","meaning":"煽动性的","definition":"likely to provoke anger or violence","examples":[{"en":"His incendiary speech inflamed the crowd.","zh":"他煽动性的演说激怒了人群。"},{"en":"The editor removed the most incendiary remarks.","zh":"编辑删去了最具煽动性的言论。"}]}],"incentive":[{"pos":"n.","meaning":"激励；刺激因素","definition":"something that encourages action","examples":[{"en":"A tax reduction provides an incentive to invest.","zh":"减税能激励投资。"},{"en":"The bonus gives employees an incentive to improve performance.","zh":"奖金激励员工提高工作表现。"},{"en":"Lower fares could be an incentive to use public transport.","zh":"更低票价可以成为使用公共交通的动力。"}]}],"incident":[{"pos":"n.","meaning":"事件；事故；事变","definition":"An occurrence, especially an unusual or unpleasant one.","examples":[{"en":"Police interviewed witnesses to the incident.","zh":"警方询问了这一事件的目击者。"},{"en":"A minor incident at the border increased tensions.","zh":"边境上的一件小事加剧了紧张局势。"}]}],"incinerate":[{"pos":"v.","meaning":"焚化;焚毁","definition":"to burn completely to ashes","examples":[{"en":"The facility incinerates contaminated waste.","zh":"设施焚化受污染废物。"},{"en":"The documents were incinerated in a secure furnace.","zh":"文件在安全焚烧炉内被焚毁。"}]}],"inclination":[{"pos":"n.","meaning":"意愿；爱好；倾向","definition":"a desire or tendency to do something","examples":[{"en":"He had little inclination to argue.","zh":"他没什么争论的意愿。"},{"en":"Her inclination towards practical work shaped her career.","zh":"她偏爱实际工作的倾向影响了职业选择。"}]},{"pos":"n.","meaning":"倾斜；倾角","definition":"the angle or state of sloping","examples":[{"en":"Measure the inclination of the roof.","zh":"测量屋顶的倾角。"},{"en":"A slight inclination helped water drain away.","zh":"轻微的倾斜帮助水排走。"}]}],"include":[{"pos":"v.","meaning":"包括；包含；计入","definition":"To contain something as part of a whole.","examples":[{"en":"The price includes breakfast and airport transport.","zh":"价格包含早餐和机场接送。"},{"en":"Remember to include your address on the form.","zh":"记得在表格上填写你的地址。"}]}],"inclusion":[{"pos":"n.","meaning":"包容；参与机会","definition":"giving people opportunities to take part","examples":[{"en":"Accessible buildings promote social inclusion.","zh":"无障碍建筑促进社会包容。"},{"en":"The school values the inclusion of pupils with disabilities.","zh":"学校重视让残障学生平等参与。"},{"en":"Digital inclusion requires both equipment and training.","zh":"数字包容既需要设备，也需要培训。"}]}],"inclusive":[{"pos":"adj.","meaning":"包含全部费用的","definition":"including all charges","examples":[{"en":"The hotel quoted an inclusive price.","zh":"酒店报了包含全部费用的价格。"},{"en":"The package is inclusive of meals.","zh":"套餐包含餐食。"}]},{"pos":"adj.","meaning":"包括首尾在内的","definition":"including the stated first and last items","examples":[{"en":"Read pages ten to twenty inclusive.","zh":"阅读第十至第二十页，包括这两页。"},{"en":"The office closes from Monday to Friday inclusive.","zh":"办公室从星期一至星期五关闭，首尾两天包括在内。"}]},{"pos":"adj.","meaning":"包容的；不排斥的","definition":"welcoming different people and groups","examples":[{"en":"The school aims to create an inclusive community.","zh":"学校旨在建立包容的群体。"},{"en":"The design makes the playground more inclusive.","zh":"设计使游乐场能容纳更多不同需求的使用者。"}]}],"income":[{"pos":"n.","meaning":"收入","definition":"money that someone earns or receives","examples":[{"en":"Housing costs take up half of her income.","zh":"住房费用占她收入的一半。"},{"en":"Families on a low income may receive support.","zh":"低收入家庭可能获得援助。"},{"en":"Tourism provides a major source of income for the island.","zh":"旅游业是该岛的主要收入来源。"}]}],"incoming":[{"pos":"adj.","meaning":"到来的;进入的;新任的","definition":"arriving or taking over a position","examples":[{"en":"The assistant screened incoming calls.","zh":"助理筛选了来电。"},{"en":"The incoming director met the staff.","zh":"新任主管会见了员工。"}]},{"pos":"n.","meaning":"收入（常用复数 incomings）","definition":"money received","examples":[{"en":"Their incomings barely covered household expenses.","zh":"他们的收入勉强够支付家庭开支。"},{"en":"The ledger records incomings and outgoings.","zh":"账簿记录收入与支出。"}]}],"incompatible":[{"pos":"adj.","meaning":"不兼容的；不能共存的；合不来的","definition":"unable to work or exist together successfully","examples":[{"en":"The software is incompatible with my computer.","zh":"软件与我的电脑不兼容。"},{"en":"Their conflicting goals proved incompatible.","zh":"他们相互冲突的目标无法兼容。"}]}],"incongruity":[{"pos":"n.","meaning":"不协调；不相称；不一致之处","definition":"A mismatch between things that would normally fit together.","examples":[{"en":"The incongruity of the modern tower beside the cottage was striking.","zh":"现代高楼与旁边的小屋显得格格不入。"},{"en":"Readers noticed several incongruities in the witness's account.","zh":"读者注意到证人叙述中有几处不一致。"}]}],"incongruous":[{"pos":"adj.","meaning":"不协调的;不相称的;不适宜的","definition":"out of place or inconsistent with surroundings","examples":[{"en":"His muddy boots looked incongruous in the ballroom.","zh":"他的泥靴在舞厅里显得格格不入。"},{"en":"The cheerful music was incongruous with the solemn occasion.","zh":"欢快的音乐与庄严场合不协调。"}]}],"incorporate":[{"pos":"v.","meaning":"合并；纳入；包含","definition":"to include something as part of a larger whole","examples":[{"en":"The design incorporates recycled materials.","zh":"设计采用了再生材料。"},{"en":"We incorporated their suggestions into the final plan.","zh":"我们把他们的建议纳入了最终计划。"}]}],"incredible":[{"pos":"adj.","meaning":"难以置信的；不可思议的","definition":"So unusual or extreme that it is hard to believe.","examples":[{"en":"It is incredible that the tiny boat survived the storm.","zh":"这么小的船竟然在风暴中幸存，真令人难以置信。"},{"en":"The athlete showed incredible endurance.","zh":"这位运动员展现了惊人的耐力。"}]},{"pos":"adj.","meaning":"不可信的","definition":"Unable to be accepted as true or reliable.","examples":[{"en":"The witness offered an incredible explanation for his absence.","zh":"证人为自己不在场提出了一个不可信的解释。"},{"en":"The story became increasingly incredible as new details emerged.","zh":"随着新细节出现，这个故事越来越不可信。"}]}],"inculcate":[{"pos":"v.","meaning":"反复灌输;谆谆教诲","definition":"to establish an idea through repeated teaching","examples":[{"en":"The school inculcates respect for others.","zh":"学校反复教导学生尊重他人。"},{"en":"Daily practice inculcated good habits in the trainees.","zh":"每日练习使学员养成了良好习惯。"}]}],"incur":[{"pos":"v.","meaning":"招致；遭受；产生费用","definition":"to become subject to a cost or harmful result","examples":[{"en":"Late payment may incur an extra charge.","zh":"逾期付款可能产生额外费用。"},{"en":"The project incurred unexpected losses.","zh":"项目遭受了意外损失。"}]}],"independence":[{"pos":"n.","meaning":"独立；自主；自立","definition":"Freedom from outside control or reliance on others.","examples":[{"en":"The country gained independence after years of negotiation.","zh":"经过多年的谈判，这个国家获得了独立。"},{"en":"Learning to cook gave him greater independence.","zh":"学会做饭使他更加自立。"}]}],"independent":[{"pos":"adj.","meaning":"独立的","definition":"able to act without relying on others","examples":[{"en":"The course encourages independent learning.","zh":"这门课程鼓励自主学习。"},{"en":"Living away from home made her more independent.","zh":"离家生活使她更加独立。"},{"en":"An independent expert reviewed the report.","zh":"一位独立专家审查了报告。"}]},{"pos":"n.","meaning":"无党派人士;独立候选人","definition":"a politician not belonging to a political party","examples":[{"en":"She stood for election as an independent.","zh":"她以独立候选人身份参选。"},{"en":"Two independents joined the committee.","zh":"两位无党派人士加入委员会。"}]}],"indicate":[{"pos":"v.","meaning":"表明；显示；标示","definition":"to show that something exists or is true","examples":[{"en":"The arrow indicates the entrance.","zh":"箭头标示入口。"},{"en":"The results indicate a clear improvement.","zh":"结果显示了明显的改善。"}]},{"pos":"v.","meaning":"示意；暗示","definition":"to communicate indirectly or with a gesture","examples":[{"en":"She indicated that the meeting was over.","zh":"她示意会议结束。"},{"en":"He indicated a chair beside the window.","zh":"他指了指窗边的椅子。"}]}],"indication":[{"pos":"n.","meaning":"迹象；指示；表明","definition":"A sign or piece of information that suggests something.","examples":[{"en":"Dark clouds are an indication that rain may be approaching.","zh":"乌云是可能要下雨的迹象。"},{"en":"She gave no indication of when she would return.","zh":"她没有透露何时回来。"}]}],"indifferent":[{"pos":"adj.","meaning":"冷漠的;不关心的","definition":"showing little interest or concern","examples":[{"en":"He seemed indifferent to the criticism.","zh":"他似乎不在意批评。"},{"en":"Voters were indifferent about the proposed change.","zh":"选民对提议中的变动漠不关心。"}]}],"indigenous":[{"pos":"adj.","meaning":"本土的；原生的","definition":"originating naturally in a particular place","examples":[{"en":"The garden contains indigenous plants.","zh":"花园里种有本土植物。"},{"en":"The museum presents indigenous cultural traditions.","zh":"博物馆展示原住民的文化传统。"}]}],"indispensable":[{"pos":"adj.","meaning":"不可或缺的；必需的","definition":"So important that one cannot manage without it.","examples":[{"en":"A reliable map is indispensable on this route.","zh":"走这条路线，一张可靠的地图必不可少。"},{"en":"Her knowledge of local customs proved indispensable.","zh":"她对当地风俗的了解被证明不可或缺。"}]}],"individual":[{"pos":"adj.","meaning":"个别的;单独的","definition":"considered separately from a group","examples":[{"en":"Each student received individual feedback.","zh":"每位学生都得到了单独反馈。"},{"en":"The biscuits come in individual packets.","zh":"饼干采用独立包装。"}]},{"pos":"adj.","meaning":"独特的;个性的","definition":"having distinctive personal qualities","examples":[{"en":"Her paintings have an individual style.","zh":"她的画作具有独特风格。"},{"en":"The architect gave each house individual character.","zh":"建筑师赋予每座房子独特个性。"}]},{"pos":"n.","meaning":"个人;个体","definition":"a single person or organism","examples":[{"en":"The rules protect the individual.","zh":"规则保护个人。"},{"en":"Researchers tagged each individual in the herd.","zh":"研究人员给兽群中每个个体作了标记。"}]}],"indolent":[{"pos":"adj.","meaning":"懒惰的；不爱活动的","definition":"avoiding effort or activity","examples":[{"en":"The indolent prince left every task to others.","zh":"懒惰的王子把所有事情都交给别人。"},{"en":"They spent an indolent afternoon beside the pool.","zh":"他们在泳池旁懒洋洋地度过了下午。"}]}],"induce":[{"pos":"v.","meaning":"诱使；劝使；促使","definition":"To persuade or cause someone to do something.","examples":[{"en":"The offer of flexible hours induced her to apply.","zh":"弹性工时的条件促使她提出申请。"},{"en":"Nothing could induce him to reveal the secret.","zh":"没有任何事情能使他说出这个秘密。"}]},{"pos":"v.","meaning":"引起；导致","definition":"To cause a state or event.","examples":[{"en":"The film's slow rhythm induced a feeling of calm.","zh":"电影缓慢的节奏使人产生平静感。"},{"en":"The experiment induced a temporary change in the material.","zh":"实验使这种材料发生了暂时变化。"}]},{"pos":"v.","meaning":"感应产生","definition":"To produce an electrical effect through a changing field.","examples":[{"en":"Moving the magnet induced a current in the coil.","zh":"移动磁铁在线圈中感应出了电流。"},{"en":"The changing field induced a voltage across the conductor.","zh":"变化的场在导体两端感应出了电压。"}]}],"induction":[{"pos":"n.","meaning":"入职介绍;就职;入会","definition":"the introduction or admission of someone to a role","examples":[{"en":"New staff attend an induction session.","zh":"新员工参加入职培训。"},{"en":"Her induction into the society took place in May.","zh":"她五月正式加入协会。"}]},{"pos":"n.","meaning":"归纳;归纳法","definition":"reasoning from particular observations to a general rule","examples":[{"en":"Induction helped them identify a recurring pattern.","zh":"归纳法帮助他们识别反复出现的模式。"},{"en":"The lecture contrasted deduction with induction.","zh":"讲座对比了演绎与归纳。"}]},{"pos":"n.","meaning":"感应;电磁感应","definition":"the production of an electrical effect without direct contact","examples":[{"en":"The cooker heats pans by induction.","zh":"炉具通过电磁感应加热锅具。"},{"en":"The experiment demonstrated electromagnetic induction.","zh":"实验展示了电磁感应。"}]}],"inductive":[{"pos":"adj.","meaning":"归纳的","definition":"reasoning from specific observations to a general conclusion","examples":[{"en":"The students used inductive reasoning to identify the pattern.","zh":"学生使用归纳推理找出了规律。"},{"en":"The method is inductive rather than based on a fixed rule.","zh":"这种方法是归纳式的，并非基于固定规则。"}]},{"pos":"adj.","meaning":"诱导的；引起变化的","definition":"producing or leading to a response","examples":[{"en":"The experiment examined the signal's inductive effect.","zh":"实验考察了该信号的诱导作用。"},{"en":"Researchers studied inductive interactions between developing tissues.","zh":"研究人员考察发育组织之间的诱导相互作用。"}]}],"inductive reasoning":[{"pos":"n.","meaning":"归纳推理","definition":"Reasoning from specific observations towards a general conclusion.","examples":[{"en":"The scientist used inductive reasoning to develop a theory from the observations.","zh":"科学家运用归纳推理，根据观察结果建立了理论。"},{"en":"Inductive reasoning can suggest a pattern without proving that it always holds.","zh":"归纳推理可以提示一种规律，但不能证明它永远成立。"}]}],"indulge":[{"pos":"v.","meaning":"沉溺;纵情享受","definition":"to allow oneself a particular pleasure","examples":[{"en":"She occasionally indulges in rich desserts.","zh":"她偶尔尽情享用浓郁甜点。"},{"en":"He indulged his passion for old maps.","zh":"他尽情满足自己收藏古地图的爱好。"}]},{"pos":"v.","meaning":"纵容;迁就","definition":"to satisfy someone's wishes too readily","examples":[{"en":"The grandparents indulged the children.","zh":"祖父母纵容孩子们。"},{"en":"Do not indulge his unreasonable demands.","zh":"不要迁就他的无理要求。"}]}],"industrialise":[{"pos":"v.","meaning":"使工业化；实现工业化","definition":"to develop manufacturing industries","examples":[{"en":"The region industrialised rapidly.","zh":"这个地区迅速实现了工业化。"},{"en":"New railways helped industrialise the valley.","zh":"新铁路帮助山谷地区实现了工业化。"}]}],"industrious":[{"pos":"adj.","meaning":"勤奋的；勤劳的；勤勉的","definition":"Working hard and steadily.","examples":[{"en":"The industrious student revised her notes every evening.","zh":"这位勤奋的学生每天晚上复习笔记。"},{"en":"An industrious team restored the neglected garden.","zh":"一个勤劳的团队修复了这座荒废的花园。"}]}],"inequality":[{"pos":"n.","meaning":"不平等","definition":"an unfair difference in opportunities or conditions","examples":[{"en":"Access to education can reduce social inequality.","zh":"获得教育的机会可以减少社会不平等。"},{"en":"Income inequality has become a major public concern.","zh":"收入不平等已成为公众关注的重要问题。"},{"en":"The policy aims to address inequality between regions.","zh":"该政策旨在解决地区间的不平等。"}]}],"inescapable":[{"pos":"adj.","meaning":"不可避免的；无法逃避的","definition":"impossible to avoid","examples":[{"en":"The evidence led to an inescapable conclusion.","zh":"证据导向一个无法回避的结论。"},{"en":"Noise is an inescapable part of city life.","zh":"噪声是城市生活中难以避免的一部分。"}]}],"inevitable":[{"pos":"adj.","meaning":"不可避免的；必然发生的","definition":"Certain to happen and impossible to prevent.","examples":[{"en":"Some disruption is inevitable during the repairs.","zh":"维修期间难免会有一些干扰。"},{"en":"With no rainfall, further water restrictions seemed inevitable.","zh":"由于一直没有降雨，进一步限水似乎不可避免。"}]}],"infection":[{"pos":"n.","meaning":"感染;传染病","definition":"the invasion of the body by harmful microorganisms or the resulting illness","examples":[{"en":"The wound showed signs of infection.","zh":"伤口出现感染迹象。"},{"en":"The clinic recorded a rise in respiratory infections.","zh":"诊所记录到呼吸道感染增多。"}]}],"infer":[{"pos":"v.","meaning":"推断；推知","definition":"to reach a conclusion from evidence","examples":[{"en":"We can infer the season from their clothing.","zh":"我们可以从他们的衣服推断季节。"},{"en":"She inferred that the office was closed.","zh":"她推断办公室已经关门。"}]}],"inference":[{"pos":"n.","meaning":"推断；推论","definition":"A conclusion reached from evidence rather than direct statements.","examples":[{"en":"The conclusion is an inference from the available data.","zh":"这个结论是根据现有数据作出的推断。"},{"en":"His silence alone does not justify that inference.","zh":"仅凭他的沉默不足以支持那个推论。"}]}],"inferential":[{"pos":"adj.","meaning":"推理的;推断得出的","definition":"based on conclusions drawn from evidence","examples":[{"en":"The conclusion rests on inferential evidence.","zh":"结论依赖推论性证据。"},{"en":"The course develops inferential reasoning skills.","zh":"课程培养推理能力。"}]}],"inferior":[{"pos":"adj.","meaning":"较差的；低劣的","definition":"lower in quality","examples":[{"en":"The cheaper paint produced an inferior finish.","zh":"较便宜的油漆产生了较差的饰面效果。"},{"en":"She refused to accept inferior materials.","zh":"她拒绝接受劣质材料。"}]},{"pos":"adj.","meaning":"下级的；地位较低的","definition":"lower in rank or position","examples":[{"en":"He held an inferior position in the hierarchy.","zh":"他在等级体系中处于较低位置。"},{"en":"The document was reviewed by an inferior court first.","zh":"文件先由下级法院审查。"}]},{"pos":"n.","meaning":"下级；下属","definition":"a person of lower rank","examples":[{"en":"The officer treated his inferiors respectfully.","zh":"军官尊重地对待下属。"},{"en":"She disliked being regarded as anyone's inferior.","zh":"她不喜欢被视为低人一等。"}]}],"infiltrate":[{"pos":"v.","meaning":"潜入；渗透进入","definition":"To enter a group or place secretly.","examples":[{"en":"An undercover reporter infiltrated the organisation.","zh":"一名卧底记者潜入了该组织。"},{"en":"The spies attempted to infiltrate the enemy camp.","zh":"间谍试图潜入敌方营地。"}]},{"pos":"v.","meaning":"渗入；渗透","definition":"To pass gradually through small spaces or spread into something.","examples":[{"en":"Rainwater infiltrated the cracked concrete.","zh":"雨水渗入了开裂的混凝土。"},{"en":"Air infiltrated the room through gaps around the window.","zh":"空气从窗户周围的缝隙渗入房间。"}]}],"infirmity":[{"pos":"n.","meaning":"虚弱;衰弱;体弱","definition":"physical weakness or illness","examples":[{"en":"Age and infirmity restricted his travel.","zh":"年迈体弱限制了他的出行。"},{"en":"Despite her infirmity, she remained mentally alert.","zh":"尽管身体虚弱，她仍思维敏捷。"}]}],"inflammable":[{"pos":"adj.","meaning":"易燃的","definition":"able to catch fire easily","examples":[{"en":"Keep inflammable materials away from heat.","zh":"让易燃材料远离热源。"},{"en":"The label identifies the liquid as inflammable.","zh":"标签标明该液体易燃。"}]},{"pos":"adj.","meaning":"易怒的；容易激动的","definition":"easily made angry or excited","examples":[{"en":"The character is known for an inflammable temper.","zh":"这个角色以脾气暴躁著称。"},{"en":"The speech excited the already inflammable crowd.","zh":"演讲激起了原本就容易激动的人群。"}]}],"inflate":[{"pos":"v.","meaning":"使充气；使膨胀","definition":"To fill something with air or gas.","examples":[{"en":"He inflated the bicycle tyres before leaving.","zh":"离开前他给自行车轮胎充了气。"},{"en":"The life jacket inflates automatically in water.","zh":"这件救生衣遇水会自动充气。"}]},{"pos":"v.","meaning":"抬高；夸大；使通货膨胀","definition":"To increase a price, amount, or claim beyond its normal level.","examples":[{"en":"High demand inflated the cost of hotel rooms.","zh":"旺盛需求推高了酒店房价。"},{"en":"The advertisement inflated the product's benefits.","zh":"广告夸大了产品的好处。"}]},{"pos":"v.","meaning":"使自满；使骄傲","definition":"To make someone feel excessively important.","examples":[{"en":"The praise inflated his ego.","zh":"赞扬使他变得自负。"},{"en":"Early success had inflated her confidence beyond her actual experience.","zh":"早期成功使她的自信膨胀，超出了实际经验所能支撑的程度。"}]}],"inflation":[{"pos":"n.","meaning":"通货膨胀","definition":"a general rise in prices","examples":[{"en":"High inflation reduces the value of savings.","zh":"高通胀降低储蓄的价值。"},{"en":"Wages have not kept pace with inflation.","zh":"工资未能跟上通胀速度。"},{"en":"The central bank raised interest rates to control inflation.","zh":"央行提高利率以控制通胀。"}]}],"inflict":[{"pos":"v.","meaning":"使遭受；把……强加于","definition":"to cause someone to suffer something harmful","examples":[{"en":"The storm inflicted serious damage.","zh":"风暴造成了严重损害。"},{"en":"The policy inflicted hardship on small businesses.","zh":"政策给小企业带来了困难。"}]}],"influence":[{"pos":"v.","meaning":"影响；左右","definition":"To affect someone's actions or the development of something.","examples":[{"en":"Weather can influence the timing of the harvest.","zh":"天气会影响收获时间。"},{"en":"Her teacher influenced her decision to study physics.","zh":"她的老师影响了她学习物理的决定。"}]},{"pos":"n.","meaning":"影响；影响力","definition":"The power to affect behaviour, events, or opinions.","examples":[{"en":"The media have a strong influence on public debate.","zh":"媒体对公共讨论有很大影响。"},{"en":"He used his influence to support the local library.","zh":"他运用自己的影响力支持当地图书馆。"}]},{"pos":"n.","meaning":"产生影响的人或事物","definition":"A person or thing that changes how someone thinks or behaves.","examples":[{"en":"Her grandmother was a positive influence during her childhood.","zh":"祖母在她童年时期给了她积极影响。"},{"en":"The book was an important influence on his early paintings.","zh":"这本书对他早期绘画产生了重要影响。"}]}],"influential":[{"pos":"adj.","meaning":"有影响力的;有权势的","definition":"able to affect decisions or events","examples":[{"en":"The book became highly influential.","zh":"这本书产生了广泛影响。"},{"en":"An influential supporter helped secure funding.","zh":"一位有影响力的支持者帮助争取到资金。"}]}],"influenza":[{"pos":"n.","meaning":"流行性感冒；流感","definition":"a contagious viral illness commonly called flu","examples":[{"en":"Influenza spread through the school.","zh":"流感在学校传播。"},{"en":"The study tracked influenza cases over winter.","zh":"研究追踪了冬季的流感病例。"}]}],"inform":[{"pos":"v.","meaning":"通知；告知；报告","definition":"To give someone facts or information.","examples":[{"en":"Please inform us of any change in your address.","zh":"地址如有变更，请告知我们。"},{"en":"The manager informed the staff that the office would close early.","zh":"经理通知员工办公室会提前关门。"}]}],"informant":[{"pos":"n.","meaning":"线人;提供情报的人","definition":"a person secretly supplying information to authorities","examples":[{"en":"An informant alerted police to the robbery.","zh":"一名线人向警方通报了抢劫案。"},{"en":"The witness feared being labelled an informant.","zh":"证人害怕被视为告密者。"}]},{"pos":"n.","meaning":"提供资料的人;受访资料提供者","definition":"someone providing information for research or inquiry","examples":[{"en":"Local informants described the village's customs.","zh":"当地资料提供者介绍了村子的风俗。"},{"en":"The linguist recorded an elderly informant's speech.","zh":"语言学家录下了一位年长受访者的话语。"}]}],"infrastructure":[{"pos":"n.","meaning":"基础设施","definition":"the basic systems and structures a society needs","examples":[{"en":"The city needs better transport infrastructure.","zh":"这座城市需要更好的交通基础设施。"},{"en":"Investment in infrastructure can support economic growth.","zh":"基础设施投资可以支持经济增长。"},{"en":"The flood damaged essential infrastructure.","zh":"洪水损坏了重要基础设施。"}]}],"infringe":[{"pos":"v.","meaning":"违反；触犯","definition":"To break a law, rule, or agreement.","examples":[{"en":"The company was accused of infringing copyright.","zh":"这家公司被指控侵犯版权。"},{"en":"The design was changed to avoid infringing the patent.","zh":"设计作了修改，以免侵犯专利权。"}]},{"pos":"v.","meaning":"侵犯；侵害；干涉","definition":"To limit or interfere with someone's rights or freedom.","examples":[{"en":"The policy must not infringe on personal privacy.","zh":"这项政策不得侵犯个人隐私。"},{"en":"Residents feared the restrictions would infringe on their freedom of movement.","zh":"居民担心这些限制会侵犯他们的行动自由。"}]}],"ingenuity":[{"pos":"n.","meaning":"足智多谋;巧妙;创造才能","definition":"skill in finding clever solutions","examples":[{"en":"Her ingenuity solved the storage problem.","zh":"她的巧思解决了储物问题。"},{"en":"The device impressed us with its ingenuity.","zh":"装置的巧妙令我们赞叹。"}]}],"ingredient":[{"pos":"n.","meaning":"原料；成分","definition":"one substance in a mixture, especially food","examples":[{"en":"Flour is the main ingredient.","zh":"面粉是主要原料。"},{"en":"Check the list of ingredients on the packet.","zh":"查看包装上的成分表。"}]},{"pos":"n.","meaning":"要素；因素","definition":"something necessary for a result","examples":[{"en":"Patience is an essential ingredient of good teaching.","zh":"耐心是良好教学的重要要素。"},{"en":"Trust was the missing ingredient in their partnership.","zh":"信任是他们的合作缺少的要素。"}]}],"inhabitant":[{"pos":"n.","meaning":"居民；居住者；栖息动物","definition":"A person or animal living in a particular place.","examples":[{"en":"The island has fewer than five hundred inhabitants.","zh":"这座岛上的居民不到五百人。"},{"en":"The pond's smallest inhabitants are visible only under a microscope.","zh":"池塘中最小的生物只有在显微镜下才看得见。"}]}],"inhale":[{"pos":"v.","meaning":"吸入;吸气","definition":"to breathe air or another substance into the lungs","examples":[{"en":"Inhale slowly before speaking.","zh":"说话前缓慢吸气。"},{"en":"Workers accidentally inhaled smoke.","zh":"工人意外吸入了烟雾。"}]}],"inherent":[{"pos":"adj.","meaning":"固有的；内在的","definition":"existing as a natural part of something","examples":[{"en":"The method has inherent limitations.","zh":"这种方法有固有局限。"},{"en":"The report examines risks inherent in the process.","zh":"报告研究了该过程固有的风险。"}]}],"inheritance":[{"pos":"n.","meaning":"继承；遗产；继承物","definition":"Money or property received from someone who has died.","examples":[{"en":"She used her inheritance to restore the family home.","zh":"她用继承的遗产修复了祖宅。"},{"en":"The siblings reached an agreement about the inheritance.","zh":"兄弟姐妹就遗产达成了协议。"}]},{"pos":"n.","meaning":"遗传","definition":"The passing of biological characteristics from parents to offspring.","examples":[{"en":"The class studied the inheritance of flower colour.","zh":"课堂上研究了花色的遗传。"},{"en":"The experiment explored patterns of genetic inheritance.","zh":"实验探讨了基因遗传的规律。"}]},{"pos":"n.","meaning":"传承；文化遗产","definition":"Traditions or qualities passed down from earlier generations.","examples":[{"en":"The songs form part of the community's cultural inheritance.","zh":"这些歌曲构成了该社区文化传承的一部分。"},{"en":"They worked to preserve their linguistic inheritance.","zh":"他们努力保存自己传承的语言文化。"}]}],"inhibit":[{"pos":"v.","meaning":"抑制;阻碍;约束","definition":"to slow, prevent, or restrain something","examples":[{"en":"Fear of mistakes can inhibit learning.","zh":"害怕犯错会阻碍学习。"},{"en":"The chemical inhibits bacterial growth.","zh":"这种化学物质抑制细菌生长。"}]}],"inhumane":[{"pos":"adj.","meaning":"不人道的；残忍的","definition":"causing unnecessary suffering","examples":[{"en":"The inquiry criticised inhumane conditions.","zh":"调查批评了不人道的条件。"},{"en":"The charity campaigns against inhumane treatment of animals.","zh":"慈善机构开展反对残忍对待动物的活动。"}]}],"initial":[{"pos":"adj.","meaning":"最初的；开始的","definition":"Occurring at the beginning.","examples":[{"en":"The initial results looked promising.","zh":"初步结果看起来很有希望。"},{"en":"After the initial meeting, we exchanged emails.","zh":"初次会面后，我们互通了电子邮件。"}]},{"pos":"adj.","meaning":"词首的；首位的","definition":"At the beginning of a word or sequence.","examples":[{"en":"The initial consonant is silent in this word.","zh":"这个词的词首辅音不发音。"},{"en":"Write the initial letter in a larger size.","zh":"把首字母写得大一些。"}]},{"pos":"n.","meaning":"姓名首字母；词首字母","definition":"The first letter of a name or word.","examples":[{"en":"Her initials are embroidered on the bag.","zh":"她姓名的首字母绣在包上。"},{"en":"Please enter your first initial and surname.","zh":"请填写名字的首字母和姓氏。"}]}],"initiate":[{"pos":"v.","meaning":"发起;开始","definition":"to cause a process to begin","examples":[{"en":"The council initiated a recycling programme.","zh":"市议会发起了回收项目。"},{"en":"Press this button to initiate the test.","zh":"按此按钮开始测试。"}],"ipa":"/ɪˈnɪʃieɪt/"},{"pos":"v.","meaning":"接纳入会;传授入门知识","definition":"to admit someone to a group or introduce a skill","examples":[{"en":"The club initiated five new members.","zh":"俱乐部接纳了五名新成员。"},{"en":"Her aunt initiated her into the art of baking.","zh":"她的姑妈教她入门烘焙技艺。"}],"ipa":"/ɪˈnɪʃieɪt/"},{"pos":"n.","meaning":"新加入者;入门者","definition":"a person newly admitted to a group or skill","examples":[{"en":"The initiates learned the society's traditions.","zh":"新成员学习了协会传统。"},{"en":"Even an initiate can follow these basic instructions.","zh":"即使初学者也能遵循这些基本说明。"}],"ipa":"/ɪˈnɪʃiət/"}],"initiative":[{"pos":"n.","meaning":"倡议；新方案","definition":"a new plan intended to improve something","examples":[{"en":"The city launched a recycling initiative.","zh":"城市发起了回收倡议。"},{"en":"The initiative supports young entrepreneurs.","zh":"这个新方案支持年轻创业者。"}]},{"pos":"n.","meaning":"主动性；积极性","definition":"the ability to act without being told","examples":[{"en":"She showed initiative by solving the problem herself.","zh":"她自行解决问题，表现了主动性。"},{"en":"Staff are encouraged to use their initiative.","zh":"员工被鼓励发挥主动性。"}]},{"pos":"n.","meaning":"主动权","definition":"the power to take action before others","examples":[{"en":"The team regained the initiative.","zh":"球队重新掌握了主动权。"},{"en":"The early agreement gave us the initiative in negotiations.","zh":"早期达成的协议让我们在谈判中获得主动权。"}]}],"inject":[{"pos":"v.","meaning":"注射；注入","definition":"To put a substance into something using pressure, often with a needle.","examples":[{"en":"The nurse injected the medicine into his arm.","zh":"护士把药注射到他的手臂中。"},{"en":"The machine injects hot plastic into a mould.","zh":"机器把热塑料注入模具。"}]},{"pos":"v.","meaning":"注入；增添；灌输","definition":"To introduce energy, money, or another quality into a situation.","examples":[{"en":"The grant injected new resources into the research programme.","zh":"这笔资助为研究项目注入了新资源。"},{"en":"Her arrival injected energy into the discussion.","zh":"她的到来为讨论增添了活力。"}]}],"inland":[{"pos":"adj.","meaning":"内陆的","definition":"located away from the coast","examples":[{"en":"They visited an inland lake.","zh":"他们游览了一个内陆湖。"},{"en":"Inland towns suffered the worst drought.","zh":"内陆城镇遭遇了最严重的干旱。"}]},{"pos":"adv.","meaning":"向内陆;在内地","definition":"toward or within the interior of a country","examples":[{"en":"The road turns inland beyond the village.","zh":"公路在村庄之后转向内陆。"},{"en":"We travelled inland to escape the storm.","zh":"我们向内地行进以避开风暴。"}]}],"inlet":[{"pos":"n.","meaning":"入口；进口","definition":"an opening through which fluid enters","examples":[{"en":"Clean the air inlet regularly.","zh":"定期清洁进气口。"},{"en":"The pipe connects to the water inlet.","zh":"管道连接进水口。"}]},{"pos":"n.","meaning":"小海湾；水湾","definition":"a narrow area of water extending into land","examples":[{"en":"The boats sheltered in a quiet inlet.","zh":"船只在安静的小海湾避风。"},{"en":"A wooded inlet lies beyond the headland.","zh":"岬角后有一个树木环绕的水湾。"}]}],"innocent":[{"pos":"adj.","meaning":"无罪的；清白的","definition":"Not responsible for wrongdoing.","examples":[{"en":"The evidence showed that he was innocent.","zh":"证据表明他是清白的。"},{"en":"Several innocent people were wrongly accused.","zh":"几名无辜者遭到了错误指控。"}]},{"pos":"adj.","meaning":"无害的；无恶意的","definition":"Not intended to cause harm or offence.","examples":[{"en":"It was an innocent question, not a criticism.","zh":"那是一个没有恶意的问题，并非批评。"},{"en":"An innocent joke caused an unexpected misunderstanding.","zh":"一个无心的玩笑引起了意外误会。"}]},{"pos":"adj.","meaning":"天真的；纯真的","definition":"Lacking experience of the unpleasant aspects of life.","examples":[{"en":"The child's innocent curiosity delighted her grandparents.","zh":"孩子天真的好奇心让祖父母很开心。"},{"en":"He had an innocent belief that everyone kept their promises.","zh":"他天真地相信人人都会遵守承诺。"}]}],"innovation":[{"pos":"n.","meaning":"创新","definition":"the development of new ideas or methods","examples":[{"en":"Investment in research encourages innovation.","zh":"研究投资鼓励创新。"},{"en":"Digital innovation has changed how people shop.","zh":"数字创新改变了人们的购物方式。"},{"en":"The company rewards innovation among its staff.","zh":"公司奖励员工的创新。"}]}],"innovative":[{"pos":"adj.","meaning":"创新的；新颖的；富有创新精神的","definition":"introducing original ideas or methods","examples":[{"en":"The team proposed an innovative design.","zh":"团队提出了创新设计。"},{"en":"An innovative teacher can make limited resources effective.","zh":"富有创新精神的老师能有效利用有限资源。"}]}],"input":[{"pos":"n.","meaning":"输入；投入；输入数据","definition":"Information, effort, or resources supplied to a system or activity.","examples":[{"en":"The programme checks the input for errors.","zh":"程序检查输入数据是否有错误。"},{"en":"We need input from teachers before changing the curriculum.","zh":"修改课程之前，我们需要教师的意见。"}]},{"pos":"v.","meaning":"输入；录入","definition":"To enter data into a computer or system.","examples":[{"en":"She input the survey results into a spreadsheet.","zh":"她把调查结果输入了电子表格。"},{"en":"Input your password to continue.","zh":"请输入密码以继续。"}]}],"inquire":[{"pos":"v.","meaning":"询问；打听","definition":"to ask for information","examples":[{"en":"I called the office to inquire about the application deadline.","zh":"我给办公室打电话询问申请截止日期。"},{"en":"Visitors can inquire at reception about guided tours.","zh":"游客可以到接待处询问导览活动。"}]},{"pos":"v.","meaning":"调查；查究","definition":"to investigate a matter carefully, often with into","examples":[{"en":"An independent panel will inquire into the cause of the accident.","zh":"一个独立小组将调查事故原因。"},{"en":"The committee was asked to inquire into the missing funds.","zh":"该委员会被要求调查失踪资金的问题。"}]}],"insane":[{"pos":"adj.","meaning":"荒唐的;疯狂的","definition":"extremely foolish or unreasonable","examples":[{"en":"Driving that fast in fog is insane.","zh":"在雾中开那么快简直疯了。"},{"en":"The proposal seemed insane to the cautious investors.","zh":"这项提议在谨慎的投资者看来很荒唐。"}]},{"pos":"adj.","meaning":"精神失常的（旧式或法律用语）","definition":"having severe mental illness in older or legal usage","examples":[{"en":"The court found him legally insane.","zh":"法院认定他在法律意义上精神失常。"},{"en":"The historical record says she was declared insane.","zh":"历史记录称她被宣布精神失常。"}]}],"inscribe":[{"pos":"v.","meaning":"题写；铭刻","definition":"to write or carve words on a surface","examples":[{"en":"Her name was inscribed on the medal.","zh":"她的名字刻在奖章上。"},{"en":"He inscribed a message inside the book.","zh":"他在书内题写了一条赠言。"}]},{"pos":"v.","meaning":"使铭记；牢记","definition":"to fix deeply in memory","examples":[{"en":"The scene remained inscribed in her memory.","zh":"那场景始终铭刻在她的记忆里。"},{"en":"The experience inscribed a lasting lesson on his mind.","zh":"这段经历使他牢记一个教训。"}]}],"insecure":[{"pos":"adj.","meaning":"不安全的；无保障的；不牢靠的","definition":"Not safe, stable, or firmly protected.","examples":[{"en":"The workers were worried about their insecure employment.","zh":"工人们担心自己的工作缺乏保障。"},{"en":"An insecure window made the house vulnerable to theft.","zh":"一扇关不牢的窗户使房屋容易遭窃。"}]},{"pos":"adj.","meaning":"缺乏自信的；不安的","definition":"Lacking confidence in oneself or one's relationships.","examples":[{"en":"She felt insecure about speaking in front of strangers.","zh":"在陌生人面前讲话使她缺乏自信。"},{"en":"Constant criticism can make a child insecure.","zh":"不断批评可能使孩子缺乏安全感。"}]}],"insert":[{"pos":"v.","meaning":"插入;嵌入","definition":"to put something into or between other things","examples":[{"en":"Insert the key into the lock.","zh":"把钥匙插进锁孔。"},{"en":"She inserted a new paragraph into the report.","zh":"她在报告中插入了新段落。"}]}],"insidious":[{"pos":"adj.","meaning":"隐伏而有害的；潜在危险的","definition":"gradually causing harm without being obvious","examples":[{"en":"The report describes the insidious effects of prejudice.","zh":"报告描述了偏见潜移默化的危害。"},{"en":"An insidious leak weakened the structure.","zh":"一处隐蔽的渗漏削弱了结构。"}]}],"insight":[{"pos":"n.","meaning":"洞察力；深刻理解；顿悟","definition":"A clear understanding of something, often gained suddenly.","examples":[{"en":"The interview gave us an insight into her working methods.","zh":"访谈让我们深入了解了她的工作方法。"},{"en":"His sudden insight solved a problem that had puzzled the team.","zh":"他突然领悟到的道理解决了困扰团队的难题。"}]}],"insignificant":[{"pos":"adj.","meaning":"微不足道的;无关紧要的","definition":"too small or unimportant to matter","examples":[{"en":"The difference in price is insignificant.","zh":"价格差异微不足道。"},{"en":"One insignificant detail changed the investigation.","zh":"一个看似不起眼的细节改变了调查。"}]}],"insist":[{"pos":"v.","meaning":"坚持说；坚决认为","definition":"to state firmly that something is true","examples":[{"en":"She insisted that the figures were correct.","zh":"她坚持认为数字正确。"},{"en":"The witness insisted he had seen the vehicle.","zh":"证人坚持说自己看到了那辆车。"}]},{"pos":"v.","meaning":"坚持要求；一定要","definition":"to demand that something happen","examples":[{"en":"He insisted on paying for lunch.","zh":"他坚持要付午餐钱。"},{"en":"The inspector insisted that the work stop.","zh":"检查员坚持要求停工。"}]}],"inspect":[{"pos":"v.","meaning":"检查；视察；检阅","definition":"To examine something carefully or make an official visit.","examples":[{"en":"The mechanic inspected the brakes before the journey.","zh":"出行前，机械师检查了刹车。"},{"en":"The officer inspected the troops on the parade ground.","zh":"军官在阅兵场上检阅了部队。"}]}],"inspiration":[{"pos":"n.","meaning":"灵感;启示","definition":"a creative idea or stimulating influence","examples":[{"en":"The landscape gave her inspiration for a poem.","zh":"风景给了她写诗的灵感。"},{"en":"He found inspiration in ordinary street scenes.","zh":"他从平常街景中获得灵感。"}]},{"pos":"n.","meaning":"鼓舞人心的人或事","definition":"someone or something that encourages others","examples":[{"en":"Her courage is an inspiration to us all.","zh":"她的勇气鼓舞着我们所有人。"},{"en":"The team's victory became an inspiration for young athletes.","zh":"团队的胜利激励了年轻运动员。"}]}],"inspire":[{"pos":"v.","meaning":"鼓舞；激起","definition":"to encourage action or cause a feeling","examples":[{"en":"Her determination inspired the whole team.","zh":"她的决心鼓舞了整个团队。"},{"en":"The speech inspired confidence.","zh":"演讲激发了信心。"}]},{"pos":"v.","meaning":"给予灵感","definition":"to give someone an idea for creative work","examples":[{"en":"The coastline inspired many of her paintings.","zh":"海岸线启发了她的许多画作。"},{"en":"A childhood memory inspired the story.","zh":"童年记忆启发了这个故事。"}]}],"inspiring":[{"pos":"adj.","meaning":"鼓舞人心的；启发灵感的","definition":"Making people feel motivated or creatively excited.","examples":[{"en":"Her inspiring speech encouraged students to volunteer.","zh":"她鼓舞人心的演讲鼓励学生参加志愿活动。"},{"en":"The landscape provided an inspiring setting for the painting class.","zh":"这片风景为绘画课提供了启发灵感的环境。"}]}],"install":[{"pos":"v.","meaning":"安装;设置","definition":"to put equipment or software in place for use","examples":[{"en":"Workers installed solar panels on the roof.","zh":"工人在屋顶安装了太阳能板。"},{"en":"Install the update before restarting.","zh":"重启前先安装更新。"}]},{"pos":"v.","meaning":"安置;使就位","definition":"to settle someone comfortably in a place","examples":[{"en":"They installed the guests in a quiet bedroom.","zh":"他们把客人安顿在安静的卧室。"},{"en":"She installed herself by the window with a book.","zh":"她拿着书在窗边安坐下来。"}]},{"pos":"v.","meaning":"正式任命;使就职","definition":"to place someone formally in an office","examples":[{"en":"The new chancellor was installed at a ceremony.","zh":"新校监在仪式上正式就职。"},{"en":"The board installed a new chief executive.","zh":"董事会任命了新的首席执行官。"}]}],"installment":[{"pos":"n.","meaning":"分期付款的一期款项","definition":"one of several payments made over time","examples":[{"en":"We paid the first installment in June.","zh":"我们六月支付了第一期款项。"},{"en":"The fee can be paid in monthly installments.","zh":"费用可以按月分期支付。"}]},{"pos":"n.","meaning":"连载的一期；一集","definition":"one part of a story or programme released in sections","examples":[{"en":"The next installment appears on Friday.","zh":"下一期将于星期五推出。"},{"en":"She eagerly awaited the final installment.","zh":"她热切等待最终一集。"}]}],"instalment":[{"pos":"n.","meaning":"分期付款的一期","definition":"one of several payments for something","examples":[{"en":"The first instalment is due in January.","zh":"第一期款项一月到期。"},{"en":"You can pay one instalment each month.","zh":"你可以每月支付一期款项。"},{"en":"Missing an instalment may result in an extra charge.","zh":"漏付一期款项可能导致额外收费。"}]}],"instil":[{"pos":"v.","meaning":"逐渐灌输;培养","definition":"to establish an idea or feeling gradually","examples":[{"en":"Her parents instilled confidence in her.","zh":"父母逐渐培养了她的自信。"},{"en":"The course instils respect for scientific evidence.","zh":"课程培养对科学证据的尊重。"}]},{"pos":"v.","meaning":"滴入;滴注（专业用语）","definition":"to introduce a liquid drop by drop","examples":[{"en":"The nurse instilled the prescribed drops into the eye.","zh":"护士将处方眼药水滴入眼中。"},{"en":"The laboratory device instils liquid into each sample.","zh":"实验装置把液体滴入每份样本。"}]}],"instinct":[{"pos":"n.","meaning":"本能；天性","definition":"a natural pattern of behaviour not learned consciously","examples":[{"en":"The bird's nesting instinct is strong.","zh":"这种鸟的筑巢本能很强。"},{"en":"Self-preservation is a basic instinct.","zh":"自我保护是一种基本本能。"}]},{"pos":"n.","meaning":"直觉","definition":"an immediate feeling not based on conscious reasoning","examples":[{"en":"Her instinct told her to wait.","zh":"她的直觉告诉她要等。"},{"en":"He has a good instinct for choosing locations.","zh":"他在选址方面直觉很好。"}]}],"instinctual":[{"pos":"adj.","meaning":"本能的","definition":"Arising naturally without conscious thought or learning.","examples":[{"en":"The bird's instinctual response was to protect its nest.","zh":"鸟的本能反应是保护自己的巢。"},{"en":"He felt an instinctual urge to step back from the edge.","zh":"他本能地想要从边缘退后。"}]}],"institute":[{"pos":"n.","meaning":"研究所;学院;机构","definition":"an organization for specialized study or work","examples":[{"en":"She works at a marine research institute.","zh":"她在海洋研究所工作。"},{"en":"The institute offers courses in design.","zh":"学院开设设计课程。"}]},{"pos":"v.","meaning":"建立;设立;开始实行","definition":"to establish a system or begin a procedure","examples":[{"en":"The school instituted a new attendance policy.","zh":"学校制定了新的出勤政策。"},{"en":"They instituted legal proceedings against the supplier.","zh":"他们对供应商提起了法律诉讼。"}]}],"institution":[{"pos":"n.","meaning":"机构；团体；协会","definition":"an established organisation serving a social purpose","examples":[{"en":"The museum is a respected cultural institution.","zh":"博物馆是一家受人尊敬的文化机构。"},{"en":"Several educational institutions joined the project.","zh":"几家教育机构加入了项目。"}]},{"pos":"n.","meaning":"制度；习俗","definition":"a long-established social system or practice","examples":[{"en":"The book examines the institution of marriage.","zh":"这本书研究婚姻制度。"},{"en":"The annual fair has become a local institution.","zh":"年度集市已成为当地的惯例。"}]},{"pos":"n.","meaning":"设立；制定；建立","definition":"the act of establishing a system or practice","examples":[{"en":"The institution of new rules reduced confusion.","zh":"新规则的制定减少了混乱。"},{"en":"The institution of regular inspections improved safety.","zh":"定期检查制度的建立提高了安全性。"}]}],"instruct":[{"pos":"v.","meaning":"教导；教授","definition":"To teach someone how to do something.","examples":[{"en":"The coach instructed us in basic climbing techniques.","zh":"教练教我们基本的攀岩技巧。"},{"en":"New staff are instructed in the safe use of equipment.","zh":"新员工会接受设备安全使用方面的培训。"}]},{"pos":"v.","meaning":"指示；命令","definition":"To tell someone formally what they must do.","examples":[{"en":"The judge instructed the jury to consider only the evidence.","zh":"法官指示陪审团只考虑证据。"},{"en":"We were instructed to wait outside the building.","zh":"我们被要求在楼外等待。"}]}],"instrument":[{"pos":"n.","meaning":"仪器;器械;工具","definition":"a device used for precise work or measurement","examples":[{"en":"The instrument measures air pressure.","zh":"这台仪器测量气压。"},{"en":"The surgeon checked each instrument.","zh":"外科医生检查了每件器械。"}]},{"pos":"n.","meaning":"乐器","definition":"a device used to produce music","examples":[{"en":"She plays several musical instruments.","zh":"她会演奏几种乐器。"},{"en":"The violin is a demanding instrument.","zh":"小提琴是一种要求很高的乐器。"}]},{"pos":"n.","meaning":"手段;工具","definition":"a means used to achieve a purpose","examples":[{"en":"Education is an instrument of social change.","zh":"教育是社会变革的工具。"},{"en":"The treaty became an instrument for cooperation.","zh":"条约成为合作的手段。"}]}],"instrumental":[{"pos":"adj.","meaning":"起重要作用的；有帮助的","definition":"important in making something happen","examples":[{"en":"She was instrumental in securing the funding.","zh":"她在争取资金方面起了重要作用。"},{"en":"Local volunteers were instrumental to the project's success.","zh":"当地志愿者为项目成功发挥了重要作用。"}]},{"pos":"adj.","meaning":"器乐的；用乐器演奏的","definition":"performed with instruments rather than voices","examples":[{"en":"The album includes three instrumental tracks.","zh":"专辑包含三首器乐曲。"},{"en":"They performed an instrumental version of the song.","zh":"他们演奏了这首歌的器乐版本。"}]}],"insufficient":[{"pos":"adj.","meaning":"不足的；不够的","definition":"Not enough for a particular purpose.","examples":[{"en":"There was insufficient evidence to support the claim.","zh":"没有足够证据支持这一说法。"},{"en":"Insufficient rainfall damaged the crops.","zh":"降雨不足损害了庄稼。"}]}],"insularity":[{"pos":"n.","meaning":"岛国状态;隔绝状态","definition":"the condition of being an island or isolated","examples":[{"en":"The island's insularity shaped its wildlife.","zh":"岛国的隔绝状态塑造了其野生生物特点。"},{"en":"Improved transport reduced the community's insularity.","zh":"交通改善减轻了社区与外界隔绝的状态。"}]},{"pos":"n.","meaning":"思想狭隘;褊狭","definition":"a narrow outlook uninterested in other cultures","examples":[{"en":"Travel challenged his cultural insularity.","zh":"旅行打破了他文化观念上的狭隘。"},{"en":"The report criticized the institution's insularity.","zh":"报告批评了该机构的思想封闭。"}]}],"insulate":[{"pos":"v.","meaning":"使隔热；使隔音；使绝缘","definition":"to prevent heat, sound, or electricity from passing","examples":[{"en":"The walls are insulated against heat loss.","zh":"墙体做了隔热处理以防热量流失。"},{"en":"Rubber insulates the electrical cable.","zh":"橡胶使电缆绝缘。"}]},{"pos":"v.","meaning":"隔离；使免受影响","definition":"to protect from an unpleasant influence","examples":[{"en":"Savings helped insulate the family from financial shocks.","zh":"储蓄帮助这个家庭抵御财务冲击。"},{"en":"No policy can fully insulate businesses from change.","zh":"没有政策能让企业完全不受变化影响。"}]}],"insulation":[{"pos":"n.","meaning":"隔热；隔音；绝缘","definition":"The prevention of heat, sound, or electricity from passing through.","examples":[{"en":"Better insulation keeps the house warm in winter.","zh":"更好的隔热措施使房子冬天保持温暖。"},{"en":"The studio needs sound insulation to protect neighbouring rooms.","zh":"录音室需要隔音，以免影响相邻房间。"}]},{"pos":"n.","meaning":"绝缘材料；隔热材料；隔音材料","definition":"Material used to block heat, sound, or electricity.","examples":[{"en":"The electrician replaced the damaged insulation around the wire.","zh":"电工更换了电线外损坏的绝缘层。"},{"en":"Workers fitted insulation between the roof beams.","zh":"工人在屋顶横梁之间安装了隔热材料。"}]},{"pos":"n.","meaning":"隔绝；隔离状态","definition":"Protection from outside influences or contact.","examples":[{"en":"The remote location gave the community some insulation from political unrest.","zh":"偏远的位置使该社区在一定程度上免受政治动荡影响。"},{"en":"No organisation can operate in complete insulation from society.","zh":"没有任何组织能完全脱离社会运作。"}]}],"insurance":[{"pos":"n.","meaning":"保险","definition":"an arrangement that provides financial protection against certain losses","examples":[{"en":"Travel insurance can cover lost luggage.","zh":"旅行保险可以承保行李遗失。"},{"en":"Check what your health insurance includes.","zh":"请核实你的健康保险包含哪些项目。"},{"en":"The insurance policy does not cover flood damage.","zh":"这份保险不承保洪水损失。"}]},{"pos":"n.","meaning":"保险费","definition":"money paid for insurance protection","examples":[{"en":"His car insurance costs more this year.","zh":"今年他的车险保费更高。"},{"en":"The rent includes insurance for the building.","zh":"租金包含建筑保险费。"}]},{"pos":"n.","meaning":"保险业","definition":"the business of providing insurance","examples":[{"en":"She works in insurance.","zh":"她从事保险业。"},{"en":"Technology is changing the insurance industry.","zh":"技术正在改变保险业。"}]}],"intact":[{"pos":"adj.","meaning":"完整无缺的；完好无损的","definition":"complete and undamaged","examples":[{"en":"The glass survived intact.","zh":"玻璃完好无损。"},{"en":"Most of the original structure remains intact.","zh":"大部分原有结构仍完整保留。"}]}],"intake":[{"pos":"n.","meaning":"摄入量；吸入；纳入","definition":"The amount or act of taking something into the body or an organisation.","examples":[{"en":"The survey measured daily water intake.","zh":"调查测量了每日饮水量。"},{"en":"The college increased its annual student intake.","zh":"学院增加了每年的招生人数。"}]},{"pos":"n.","meaning":"入口；进气口","definition":"An opening through which air, water, or another substance enters.","examples":[{"en":"Leaves blocked the engine's air intake.","zh":"树叶堵住了发动机的进气口。"},{"en":"A screen prevents fish from entering the water intake.","zh":"一道网阻止鱼游进取水口。"}]}],"integral":[{"pos":"adj.","meaning":"必不可少的;构成整体所必需的","definition":"essential to a complete whole","examples":[{"en":"Trust is integral to their partnership.","zh":"信任是他们合作不可或缺的一部分。"},{"en":"The handle is an integral part of the lid.","zh":"把手是盖子的组成部分。"}]},{"pos":"adj.","meaning":"完整的;一体的","definition":"forming a complete unit","examples":[{"en":"The device has an integral battery compartment.","zh":"装置有一体式电池仓。"},{"en":"The designer conceived the complex as an integral whole.","zh":"设计师把建筑群构想为完整的整体。"}]}],"integrate":[{"pos":"v.","meaning":"整合；合并；融为一体","definition":"to combine parts into a functioning whole","examples":[{"en":"The course integrates theory and practice.","zh":"课程融合理论与实践。"},{"en":"The new system integrates with existing software.","zh":"新系统与现有软件整合。"}]}],"integration":[{"pos":"n.","meaning":"融合；融入","definition":"the process of bringing different parts or people together","examples":[{"en":"Language classes can support the integration of newcomers.","zh":"语言课程可以帮助新来者融入社会。"},{"en":"Social integration requires effort from the whole community.","zh":"社会融合需要整个社区共同努力。"},{"en":"The programme encourages integration through shared activities.","zh":"该项目通过共同活动促进融合。"}]}],"intellectual":[{"pos":"adj.","meaning":"智力的;理智的;知识方面的","definition":"relating to thought and understanding","examples":[{"en":"The debate provided an intellectual challenge.","zh":"辩论带来了智力挑战。"},{"en":"She prefers intellectual discussion to gossip.","zh":"比起闲话，她更喜欢有思想的讨论。"}]},{"pos":"n.","meaning":"知识分子","definition":"a person deeply involved in learning and ideas","examples":[{"en":"Many intellectuals supported the reform.","zh":"许多知识分子支持改革。"},{"en":"The café attracted writers and intellectuals.","zh":"咖啡馆吸引了作家和知识分子。"}]}],"intelligence":[{"pos":"n.","meaning":"智力；理解力","definition":"the ability to learn, understand, and reason","examples":[{"en":"The task requires both intelligence and patience.","zh":"这项任务既需要智力也需要耐心。"},{"en":"Researchers study animal intelligence.","zh":"研究人员研究动物智力。"}]},{"pos":"n.","meaning":"情报","definition":"information collected for strategic purposes","examples":[{"en":"The agency gathered intelligence about the threat.","zh":"该机构搜集了关于威胁的情报。"},{"en":"The report relied on reliable intelligence.","zh":"报告依赖可靠情报。"}]}],"intelligent":[{"pos":"adj.","meaning":"聪明的；有理解力的；明智的","definition":"Able to learn and reason well or showing good judgement.","examples":[{"en":"She asked an intelligent question about the experiment.","zh":"她就实验提出了一个很有见地的问题。"},{"en":"Dolphins are widely regarded as intelligent animals.","zh":"海豚普遍被认为是聪明的动物。"}]}],"intelligible":[{"pos":"adj.","meaning":"可理解的;清楚易懂的","definition":"clear enough to understand","examples":[{"en":"His explanation was intelligible to beginners.","zh":"他的解释初学者也能听懂。"},{"en":"The damaged recording was barely intelligible.","zh":"受损录音几乎听不清。"}]}],"intend":[{"pos":"v.","meaning":"打算；想要","definition":"to plan or mean to do something","examples":[{"en":"I intend to finish before Friday.","zh":"我打算星期五前完成。"},{"en":"The rooms are intended for visiting researchers.","zh":"这些房间是为来访研究人员准备的。"}]}],"intense":[{"pos":"adj.","meaning":"强烈的；剧烈的；紧张的","definition":"Very strong or extreme in degree.","examples":[{"en":"The hikers struggled in the intense heat.","zh":"徒步者在酷热中艰难前行。"},{"en":"After intense negotiations, the two sides reached an agreement.","zh":"经过紧张谈判，双方达成了协议。"}]},{"pos":"adj.","meaning":"热切的；专注的；情感强烈的","definition":"Showing deep concentration or strong feeling.","examples":[{"en":"She listened with intense interest.","zh":"她怀着极大的兴趣倾听。"},{"en":"He is an intense young musician who practises for hours.","zh":"他是个十分投入的年轻音乐家，一练就是好几个小时。"}]}],"intensify":[{"pos":"v.","meaning":"增强;加剧","definition":"to become or make stronger","examples":[{"en":"The storm intensified overnight.","zh":"风暴在夜间加剧了。"},{"en":"The discovery intensified interest in the site.","zh":"这项发现加强了人们对遗址的兴趣。"}]}],"intensity":[{"pos":"n.","meaning":"强度；强烈程度","definition":"the degree of strength or force","examples":[{"en":"Light intensity decreases with distance.","zh":"光强随距离增加而减弱。"},{"en":"She studied with unusual intensity.","zh":"她学习时格外专注。"}]}],"intensive":[{"pos":"adj.","meaning":"密集的；强化的；集约的","definition":"Involving concentrated effort or activity within a limited period or space.","examples":[{"en":"She completed an intensive language course.","zh":"她完成了一门强化语言课程。"},{"en":"Intensive farming can place heavy demands on soil and water.","zh":"集约农业可能对土壤和水资源提出很高要求。"}]}],"intent":[{"pos":"n.","meaning":"意图;目的","definition":"a purpose or intention","examples":[{"en":"The letter stated their intent to withdraw.","zh":"信中表明了他们退出的意图。"},{"en":"The court examined whether there was criminal intent.","zh":"法院审查是否存在犯罪意图。"}]},{"pos":"adj.","meaning":"专注的;坚决的;一心想做的","definition":"giving full attention or firmly determined","examples":[{"en":"She was intent on finishing the experiment.","zh":"她一心要完成实验。"},{"en":"His intent gaze followed every movement.","zh":"他专注的目光追随着每个动作。"}]}],"intention":[{"pos":"n.","meaning":"意图；目的；打算","definition":"what someone plans or means to do","examples":[{"en":"His intention was to help.","zh":"他的本意是帮忙。"},{"en":"She announced her intention to retire.","zh":"她宣布了退休的打算。"}]}],"interact":[{"pos":"v.","meaning":"相互作用；互动；相互影响","definition":"To communicate or act upon each other.","examples":[{"en":"Children learn social skills by interacting with their peers.","zh":"孩子们通过与同龄人互动学习社交技能。"},{"en":"The chemicals interact to produce a new substance.","zh":"这些化学物质相互作用，生成一种新物质。"}]}],"interdependent":[{"pos":"adj.","meaning":"相互依赖的","definition":"relying on each other","examples":[{"en":"The two economies are closely interdependent.","zh":"两个经济体密切相互依存。"},{"en":"Plants and pollinators form interdependent relationships.","zh":"植物和传粉者形成相互依赖的关系。"}]}],"interest":[{"pos":"n.","meaning":"兴趣；关注","definition":"a desire to know about or take part in something","examples":[{"en":"The talk sparked her interest in astronomy.","zh":"讲座激发了她对天文学的兴趣。"},{"en":"Public interest in the project has grown.","zh":"公众对项目的关注增加了。"}]},{"pos":"n.","meaning":"利息","definition":"money paid for borrowing or keeping money","examples":[{"en":"The account earns interest each month.","zh":"这个账户每月获得利息。"},{"en":"They paid interest on the loan.","zh":"他们支付了贷款利息。"}]},{"pos":"n.","meaning":"利益；权益（常用复数）","definition":"something that benefits or concerns a person or group","examples":[{"en":"The policy protects consumers' interests.","zh":"政策保护消费者利益。"},{"en":"She acted in the children's best interests.","zh":"她以孩子们的最大利益行事。"}]},{"pos":"v.","meaning":"使感兴趣","definition":"to attract someone's attention or curiosity","examples":[{"en":"The old photographs interested the visitors.","zh":"老照片吸引了游客。"},{"en":"Would a course in photography interest you?","zh":"你对摄影课程感兴趣吗？"}]}],"interface":[{"pos":"n.","meaning":"界面；接口","definition":"A point or system through which people or devices communicate.","examples":[{"en":"The app has a simple user interface.","zh":"这个应用的用户界面很简单。"},{"en":"The printer connects through a standard interface.","zh":"打印机通过标准接口连接。"}]},{"pos":"n.","meaning":"交接点；交界；相互作用的领域","definition":"A boundary or area where different systems or subjects meet.","examples":[{"en":"Her research lies at the interface between biology and engineering.","zh":"她的研究处于生物学与工程学的交叉领域。"},{"en":"The project examines the interface between public policy and everyday life.","zh":"项目研究公共政策与日常生活之间的联系。"}]}],"interfere":[{"pos":"v.","meaning":"干涉;干扰;妨碍","definition":"to become involved unwelcome or obstruct something","examples":[{"en":"Do not interfere in their private argument.","zh":"不要干涉他们私下的争论。"},{"en":"Background noise interfered with the recording.","zh":"背景噪声干扰了录音。"}]}],"interior":[{"pos":"adj.","meaning":"内部的；里面的","definition":"inside a building or object","examples":[{"en":"The interior walls need painting.","zh":"内墙需要刷漆。"},{"en":"The designer chose warm interior colours.","zh":"设计师选择了温暖的室内色彩。"}]},{"pos":"n.","meaning":"内部","definition":"the inside part of something","examples":[{"en":"The car's interior was surprisingly spacious.","zh":"车内出人意料地宽敞。"},{"en":"Visitors could inspect the building's interior.","zh":"游客可以查看建筑内部。"}]},{"pos":"n.","meaning":"内地；腹地","definition":"the inland region of a country","examples":[{"en":"The expedition travelled into the interior.","zh":"探险队深入内地。"},{"en":"Railways linked coastal ports to the interior.","zh":"铁路把沿海港口与内地连接起来。"}]}],"intermediate":[{"pos":"adj.","meaning":"中间的；中级的","definition":"Between two stages, positions, or levels.","examples":[{"en":"The course is suitable for intermediate learners.","zh":"这门课程适合中级学习者。"},{"en":"The process has several intermediate stages.","zh":"这一过程包含几个中间阶段。"}]}],"intermix":[{"pos":"v.","meaning":"混合;混杂","definition":"to mix together","examples":[{"en":"The artist intermixed blue and green pigments.","zh":"画家混合了蓝色和绿色颜料。"},{"en":"Several languages intermixed in the lively conversation.","zh":"热闹的交谈中混杂着几种语言。"}]}],"intern":[{"pos":"v.","meaning":"拘禁；扣留","definition":"to detain someone, especially during a war","examples":[{"en":"The authorities interned the sailors during the conflict.","zh":"当局在冲突期间拘禁了这些水手。"},{"en":"The memoir describes being interned in a camp.","zh":"回忆录描述了被拘禁在营地的经历。"}],"ipa":"/ɪnˈtɜːn/"},{"pos":"n.","meaning":"实习生","definition":"a person gaining supervised practical work experience","examples":[{"en":"The museum hired two summer interns.","zh":"博物馆招了两名暑期实习生。"},{"en":"The intern assisted with data collection.","zh":"实习生协助收集数据。"}],"ipa":"/ˈɪntɜːn/"}],"internal":[{"pos":"adj.","meaning":"内部的；体内的","definition":"Located or occurring inside something.","examples":[{"en":"The device has an internal battery.","zh":"这个装置配有内置电池。"},{"en":"The doctor checked for internal injuries.","zh":"医生检查是否存在内伤。"}]},{"pos":"adj.","meaning":"国内的；组织内部的","definition":"Concerning affairs within a country or organisation.","examples":[{"en":"The committee discussed internal policy changes.","zh":"委员会讨论了内部政策调整。"},{"en":"The government faced pressure over its internal affairs.","zh":"政府因其国内事务面临压力。"}]}],"internationalist":[{"pos":"n.","meaning":"国际主义者","definition":"a person supporting cooperation among nations","examples":[{"en":"The internationalist argued for stronger global institutions.","zh":"这位国际主义者主张加强全球机构。"},{"en":"She was an internationalist committed to cultural exchange.","zh":"她是一位致力于文化交流的国际主义者。"}]},{"pos":"adj.","meaning":"国际主义的","definition":"supporting cooperation among nations","examples":[{"en":"The party adopted an internationalist outlook.","zh":"该党采取了国际主义视角。"},{"en":"His internationalist principles shaped the organisation.","zh":"他的国际主义原则塑造了这个组织。"}]}],"internist":[{"pos":"n.","meaning":"内科医生","definition":"a doctor specialising in internal medicine","examples":[{"en":"The patient was referred to an internist.","zh":"患者被转诊给内科医生。"},{"en":"The internist reviewed the test results.","zh":"内科医生查看了检查结果。"}]}],"internship":[{"pos":"n.","meaning":"实习；实习期；实习职位","definition":"A period or position of practical training in a workplace.","examples":[{"en":"She completed a summer internship at a design firm.","zh":"她在一家设计公司完成了暑期实习。"},{"en":"His medical internship gave him experience in several hospital departments.","zh":"他的医学实习让他在医院的多个科室积累了经验。"}]}],"interplay":[{"pos":"n.","meaning":"相互作用;相互影响","definition":"the way things affect one another","examples":[{"en":"The study examines the interplay of genes and environment.","zh":"研究考察基因与环境的相互作用。"},{"en":"Light and shadow create a delicate interplay.","zh":"光与影形成微妙的相互映衬。"}]},{"pos":"v.","meaning":"相互作用;相互影响","definition":"to act upon one another","examples":[{"en":"Economic and political forces interplay throughout the crisis.","zh":"经济与政治力量在危机中持续相互作用。"},{"en":"Colours interplay across the woven fabric.","zh":"色彩在编织布面上相互映衬。"}]}],"interpret":[{"pos":"v.","meaning":"解释；理解","definition":"to explain the meaning of something","examples":[{"en":"Experts may interpret the same evidence differently.","zh":"专家对相同证据可能有不同解释。"},{"en":"We should interpret these results with caution.","zh":"我们应该谨慎解读这些结果。"},{"en":"The teacher helped students interpret the graph.","zh":"老师帮助学生解读图表。"}]},{"pos":"v.","meaning":"口译；翻译","definition":"to translate spoken language","examples":[{"en":"She interpreted for the visiting delegation.","zh":"她为来访代表团做口译。"},{"en":"The guide interpreted the conversation into English.","zh":"导游把对话译成了英语。"}]}],"interpretation":[{"pos":"n.","meaning":"解释；理解；诠释","definition":"The meaning assigned to something.","examples":[{"en":"The poem is open to several interpretations.","zh":"这首诗可以有几种不同的理解。"},{"en":"Their interpretation of the data differs from ours.","zh":"他们对数据的解释与我们不同。"}]},{"pos":"n.","meaning":"口译；传译","definition":"The spoken translation of one language into another.","examples":[{"en":"Simultaneous interpretation was available during the conference.","zh":"会议期间提供同声传译。"},{"en":"Accurate interpretation helped both delegations negotiate.","zh":"准确的口译帮助两个代表团进行谈判。"}]},{"pos":"n.","meaning":"表演诠释；艺术处理","definition":"A performer's distinctive way of presenting a work.","examples":[{"en":"Her interpretation of the final movement was unusually gentle.","zh":"她对最后一个乐章的演绎格外柔和。"},{"en":"The actor offered a fresh interpretation of the familiar role.","zh":"演员对这个熟悉角色作出了全新诠释。"}]}],"interrelationship":[{"pos":"n.","meaning":"相互关系;相互影响","definition":"a connection in which things affect one another","examples":[{"en":"The diagram shows the interrelationship between the systems.","zh":"图表展示了系统间的相互关系。"},{"en":"Researchers explored the interrelationship of diet and sleep.","zh":"研究人员探索了饮食与睡眠的相互影响。"}]}],"interrupt":[{"pos":"v.","meaning":"打断；中断；打扰","definition":"to stop an activity or speech temporarily","examples":[{"en":"Please do not interrupt the speaker.","zh":"请不要打断发言者。"},{"en":"A power failure interrupted the broadcast.","zh":"停电中断了广播。"}]}],"intersection":[{"pos":"n.","meaning":"交叉路口；十字路口","definition":"A place where roads cross or meet.","examples":[{"en":"Turn left at the next intersection.","zh":"到下一个路口左转。"},{"en":"Traffic lights were installed at the dangerous intersection.","zh":"危险的交叉路口安装了交通信号灯。"}]}],"interval":[{"pos":"n.","meaning":"间隔;间距","definition":"a space or period between things","examples":[{"en":"Take measurements at regular intervals.","zh":"每隔固定时间测量一次。"},{"en":"Trees were planted at intervals of five metres.","zh":"树木每隔五米种植一棵。"}]},{"pos":"n.","meaning":"幕间休息;中场休息","definition":"a break between parts of a performance","examples":[{"en":"We bought drinks during the interval.","zh":"我们在幕间休息时买了饮料。"},{"en":"The play resumes after a short interval.","zh":"短暂幕间休息后戏剧继续。"}]}],"intervene":[{"pos":"v.","meaning":"干预；介入","definition":"to act in a situation to change its course","examples":[{"en":"The teacher intervened to stop the argument.","zh":"老师介入制止争吵。"},{"en":"The council intervened when talks broke down.","zh":"谈判破裂时议会进行了干预。"}]},{"pos":"v.","meaning":"介于其间；发生于其间","definition":"to occur or lie between two things","examples":[{"en":"Several years intervened before they met again.","zh":"多年之后他们才再次见面。"},{"en":"A wooded ridge intervenes between the two valleys.","zh":"一道林木茂密的山脊横在两个山谷之间。"}]}],"intervention":[{"pos":"n.","meaning":"干预；介入；干涉","definition":"Action taken to change a situation or influence events.","examples":[{"en":"Early intervention helped prevent the dispute from escalating.","zh":"及早介入帮助防止争端升级。"},{"en":"The study evaluated an intervention designed to improve reading skills.","zh":"研究评估了一项旨在提高阅读能力的干预措施。"}]}],"interview":[{"pos":"n.","meaning":"面试","definition":"a meeting to assess someone for a job","examples":[{"en":"My job interview is scheduled for Tuesday.","zh":"我的求职面试安排在周二。"},{"en":"Prepare a few questions before the interview.","zh":"面试前准备几个问题。"},{"en":"The interview lasted about forty minutes.","zh":"面试持续了大约四十分钟。"}]},{"pos":"n.","meaning":"采访;会见","definition":"a meeting to ask questions or exchange information","examples":[{"en":"The journalist requested an interview with the artist.","zh":"记者请求采访艺术家。"},{"en":"The ambassador secured an interview with the minister.","zh":"大使获准会见部长。"}]},{"pos":"v.","meaning":"面试","definition":"to question someone about suitability for a position","examples":[{"en":"The panel interviewed six applicants.","zh":"小组面试了六位申请者。"},{"en":"She interviewed for a teaching post.","zh":"她参加了教师岗位面试。"}]},{"pos":"v.","meaning":"采访;会见并询问","definition":"to question someone for information","examples":[{"en":"Researchers interviewed local residents.","zh":"研究人员访谈了当地居民。"},{"en":"The reporter interviewed the rescue team.","zh":"记者采访了救援队。"}]}],"intestine":[{"pos":"n.","meaning":"肠","definition":"the digestive tube between the stomach and anus","examples":[{"en":"The diagram shows the small intestine.","zh":"图中展示了小肠。"},{"en":"Nutrients are absorbed through the walls of the intestine.","zh":"营养物质通过肠壁吸收。"}]}],"intimate":[{"pos":"adj.","meaning":"亲密的；密切的","definition":"Having a close personal relationship or deep familiarity.","examples":[{"en":"They remained intimate friends for many years.","zh":"多年来，他们一直是亲密的朋友。"},{"en":"She has an intimate knowledge of the city's history.","zh":"她对这座城市的历史非常熟悉。"}],"ipa":"/ˈɪntɪmət/"},{"pos":"adj.","meaning":"私人的；隐私的；小范围而温馨的","definition":"Very personal or involving a small, private group.","examples":[{"en":"The diary contains intimate details of family life.","zh":"日记包含家庭生活中的私密细节。"},{"en":"We held an intimate dinner for a few close friends.","zh":"我们为几位密友举办了一场小型温馨晚宴。"}],"ipa":"/ˈɪntɪmət/"},{"pos":"n.","meaning":"密友；至交","definition":"A very close friend.","examples":[{"en":"Only his intimates knew about the planned move.","zh":"只有他的密友知道这次计划中的搬迁。"},{"en":"She invited a small circle of intimates to the celebration.","zh":"她邀请了一小圈密友参加庆祝活动。"}],"ipa":"/ˈɪntɪmət/"},{"pos":"v.","meaning":"暗示；透露；间接表示","definition":"To suggest or communicate something indirectly.","examples":[{"en":"She intimated that she might leave the company.","zh":"她暗示自己可能会离开公司。"},{"en":"The letter intimated a willingness to reopen negotiations.","zh":"信中透露出愿意重启谈判的意思。"}],"ipa":"/ˈɪntɪmeɪt/"}],"intrigue":[{"pos":"v.","meaning":"引起兴趣;使着迷","definition":"to arouse strong curiosity","examples":[{"en":"The unusual pattern intrigued the scientist.","zh":"不寻常的图案引起了科学家的兴趣。"},{"en":"Her mysterious background intrigued her colleagues.","zh":"她神秘的背景让同事们好奇。"}],"ipa":"/ɪnˈtriːɡ/"},{"pos":"v.","meaning":"密谋;施诡计","definition":"to make secret plans against others","examples":[{"en":"Rival courtiers intrigued against the young king.","zh":"敌对朝臣密谋反对年轻国王。"},{"en":"They intrigued to gain control of the company.","zh":"他们密谋夺取公司控制权。"}],"ipa":"/ɪnˈtriːɡ/"},{"pos":"n.","meaning":"阴谋;诡计;密谋","definition":"secret planning to gain an advantage","examples":[{"en":"The novel is full of political intrigue.","zh":"小说充满政治阴谋。"},{"en":"A court intrigue threatened the peace treaty.","zh":"一场宫廷阴谋威胁了和平条约。"}],"ipa":"/ˈɪntriːɡ/"}],"intrinsic":[{"pos":"adj.","meaning":"固有的；内在的；本质的","definition":"belonging naturally to something","examples":[{"en":"The material has intrinsic strength.","zh":"这种材料具有固有的强度。"},{"en":"She values learning for its intrinsic rewards.","zh":"她看重学习本身带来的回报。"}]}],"introduce":[{"pos":"v.","meaning":"介绍；引见","definition":"To make people known to one another or present a subject.","examples":[{"en":"Let me introduce you to our new colleague.","zh":"让我把你介绍给我们的新同事。"},{"en":"The first chapter introduces the central argument.","zh":"第一章介绍了核心论点。"}]},{"pos":"v.","meaning":"引进；传入","definition":"To bring something into a place or situation for the first time.","examples":[{"en":"The plant was introduced to the island by settlers.","zh":"这种植物由定居者引入岛上。"},{"en":"The school introduced new equipment into its science laboratories.","zh":"学校为科学实验室引进了新设备。"}]},{"pos":"v.","meaning":"推行；提出；开始采用","definition":"To put a new system, rule, or proposal into use or discussion.","examples":[{"en":"The city introduced a cheaper monthly bus pass.","zh":"这座城市推出了更便宜的公交月票。"},{"en":"The minister introduced a bill on water conservation.","zh":"部长提出了一项节约用水的法案。"}]}],"introduction":[{"pos":"n.","meaning":"介绍;初次认识","definition":"the act of presenting someone or something","examples":[{"en":"After a brief introduction, she began speaking.","zh":"简短介绍后，她开始发言。"},{"en":"The course provides an introduction to astronomy.","zh":"课程提供天文学入门知识。"}]},{"pos":"n.","meaning":"引入;采用;传入","definition":"the act of bringing something into use or a place","examples":[{"en":"The introduction of buses improved village transport.","zh":"公交车的引入改善了乡村交通。"},{"en":"The introduction of foreign species changed the habitat.","zh":"外来物种的引入改变了栖息地。"}]},{"pos":"n.","meaning":"导言;绪论","definition":"the opening section of a text","examples":[{"en":"The introduction explains the research question.","zh":"导言解释了研究问题。"},{"en":"Read the introduction before tackling the main chapters.","zh":"阅读正文前先读绪论。"}]}],"introspection":[{"pos":"n.","meaning":"内省；反省","definition":"careful examination of one's own thoughts and feelings","examples":[{"en":"The quiet journey gave her time for introspection.","zh":"安静的旅程给了她内省的时间。"},{"en":"His diary records a period of intense introspection.","zh":"日记记录了他深入反省的一段时期。"}]}],"introvert":[{"pos":"n.","meaning":"性格内向的人","definition":"A person who tends to focus on inner thoughts and prefers quieter social settings.","examples":[{"en":"As an introvert, she often needs time alone after a busy day.","zh":"作为一个内向的人，她在忙碌一天后往往需要独处。"},{"en":"The club welcomes introverts as well as outgoing members.","zh":"这个俱乐部既欢迎内向者，也欢迎外向的成员。"}]}],"intrusion":[{"pos":"n.","meaning":"闯入;侵扰;打搅","definition":"an unwelcome entry or interference","examples":[{"en":"The cameras felt like an intrusion into privacy.","zh":"摄像头让人感到隐私受到了侵犯。"},{"en":"The alarm detected an intrusion after midnight.","zh":"警报在午夜后检测到有人闯入。"}]}],"inundate":[{"pos":"v.","meaning":"淹没；泛滥","definition":"to cover land with water","examples":[{"en":"Floodwater inundated the fields.","zh":"洪水淹没了田野。"},{"en":"The storm inundated several coastal streets.","zh":"风暴淹没了几条沿海街道。"}]},{"pos":"v.","meaning":"使应接不暇；使不胜负荷","definition":"to overwhelm with large amounts","examples":[{"en":"The office was inundated with applications.","zh":"办公室收到大量申请，应接不暇。"},{"en":"Questions inundated the speaker after the lecture.","zh":"讲座后，大量问题涌向发言者。"}]}],"invade":[{"pos":"v.","meaning":"侵略；入侵；侵占","definition":"To enter a country or place by force or in large numbers.","examples":[{"en":"The army invaded the neighbouring territory.","zh":"军队入侵了邻近领土。"},{"en":"Ants invaded the kitchen during the hot weather.","zh":"炎热天气里，蚂蚁大量进入了厨房。"}]},{"pos":"v.","meaning":"侵犯；侵扰","definition":"To intrude upon something private or protected.","examples":[{"en":"Reporters were accused of invading the family's privacy.","zh":"记者们被指控侵犯这家人的隐私。"},{"en":"The constant noise invaded the peace of the village.","zh":"持续的噪音扰乱了村庄的宁静。"}]}],"invader":[{"pos":"n.","meaning":"入侵者","definition":"a person, army, or organism entering without welcome","examples":[{"en":"The castle walls held back the invaders.","zh":"城墙阻挡了入侵者。"},{"en":"The introduced plant became a destructive invader.","zh":"被引入的植物成了破坏性入侵物种。"}]}],"invalid":[{"pos":"adj.","meaning":"无效的；作废的","definition":"not officially or legally acceptable","examples":[{"en":"The expired ticket was invalid.","zh":"过期车票无效。"},{"en":"The missing signature made the agreement invalid.","zh":"缺少签名使协议无效。"}],"ipa":"/ɪnˈvælɪd/"},{"pos":"adj.","meaning":"无根据的；站不住脚的","definition":"not logically sound or supported","examples":[{"en":"The argument rests on an invalid assumption.","zh":"论证建立在一个站不住脚的假设上。"},{"en":"The calculation produced an invalid result.","zh":"计算得出了不正确的结果。"}],"ipa":"/ɪnˈvælɪd/"},{"pos":"adj.","meaning":"病弱的；需照护的（旧用，可能冒犯）","definition":"an outdated term for someone weakened by illness","examples":[{"en":"The old novel describes his invalid aunt.","zh":"这部旧小说描写了他体弱多病的姑母。"},{"en":"The historical record refers to an invalid soldier.","zh":"历史记录提到了一名伤病士兵。"}],"ipa":"/ˈɪnvəlɪd/"},{"pos":"n.","meaning":"病弱者（旧用，可能冒犯）","definition":"an outdated term for a person needing care due to illness","examples":[{"en":"The memoir says he was treated as an invalid.","zh":"回忆录说他被当作病弱者照料。"},{"en":"The old register listed residents described as invalids.","zh":"旧登记簿列出了被称为病弱者的居民。"}],"ipa":"/ˈɪnvəlɪd/"}],"invaluable":[{"pos":"adj.","meaning":"极宝贵的；非常有用的；无价的","definition":"Extremely useful or valuable.","examples":[{"en":"Her local knowledge proved invaluable during the search.","zh":"搜索过程中，她对当地的了解发挥了极重要的作用。"},{"en":"The internship gave him invaluable practical experience.","zh":"实习为他提供了极其宝贵的实践经验。"}]}],"invasion":[{"pos":"n.","meaning":"入侵;侵略;侵犯","definition":"an unwanted entry by force or in large numbers","examples":[{"en":"The invasion displaced thousands of families.","zh":"入侵使数千家庭流离失所。"},{"en":"Publishing those photographs was an invasion of privacy.","zh":"刊登那些照片侵犯了隐私。"}]}],"invasive":[{"pos":"adj.","meaning":"入侵的；侵扰的","definition":"spreading into an area or intruding unwantedly","examples":[{"en":"Invasive plants crowded out native species.","zh":"入侵植物挤占了本土物种的生存空间。"},{"en":"Residents opposed invasive monitoring of their activities.","zh":"居民反对侵扰其生活的活动监控。"}]},{"pos":"adj.","meaning":"侵袭性的；扩散的（医学）","definition":"spreading into surrounding body tissue","examples":[{"en":"The report distinguished invasive from localised disease.","zh":"报告区分了侵袭性疾病与局限性疾病。"},{"en":"Researchers studied the tumour's invasive behaviour.","zh":"研究人员研究了肿瘤的侵袭行为。"}]},{"pos":"adj.","meaning":"侵入性的；需要进入身体的（医疗操作）","definition":"involving entry into the body","examples":[{"en":"The study compared invasive and non-invasive tests.","zh":"研究比较了侵入性和非侵入性检查。"},{"en":"The surgeon described a less invasive procedure.","zh":"外科医生介绍了一种侵入程度较低的操作。"}]}],"invention":[{"pos":"n.","meaning":"发明；发明物","definition":"the creation of a new device or method, or the thing created","examples":[{"en":"The invention of the printing press changed the spread of information.","zh":"印刷机的发明改变了信息传播。"},{"en":"Her invention helps people open jars with one hand.","zh":"她的发明帮助人们用一只手打开罐子。"}]},{"pos":"n.","meaning":"虚构；编造","definition":"a story or claim that someone has made up","examples":[{"en":"The supposed witness was entirely the writer's invention.","zh":"那个所谓的目击者完全是作者虚构的。"},{"en":"Their excuse sounded like an invention designed to avoid blame.","zh":"他们的借口听起来像是为了逃避责备而编造的。"}]}],"inventive":[{"pos":"adj.","meaning":"有创造力的；善于发明的；创新的","definition":"Good at creating new ideas or solutions.","examples":[{"en":"The team found an inventive way to reuse waste heat.","zh":"团队找到了重复利用余热的创新方法。"},{"en":"She is an inventive teacher who designs her own learning games.","zh":"她是一位富有创造力的教师，会自己设计学习游戏。"}]}],"inventory":[{"pos":"n.","meaning":"物品清单;目录","definition":"a detailed list of goods or possessions","examples":[{"en":"The museum updated its inventory.","zh":"博物馆更新了藏品清单。"},{"en":"Make an inventory before moving house.","zh":"搬家前列一份物品清单。"}]},{"pos":"n.","meaning":"存货;库存","definition":"goods held ready for sale or use","examples":[{"en":"The shop reduced its winter inventory.","zh":"商店减少了冬季库存。"},{"en":"A shortage of components depleted the factory's inventory.","zh":"零件短缺耗尽了工厂库存。"}]}],"inversion":[{"pos":"n.","meaning":"倒置；颠倒","definition":"a reversal of normal order or position","examples":[{"en":"The poem uses an inversion of normal word order.","zh":"诗中使用了正常语序的倒置。"},{"en":"The picture is an inversion of the original image.","zh":"这幅图是原图的颠倒版本。"}]}],"invert":[{"pos":"v.","meaning":"倒置；颠倒；使倒转","definition":"To turn something upside down or reverse its order.","examples":[{"en":"Invert the bowl onto a plate to release the pudding.","zh":"把碗倒扣在盘子上，倒出布丁。"},{"en":"The author inverts the usual relationship between hero and villain.","zh":"作者颠倒了英雄与反派的通常关系。"}]}],"invest":[{"pos":"v.","meaning":"投资","definition":"to put money into something expecting a return","examples":[{"en":"The firm invested in new equipment.","zh":"公司投资购置了新设备。"},{"en":"She invested her savings in a small business.","zh":"她把积蓄投资在一家小企业中。"}]},{"pos":"v.","meaning":"投入时间或精力","definition":"to devote time or effort to a purpose","examples":[{"en":"He invested years in learning the craft.","zh":"他投入多年学习这门手艺。"},{"en":"We must invest more effort in training.","zh":"我们必须在培训上投入更多精力。"}]},{"pos":"v.","meaning":"赋予;授予","definition":"to give someone authority or a quality","examples":[{"en":"The law invests the committee with new powers.","zh":"法律赋予委员会新的权力。"},{"en":"Her performance invested the character with dignity.","zh":"她的表演赋予角色尊严。"}]}],"investigate":[{"pos":"v.","meaning":"调查；研究","definition":"to examine carefully to discover facts","examples":[{"en":"The team investigated the cause of the leak.","zh":"团队调查了泄漏原因。"},{"en":"Researchers are investigating a new material.","zh":"研究人员正在研究一种新材料。"}]}],"investment":[{"pos":"n.","meaning":"投资","definition":"money or effort put into something for a future benefit","examples":[{"en":"The region needs more investment in education.","zh":"该地区需要更多教育投资。"},{"en":"Public investment helped improve the rail network.","zh":"公共投资帮助改善了铁路网。"},{"en":"Training is an investment in future productivity.","zh":"培训是对未来生产率的投资。"}]}],"inviolable":[{"pos":"adj.","meaning":"不可侵犯的;不容破坏的","definition":"too important or protected to be violated","examples":[{"en":"The treaty declared the border inviolable.","zh":"条约宣布边境不可侵犯。"},{"en":"She regarded patient confidentiality as inviolable.","zh":"她认为患者保密原则不容侵犯。"}]}],"invisible":[{"pos":"adj.","meaning":"看不见的；无形的","definition":"unable to be seen","examples":[{"en":"The marks are invisible in ordinary light.","zh":"这些标记在普通光线下看不见。"},{"en":"Much of her work remained invisible to the public.","zh":"她的大量工作不为公众所见。"}]}],"invoice":[{"pos":"n.","meaning":"发票；付款清单","definition":"A document listing goods or services supplied and the amount owed.","examples":[{"en":"The supplier sent an invoice for the replacement parts.","zh":"供应商寄来了更换部件的付款清单。"},{"en":"Please attach the invoice to your expense claim.","zh":"请把发票附在报销申请上。"}]},{"pos":"v.","meaning":"给……开发票；开账单","definition":"To send a bill for goods or services.","examples":[{"en":"We will invoice you after the equipment arrives.","zh":"设备到货后，我们会向你开具账单。"},{"en":"The consultant invoices clients at the end of each month.","zh":"顾问在每个月月底向客户开账单。"}]}],"invoke":[{"pos":"v.","meaning":"援引;援用","definition":"to appeal to a rule or authority","examples":[{"en":"The lawyer invoked the right to silence.","zh":"律师援引了沉默权。"},{"en":"The president invoked emergency powers.","zh":"总统援用了紧急权力。"}]},{"pos":"v.","meaning":"祈求;恳求","definition":"to call on a power or person for help","examples":[{"en":"The sailors invoked divine protection.","zh":"水手们祈求神灵保护。"},{"en":"The poem invokes the aid of a muse.","zh":"诗歌祈求缪斯女神帮助。"}]},{"pos":"v.","meaning":"调用;使用","definition":"to activate a function or process","examples":[{"en":"The script invokes the backup routine.","zh":"脚本调用备份程序。"},{"en":"Clicking the icon invokes the search tool.","zh":"点击图标会调用搜索工具。"}]}],"involve":[{"pos":"v.","meaning":"使参与；使卷入；牵涉","definition":"to include someone in an activity or situation","examples":[{"en":"The project involves local residents.","zh":"项目让当地居民参与。"},{"en":"She did not want to involve her family in the dispute.","zh":"她不想把家人卷入争端。"}]},{"pos":"v.","meaning":"包含；需要","definition":"to include something as a necessary part","examples":[{"en":"The job involves frequent travel.","zh":"这份工作需要频繁出差。"},{"en":"Restoration involves careful cleaning and repair.","zh":"修复包括仔细清洁和维修。"}]}],"ion":[{"pos":"n.","meaning":"离子","definition":"An atom or group of atoms carrying an electric charge.","examples":[{"en":"Sodium ions carry a positive charge.","zh":"钠离子带正电荷。"},{"en":"The sensor measures the concentration of ions in the solution.","zh":"传感器测量溶液中的离子浓度。"}]}],"iris":[{"pos":"n.","meaning":"虹膜","definition":"the coloured ring surrounding the pupil","examples":[{"en":"The camera scanned her iris.","zh":"相机扫描了她的虹膜。"},{"en":"A brown iris surrounds the dark pupil.","zh":"棕色虹膜围绕着黑色瞳孔。"}]},{"pos":"n.","meaning":"虹;彩虹（诗歌或罕见用法）","definition":"a rainbow in poetic or rare usage","examples":[{"en":"A bright iris arched above the waterfall.","zh":"一道明亮彩虹弯跨瀑布上方。"},{"en":"The fading iris dissolved into the evening mist.","zh":"渐淡的彩虹消融在晚雾之中。"}]},{"pos":"n.","meaning":"鸢尾花;鸢尾属植物","definition":"a plant with showy flowers and long pointed leaves","examples":[{"en":"Purple irises bloom beside the pond.","zh":"紫色鸢尾花在池边绽放。"},{"en":"She planted an iris near the garden wall.","zh":"她在花园墙边种了一株鸢尾。"}]}],"iron":[{"pos":"n.","meaning":"铁","definition":"a strong metallic element","examples":[{"en":"The gate is made of iron.","zh":"大门由铁制成。"},{"en":"Iron reacts with moisture and oxygen to form rust.","zh":"铁与水分和氧气反应形成铁锈。"}]},{"pos":"n.","meaning":"熨斗；烙铁","definition":"a heated tool used for pressing or joining","examples":[{"en":"The iron removed the creases.","zh":"熨斗烫平了褶皱。"},{"en":"He placed the soldering iron on its stand.","zh":"他把电烙铁放在支架上。"}]},{"pos":"v.","meaning":"熨烫；烫平","definition":"to smooth clothes using heat and pressure","examples":[{"en":"She ironed her shirt before the interview.","zh":"她面试前熨了衬衫。"},{"en":"The curtains need ironing.","zh":"窗帘需要熨烫。"}]}],"irony":[{"pos":"n.","meaning":"反讽；反话；讽刺","definition":"The use of words that suggest the opposite of their literal meaning.","examples":[{"en":"His remark about the wonderful weather was full of irony as rain poured down.","zh":"倾盆大雨中，他那句称赞天气美妙的话充满反讽。"},{"en":"The poem uses irony to expose the ruler's vanity.","zh":"这首诗运用反讽揭露统治者的虚荣。"}]},{"pos":"n.","meaning":"出乎意料的反常情况；讽刺性巧合","definition":"A situation in which events turn out contrary to expectations.","examples":[{"en":"The irony was that the fire station itself needed fire repairs.","zh":"讽刺的是，消防站本身竟需要进行火灾后的修复。"},{"en":"She appreciated the irony of teaching punctuality after arriving late.","zh":"她迟到了却要教人守时，自己也明白这其中的讽刺意味。"}]}],"irrational":[{"pos":"adj.","meaning":"不合理的;不合逻辑的","definition":"not based on sound reasoning","examples":[{"en":"His fear of the harmless insect seemed irrational.","zh":"他对无害昆虫的恐惧似乎不合常理。"},{"en":"Anger led her to an irrational decision.","zh":"愤怒使她作出不理性的决定。"}]},{"pos":"n.","meaning":"无理数","definition":"a number that cannot be expressed as a ratio of integers","examples":[{"en":"The square root of two is an irrational.","zh":"二的平方根是一个无理数。"},{"en":"The exercise asks students to distinguish rationals from irrationals.","zh":"练习要求学生区分有理数和无理数。"}]}],"irregularity":[{"pos":"n.","meaning":"不规则；无规律","definition":"a lack of evenness or regular pattern","examples":[{"en":"The scan revealed an irregularity in the surface.","zh":"扫描发现表面一处不规则。"},{"en":"The irregularity of rainfall makes planning difficult.","zh":"降雨的不规律使规划困难。"}]}],"irrelevant":[{"pos":"adj.","meaning":"不相关的；离题的","definition":"Not connected with the matter being considered.","examples":[{"en":"His personal hobbies are irrelevant to his ability to do the job.","zh":"他的个人爱好与工作能力无关。"},{"en":"Remove any irrelevant details from the summary.","zh":"删除摘要中所有无关细节。"}]}],"irresistible":[{"pos":"adj.","meaning":"无法抗拒的;不可抑制的","definition":"too attractive or powerful to resist","examples":[{"en":"The warm bread smelled irresistible.","zh":"温热面包的香味令人无法抗拒。"},{"en":"She felt an irresistible urge to laugh.","zh":"她忍不住想笑。"}]}],"irrevocable":[{"pos":"adj.","meaning":"不可撤销的；不能改变的","definition":"impossible to reverse or cancel","examples":[{"en":"The decision was described as irrevocable.","zh":"这一决定被认为不可撤销。"},{"en":"They made an irrevocable commitment to the project.","zh":"他们对项目作出了不可撤销的承诺。"}]}],"irrigation":[{"pos":"n.","meaning":"灌溉","definition":"The supply of water to crops or land.","examples":[{"en":"The village built channels for irrigation.","zh":"村里修建了灌溉渠道。"},{"en":"Efficient irrigation helps farmers use less water.","zh":"高效灌溉帮助农民减少用水。"}]},{"pos":"n.","meaning":"冲洗","definition":"The washing of a body part or cavity with a flowing liquid.","examples":[{"en":"The nurse prepared sterile fluid for wound irrigation.","zh":"护士准备了无菌液用于冲洗伤口。"},{"en":"The training covered irrigation of the ear under appropriate supervision.","zh":"培训包括在适当监督下进行耳部冲洗。"}]}],"irritable":[{"pos":"adj.","meaning":"易怒的;急躁的","definition":"easily annoyed","examples":[{"en":"Lack of sleep made him irritable.","zh":"睡眠不足使他容易发怒。"},{"en":"The tired child became increasingly irritable.","zh":"疲倦的孩子越来越烦躁。"}]},{"pos":"adj.","meaning":"易受刺激的;过敏性的","definition":"reacting readily to stimulation","examples":[{"en":"The fabric irritated her already irritable skin.","zh":"布料刺激了她原本敏感的皮肤。"},{"en":"The study examined responses in irritable bowel tissue.","zh":"研究考察了易受刺激的肠组织反应。"}]}],"irritate":[{"pos":"v.","meaning":"使烦躁；惹恼","definition":"to annoy someone","examples":[{"en":"The repeated noise irritated the neighbours.","zh":"反复的噪声惹恼了邻居。"},{"en":"His habit of interrupting irritated her.","zh":"他爱打断人的习惯使她烦躁。"}]},{"pos":"v.","meaning":"刺激；使疼痛","definition":"to make a body part sore or uncomfortable","examples":[{"en":"Dust irritated her eyes.","zh":"灰尘刺激了她的眼睛。"},{"en":"The rough collar irritated his neck.","zh":"粗糙的衣领磨得他的脖子疼。"}]}],"irritation":[{"pos":"n.","meaning":"恼怒；烦躁","definition":"A feeling of annoyance.","examples":[{"en":"He tried to hide his irritation at the repeated interruptions.","zh":"他试图掩饰对一再被打断的恼怒。"},{"en":"The delay caused considerable irritation among passengers.","zh":"延误使乘客十分烦躁。"}]},{"pos":"n.","meaning":"刺激；发炎；不适","definition":"Physical soreness or discomfort caused by a stimulus.","examples":[{"en":"The soap caused irritation to her skin.","zh":"这种肥皂刺激了她的皮肤。"},{"en":"Dust can produce eye irritation.","zh":"灰尘可能引起眼部不适。"}]},{"pos":"n.","meaning":"恼人的事；烦心事","definition":"Something that repeatedly causes annoyance.","examples":[{"en":"The buzzing light became a constant irritation.","zh":"嗡嗡作响的灯成了一件持续烦人的事。"},{"en":"Long queues are one of the daily irritations of commuting.","zh":"排长队是通勤中每天让人烦心的事之一。"}]}],"isle":[{"pos":"n.","meaning":"岛;小岛","definition":"an island, often in names or literary use","examples":[{"en":"They sailed toward a distant isle.","zh":"他们驶向远处的小岛。"},{"en":"The little isle shelters nesting seabirds.","zh":"这座小岛庇护着筑巢的海鸟。"}]}],"isolate":[{"pos":"v.","meaning":"隔离；使孤立","definition":"to separate from other people or things","examples":[{"en":"Snow isolated the village for days.","zh":"大雪使村庄与外界隔绝了数日。"},{"en":"The researchers isolated a single variable.","zh":"研究人员单独分离出一个变量。"}]}],"isolated":[{"pos":"adj.","meaning":"隔离的；分离的；偏僻的","definition":"Separated from others or far from populated places.","examples":[{"en":"The hikers reached an isolated mountain village.","zh":"徒步者来到了一座偏僻山村。"},{"en":"The damaged section was isolated from the main network.","zh":"受损部分已与主网络隔离。"}]},{"pos":"adj.","meaning":"孤独的；孤立无援的","definition":"Feeling alone or lacking social support.","examples":[{"en":"She felt isolated after moving to a new city.","zh":"搬到一座新城市后，她感到孤独。"},{"en":"Regular visits help older residents feel less isolated.","zh":"经常探访有助于减轻老年居民的孤独感。"}]},{"pos":"adj.","meaning":"个别的；偶发的","definition":"Occurring separately and not as part of a wider pattern.","examples":[{"en":"Officials described the problem as an isolated incident.","zh":"官员称这个问题是个别事件。"},{"en":"Only a few isolated errors appeared in the report.","zh":"报告中只有几个零星错误。"}]}],"isolation":[{"pos":"n.","meaning":"孤立；隔离","definition":"the state of being separated from others","examples":[{"en":"Older people may experience social isolation.","zh":"老年人可能遭受社会孤立。"},{"en":"Community activities can reduce isolation.","zh":"社区活动可以减轻孤立感。"},{"en":"Geographical isolation makes the village difficult to reach.","zh":"地理隔绝使这个村庄难以到达。"}]}],"issue":[{"pos":"n.","meaning":"问题；争议点","definition":"a subject requiring discussion or attention","examples":[{"en":"Housing is a major local issue.","zh":"住房是当地的重大问题。"},{"en":"The meeting addressed several safety issues.","zh":"会议讨论了几个安全问题。"}]},{"pos":"n.","meaning":"一期；一号","definition":"one edition of a newspaper or magazine","examples":[{"en":"The latest issue contains an interview.","zh":"最新一期刊有一篇访谈。"},{"en":"She collects early issues of the magazine.","zh":"她收藏这本杂志的早期各期。"}]},{"pos":"n.","meaning":"发行；分发","definition":"the act of officially supplying or publishing something","examples":[{"en":"The issue of new permits begins Monday.","zh":"新许可证星期一开始发放。"},{"en":"The bank announced a new share issue.","zh":"银行宣布新股发行。"}]},{"pos":"n.","meaning":"流出；排出（正式用法）","definition":"the act of flowing or coming out","examples":[{"en":"The pipe allows the controlled issue of water.","zh":"管道使水能受控流出。"},{"en":"The engineer examined the issue of steam from the valve.","zh":"工程师检查了阀门蒸汽排出的情况。"}]},{"pos":"v.","meaning":"发布；发行；颁布；发给","definition":"to officially provide or publish something","examples":[{"en":"The agency issued a warning.","zh":"该机构发布了警告。"},{"en":"Each visitor was issued a pass.","zh":"每位访客都领到一张通行证。"}]},{"pos":"v.","meaning":"流出；涌出","definition":"to flow or come out","examples":[{"en":"Smoke issued from the chimney.","zh":"烟从烟囱里冒出。"},{"en":"Water issued from a crack in the rock.","zh":"水从岩石裂缝中流出。"}]}],"item":[{"pos":"n.","meaning":"物品；项目；条目","definition":"A single thing or entry in a list.","examples":[{"en":"Each item in the collection has a number.","zh":"收藏品中的每件物品都有编号。"},{"en":"The next item on the agenda is the budget.","zh":"议程的下一个项目是预算。"}]},{"pos":"n.","meaning":"一则消息；一条报道","definition":"A single piece of news.","examples":[{"en":"A short news item mentioned the discovery.","zh":"一则简短新闻提到了这一发现。"},{"en":"The final item in the bulletin concerned local transport.","zh":"新闻简报的最后一条报道涉及当地交通。"}]}],"itinerary":[{"pos":"n.","meaning":"行程表;旅行路线;旅行计划","definition":"a planned route or schedule for a journey","examples":[{"en":"Our itinerary includes three coastal towns.","zh":"我们的行程包括三个海滨城镇。"},{"en":"She emailed the itinerary to everyone.","zh":"她把行程表通过邮件发给所有人。"}]}],"jargon":[{"pos":"n.","meaning":"行话；专业术语","definition":"specialised language used by a particular group","examples":[{"en":"The guide avoids technical jargon.","zh":"指南避免使用专业术语。"},{"en":"Legal jargon confused the new employee.","zh":"法律行话让新员工感到困惑。"}]}],"jaw":[{"pos":"n.","meaning":"颌；颚","definition":"Either of the bones forming the mouth and holding the teeth.","examples":[{"en":"The dentist examined her lower jaw.","zh":"牙医检查了她的下颌。"},{"en":"The fossil's powerful jaws suggest that it ate tough food.","zh":"化石强壮的颌骨表明它以坚硬食物为食。"}]}],"jealous":[{"pos":"adj.","meaning":"嫉妒的;妒忌的","definition":"unhappy because another has something desired","examples":[{"en":"He was jealous of her success.","zh":"他嫉妒她的成功。"},{"en":"The siblings grew jealous of each other's gifts.","zh":"兄弟姐妹开始嫉妒彼此的礼物。"}]},{"pos":"adj.","meaning":"猜疑的;有嫉妒心的","definition":"afraid of losing someone's affection to another","examples":[{"en":"Her partner became jealous of an old friend.","zh":"她的伴侣对一位老朋友产生了醋意。"},{"en":"Jealous suspicion damaged their relationship.","zh":"猜疑和嫉妒损害了他们的关系。"}]}],"jeopardise":[{"pos":"v.","meaning":"危及；使陷入危险","definition":"to put something at risk","examples":[{"en":"The delay could jeopardise the whole project.","zh":"延误可能危及整个项目。"},{"en":"Careless handling jeopardised the fragile collection.","zh":"粗心搬运危及了这批易碎藏品。"}]}],"jerk":[{"pos":"v.","meaning":"猛拉；猛推；突然移动","definition":"To move or pull with a sudden sharp motion.","examples":[{"en":"The dog jerked the lead from his hand.","zh":"狗猛地把牵绳从他手中拽了出去。"},{"en":"She jerked her head back in surprise.","zh":"她惊讶地猛然向后仰头。"}]},{"pos":"n.","meaning":"突然的猛动；抽搐","definition":"A quick sharp movement.","examples":[{"en":"The train stopped with a sudden jerk.","zh":"火车猛然一震停了下来。"},{"en":"A small jerk of his hand knocked over the cup.","zh":"他的手突然一抖，碰倒了杯子。"}]}],"joint":[{"pos":"n.","meaning":"关节","definition":"a place where bones meet","examples":[{"en":"The knee joint bends when you walk.","zh":"走路时膝关节弯曲。"},{"en":"Arthritis affected the joints in her hands.","zh":"关节炎影响了她的手关节。"}]},{"pos":"n.","meaning":"接头;连接处","definition":"a place where two parts are connected","examples":[{"en":"Water leaked from the pipe joint.","zh":"水从管道接头漏出。"},{"en":"The carpenter strengthened each joint.","zh":"木匠加固了每个连接处。"}]},{"pos":"adj.","meaning":"联合的;共同的","definition":"shared or done by two or more parties","examples":[{"en":"They opened a joint bank account.","zh":"他们开了一个联名银行账户。"},{"en":"The universities launched a joint research project.","zh":"两所大学启动了联合研究项目。"}]}],"jostle":[{"pos":"v.","meaning":"推挤；挤着前行","definition":"to push against others in a crowd","examples":[{"en":"Passengers jostled for space on the platform.","zh":"乘客在站台上推挤着找位置。"},{"en":"She was jostled as the crowd moved forward.","zh":"人群向前移动时她被推搡了。"}]}],"journal":[{"pos":"n.","meaning":"期刊；杂志；日报","definition":"A regularly published collection of articles or news.","examples":[{"en":"The findings were published in a scientific journal.","zh":"研究结果发表在一份科学期刊上。"},{"en":"She reads the local journal every morning.","zh":"她每天早晨阅读当地报纸。"}]},{"pos":"n.","meaning":"日志；日记","definition":"A personal written record of events and thoughts.","examples":[{"en":"He kept a journal during his voyage.","zh":"他在航行期间写日志。"},{"en":"Her travel journal includes sketches of every town she visited.","zh":"她的旅行日记里有她到访过的每座城镇的速写。"}]}],"journalist":[{"pos":"n.","meaning":"新闻记者;新闻工作者","definition":"a person who reports news","examples":[{"en":"The journalist interviewed local residents.","zh":"记者采访了当地居民。"},{"en":"She worked as a journalist for a regional newspaper.","zh":"她曾在地方报纸担任记者。"}]}],"judgment":[{"pos":"n.","meaning":"判断；判断力","definition":"the ability or act of making considered decisions","examples":[{"en":"The role requires sound judgment.","zh":"这个岗位需要良好的判断力。"},{"en":"Experience improved her judgment.","zh":"经验提高了她的判断能力。"}]},{"pos":"n.","meaning":"意见；看法","definition":"an opinion reached after consideration","examples":[{"en":"In my judgment, the plan is workable.","zh":"依我看，这个计划可行。"},{"en":"Do not make a judgment before hearing the evidence.","zh":"听取证据前不要下结论。"}]},{"pos":"n.","meaning":"判决；裁决","definition":"a court's official decision","examples":[{"en":"The court delivered its judgment.","zh":"法院作出了判决。"},{"en":"They appealed against the judgment.","zh":"他们对判决提出了上诉。"}]}],"judicious":[{"pos":"adj.","meaning":"明智的；审慎的；有见识的","definition":"Showing careful and sensible judgement.","examples":[{"en":"Judicious use of colour made the small room feel spacious.","zh":"巧妙审慎地运用色彩，使小房间显得宽敞。"},{"en":"A judicious decision now could prevent greater problems later.","zh":"现在作出明智决定，可以防止以后出现更大问题。"}]}],"jumble":[{"pos":"n.","meaning":"杂乱的一堆;混杂","definition":"a disordered mixture","examples":[{"en":"The drawer contained a jumble of cables.","zh":"抽屉里有乱七八糟的一堆电线。"},{"en":"His notes were a jumble of unrelated ideas.","zh":"他的笔记是一堆不相干想法的混杂。"}]},{"pos":"n.","meaning":"供义卖的旧杂物","definition":"used goods collected for a charity sale","examples":[{"en":"We donated old clothes to the jumble sale.","zh":"我们把旧衣服捐给了旧物义卖。"},{"en":"Volunteers sorted the jumble before opening.","zh":"志愿者在开场前整理义卖旧物。"}]},{"pos":"v.","meaning":"混杂;使混乱","definition":"to mix things without order","examples":[{"en":"The move jumbled all our files.","zh":"搬迁把我们的文件全弄乱了。"},{"en":"Memories and dreams jumbled together in his mind.","zh":"记忆和梦在他脑海中混杂。"}]}],"junction":[{"pos":"n.","meaning":"连接处；交叉路口","definition":"a place where routes or things join","examples":[{"en":"Turn left at the next junction.","zh":"在下一个路口左转。"},{"en":"Check the junction between the two pipes.","zh":"检查两根管子的连接处。"}]}],"jungle":[{"pos":"n.","meaning":"丛林；热带密林","definition":"A dense forest in a tropical region.","examples":[{"en":"The expedition followed a narrow trail through the jungle.","zh":"探险队沿着狭窄小径穿过丛林。"},{"en":"Heavy rain echoed beneath the jungle canopy.","zh":"大雨声在丛林树冠下回荡。"}]}],"justice":[{"pos":"n.","meaning":"公正;正义","definition":"fairness in the treatment of people","examples":[{"en":"The campaign demanded justice for the victims.","zh":"运动要求为受害者伸张正义。"},{"en":"Her decision showed a strong sense of justice.","zh":"她的决定体现了强烈的公正感。"}]},{"pos":"n.","meaning":"司法;法律制裁","definition":"the administration of law","examples":[{"en":"The reform changed the criminal justice system.","zh":"改革改变了刑事司法制度。"},{"en":"The offenders were brought to justice.","zh":"违法者被绳之以法。"}]}],"justify":[{"pos":"v.","meaning":"证明有理；为…提供理由","definition":"to give good reasons for something","examples":[{"en":"The benefits may justify the additional cost.","zh":"这些好处可能足以证明额外费用合理。"},{"en":"You need evidence to justify this conclusion.","zh":"你需要证据来证明这个结论合理。"},{"en":"Convenience alone does not justify ignoring safety.","zh":"仅凭方便不足以成为忽视安全的理由。"}]}],"juvenile":[{"pos":"adj.","meaning":"青少年的；幼年的","definition":"Relating to young people or young animals.","examples":[{"en":"The programme supports juvenile offenders returning to school.","zh":"这个项目帮助未成年违法者重返学校。"},{"en":"Juvenile birds often have different markings from adults.","zh":"幼鸟的斑纹往往与成鸟不同。"}]},{"pos":"adj.","meaning":"幼稚的；不成熟的","definition":"Showing behaviour that is childish or immature.","examples":[{"en":"She found his juvenile jokes tiresome.","zh":"她觉得他那些幼稚的笑话很烦人。"},{"en":"Their argument descended into juvenile name-calling.","zh":"他们的争论演变成幼稚的辱骂。"}]},{"pos":"n.","meaning":"未成年人；幼体","definition":"A young person or animal that has not reached adulthood.","examples":[{"en":"The centre provides counselling for juveniles.","zh":"中心为未成年人提供心理咨询。"},{"en":"The researchers counted both adults and juveniles in the colony.","zh":"研究人员统计了群落中的成年个体和幼体。"}]}],"keen":[{"pos":"adj.","meaning":"热心的;渴望的;热衷的","definition":"eager or strongly interested","examples":[{"en":"She is keen to learn photography.","zh":"她渴望学习摄影。"},{"en":"He is a keen birdwatcher.","zh":"他是热心的观鸟爱好者。"}]},{"pos":"adj.","meaning":"敏锐的;灵敏的","definition":"quick to notice or understand","examples":[{"en":"The detective has a keen eye for detail.","zh":"侦探对细节有敏锐的观察力。"},{"en":"Dogs have a keen sense of smell.","zh":"狗有灵敏的嗅觉。"}]},{"pos":"adj.","meaning":"激烈的;强烈的","definition":"intense or strongly felt","examples":[{"en":"Competition for the prize was keen.","zh":"奖项竞争激烈。"},{"en":"She felt a keen sense of loss.","zh":"她感到强烈的失落。"}]},{"pos":"adj.","meaning":"锋利的","definition":"having a sharp cutting edge","examples":[{"en":"The blade retained a keen edge.","zh":"刀刃仍然锋利。"},{"en":"He cut the rope with a keen knife.","zh":"他用锋利的刀割断绳子。"}]}],"keystone":[{"pos":"n.","meaning":"拱顶石","definition":"the central stone holding an arch together","examples":[{"en":"The mason fitted the keystone into the arch.","zh":"石匠把拱顶石嵌入拱门。"},{"en":"A carved face decorated the keystone.","zh":"一张雕刻的人脸装饰着拱顶石。"}]},{"pos":"n.","meaning":"关键基础；核心","definition":"the essential part supporting a system","examples":[{"en":"Trust is the keystone of their partnership.","zh":"信任是他们合作关系的基础。"},{"en":"The bridge became the keystone of the transport plan.","zh":"这座桥成为交通规划的关键。"}]}],"kidney":[{"pos":"n.","meaning":"肾；肾脏","definition":"An organ that filters blood and produces urine.","examples":[{"en":"The diagram shows the position of each kidney.","zh":"图中显示了两侧肾脏的位置。"},{"en":"The specialist reviewed the results of her kidney tests.","zh":"专科医生查看了她的肾脏检查结果。"}]}],"kindergarten":[{"pos":"n.","meaning":"幼儿园","definition":"a school or class for young children","examples":[{"en":"Their daughter started kindergarten in September.","zh":"他们的女儿九月开始上幼儿园。"},{"en":"The kindergarten has a colourful play area.","zh":"幼儿园有色彩丰富的游戏区。"}]}],"kit":[{"pos":"n.","meaning":"成套工具；装备","definition":"a set of items used for a purpose","examples":[{"en":"Keep a repair kit in the car.","zh":"在车里备一套维修工具。"},{"en":"The students received a science kit.","zh":"学生们领到了一套科学实验工具。"}]},{"pos":"v.","meaning":"装备（常与 out 或 up 连用）","definition":"to supply with suitable equipment","examples":[{"en":"The centre kitted us out with helmets.","zh":"中心给我们配备了头盔。"},{"en":"The team was fully kitted for the expedition.","zh":"团队已为探险配齐装备。"}]}],"kneel":[{"pos":"v.","meaning":"跪下；跪着","definition":"To rest on one or both knees.","examples":[{"en":"She knelt beside the child to tie his shoe.","zh":"她跪在孩子身旁给他系鞋带。"},{"en":"The gardener knelt on a cushion while planting seedlings.","zh":"园丁跪在垫子上栽种幼苗。"}]}],"knob":[{"pos":"n.","meaning":"球形把手;旋钮","definition":"a rounded handle or control","examples":[{"en":"Turn the knob to lower the volume.","zh":"转动旋钮调低音量。"},{"en":"The brass door knob felt cold.","zh":"黄铜门把手摸起来很冷。"}]}],"kung fu":[{"pos":"n.","meaning":"功夫；中国武术","definition":"Chinese martial arts","examples":[{"en":"She practises kung fu twice a week.","zh":"她每周练两次功夫。"},{"en":"The demonstration introduced basic kung fu movements.","zh":"表演介绍了基本功夫动作。"}]}],"label":[{"pos":"v.","meaning":"贴标签；标明","definition":"To attach a written name or description to something.","examples":[{"en":"Please label each box with its destination.","zh":"请在每个箱子上贴标签，写明目的地。"},{"en":"The samples were labelled with the collection date.","zh":"样本标注了采集日期。"}]},{"pos":"n.","meaning":"标签；标记","definition":"A small piece of material giving information about an object.","examples":[{"en":"Read the care label before washing the coat.","zh":"洗外套前请阅读护理标签。"},{"en":"The label on the jar had faded.","zh":"罐子上的标签褪色了。"}]},{"pos":"n.","meaning":"称号；外号；归类名称","definition":"A description used to classify or characterise someone.","examples":[{"en":"She rejected the label of troublemaker.","zh":"她拒绝接受惹事者这个称号。"},{"en":"The broad label of modern art covers many different styles.","zh":"现代艺术这一大类名称涵盖许多不同风格。"}]}],"laboratory":[{"pos":"n.","meaning":"实验室;研究室","definition":"a room equipped for scientific work","examples":[{"en":"The samples arrived at the laboratory.","zh":"样本送到了实验室。"},{"en":"Students wear protective coats in the laboratory.","zh":"学生在实验室穿防护服。"}]}],"labour":[{"pos":"n.","meaning":"劳动；工作","definition":"physical or mental work","examples":[{"en":"The repairs required weeks of labour.","zh":"维修需要数周劳动。"},{"en":"Much of the farm work relies on manual labour.","zh":"许多农活依靠体力劳动。"}]},{"pos":"n.","meaning":"劳动力；工人","definition":"workers considered as a group or resource","examples":[{"en":"The region has a shortage of skilled labour.","zh":"该地区缺乏熟练劳动力。"},{"en":"The project hired local labour.","zh":"项目雇用了当地工人。"}]},{"pos":"v.","meaning":"劳动；努力","definition":"to work hard","examples":[{"en":"They laboured all day to clear the path.","zh":"他们辛苦工作了一整天清理小路。"},{"en":"She laboured over the final chapter.","zh":"她费力地写最后一章。"}]}],"lack":[{"pos":"n.","meaning":"缺乏；不足","definition":"The absence or shortage of something needed.","examples":[{"en":"A lack of sleep affected his concentration.","zh":"睡眠不足影响了他的注意力。"},{"en":"The project failed through lack of funding.","zh":"项目因缺少资金而失败。"}]},{"pos":"v.","meaning":"缺少；没有","definition":"To not have enough of something.","examples":[{"en":"The village lacks a reliable water supply.","zh":"村庄缺乏可靠的供水。"},{"en":"She has talent but lacks experience.","zh":"她有天赋，但缺少经验。"}]}],"lag":[{"pos":"v.","meaning":"落后;走得慢","definition":"to move or develop more slowly","examples":[{"en":"The youngest walker began to lag behind.","zh":"最年幼的步行者开始落在后面。"},{"en":"Wages lagged behind rising prices.","zh":"工资增长落后于物价上涨。"}]},{"pos":"n.","meaning":"滞后;时间间隔","definition":"a delay between connected events","examples":[{"en":"There is a lag between payment and delivery.","zh":"付款与交付之间有一段时间差。"},{"en":"The policy's effects appeared after a long lag.","zh":"政策的效果经过长时间滞后才显现。"}]}],"landfill":[{"pos":"n.","meaning":"垃圾填埋场；垃圾填埋","definition":"a place or method for disposing of waste in the ground","examples":[{"en":"The waste was taken to a landfill.","zh":"废物被运往垃圾填埋场。"},{"en":"Recycling reduces the amount sent to landfill.","zh":"回收减少了用于填埋的垃圾量。"}]}],"landlord":[{"pos":"n.","meaning":"房东","definition":"a person who rents a property to someone else","examples":[{"en":"Contact your landlord if the heating stops working.","zh":"如果暖气坏了，请联系房东。"},{"en":"Our landlord agreed to repair the leaking roof.","zh":"我们的房东同意修理漏水的屋顶。"},{"en":"The landlord inspected the flat before we moved in.","zh":"房东在我们入住前检查了公寓。"}]}],"landmark":[{"pos":"n.","meaning":"地标;路标","definition":"an easily recognized feature used for location","examples":[{"en":"The tower is the city's best-known landmark.","zh":"这座塔是城市最著名的地标。"},{"en":"We used the old oak as a landmark.","zh":"我们把老橡树作为认路标志。"}]},{"pos":"n.","meaning":"里程碑;重大事件","definition":"an important stage or achievement","examples":[{"en":"The agreement was a landmark in peace efforts.","zh":"协议是和平努力中的里程碑。"},{"en":"Graduation marked a personal landmark.","zh":"毕业标志着人生的重要节点。"}]}],"landscape":[{"pos":"n.","meaning":"风景；地貌","definition":"the visible features of an area of land","examples":[{"en":"The landscape changes from forest to grassland.","zh":"地貌从森林变为草原。"},{"en":"She painted the coastal landscape.","zh":"她画了海岸风景。"}]},{"pos":"v.","meaning":"进行景观美化","definition":"to improve the appearance of outdoor land","examples":[{"en":"They landscaped the grounds around the school.","zh":"他们美化了学校周围的场地。"},{"en":"The courtyard was landscaped with native shrubs.","zh":"庭院用本土灌木进行了景观设计。"}]}],"landward":[{"pos":"adj.","meaning":"向陆的；近陆的","definition":"Facing or nearer the land.","examples":[{"en":"The landward side of the fort was protected by a deep ditch.","zh":"堡垒靠陆地的一侧由一条深沟保护。"},{"en":"Plants grew on the landward slopes of the dunes.","zh":"沙丘朝陆地一侧的坡面生长着植物。"}]},{"pos":"adv.","meaning":"向陆地；朝岸上","definition":"Towards the land.","examples":[{"en":"The boat turned landward as the weather worsened.","zh":"天气恶化时，船转向岸边。"},{"en":"The wind carried the mist landward.","zh":"风把雾吹向陆地。"}]}],"lane":[{"pos":"n.","meaning":"小巷;小路","definition":"a narrow road","examples":[{"en":"A quiet lane leads to the farm.","zh":"一条安静小路通向农场。"},{"en":"They walked down a cobbled lane.","zh":"他们沿鹅卵石小巷走去。"}]},{"pos":"n.","meaning":"车道;跑道;泳道","definition":"a marked strip for a stream of traffic or competitor","examples":[{"en":"Stay in the left lane.","zh":"保持在左侧车道。"},{"en":"The swimmer won from lane four.","zh":"游泳选手从第四泳道出发并夺冠。"}]}],"large-scale":[{"pos":"adj.","meaning":"大规模的；大范围的","definition":"involving a great extent or number","examples":[{"en":"The region needs large-scale investment.","zh":"这个地区需要大规模投资。"},{"en":"A large-scale survey covered every district.","zh":"一项大范围调查覆盖了每个地区。"}]}],"larva":[{"pos":"n.","meaning":"幼虫；幼体","definition":"An early immature stage of an animal that changes form as it develops.","examples":[{"en":"The larva feeds on leaves before becoming a butterfly.","zh":"幼虫在变成蝴蝶前以叶片为食。"},{"en":"Mosquito larvae moved just below the water's surface.","zh":"蚊子幼虫在水面下活动。"}]}],"laser":[{"pos":"n.","meaning":"激光;激光器","definition":"a device producing a narrow intense beam of light or its beam","examples":[{"en":"The laser cut a precise shape in metal.","zh":"激光在金属上切出精确形状。"},{"en":"The scanner uses a small laser.","zh":"扫描仪使用小型激光器。"}]}],"latent":[{"pos":"adj.","meaning":"潜在的；潜伏的","definition":"present but not yet active or obvious","examples":[{"en":"The course revealed her latent talent.","zh":"课程显露了她潜在的才能。"},{"en":"The fault remained latent for years.","zh":"故障潜伏了多年。"}]}],"lateral":[{"pos":"adj.","meaning":"侧面的；横向的","definition":"At, towards, or from the side.","examples":[{"en":"The diagram shows a lateral view of the skull.","zh":"图中展示了头骨的侧面。"},{"en":"The structure allows a small amount of lateral movement.","zh":"这个结构允许少量横向移动。"}]}],"laterality":[{"pos":"n.","meaning":"侧偏性;偏侧优势","definition":"preference or dominance of one side of the body","examples":[{"en":"The study measured laterality in hand use.","zh":"研究测量了用手的偏侧性。"},{"en":"Laterality can differ between hand and eye preference.","zh":"手与眼的偏侧优势可能不同。"}]}],"latitude":[{"pos":"n.","meaning":"纬度","definition":"distance north or south of the equator in degrees","examples":[{"en":"The island lies at a latitude of ten degrees north.","zh":"该岛位于北纬十度。"},{"en":"The navigator calculated their latitude.","zh":"领航员计算了他们的纬度。"}]},{"pos":"n.","meaning":"纬度地区（常用复数）","definition":"regions defined by distance from the equator","examples":[{"en":"Winter days are short at high latitudes.","zh":"高纬度地区冬季白昼短。"},{"en":"The species is common in tropical latitudes.","zh":"这个物种常见于热带纬度地区。"}]},{"pos":"n.","meaning":"自由；自主余地","definition":"freedom to act or choose","examples":[{"en":"Teachers have latitude in choosing materials.","zh":"教师有选择材料的自由。"},{"en":"The rules allow little latitude for exceptions.","zh":"规则几乎不容许例外。"}]}],"launch":[{"pos":"v.","meaning":"推出；投放市场","definition":"To make a new product or service available.","examples":[{"en":"The company will launch a cheaper model next month.","zh":"公司下个月将推出一款更便宜的型号。"},{"en":"The museum launched a new online ticket service.","zh":"博物馆推出了新的网上售票服务。"}]},{"pos":"v.","meaning":"发起；开展","definition":"To begin an organised activity or effort.","examples":[{"en":"Residents launched a campaign to save the park.","zh":"居民发起了拯救公园的运动。"},{"en":"The police launched an investigation into the missing funds.","zh":"警方对失踪资金展开了调查。"}]},{"pos":"v.","meaning":"发射；使下水","definition":"To send a vehicle into space or set a boat onto water.","examples":[{"en":"Engineers launched the satellite before dawn.","zh":"工程师在黎明前发射了卫星。"},{"en":"We launched the canoe from a shallow beach.","zh":"我们从浅滩把独木舟放入水中。"}]},{"pos":"n.","meaning":"发射；下水","definition":"The act of sending a spacecraft up or putting a boat in water.","examples":[{"en":"Strong winds delayed the rocket launch.","zh":"强风推迟了火箭发射。"},{"en":"The ship's launch attracted a large crowd.","zh":"船舶下水吸引了很多人。"}]},{"pos":"n.","meaning":"推出；上市；启动","definition":"The introduction of a new product, service, or campaign.","examples":[{"en":"The product launch received wide media coverage.","zh":"产品发布获得了广泛的媒体报道。"},{"en":"They held a small event to mark the launch of the charity.","zh":"他们举行了一场小型活动，庆祝慈善机构成立。"}]}],"laundry":[{"pos":"n.","meaning":"待洗或洗好的衣物","definition":"clothes and other textiles to be washed or recently washed","examples":[{"en":"A basket of laundry stood by the door.","zh":"门旁放着一篮待洗衣物。"},{"en":"She hung the laundry outside.","zh":"她把洗好的衣物晾在外面。"}]},{"pos":"n.","meaning":"洗衣房;洗衣店","definition":"a place where clothes are washed","examples":[{"en":"The hotel has a small laundry.","zh":"酒店有小洗衣房。"},{"en":"He took his shirts to the laundry.","zh":"他把衬衣送去洗衣店。"}]}],"lava":[{"pos":"n.","meaning":"熔岩（喷出地表的岩浆）","definition":"molten rock that has reached Earth's surface","examples":[{"en":"Lava flowed down the volcano's slope.","zh":"熔岩沿火山坡流下。"},{"en":"The cooled lava formed dark rock.","zh":"冷却的熔岩形成了深色岩石。"}]}],"lavatory":[{"pos":"n.","meaning":"厕所；盥洗室","definition":"A toilet or a room containing one.","examples":[{"en":"The lavatory is at the end of the corridor.","zh":"厕所在走廊尽头。"},{"en":"Passengers were asked to keep the lavatory clean.","zh":"乘客被要求保持厕所清洁。"}]}],"lawsuit":[{"pos":"n.","meaning":"诉讼;官司","definition":"a legal case brought before a court","examples":[{"en":"The neighbours filed a lawsuit over the boundary.","zh":"邻居因地界争议提起诉讼。"},{"en":"The company settled the lawsuit.","zh":"公司就诉讼达成了和解。"}]}],"lax":[{"pos":"adj.","meaning":"松懈的；不严格的；马虎的","definition":"not sufficiently careful or strict","examples":[{"en":"Lax security allowed the theft.","zh":"安保松懈使盗窃得逞。"},{"en":"The review criticised lax accounting practices.","zh":"审查批评了不严谨的会计做法。"}]}],"layer":[{"pos":"n.","meaning":"层；层次","definition":"A thickness or level of material covering a surface or forming part of a whole.","examples":[{"en":"A thin layer of ice covered the pond.","zh":"一层薄冰覆盖着池塘。"},{"en":"The archaeologists uncovered several layers of settlement.","zh":"考古学家发掘出了几个不同时期的聚落层。"}]}],"layout":[{"pos":"n.","meaning":"布局;排列;设计","definition":"the arrangement of parts in a space","examples":[{"en":"The kitchen layout makes cooking easier.","zh":"厨房布局使做饭更方便。"},{"en":"She revised the magazine's page layout.","zh":"她修改了杂志页面布局。"}]}],"lead":[{"pos":"v.","meaning":"带领；指引","definition":"to guide someone along a route","examples":[{"en":"The path leads to the lake.","zh":"小路通向湖泊。"},{"en":"She led the visitors through the gallery.","zh":"她带领游客穿过展厅。"}],"ipa":"/liːd/"},{"pos":"v.","meaning":"领导；率领","definition":"to be in charge of a group or activity","examples":[{"en":"He leads a team of engineers.","zh":"他领导一个工程师团队。"},{"en":"She was chosen to lead the investigation.","zh":"她被选中负责这项调查。"}],"ipa":"/liːd/"},{"pos":"v.","meaning":"导致；致使","definition":"to cause a result","examples":[{"en":"Heavy rain can lead to flooding.","zh":"大雨可能导致洪水。"},{"en":"The discovery led them to revise the theory.","zh":"这一发现使他们修正了理论。"}],"ipa":"/liːd/"},{"pos":"n.","meaning":"铅","definition":"a heavy soft metal","examples":[{"en":"The old pipe contained lead.","zh":"旧管道含铅。"},{"en":"The laboratory tested the paint for lead.","zh":"实验室检测了油漆是否含铅。"}],"ipa":"/led/"}],"lead to":[{"pos":"v.","meaning":"导致；引起","definition":"To cause a result.","examples":[{"en":"Poor drainage can lead to flooding.","zh":"排水不良可能导致洪水。"},{"en":"The discovery led to a new line of research.","zh":"这个发现引出了一个新的研究方向。"}]},{"pos":"v.","meaning":"通向；通往","definition":"To provide a route to a place.","examples":[{"en":"This path leads to the beach.","zh":"这条小路通向海滩。"},{"en":"The stairs lead to a roof terrace.","zh":"楼梯通往屋顶露台。"}]}],"leadership":[{"pos":"n.","meaning":"领导;领导能力","definition":"the ability or act of guiding others","examples":[{"en":"The crisis required strong leadership.","zh":"危机需要有力的领导。"},{"en":"Volunteering helped develop her leadership skills.","zh":"志愿工作帮助培养了她的领导能力。"}]},{"pos":"n.","meaning":"领导层","definition":"the people controlling an organization","examples":[{"en":"The party leadership approved the proposal.","zh":"党的领导层批准了提议。"},{"en":"Workers requested a meeting with the leadership.","zh":"工人要求与领导层会面。"}]}],"leaflet":[{"pos":"n.","meaning":"传单；小册子","definition":"a small printed sheet giving information","examples":[{"en":"The leaflet explains the museum's opening hours.","zh":"传单介绍了博物馆的开放时间。"},{"en":"She picked up a travel leaflet.","zh":"她拿起了一本旅行小册子。"}]},{"pos":"v.","meaning":"散发传单","definition":"to distribute printed information sheets","examples":[{"en":"Volunteers leafleted the neighbourhood.","zh":"志愿者在社区散发传单。"},{"en":"Campaigners leafleted outside the station.","zh":"活动人士在车站外发传单。"}]}],"leak":[{"pos":"n.","meaning":"漏孔；裂隙","definition":"A hole or fault through which liquid or gas escapes.","examples":[{"en":"A plumber repaired the leak beneath the sink.","zh":"水管工修好了洗手池下的漏水处。"},{"en":"The roof has a small leak near the chimney.","zh":"屋顶靠近烟囱处有一个小漏孔。"}]},{"pos":"n.","meaning":"泄漏；泄密","definition":"An unintended escape of a substance or confidential information.","examples":[{"en":"A gas leak forced the building to be evacuated.","zh":"煤气泄漏迫使大楼人员撤离。"},{"en":"The company investigated a leak of customer records.","zh":"公司调查了客户记录泄露事件。"}]},{"pos":"v.","meaning":"漏出；渗漏","definition":"To escape or allow a substance to escape through a hole.","examples":[{"en":"Water leaked through the ceiling.","zh":"水从天花板渗了下来。"},{"en":"The damaged container was leaking oil.","zh":"受损容器正在漏油。"}]},{"pos":"v.","meaning":"泄露；泄密","definition":"To reveal secret information without permission.","examples":[{"en":"Someone leaked the confidential report to the press.","zh":"有人向媒体泄露了机密报告。"},{"en":"Details of the agreement leaked before the announcement.","zh":"协议细节在宣布前就泄露了。"}]}],"leap":[{"pos":"v.","meaning":"跳跃;猛冲","definition":"to jump or move suddenly","examples":[{"en":"The deer leaped over the fence.","zh":"鹿跃过了篱笆。"},{"en":"She leaped to her feet.","zh":"她猛地站了起来。"}]},{"pos":"n.","meaning":"跳跃","definition":"a sudden jump","examples":[{"en":"One leap carried him across the stream.","zh":"他一跃跨过小溪。"},{"en":"The dancer finished with a graceful leap.","zh":"舞者以优美的一跃结束表演。"}]},{"pos":"n.","meaning":"激增;飞跃","definition":"a sudden large increase or advance","examples":[{"en":"The discovery represented a leap in understanding.","zh":"这项发现代表认识上的飞跃。"},{"en":"The company reported a leap in profits.","zh":"公司报告利润大增。"}]}],"lease":[{"pos":"n.","meaning":"租约","definition":"an agreement to rent property for a period of time","examples":[{"en":"Read the lease carefully before signing it.","zh":"签字前请仔细阅读租约。"},{"en":"Our lease ends in September.","zh":"我们的租约九月到期。"},{"en":"The lease does not allow pets in the flat.","zh":"租约不允许在公寓里养宠物。"}]},{"pos":"v.","meaning":"租用；承租","definition":"to obtain the use of property under a rental contract","examples":[{"en":"The company leases its office space.","zh":"公司租用办公空间。"},{"en":"We leased a van for six months.","zh":"我们租了一辆货车，租期六个月。"}]},{"pos":"v.","meaning":"出租","definition":"to allow someone to use property under a rental contract","examples":[{"en":"They leased the field to a local farmer.","zh":"他们把田地租给了一位当地农民。"},{"en":"The owner leases the upstairs rooms to students.","zh":"房主把楼上的房间出租给学生。"}]}],"leather":[{"pos":"n.","meaning":"皮革；皮革制品","definition":"Animal skin prepared for making clothing and other goods.","examples":[{"en":"The bag is made of soft leather.","zh":"这个包是用柔软皮革制成的。"},{"en":"She cleaned her leather shoes before the interview.","zh":"面试前她擦了皮鞋。"}]}],"lecture":[{"pos":"n.","meaning":"讲座;授课;演讲","definition":"a formal educational talk","examples":[{"en":"The lecture focused on urban history.","zh":"讲座聚焦城市历史。"},{"en":"Students took notes during the lecture.","zh":"学生们在上课时记笔记。"}]}],"legacy":[{"pos":"n.","meaning":"遗赠；遗产","definition":"money or property left after someone's death","examples":[{"en":"She received a small legacy from her aunt.","zh":"她继承了姑母的一小笔遗产。"},{"en":"The legacy helped fund a scholarship.","zh":"这笔遗赠帮助设立了一项奖学金。"}]},{"pos":"n.","meaning":"遗留影响；传承","definition":"something lasting that comes from the past","examples":[{"en":"The railway is a legacy of industrial expansion.","zh":"铁路是工业扩张留下的遗产。"},{"en":"Her teaching left a lasting legacy.","zh":"她的教学留下了长久影响。"}]}],"legal":[{"pos":"adj.","meaning":"法律的","definition":"Relating to the law.","examples":[{"en":"She sought legal advice before signing the agreement.","zh":"她在签协议前寻求了法律建议。"},{"en":"The dispute raised several legal questions.","zh":"这场纠纷引出了几个法律问题。"}]},{"pos":"adj.","meaning":"合法的；法律允许的","definition":"Allowed by law.","examples":[{"en":"The shop needs a permit to make the operation legal.","zh":"商店需要许可证才能合法经营。"},{"en":"He checked whether the proposed changes were legal.","zh":"他核查了拟议改动是否合法。"}]}],"legislation":[{"pos":"n.","meaning":"法律；法规","definition":"laws considered collectively","examples":[{"en":"New legislation protects consumers from unfair charges.","zh":"新法律保护消费者免受不合理收费。"},{"en":"The government introduced legislation to improve air quality.","zh":"政府出台法律改善空气质量。"},{"en":"Effective legislation must be properly enforced.","zh":"有效的法律必须得到切实执行。"}]},{"pos":"n.","meaning":"立法","definition":"the process of making laws","examples":[{"en":"The debate concerned the proper procedure for legislation.","zh":"辩论涉及适当的立法程序。"},{"en":"Public consultation can improve the process of legislation.","zh":"公众咨询可以改善立法过程。"}]}],"legislative":[{"pos":"adj.","meaning":"立法的；立法机关的；有立法权的","definition":"relating to making laws or a lawmaking body","examples":[{"en":"The proposal needs legislative approval.","zh":"提案需要立法机关批准。"},{"en":"The assembly has legislative powers.","zh":"议会拥有立法权。"}]},{"pos":"adj.","meaning":"通过立法制定或执行的","definition":"created or enforced through legislation","examples":[{"en":"The report called for a legislative remedy.","zh":"报告呼吁通过立法解决问题。"},{"en":"They sought legislative protection for the site.","zh":"他们寻求对该地点提供立法保护。"}]},{"pos":"n.","meaning":"立法机关（罕见用法，通常用 legislature）","definition":"a lawmaking body","examples":[{"en":"The old text separates the executive from the legislative.","zh":"旧文献将行政机关与立法机关区分开来。"},{"en":"The charter defined the powers of the legislative.","zh":"宪章规定了立法机关的权力。"}]}],"legitimacy":[{"pos":"n.","meaning":"合法性；正当性；正统性","definition":"The quality of being lawful, justified, or accepted as valid.","examples":[{"en":"The court examined the legitimacy of the claim.","zh":"法院审查了该诉求的合法性。"},{"en":"Public trust is important to the legitimacy of an institution.","zh":"公众信任对机构的正当性很重要。"}]}],"legitimate":[{"pos":"adj.","meaning":"合法的;正当的;合理的","definition":"allowed by law or reasonable","examples":[{"en":"The company operates a legitimate business.","zh":"公司经营合法业务。"},{"en":"Residents raised legitimate concerns about noise.","zh":"居民对噪声提出了合理担忧。"}],"ipa":"/lɪˈdʒɪtɪmət/"},{"pos":"v.","meaning":"使合法;使正当化","definition":"to give legal or accepted status to something","examples":[{"en":"The ruling legitimated the new arrangement.","zh":"裁决使新安排合法化。"},{"en":"The charter legitimated the council's authority.","zh":"宪章确认了议会权力的合法性。"}],"ipa":"/lɪˈdʒɪtɪmeɪt/"}],"legitimize":[{"pos":"v.","meaning":"使合法；赋予正当性","definition":"to make something legally or socially acceptable","examples":[{"en":"The agreement helped legitimize the new organisation.","zh":"协议帮助新组织获得合法地位。"},{"en":"The vote was intended to legitimize the decision.","zh":"投票旨在赋予决定正当性。"}]}],"leisure":[{"pos":"n.","meaning":"闲暇；空闲时间；悠闲","definition":"Time free from work or other duties.","examples":[{"en":"She spends her leisure reading history books.","zh":"她利用闲暇阅读历史书。"},{"en":"We finally had the leisure to explore the town.","zh":"我们终于有空悠闲地游览这座小镇。"}]}],"lenient":[{"pos":"adj.","meaning":"宽容的;宽大的","definition":"less strict or severe than expected","examples":[{"en":"The judge imposed a lenient sentence.","zh":"法官判处了较轻的刑罚。"},{"en":"Her parents were lenient about bedtime.","zh":"她的父母对就寝时间要求宽松。"}]}],"lens":[{"pos":"n.","meaning":"透镜；镜片；镜头","definition":"a curved transparent object that focuses light","examples":[{"en":"The lens magnified the tiny letters.","zh":"透镜放大了微小的字。"},{"en":"She cleaned the camera lens carefully.","zh":"她仔细清洁了相机镜头。"}]}],"leopard":[{"pos":"n.","meaning":"豹；花豹","definition":"A large spotted wild cat native to parts of Africa and Asia.","examples":[{"en":"A leopard rested on a branch above the trail.","zh":"一只豹在小路上方的树枝上休息。"},{"en":"The leopard's spotted coat helped it blend into the woodland.","zh":"豹身上的斑点帮助它融入林地环境。"}]}],"lethal":[{"pos":"adj.","meaning":"致命的;毁灭性的;极有害的","definition":"capable of causing death or serious destruction","examples":[{"en":"The gas can be lethal in enclosed spaces.","zh":"这种气体在密闭空间内可能致命。"},{"en":"The drought dealt a lethal blow to the crop.","zh":"干旱给作物造成毁灭性打击。"}]}],"leukaemia":[{"pos":"n.","meaning":"白血病","definition":"a cancer affecting blood-forming tissues","examples":[{"en":"The laboratory studies leukaemia cells.","zh":"实验室研究白血病细胞。"},{"en":"The charity funds leukaemia research.","zh":"慈善机构资助白血病研究。"}]}],"level":[{"pos":"n.","meaning":"水平；高度；含量","definition":"A particular position, amount, or degree on a scale.","examples":[{"en":"The water level rose overnight.","zh":"水位在夜间升高了。"},{"en":"The test measures the level of sugar in the sample.","zh":"这项检测测量样本中的糖含量。"}]},{"pos":"n.","meaning":"等级；层次；水平","definition":"A stage or standard of achievement or organisation.","examples":[{"en":"The course is offered at three levels.","zh":"这门课程分为三个级别。"},{"en":"Decisions are made at the local level.","zh":"决策在地方层面作出。"}]},{"pos":"adj.","meaning":"平坦的；水平的；同高的","definition":"Flat, horizontal, or at the same height.","examples":[{"en":"Make sure the shelf is level before tightening the screws.","zh":"拧紧螺丝前，确保搁板是水平的。"},{"en":"The two platforms are level with each other.","zh":"两个平台处于同一高度。"}]},{"pos":"adj.","meaning":"同等的；持平的","definition":"Equal in amount, score, or degree.","examples":[{"en":"The teams were level at half-time.","zh":"中场休息时，两队比分持平。"},{"en":"Her score was level with the previous record.","zh":"她的成绩与此前纪录持平。"}]},{"pos":"adj.","meaning":"平稳的；冷静的","definition":"Steady and controlled in manner or sound.","examples":[{"en":"She answered in a level voice.","zh":"她用平稳的语气回答。"},{"en":"He kept a level head throughout the crisis.","zh":"危机期间他始终保持冷静。"}]},{"pos":"v.","meaning":"使平坦；夷平","definition":"To make a surface flat or bring something down to ground level.","examples":[{"en":"Workers levelled the ground before laying the tiles.","zh":"工人在铺瓷砖前把地面整平。"},{"en":"The old warehouse was levelled to make room for a park.","zh":"旧仓库被夷平，以腾出地方建公园。"}]}],"lever":[{"pos":"n.","meaning":"杠杆;操作杆","definition":"a bar used to move something or operate a mechanism","examples":[{"en":"Pull the lever to release the brake.","zh":"拉动操作杆松开刹车。"},{"en":"A long lever helped lift the stone.","zh":"长杠杆帮助撬起石头。"}]},{"pos":"n.","meaning":"施压手段;影响途径","definition":"a means of influencing an outcome","examples":[{"en":"Trade can be a lever for cooperation.","zh":"贸易可以成为推动合作的手段。"},{"en":"The council used funding as a lever for reform.","zh":"议会用资金作为推动改革的手段。"}]},{"pos":"v.","meaning":"撬动","definition":"to move something with a lever","examples":[{"en":"They levered the lid off the crate.","zh":"他们撬开了木箱盖。"},{"en":"He used a bar to lever the rock aside.","zh":"他用铁杆把石头撬到一旁。"}]}],"lexicographer":[{"pos":"n.","meaning":"词典编纂者","definition":"a person who writes or edits dictionaries","examples":[{"en":"The lexicographer compared historical uses of the word.","zh":"词典编纂者比较了这个词的历史用法。"},{"en":"Lexicographers revised several definitions.","zh":"词典编纂者修订了几条释义。"}]}],"liaise":[{"pos":"v.","meaning":"联络；联系；协调","definition":"To exchange information so that people can work together.","examples":[{"en":"She will liaise with the school about transport arrangements.","zh":"她会与学校联系，协调交通安排。"},{"en":"Our engineers liaise closely with the design team.","zh":"我们的工程师与设计团队保持密切联系。"}]}],"libel":[{"pos":"n.","meaning":"书面诽谤;诽谤文字","definition":"a published false statement damaging someone's reputation","examples":[{"en":"The article was the subject of a libel case.","zh":"那篇文章引发了一起诽谤诉讼。"},{"en":"She denied writing the alleged libel.","zh":"她否认撰写了被指为诽谤的文字。"}]},{"pos":"v.","meaning":"书面诽谤;中伤","definition":"to publish a false statement damaging someone's reputation","examples":[{"en":"The newspaper was accused of libelling the teacher.","zh":"报纸被指控诽谤教师。"},{"en":"He claimed that the pamphlet libelled his family.","zh":"他声称小册子中伤了他的家人。"}]}],"liberty":[{"pos":"n.","meaning":"自由；自由权","definition":"the freedom to act and live without unnecessary control","examples":[{"en":"The law protects individual liberty.","zh":"法律保护个人自由。"},{"en":"The prisoners longed for liberty.","zh":"囚犯渴望自由。"}]},{"pos":"n.","meaning":"许可；自由行事的权利","definition":"permission to act in a particular way","examples":[{"en":"You are at liberty to leave.","zh":"你可以自由离开。"},{"en":"She was not at liberty to discuss the details.","zh":"她无权讨论细节。"}]},{"pos":"n.","meaning":"放肆行为；随意改动（常用复数）","definition":"an action that exceeds acceptable freedom","examples":[{"en":"He took liberties with the historical facts.","zh":"他随意改动了历史事实。"},{"en":"She objected to the liberties taken with her work.","zh":"她反对别人擅自改动她的作品。"}]}],"license":[{"pos":"n.","meaning":"许可证；执照（美式拼写）","definition":"An official document giving permission to do something.","examples":[{"en":"He applied for a driver's license.","zh":"他申请了驾驶执照。"},{"en":"The restaurant displayed its business license near the entrance.","zh":"餐厅把营业执照挂在入口附近。"}]},{"pos":"v.","meaning":"批准；许可；授权","definition":"To give official permission for an activity.","examples":[{"en":"The city licenses street vendors.","zh":"市政府向街头商贩发放经营许可。"},{"en":"The company licensed its technology to another manufacturer.","zh":"公司授权另一家制造商使用其技术。"}]}],"likelihood":[{"pos":"n.","meaning":"可能性","definition":"the chance that something will happen","examples":[{"en":"The likelihood of rain is high.","zh":"下雨的可能性很高。"},{"en":"Training reduces the likelihood of accidents.","zh":"培训降低了发生事故的可能性。"}]}],"limb":[{"pos":"n.","meaning":"肢；臂；腿","definition":"an arm or leg","examples":[{"en":"The swimmer stretched all four limbs.","zh":"游泳者伸展了四肢。"},{"en":"The robot has four jointed limbs.","zh":"机器人有四条带关节的肢体。"}]},{"pos":"n.","meaning":"大树枝","definition":"a large branch of a tree","examples":[{"en":"A heavy limb fell in the storm.","zh":"一根粗树枝在风暴中掉落。"},{"en":"Birds nested on the oak's upper limbs.","zh":"鸟在橡树高处的大树枝上筑巢。"}]}],"lime":[{"pos":"n.","meaning":"石灰","definition":"A calcium-based material used in building and treating soil.","examples":[{"en":"The builder mixed lime with sand and water.","zh":"建筑工人把石灰与沙和水混合。"},{"en":"The farmer added lime to reduce the soil's acidity.","zh":"农民加入石灰以降低土壤酸性。"}]}],"limestone":[{"pos":"n.","meaning":"石灰岩;石灰石","definition":"a rock mainly composed of calcium carbonate","examples":[{"en":"The cave formed in limestone.","zh":"洞穴形成于石灰岩中。"},{"en":"Builders used local limestone for the walls.","zh":"建筑工人用当地石灰石砌墙。"}]}],"limitation":[{"pos":"n.","meaning":"限制；局限","definition":"a restriction or a weakness that limits ability","examples":[{"en":"The study acknowledges its limitations.","zh":"研究承认自身的局限。"},{"en":"Space limitations affected the design.","zh":"空间限制影响了设计。"}]}],"limited":[{"pos":"adj.","meaning":"有限的；受限制的","definition":"Restricted in amount, extent, or availability.","examples":[{"en":"Seating is limited, so book early.","zh":"座位有限，请尽早预订。"},{"en":"The study had a limited budget.","zh":"这项研究的预算有限。"}]}],"limp":[{"pos":"adj.","meaning":"软的;无力的;松弛的","definition":"lacking firmness or strength","examples":[{"en":"The flowers looked limp in the heat.","zh":"花朵在高温下显得蔫软。"},{"en":"His injured arm hung limp.","zh":"他受伤的手臂无力地垂着。"}]}],"linen":[{"pos":"n.","meaning":"亚麻布；亚麻织物","definition":"cloth made from flax fibres","examples":[{"en":"The jacket is made of linen.","zh":"夹克由亚麻布制成。"},{"en":"Linen curtains softened the light.","zh":"亚麻窗帘使光线柔和。"}]}],"linger":[{"pos":"v.","meaning":"逗留；迟迟不走","definition":"To stay longer than necessary or expected.","examples":[{"en":"We lingered in the café after lunch.","zh":"午餐后，我们在咖啡馆里又待了一会儿。"},{"en":"She lingered at the gate, reluctant to say goodbye.","zh":"她在门口迟迟不走，不愿告别。"}]},{"pos":"v.","meaning":"持续存在；缓慢消失","definition":"To remain for a long time before disappearing.","examples":[{"en":"The smell of smoke lingered in the room.","zh":"房间里的烟味久久不散。"},{"en":"Doubts about the plan lingered after the meeting.","zh":"会议后，对计划的疑虑依然存在。"}]}],"linguistic":[{"pos":"adj.","meaning":"语言的;语言学的","definition":"relating to language or its study","examples":[{"en":"The region has remarkable linguistic diversity.","zh":"该地区具有惊人的语言多样性。"},{"en":"She conducted a linguistic analysis of the speeches.","zh":"她对演讲进行了语言学分析。"}]}],"link":[{"pos":"n.","meaning":"环；环节","definition":"one connecting part of a chain","examples":[{"en":"A broken link weakened the chain.","zh":"一个断环使链条变弱了。"},{"en":"Each link must support the same weight.","zh":"每个链环都必须承受同样的重量。"}]},{"pos":"n.","meaning":"联系；纽带","definition":"a connection between things or people","examples":[{"en":"The study found a link between the variables.","zh":"研究发现这些变量之间存在联系。"},{"en":"The bridge provides a vital link between communities.","zh":"大桥是连接社区的重要纽带。"}]},{"pos":"v.","meaning":"连接；联系","definition":"to join or show a relationship","examples":[{"en":"A tunnel links the two buildings.","zh":"隧道连接两栋建筑。"},{"en":"The report links the decline to habitat loss.","zh":"报告将下降与栖息地丧失联系起来。"}]}],"liquor":[{"pos":"n.","meaning":"烈性酒；酒类饮料","definition":"Alcoholic drink, especially distilled spirits.","examples":[{"en":"The hotel keeps expensive liquor in a locked cabinet.","zh":"酒店把昂贵的烈酒放在上锁的柜子里。"},{"en":"The menu lists wine, beer, and liquor separately.","zh":"菜单把葡萄酒、啤酒和烈酒分开列出。"}]}],"literacy":[{"pos":"n.","meaning":"读写能力","definition":"the ability to read and write","examples":[{"en":"Adult literacy classes are offered at the community centre.","zh":"社区中心开设成人读写课程。"},{"en":"Early reading can improve literacy.","zh":"早期阅读可以提升读写能力。"},{"en":"The programme aims to raise literacy levels in rural areas.","zh":"该项目旨在提高农村地区的读写水平。"}]}],"literal":[{"pos":"adj.","meaning":"字面的；逐字的","definition":"following the exact meaning of the words","examples":[{"en":"A literal translation can sound unnatural.","zh":"逐字翻译可能听起来不自然。"},{"en":"She understood the remark in its literal sense.","zh":"她按字面意思理解了那番话。"}]}],"literate":[{"pos":"adj.","meaning":"有读写能力的；识字的","definition":"Able to read and write.","examples":[{"en":"The programme aims to help every adult become literate.","zh":"这个项目旨在帮助每个成年人掌握读写能力。"},{"en":"A literate population can access a wider range of information.","zh":"具备读写能力的人群可以获取更广泛的信息。"}]},{"pos":"adj.","meaning":"有文化的；有某领域知识的","definition":"Educated or knowledgeable in a particular area.","examples":[{"en":"Modern employees often need to be computer literate.","zh":"现代员工通常需要具备计算机知识。"},{"en":"Her essays are thoughtful and highly literate.","zh":"她的文章思想深刻，文辞娴熟。"}]}],"literature":[{"pos":"n.","meaning":"文学;文学作品","definition":"written works valued for artistic quality","examples":[{"en":"She studies English literature.","zh":"她研究英国文学。"},{"en":"The story became a classic of children's literature.","zh":"这个故事成为儿童文学经典。"}]},{"pos":"n.","meaning":"文献;资料","definition":"written material on a particular subject","examples":[{"en":"Review the existing literature before designing the study.","zh":"设计研究前先回顾已有文献。"},{"en":"The clinic provides literature about its services.","zh":"诊所提供介绍其服务的资料。"}]}],"litter":[{"pos":"v.","meaning":"乱扔；使杂乱","definition":"to scatter rubbish or objects untidily","examples":[{"en":"Visitors must not litter the beach.","zh":"游客不得在海滩乱扔垃圾。"},{"en":"Empty boxes littered the floor.","zh":"空盒子散乱地堆在地板上。"}]},{"pos":"n.","meaning":"垃圾；废弃物","definition":"rubbish left in a public place","examples":[{"en":"Volunteers collected litter along the river.","zh":"志愿者沿河捡垃圾。"},{"en":"Please put litter in the bin.","zh":"请把垃圾扔进垃圾桶。"}]},{"pos":"n.","meaning":"一窝幼崽","definition":"young animals born to the same mother at one time","examples":[{"en":"The cat had a litter of kittens.","zh":"猫生了一窝小猫。"},{"en":"Three puppies from the litter found homes.","zh":"这一窝中的三只小狗找到了归宿。"}]}],"livelihood":[{"pos":"n.","meaning":"生计；谋生手段","definition":"The means by which someone earns enough to live.","examples":[{"en":"Fishing provides a livelihood for many coastal families.","zh":"捕鱼为许多沿海家庭提供了生计。"},{"en":"The drought threatened the farmers' livelihoods.","zh":"干旱威胁着农民的生计。"}]}],"liver":[{"pos":"n.","meaning":"肝脏;食用动物肝","definition":"a large organ involved in metabolism and digestion","examples":[{"en":"The scan showed a healthy liver.","zh":"扫描显示肝脏健康。"},{"en":"The chef cooked chicken liver with onions.","zh":"厨师把鸡肝和洋葱一起烹制。"}]},{"pos":"n.","meaning":"以某种方式生活的人;居住者（常有修饰语）","definition":"a person living in a specified way or place","examples":[{"en":"A frugal liver, she spent little on luxuries.","zh":"她生活节俭，很少购买奢侈品。"},{"en":"He had been a country liver all his life.","zh":"他一辈子都住在乡下。"}]}],"livestock":[{"pos":"n.","meaning":"牲畜；家畜","definition":"farm animals kept for use or profit","examples":[{"en":"Farmers moved the livestock to higher ground.","zh":"农民把牲畜转移到高处。"},{"en":"The farm raises livestock as well as crops.","zh":"农场既饲养牲畜也种植作物。"}]}],"load":[{"pos":"v.","meaning":"装载；装入","definition":"To put goods, material, or ammunition into something.","examples":[{"en":"They loaded the van with furniture.","zh":"他们把家具装进货车。"},{"en":"She loaded a new roll of film into the camera.","zh":"她往相机里装入一卷新胶片。"}]},{"pos":"n.","meaning":"负载；装载物；负担","definition":"An amount carried or supported by something.","examples":[{"en":"The bridge can support heavy loads.","zh":"这座桥能承受重载。"},{"en":"The lorry carried a load of bricks.","zh":"货车运载了一车砖。"}]}],"loan":[{"pos":"n.","meaning":"贷款;借款;借用","definition":"money or an item lent for temporary use","examples":[{"en":"The bank approved their home loan.","zh":"银行批准了他们的住房贷款。"},{"en":"The painting is on loan from a private collection.","zh":"这幅画是从私人收藏中借展的。"}]},{"pos":"v.","meaning":"借给;贷出","definition":"to lend money or an object","examples":[{"en":"She loaned me her bicycle.","zh":"她把自行车借给了我。"},{"en":"The museum loaned several objects to the exhibition.","zh":"博物馆为展览借出了几件藏品。"}]}],"loath":[{"pos":"adj.","meaning":"不情愿的；不愿意的","definition":"unwilling or reluctant","examples":[{"en":"She was loath to leave the garden.","zh":"她不愿离开花园。"},{"en":"They were loath to abandon the project.","zh":"他们不愿放弃项目。"}]}],"lobby":[{"pos":"n.","meaning":"大厅；门厅","definition":"An entrance hall in a large building.","examples":[{"en":"We met in the hotel lobby.","zh":"我们在酒店大厅见面。"},{"en":"A visitor was waiting in the lobby.","zh":"一位访客正在门厅等候。"}]},{"pos":"n.","meaning":"游说团体；利益集团","definition":"A group seeking to influence public decisions.","examples":[{"en":"The transport lobby supported the new road.","zh":"交通运输利益团体支持修建新路。"},{"en":"A powerful environmental lobby opposed the development.","zh":"一个有影响力的环保游说团体反对这项开发。"}]},{"pos":"v.","meaning":"游说；向决策者施压","definition":"To try to influence people who make decisions.","examples":[{"en":"Residents lobbied the council for safer crossings.","zh":"居民游说地方议会设置更安全的人行横道。"},{"en":"The association is lobbying against the proposed fee.","zh":"协会正在游说，反对拟议中的收费。"}]}],"locality":[{"pos":"n.","meaning":"地区;地点;位置","definition":"a particular area or place","examples":[{"en":"The plant grows in several coastal localities.","zh":"这种植物生长在几处沿海地区。"},{"en":"Doctors in the locality shared their findings.","zh":"当地医生分享了研究发现。"}]}],"locate":[{"pos":"v.","meaning":"找到；确定位置","definition":"to discover the position of something","examples":[{"en":"We located the missing file.","zh":"我们找到了丢失的文件。"},{"en":"The sensor helps locate underground pipes.","zh":"传感器帮助确定地下管道的位置。"}]},{"pos":"v.","meaning":"设置在；位于","definition":"to place or be situated somewhere","examples":[{"en":"They located the office near the station.","zh":"他们把办公室设在车站附近。"},{"en":"The village is located beside a lake.","zh":"村庄位于湖边。"}]}],"location":[{"pos":"n.","meaning":"地点；位置；场所","definition":"The place where something is situated.","examples":[{"en":"The map shows the location of the nearest shelter.","zh":"地图显示了最近避难所的位置。"},{"en":"The shop's central location attracts many customers.","zh":"商店位于市中心，吸引了许多顾客。"}]},{"pos":"n.","meaning":"外景拍摄地","definition":"A real place used for filming outside a studio.","examples":[{"en":"The crew spent a month on location in the mountains.","zh":"摄制组在山区外景地待了一个月。"},{"en":"The village served as a location for the historical drama.","zh":"这个村庄是那部历史剧的外景拍摄地。"}]}],"log":[{"pos":"n.","meaning":"原木;木段","definition":"a section of a cut tree trunk","examples":[{"en":"He added a log to the fire.","zh":"他往火里添了一段木头。"},{"en":"Logs floated downstream toward the mill.","zh":"原木顺流漂向木材厂。"}]},{"pos":"n.","meaning":"日志;记录","definition":"a written record of events or activities","examples":[{"en":"The pilot completed the flight log.","zh":"飞行员填写了飞行日志。"},{"en":"Keep a log of all maintenance work.","zh":"记录所有维护工作。"}]},{"pos":"v.","meaning":"记录","definition":"to record information systematically","examples":[{"en":"The sensor logs temperature every minute.","zh":"传感器每分钟记录一次温度。"},{"en":"Staff logged each visitor's arrival.","zh":"员工记录了每位访客的到达时间。"}]}],"logic":[{"pos":"n.","meaning":"逻辑；推理方式","definition":"reasoning that follows connected steps","examples":[{"en":"I could not follow his logic.","zh":"我无法理解他的逻辑。"},{"en":"There is clear logic behind the decision.","zh":"这个决定背后有清晰的逻辑。"}]},{"pos":"n.","meaning":"逻辑学","definition":"the study of valid reasoning","examples":[{"en":"She studied logic at university.","zh":"她在大学学过逻辑学。"},{"en":"The course introduces formal logic.","zh":"课程介绍形式逻辑学。"}]}],"long-term":[{"pos":"adj.","meaning":"长期的；长远的","definition":"Continuing or relating to a long period.","examples":[{"en":"The project needs long-term financial support.","zh":"这个项目需要长期资金支持。"},{"en":"We should consider the long-term effects of the decision.","zh":"我们应考虑这个决定的长远影响。"}]}],"longitude":[{"pos":"n.","meaning":"经度","definition":"angular distance east or west of a reference meridian","examples":[{"en":"The map gives latitude and longitude.","zh":"地图标明纬度和经度。"},{"en":"The ship's longitude was calculated from accurate time.","zh":"船只的经度根据精确时间计算得出。"}]}],"longitudinal":[{"pos":"adj.","meaning":"纵向的；沿长度方向的","definition":"running along the length of something","examples":[{"en":"The leaf has a longitudinal stripe.","zh":"叶子上有一条纵纹。"},{"en":"Engineers examined a longitudinal section of the beam.","zh":"工程师检查了横梁的纵截面。"}]},{"pos":"adj.","meaning":"经度的；经线的","definition":"relating to longitude","examples":[{"en":"The chart shows longitudinal differences between locations.","zh":"图表显示各地的经度差异。"},{"en":"The navigator checked the vessel's longitudinal position.","zh":"领航员检查了船只的经度位置。"}]},{"pos":"adj.","meaning":"纵向追踪的（研究）","definition":"following the same subjects over time","examples":[{"en":"A longitudinal study followed the children for ten years.","zh":"一项纵向研究追踪了这些孩子十年。"},{"en":"Longitudinal data revealed changes in commuting habits.","zh":"追踪数据揭示了通勤习惯的变化。"}]}],"loop":[{"pos":"n.","meaning":"环；圈；环状物","definition":"A curved shape that bends back towards itself.","examples":[{"en":"She tied a loop in the rope.","zh":"她在绳子上打了一个环。"},{"en":"A small loop of fabric holds the button.","zh":"一个小布环扣住纽扣。"}]},{"pos":"n.","meaning":"环路；循环","definition":"A route or sequence that returns to its starting point.","examples":[{"en":"The bus follows a loop around the campus.","zh":"公交车沿校园环线行驶。"},{"en":"The programme repeats the calculation in a loop.","zh":"程序通过循环重复计算。"}]},{"pos":"v.","meaning":"使成环；绕圈；环形移动","definition":"To form a curved loop or move in a circular path.","examples":[{"en":"He looped the scarf around his neck.","zh":"他把围巾绕在脖子上。"},{"en":"The path loops around the lake before returning to the car park.","zh":"小路绕湖一圈后返回停车场。"}]}],"loose":[{"pos":"adj.","meaning":"松的;未固定的","definition":"not tightly held or attached","examples":[{"en":"A loose screw caused the rattle.","zh":"一颗松螺丝造成了异响。"},{"en":"She wore a loose cotton shirt.","zh":"她穿着宽松棉衬衫。"}]},{"pos":"adj.","meaning":"松散的;不精确的","definition":"not strict, detailed, or closely organized","examples":[{"en":"They formed a loose alliance.","zh":"他们建立了松散联盟。"},{"en":"This is only a loose translation of the poem.","zh":"这只是诗歌的大意翻译。"}]}],"lounge":[{"pos":"v.","meaning":"懒洋洋地坐、躺或闲站","definition":"to sit or lie in a relaxed lazy way","examples":[{"en":"Guests lounged beside the pool.","zh":"客人们懒洋洋地躺在泳池旁。"},{"en":"He lounged on the sofa all afternoon.","zh":"他整个下午都懒坐在沙发上。"}]},{"pos":"n.","meaning":"休息室；候客室","definition":"a comfortable room for relaxing or waiting","examples":[{"en":"We waited in the airport lounge.","zh":"我们在机场候机室等待。"},{"en":"The hotel lounge overlooks the garden.","zh":"酒店休息室俯瞰花园。"}]}],"lower":[{"pos":"adj.","meaning":"较低的；下面的；下层的","definition":"Below something else in position, amount, or rank.","examples":[{"en":"Keep heavy boxes on the lower shelf.","zh":"把重箱子放在下面的搁板上。"},{"en":"The new model has lower running costs.","zh":"新型号的运行成本更低。"}]},{"pos":"v.","meaning":"降低；放低；减少","definition":"To move down or reduce an amount.","examples":[{"en":"They lowered the boat into the water.","zh":"他们把船放入水中。"},{"en":"The shop lowered its prices after the holiday.","zh":"假期后，商店降价了。"}]}],"loyalty":[{"pos":"n.","meaning":"忠诚;忠心","definition":"faithfulness to a person, group, or principle","examples":[{"en":"Her loyalty to her friends never wavered.","zh":"她对朋友的忠诚从未动摇。"},{"en":"The programme rewards customer loyalty.","zh":"该计划回馈忠实顾客。"}]}],"luggage":[{"pos":"n.","meaning":"行李","definition":"bags and cases taken on a journey","examples":[{"en":"Keep your luggage with you at all times.","zh":"请始终随身保管行李。"},{"en":"The airline allows one piece of hand luggage.","zh":"该航空公司允许携带一件手提行李。"},{"en":"There is a luggage storage room beside reception.","zh":"前台旁有行李寄存室。"}]}],"lull":[{"pos":"n.","meaning":"暂停；间歇；平静期","definition":"A temporary period of reduced activity or quiet.","examples":[{"en":"We went outside during a lull in the rain.","zh":"雨暂时停歇时，我们出了门。"},{"en":"There was a brief lull in the conversation.","zh":"谈话出现了短暂的停顿。"}]}],"lunar":[{"pos":"adj.","meaning":"月球的;月亮的","definition":"relating to the Moon","examples":[{"en":"The spacecraft collected lunar rocks.","zh":"航天器采集了月球岩石。"},{"en":"A lunar eclipse attracted many observers.","zh":"月食吸引了许多观测者。"}]}],"luxuriant":[{"pos":"adj.","meaning":"繁茂的；浓密的","definition":"growing thickly and abundantly","examples":[{"en":"Luxuriant vegetation covered the hillside.","zh":"繁茂的植被覆盖山坡。"},{"en":"The painting shows her luxuriant dark hair.","zh":"画中描绘了她浓密的黑发。"}]},{"pos":"adj.","meaning":"肥沃多产的","definition":"producing abundant growth","examples":[{"en":"The settlers found luxuriant land beside the river.","zh":"定居者在河边发现了肥沃的土地。"},{"en":"The account describes a luxuriant valley rich in crops.","zh":"记载描绘了一个庄稼丰盛的肥沃山谷。"}]},{"pos":"adj.","meaning":"丰富的；繁复华丽的","definition":"rich and abundant in detail or expression","examples":[{"en":"The novel is full of luxuriant imagery.","zh":"小说充满丰富华丽的意象。"},{"en":"The hall had luxuriant decoration.","zh":"大厅装饰繁复华美。"}]}],"luxury":[{"pos":"n.","meaning":"奢华；奢侈的享受","definition":"Great comfort and expensive surroundings.","examples":[{"en":"They spent a weekend in luxury at a lakeside hotel.","zh":"他们在湖边酒店奢华地度过了一个周末。"},{"en":"Hot running water once represented real luxury.","zh":"流动热水曾经意味着真正的奢侈享受。"}]},{"pos":"n.","meaning":"奢侈品；非必需的享受","definition":"An expensive or pleasurable thing that is not essential.","examples":[{"en":"A second car would be a luxury for us.","zh":"对我们来说，第二辆车是奢侈品。"},{"en":"During exam week, an afternoon off felt like a luxury.","zh":"考试周里，休息一个下午都像是一种奢侈享受。"}]},{"pos":"adj.","meaning":"奢华的；高档的","definition":"Providing expensive comfort and quality.","examples":[{"en":"The company builds luxury apartments.","zh":"这家公司建造高档公寓。"},{"en":"They hired a luxury coach for the tour.","zh":"他们为旅行租了一辆豪华大巴。"}]}],"machinery":[{"pos":"n.","meaning":"机器;机械设备总称","definition":"machines considered collectively","examples":[{"en":"The factory replaced its ageing machinery.","zh":"工厂更换了老旧机器。"},{"en":"Heavy machinery cleared the site.","zh":"重型机械清理了场地。"}]},{"pos":"n.","meaning":"机构;运作体系","definition":"the organized system used to achieve something","examples":[{"en":"The machinery of government moved slowly.","zh":"政府机构运转缓慢。"},{"en":"They established machinery for resolving disputes.","zh":"他们建立了解决争议的机制。"}]}],"magic":[{"pos":"n.","meaning":"魔法；法术","definition":"supernatural power or tricks creating impossible effects","examples":[{"en":"The story begins with a spell of magic.","zh":"故事从一道魔法咒语开始。"},{"en":"The children enjoyed the magic show.","zh":"孩子们喜欢这场魔术表演。"}]},{"pos":"n.","meaning":"魅力；魔力","definition":"a special attractive or exciting quality","examples":[{"en":"The old theatre has lost none of its magic.","zh":"老剧院的魅力丝毫未减。"},{"en":"The music brought magic to the evening.","zh":"音乐为这个夜晚增添了魔力。"}]},{"pos":"adj.","meaning":"有魔力的；神奇的","definition":"having supernatural or remarkable power","examples":[{"en":"The hero discovered a magic ring.","zh":"主人公发现了一枚魔戒。"},{"en":"There is no magic solution to the problem.","zh":"这个问题没有神奇的解决办法。"}]}],"magma":[{"pos":"n.","meaning":"岩浆","definition":"Hot molten rock beneath the Earth's surface.","examples":[{"en":"Magma rose through cracks in the crust.","zh":"岩浆沿地壳裂隙上升。"},{"en":"The diagram shows a chamber of magma below the volcano.","zh":"图中显示了火山下面的岩浆房。"}]}],"magnet":[{"pos":"n.","meaning":"磁铁;磁体","definition":"an object producing a magnetic field","examples":[{"en":"The magnet attracted the iron nails.","zh":"磁铁吸引了铁钉。"},{"en":"A strong magnet holds the door closed.","zh":"强磁铁使门保持关闭。"}]},{"pos":"n.","meaning":"有吸引力的人或事物","definition":"something strongly attracting people or things","examples":[{"en":"The new park became a magnet for families.","zh":"新公园成为吸引家庭游客的地方。"},{"en":"The university is a magnet for talented researchers.","zh":"大学吸引了许多优秀研究人员。"}]}],"magnetic":[{"pos":"adj.","meaning":"磁的；有磁性的","definition":"relating to magnets or their effects","examples":[{"en":"The compass responds to a magnetic field.","zh":"指南针对磁场作出反应。"},{"en":"A magnetic strip holds the tools.","zh":"磁条固定着工具。"}]},{"pos":"adj.","meaning":"有吸引力的；迷人的","definition":"strongly attracting people's attention","examples":[{"en":"Her magnetic personality drew a crowd.","zh":"她迷人的个性吸引了人群。"},{"en":"The actor has a magnetic presence.","zh":"这位演员极有魅力。"}]}],"magnificent":[{"pos":"adj.","meaning":"宏伟的；壮丽的；极出色的","definition":"Very impressive in beauty, scale, or quality.","examples":[{"en":"The palace has a magnificent marble entrance.","zh":"宫殿有一座宏伟的大理石入口。"},{"en":"The goalkeeper made a magnificent save.","zh":"守门员完成了一次极为精彩的扑救。"}]},{"pos":"adj.","meaning":"高尚的；慷慨大度的","definition":"Exceptionally noble or generous.","examples":[{"en":"Her magnificent generosity funded the entire scholarship programme.","zh":"她极其慷慨的捐助资助了整个奖学金项目。"},{"en":"The volunteers showed magnificent courage during the rescue.","zh":"志愿者在救援中表现出非凡的勇气。"}]}],"magnify":[{"pos":"v.","meaning":"放大;扩大","definition":"to make something appear larger or more serious","examples":[{"en":"The lens magnifies small objects.","zh":"镜片放大小物体。"},{"en":"Rumours magnified the scale of the problem.","zh":"传闻夸大了问题的规模。"}]}],"magnitude":[{"pos":"n.","meaning":"巨大程度；规模；重要性","definition":"the size, extent, or importance of something","examples":[{"en":"We underestimated the magnitude of the task.","zh":"我们低估了任务的规模。"},{"en":"The discovery's magnitude became clear later.","zh":"这项发现的重要性后来才显现。"}]},{"pos":"n.","meaning":"星等；天体亮度等级","definition":"a numerical measure of a celestial object's brightness","examples":[{"en":"The catalogue lists each star's magnitude.","zh":"星表列出了每颗星的星等。"},{"en":"Observers measured the changing magnitude of the star.","zh":"观测者测量了这颗星变化的星等。"}]}],"mainly":[{"pos":"adv.","meaning":"主要地；大体上","definition":"For the most part.","examples":[{"en":"The island's economy depends mainly on tourism.","zh":"这座岛的经济主要依靠旅游业。"},{"en":"The audience consisted mainly of university students.","zh":"观众主要是大学生。"}]}],"mainstream":[{"pos":"n.","meaning":"主流;主要倾向","definition":"the ideas or practices accepted by most people","examples":[{"en":"The movement entered the political mainstream.","zh":"这场运动进入政治主流。"},{"en":"Her work lies outside the artistic mainstream.","zh":"她的作品处于艺术主流之外。"}]},{"pos":"n.","meaning":"主流爵士乐","definition":"jazz between traditional and modern styles","examples":[{"en":"The band specialises in mainstream jazz.","zh":"乐队专演主流爵士乐。"},{"en":"The festival devoted an evening to mainstream.","zh":"音乐节专设一晚演奏主流爵士乐。"}]},{"pos":"adj.","meaning":"主流的","definition":"accepted or used by most people","examples":[{"en":"The idea gained mainstream support.","zh":"这个想法获得了主流支持。"},{"en":"Mainstream newspapers covered the story.","zh":"主流报纸报道了此事。"}]}],"maintain":[{"pos":"v.","meaning":"维持；保持","definition":"to keep something at a particular level or state","examples":[{"en":"The system maintains a constant temperature.","zh":"系统保持恒温。"},{"en":"She maintained contact with former colleagues.","zh":"她与以前的同事保持联系。"}]},{"pos":"v.","meaning":"维修；保养","definition":"to keep equipment in good condition","examples":[{"en":"The landlord maintains the heating system.","zh":"房东维护供暖系统。"},{"en":"Regularly maintained bicycles last longer.","zh":"定期保养的自行车使用寿命更长。"}]},{"pos":"v.","meaning":"坚持说；主张","definition":"to state firmly that something is true","examples":[{"en":"He maintained that the figures were accurate.","zh":"他坚持说数据准确。"},{"en":"The author maintains her original position.","zh":"作者坚持原来的立场。"}]},{"pos":"v.","meaning":"供养；赡养","definition":"to provide financial support for someone","examples":[{"en":"She worked hard to maintain her family.","zh":"她努力工作养家。"},{"en":"The allowance helped him maintain two children.","zh":"津贴帮助他抚养两个孩子。"}]}],"maintenance":[{"pos":"n.","meaning":"维护；保养","definition":"work that keeps something in good condition","examples":[{"en":"The lift is closed for maintenance.","zh":"电梯因维护暂停使用。"},{"en":"Regular maintenance keeps the heating system safe.","zh":"定期维护能保证供暖系统安全。"},{"en":"The monthly fee covers building maintenance.","zh":"月费包含楼宇维护费用。"}]},{"pos":"n.","meaning":"维持；保持","definition":"The act of keeping a state or condition unchanged.","examples":[{"en":"The agreement supports the maintenance of peace.","zh":"协议有助于维持和平。"},{"en":"The maintenance of accurate records is essential.","zh":"保持准确记录至关重要。"}]},{"pos":"n.","meaning":"赡养费；抚养费；生活费","definition":"Money paid to support someone financially.","examples":[{"en":"He makes monthly maintenance payments for his children.","zh":"他每月为孩子支付抚养费。"},{"en":"The court considered the family's maintenance needs.","zh":"法院考虑了这家人的生活供养需要。"}]}],"major":[{"pos":"adj.","meaning":"主要的;重大的","definition":"important or large in extent","examples":[{"en":"The bridge needs major repairs.","zh":"桥梁需要大修。"},{"en":"Agriculture is a major source of income.","zh":"农业是主要收入来源。"}]},{"pos":"n.","meaning":"主修专业","definition":"a principal subject studied at university","examples":[{"en":"She chose chemistry as her major.","zh":"她选择化学作为主修专业。"},{"en":"Students may change their major after the first year.","zh":"学生可在第一年后更换专业。"}]},{"pos":"n.","meaning":"某专业学生","definition":"a student specializing in a subject","examples":[{"en":"He is a history major.","zh":"他是历史专业学生。"},{"en":"Several engineering majors joined the project.","zh":"几名工程专业学生加入了项目。"}]},{"pos":"v.","meaning":"主修;专攻","definition":"to study a subject as a university specialization","examples":[{"en":"She majors in economics.","zh":"她主修经济学。"},{"en":"He decided to major in biology.","zh":"他决定主修生物学。"}]}],"majority":[{"pos":"n.","meaning":"多数；大多数","definition":"more than half of a group","examples":[{"en":"The majority supported the proposal.","zh":"多数人支持提案。"},{"en":"A majority of households have internet access.","zh":"大多数家庭可以上网。"}]}],"malevolent":[{"pos":"adj.","meaning":"恶意的；恶毒的","definition":"Wishing to harm others.","examples":[{"en":"The story's villain hides his malevolent intentions behind polite manners.","zh":"故事中的反派用礼貌举止掩饰恶意。"},{"en":"A malevolent rumour damaged her reputation.","zh":"一个恶毒的谣言损害了她的声誉。"}]}],"mall":[{"pos":"n.","meaning":"购物中心","definition":"a large building or area containing many shops","examples":[{"en":"The mall has a cinema upstairs.","zh":"购物中心楼上有电影院。"},{"en":"A new mall opened near the station.","zh":"车站附近新开了一家购物中心。"}]}],"malleable":[{"pos":"adj.","meaning":"可锻的；可塑的","definition":"able to be shaped without breaking","examples":[{"en":"Gold is a malleable metal.","zh":"金是一种有延展性的金属。"},{"en":"The warm material became soft and malleable.","zh":"温热的材料变得柔软且可塑。"}]},{"pos":"adj.","meaning":"易受影响的；易改变的","definition":"easily influenced or changed","examples":[{"en":"Public opinion proved surprisingly malleable.","zh":"公众意见出人意料地容易改变。"},{"en":"The character is young and malleable.","zh":"这个角色年轻，容易受影响。"}]}],"malt":[{"pos":"n.","meaning":"麦芽","definition":"Grain that has begun to sprout and is then dried.","examples":[{"en":"The brewer added crushed malt to the warm water.","zh":"酿酒师把碎麦芽加入温水中。"},{"en":"The biscuits have a mild flavour of malt.","zh":"这种饼干有淡淡的麦芽味。"}]},{"pos":"n.","meaning":"麦芽威士忌；麦芽酒","definition":"An alcoholic drink made using malted grain, especially malt whisky.","examples":[{"en":"He ordered a single malt after dinner.","zh":"晚餐后他点了一杯单一麦芽威士忌。"},{"en":"The shop sells several locally produced malts.","zh":"这家店出售几种本地生产的麦芽酒。"}]},{"pos":"v.","meaning":"使发麦芽；制成麦芽","definition":"To allow grain to sprout before drying it.","examples":[{"en":"The factory malts barley for nearby breweries.","zh":"工厂把大麦制成麦芽，供附近酿酒厂使用。"},{"en":"The grain is malted under carefully controlled conditions.","zh":"谷物在严格控制的条件下发芽制成麦芽。"}]}],"maltreat":[{"pos":"v.","meaning":"虐待","definition":"to treat someone cruelly or badly","examples":[{"en":"The inquiry investigated claims that prisoners were maltreated.","zh":"调查核查了囚犯遭虐待的指控。"},{"en":"The shelter cares for animals that were maltreated.","zh":"收容所照顾曾受虐待的动物。"}]}],"mammal":[{"pos":"n.","meaning":"哺乳动物","definition":"an animal whose females feed young with milk","examples":[{"en":"A whale is a mammal.","zh":"鲸是一种哺乳动物。"},{"en":"The survey recorded several small mammals.","zh":"调查记录了几种小型哺乳动物。"}]}],"management":[{"pos":"n.","meaning":"管理；经营；处理","definition":"The organisation and control of work, resources, or situations.","examples":[{"en":"Good time management reduces stress.","zh":"良好的时间管理可以减少压力。"},{"en":"The course covers the management of small businesses.","zh":"这门课程涵盖小企业经营管理。"}]},{"pos":"n.","meaning":"管理层；管理部门","definition":"The people responsible for running an organisation.","examples":[{"en":"The staff met with management to discuss schedules.","zh":"员工与管理层会面，讨论排班安排。"},{"en":"Hotel management apologised for the inconvenience.","zh":"酒店管理层为造成的不便道歉。"}]}],"managerial":[{"pos":"adj.","meaning":"管理的;经理的;经营的","definition":"relating to managing an organization","examples":[{"en":"The job requires managerial experience.","zh":"这份工作要求管理经验。"},{"en":"She developed strong managerial skills.","zh":"她培养了很强的管理能力。"}]}],"mandarin":[{"pos":"n.","meaning":"柑橘；橘子","definition":"a small easily peeled citrus fruit","examples":[{"en":"She peeled a mandarin for the child.","zh":"她给孩子剥了一只橘子。"},{"en":"The bowl contained apples and mandarins.","zh":"碗里有苹果和橘子。"}]},{"pos":"n.","meaning":"中国旧时高级官员；高级官僚","definition":"a historical Chinese official or powerful senior bureaucrat","examples":[{"en":"The portrait depicts a mandarin in formal robes.","zh":"肖像描绘了一位身穿官服的中国官员。"},{"en":"Government mandarins debated the proposal privately.","zh":"政府高级官员私下讨论了提议。"}]},{"pos":"n.","meaning":"普通话；官话（通常大写 Mandarin）","definition":"the main standard variety of spoken Chinese","examples":[{"en":"She studies Mandarin at evening classes.","zh":"她在夜校学习普通话。"},{"en":"The guide spoke fluent Mandarin.","zh":"导游普通话流利。"}]}],"manifest":[{"pos":"adj.","meaning":"明显的；显而易见的","definition":"Easy to see or recognise.","examples":[{"en":"Her disappointment was manifest in her expression.","zh":"她的失望明显表现在脸上。"},{"en":"The proposal has several manifest advantages.","zh":"这个提案有几个显而易见的优点。"}]},{"pos":"v.","meaning":"显示；表明；显现","definition":"To show or become evident.","examples":[{"en":"The illness can manifest itself in different ways.","zh":"这种疾病可能以不同方式表现出来。"},{"en":"Their concern manifested itself in practical offers of help.","zh":"他们的关心表现为提供实际帮助。"}]},{"pos":"n.","meaning":"货物清单；载货清单","definition":"An official list of cargo or passengers.","examples":[{"en":"The customs officer checked the ship's manifest.","zh":"海关官员检查了船舶的货物清单。"},{"en":"The missing crate was recorded on the cargo manifest.","zh":"丢失的货箱记载在货物清单上。"}]}],"manipulate":[{"pos":"v.","meaning":"操纵;控制;巧妙影响","definition":"to control someone or something for a purpose","examples":[{"en":"The advertisement manipulated consumers' fears.","zh":"广告利用消费者的恐惧来影响他们。"},{"en":"He manipulated the figures to hide the loss.","zh":"他操纵数据以掩盖亏损。"}]},{"pos":"v.","meaning":"操作;处理","definition":"to handle or adjust something skilfully","examples":[{"en":"The surgeon manipulated the tiny instrument.","zh":"外科医生熟练操作微型器械。"},{"en":"The software lets users manipulate images.","zh":"软件让用户能够处理图像。"}]}],"manipulative":[{"pos":"adj.","meaning":"操纵他人的；善于摆布人的","definition":"controlling others unfairly for one's own purposes","examples":[{"en":"His manipulative behaviour damaged their trust.","zh":"他操纵他人的行为损害了彼此信任。"},{"en":"The advertisement was criticised as manipulative.","zh":"广告被批评为具有操纵性。"}]}],"manoeuvre":[{"pos":"n.","meaning":"移动；操作动作","definition":"A controlled movement requiring care or skill.","examples":[{"en":"Parking in the narrow space required a difficult manoeuvre.","zh":"在狭窄车位停车需要完成一个困难动作。"},{"en":"The pilot completed the manoeuvre safely.","zh":"飞行员安全完成了这个飞行动作。"}]},{"pos":"n.","meaning":"策略；手段","definition":"A planned action intended to gain an advantage.","examples":[{"en":"The announcement was seen as a political manoeuvre.","zh":"这项宣布被视为一种政治策略。"},{"en":"The company used a legal manoeuvre to delay the sale.","zh":"公司运用法律手段推迟了出售。"}]},{"pos":"v.","meaning":"操纵；移动；转动","definition":"To move or control something carefully.","examples":[{"en":"She manoeuvred the wheelchair through the narrow doorway.","zh":"她小心地操纵轮椅穿过狭窄门口。"},{"en":"The captain manoeuvred the boat away from the rocks.","zh":"船长操纵船只驶离礁石。"}]},{"pos":"v.","meaning":"设法促成；耍手段","definition":"To arrange a situation through skilful or indirect action.","examples":[{"en":"He manoeuvred himself into a position of influence.","zh":"他设法使自己进入了一个有影响力的位置。"},{"en":"The negotiators manoeuvred to secure a better agreement.","zh":"谈判代表运用策略争取更有利的协议。"}]}],"manor":[{"pos":"n.","meaning":"庄园;领地;庄园宅邸","definition":"a large country estate or its main house","examples":[{"en":"The manor overlooked rolling farmland.","zh":"庄园俯瞰起伏的农田。"},{"en":"The old manor is now a hotel.","zh":"旧庄园宅邸如今是一家酒店。"}]}],"mansion":[{"pos":"n.","meaning":"豪宅；宅邸","definition":"a very large impressive house","examples":[{"en":"The mansion is surrounded by gardens.","zh":"豪宅四周是花园。"},{"en":"The old mansion now houses a museum.","zh":"旧宅邸现在是一座博物馆。"}]}],"mantle":[{"pos":"n.","meaning":"披风；斗篷","definition":"A loose sleeveless outer garment.","examples":[{"en":"The traveller wrapped a woollen mantle around her shoulders.","zh":"旅行者把羊毛披风裹在肩上。"},{"en":"The king's ceremonial mantle was embroidered with gold.","zh":"国王的礼仪披风上绣着金线。"}]},{"pos":"n.","meaning":"覆盖层；覆盖物；外表","definition":"A layer that covers or surrounds something.","examples":[{"en":"A mantle of snow covered the hills.","zh":"一层积雪覆盖了群山。"},{"en":"The town lay beneath a grey mantle of fog.","zh":"小镇笼罩在一层灰雾中。"}]},{"pos":"n.","meaning":"灯纱罩；白炽纱罩","definition":"A mesh covering that glows in a gas or oil lamp.","examples":[{"en":"The gas lamp needed a new mantle.","zh":"这盏煤气灯需要换一个新纱罩。"},{"en":"The fragile mantle broke when the lantern fell.","zh":"提灯落地时，易碎的纱罩破了。"}]},{"pos":"n.","meaning":"外套膜；包膜；皮层","definition":"A covering layer in an animal's anatomy.","examples":[{"en":"The mollusc's mantle secretes material for its shell.","zh":"软体动物的外套膜分泌形成外壳的物质。"},{"en":"The biologist examined the mantle beneath the shell.","zh":"生物学家检查了外壳下的外套膜。"}]},{"pos":"n.","meaning":"地幔","definition":"The layer of the Earth between the crust and the core.","examples":[{"en":"The mantle lies beneath the Earth's crust.","zh":"地幔位于地壳之下。"},{"en":"Scientists use seismic waves to study the mantle.","zh":"科学家利用地震波研究地幔。"}]},{"pos":"v.","meaning":"覆盖；笼罩","definition":"To cover or envelop something like a cloak.","examples":[{"en":"Snow mantled the rooftops overnight.","zh":"一夜之间，积雪覆盖了屋顶。"},{"en":"Mist mantled the river at dawn.","zh":"黎明时，薄雾笼罩着河流。"}]}],"manual":[{"pos":"n.","meaning":"手册;指南","definition":"a book giving instructions","examples":[{"en":"Consult the manual before assembling the desk.","zh":"组装书桌前先查阅手册。"},{"en":"The training manual explains emergency procedures.","zh":"培训手册说明了应急程序。"}]},{"pos":"adj.","meaning":"手工的;体力的;手动的","definition":"done by hand or physical effort","examples":[{"en":"The factory still relies on manual labour.","zh":"工厂仍依赖体力劳动。"},{"en":"Switch the camera to manual focus.","zh":"把相机切换为手动对焦。"}]}],"manufacture":[{"pos":"v.","meaning":"大量制造；生产","definition":"to make goods on an industrial scale","examples":[{"en":"The factory manufactures medical equipment.","zh":"工厂生产医疗设备。"},{"en":"These parts are manufactured locally.","zh":"这些零件在当地制造。"}]},{"pos":"n.","meaning":"制造；生产","definition":"the industrial production of goods","examples":[{"en":"The process reduces the cost of manufacture.","zh":"该工艺降低制造成本。"},{"en":"Water is used in the manufacture of paper.","zh":"造纸过程需要用水。"}]},{"pos":"n.","meaning":"工业产品（常用复数）","definition":"goods produced by industry","examples":[{"en":"The port exported local manufactures.","zh":"港口出口当地工业产品。"},{"en":"The exhibition displayed manufactures from several regions.","zh":"展览展示了几个地区的工业产品。"}]}],"manufacturer":[{"pos":"n.","meaning":"制造商；生产者；制造厂","definition":"A company or person that makes goods.","examples":[{"en":"The manufacturer recalled the faulty appliances.","zh":"制造商召回了有故障的电器。"},{"en":"Local manufacturers supply most of the building materials.","zh":"大多数建筑材料由当地制造商提供。"}]}],"marble":[{"pos":"n.","meaning":"大理石","definition":"a hard stone used in buildings and sculpture","examples":[{"en":"The statue was carved from white marble.","zh":"雕像由白色大理石雕成。"},{"en":"Marble floors kept the hall cool.","zh":"大理石地面使大厅保持凉爽。"}]},{"pos":"n.","meaning":"弹珠","definition":"a small glass ball used in games","examples":[{"en":"A blue marble rolled under the sofa.","zh":"一颗蓝色弹珠滚到沙发下面。"},{"en":"She kept her marbles in a cloth bag.","zh":"她把弹珠放在布袋里。"}]},{"pos":"n.","meaning":"弹珠游戏（复数 marbles）","definition":"a game played with small balls","examples":[{"en":"The children played marbles in the courtyard.","zh":"孩子们在院子里玩弹珠游戏。"},{"en":"He taught his younger brother the rules of marbles.","zh":"他教弟弟弹珠游戏的规则。"}]}],"margin":[{"pos":"n.","meaning":"差额；差距；幅度","definition":"the difference between two amounts","examples":[{"en":"She won by a narrow margin.","zh":"她以微弱优势获胜。"},{"en":"The profit margin increased this year.","zh":"今年利润率提高了。"}]},{"pos":"n.","meaning":"页边空白；边缘","definition":"the blank border of a page or edge of an area","examples":[{"en":"Write comments in the margin.","zh":"把评论写在页边空白处。"},{"en":"Reeds grew along the lake's margin.","zh":"芦苇长在湖边。"}]},{"pos":"n.","meaning":"余地；富余量","definition":"an extra amount allowed for uncertainty","examples":[{"en":"Leave a margin for unexpected costs.","zh":"为意外费用留出余地。"},{"en":"The timetable allows little margin for delay.","zh":"时刻表几乎没有给延误留余地。"}]},{"pos":"v.","meaning":"给……加边；在页边加注（少见）","definition":"to provide a border or write notes in a margin","examples":[{"en":"A narrow red line margins the page.","zh":"一条细红线给页面镶边。"},{"en":"The scholar margined the text with brief notes.","zh":"学者在文稿边上加了简短批注。"}]}],"marginally":[{"pos":"adv.","meaning":"稍微；略微","definition":"By a small amount or degree.","examples":[{"en":"The new engine is marginally quieter.","zh":"新发动机略微安静一些。"},{"en":"Sales increased marginally during the summer.","zh":"夏季销售额略有增加。"}]}],"maritime":[{"pos":"adj.","meaning":"海的;海事的;海运的","definition":"relating to the sea or shipping","examples":[{"en":"The museum displays the town's maritime history.","zh":"博物馆展示小镇的海事历史。"},{"en":"Maritime trade supported the port's economy.","zh":"海上贸易支撑了港口经济。"}]}],"marker":[{"pos":"n.","meaning":"标记；标志物","definition":"an object or sign identifying a place or feature","examples":[{"en":"A stone marker shows the boundary.","zh":"石质标志物标示边界。"},{"en":"The researchers used a marker to track movement.","zh":"研究人员使用标记物跟踪运动。"}]}],"marketplace":[{"pos":"n.","meaning":"市场；集市","definition":"A place where goods are bought and sold.","examples":[{"en":"Farmers brought vegetables to the marketplace.","zh":"农民把蔬菜运到集市。"},{"en":"The old marketplace is busiest on Saturdays.","zh":"老集市在周六最热闹。"}]},{"pos":"n.","meaning":"商业市场；竞争市场","definition":"The environment in which goods or services compete for buyers.","examples":[{"en":"The firm entered a highly competitive marketplace.","zh":"这家公司进入了一个竞争十分激烈的市场。"},{"en":"Online platforms have changed the global marketplace.","zh":"网络平台改变了全球商业市场。"}]}],"marsh":[{"pos":"n.","meaning":"沼泽;湿地","definition":"low wet ground with grasses and other plants","examples":[{"en":"Birds nested in the marsh.","zh":"鸟在沼泽中筑巢。"},{"en":"A wooden path crosses the marsh.","zh":"木栈道穿过沼泽。"}]}],"marsupial":[{"pos":"n.","meaning":"有袋动物","definition":"a mammal whose young usually develop in a pouch","examples":[{"en":"The kangaroo is a marsupial.","zh":"袋鼠是有袋动物。"},{"en":"The sanctuary protects several marsupials.","zh":"保护区保护了几种有袋动物。"}]},{"pos":"adj.","meaning":"有袋动物的","definition":"relating to mammals that usually carry young in pouches","examples":[{"en":"The study examined marsupial development.","zh":"研究考察了有袋动物的发育。"},{"en":"Australia has many marsupial species.","zh":"澳大利亚有许多有袋动物物种。"}]}],"marvellous":[{"pos":"adj.","meaning":"极好的；非凡的；令人惊叹的","definition":"Extremely good, enjoyable, or surprising.","examples":[{"en":"The concert was a marvellous experience.","zh":"这场音乐会是一次美妙的体验。"},{"en":"The child has a marvellous memory for melodies.","zh":"这个孩子对旋律有惊人的记忆力。"}]}],"mass":[{"pos":"adj.","meaning":"大量的;大规模的","definition":"involving many people or things","examples":[{"en":"The invention enabled mass production.","zh":"这项发明实现了大规模生产。"},{"en":"The closure triggered mass unemployment.","zh":"关闭引发了大规模失业。"}]},{"pos":"n.","meaning":"团;块;大量","definition":"a large amount gathered together","examples":[{"en":"A mass of dark clouds approached.","zh":"一大团乌云逼近。"},{"en":"She faced a mass of paperwork.","zh":"她面对着大量文书工作。"}]},{"pos":"n.","meaning":"质量","definition":"the amount of matter in an object","examples":[{"en":"The instrument measures the sample's mass.","zh":"仪器测量样本的质量。"},{"en":"Mass remains the same when location changes.","zh":"位置改变时质量保持不变。"}]},{"pos":"n.","meaning":"群众;大众（常用复数）","definition":"ordinary people considered collectively","examples":[{"en":"The speech appealed to the masses.","zh":"演讲吸引了大众。"},{"en":"Cheap printing brought books to the masses.","zh":"廉价印刷让大众能接触到书籍。"}]},{"pos":"v.","meaning":"聚集;集结","definition":"to gather in a large group","examples":[{"en":"Protesters massed outside the building.","zh":"抗议者聚集在大楼外。"},{"en":"Clouds massed over the hills.","zh":"云团聚集在山丘上空。"}]}],"massive":[{"pos":"adj.","meaning":"巨大厚重的；粗大的","definition":"very large and heavy","examples":[{"en":"Massive stone pillars support the roof.","zh":"巨大的石柱支撑屋顶。"},{"en":"The ship struck a massive block of ice.","zh":"船撞上了一大块冰。"}]},{"pos":"adj.","meaning":"大量的；大规模的","definition":"very great in amount or extent","examples":[{"en":"The project requires massive investment.","zh":"项目需要巨额投资。"},{"en":"The decision triggered massive public interest.","zh":"这一决定引起了公众的极大关注。"}]}],"mastercard":[{"pos":"n.","meaning":"万事达卡","definition":"A payment card using the Mastercard network.","examples":[{"en":"The hotel accepts Mastercard for room payments.","zh":"酒店接受用万事达卡支付房费。"},{"en":"She used her Mastercard to buy the train tickets.","zh":"她用万事达卡购买了火车票。"}]}],"mastery":[{"pos":"n.","meaning":"精通;熟练掌握","definition":"great knowledge or skill","examples":[{"en":"Her playing shows mastery of the instrument.","zh":"她的演奏表明已熟练掌握这件乐器。"},{"en":"Mastery of a language requires sustained practice.","zh":"精通语言需要持续练习。"}]},{"pos":"n.","meaning":"控制;支配","definition":"complete control over something","examples":[{"en":"He struggled to regain mastery of his emotions.","zh":"他努力重新控制自己的情绪。"},{"en":"The victory gave them mastery of the sea routes.","zh":"胜利使他们控制了海上航线。"}]}],"match":[{"pos":"n.","meaning":"火柴","definition":"a small stick used to start a flame","examples":[{"en":"He lit the candle with a match.","zh":"他用火柴点燃蜡烛。"},{"en":"Keep the matches dry.","zh":"保持火柴干燥。"}]},{"pos":"n.","meaning":"比赛","definition":"a sports contest","examples":[{"en":"The match ended in a draw.","zh":"比赛以平局结束。"},{"en":"We watched a tennis match.","zh":"我们看了一场网球比赛。"}]},{"pos":"n.","meaning":"对手；相配的人或事物","definition":"someone or something equal or suitable","examples":[{"en":"She finally met her match in the final.","zh":"她终于在决赛中遇到了劲敌。"},{"en":"The curtains are a good match for the walls.","zh":"窗帘与墙面很相配。"}]},{"pos":"v.","meaning":"匹配；相称；比得上","definition":"to be equal or suitable together","examples":[{"en":"Her shoes match her bag.","zh":"她的鞋与包很搭。"},{"en":"The results matched our expectations.","zh":"结果符合我们的预期。"}]}],"mate":[{"pos":"v.","meaning":"交配；使配种","definition":"To come together for reproduction or pair animals for breeding.","examples":[{"en":"The birds return to the island to mate.","zh":"这些鸟返回岛上交配。"},{"en":"The farmer carefully selected which animals to mate.","zh":"农民仔细挑选了用于配种的动物。"}]},{"pos":"n.","meaning":"配偶；交配对象","definition":"An animal's sexual or breeding partner.","examples":[{"en":"The bird called repeatedly to attract a mate.","zh":"这只鸟反复鸣叫，以吸引配偶。"},{"en":"The male stayed near its mate during nesting.","zh":"筑巢期间，雄鸟一直待在配偶附近。"}]},{"pos":"n.","meaning":"伙伴；朋友","definition":"A friend or companion.","examples":[{"en":"He met his old school mates at the reunion.","zh":"他在聚会上见到了老同学。"},{"en":"My flatmate is also a close mate from university.","zh":"我的室友也是大学时的好友。"}]},{"pos":"n.","meaning":"大副；副船长","definition":"An officer on a merchant ship below the captain.","examples":[{"en":"The first mate supervised the loading of the cargo.","zh":"大副监督货物装船。"},{"en":"The captain asked the mate to take the next watch.","zh":"船长让大副接下一班值勤。"}]}],"material":[{"pos":"n.","meaning":"材料;物料","definition":"a substance used to make things","examples":[{"en":"The roof uses recycled material.","zh":"屋顶使用回收材料。"},{"en":"Choose a material that resists moisture.","zh":"选择一种耐潮的材料。"}]},{"pos":"n.","meaning":"资料;素材","definition":"information used for study or creative work","examples":[{"en":"The interviews provided material for her book.","zh":"采访为她的书提供了素材。"},{"en":"Students can download the course material.","zh":"学生可以下载课程资料。"}]},{"pos":"adj.","meaning":"物质的","definition":"relating to physical possessions or substances","examples":[{"en":"Their material needs were modest.","zh":"他们的物质需求很少。"},{"en":"The study examines material culture.","zh":"研究考察物质文化。"}]},{"pos":"adj.","meaning":"重要的;实质性的","definition":"important enough to affect a decision","examples":[{"en":"The new evidence is material to the case.","zh":"新证据对案件十分重要。"},{"en":"There was no material change in the results.","zh":"结果没有实质性变化。"}]}],"materialistic":[{"pos":"adj.","meaning":"物质至上的；重视物质享受的","definition":"placing great importance on money and possessions","examples":[{"en":"The novel criticises a materialistic lifestyle.","zh":"小说批评物质至上的生活方式。"},{"en":"She rejected her friends' materialistic values.","zh":"她不认同朋友们重视物质享受的价值观。"}]},{"pos":"adj.","meaning":"唯物主义的","definition":"relating to the view that reality is fundamentally material","examples":[{"en":"The philosopher proposed a materialistic account of mind.","zh":"哲学家提出了一种关于心灵的唯物主义解释。"},{"en":"The essay compares materialistic and idealistic theories.","zh":"文章比较了唯物主义与唯心主义理论。"}]}],"maternal":[{"pos":"adj.","meaning":"母亲的；母爱的","definition":"Relating to a mother or the qualities of motherly care.","examples":[{"en":"The clinic provides maternal healthcare.","zh":"诊所提供孕产妇医疗服务。"},{"en":"She showed maternal concern for the younger children.","zh":"她对年幼孩子表现出母亲般的关怀。"}]},{"pos":"adj.","meaning":"母系的；母亲一方的","definition":"Related through one's mother.","examples":[{"en":"His maternal grandmother taught him to cook.","zh":"他的外祖母教他做饭。"},{"en":"The family traced its maternal ancestry to a coastal village.","zh":"这个家族追溯出母系祖先来自一座沿海村庄。"}]}],"mattress":[{"pos":"n.","meaning":"床垫","definition":"a padded surface placed on a bed","examples":[{"en":"The mattress was too soft for him.","zh":"床垫对他来说太软。"},{"en":"They carried the new mattress upstairs.","zh":"他们把新床垫搬上楼。"}]}],"mature":[{"pos":"adj.","meaning":"成熟的；发育完全的","definition":"fully developed or grown","examples":[{"en":"The orchard contains mature apple trees.","zh":"果园里有成年的苹果树。"},{"en":"The cheese has a mature flavour.","zh":"奶酪有熟成的风味。"}]},{"pos":"adj.","meaning":"成熟稳重的；深思熟虑的","definition":"showing good judgment and emotional development","examples":[{"en":"She gave a mature response to criticism.","zh":"她成熟地回应了批评。"},{"en":"The decision followed mature consideration.","zh":"决定经过了深思熟虑。"}]},{"pos":"v.","meaning":"成熟；使成熟","definition":"to develop fully over time","examples":[{"en":"The fruit matures in late summer.","zh":"果实在夏末成熟。"},{"en":"His writing matured with experience.","zh":"他的写作随经验增长而成熟。"}]}],"maturity":[{"pos":"n.","meaning":"成熟；成熟期；完善","definition":"The state of being fully developed physically or mentally.","examples":[{"en":"The trees take many years to reach maturity.","zh":"这些树需要很多年才能成熟。"},{"en":"She handled the disagreement with impressive maturity.","zh":"她处理分歧的方式十分成熟。"}]},{"pos":"n.","meaning":"到期；偿付日期","definition":"The date when a financial obligation becomes due.","examples":[{"en":"The bond reaches maturity next year.","zh":"这只债券明年到期。"},{"en":"The deposit can be withdrawn at maturity.","zh":"这笔存款到期时可以支取。"}]}],"maximise":[{"pos":"v.","meaning":"最大化;充分利用","definition":"to increase to the greatest possible amount","examples":[{"en":"The design maximises natural light.","zh":"设计最大限度地利用自然光。"},{"en":"Plan your route to maximise study time.","zh":"规划路线以充分利用学习时间。"}]}],"maximum":[{"pos":"n.","meaning":"最大值；上限","definition":"the greatest possible amount","examples":[{"en":"The room holds a maximum of forty people.","zh":"房间最多容纳四十人。"},{"en":"Keep noise to the permitted maximum or below.","zh":"把噪声控制在允许上限以内。"}]},{"pos":"adj.","meaning":"最大的；最高的","definition":"as great as allowed or possible","examples":[{"en":"The maximum speed is clearly posted.","zh":"最高限速标示得很清楚。"},{"en":"The design provides maximum storage.","zh":"设计提供了最大的储物空间。"}]}],"meadow":[{"pos":"n.","meaning":"草地；牧草地","definition":"A field of grass, often containing wildflowers.","examples":[{"en":"Wildflowers covered the meadow in spring.","zh":"春天，野花开遍草地。"},{"en":"We crossed a meadow where sheep were grazing.","zh":"我们穿过一片羊正在吃草的草地。"}]}],"meagre":[{"pos":"adj.","meaning":"少量的;不足的;贫乏的","definition":"too small in amount or quality","examples":[{"en":"They survived on meagre rations.","zh":"他们靠少量配给食物活下来。"},{"en":"The evidence offered meagre support for the claim.","zh":"证据对该主张的支持很有限。"}]}],"meaningful":[{"pos":"adj.","meaning":"有意义的；有价值的；有明确作用的","definition":"having significance or useful purpose","examples":[{"en":"She wanted more meaningful work.","zh":"她想要更有意义的工作。"},{"en":"The data showed a meaningful difference.","zh":"数据显示了有意义的差异。"}]}],"meantime":[{"pos":"n.","meaning":"其间；这段时间","definition":"The period between one event and another.","examples":[{"en":"The repairs will take a week; in the meantime, we can stay with friends.","zh":"维修需要一周；在此期间，我们可以住在朋友家。"},{"en":"In the meantime, please keep the receipts.","zh":"在此期间，请保留收据。"}]},{"pos":"adv.","meaning":"与此同时；在此期间","definition":"During the time until another event happens.","examples":[{"en":"The soup was simmering; meantime, she prepared the salad.","zh":"汤正在煨着；与此同时，她准备沙拉。"},{"en":"The train was delayed, so meantime we explored the station shops.","zh":"火车晚点了，所以这期间我们逛了车站商店。"}]}],"meanwhile":[{"pos":"adv.","meaning":"与此同时;在此期间","definition":"at the same time or during the interval","examples":[{"en":"The soup simmered; meanwhile, she prepared the salad.","zh":"汤炖着，与此同时她准备沙拉。"},{"en":"The bridge is closed. Meanwhile, use the ferry.","zh":"桥关闭了，在此期间请乘渡轮。"}]}],"mechanic":[{"pos":"n.","meaning":"机修工；机械技师","definition":"a person who repairs machinery","examples":[{"en":"The mechanic repaired the brakes.","zh":"机修工修好了刹车。"},{"en":"A mechanic inspected the engine.","zh":"技师检查了发动机。"}]},{"pos":"n.","meaning":"力学；机械学（用 mechanics）","definition":"the study of forces and motion","examples":[{"en":"She studied classical mechanics.","zh":"她学习了经典力学。"},{"en":"The course explains the mechanics of moving bodies.","zh":"课程讲解运动物体的力学原理。"}]}],"mechanical":[{"pos":"adj.","meaning":"机械的；机械制造的","definition":"Relating to machines or their operation.","examples":[{"en":"The delay was caused by a mechanical fault.","zh":"延误是机械故障造成的。"},{"en":"He studied mechanical engineering at university.","zh":"他在大学学习机械工程。"}]},{"pos":"adj.","meaning":"机械呆板的；习惯性的","definition":"Done automatically without thought or feeling.","examples":[{"en":"She gave a mechanical smile and returned to work.","zh":"她机械地笑了笑，继续工作。"},{"en":"The task had become a mechanical routine.","zh":"这项任务已变成机械重复的日常程序。"}]},{"pos":"adj.","meaning":"体力操作的；物理作用的","definition":"Involving physical force or movement rather than mental or chemical processes.","examples":[{"en":"The workshop combines design work with mechanical tasks such as cutting and lifting.","zh":"工作坊把设计与切割、搬运等体力操作相结合。"},{"en":"Mechanical cleaning removed the dirt without chemicals.","zh":"物理清洁在不用化学品的情况下清除了污垢。"}]}],"mechanism":[{"pos":"n.","meaning":"机械装置","definition":"a set of parts working together","examples":[{"en":"The clock's mechanism needs cleaning.","zh":"钟的机械装置需要清洁。"},{"en":"A spring operates the locking mechanism.","zh":"弹簧驱动锁定装置。"}]},{"pos":"n.","meaning":"机制;机理;办法","definition":"a process or system producing an effect","examples":[{"en":"Scientists studied the mechanism of the reaction.","zh":"科学家研究了反应机理。"},{"en":"The agreement provides a mechanism for resolving disputes.","zh":"协议提供了解决争议的机制。"}]}],"medical":[{"pos":"adj.","meaning":"医学的；医疗的","definition":"relating to medicine or healthcare","examples":[{"en":"The village needs better medical facilities.","zh":"村庄需要更好的医疗设施。"},{"en":"She is studying medical history.","zh":"她正在研究医学史。"}]},{"pos":"adj.","meaning":"内科的；药物治疗的","definition":"relating to treatment with medicine rather than surgery","examples":[{"en":"The team considered medical and surgical options.","zh":"团队考虑了内科和外科治疗方案。"},{"en":"The ward provides medical care for nonsurgical patients.","zh":"病房为非手术患者提供内科照护。"}]}],"medication":[{"pos":"n.","meaning":"药物；药品；药物治疗","definition":"Medicine used to treat illness.","examples":[{"en":"The nurse recorded the patient's medication.","zh":"护士记录了患者的用药情况。"},{"en":"Keep medication out of children's reach.","zh":"将药物放在儿童接触不到的地方。"}]}],"medieval":[{"pos":"adj.","meaning":"中世纪的","definition":"relating to the Middle Ages","examples":[{"en":"The town retains its medieval walls.","zh":"城镇保留着中世纪城墙。"},{"en":"She researches medieval manuscripts.","zh":"她研究中世纪手稿。"}]}],"mediocre":[{"pos":"adj.","meaning":"平庸的；不怎么样的","definition":"of ordinary or disappointing quality","examples":[{"en":"The restaurant served mediocre food.","zh":"餐馆提供的食物很一般。"},{"en":"The film received mediocre reviews.","zh":"电影得到的评价平平。"}]}],"mediterranean":[{"pos":"adj.","meaning":"地中海的；地中海式的","definition":"Relating to the Mediterranean Sea or surrounding region.","examples":[{"en":"Olive trees thrive in a Mediterranean climate.","zh":"橄榄树在地中海气候中生长旺盛。"},{"en":"The restaurant serves Mediterranean dishes.","zh":"这家餐厅供应地中海风味菜肴。"}]},{"pos":"n.","meaning":"地中海","definition":"The sea between southern Europe, northern Africa, and western Asia.","examples":[{"en":"The ship crossed the Mediterranean in calm weather.","zh":"船在风平浪静的天气中横渡了地中海。"},{"en":"Many ancient trading routes passed through the Mediterranean.","zh":"许多古代贸易路线经过地中海。"}]}],"medium":[{"pos":"n.","meaning":"媒介;手段;传播工具","definition":"a means of communicating or achieving something","examples":[{"en":"Radio remained an important medium for news.","zh":"广播仍是重要新闻媒介。"},{"en":"Photography became her preferred artistic medium.","zh":"摄影成为她偏爱的艺术表达方式。"}]},{"pos":"n.","meaning":"介质;培养基;生存环境","definition":"a substance through which something travels or grows","examples":[{"en":"Sound travels through a medium such as air.","zh":"声音通过空气等介质传播。"},{"en":"The bacteria grew in a nutrient medium.","zh":"细菌在营养培养基中生长。"}]},{"pos":"adj.","meaning":"中等的","definition":"between small and large or low and high","examples":[{"en":"I need a medium size.","zh":"我需要中号。"},{"en":"Cook the onions over medium heat.","zh":"用中火烹炒洋葱。"}]}],"megacity":[{"pos":"n.","meaning":"超大城市（通常指人口至少1000万的城市地区）","definition":"a very large urban area, usually with at least ten million people","examples":[{"en":"The report compares transport in several megacities.","zh":"报告比较了几个超大城市的交通。"},{"en":"Rapid growth turned the region into a megacity.","zh":"迅速增长使这个地区成为超大城市。"}]}],"melatonin":[{"pos":"n.","meaning":"褪黑激素；褪黑素","definition":"A hormone involved in regulating the sleep-wake cycle.","examples":[{"en":"The study measured melatonin levels during the evening.","zh":"研究测量了晚间的褪黑素水平。"},{"en":"The lecture explained melatonin's role in the body's daily rhythms.","zh":"讲座解释了褪黑素在人体昼夜节律中的作用。"}]}],"melt":[{"pos":"v.","meaning":"融化;熔化","definition":"to become or make liquid through heat","examples":[{"en":"The ice melted in the sun.","zh":"冰在阳光下融化了。"},{"en":"Melt the butter in a small pan.","zh":"在小锅中融化黄油。"}]},{"pos":"v.","meaning":"逐渐消失;使心软","definition":"to disappear gradually or become emotionally softened","examples":[{"en":"Her anger melted when the child apologised.","zh":"孩子道歉后，她的怒气消散了。"},{"en":"The crowd melted away after sunset.","zh":"日落后人群渐渐散去。"}]}],"membership":[{"pos":"n.","meaning":"会员身份；会员资格","definition":"the state of belonging to an organisation","examples":[{"en":"Annual membership includes free entry.","zh":"年度会员资格包含免费入场。"},{"en":"She renewed her gym membership.","zh":"她续办了健身房会员。"}]},{"pos":"n.","meaning":"全体会员；会员人数","definition":"all the members of an organisation","examples":[{"en":"The club's membership has doubled.","zh":"俱乐部的会员人数翻了一倍。"},{"en":"The committee consulted the membership.","zh":"委员会征询了全体会员意见。"}]}],"memorable":[{"pos":"adj.","meaning":"难忘的；值得记住的","definition":"Easy to remember because it is special or striking.","examples":[{"en":"The trip ended with a memorable night under the stars.","zh":"旅行以一个在星空下度过的难忘夜晚结束。"},{"en":"The speaker used a memorable example to explain the idea.","zh":"演讲者用了一个令人难忘的例子来解释这个概念。"}]}],"memorandum":[{"pos":"n.","meaning":"备忘录;摘要","definition":"a written note recording information or an agreement","examples":[{"en":"She sent a memorandum to all department heads.","zh":"她给所有部门主管发了一份备忘录。"},{"en":"The memorandum summarised the meeting's decisions.","zh":"备忘录概括了会议决定。"}]}],"memorise":[{"pos":"v.","meaning":"记住；熟记","definition":"to learn so something can be recalled exactly","examples":[{"en":"She memorised the poem.","zh":"她背熟了这首诗。"},{"en":"The actors must memorise their lines.","zh":"演员必须记熟台词。"}]}],"menace":[{"pos":"n.","meaning":"威胁；危险；危险的人或物","definition":"Someone or something likely to cause harm.","examples":[{"en":"Polluted water is a menace to local wildlife.","zh":"受污染的水威胁着当地野生生物。"},{"en":"The loose dog became a menace to cyclists.","zh":"这只无人牵管的狗成了骑车人的威胁。"}]},{"pos":"v.","meaning":"威胁；危及","definition":"To threaten harm or danger.","examples":[{"en":"Rising water menaced the houses beside the river.","zh":"不断上涨的河水威胁着河边房屋。"},{"en":"Armed groups menaced travellers on the road.","zh":"武装团伙威胁着路上的旅行者。"}]}],"mental":[{"pos":"adj.","meaning":"心理的；精神的；智力的","definition":"relating to the mind","examples":[{"en":"Long working hours can affect mental health.","zh":"长时间工作可能影响心理健康。"},{"en":"The charity provides mental health support.","zh":"这个慈善机构提供心理健康支持。"},{"en":"Adequate sleep improves mental concentration.","zh":"充足睡眠能改善精神专注力。"}]}],"mention":[{"pos":"v.","meaning":"提到；说起","definition":"to refer to something briefly","examples":[{"en":"He mentioned the delay in his email.","zh":"他在邮件中提到了延误。"},{"en":"Please mention any dietary requirements.","zh":"请说明任何饮食要求。"}]},{"pos":"n.","meaning":"提及；简短的说明","definition":"a brief reference to something","examples":[{"en":"The report makes no mention of costs.","zh":"报告没有提到成本。"},{"en":"Her name received a special mention.","zh":"她的名字被特别提及。"}]}],"mentor":[{"pos":"n.","meaning":"导师；指导者；顾问","definition":"An experienced person who advises and supports someone less experienced.","examples":[{"en":"A senior engineer became her mentor.","zh":"一位资深工程师成了她的导师。"},{"en":"Each trainee meets a mentor once a week.","zh":"每位实习生每周与一名指导者会面一次。"}]}],"merchandising":[{"pos":"n.","meaning":"商品销售策划;促销;商品陈列","definition":"activities used to promote and sell goods","examples":[{"en":"Better merchandising increased shop sales.","zh":"更好的商品销售策划提高了门店销量。"},{"en":"The course covers pricing and visual merchandising.","zh":"课程涵盖定价和视觉商品陈列。"}]}],"mercury":[{"pos":"n.","meaning":"汞；水银","definition":"a metallic element liquid at ordinary room temperature","examples":[{"en":"The old thermometer contained mercury.","zh":"旧温度计含有水银。"},{"en":"The laboratory tested the water for mercury.","zh":"实验室检测了水中的汞。"}]}],"mere":[{"pos":"adj.","meaning":"仅仅的；只不过的；纯粹的","definition":"Used to emphasise that something is small, simple, or nothing more.","examples":[{"en":"The station is a mere five minutes away.","zh":"车站距离这里只有五分钟路程。"},{"en":"The mere thought of the interview made him nervous.","zh":"仅仅想到面试就让他紧张。"}]}],"merely":[{"pos":"adv.","meaning":"仅仅;只不过","definition":"only and nothing more","examples":[{"en":"I was merely asking a question.","zh":"我只是问一个问题。"},{"en":"The delay was merely temporary.","zh":"延误只是暂时的。"}]}],"merge":[{"pos":"v.","meaning":"合并；融合","definition":"to combine into one","examples":[{"en":"The two companies merged last year.","zh":"两家公司去年合并了。"},{"en":"The path merges with a wider road.","zh":"小路汇入一条更宽的道路。"}]}],"mess":[{"pos":"n.","meaning":"凌乱；混乱；一团糟","definition":"A dirty, untidy, or confused state.","examples":[{"en":"The kitchen was a mess after the party.","zh":"聚会后，厨房一片狼藉。"},{"en":"The missing records left the accounts in a mess.","zh":"记录缺失使账目乱成一团。"}]},{"pos":"v.","meaning":"弄乱；弄糟","definition":"To make something untidy or spoil it.","examples":[{"en":"The wind messed up her hair.","zh":"风吹乱了她的头发。"},{"en":"One wrong number messed up the calculation.","zh":"一个错误数字把计算弄错了。"}]}],"metaphor":[{"pos":"n.","meaning":"隐喻;暗喻","definition":"a comparison describing one thing as another","examples":[{"en":"The poet uses winter as a metaphor for old age.","zh":"诗人用冬天隐喻晚年。"},{"en":"Her speech relied on a journey metaphor.","zh":"她的演讲运用了旅程的隐喻。"}]}],"metaphorical":[{"pos":"adj.","meaning":"比喻的；隐喻的","definition":"using figurative comparison rather than literal meaning","examples":[{"en":"The title has a metaphorical meaning.","zh":"标题有比喻意义。"},{"en":"Her description of life as a journey is metaphorical.","zh":"她将人生描述为旅程是一种隐喻。"}]}],"meteorology":[{"pos":"n.","meaning":"气象学","definition":"The scientific study of the atmosphere and weather.","examples":[{"en":"She studied meteorology before becoming a weather forecaster.","zh":"她成为天气预报员前学习过气象学。"},{"en":"The course introduces basic meteorology and cloud formation.","zh":"这门课程介绍基础气象学和云的形成。"}]}],"methane":[{"pos":"n.","meaning":"甲烷;沼气的主要成分","definition":"a flammable gas with the formula CH4","examples":[{"en":"The sensor detected methane near the pipe.","zh":"传感器检测到管道附近有甲烷。"},{"en":"Decomposing waste can release methane.","zh":"废物分解会释放甲烷。"}]}],"method":[{"pos":"n.","meaning":"方法","definition":"a way of doing something","examples":[{"en":"This method is suitable for comparing prices.","zh":"这种方法适合比较价格。"},{"en":"Teachers should choose a method that suits their students.","zh":"教师应选择适合学生的方法。"},{"en":"The report explains the method used to collect data.","zh":"报告解释了收集数据所用的方法。"}]}],"metro":[{"pos":"n.","meaning":"地铁；地下铁路","definition":"An urban railway system, usually partly or wholly underground.","examples":[{"en":"We took the metro to the city centre.","zh":"我们乘地铁前往市中心。"},{"en":"The new metro line connects the airport with the university.","zh":"新地铁线路连接机场与大学。"}]}],"microbiology":[{"pos":"n.","meaning":"微生物学","definition":"the scientific study of microorganisms","examples":[{"en":"She specialises in microbiology.","zh":"她专攻微生物学。"},{"en":"The microbiology laboratory identified the bacterium.","zh":"微生物实验室鉴定了这种细菌。"}]}],"microcosm":[{"pos":"n.","meaning":"缩影；小天地","definition":"a small system representing a larger one","examples":[{"en":"The school is a microcosm of society.","zh":"学校是社会的缩影。"},{"en":"The island offered a microcosm of regional wildlife.","zh":"岛上呈现了当地野生生物的缩影。"}]}],"microprocessor":[{"pos":"n.","meaning":"微处理器","definition":"A small electronic chip that performs a computer's processing operations.","examples":[{"en":"A microprocessor controls the washing cycle.","zh":"微处理器控制洗涤程序。"},{"en":"The engineer replaced the damaged microprocessor.","zh":"工程师更换了损坏的微处理器。"}]}],"microscope":[{"pos":"n.","meaning":"显微镜","definition":"an instrument making tiny objects appear larger","examples":[{"en":"Examine the cells under a microscope.","zh":"在显微镜下观察细胞。"},{"en":"The microscope revealed details invisible to the eye.","zh":"显微镜揭示了肉眼看不见的细节。"}]}],"midst":[{"pos":"n.","meaning":"中间；当中","definition":"the middle of a place, group, or situation","examples":[{"en":"She stood in the midst of the crowd.","zh":"她站在人群之中。"},{"en":"We moved house in the midst of winter.","zh":"我们在隆冬搬了家。"}]}],"migrant":[{"pos":"n.","meaning":"移民；移居者；流动人口","definition":"A person who moves to another place to live or work.","examples":[{"en":"The town attracted migrants seeking factory jobs.","zh":"这座城镇吸引了寻找工厂工作的外来人口。"},{"en":"Seasonal migrants help with the fruit harvest.","zh":"季节性流动工人帮助采收水果。"}]},{"pos":"n.","meaning":"迁徙动物；候鸟","definition":"An animal that moves between regions at different times of year.","examples":[{"en":"The wetlands provide shelter for winter migrants.","zh":"湿地为冬季候鸟提供栖息地。"},{"en":"Birdwatchers recorded several rare migrants along the coast.","zh":"观鸟者在沿海记录到了几种稀有候鸟。"}]}],"migrate":[{"pos":"v.","meaning":"迁徙;迁移;移居","definition":"to move from one region or system to another","examples":[{"en":"The birds migrate south each autumn.","zh":"鸟类每年秋天向南迁徙。"},{"en":"Many families migrated to industrial cities.","zh":"许多家庭迁居工业城市。"}]}],"migration":[{"pos":"n.","meaning":"迁移；移居","definition":"movement from one place to live in another","examples":[{"en":"Migration from villages to cities can affect rural services.","zh":"从乡村向城市的迁移会影响农村服务。"},{"en":"Economic opportunities are one cause of migration.","zh":"经济机会是人口迁移的一个原因。"},{"en":"The report examines patterns of international migration.","zh":"这份报告研究国际人口迁移的模式。"}]},{"pos":"n.","meaning":"迁徙（动物）","definition":"the seasonal movement of animals between regions","examples":[{"en":"The wetland is an important stop during bird migration.","zh":"这片湿地是鸟类迁徙的重要停歇地。"},{"en":"Researchers tracked the whales' annual migration.","zh":"研究人员追踪了鲸鱼每年的迁徙。"}]}],"migratory":[{"pos":"adj.","meaning":"迁徙的；迁移的；流动的","definition":"Regularly moving between places or regions.","examples":[{"en":"Migratory birds rest here during their long journeys.","zh":"候鸟在漫长旅途中在这里歇息。"},{"en":"The study followed migratory workers between farming regions.","zh":"研究追踪了在农业地区之间流动的工人。"}]}],"mild":[{"pos":"adj.","meaning":"温和的;温柔的","definition":"gentle in behaviour or conditions","examples":[{"en":"She answered in a mild voice.","zh":"她以温柔的声音作答。"},{"en":"The region enjoys mild winters.","zh":"该地区冬季温和。"}]},{"pos":"adj.","meaning":"轻微的;不强烈的","definition":"not severe or strong","examples":[{"en":"He felt mild discomfort after the exercise.","zh":"锻炼后他感到轻微不适。"},{"en":"This cheese has a mild flavour.","zh":"这种奶酪味道清淡。"}]}],"milestone":[{"pos":"n.","meaning":"里程碑；重要阶段","definition":"an event marking significant progress","examples":[{"en":"Graduation was a major milestone.","zh":"毕业是一个重要里程碑。"},{"en":"The project reached its first milestone.","zh":"项目达到了第一个重要阶段。"}]},{"pos":"n.","meaning":"里程标","definition":"a roadside marker showing distance","examples":[{"en":"An old milestone stood beside the road.","zh":"路旁立着一块旧里程碑。"},{"en":"The inscription on the milestone was barely readable.","zh":"里程标上的铭文几乎无法辨认。"}]}],"militant":[{"pos":"adj.","meaning":"激进的；好斗的；斗争性强的","definition":"Using forceful or confrontational methods to support a cause.","examples":[{"en":"The union adopted a more militant approach to the dispute.","zh":"工会对争端采取了更强硬的做法。"},{"en":"The speaker's militant tone worried some supporters.","zh":"演讲者激进的语气令部分支持者担忧。"}]},{"pos":"n.","meaning":"激进分子；好斗者","definition":"A person who strongly or aggressively supports a cause.","examples":[{"en":"Several militants rejected the proposed compromise.","zh":"几名激进分子拒绝了拟议中的妥协。"},{"en":"The movement included both moderates and militants.","zh":"这场运动既有温和派，也有激进派。"}]}],"military":[{"pos":"adj.","meaning":"军事的;军队的","definition":"relating to armed forces","examples":[{"en":"The bridge has military importance.","zh":"这座桥具有军事重要性。"},{"en":"The museum displays military uniforms.","zh":"博物馆展出军装。"}]},{"pos":"n.","meaning":"军队","definition":"the armed forces of a country","examples":[{"en":"The military assisted with flood relief.","zh":"军队协助抗洪救灾。"},{"en":"She joined the military after college.","zh":"她大学毕业后参军了。"}]}],"millennium":[{"pos":"n.","meaning":"一千年；千年期","definition":"a period of one thousand years","examples":[{"en":"The settlement existed for a millennium.","zh":"聚落存在了一千年。"},{"en":"The museum examines change over two millennia.","zh":"博物馆考察两千年间的变化。"}]},{"pos":"n.","meaning":"太平盛世；理想时代","definition":"an imagined future age of peace and happiness","examples":[{"en":"The reformers dreamed of a social millennium.","zh":"改革者梦想着一个社会太平盛世。"},{"en":"The novel imagines a millennium without poverty.","zh":"小说设想了一个没有贫困的理想时代。"}]}],"mime":[{"pos":"v.","meaning":"用动作模仿；做哑剧表演","definition":"To express an action or idea through movements without speech.","examples":[{"en":"She mimed opening an enormous door.","zh":"她用动作模仿打开一扇巨大的门。"},{"en":"The children mimed different animals for the class to guess.","zh":"孩子们模仿不同动物，让全班猜。"}]},{"pos":"n.","meaning":"哑剧；哑剧表演","definition":"A performance that communicates through actions rather than speech.","examples":[{"en":"The scene was performed entirely in mime.","zh":"这一场完全以哑剧形式表演。"},{"en":"We watched a short mime about a lost traveller.","zh":"我们看了一段关于迷路旅人的短哑剧。"}]},{"pos":"n.","meaning":"哑剧演员","definition":"A performer who uses silent movements to communicate.","examples":[{"en":"A mime entertained the crowd in the square.","zh":"一位哑剧演员在广场上为人群表演。"},{"en":"The mime made an invisible wall seem real.","zh":"这位哑剧演员把看不见的墙表演得像真的一样。"}]}],"mineral":[{"pos":"n.","meaning":"矿物;矿产","definition":"a naturally occurring inorganic substance","examples":[{"en":"Quartz is a common mineral.","zh":"石英是一种常见矿物。"},{"en":"The region is rich in valuable minerals.","zh":"该地区富含珍贵矿产。"}]}],"mingle":[{"pos":"v.","meaning":"混合；混杂","definition":"to mix together","examples":[{"en":"The smell of coffee mingled with fresh bread.","zh":"咖啡香与新鲜面包香混合在一起。"},{"en":"Laughter mingled with music from the stage.","zh":"笑声与舞台传来的音乐交织。"}]},{"pos":"v.","meaning":"交际；混在人群中","definition":"to move among people and talk to them","examples":[{"en":"Guests mingled before dinner.","zh":"宾客在晚餐前相互交谈。"},{"en":"She mingled with the audience after the show.","zh":"演出后她与观众交流。"}]}],"minimal":[{"pos":"adj.","meaning":"极少的；最低限度的；最小的","definition":"Very small in amount or no more than necessary.","examples":[{"en":"The repairs caused minimal disruption.","zh":"维修造成的干扰很小。"},{"en":"The course assumes only minimal knowledge of computers.","zh":"这门课程只要求具备最基本的计算机知识。"}]}],"minimise":[{"pos":"v.","meaning":"尽量减少;使最小化","definition":"to reduce to the smallest possible amount","examples":[{"en":"Careful planning minimises waste.","zh":"仔细规划能尽量减少浪费。"},{"en":"The redesign minimised noise in the cabin.","zh":"重新设计最大限度地降低了舱内噪声。"}]}],"minimum":[{"pos":"n.","meaning":"最低限度；最小值","definition":"the smallest possible or permitted amount","examples":[{"en":"Keep waste to a minimum.","zh":"尽量减少浪费。"},{"en":"The course requires a minimum of ten participants.","zh":"课程至少需要十位参加者。"}]},{"pos":"adj.","meaning":"最低的；最小的","definition":"as small as possible or allowed","examples":[{"en":"The minimum age is sixteen.","zh":"最低年龄是十六岁。"},{"en":"The task needs minimum supervision.","zh":"这项任务只需极少监督。"}]}],"minister":[{"pos":"n.","meaning":"部长；大臣","definition":"A senior government official responsible for a department.","examples":[{"en":"The education minister visited the new school.","zh":"教育部长参观了新学校。"},{"en":"The minister announced changes to transport funding.","zh":"部长宣布调整交通资金安排。"}]},{"pos":"n.","meaning":"外交公使；外交使节","definition":"A diplomatic representative below the rank of ambassador.","examples":[{"en":"The minister delivered a formal message to the foreign office.","zh":"公使向外交部门递交了一份正式照会。"},{"en":"The country appointed a minister to its overseas mission.","zh":"该国向驻外使团任命了一位公使。"}]},{"pos":"n.","meaning":"牧师","definition":"A religious leader in some Christian churches.","examples":[{"en":"The minister welcomed the congregation.","zh":"牧师欢迎会众到来。"},{"en":"A local minister conducted the wedding ceremony.","zh":"一位当地牧师主持了婚礼。"}]}],"ministry":[{"pos":"n.","meaning":"政府部门;部","definition":"a government department","examples":[{"en":"The education ministry issued new guidance.","zh":"教育部发布了新指南。"},{"en":"She works for the ministry of transport.","zh":"她在交通部工作。"}]}],"minority":[{"pos":"n.","meaning":"少数；少数派","definition":"a group smaller than half of a larger group","examples":[{"en":"Only a minority opposed the plan.","zh":"只有少数人反对计划。"},{"en":"She found herself in the minority.","zh":"她发现自己属于少数派。"}]},{"pos":"n.","meaning":"少数群体；少数民族","definition":"a group distinct from the larger population","examples":[{"en":"The programme supports minority languages.","zh":"项目支持少数民族语言。"},{"en":"Several minorities are represented on the council.","zh":"议会中有几个少数群体的代表。"}]}],"miracle":[{"pos":"n.","meaning":"奇迹；不可思议的事","definition":"An extraordinary event that seems impossible or divinely caused.","examples":[{"en":"It seemed a miracle that everyone survived the crash.","zh":"所有人都在事故中幸存，似乎是个奇迹。"},{"en":"The villagers regarded the unexpected recovery as a miracle.","zh":"村民们把这次出人意料的康复视为奇迹。"}]}],"miscellaneous":[{"pos":"adj.","meaning":"各种各样的;混杂的","definition":"consisting of different types","examples":[{"en":"The drawer holds miscellaneous tools.","zh":"抽屉里放着各种工具。"},{"en":"Set aside money for miscellaneous expenses.","zh":"留出一笔钱用于杂项开支。"}]}],"misconception":[{"pos":"n.","meaning":"误解；错误观念","definition":"an incorrect belief or understanding","examples":[{"en":"The lesson corrected a common misconception.","zh":"这节课纠正了一种常见误解。"},{"en":"She had a misconception about the course requirements.","zh":"她对课程要求有误解。"}]}],"miserable":[{"pos":"adj.","meaning":"痛苦的；悲惨的；难受的","definition":"Very unhappy or unpleasant.","examples":[{"en":"He felt miserable after losing his job.","zh":"失去工作后，他感到十分痛苦。"},{"en":"We spent a miserable night in the cold tent.","zh":"我们在寒冷的帐篷里度过了难熬的一夜。"}]}],"mishandle":[{"pos":"v.","meaning":"错误处理;粗暴操作","definition":"to deal with or handle badly","examples":[{"en":"The company mishandled the complaint.","zh":"公司错误处理了投诉。"},{"en":"The fragile vase broke after being mishandled.","zh":"脆弱花瓶因粗暴搬动而破碎。"}]}],"misinformation":[{"pos":"n.","meaning":"错误信息","definition":"false or inaccurate information","examples":[{"en":"Misinformation can spread quickly on social media.","zh":"错误信息可以在社交媒体上迅速传播。"},{"en":"Checking original sources helps people identify misinformation.","zh":"核查原始来源有助于识别错误信息。"},{"en":"Health misinformation may influence people's decisions.","zh":"健康方面的错误信息可能影响人们的决定。"}]}],"misjudge":[{"pos":"v.","meaning":"判断错误；误判","definition":"To form an inaccurate opinion or estimate.","examples":[{"en":"I misjudged the distance and arrived late.","zh":"我误判了距离，所以迟到了。"},{"en":"She realised that she had misjudged his intentions.","zh":"她意识到自己误解了他的意图。"}]}],"missile":[{"pos":"n.","meaning":"导弹;飞弹","definition":"a weapon flying toward a target","examples":[{"en":"The ship detected an approaching missile.","zh":"船探测到一枚接近的导弹。"},{"en":"The missile missed its intended target.","zh":"导弹未击中预定目标。"}]},{"pos":"n.","meaning":"投掷物;发射物","definition":"an object thrown or launched through the air","examples":[{"en":"Stones became missiles during the disturbance.","zh":"骚乱中石头被当作投掷物。"},{"en":"A loose roof tile flew like a missile.","zh":"一片松瓦像飞弹一样飞出。"}]}],"mission":[{"pos":"n.","meaning":"使命；任务","definition":"an important task or purpose","examples":[{"en":"The rescue mission lasted all night.","zh":"救援任务持续了一整夜。"},{"en":"The museum's mission is to preserve local history.","zh":"博物馆的使命是保存地方历史。"}]},{"pos":"n.","meaning":"代表团；使团","definition":"a group sent to perform an official task","examples":[{"en":"A trade mission visited the region.","zh":"一个贸易代表团访问了该地区。"},{"en":"The diplomatic mission returned home.","zh":"外交使团返回国内。"}]},{"pos":"n.","meaning":"传教活动；传教团","definition":"religious work intended to spread a faith","examples":[{"en":"The archive records the history of the mission.","zh":"档案记录了传教活动的历史。"},{"en":"The mission established a school beside the church.","zh":"传教团在教堂旁建立了学校。"}]}],"mite":[{"pos":"n.","meaning":"螨；螨虫","definition":"A tiny eight-legged animal related to spiders.","examples":[{"en":"The leaves were damaged by a tiny mite.","zh":"叶片受到了一种微小螨虫的损害。"},{"en":"The microscope revealed mites in the dust sample.","zh":"显微镜显示灰尘样本中有螨虫。"}]},{"pos":"n.","meaning":"极小量；一点点","definition":"A very small amount.","examples":[{"en":"The room felt a mite warmer after we closed the window.","zh":"关窗后，房间感觉稍微暖和了一点。"},{"en":"She added her mite to the community fund.","zh":"她为社区基金贡献了自己微薄的一份力量。"}]}],"mitigate":[{"pos":"v.","meaning":"减轻负面影响","definition":"to reduce the harmful effects of something","examples":[{"en":"Trees can help mitigate the effects of urban heat.","zh":"树木可以帮助减轻城市高温的影响。"},{"en":"Careful planning can mitigate the risks of the project.","zh":"周密规划可以减轻项目风险。"},{"en":"Training may mitigate the impact of job changes.","zh":"培训可能减轻岗位变化的影响。"}]}],"mixture":[{"pos":"n.","meaning":"混合物；混合","definition":"a combination of different things","examples":[{"en":"Stir the mixture until smooth.","zh":"搅拌混合物，直到均匀。"},{"en":"She felt a mixture of excitement and anxiety.","zh":"她既兴奋又焦虑。"}]}],"mock":[{"pos":"adj.","meaning":"模拟的；假的；假装的","definition":"Imitating something for practice, testing, or pretence.","examples":[{"en":"The students held a mock election.","zh":"学生们举行了一次模拟选举。"},{"en":"He bowed with mock seriousness.","zh":"他故作严肃地鞠了一躬。"}]},{"pos":"v.","meaning":"嘲笑；嘲弄；模仿取笑","definition":"To make fun of someone or something.","examples":[{"en":"The children were told not to mock anyone's accent.","zh":"孩子们被告知不要嘲笑任何人的口音。"},{"en":"The cartoon mocked the politician's extravagant promises.","zh":"漫画讽刺了这位政客夸大的承诺。"}]},{"pos":"n.","meaning":"嘲弄；嘲笑（较旧用法）","definition":"An act of ridicule or derision.","examples":[{"en":"The old tale describes the villagers' cruel mocks at the stranger.","zh":"这个古老故事描述了村民对陌生人的残酷嘲弄。"},{"en":"He answered their mocks with quiet dignity.","zh":"他以沉着而有尊严的态度回应他们的嘲弄。"}]},{"pos":"n.","meaning":"模拟品；仿制品；模拟考试","definition":"An imitation or a practice version of something.","examples":[{"en":"The designer prepared a mock of the packaging for discussion.","zh":"设计师准备了包装样品供讨论。"},{"en":"Her results in the mocks showed where she needed more practice.","zh":"她的模拟考试成绩表明了她需要加强练习的方面。"}]}],"modem":[{"pos":"n.","meaning":"调制解调器","definition":"a device converting signals for data transmission","examples":[{"en":"Restart the modem if the connection fails.","zh":"连接失败时重启调制解调器。"},{"en":"The old modem made a distinctive dialling sound.","zh":"旧调制解调器发出独特的拨号声。"}]}],"moderate":[{"pos":"adj.","meaning":"温和的；不极端的","definition":"not extreme in views or behaviour","examples":[{"en":"She advocated a moderate approach.","zh":"她主张采取温和的方式。"},{"en":"His political views are moderate.","zh":"他的政治观点温和。"}],"ipa":"/ˈmɒdərət/"},{"pos":"adj.","meaning":"适度的；中等的","definition":"neither very large nor very small","examples":[{"en":"The walk requires moderate effort.","zh":"这次步行需要中等体力。"},{"en":"Prices remained at a moderate level.","zh":"价格保持在适中水平。"}],"ipa":"/ˈmɒdərət/"},{"pos":"v.","meaning":"减轻；缓和；使适中","definition":"to become or make less severe","examples":[{"en":"The wind moderated by evening.","zh":"傍晚时风力减弱了。"},{"en":"She moderated her criticism after hearing the explanation.","zh":"听了解释后，她缓和了批评语气。"}],"ipa":"/ˈmɒdəreɪt/"}],"moderately":[{"pos":"adv.","meaning":"适度地；不过分地；相当地","definition":"To a medium or reasonable degree.","examples":[{"en":"The room was moderately warm.","zh":"房间温度适中。"},{"en":"The exhibition was moderately successful.","zh":"这次展览取得了一定程度的成功。"}]}],"moderation":[{"pos":"n.","meaning":"适度;节制;温和","definition":"avoidance of extremes or excess","examples":[{"en":"Enjoy sweet foods in moderation.","zh":"适量享用甜食。"},{"en":"Her moderation helped calm the argument.","zh":"她温和的态度帮助平息了争论。"}]}],"modernism":[{"pos":"n.","meaning":"现代主义","definition":"an artistic movement that breaks with traditional forms","examples":[{"en":"The exhibition traces modernism in architecture.","zh":"展览追溯建筑中的现代主义。"},{"en":"Her essay examines literary modernism.","zh":"她的论文研究文学现代主义。"}]}],"modification":[{"pos":"n.","meaning":"修改；调整；改动","definition":"A change made to improve or adapt something.","examples":[{"en":"The plan needs a small modification.","zh":"这个计划需要稍作修改。"},{"en":"Several modifications made the vehicle easier to use.","zh":"几项改动使这辆车更易于使用。"}]}],"modify":[{"pos":"v.","meaning":"修改;调整","definition":"to change something partly","examples":[{"en":"We modified the plan after testing.","zh":"测试后我们修改了计划。"},{"en":"The car was modified for wheelchair access.","zh":"汽车经过改装，方便轮椅使用者进出。"}]},{"pos":"v.","meaning":"修饰（语法）","definition":"to limit or describe the meaning of another word","examples":[{"en":"In this phrase, the adjective modifies the noun.","zh":"这个短语中，形容词修饰名词。"},{"en":"An adverb can modify a verb.","zh":"副词可以修饰动词。"}]}],"modish":[{"pos":"adj.","meaning":"时髦的；流行的","definition":"fashionable in style","examples":[{"en":"The shop sells modish furniture.","zh":"商店出售时髦家具。"},{"en":"He wore a modish jacket.","zh":"他穿着一件时髦夹克。"}]}],"module":[{"pos":"n.","meaning":"模块；组件；单元","definition":"A separate unit that forms part of a larger system or course.","examples":[{"en":"Students must complete a module on research methods.","zh":"学生必须完成一个研究方法课程单元。"},{"en":"The damaged module can be replaced without dismantling the whole machine.","zh":"可以更换损坏模块，而无需拆卸整台机器。"}]},{"pos":"n.","meaning":"航天舱；功能舱","definition":"A self-contained part of a spacecraft.","examples":[{"en":"The astronauts entered the landing module.","zh":"宇航员进入了着陆舱。"},{"en":"The new module provides additional living space on the station.","zh":"新舱段为空间站提供了额外生活空间。"}]}],"moist":[{"pos":"adj.","meaning":"湿润的;潮湿的","definition":"slightly wet","examples":[{"en":"Keep the soil moist.","zh":"保持土壤湿润。"},{"en":"The cake stayed moist for several days.","zh":"蛋糕连续几天都保持湿润。"}]}],"molecule":[{"pos":"n.","meaning":"分子","definition":"a group of atoms chemically bonded together","examples":[{"en":"A water molecule contains three atoms.","zh":"一个水分子含有三个原子。"},{"en":"The model shows the molecule's shape.","zh":"模型展示了分子的形状。"}]}],"molten":[{"pos":"adj.","meaning":"熔化的；熔融的","definition":"Made liquid by heat.","examples":[{"en":"Molten metal was poured into the mould.","zh":"熔化的金属被倒入铸模。"},{"en":"The workers watched the molten glass change shape.","zh":"工人看着熔融玻璃改变形状。"}]}],"momentum":[{"pos":"n.","meaning":"势头;动力","definition":"the force driving continued progress","examples":[{"en":"The campaign gained momentum.","zh":"运动势头增强了。"},{"en":"Early success gave the project momentum.","zh":"早期成功为项目提供了动力。"}]},{"pos":"n.","meaning":"动量","definition":"mass multiplied by velocity","examples":[{"en":"The collision transferred momentum between the balls.","zh":"碰撞使两个球之间发生动量传递。"},{"en":"A heavier moving object has more momentum at the same speed.","zh":"相同速度下，较重的运动物体动量更大。"}]}],"monitor":[{"pos":"n.","meaning":"班长；负责学生","definition":"a pupil given a particular responsibility","examples":[{"en":"The class monitor collected the forms.","zh":"班长收齐了表格。"},{"en":"A library monitor helped organise the shelves.","zh":"图书管理员学生协助整理书架。"}]},{"pos":"n.","meaning":"监视器；显示器；监测装置","definition":"a device that displays or tracks information","examples":[{"en":"The monitor shows live camera images.","zh":"监视器显示实时摄像画面。"},{"en":"The technician checked the air-quality monitor.","zh":"技术员检查了空气质量监测仪。"}]},{"pos":"v.","meaning":"监视；监测","definition":"to observe and check changes regularly","examples":[{"en":"Sensors monitor the temperature.","zh":"传感器监测温度。"},{"en":"The team monitored progress every week.","zh":"团队每周监测进展。"}]}],"monopoly":[{"pos":"n.","meaning":"垄断；专卖权；独占","definition":"Exclusive control over a market, resource, or activity.","examples":[{"en":"The company once held a monopoly on rail transport.","zh":"这家公司曾垄断铁路运输。"},{"en":"No group has a monopoly on good ideas.","zh":"没有任何群体能够独占好点子。"}]},{"pos":"n.","meaning":"垄断企业；专卖商品或服务","definition":"A business or product under exclusive control.","examples":[{"en":"The state monopoly supplied electricity to the entire region.","zh":"这家国营垄断企业向整个地区供电。"},{"en":"Salt was once a royal monopoly.","zh":"食盐曾是王室专卖商品。"}]}],"monotonous":[{"pos":"adj.","meaning":"单调的;乏味的","definition":"repetitive and uninteresting","examples":[{"en":"The work became monotonous after an hour.","zh":"一小时后工作变得单调。"},{"en":"His monotonous voice made the lecture hard to follow.","zh":"他单调的声音使讲座难以听下去。"}]}],"monster":[{"pos":"n.","meaning":"怪物","definition":"an imaginary frightening creature","examples":[{"en":"The story features a sea monster.","zh":"故事中有一只海怪。"},{"en":"The child drew a friendly monster.","zh":"孩子画了一个友善的怪物。"}]},{"pos":"n.","meaning":"庞然大物","definition":"something unusually large or powerful","examples":[{"en":"The new truck is a monster.","zh":"新卡车是个庞然大物。"},{"en":"A monster of a machine filled the workshop.","zh":"一台庞大的机器占满了车间。"}]}],"monumental":[{"pos":"adj.","meaning":"纪念碑的；纪念性的","definition":"Relating to monuments or serving as a lasting memorial.","examples":[{"en":"The cemetery contains impressive monumental sculpture.","zh":"公墓里有令人印象深刻的纪念雕塑。"},{"en":"The square was designed around a monumental arch.","zh":"广场围绕一座纪念拱门设计而成。"}]},{"pos":"adj.","meaning":"巨大的；意义重大的；不朽的","definition":"Extremely large, important, or lasting.","examples":[{"en":"Restoring the cathedral was a monumental task.","zh":"修复大教堂是一项巨大的任务。"},{"en":"The discovery marked a monumental advance in the field.","zh":"这个发现标志着该领域的一次重大进步。"}]}],"mood":[{"pos":"n.","meaning":"心情;情绪;气氛","definition":"a temporary emotional state or prevailing atmosphere","examples":[{"en":"Her mood improved after the walk.","zh":"散步后她心情好转了。"},{"en":"Soft lighting created a relaxed mood.","zh":"柔和灯光营造了轻松气氛。"}]}],"moral":[{"pos":"adj.","meaning":"道德的；伦理的","definition":"relating to right and wrong behaviour","examples":[{"en":"The decision raised moral questions.","zh":"这个决定提出了道德问题。"},{"en":"She felt a moral duty to help.","zh":"她觉得帮助别人是一项道德义务。"}]},{"pos":"n.","meaning":"道德准则；品行（常用复数）","definition":"principles concerning right and wrong","examples":[{"en":"The novel questions conventional morals.","zh":"小说质疑传统道德。"},{"en":"His actions conflicted with his stated morals.","zh":"他的行为违背了自己宣称的道德准则。"}]},{"pos":"n.","meaning":"寓意；教训","definition":"the lesson taught by a story or event","examples":[{"en":"The fable has a clear moral.","zh":"寓言有明确的寓意。"},{"en":"The moral of the story is to plan ahead.","zh":"故事的教训是提前规划。"}]}],"morality":[{"pos":"n.","meaning":"道德；道德准则；美德","definition":"Principles concerning right and wrong behaviour.","examples":[{"en":"The debate raised questions about the morality of the decision.","zh":"辩论引发了对这一决定是否合乎道德的质疑。"},{"en":"Different societies may develop different codes of morality.","zh":"不同社会可能形成不同的道德准则。"}]}],"moribund":[{"pos":"adj.","meaning":"垂死的;即将结束的;停滞不振的","definition":"near death or lacking vitality and activity","examples":[{"en":"New investment revived the moribund industry.","zh":"新投资重振了奄奄一息的行业。"},{"en":"The veterinary team examined the moribund animal.","zh":"兽医团队检查了垂死的动物。"}]}],"mortality":[{"pos":"n.","meaning":"死亡率；死亡数量","definition":"the rate or number of deaths in a population","examples":[{"en":"The study compares infant mortality across regions.","zh":"研究比较各地区的婴儿死亡率。"},{"en":"Researchers recorded mortality among the seedlings.","zh":"研究人员记录了幼苗的死亡率。"}]}],"mosquito":[{"pos":"n.","meaning":"蚊子","definition":"A small flying insect whose females often bite to obtain blood.","examples":[{"en":"A mosquito buzzed near my ear.","zh":"一只蚊子在我耳边嗡嗡叫。"},{"en":"We slept under mosquito nets.","zh":"我们睡在蚊帐里。"}]}],"moss":[{"pos":"n.","meaning":"苔藓","definition":"a small green plant growing in damp places","examples":[{"en":"Moss covered the shaded stones.","zh":"苔藓覆盖了背阴石头。"},{"en":"A soft carpet of moss surrounded the tree.","zh":"一层柔软苔藓铺在树周围。"}]}],"motion":[{"pos":"n.","meaning":"运动；移动","definition":"the act or state of moving","examples":[{"en":"The wheel remained in motion.","zh":"轮子一直在转动。"},{"en":"The camera captures motion clearly.","zh":"相机清晰捕捉运动。"}]},{"pos":"n.","meaning":"手势；动作","definition":"a movement expressing something","examples":[{"en":"She made a motion towards the door.","zh":"她朝门做了个手势。"},{"en":"With one motion, he cleared the desk.","zh":"他一个动作就清空了桌面。"}]},{"pos":"v.","meaning":"打手势；示意","definition":"to signal with a movement","examples":[{"en":"She motioned us to sit down.","zh":"她示意我们坐下。"},{"en":"The guard motioned the car forward.","zh":"门卫示意汽车往前开。"}]}],"motivate":[{"pos":"v.","meaning":"激励；促使；激发动力","definition":"To give someone a reason or desire to act.","examples":[{"en":"Clear goals can motivate students to keep practising.","zh":"明确目标可以激励学生坚持练习。"},{"en":"Concern for the environment motivated her career choice.","zh":"对环境的关注促使她作出了职业选择。"}]}],"motivational":[{"pos":"adj.","meaning":"激励的;与动机有关的","definition":"encouraging action or relating to motivation","examples":[{"en":"The coach gave a motivational speech.","zh":"教练发表了鼓舞士气的讲话。"},{"en":"Researchers examined motivational factors in learning.","zh":"研究人员考察学习中的动机因素。"}]}],"motive":[{"pos":"n.","meaning":"动机；目的","definition":"a reason for acting","examples":[{"en":"His motive was unclear.","zh":"他的动机不明。"},{"en":"The interview explored her motives for volunteering.","zh":"访谈探讨了她做志愿服务的动机。"}]}],"mould":[{"pos":"n.","meaning":"霉；霉菌","definition":"A fungus that grows as a thin layer on damp material.","examples":[{"en":"Mould grew on the bread left in the cupboard.","zh":"放在橱柜里的面包长霉了。"},{"en":"The damp wall was covered with black mould.","zh":"潮湿的墙面长满了黑霉。"}]},{"pos":"n.","meaning":"模具；铸模","definition":"A hollow container used to shape a material.","examples":[{"en":"Pour the mixture into a round mould.","zh":"把混合物倒入圆形模具。"},{"en":"The factory uses steel moulds to shape the parts.","zh":"工厂用钢模具塑造这些部件。"}]},{"pos":"n.","meaning":"类型；性格；模式","definition":"A characteristic pattern of personality or behaviour.","examples":[{"en":"She is a leader in a very different mould from her predecessor.","zh":"她是与前任性格类型很不同的领导者。"},{"en":"The school encourages students to break the traditional mould.","zh":"学校鼓励学生突破传统模式。"}]},{"pos":"v.","meaning":"用模具制作；塑形","definition":"To shape a soft material using a mould or pressure.","examples":[{"en":"The children moulded animals from clay.","zh":"孩子们用黏土捏出动物。"},{"en":"The parts are moulded from recycled plastic.","zh":"这些部件由再生塑料模制而成。"}]},{"pos":"v.","meaning":"塑造；影响形成","definition":"To influence how someone or something develops.","examples":[{"en":"Early experiences mould a child's expectations.","zh":"早期经历塑造孩子的预期。"},{"en":"Years at sea moulded his independent character.","zh":"多年的海上生活塑造了他独立的性格。"}]}],"mount":[{"pos":"n.","meaning":"山;山峰","definition":"a mountain, especially in names","examples":[{"en":"The climbers reached the foot of Mount Fuji.","zh":"登山者到达富士山脚。"},{"en":"Mount Etna appeared through the clouds.","zh":"埃特纳山从云间显现。"}]},{"pos":"n.","meaning":"支架;底座","definition":"a support holding something in position","examples":[{"en":"The camera sits on a sturdy mount.","zh":"相机固定在坚固支架上。"},{"en":"The jeweller repaired the diamond's gold mount.","zh":"珠宝匠修好了钻石的金托。"}]},{"pos":"v.","meaning":"登上;骑上","definition":"to climb onto something","examples":[{"en":"She mounted the horse confidently.","zh":"她自信地骑上马。"},{"en":"He mounted the steps to the platform.","zh":"他登上通往讲台的台阶。"}]},{"pos":"v.","meaning":"发起;组织开展","definition":"to organize and begin an activity","examples":[{"en":"They mounted a campaign against littering.","zh":"他们发起了反对乱扔垃圾的运动。"},{"en":"The museum mounted a major exhibition.","zh":"博物馆举办了大型展览。"}]},{"pos":"v.","meaning":"安装;镶嵌","definition":"to attach to a supporting surface","examples":[{"en":"Mount the screen on the wall.","zh":"把屏幕安装在墙上。"},{"en":"The photograph was mounted on stiff card.","zh":"照片被裱在硬卡纸上。"}]}],"mountainous":[{"pos":"adj.","meaning":"多山的","definition":"having many mountains","examples":[{"en":"The northern region is mountainous.","zh":"北部地区多山。"},{"en":"Road construction is difficult in mountainous terrain.","zh":"在山地修路很困难。"}]}],"muddle":[{"pos":"n.","meaning":"混乱；凌乱；困惑","definition":"A confused or untidy state.","examples":[{"en":"The booking system was in a muddle.","zh":"预订系统一片混乱。"},{"en":"Her notes were such a muddle that she rewrote them.","zh":"她的笔记太混乱，便重新写了一遍。"}]},{"pos":"v.","meaning":"弄乱；混淆；使困惑","definition":"To confuse things or make a situation disorganised.","examples":[{"en":"I muddled the dates and missed the appointment.","zh":"我弄混了日期，错过了预约。"},{"en":"The conflicting instructions muddled the new volunteers.","zh":"相互矛盾的指示把新志愿者弄糊涂了。"}]}],"multinational":[{"pos":"adj.","meaning":"多国的;跨国的;多民族的","definition":"involving several countries or nationalities","examples":[{"en":"A multinational team conducted the study.","zh":"一个多国团队开展了研究。"},{"en":"She works for a multinational company.","zh":"她在一家跨国公司工作。"}]},{"pos":"n.","meaning":"跨国公司","definition":"a company operating in several countries","examples":[{"en":"The multinational opened a regional office.","zh":"这家跨国公司设立了区域办事处。"},{"en":"Local firms compete with large multinationals.","zh":"当地企业与大型跨国公司竞争。"}]}],"multiple":[{"pos":"adj.","meaning":"多重的；多个的","definition":"involving more than one","examples":[{"en":"The study used multiple sources.","zh":"研究使用了多个来源。"},{"en":"The device serves multiple purposes.","zh":"这个装置有多种用途。"}]},{"pos":"n.","meaning":"倍数","definition":"a number obtained by multiplying another by an integer","examples":[{"en":"Twelve is a multiple of three.","zh":"十二是三的倍数。"},{"en":"Pack the items in multiples of six.","zh":"按六的倍数包装这些物品。"}]}],"multiply":[{"pos":"v.","meaning":"增加；繁殖；成倍增长","definition":"To increase greatly in number or reproduce.","examples":[{"en":"Bacteria multiply rapidly in suitable conditions.","zh":"细菌在适宜条件下迅速繁殖。"},{"en":"Their difficulties multiplied as winter approached.","zh":"随着冬季临近，他们的困难不断增加。"}]},{"pos":"v.","meaning":"乘；乘以","definition":"To calculate the result of adding a number a specified number of times.","examples":[{"en":"Multiply six by four to get twenty-four.","zh":"六乘以四得到二十四。"},{"en":"The software multiplies the unit price by the quantity.","zh":"软件将单价乘以数量。"}]}],"mundane":[{"pos":"adj.","meaning":"平凡的;枯燥的","definition":"ordinary and not exciting","examples":[{"en":"She disliked mundane household tasks.","zh":"她不喜欢琐碎家务。"},{"en":"The mystery had a surprisingly mundane explanation.","zh":"谜团的解释出乎意料地平常。"}]},{"pos":"adj.","meaning":"世俗的;现世的","definition":"relating to ordinary earthly life rather than spiritual matters","examples":[{"en":"The monk withdrew from mundane concerns.","zh":"僧人远离世俗烦恼。"},{"en":"The poem contrasts sacred love with mundane ambition.","zh":"诗歌对比了神圣之爱和世俗野心。"}]}],"municipal":[{"pos":"adj.","meaning":"市政的；市的；地方自治的","definition":"relating to a town or its local government","examples":[{"en":"The municipal library closes at six.","zh":"市立图书馆六点关门。"},{"en":"Municipal authorities approved the park.","zh":"市政当局批准了公园项目。"}]},{"pos":"adj.","meaning":"国内的；内政的（法律用语）","definition":"relating to a state's internal affairs rather than international matters","examples":[{"en":"The course compares municipal law with international law.","zh":"课程比较国内法与国际法。"},{"en":"The judgment examined the treaty's effect in municipal law.","zh":"判决考察了条约在国内法中的效力。"}]}],"murder":[{"pos":"n.","meaning":"谋杀；凶杀","definition":"The intentional unlawful killing of a person.","examples":[{"en":"The detective investigated a murder near the station.","zh":"侦探调查了车站附近的一起谋杀案。"},{"en":"A witness provided evidence in the murder trial.","zh":"一名证人在谋杀案审判中提供了证据。"}]},{"pos":"v.","meaning":"谋杀；杀害","definition":"To kill a person intentionally and unlawfully.","examples":[{"en":"The novel begins when a businessman is murdered.","zh":"小说以一名商人遭到谋杀为开端。"},{"en":"He was convicted of murdering his neighbour.","zh":"他因谋杀邻居被定罪。"}]}],"murky":[{"pos":"adj.","meaning":"昏暗的;浑浊的","definition":"dark or difficult to see through","examples":[{"en":"Fish moved through the murky water.","zh":"鱼穿行于浑浊水中。"},{"en":"We entered a murky cellar.","zh":"我们进入阴暗地窖。"}]},{"pos":"adj.","meaning":"隐晦的;不清楚的;可疑的","definition":"unclear or involving hidden wrongdoing","examples":[{"en":"The company's finances remain murky.","zh":"公司的财务状况仍不透明。"},{"en":"The documentary explored a murky political deal.","zh":"纪录片探查了一项可疑的政治交易。"}]}],"muscle":[{"pos":"n.","meaning":"肌肉","definition":"body tissue that contracts to produce movement","examples":[{"en":"The exercise strengthens leg muscles.","zh":"这个练习增强腿部肌肉。"},{"en":"The diagram shows the muscles of the arm.","zh":"图中展示手臂肌肉。"}]},{"pos":"n.","meaning":"体力；实力；影响力","definition":"physical strength or power to influence","examples":[{"en":"Moving the piano required considerable muscle.","zh":"搬钢琴需要很大的力气。"},{"en":"The company used its financial muscle to expand.","zh":"公司运用财力扩张。"}]}],"mushroom":[{"pos":"n.","meaning":"蘑菇","definition":"A fungus with a stalk and a cap, some varieties of which are edible.","examples":[{"en":"She added sliced mushrooms to the soup.","zh":"她在汤里加了蘑菇片。"},{"en":"Mushrooms appeared beneath the trees after the rain.","zh":"雨后树下长出了蘑菇。"}]},{"pos":"v.","meaning":"迅速增长；快速发展","definition":"To grow or increase rapidly.","examples":[{"en":"New cafés mushroomed around the university.","zh":"大学周围的新咖啡馆迅速增多。"},{"en":"The small dispute mushroomed into a national controversy.","zh":"小小的争端迅速演变成全国性争议。"}]}],"mutual":[{"pos":"adj.","meaning":"相互的;共同的","definition":"felt by both parties or shared","examples":[{"en":"Their friendship rests on mutual respect.","zh":"他们的友谊建立在相互尊重上。"},{"en":"We met through a mutual friend.","zh":"我们通过共同朋友认识。"}]}],"mysterious":[{"pos":"adj.","meaning":"神秘的；难以解释的","definition":"difficult to understand or explain","examples":[{"en":"A mysterious noise came from the attic.","zh":"阁楼传来神秘的声响。"},{"en":"The island's disappearance remains mysterious.","zh":"岛屿的消失仍难以解释。"}]}],"naive":[{"pos":"adj.","meaning":"天真的；缺乏经验的；幼稚的","definition":"Lacking experience and therefore too trusting or simple.","examples":[{"en":"It was naive to expect the problem to solve itself.","zh":"指望问题自行解决很天真。"},{"en":"She was young and naive when she signed the contract.","zh":"她签合同时年轻而缺乏经验。"}]}],"naked":[{"pos":"adj.","meaning":"裸体的;裸露的;无遮蔽的","definition":"without clothing or covering","examples":[{"en":"The child ran naked into the bath.","zh":"孩子光着身子跑进浴缸。"},{"en":"The storm stripped the tree's branches naked.","zh":"风暴使树枝变得光秃秃。"}]}],"narrator":[{"pos":"n.","meaning":"叙述者；讲述者","definition":"the person or voice telling a story","examples":[{"en":"The narrator describes her childhood.","zh":"叙述者描述了自己的童年。"},{"en":"An unreliable narrator complicates the novel.","zh":"一个不可靠的叙述者使小说复杂起来。"}]}],"nasty":[{"pos":"adj.","meaning":"令人讨厌的；恶劣的；难受的","definition":"Very unpleasant or troublesome.","examples":[{"en":"A nasty smell came from the drain.","zh":"排水口传来难闻的气味。"},{"en":"He caught a nasty cold during the trip.","zh":"旅行中他患了重感冒。"}]},{"pos":"adj.","meaning":"不友善的；恶意的；下流的","definition":"Unkind, malicious, or offensive.","examples":[{"en":"She received several nasty messages online.","zh":"她在网上收到了几条恶意信息。"},{"en":"There is no need to make nasty remarks about his appearance.","zh":"没有必要对他的外貌作恶毒评论。"}]}],"nationality":[{"pos":"n.","meaning":"国籍","definition":"legal membership of a particular country","examples":[{"en":"State your nationality on the form.","zh":"在表格上填写国籍。"},{"en":"She holds dual nationality.","zh":"她拥有双重国籍。"}]},{"pos":"n.","meaning":"民族;民族群体","definition":"a group sharing national culture or identity","examples":[{"en":"The city contains many nationalities.","zh":"城市中有许多民族群体。"},{"en":"Representatives of several nationalities attended the festival.","zh":"几个民族的代表参加了节庆活动。"}]}],"native":[{"pos":"adj.","meaning":"本地的；本土的；出生地的","definition":"belonging to a place by birth or origin","examples":[{"en":"She returned to her native town.","zh":"她回到家乡。"},{"en":"The project protects native trees.","zh":"项目保护本土树木。"}]},{"pos":"n.","meaning":"本地人；出生于某地的人","definition":"a person born in a particular place","examples":[{"en":"He is a native of this city.","zh":"他是这座城市的本地人。"},{"en":"As a London native, she knew the streets well.","zh":"作为伦敦本地人，她很熟悉这些街道。"}]}],"natural":[{"pos":"adj.","meaning":"自然界的；天然的","definition":"Existing in nature rather than made by people.","examples":[{"en":"The room has plenty of natural light.","zh":"房间有充足的自然光。"},{"en":"The park protects important natural habitats.","zh":"公园保护着重要的天然栖息地。"}]},{"pos":"adj.","meaning":"自然的；正常的；不做作的","definition":"Expected, ordinary, or spontaneous in the circumstances.","examples":[{"en":"It is natural to feel nervous before an exam.","zh":"考试前感到紧张很正常。"},{"en":"Her relaxed manner made the conversation feel natural.","zh":"她放松的举止让谈话显得很自然。"}]},{"pos":"adj.","meaning":"天生的；有天赋的；固有的","definition":"Present from birth or arising from an inherent ability.","examples":[{"en":"She is a natural storyteller.","zh":"她天生善于讲故事。"},{"en":"The child showed a natural talent for music.","zh":"这个孩子表现出天生的音乐才能。"}]}],"naturally":[{"pos":"adv.","meaning":"自然地;当然","definition":"as expected or in a normal way","examples":[{"en":"Naturally, the parents were worried.","zh":"父母当然很担心。"},{"en":"The river flows naturally through the valley.","zh":"河流自然地流经山谷。"}]},{"pos":"adv.","meaning":"天生地;本性上","definition":"by inherent ability or character","examples":[{"en":"She is naturally curious.","zh":"她天生好奇。"},{"en":"He speaks naturally and confidently in public.","zh":"他在公众面前说话自然自信。"}]}],"navigable":[{"pos":"adj.","meaning":"可通航的；适于航行的","definition":"deep or wide enough for boats to travel on","examples":[{"en":"The river is navigable below the bridge.","zh":"大桥下游的河段可以通航。"},{"en":"Dredging kept the channel navigable.","zh":"疏浚使航道保持可通航状态。"}]}],"navigation":[{"pos":"n.","meaning":"航行；导航；领航","definition":"The activity of finding and following a route.","examples":[{"en":"The sailors relied on the stars for navigation.","zh":"水手们依靠星星导航。"},{"en":"The course covers navigation in mountain terrain.","zh":"这门课程教授山地导航。"}]}],"necessarily":[{"pos":"adv.","meaning":"必然地;必要地","definition":"as an unavoidable consequence or requirement","examples":[{"en":"A larger sample is not necessarily better.","zh":"样本更大并不一定更好。"},{"en":"The changes necessarily involved extra work.","zh":"这些变化必然带来额外工作。"}]}],"necessity":[{"pos":"n.","meaning":"必要性；必然","definition":"the state of being needed or unavoidable","examples":[{"en":"The report stresses the necessity of maintenance.","zh":"报告强调维护的必要性。"},{"en":"Necessity forced them to change their plans.","zh":"形势迫使他们改变计划。"}]},{"pos":"n.","meaning":"必需品","definition":"something essential","examples":[{"en":"Clean water is a basic necessity.","zh":"清洁水是基本必需品。"},{"en":"They packed only the necessities.","zh":"他们只打包了必需品。"}]}],"negative":[{"pos":"adj.","meaning":"否定的；反对的","definition":"Expressing refusal or disagreement.","examples":[{"en":"We received a negative response to the request.","zh":"我们的请求遭到否定答复。"},{"en":"The sentence is negative because it denies the claim.","zh":"这句话是否定句，因为它否定了该主张。"}]},{"pos":"adj.","meaning":"消极的；负面的；不利的","definition":"Focusing on bad aspects or producing harmful effects.","examples":[{"en":"Constant negative comments lowered morale.","zh":"不断的负面评论打击了士气。"},{"en":"Noise can have a negative effect on concentration.","zh":"噪音可能对注意力产生不良影响。"}]},{"pos":"adj.","meaning":"负的；阴性的","definition":"Below zero, having a negative charge, or showing no detected condition.","examples":[{"en":"The account balance became negative.","zh":"账户余额变成了负数。"},{"en":"The sample gave a negative result for contamination.","zh":"样本污染检测结果为阴性。"}]},{"pos":"n.","meaning":"负数","definition":"A number below zero.","examples":[{"en":"A negative multiplied by a positive gives a negative.","zh":"负数乘以正数得到负数。"},{"en":"Arrange the negatives to the left of zero on the number line.","zh":"把负数排列在数轴上零的左边。"}]},{"pos":"n.","meaning":"底片","definition":"A photographic image with light and dark values reversed.","examples":[{"en":"The photographer stored the negatives in protective sleeves.","zh":"摄影师把底片放在保护套中保存。"},{"en":"We made a new print from an old negative.","zh":"我们用一张旧底片洗出了一张新照片。"}]}],"neglect":[{"pos":"v.","meaning":"忽视;疏于照顾;疏漏","definition":"to fail to give needed attention or action","examples":[{"en":"He neglected the garden for months.","zh":"他几个月未照料花园。"},{"en":"She neglected to mention the fee.","zh":"她忘了提到费用。"}]},{"pos":"n.","meaning":"忽视;疏忽;疏于照顾","definition":"a failure to provide needed care or attention","examples":[{"en":"The house suffered years of neglect.","zh":"房屋多年疏于维护。"},{"en":"The inquiry found evidence of serious neglect.","zh":"调查发现了严重疏忽的证据。"}]}],"negotiate":[{"pos":"v.","meaning":"协商；谈判；商定","definition":"to discuss something to reach agreement","examples":[{"en":"The unions negotiated a new agreement.","zh":"工会通过谈判达成新协议。"},{"en":"We negotiated the price with the supplier.","zh":"我们与供应商协商价格。"}]},{"pos":"v.","meaning":"顺利通过；越过障碍","definition":"to get past a difficult place or obstacle","examples":[{"en":"The driver negotiated the sharp bend.","zh":"司机顺利驶过急弯。"},{"en":"We negotiated the narrow path carefully.","zh":"我们小心通过狭窄小路。"}]}],"neighbourhood":[{"pos":"n.","meaning":"街区；社区","definition":"the area around where people live","examples":[{"en":"There is a small park in our neighbourhood.","zh":"我们的社区有一个小公园。"},{"en":"The neighbourhood is popular with young families.","zh":"这个街区很受年轻家庭欢迎。"},{"en":"Residents want better lighting in the neighbourhood.","zh":"居民希望改善社区照明。"}]}],"neoclassical":[{"pos":"adj.","meaning":"新古典主义的","definition":"reviving classical styles or relating to neoclassical theory","examples":[{"en":"The museum occupies a neoclassical building.","zh":"博物馆位于一座新古典主义建筑中。"},{"en":"The lecture examined neoclassical economic theory.","zh":"讲座考察了新古典经济理论。"}]}],"nerve":[{"pos":"n.","meaning":"神经","definition":"a fibre carrying signals through the body","examples":[{"en":"The diagram shows a nerve in the arm.","zh":"图中展示手臂的一条神经。"},{"en":"The injury damaged a nearby nerve.","zh":"伤害损伤了附近的一条神经。"}]},{"pos":"n.","meaning":"勇气；胆量","definition":"the courage to act despite fear","examples":[{"en":"She found the nerve to speak.","zh":"她鼓起勇气发言。"},{"en":"He lost his nerve before the jump.","zh":"跳跃前他失去了勇气。"}]}],"neutral":[{"pos":"adj.","meaning":"中立的；不偏不倚的","definition":"Not supporting either side in a disagreement.","examples":[{"en":"The mediator remained neutral throughout the talks.","zh":"调解员在整个谈判中保持中立。"},{"en":"They chose a neutral country for the meeting.","zh":"他们选择在一个中立国家开会。"}]},{"pos":"adj.","meaning":"中性的；无明显特征的","definition":"Not strongly marked by a particular quality, feeling, or colour.","examples":[{"en":"The walls were painted in neutral colours.","zh":"墙壁涂成了中性色。"},{"en":"She kept her expression neutral while listening.","zh":"她倾听时表情平静，不露声色。"}]}],"nevertheless":[{"pos":"adv.","meaning":"然而;尽管如此;仍然","definition":"despite what was just stated","examples":[{"en":"The climb was difficult; nevertheless, we continued.","zh":"攀登很困难，尽管如此我们仍继续。"},{"en":"She was inexperienced but nevertheless effective.","zh":"她经验不足，却仍然卓有成效。"}]}],"newsletter":[{"pos":"n.","meaning":"通讯；简报","definition":"a regular publication for members of a group","examples":[{"en":"The school sends a monthly newsletter.","zh":"学校每月发送一份简报。"},{"en":"The newsletter lists upcoming events.","zh":"通讯列出了即将举行的活动。"}]}],"nickel":[{"pos":"n.","meaning":"镍","definition":"A silvery metallic chemical element.","examples":[{"en":"The alloy contains copper and nickel.","zh":"这种合金含有铜和镍。"},{"en":"A thin layer of nickel protects the surface from corrosion.","zh":"一层薄镍保护表面免受腐蚀。"}]},{"pos":"n.","meaning":"五分硬币（美国或加拿大）","definition":"A coin worth five cents.","examples":[{"en":"He dropped a nickel into the jar.","zh":"他往罐子里投了一枚五分硬币。"},{"en":"The cashier gave her two nickels in change.","zh":"收银员找给她两枚五分硬币。"}]}],"niggle":[{"pos":"v.","meaning":"吹毛求疵;拘泥小节","definition":"to complain about minor details","examples":[{"en":"He niggled over every word of the proposal.","zh":"他对提案中的每个词都挑剔。"},{"en":"Stop niggling and consider the main argument.","zh":"别再拘泥小节，考虑一下主要论点。"}]},{"pos":"v.","meaning":"不断烦扰;为小事担忧","definition":"to cause or feel persistent slight worry","examples":[{"en":"A small doubt niggled at her.","zh":"一点疑虑不断困扰着她。"},{"en":"The unpaid bill kept niggling in his mind.","zh":"未付账单一直让他心里不安。"}]}],"nightmare":[{"pos":"n.","meaning":"噩梦","definition":"a frightening dream","examples":[{"en":"The noise woke her from a nightmare.","zh":"噪声把她从噩梦中惊醒。"},{"en":"He had a nightmare about missing the train.","zh":"他做了一个错过火车的噩梦。"}]},{"pos":"n.","meaning":"可怕的经历；难以处理的事","definition":"a very unpleasant or difficult situation","examples":[{"en":"The delayed journey became a nightmare.","zh":"延误的旅程变成了可怕的经历。"},{"en":"Organising the move was a logistical nightmare.","zh":"组织搬家在后勤方面极其棘手。"}]}],"nocturnal":[{"pos":"adj.","meaning":"夜间的；夜间活动的","definition":"Occurring or being active during the night.","examples":[{"en":"Owls are mainly nocturnal hunters.","zh":"猫头鹰主要在夜间捕食。"},{"en":"The researchers recorded nocturnal changes in temperature.","zh":"研究人员记录了夜间气温变化。"}]}],"nominal":[{"pos":"adj.","meaning":"名义上的","definition":"existing in name but not in practical effect","examples":[{"en":"He remained the nominal leader.","zh":"他仍是名义上的领导。"},{"en":"The committee had only nominal independence.","zh":"委员会只有名义上的独立。"}]},{"pos":"adj.","meaning":"象征性的;微不足道的","definition":"very small in amount","examples":[{"en":"Visitors pay a nominal entrance fee.","zh":"游客支付少量象征性门票费。"},{"en":"The charity rented the hall for a nominal sum.","zh":"慈善机构以象征性金额租用了大厅。"}]}],"nordic":[{"pos":"adj.","meaning":"北欧的；北欧人的（通常大写 Nordic）","definition":"relating to the countries and peoples of northern Europe","examples":[{"en":"The museum explores Nordic design.","zh":"博物馆探讨北欧设计。"},{"en":"Several Nordic countries joined the study.","zh":"几个北欧国家参加了研究。"}]}],"normal":[{"pos":"adj.","meaning":"正常的；通常的；标准的","definition":"Usual, expected, or meeting a standard.","examples":[{"en":"The machine is operating at its normal speed.","zh":"机器正在以正常速度运行。"},{"en":"It took several days for life to return to normal.","zh":"生活过了几天才恢复正常。"}]}],"notable":[{"pos":"adj.","meaning":"值得注意的;显著的;杰出的","definition":"worthy of attention or especially distinguished","examples":[{"en":"There has been a notable improvement.","zh":"有了显著改善。"},{"en":"She made a notable contribution to the field.","zh":"她对该领域作出了杰出贡献。"}]},{"pos":"n.","meaning":"名人;要人","definition":"a distinguished or important person","examples":[{"en":"Local notables attended the opening.","zh":"当地名流出席了开幕式。"},{"en":"The guest list included several scientific notables.","zh":"宾客名单包括几位科学名人。"}]}],"notice board":[{"pos":"n.","meaning":"布告牌；公告栏","definition":"a board on which notices are displayed","examples":[{"en":"Check the notice board for room changes.","zh":"查看公告栏了解教室变更。"},{"en":"She pinned a poster to the notice board.","zh":"她把海报钉在公告栏上。"}]}],"noticeable":[{"pos":"adj.","meaning":"明显的；显而易见的","definition":"Easy to see or recognise.","examples":[{"en":"There was a noticeable improvement in her pronunciation.","zh":"她的发音有了明显改善。"},{"en":"The stain is barely noticeable in this light.","zh":"在这种光线下，污渍几乎看不出来。"}]}],"notify":[{"pos":"v.","meaning":"通知;告知;报告","definition":"to formally inform someone","examples":[{"en":"Notify the office if your address changes.","zh":"地址变更时请通知办公室。"},{"en":"The school notified parents of the closure.","zh":"学校把停课消息通知了家长。"}]}],"notion":[{"pos":"n.","meaning":"概念；观念；想法","definition":"an idea or belief","examples":[{"en":"The book challenges the notion of fixed ability.","zh":"这本书挑战能力固定不变的观念。"},{"en":"He had no notion of the difficulty involved.","zh":"他不知道其中的困难。"}]}],"notoriety":[{"pos":"n.","meaning":"恶名；臭名昭著","definition":"The state of being widely known for something bad.","examples":[{"en":"The prison gained notoriety for its harsh conditions.","zh":"这座监狱因条件恶劣而臭名昭著。"},{"en":"He tried to escape the notoriety brought by the scandal.","zh":"他试图摆脱丑闻带来的恶名。"}]}],"notorious":[{"pos":"adj.","meaning":"臭名昭著的;因坏事而出名的","definition":"widely known for something bad","examples":[{"en":"The road is notorious for accidents.","zh":"这条路因事故频发而臭名昭著。"},{"en":"A notorious fraudster ran the scheme.","zh":"一个臭名昭著的骗子经营着这个骗局。"}]}],"nourish":[{"pos":"v.","meaning":"滋养；养育","definition":"to provide what is needed for growth and health","examples":[{"en":"The soil nourishes the young plants.","zh":"土壤滋养幼苗。"},{"en":"A varied diet helps nourish the body.","zh":"多样化饮食有助于滋养身体。"}]},{"pos":"v.","meaning":"培养；助长","definition":"to support the development of a feeling or idea","examples":[{"en":"Reading nourished her imagination.","zh":"阅读滋养了她的想象力。"},{"en":"She nourished the hope of returning.","zh":"她一直怀着回去的希望。"}]}],"novice":[{"pos":"n.","meaning":"新手；初学者","definition":"A person new to an activity.","examples":[{"en":"The trail is suitable for complete novices.","zh":"这条步道适合完全没有经验的新手。"},{"en":"As a novice cook, he followed the recipe carefully.","zh":"作为烹饪初学者，他仔细按照食谱操作。"}]},{"pos":"n.","meaning":"初学修士；初学修女","definition":"A person beginning religious training before taking full vows.","examples":[{"en":"The novice spent her first year learning the community's rules.","zh":"这位初学修女在第一年学习团体的规章。"},{"en":"A senior monk guided the novices through their daily duties.","zh":"一位资深修士指导初学修士完成日常职责。"}]}],"nuclear":[{"pos":"adj.","meaning":"核能的;原子核的","definition":"relating to atomic nuclei or nuclear energy","examples":[{"en":"The country invested in nuclear research.","zh":"该国投资了核研究。"},{"en":"The plant generates nuclear power.","zh":"这座电站利用核能发电。"}]}],"numerous":[{"pos":"adj.","meaning":"众多的；许多的","definition":"existing in large numbers","examples":[{"en":"The proposal received numerous comments.","zh":"提案收到了许多评论。"},{"en":"Numerous birds nest along the coast.","zh":"众多鸟类沿海岸筑巢。"}]}],"nursery":[{"pos":"n.","meaning":"托儿所；幼儿园","definition":"A place where young children are cared for or taught.","examples":[{"en":"Her daughter attends a nursery near the office.","zh":"她女儿在办公室附近的托儿所上学。"},{"en":"The nursery provides meals and afternoon naps.","zh":"托儿所提供餐食和午睡安排。"}]},{"pos":"n.","meaning":"苗圃","definition":"A place where plants are grown for sale or planting elsewhere.","examples":[{"en":"We bought young apple trees from a nursery.","zh":"我们从苗圃买了苹果树苗。"},{"en":"The nursery grows native plants for local parks.","zh":"苗圃为当地公园培育本土植物。"}]},{"pos":"adj.","meaning":"幼儿教育的；育幼的","definition":"Relating to the care or education of young children.","examples":[{"en":"She works as a nursery teacher.","zh":"她是一名幼儿教师。"},{"en":"The library holds nursery rhyme sessions for toddlers.","zh":"图书馆为幼儿举办童谣活动。"}]}],"nurture":[{"pos":"v.","meaning":"培养;养育;滋养","definition":"to care for and help develop","examples":[{"en":"Teachers nurture children's curiosity.","zh":"教师培养孩子的好奇心。"},{"en":"The seedlings were nurtured in a warm greenhouse.","zh":"幼苗在温暖的温室中受到培育。"}]},{"pos":"n.","meaning":"养育;培养;滋养","definition":"care and nourishment supporting development","examples":[{"en":"The study examines the influence of nurture.","zh":"研究考察后天培养的影响。"},{"en":"Young animals need warmth and nurture.","zh":"幼小动物需要温暖与养育。"}]}],"nutrient":[{"pos":"n.","meaning":"营养物质；养分","definition":"a substance needed for growth and health","examples":[{"en":"Plants absorb nutrients through their roots.","zh":"植物通过根部吸收养分。"},{"en":"The analysis measured nutrients in the soil.","zh":"分析测量了土壤中的营养物质。"}]}],"nutrition":[{"pos":"n.","meaning":"营养","definition":"the food and nutrients needed for health","examples":[{"en":"Good nutrition supports children's growth.","zh":"良好的营养有助于儿童生长。"},{"en":"The course explains the basics of nutrition.","zh":"这门课程讲解营养学基础。"},{"en":"Poor nutrition can weaken the immune system.","zh":"营养不良会削弱免疫系统。"}]},{"pos":"n.","meaning":"营养学","definition":"The study of food and its relationship to health.","examples":[{"en":"She earned a degree in nutrition.","zh":"她获得了营养学学位。"},{"en":"The department teaches nutrition alongside food science.","zh":"该系在教授食品科学的同时教授营养学。"}]}],"nutritional":[{"pos":"adj.","meaning":"营养的;与营养有关的","definition":"relating to the nutrients provided by food","examples":[{"en":"The label lists the nutritional content.","zh":"标签列出了营养成分。"},{"en":"The programme assessed children's nutritional needs.","zh":"项目评估了儿童的营养需求。"}]}],"nutritious":[{"pos":"adj.","meaning":"有营养的；营养丰富的","definition":"providing useful substances for health and growth","examples":[{"en":"The kitchen serves nutritious meals.","zh":"厨房提供有营养的饭菜。"},{"en":"Beans can form part of a nutritious diet.","zh":"豆类可以成为营养饮食的一部分。"}]}],"oak":[{"pos":"n.","meaning":"橡树","definition":"A large tree that produces acorns.","examples":[{"en":"An old oak shaded the village square.","zh":"一棵老橡树为村庄广场遮荫。"},{"en":"The children collected acorns beneath the oak.","zh":"孩子们在橡树下捡橡子。"}]},{"pos":"n.","meaning":"橡木","definition":"The hard wood of an oak tree.","examples":[{"en":"The dining table is made of solid oak.","zh":"这张餐桌是实心橡木做的。"},{"en":"Oak was used for the heavy doors.","zh":"厚重的门使用了橡木。"}]}],"object":[{"pos":"n.","meaning":"物体;物品","definition":"a thing that can be seen or touched","examples":[{"en":"A shiny object lay beneath the chair.","zh":"椅子下面有个闪亮物体。"},{"en":"Do not place heavy objects on the shelf.","zh":"不要在架子上放重物。"}],"ipa":"/ˈɒbdʒɪkt/"},{"pos":"n.","meaning":"对象;目标;目的","definition":"the focus or purpose of an action","examples":[{"en":"The object of the exercise is cooperation.","zh":"练习的目的是合作。"},{"en":"The painting became the object of intense debate.","zh":"画作成为激烈争论的对象。"}],"ipa":"/ˈɒbdʒɪkt/"},{"pos":"n.","meaning":"宾语","definition":"the grammatical element affected by a verb or preposition","examples":[{"en":"In this sentence, the verb has no object.","zh":"这个句子中的动词没有宾语。"},{"en":"Place the object after the verb.","zh":"把宾语放在动词后面。"}],"ipa":"/ˈɒbdʒɪkt/"},{"pos":"v.","meaning":"反对;不赞成","definition":"to express disagreement","examples":[{"en":"Residents objected to the noisy development.","zh":"居民反对这个吵闹的开发项目。"},{"en":"I object to being treated unfairly.","zh":"我反对受到不公平对待。"}],"ipa":"/əbˈdʒekt/"}],"objectify":[{"pos":"v.","meaning":"物化；把人当作物品","definition":"to treat a person as an object rather than an individual","examples":[{"en":"The article criticises adverts that objectify people.","zh":"文章批评把人物化的广告。"},{"en":"The film challenges the tendency to objectify its characters.","zh":"电影挑战了把人物当作物品的倾向。"}]},{"pos":"v.","meaning":"使具体化；使客观化","definition":"to give an abstract idea an external form","examples":[{"en":"The sculpture objectifies a feeling of isolation.","zh":"雕塑把孤独感具体化了。"},{"en":"Writing helped her objectify her fears.","zh":"写作帮助她将恐惧外化。"}]}],"objection":[{"pos":"n.","meaning":"反对；异议；反对理由","definition":"A statement or reason expressing opposition.","examples":[{"en":"Nobody raised an objection to the plan.","zh":"没有人对计划提出异议。"},{"en":"Her main objection was the lack of parking space.","zh":"她反对的主要理由是停车位不足。"}]}],"objective":[{"pos":"adj.","meaning":"客观的","definition":"based on facts rather than personal feelings","examples":[{"en":"An objective assessment considers both strengths and weaknesses.","zh":"客观评估会同时考虑优点和缺点。"},{"en":"Journalists should aim to provide objective information.","zh":"记者应该努力提供客观信息。"},{"en":"It is hard to remain objective when discussing your own work.","zh":"讨论自己的工作时很难保持客观。"}]},{"pos":"n.","meaning":"目标","definition":"a goal to be achieved","examples":[{"en":"The main objective is to reduce traffic accidents.","zh":"主要目标是减少交通事故。"},{"en":"Set a clear objective before starting the project.","zh":"开始项目前设定明确目标。"},{"en":"Our objective is to improve access to education.","zh":"我们的目标是改善受教育机会。"}]}],"obligation":[{"pos":"n.","meaning":"义务；责任","definition":"something one must do because of duty or agreement","examples":[{"en":"She has an obligation to report the error.","zh":"她有责任报告错误。"},{"en":"The contract outlines each party's obligations.","zh":"合同列明双方的义务。"}]}],"obscene":[{"pos":"adj.","meaning":"淫秽的；猥亵的；下流的","definition":"Sexually offensive or indecent.","examples":[{"en":"The moderator removed an obscene comment.","zh":"管理员删除了一条淫秽评论。"},{"en":"The audience complained about the comedian's obscene language.","zh":"观众对喜剧演员的下流语言提出了投诉。"}]},{"pos":"adj.","meaning":"可憎的；大得惊人的；令人愤慨的","definition":"Shockingly excessive or morally offensive.","examples":[{"en":"The executives received obscene bonuses while workers lost their jobs.","zh":"工人失业之际，高管却获得了高得惊人的奖金。"},{"en":"The waste of food seemed obscene beside such poverty.","zh":"面对如此贫困，浪费食物显得令人愤慨。"}]}],"obscurity":[{"pos":"n.","meaning":"晦涩;模糊;费解","definition":"difficulty in seeing or understanding clearly","examples":[{"en":"The obscurity of the wording caused confusion.","zh":"措辞晦涩引起了混乱。"},{"en":"Mist hid the coastline in obscurity.","zh":"雾使海岸线模糊不清。"}]},{"pos":"n.","meaning":"默默无闻;不出名","definition":"the state of being little known","examples":[{"en":"The artist spent years in obscurity.","zh":"这位艺术家多年默默无闻。"},{"en":"The discovery rescued the author from obscurity.","zh":"这项发现让作者摆脱了不为人知的境地。"}]}],"observation":[{"pos":"n.","meaning":"观察；观测；监视","definition":"watching carefully to obtain information","examples":[{"en":"The study relied on direct observation.","zh":"研究依靠直接观察。"},{"en":"The equipment remained under observation overnight.","zh":"设备整夜处于监测之下。"}]},{"pos":"n.","meaning":"评论；观察所得","definition":"a remark based on what one notices","examples":[{"en":"She made an interesting observation about the design.","zh":"她对设计作了有趣的评论。"},{"en":"The report includes the guide's observations.","zh":"报告包含导游的观察意见。"}]}],"observe":[{"pos":"v.","meaning":"观察；察觉；注意到","definition":"To watch carefully or notice something.","examples":[{"en":"The students observed the birds from a shelter.","zh":"学生们从隐蔽处观察鸟类。"},{"en":"She observed a small crack in the glass.","zh":"她注意到玻璃上有一条细裂缝。"}]},{"pos":"v.","meaning":"遵守；奉行","definition":"To follow a rule, custom, or ceremony.","examples":[{"en":"All visitors must observe the safety rules.","zh":"所有游客必须遵守安全规定。"},{"en":"The family observes several traditional festivals.","zh":"这个家庭庆祝几个传统节日。"}]}],"obsession":[{"pos":"n.","meaning":"痴迷;萦绕心头的人或事;执念","definition":"a persistent and excessive preoccupation","examples":[{"en":"His obsession with perfection delayed the project.","zh":"他对完美的执着耽误了项目。"},{"en":"Collecting rare stamps became her obsession.","zh":"收藏稀有邮票成了她的痴迷。"}]}],"obstacle":[{"pos":"n.","meaning":"障碍；阻碍物","definition":"something that blocks movement or progress","examples":[{"en":"Funding remains the main obstacle.","zh":"资金仍是主要障碍。"},{"en":"The rider jumped over the obstacle.","zh":"骑手跃过了障碍。"}]}],"obstruct":[{"pos":"v.","meaning":"阻塞；堵住","definition":"To block a passage or view.","examples":[{"en":"A fallen branch obstructed the entrance.","zh":"一根断枝堵住了入口。"},{"en":"The new building obstructs our view of the river.","zh":"新楼挡住了我们看河的视线。"}]},{"pos":"v.","meaning":"妨碍；阻止；阻挠","definition":"To prevent or delay an activity.","examples":[{"en":"Poor communication obstructed progress.","zh":"沟通不畅阻碍了进展。"},{"en":"The witness was accused of obstructing the investigation.","zh":"证人被指控妨碍调查。"}]}],"obtain":[{"pos":"v.","meaning":"获得;得到","definition":"to get something through effort or a process","examples":[{"en":"She obtained permission to enter the archive.","zh":"她获准进入档案馆。"},{"en":"We obtained the samples from three sites.","zh":"我们从三个地点取得样本。"}]},{"pos":"v.","meaning":"存在;通行;适用（正式用语）","definition":"to exist or be generally accepted","examples":[{"en":"Similar conditions obtain in neighbouring regions.","zh":"邻近地区也存在类似情况。"},{"en":"The old custom still obtains in some villages.","zh":"这一古老习俗在一些村庄仍然通行。"}]}],"occasion":[{"pos":"n.","meaning":"时刻；场合；某次事件","definition":"a particular time when something happens","examples":[{"en":"I met her on several occasions.","zh":"我见过她几次。"},{"en":"This is not the occasion for an argument.","zh":"这不是争吵的场合。"}]},{"pos":"n.","meaning":"盛会；特殊活动","definition":"an important or special event","examples":[{"en":"The anniversary was a joyful occasion.","zh":"周年纪念是个欢乐盛会。"},{"en":"Everyone dressed formally for the occasion.","zh":"大家为这一特殊活动穿着正式。"}]},{"pos":"n.","meaning":"机会；时机","definition":"an opportunity to do something","examples":[{"en":"The visit gave us occasion to discuss the project.","zh":"访问给了我们讨论项目的机会。"},{"en":"I had no occasion to use the spare key.","zh":"我没有机会用到备用钥匙。"}]},{"pos":"n.","meaning":"起因；理由","definition":"a reason or cause for something","examples":[{"en":"There is no occasion for alarm.","zh":"没有惊慌的理由。"},{"en":"The delay was the occasion of much complaint.","zh":"延误引起了许多抱怨。"}]},{"pos":"v.","meaning":"引起；导致","definition":"to cause something","examples":[{"en":"The closure occasioned considerable inconvenience.","zh":"关闭造成了相当大的不便。"},{"en":"Her remarks occasioned a lengthy debate.","zh":"她的话引发了长时间的辩论。"}]}],"occasional":[{"pos":"adj.","meaning":"偶尔的；间或发生的","definition":"Happening from time to time rather than regularly.","examples":[{"en":"We heard occasional thunder in the distance.","zh":"我们偶尔听到远处的雷声。"},{"en":"She makes occasional visits to her old school.","zh":"她偶尔会回母校探访。"}]}],"occasionally":[{"pos":"adv.","meaning":"偶尔;有时","definition":"sometimes but not often","examples":[{"en":"We occasionally meet for lunch.","zh":"我们偶尔一起吃午饭。"},{"en":"The machine occasionally makes a strange noise.","zh":"机器偶尔发出奇怪声响。"}]}],"occupation":[{"pos":"n.","meaning":"职业","definition":"a person's job","examples":[{"en":"Please state your occupation on the form.","zh":"请在表格上填写职业。"},{"en":"Teaching was her chosen occupation.","zh":"教学是她选择的职业。"}]},{"pos":"n.","meaning":"占领；占用","definition":"the act of controlling or using a place","examples":[{"en":"The building was ready for occupation.","zh":"建筑已可入住。"},{"en":"The museum documents the military occupation.","zh":"博物馆记录了军事占领。"}]},{"pos":"n.","meaning":"消遣；活动","definition":"something done to spend time","examples":[{"en":"Gardening became his favourite occupation.","zh":"园艺成为他最喜欢的消遣。"},{"en":"Reading was a pleasant occupation on rainy days.","zh":"雨天阅读是一种愉快的消遣。"}]}],"occupy":[{"pos":"v.","meaning":"占据；占用；居住","definition":"To take up space, time, or a place.","examples":[{"en":"The table occupies most of the small room.","zh":"这张桌子占了小房间的大部分空间。"},{"en":"Three families occupy the building.","zh":"三户人家住在这栋楼里。"}]},{"pos":"v.","meaning":"占领","definition":"To take control of a place by force.","examples":[{"en":"The army occupied the port.","zh":"军队占领了港口。"},{"en":"Protesters occupied the empty hall overnight.","zh":"抗议者连夜占据了空礼堂。"}]},{"pos":"v.","meaning":"使忙于；使从事","definition":"To keep someone busy or interested.","examples":[{"en":"Puzzles occupied the children during the journey.","zh":"旅途中，拼图让孩子们有事可做。"},{"en":"She occupied herself with preparing the exhibition.","zh":"她忙于筹备展览。"}]}],"occur":[{"pos":"v.","meaning":"发生","definition":"to happen","examples":[{"en":"The accident occurred near the bridge.","zh":"事故发生在桥附近。"},{"en":"Errors may occur during data transfer.","zh":"数据传输时可能出现错误。"}]},{"pos":"v.","meaning":"存在;出现于","definition":"to be found in a place or situation","examples":[{"en":"This mineral occurs in volcanic rocks.","zh":"这种矿物存在于火山岩中。"},{"en":"The same phrase occurs throughout the poem.","zh":"同一短语在整首诗中反复出现。"}]}],"odd":[{"pos":"adj.","meaning":"奇怪的；不寻常的","definition":"unusual or unexpected","examples":[{"en":"There was an odd smell in the kitchen.","zh":"厨房里有一股奇怪的气味。"},{"en":"She gave him an odd look.","zh":"她奇怪地看了他一眼。"}]},{"pos":"adj.","meaning":"零星的；临时的","definition":"occasional or not part of a regular set","examples":[{"en":"He earned money doing odd jobs.","zh":"他靠打零工赚钱。"},{"en":"We used the odd free hour to decorate.","zh":"我们利用零星的空闲时间装修。"}]},{"pos":"adj.","meaning":"奇数的","definition":"not divisible by two without a remainder","examples":[{"en":"Seven is an odd number.","zh":"七是奇数。"},{"en":"Answer only the odd-numbered questions.","zh":"只回答奇数编号的题目。"}]}],"odour":[{"pos":"n.","meaning":"气味；异味","definition":"A noticeable smell.","examples":[{"en":"A sweet odour drifted from the bakery.","zh":"面包店飘来一股香甜的气味。"},{"en":"The room had an unpleasant odour of damp wood.","zh":"房间里有一股潮湿木头的难闻气味。"}]}],"offend":[{"pos":"v.","meaning":"冒犯;使厌恶","definition":"to upset or insult someone","examples":[{"en":"His careless joke offended several guests.","zh":"他随口的笑话冒犯了几位客人。"},{"en":"The strong smell offended her senses.","zh":"浓烈气味令她感到不适。"}]},{"pos":"v.","meaning":"违法;违犯","definition":"to break a law or rule","examples":[{"en":"Some prisoners offend again after release.","zh":"一些囚犯获释后再次犯罪。"},{"en":"The design offends against basic safety principles.","zh":"设计违反了基本安全原则。"}]}],"offensive":[{"pos":"adj.","meaning":"冒犯的；令人不快的","definition":"causing hurt, disgust, or anger","examples":[{"en":"The remark was deeply offensive.","zh":"这句话非常冒犯人。"},{"en":"An offensive smell came from the drain.","zh":"排水口发出难闻的气味。"}]},{"pos":"adj.","meaning":"进攻的；攻击性的","definition":"intended to attack","examples":[{"en":"The coach adopted an offensive strategy.","zh":"教练采用了进攻策略。"},{"en":"The exercise tested offensive capabilities.","zh":"演习测试了进攻能力。"}]},{"pos":"n.","meaning":"进攻；攻势","definition":"an organised attack or campaign","examples":[{"en":"The army launched an offensive.","zh":"军队发动了进攻。"},{"en":"The company began a marketing offensive.","zh":"公司展开了营销攻势。"}]}],"offset":[{"pos":"v.","meaning":"抵消；补偿；弥补","definition":"To balance one effect against another.","examples":[{"en":"Lower energy bills offset the cost of the new windows.","zh":"较低的能源账单抵消了新窗户的费用。"},{"en":"The extra staff helped offset the loss of experienced workers.","zh":"增加的人手帮助弥补了熟练工人流失的影响。"}]}],"offspring":[{"pos":"n.","meaning":"后代;子女;产物","definition":"the young of a person or animal or a resulting creation","examples":[{"en":"The bird feeds its offspring daily.","zh":"鸟每天喂养幼鸟。"},{"en":"The new theory was the offspring of their collaboration.","zh":"新理论是他们合作的产物。"}]}],"on the horizon":[{"pos":"phrase","meaning":"即将发生；初现端倪","definition":"likely to happen or appear soon","examples":[{"en":"Major changes are on the horizon.","zh":"重大变化即将发生。"},{"en":"A solution may be on the horizon.","zh":"解决方案可能即将出现。"}]}],"ongoing":[{"pos":"adj.","meaning":"正在进行的；持续的；不断发展的","definition":"Continuing to happen, exist, or develop.","examples":[{"en":"The investigation is ongoing.","zh":"调查仍在进行。"},{"en":"The school provides ongoing support for new teachers.","zh":"学校为新教师提供持续支持。"}]}],"onslaught":[{"pos":"n.","meaning":"猛攻;猛烈袭击","definition":"a fierce attack or overwhelming rush","examples":[{"en":"The defenders resisted the onslaught.","zh":"防守者抵挡了猛攻。"},{"en":"The announcement triggered an onslaught of complaints.","zh":"公告引发了大量投诉的猛烈冲击。"}]}],"onwards":[{"pos":"adv.","meaning":"向前；往后继续","definition":"forward in place or time","examples":[{"en":"We walked onwards through the valley.","zh":"我们继续向前穿过山谷。"},{"en":"From April onwards, the park stays open later.","zh":"从四月起，公园延长开放时间。"}]}],"opaque":[{"pos":"adj.","meaning":"不透明的","definition":"Not allowing light to pass through.","examples":[{"en":"The bottle is made of opaque glass.","zh":"这个瓶子用不透明玻璃制成。"},{"en":"An opaque screen hides the storage area.","zh":"一块不透明屏风遮住了储物区。"}]},{"pos":"adj.","meaning":"晦涩的；难懂的；不透明的","definition":"Difficult to understand or examine.","examples":[{"en":"The contract was written in opaque language.","zh":"合同用语晦涩难懂。"},{"en":"The company's decision-making process remained opaque.","zh":"公司的决策过程依然不透明。"}]}],"operate":[{"pos":"v.","meaning":"运转;操作","definition":"to function or control a machine","examples":[{"en":"The lift operates smoothly.","zh":"电梯运行平稳。"},{"en":"Only trained workers may operate the crane.","zh":"只有受训工人可以操作起重机。"}]},{"pos":"v.","meaning":"经营;开展业务","definition":"to run a business or service","examples":[{"en":"The company operates three factories.","zh":"公司经营三家工厂。"},{"en":"The charity operates in several countries.","zh":"慈善机构在几个国家开展业务。"}]},{"pos":"v.","meaning":"动手术","definition":"to perform a surgical procedure","examples":[{"en":"The surgeon operated on his injured knee.","zh":"外科医生给他受伤的膝盖做了手术。"},{"en":"The team operated through the night.","zh":"医疗团队整夜进行手术。"}]},{"pos":"v.","meaning":"起作用;生效","definition":"to have an effect or be in force","examples":[{"en":"The rule operates throughout the school.","zh":"规则在全校生效。"},{"en":"Several factors operate together to shape demand.","zh":"几个因素共同起作用，影响需求。"}]}],"operational":[{"pos":"adj.","meaning":"运行中的；可使用的","definition":"ready for use or working","examples":[{"en":"The new system is fully operational.","zh":"新系统已完全投入运行。"},{"en":"The bridge will become operational in June.","zh":"大桥将于六月启用。"}]},{"pos":"adj.","meaning":"操作的；运营的；业务的","definition":"relating to practical activities and functioning","examples":[{"en":"The report identifies operational problems.","zh":"报告指出了运营问题。"},{"en":"Staff received operational training.","zh":"员工接受了操作培训。"}]}],"opponent":[{"pos":"n.","meaning":"对手；敌手；反对者","definition":"Someone competing against or opposing another person or idea.","examples":[{"en":"She defeated a strong opponent in the final.","zh":"她在决赛中击败了一位强劲对手。"},{"en":"Opponents of the road scheme organised a petition.","zh":"道路方案的反对者组织了请愿。"}]},{"pos":"adj.","meaning":"对抗的；相对作用的","definition":"Acting against or in contrast to something else.","examples":[{"en":"The theory describes opponent processes that balance each other.","zh":"该理论描述了相互平衡的对抗过程。"},{"en":"Opponent forces pulled the structure in different directions.","zh":"相对作用的力把结构拉向不同方向。"}]}],"opportunity":[{"pos":"n.","meaning":"机会;时机","definition":"a favourable chance to do something","examples":[{"en":"The internship offered valuable learning opportunities.","zh":"实习提供了宝贵学习机会。"},{"en":"She seized the opportunity to ask a question.","zh":"她抓住机会提了一个问题。"}]}],"oppose":[{"pos":"v.","meaning":"反对；抵制","definition":"to disagree with or act against something","examples":[{"en":"Residents opposed the road closure.","zh":"居民反对封路。"},{"en":"Several members opposed the amendment.","zh":"几位成员反对修正案。"}]}],"opposite":[{"pos":"prep.","meaning":"在……对面","definition":"Across from and facing something.","examples":[{"en":"The café is opposite the station.","zh":"咖啡馆在车站对面。"},{"en":"She sat opposite me at the table.","zh":"她在桌边坐在我对面。"}]},{"pos":"adj.","meaning":"对面的；相反的；对立的","definition":"Facing something or completely different from it.","examples":[{"en":"We walked in opposite directions.","zh":"我们朝相反方向走去。"},{"en":"The two candidates expressed opposite views.","zh":"两位候选人表达了相反的观点。"}]},{"pos":"n.","meaning":"相反的人或物；对立面","definition":"A person or thing completely different from another.","examples":[{"en":"Her brother is her exact opposite.","zh":"她哥哥与她完全相反。"},{"en":"Instead of improving, the situation did the opposite.","zh":"情况非但没有改善，反而变坏了。"}]}],"optic":[{"pos":"adj.","meaning":"眼的;视觉的;光学的","definition":"relating to sight, the eyes, or light","examples":[{"en":"The optic nerve carries signals from the eye.","zh":"视神经传递来自眼睛的信号。"},{"en":"Fibre-optic cables carry data using light.","zh":"光纤电缆利用光传输数据。"}]},{"pos":"n.","meaning":"光学仪器;光学镜片","definition":"a lens or optical instrument","examples":[{"en":"The technician cleaned the telescope's optics.","zh":"技术员清洁了望远镜的光学镜片。"},{"en":"A damaged optic blurred the image.","zh":"受损镜片使图像模糊。"}]}],"optical":[{"pos":"adj.","meaning":"视觉的；视力的","definition":"relating to sight","examples":[{"en":"The pattern creates an optical illusion.","zh":"图案造成了视觉错觉。"},{"en":"The test measures optical performance.","zh":"测试测量视觉性能。"}]},{"pos":"adj.","meaning":"光学的","definition":"relating to light and its behaviour","examples":[{"en":"The laboratory uses optical instruments.","zh":"实验室使用光学仪器。"},{"en":"An optical fibre carries the signal.","zh":"光纤传输信号。"}]}],"optimism":[{"pos":"n.","meaning":"乐观；乐观主义","definition":"A tendency to expect good outcomes.","examples":[{"en":"There is growing optimism about the rescue effort.","zh":"人们对救援行动越来越乐观。"},{"en":"Her optimism helped the team continue.","zh":"她的乐观帮助团队继续坚持。"}]}],"optimistic":[{"pos":"adj.","meaning":"乐观的","definition":"expecting good results","examples":[{"en":"She remains optimistic about the recovery.","zh":"她对恢复仍持乐观态度。"},{"en":"The report gives an optimistic forecast.","zh":"报告给出了乐观预测。"}]}],"optimum":[{"pos":"adj.","meaning":"最佳的；最有利的","definition":"best for achieving a particular result","examples":[{"en":"The seeds need optimum growing conditions.","zh":"种子需要最佳生长条件。"},{"en":"The study identified the optimum temperature.","zh":"研究确定了最佳温度。"}]}],"option":[{"pos":"n.","meaning":"选择；选择权；可选事物","definition":"Something that can be chosen or the freedom to choose.","examples":[{"en":"Taking the train is our cheapest option.","zh":"乘火车是我们最便宜的选择。"},{"en":"You have the option of working from home.","zh":"你可以选择在家工作。"}]},{"pos":"n.","meaning":"选修课；选修项目","definition":"A subject chosen from a set of available courses.","examples":[{"en":"She chose photography as an option.","zh":"她选修了摄影。"},{"en":"The department offers several language options.","zh":"该系提供几门语言选修课。"}]}],"optional":[{"pos":"adj.","meaning":"可选择的;非强制的","definition":"available by choice rather than required","examples":[{"en":"Attendance at the workshop is optional.","zh":"参加工作坊是自愿的。"},{"en":"The course includes two optional modules.","zh":"课程包括两个选修单元。"}]}],"optometrist":[{"pos":"n.","meaning":"验光师；视光师","definition":"a professional who examines vision and prescribes corrective lenses","examples":[{"en":"The optometrist checked her vision.","zh":"验光师检查了她的视力。"},{"en":"He booked an appointment with an optometrist.","zh":"他预约了验光师。"}]}],"opulence":[{"pos":"n.","meaning":"富裕；奢华；富丽堂皇","definition":"Great wealth or luxurious abundance.","examples":[{"en":"The palace's opulence astonished the visitors.","zh":"宫殿的富丽堂皇令游客惊叹。"},{"en":"The hotel combines modern comfort with traditional opulence.","zh":"这家酒店将现代舒适与传统奢华结合起来。"}]}],"opulent":[{"pos":"adj.","meaning":"豪华的;富裕的;丰盛的","definition":"rich, luxurious, or abundant","examples":[{"en":"The palace has an opulent dining room.","zh":"宫殿里有豪华餐厅。"},{"en":"The guests enjoyed an opulent feast.","zh":"宾客享用了丰盛宴席。"}]}],"orbit":[{"pos":"n.","meaning":"轨道","definition":"the path of one object around another","examples":[{"en":"The satellite entered orbit.","zh":"卫星进入了轨道。"},{"en":"The planet follows an elliptical orbit.","zh":"这颗行星沿椭圆轨道运行。"}]},{"pos":"n.","meaning":"影响范围；活动范围","definition":"a sphere of influence or activity","examples":[{"en":"The alliance brought the state into a new political orbit.","zh":"联盟使该国进入新的政治影响范围。"},{"en":"The issue lies outside the committee's usual orbit.","zh":"这个问题超出了委员会通常的活动范围。"}]},{"pos":"v.","meaning":"绕轨道运行；围绕运动","definition":"to travel around another body","examples":[{"en":"The moon orbits Earth.","zh":"月球绕地球运行。"},{"en":"A spacecraft orbited the planet for months.","zh":"航天器绕该行星运行了数月。"}]}],"orchestra":[{"pos":"n.","meaning":"管弦乐队","definition":"A large group of musicians playing strings, winds, and percussion.","examples":[{"en":"The orchestra tuned its instruments before the concert.","zh":"音乐会前，管弦乐队调好了乐器。"},{"en":"She plays the violin in a youth orchestra.","zh":"她在青年管弦乐队拉小提琴。"}]}],"organ":[{"pos":"n.","meaning":"器官","definition":"a body part performing a particular function","examples":[{"en":"The heart is a vital organ.","zh":"心脏是重要器官。"},{"en":"The disease can affect several organs.","zh":"疾病可影响多个器官。"}]},{"pos":"n.","meaning":"机构;机关","definition":"an official part of a larger organization","examples":[{"en":"The council is an advisory organ.","zh":"理事会是咨询机构。"},{"en":"The constitution defines the principal organs of government.","zh":"宪法规定了主要政府机关。"}]},{"pos":"n.","meaning":"管风琴;风琴","definition":"a keyboard instrument producing sustained musical tones","examples":[{"en":"The organ filled the church with music.","zh":"管风琴的音乐充满教堂。"},{"en":"She practises the organ every Saturday.","zh":"她每周六练习风琴。"}]}],"organic":[{"pos":"adj.","meaning":"有机的（化学）","definition":"relating mainly to carbon compounds","examples":[{"en":"The laboratory studies organic compounds.","zh":"实验室研究有机化合物。"},{"en":"She took a course in organic chemistry.","zh":"她修了一门有机化学课程。"}]},{"pos":"adj.","meaning":"生物的；来自生物体的","definition":"relating to living things or their remains","examples":[{"en":"Organic matter improves the soil.","zh":"有机物改善土壤。"},{"en":"The sediment contains organic remains.","zh":"沉积物中含有生物遗存。"}]},{"pos":"adj.","meaning":"器官的；器质性的","definition":"relating to bodily organs or structural changes in them","examples":[{"en":"The examination found no organic cause.","zh":"检查没有发现器质性原因。"},{"en":"The chapter discusses organic disorders.","zh":"本章讨论器质性疾病。"}]},{"pos":"adj.","meaning":"有机种植的；有机生产的","definition":"produced under farming systems restricting synthetic chemicals","examples":[{"en":"The farm grows organic vegetables.","zh":"农场种植有机蔬菜。"},{"en":"The shop sells certified organic produce.","zh":"商店销售经认证的有机农产品。"}]},{"pos":"adj.","meaning":"有机联系的；自然发展的","definition":"forming an integrated whole or developing naturally","examples":[{"en":"The city grew in an organic way.","zh":"城市以自然方式发展。"},{"en":"The essay argues for an organic unity between form and content.","zh":"文章主张形式与内容之间的有机统一。"}]}],"organism":[{"pos":"n.","meaning":"生物；有机体","definition":"An individual living thing.","examples":[{"en":"The pond contains many microscopic organisms.","zh":"池塘里有许多微小生物。"},{"en":"Every organism depends on its environment for resources.","zh":"每个生物体都依靠环境获取资源。"}]}],"organize":[{"pos":"v.","meaning":"组织;安排;整理;成立","definition":"to arrange systematically or establish a group","examples":[{"en":"Volunteers organized a neighbourhood clean-up.","zh":"志愿者组织了社区清扫。"},{"en":"Organize the files by date.","zh":"按日期整理文件。"}]}],"orientate":[{"pos":"v.","meaning":"使熟悉环境；使适应","definition":"to help someone understand a new place or situation","examples":[{"en":"The tour helped us orientate ourselves.","zh":"参观帮助我们熟悉了环境。"},{"en":"New staff need time to orientate themselves.","zh":"新员工需要时间适应环境。"}]},{"pos":"v.","meaning":"定向；使朝向","definition":"to position something in a particular direction","examples":[{"en":"Orientate the panel towards the sun.","zh":"把面板朝向太阳。"},{"en":"The map must be orientated to the north.","zh":"地图必须对准北方。"}]}],"orientation":[{"pos":"n.","meaning":"方向；定位；朝向","definition":"The direction in which something faces or its position relative to other things.","examples":[{"en":"The house's orientation allows sunlight into the kitchen.","zh":"房屋的朝向使阳光能够照进厨房。"},{"en":"A compass helps with orientation in dense forest.","zh":"指南针有助于在密林中辨明方向。"}]},{"pos":"n.","meaning":"入门介绍；适应培训","definition":"Information or training that helps someone understand a new setting.","examples":[{"en":"New students attend an orientation session.","zh":"新生参加入学介绍活动。"},{"en":"The company provides a week of orientation for new staff.","zh":"公司为新员工提供为期一周的入职培训。"}]}],"orientation meeting":[{"pos":"n. phr.","meaning":"新生报到会;迎新介绍会","definition":"a meeting introducing newcomers to an institution","examples":[{"en":"The orientation meeting explained campus services.","zh":"迎新会介绍了校园服务。"},{"en":"New students attended an orientation meeting on Monday.","zh":"新生周一参加了报到介绍会。"}]}],"origin":[{"pos":"n.","meaning":"起源；来源","definition":"the place or cause from which something begins","examples":[{"en":"The custom's origin is uncertain.","zh":"这个习俗的起源不确定。"},{"en":"Researchers traced the origin of the material.","zh":"研究人员追溯了材料的来源。"}]},{"pos":"n.","meaning":"出身；血统（常用复数）","definition":"a person's family or social background","examples":[{"en":"She was proud of her rural origins.","zh":"她为自己的乡村出身感到自豪。"},{"en":"The novel explores the family's origins.","zh":"小说探讨了家族的出身。"}]}],"original":[{"pos":"adj.","meaning":"最初的；原始的","definition":"Existing at the beginning or before changes were made.","examples":[{"en":"We returned to the original plan.","zh":"我们回到了最初的计划。"},{"en":"The building still has its original windows.","zh":"大楼仍保留着原来的窗户。"}]},{"pos":"adj.","meaning":"独创的；新颖的","definition":"New and created independently rather than copied.","examples":[{"en":"She proposed an original solution to the problem.","zh":"她提出了一个有创意的解决方案。"},{"en":"The exhibition features highly original designs.","zh":"展览展出了极具独创性的设计。"}]},{"pos":"n.","meaning":"原件；原作；原物","definition":"The first version from which copies are made.","examples":[{"en":"Keep the original and send us a copy.","zh":"请保留原件，寄给我们一份副本。"},{"en":"The painting is an original, not a reproduction.","zh":"这幅画是真迹，不是复制品。"}]}],"originate":[{"pos":"v.","meaning":"起源;源自","definition":"to begin or come from somewhere","examples":[{"en":"The river originates in the mountains.","zh":"河流发源于山区。"},{"en":"The idea originated during a workshop.","zh":"这个想法产生于一次工作坊。"}]},{"pos":"v.","meaning":"首创;创立","definition":"to create or begin something","examples":[{"en":"She originated the award-winning design.","zh":"她首创了这个获奖设计。"},{"en":"The committee originated a new exchange programme.","zh":"委员会创立了新的交流项目。"}]}],"ornament":[{"pos":"n.","meaning":"装饰品；装饰","definition":"something added to make an object attractive","examples":[{"en":"A glass ornament stood on the shelf.","zh":"架子上摆着玻璃装饰品。"},{"en":"The building uses little ornament.","zh":"这栋建筑装饰很少。"}]},{"pos":"v.","meaning":"装饰；美化","definition":"to decorate something","examples":[{"en":"Carved leaves ornament the doorway.","zh":"雕刻的叶子装饰着门口。"},{"en":"She ornamented the box with shells.","zh":"她用贝壳装饰盒子。"}]}],"ornamental":[{"pos":"adj.","meaning":"装饰性的；供观赏的","definition":"Used mainly to make something look attractive.","examples":[{"en":"An ornamental fountain stands in the courtyard.","zh":"庭院里有一座装饰性喷泉。"},{"en":"The nursery sells ornamental trees.","zh":"苗圃出售观赏树木。"}]}],"orthodox":[{"pos":"adj.","meaning":"正统的;传统的","definition":"following accepted beliefs or practices","examples":[{"en":"His views challenged orthodox economic thinking.","zh":"他的观点挑战了正统经济思想。"},{"en":"The doctor recommended an orthodox approach.","zh":"医生建议采用常规方法。"}]}],"otherwise":[{"pos":"adv.","meaning":"以其他方式；不然","definition":"in a different way","examples":[{"en":"The instructions say otherwise.","zh":"说明中的说法并非如此。"},{"en":"We assumed it was free unless told otherwise.","zh":"除非另有告知，我们认为这是免费的。"}]},{"pos":"adv.","meaning":"在其他方面","definition":"in other respects","examples":[{"en":"The roof leaks, but the house is otherwise sound.","zh":"屋顶漏水，但房子其他方面都很好。"},{"en":"She was tired but otherwise well.","zh":"她有点累，但其他方面都好。"}]},{"pos":"adv.","meaning":"否则；要不然","definition":"if not","examples":[{"en":"Leave now; otherwise, you may miss the train.","zh":"现在出发，否则你可能赶不上火车。"},{"en":"Save the file, otherwise your changes will be lost.","zh":"保存文件，否则修改会丢失。"}]}],"ounce":[{"pos":"n.","meaning":"盎司","definition":"A unit used to measure weight, approximately 28 grams in ordinary use.","examples":[{"en":"The parcel weighs eight ounces.","zh":"这个包裹重八盎司。"},{"en":"The recipe calls for two ounces of butter.","zh":"食谱需要两盎司黄油。"}]}],"outcome":[{"pos":"n.","meaning":"结果;成果;结局","definition":"the result of a process or event","examples":[{"en":"The talks produced a positive outcome.","zh":"会谈取得了积极成果。"},{"en":"No one could predict the trial's outcome.","zh":"没人能预测审判结果。"}]}],"outdo":[{"pos":"v.","meaning":"胜过；超过","definition":"to perform better than someone or something","examples":[{"en":"She outdid her previous record.","zh":"她超过了自己以前的纪录。"},{"en":"The restaurants compete to outdo each other.","zh":"餐馆竞相超过彼此。"}]}],"outlaw":[{"pos":"n.","meaning":"逃犯；亡命之徒；被宣布不受法律保护者","definition":"A person living outside the law or avoiding arrest.","examples":[{"en":"The story follows an outlaw hiding in the mountains.","zh":"故事讲述了一个藏身山中的逃犯。"},{"en":"The sheriff searched for the escaped outlaw.","zh":"治安官搜寻那个逃走的亡命之徒。"}]},{"pos":"v.","meaning":"宣布为非法；取缔","definition":"To make an activity illegal.","examples":[{"en":"The law outlawed the dumping of waste in rivers.","zh":"法律禁止向河流倾倒废物。"},{"en":"The treaty outlawed the use of those weapons.","zh":"条约禁止使用那些武器。"}]}],"outline":[{"pos":"n.","meaning":"轮廓;外形","definition":"the outer shape of something","examples":[{"en":"The mountain's outline appeared through the mist.","zh":"山的轮廓从雾中显现。"},{"en":"Trace the outline of your hand.","zh":"描出手的轮廓。"}]},{"pos":"n.","meaning":"提纲;梗概;草图","definition":"a summary or basic plan","examples":[{"en":"She prepared an outline for the essay.","zh":"她为文章准备了提纲。"},{"en":"The architect showed us a rough outline.","zh":"建筑师给我们看了粗略草图。"}]},{"pos":"v.","meaning":"概述;列出提纲;勾勒","definition":"to state the main points or draw the shape","examples":[{"en":"The speaker outlined the main challenges.","zh":"演讲者概述了主要挑战。"},{"en":"He outlined the figure with a pencil.","zh":"他用铅笔勾勒人物轮廓。"}]}],"outlook":[{"pos":"n.","meaning":"观点；人生观","definition":"a way of thinking about life or a situation","examples":[{"en":"Travel broadened her outlook.","zh":"旅行开阔了她的视野。"},{"en":"He has an optimistic outlook.","zh":"他有乐观的人生观。"}]},{"pos":"n.","meaning":"前景；展望","definition":"what is likely to happen in the future","examples":[{"en":"The economic outlook remains uncertain.","zh":"经济前景仍不确定。"},{"en":"The outlook for recovery has improved.","zh":"复苏前景有所改善。"}]}],"outpost":[{"pos":"n.","meaning":"前哨；哨所；边远驻地","definition":"A small station far from the main settlement or force.","examples":[{"en":"The soldiers guarded a remote outpost.","zh":"士兵守卫着一处偏远前哨。"},{"en":"The trading outpost gradually grew into a town.","zh":"这个贸易站逐渐发展成一座城镇。"}]}],"output":[{"pos":"n.","meaning":"产量;输出;输出功率","definition":"the amount produced or delivered by a system","examples":[{"en":"Factory output rose this month.","zh":"本月工厂产量上升。"},{"en":"The generator has a high power output.","zh":"发电机输出功率很高。"}]},{"pos":"v.","meaning":"输出","definition":"to produce or deliver information or energy","examples":[{"en":"The program outputs a detailed report.","zh":"程序输出详细报告。"},{"en":"The device outputs a digital signal.","zh":"装置输出数字信号。"}]}],"outsell":[{"pos":"v.","meaning":"比……卖得多","definition":"to sell in greater quantities than another product","examples":[{"en":"The new edition outsold the original.","zh":"新版比原版卖得更多。"},{"en":"Bicycles outsold scooters at the shop.","zh":"这家店的自行车销量超过了踏板车。"}]}],"outward":[{"pos":"adj.","meaning":"外部的；外表的；表面的","definition":"Visible on the outside rather than relating to inner feelings.","examples":[{"en":"There were no outward signs of damage.","zh":"外表上没有受损迹象。"},{"en":"Her outward calm hid considerable anxiety.","zh":"她外表的平静掩饰着极大的焦虑。"}]}],"outweigh":[{"pos":"v.","meaning":"比……更重要;超过","definition":"to be greater in importance or value","examples":[{"en":"The benefits outweigh the costs.","zh":"收益大于成本。"},{"en":"Safety considerations outweigh convenience.","zh":"安全考量比便利更重要。"}]},{"pos":"v.","meaning":"比……重","definition":"to be heavier than","examples":[{"en":"The adult outweighs the cub several times over.","zh":"成年动物的体重是幼崽的数倍。"},{"en":"The loaded suitcase outweighs the empty one considerably.","zh":"装满的手提箱比空箱重得多。"}]}],"overall":[{"pos":"adj.","meaning":"全面的；总体的","definition":"considering everything together","examples":[{"en":"The overall cost was lower than expected.","zh":"总成本低于预期。"},{"en":"The review praised the overall design.","zh":"评审赞扬了整体设计。"}]}],"overcome":[{"pos":"v.","meaning":"克服；战胜","definition":"To succeed in dealing with a difficulty or opponent.","examples":[{"en":"She overcame her fear of public speaking.","zh":"她克服了公开演讲的恐惧。"},{"en":"The team overcame several setbacks to finish the project.","zh":"团队克服数次挫折，完成了项目。"}]},{"pos":"v.","meaning":"使不堪承受；压倒","definition":"To affect someone so strongly that normal control is lost.","examples":[{"en":"He was overcome with relief when the child was found.","zh":"孩子找到时，他如释重负，激动不已。"},{"en":"Two workers were overcome by smoke.","zh":"两名工人被浓烟熏倒了。"}]}],"overdraft":[{"pos":"n.","meaning":"透支;透支额","definition":"money withdrawn beyond an account's available balance","examples":[{"en":"The bank approved a small overdraft.","zh":"银行批准了一小笔透支额度。"},{"en":"He cleared his overdraft after payday.","zh":"发薪后他还清了透支款。"}]}],"overdue":[{"pos":"adj.","meaning":"逾期的；延误的；过期未付的","definition":"later than the expected or required time","examples":[{"en":"The library book is overdue.","zh":"图书馆借书逾期了。"},{"en":"Payment is now two weeks overdue.","zh":"款项现已逾期两周。"}]},{"pos":"adj.","meaning":"早该发生的；迟迟未实现的","definition":"needed or expected long before now","examples":[{"en":"The building needs a long-overdue repair.","zh":"这栋建筑需要早该进行的维修。"},{"en":"The award was overdue recognition of her work.","zh":"这个奖项是对她工作迟来的认可。"}]},{"pos":"adj.","meaning":"过度的；过分的（少见义）","definition":"excessive in amount or importance","examples":[{"en":"The agreement gave one partner an overdue share of the earnings, leaving the others very little.","zh":"协议给予一位合伙人过多的收益份额，留给其他人的很少。"},{"en":"The critic assigned overdue importance to a minor detail and ignored the main argument.","zh":"这位评论者过分重视一个次要细节，却忽视了主要论点。"}]}],"overestimate":[{"pos":"v.","meaning":"高估；估计过高","definition":"To judge an amount or ability as greater than it really is.","examples":[{"en":"We overestimated how many guests would attend.","zh":"我们高估了到场宾客的人数。"},{"en":"Do not overestimate your ability on a difficult climb.","zh":"在艰难攀登中不要高估自己的能力。"}],"ipa":"/ˌəʊvəˈrestɪmeɪt/"},{"pos":"n.","meaning":"过高的估计","definition":"An estimate that exceeds the true amount or value.","examples":[{"en":"The budget included a large overestimate of fuel costs.","zh":"预算大幅高估了燃料成本。"},{"en":"The original forecast proved to be an overestimate.","zh":"最初的预测被证明估计过高。"}],"ipa":"/ˌəʊvəˈrestɪmət/"}],"overexploit":[{"pos":"v.","meaning":"过度开发;过度利用","definition":"to use a resource beyond sustainable limits","examples":[{"en":"The fleet overexploited local fish stocks.","zh":"船队过度捕捞了当地鱼类资源。"},{"en":"Farmers were warned not to overexploit groundwater.","zh":"农民受到警告，不要过度开采地下水。"}]}],"overfill":[{"pos":"v.","meaning":"装得过满；装至溢出","definition":"to fill beyond capacity","examples":[{"en":"Do not overfill the kettle.","zh":"不要把水壶装得过满。"},{"en":"The suitcase was overfilled and would not close.","zh":"箱子装得太满，合不上。"}]}],"overgraze":[{"pos":"v.","meaning":"过度放牧；过度啃食","definition":"To allow animals to feed on land so heavily that vegetation is damaged.","examples":[{"en":"Too many sheep had overgrazed the hillside.","zh":"过多的羊使山坡遭到过度放牧。"},{"en":"The reserve limits cattle numbers to avoid overgrazing the grassland.","zh":"保护区限制牛的数量，以免草原被过度啃食。"}]}],"overhead":[{"pos":"adj.","meaning":"头顶上的;高架的","definition":"located above head level","examples":[{"en":"An overhead cable supplies the tram.","zh":"高架电缆为电车供电。"},{"en":"Put your bag in the overhead locker.","zh":"把包放在头顶行李柜里。"}],"ipa":"/ˈəʊvəhed/"},{"pos":"adv.","meaning":"在头顶上;在空中","definition":"above the head or high in the air","examples":[{"en":"Geese flew overhead.","zh":"雁从头顶飞过。"},{"en":"Thunder rumbled directly overhead.","zh":"雷声就在头顶轰鸣。"}],"ipa":"/ˌəʊvəˈhed/"},{"pos":"n.","meaning":"管理费用;经常性开支","definition":"ongoing costs of running a business","examples":[{"en":"Rent is a major overhead.","zh":"租金是一项主要经常性支出。"},{"en":"The firm reduced its overheads.","zh":"公司降低了管理开支。"}],"ipa":"/ˈəʊvəhed/"},{"pos":"n.","meaning":"舱室天花板（航海用语）","definition":"the ceiling of a ship's compartment","examples":[{"en":"A lamp hung from the cabin overhead.","zh":"一盏灯从船舱天花板垂下。"},{"en":"The sailor repainted the overhead white.","zh":"水手把舱顶重新漆成白色。"}],"ipa":"/ˈəʊvəhed/"}],"overlap":[{"pos":"v.","meaning":"部分重叠；交叠","definition":"to cover part of the same area or share features","examples":[{"en":"The two circles overlap.","zh":"两个圆部分重叠。"},{"en":"Our responsibilities overlap in several areas.","zh":"我们的职责在几个方面有重合。"}]}],"overlapping":[{"pos":"adj.","meaning":"重叠的；部分相同的","definition":"Sharing part of the same area, time, or responsibility.","examples":[{"en":"The roof is covered with overlapping tiles.","zh":"屋顶覆盖着相互搭叠的瓦片。"},{"en":"The two departments have overlapping responsibilities.","zh":"这两个部门的职责有部分重叠。"}]}],"overlie":[{"pos":"v.","meaning":"覆盖在……上;位于……之上","definition":"to lie on top of something","examples":[{"en":"Clay overlies the older rock.","zh":"黏土覆盖在较老的岩层上。"},{"en":"A thin layer of sand overlies the gravel.","zh":"一层薄沙覆在砾石上。"}]}],"overrate":[{"pos":"v.","meaning":"高估；过高评价","definition":"to consider something better than it is","examples":[{"en":"The review overrated the hotel's facilities.","zh":"评价高估了酒店设施。"},{"en":"He tends to overrate his own influence.","zh":"他往往高估自己的影响力。"}]}],"overseas":[{"pos":"adj.","meaning":"海外的；国外的","definition":"Located in or relating to a foreign country across the sea.","examples":[{"en":"The company opened an overseas office.","zh":"公司开设了一个海外办事处。"},{"en":"Overseas students attended the welcome event.","zh":"国际学生参加了欢迎活动。"}]},{"pos":"adv.","meaning":"在海外；到国外","definition":"In or to a foreign country.","examples":[{"en":"She hopes to study overseas.","zh":"她希望出国学习。"},{"en":"The goods are shipped overseas every week.","zh":"这些货物每周运往海外。"}]}],"oversee":[{"pos":"v.","meaning":"监督;监管","definition":"to supervise work or activity","examples":[{"en":"She oversees the restoration project.","zh":"她监督修复项目。"},{"en":"An independent panel oversaw the review.","zh":"独立小组监督了审查。"}]},{"pos":"v.","meaning":"俯瞰;眺望（较少用）","definition":"to survey from a higher position","examples":[{"en":"From the tower, guards could oversee the valley.","zh":"守卫从塔上可以俯瞰山谷。"},{"en":"The hilltop allowed us to oversee the entire plain.","zh":"山顶让我们能眺望整个平原。"}]}],"overshadow":[{"pos":"v.","meaning":"遮蔽；给……蒙上阴影","definition":"to cast a shadow or make an event less pleasant","examples":[{"en":"Tall buildings overshadow the garden.","zh":"高楼遮住了花园的阳光。"},{"en":"The accident overshadowed the celebration.","zh":"事故给庆祝活动蒙上了阴影。"}]},{"pos":"v.","meaning":"使黯然失色","definition":"to seem much more important or impressive than something else","examples":[{"en":"Her later success overshadowed her early work.","zh":"她后来的成功使早期作品显得逊色。"},{"en":"One dramatic scene overshadowed the rest of the film.","zh":"一个戏剧性场景使影片其他部分黯然失色。"}]}],"overtime":[{"pos":"n.","meaning":"加班；加班时间","definition":"time spent working beyond normal hours","examples":[{"en":"Staff receive extra pay for overtime.","zh":"员工加班可获得额外报酬。"},{"en":"Too much overtime can affect your health.","zh":"过多加班会影响健康。"},{"en":"We worked overtime to finish the urgent order.","zh":"我们加班完成了紧急订单。"}]}],"overview":[{"pos":"n.","meaning":"概览;概述","definition":"a general summary","examples":[{"en":"The chapter gives an overview of the debate.","zh":"这一章概述了争论。"},{"en":"The dashboard provides an overview of sales.","zh":"仪表板提供销售概览。"}]}],"overweight":[{"pos":"adj.","meaning":"超重的；过重的","definition":"heavier than a recommended or permitted weight","examples":[{"en":"The suitcase was overweight.","zh":"手提箱超重了。"},{"en":"The survey recorded how many participants were overweight.","zh":"调查记录了多少参与者超重。"}]},{"pos":"n.","meaning":"超重；过重","definition":"weight above a desirable or permitted amount","examples":[{"en":"The report examines the prevalence of overweight.","zh":"报告考察超重的普遍程度。"},{"en":"The airline charged for the bag's overweight.","zh":"航空公司对行李超重收费。"}]},{"pos":"v.","meaning":"使负担过重；赋予过多权重","definition":"to load too heavily or give excessive importance","examples":[{"en":"The extra equipment overweighted the small boat.","zh":"额外设备使小船负载过重。"},{"en":"The model overweights recent observations.","zh":"模型给予近期观测值过高权重。"}]}],"overwhelm":[{"pos":"v.","meaning":"压倒；击败；征服","definition":"To defeat or affect with far greater force.","examples":[{"en":"The defenders were overwhelmed by a larger army.","zh":"守军被一支更庞大的军队击败了。"},{"en":"The volume of requests overwhelmed the small team.","zh":"大量请求使这个小团队不堪重负。"}]},{"pos":"v.","meaning":"淹没；使沉没","definition":"To cover completely with water or another force.","examples":[{"en":"Floodwater overwhelmed the low embankment.","zh":"洪水淹没了低矮的堤岸。"},{"en":"A huge wave overwhelmed the small boat.","zh":"巨浪吞没了小船。"}]},{"pos":"v.","meaning":"使情绪强烈；使难以承受","definition":"To fill someone with an overpowering emotion.","examples":[{"en":"The welcome overwhelmed her with gratitude.","zh":"热情欢迎让她满怀感激。"},{"en":"He felt overwhelmed by the kindness of strangers.","zh":"陌生人的善意令他感动不已。"}]}],"overwork":[{"pos":"v.","meaning":"过度工作;使过劳","definition":"to work or make someone work too much","examples":[{"en":"Do not overwork yourself before the exam.","zh":"考试前不要过度劳累。"},{"en":"The shortage forced managers to overwork their staff.","zh":"人员短缺迫使管理者让员工超负荷工作。"}]},{"pos":"v.","meaning":"过度使用;滥用","definition":"to use or develop something excessively","examples":[{"en":"Overworking the dough can make bread tough.","zh":"面团揉得过度可能使面包变硬。"},{"en":"The writer overworked the same metaphor.","zh":"作者反复滥用同一个隐喻。"}]},{"pos":"n.","meaning":"过度劳累;过重工作","definition":"work beyond a reasonable amount","examples":[{"en":"She needed rest after months of overwork.","zh":"几个月过度劳累后她需要休息。"},{"en":"Overwork reduced the team's efficiency.","zh":"过重工作降低了团队效率。"}]}],"owe":[{"pos":"v.","meaning":"欠；应偿还","definition":"to have a debt or duty to someone","examples":[{"en":"I owe you ten pounds.","zh":"我欠你十英镑。"},{"en":"We owe the volunteers an apology.","zh":"我们应该向志愿者道歉。"}]},{"pos":"v.","meaning":"把……归功于","definition":"to have something because of someone's help or a cause","examples":[{"en":"She owes her success to persistence.","zh":"她把成功归功于坚持。"},{"en":"The town owes its growth to the railway.","zh":"小镇的发展得益于铁路。"}]}],"owl":[{"pos":"n.","meaning":"猫头鹰","definition":"A bird of prey with large eyes that often hunts at night.","examples":[{"en":"An owl called from the old barn.","zh":"一只猫头鹰从旧谷仓里发出叫声。"},{"en":"We saw an owl resting in a hollow tree.","zh":"我们看见一只猫头鹰在空心树里休息。"}]}],"oxide":[{"pos":"n.","meaning":"氧化物","definition":"a compound of oxygen with another element","examples":[{"en":"Iron oxide gives the rock its red colour.","zh":"氧化铁使岩石呈红色。"},{"en":"The metal formed a protective oxide layer.","zh":"金属形成了一层保护性氧化层。"}]}],"oxygen":[{"pos":"n.","meaning":"氧；氧气","definition":"a chemical element essential for most forms of respiration","examples":[{"en":"Fish obtain oxygen from water.","zh":"鱼从水中获取氧气。"},{"en":"The equipment measures oxygen levels.","zh":"设备测量氧含量。"}]}],"ozone":[{"pos":"n.","meaning":"臭氧","definition":"A form of oxygen containing three atoms per molecule.","examples":[{"en":"The ozone layer absorbs much of the Sun's ultraviolet radiation.","zh":"臭氧层吸收了大量太阳紫外线。"},{"en":"The station monitors ozone levels near the ground.","zh":"监测站监测近地面的臭氧水平。"}]}],"ozone layer":[{"pos":"n. phr.","meaning":"臭氧层","definition":"the atmospheric region rich in ozone that absorbs ultraviolet radiation","examples":[{"en":"The ozone layer absorbs much harmful ultraviolet radiation.","zh":"臭氧层吸收大量有害紫外线。"},{"en":"Scientists monitor changes in the ozone layer.","zh":"科学家监测臭氧层变化。"}]}],"pack":[{"pos":"v.","meaning":"打包；收拾行李；包装","definition":"to put things into containers for storage or travel","examples":[{"en":"She packed her suitcase before breakfast.","zh":"她早饭前整理了行李箱。"},{"en":"The workers packed the glasses carefully.","zh":"工人仔细包装了玻璃杯。"}]},{"pos":"v.","meaning":"塞满；挤满","definition":"to fill a space tightly","examples":[{"en":"Fans packed the hall.","zh":"歌迷挤满了大厅。"},{"en":"The drawer was packed with receipts.","zh":"抽屉里塞满了收据。"}]},{"pos":"n.","meaning":"包；一包物品","definition":"a container or group of things wrapped together","examples":[{"en":"He carried a pack on his back.","zh":"他背着一个包。"},{"en":"She bought a pack of envelopes.","zh":"她买了一包信封。"}]}],"pad":[{"pos":"n.","meaning":"软垫；衬垫","definition":"A piece of soft material used for comfort or protection.","examples":[{"en":"She placed a pad beneath her knees.","zh":"她在膝盖下面放了一块软垫。"},{"en":"The helmet has protective pads inside.","zh":"头盔内部有保护衬垫。"}]},{"pos":"n.","meaning":"便笺本；纸簿","definition":"A set of sheets of paper joined at one edge.","examples":[{"en":"He wrote the number on a pad beside the telephone.","zh":"他把号码写在电话旁的便笺本上。"},{"en":"She tore a sheet from her drawing pad.","zh":"她从绘画本上撕下一页纸。"}]},{"pos":"v.","meaning":"加衬垫；用软物填塞","definition":"To fill or cover with soft protective material.","examples":[{"en":"They padded the box with folded towels.","zh":"他们用折叠毛巾给箱子加了衬垫。"},{"en":"The chair was padded for extra comfort.","zh":"椅子加了软垫以增加舒适度。"}]},{"pos":"v.","meaning":"轻步走；蹑手蹑脚地走","definition":"To walk quietly with soft steps.","examples":[{"en":"The cat padded across the kitchen floor.","zh":"猫轻轻走过厨房地板。"},{"en":"She padded downstairs in her socks.","zh":"她穿着袜子轻手轻脚地下楼。"}]}],"painstaking":[{"pos":"adj.","meaning":"细致的;煞费苦心的;勤勉的","definition":"done with great care and effort","examples":[{"en":"The restoration required painstaking work.","zh":"修复需要细致费力的工作。"},{"en":"She made a painstaking comparison of the records.","zh":"她细致地比较了记录。"}]},{"pos":"n.","meaning":"辛勤努力;细致用功（较少用）","definition":"careful and diligent effort","examples":[{"en":"The finished model rewarded months of painstaking.","zh":"完成的模型回报了数月的辛勤努力。"},{"en":"Such accuracy demands patience and painstaking.","zh":"这种精确度需要耐心和细致用功。"}]}],"pamper":[{"pos":"v.","meaning":"娇惯；精心照顾","definition":"to treat someone with excessive or special care","examples":[{"en":"The grandparents pampered the children.","zh":"祖父母娇惯孩子们。"},{"en":"The hotel pampers guests with attentive service.","zh":"酒店以周到服务悉心照顾客人。"}]}],"pamphlet":[{"pos":"n.","meaning":"小册子；宣传册","definition":"A short printed booklet on a particular subject.","examples":[{"en":"The museum gives visitors a pamphlet about the exhibition.","zh":"博物馆向游客发放介绍展览的小册子。"},{"en":"He distributed pamphlets explaining the campaign.","zh":"他分发了介绍这场活动的宣传册。"}]}],"panic":[{"pos":"n.","meaning":"恐慌;惊慌","definition":"sudden overwhelming fear","examples":[{"en":"The false alarm caused widespread panic.","zh":"误报引起普遍恐慌。"},{"en":"She searched for her passport in a panic.","zh":"她惊慌地寻找护照。"}]},{"pos":"v.","meaning":"恐慌;使惊慌","definition":"to become or make suddenly frightened","examples":[{"en":"Do not panic if the lights fail.","zh":"停电时不要惊慌。"},{"en":"The loud crash panicked the horses.","zh":"巨响惊到了马群。"}]},{"pos":"adj.","meaning":"恐慌的;由恐慌引起的","definition":"involving sudden uncontrolled fear","examples":[{"en":"Panic buying emptied the shelves.","zh":"恐慌性抢购使货架空了。"},{"en":"The rumour triggered panic selling.","zh":"谣言引发了恐慌性抛售。"}]}],"parallel":[{"pos":"n.","meaning":"相似之处；类似事物","definition":"a similarity or comparable case","examples":[{"en":"The historian drew parallels between the events.","zh":"历史学家指出了事件之间的相似之处。"},{"en":"This success has no parallel in the club's history.","zh":"这种成功在俱乐部历史上无可比拟。"}]},{"pos":"n.","meaning":"纬线","definition":"an imaginary circle of latitude","examples":[{"en":"The border follows the forty-ninth parallel.","zh":"边界沿北纬四十九度线延伸。"},{"en":"The map marks each parallel clearly.","zh":"地图清楚标出了每条纬线。"}]},{"pos":"adj.","meaning":"平行的","definition":"remaining the same distance apart","examples":[{"en":"Draw two parallel lines.","zh":"画两条平行线。"},{"en":"The road runs parallel to the river.","zh":"公路与河流平行。"}]},{"pos":"adj.","meaning":"相似的；对应的；并行的","definition":"similar or happening alongside something else","examples":[{"en":"The teams conducted parallel studies.","zh":"两个团队进行了并行研究。"},{"en":"Their careers followed parallel paths.","zh":"他们的职业生涯走了相似的道路。"}]},{"pos":"v.","meaning":"与……相似；比得上","definition":"to resemble or equal something","examples":[{"en":"The findings parallel those of an earlier study.","zh":"发现与早先研究相似。"},{"en":"Few performances can parallel her achievement.","zh":"少有表演能与她的成就媲美。"}]}],"paralysis":[{"pos":"n.","meaning":"瘫痪；麻痹","definition":"Loss of the ability to move part or all of the body.","examples":[{"en":"The injury caused paralysis in one leg.","zh":"伤势导致一条腿瘫痪。"},{"en":"The researchers studied the causes of temporary paralysis.","zh":"研究人员研究了暂时性麻痹的原因。"}]},{"pos":"n.","meaning":"停顿；瘫痪状态；无力行动","definition":"An inability to act or make decisions.","examples":[{"en":"Political disagreements led to months of paralysis.","zh":"政治分歧导致数月无法采取行动。"},{"en":"Too many competing plans produced decision paralysis.","zh":"相互竞争的方案太多，导致决策停滞。"}]}],"paramount":[{"pos":"adj.","meaning":"最重要的;至高的","definition":"more important than anything else","examples":[{"en":"Patient safety is paramount.","zh":"患者安全至关重要。"},{"en":"Accuracy is of paramount importance in this work.","zh":"准确性对这项工作最为重要。"}]},{"pos":"n.","meaning":"最高统治者（罕见用法）","definition":"a supreme ruler","examples":[{"en":"The regional chiefs acknowledged one paramount.","zh":"各地区首领承认一位最高统治者。"},{"en":"The paramount summoned his subordinate rulers.","zh":"最高统治者召见了下属统治者。"}]}],"parcel":[{"pos":"n.","meaning":"包裹","definition":"an object wrapped for sending or carrying","examples":[{"en":"A parcel arrived this morning.","zh":"今天早晨来了一个包裹。"},{"en":"She wrapped the parcel in brown paper.","zh":"她用牛皮纸包好了包裹。"}]}],"pardon":[{"pos":"interj.","meaning":"请再说一遍；什么","definition":"Used politely when asking someone to repeat something.","examples":[{"en":"Pardon? I could not hear you over the music.","zh":"请再说一遍？音乐太响，我没听清。"},{"en":"Pardon, did you say fifteen or fifty?","zh":"抱歉，你说的是十五还是五十？"}]},{"pos":"n.","meaning":"原谅；宽恕；赦免","definition":"Forgiveness or an official cancellation of a punishment.","examples":[{"en":"He asked her pardon for the interruption.","zh":"他因打断她而请求原谅。"},{"en":"The prisoner received a royal pardon.","zh":"囚犯获得了王室赦免。"}]},{"pos":"v.","meaning":"原谅；宽恕；赦免","definition":"To forgive someone or release them from a legal penalty.","examples":[{"en":"Please pardon my late arrival.","zh":"请原谅我来晚了。"},{"en":"The governor pardoned the wrongly convicted man.","zh":"州长赦免了那个被错误定罪的人。"}]}],"parental":[{"pos":"adj.","meaning":"父母的;像父母的","definition":"relating to parents","examples":[{"en":"The school requires parental consent.","zh":"学校要求家长同意。"},{"en":"The bird provides extensive parental care.","zh":"这种鸟给予幼鸟充分照料。"}]}],"parliament":[{"pos":"n.","meaning":"议会；国会","definition":"a national lawmaking assembly","examples":[{"en":"Parliament debated the proposal.","zh":"议会辩论了提案。"},{"en":"The bill was introduced in parliament.","zh":"法案被提交议会。"}]}],"partial":[{"pos":"adj.","meaning":"部分的；不完全的","definition":"Not complete or affecting only part of something.","examples":[{"en":"The report provides only a partial explanation.","zh":"报告只提供了部分解释。"},{"en":"The building suffered a partial collapse.","zh":"建筑物部分坍塌。"}]},{"pos":"adj.","meaning":"偏爱的；特别喜欢的","definition":"Having a liking for something.","examples":[{"en":"She is partial to dark chocolate.","zh":"她特别喜欢黑巧克力。"},{"en":"He has always been partial to quiet coastal towns.","zh":"他一直偏爱安静的沿海小镇。"}]},{"pos":"adj.","meaning":"偏袒的；不公正的","definition":"Unfairly favouring one side.","examples":[{"en":"The judge must not appear partial.","zh":"法官不能显得偏袒任何一方。"},{"en":"The review was criticised as partial and unreliable.","zh":"这篇评论被批评为偏颇且不可靠。"}]}],"participant":[{"pos":"n.","meaning":"参与者;参加者","definition":"a person taking part in an activity","examples":[{"en":"Each participant received a questionnaire.","zh":"每位参与者都收到了一份问卷。"},{"en":"The workshop attracted fifty participants.","zh":"工作坊吸引了五十名参加者。"}]}],"participate":[{"pos":"v.","meaning":"参与；参加","definition":"to take part in an activity","examples":[{"en":"Everyone can participate in the discussion.","zh":"每个人都可以参与讨论。"},{"en":"Ten schools participated in the project.","zh":"十所学校参加了项目。"}]}],"participation":[{"pos":"n.","meaning":"参与","definition":"the act of taking part","examples":[{"en":"Public participation can improve local decisions.","zh":"公众参与可以改善地方决策。"},{"en":"The scheme encourages participation in sport.","zh":"该计划鼓励参与体育运动。"},{"en":"Active participation is more useful than simply attending.","zh":"积极参与比仅仅到场更有帮助。"}]},{"pos":"n.","meaning":"分享；分担；共同享有","definition":"The sharing of benefits, profits, or responsibilities.","examples":[{"en":"The contract provides for employee participation in profits.","zh":"合同规定员工分享利润。"},{"en":"Participation in the pension scheme is open to all staff.","zh":"所有员工都可参加并享有这项养老金计划。"}]}],"particle":[{"pos":"n.","meaning":"微粒;极少量","definition":"a very small piece or quantity","examples":[{"en":"Dust particles floated in the sunlight.","zh":"尘埃微粒在阳光中飘浮。"},{"en":"There was not a particle of truth in the rumour.","zh":"谣言没有丝毫真实性。"}]}],"particular":[{"pos":"adj.","meaning":"特定的；个别的","definition":"one specific thing rather than others","examples":[{"en":"Do you have a particular date in mind?","zh":"你有特定日期吗？"},{"en":"The method suits this particular problem.","zh":"方法适合这个特定问题。"}]},{"pos":"adj.","meaning":"特别的；突出的","definition":"greater than usual in a specific respect","examples":[{"en":"She took particular care with the details.","zh":"她特别注意细节。"},{"en":"The final chapter is of particular interest.","zh":"最后一章特别有趣。"}]},{"pos":"adj.","meaning":"详细的；具体的","definition":"giving attention to individual details","examples":[{"en":"The witness gave a particular account of the journey.","zh":"证人详细叙述了行程。"},{"en":"The instructions were particular about each stage.","zh":"说明对每个阶段都有详细交代。"}]},{"pos":"n.","meaning":"详情；细节（常用复数）","definition":"an individual detail of information","examples":[{"en":"Please send the particulars of the property.","zh":"请寄送房产详情。"},{"en":"She checked every particular of the agreement.","zh":"她核查了协议的每项细节。"}]}],"particularly":[{"pos":"adv.","meaning":"尤其；特别地","definition":"To a greater degree than usual or than other things.","examples":[{"en":"I particularly enjoyed the final lecture.","zh":"我尤其喜欢最后一场讲座。"},{"en":"The path is particularly dangerous after dark.","zh":"这条小路天黑后尤其危险。"}]}],"particulate":[{"pos":"adj.","meaning":"微粒的;颗粒状的","definition":"consisting of tiny particles","examples":[{"en":"The filter removes particulate matter.","zh":"滤器除去颗粒物。"},{"en":"Particulate pollution reduced visibility.","zh":"颗粒物污染降低了能见度。"}]},{"pos":"n.","meaning":"颗粒物;微粒","definition":"a tiny solid or liquid particle","examples":[{"en":"The monitor detects airborne particulates.","zh":"监测仪检测空气中的颗粒物。"},{"en":"Industrial emissions contain fine particulates.","zh":"工业排放含有细颗粒物。"}]}],"passionate":[{"pos":"adj.","meaning":"热情的；充满激情的","definition":"showing strong feeling or enthusiasm","examples":[{"en":"He is passionate about wildlife conservation.","zh":"他热心于野生动物保护。"},{"en":"She made a passionate appeal for support.","zh":"她热情呼吁大家支持。"}]}],"passport":[{"pos":"n.","meaning":"护照","definition":"An official document identifying a traveller's nationality.","examples":[{"en":"Keep your passport in a safe place.","zh":"把护照放在安全的地方。"},{"en":"Her passport expires next spring.","zh":"她的护照明年春天到期。"}]},{"pos":"n.","meaning":"通行证；成功途径；手段","definition":"Something that enables access to an opportunity or advantage.","examples":[{"en":"A degree is not an automatic passport to success.","zh":"学位并不是通向成功的自动通行证。"},{"en":"Language skills can be a passport to international work.","zh":"语言能力可以成为从事国际工作的敲门砖。"}]}],"pasture":[{"pos":"n.","meaning":"牧场;牧草地","definition":"grassland used for grazing animals","examples":[{"en":"Cattle grazed in the pasture.","zh":"牛在牧场吃草。"},{"en":"Rain turned the dry pasture green.","zh":"雨使干牧场变绿了。"}]},{"pos":"v.","meaning":"放牧","definition":"to let animals graze","examples":[{"en":"The farmer pastured sheep on the hillside.","zh":"农民在山坡上放羊。"},{"en":"They pasture cattle near the river.","zh":"他们在河边放牛。"}]}],"patent":[{"pos":"v.","meaning":"取得专利；授予专利","definition":"to obtain legal protection for an invention","examples":[{"en":"She patented the new mechanism.","zh":"她为新机构申请取得了专利。"},{"en":"The company patented its manufacturing process.","zh":"公司为制造工艺取得了专利。"}]},{"pos":"n.","meaning":"专利；专利权","definition":"a legal right protecting an invention","examples":[{"en":"The inventor applied for a patent.","zh":"发明者申请了专利。"},{"en":"The patent covers a new type of filter.","zh":"专利涵盖了一种新型过滤器。"}]},{"pos":"adj.","meaning":"有专利的；受专利保护的","definition":"protected by an exclusive invention right","examples":[{"en":"The device uses a patent locking system.","zh":"装置使用专利锁定系统。"},{"en":"They advertised a patent cleaning process.","zh":"他们宣传一种专利清洁工艺。"}]},{"pos":"adj.","meaning":"显而易见的","definition":"clear and obvious","examples":[{"en":"The statement contained a patent contradiction.","zh":"声明中有一个明显的矛盾。"},{"en":"Her disappointment was patent to everyone.","zh":"她的失望人人都看得出来。"}]}],"pathology":[{"pos":"n.","meaning":"病理学","definition":"The study of disease and its effects on the body.","examples":[{"en":"She specialises in pathology.","zh":"她专攻病理学。"},{"en":"The pathology laboratory examined the tissue sample.","zh":"病理实验室检查了组织样本。"}]},{"pos":"n.","meaning":"病变；病理特征","definition":"The disease-related changes present in a tissue or organism.","examples":[{"en":"The scan revealed no obvious pathology.","zh":"扫描未显示明显病变。"},{"en":"The team compared the pathology of the two conditions.","zh":"团队比较了两种疾病的病理特征。"}]}],"pathway":[{"pos":"n.","meaning":"小径;途径;通路","definition":"a path or a route toward a result","examples":[{"en":"A narrow pathway crosses the garden.","zh":"一条小径穿过花园。"},{"en":"The programme offers a pathway into employment.","zh":"项目提供了就业途径。"}]}],"patriotic":[{"pos":"adj.","meaning":"爱国的；表现爱国精神的","definition":"showing love and loyalty to one's country","examples":[{"en":"The festival included patriotic songs.","zh":"节庆包括爱国歌曲。"},{"en":"She described her service as a patriotic duty.","zh":"她把自己的服务称为爱国义务。"}]}],"patronage":[{"pos":"n.","meaning":"赞助；扶持；支持","definition":"Financial or influential support for a person or activity.","examples":[{"en":"The gallery flourished under private patronage.","zh":"画廊在私人赞助下繁荣发展。"},{"en":"Royal patronage helped the composer continue his work.","zh":"王室的资助帮助作曲家继续创作。"}]},{"pos":"n.","meaning":"光顾；惠顾","definition":"The custom given to a shop or business.","examples":[{"en":"The café thanked residents for their continued patronage.","zh":"咖啡馆感谢居民持续光顾。"},{"en":"The theatre depends on regular local patronage.","zh":"剧院依靠当地观众经常惠顾。"}]},{"pos":"n.","meaning":"任命权；恩赐职位的权力","definition":"The power to appoint supporters to jobs or grant them advantages.","examples":[{"en":"The reform aimed to reduce political patronage in public appointments.","zh":"改革旨在减少公共任命中的政治任人唯亲。"},{"en":"The ruler used patronage to reward loyal supporters.","zh":"统治者运用任命权奖赏忠诚支持者。"}]}],"pattern":[{"pos":"n.","meaning":"图案;样式","definition":"a repeated decorative design","examples":[{"en":"The fabric has a floral pattern.","zh":"布料有花卉图案。"},{"en":"Tiles form a geometric pattern.","zh":"瓷砖构成几何图案。"}]},{"pos":"n.","meaning":"模式;规律","definition":"a repeated way in which things happen","examples":[{"en":"The data reveal a seasonal pattern.","zh":"数据显示季节性规律。"},{"en":"Her sleep pattern changed after the move.","zh":"搬家后她的睡眠模式改变了。"}]},{"pos":"v.","meaning":"使形成图案","definition":"to decorate with a repeated design","examples":[{"en":"Dark stripes patterned the animal's coat.","zh":"动物皮毛上布满深色条纹。"},{"en":"The artist patterned the bowl with blue lines.","zh":"艺术家用蓝线给碗绘制图案。"}]},{"pos":"v.","meaning":"仿照;使按某模式形成","definition":"to shape according to a model","examples":[{"en":"The school patterned its programme on a successful trial.","zh":"学校仿照成功试点制定项目。"},{"en":"Her teaching was patterned after her mentor's approach.","zh":"她的教学仿照了导师的方法。"}]}],"pavement":[{"pos":"n.","meaning":"人行道（英式）","definition":"a path for pedestrians beside a road","examples":[{"en":"Walk on the pavement.","zh":"走在人行道上。"},{"en":"The cafe placed tables on the pavement.","zh":"咖啡馆在人行道上摆了桌子。"}]},{"pos":"n.","meaning":"铺筑路面；硬质地面","definition":"the hard surface of a road or area","examples":[{"en":"The hot pavement reflected the sun.","zh":"炎热的路面反射着阳光。"},{"en":"Workers repaired cracks in the pavement.","zh":"工人修补了路面的裂缝。"}]}],"payable":[{"pos":"adj.","meaning":"应支付的；可支付给的","definition":"Due to be paid or addressed to a named recipient.","examples":[{"en":"The balance is payable within thirty days.","zh":"余款应在三十天内支付。"},{"en":"Make the cheque payable to the school.","zh":"请将支票收款人填写为学校。"}]}],"payment":[{"pos":"n.","meaning":"支付;付款;款项","definition":"the act of paying or money paid","examples":[{"en":"Payment is due before delivery.","zh":"交货前需付款。"},{"en":"The first payment covered half the cost.","zh":"首笔款项支付了一半费用。"}]}],"pearl":[{"pos":"n.","meaning":"珍珠","definition":"a smooth rounded object formed inside certain shellfish","examples":[{"en":"A single pearl hung from the necklace.","zh":"项链上悬着一颗珍珠。"},{"en":"The museum displays a collection of pearls.","zh":"博物馆展出了一批珍珠。"}]}],"pedal":[{"pos":"n.","meaning":"踏板","definition":"A part operated by the foot to control a machine.","examples":[{"en":"Press the brake pedal gently.","zh":"轻踩刹车踏板。"},{"en":"The bicycle's left pedal was loose.","zh":"自行车的左踏板松了。"}]},{"pos":"v.","meaning":"踩踏板；骑自行车","definition":"To operate pedals, especially to move a bicycle.","examples":[{"en":"She pedalled slowly up the hill.","zh":"她踩着踏板缓缓骑上山坡。"},{"en":"We pedalled along the river for an hour.","zh":"我们沿河骑了一个小时自行车。"}]}],"pedestrian":[{"pos":"n.","meaning":"行人","definition":"a person walking rather than travelling in a vehicle","examples":[{"en":"A pedestrian was waiting to cross the road.","zh":"一位行人在等候过马路。"},{"en":"The driver stopped to let the pedestrian pass.","zh":"司机停车让行人通过。"},{"en":"Every pedestrian should be able to cross safely.","zh":"每位行人都应能安全过街。"}]},{"pos":"adj.","meaning":"行人的;步行的","definition":"relating to people travelling on foot","examples":[{"en":"A pedestrian bridge crosses the road.","zh":"一座人行桥跨过道路。"},{"en":"The centre now has a pedestrian zone.","zh":"中心区现在设有步行区。"}]},{"pos":"adj.","meaning":"平淡乏味的;缺乏想象力的","definition":"dull and lacking imagination","examples":[{"en":"The film's pedestrian dialogue disappointed critics.","zh":"电影平淡的对白令评论者失望。"},{"en":"Her first draft was accurate but pedestrian.","zh":"她的初稿准确却缺乏想象力。"}]}],"pedigree":[{"pos":"n.","meaning":"家谱；血统；渊源","definition":"the ancestry or recorded origins of a person or animal","examples":[{"en":"The breeder documented the dog's pedigree.","zh":"繁育者记录了狗的血统。"},{"en":"The family traced its pedigree through old records.","zh":"家族通过旧档案追溯家谱。"}]}],"penalize":[{"pos":"v.","meaning":"惩罚；处罚；判罚","definition":"To impose a penalty for breaking a rule.","examples":[{"en":"Drivers are penalized for parking here.","zh":"在这里停车的司机会受到处罚。"},{"en":"The referee penalized the player for holding an opponent.","zh":"裁判因球员拉住对手而作出判罚。"}]},{"pos":"v.","meaning":"使处于不利地位","definition":"To place someone at an unfair disadvantage.","examples":[{"en":"The pricing system penalizes customers who use very little water.","zh":"这个定价体系使少量用水的顾客处于不利地位。"},{"en":"Inflexible schedules can penalize workers with caring responsibilities.","zh":"僵硬的时间安排可能使承担照护责任的员工吃亏。"}]}],"penalty":[{"pos":"n.","meaning":"惩罚;罚金;处罚","definition":"a punishment for breaking a rule","examples":[{"en":"Late payment incurs a penalty.","zh":"逾期付款会产生罚金。"},{"en":"The referee awarded a penalty.","zh":"裁判判罚了点球。"}]}],"penetration":[{"pos":"n.","meaning":"穿透；进入；渗入","definition":"the act of entering or passing through something","examples":[{"en":"The coating reduces water penetration.","zh":"涂层减少水的渗入。"},{"en":"The study measured light penetration into the lake.","zh":"研究测量光线进入湖水的深度。"}]},{"pos":"n.","meaning":"洞察力；透彻理解","definition":"the ability to understand something deeply","examples":[{"en":"Her analysis showed remarkable penetration.","zh":"她的分析展现了非凡洞察力。"},{"en":"The critic wrote with unusual intellectual penetration.","zh":"评论家写作时表现出非同寻常的思想洞察力。"}]}],"pension":[{"pos":"n.","meaning":"养老金；退休金；抚恤金；年金","definition":"A regular payment received after retirement or because of disability or loss.","examples":[{"en":"She receives a small pension each month.","zh":"她每月领取一笔数额不大的养老金。"},{"en":"The family depended on a survivor's pension.","zh":"这家人依靠遗属抚恤金生活。"}]}],"pepper":[{"pos":"n.","meaning":"胡椒;胡椒粉","definition":"a pungent spice made from dried berries","examples":[{"en":"Add a little black pepper.","zh":"加少许黑胡椒。"},{"en":"She ground pepper over the soup.","zh":"她往汤里磨了些胡椒粉。"}]},{"pos":"v.","meaning":"撒胡椒粉","definition":"to season with pepper","examples":[{"en":"Pepper the vegetables before roasting.","zh":"烤蔬菜前撒上胡椒粉。"},{"en":"She lightly peppered the eggs.","zh":"她在鸡蛋上撒了少许胡椒粉。"}]},{"pos":"v.","meaning":"密集散布;接连提出","definition":"to scatter densely or direct many things at someone","examples":[{"en":"Tiny flowers peppered the meadow.","zh":"小花密密点缀着草地。"},{"en":"The students peppered the speaker with questions.","zh":"学生接连不断地向演讲者提问。"}]}],"perceive":[{"pos":"v.","meaning":"察觉；感知","definition":"to notice through the senses","examples":[{"en":"She perceived a faint smell of smoke.","zh":"她闻到一丝烟味。"},{"en":"The camera perceives light differently from the eye.","zh":"相机感知光线的方式与人眼不同。"}]},{"pos":"v.","meaning":"理解；认为；认识到","definition":"to understand or interpret something in a particular way","examples":[{"en":"They perceived the change as a threat.","zh":"他们把变化视为威胁。"},{"en":"He failed to perceive the importance of the evidence.","zh":"他没有认识到证据的重要性。"}]}],"percentage":[{"pos":"n.","meaning":"百分比；百分率","definition":"A proportion expressed as parts out of one hundred.","examples":[{"en":"What percentage of the class passed the test?","zh":"班里通过考试的比例是多少？"},{"en":"The chart shows the percentage of energy from renewable sources.","zh":"图表显示来自可再生能源的能量百分比。"}]}],"perception":[{"pos":"n.","meaning":"看法;认识","definition":"a way of understanding something","examples":[{"en":"The campaign changed public perception of the issue.","zh":"宣传改变了公众对问题的看法。"},{"en":"Our perceptions of risk differed.","zh":"我们对风险的认识不同。"}]},{"pos":"n.","meaning":"感知;知觉;洞察力","definition":"the ability to notice or understand through senses or insight","examples":[{"en":"The experiment tests depth perception.","zh":"实验测试深度知觉。"},{"en":"Her sharp perception revealed the hidden conflict.","zh":"她敏锐的洞察力揭示了隐藏冲突。"}]}],"perform":[{"pos":"v.","meaning":"执行；履行；完成","definition":"to carry out a task or action","examples":[{"en":"The engineer performed a safety check.","zh":"工程师进行了安全检查。"},{"en":"She performed her duties carefully.","zh":"她认真履行职责。"}]},{"pos":"v.","meaning":"表演；演出","definition":"to entertain an audience through music or drama","examples":[{"en":"The orchestra performed a new symphony.","zh":"乐团演奏了一部新交响曲。"},{"en":"The actors performed outdoors.","zh":"演员们在户外演出。"}]},{"pos":"v.","meaning":"运作；表现","definition":"to function or achieve results","examples":[{"en":"The engine performed well in cold weather.","zh":"发动机在寒冷天气中运作良好。"},{"en":"The team performed better than expected.","zh":"团队表现比预期好。"}]}],"performance":[{"pos":"n.","meaning":"演出；表演","definition":"An act of presenting music, drama, or entertainment.","examples":[{"en":"The evening performance begins at seven.","zh":"晚场演出七点开始。"},{"en":"Her performance received a standing ovation.","zh":"她的表演获得了全场起立鼓掌。"}]},{"pos":"n.","meaning":"履行；执行；表现","definition":"The carrying out of a task and how well it is done.","examples":[{"en":"The review assessed his performance as a team leader.","zh":"评估考察了他担任团队负责人时的表现。"},{"en":"Payment depends on satisfactory performance of the contract.","zh":"付款取决于合同得到令人满意的履行。"}]},{"pos":"n.","meaning":"性能；工作效率","definition":"How effectively a machine or system operates.","examples":[{"en":"The upgrade improved the computer's performance.","zh":"升级改善了电脑性能。"},{"en":"We tested the engine's performance in cold weather.","zh":"我们测试了发动机在寒冷天气下的性能。"}]}],"perimeter":[{"pos":"n.","meaning":"周边;周界","definition":"the boundary of an area","examples":[{"en":"Guards patrolled the airport perimeter.","zh":"守卫巡逻机场周界。"},{"en":"A fence runs around the garden's perimeter.","zh":"一道篱笆围着花园周边。"}]},{"pos":"n.","meaning":"周长","definition":"the total length around a shape","examples":[{"en":"Calculate the perimeter of the rectangle.","zh":"计算长方形的周长。"},{"en":"The square has a perimeter of twenty metres.","zh":"这个正方形周长二十米。"}]}],"periodical":[{"pos":"n.","meaning":"期刊；杂志","definition":"a publication issued regularly","examples":[{"en":"The library subscribes to several periodicals.","zh":"图书馆订阅了几种期刊。"},{"en":"Her article appeared in a scientific periodical.","zh":"她的文章刊登在一份科学期刊中。"}]},{"pos":"adj.","meaning":"定期的；周期性的","definition":"occurring at regular intervals","examples":[{"en":"The equipment requires periodical inspection.","zh":"设备需要定期检查。"},{"en":"The river undergoes periodical flooding.","zh":"河流周期性泛滥。"}]}],"peripheral":[{"pos":"adj.","meaning":"外围的；边缘的","definition":"Located at or near the outer edge.","examples":[{"en":"Trees were planted along the peripheral boundary.","zh":"外围边界沿线种了树。"},{"en":"Movement was detected in her peripheral vision.","zh":"她的周边视野察觉到了动静。"}]},{"pos":"adj.","meaning":"次要的；附带的","definition":"Not central or most important.","examples":[{"en":"The debate became distracted by peripheral issues.","zh":"辩论被次要问题分散了注意力。"},{"en":"His role in the project was peripheral.","zh":"他在项目中的角色是次要的。"}]},{"pos":"n.","meaning":"外围设备；外设","definition":"A device connected to a computer to provide additional functions.","examples":[{"en":"A printer is a common computer peripheral.","zh":"打印机是一种常见的电脑外设。"},{"en":"Disconnect unnecessary peripherals before moving the computer.","zh":"移动电脑前，请断开不必要的外设。"}]}],"periphery":[{"pos":"n.","meaning":"外围;边缘;次要部分","definition":"the outer or less central area","examples":[{"en":"Factories moved to the city's periphery.","zh":"工厂迁到城市外围。"},{"en":"The issue remained on the periphery of debate.","zh":"这个问题仍处于讨论的边缘。"}]}],"permanent":[{"pos":"adj.","meaning":"永久的；持久的","definition":"lasting indefinitely rather than temporarily","examples":[{"en":"The museum needs a permanent home.","zh":"博物馆需要一个永久馆址。"},{"en":"The change had a permanent effect.","zh":"变化产生了持久影响。"}]}],"permeate":[{"pos":"v.","meaning":"渗透；渗入；弥漫","definition":"To spread through or pass into every part of something.","examples":[{"en":"The smell of bread permeated the kitchen.","zh":"面包的香气弥漫整个厨房。"},{"en":"Water slowly permeated the porous stone.","zh":"水慢慢渗入多孔石材。"}]}],"permission":[{"pos":"n.","meaning":"许可","definition":"approval to do something","examples":[{"en":"You need permission to park here.","zh":"在这里停车需要许可。"},{"en":"The school asked for parents' permission before the trip.","zh":"学校在出游前征求了家长许可。"},{"en":"Do not share personal information without permission.","zh":"未经许可不要分享个人信息。"}]}],"perpetrate":[{"pos":"v.","meaning":"犯下；实施恶行","definition":"to carry out a harmful or illegal act","examples":[{"en":"The investigators identified who perpetrated the fraud.","zh":"调查人员查明了谁实施了欺诈。"},{"en":"The account records abuses perpetrated during the conflict.","zh":"记载记录了冲突期间犯下的暴行。"}]}],"perpetual":[{"pos":"adj.","meaning":"持续不断的；长久的；永久的","definition":"Continuing all the time or seeming never to end.","examples":[{"en":"The mountain peaks are covered in perpetual snow.","zh":"山峰终年积雪。"},{"en":"The office seemed to be in perpetual confusion.","zh":"办公室似乎始终处于混乱之中。"}]}],"perpetuate":[{"pos":"v.","meaning":"使持续;使长存","definition":"to cause something to continue","examples":[{"en":"The policy perpetuates inequality.","zh":"这项政策使不平等延续。"},{"en":"Annual ceremonies perpetuate the founder's memory.","zh":"年度仪式使人们长久纪念创始人。"}]}],"perplex":[{"pos":"v.","meaning":"使困惑","definition":"to puzzle someone greatly","examples":[{"en":"The unexpected result perplexed the researchers.","zh":"意外结果让研究人员困惑。"},{"en":"Her silence perplexed him.","zh":"她的沉默令他不解。"}]},{"pos":"v.","meaning":"使复杂难解（正式）","definition":"to make something confusingly complicated","examples":[{"en":"Contradictory definitions perplexed the issue further.","zh":"相互矛盾的定义使问题更复杂难解。"},{"en":"Unnecessary exceptions only perplex the argument.","zh":"不必要的例外只会让论证变复杂。"}]}],"perquisite":[{"pos":"n.","meaning":"额外待遇；附带福利；特权","definition":"An extra benefit received because of a job or position.","examples":[{"en":"A company car is one of the perquisites of the job.","zh":"公司配车是这份工作的附带福利之一。"},{"en":"The position came with several valuable perquisites.","zh":"这个职位附带几项很有价值的福利。"}]}],"persist":[{"pos":"v.","meaning":"坚持;持续存在","definition":"to continue despite difficulty or over time","examples":[{"en":"She persisted with the difficult experiment.","zh":"她坚持进行困难的实验。"},{"en":"The smell persisted for several days.","zh":"气味持续了好几天。"}]}],"personal":[{"pos":"adj.","meaning":"个人的；私人的","definition":"belonging to an individual or private life","examples":[{"en":"Keep personal belongings with you.","zh":"请随身保管个人物品。"},{"en":"She declined to discuss personal matters.","zh":"她拒绝讨论私事。"}]},{"pos":"adj.","meaning":"亲自的；本人的","definition":"done directly by the person concerned","examples":[{"en":"The director made a personal visit.","zh":"主管亲自来访。"},{"en":"I received a personal invitation from the author.","zh":"我收到了作者本人的邀请。"}]},{"pos":"adj.","meaning":"人身的；身体的","definition":"relating to a person's body or safety","examples":[{"en":"The rules protect personal safety.","zh":"规则保护人身安全。"},{"en":"The policy covers personal injury.","zh":"保单承保人身伤害。"}]}],"personality":[{"pos":"n.","meaning":"个性；性格；人格","definition":"The combination of qualities that makes a person distinctive.","examples":[{"en":"Her cheerful personality put everyone at ease.","zh":"她开朗的个性让大家放松下来。"},{"en":"The twins have very different personalities.","zh":"这对双胞胎性格很不相同。"}]},{"pos":"n.","meaning":"名人；知名人物","definition":"A well-known person, especially in entertainment or sport.","examples":[{"en":"A television personality hosted the charity event.","zh":"一位电视名人主持了慈善活动。"},{"en":"The festival attracted several leading sports personalities.","zh":"这个节日吸引了几位著名体育人物。"}]}],"personalize":[{"pos":"v.","meaning":"个性化;使适合个人","definition":"to adapt something for a particular person","examples":[{"en":"The app lets users personalize their schedules.","zh":"应用让用户自定义日程。"},{"en":"Teachers personalize feedback for each learner.","zh":"教师为每位学习者提供个性化反馈。"}]},{"pos":"v.","meaning":"标上姓名或个人标记","definition":"to mark with the owner's name or initials","examples":[{"en":"They personalized the pen with her initials.","zh":"他们在钢笔上刻了她姓名的首字母。"},{"en":"You can personalize the notebook with your name.","zh":"你可以在笔记本上标注自己的姓名。"}]}],"personnel":[{"pos":"n.","meaning":"全体员工；人员","definition":"the people employed by an organisation","examples":[{"en":"All personnel must wear identification.","zh":"所有员工必须佩戴身份标识。"},{"en":"The company trained additional personnel.","zh":"公司培训了更多人员。"}]}],"perspective":[{"pos":"n.","meaning":"视角；观点；看法","definition":"A particular way of considering something.","examples":[{"en":"Living abroad gave her a different perspective on home.","zh":"在海外生活使她从不同角度看待故乡。"},{"en":"Try to see the problem from the customer's perspective.","zh":"试着从顾客的角度看待问题。"}]},{"pos":"n.","meaning":"透视法；空间远近关系","definition":"The representation of depth and distance in an image.","examples":[{"en":"The artist used perspective to create a sense of depth.","zh":"画家使用透视法营造深度感。"},{"en":"The buildings look distorted because the perspective is wrong.","zh":"建筑物看起来变形了，因为透视不正确。"}]}],"persuade":[{"pos":"v.","meaning":"说服;使相信","definition":"to convince someone to act or believe","examples":[{"en":"She persuaded him to take the train.","zh":"她说服他乘火车。"},{"en":"The evidence persuaded us that the claim was true.","zh":"证据使我们相信主张属实。"}]}],"pervasive":[{"pos":"adj.","meaning":"普遍存在的；弥漫的","definition":"spreading throughout an area or group","examples":[{"en":"A pervasive smell of damp filled the house.","zh":"屋里弥漫着潮湿气味。"},{"en":"The report describes pervasive uncertainty.","zh":"报告描述了普遍的不确定性。"}]}],"pest":[{"pos":"n.","meaning":"害虫；有害生物","definition":"An animal that damages crops, food, or property.","examples":[{"en":"The farmer inspected the crop for pests.","zh":"农民检查庄稼是否有害虫。"},{"en":"Sealed containers help keep pests away from stored grain.","zh":"密封容器有助于防止害虫侵入储存的粮食。"}]}],"pesticide":[{"pos":"n.","meaning":"杀虫剂;农药","definition":"a substance used to kill harmful organisms","examples":[{"en":"The farmer reduced pesticide use.","zh":"农民减少了农药用量。"},{"en":"Tests found pesticide residues on the fruit.","zh":"检测发现水果上有农药残留。"}]}],"petrol":[{"pos":"n.","meaning":"汽油（英式）","definition":"fuel used in many car engines","examples":[{"en":"The car is running low on petrol.","zh":"汽车的汽油快用完了。"},{"en":"We stopped to buy petrol.","zh":"我们停下买汽油。"}]}],"petroleum":[{"pos":"n.","meaning":"石油","definition":"A natural liquid mixture used to make fuel and other products.","examples":[{"en":"The country exports petroleum.","zh":"这个国家出口石油。"},{"en":"Many plastics are made from chemicals derived from petroleum.","zh":"许多塑料由石油提取的化学物质制成。"}]}],"phenomenon":[{"pos":"n.","meaning":"现象","definition":"an observable event or fact","examples":[{"en":"The scientist explained the unusual phenomenon.","zh":"科学家解释了不寻常的现象。"},{"en":"Urban migration is a global phenomenon.","zh":"向城市迁移是全球现象。"}]},{"pos":"n.","meaning":"非凡的人或事","definition":"someone or something remarkably successful or impressive","examples":[{"en":"The young pianist became a musical phenomenon.","zh":"年轻钢琴家成为音乐界奇才。"},{"en":"The book was a publishing phenomenon.","zh":"这本书成为出版界的奇迹。"}]}],"philosophy":[{"pos":"n.","meaning":"哲学","definition":"the study of fundamental questions about reality and knowledge","examples":[{"en":"She teaches philosophy at university.","zh":"她在大学教授哲学。"},{"en":"The course introduces Greek philosophy.","zh":"课程介绍希腊哲学。"}]},{"pos":"n.","meaning":"人生观；理念；哲理","definition":"a set of beliefs guiding behaviour","examples":[{"en":"His teaching philosophy emphasises curiosity.","zh":"他的教学理念强调好奇心。"},{"en":"Their design philosophy is based on simplicity.","zh":"他们的设计理念以简洁为基础。"}]}],"photocopy":[{"pos":"v.","meaning":"复印；影印","definition":"To make a paper copy using a photocopier.","examples":[{"en":"Please photocopy the signed form for our records.","zh":"请复印签好的表格供我们存档。"},{"en":"She photocopied the relevant pages.","zh":"她复印了相关页面。"}]},{"pos":"n.","meaning":"复印件；影印本","definition":"A paper copy made using a photocopier.","examples":[{"en":"Keep a photocopy of your application.","zh":"保留一份申请表复印件。"},{"en":"The photocopy was too faint to read.","zh":"复印件颜色太浅，无法阅读。"}]}],"photography":[{"pos":"n.","meaning":"摄影;摄影术","definition":"the art or practice of taking photographs","examples":[{"en":"She studied photography at college.","zh":"她在大学学习摄影。"},{"en":"Digital photography changed how we record events.","zh":"数码摄影改变了我们记录事件的方式。"}]}],"physical":[{"pos":"adj.","meaning":"身体的","definition":"relating to the body","examples":[{"en":"Regular physical activity benefits your health.","zh":"经常参加身体活动有益健康。"},{"en":"The job involves demanding physical work.","zh":"这份工作涉及繁重的体力劳动。"},{"en":"Children need opportunities for physical exercise.","zh":"孩子们需要进行体育锻炼的机会。"}]},{"pos":"adj.","meaning":"物理的；物理学的","definition":"relating to the laws and properties of matter and energy","examples":[{"en":"The experiment measured physical properties of the material.","zh":"实验测量了材料的物理性质。"},{"en":"The model follows basic physical laws.","zh":"模型遵循基本物理定律。"}]},{"pos":"adj.","meaning":"物质的；有形的","definition":"having a material existence","examples":[{"en":"The archive stores both digital and physical records.","zh":"档案馆同时保存数字记录与实物记录。"},{"en":"The project has no physical presence in the town.","zh":"项目在镇上没有实体场所。"}]},{"pos":"n.","meaning":"体检","definition":"a medical examination of the body","examples":[{"en":"He had a physical before joining the team.","zh":"他入队前做了体检。"},{"en":"The job requires an annual physical.","zh":"这份工作要求每年体检。"}]}],"physician":[{"pos":"n.","meaning":"医师；内科医生","definition":"A doctor, especially one treating illness without surgery.","examples":[{"en":"The physician examined the patient's breathing.","zh":"医生检查了患者的呼吸。"},{"en":"Her family physician referred her to a specialist.","zh":"她的家庭医生把她转诊给了专科医生。"}]}],"picturesque":[{"pos":"adj.","meaning":"风景如画的","definition":"visually attractive like a painting","examples":[{"en":"The village has a picturesque harbour.","zh":"村庄有风景如画的港湾。"},{"en":"We followed a picturesque route through the hills.","zh":"我们沿着山间如画的路线前进。"}]},{"pos":"adj.","meaning":"语言生动的","definition":"vivid and colourful in expression","examples":[{"en":"Her picturesque language brought the market to life.","zh":"她生动的语言使市场跃然眼前。"},{"en":"The guide offered a picturesque account of village life.","zh":"导游生动描述了乡村生活。"}]}],"pilot":[{"pos":"n.","meaning":"飞行员","definition":"a person who operates an aircraft","examples":[{"en":"The pilot announced our arrival.","zh":"飞行员宣布我们即将到达。"},{"en":"An experienced pilot flew the plane.","zh":"一位经验丰富的飞行员驾驶飞机。"}]},{"pos":"n.","meaning":"引航员","definition":"a person guiding ships through difficult waters","examples":[{"en":"A harbour pilot boarded the ship.","zh":"港口引航员登上船。"},{"en":"The pilot guided the vessel past the sandbanks.","zh":"引航员引导船只驶过沙洲。"}]},{"pos":"v.","meaning":"驾驶；为……引航","definition":"to control an aircraft or guide a vessel","examples":[{"en":"She piloted the helicopter over the valley.","zh":"她驾驶直升机飞越山谷。"},{"en":"He piloted the boat through the channel.","zh":"他引导船只穿过航道。"}]}],"pine":[{"pos":"n.","meaning":"松树；松木","definition":"An evergreen tree with needles and cones, or its wood.","examples":[{"en":"A tall pine stood beside the cabin.","zh":"小屋旁矗立着一棵高大的松树。"},{"en":"The shelves are made of pine.","zh":"这些搁板用松木制成。"}]},{"pos":"v.","meaning":"思念；渴望；因悲伤而憔悴","definition":"To feel deeply sad because someone or something is absent.","examples":[{"en":"The dog pined for its owner.","zh":"狗思念着主人。"},{"en":"She pined for the quiet village where she had grown up.","zh":"她深深怀念自己长大的宁静村庄。"}]}],"pirate":[{"pos":"n.","meaning":"海盗","definition":"a person attacking and robbing ships","examples":[{"en":"Pirates captured the merchant ship.","zh":"海盗劫持了商船。"},{"en":"The captain feared an attack by pirates.","zh":"船长担心海盗袭击。"}]},{"pos":"n.","meaning":"盗版者;侵犯版权者","definition":"someone illegally copying protected work","examples":[{"en":"Software pirates distributed unauthorised copies.","zh":"软件盗版者散布未经授权的副本。"},{"en":"The publisher pursued the pirate through the courts.","zh":"出版商通过法院追究盗版者责任。"}]},{"pos":"v.","meaning":"盗版;非法复制","definition":"to copy or distribute protected work without permission","examples":[{"en":"The film was pirated soon after release.","zh":"影片上映不久就被盗版。"},{"en":"They were accused of pirating the software.","zh":"他们被指控盗版软件。"}]}],"pitch":[{"pos":"v.","meaning":"投掷；抛","definition":"to throw something","examples":[{"en":"He pitched the ball to his teammate.","zh":"他把球投给队友。"},{"en":"She pitched the empty sack into the cart.","zh":"她把空袋扔进手推车。"}]},{"pos":"v.","meaning":"颠簸；前后摇晃","definition":"to move up and down at the front and back","examples":[{"en":"The boat pitched in the waves.","zh":"船在海浪中上下颠簸。"},{"en":"The aircraft pitched as it entered rough air.","zh":"飞机进入乱流时前后颠簸。"}]},{"pos":"v.","meaning":"定音高；确定程度","definition":"to set a sound or message at a particular level","examples":[{"en":"The singer pitched the first note too high.","zh":"歌手把第一个音唱得太高。"},{"en":"Pitch the explanation at a beginner's level.","zh":"把解释的难度定在初学者水平。"}]},{"pos":"n.","meaning":"沥青；柏油状物","definition":"a dark sticky substance used for waterproofing","examples":[{"en":"The workers sealed the seams with pitch.","zh":"工人用沥青封住接缝。"},{"en":"The old boat smelled of pitch.","zh":"旧船有一股沥青味。"}]},{"pos":"n.","meaning":"运动场地（英式）","definition":"a marked area for playing a sport","examples":[{"en":"The football pitch was waterlogged.","zh":"足球场积水了。"},{"en":"Players returned to the pitch.","zh":"球员回到场上。"}]},{"pos":"n.","meaning":"音高","definition":"how high or low a sound is","examples":[{"en":"The instrument produces a steady pitch.","zh":"乐器发出稳定音高。"},{"en":"Her voice rose in pitch.","zh":"她的声音音调升高了。"}]},{"pos":"n.","meaning":"程度；顶点","definition":"a degree of intensity or a high point","examples":[{"en":"Excitement reached fever pitch.","zh":"兴奋达到了狂热程度。"},{"en":"The debate rose to a high pitch.","zh":"辩论的激烈程度上升。"}]}],"plagiarise":[{"pos":"v.","meaning":"剽窃；抄袭","definition":"To present another person's words or ideas as one's own.","examples":[{"en":"The student was accused of plagiarising an online article.","zh":"这名学生被指控抄袭网络文章。"},{"en":"Writers must acknowledge sources rather than plagiarise them.","zh":"作者必须注明来源，而不能抄袭。"}]}],"plagiarism":[{"pos":"n.","meaning":"剽窃;抄袭;抄袭内容","definition":"presenting another person's work as one's own","examples":[{"en":"The essay was rejected for plagiarism.","zh":"论文因抄袭被拒。"},{"en":"A plagiarism investigation compared the two articles.","zh":"抄袭调查比较了两篇文章。"}]}],"plaster":[{"pos":"n.","meaning":"灰泥；石膏","definition":"a material that hardens after mixing with water","examples":[{"en":"The wall needs fresh plaster.","zh":"墙面需要重新抹灰。"},{"en":"The artist made a plaster cast.","zh":"艺术家制作了石膏模型。"}]},{"pos":"n.","meaning":"膏药；创可贴（英式）","definition":"a small adhesive covering for skin or a wound","examples":[{"en":"She put a plaster on the cut.","zh":"她在伤口上贴了创可贴。"},{"en":"The first-aid box contains plasters.","zh":"急救箱里有创可贴。"}]}],"plastic":[{"pos":"adj.","meaning":"塑料的；塑料制的","definition":"Made of plastic.","examples":[{"en":"The seedlings were growing in plastic trays.","zh":"幼苗长在塑料盘里。"},{"en":"She replaced the broken plastic handle.","zh":"她更换了损坏的塑料把手。"}]}],"plateau":[{"pos":"n.","meaning":"高原","definition":"a large area of high, relatively flat land","examples":[{"en":"The village stands on a dry plateau.","zh":"村庄位于干燥高原上。"},{"en":"They crossed the plateau before sunset.","zh":"他们在日落前穿过了高原。"}]},{"pos":"n.","meaning":"稳定期;停滞期","definition":"a level stage after growth or progress","examples":[{"en":"Sales reached a plateau in June.","zh":"销售额六月进入稳定期。"},{"en":"Her fitness gains hit a plateau.","zh":"她的体能提升进入瓶颈期。"}]}],"platform":[{"pos":"n.","meaning":"站台","definition":"the area beside a railway track where passengers wait","examples":[{"en":"The train to Oxford leaves from platform six.","zh":"去牛津的火车从六号站台发车。"},{"en":"Wait behind the yellow line on the platform.","zh":"请在站台黄线后等候。"},{"en":"A member of staff directed us to the correct platform.","zh":"一名工作人员指引我们去正确的站台。"}]},{"pos":"n.","meaning":"网络平台","definition":"an online system where people can use services or share information","examples":[{"en":"The platform connects tutors with learners online.","zh":"这个平台在线连接导师和学习者。"},{"en":"Our online platform allows users to share documents.","zh":"我们的网络平台允许用户共享文件。"},{"en":"The digital platform offers courses in several languages.","zh":"这个数字平台提供多种语言的课程。"}]},{"pos":"n.","meaning":"平台；讲台","definition":"a raised level surface","examples":[{"en":"The speaker stepped onto the platform.","zh":"发言者走上讲台。"},{"en":"Workers stood on a raised platform.","zh":"工人站在高起的平台上。"}]},{"pos":"n.","meaning":"纲领；政见","definition":"a public statement of aims or policies","examples":[{"en":"The party's platform focused on housing.","zh":"该党的纲领着重于住房。"},{"en":"She campaigned on a platform of local reform.","zh":"她以地方改革纲领开展竞选。"}]}],"plausible":[{"pos":"adj.","meaning":"貌似合理的；似乎可信的","definition":"Appearing reasonable or likely to be true.","examples":[{"en":"He offered a plausible explanation for the delay.","zh":"他对延误给出了一个似乎合理的解释。"},{"en":"The researchers tested several plausible causes.","zh":"研究人员检验了几种可能的原因。"}]},{"pos":"adj.","meaning":"善于花言巧语的；貌似诚恳的","definition":"Sounding convincing, sometimes in a misleading way.","examples":[{"en":"The plausible salesman persuaded them to pay in advance.","zh":"那位能说会道的推销员说服他们预先付款。"},{"en":"She was fooled by his plausible manner.","zh":"她被他貌似诚恳的态度骗了。"}]}],"pledge":[{"pos":"v.","meaning":"保证;正式承诺","definition":"to make a serious promise","examples":[{"en":"The company pledged to reduce waste.","zh":"公司承诺减少浪费。"},{"en":"She pledged her support for the project.","zh":"她承诺支持项目。"}]},{"pos":"v.","meaning":"抵押","definition":"to offer property as security","examples":[{"en":"He pledged his house as security.","zh":"他把房屋作为抵押。"},{"en":"The farmer pledged the harvest against a loan.","zh":"农民以收成为贷款作担保。"}]},{"pos":"n.","meaning":"誓言;保证","definition":"a serious promise","examples":[{"en":"They signed a pledge to protect the forest.","zh":"他们签署了保护森林的承诺书。"},{"en":"She honoured her pledge to return.","zh":"她履行了承诺，回来了。"}]},{"pos":"n.","meaning":"抵押物;抵押","definition":"property offered as security","examples":[{"en":"The ring was held as a pledge.","zh":"戒指被留作抵押物。"},{"en":"The lender required a pledge of assets.","zh":"贷款人要求抵押资产。"}]}],"pliable":[{"pos":"adj.","meaning":"柔韧的；易弯曲的","definition":"easily bent without breaking","examples":[{"en":"Warm the material until pliable.","zh":"把材料加热至柔韧可弯。"},{"en":"The basket is woven from pliable branches.","zh":"篮子用柔韧的枝条编成。"}]},{"pos":"adj.","meaning":"易受影响的；顺从的","definition":"easily persuaded or controlled","examples":[{"en":"The leader preferred pliable advisers.","zh":"领导者偏爱顺从的顾问。"},{"en":"Young opinions can be highly pliable.","zh":"年轻人的观点可能很容易受到影响。"}]}],"plot":[{"pos":"n.","meaning":"情节","definition":"The sequence of events in a story.","examples":[{"en":"The plot becomes more complex in the final chapters.","zh":"故事情节在最后几章变得更加复杂。"},{"en":"A surprising twist changes the direction of the plot.","zh":"一个出人意料的转折改变了情节走向。"}]},{"pos":"n.","meaning":"阴谋；密谋","definition":"A secret plan to do something harmful or illegal.","examples":[{"en":"The police uncovered a plot to steal the paintings.","zh":"警方揭露了一起盗窃画作的阴谋。"},{"en":"The novel centres on a plot against the king.","zh":"小说围绕针对国王的阴谋展开。"}]},{"pos":"n.","meaning":"小块土地；地块","definition":"A small piece of land used for a particular purpose.","examples":[{"en":"They grow vegetables on a small plot.","zh":"他们在一小块地上种蔬菜。"},{"en":"The empty plot will become a community garden.","zh":"这块空地将成为社区花园。"}]}],"plough":[{"pos":"n.","meaning":"犁","definition":"a tool for turning soil before planting","examples":[{"en":"The horse pulled the heavy plough.","zh":"马拉着沉重的犁。"},{"en":"The farmer repaired a broken plough.","zh":"农民修好了坏犁。"}]},{"pos":"v.","meaning":"犁地;耕地","definition":"to turn soil with a plough","examples":[{"en":"They ploughed the field in autumn.","zh":"他们秋天犁了田。"},{"en":"The tractor ploughed a straight furrow.","zh":"拖拉机犁出笔直的沟。"}]},{"pos":"v.","meaning":"奋力穿过;开路;破浪","definition":"to move forcefully through something","examples":[{"en":"The ship ploughed through rough waves.","zh":"船在巨浪中破浪前行。"},{"en":"We ploughed our way through deep snow.","zh":"我们奋力穿过深雪。"}]}],"plus":[{"pos":"prep.","meaning":"加上；以及","definition":"with the addition of","examples":[{"en":"The price is fifty pounds plus tax.","zh":"价格为五十英镑另加税。"},{"en":"Two plus three equals five.","zh":"二加三等于五。"}]},{"pos":"n.","meaning":"加号；正号","definition":"the symbol indicating addition or a positive value","examples":[{"en":"Put a plus before the positive number.","zh":"在正数前写一个正号。"},{"en":"The button is marked with a plus.","zh":"按钮上标有加号。"}]},{"pos":"adj.","meaning":"以上的；更多的","definition":"more than the amount stated","examples":[{"en":"The trip takes two hours plus.","zh":"旅程需要两个多小时。"},{"en":"The programme is for ages sixteen plus.","zh":"节目适合十六岁及以上人群。"}]}],"plush":[{"pos":"adj.","meaning":"豪华的；舒适的","definition":"Richly comfortable and expensive-looking.","examples":[{"en":"We waited in a plush lounge.","zh":"我们在豪华休息室等候。"},{"en":"The theatre has plush red seats.","zh":"剧院配有舒适华丽的红色座椅。"}]},{"pos":"n.","meaning":"长毛绒","definition":"A soft fabric with a long raised surface.","examples":[{"en":"The toy bear was covered in brown plush.","zh":"玩具熊外面包着棕色长毛绒。"},{"en":"She chose plush for the costume's collar.","zh":"她选择长毛绒制作服装的领子。"}]}],"point":[{"pos":"n.","meaning":"尖端;尖头","definition":"the sharp end of something","examples":[{"en":"The pencil's point broke.","zh":"铅笔尖断了。"},{"en":"Keep the knife point away from your hand.","zh":"刀尖要远离手。"}]},{"pos":"n.","meaning":"点;地点;时刻;小数点","definition":"a precise position or mark","examples":[{"en":"Mark the meeting point on the map.","zh":"在地图上标出集合点。"},{"en":"The decimal point is in the wrong place.","zh":"小数点位置错了。"}]},{"pos":"n.","meaning":"要点;论点;观点;细目","definition":"an idea or item in an argument or list","examples":[{"en":"Your final point is convincing.","zh":"你的最后一个论点很有说服力。"},{"en":"We discussed each point on the agenda.","zh":"我们讨论了议程上的每个事项。"}]},{"pos":"n.","meaning":"得分;分数","definition":"a unit used to score performance","examples":[{"en":"The team won by two points.","zh":"球队以两分优势获胜。"},{"en":"Each correct answer earns one point.","zh":"每答对一题得一分。"}]},{"pos":"v.","meaning":"指向;指明;瞄准","definition":"to direct something or indicate a direction","examples":[{"en":"She pointed to the exit.","zh":"她指向出口。"},{"en":"The evidence points to a different explanation.","zh":"证据指向另一种解释。"}]}],"poison":[{"pos":"n.","meaning":"毒物；毒药","definition":"a substance that can harm or kill","examples":[{"en":"The laboratory identified the poison.","zh":"实验室鉴定了毒物。"},{"en":"The label warns that the substance is a poison.","zh":"标签警告该物质是毒物。"}]},{"pos":"v.","meaning":"使中毒；毒害","definition":"to harm with a toxic substance","examples":[{"en":"The leak poisoned the river.","zh":"泄漏污染毒害了河流。"},{"en":"False rumours poisoned their relationship.","zh":"虚假谣言毒害了他们的关系。"}]}],"poisonous":[{"pos":"adj.","meaning":"有毒的；有害的","definition":"Containing or producing a substance that can cause illness or death.","examples":[{"en":"Some wild mushrooms are poisonous.","zh":"有些野生蘑菇有毒。"},{"en":"The fire released poisonous fumes.","zh":"火灾释放了有毒烟气。"}]},{"pos":"adj.","meaning":"恶毒的；充满恶意的","definition":"Intended to harm through cruel words or behaviour.","examples":[{"en":"A poisonous rumour spread through the office.","zh":"一个恶毒的谣言在办公室传播开来。"},{"en":"The argument created a poisonous atmosphere.","zh":"争论造成了一种充满敌意的气氛。"}]}],"policy":[{"pos":"n.","meaning":"政策；方针","definition":"a plan or rule guiding decisions","examples":[{"en":"The new policy encourages energy conservation.","zh":"新政策鼓励节约能源。"},{"en":"Parents questioned the school's phone policy.","zh":"家长质疑学校的手机管理政策。"},{"en":"A clear policy helps staff make consistent decisions.","zh":"明确的政策帮助员工做出一致的决定。"}]}],"polish":[{"pos":"v.","meaning":"擦亮；磨光","definition":"to make a surface smooth and shiny","examples":[{"en":"She polished the silver bowl.","zh":"她擦亮了银碗。"},{"en":"The workers polished the stone floor.","zh":"工人磨光了石地板。"}]},{"pos":"v.","meaning":"润色；改进","definition":"to improve through careful revision or practice","examples":[{"en":"He polished his presentation before the meeting.","zh":"他在会前完善了演示。"},{"en":"The editor helped polish the final paragraph.","zh":"编辑帮助润色最后一段。"}]},{"pos":"n.","meaning":"擦光剂；上光蜡","definition":"a substance used to make a surface shiny","examples":[{"en":"Apply a little shoe polish.","zh":"涂一点鞋油。"},{"en":"The cupboard contained furniture polish.","zh":"柜子里有家具上光剂。"}]}],"poll":[{"pos":"n.","meaning":"民意调查；民意测验","definition":"A survey of people's opinions.","examples":[{"en":"The poll asked residents about public transport.","zh":"民意调查询问居民对公共交通的看法。"},{"en":"A recent poll showed strong support for the library.","zh":"近期民调显示人们大力支持图书馆。"}]},{"pos":"n.","meaning":"投票；选举","definition":"The act of voting or an election.","examples":[{"en":"Voters went to the polls early in the morning.","zh":"选民一大早就去投票。"},{"en":"The candidate won a majority of the poll.","zh":"这名候选人获得了多数选票。"}]},{"pos":"v.","meaning":"对……进行民意调查","definition":"To ask people for their opinions in a survey.","examples":[{"en":"The researchers polled five hundred households.","zh":"研究人员调查了五百户家庭的意见。"},{"en":"The newspaper polled readers about the proposed changes.","zh":"报纸就拟议改动调查了读者意见。"}]},{"pos":"v.","meaning":"获得选票","definition":"To receive a particular number or proportion of votes.","examples":[{"en":"She polled forty per cent of the vote.","zh":"她获得了百分之四十的选票。"},{"en":"The independent candidate polled better than expected.","zh":"独立候选人的得票情况比预期好。"}]}],"pollinate":[{"pos":"v.","meaning":"给……授粉","definition":"to transfer pollen so fertilization can occur","examples":[{"en":"Bees pollinate many fruit trees.","zh":"蜜蜂给许多果树授粉。"},{"en":"Workers pollinated the flowers by hand.","zh":"工人给花人工授粉。"}]}],"pollutant":[{"pos":"n.","meaning":"污染物；有害污染物质","definition":"a substance that contaminates the environment","examples":[{"en":"The filter removes pollutants from the water.","zh":"过滤器去除水中的污染物。"},{"en":"Vehicles release pollutants into the air.","zh":"车辆向空气中排放污染物。"}]}],"pollution":[{"pos":"n.","meaning":"污染；玷污","definition":"The contamination of an environment, or the state of being contaminated.","examples":[{"en":"Air pollution is a serious problem in many cities.","zh":"空气污染是许多城市的严重问题。"},{"en":"The river was closed to swimmers because of pollution.","zh":"这条河因污染而禁止游泳。"},{"en":"Better public transport can help reduce pollution.","zh":"更好的公共交通有助于减少污染。"}]},{"pos":"n.","meaning":"污染物；有害物质","definition":"Harmful material that contaminates an environment.","examples":[{"en":"Filters remove much of the pollution from the exhaust gases.","zh":"过滤器去除了废气中的大量污染物。"},{"en":"Ocean currents carried the pollution far from the damaged tanker.","zh":"洋流把污染物带到了离受损油轮很远的地方。"}]}],"populace":[{"pos":"n.","meaning":"全体居民;平民;大众","definition":"the people living in a country or area","examples":[{"en":"The policy angered the local populace.","zh":"政策激怒了当地居民。"},{"en":"The festival brought the populace together.","zh":"节庆使全体居民聚在一起。"}]}],"popularity":[{"pos":"n.","meaning":"受欢迎程度；流行","definition":"the state of being liked by many people","examples":[{"en":"The sport's popularity has grown.","zh":"这项运动越来越受欢迎。"},{"en":"The cafe owes its popularity to friendly service.","zh":"咖啡馆因服务友好而受欢迎。"}]}],"popularize":[{"pos":"v.","meaning":"推广；使普及","definition":"To make something widely known or liked.","examples":[{"en":"The television series popularized coastal walking.","zh":"这部电视系列片让海岸徒步广受欢迎。"},{"en":"Local clubs helped popularize the sport.","zh":"当地俱乐部帮助普及了这项运动。"}]},{"pos":"v.","meaning":"使通俗化","definition":"To explain a difficult subject so that many people can understand it.","examples":[{"en":"The author popularized astronomy through lively books.","zh":"作者通过生动的书籍使天文学通俗化。"},{"en":"The exhibition popularizes complex research without oversimplifying it.","zh":"展览以通俗方式介绍复杂研究，同时避免过度简化。"}]}],"populate":[{"pos":"v.","meaning":"居住于;使有人口","definition":"to live in or fill a place","examples":[{"en":"Small fishing communities populate the coast.","zh":"沿海分布着小型渔村。"},{"en":"The island is populated mainly by seabirds.","zh":"岛上主要栖息着海鸟。"}]}],"population":[{"pos":"n.","meaning":"人口；某地区的全部居民","definition":"all the people living in an area","examples":[{"en":"The town's population is growing.","zh":"小镇人口正在增长。"},{"en":"Most of the population lives near the coast.","zh":"大部分人口住在沿海。"}]}],"pore over":[{"pos":"v.","meaning":"仔细阅读；认真研究","definition":"To examine written material closely and carefully.","examples":[{"en":"She pored over the map before choosing a route.","zh":"她仔细研究地图后才选择路线。"},{"en":"The accountant pored over the records for hours.","zh":"会计仔细查看记录长达数小时。"}]}],"portable":[{"pos":"adj.","meaning":"便携的;手提式的","definition":"easy to carry or move","examples":[{"en":"She bought a portable speaker.","zh":"她买了便携音箱。"},{"en":"A portable heater warmed the tent.","zh":"便携取暖器给帐篷供暖。"}]}],"portion":[{"pos":"n.","meaning":"部分；份额","definition":"a part of a larger whole","examples":[{"en":"A portion of the profits supports the charity.","zh":"一部分利润用于支持慈善机构。"},{"en":"Only a small portion of the site was excavated.","zh":"遗址只有一小部分被发掘。"}]},{"pos":"n.","meaning":"一份食物","definition":"an amount of food served to one person","examples":[{"en":"The restaurant serves generous portions.","zh":"餐馆供应的食物分量很足。"},{"en":"She ordered a small portion of rice.","zh":"她点了一小份米饭。"}]},{"pos":"v.","meaning":"分配；分成份","definition":"to divide into shares","examples":[{"en":"Portion the mixture into six bowls.","zh":"把混合物分装到六个碗里。"},{"en":"They portioned out the available supplies.","zh":"他们分配了现有物资。"}]}],"position":[{"pos":"n.","meaning":"位置；方位","definition":"The place where something is located.","examples":[{"en":"Mark your position on the map.","zh":"在地图上标出你的位置。"},{"en":"The telescope can determine the star's position.","zh":"望远镜可以确定恒星的位置。"}]},{"pos":"n.","meaning":"职位；职务","definition":"A job or official role.","examples":[{"en":"She applied for a teaching position.","zh":"她申请了一个教学职位。"},{"en":"The position requires experience in project management.","zh":"这个职位要求有项目管理经验。"}]},{"pos":"n.","meaning":"姿势；姿态","definition":"The way the body or an object is arranged.","examples":[{"en":"Change your sitting position regularly.","zh":"定期变换坐姿。"},{"en":"The chair can be adjusted to a comfortable position.","zh":"椅子可以调整到舒适的位置。"}]},{"pos":"n.","meaning":"立场；看法","definition":"An opinion or attitude on an issue.","examples":[{"en":"The union explained its position on pay.","zh":"工会阐明了其在薪资问题上的立场。"},{"en":"Her position changed after she saw the evidence.","zh":"看到证据后，她改变了看法。"}]},{"pos":"v.","meaning":"放置；安置；使处于某位置","definition":"To put something in a particular place.","examples":[{"en":"Position the lamp beside the desk.","zh":"把灯放在书桌旁边。"},{"en":"The camera was positioned to face the entrance.","zh":"相机被安置为对准入口。"}]}],"positive":[{"pos":"adj.","meaning":"积极的;乐观的;有益的","definition":"constructive or expecting good results","examples":[{"en":"The change had a positive effect.","zh":"变化产生了积极影响。"},{"en":"She remained positive despite the setback.","zh":"尽管受挫，她仍保持乐观。"}]},{"pos":"adj.","meaning":"确定的;明确的;肯定的","definition":"certain or definite","examples":[{"en":"Are you positive that the door is locked?","zh":"你确定门锁好了吗？"},{"en":"The witness made a positive identification.","zh":"证人作出了明确辨认。"}]},{"pos":"adj.","meaning":"阳性的","definition":"showing that a tested substance or condition is present","examples":[{"en":"The test gave a positive result.","zh":"检测结果呈阳性。"},{"en":"A second sample confirmed the positive finding.","zh":"第二份样本确认了阳性发现。"}]}],"possess":[{"pos":"v.","meaning":"拥有；具有","definition":"to own something or have a quality","examples":[{"en":"She possesses excellent organisational skills.","zh":"她具有出色的组织能力。"},{"en":"The museum possesses a rare manuscript.","zh":"博物馆拥有一份珍贵手稿。"}]}],"possession":[{"pos":"n.","meaning":"拥有；持有；所有权","definition":"The state of having or owning something.","examples":[{"en":"The museum took possession of the collection.","zh":"博物馆获得了这批藏品的所有权。"},{"en":"The documents remained in her possession.","zh":"文件仍由她持有。"}]},{"pos":"n.","meaning":"财产；所有物","definition":"Something that someone owns.","examples":[{"en":"Books were her most treasured possessions.","zh":"书籍是她最珍贵的财产。"},{"en":"They packed their few possessions into two suitcases.","zh":"他们把仅有的财物装进两个箱子。"}]},{"pos":"n.","meaning":"属地；领地","definition":"A territory controlled by a country.","examples":[{"en":"The island was once an overseas possession.","zh":"这座岛曾经是一块海外属地。"},{"en":"The map shows the empire's distant possessions.","zh":"地图显示了这个帝国遥远的领地。"}]}],"post-mortem":[{"pos":"adj.","meaning":"死后的;事后的","definition":"occurring after death or after an event","examples":[{"en":"The report included post-mortem findings.","zh":"报告包含死后检查结果。"},{"en":"A post-mortem review identified planning errors.","zh":"事后审查查明了规划错误。"}]},{"pos":"n.","meaning":"尸体解剖;验尸","definition":"an examination of a body to determine the cause of death","examples":[{"en":"The post-mortem established the cause of death.","zh":"尸检确定了死因。"},{"en":"A pathologist carried out the post-mortem.","zh":"病理医生进行了尸检。"}]},{"pos":"n.","meaning":"事后分析;总结反思","definition":"an analysis after an event to explain what happened","examples":[{"en":"The team held a post-mortem after the failed launch.","zh":"发布失败后团队进行了复盘。"},{"en":"Their post-mortem produced several useful lessons.","zh":"事后分析总结了几条有用教训。"}]}],"postcode":[{"pos":"n.","meaning":"邮政编码","definition":"a code identifying a postal delivery area","examples":[{"en":"Please include your postcode.","zh":"请写上邮政编码。"},{"en":"The website searches by postcode.","zh":"网站按邮政编码搜索。"}]}],"postgraduate":[{"pos":"n.","meaning":"研究生","definition":"A student studying for a higher qualification after a first degree.","examples":[{"en":"The laboratory employs several postgraduates.","zh":"实验室聘用了几名研究生。"},{"en":"She became a postgraduate in environmental science.","zh":"她成为了一名环境科学研究生。"}]}],"postpone":[{"pos":"v.","meaning":"推迟","definition":"to move an event to a later time","examples":[{"en":"We have to postpone the meeting until Friday.","zh":"我们必须把会议推迟到周五。"},{"en":"Bad weather forced us to postpone the outdoor event.","zh":"恶劣天气迫使我们推迟户外活动。"},{"en":"Please do not postpone submitting your application.","zh":"请不要推迟提交申请。"}]}],"posture":[{"pos":"n.","meaning":"姿势；体态","definition":"the position in which the body is held","examples":[{"en":"The chair encourages an upright posture.","zh":"椅子有助于保持直立坐姿。"},{"en":"The dancer changed her posture.","zh":"舞者改变了姿势。"}]},{"pos":"n.","meaning":"态度；立场","definition":"an approach adopted towards a situation","examples":[{"en":"The company adopted a defensive posture.","zh":"公司采取了防御立场。"},{"en":"Their negotiating posture became more flexible.","zh":"他们的谈判姿态变得更灵活。"}]}],"potential":[{"pos":"adj.","meaning":"潜在的；可能的","definition":"Able to develop or become real in the future.","examples":[{"en":"The site has several potential uses.","zh":"这个场所有几种潜在用途。"},{"en":"We identified a potential problem with the design.","zh":"我们发现了设计中一个可能的问题。"}]},{"pos":"n.","meaning":"潜力；潜能","definition":"The capacity to develop or achieve something.","examples":[{"en":"The young athlete has enormous potential.","zh":"这名年轻运动员潜力巨大。"},{"en":"The region has considerable potential for solar energy.","zh":"该地区发展太阳能具有相当大的潜力。"}]}],"poultry":[{"pos":"n.","meaning":"家禽;禽肉","definition":"domesticated birds raised for meat or eggs, or their meat","examples":[{"en":"The farm raises poultry and sheep.","zh":"农场饲养家禽和羊。"},{"en":"Keep raw poultry separate from cooked food.","zh":"生禽肉与熟食分开存放。"}]}],"pour":[{"pos":"v.","meaning":"倒；灌；倾泻","definition":"to make liquid flow or flow heavily","examples":[{"en":"Pour the water into the jug.","zh":"把水倒进壶里。"},{"en":"Rain poured through the broken roof.","zh":"雨水从破屋顶倾泻而入。"}]},{"pos":"v.","meaning":"大量涌入；不断涌现","definition":"to arrive or move in large quantities","examples":[{"en":"Visitors poured into the gallery.","zh":"游客涌入展厅。"},{"en":"Donations poured in after the appeal.","zh":"呼吁发出后，捐款纷纷涌来。"}]}],"poverty":[{"pos":"n.","meaning":"贫困","definition":"the condition of having too little money for basic needs","examples":[{"en":"Many families struggle to escape poverty.","zh":"许多家庭艰难地试图摆脱贫困。"},{"en":"Affordable childcare can help reduce poverty.","zh":"负担得起的托育服务有助于减少贫困。"},{"en":"The charity supports children living in poverty.","zh":"该慈善机构帮助生活贫困的儿童。"}]}],"practical":[{"pos":"adj.","meaning":"实践的；应用的","definition":"relating to actual activity rather than theory","examples":[{"en":"The workshop teaches practical skills.","zh":"这个工作坊教授实用技能。"},{"en":"Students gain practical experience during their placement.","zh":"学生在实习期间获得实践经验。"}]},{"pos":"adj.","meaning":"实用的；切合实际的","definition":"useful and workable in real circumstances","examples":[{"en":"We need a practical solution to the storage problem.","zh":"我们需要一个解决储物问题的实用方案。"},{"en":"The folding table is a practical choice for a small room.","zh":"折叠桌对小房间而言是实用的选择。"}]}],"practically":[{"pos":"adv.","meaning":"几乎；差不多","definition":"almost entirely","examples":[{"en":"The work is practically finished.","zh":"工作几乎完成了。"},{"en":"Practically everyone attended the meeting.","zh":"几乎所有人都参加了会议。"}]},{"pos":"adv.","meaning":"从实际角度；实际地","definition":"in a practical manner or in real conditions","examples":[{"en":"Practically speaking, the plan needs more staff.","zh":"从实际角度看，计划需要更多人员。"},{"en":"The course teaches students to think practically.","zh":"课程教学生从实际出发思考。"}]}],"practise":[{"pos":"v.","meaning":"练习；训练","definition":"to repeat an activity in order to improve a skill","examples":[{"en":"I practise speaking English with a friend every evening.","zh":"我每天晚上和朋友练习说英语。"},{"en":"The musicians practise in the hall after school.","zh":"这些音乐学员放学后在礼堂练习。"}]},{"pos":"v.","meaning":"从事专业工作；执业","definition":"to work in a profession such as medicine or law","examples":[{"en":"She is qualified to practise law in this country.","zh":"她具备在这个国家从事律师工作的资格。"},{"en":"Doctors must register before they can practise medicine here.","zh":"医生在这里行医前必须注册。"}]},{"pos":"v.","meaning":"实行；奉行","definition":"to regularly follow a belief or way of behaving","examples":[{"en":"The community continues to practise its traditional customs.","zh":"这个社区继续沿袭其传统习俗。"},{"en":"It is easier to recommend patience than to practise it.","zh":"劝别人耐心比自己做到耐心容易。"}]}],"pragmatic":[{"pos":"adj.","meaning":"务实的；实事求是的","definition":"Dealing with practical realities rather than abstract ideals.","examples":[{"en":"They adopted a pragmatic solution to the shortage.","zh":"他们对短缺采取了务实的解决办法。"},{"en":"Her pragmatic approach kept the project moving.","zh":"她务实的做法推动项目继续进行。"}]}],"precarious":[{"pos":"adj.","meaning":"不稳定的;危险的;不牢靠的","definition":"unsafe or likely to fail","examples":[{"en":"The ladder was in a precarious position.","zh":"梯子摆得很不稳。"},{"en":"The family faced a precarious financial future.","zh":"家庭面临不稳定的财务前景。"}]}],"precede":[{"pos":"v.","meaning":"先于；在……之前","definition":"to happen or come before","examples":[{"en":"A short introduction preceded the film.","zh":"影片前有一段简短介绍。"},{"en":"Dark clouds often precede a storm.","zh":"暴风雨前往往先出现乌云。"}]}],"precedent":[{"pos":"n.","meaning":"先例；范例；惯例","definition":"An earlier action or decision that guides later ones.","examples":[{"en":"The decision set an important precedent.","zh":"这个决定确立了一个重要先例。"},{"en":"There is no precedent for a closure of this length.","zh":"如此长时间的关闭没有先例。"}]}],"precipitation":[{"pos":"n.","meaning":"降水;降水量","definition":"rain, snow, or other water falling from the atmosphere","examples":[{"en":"Annual precipitation is low in the desert.","zh":"沙漠年降水量很低。"},{"en":"The forecast predicts heavy precipitation.","zh":"预报称将有强降水。"}]},{"pos":"n.","meaning":"沉淀作用","definition":"the formation of a solid from a solution","examples":[{"en":"Mixing the solutions caused precipitation.","zh":"混合溶液引起了沉淀。"},{"en":"The experiment measured the rate of precipitation.","zh":"实验测量了沉淀形成速度。"}]},{"pos":"n.","meaning":"仓促;急躁（较少用）","definition":"rash or excessive haste","examples":[{"en":"His precipitation led to an avoidable mistake.","zh":"他的仓促导致了可避免的错误。"},{"en":"She urged patience instead of precipitation.","zh":"她劝人耐心行事，别急躁。"}]}],"precise":[{"pos":"adj.","meaning":"精确的；准确的","definition":"exact and accurate","examples":[{"en":"We need a precise measurement.","zh":"我们需要精确的测量。"},{"en":"The report gives precise dates.","zh":"报告给出了准确日期。"}]},{"pos":"adj.","meaning":"严谨的；细致的","definition":"careful and exact in behaviour","examples":[{"en":"She is precise in her use of language.","zh":"她用语严谨。"},{"en":"His precise movements impressed the instructor.","zh":"他精确细致的动作给教练留下印象。"}]}],"precision":[{"pos":"n.","meaning":"精确；准确；精确度","definition":"The quality of being exact and careful.","examples":[{"en":"The instrument measures distances with great precision.","zh":"这个仪器测量距离的精确度很高。"},{"en":"The surgeon worked with remarkable precision.","zh":"外科医生操作得极为精准。"}]}],"predator":[{"pos":"n.","meaning":"捕食者;捕食性动物","definition":"an animal that hunts other animals","examples":[{"en":"The owl is an efficient predator.","zh":"猫头鹰是高效捕食者。"},{"en":"Small fish hide from predators.","zh":"小鱼躲避捕食者。"}]},{"pos":"n.","meaning":"掠夺者;剥削者","definition":"a person exploiting vulnerable others","examples":[{"en":"Financial predators targeted elderly people living alone.","zh":"金融骗子盯上了独居老年人。"},{"en":"The organisation protects children from sexual predators.","zh":"组织保护儿童免受性侵害者伤害。"}]}],"predatory":[{"pos":"adj.","meaning":"捕食性的","definition":"hunting other animals for food","examples":[{"en":"Owls are predatory birds.","zh":"猫头鹰是捕食性鸟类。"},{"en":"The pond contains predatory insects.","zh":"池塘里有捕食性昆虫。"}]},{"pos":"adj.","meaning":"掠夺性的；剥削他人的","definition":"seeking to exploit others","examples":[{"en":"The rules target predatory lending.","zh":"规则针对掠夺性放贷。"},{"en":"The report criticised the company's predatory practices.","zh":"报告批评了公司的掠夺性做法。"}]}],"predict":[{"pos":"v.","meaning":"预测；预言；预告","definition":"To say what is likely to happen.","examples":[{"en":"Experts predict a rise in demand.","zh":"专家预测需求将上升。"},{"en":"It is difficult to predict the exact path of the storm.","zh":"很难预测风暴的确切路径。"}]}],"predictable":[{"pos":"adj.","meaning":"可预测的","definition":"possible to foresee","examples":[{"en":"The experiment produced predictable results.","zh":"实验产生了可预测的结果。"},{"en":"The tides follow a predictable cycle.","zh":"潮汐遵循可预测的周期。"}]},{"pos":"adj.","meaning":"老套的;墨守成规的","definition":"so familiar that it is unsurprising or dull","examples":[{"en":"The film had a predictable ending.","zh":"电影结局很老套。"},{"en":"His speeches became increasingly predictable.","zh":"他的演讲越来越千篇一律。"}]}],"prediction":[{"pos":"n.","meaning":"预测；预言","definition":"a statement about a likely future event","examples":[{"en":"Her prediction proved accurate.","zh":"她的预测证明准确。"},{"en":"The model generates rainfall predictions.","zh":"模型生成降雨预测。"}]}],"predispose":[{"pos":"v.","meaning":"使倾向于；预先影响","definition":"To make someone more likely to think or act in a certain way.","examples":[{"en":"Her early experiences predisposed her to distrust strangers.","zh":"她早年的经历使她倾向于不信任陌生人。"},{"en":"A supportive upbringing may predispose children to cooperate.","zh":"充满支持的成长环境可能使孩子更愿意合作。"}]},{"pos":"v.","meaning":"使易患；使易受影响","definition":"To make someone more susceptible to a condition.","examples":[{"en":"The study examined factors that predispose people to the disease.","zh":"研究考察了使人容易患这种疾病的因素。"},{"en":"Certain inherited traits can predispose animals to particular disorders.","zh":"某些遗传特征可能使动物易患特定疾病。"}]}],"predominant":[{"pos":"adj.","meaning":"主要的;占支配地位的;盛行的","definition":"more common or influential than others","examples":[{"en":"Agriculture is the predominant industry.","zh":"农业是主导产业。"},{"en":"Blue is the predominant colour in the painting.","zh":"蓝色是画作的主色调。"}]}],"predominantly":[{"pos":"adv.","meaning":"主要地；大部分地","definition":"mainly or mostly","examples":[{"en":"The area is predominantly rural.","zh":"该地区主要是乡村。"},{"en":"The audience was predominantly young.","zh":"观众大部分是年轻人。"}]}],"predominate":[{"pos":"v.","meaning":"占主导地位；占多数；占优势","definition":"To be greater in number, importance, or influence.","examples":[{"en":"Small farms predominate in this region.","zh":"这个地区以小农场为主。"},{"en":"Economic concerns predominated in the discussion.","zh":"经济问题在讨论中占主导地位。"}]}],"prefabricate":[{"pos":"v.","meaning":"预制","definition":"to manufacture parts before assembly at a site","examples":[{"en":"The company prefabricates wall panels.","zh":"公司预制墙板。"},{"en":"Sections were prefabricated and assembled on site.","zh":"各部分预先制造，再在现场组装。"}]}],"preface":[{"pos":"n.","meaning":"序言；前言","definition":"an introduction at the beginning of a book","examples":[{"en":"The preface explains the author's purpose.","zh":"序言解释作者的目的。"},{"en":"She wrote a preface to the new edition.","zh":"她为新版写了前言。"}]},{"pos":"v.","meaning":"作序；以……开场","definition":"to introduce something with preliminary remarks","examples":[{"en":"He prefaced his talk with a story.","zh":"他用一个故事作为演讲开场。"},{"en":"The editor prefaced the collection with a brief essay.","zh":"编辑为选集作了一篇简短序文。"}]}],"preferable":[{"pos":"adj.","meaning":"更可取的；更合意的","definition":"More suitable or desirable.","examples":[{"en":"A written agreement is preferable to a verbal promise.","zh":"书面协议比口头承诺更可取。"},{"en":"Walking is preferable when the streets are congested.","zh":"街道拥堵时，步行更合适。"}]}],"preference":[{"pos":"n.","meaning":"偏爱;偏好","definition":"liking one thing more than another","examples":[{"en":"She has a preference for quiet hotels.","zh":"她偏爱安静的酒店。"},{"en":"Please state your seating preference.","zh":"请说明座位偏好。"}]},{"pos":"n.","meaning":"优先;优待","definition":"priority given to someone or something","examples":[{"en":"Preference is given to local applicants.","zh":"当地申请者获得优先考虑。"},{"en":"The policy grants preference to recycled materials.","zh":"政策优先采用回收材料。"}]}],"pregnancy":[{"pos":"n.","meaning":"怀孕；孕期","definition":"the condition or period of carrying a developing baby","examples":[{"en":"The study followed women during pregnancy.","zh":"研究追踪了孕期女性。"},{"en":"She announced her pregnancy to the family.","zh":"她向家人宣布了怀孕消息。"}]}],"pregnant":[{"pos":"adj.","meaning":"怀孕的；妊娠的","definition":"Carrying a developing baby or young animal.","examples":[{"en":"She was pregnant with her first child.","zh":"她怀着第一个孩子。"},{"en":"The farmer moved the pregnant mare to a quieter field.","zh":"农民把怀孕的母马移到较安静的牧场。"}]},{"pos":"adj.","meaning":"充满意味的；蕴含着的","definition":"Filled with significance, emotion, or possibility.","examples":[{"en":"A pregnant pause followed the announcement.","zh":"宣布之后，出现了一段意味深长的沉默。"},{"en":"The moment seemed pregnant with possibility.","zh":"那个时刻似乎蕴含着无限可能。"}]}],"preliminary":[{"pos":"adj.","meaning":"初步的;预备的","definition":"coming before the main stage","examples":[{"en":"Preliminary results look encouraging.","zh":"初步结果令人鼓舞。"},{"en":"We held a preliminary meeting.","zh":"我们举行了预备会议。"}]},{"pos":"n.","meaning":"准备工作;初步步骤;预赛","definition":"an action or event before the main one","examples":[{"en":"We completed the preliminaries quickly.","zh":"我们很快完成准备工作。"},{"en":"She qualified through the preliminaries.","zh":"她通过预赛获得资格。"}]}],"premier":[{"pos":"n.","meaning":"总理；首相","definition":"the head of a government","examples":[{"en":"The premier addressed parliament.","zh":"总理向议会发表讲话。"},{"en":"The delegation met the provincial premier.","zh":"代表团会见了省政府首脑。"}]},{"pos":"adj.","meaning":"首要的；最著名的","definition":"first in importance or quality","examples":[{"en":"It is one of the region's premier museums.","zh":"它是地区内首屈一指的博物馆之一。"},{"en":"The tournament attracts premier athletes.","zh":"锦标赛吸引顶尖运动员。"}]}],"premise":[{"pos":"n.","meaning":"前提；假设","definition":"An idea accepted as the starting point of an argument.","examples":[{"en":"The argument rests on a questionable premise.","zh":"这个论点建立在值得质疑的前提上。"},{"en":"We began with the premise that everyone needed equal access.","zh":"我们以人人都应有平等使用机会为前提开始工作。"}]},{"pos":"n.","meaning":"经营场所；房屋及地基（通常用premises）","definition":"The buildings and land used by an organisation.","examples":[{"en":"The company moved to larger premises.","zh":"公司搬到了更大的经营场所。"},{"en":"Smoking is not allowed anywhere on the premises.","zh":"场所内任何地方都不准吸烟。"}]}],"premium":[{"pos":"adj.","meaning":"优质的;高级的;高价的","definition":"of high quality and usually high price","examples":[{"en":"The hotel offers premium rooms.","zh":"酒店提供高档客房。"},{"en":"They use premium ingredients.","zh":"他们使用优质食材。"}]},{"pos":"n.","meaning":"保险费","definition":"money paid for insurance cover","examples":[{"en":"The annual insurance premium increased.","zh":"年度保费上涨了。"},{"en":"She pays her health insurance premium monthly.","zh":"她按月缴纳健康保险费。"}]},{"pos":"n.","meaning":"额外费用;溢价;津贴","definition":"an additional amount paid above a normal price","examples":[{"en":"Buyers paid a premium for river views.","zh":"买家为河景支付了溢价。"},{"en":"Night workers receive a wage premium.","zh":"夜班工人领取额外津贴。"}]},{"pos":"n.","meaning":"赠品;奖品","definition":"an extra item offered as an incentive","examples":[{"en":"Subscribers received a book as a premium.","zh":"订阅者获赠一本书。"},{"en":"The shop offered small premiums with large purchases.","zh":"商店为大额购物提供小赠品。"}]}],"preparation":[{"pos":"n.","meaning":"准备；筹备","definition":"the process of getting ready","examples":[{"en":"Careful preparation saved time later.","zh":"周密准备节省了后面的时间。"},{"en":"Wedding preparations occupied the family.","zh":"婚礼筹备让全家忙碌。"}]},{"pos":"n.","meaning":"制剂；配制品","definition":"a substance prepared for a particular use","examples":[{"en":"The laboratory tested the new preparation.","zh":"实验室测试了新制剂。"},{"en":"The shop sells herbal preparations.","zh":"店里出售草本配制品。"}]}],"prepare":[{"pos":"v.","meaning":"准备；预备；使做好准备","definition":"To make or become ready for something.","examples":[{"en":"She prepared the room for the guests.","zh":"她为客人准备好了房间。"},{"en":"The course prepares students for university study.","zh":"这门课程帮助学生为大学学习做好准备。"}]}],"prerequisite":[{"pos":"n.","meaning":"先决条件;必备条件","definition":"something required before another thing can happen","examples":[{"en":"Basic algebra is a prerequisite for this course.","zh":"基础代数是修这门课的先决条件。"},{"en":"Trust is a prerequisite for cooperation.","zh":"信任是合作的前提。"}]},{"pos":"adj.","meaning":"必备的;预先需要的","definition":"required beforehand","examples":[{"en":"Applicants must have the prerequisite qualifications.","zh":"申请人必须具备所需资格。"},{"en":"The training develops prerequisite skills.","zh":"培训培养必备技能。"}]}],"prescribe":[{"pos":"v.","meaning":"开处方；开药","definition":"to officially order a medical treatment","examples":[{"en":"The doctor prescribed a treatment.","zh":"医生开出了治疗方案。"},{"en":"The medication must be prescribed by a clinician.","zh":"药物必须由临床医师开具处方。"}]},{"pos":"v.","meaning":"规定；指示","definition":"to state officially what must be done","examples":[{"en":"The rules prescribe a clear procedure.","zh":"规则规定了明确程序。"},{"en":"The course prescribes several essential texts.","zh":"课程规定了几本必读书。"}]}],"prescription":[{"pos":"n.","meaning":"处方；药方","definition":"a doctor's written instruction for medicine","examples":[{"en":"This medicine is only available on prescription.","zh":"这种药只能凭处方购买。"},{"en":"Take the prescription to the pharmacy.","zh":"请把处方拿到药房。"},{"en":"The doctor gave me a prescription for antibiotics.","zh":"医生给我开了抗生素处方。"}]},{"pos":"n.","meaning":"开处方；处方行为","definition":"The act of ordering a medicine or medical treatment.","examples":[{"en":"The audit examined the prescription of antibiotics in local clinics.","zh":"这次审核调查了当地诊所开具抗生素处方的情况。"},{"en":"The hospital introduced checks on the prescription of strong painkillers.","zh":"医院开始对强效止痛药的处方行为进行检查。"}]}],"presence":[{"pos":"n.","meaning":"出席;在场;存在","definition":"the state of being present or existing","examples":[{"en":"Her presence reassured the children.","zh":"她在场让孩子安心。"},{"en":"The test confirmed the presence of lead.","zh":"测试确认存在铅。"}]},{"pos":"n.","meaning":"仪态;气场","definition":"a strong or impressive personal manner","examples":[{"en":"The actor has a commanding stage presence.","zh":"演员具有强大的舞台气场。"},{"en":"Her quiet presence filled the room with authority.","zh":"她沉静的仪态让房间充满威严。"}]}],"presentation":[{"pos":"n.","meaning":"报告；演示","definition":"a talk explaining information to an audience","examples":[{"en":"She gave a presentation on renewable energy.","zh":"她作了关于可再生能源的报告。"},{"en":"The presentation included several diagrams.","zh":"演示包含几张图。"}]},{"pos":"n.","meaning":"呈现方式；展示","definition":"the way something is shown or arranged","examples":[{"en":"The food's presentation was attractive.","zh":"食物的摆盘很吸引人。"},{"en":"Clear presentation makes the data easier to understand.","zh":"清晰的呈现让数据更易理解。"}]},{"pos":"n.","meaning":"颁发；赠送；授予","definition":"the formal giving of something","examples":[{"en":"The presentation of prizes followed the concert.","zh":"音乐会后举行颁奖。"},{"en":"The presentation of the medal moved her.","zh":"授予奖章的仪式令她感动。"}]},{"pos":"n.","meaning":"赠品；礼物（正式旧用）","definition":"an object formally given as a gift","examples":[{"en":"The silver cup was a presentation from former pupils.","zh":"银杯是往届学生赠送的礼物。"},{"en":"The inscription records the clock as a retirement presentation.","zh":"铭文记载这座钟是退休赠礼。"}]},{"pos":"n.","meaning":"引见；正式介绍","definition":"the formal introduction of a person","examples":[{"en":"The biography describes her presentation at court.","zh":"传记描述了她在宫廷的正式引见。"},{"en":"The ceremony included the presentation of the new ambassador.","zh":"仪式包括正式引见新大使。"}]},{"pos":"n.","meaning":"演出；上演","definition":"a performance shown to an audience","examples":[{"en":"The theatre staged a presentation of local legends.","zh":"剧院上演了地方传说。"},{"en":"Their final presentation combined dance and music.","zh":"他们最后的演出结合了舞蹈和音乐。"}]}],"preservation":[{"pos":"n.","meaning":"保护；保存；维护","definition":"keeping something safe from damage or loss","examples":[{"en":"The preservation of historic buildings requires careful planning.","zh":"保护历史建筑需要周密规划。"},{"en":"The charity raises money for the preservation of local wildlife habitats.","zh":"该慈善机构为保护当地野生动物栖息地筹款。"}]},{"pos":"n.","meaning":"保鲜；防腐","definition":"treatment that prevents food or other material from decaying","examples":[{"en":"Refrigeration is an important method of food preservation.","zh":"冷藏是食品保鲜的一种重要方法。"},{"en":"Salt was once widely used for the preservation of meat.","zh":"盐曾被广泛用于肉类防腐。"}]}],"preserve":[{"pos":"v.","meaning":"保护；保持；维持","definition":"To keep something safe or in its existing condition.","examples":[{"en":"The project aims to preserve the historic bridge.","zh":"项目旨在保护这座历史桥梁。"},{"en":"They worked hard to preserve their independence.","zh":"他们努力维护自己的独立。"}]},{"pos":"v.","meaning":"保存；保藏；腌制","definition":"To prevent decay, especially by treating food.","examples":[{"en":"Fruit can be preserved in syrup.","zh":"水果可以用糖浆保存。"},{"en":"The fishermen preserved their catch with salt.","zh":"渔民用盐腌制捕获的鱼以便保存。"}]}],"president":[{"pos":"n.","meaning":"总统","definition":"the elected head of certain countries","examples":[{"en":"The president addressed the nation.","zh":"总统向全国发表讲话。"},{"en":"Voters will elect a new president.","zh":"选民将选举新总统。"}]},{"pos":"n.","meaning":"会长;校长;主席;总裁","definition":"the head of an organization or institution","examples":[{"en":"The university president welcomed the graduates.","zh":"大学校长欢迎毕业生。"},{"en":"She was elected president of the association.","zh":"她当选为协会会长。"}]}],"pressure":[{"pos":"n.","meaning":"压力；压强","definition":"force acting on a surface","examples":[{"en":"The gauge measures air pressure.","zh":"仪表测量气压。"},{"en":"Apply gentle pressure to close the lid.","zh":"轻轻按压以合上盖子。"}]},{"pos":"n.","meaning":"精神压力；催逼；压迫","definition":"demands or influence pushing someone to act","examples":[{"en":"She works well under pressure.","zh":"她在压力下工作得很好。"},{"en":"Public pressure forced a review.","zh":"公众压力促使进行了审查。"}]},{"pos":"v.","meaning":"向……施压；迫使","definition":"to strongly persuade or force someone","examples":[{"en":"They pressured him to sign.","zh":"他们向他施压让他签字。"},{"en":"She refused to be pressured into a decision.","zh":"她拒绝在压力下作决定。"}]}],"presumably":[{"pos":"adv.","meaning":"大概；想必；据推测","definition":"Used to say what is likely based on available evidence.","examples":[{"en":"The lights are off, so they have presumably gone home.","zh":"灯关着，所以他们大概已经回家了。"},{"en":"Presumably, the missing page contains the conclusion.","zh":"缺失的那页想必包含结论。"}]}],"presuppose":[{"pos":"v.","meaning":"预先假定;以……为前提","definition":"to assume beforehand or require as a prior condition","examples":[{"en":"Your argument presupposes equal access to education.","zh":"你的论证以平等获得教育为前提。"},{"en":"Successful cooperation presupposes mutual trust.","zh":"成功合作需要相互信任作为前提。"}]}],"pretend":[{"pos":"v.","meaning":"假装；装作","definition":"to act as though something untrue is real","examples":[{"en":"The children pretended to be explorers.","zh":"孩子们假装是探险家。"},{"en":"He pretended not to hear.","zh":"他假装没听见。"}]}],"pretension":[{"pos":"n.","meaning":"自称；自命；标榜","definition":"A claim to a quality or status, often not justified.","examples":[{"en":"The café has no pretensions to luxury.","zh":"这家咖啡馆并不标榜奢华。"},{"en":"His pretensions to expertise were soon exposed.","zh":"他自称专业人士的虚假说法很快被揭穿。"}]},{"pos":"n.","meaning":"自负；矫饰；自命不凡","definition":"Behaviour intended to appear more important or cultured than one is.","examples":[{"en":"She spoke plainly and without pretension.","zh":"她说话直白，毫不做作。"},{"en":"The critic disliked the film's pretension.","zh":"评论家不喜欢这部电影的矫饰。"}]}],"pretentious":[{"pos":"adj.","meaning":"自命不凡的;做作的;炫耀的","definition":"trying to appear more important or cultured than one is","examples":[{"en":"The review criticised the film's pretentious dialogue.","zh":"评论批评电影对白做作。"},{"en":"He found the restaurant rather pretentious.","zh":"他觉得餐厅相当故作高雅。"}]}],"prevail":[{"pos":"v.","meaning":"盛行；普遍存在","definition":"to exist widely in a place or time","examples":[{"en":"A sense of optimism prevailed.","zh":"乐观情绪普遍存在。"},{"en":"These customs prevailed for centuries.","zh":"这些习俗盛行了几个世纪。"}]},{"pos":"v.","meaning":"获胜；占上风","definition":"to prove stronger or more successful","examples":[{"en":"Reason eventually prevailed.","zh":"理性最终占了上风。"},{"en":"The smaller team prevailed against the odds.","zh":"较小的队伍出乎意料地获胜。"}]}],"prevalence":[{"pos":"n.","meaning":"流行；普遍存在；盛行程度","definition":"How common something is within a population or area.","examples":[{"en":"The study measured the prevalence of asthma among children.","zh":"研究测量了儿童哮喘的患病率。"},{"en":"The survey revealed the prevalence of flexible working.","zh":"调查显示弹性工作制已相当普遍。"}]}],"prevalent":[{"pos":"adj.","meaning":"普遍的;盛行的","definition":"widespread at a particular time or place","examples":[{"en":"This custom remains prevalent in rural areas.","zh":"这一习俗在农村仍然普遍。"},{"en":"The belief was prevalent during that period.","zh":"这种信念在那一时期很盛行。"}]}],"prevent":[{"pos":"v.","meaning":"预防；阻止","definition":"to stop something from happening","examples":[{"en":"Regular handwashing can help prevent infection.","zh":"经常洗手有助于预防感染。"},{"en":"Better street lighting may prevent accidents.","zh":"改善街道照明可能防止事故。"},{"en":"The company installed alarms to prevent theft.","zh":"公司安装了警报器以防盗。"}]}],"preventative":[{"pos":"adj.","meaning":"预防性的；防止发生的","definition":"Intended to stop a problem from occurring.","examples":[{"en":"Regular inspections are a preventative measure.","zh":"定期检查是一项预防措施。"},{"en":"The workshop focuses on preventative maintenance.","zh":"研讨会重点介绍预防性维护。"}]}],"previous":[{"pos":"adj.","meaning":"先前的;以前的","definition":"existing or happening before the current one","examples":[{"en":"The previous owner planted these trees.","zh":"前主人种了这些树。"},{"en":"Refer to the previous chapter.","zh":"参阅前一章。"}]}],"prey":[{"pos":"n.","meaning":"猎物","definition":"an animal hunted for food","examples":[{"en":"The owl spotted its prey.","zh":"猫头鹰发现了猎物。"},{"en":"The predator carried its prey into the trees.","zh":"捕食者把猎物带进了树林。"}]},{"pos":"n.","meaning":"受害者；被掠夺的对象","definition":"a victim vulnerable to attack or exploitation","examples":[{"en":"Inexperienced buyers can become prey to fraud.","zh":"缺乏经验的买家可能成为诈骗受害者。"},{"en":"The isolated village was easy prey for raiders.","zh":"偏僻村庄很容易成为掠夺者的目标。"}]},{"pos":"v.","meaning":"捕食（常与 on 连用）","definition":"to hunt another animal for food","examples":[{"en":"These birds prey on small fish.","zh":"这些鸟捕食小鱼。"},{"en":"Foxes sometimes prey on rabbits.","zh":"狐狸有时捕食兔子。"}]},{"pos":"v.","meaning":"折磨；使烦恼（常与 on 连用）","definition":"to cause persistent mental distress","examples":[{"en":"The mistake preyed on her mind.","zh":"那个错误一直困扰着她。"},{"en":"His unanswered question continued to prey on him.","zh":"没有答案的问题持续折磨着他。"}]},{"pos":"v.","meaning":"剥削；掠夺（常与 on 连用）","definition":"to exploit someone vulnerable","examples":[{"en":"The scheme preyed on people's fears.","zh":"骗局利用了人们的恐惧。"},{"en":"Fraudsters prey on inexperienced customers.","zh":"骗子专挑缺乏经验的顾客下手。"}]}],"primarily":[{"pos":"adv.","meaning":"主要地；首要地","definition":"Mainly or above all.","examples":[{"en":"The organisation is primarily funded by donations.","zh":"这个组织主要靠捐款资助。"},{"en":"The book is intended primarily for beginners.","zh":"这本书主要面向初学者。"}]}],"primary":[{"pos":"adj.","meaning":"首要的;主要的;基本的","definition":"most important or fundamental","examples":[{"en":"Safety is our primary concern.","zh":"安全是首要考虑。"},{"en":"The study relies on primary sources.","zh":"研究依靠第一手资料。"}]},{"pos":"adj.","meaning":"初级的;最初的","definition":"belonging to an early or first stage","examples":[{"en":"She teaches at a primary school.","zh":"她在小学任教。"},{"en":"The primary stage involves collecting samples.","zh":"初始阶段包括采集样本。"}]}],"prime":[{"pos":"adj.","meaning":"首要的；主要的","definition":"most important","examples":[{"en":"Safety is our prime concern.","zh":"安全是我们首要关注的问题。"},{"en":"The site is a prime target for restoration.","zh":"该地点是首要修复对象。"}]},{"pos":"adj.","meaning":"最好的；最佳的","definition":"of the highest quality or suitability","examples":[{"en":"The shop occupies a prime location.","zh":"商店位于绝佳位置。"},{"en":"This is a prime example of good design.","zh":"这是优秀设计的典范。"}]}],"primitive":[{"pos":"adj.","meaning":"原始的；早期的","definition":"Belonging to an early stage of development.","examples":[{"en":"The museum displays primitive stone tools.","zh":"博物馆展出了早期石器。"},{"en":"The fossils reveal primitive forms of marine life.","zh":"这些化石揭示了早期海洋生物形态。"}]},{"pos":"adj.","meaning":"简陋的；粗糙的","definition":"Very basic and lacking modern improvements.","examples":[{"en":"The campsite had only primitive washing facilities.","zh":"营地只有简陋的洗漱设施。"},{"en":"They built a primitive shelter from branches.","zh":"他们用树枝搭了一个简陋庇护所。"}]},{"pos":"n.","meaning":"原始人；原始事物（旧式用法）","definition":"A person or thing described as belonging to an early or simple stage.","examples":[{"en":"The old textbook called the cave dwellers primitives.","zh":"这本旧教科书把穴居者称作原始人。"},{"en":"The display contrasted early primitives with later, more elaborate tools.","zh":"展览将早期原始器具与后来更精细的工具作了对比。"}]}],"principal":[{"pos":"adj.","meaning":"主要的;首要的","definition":"most important","examples":[{"en":"The principal reason was lack of funding.","zh":"主要原因是缺乏资金。"},{"en":"Rice is the region's principal crop.","zh":"水稻是该地区主要作物。"}]},{"pos":"n.","meaning":"校长","definition":"the head of a school or college","examples":[{"en":"The principal welcomed the new teachers.","zh":"校长欢迎新教师。"},{"en":"Parents met with the principal.","zh":"家长与校长会面。"}]},{"pos":"n.","meaning":"本金;资本","definition":"money invested or borrowed before interest","examples":[{"en":"The payment reduced the loan principal.","zh":"付款减少了贷款本金。"},{"en":"Interest is calculated on the remaining principal.","zh":"利息按剩余本金计算。"}]},{"pos":"n.","meaning":"主角;主要演员;主要人物","definition":"a leading performer or person in an activity","examples":[{"en":"The opera's principals received enthusiastic applause.","zh":"歌剧主角受到热烈掌声欢迎。"},{"en":"The principals in the negotiations met privately.","zh":"谈判中的主要人物私下会面。"}]}],"principle":[{"pos":"n.","meaning":"原则；准则；信条","definition":"a basic rule or belief guiding action","examples":[{"en":"She refused on principle.","zh":"她出于原则拒绝了。"},{"en":"Fairness is a central principle of the policy.","zh":"公平是政策的核心原则。"}]},{"pos":"n.","meaning":"原理；基本规律","definition":"a basic truth explaining how something works","examples":[{"en":"The lesson explains the principle of flotation.","zh":"课上解释了浮力原理。"},{"en":"The machine operates on a simple principle.","zh":"机器基于一个简单原理运行。"}]}],"prior":[{"pos":"adj.","meaning":"先前的；在前的；优先的","definition":"Existing or happening earlier.","examples":[{"en":"No prior experience is required.","zh":"不要求有先前经验。"},{"en":"She could not attend because of a prior commitment.","zh":"她因已有约定而无法参加。"}]}],"priority":[{"pos":"n.","meaning":"优先事项","definition":"something that needs attention before other things","examples":[{"en":"Improving public health should be a priority.","zh":"改善公共健康应是一项优先任务。"},{"en":"The council made road safety its top priority.","zh":"地方议会将道路安全列为首要任务。"},{"en":"Parents often give priority to their children's education.","zh":"父母往往优先考虑孩子的教育。"}]},{"pos":"n.","meaning":"优先权;优先地位","definition":"the right to be considered or served first","examples":[{"en":"Emergency vehicles have priority.","zh":"紧急车辆享有优先权。"},{"en":"The policy gives priority to children.","zh":"政策优先照顾儿童。"}]}],"privacy":[{"pos":"n.","meaning":"隐私；隐私权","definition":"freedom from unwanted attention or access to personal information","examples":[{"en":"Users should be able to protect their privacy.","zh":"用户应该能够保护自己的隐私。"},{"en":"Sharing personal details online can threaten privacy.","zh":"在线分享个人信息可能威胁隐私。"},{"en":"The policy explains how the service protects privacy.","zh":"该政策说明服务如何保护隐私。"}]}],"private":[{"pos":"adj.","meaning":"私人的；个人的；非公开的","definition":"Belonging to an individual or not meant to be shared publicly.","examples":[{"en":"Please keep my private documents secure.","zh":"请妥善保管我的私人文件。"},{"en":"They held a private meeting after the ceremony.","zh":"仪式后，他们举行了非公开会议。"}]},{"pos":"adj.","meaning":"私立的；私营的","definition":"Owned or run independently of the state.","examples":[{"en":"He attended a private school.","zh":"他曾就读于私立学校。"},{"en":"The hospital is managed by a private company.","zh":"这家医院由一家私营公司管理。"}]}],"privilege":[{"pos":"n.","meaning":"特权;优惠;荣幸","definition":"a special right or advantage","examples":[{"en":"Education should not be a privilege of the wealthy.","zh":"教育不应是富人的特权。"},{"en":"It was a privilege to work with her.","zh":"与她共事是一种荣幸。"}]},{"pos":"v.","meaning":"给予特权;优待","definition":"to give special advantage to someone or something","examples":[{"en":"The policy privileges larger companies.","zh":"政策优待大公司。"},{"en":"The curriculum should not privilege one culture over others.","zh":"课程不应把一种文化置于其他文化之上。"}]}],"probability":[{"pos":"n.","meaning":"可能性；概率","definition":"the likelihood that something will happen","examples":[{"en":"The probability of rain is high.","zh":"降雨的可能性很高。"},{"en":"The students calculated the probability of each outcome.","zh":"学生计算了每种结果的概率。"}]}],"probable":[{"pos":"adj.","meaning":"很可能的；大概会发生的","definition":"Likely to happen or be true.","examples":[{"en":"Rain is probable later in the day.","zh":"今天晚些时候很可能下雨。"},{"en":"The engineer identified the probable cause of the failure.","zh":"工程师找出了故障的可能原因。"}]}],"probation":[{"pos":"n.","meaning":"试用期","definition":"a trial period at the beginning of a job","examples":[{"en":"New employees are on probation for three months.","zh":"新员工有三个月试用期。"},{"en":"Your performance will be reviewed during probation.","zh":"试用期内会评估你的工作表现。"},{"en":"She completed her probation successfully.","zh":"她顺利通过了试用期。"}]},{"pos":"n.","meaning":"缓刑;监督考察期","definition":"a period of supervised freedom instead of imprisonment","examples":[{"en":"The judge placed him on probation.","zh":"法官判他缓刑。"},{"en":"She met her probation officer every week.","zh":"她每周会见缓刑监督官。"}]}],"probe":[{"pos":"v.","meaning":"调查；探究","definition":"to investigate closely","examples":[{"en":"The committee probed the causes of the delay.","zh":"委员会调查了延误原因。"},{"en":"The interview probed her reasons for leaving.","zh":"采访深入探询她离开的原因。"}]},{"pos":"v.","meaning":"用探针探查；探测","definition":"to examine using a tool or instrument","examples":[{"en":"The technician probed the gap with a thin rod.","zh":"技术员用细杆探查缝隙。"},{"en":"The sensor probes the soil beneath the surface.","zh":"传感器探测表层下的土壤。"}]},{"pos":"n.","meaning":"探针；探测器；探测飞船","definition":"an instrument or craft used for exploration","examples":[{"en":"The probe measured the water temperature.","zh":"探测器测量了水温。"},{"en":"A space probe sent back images.","zh":"太空探测器传回了图像。"}]},{"pos":"n.","meaning":"调查；探查","definition":"a detailed investigation","examples":[{"en":"The agency launched a probe into the accident.","zh":"机构发起了事故调查。"},{"en":"The financial probe uncovered missing records.","zh":"财务调查发现记录缺失。"}]}],"procedure":[{"pos":"n.","meaning":"程序；操作步骤","definition":"an established series of steps for doing something","examples":[{"en":"Follow the correct procedure when handling chemicals.","zh":"处理化学品时请遵循正确步骤。"},{"en":"The company has a clear procedure for reporting accidents.","zh":"公司有明确的事故报告程序。"},{"en":"Please explain the registration procedure to new members.","zh":"请向新会员解释注册流程。"}]}],"proceed":[{"pos":"v.","meaning":"继续;进行;前进","definition":"to continue an action or move forward","examples":[{"en":"Please proceed with the presentation.","zh":"请继续演示。"},{"en":"Passengers should proceed to gate twelve.","zh":"旅客请前往十二号登机口。"}]}],"process":[{"pos":"n.","meaning":"过程；程序；步骤","definition":"a series of actions leading to a result","examples":[{"en":"Learning is a gradual process.","zh":"学习是渐进的过程。"},{"en":"The application process takes two weeks.","zh":"申请程序需要两周。"}]},{"pos":"v.","meaning":"加工","definition":"to change raw materials into useful products","examples":[{"en":"The factory processes milk.","zh":"工厂加工牛奶。"},{"en":"The timber is processed locally.","zh":"木材在当地加工。"}]},{"pos":"v.","meaning":"处理；办理","definition":"to handle information or official work","examples":[{"en":"The computer processes the data.","zh":"电脑处理数据。"},{"en":"Your request is being processed.","zh":"你的申请正在办理中。"}]}],"procession":[{"pos":"n.","meaning":"队伍；行列；游行队列","definition":"A group moving together in an organised line.","examples":[{"en":"The procession moved slowly through the square.","zh":"队伍缓缓穿过广场。"},{"en":"Musicians led the wedding procession.","zh":"乐师走在婚礼队伍前面。"}]}],"processor":[{"pos":"n.","meaning":"处理器","definition":"a computer component that performs calculations","examples":[{"en":"The new processor runs faster.","zh":"新处理器运行更快。"},{"en":"A damaged processor stopped the computer.","zh":"处理器损坏使计算机停机。"}]},{"pos":"n.","meaning":"加工机;加工者;加工企业","definition":"a machine or person that processes materials","examples":[{"en":"Use a food processor to chop the nuts.","zh":"用食品加工机切碎坚果。"},{"en":"Local milk processors buy from nearby farms.","zh":"当地乳品加工企业从附近农场收奶。"}]}],"proclaim":[{"pos":"v.","meaning":"宣布；宣告","definition":"to state publicly and formally","examples":[{"en":"The mayor proclaimed a day of celebration.","zh":"市长宣布设立庆祝日。"},{"en":"The notice proclaimed the winners.","zh":"通知公布了获胜者。"}]},{"pos":"v.","meaning":"显示；清楚表明","definition":"to show something clearly","examples":[{"en":"The decorations proclaimed the family's love of music.","zh":"装饰清楚显示出这家人对音乐的热爱。"},{"en":"His confident manner proclaimed his experience.","zh":"他自信的举止表明他经验丰富。"}]}],"procrastinate":[{"pos":"v.","meaning":"拖延；耽搁","definition":"To delay doing something that needs to be done.","examples":[{"en":"He procrastinated until the application deadline had passed.","zh":"他拖延到申请截止日期都过了。"},{"en":"Starting with a small task helps me avoid procrastinating.","zh":"从小任务开始有助于我避免拖延。"}]}],"productive":[{"pos":"adj.","meaning":"多产的;生产性的;富有成效的","definition":"producing many goods or useful results","examples":[{"en":"The meeting was unusually productive.","zh":"会议格外富有成效。"},{"en":"Irrigation made the farmland more productive.","zh":"灌溉提高了农田产量。"}]}],"productivity":[{"pos":"n.","meaning":"生产率；工作效率","definition":"the amount produced in relation to the resources used","examples":[{"en":"Better equipment can increase productivity.","zh":"更好的设备可以提高生产率。"},{"en":"Long hours do not always lead to higher productivity.","zh":"长工时并不总能带来更高的工作效率。"},{"en":"Staff training contributed to a rise in productivity.","zh":"员工培训促成了生产率提升。"}]}],"profession":[{"pos":"n.","meaning":"职业；行业","definition":"A type of work requiring particular knowledge or training.","examples":[{"en":"Teaching is a demanding profession.","zh":"教学是一项要求很高的职业。"},{"en":"She entered the legal profession after graduation.","zh":"毕业后，她进入了法律行业。"}]},{"pos":"n.","meaning":"宣称；表白；公开表示","definition":"An open statement of a belief or feeling.","examples":[{"en":"His profession of innocence failed to convince the jury.","zh":"他自称无辜的表白未能说服陪审团。"},{"en":"Her actions contradicted her professions of friendship.","zh":"她的行动与她口头声称的友谊相矛盾。"}]}],"professional":[{"pos":"adj.","meaning":"职业的;专业的","definition":"relating to paid skilled work","examples":[{"en":"She became a professional musician.","zh":"她成为职业音乐家。"},{"en":"The report requires professional expertise.","zh":"报告需要专业知识。"}]},{"pos":"n.","meaning":"专业人员;职业选手","definition":"a person doing skilled work as a paid occupation","examples":[{"en":"Consult a qualified professional.","zh":"咨询合格专业人员。"},{"en":"The tournament welcomes amateurs and professionals.","zh":"锦标赛欢迎业余选手和职业选手。"}]}],"profile":[{"pos":"n.","meaning":"侧脸；侧面轮廓","definition":"the outline seen from the side","examples":[{"en":"The portrait shows her in profile.","zh":"肖像描绘了她的侧脸。"},{"en":"The mountain's profile stood against the sky.","zh":"山的轮廓映在天空上。"}]},{"pos":"n.","meaning":"人物简介；概况","definition":"a short description of a person or organisation","examples":[{"en":"The magazine published a profile of the scientist.","zh":"杂志刊登了这位科学家的简介。"},{"en":"The report includes a demographic profile.","zh":"报告包含人口特征概况。"}]},{"pos":"v.","meaning":"为……写简介；扼要介绍","definition":"to describe the main features of someone or something","examples":[{"en":"The article profiles three young artists.","zh":"文章介绍了三位年轻艺术家。"},{"en":"The programme profiled a coastal community.","zh":"节目介绍了一个沿海社区。"}]}],"profit":[{"pos":"n.","meaning":"利润；盈利","definition":"Money remaining after costs are paid.","examples":[{"en":"The shop made a small profit in its first year.","zh":"商店第一年赚了少量利润。"},{"en":"Rising costs reduced the firm's profits.","zh":"成本上升减少了公司的利润。"}]},{"pos":"n.","meaning":"益处；好处","definition":"An advantage or benefit.","examples":[{"en":"There is little profit in repeating the same argument.","zh":"重复同样的争论没什么益处。"},{"en":"Students can read the report with considerable profit.","zh":"学生阅读这份报告可以获益良多。"}]},{"pos":"v.","meaning":"获益；有利于","definition":"To gain or provide an advantage.","examples":[{"en":"Both communities profited from the new bridge.","zh":"两个社区都受益于新桥。"},{"en":"It would profit the team to review the errors carefully.","zh":"认真检查错误会让团队受益。"}]}],"profitable":[{"pos":"adj.","meaning":"有利润的;赚钱的","definition":"earning more money than it costs","examples":[{"en":"The shop became profitable in its second year.","zh":"商店第二年开始盈利。"},{"en":"The company abandoned an unprofitable route for a profitable one.","zh":"公司放弃亏损线路，选择了盈利线路。"}]},{"pos":"adj.","meaning":"有益的;有收获的","definition":"producing useful results","examples":[{"en":"We spent a profitable afternoon in the archive.","zh":"我们在档案馆度过收获颇丰的下午。"},{"en":"The comparison proved profitable for both researchers.","zh":"比较对两位研究者都有益。"}]}],"profound":[{"pos":"adj.","meaning":"深切的；深远的","definition":"very great or deep in effect or feeling","examples":[{"en":"The discovery had a profound impact.","zh":"发现产生了深远影响。"},{"en":"She felt profound gratitude.","zh":"她深怀感激。"}]},{"pos":"adj.","meaning":"见解深刻的；深奥的","definition":"showing deep understanding or requiring serious thought","examples":[{"en":"The book offers profound insights.","zh":"书中提供了深刻见解。"},{"en":"The question raises profound philosophical issues.","zh":"问题涉及深奥的哲学议题。"}]}],"prohibit":[{"pos":"v.","meaning":"禁止","definition":"to officially forbid something","examples":[{"en":"Local rules prohibit swimming in the reservoir.","zh":"当地规定禁止在水库游泳。"},{"en":"Many workplaces prohibit smoking indoors.","zh":"许多工作场所禁止室内吸烟。"},{"en":"The agreement does not prohibit employees from working remotely.","zh":"该协议不禁止员工远程办公。"}]}],"prohibitive":[{"pos":"adj.","meaning":"令人望而却步的;高得难以承受的","definition":"so high or difficult that it prevents action","examples":[{"en":"The repair cost was prohibitive.","zh":"维修费用高得难以承受。"},{"en":"Prohibitive fees prevented many students from enrolling.","zh":"过高费用阻止许多学生报名。"}]},{"pos":"adj.","meaning":"禁止的;限制的","definition":"intended to prevent or forbid","examples":[{"en":"The law imposed prohibitive restrictions on imports.","zh":"法律对进口施加禁止性限制。"},{"en":"Such prohibitive rules discouraged experimentation.","zh":"这类限制性规定抑制了试验。"}]}],"project":[{"pos":"n.","meaning":"项目；计划；课题；工程","definition":"a planned piece of work","examples":[{"en":"The project will restore the old bridge.","zh":"项目将修复旧桥。"},{"en":"Students completed a research project.","zh":"学生完成了一项研究课题。"}],"ipa":"/ˈprɒdʒekt/"},{"pos":"v.","meaning":"投射；放映","definition":"to send light or an image onto a surface","examples":[{"en":"The device projects images onto the wall.","zh":"装置把图像投到墙上。"},{"en":"They projected the film outdoors.","zh":"他们在户外放映电影。"}],"ipa":"/prəˈdʒekt/"},{"pos":"v.","meaning":"突出；伸出","definition":"to extend beyond a surface","examples":[{"en":"A balcony projects over the street.","zh":"阳台伸出到街道上方。"},{"en":"The rock projects from the cliff.","zh":"岩石从悬崖凸出。"}],"ipa":"/prəˈdʒekt/"},{"pos":"v.","meaning":"计划；规划；预计","definition":"to plan or estimate a future result","examples":[{"en":"The company projects a rise in sales.","zh":"公司预计销售会上升。"},{"en":"The new railway was projected years ago.","zh":"新铁路多年前就已规划。"}],"ipa":"/prəˈdʒekt/"}],"prolonged":[{"pos":"adj.","meaning":"持久的；长期的；延长的","definition":"Continuing for a long time.","examples":[{"en":"The area experienced a prolonged drought.","zh":"这个地区经历了长期干旱。"},{"en":"Prolonged negotiations finally produced an agreement.","zh":"漫长的谈判终于达成了协议。"}]}],"prominence":[{"pos":"n.","meaning":"突出;显著;重要;知名度","definition":"the state of being noticeable or important","examples":[{"en":"The issue gained prominence during the election.","zh":"这个问题在选举期间受到重视。"},{"en":"The exhibition brought the artist to prominence.","zh":"展览使艺术家声名鹊起。"}]}],"prominent":[{"pos":"adj.","meaning":"显著的；突出的","definition":"easily seen or noticed","examples":[{"en":"The building has a prominent tower.","zh":"建筑有一座显眼的塔。"},{"en":"Her name appears in a prominent position.","zh":"她的名字出现在显著位置。"}]},{"pos":"adj.","meaning":"著名的；重要的","definition":"well known and influential","examples":[{"en":"A prominent scientist opened the event.","zh":"一位著名科学家为活动开场。"},{"en":"She became prominent in local politics.","zh":"她在地方政界崭露头角。"}]}],"promise":[{"pos":"n.","meaning":"承诺；保证","definition":"A statement that one will do something.","examples":[{"en":"She kept her promise to return.","zh":"她履行了回来的承诺。"},{"en":"The proposal came with a promise of additional funding.","zh":"提案附带了提供额外资金的保证。"}]},{"pos":"v.","meaning":"承诺；答应；保证","definition":"To say firmly that one will do something.","examples":[{"en":"He promised to send the documents today.","zh":"他答应今天发送文件。"},{"en":"The company promised customers a refund.","zh":"公司承诺向顾客退款。"}]},{"pos":"n.","meaning":"前景；潜力；希望","definition":"Signs that something good may happen or develop.","examples":[{"en":"The young pianist shows great promise.","zh":"这位年轻钢琴家很有前途。"},{"en":"The project offers the promise of cleaner energy.","zh":"这个项目带来了更清洁能源的希望。"}]},{"pos":"v.","meaning":"预示；有望带来","definition":"To suggest that a particular result is likely.","examples":[{"en":"The clear sky promised a fine day.","zh":"晴朗的天空预示着好天气。"},{"en":"The new method promises to reduce waste.","zh":"新方法有望减少浪费。"}]}],"promising":[{"pos":"adj.","meaning":"有前途的;有希望的","definition":"showing signs of future success","examples":[{"en":"The trial produced promising results.","zh":"试验取得了有希望的结果。"},{"en":"She is a promising young architect.","zh":"她是一位有前途的年轻建筑师。"}]}],"promote":[{"pos":"v.","meaning":"促进；推动","definition":"to support growth or development","examples":[{"en":"The scheme promotes public transport.","zh":"方案促进公共交通发展。"},{"en":"The activity promotes cooperation.","zh":"活动促进合作。"}]},{"pos":"v.","meaning":"晋升；提升","definition":"to raise someone to a higher position","examples":[{"en":"She was promoted to manager.","zh":"她被提升为经理。"},{"en":"The team was promoted to the top division.","zh":"球队升入最高级别联赛。"}]},{"pos":"v.","meaning":"宣传；促销","definition":"to advertise or encourage sales","examples":[{"en":"The campaign promotes local food.","zh":"宣传活动推销本地食品。"},{"en":"The author toured to promote her book.","zh":"作者巡回宣传自己的书。"}]}],"promotion":[{"pos":"n.","meaning":"晋升；升级","definition":"Movement to a higher position or rank.","examples":[{"en":"Her promotion to manager surprised nobody.","zh":"她晋升经理没有让任何人意外。"},{"en":"The team celebrated its promotion to the top division.","zh":"球队庆祝晋级最高级别联赛。"}]},{"pos":"n.","meaning":"促进；推广；倡导","definition":"Action that supports the development of something.","examples":[{"en":"The charity works for the promotion of literacy.","zh":"慈善机构致力于推广识字教育。"},{"en":"Health promotion is part of the school's programme.","zh":"健康促进是学校课程的一部分。"}]},{"pos":"n.","meaning":"促销；宣传活动","definition":"Advertising or an offer intended to increase sales.","examples":[{"en":"The store launched a summer promotion.","zh":"商店推出了夏季促销活动。"},{"en":"The film's promotion included interviews with the cast.","zh":"电影宣传包括对演员的采访。"}]}],"pronounceable":[{"pos":"adj.","meaning":"可发音的;读得出的","definition":"able to be spoken or pronounced","examples":[{"en":"The company wanted a short, pronounceable name.","zh":"公司想要一个简短易读的名称。"},{"en":"The teacher divided the word into pronounceable syllables.","zh":"老师把词分成可以发音的音节。"}]}],"proof":[{"pos":"n.","meaning":"证据；证明","definition":"evidence showing that something is true","examples":[{"en":"The receipt is proof of purchase.","zh":"收据是购买凭证。"},{"en":"The claim needs further proof.","zh":"这一说法需要更多证据。"}]},{"pos":"n.","meaning":"校样；样张","definition":"a trial printed copy checked for errors","examples":[{"en":"The editor corrected the proofs.","zh":"编辑校正了校样。"},{"en":"She approved the final proof.","zh":"她批准了最终样张。"}]},{"pos":"adj.","meaning":"能防……的；耐……的","definition":"resistant to something harmful","examples":[{"en":"The casing is proof against moisture.","zh":"外壳能防潮。"},{"en":"No design is entirely proof against human error.","zh":"没有设计能完全防止人为错误。"}]}],"propagate":[{"pos":"v.","meaning":"繁殖；培育；增殖","definition":"To produce new plants or organisms.","examples":[{"en":"Gardeners propagate these plants from cuttings.","zh":"园丁通过扦插繁殖这些植物。"},{"en":"The bacteria propagated rapidly in the warm liquid.","zh":"细菌在温热液体中迅速繁殖。"}]},{"pos":"v.","meaning":"传播；宣传；使普及","definition":"To spread an idea, belief, or signal.","examples":[{"en":"The group used leaflets to propagate its ideas.","zh":"这个团体用传单传播其思想。"},{"en":"False stories can propagate rapidly online.","zh":"虚假消息可以在网上迅速传播。"}]}],"propel":[{"pos":"v.","meaning":"推动;驱使","definition":"to drive forward","examples":[{"en":"A small motor propels the boat.","zh":"小马达推动船前进。"},{"en":"Curiosity propelled her into research.","zh":"好奇心推动她投身研究。"}]}],"propellant":[{"pos":"n.","meaning":"推进剂；喷射剂","definition":"a substance providing thrust or pressure","examples":[{"en":"The rocket carries liquid propellant.","zh":"火箭携带液体推进剂。"},{"en":"The aerosol uses a gas as its propellant.","zh":"喷雾罐用一种气体作喷射剂。"}]}],"property":[{"pos":"n.","meaning":"财产；所有物","definition":"Things that someone owns.","examples":[{"en":"Keep personal property in the lockers.","zh":"把个人财物放在储物柜里。"},{"en":"The land became public property.","zh":"这片土地变成了公共财产。"}]},{"pos":"n.","meaning":"房产；地产","definition":"Land or buildings that are owned.","examples":[{"en":"They bought a small property near the coast.","zh":"他们在海边买了一处小房产。"},{"en":"Property prices rose after the station opened.","zh":"车站启用后，房价上涨了。"}]},{"pos":"n.","meaning":"性质；特性","definition":"A characteristic of a substance or thing.","examples":[{"en":"The material has useful insulating properties.","zh":"这种材料具有很好的绝缘特性。"},{"en":"Heating changes the physical properties of the substance.","zh":"加热改变了这种物质的物理性质。"}]}],"proportion":[{"pos":"n.","meaning":"比例；部分","definition":"the share of a whole represented by a part","examples":[{"en":"A large proportion of residents use public transport.","zh":"很大比例的居民使用公共交通。"},{"en":"The proportion of older people is increasing.","zh":"老年人口比例正在上升。"},{"en":"Only a small proportion of the budget goes to advertising.","zh":"只有一小部分预算用于广告。"}]},{"pos":"n.","meaning":"相称;比例关系","definition":"a balanced relationship between sizes or amounts","examples":[{"en":"The windows are in proportion to the building.","zh":"窗户与建筑大小相称。"},{"en":"The head is out of proportion to the body.","zh":"头部与身体比例失调。"}]}],"proposal":[{"pos":"n.","meaning":"提议；建议；方案","definition":"a suggested plan","examples":[{"en":"The committee approved the proposal.","zh":"委员会批准了方案。"},{"en":"She submitted a proposal for the exhibition.","zh":"她提交了展览提案。"}]},{"pos":"n.","meaning":"求婚","definition":"an offer of marriage","examples":[{"en":"She accepted his marriage proposal.","zh":"她接受了他的求婚。"},{"en":"The novel ends with a proposal.","zh":"小说以一场求婚结束。"}]}],"propose":[{"pos":"v.","meaning":"提议；建议","definition":"To put forward an idea for consideration.","examples":[{"en":"She proposed a different route.","zh":"她建议走另一条路线。"},{"en":"The report proposes changes to the timetable.","zh":"报告建议修改时间表。"}]},{"pos":"v.","meaning":"提名；推荐","definition":"To suggest someone for a position or honour.","examples":[{"en":"I propose Maya as chair of the committee.","zh":"我提名玛雅担任委员会主席。"},{"en":"Two colleagues proposed him for membership.","zh":"两位同事推荐他入会。"}]},{"pos":"v.","meaning":"打算；计划","definition":"To intend to do something.","examples":[{"en":"How do you propose to pay for the repairs?","zh":"你打算怎样支付维修费用？"},{"en":"We propose to begin the survey in June.","zh":"我们计划六月开始调查。"}]},{"pos":"v.","meaning":"求婚","definition":"To ask someone to marry.","examples":[{"en":"He proposed to her during a walk by the lake.","zh":"他在湖边散步时向她求婚。"},{"en":"She was surprised when her partner proposed.","zh":"伴侣求婚时，她很惊讶。"}]}],"prospective":[{"pos":"adj.","meaning":"未来的;预期的;可能的","definition":"expected or likely to be something in the future","examples":[{"en":"Prospective students toured the campus.","zh":"有意入学的学生参观了校园。"},{"en":"The agent met several prospective buyers.","zh":"中介会见了几位潜在买家。"}]}],"prospectus":[{"pos":"n.","meaning":"招生简章；介绍书；说明书","definition":"a document describing an organisation or planned venture","examples":[{"en":"The college prospectus lists available courses.","zh":"学院招生简章列出了可选课程。"},{"en":"Read the prospectus before choosing a programme.","zh":"选择课程项目前阅读介绍书。"}]}],"prosper":[{"pos":"v.","meaning":"繁荣；兴旺；成功","definition":"To develop successfully and do well.","examples":[{"en":"The town prospered after the railway arrived.","zh":"铁路通车后，小镇繁荣起来。"},{"en":"Small businesses can prosper with reliable local support.","zh":"小企业得到可靠的本地支持就能兴旺发展。"}]}],"prosperity":[{"pos":"n.","meaning":"繁荣；富足","definition":"a condition of wealth and success","examples":[{"en":"Good education contributes to long-term prosperity.","zh":"良好的教育有助于长期繁荣。"},{"en":"Economic prosperity should benefit the whole community.","zh":"经济繁荣应惠及整个社区。"},{"en":"The port brought prosperity to the town.","zh":"港口给这个城镇带来了繁荣。"}]}],"prosperous":[{"pos":"adj.","meaning":"繁荣的；兴旺的；富裕的","definition":"successful and financially secure","examples":[{"en":"The port became prosperous through trade.","zh":"港口通过贸易繁荣起来。"},{"en":"They lived in a prosperous farming region.","zh":"他们住在富裕的农业地区。"}]}],"prototype":[{"pos":"n.","meaning":"原型；样机；蓝本","definition":"An early model used to test or develop a design.","examples":[{"en":"The engineers built a working prototype.","zh":"工程师造出了一台可运行的样机。"},{"en":"Feedback from the prototype shaped the final product.","zh":"对原型的反馈影响了最终产品。"}]}],"protrude":[{"pos":"v.","meaning":"突出;伸出","definition":"to extend beyond a surface","examples":[{"en":"A nail protruded from the board.","zh":"一根钉子从木板上突出来。"},{"en":"The balcony protrudes over the pavement.","zh":"阳台伸出在人行道上方。"}]}],"provenance":[{"pos":"n.","meaning":"出处；来源；来历","definition":"the origin or ownership history of an object","examples":[{"en":"The painting's provenance was uncertain.","zh":"画作的来历不确定。"},{"en":"The museum documented the object's provenance.","zh":"博物馆记录了物品的来源。"}]}],"provided":[{"pos":"conj.","meaning":"只要；倘若；假如","definition":"On the condition that something is true or happens.","examples":[{"en":"You may borrow the camera provided you return it tomorrow.","zh":"只要明天归还，你可以借这台相机。"},{"en":"The event will go ahead provided the weather stays dry.","zh":"只要天气不下雨，活动就会照常进行。"}]}],"provision":[{"pos":"n.","meaning":"供应;提供;准备","definition":"the act of supplying or preparing for a need","examples":[{"en":"The plan improves the provision of clean water.","zh":"计划改善清洁水供应。"},{"en":"Make provision for unexpected expenses.","zh":"为意外开支做好准备。"}]},{"pos":"n.","meaning":"给养;口粮;供应品","definition":"supplies, especially food for a journey","examples":[{"en":"They loaded provisions onto the ship.","zh":"他们把给养装上船。"},{"en":"Our provisions lasted a week.","zh":"我们的口粮维持了一周。"}]},{"pos":"n.","meaning":"条款;规定","definition":"a requirement in a legal document","examples":[{"en":"The contract contains a confidentiality provision.","zh":"合同有一项保密条款。"},{"en":"A new provision protects temporary workers.","zh":"新规定保护临时工。"}]}],"prowess":[{"pos":"n.","meaning":"高超技艺；杰出能力","definition":"exceptional skill or ability","examples":[{"en":"Her musical prowess impressed the judges.","zh":"她的音乐才华打动了评委。"},{"en":"The display demonstrated engineering prowess.","zh":"展示证明了高超的工程能力。"}]}],"proximity":[{"pos":"n.","meaning":"接近；邻近；亲近","definition":"Nearness in space, time, or relationship.","examples":[{"en":"The hotel's proximity to the station is convenient.","zh":"酒店离车站近，很方便。"},{"en":"The houses were built in close proximity to each other.","zh":"这些房屋建得彼此很近。"}]}],"psychiatric":[{"pos":"adj.","meaning":"精神病学的;精神科的","definition":"relating to the study or treatment of mental illness","examples":[{"en":"The hospital opened a psychiatric unit.","zh":"医院开设了精神科。"},{"en":"The study reviewed psychiatric services in rural areas.","zh":"研究审查了农村地区精神科服务。"}]}],"publicity":[{"pos":"n.","meaning":"宣传；公众关注","definition":"attention given by the public or media","examples":[{"en":"The exhibition received widespread publicity.","zh":"展览受到广泛宣传。"},{"en":"The company sought publicity for its new service.","zh":"公司为新服务寻求宣传。"}]}],"pudding":[{"pos":"n.","meaning":"布丁；甜食","definition":"A sweet cooked dish, or a dessert in British usage.","examples":[{"en":"She served a warm rice pudding.","zh":"她端上了一份热米布丁。"},{"en":"We had chocolate pudding after dinner.","zh":"晚饭后我们吃了巧克力布丁。"}]}],"pull up stakes":[{"pos":"v. phr.","meaning":"搬家;离开定居地","definition":"to leave a place and move elsewhere","examples":[{"en":"They pulled up stakes and moved to the coast.","zh":"他们搬家去了海边。"},{"en":"After the factory closed, many families pulled up stakes.","zh":"工厂关闭后，许多家庭搬离了。"}]}],"pulley":[{"pos":"n.","meaning":"滑轮；滑车","definition":"a wheel guiding a rope to lift or move loads","examples":[{"en":"The pulley helped lift the heavy crate.","zh":"滑轮帮助吊起沉重箱子。"},{"en":"A rope runs over the pulley.","zh":"绳子绕过滑轮。"}]}],"pulverise":[{"pos":"v.","meaning":"粉碎；碾成粉末","definition":"To crush something into very small pieces or powder.","examples":[{"en":"The mill pulverises the grain into flour.","zh":"磨坊把谷物磨成面粉。"},{"en":"The impact pulverised the brittle rock.","zh":"撞击把脆弱的岩石粉碎了。"}]}],"pumice":[{"pos":"n.","meaning":"浮石;浮岩","definition":"a light porous volcanic rock","examples":[{"en":"Pumice can float on water.","zh":"浮石能浮在水面上。"},{"en":"The beach was scattered with pumice.","zh":"海滩上散布着浮石。"}]},{"pos":"v.","meaning":"用浮石磨","definition":"to rub or polish with pumice","examples":[{"en":"The craft worker pumiced the rough surface.","zh":"工匠用浮石打磨粗糙表面。"},{"en":"She gently pumiced the hardened patch.","zh":"她用浮石轻轻磨了那块硬化部位。"}]}],"pump":[{"pos":"v.","meaning":"用泵抽送","definition":"to move liquid or gas with a pump","examples":[{"en":"They pumped water from the basement.","zh":"他们用泵把地下室的水抽走。"},{"en":"Air is pumped into the tyres.","zh":"空气被泵入轮胎。"}]},{"pos":"v.","meaning":"涌出；奔流","definition":"to flow strongly and repeatedly","examples":[{"en":"Water pumped from the damaged pipe.","zh":"水从破损管道中涌出。"},{"en":"Blood pumps through the body's vessels.","zh":"血液在身体血管中流动。"}]},{"pos":"n.","meaning":"泵；抽水机","definition":"a machine moving liquids or gases","examples":[{"en":"The pump stopped working.","zh":"泵停止运转了。"},{"en":"The farmer installed an irrigation pump.","zh":"农民安装了灌溉泵。"}]}],"punch":[{"pos":"v.","meaning":"猛击；用拳击打","definition":"To hit forcefully with a closed hand.","examples":[{"en":"He punched the training bag.","zh":"他用拳猛击训练沙袋。"},{"en":"The boxer punched his opponent in the shoulder.","zh":"拳击手击中了对手的肩膀。"}]},{"pos":"v.","meaning":"打孔；冲孔","definition":"To make a hole with a tool.","examples":[{"en":"Punch two holes along the edge of the paper.","zh":"沿纸张边缘打两个孔。"},{"en":"The machine punches holes in thin metal sheets.","zh":"机器在薄金属板上冲孔。"}]},{"pos":"n.","meaning":"拳击；猛击","definition":"A forceful blow with a closed hand.","examples":[{"en":"She avoided the punch by stepping back.","zh":"她后退一步躲开了那一拳。"},{"en":"The boxer landed a powerful punch.","zh":"拳击手打出了一记有力的重拳。"}]},{"pos":"n.","meaning":"打孔器；冲床；冲头","definition":"A tool or machine used to make holes.","examples":[{"en":"Use a paper punch to prepare the pages for the binder.","zh":"用打孔器在纸上打孔，以便装进活页夹。"},{"en":"The metal punch needed a replacement cutting part.","zh":"金属冲床需要更换切割部件。"}]},{"pos":"n.","meaning":"力量；感染力；效果","definition":"Strong impact or effectiveness.","examples":[{"en":"The speech had real punch.","zh":"这场演讲很有感染力。"},{"en":"A little lemon juice adds punch to the sauce.","zh":"加一点柠檬汁能让酱汁味道更鲜明。"}]}],"punctual":[{"pos":"adj.","meaning":"准时的;守时的","definition":"arriving or happening at the arranged time","examples":[{"en":"Please be punctual for the interview.","zh":"面试请守时。"},{"en":"The service is usually punctual.","zh":"这项服务通常很准时。"}]}],"purchase":[{"pos":"v.","meaning":"购买","definition":"to buy something","examples":[{"en":"You can purchase tickets at the entrance.","zh":"你可以在入口购票。"},{"en":"We plan to purchase new equipment for the office.","zh":"我们计划为办公室购买新设备。"},{"en":"Customers must be eighteen to purchase this product.","zh":"顾客必须年满十八岁才能购买这种产品。"}]},{"pos":"n.","meaning":"购买的物品","definition":"something bought","examples":[{"en":"She carried her purchases home.","zh":"她把买的东西带回家。"},{"en":"The jacket was my only purchase that day.","zh":"那件夹克是我那天唯一买的东西。"}]},{"pos":"n.","meaning":"购买；购买行为","definition":"the act of buying something","examples":[{"en":"Keep the receipt after your purchase.","zh":"购买后保留收据。"},{"en":"The purchase of the equipment required board approval.","zh":"购买设备需要董事会批准。"}]}],"purify":[{"pos":"v.","meaning":"净化；提纯；使洁净","definition":"To remove unwanted or harmful substances.","examples":[{"en":"The filter purifies drinking water.","zh":"过滤器净化饮用水。"},{"en":"The metal was purified before use.","zh":"金属在使用前进行了提纯。"}]}],"purpose":[{"pos":"n.","meaning":"目的;意图;用途","definition":"the reason something is done or used","examples":[{"en":"The purpose of the survey is to improve services.","zh":"调查目的是改善服务。"},{"en":"This room serves several purposes.","zh":"这个房间有多种用途。"}]},{"pos":"v.","meaning":"打算;决心（正式用语）","definition":"to intend or resolve to do something","examples":[{"en":"She purposed to finish before winter.","zh":"她决心在冬天之前完成。"},{"en":"They purposed to establish a school.","zh":"他们打算建立一所学校。"}]}],"pursuit":[{"pos":"n.","meaning":"追求；寻求","definition":"the act of trying to achieve something","examples":[{"en":"She travelled in pursuit of new opportunities.","zh":"她为寻找新机会而旅行。"},{"en":"The pursuit of knowledge motivated him.","zh":"追求知识激励着他。"}]},{"pos":"n.","meaning":"爱好；消遣；从事的活动","definition":"an activity occupying time and effort","examples":[{"en":"Gardening is his favourite pursuit.","zh":"园艺是他最喜欢的消遣。"},{"en":"The course encourages creative pursuits.","zh":"课程鼓励创造性活动。"}]}],"qualification":[{"pos":"n.","meaning":"资格；学历","definition":"a skill or official achievement needed for a job","examples":[{"en":"A teaching qualification is required for this role.","zh":"这个职位要求具备教师资格。"},{"en":"She gained a qualification in accounting.","zh":"她取得了会计资格。"},{"en":"The course leads to a recognised professional qualification.","zh":"完成该课程可获得受认可的专业资格。"}]},{"pos":"n.","meaning":"能力条件；技能资历","definition":"A quality or skill making someone suitable for a role.","examples":[{"en":"Patience is an important qualification for this work.","zh":"耐心是这项工作的重要条件。"},{"en":"Her practical experience was her strongest qualification.","zh":"她的实践经验是她最有力的资历。"}]},{"pos":"n.","meaning":"限制条件；保留；限定","definition":"A condition or limitation attached to a statement or agreement.","examples":[{"en":"He accepted the proposal with one qualification.","zh":"他接受了提案，但附带一个条件。"},{"en":"The claim is true only with several important qualifications.","zh":"这一说法只有加上几项重要限定才成立。"}]}],"qualitative":[{"pos":"adj.","meaning":"定性的;性质方面的","definition":"relating to qualities rather than numerical amounts","examples":[{"en":"The study used qualitative interviews.","zh":"研究采用了定性访谈。"},{"en":"There is a qualitative difference between the two approaches.","zh":"这两种方法存在性质上的差别。"}]}],"quantity":[{"pos":"n.","meaning":"数量；量","definition":"an amount of something","examples":[{"en":"Measure the quantity of water carefully.","zh":"仔细测量水量。"},{"en":"The shop buys paper in large quantities.","zh":"商店大量采购纸张。"}]}],"quartz":[{"pos":"n.","meaning":"石英","definition":"A hard mineral consisting of silica.","examples":[{"en":"The rock contains veins of white quartz.","zh":"岩石中有白色石英脉。"},{"en":"A quartz crystal regulates the watch's movement.","zh":"石英晶体调节手表机芯的运行。"}]}],"questionnaire":[{"pos":"n.","meaning":"问卷;调查表","definition":"a set of written questions for gathering information","examples":[{"en":"Please complete the questionnaire anonymously.","zh":"请匿名填写问卷。"},{"en":"The questionnaire asked about travel habits.","zh":"问卷询问出行习惯。"}]}],"quiver":[{"pos":"v.","meaning":"颤抖；抖动","definition":"to shake with small rapid movements","examples":[{"en":"Her voice quivered with excitement.","zh":"她的声音因激动而颤抖。"},{"en":"The leaves quivered in the breeze.","zh":"叶子在微风中颤动。"}]}],"quota":[{"pos":"n.","meaning":"配额；限额；定额","definition":"A fixed amount that is allowed or required.","examples":[{"en":"Each boat has an annual fishing quota.","zh":"每艘船都有年度捕捞配额。"},{"en":"The factory met its production quota.","zh":"工厂完成了生产定额。"}]}],"quote":[{"pos":"v.","meaning":"引用;引述","definition":"to repeat someone's exact words","examples":[{"en":"She quoted a line from the poem.","zh":"她引用了诗中的一句。"},{"en":"The article quotes several local residents.","zh":"文章引用了几位当地居民的话。"}]},{"pos":"v.","meaning":"报价","definition":"to state a price for goods or services","examples":[{"en":"The builder quoted a price for repairs.","zh":"建筑工人报了维修价格。"},{"en":"They quoted us two hundred pounds.","zh":"他们向我们报价两百英镑。"}]},{"pos":"v.","meaning":"举出;提供作为例证","definition":"to mention as evidence or an example","examples":[{"en":"The report quotes figures from last year's survey.","zh":"报告援用了去年调查的数据。"},{"en":"He quoted the regulation in support of his argument.","zh":"他援引规定支持自己的论点。"}]},{"pos":"n.","meaning":"引文;引语","definition":"words repeated from another source","examples":[{"en":"The chapter opens with a quote from a diary.","zh":"章节以日记中的引文开头。"},{"en":"Check the quote against the original.","zh":"对照原文核对引语。"}]},{"pos":"n.","meaning":"报价;估价","definition":"a statement of the price to be charged","examples":[{"en":"We requested three quotes for the work.","zh":"我们为这项工程索取了三份报价。"},{"en":"The quote includes labour and materials.","zh":"报价包含人工和材料。"}]},{"pos":"n.","meaning":"引号（常用复数）","definition":"a quotation mark","examples":[{"en":"Put the title inside quotes.","zh":"把标题放在引号内。"},{"en":"A missing quote caused the code to fail.","zh":"漏掉一个引号导致代码出错。"}]}],"racket":[{"pos":"n.","meaning":"球拍","definition":"a framed implement used to hit a ball or shuttlecock","examples":[{"en":"She replaced the strings on her tennis racket.","zh":"她更换了网球拍的拍线。"},{"en":"He borrowed a badminton racket.","zh":"他借了一支羽毛球拍。"}]}],"radiate":[{"pos":"v.","meaning":"辐射；散发；发光发热","definition":"To send out heat, light, energy, or a quality from a centre.","examples":[{"en":"The stove radiated heat into the room.","zh":"炉子向房间散发热量。"},{"en":"Her face radiated happiness.","zh":"她的脸上洋溢着幸福。"}]}],"radius":[{"pos":"n.","meaning":"半径","definition":"the distance from a circle's centre to its edge","examples":[{"en":"The circle has a radius of five centimetres.","zh":"圆的半径为五厘米。"},{"en":"Double the radius to find the diameter.","zh":"将半径乘二得到直径。"}]},{"pos":"n.","meaning":"周边范围;半径范围","definition":"an area within a specified distance","examples":[{"en":"We searched within a ten-kilometre radius.","zh":"我们在十公里半径范围内搜寻。"},{"en":"Several schools lie within a small radius of the station.","zh":"车站附近小范围内有几所学校。"}]}],"rampant":[{"pos":"adj.","meaning":"猖獗的；肆虐的","definition":"spreading widely in an uncontrolled harmful way","examples":[{"en":"Corruption was rampant in the organisation.","zh":"组织内腐败猖獗。"},{"en":"The report warned of rampant misinformation.","zh":"报告警告错误信息泛滥。"}]},{"pos":"adj.","meaning":"蔓生的；疯长的","definition":"growing quickly and uncontrollably","examples":[{"en":"Rampant weeds covered the path.","zh":"疯长的杂草覆盖了小路。"},{"en":"The gardener cut back the rampant ivy.","zh":"园丁修剪了蔓生的常春藤。"}]}],"random":[{"pos":"adj.","meaning":"随机的；随意的；无规则的","definition":"Chosen or happening without a fixed plan or pattern.","examples":[{"en":"The computer selected a random sample.","zh":"电脑随机选取了一个样本。"},{"en":"We heard random bursts of applause.","zh":"我们听到零星的阵阵掌声。"}]},{"pos":"n.","meaning":"随机；随意（用于at random）","definition":"Chance or lack of a plan, now chiefly in the phrase at random.","examples":[{"en":"Names were drawn at random from a box.","zh":"名字从盒子里随机抽出。"},{"en":"She opened the book at random.","zh":"她随手翻开了书。"}]}],"range":[{"pos":"n.","meaning":"范围;领域;幅度","definition":"the limits or extent of something","examples":[{"en":"The course covers a wide range of topics.","zh":"课程涵盖广泛主题。"},{"en":"Temperatures stayed within the normal range.","zh":"温度保持在正常范围内。"}]},{"pos":"n.","meaning":"系列;一组产品","definition":"a set of related things","examples":[{"en":"The shop introduced a new range of shoes.","zh":"商店推出新鞋系列。"},{"en":"They offer a range of vegetarian dishes.","zh":"他们提供一系列素食菜肴。"}]},{"pos":"n.","meaning":"山脉","definition":"a line or group of mountains","examples":[{"en":"A mountain range divides the region.","zh":"一条山脉将该地区分开。"},{"en":"Snow covered the entire range.","zh":"雪覆盖了整条山脉。"}]},{"pos":"n.","meaning":"射程;可达距离","definition":"the distance over which something can reach","examples":[{"en":"The target was beyond the cannon's range.","zh":"目标超出了大炮射程。"},{"en":"The radio has a range of five kilometres.","zh":"对讲机通信距离为五公里。"}]},{"pos":"v.","meaning":"在一定范围内变化","definition":"to vary between limits","examples":[{"en":"Prices range from ten to fifty pounds.","zh":"价格从十到五十英镑不等。"},{"en":"The animals range in size from tiny to enormous.","zh":"这些动物的体型从微小到巨大不等。"}]},{"pos":"v.","meaning":"排列;使排成行","definition":"to arrange in a row or group","examples":[{"en":"Chairs were ranged along the wall.","zh":"椅子沿墙排列。"},{"en":"She ranged the bottles by size.","zh":"她按大小排列瓶子。"}]}],"rank":[{"pos":"v.","meaning":"排列；分等；排名","definition":"to place in an order of quality or importance","examples":[{"en":"Rank the options by cost.","zh":"按成本给选项排序。"},{"en":"The university ranks highly for research.","zh":"该大学在研究方面排名靠前。"}]},{"pos":"n.","meaning":"等级；级别；军衔","definition":"a position in a hierarchy","examples":[{"en":"She rose to the rank of captain.","zh":"她晋升为上尉。"},{"en":"The award recognises work of the highest rank.","zh":"奖项表彰最高水平的作品。"}]}],"rarity":[{"pos":"n.","meaning":"稀有；罕见","definition":"The quality of being uncommon.","examples":[{"en":"The coin's rarity makes it valuable.","zh":"这枚硬币因稀有而珍贵。"},{"en":"The rarity of snow here makes every snowfall memorable.","zh":"这里很少下雪，所以每次降雪都令人难忘。"}]},{"pos":"n.","meaning":"稀罕物；罕见之事","definition":"Something unusual or seldom found.","examples":[{"en":"The library owns several botanical rarities.","zh":"图书馆收藏了几部珍稀植物学著作。"},{"en":"A quiet morning was a rarity in their busy home.","zh":"在他们忙碌的家里，一个安静的早晨很少见。"}]}],"ratio":[{"pos":"n.","meaning":"比;比率","definition":"the quantitative relationship between two amounts","examples":[{"en":"The ratio of teachers to students is one to twenty.","zh":"师生比是一比二十。"},{"en":"Mix the liquids in a two-to-one ratio.","zh":"按二比一混合液体。"}]}],"ration":[{"pos":"n.","meaning":"配给量；口粮","definition":"a fixed amount of food or supplies allowed to someone","examples":[{"en":"Each family received a weekly ration.","zh":"每个家庭领到每周配给。"},{"en":"The hikers carried emergency rations.","zh":"徒步者携带了应急口粮。"}]},{"pos":"v.","meaning":"定量供应；配给","definition":"to limit supplies to fixed amounts","examples":[{"en":"The town rationed water during the drought.","zh":"干旱期间小镇定量供应水。"},{"en":"Fuel was carefully rationed.","zh":"燃料受到严格配给。"}]}],"raw material":[{"pos":"n.","meaning":"原材料","definition":"A basic substance used to manufacture something.","examples":[{"en":"Wood is the main raw material for this factory.","zh":"木材是这家工厂的主要原材料。"},{"en":"The company stores its raw materials near the workshop.","zh":"公司把原材料存放在车间附近。"}]}],"realistic":[{"pos":"adj.","meaning":"现实的;切合实际的","definition":"based on practical understanding","examples":[{"en":"Set a realistic deadline.","zh":"设定切合实际的截止日期。"},{"en":"We need a realistic estimate of the cost.","zh":"我们需要实际可信的成本估计。"}]},{"pos":"adj.","meaning":"逼真的;写实的","definition":"representing life accurately","examples":[{"en":"The model contains realistic details.","zh":"模型包含逼真细节。"},{"en":"She paints realistic portraits.","zh":"她画写实肖像。"}]}],"realm":[{"pos":"n.","meaning":"领域；范围","definition":"an area of knowledge or activity","examples":[{"en":"The question belongs to the realm of philosophy.","zh":"这个问题属于哲学领域。"},{"en":"The discovery opened a new realm of research.","zh":"发现开辟了新的研究领域。"}]},{"pos":"n.","meaning":"王国；国度","definition":"a kingdom or domain","examples":[{"en":"The king travelled throughout his realm.","zh":"国王巡视整个王国。"},{"en":"The map shows the boundaries of the ancient realm.","zh":"地图显示古代王国的边界。"}]}],"rear":[{"pos":"adj.","meaning":"后面的；后部的","definition":"At or towards the back.","examples":[{"en":"Use the rear entrance after six.","zh":"六点以后请走后门。"},{"en":"The car's rear window was covered in frost.","zh":"汽车后窗覆盖了一层霜。"}]},{"pos":"n.","meaning":"后部；后方；尾部","definition":"The back part or position of something.","examples":[{"en":"The luggage is stored at the rear of the bus.","zh":"行李存放在公交车后部。"},{"en":"A small garden lies to the rear of the house.","zh":"房子后面有一个小花园。"}]},{"pos":"v.","meaning":"抚养；饲养；培育","definition":"To care for children, animals, or plants as they grow.","examples":[{"en":"She reared three children on her own.","zh":"她独自抚养了三个孩子。"},{"en":"The nursery rears young trees for replanting.","zh":"苗圃培育幼树以供移栽。"}]}],"reasonable":[{"pos":"adj.","meaning":"合理的;有道理的;通情达理的","definition":"fair and based on good judgement","examples":[{"en":"Your request seems reasonable.","zh":"你的请求似乎合理。"},{"en":"The manager was reasonable about the delay.","zh":"经理对延误通情达理。"}]},{"pos":"adj.","meaning":"适度的;价格公道的;尚可的","definition":"not excessive or fairly satisfactory","examples":[{"en":"The hotel charges reasonable rates.","zh":"酒店收费公道。"},{"en":"The car is in reasonable condition.","zh":"汽车状况尚可。"}]}],"recalcitrant":[{"pos":"adj.","meaning":"顽抗的；不服管束的","definition":"stubbornly refusing to obey","examples":[{"en":"The teacher dealt patiently with a recalcitrant pupil.","zh":"老师耐心地应对一名不服管束的学生。"},{"en":"Recalcitrant members refused the compromise.","zh":"顽固的成员拒绝了妥协方案。"}]}],"recapture":[{"pos":"v.","meaning":"重获；收复；再现","definition":"To gain control again or experience something again.","examples":[{"en":"The army recaptured the bridge.","zh":"军队收复了桥梁。"},{"en":"The film recaptures the excitement of the original adventure.","zh":"电影重现了最初冒险的刺激感。"}]}],"receipt":[{"pos":"n.","meaning":"收据","definition":"a document showing that something has been paid for","examples":[{"en":"Keep your receipt in case you need to return the item.","zh":"请保留收据，以备退货时使用。"},{"en":"The cashier put the receipt in my bag.","zh":"收银员把收据放进了我的袋子。"},{"en":"A printed receipt is available on request.","zh":"如有需要，可提供纸质收据。"}]},{"pos":"n.","meaning":"收到;接收","definition":"the act of receiving","examples":[{"en":"Please acknowledge receipt of the documents.","zh":"请确认收到文件。"},{"en":"Payment is due on receipt of the invoice.","zh":"收到发票后应付款。"}]},{"pos":"n.","meaning":"收入;进款（常用复数）","definition":"money received by a business","examples":[{"en":"Ticket receipts exceeded expectations.","zh":"票务收入超出预期。"},{"en":"The shop records its daily receipts.","zh":"商店记录每日收入。"}]}],"receiver":[{"pos":"n.","meaning":"电话听筒","definition":"the part of a telephone held to the ear","examples":[{"en":"She lifted the receiver.","zh":"她拿起听筒。"},{"en":"He replaced the receiver gently.","zh":"他轻轻放回听筒。"}]},{"pos":"n.","meaning":"接收器","definition":"a device that receives signals","examples":[{"en":"The radio receiver needs a new battery.","zh":"无线电接收器需要新电池。"},{"en":"The satellite receiver was installed on the roof.","zh":"卫星接收器安装在屋顶。"}]}],"reception":[{"pos":"n.","meaning":"接待处；接待","definition":"The welcoming of visitors or the place where they are welcomed.","examples":[{"en":"Please leave the key at reception.","zh":"请把钥匙留在接待处。"},{"en":"The visitors received a warm reception.","zh":"来访者受到热情接待。"}]},{"pos":"n.","meaning":"招待会；欢迎会","definition":"A formal social event for welcoming or celebrating.","examples":[{"en":"A reception followed the graduation ceremony.","zh":"毕业典礼后举行了招待会。"},{"en":"They held a wedding reception in the garden.","zh":"他们在花园里举行了婚宴。"}]},{"pos":"n.","meaning":"接收；接收效果","definition":"The receiving of radio, television, or other signals.","examples":[{"en":"Radio reception is poor in the valley.","zh":"山谷里的广播接收效果很差。"},{"en":"Moving the aerial improved television reception.","zh":"移动天线改善了电视接收效果。"}]},{"pos":"n.","meaning":"反应；评价；接受情况","definition":"The way people respond to an idea or work.","examples":[{"en":"The novel received an enthusiastic reception.","zh":"这部小说受到热烈欢迎。"},{"en":"The proposal's cool reception surprised its author.","zh":"提案反响冷淡，令提案人感到意外。"}]}],"receptionist":[{"pos":"n.","meaning":"接待员","definition":"a person greeting visitors and handling enquiries","examples":[{"en":"The receptionist gave us a room key.","zh":"接待员给了我们房间钥匙。"},{"en":"Ask the receptionist to arrange an appointment.","zh":"请接待员安排预约。"}]}],"recession":[{"pos":"n.","meaning":"经济衰退；衰退期","definition":"a period of declining economic activity","examples":[{"en":"The recession reduced consumer spending.","zh":"经济衰退减少了消费支出。"},{"en":"Many businesses struggled during the recession.","zh":"经济衰退期间许多企业经营困难。"}]},{"pos":"n.","meaning":"后退；退缩","definition":"the movement of something back from a previous position","examples":[{"en":"The study measured the recession of the glacier.","zh":"研究测量了冰川后退。"},{"en":"Wave action caused the recession of the cliff.","zh":"波浪作用造成悬崖后退。"}]}],"recipe":[{"pos":"n.","meaning":"食谱；烹饪配方","definition":"Instructions and ingredients for preparing a dish.","examples":[{"en":"The recipe calls for fresh ginger.","zh":"食谱要求使用鲜姜。"},{"en":"She shared her grandmother's bread recipe.","zh":"她分享了祖母的面包配方。"}]},{"pos":"n.","meaning":"方法；秘诀；导致某结果的因素","definition":"A method or combination of conditions producing a result.","examples":[{"en":"Clear goals and teamwork are a recipe for success.","zh":"明确目标与团队合作是成功的秘诀。"},{"en":"Rushing without checking is a recipe for mistakes.","zh":"不检查就匆忙行事很容易出错。"}]}],"recipient":[{"pos":"n.","meaning":"接受者;收件人","definition":"a person receiving something","examples":[{"en":"The recipient signed for the parcel.","zh":"收件人签收了包裹。"},{"en":"Each scholarship recipient received a letter.","zh":"每位奖学金获得者都收到了一封信。"}]}],"reciprocate":[{"pos":"v.","meaning":"回报；回应","definition":"to respond with a similar action or feeling","examples":[{"en":"She reciprocated their kindness.","zh":"她回报了他们的善意。"},{"en":"The university reciprocated by inviting their students.","zh":"大学也邀请了对方学生作为回应。"}]}],"reckon":[{"pos":"v.","meaning":"认为；估计；料想","definition":"To believe or estimate.","examples":[{"en":"I reckon the journey will take two hours.","zh":"我估计旅程需要两个小时。"},{"en":"She reckoned that the plan was worth trying.","zh":"她认为这个计划值得一试。"}]},{"pos":"v.","meaning":"计算；测算","definition":"To calculate an amount.","examples":[{"en":"The builder reckoned the cost at ten thousand pounds.","zh":"建筑商估算费用为一万英镑。"},{"en":"We reckoned the total by adding the daily figures.","zh":"我们将每日数字相加，算出了总数。"}]},{"pos":"v.","meaning":"指望；预料；把……考虑在内","definition":"To rely on or allow for something, often with on or with.","examples":[{"en":"We had reckoned on having more time.","zh":"我们原本指望能有更多时间。"},{"en":"They had not reckoned with such strong opposition.","zh":"他们没有料到会遇到如此强烈的反对。"}]}],"reclaim":[{"pos":"v.","meaning":"收回;要求归还","definition":"to take back something belonging to one","examples":[{"en":"She reclaimed her bag from lost property.","zh":"她从失物招领处领回了包。"},{"en":"The community reclaimed the abandoned building.","zh":"社区收回了被遗弃的建筑。"}]},{"pos":"v.","meaning":"开垦;改造土地","definition":"to make land usable for a new purpose","examples":[{"en":"Engineers reclaimed land from the sea.","zh":"工程师填海造地。"},{"en":"The project reclaimed an old mining site.","zh":"项目整治了旧矿区。"}]},{"pos":"v.","meaning":"改造;使改过自新（较少用）","definition":"to reform someone from harmful behaviour","examples":[{"en":"The charity hoped to reclaim young offenders.","zh":"慈善机构希望帮助少年犯改过自新。"},{"en":"Education helped reclaim him from a life of crime.","zh":"教育帮助他摆脱了犯罪生活。"}]}],"recognition":[{"pos":"n.","meaning":"识别；认出","definition":"the act of identifying something known","examples":[{"en":"The software uses speech recognition.","zh":"软件使用语音识别。"},{"en":"Her expression changed with recognition.","zh":"认出对方后，她的表情变了。"}]},{"pos":"n.","meaning":"承认；认可","definition":"acceptance that something is true or valid","examples":[{"en":"The decision reflects recognition of the problem.","zh":"决定反映出对问题的承认。"},{"en":"The qualification gained international recognition.","zh":"资格获得了国际认可。"}]},{"pos":"n.","meaning":"赏识；表彰","definition":"public appreciation of achievement","examples":[{"en":"She received recognition for her research.","zh":"她的研究受到表彰。"},{"en":"The award gives volunteers deserved recognition.","zh":"奖项给予志愿者应得的赞赏。"}]}],"recognize":[{"pos":"v.","meaning":"认出；识别","definition":"To know someone or something from previous experience.","examples":[{"en":"I recognized her voice immediately.","zh":"我立刻认出了她的声音。"},{"en":"The software can recognize handwritten numbers.","zh":"软件可以识别手写数字。"}]},{"pos":"v.","meaning":"承认；认可；意识到","definition":"To accept something as valid or become aware of it.","examples":[{"en":"The manager recognized the need for extra staff.","zh":"经理意识到需要增加员工。"},{"en":"The award recognizes her contribution to science.","zh":"这个奖项表彰她对科学的贡献。"}]}],"recommend":[{"pos":"v.","meaning":"推荐；建议","definition":"to suggest that something is suitable or worth doing","examples":[{"en":"Can you recommend a reliable local mechanic?","zh":"你能推荐一位可靠的当地修理工吗？"},{"en":"Doctors recommend taking regular exercise.","zh":"医生建议经常锻炼。"},{"en":"I would recommend this course to new managers.","zh":"我会向新任经理推荐这门课程。"}]},{"pos":"v.","meaning":"使受欢迎;使显得可取","definition":"to make someone or something attractive or suitable","examples":[{"en":"Her reliability recommended her for the position.","zh":"她的可靠使她适合这个职位。"},{"en":"The hotel's location has much to recommend it.","zh":"酒店的位置有许多值得称道之处。"}]}],"recommend doing":[{"pos":"phr.","meaning":"建议做某事；推荐做某事","definition":"to advise an action, using a verb ending in -ing","examples":[{"en":"I recommend booking your train tickets in advance.","zh":"我建议提前预订火车票。"},{"en":"The guide recommends visiting the museum early in the morning.","zh":"导游建议一早去参观博物馆。"}]}],"recommendation":[{"pos":"n.","meaning":"建议；劝告","definition":"advice about what should be done","examples":[{"en":"The report makes several recommendations.","zh":"报告提出几项建议。"},{"en":"We followed the guide's recommendation.","zh":"我们听从了导游的建议。"}]},{"pos":"n.","meaning":"推荐；推荐信","definition":"a statement supporting someone's suitability","examples":[{"en":"She wrote a recommendation for her former student.","zh":"她为以前的学生写了推荐信。"},{"en":"The candidate came with strong recommendations.","zh":"候选人获得了有力推荐。"}]}],"reconstruction":[{"pos":"n.","meaning":"重建；修复","definition":"The process of building something again after damage.","examples":[{"en":"Reconstruction of the bridge took two years.","zh":"重建这座桥花了两年。"},{"en":"The town began reconstruction after the earthquake.","zh":"地震后，小镇开始重建。"}]},{"pos":"n.","meaning":"重现；复原","definition":"A representation of how something looked or happened.","examples":[{"en":"The museum displays a reconstruction of an ancient kitchen.","zh":"博物馆展示了一间古代厨房的复原场景。"},{"en":"The police filmed a reconstruction of the incident.","zh":"警方拍摄了事件重演。"}]}],"recourse":[{"pos":"n.","meaning":"求助;依靠;可用手段","definition":"help or a method available when facing difficulty","examples":[{"en":"Negotiation was their only recourse.","zh":"谈判是他们唯一可用的办法。"},{"en":"She solved the dispute without recourse to law.","zh":"她未诉诸法律便解决了争议。"}]}],"recover":[{"pos":"v.","meaning":"恢复；康复","definition":"to return to health or a normal state","examples":[{"en":"The forest recovered after the fire.","zh":"森林在火灾后恢复了。"},{"en":"She recovered from the illness.","zh":"她病后康复了。"}]},{"pos":"v.","meaning":"找回；收回；重新获得","definition":"to regain something lost","examples":[{"en":"The police recovered the stolen painting.","zh":"警方找回了被盗画作。"},{"en":"The company recovered its costs.","zh":"公司收回了成本。"}]}],"recovery":[{"pos":"n.","meaning":"康复","definition":"the process of becoming healthy again","examples":[{"en":"Rest is important for recovery after surgery.","zh":"休息对术后康复很重要。"},{"en":"We wish you a speedy recovery.","zh":"我们祝你早日康复。"},{"en":"Her recovery took longer than expected.","zh":"她的康复时间比预期更长。"}]}],"recreate":[{"pos":"v.","meaning":"再现;重新创造","definition":"to create again or reproduce","examples":[{"en":"The museum recreates a nineteenth-century street.","zh":"博物馆再现了一条十九世纪街道。"},{"en":"We tried to recreate the original recipe.","zh":"我们试着重现原来的食谱。"}],"ipa":"/ˌriːkriˈeɪt/"}],"recreation":[{"pos":"n.","meaning":"娱乐；消遣","definition":"activities done for pleasure and relaxation","examples":[{"en":"The park provides space for recreation.","zh":"公园提供娱乐休闲空间。"},{"en":"Swimming is her main form of recreation.","zh":"游泳是她主要的消遣方式。"}]}],"recreational":[{"pos":"adj.","meaning":"娱乐的；休闲的；消遣的","definition":"Done for enjoyment during free time.","examples":[{"en":"The lake is popular for recreational boating.","zh":"这片湖很适合休闲划船。"},{"en":"The council improved local recreational facilities.","zh":"地方议会改善了当地休闲设施。"}]}],"recruit":[{"pos":"v.","meaning":"招聘；招募","definition":"to find people to join an organisation","examples":[{"en":"The company plans to recruit five engineers.","zh":"公司计划招聘五名工程师。"},{"en":"Hospitals need to recruit more nurses.","zh":"医院需要招聘更多护士。"},{"en":"We recruit volunteers through our website.","zh":"我们通过网站招募志愿者。"}]},{"pos":"n.","meaning":"新成员;新兵;新雇员","definition":"someone newly joining a group","examples":[{"en":"The new recruits began training.","zh":"新兵开始训练。"},{"en":"Each recruit received a welcome pack.","zh":"每名新成员收到入职资料包。"}]},{"pos":"v.","meaning":"补充;补足（较少用）","definition":"to replenish a supply","examples":[{"en":"The travellers stopped to recruit their provisions.","zh":"旅行者停下补充给养。"},{"en":"The expedition recruited its dwindling stores at the port.","zh":"探险队在港口补充日渐减少的储备。"}]},{"pos":"v.","meaning":"恢复体力或精神（古义）","definition":"to restore strength or health","examples":[{"en":"A week's rest recruited his strength.","zh":"一周休息恢复了他的体力。"},{"en":"They paused to recruit their exhausted spirits.","zh":"他们停下来恢复疲惫精神。"}]}],"rectangle":[{"pos":"n.","meaning":"矩形；长方形","definition":"a four-sided shape with four right angles","examples":[{"en":"Draw a rectangle around the title.","zh":"在标题周围画一个矩形。"},{"en":"The garden forms a narrow rectangle.","zh":"花园呈狭长矩形。"}]}],"rectangular":[{"pos":"adj.","meaning":"长方形的；矩形的","definition":"Having four right angles and opposite sides equal.","examples":[{"en":"The garden is roughly rectangular.","zh":"花园大致呈长方形。"},{"en":"Cut the dough into rectangular pieces.","zh":"把面团切成长方形块。"}]}],"recycle":[{"pos":"v.","meaning":"回收利用","definition":"to process used materials so they can be used again","examples":[{"en":"Residents can recycle glass at the local centre.","zh":"居民可以在当地中心回收玻璃。"},{"en":"We should recycle old electronics safely.","zh":"我们应该安全地回收旧电子产品。"},{"en":"The company aims to recycle all its packaging.","zh":"公司计划回收利用所有包装。"}]}],"redevelopment":[{"pos":"n.","meaning":"重新规划；重新建设","definition":"the rebuilding or improvement of an area","examples":[{"en":"The old dock is undergoing redevelopment.","zh":"旧码头正在重新开发。"},{"en":"Residents discussed plans for redevelopment.","zh":"居民讨论了重建计划。"}]}],"reduce":[{"pos":"v.","meaning":"减少；降低；缩小","definition":"To make something smaller in amount or size.","examples":[{"en":"The measures reduced water consumption.","zh":"这些措施减少了用水量。"},{"en":"She reduced the image to fit the page.","zh":"她把图片缩小，以适应页面。"}]},{"pos":"v.","meaning":"简化；归纳为","definition":"To express something in a simpler form.","examples":[{"en":"The problem can be reduced to two basic questions.","zh":"这个问题可以简化为两个基本问题。"},{"en":"Reduce the fraction to its simplest form.","zh":"把分数约分为最简形式。"}]}],"redundancy":[{"pos":"n.","meaning":"裁员；因岗位取消而失业","definition":"job loss because the position is no longer needed","examples":[{"en":"Factory workers face redundancy after the closure.","zh":"工厂关闭后，工人面临裁员。"},{"en":"The company offered voluntary redundancy to some staff.","zh":"公司为部分员工提供了自愿离职裁员方案。"},{"en":"She received a redundancy payment when her role was removed.","zh":"她的岗位被取消后获得了裁员补偿。"}]}],"redundant":[{"pos":"adj.","meaning":"被裁员的（英式）","definition":"no longer employed because a job is unnecessary","examples":[{"en":"Several workers were made redundant.","zh":"几位工人被裁员。"},{"en":"The scheme helps redundant employees retrain.","zh":"计划帮助被裁员工再培训。"}]},{"pos":"adj.","meaning":"多余的；冗余的","definition":"unnecessary because something else serves the same purpose","examples":[{"en":"Delete the redundant sentence.","zh":"删除多余的句子。"},{"en":"The upgrade made older equipment redundant.","zh":"升级使旧设备变得多余。"}]}],"reel":[{"pos":"n.","meaning":"卷轴；卷盘；线轴","definition":"A cylinder on which film, thread, or wire is wound.","examples":[{"en":"The film was stored on a metal reel.","zh":"胶片储存在金属卷盘上。"},{"en":"She bought a reel of blue thread.","zh":"她买了一轴蓝线。"}]},{"pos":"v.","meaning":"踉跄；摇晃；眩晕","definition":"To stagger or feel dizzy from shock or physical imbalance.","examples":[{"en":"He reeled backwards after the blow.","zh":"他挨了一击后踉跄着后退。"},{"en":"Her mind reeled at the unexpected news.","zh":"意外消息让她脑中一阵眩晕。"}]},{"pos":"v.","meaning":"卷起；收卷","definition":"To wind something onto a reel.","examples":[{"en":"The fisherman reeled in the line.","zh":"渔夫把鱼线收了回来。"},{"en":"She carefully reeled the cable onto its drum.","zh":"她小心地把电缆卷到线筒上。"}]}],"refectory":[{"pos":"n.","meaning":"食堂;公共餐厅","definition":"a communal dining room in an institution","examples":[{"en":"Students gathered in the college refectory.","zh":"学生聚集在学院食堂。"},{"en":"The monks ate silently in the refectory.","zh":"僧侣在公共餐厅默默用餐。"}]}],"refer":[{"pos":"v.","meaning":"查阅；参考（常与 to 连用）","definition":"to consult a source of information","examples":[{"en":"Refer to the manual for details.","zh":"详情请查阅手册。"},{"en":"She referred to her notes during the talk.","zh":"讲话时她参考了笔记。"}]},{"pos":"v.","meaning":"提及；指称；引用（常与 to 连用）","definition":"to mention or direct attention to something","examples":[{"en":"He referred to the earlier study.","zh":"他提到了之前的研究。"},{"en":"The term refers to a type of soil.","zh":"这个术语指一种土壤。"}]},{"pos":"v.","meaning":"转交；提交；转介","definition":"to send someone or something to another authority","examples":[{"en":"The case was referred to a specialist.","zh":"案件被转交给专家。"},{"en":"The committee referred the question to legal advisers.","zh":"委员会把问题提交法律顾问。"}]}],"referee":[{"pos":"n.","meaning":"裁判；仲裁人；调停人","definition":"A person who applies rules or settles a dispute.","examples":[{"en":"The referee stopped the match.","zh":"裁判叫停了比赛。"},{"en":"Both sides accepted an independent referee to settle the disagreement.","zh":"双方接受由独立仲裁人解决分歧。"}]},{"pos":"n.","meaning":"证明人；推荐人","definition":"Someone who provides information about an applicant's character or ability.","examples":[{"en":"List two referees on the application.","zh":"请在申请表上列出两位推荐人。"},{"en":"Her former supervisor agreed to act as a referee.","zh":"她的前主管同意担任推荐人。"}]},{"pos":"v.","meaning":"担任裁判；仲裁；调停","definition":"To supervise a game or settle a disagreement.","examples":[{"en":"He refereed the school football final.","zh":"他担任了学校足球决赛的裁判。"},{"en":"A retired judge refereed the dispute.","zh":"一位退休法官仲裁了这场纠纷。"}]}],"reference":[{"pos":"n.","meaning":"推荐信；工作证明","definition":"a statement about a person's suitability for a job","examples":[{"en":"Please ask your former manager for a reference.","zh":"请向你的前任经理索取推荐信。"},{"en":"We require a written reference from your last employer.","zh":"我们需要你上一家雇主出具书面工作证明。"},{"en":"Her supervisor provided an excellent reference.","zh":"她的主管提供了一封评价很高的推荐信。"}]},{"pos":"n.","meaning":"参考；查阅","definition":"the act of looking at information for help","examples":[{"en":"Keep this guide for future reference.","zh":"请保留这份指南以供日后查阅。"},{"en":"The manual is available for reference in the office.","zh":"办公室有这本手册供查阅。"},{"en":"The website provides useful reference material.","zh":"这个网站提供有用的参考资料。"}]},{"pos":"n.","meaning":"提及;涉及","definition":"a mention of something","examples":[{"en":"The speech made no reference to the delay.","zh":"演讲没有提及延误。"},{"en":"I found several references to the village in the diary.","zh":"我在日记里找到几处提及村庄的内容。"}]},{"pos":"n.","meaning":"参考文献;出处","definition":"a source cited to support information","examples":[{"en":"List all references at the end of the essay.","zh":"在文章末尾列出全部参考文献。"},{"en":"The editor checked each reference.","zh":"编辑核对了每一条出处。"}]},{"pos":"n.","meaning":"推荐人;证明人","definition":"a person willing to vouch for someone","examples":[{"en":"May I name you as a reference?","zh":"我能把你列为推荐人吗？"},{"en":"The employer contacted both references.","zh":"雇主联系了两位证明人。"}]}],"refinement":[{"pos":"n.","meaning":"改进；精巧的附加功能","definition":"a small improvement making something better","examples":[{"en":"The design needs further refinement.","zh":"设计还需进一步改进。"},{"en":"The new model includes several useful refinements.","zh":"新型号包含几个实用改进。"}]},{"pos":"n.","meaning":"精炼；提纯","definition":"the removal of unwanted substances","examples":[{"en":"The process involves the refinement of raw sugar.","zh":"过程涉及原糖精炼。"},{"en":"Oil refinement takes place at the coastal plant.","zh":"石油精炼在沿海工厂进行。"}]},{"pos":"n.","meaning":"文雅；高雅","definition":"politeness and cultivated taste","examples":[{"en":"Her conversation showed great refinement.","zh":"她的谈吐十分文雅。"},{"en":"The room combined comfort with refinement.","zh":"房间兼具舒适与高雅。"}]}],"refrain":[{"pos":"v.","meaning":"克制；避免；忍住","definition":"To deliberately avoid doing something.","examples":[{"en":"Please refrain from using phones during the performance.","zh":"演出期间请勿使用手机。"},{"en":"She refrained from commenting until the facts were clear.","zh":"在事实清楚之前，她克制自己，没有评论。"}]},{"pos":"n.","meaning":"副歌；叠句；反复出现的话","definition":"A repeated line in a song or a frequently repeated statement.","examples":[{"en":"The audience joined in the final refrain.","zh":"观众一起唱起了最后一段副歌。"},{"en":"The familiar refrain was that there was no money available.","zh":"反复听到的老话是没有可用资金。"}]}],"refresh":[{"pos":"v.","meaning":"使恢复精神;使振作","definition":"to restore energy or freshness","examples":[{"en":"A short walk refreshed her.","zh":"短暂散步使她精神恢复。"},{"en":"The cool water refreshed the tired hikers.","zh":"凉水使疲惫的徒步者恢复了精神。"}]},{"pos":"v.","meaning":"更新;刷新;重新唤起","definition":"to renew information or memory","examples":[{"en":"Refresh the page to see the latest figures.","zh":"刷新页面查看最新数据。"},{"en":"The notes refreshed his memory of the meeting.","zh":"笔记唤起了他对会议的记忆。"}]}],"refresher":[{"pos":"n.","meaning":"复习课程；提醒记忆的事物","definition":"a short review that renews knowledge","examples":[{"en":"The guide offers a refresher on basic grammar.","zh":"指南提供基础语法复习。"},{"en":"He took a refresher before returning to teaching.","zh":"重返教学前，他参加了进修复习课。"}]},{"pos":"n.","meaning":"提神物；使人恢复精神的东西","definition":"something that restores energy or freshness","examples":[{"en":"A cool drink was a welcome refresher.","zh":"一杯冷饮让人舒畅提神。"},{"en":"The brief walk served as a refresher after hours indoors.","zh":"在室内待了几小时后，短暂散步使人恢复精神。"}]}],"refreshment":[{"pos":"n.","meaning":"恢复精神；焕发精力","definition":"Rest or something that restores energy.","examples":[{"en":"The quiet walk provided mental refreshment.","zh":"这次安静散步使精神得到恢复。"},{"en":"After hours of work, she needed rest and refreshment.","zh":"工作了几个小时后，她需要休息并恢复精力。"}]},{"pos":"n.","meaning":"茶点；饮料；点心（常用复数）","definition":"Small amounts of food and drink.","examples":[{"en":"Refreshments will be served during the interval.","zh":"中场休息时会供应茶点。"},{"en":"We stopped for refreshments at a roadside café.","zh":"我们在路边咖啡馆停下来吃点心、喝饮料。"}]}],"refrigerator":[{"pos":"n.","meaning":"冰箱;冷藏设备","definition":"a device keeping food or other items cold","examples":[{"en":"Put the milk in the refrigerator.","zh":"把牛奶放进冰箱。"},{"en":"The laboratory refrigerator stores the samples.","zh":"实验室冰箱存放样本。"}]}],"refund":[{"pos":"n.","meaning":"退款","definition":"money returned after a purchase","examples":[{"en":"I requested a refund for the broken headphones.","zh":"我要求退还损坏耳机的货款。"},{"en":"You can get a full refund within fourteen days.","zh":"你可以在十四天内获得全额退款。"},{"en":"The company sent my refund to the original payment card.","zh":"公司将退款退回了原支付银行卡。"}],"ipa":"/ˈriːfʌnd/"},{"pos":"v.","meaning":"退还款项；退款","definition":"to return money paid","examples":[{"en":"The shop refunded the full price.","zh":"商店退还了全款。"},{"en":"They refunded our tickets after the cancellation.","zh":"取消后他们退还了票款。"}],"ipa":"/riːˈfʌnd/"}],"refundable":[{"pos":"adj.","meaning":"可退还的；可退款的","definition":"Able to be paid back.","examples":[{"en":"The deposit is fully refundable.","zh":"押金可以全额退还。"},{"en":"Check whether the ticket is refundable before buying it.","zh":"买票前请检查是否可以退款。"}]}],"refusal":[{"pos":"n.","meaning":"拒绝","definition":"the act of saying no","examples":[{"en":"Her refusal surprised the committee.","zh":"她的拒绝让委员会吃惊。"},{"en":"The letter contained a polite refusal.","zh":"信中作出了礼貌的拒绝。"}]}],"regarding":[{"pos":"prep.","meaning":"关于；就……而言","definition":"concerning a subject","examples":[{"en":"I have a question regarding the timetable.","zh":"我有一个关于时刻表的问题。"},{"en":"She sent instructions regarding the delivery.","zh":"她发送了有关交货的指示。"}]}],"regardless":[{"pos":"adv.","meaning":"不顾；无论如何","definition":"Without allowing a difficulty or objection to stop an action.","examples":[{"en":"It began to rain, but the runners continued regardless.","zh":"开始下雨了，但跑步者仍继续前进。"},{"en":"She was warned about the cost and went ahead regardless.","zh":"她被提醒过费用问题，却依然继续。"}]}],"regent":[{"pos":"n.","meaning":"摄政者","definition":"someone ruling temporarily for a monarch","examples":[{"en":"The queen acted as regent for her young son.","zh":"王后为年幼的儿子摄政。"},{"en":"The regent governed during the king's absence.","zh":"国王不在时由摄政者治理。"}]}],"region":[{"pos":"n.","meaning":"地区；区域；范围","definition":"an area defined by location or features","examples":[{"en":"The region is famous for its forests.","zh":"该地区以森林闻名。"},{"en":"Pain was felt in the shoulder region.","zh":"疼痛出现在肩部区域。"}]}],"regional":[{"pos":"adj.","meaning":"地区的；区域性的；地方性的","definition":"Relating to a particular area of a country or world.","examples":[{"en":"The regional airport serves several small towns.","zh":"这座地区机场服务于几个小城镇。"},{"en":"The study compares regional differences in rainfall.","zh":"研究比较了降雨量的地区差异。"}]}],"register":[{"pos":"n.","meaning":"登记簿;名册;登记记录","definition":"an official list or record","examples":[{"en":"Sign the visitors' register.","zh":"在访客登记簿上签名。"},{"en":"The teacher checked the attendance register.","zh":"老师核对出勤名册。"}]},{"pos":"v.","meaning":"登记;注册","definition":"to record officially","examples":[{"en":"Students must register before Friday.","zh":"学生必须在周五前注册。"},{"en":"They registered the birth at the local office.","zh":"他们在当地办事处登记了出生信息。"}]}],"registration":[{"pos":"n.","meaning":"登记；注册；挂号","definition":"the act of entering information in an official record","examples":[{"en":"Registration closes on Friday.","zh":"注册星期五截止。"},{"en":"Postal registration provides a record of delivery.","zh":"邮政挂号提供投递记录。"}]},{"pos":"n.","meaning":"登记事项；注册记录；登记号码","definition":"an officially recorded entry or identifying number","examples":[{"en":"The office received fifty registrations.","zh":"办公室收到了五十份注册记录。"},{"en":"She checked the car's registration.","zh":"她检查了汽车的登记信息。"}]}],"regularity":[{"pos":"n.","meaning":"规律性；经常发生","definition":"The quality of happening at consistent intervals or according to a pattern.","examples":[{"en":"The regularity of the tides helped them plan their work.","zh":"潮汐的规律性帮助他们安排工作。"},{"en":"The buses arrived with impressive regularity.","zh":"公交车班次相当准时有规律。"}]},{"pos":"n.","meaning":"整齐；匀称；规则性","definition":"Uniformity of shape, arrangement, or structure.","examples":[{"en":"The regularity of the pattern suggests it was made by a machine.","zh":"图案的整齐一致表明它由机器制作。"},{"en":"The architect admired the regularity of the stonework.","zh":"建筑师欣赏石砌结构的匀称。"}]}],"regulate":[{"pos":"v.","meaning":"监管；规范","definition":"to control an activity through rules","examples":[{"en":"Governments regulate the sale of dangerous products.","zh":"政府监管危险产品的销售。"},{"en":"The authority aims to regulate online advertising.","zh":"该机构旨在规范网络广告。"},{"en":"It is difficult to regulate an industry that changes rapidly.","zh":"监管快速变化的行业很困难。"}]},{"pos":"v.","meaning":"调节;校准","definition":"to adjust a level, speed, or process","examples":[{"en":"The thermostat regulates room temperature.","zh":"恒温器调节室温。"},{"en":"A valve regulates the flow of water.","zh":"阀门调节水流。"}]}],"regulation":[{"pos":"n.","meaning":"规定；规章","definition":"an official rule","examples":[{"en":"The new regulation requires helmets on this site.","zh":"新规定要求在此工地佩戴安全帽。"},{"en":"Every employee must follow this safety regulation.","zh":"每位员工都必须遵守这条安全规定。"},{"en":"The regulation aims to reduce water waste.","zh":"这项规定旨在减少水资源浪费。"}]}],"regurgitate":[{"pos":"v.","meaning":"反刍；使咽下的食物返回口中；涌回","definition":"To bring swallowed food or liquid back into the mouth.","examples":[{"en":"The bird regurgitated food for its chicks.","zh":"鸟把食物反刍出来喂雏鸟。"},{"en":"The animal regurgitates partially digested food and chews it again.","zh":"这种动物把部分消化的食物返回口中，再次咀嚼。"}]}],"rehabilitate":[{"pos":"v.","meaning":"使康复;使恢复正常生活","definition":"to help someone return to normal health or life","examples":[{"en":"The centre rehabilitates injured athletes.","zh":"中心帮助受伤运动员康复。"},{"en":"The programme aims to rehabilitate former prisoners.","zh":"项目旨在帮助前囚犯重新融入正常生活。"}]},{"pos":"v.","meaning":"修复;恢复原状","definition":"to restore something to a good condition","examples":[{"en":"Volunteers rehabilitated the damaged wetland.","zh":"志愿者修复了受损湿地。"},{"en":"The scheme rehabilitates empty houses.","zh":"计划修缮空置房屋。"}]},{"pos":"v.","meaning":"恢复名誉;恢复职位","definition":"to restore someone's reputation or status","examples":[{"en":"New evidence rehabilitated the dismissed scientist.","zh":"新证据恢复了被解职科学家的名誉。"},{"en":"The government rehabilitated officials wrongly accused.","zh":"政府为受冤指控的官员平反复职。"}]}],"reinforce":[{"pos":"v.","meaning":"加强；加固；增援","definition":"to make stronger or provide additional support","examples":[{"en":"Steel bars reinforce the concrete.","zh":"钢筋加固混凝土。"},{"en":"Extra staff reinforced the rescue team.","zh":"额外人员增援了救援队。"}]}],"reinforcement":[{"pos":"n.","meaning":"加强；加固；强化","definition":"The act or means of making something stronger.","examples":[{"en":"The wall needs reinforcement before the roof is replaced.","zh":"更换屋顶前需要加固墙壁。"},{"en":"Positive reinforcement encouraged the children to practise.","zh":"积极强化鼓励孩子们练习。"}]},{"pos":"n.","meaning":"增援；援兵（常用复数）","definition":"Additional people or supplies sent to help.","examples":[{"en":"The rescue team requested reinforcements.","zh":"救援队请求增援。"},{"en":"Reinforcements arrived before nightfall.","zh":"援兵在天黑前到达。"}]}],"reinvigorate":[{"pos":"v.","meaning":"使恢复活力;使重新振作","definition":"to give new strength or energy","examples":[{"en":"The grant reinvigorated the research programme.","zh":"资助使研究项目恢复活力。"},{"en":"A holiday reinvigorated the exhausted teacher.","zh":"假期使疲惫的老师重新振作。"}]}],"reiterate":[{"pos":"v.","meaning":"重申；反复说","definition":"to state something again for emphasis","examples":[{"en":"She reiterated her support.","zh":"她重申了支持。"},{"en":"The notice reiterates the deadline.","zh":"通知再次强调截止日期。"}]}],"reject":[{"pos":"v.","meaning":"拒绝；不接受；排斥","definition":"To refuse to accept or use something.","examples":[{"en":"The committee rejected the proposal.","zh":"委员会拒绝了这个提案。"},{"en":"The machine rejects damaged coins.","zh":"机器不接受损坏的硬币。"}],"ipa":"/rɪˈdʒekt/"},{"pos":"n.","meaning":"不合格品；被弃之物","definition":"Something not accepted because it fails a standard.","examples":[{"en":"The factory sells rejects at reduced prices.","zh":"工厂以折扣价出售不合格品。"},{"en":"The cracked bowl was placed among the rejects.","zh":"有裂纹的碗被放到次品中。"}],"ipa":"/ˈriːdʒekt/"}],"rekindle":[{"pos":"v.","meaning":"重新点燃","definition":"to make a fire burn again","examples":[{"en":"He added dry wood to rekindle the fire.","zh":"他添干木柴重新点燃火。"},{"en":"A stray spark rekindled the embers.","zh":"一颗飞散火星使余烬复燃。"}]},{"pos":"v.","meaning":"重新唤起;使复苏","definition":"to revive a feeling or interest","examples":[{"en":"The visit rekindled her love of painting.","zh":"这次参观重新唤起她对绘画的热爱。"},{"en":"The letter rekindled their friendship.","zh":"信使他们的友谊复苏。"}]}],"relate":[{"pos":"v.","meaning":"有关联；联系","definition":"to connect or have a connection","examples":[{"en":"The questions relate to travel habits.","zh":"问题与出行习惯有关。"},{"en":"We related the results to earlier findings.","zh":"我们把结果与早先发现联系起来。"}]},{"pos":"v.","meaning":"讲述；叙述","definition":"to tell a story or sequence of events","examples":[{"en":"He related the events calmly.","zh":"他平静地叙述了事件。"},{"en":"She related an amusing incident.","zh":"她讲述了一件有趣的事。"}]}],"relation":[{"pos":"n.","meaning":"关系；联系","definition":"A connection between people, things, or ideas.","examples":[{"en":"The study examines the relation between sleep and memory.","zh":"研究考察睡眠与记忆的关系。"},{"en":"Relations between the two departments improved.","zh":"两个部门之间的关系改善了。"}]},{"pos":"n.","meaning":"亲戚；亲属","definition":"A member of one's family.","examples":[{"en":"She invited all her close relations.","zh":"她邀请了所有近亲。"},{"en":"He is a distant relation of my mother.","zh":"他是我母亲的一位远亲。"}]}],"relative":[{"pos":"adj.","meaning":"相对的;比较而言的","definition":"judged in comparison with something else","examples":[{"en":"The villages enjoyed relative prosperity.","zh":"这些村庄比较富裕。"},{"en":"We compared the relative costs of each option.","zh":"我们比较了各方案的相对成本。"}]},{"pos":"adj.","meaning":"有关的;相关的","definition":"connected with a particular subject","examples":[{"en":"The file contains documents relative to the inquiry.","zh":"档案包含与调查有关的文件。"},{"en":"She raised several points relative to funding.","zh":"她提出了几个有关资金的问题。"}]},{"pos":"n.","meaning":"亲戚;亲属","definition":"a member of the same family","examples":[{"en":"Several relatives came to the wedding.","zh":"几位亲属参加了婚礼。"},{"en":"Her nearest relative lives abroad.","zh":"她最亲近的亲属住在国外。"}]}],"relax":[{"pos":"v.","meaning":"放松；使松弛","definition":"to become or make less tense","examples":[{"en":"She relaxed after the examination.","zh":"考试后她放松下来。"},{"en":"The exercise helps relax the shoulders.","zh":"练习帮助肩部放松。"}]}],"relay":[{"pos":"n.","meaning":"接力赛；接力传递","definition":"A race or activity in which participants take turns.","examples":[{"en":"Our team won the relay.","zh":"我们队赢得了接力赛。"},{"en":"Volunteers formed a relay to carry supplies uphill.","zh":"志愿者组成接力队，把补给运上山。"}]},{"pos":"n.","meaning":"中继设备；继电器","definition":"A device that passes on a signal or controls another circuit.","examples":[{"en":"The relay switches the motor on automatically.","zh":"继电器自动启动电机。"},{"en":"A hilltop relay extends the radio signal's range.","zh":"山顶中继设备扩大了无线电信号的覆盖范围。"}]},{"pos":"v.","meaning":"传递；转播","definition":"To pass on information or transmit a broadcast.","examples":[{"en":"She relayed the message to the rest of the team.","zh":"她把消息传达给团队其他成员。"},{"en":"The concert was relayed live to several cinemas.","zh":"音乐会向几家电影院进行了现场直播。"}]}],"release":[{"pos":"v.","meaning":"释放;放出;解除","definition":"to let someone or something go free","examples":[{"en":"The rescuers released the trapped bird.","zh":"救援者放出了被困的鸟。"},{"en":"The valve releases excess pressure.","zh":"阀门释放多余压力。"}]},{"pos":"v.","meaning":"发布;发行","definition":"to make a product or information publicly available","examples":[{"en":"The band released a new album.","zh":"乐队发行了新专辑。"},{"en":"The agency released the survey results.","zh":"机构公布了调查结果。"}]},{"pos":"n.","meaning":"释放;排放;泄漏","definition":"the act of letting someone or something out","examples":[{"en":"His release from prison came in June.","zh":"他于六月获释。"},{"en":"The accidental release contaminated the stream.","zh":"意外泄漏污染了溪流。"}]},{"pos":"n.","meaning":"发布;发行作品","definition":"the act of making something public or a published item","examples":[{"en":"The film's release was delayed.","zh":"电影上映延期了。"},{"en":"Her latest release received excellent reviews.","zh":"她的最新作品获得好评。"}]}],"relentless":[{"pos":"adj.","meaning":"持续不止的；毫不留情的","definition":"continuing without easing or showing mercy","examples":[{"en":"Relentless rain delayed the work.","zh":"不停的雨延误了工作。"},{"en":"The team faced relentless criticism.","zh":"团队面临无情的批评。"}]}],"relevance":[{"pos":"n.","meaning":"相关性；切题；适当性","definition":"The connection or usefulness of something to a subject.","examples":[{"en":"Explain the relevance of this example to your argument.","zh":"请解释这个例子与你论点的关系。"},{"en":"The committee questioned the relevance of the old data.","zh":"委员会质疑旧数据是否仍适用。"}]}],"relevant":[{"pos":"adj.","meaning":"相关的","definition":"connected to the subject being considered","examples":[{"en":"Include only information relevant to the question.","zh":"只包含与问题相关的信息。"},{"en":"Work experience is highly relevant to this position.","zh":"工作经验与这个职位密切相关。"},{"en":"The report provides relevant evidence for the debate.","zh":"报告为这场讨论提供了相关证据。"}]}],"reliable":[{"pos":"adj.","meaning":"可靠的","definition":"able to be trusted to work well","examples":[{"en":"We need a reliable internet connection for work.","zh":"我们工作需要可靠的互联网连接。"},{"en":"She is a reliable employee who always meets deadlines.","zh":"她是一名可靠的员工，总能按时完成任务。"},{"en":"Check the information against a reliable source.","zh":"请用可靠来源核对这条信息。"}]}],"reliance":[{"pos":"n.","meaning":"依赖；依靠；信赖","definition":"Dependence on someone or something.","examples":[{"en":"The policy aims to reduce reliance on imported fuel.","zh":"政策旨在减少对进口燃料的依赖。"},{"en":"Excessive reliance on one supplier creates risk.","zh":"过度依赖单一供应商会带来风险。"}]}],"relief":[{"pos":"n.","meaning":"减轻;宽慰;缓解","definition":"the easing of pain or anxiety","examples":[{"en":"The cool breeze brought relief from the heat.","zh":"凉风缓解了炎热。"},{"en":"She sighed with relief when he arrived safely.","zh":"他安全到达时，她松了口气。"}]},{"pos":"n.","meaning":"救济;援助","definition":"help given to people in need","examples":[{"en":"The organisation delivered disaster relief.","zh":"组织提供了救灾援助。"},{"en":"Relief supplies reached the village.","zh":"救济物资抵达村庄。"}]},{"pos":"n.","meaning":"带来慰藉或轻松的事物","definition":"something that provides a welcome change","examples":[{"en":"The quiet garden was a relief after the crowded market.","zh":"拥挤市场过后，安静花园令人放松。"},{"en":"A day off was a welcome relief.","zh":"休一天假让人如释重负。"}]}],"relieve":[{"pos":"v.","meaning":"缓解；减轻","definition":"to make pain or difficulty less severe","examples":[{"en":"The new road relieved congestion.","zh":"新道路缓解了拥堵。"},{"en":"Her explanation relieved their anxiety.","zh":"她的解释减轻了他们的焦虑。"}]},{"pos":"v.","meaning":"救济；解救","definition":"to help people suffering from need or hardship","examples":[{"en":"The charity works to relieve poverty.","zh":"慈善机构致力于救济贫困。"},{"en":"The convoy brought supplies to relieve the isolated town.","zh":"车队运来物资救助被隔绝的小镇。"}]}],"religion":[{"pos":"n.","meaning":"宗教；宗教信仰","definition":"A system of beliefs and practices concerning the sacred or divine.","examples":[{"en":"The course explores the role of religion in history.","zh":"这门课程探讨宗教在历史中的作用。"},{"en":"People of different religions attended the event.","zh":"不同宗教信仰的人参加了活动。"}]}],"relocate":[{"pos":"v.","meaning":"搬迁;重新安置","definition":"to move to a new place","examples":[{"en":"The company relocated to a larger office.","zh":"公司迁入更大办公室。"},{"en":"Families were relocated after the flood.","zh":"洪水后家庭被重新安置。"}]}],"reluctant":[{"pos":"adj.","meaning":"不情愿的；勉强的","definition":"unwilling or hesitant","examples":[{"en":"He was reluctant to leave.","zh":"他不愿离开。"},{"en":"She gave reluctant permission.","zh":"她勉强同意了。"}]},{"pos":"adj.","meaning":"抗拒的；难以带动的（少见拟人用法）","definition":"resisting movement or action","examples":[{"en":"The reluctant engine finally started.","zh":"那台迟迟不肯发动的引擎终于启动了。"},{"en":"They urged the reluctant mule forward.","zh":"他们催促不肯前行的骡子向前。"}]}],"rely":[{"pos":"v.","meaning":"依靠；依赖；信赖","definition":"To depend on or trust someone or something.","examples":[{"en":"The village relies on a single well.","zh":"村庄依赖一口井供水。"},{"en":"You can rely on her to keep the information confidential.","zh":"你可以相信她会为这些信息保密。"}]}],"remain":[{"pos":"v.","meaning":"保持;仍然是","definition":"to continue in a state or place","examples":[{"en":"Please remain seated.","zh":"请继续坐好。"},{"en":"The cause remains unknown.","zh":"原因仍不清楚。"}]},{"pos":"v.","meaning":"剩余;遗留","definition":"to be left after others have gone","examples":[{"en":"Only three tickets remain.","zh":"只剩三张票。"},{"en":"Much work remains to be done.","zh":"仍有许多工作待完成。"}]},{"pos":"n.","meaning":"残余;遗迹（复数 remains）","definition":"parts left after most has disappeared","examples":[{"en":"We explored the remains of a Roman fort.","zh":"我们探索了罗马堡垒的遗迹。"},{"en":"The remains of dinner lay on the table.","zh":"晚餐残余留在桌上。"}]},{"pos":"n.","meaning":"遗体;遗骸（复数 remains）","definition":"the body of a dead person or animal","examples":[{"en":"The remains were returned to the family.","zh":"遗体交还给了家属。"},{"en":"Archaeologists uncovered human remains.","zh":"考古学家发现了人类遗骸。"}]}],"remark":[{"pos":"v.","meaning":"评论；说起","definition":"to say something as a comment","examples":[{"en":"She remarked that the room was cold.","zh":"她说房间很冷。"},{"en":"He remarked on the unusual design.","zh":"他评论了这个不寻常的设计。"}]},{"pos":"v.","meaning":"注意到；察觉（正式）","definition":"to notice something","examples":[{"en":"The traveller remarked the village's unusual layout.","zh":"旅行者注意到村庄不寻常的布局。"},{"en":"She remarked a change in his manner.","zh":"她注意到他的举止变了。"}]},{"pos":"n.","meaning":"评论；评语；附注","definition":"a spoken or written comment","examples":[{"en":"His remark caused laughter.","zh":"他的话引起了笑声。"},{"en":"The editor added a brief remark.","zh":"编辑加了一条简短附注。"}]}],"remarkable":[{"pos":"adj.","meaning":"非凡的；显著的；引人注目的","definition":"Unusual enough to deserve attention or admiration.","examples":[{"en":"She made a remarkable recovery.","zh":"她恢复得十分惊人。"},{"en":"The two paintings show a remarkable similarity.","zh":"这两幅画有着惊人的相似之处。"}]}],"remedy":[{"pos":"n.","meaning":"疗法;药物","definition":"a treatment for an illness or problem","examples":[{"en":"She asked about remedies for the cough.","zh":"她询问了治疗咳嗽的办法。"},{"en":"The museum displays old herbal remedies.","zh":"博物馆展出古老草药制剂。"}]},{"pos":"n.","meaning":"补救办法","definition":"a way to correct a wrong situation","examples":[{"en":"There is no easy remedy for the shortage.","zh":"短缺没有简单的解决办法。"},{"en":"The court considered an appropriate remedy.","zh":"法院考虑了适当救济措施。"}]},{"pos":"v.","meaning":"纠正;补救;医治","definition":"to put right something wrong","examples":[{"en":"We must remedy the design flaw.","zh":"我们必须补救设计缺陷。"},{"en":"Extra tutoring remedied the gaps in his knowledge.","zh":"额外辅导弥补了他的知识缺口。"}]}],"remind":[{"pos":"v.","meaning":"提醒；使想起","definition":"to cause someone to remember","examples":[{"en":"Please remind me to call.","zh":"请提醒我打电话。"},{"en":"The smell reminded her of home.","zh":"气味让她想起家。"}]}],"remote":[{"pos":"adj.","meaning":"远程的；远距离操作的","definition":"Done or controlled from a distance.","examples":[{"en":"Remote working reduces the need to commute.","zh":"远程工作减少了通勤需求。"},{"en":"Remote access allows staff to use office files from home.","zh":"远程访问使员工能够在家使用办公文件。"}]},{"pos":"adj.","meaning":"偏远的；遥远的","definition":"Far away from populated or familiar places.","examples":[{"en":"People in remote villages may lack reliable internet.","zh":"偏远村庄的人们可能缺乏可靠的互联网。"},{"en":"The expedition reached a remote island.","zh":"探险队到达了一座偏远岛屿。"}]},{"pos":"adj.","meaning":"久远的；遥远的（时间）","definition":"Far away in time.","examples":[{"en":"The custom began in the remote past.","zh":"这种习俗始于遥远的过去。"},{"en":"They imagined a city in the remote future.","zh":"他们想象了一座遥远未来的城市。"}]},{"pos":"adj.","meaning":"关系疏远的；关联很小的","definition":"Only weakly connected or related.","examples":[{"en":"He is a remote relative whom I have never met.","zh":"他是我从未见过的一位远亲。"},{"en":"The theory has only a remote connection with the evidence.","zh":"这个理论与证据只有微弱联系。"}]},{"pos":"adj.","meaning":"微乎其微的；极小的","definition":"Very unlikely or slight.","examples":[{"en":"There is a remote chance of finding the original letter.","zh":"找到原信的可能性微乎其微。"},{"en":"The risk seemed remote at the time.","zh":"当时风险似乎极小。"}]},{"pos":"adj.","meaning":"冷淡的；疏远的；孤高的","definition":"Emotionally distant and difficult to know.","examples":[{"en":"Her manner became remote after the argument.","zh":"争吵后，她的态度变得冷淡。"},{"en":"The director seemed remote from the concerns of ordinary staff.","zh":"主管似乎与普通员工的关切疏离。"}]}],"removal":[{"pos":"n.","meaning":"移除;除去","definition":"the act of taking something away","examples":[{"en":"The procedure involves the removal of damaged material.","zh":"过程涉及去除受损材料。"},{"en":"Snow removal began before dawn.","zh":"天亮前开始清雪。"}]},{"pos":"n.","meaning":"免职;撤职","definition":"the dismissal of someone from a position","examples":[{"en":"The scandal led to his removal from office.","zh":"丑闻导致他被免职。"},{"en":"The board approved the director's removal.","zh":"董事会批准撤换主管。"}]},{"pos":"n.","meaning":"搬迁;搬家","definition":"the process of moving possessions to another place","examples":[{"en":"A removal company packed our furniture.","zh":"搬家公司打包了我们的家具。"},{"en":"The office removal took all weekend.","zh":"办公室搬迁花了整个周末。"}]}],"remove":[{"pos":"v.","meaning":"移走；取下；消除","definition":"to take away or get rid of something","examples":[{"en":"Remove the lid carefully.","zh":"小心取下盖子。"},{"en":"The filter removes dust.","zh":"过滤器去除灰尘。"}]},{"pos":"v.","meaning":"免职；解除职务","definition":"to dismiss someone from a position","examples":[{"en":"The board removed the director.","zh":"董事会免除了主管职务。"},{"en":"He was removed from the committee.","zh":"他被解除委员会职务。"}]},{"pos":"v.","meaning":"迁移；搬迁（正式旧用）","definition":"to move to another place","examples":[{"en":"The family removed to a larger house.","zh":"一家人搬到了更大的房子。"},{"en":"The business removed from the old premises.","zh":"企业搬离了旧址。"}]},{"pos":"n.","meaning":"距离；间隔","definition":"a degree of separation","examples":[{"en":"She observed the events at one remove.","zh":"她隔着一层间接观察这些事件。"},{"en":"The account is several removes from the original source.","zh":"这份叙述与最初来源相隔了几层转述。"}]}],"remuneration":[{"pos":"n.","meaning":"报酬；酬金","definition":"Payment for work or services.","examples":[{"en":"The contract specifies the consultant's remuneration.","zh":"合同规定了顾问的报酬。"},{"en":"The position offers reasonable remuneration and flexible hours.","zh":"这个职位提供合理报酬和弹性工时。"}]}],"renaissance":[{"pos":"n.","meaning":"文艺复兴;文艺复兴时期","definition":"the European cultural revival associated with the fourteenth to sixteenth centuries","examples":[{"en":"The course explores Renaissance painting.","zh":"课程探索文艺复兴绘画。"},{"en":"Printing transformed learning during the Renaissance.","zh":"印刷术改变了文艺复兴时期的学习。"}]},{"pos":"n.","meaning":"复兴;新生","definition":"a renewed period of activity or popularity","examples":[{"en":"The town experienced a cultural renaissance.","zh":"小镇经历了文化复兴。"},{"en":"Traditional crafts are enjoying a renaissance.","zh":"传统工艺正在复兴。"}]}],"render":[{"pos":"v.","meaning":"使得；使成为","definition":"to cause someone or something to be in a state","examples":[{"en":"The storm rendered the road impassable.","zh":"风暴使道路无法通行。"},{"en":"The error rendered the results unreliable.","zh":"错误使结果不可靠。"}]},{"pos":"v.","meaning":"提供；给予；回报","definition":"to give a service or assistance","examples":[{"en":"The volunteers rendered valuable assistance.","zh":"志愿者提供了宝贵帮助。"},{"en":"The ceremony honoured services rendered to the community.","zh":"仪式表彰了为社区作出的服务。"}]},{"pos":"v.","meaning":"呈递；提交","definition":"to formally present a document or decision","examples":[{"en":"The accountant rendered a detailed statement.","zh":"会计提交了详细报表。"},{"en":"The court rendered its decision.","zh":"法院作出了裁决。"}]},{"pos":"v.","meaning":"表现；演绎；表演","definition":"to express or represent artistically","examples":[{"en":"The artist rendered the scene in charcoal.","zh":"艺术家用炭笔表现了场景。"},{"en":"The choir rendered the song beautifully.","zh":"合唱团优美地演绎了歌曲。"}]},{"pos":"v.","meaning":"翻译","definition":"to express in another language","examples":[{"en":"The poem was rendered into English.","zh":"诗被译成了英语。"},{"en":"She rendered the phrase more naturally.","zh":"她把短语译得更自然。"}]}],"rendition":[{"pos":"n.","meaning":"演绎；表演；演唱","definition":"A particular performance of music or a dramatic work.","examples":[{"en":"Her rendition of the folk song moved the audience.","zh":"她对这首民歌的演绎感动了观众。"},{"en":"The actor gave a lively rendition of the monologue.","zh":"演员生动地表演了这段独白。"}]},{"pos":"n.","meaning":"翻译；译文","definition":"A translation or particular wording of a text.","examples":[{"en":"The new rendition preserves the poem's simple language.","zh":"这个新译本保留了诗歌质朴的语言。"},{"en":"We compared two English renditions of the passage.","zh":"我们比较了这段文字的两个英文译本。"}]},{"pos":"n.","meaning":"描绘；视觉再现","definition":"A representation of something in visual form.","examples":[{"en":"The architect presented a digital rendition of the building.","zh":"建筑师展示了大楼的数字效果图。"},{"en":"The painting is a vivid rendition of the crowded market.","zh":"这幅画生动地再现了拥挤的市场。"}]}],"renew":[{"pos":"v.","meaning":"重新开始;恢复;更新","definition":"to begin again or restore strength or condition","examples":[{"en":"They renewed their efforts after the setback.","zh":"受挫后他们重新努力。"},{"en":"Fresh investment renewed the town's economy.","zh":"新投资使小镇经济恢复活力。"}]},{"pos":"v.","meaning":"续期;续借","definition":"to extend the period of validity or use","examples":[{"en":"You can renew the library book online.","zh":"你可以在线续借图书馆的书。"},{"en":"She renewed her passport before travelling.","zh":"旅行前她更新了护照。"}]}],"renewable":[{"pos":"adj.","meaning":"可再生的","definition":"able to be naturally replaced","examples":[{"en":"Wind is a renewable source of energy.","zh":"风是一种可再生能源。"},{"en":"The country is investing in renewable power.","zh":"该国正在投资可再生能源发电。"},{"en":"Renewable resources can be replaced naturally over time.","zh":"可再生资源能随时间自然补充。"}]},{"pos":"adj.","meaning":"可续期的；可延长有效期的","definition":"able to have its period of validity extended","examples":[{"en":"The contract is renewable annually.","zh":"合同可每年续期。"},{"en":"She obtained a renewable permit.","zh":"她获得了可续期的许可证。"}]}],"renewal":[{"pos":"n.","meaning":"更新；恢复；复兴；重新开始","definition":"The process of making something active, new, or strong again.","examples":[{"en":"The project supports the renewal of the old town centre.","zh":"项目支持旧城中心的更新。"},{"en":"Spring brought a sense of renewal.","zh":"春天带来了焕然一新的感觉。"}]},{"pos":"n.","meaning":"续期；续签；重申","definition":"The extension or repetition of an agreement, commitment, or validity period.","examples":[{"en":"Your membership is due for renewal.","zh":"你的会员资格该续期了。"},{"en":"The ceremony included a renewal of their vows.","zh":"仪式包括重申他们的誓言。"}]}],"renovate":[{"pos":"v.","meaning":"翻新；修缮","definition":"to repair and improve an old building","examples":[{"en":"The council will renovate the old library.","zh":"地方议会将翻新旧图书馆。"},{"en":"It may cost less to renovate than to rebuild.","zh":"翻新可能比重建成本更低。"},{"en":"They hope to renovate the house while preserving its character.","zh":"他们希望在保留房屋特色的同时进行翻新。"}]}],"rent":[{"pos":"v.","meaning":"租用；出租","definition":"to use or provide property for payment","examples":[{"en":"We rented a small flat.","zh":"我们租了一套小公寓。"},{"en":"She rents her spare room to students.","zh":"她把空房间租给学生。"}]},{"pos":"n.","meaning":"租金","definition":"payment for using property","examples":[{"en":"The monthly rent includes heating.","zh":"月租包含暖气费。"},{"en":"They paid the rent on time.","zh":"他们按时付了租金。"}]}],"rental":[{"pos":"n.","meaning":"租金；租赁费用","definition":"The amount paid to use something temporarily.","examples":[{"en":"The monthly rental includes heating.","zh":"月租包含取暖费。"},{"en":"Equipment rental was the largest expense.","zh":"设备租金是最大的开支。"}]},{"pos":"n.","meaning":"租赁；出租","definition":"The act or business of renting something.","examples":[{"en":"Car rental is available at the airport.","zh":"机场提供租车服务。"},{"en":"The agreement covers the rental of two rooms.","zh":"协议涉及两间房屋的租赁。"}]},{"pos":"adj.","meaning":"租用的；出租的","definition":"Available or used under a renting arrangement.","examples":[{"en":"They moved into a rental apartment.","zh":"他们搬进了一套出租公寓。"},{"en":"The rental car was waiting outside.","zh":"租来的汽车正在外面等候。"}]}],"reorient":[{"pos":"v.","meaning":"重新定位;调整方向;使重新适应","definition":"to change direction or focus","examples":[{"en":"The company reoriented its strategy toward local markets.","zh":"公司调整战略，转向本地市场。"},{"en":"After checking the map, we reoriented ourselves.","zh":"查看地图后，我们重新辨明方向。"}]}],"repack":[{"pos":"v.","meaning":"重新打包；重新装填","definition":"to pack something again","examples":[{"en":"She repacked her suitcase to reduce its weight.","zh":"她重新整理行李箱以减轻重量。"},{"en":"The mechanic repacked the bearing with grease.","zh":"技工给轴承重新填入润滑脂。"}]}],"repaint":[{"pos":"v.","meaning":"重新涂漆；重画","definition":"To paint something again.","examples":[{"en":"We repainted the kitchen pale blue.","zh":"我们把厨房重新漆成浅蓝色。"},{"en":"The artist repainted the cloudy sky.","zh":"画家重画了阴云密布的天空。"}]}],"repair":[{"pos":"v.","meaning":"修理；修复","definition":"to restore something damaged to a working condition","examples":[{"en":"A mechanic will repair the brakes tomorrow.","zh":"机械师明天会修理刹车。"},{"en":"We need to repair the roof before winter arrives.","zh":"我们需要在冬天来临前修好屋顶。"}]},{"pos":"v.","meaning":"补救；修复关系或损害","definition":"to put right harm or damage to a relationship or situation","examples":[{"en":"An honest apology may help repair their friendship.","zh":"真诚的道歉可能有助于修复他们的友谊。"},{"en":"The company is trying to repair its damaged reputation.","zh":"该公司正努力挽回受损的声誉。"}]},{"pos":"n.","meaning":"修理；维修","definition":"the work or process of fixing something damaged","examples":[{"en":"The repair took longer than the engineer expected.","zh":"这次维修花的时间比工程师预期更长。"},{"en":"The bridge is closed for urgent repair.","zh":"这座桥因紧急维修而封闭。"}]}],"repatriate":[{"pos":"v.","meaning":"遣返回国;返回祖国","definition":"to send or bring someone back to their home country","examples":[{"en":"The stranded tourists were repatriated.","zh":"滞留游客被送回国。"},{"en":"The agreement allowed refugees to repatriate voluntarily.","zh":"协议允许难民自愿返回祖国。"}]}],"repay":[{"pos":"v.","meaning":"偿还；归还","definition":"to pay back borrowed money","examples":[{"en":"He repaid the loan early.","zh":"他提前还清贷款。"},{"en":"The company repaid its debts.","zh":"公司偿还了债务。"}]},{"pos":"v.","meaning":"报答；回报","definition":"to reward someone's help or effort","examples":[{"en":"She repaid their kindness with practical help.","zh":"她以实际帮助回报他们的善意。"},{"en":"The effort was repaid by excellent results.","zh":"努力得到了优异成绩的回报。"}]}],"repel":[{"pos":"v.","meaning":"击退；驱逐；排斥","definition":"To drive something away or push it back.","examples":[{"en":"The defenders repelled the attack.","zh":"守军击退了进攻。"},{"en":"The coating repels water.","zh":"这种涂层能够防水。"}]},{"pos":"v.","meaning":"使反感；使厌恶","definition":"To cause strong dislike or disgust.","examples":[{"en":"His cruelty repelled the audience.","zh":"他的残酷让观众反感。"},{"en":"The unpleasant smell repelled potential customers.","zh":"难闻的气味赶跑了潜在顾客。"}]}],"repertoire":[{"pos":"n.","meaning":"常备剧目;全部节目;技能储备","definition":"the works or skills someone can perform","examples":[{"en":"The orchestra expanded its repertoire.","zh":"乐团扩大了演奏曲目。"},{"en":"Her repertoire includes several comic roles.","zh":"她的表演角色包括几个喜剧人物。"}]}],"replace":[{"pos":"v.","meaning":"代替；更换","definition":"to take the place of something or put a new item in its place","examples":[{"en":"We replaced the broken window.","zh":"我们更换了破窗户。"},{"en":"The new system replaces paper forms.","zh":"新系统替代纸质表格。"}]},{"pos":"v.","meaning":"把……放回原处","definition":"to put something back where it was","examples":[{"en":"Replace the lid after use.","zh":"使用后把盖子盖回去。"},{"en":"She replaced the book on the shelf.","zh":"她把书放回架上。"}]}],"replacement":[{"pos":"n.","meaning":"替换品；替代品","definition":"something used instead of another thing","examples":[{"en":"The shop offered a replacement for the faulty kettle.","zh":"商店为有故障的水壶提供了替换品。"},{"en":"We are waiting for a replacement part.","zh":"我们正在等待替换零件。"},{"en":"A replacement card will arrive within five days.","zh":"补发的卡片将在五天内送达。"}]}],"replenish":[{"pos":"v.","meaning":"补充;重新装满","definition":"to fill again after use","examples":[{"en":"We stopped to replenish our water supply.","zh":"我们停下来补充饮水。"},{"en":"The assistant replenished the empty shelves.","zh":"助理补满了空货架。"}]}],"replicate":[{"pos":"v.","meaning":"复制；重复；复现","definition":"to make an exact copy or repeat a result","examples":[{"en":"The laboratory replicated the experiment.","zh":"实验室重复了实验。"},{"en":"The virus replicates inside host cells.","zh":"病毒在宿主细胞内复制。"}]}],"represent":[{"pos":"v.","meaning":"代表；代理","definition":"To speak or act on behalf of someone.","examples":[{"en":"She represents the workers in negotiations.","zh":"她代表工人参加谈判。"},{"en":"The athlete represented her country at the games.","zh":"这位运动员代表国家参加运动会。"}]},{"pos":"v.","meaning":"表示；象征","definition":"To stand for a meaning, amount, or idea.","examples":[{"en":"Each dot represents one household.","zh":"每个点代表一户家庭。"},{"en":"The increase represents a major change in demand.","zh":"这次增长意味着需求发生了重大变化。"}]},{"pos":"v.","meaning":"描绘；表现；描述","definition":"To show or describe something in a particular way.","examples":[{"en":"The painting represents a winter market.","zh":"这幅画描绘了冬日市场。"},{"en":"The report represents the situation as stable.","zh":"报告将局势描述为稳定。"}]}],"representative":[{"pos":"n.","meaning":"代表;代理人","definition":"someone acting on behalf of others","examples":[{"en":"Each class elected a representative.","zh":"每班选出一位代表。"},{"en":"A sales representative visited the shop.","zh":"一位销售代表拜访了商店。"}]},{"pos":"adj.","meaning":"典型的;有代表性的","definition":"typical of a larger group","examples":[{"en":"The survey used a representative sample.","zh":"调查使用了有代表性的样本。"},{"en":"This painting is representative of her early work.","zh":"这幅画代表她早期创作风格。"}]}],"reproduce":[{"pos":"v.","meaning":"繁殖；生育","definition":"to produce offspring","examples":[{"en":"These plants reproduce by seed.","zh":"这些植物通过种子繁殖。"},{"en":"The species reproduces in spring.","zh":"这个物种在春季繁殖。"}]},{"pos":"v.","meaning":"复制；再现","definition":"to make a copy or recreate something","examples":[{"en":"The book reproduces several old maps.","zh":"书中复制了几幅旧地图。"},{"en":"She reproduced the melody from memory.","zh":"她凭记忆再现了旋律。"}]}],"reptile":[{"pos":"n.","meaning":"爬行动物","definition":"A cold-blooded vertebrate such as a snake, lizard, or turtle.","examples":[{"en":"The zoo has a separate house for reptiles.","zh":"动物园为爬行动物设有独立展馆。"},{"en":"Many reptiles warm themselves in the sun.","zh":"许多爬行动物晒太阳来提高体温。"}]},{"pos":"n.","meaning":"卑鄙的人（贬义）","definition":"A contemptible or deceitful person.","examples":[{"en":"In the novel, she calls the betrayer a reptile.","zh":"小说中，她把背叛者骂作卑鄙小人。"},{"en":"He regarded the dishonest official as a reptile.","zh":"他把那个不诚实的官员视为卑鄙之徒。"}]}],"reputable":[{"pos":"adj.","meaning":"声誉好的;值得信赖的","definition":"known to be honest or reliable","examples":[{"en":"Buy equipment from a reputable supplier.","zh":"从信誉良好的供应商购买设备。"},{"en":"The article appeared in a reputable journal.","zh":"文章发表在声誉良好的期刊上。"}]}],"reputation":[{"pos":"n.","meaning":"名誉；名声","definition":"the opinion others generally hold about someone or something","examples":[{"en":"The restaurant has a good reputation.","zh":"餐馆声誉很好。"},{"en":"Careless work damaged his reputation.","zh":"粗心的工作损害了他的名声。"}]}],"request":[{"pos":"v.","meaning":"请求","definition":"to ask for something","examples":[{"en":"I would like to request a copy of the contract.","zh":"我想请求提供一份合同副本。"},{"en":"Customers can request a later delivery date.","zh":"顾客可以要求延后送货日期。"},{"en":"Please request assistance if you need help boarding.","zh":"如果登车需要帮助，请申请协助。"}]},{"pos":"n.","meaning":"请求；要求","definition":"An act of asking for something.","examples":[{"en":"The office received a request for additional information.","zh":"办公室收到了一项补充信息的请求。"},{"en":"We approved her request for leave.","zh":"我们批准了她的请假申请。"}]}],"require":[{"pos":"v.","meaning":"需要","definition":"to need something","examples":[{"en":"The plant requires plenty of light.","zh":"这种植物需要充足光照。"},{"en":"Repairing the roof requires specialist skills.","zh":"修理屋顶需要专业技能。"}]},{"pos":"v.","meaning":"要求;规定","definition":"to demand something as a rule or obligation","examples":[{"en":"The law requires drivers to wear seat belts.","zh":"法律要求驾驶员系安全带。"},{"en":"All applicants are required to provide identification.","zh":"所有申请者都须提供身份证明。"}]}],"requirement":[{"pos":"n.","meaning":"要求；必要条件；所需之物","definition":"something necessary or officially demanded","examples":[{"en":"Experience is a basic requirement.","zh":"经验是基本要求。"},{"en":"The plan meets the school's space requirements.","zh":"计划满足学校的空间需求。"}]}],"requisite":[{"pos":"adj.","meaning":"必要的；必需的","definition":"Required for a particular purpose.","examples":[{"en":"Applicants must have the requisite qualifications.","zh":"申请者必须具备所需资格。"},{"en":"The team lacked the requisite equipment.","zh":"团队缺少必需的设备。"}]},{"pos":"n.","meaning":"必需品；必要条件；要素","definition":"Something necessary for a purpose.","examples":[{"en":"Patience is a requisite for this work.","zh":"耐心是做这项工作的必要条件。"},{"en":"The shop supplies artists with their basic requisites.","zh":"商店向艺术家供应基本必需品。"}]}],"requisition":[{"pos":"n.","meaning":"正式请求;征用令","definition":"an official demand for supplies or property","examples":[{"en":"She submitted a requisition for new equipment.","zh":"她提交了新设备申请单。"},{"en":"The owner received a requisition for his vehicles.","zh":"车主收到征用车辆的命令。"}]},{"pos":"v.","meaning":"正式要求;征用","definition":"to officially demand or take something for use","examples":[{"en":"The army requisitioned the hotel.","zh":"军队征用了酒店。"},{"en":"The laboratory requisitioned additional supplies.","zh":"实验室正式申请额外物资。"}]}],"rescue":[{"pos":"v.","meaning":"营救；救援","definition":"to save from danger","examples":[{"en":"Firefighters rescued the trapped residents.","zh":"消防员救出了被困居民。"},{"en":"The team rescued an injured bird.","zh":"团队救助了一只受伤的鸟。"}]},{"pos":"n.","meaning":"营救；救援行动","definition":"the act of saving from danger","examples":[{"en":"The rescue took several hours.","zh":"救援花了几个小时。"},{"en":"Help arrived just in time for the rescue.","zh":"援助及时赶到参与营救。"}]}],"research":[{"pos":"n.","meaning":"研究","definition":"careful study to discover information","examples":[{"en":"More research is needed before drawing a conclusion.","zh":"在得出结论前还需要更多研究。"},{"en":"The university conducts research into renewable energy.","zh":"这所大学研究可再生能源。"},{"en":"Recent research suggests that sleep affects memory.","zh":"近期研究表明睡眠影响记忆。"}]}],"resemble":[{"pos":"v.","meaning":"像;与……相似","definition":"to look or be like something","examples":[{"en":"The child resembles her grandmother.","zh":"孩子长得像祖母。"},{"en":"The pattern resembles a fern leaf.","zh":"图案像蕨类叶片。"}]}],"resent":[{"pos":"v.","meaning":"愤恨；对……感到气愤","definition":"to feel anger about unfair treatment","examples":[{"en":"She resented being excluded.","zh":"她对被排除在外感到气愤。"},{"en":"He resented the unnecessary interference.","zh":"他对不必要的干涉心怀不满。"}]}],"reservation":[{"pos":"n.","meaning":"预订","definition":"an arrangement to keep a room or seat for someone","examples":[{"en":"I would like to confirm my hotel reservation.","zh":"我想确认酒店预订。"},{"en":"You need a reservation to use the meeting room.","zh":"使用会议室需要预订。"},{"en":"Please give us your reservation number.","zh":"请提供你的预订编号。"}]},{"pos":"n.","meaning":"保留意见；疑虑","definition":"A doubt that prevents complete agreement.","examples":[{"en":"She expressed reservations about the cost.","zh":"她对成本表示了疑虑。"},{"en":"I support the idea with some reservations.","zh":"我支持这个想法，但有所保留。"}]}],"reserve":[{"pos":"v.","meaning":"预订;预约","definition":"to arrange to keep something for future use","examples":[{"en":"We reserved a table by the window.","zh":"我们预订了靠窗桌位。"},{"en":"Reserve your seat before Friday.","zh":"周五前预订座位。"}]},{"pos":"v.","meaning":"保留;储备","definition":"to keep something for a particular purpose","examples":[{"en":"Reserve some funds for emergencies.","zh":"留一些资金应急。"},{"en":"She reserved judgement until she heard both sides.","zh":"听取双方意见前她保留判断。"}]},{"pos":"n.","meaning":"储备;储备量","definition":"a supply kept for future need","examples":[{"en":"The reservoir holds a large water reserve.","zh":"水库储存大量水。"},{"en":"The country drew on its fuel reserves.","zh":"国家动用了燃料储备。"}]},{"pos":"n.","meaning":"自然保护区","definition":"an area protected for wildlife or nature","examples":[{"en":"The reserve protects rare birds.","zh":"保护区保护珍稀鸟类。"},{"en":"Visitors must stay on paths in the reserve.","zh":"游客在保护区必须沿路行走。"}]}],"reserved":[{"pos":"adj.","meaning":"内向的；矜持的；不多话的","definition":"not readily showing feelings or speaking much","examples":[{"en":"He was quiet and reserved.","zh":"他安静内敛。"},{"en":"Her reserved manner hid a warm personality.","zh":"她矜持的举止掩盖了热情的个性。"}]},{"pos":"adj.","meaning":"预订的；保留的","definition":"kept for a particular person or purpose","examples":[{"en":"These seats are reserved.","zh":"这些座位已被预订。"},{"en":"The funds are reserved for repairs.","zh":"资金留作维修之用。"}]}],"residence":[{"pos":"n.","meaning":"住宅；住处","definition":"A place where someone lives.","examples":[{"en":"The building was once a private residence.","zh":"这栋楼曾是一处私人住宅。"},{"en":"Please state your current place of residence.","zh":"请填写你目前的居住地址。"}]},{"pos":"n.","meaning":"居住；居留","definition":"The act or state of living in a place.","examples":[{"en":"He took up residence in the old farmhouse.","zh":"他住进了旧农舍。"},{"en":"The application requires proof of residence.","zh":"申请需要提供居住证明。"}]}],"resident":[{"pos":"n.","meaning":"居民","definition":"a person who lives in a particular place","examples":[{"en":"Every resident can vote on the proposal.","zh":"每位居民都可以就该提议投票。"},{"en":"A local resident reported the broken street light.","zh":"一位当地居民报告路灯坏了。"},{"en":"The scheme gives each resident access to a shared garden.","zh":"该方案让每位居民都能使用公共花园。"}]},{"pos":"adj.","meaning":"居住的;常驻的","definition":"living or based in a particular place","examples":[{"en":"She is resident in the village.","zh":"她住在村里。"},{"en":"A resident engineer supervises the site.","zh":"一位常驻工程师监督工地。"}]}],"residential":[{"pos":"adj.","meaning":"住宅的；居住用的","definition":"used mainly for homes","examples":[{"en":"The factory is far from residential areas.","zh":"工厂远离住宅区。"},{"en":"Heavy traffic has increased noise in this residential street.","zh":"繁忙的交通使这条住宅街道更吵了。"},{"en":"The council approved a new residential development.","zh":"地方议会批准了一个新的住宅开发项目。"}]},{"pos":"adj.","meaning":"寄宿的；提供住宿的","definition":"requiring or providing accommodation on site","examples":[{"en":"She attended a residential training course.","zh":"她参加了寄宿式培训课程。"},{"en":"The college offers residential places for students.","zh":"学院向学生提供住宿名额。"}]}],"resign":[{"pos":"v.","meaning":"辞职；辞去","definition":"To formally leave a job or position.","examples":[{"en":"The director resigned after ten years.","zh":"这位董事任职十年后辞职了。"},{"en":"She resigned her post to care for her family.","zh":"她辞去了职务，以便照顾家人。"}]},{"pos":"v.","meaning":"放弃；顺从接受（resign oneself to）","definition":"To give something up or accept an unwanted situation.","examples":[{"en":"He resigned his claim to the title.","zh":"他放弃了对头衔的要求。"},{"en":"We resigned ourselves to a long wait.","zh":"我们无奈地接受了长时间等待。"}]}],"resilience":[{"pos":"n.","meaning":"韧性;恢复力;适应力","definition":"the ability to recover from difficulty","examples":[{"en":"The community showed resilience after the flood.","zh":"社区在洪灾后展现了恢复力。"},{"en":"Supportive friendships can strengthen resilience.","zh":"互相支持的友谊可以增强抗挫力。"}]},{"pos":"n.","meaning":"弹性;回弹能力","definition":"the ability of a material to regain shape","examples":[{"en":"The foam's resilience makes it suitable for cushions.","zh":"泡沫的回弹能力使其适合作靠垫。"},{"en":"Repeated compression tested the rubber's resilience.","zh":"反复压缩测试了橡胶弹性。"}]}],"resist":[{"pos":"v.","meaning":"抵抗；抵制","definition":"to oppose or refuse to accept something","examples":[{"en":"Residents resisted the proposed closure.","zh":"居民抵制拟议的关闭。"},{"en":"She resisted the temptation to interrupt.","zh":"她忍住了打断的冲动。"}]},{"pos":"v.","meaning":"耐受；抗……","definition":"to remain unaffected or undamaged by something","examples":[{"en":"The material resists heat.","zh":"这种材料耐热。"},{"en":"These plants resist several common diseases.","zh":"这些植物能抵抗几种常见病害。"}]}],"resistance":[{"pos":"n.","meaning":"反抗；抵制","definition":"Opposition to an action, force, or change.","examples":[{"en":"The proposal met strong resistance.","zh":"这项提案遭到了强烈抵制。"},{"en":"The defenders offered little resistance.","zh":"守军几乎没有抵抗。"}]},{"pos":"n.","meaning":"抵抗力；耐受性","definition":"The ability to withstand damage, disease, or another effect.","examples":[{"en":"The plants were selected for their resistance to drought.","zh":"这些植物因耐旱性而被选中。"},{"en":"The coating improves the metal's resistance to corrosion.","zh":"涂层提高了金属的耐腐蚀性。"}]},{"pos":"n.","meaning":"阻力；电阻","definition":"A force or property that opposes movement or electrical current.","examples":[{"en":"Air resistance slows the falling object.","zh":"空气阻力减慢了下落物体的速度。"},{"en":"The technician measured the wire's electrical resistance.","zh":"技术人员测量了电线的电阻。"}]}],"resistant":[{"pos":"adj.","meaning":"抵抗的;有抵抗力的;耐受的","definition":"able or unwilling to be affected by something","examples":[{"en":"The coating is resistant to heat.","zh":"涂层耐热。"},{"en":"Some staff were resistant to change.","zh":"一些员工抗拒变化。"}]}],"resit":[{"pos":"v.","meaning":"重新参加考试；补考","definition":"to take an examination again","examples":[{"en":"She will resit the exam in June.","zh":"她将在六月补考。"},{"en":"He had to resit mathematics.","zh":"他不得不补考数学。"}],"ipa":"/riːˈsɪt/"},{"pos":"n.","meaning":"补考；重考","definition":"an examination taken again","examples":[{"en":"The resit takes place next month.","zh":"补考下个月举行。"},{"en":"Students can register for a resit.","zh":"学生可以报名补考。"}],"ipa":"/ˈriːsɪt/"}],"resolve":[{"pos":"v.","meaning":"解决","definition":"to find a solution to a problem","examples":[{"en":"We hope to resolve the problem quickly.","zh":"我们希望迅速解决这个问题。"},{"en":"The manager helped resolve the dispute.","zh":"经理帮助解决了争议。"},{"en":"Please contact support so we can resolve your complaint.","zh":"请联系客服，以便我们处理你的投诉。"}]},{"pos":"v.","meaning":"决定；决意","definition":"To make a firm decision.","examples":[{"en":"She resolved to finish the course.","zh":"她下定决心完成课程。"},{"en":"The committee resolved that the repairs should begin immediately.","zh":"委员会决定维修应立即开始。"}]},{"pos":"v.","meaning":"分解；解析","definition":"To separate something into its components or make its details clear.","examples":[{"en":"The prism resolves light into different colours.","zh":"棱镜把光分解成不同颜色。"},{"en":"The engineer resolved the force into horizontal and vertical components.","zh":"工程师把力分解为水平和竖直分量。"}]},{"pos":"n.","meaning":"决心；决意","definition":"Firm determination to do something.","examples":[{"en":"The setback strengthened her resolve.","zh":"挫折坚定了她的决心。"},{"en":"He showed great resolve during the difficult negotiations.","zh":"艰难谈判期间，他表现出坚定决心。"}]}],"resort":[{"pos":"n.","meaning":"度假胜地","definition":"a place popular for holidays","examples":[{"en":"They stayed at a coastal resort.","zh":"他们住在海滨度假村。"},{"en":"The ski resort closes in summer.","zh":"滑雪度假地夏季关闭。"}]},{"pos":"n.","meaning":"求助;可用手段","definition":"a person or action turned to for help","examples":[{"en":"Legal action was a last resort.","zh":"采取法律行动是最后手段。"},{"en":"The clinic became their only resort.","zh":"诊所成为他们唯一能求助的地方。"}]},{"pos":"v.","meaning":"诉诸;求助于","definition":"to turn to a method when other options fail","examples":[{"en":"They resorted to borrowing money.","zh":"他们只得借钱。"},{"en":"We should not resort to threats.","zh":"我们不应诉诸威胁。"}]}],"resource":[{"pos":"n.","meaning":"资源","definition":"something useful that can meet a need","examples":[{"en":"Fresh water is a valuable natural resource.","zh":"淡水是一种宝贵的自然资源。"},{"en":"The library is a useful resource for job seekers.","zh":"图书馆是求职者的实用资源。"},{"en":"We should manage this limited resource carefully.","zh":"我们应该谨慎管理这种有限资源。"}]},{"pos":"n.","meaning":"应变能力；智谋","definition":"skill in finding ways to deal with difficulties","examples":[{"en":"She is a person of considerable resource.","zh":"她是个足智多谋的人。"},{"en":"The emergency tested his resource and courage.","zh":"紧急情况考验了他的应变能力和勇气。"}]},{"pos":"n.","meaning":"应付办法；可依靠的手段","definition":"a means of dealing with a problem","examples":[{"en":"Their last resource was to ask neighbours for help.","zh":"他们最后的办法是向邻居求助。"},{"en":"The team drew on every available resource to solve the problem.","zh":"团队动用了每一种可用手段解决问题。"}]},{"pos":"n.","meaning":"财力；资金（常用复数）","definition":"money or assets available to a person or organisation","examples":[{"en":"The charity lacks the financial resources to buy the building.","zh":"这家慈善机构缺少购买这栋楼的财力。"},{"en":"They pooled their resources to start a small business.","zh":"他们汇集资金创办了一家小企业。"}]}],"respect":[{"pos":"v.","meaning":"尊敬；尊重","definition":"To admire someone or treat something with due consideration.","examples":[{"en":"I respect her honesty.","zh":"我敬重她的诚实。"},{"en":"Visitors should respect local customs.","zh":"游客应尊重当地风俗。"}]},{"pos":"n.","meaning":"尊敬；尊重","definition":"A feeling or expression of admiration and consideration.","examples":[{"en":"She earned the respect of her colleagues.","zh":"她赢得了同事的尊敬。"},{"en":"They listened to one another with respect.","zh":"他们互相尊重地倾听。"}]},{"pos":"n.","meaning":"方面；细节","definition":"A particular feature or point of consideration.","examples":[{"en":"The two designs differ in several respects.","zh":"这两种设计在几个方面有所不同。"},{"en":"In this respect, the new system is better.","zh":"在这方面，新系统更好。"}]}],"respond":[{"pos":"v.","meaning":"答复;回应;作出反应","definition":"to answer or react","examples":[{"en":"She responded to the email promptly.","zh":"她及时回复了邮件。"},{"en":"The plant responded well to extra light.","zh":"植物对增加光照反应良好。"}]}],"respondent":[{"pos":"n.","meaning":"回答者；受访者","definition":"a person who answers questions, especially in a survey","examples":[{"en":"Each respondent completed a questionnaire.","zh":"每位受访者填写了问卷。"},{"en":"Most respondents supported the proposal.","zh":"大多数回答者支持提案。"}]},{"pos":"n.","meaning":"被申请人；被上诉人；应诉方","definition":"a party responding to a legal application or appeal","examples":[{"en":"The respondent filed a written reply.","zh":"被申请人提交了书面答复。"},{"en":"The court heard the respondent's argument.","zh":"法院听取了被上诉人的论点。"}]}],"response":[{"pos":"n.","meaning":"回答；答复","definition":"An answer to a question or communication.","examples":[{"en":"We received no response to our email.","zh":"我们的邮件没有收到答复。"},{"en":"Her response was brief but clear.","zh":"她的回答简短但清楚。"}]},{"pos":"n.","meaning":"反应；响应","definition":"An action or feeling caused by something else.","examples":[{"en":"The new rule prompted an angry response.","zh":"新规定引发了愤怒反应。"},{"en":"The body produces a response to changes in temperature.","zh":"身体会对温度变化产生反应。"}]}],"responsibility":[{"pos":"n.","meaning":"责任；职责","definition":"a duty to deal with something","examples":[{"en":"Safety is everyone's responsibility.","zh":"安全是每个人的责任。"},{"en":"Managing the budget is my main responsibility.","zh":"管理预算是我的主要职责。"},{"en":"Parents have a responsibility to support their children.","zh":"父母有责任支持自己的孩子。"}]},{"pos":"n.","meaning":"责任心;负责的态度","definition":"the quality of being dependable and aware of one's duties","examples":[{"en":"Her sense of responsibility impressed her colleagues.","zh":"她的责任心给同事留下深刻印象。"},{"en":"The task helped him develop responsibility.","zh":"这项任务帮助他培养责任心。"}]}],"responsible":[{"pos":"adj.","meaning":"可靠的；有责任感的","definition":"trustworthy and able to make sensible decisions","examples":[{"en":"She is a responsible employee.","zh":"她是个有责任感的员工。"},{"en":"The club needs responsible volunteers.","zh":"俱乐部需要可靠的志愿者。"}]}],"restore":[{"pos":"v.","meaning":"恢复；使复位","definition":"To return something to an earlier state or position.","examples":[{"en":"The repair restored power to the village.","zh":"维修恢复了村庄供电。"},{"en":"The measures helped restore public confidence.","zh":"这些措施帮助恢复了公众信心。"}]},{"pos":"v.","meaning":"修复；整修；重建","definition":"To repair something old or damaged.","examples":[{"en":"Volunteers restored the abandoned garden.","zh":"志愿者修复了荒废的花园。"},{"en":"The painting was carefully restored.","zh":"这幅画得到了精心修复。"}]},{"pos":"v.","meaning":"归还；交还","definition":"To give something back to its owner.","examples":[{"en":"The stolen books were restored to the library.","zh":"被盗书籍归还给了图书馆。"},{"en":"The court restored the land to the family.","zh":"法院把土地归还给了这个家庭。"}]}],"restrain":[{"pos":"v.","meaning":"阻止;约束;抑制","definition":"to hold back or control","examples":[{"en":"The guard restrained the intruder.","zh":"卫兵制住了闯入者。"},{"en":"She struggled to restrain her laughter.","zh":"她努力忍住笑。"}]}],"restrict":[{"pos":"v.","meaning":"限制；约束","definition":"to limit the amount or freedom of something","examples":[{"en":"The rules restrict access to the site.","zh":"规则限制进入场地。"},{"en":"Limited funds restricted the project's scope.","zh":"资金有限限制了项目规模。"}]}],"restriction":[{"pos":"n.","meaning":"限制；约束；限制规定","definition":"A rule or condition limiting what is allowed.","examples":[{"en":"Water restrictions remain in force.","zh":"限水规定仍然有效。"},{"en":"There are restrictions on parking near the hospital.","zh":"医院附近有停车限制。"}]}],"result":[{"pos":"n.","meaning":"结果；后果","definition":"something that happens because of an action or process","examples":[{"en":"The result of the experiment surprised the whole team.","zh":"实验结果使整个团队都感到惊讶。"},{"en":"Better planning produced a much better result.","zh":"更好的规划带来了好得多的结果。"}]},{"pos":"v.","meaning":"导致；造成","definition":"to cause a particular outcome, usually followed by in","examples":[{"en":"Heavy rain may result in delays on the railway.","zh":"大雨可能导致铁路晚点。"},{"en":"Regular maintenance can result in lower repair costs.","zh":"定期维护能降低维修成本。"}]},{"pos":"v.","meaning":"由……引起；起因于","definition":"to happen as a consequence of something, usually followed by from","examples":[{"en":"These problems often result from poor communication.","zh":"这些问题往往由沟通不畅引起。"},{"en":"The improvement may result from a change in teaching methods.","zh":"这种改善可能源于教学方法的改变。"}]}],"resume":[{"pos":"v.","meaning":"重新开始;继续","definition":"to begin again after a pause","examples":[{"en":"The meeting resumed after lunch.","zh":"午饭后会议继续。"},{"en":"She resumed work after recovering.","zh":"康复后她重新工作。"}]}],"retail":[{"pos":"n.","meaning":"零售","definition":"the sale of goods directly to consumers","examples":[{"en":"She works in retail.","zh":"她从事零售业。"},{"en":"The business expanded from wholesale into retail.","zh":"企业从批发扩展到零售。"}]},{"pos":"v.","meaning":"零售；售价为","definition":"to sell directly to consumers at a stated price","examples":[{"en":"The company retails kitchen equipment.","zh":"公司零售厨房设备。"},{"en":"The book retails at twenty pounds.","zh":"这本书零售价二十英镑。"}]}],"retailer":[{"pos":"n.","meaning":"零售商；零售企业","definition":"A person or business selling goods directly to consumers.","examples":[{"en":"The retailer offers free delivery.","zh":"这家零售商提供免费送货。"},{"en":"Local retailers opposed the road closure.","zh":"当地零售商反对关闭道路。"}]},{"pos":"n.","meaning":"复述者；传播者（故事或流言的）","definition":"Someone who repeats stories or information to others.","examples":[{"en":"The columnist became a retailer of fashionable gossip.","zh":"这位专栏作家成了时髦流言的传播者。"},{"en":"Travelling merchants were retailers of news as well as goods.","zh":"旅行商人不仅出售货物，也传播消息。"}]}],"retailing":[{"pos":"n.","meaning":"零售;零售业","definition":"the business of selling goods directly to consumers","examples":[{"en":"Online retailing transformed shopping habits.","zh":"网上零售改变了购物习惯。"},{"en":"She has ten years of experience in retailing.","zh":"她有十年零售业经验。"}]}],"retain":[{"pos":"v.","meaning":"保留；保持","definition":"to keep something or continue to have it","examples":[{"en":"The house retains its original windows.","zh":"房子保留了原有窗户。"},{"en":"She retained control of the project.","zh":"她保持了对项目的控制权。"}]}],"retaliate":[{"pos":"v.","meaning":"报复；反击","definition":"To respond to an attack or injury with similar action.","examples":[{"en":"He chose to report the insult rather than retaliate.","zh":"他选择报告侮辱事件，而非报复。"},{"en":"The country threatened to retaliate with trade restrictions.","zh":"该国威胁以贸易限制进行反击。"}]}],"retire":[{"pos":"v.","meaning":"退休","definition":"to stop working at the end of a career","examples":[{"en":"He retired after forty years of teaching.","zh":"他执教四十年后退休。"},{"en":"She plans to retire next year.","zh":"她计划明年退休。"}]},{"pos":"v.","meaning":"退出;隐退;撤退","definition":"to withdraw from an activity or place","examples":[{"en":"The injured player retired from the match.","zh":"受伤选手退出比赛。"},{"en":"The army retired to a safer position.","zh":"军队撤至较安全位置。"}]}],"retrenchment":[{"pos":"n.","meaning":"削减开支；紧缩；裁减","definition":"a reduction in costs or activities","examples":[{"en":"The company announced a period of retrenchment.","zh":"公司宣布进入开支紧缩期。"},{"en":"Budget retrenchment reduced the number of programmes.","zh":"预算削减减少了项目数量。"}]}],"reunion":[{"pos":"n.","meaning":"重聚；团圆；重聚活动","definition":"A meeting of people who have been apart for some time.","examples":[{"en":"The family reunion brought three generations together.","zh":"家庭聚会使三代人团聚。"},{"en":"Their reunion after twenty years was deeply emotional.","zh":"二十年后的重聚让他们情绪激动。"}]}],"reunite":[{"pos":"v.","meaning":"重聚;重新结合","definition":"to bring or come together again","examples":[{"en":"The missing child was reunited with her parents.","zh":"走失女孩与父母团聚。"},{"en":"The old band reunited for a concert.","zh":"老乐队重聚举办音乐会。"}]}],"reveal":[{"pos":"v.","meaning":"揭示；透露；展现","definition":"to make something known or visible","examples":[{"en":"The test revealed a hidden fault.","zh":"测试发现了隐藏故障。"},{"en":"She lifted the cover to reveal the painting.","zh":"她掀开罩布，露出了画作。"}]}],"revegetate":[{"pos":"v.","meaning":"重新植被覆盖；重新种植；恢复植被","definition":"To grow vegetation again or restore plants to bare land.","examples":[{"en":"The project will revegetate the damaged hillside.","zh":"项目将恢复受损山坡的植被。"},{"en":"Bare patches began to revegetate after grazing stopped.","zh":"放牧停止后，裸地开始重新长出植物。"}]}],"revelation":[{"pos":"n.","meaning":"揭示;披露;被揭露的真相","definition":"the act of revealing or something newly revealed","examples":[{"en":"The revelation of fraud shocked investors.","zh":"欺诈行为的曝光震惊了投资者。"},{"en":"Her diary contained surprising revelations.","zh":"她的日记包含令人惊讶的新发现。"}]}],"revenue":[{"pos":"n.","meaning":"收入；营收","definition":"income received by a business or organisation","examples":[{"en":"Ticket sales provide most of the museum's revenue.","zh":"门票销售提供了博物馆的大部分收入。"},{"en":"Tourism generates revenue for local businesses.","zh":"旅游业为当地企业带来营收。"}]},{"pos":"n.","meaning":"财政收入；税收","definition":"money received by a government","examples":[{"en":"Tax revenue funds public services.","zh":"税收为公共服务提供资金。"},{"en":"The council reported a fall in revenue.","zh":"议会报告财政收入下降。"},{"en":"The government used tax revenue to fund hospitals.","zh":"政府用税收收入资助医院。"}]}],"reverse":[{"pos":"n.","meaning":"相反；反面情况","definition":"The opposite of something.","examples":[{"en":"I expected criticism, but the reverse happened.","zh":"我原以为会受到批评，结果恰恰相反。"},{"en":"The new policy produced the reverse of its intended effect.","zh":"新政策产生了与预期相反的效果。"}]},{"pos":"n.","meaning":"背面；反面","definition":"The back side of an object.","examples":[{"en":"Write your name on the reverse of the photograph.","zh":"在照片背面写上你的名字。"},{"en":"The coin has a bird on the reverse.","zh":"硬币背面有一只鸟。"}]},{"pos":"adj.","meaning":"相反的；倒转的","definition":"Going in the opposite direction or order.","examples":[{"en":"Read the numbers in reverse order.","zh":"按相反顺序读这些数字。"},{"en":"The reverse journey took longer because of traffic.","zh":"返程因堵车花了更长时间。"}]},{"pos":"v.","meaning":"颠倒；逆转；撤销","definition":"To change something to the opposite direction or outcome.","examples":[{"en":"The treatment reversed the decline in quality.","zh":"这种处理扭转了质量下降的趋势。"},{"en":"The court reversed the earlier decision.","zh":"法院撤销了先前的判决。"}]},{"pos":"v.","meaning":"倒车；使倒退","definition":"To move backwards, especially in a vehicle.","examples":[{"en":"She reversed into the parking space.","zh":"她倒车驶入停车位。"},{"en":"Reverse slowly until you reach the gate.","zh":"慢慢倒车，直到抵达大门。"}]}],"review":[{"pos":"v.","meaning":"审查;回顾;复习","definition":"to examine again or look back over","examples":[{"en":"We reviewed the safety procedures.","zh":"我们审查了安全流程。"},{"en":"She reviewed her notes before the exam.","zh":"她考试前复习了笔记。"}]},{"pos":"v.","meaning":"评论;写评论","definition":"to evaluate a book, film, or performance publicly","examples":[{"en":"He reviews films for a newspaper.","zh":"他为报纸写影评。"},{"en":"The critic reviewed her latest novel.","zh":"评论家评论了她的新小说。"}]},{"pos":"n.","meaning":"审查;回顾;复习","definition":"an examination or reconsideration","examples":[{"en":"The policy is under review.","zh":"政策正在审查。"},{"en":"The chapter ends with a brief review.","zh":"章节以简短回顾结尾。"}]},{"pos":"n.","meaning":"评论;评价文章","definition":"a published evaluation","examples":[{"en":"The restaurant received a favourable review.","zh":"餐厅获得好评。"},{"en":"I read a review of the exhibition.","zh":"我读了展览评论。"}]}],"revise":[{"pos":"v.","meaning":"修订；修改","definition":"to change and improve something","examples":[{"en":"We revised the timetable.","zh":"我们修订了时刻表。"},{"en":"She revised her estimate after the survey.","zh":"调查后她调整了估计。"}]},{"pos":"v.","meaning":"复习（英式）","definition":"to study previously learned material before an exam","examples":[{"en":"He is revising for his final exams.","zh":"他正在复习期末考试。"},{"en":"She revised the chapter before the test.","zh":"她在测试前复习了这一章。"}]}],"revival":[{"pos":"n.","meaning":"恢复；复苏；复兴；重新流行","definition":"A return of strength, activity, popularity, or use.","examples":[{"en":"The town experienced a revival in tourism.","zh":"小镇旅游业迎来了复苏。"},{"en":"The play's revival attracted a new generation of audiences.","zh":"这部剧的复排吸引了新一代观众。"}]}],"revive":[{"pos":"v.","meaning":"使苏醒;恢复活力","definition":"to return or bring back to consciousness or strength","examples":[{"en":"Fresh air helped revive him.","zh":"新鲜空气帮助他清醒过来。"},{"en":"Rain revived the wilted plants.","zh":"雨使枯萎植物恢复生机。"}]},{"pos":"v.","meaning":"恢复使用;复兴","definition":"to bring something back into use or popularity","examples":[{"en":"The theatre revived a forgotten play.","zh":"剧院重新上演被遗忘的戏剧。"},{"en":"The festival revived an ancient custom.","zh":"节庆恢复了一项古老习俗。"}]}],"revolution":[{"pos":"n.","meaning":"革命","definition":"a major change of political power or social order","examples":[{"en":"The revolution transformed the government.","zh":"革命改变了政府。"},{"en":"The museum explores the causes of the revolution.","zh":"博物馆探讨革命的原因。"}]},{"pos":"n.","meaning":"巨变；重大变革","definition":"a fundamental change in a field","examples":[{"en":"Digital photography brought a revolution in publishing.","zh":"数码摄影给出版业带来了巨变。"},{"en":"The invention sparked a transport revolution.","zh":"发明引发了交通革命。"}]}],"revolve":[{"pos":"v.","meaning":"旋转；绕转","definition":"To move in a circle around a central point.","examples":[{"en":"The wheel revolves slowly.","zh":"轮子缓缓转动。"},{"en":"The planets revolve around the Sun.","zh":"行星绕太阳公转。"}]}],"reward":[{"pos":"n.","meaning":"奖励;报酬;回报","definition":"something given in return for effort or help","examples":[{"en":"She received a reward for finding the dog.","zh":"她因找到狗而获得报酬。"},{"en":"The work brings its own rewards.","zh":"这项工作本身就带来回报。"}]},{"pos":"v.","meaning":"奖励;酬谢","definition":"to give something in recognition of effort","examples":[{"en":"The school rewarded her achievement.","zh":"学校奖励了她的成就。"},{"en":"He rewarded the volunteers with a meal.","zh":"他请志愿者吃饭以示感谢。"}]}],"ridiculous":[{"pos":"adj.","meaning":"荒谬的；可笑的","definition":"very unreasonable or absurd","examples":[{"en":"The price was ridiculous.","zh":"价格高得荒谬。"},{"en":"He rejected the ridiculous accusation.","zh":"他否认了荒谬的指控。"}]}],"rig":[{"pos":"v.","meaning":"操纵；暗中做手脚","definition":"To dishonestly arrange a result in one's favour.","examples":[{"en":"The officials were accused of rigging the election.","zh":"官员被指控操纵选举。"},{"en":"The contest was rigged to favour one entrant.","zh":"比赛被暗中操纵，以偏袒一位参赛者。"}]},{"pos":"n.","meaning":"帆装；船帆及索具装置","definition":"The arrangement of a ship's masts, sails, and ropes.","examples":[{"en":"The sailor checked the yacht's rig before departure.","zh":"水手在出发前检查了游艇的帆装。"},{"en":"The vessel has a simple rig that one person can manage.","zh":"这艘船的帆装简单，一个人就能操作。"}]},{"pos":"n.","meaning":"成套设备；钻探装置","definition":"A set of equipment assembled for a particular purpose.","examples":[{"en":"The camera rig was mounted on a vehicle.","zh":"整套摄像设备安装在车辆上。"},{"en":"The drilling rig operated throughout the night.","zh":"钻机整夜运行。"}]}],"righteous":[{"pos":"adj.","meaning":"正义的;正直的;正当的","definition":"morally right or justified","examples":[{"en":"They fought for a righteous cause.","zh":"他们为正义事业奋斗。"},{"en":"Her righteous anger followed a serious injustice.","zh":"严重的不公引起了她正当的愤怒。"}]}],"rigid":[{"pos":"adj.","meaning":"严格死板的；不易改变的","definition":"inflexible in rules or behaviour","examples":[{"en":"The school follows a rigid timetable.","zh":"学校遵循严格固定的时间表。"},{"en":"Rigid thinking prevented a compromise.","zh":"僵化思维阻碍了妥协。"}]},{"pos":"adj.","meaning":"坚硬的；僵硬的","definition":"not easily bent or moved","examples":[{"en":"The frame is light but rigid.","zh":"框架轻巧但坚硬。"},{"en":"She stood rigid with fear.","zh":"她吓得僵立不动。"}]}],"rigorous":[{"pos":"adj.","meaning":"严格的；严密的；严厉的","definition":"Very careful, thorough, and demanding.","examples":[{"en":"The product passed rigorous safety tests.","zh":"产品通过了严格的安全测试。"},{"en":"The paper requires a rigorous analysis of the evidence.","zh":"论文需要对证据作严密分析。"}]},{"pos":"adj.","meaning":"严酷的；艰苦的","definition":"Harsh or difficult to endure.","examples":[{"en":"The plants survived a rigorous winter.","zh":"这些植物熬过了严冬。"},{"en":"The expedition faced rigorous conditions at high altitude.","zh":"探险队在高海拔地区面临严酷条件。"}]}],"rim":[{"pos":"n.","meaning":"边缘;轮缘","definition":"the outer edge of a rounded object","examples":[{"en":"A crack appeared on the cup's rim.","zh":"杯沿出现裂缝。"},{"en":"They walked around the crater's rim.","zh":"他们绕着火山口边缘行走。"}]}],"ripe":[{"pos":"adj.","meaning":"成熟的（果实等）","definition":"fully developed and ready to eat","examples":[{"en":"The peaches are ripe.","zh":"桃子熟了。"},{"en":"Workers gathered ripe grapes.","zh":"工人采摘成熟葡萄。"}]},{"pos":"adj.","meaning":"时机成熟的；条件适宜的","definition":"ready for a particular action","examples":[{"en":"The time is ripe for reform.","zh":"改革的时机已成熟。"},{"en":"The region is ripe for investment.","zh":"该地区的投资条件已成熟。"}]}],"ritual":[{"pos":"n.","meaning":"仪式；典礼","definition":"A set of traditional actions performed for religious or ceremonial purposes.","examples":[{"en":"The ceremony included an ancient ritual.","zh":"典礼包含一项古老仪式。"},{"en":"The community gathers for the annual harvest ritual.","zh":"社区每年聚集举行丰收仪式。"}]},{"pos":"n.","meaning":"惯例；固定程序；例行公事","definition":"An activity regularly repeated in a familiar way.","examples":[{"en":"Making tea is part of his morning ritual.","zh":"泡茶是他早晨固定程序的一部分。"},{"en":"Their weekly walk became a cherished ritual.","zh":"每周散步成了他们珍视的惯例。"}]},{"pos":"adj.","meaning":"仪式的；例行的","definition":"Relating to a ceremony or customary repeated action.","examples":[{"en":"The dancers wore ritual masks.","zh":"舞者戴着仪式面具。"},{"en":"They exchanged the usual ritual greetings.","zh":"他们照例互致问候。"}]}],"rival":[{"pos":"n.","meaning":"竞争者;对手","definition":"someone competing with another","examples":[{"en":"The two rivals trained together.","zh":"两个竞争对手一起训练。"},{"en":"The new store undercut its rivals.","zh":"新店以低价与对手竞争。"}]},{"pos":"adj.","meaning":"竞争的;对立的","definition":"competing for the same objective","examples":[{"en":"Rival teams met in the final.","zh":"竞争球队在决赛相遇。"},{"en":"She compared offers from rival companies.","zh":"她比较了竞争公司的报价。"}]},{"pos":"v.","meaning":"比得上;与……匹敌","definition":"to equal or compete strongly with","examples":[{"en":"The view rivals anything on the coast.","zh":"这景色不逊于沿海任何一处。"},{"en":"Few pianists can rival her technique.","zh":"很少有钢琴家能与她的技巧匹敌。"}]}],"roam":[{"pos":"v.","meaning":"漫游；闲逛；漫谈","definition":"to move or range freely without a fixed route","examples":[{"en":"We roamed through the old streets.","zh":"我们漫步在老街上。"},{"en":"The conversation roamed over many topics.","zh":"谈话漫及许多话题。"}]},{"pos":"n.","meaning":"漫步；闲逛","definition":"a walk without a fixed destination","examples":[{"en":"We enjoyed a roam around the market.","zh":"我们开心地逛了逛市场。"},{"en":"A quiet roam through the woods cleared her mind.","zh":"在林中安静漫步使她思路清晰。"}]}],"roast":[{"pos":"v.","meaning":"烤；烘烤","definition":"To cook using dry heat.","examples":[{"en":"Roast the vegetables until their edges turn brown.","zh":"把蔬菜烤到边缘变褐。"},{"en":"They roasted coffee beans in small batches.","zh":"他们分小批烘焙咖啡豆。"}]},{"pos":"adj.","meaning":"烤制的；烤过的","definition":"Cooked by dry heat.","examples":[{"en":"We had roast chicken for dinner.","zh":"我们晚餐吃了烤鸡。"},{"en":"The café serves roast vegetables with rice.","zh":"咖啡馆供应烤蔬菜配米饭。"}]},{"pos":"n.","meaning":"烤肉；烤制大块肉","definition":"A large piece of meat cooked by roasting.","examples":[{"en":"She carved the roast at the table.","zh":"她在餐桌上切烤肉。"},{"en":"The family shared a roast on Sunday.","zh":"一家人在周日分享了烤肉。"}]}],"robotic":[{"pos":"adj.","meaning":"机器人的;机器人操作的","definition":"relating to robots","examples":[{"en":"A robotic arm assembles the parts.","zh":"机械臂组装零件。"},{"en":"The lab tests robotic vehicles.","zh":"实验室测试机器人车辆。"}]},{"pos":"adj.","meaning":"机械呆板的","definition":"lacking natural feeling or variation","examples":[{"en":"His robotic voice sounded emotionless.","zh":"他的声音机械呆板，毫无感情。"},{"en":"The dancers avoided robotic movements.","zh":"舞者避免机械僵硬的动作。"}]}],"robust":[{"pos":"adj.","meaning":"强壮的；结实的；耐用的","definition":"strong and able to withstand difficulty","examples":[{"en":"The equipment has a robust frame.","zh":"设备有结实的框架。"},{"en":"The plants showed robust growth.","zh":"植物生长健壮。"}]},{"pos":"adj.","meaning":"坚定有力的；经得住检验的","definition":"strong and effective in argument or action","examples":[{"en":"She offered a robust defence of the plan.","zh":"她有力地捍卫了计划。"},{"en":"The conclusions rely on robust evidence.","zh":"结论依赖可靠而充分的证据。"}]}],"roll film":[{"pos":"n.","meaning":"胶卷；卷装胶片","definition":"Photographic film wound onto a spool.","examples":[{"en":"The old camera uses roll film.","zh":"这台老相机使用胶卷。"},{"en":"She kept spare roll film in her camera bag.","zh":"她在相机包里放着备用胶卷。"}]}],"roller":[{"pos":"n.","meaning":"滚筒;滚轴","definition":"a revolving cylinder used for moving or pressing things","examples":[{"en":"Apply paint with a roller.","zh":"用滚筒涂漆。"},{"en":"The paper passes between two rollers.","zh":"纸张从两个滚轴之间通过。"}]}],"romance":[{"pos":"n.","meaning":"恋爱；浪漫爱情","definition":"a loving relationship or romantic feeling","examples":[{"en":"Their romance began at university.","zh":"他们的恋情始于大学。"},{"en":"The letters reveal a lifelong romance.","zh":"信件揭示了一段终身恋情。"}]},{"pos":"n.","meaning":"爱情小说；传奇故事","definition":"a story about love or adventurous events","examples":[{"en":"She enjoys reading historical romances.","zh":"她喜欢读历史爱情小说。"},{"en":"The poem draws on medieval romance.","zh":"诗歌取材于中世纪传奇。"}]}],"rot":[{"pos":"v.","meaning":"腐烂；使腐烂","definition":"To decay through natural processes.","examples":[{"en":"The fallen apples began to rot.","zh":"掉落的苹果开始腐烂。"},{"en":"Damp conditions rotted the wooden beams.","zh":"潮湿条件使木梁腐烂了。"}]},{"pos":"n.","meaning":"腐烂；腐朽","definition":"The process or condition of decaying.","examples":[{"en":"The survey found rot in the roof timbers.","zh":"勘查发现屋顶木料腐烂了。"},{"en":"Good ventilation helps prevent rot.","zh":"良好通风有助于防止腐烂。"}]}],"rotate":[{"pos":"v.","meaning":"旋转;转动","definition":"to turn around an axis","examples":[{"en":"The fan blades rotate rapidly.","zh":"风扇叶片迅速旋转。"},{"en":"Rotate the handle clockwise.","zh":"顺时针转动把手。"}]},{"pos":"v.","meaning":"轮换;轮流","definition":"to change positions or duties in a sequence","examples":[{"en":"The staff rotate between departments.","zh":"员工在部门之间轮岗。"},{"en":"Farmers rotate crops to protect the soil.","zh":"农民轮作以保护土壤。"}]}],"route":[{"pos":"n.","meaning":"路线","definition":"a way from one place to another","examples":[{"en":"This bus route passes the hospital.","zh":"这条公交路线经过医院。"},{"en":"We chose a shorter route through the park.","zh":"我们选了一条穿过公园的较短路线。"},{"en":"The driver explained the route to the airport.","zh":"司机解释了去机场的路线。"}]}],"routine":[{"pos":"n.","meaning":"惯例；例行程序","definition":"A usual or regular way of doing things.","examples":[{"en":"Exercise is part of her daily routine.","zh":"锻炼是她日常生活的一部分。"},{"en":"The new job disrupted his familiar routine.","zh":"新工作打乱了他熟悉的日常安排。"}]},{"pos":"adj.","meaning":"常规的；例行的","definition":"Done regularly as a normal procedure.","examples":[{"en":"The vehicle underwent a routine inspection.","zh":"车辆接受了例行检查。"},{"en":"Routine tasks can often be automated.","zh":"常规任务往往可以自动化。"}]}],"rude":[{"pos":"adj.","meaning":"粗鲁的;无礼的","definition":"impolite or offensive","examples":[{"en":"It is rude to interrupt.","zh":"打断别人是不礼貌的。"},{"en":"She apologised for her rude remark.","zh":"她为粗鲁的话道歉。"}]},{"pos":"adj.","meaning":"粗糙的;简陋的","definition":"roughly made or simple","examples":[{"en":"They built a rude shelter from branches.","zh":"他们用树枝搭了简陋住所。"},{"en":"A rude wooden bench stood by the fire.","zh":"火旁放着粗糙木凳。"}]}],"rudimentary":[{"pos":"adj.","meaning":"基础的；初步的","definition":"basic and not highly developed","examples":[{"en":"He has a rudimentary knowledge of French.","zh":"他略懂法语。"},{"en":"The shelter offered only rudimentary facilities.","zh":"收容所只提供基本设施。"}]},{"pos":"adj.","meaning":"未充分发育的；退化残留的","definition":"undeveloped or present only in a reduced form","examples":[{"en":"The specimen had rudimentary wings.","zh":"标本有未充分发育的翅膀。"},{"en":"The diagram shows a rudimentary organ.","zh":"图示展示一个退化器官。"}]}],"rumour":[{"pos":"n.","meaning":"谣言；传闻","definition":"Information passed between people without confirmed evidence.","examples":[{"en":"A rumour spread that the factory would close.","zh":"有传闻说工厂将关闭。"},{"en":"She refused to comment on the rumours.","zh":"她拒绝对这些传闻发表评论。"}]}],"rural":[{"pos":"adj.","meaning":"农村的","definition":"relating to the countryside","examples":[{"en":"Many rural areas lack frequent bus services.","zh":"许多农村地区缺乏班次充足的公交服务。"},{"en":"Rural communities may struggle to attract doctors.","zh":"农村社区可能很难吸引医生。"},{"en":"Better internet access can support rural businesses.","zh":"更好的互联网接入可以支持农村企业。"}]}],"ruthless":[{"pos":"adj.","meaning":"冷酷无情的；残忍的","definition":"showing no pity when pursuing a goal","examples":[{"en":"The ruler was ruthless towards opponents.","zh":"统治者对反对者冷酷无情。"},{"en":"The editor made ruthless cuts to the draft.","zh":"编辑毫不留情地删减草稿。"}]}],"sack":[{"pos":"n.","meaning":"麻袋；粗布袋；大袋","definition":"A large strong bag used for storing or carrying goods.","examples":[{"en":"He carried a sack of potatoes.","zh":"他扛着一袋土豆。"},{"en":"The grain was stored in woven sacks.","zh":"粮食储存在编织袋里。"}]},{"pos":"n.","meaning":"解雇（常用于the sack）","definition":"Dismissal from employment.","examples":[{"en":"He feared getting the sack.","zh":"他担心被解雇。"},{"en":"The employee was given the sack after repeated absences.","zh":"这个员工多次缺勤后被解雇了。"}]},{"pos":"n.","meaning":"劫掠；洗劫","definition":"The violent looting of a captured place.","examples":[{"en":"The museum describes the sack of the ancient city.","zh":"博物馆介绍了古城遭洗劫的经过。"},{"en":"Many records were destroyed during the sack.","zh":"许多档案在劫掠中被毁。"}]},{"pos":"v.","meaning":"解雇","definition":"To dismiss someone from a job.","examples":[{"en":"The club sacked its coach.","zh":"俱乐部解雇了教练。"},{"en":"She was sacked after a serious breach of procedure.","zh":"她因严重违反程序而被解雇。"}]},{"pos":"v.","meaning":"洗劫；掠夺","definition":"To rob and damage a captured place.","examples":[{"en":"The invading army sacked the town.","zh":"入侵军队洗劫了小镇。"},{"en":"The palace was sacked during the revolt.","zh":"宫殿在叛乱中遭到了掠夺。"}]}],"sacrifice":[{"pos":"n.","meaning":"牺牲;舍弃的事物","definition":"giving up something valuable for another purpose","examples":[{"en":"Parents often make sacrifices for their children.","zh":"父母常为孩子作出牺牲。"},{"en":"The move involved a considerable financial sacrifice.","zh":"搬迁意味着相当大的经济牺牲。"}]},{"pos":"n.","meaning":"献祭;祭品","definition":"an offering made to a deity","examples":[{"en":"The ancient ritual included an animal sacrifice.","zh":"古代仪式包括动物献祭。"},{"en":"Offerings were placed on the altar for sacrifice.","zh":"供物放在祭坛上用于献祭。"}]},{"pos":"v.","meaning":"牺牲;舍弃","definition":"to give up something valued","examples":[{"en":"She sacrificed leisure time to finish the work.","zh":"她牺牲休闲时间完成工作。"},{"en":"Do not sacrifice safety for speed.","zh":"不要为速度牺牲安全。"}]},{"pos":"v.","meaning":"献祭","definition":"to offer something to a deity","examples":[{"en":"The community sacrificed grain at harvest time.","zh":"这个群体在收获时献祭谷物。"},{"en":"Ancient worshippers sacrificed animals at the temple.","zh":"古代信徒在神庙献祭动物。"}]}],"salary":[{"pos":"n.","meaning":"薪水","definition":"regular pay received for a job","examples":[{"en":"The position offers a competitive salary.","zh":"这个职位提供有竞争力的薪水。"},{"en":"Her salary is paid at the end of each month.","zh":"她的薪水在每月月底发放。"},{"en":"We discussed the starting salary during the interview.","zh":"我们在面试中讨论了起薪。"}]}],"saline":[{"pos":"adj.","meaning":"含盐的；咸的","definition":"Containing salt.","examples":[{"en":"Few crops tolerate highly saline soil.","zh":"很少有作物能耐受高盐土壤。"},{"en":"The lake's water is too saline to drink.","zh":"湖水含盐太高，无法饮用。"}]},{"pos":"n.","meaning":"盐水；生理盐水","definition":"A solution of salt in water, often used medically.","examples":[{"en":"The nurse prepared a bag of saline.","zh":"护士准备了一袋生理盐水。"},{"en":"The sample was rinsed with saline in the laboratory.","zh":"样本在实验室用盐水冲洗了。"}]}],"salinity":[{"pos":"n.","meaning":"盐度;含盐量","definition":"the amount of salt in water or soil","examples":[{"en":"The instrument measures seawater salinity.","zh":"仪器测量海水盐度。"},{"en":"High soil salinity limits crop growth.","zh":"土壤盐度高限制了作物生长。"}]}],"sample":[{"pos":"n.","meaning":"样本；统计样本；抽样群体","definition":"a small part used to represent a larger group","examples":[{"en":"The study used a sample of two hundred adults.","zh":"这项研究使用了两百名成年人的样本。"},{"en":"A small sample may produce unreliable results.","zh":"小样本可能产生不可靠的结果。"},{"en":"The researchers selected a random sample of households.","zh":"研究人员随机抽取了一组家庭作为样本。"}]},{"pos":"v.","meaning":"抽样；采样","definition":"to take a small part for testing","examples":[{"en":"Researchers sampled water from each well.","zh":"研究人员从每口井采集水样。"},{"en":"The survey sampled households across the city.","zh":"调查在全市家庭中抽样。"}]},{"pos":"v.","meaning":"品尝；体验","definition":"to try a small amount of something","examples":[{"en":"Visitors sampled local cheeses.","zh":"游客品尝了当地奶酪。"},{"en":"The festival lets children sample different sports.","zh":"节庆让孩子体验不同运动。"}]},{"pos":"n.","meaning":"样品；少量试用品；检验样本","definition":"a small amount of a substance or product used for testing or demonstration","examples":[{"en":"The nurse placed the blood sample in a labelled tube.","zh":"护士将血样放入带标签的试管。"},{"en":"The shop gave us a sample of the new soap.","zh":"商店给了我们一份新香皂的试用品。"}]}],"sanction":[{"pos":"v.","meaning":"批准；认可","definition":"To officially approve or permit something.","examples":[{"en":"The committee sanctioned the expenditure.","zh":"委员会批准了这笔开支。"},{"en":"The event was sanctioned by the governing body.","zh":"这项活动获得了管理机构批准。"}]},{"pos":"n.","meaning":"批准；许可","definition":"Official permission or approval.","examples":[{"en":"The project needs government sanction.","zh":"项目需要政府批准。"},{"en":"They acted without the board's sanction.","zh":"他们未经董事会许可便采取了行动。"}]},{"pos":"n.","meaning":"制裁；约束性惩罚","definition":"A penalty used to enforce rules or influence behaviour.","examples":[{"en":"The country faced economic sanctions.","zh":"该国面临经济制裁。"},{"en":"Professional bodies can impose sanctions for misconduct.","zh":"专业组织可以对不当行为施加处罚。"}]}],"sanctuary":[{"pos":"n.","meaning":"庇护所;避难所;庇护","definition":"a place of safety or protection","examples":[{"en":"The church offered sanctuary to refugees.","zh":"教堂为难民提供庇护。"},{"en":"Her garden became a private sanctuary.","zh":"她的花园成了私人避静之所。"}]},{"pos":"n.","meaning":"动物保护区;禁猎区","definition":"an area protecting wildlife","examples":[{"en":"The island is a bird sanctuary.","zh":"岛屿是鸟类保护区。"},{"en":"Hunting is forbidden in the sanctuary.","zh":"保护区内禁止狩猎。"}]},{"pos":"n.","meaning":"圣殿;圣坛;圣所","definition":"a sacred part of a religious building","examples":[{"en":"Candles lit the sanctuary.","zh":"蜡烛照亮了圣所。"},{"en":"The priest entered the sanctuary quietly.","zh":"牧师静静走进圣坛区。"}]}],"sanitary":[{"pos":"adj.","meaning":"卫生的；清洁的","definition":"clean and designed to protect health","examples":[{"en":"The kitchen meets sanitary standards.","zh":"厨房符合卫生标准。"},{"en":"The camp needs better sanitary facilities.","zh":"营地需要更好的卫生设施。"}]},{"pos":"n.","meaning":"公共厕所（旧式用法）","definition":"an old term for a public toilet","examples":[{"en":"The old station plan labels a room as a sanitary.","zh":"旧车站平面图将一个房间标为公共厕所。"},{"en":"The historical report describes a public sanitary near the market.","zh":"历史报告描述了市场附近的一座公厕。"}]}],"sanitation":[{"pos":"n.","meaning":"公共卫生；卫生设施；环境卫生","definition":"Systems and practices for keeping places clean and safely disposing of waste.","examples":[{"en":"The village needs better sanitation.","zh":"村庄需要更好的卫生设施。"},{"en":"Poor sanitation contributed to the spread of disease.","zh":"恶劣的卫生条件助长了疾病传播。"}]}],"saturate":[{"pos":"v.","meaning":"浸透;使湿透","definition":"to soak completely with liquid","examples":[{"en":"Heavy rain saturated the soil.","zh":"大雨浸透土壤。"},{"en":"The sponge was saturated with water.","zh":"海绵吸满了水。"}]},{"pos":"v.","meaning":"使充满;使饱和","definition":"to fill completely beyond further absorption","examples":[{"en":"The market is saturated with similar products.","zh":"市场上同类产品已饱和。"},{"en":"Advertising saturated every available screen.","zh":"广告充斥每一块可用屏幕。"}]}],"sausage":[{"pos":"n.","meaning":"香肠","definition":"seasoned meat or a substitute enclosed in a casing","examples":[{"en":"The stall sells grilled sausages.","zh":"摊位出售烤香肠。"},{"en":"She sliced a sausage into the stew.","zh":"她把香肠切片放入炖菜。"}]}],"savings":[{"pos":"n.","meaning":"储蓄；积蓄","definition":"money kept for future use","examples":[{"en":"She used her savings to pay for the course.","zh":"她用积蓄支付了课程费用。"},{"en":"Keep some savings for emergencies.","zh":"留一些积蓄以应对紧急情况。"},{"en":"Our savings helped us buy a small flat.","zh":"我们的积蓄帮助我们买了一套小公寓。"}]}],"savour":[{"pos":"v.","meaning":"细品;品尝;享受","definition":"to enjoy something slowly and fully","examples":[{"en":"She savoured each mouthful of soup.","zh":"她细品每口汤。"},{"en":"He savoured the moment of victory.","zh":"他尽情享受胜利时刻。"}]},{"pos":"n.","meaning":"味道;风味","definition":"a distinctive pleasant taste or smell","examples":[{"en":"Herbs gave the stew a rich savour.","zh":"香草赋予炖菜浓郁风味。"},{"en":"The broth retained the savour of roasted onions.","zh":"汤保留了烤洋葱的香味。"}]},{"pos":"n.","meaning":"情趣;吸引力","definition":"an appealing quality or enjoyment","examples":[{"en":"Travel gave a new savour to her life.","zh":"旅行给她的生活增添新情趣。"},{"en":"Success had lost its savour without friends to share it.","zh":"没有朋友分享，成功失去了乐趣。"}]}],"scale":[{"pos":"n.","meaning":"规模；大小","definition":"the size or extent of something","examples":[{"en":"We underestimated the scale of the damage.","zh":"我们低估了损失规模。"},{"en":"The project operates on a small scale.","zh":"项目规模较小。"}]},{"pos":"n.","meaning":"秤；天平（常用复数 scales）","definition":"a device for measuring weight","examples":[{"en":"Place the flour on the scales.","zh":"把面粉放在秤上。"},{"en":"The scale showed five kilograms.","zh":"秤显示五公斤。"}]},{"pos":"n.","meaning":"刻度；等级体系","definition":"a graduated range used for measurement or ranking","examples":[{"en":"The thermometer has a Celsius scale.","zh":"温度计有摄氏刻度。"},{"en":"Rate the pain on a scale of one to ten.","zh":"按一到十分评估疼痛。"}]},{"pos":"n.","meaning":"鳞；鳞片","definition":"a small overlapping plate covering some animals","examples":[{"en":"The fish has shiny scales.","zh":"鱼有闪亮的鳞片。"},{"en":"A snake sheds the outer layer of its scales.","zh":"蛇会蜕掉鳞片的外层。"}]},{"pos":"n.","meaning":"音阶","definition":"a sequence of musical notes","examples":[{"en":"She practised a major scale.","zh":"她练习了一个大调音阶。"},{"en":"The melody rises through the scale.","zh":"旋律沿音阶上行。"}]},{"pos":"n.","meaning":"比例；比例尺","definition":"the ratio between a representation and the real object","examples":[{"en":"The map has a scale of one to fifty thousand.","zh":"地图比例尺为一比五万。"},{"en":"The model was built to scale.","zh":"模型按比例建造。"}]},{"pos":"v.","meaning":"攀登；爬越","definition":"to climb a steep surface","examples":[{"en":"The climbers scaled the rock face.","zh":"登山者爬上岩壁。"},{"en":"He scaled the wall to reach the garden.","zh":"他翻墙进入花园。"}]}],"scamper":[{"pos":"v.","meaning":"蹦蹦跳跳地跑；快跑","definition":"To run with quick light steps.","examples":[{"en":"The squirrel scampered up the tree.","zh":"松鼠飞快地跑上树。"},{"en":"The children scampered across the lawn.","zh":"孩子们轻快地跑过草坪。"}]}],"scan":[{"pos":"v.","meaning":"扫描","definition":"to examine using a machine","examples":[{"en":"The technician scanned the damaged component.","zh":"技术员扫描了损坏部件。"},{"en":"Scan the document and save a copy.","zh":"扫描文件并保存副本。"}]},{"pos":"v.","meaning":"浏览;扫视","definition":"to look over quickly or systematically","examples":[{"en":"She scanned the timetable for her train.","zh":"她浏览时刻表寻找自己的列车。"},{"en":"He scanned the crowd for a familiar face.","zh":"他扫视人群寻找熟悉面孔。"}]},{"pos":"n.","meaning":"扫描;扫描图像","definition":"an examination or image made by scanning","examples":[{"en":"The scan revealed a small crack.","zh":"扫描显示一道小裂缝。"},{"en":"A clear scan of the letter is attached.","zh":"附有这封信的清晰扫描件。"}]}],"scandal":[{"pos":"n.","meaning":"丑闻；引起公愤的事件","definition":"an event involving disgraceful behaviour","examples":[{"en":"The financial scandal forced an investigation.","zh":"财务丑闻迫使当局调查。"},{"en":"The neglected housing became a public scandal.","zh":"被忽视的住房问题成为公众关注的丑闻。"}]},{"pos":"n.","meaning":"恶意流言；诽谤","definition":"harmful gossip about someone","examples":[{"en":"The newspaper spread scandal about the family.","zh":"报纸散布关于这个家庭的恶意流言。"},{"en":"She refused to listen to village scandal.","zh":"她拒绝听村里的闲言碎语。"}]},{"pos":"n.","meaning":"反感；公愤","definition":"public shock or anger at wrongdoing","examples":[{"en":"The decision caused scandal in the town.","zh":"决定在镇上引起了公愤。"},{"en":"The affair provoked a sense of scandal.","zh":"这件事激起了愤慨。"}]}],"scarce":[{"pos":"adj.","meaning":"稀缺的；不足的；罕见的","definition":"Not available in sufficient quantities or rarely found.","examples":[{"en":"Fresh water is scarce on the island.","zh":"岛上淡水稀缺。"},{"en":"Jobs became scarce after the factory closed.","zh":"工厂关闭后，工作岗位变得稀少。"}]}],"scare":[{"pos":"n.","meaning":"惊吓;恐慌","definition":"a sudden fright or period of fear","examples":[{"en":"The loud bang gave me a scare.","zh":"巨响吓了我一跳。"},{"en":"The food scare reduced sales.","zh":"食品安全恐慌使销量下降。"}]},{"pos":"v.","meaning":"使害怕;受惊","definition":"to frighten or become frightened","examples":[{"en":"The thunder scared the dog.","zh":"雷声吓到了狗。"},{"en":"She does not scare easily.","zh":"她不轻易受惊。"}]}],"scatter":[{"pos":"v.","meaning":"撒；散播","definition":"to throw or distribute things over an area","examples":[{"en":"She scattered seeds over the soil.","zh":"她把种子撒在土上。"},{"en":"Papers were scattered across the desk.","zh":"文件散落在桌上。"}]},{"pos":"v.","meaning":"散开；驱散","definition":"to move or make move in different directions","examples":[{"en":"The birds scattered at the noise.","zh":"鸟群听到声响四散飞去。"},{"en":"The sudden rain scattered the crowd.","zh":"突来的雨使人群散开。"}]}],"scenery":[{"pos":"n.","meaning":"风景；景色","definition":"The natural appearance of an area.","examples":[{"en":"We stopped to admire the mountain scenery.","zh":"我们停下来欣赏山景。"},{"en":"The train journey offers spectacular coastal scenery.","zh":"这段火车旅程能欣赏到壮丽海岸风光。"}]},{"pos":"n.","meaning":"舞台布景","definition":"Painted backgrounds and structures used in a play.","examples":[{"en":"The actors helped move the scenery.","zh":"演员们帮忙移动布景。"},{"en":"The scenery changed between acts.","zh":"幕间更换了舞台布景。"}]}],"scent":[{"pos":"n.","meaning":"气味;香味","definition":"a distinctive smell","examples":[{"en":"The scent of pine filled the air.","zh":"空气中弥漫松树香。"},{"en":"The dog followed the rabbit's scent.","zh":"狗追踪兔子的气味。"}]},{"pos":"v.","meaning":"嗅到;察觉","definition":"to detect by smell or intuition","examples":[{"en":"The wolf scented prey nearby.","zh":"狼嗅到了附近的猎物。"},{"en":"Reporters scented a scandal.","zh":"记者察觉到丑闻的苗头。"}]}],"sceptical":[{"pos":"adj.","meaning":"怀疑的；不轻信的","definition":"not easily convinced that something is true","examples":[{"en":"She remained sceptical about the claim.","zh":"她仍怀疑这一说法。"},{"en":"The proposal met a sceptical audience.","zh":"听众对提案持怀疑态度。"}]}],"schedule":[{"pos":"n.","meaning":"时间表；日程表","definition":"A plan showing when things will happen.","examples":[{"en":"The schedule lists three lectures each morning.","zh":"日程表列出每天上午三场讲座。"},{"en":"The train arrived ahead of schedule.","zh":"火车提前到达了。"}]},{"pos":"n.","meaning":"清单；附表","definition":"A formal list of items or details.","examples":[{"en":"The contract includes a schedule of charges.","zh":"合同附有收费表。"},{"en":"The surveyor prepared a schedule of required repairs.","zh":"测量师列出了一份所需维修的清单。"}]},{"pos":"v.","meaning":"安排；列入计划或清单","definition":"To arrange a time for something or include it in a formal list.","examples":[{"en":"The meeting is scheduled for Tuesday.","zh":"会议安排在周二。"},{"en":"They scheduled the repairs for the quiet season.","zh":"他们把维修安排在淡季。"}]}],"scheme":[{"pos":"n.","meaning":"计划;方案;体系","definition":"an organized plan or system","examples":[{"en":"The council launched a recycling scheme.","zh":"市议会启动了回收计划。"},{"en":"The colour scheme unifies the rooms.","zh":"配色方案使各房间风格统一。"}]},{"pos":"n.","meaning":"阴谋;诡计","definition":"a secret or dishonest plan","examples":[{"en":"The police uncovered a fraudulent scheme.","zh":"警方揭露了诈骗阴谋。"},{"en":"Their scheme to cheat investors failed.","zh":"他们欺骗投资者的诡计失败了。"}]},{"pos":"v.","meaning":"策划;密谋","definition":"to make plans, often secretly","examples":[{"en":"The rivals schemed to remove the director.","zh":"竞争对手密谋罢免主管。"},{"en":"She spent the winter scheming how to escape.","zh":"她整个冬天都在策划如何逃走。"}]}],"scholar":[{"pos":"n.","meaning":"学者","definition":"a person studying a subject deeply","examples":[{"en":"The scholar examined medieval texts.","zh":"学者研究了中世纪文献。"},{"en":"Several scholars contributed to the volume.","zh":"几位学者为这本文集撰稿。"}]},{"pos":"n.","meaning":"奖学金获得者","definition":"a student awarded financial support for study","examples":[{"en":"She entered the college as a scholar.","zh":"她以奖学金获得者身份进入学院。"},{"en":"The new scholar will study engineering.","zh":"新奖学金获得者将学习工程。"}]}],"scholarship":[{"pos":"n.","meaning":"奖学金","definition":"money awarded to support someone's education","examples":[{"en":"She won a scholarship to study engineering.","zh":"她获得了攻读工程学的奖学金。"},{"en":"The scholarship covers tuition fees.","zh":"这项奖学金涵盖学费。"},{"en":"You must apply for the scholarship by March.","zh":"你必须在三月截止日前申请奖学金。"}]},{"pos":"n.","meaning":"学问；学识；学术研究","definition":"Serious learning and scholarly work.","examples":[{"en":"The book is admired for its careful scholarship.","zh":"这本书因严谨的学术研究而受赞赏。"},{"en":"Her scholarship changed how the period was understood.","zh":"她的学术研究改变了人们对那个时期的认识。"}]}],"scope":[{"pos":"n.","meaning":"范围;眼界;广度","definition":"the extent covered by an activity or knowledge","examples":[{"en":"The question lies outside the report's scope.","zh":"这个问题不在报告范围内。"},{"en":"Travel broadened the scope of her understanding.","zh":"旅行扩大了她的认识范围。"}]},{"pos":"n.","meaning":"发挥余地;机会","definition":"freedom or opportunity to act","examples":[{"en":"The job offers scope for creativity.","zh":"这份工作提供了发挥创造力的空间。"},{"en":"There is little scope for reducing costs further.","zh":"进一步降成本的余地很小。"}]}],"scorching":[{"pos":"adj.","meaning":"酷热的","definition":"extremely hot","examples":[{"en":"We walked under a scorching sun.","zh":"我们在烈日下行走。"},{"en":"The scorching weather dried the ground.","zh":"酷热天气使地面干燥。"}]},{"pos":"adj.","meaning":"猛烈的；严厉的","definition":"very intense or harsh","examples":[{"en":"The review delivered scorching criticism.","zh":"评论提出了尖锐批评。"},{"en":"He ran at a scorching pace.","zh":"他以极快的速度奔跑。"}]}],"score":[{"pos":"v.","meaning":"得分；记分；评分","definition":"To gain or assign points.","examples":[{"en":"She scored twice in the final.","zh":"她在决赛中两次得分。"},{"en":"Two examiners scored each essay independently.","zh":"两位考官分别独立给每篇作文评分。"}]},{"pos":"v.","meaning":"刻痕；划线","definition":"To make a shallow cut or mark.","examples":[{"en":"Score the pastry lightly before baking.","zh":"烘烤前在面皮上轻轻划痕。"},{"en":"The sharp stone scored the surface of the table.","zh":"尖石在桌面上划出痕迹。"}]},{"pos":"v.","meaning":"取得；赢得；获得成功","definition":"To achieve something desirable.","examples":[{"en":"The team scored an important victory.","zh":"团队取得了一场重要胜利。"},{"en":"She scored a major success with her first novel.","zh":"她的首部小说获得了巨大成功。"}]},{"pos":"n.","meaning":"得分；分数","definition":"The number of points achieved.","examples":[{"en":"The final score was two to one.","zh":"最终比分为二比一。"},{"en":"Her score improved after regular practice.","zh":"规律练习后，她的分数提高了。"}]},{"pos":"n.","meaning":"乐谱；总谱","definition":"The written music for a composition.","examples":[{"en":"The conductor studied the score.","zh":"指挥研究了总谱。"},{"en":"A handwritten score was found in the archive.","zh":"档案中发现了一份手写乐谱。"}]},{"pos":"n.","meaning":"划痕；刻痕","definition":"A shallow line cut into a surface.","examples":[{"en":"A deep score marked the wooden panel.","zh":"木板上有一道深划痕。"},{"en":"The mechanic noticed scores on the metal surface.","zh":"机械师注意到金属表面上的刻痕。"}]},{"pos":"n.","meaning":"二十；二十个","definition":"A group of twenty.","examples":[{"en":"A score of volunteers arrived before dawn.","zh":"二十名志愿者在黎明前到达。"},{"en":"The old ledger recorded three score sheep.","zh":"旧账簿记录了六十只羊。"}]}],"scour":[{"pos":"v.","meaning":"四处搜寻;细查","definition":"to search thoroughly","examples":[{"en":"Volunteers scoured the woods for the missing child.","zh":"志愿者搜遍树林寻找失踪儿童。"},{"en":"She scoured the archives for evidence.","zh":"她仔细搜查档案寻找证据。"}]},{"pos":"v.","meaning":"用力擦洗;擦亮","definition":"to clean by rubbing hard","examples":[{"en":"He scoured the burnt saucepan.","zh":"他用力擦洗烧焦的平底锅。"},{"en":"Workers scoured the tiles until they shone.","zh":"工人把瓷砖擦洗得发亮。"}]},{"pos":"v.","meaning":"冲刷;冲蚀","definition":"to wear away through flowing water","examples":[{"en":"Floodwater scoured a channel through the field.","zh":"洪水在田间冲出一道沟。"},{"en":"The current scoured sediment from the riverbed.","zh":"水流冲走了河床沉积物。"}]}],"scout":[{"pos":"n.","meaning":"侦察员；侦察机或舰","definition":"a person or vehicle sent ahead to gather information","examples":[{"en":"The scout returned with news of the route.","zh":"侦察员带回了路线消息。"},{"en":"A naval scout searched the coast.","zh":"一艘海军侦察舰搜索海岸。"}]},{"pos":"n.","meaning":"童子军成员","definition":"a member of a youth scouting organisation","examples":[{"en":"The scouts learned to pitch tents.","zh":"童子军学习搭帐篷。"},{"en":"She joined the scouts last year.","zh":"她去年加入童子军。"}]},{"pos":"v.","meaning":"侦察；寻找；搜寻","definition":"to search an area for information or opportunities","examples":[{"en":"They scouted the valley for a campsite.","zh":"他们在山谷中寻找营地。"},{"en":"The director scouted locations for the film.","zh":"导演为电影寻找拍摄地点。"}]}],"scrap":[{"pos":"n.","meaning":"碎片；碎屑；少量","definition":"A small leftover piece of material.","examples":[{"en":"She wrote the address on a scrap of paper.","zh":"她把地址写在一张碎纸上。"},{"en":"The dog waited for scraps from the table.","zh":"狗等着吃桌上剩下的碎食物。"}]},{"pos":"v.","meaning":"废弃；取消；报废","definition":"To discard something as no longer useful or cancel a plan.","examples":[{"en":"The company scrapped the outdated machines.","zh":"公司报废了过时机器。"},{"en":"They scrapped the plan after costs doubled.","zh":"成本翻倍后，他们取消了计划。"}]}],"scrape":[{"pos":"v.","meaning":"刮;擦;刮去","definition":"to rub with a hard or sharp edge","examples":[{"en":"Scrape the mud off your boots.","zh":"刮去靴子上的泥。"},{"en":"The branch scraped the car's roof.","zh":"树枝刮擦了车顶。"}]},{"pos":"n.","meaning":"擦伤;刮痕;刮擦声","definition":"a mark, injury, or sound caused by scraping","examples":[{"en":"He escaped with a scrape on his knee.","zh":"他幸免于难，只擦伤了膝盖。"},{"en":"We heard the scrape of a chair.","zh":"我们听见椅子刮擦的声音。"}]}],"scratch":[{"pos":"n.","meaning":"抓痕；划伤","definition":"a thin mark made by a sharp object","examples":[{"en":"There is a scratch on the table.","zh":"桌上有一道划痕。"},{"en":"The cat left a small scratch on his hand.","zh":"猫在他手上留下一道小抓痕。"}]},{"pos":"v.","meaning":"抓；搔","definition":"to rub with nails or claws","examples":[{"en":"She scratched an itchy arm.","zh":"她搔了搔发痒的手臂。"},{"en":"The dog scratched at the door.","zh":"狗抓挠着门。"}]},{"pos":"v.","meaning":"划伤；刮坏","definition":"to damage a surface with something sharp","examples":[{"en":"The branch scratched the car.","zh":"树枝划伤了车。"},{"en":"Be careful not to scratch the lens.","zh":"小心别刮伤镜头。"}]}],"scream":[{"pos":"v.","meaning":"尖叫；大声喊叫","definition":"To make a loud high-pitched cry.","examples":[{"en":"She screamed when the mouse ran past.","zh":"老鼠跑过时，她尖叫起来。"},{"en":"Fans screamed with excitement.","zh":"歌迷兴奋地尖叫。"}]},{"pos":"n.","meaning":"尖叫声","definition":"A loud high-pitched cry.","examples":[{"en":"A scream came from upstairs.","zh":"楼上传来一声尖叫。"},{"en":"The crowd's screams drowned out the music.","zh":"人群的尖叫声盖过了音乐。"}]}],"screen":[{"pos":"n.","meaning":"屏幕;银幕","definition":"a surface displaying images","examples":[{"en":"The screen went dark.","zh":"屏幕变黑了。"},{"en":"The film appeared on a giant outdoor screen.","zh":"电影在户外巨幕上放映。"}]},{"pos":"n.","meaning":"屏风;帘;遮蔽物","definition":"something that hides or protects","examples":[{"en":"A screen separated the beds.","zh":"屏风把床分隔开。"},{"en":"Trees formed a screen against the road.","zh":"树木形成了遮挡道路的屏障。"}]},{"pos":"n.","meaning":"筛子;筛网","definition":"a mesh separating particles","examples":[{"en":"The sand passed through a fine screen.","zh":"沙子通过细筛网。"},{"en":"The screen trapped larger pieces of debris.","zh":"筛网截住了较大的碎片。"}]},{"pos":"v.","meaning":"遮挡;保护;包庇","definition":"to hide or shield from view or harm","examples":[{"en":"The hedge screens the garden from the road.","zh":"树篱遮住了道路对花园的视线。"},{"en":"He tried to screen his friend from criticism.","zh":"他试图保护朋友免受批评。"}]},{"pos":"v.","meaning":"筛查;筛选","definition":"to examine for suitability or disease","examples":[{"en":"The agency screens all applicants.","zh":"机构筛选所有申请者。"},{"en":"The clinic screened patients for the infection.","zh":"诊所筛查患者是否感染。"}]},{"pos":"v.","meaning":"放映;播映","definition":"to show a film or programme","examples":[{"en":"The festival screened independent films.","zh":"电影节放映独立电影。"},{"en":"The interview was screened on television.","zh":"访谈在电视上播出。"}]}],"screw":[{"pos":"v.","meaning":"用螺钉固定；拧紧","definition":"to attach with a screw or twisting motion","examples":[{"en":"Screw the bracket to the wall.","zh":"把支架用螺钉固定在墙上。"},{"en":"She screwed the lid on tightly.","zh":"她拧紧了盖子。"}]},{"pos":"n.","meaning":"螺钉；螺丝","definition":"a threaded fastener turned into a material","examples":[{"en":"One screw was missing.","zh":"少了一颗螺钉。"},{"en":"The shelf is held by four screws.","zh":"架子用四颗螺钉固定。"}]}],"scrub":[{"pos":"v.","meaning":"用力擦洗；刷洗","definition":"To clean by rubbing hard.","examples":[{"en":"He scrubbed the muddy boots.","zh":"他用力刷洗沾满泥的靴子。"},{"en":"Scrub the pan with a stiff brush.","zh":"用硬刷子刷洗锅。"}]},{"pos":"v.","meaning":"取消；放弃","definition":"To cancel a plan or activity.","examples":[{"en":"The launch was scrubbed because of high winds.","zh":"发射因强风而取消。"},{"en":"They scrubbed the excursion after the road closed.","zh":"道路关闭后，他们取消了短途旅行。"}]},{"pos":"n.","meaning":"灌木丛；矮树丛","definition":"Low bushes and small trees growing densely.","examples":[{"en":"The hillside was covered in scrub.","zh":"山坡布满灌木丛。"},{"en":"A narrow track crossed the dry scrub.","zh":"一条小径穿过干燥的灌木丛。"}]}],"scrupulous":[{"pos":"adj.","meaning":"谨守道德的;一丝不苟的","definition":"careful to be honest or exact","examples":[{"en":"She was scrupulous about declaring expenses.","zh":"她申报开支时严守诚信。"},{"en":"The restoration required scrupulous attention to detail.","zh":"修复要求对细节一丝不苟。"}]}],"scrutiny":[{"pos":"n.","meaning":"仔细检查；严密审视","definition":"close and careful examination","examples":[{"en":"The accounts came under scrutiny.","zh":"账目受到仔细审查。"},{"en":"Her methods withstand close scrutiny.","zh":"她的方法经得起细致审查。"}]}],"scuffle":[{"pos":"v.","meaning":"扭打；推搡打斗","definition":"To fight in a brief, confused way.","examples":[{"en":"Two spectators scuffled near the entrance.","zh":"两名观众在入口附近扭打起来。"},{"en":"The protesters scuffled with guards at the gate.","zh":"抗议者在门口与警卫发生推搡打斗。"}]},{"pos":"n.","meaning":"扭打；小规模混战","definition":"A short disorganised fight.","examples":[{"en":"A scuffle broke out in the queue.","zh":"队伍里发生了一场扭打。"},{"en":"Nobody was seriously hurt in the scuffle.","zh":"扭打中无人严重受伤。"}]}],"sculpture":[{"pos":"n.","meaning":"雕塑;雕塑作品","definition":"a three-dimensional work of art or the art of making it","examples":[{"en":"A bronze sculpture stands in the square.","zh":"广场上立着青铜雕塑。"},{"en":"She studies sculpture at art school.","zh":"她在艺术学校学习雕塑。"}]}],"seal":[{"pos":"v.","meaning":"密封；封住","definition":"to close tightly","examples":[{"en":"Seal the envelope before posting it.","zh":"邮寄前封好信封。"},{"en":"The workers sealed the crack.","zh":"工人封住了裂缝。"}]},{"pos":"n.","meaning":"封条；密封件","definition":"a closure preventing opening or leakage","examples":[{"en":"The bottle's seal was broken.","zh":"瓶子的封条破了。"},{"en":"A rubber seal prevents leaks.","zh":"橡胶密封圈防止泄漏。"}]},{"pos":"n.","meaning":"印章；印记","definition":"an official stamp or its mark","examples":[{"en":"The document bears the royal seal.","zh":"文件盖有王室印章。"},{"en":"She pressed the seal into the wax.","zh":"她把印章按进封蜡。"}]},{"pos":"n.","meaning":"海豹","definition":"a marine mammal with flippers","examples":[{"en":"A seal rested on the rock.","zh":"一只海豹在岩石上休息。"},{"en":"We watched seals swimming near the coast.","zh":"我们看海豹在海岸附近游泳。"}]}],"seam":[{"pos":"n.","meaning":"缝；接缝","definition":"A line where two pieces of material are joined.","examples":[{"en":"The sleeve split along the seam.","zh":"袖子沿接缝裂开了。"},{"en":"She pressed the seam flat with an iron.","zh":"她用熨斗把接缝熨平。"}]},{"pos":"n.","meaning":"煤层；矿层","definition":"A layer of coal or mineral within rock.","examples":[{"en":"The miners reached a thick seam of coal.","zh":"矿工到达了一层厚煤层。"},{"en":"The survey mapped several mineral seams.","zh":"勘查绘制了几个矿层的分布。"}]}],"seasonal":[{"pos":"adj.","meaning":"季节性的;应时的","definition":"occurring or changing with the seasons","examples":[{"en":"The restaurant uses seasonal vegetables.","zh":"餐厅使用时令蔬菜。"},{"en":"Tourism creates seasonal jobs.","zh":"旅游业创造季节性工作。"}]}],"seclude":[{"pos":"v.","meaning":"使隔离；使独处","definition":"to keep apart from other people","examples":[{"en":"She secluded herself to finish the book.","zh":"她独处以完成写作。"},{"en":"High walls seclude the garden.","zh":"高墙使花园与外界隔开。"}]}],"secondary":[{"pos":"adj.","meaning":"次要的；从属的；辅助的","definition":"Less important or occurring after something primary.","examples":[{"en":"Cost is a secondary concern when safety is at stake.","zh":"涉及安全时，成本是次要考虑。"},{"en":"The treatment can have secondary effects.","zh":"这种治疗可能产生次生影响。"}]},{"pos":"adj.","meaning":"中等教育的；中学的","definition":"Relating to education after primary school.","examples":[{"en":"She teaches at a secondary school.","zh":"她在一所中学任教。"},{"en":"The report reviews secondary education in rural areas.","zh":"报告审查了农村地区的中等教育。"}]}],"section":[{"pos":"n.","meaning":"部分;部门;段落","definition":"a distinct part of a larger whole","examples":[{"en":"Read the final section of the report.","zh":"阅读报告最后一部分。"},{"en":"She works in the library's reference section.","zh":"她在图书馆参考资料部工作。"}]},{"pos":"n.","meaning":"截面;剖面","definition":"a view showing the inside of something cut through","examples":[{"en":"The diagram shows a section through the stem.","zh":"图表显示茎的剖面。"},{"en":"The engineer drew a cross section of the tunnel.","zh":"工程师画了隧道横截面。"}]}],"sector":[{"pos":"n.","meaning":"部门；部分；领域","definition":"a part of an economy or area","examples":[{"en":"The public sector employs many residents.","zh":"公共部门雇用许多居民。"},{"en":"The northern sector needs more transport links.","zh":"北部区域需要更多交通连接。"}]},{"pos":"n.","meaning":"防区；军事区域","definition":"an area under military control","examples":[{"en":"The patrol moved into its assigned sector.","zh":"巡逻队进入指定防区。"},{"en":"The commander inspected the eastern sector.","zh":"指挥官视察了东部防区。"}]},{"pos":"n.","meaning":"扇形","definition":"a part of a circle bounded by two radii and an arc","examples":[{"en":"Shade the sector between the two radii.","zh":"给两条半径之间的扇形涂色。"},{"en":"The diagram divides the circle into sectors.","zh":"图把圆分成几个扇形。"}]}],"secure":[{"pos":"v.","meaning":"获得；争取到","definition":"To succeed in obtaining something.","examples":[{"en":"The researchers secured funding for another year.","zh":"研究人员争取到了又一年的资助。"},{"en":"She secured a place on the course.","zh":"她获得了这门课程的名额。"}]},{"pos":"v.","meaning":"保卫；使安全；固定牢","definition":"To protect something or fasten it firmly.","examples":[{"en":"Secure the ladder before climbing.","zh":"攀爬前先固定梯子。"},{"en":"Guards secured the entrance.","zh":"警卫把守住了入口。"}]},{"pos":"adj.","meaning":"安全的；牢固的；可靠的","definition":"Protected from danger or unlikely to fail or move.","examples":[{"en":"Keep the documents in a secure location.","zh":"把文件保存在安全的地方。"},{"en":"The gate is secure now that the lock is fixed.","zh":"锁修好后，大门现在很牢靠。"}]},{"pos":"adj.","meaning":"安心的；有安全感的","definition":"Confident and free from worry.","examples":[{"en":"Children need to feel secure at home.","zh":"孩子在家需要有安全感。"},{"en":"She felt secure in her new role.","zh":"她在新岗位上感到安心自信。"}]}],"security":[{"pos":"n.","meaning":"安全；安全保障","definition":"protection from danger or unauthorised access","examples":[{"en":"Strong passwords improve account security.","zh":"强密码能提高账户安全性。"},{"en":"The company invested in better data security.","zh":"公司投资改善了数据安全。"},{"en":"Airport security checks can take a long time.","zh":"机场安检可能耗时较长。"}]},{"pos":"n.","meaning":"抵押品;担保","definition":"property offered as protection for a loan","examples":[{"en":"The bank accepted the house as security.","zh":"银行接受房屋作为抵押。"},{"en":"The lender required additional security.","zh":"贷款人要求额外担保。"}]},{"pos":"n.","meaning":"证券（常用复数）","definition":"a tradable financial asset such as a bond or share","examples":[{"en":"The fund holds government securities.","zh":"基金持有政府证券。"},{"en":"The firm trades securities for clients.","zh":"公司为客户交易证券。"}]}],"sedentary":[{"pos":"adj.","meaning":"久坐的；少活动的","definition":"involving much sitting and little physical activity","examples":[{"en":"The job is largely sedentary.","zh":"这份工作大多需要久坐。"},{"en":"She changed her sedentary routine.","zh":"她改变了久坐的日常习惯。"}]},{"pos":"adj.","meaning":"定居的；不迁徙的","definition":"remaining in one place rather than migrating","examples":[{"en":"These birds are sedentary throughout the year.","zh":"这些鸟全年不迁徙。"},{"en":"The study compares nomadic and sedentary communities.","zh":"研究比较游牧与定居群体。"}]},{"pos":"adj.","meaning":"原地形成的；残积的（土壤）","definition":"remaining where formed rather than transported","examples":[{"en":"The geologist identified a sedentary soil above the bedrock.","zh":"地质学家辨认出基岩上方的残积土。"},{"en":"Sedentary soils reflect the rock beneath them.","zh":"残积土反映了其下方岩石的特征。"}]}],"sediment":[{"pos":"n.","meaning":"沉积物；沉淀物","definition":"Material that settles at the bottom of a liquid or is deposited by water.","examples":[{"en":"A layer of sediment covered the riverbed.","zh":"河床上覆盖着一层沉积物。"},{"en":"Leave the bottle still so the sediment can settle.","zh":"让瓶子静置，以便沉淀物沉降。"}]}],"seduce":[{"pos":"v.","meaning":"诱使发生性关系;勾引","definition":"to persuade someone to have sexual relations","examples":[{"en":"The novel describes a courtier trying to seduce the countess.","zh":"小说描写朝臣试图勾引伯爵夫人。"},{"en":"She rejected his attempt to seduce her.","zh":"她拒绝了他的勾引。"}]},{"pos":"v.","meaning":"诱惑;诱使","definition":"to attract someone into a course of action","examples":[{"en":"The low price seduced buyers into ignoring the flaws.","zh":"低价诱使买家忽视缺陷。"},{"en":"He was seduced by promises of easy success.","zh":"他被轻易成功的承诺诱惑。"}]}],"seek":[{"pos":"v.","meaning":"寻找；探索；追求","definition":"to try to find or obtain something","examples":[{"en":"They seek a solution to the problem.","zh":"他们寻找问题的解决方法。"},{"en":"She travelled to seek new opportunities.","zh":"她为了寻求新机会而旅行。"}]}],"seep":[{"pos":"v.","meaning":"渗出；渗入；渗漏","definition":"To move slowly through small openings.","examples":[{"en":"Water seeped through the cracked wall.","zh":"水从开裂的墙体渗了进来。"},{"en":"Oil was seeping from the damaged pipe.","zh":"油正从损坏的管道渗出。"}]}],"segment":[{"pos":"n.","meaning":"部分;片段;节;瓣","definition":"a distinct part of something","examples":[{"en":"The company targets a small market segment.","zh":"公司针对一个小市场分部。"},{"en":"She separated the orange into segments.","zh":"她把橘子分成瓣。"}]},{"pos":"n.","meaning":"线段;弓形","definition":"a bounded part of a line or circle","examples":[{"en":"Draw a line segment between the points.","zh":"在两点间画一条线段。"},{"en":"The chord divides the circle into two segments.","zh":"弦把圆分成两个弓形区域。"}]}],"segregate":[{"pos":"v.","meaning":"隔离；分开","definition":"to keep groups or things separate","examples":[{"en":"The plant segregates waste by type.","zh":"工厂按类别分离废物。"},{"en":"The old system segregated pupils by background.","zh":"旧制度按背景隔离学生。"}]}],"select":[{"pos":"v.","meaning":"选择；挑选","definition":"To choose from several possibilities.","examples":[{"en":"Select the correct answer from the list.","zh":"从列表中选择正确答案。"},{"en":"The committee selected three finalists.","zh":"委员会选出了三名决赛选手。"}]},{"pos":"adj.","meaning":"精选的；优等的；小范围的","definition":"Carefully chosen for special quality or status.","examples":[{"en":"A select group of students attended the workshop.","zh":"一小批经过挑选的学生参加了工作坊。"},{"en":"The shop offers a select range of local cheeses.","zh":"商店供应精选的当地奶酪。"}]}],"self-esteem":[{"pos":"n.","meaning":"自尊;自我价值感","definition":"confidence in one's own worth","examples":[{"en":"Supportive feedback improved her self-esteem.","zh":"支持性的反馈提高了她的自尊。"},{"en":"Repeated ridicule damaged the child's self-esteem.","zh":"反复嘲笑伤害了孩子的自尊。"}]}],"semantic":[{"pos":"adj.","meaning":"语义的","definition":"relating to meaning in language","examples":[{"en":"The words have a subtle semantic difference.","zh":"这些词有细微的语义差别。"},{"en":"The study examines semantic change.","zh":"研究考察语义变化。"}]}],"semester":[{"pos":"n.","meaning":"学期","definition":"One of the main periods into which an academic year is divided.","examples":[{"en":"She is taking four courses this semester.","zh":"这学期她修四门课。"},{"en":"The autumn semester begins in September.","zh":"秋季学期九月开始。"}]}],"seminar":[{"pos":"n.","meaning":"研讨会;讨论课","definition":"a meeting or class involving focused discussion","examples":[{"en":"The seminar examined renewable energy.","zh":"研讨会探讨了可再生能源。"},{"en":"Students presented papers in the weekly seminar.","zh":"学生在每周讨论课上报告论文。"}]}],"senior":[{"pos":"adj.","meaning":"级别高的；资历深的","definition":"higher in rank or experience","examples":[{"en":"A senior engineer reviewed the design.","zh":"一位资深工程师审查了设计。"},{"en":"She holds a senior position.","zh":"她担任高级职位。"}]},{"pos":"adj.","meaning":"年长的","definition":"older than another person","examples":[{"en":"He is three years senior to me.","zh":"他比我年长三岁。"},{"en":"The centre runs activities for senior citizens.","zh":"中心为老年人举办活动。"}]},{"pos":"n.","meaning":"较年长者；资深者","definition":"a person older or higher in rank","examples":[{"en":"She listened carefully to her seniors.","zh":"她认真听取资深同事的意见。"},{"en":"He is her senior by several years.","zh":"他比她年长几岁。"}]},{"pos":"n.","meaning":"毕业班学生（美式）","definition":"a student in the final year of school or college","examples":[{"en":"The seniors are preparing for graduation.","zh":"毕业班学生正准备毕业。"},{"en":"As a senior, she completed a research project.","zh":"作为毕业班学生，她完成了一项研究项目。"}]}],"sensation":[{"pos":"n.","meaning":"感觉；知觉；感觉能力","definition":"A physical feeling or the ability to feel.","examples":[{"en":"She felt a tingling sensation in her fingers.","zh":"她感到手指有刺麻感。"},{"en":"Sensation slowly returned to his foot.","zh":"他的脚慢慢恢复了知觉。"}]},{"pos":"n.","meaning":"轰动；引起轰动的人或事","definition":"Great public excitement or its cause.","examples":[{"en":"The discovery caused a sensation.","zh":"这一发现引起了轰动。"},{"en":"The young singer became an overnight sensation.","zh":"这位年轻歌手一夜成名。"}]}],"sensational":[{"pos":"adj.","meaning":"轰动性的;耸人听闻的","definition":"causing great public excitement or shock","examples":[{"en":"The paper printed a sensational headline.","zh":"报纸刊登了耸人听闻的标题。"},{"en":"The trial produced sensational revelations.","zh":"审判披露了轰动性消息。"}]},{"pos":"adj.","meaning":"极好的;绝妙的","definition":"extremely impressive or enjoyable","examples":[{"en":"The singer gave a sensational performance.","zh":"歌手献上了绝妙表演。"},{"en":"The view from the summit was sensational.","zh":"峰顶景色美妙绝伦。"}]}],"sensible":[{"pos":"adj.","meaning":"明智的；合情理的","definition":"showing good practical judgment","examples":[{"en":"That seems a sensible solution.","zh":"那似乎是个明智的解决方案。"},{"en":"She made a sensible choice.","zh":"她作出了合理选择。"}]},{"pos":"adj.","meaning":"可感知的；意识到的（正式）","definition":"perceptible or aware of something","examples":[{"en":"There was a sensible change in temperature.","zh":"温度有可感知的变化。"},{"en":"He was sensible of the responsibility.","zh":"他意识到了这项责任。"}]}],"sensitive":[{"pos":"adj.","meaning":"敏感的；灵敏的","definition":"Quick to detect or respond to small changes.","examples":[{"en":"The instrument is sensitive to tiny temperature changes.","zh":"仪器对微小温度变化很灵敏。"},{"en":"Her skin is sensitive to strong sunlight.","zh":"她的皮肤对强烈阳光很敏感。"}]},{"pos":"adj.","meaning":"容易受伤的；容易生气的","definition":"Easily hurt or upset.","examples":[{"en":"He is sensitive about criticism of his work.","zh":"他对别人批评自己的工作很敏感。"},{"en":"Be gentle with her; she is feeling particularly sensitive today.","zh":"对她温和一些，她今天情绪特别敏感。"}]},{"pos":"adj.","meaning":"敏感的；需谨慎处理的","definition":"Likely to cause difficulty or requiring protection.","examples":[{"en":"The report contains sensitive personal information.","zh":"报告包含敏感个人信息。"},{"en":"We discussed a sensitive issue in private.","zh":"我们私下讨论了一个敏感问题。"}]}],"sensory":[{"pos":"adj.","meaning":"感觉的;感官的","definition":"relating to the senses","examples":[{"en":"The exhibition offers a rich sensory experience.","zh":"展览提供丰富的感官体验。"},{"en":"Sensory information reaches the brain.","zh":"感觉信息传至大脑。"}]}],"sentient":[{"pos":"adj.","meaning":"有感知能力的","definition":"capable of sensation or conscious experience","examples":[{"en":"The novel imagines a sentient machine.","zh":"小说想象了一台有知觉的机器。"},{"en":"The discussion concerns the treatment of sentient animals.","zh":"讨论涉及如何对待有感知能力的动物。"}]},{"pos":"adj.","meaning":"知悉的；能意识到的（正式）","definition":"aware of something","examples":[{"en":"She seemed sentient of the change around her.","zh":"她似乎意识到了周围的变化。"},{"en":"The narrator is sentient of approaching danger.","zh":"叙述者察觉到了逼近的危险。"}]}],"separate":[{"pos":"v.","meaning":"分开；分离；区分","definition":"To divide things or keep them apart.","examples":[{"en":"Separate the paper from the plastic.","zh":"把纸和塑料分开。"},{"en":"A narrow river separates the two villages.","zh":"一条窄河把两个村庄隔开。"}],"ipa":"/ˈsepəreɪt/"},{"pos":"v.","meaning":"分居；分手","definition":"To stop living together as a couple.","examples":[{"en":"They separated after many years of marriage.","zh":"结婚多年后，他们分居了。"},{"en":"The couple decided to separate temporarily.","zh":"这对夫妇决定暂时分居。"}],"ipa":"/ˈsepəreɪt/"},{"pos":"adj.","meaning":"分开的；独立的；不同的","definition":"Not joined or shared with something else.","examples":[{"en":"Each child has a separate bedroom.","zh":"每个孩子都有单独的卧室。"},{"en":"That is a separate issue we should discuss later.","zh":"那是另一个问题，我们稍后再讨论。"}],"ipa":"/ˈseprət/"}],"sequence":[{"pos":"n.","meaning":"一连串;系列","definition":"a set of related things following each other","examples":[{"en":"The film opens with a sequence of aerial shots.","zh":"电影以一连串航拍镜头开场。"},{"en":"A sequence of errors caused the failure.","zh":"一连串错误导致失败。"}]},{"pos":"n.","meaning":"顺序;次序","definition":"the order in which things happen","examples":[{"en":"Put the photographs in chronological sequence.","zh":"按时间顺序排列照片。"},{"en":"The instructions must be followed in sequence.","zh":"必须依次遵循指示。"}]}],"serial":[{"pos":"n.","meaning":"连续剧；连载作品","definition":"a story broadcast or published in parts","examples":[{"en":"The radio serial ended this week.","zh":"广播连续剧本周结束。"},{"en":"She followed the newspaper serial.","zh":"她追读报纸上的连载。"}]},{"pos":"adj.","meaning":"连续的；顺序排列的","definition":"occurring in a sequence","examples":[{"en":"The parts have serial numbers.","zh":"零件有序列号。"},{"en":"The experiment involved serial measurements.","zh":"实验进行了连续测量。"}]}],"series":[{"pos":"n.","meaning":"一系列；连续；丛书；系列节目","definition":"A group of related things arranged in order.","examples":[{"en":"The museum organised a series of lectures.","zh":"博物馆组织了一系列讲座。"},{"en":"She is reading the final book in the series.","zh":"她正在读这套丛书的最后一本。"}]}],"service":[{"pos":"n.","meaning":"服务;帮助","definition":"work done for others","examples":[{"en":"The staff provided excellent service.","zh":"员工提供了优质服务。"},{"en":"The volunteers offered a valuable service.","zh":"志愿者提供了宝贵帮助。"}]},{"pos":"n.","meaning":"公共服务;公共事业;服务机构","definition":"an organized system providing a public need","examples":[{"en":"The village has a regular bus service.","zh":"村庄有定时公交服务。"},{"en":"She joined the civil service.","zh":"她加入了公务员队伍。"}]},{"pos":"n.","meaning":"维修;保养","definition":"maintenance to keep something working","examples":[{"en":"The car needs a service.","zh":"汽车需要保养。"},{"en":"The annual service includes safety checks.","zh":"年度保养包括安全检查。"}]},{"pos":"v.","meaning":"维修;保养","definition":"to maintain or repair equipment","examples":[{"en":"A technician serviced the boiler.","zh":"技术员保养了锅炉。"},{"en":"The machines are serviced every month.","zh":"机器每月维护一次。"}]}],"session":[{"pos":"n.","meaning":"一场；一节；会议期","definition":"a period devoted to a particular activity","examples":[{"en":"The training session lasts an hour.","zh":"培训课持续一小时。"},{"en":"Parliament began a new session.","zh":"议会开始了新的会期。"}]}],"setting":[{"pos":"n.","meaning":"环境；背景；场景","definition":"The place and circumstances in which something happens.","examples":[{"en":"The village provides a peaceful setting for the retreat.","zh":"村庄为静修活动提供了宁静环境。"},{"en":"The novel's setting is a nineteenth-century port.","zh":"小说的背景是一座十九世纪港口。"}]},{"pos":"n.","meaning":"安放；设定；设置","definition":"The act of arranging something or an adjustable position on a device.","examples":[{"en":"The setting of the stones required great care.","zh":"安放石块需要十分小心。"},{"en":"Use the lowest heat setting.","zh":"请使用最低温度设置。"}]}],"settle":[{"pos":"v.","meaning":"定居;安家","definition":"to begin living permanently somewhere","examples":[{"en":"They settled in a small coastal town.","zh":"他们在海滨小镇定居。"},{"en":"The family settled abroad after the war.","zh":"战后这家人在国外定居。"}]},{"pos":"v.","meaning":"解决;调停","definition":"to resolve a disagreement or problem","examples":[{"en":"The neighbours settled their dispute.","zh":"邻居解决了争执。"},{"en":"We settled the question by voting.","zh":"我们通过投票解决了问题。"}]},{"pos":"v.","meaning":"安顿;安置;使平静","definition":"to put into a comfortable or stable state","examples":[{"en":"She settled the baby in the cot.","zh":"她把婴儿安顿在小床里。"},{"en":"Give the children time to settle.","zh":"给孩子时间安静下来。"}]},{"pos":"v.","meaning":"付清;结算","definition":"to pay money owed","examples":[{"en":"He settled the bill before leaving.","zh":"他离开前结清账单。"},{"en":"The company settled its debts.","zh":"公司还清了债务。"}]},{"pos":"v.","meaning":"落下;停留;沉降","definition":"to come to rest or sink gradually","examples":[{"en":"A butterfly settled on the leaf.","zh":"蝴蝶落在叶上。"},{"en":"Dust settled on the unused desk.","zh":"灰尘落在闲置书桌上。"}]}],"severe":[{"pos":"adj.","meaning":"严重的；剧烈的","definition":"very great in intensity or harmful effect","examples":[{"en":"The storm caused severe damage.","zh":"风暴造成严重损害。"},{"en":"The region faces a severe shortage of water.","zh":"该地区严重缺水。"}]},{"pos":"adj.","meaning":"严厉的；严格的","definition":"very harsh or strict","examples":[{"en":"The offence carries a severe penalty.","zh":"该违法行为会受到严厉处罚。"},{"en":"She gave him a severe look.","zh":"她严厉地看了他一眼。"}]}],"shade":[{"pos":"n.","meaning":"阴凉处；阴影；暗部","definition":"An area sheltered from direct light.","examples":[{"en":"We rested in the shade of a tree.","zh":"我们在树荫下休息。"},{"en":"The artist balanced areas of light and shade.","zh":"画家平衡了画面中的明暗区域。"}]},{"pos":"n.","meaning":"灯罩；遮光物","definition":"A covering used to soften or block light.","examples":[{"en":"The lamp has a green glass shade.","zh":"这盏灯有一个绿色玻璃灯罩。"},{"en":"She lowered the window shade.","zh":"她放下了窗帘遮光。"}]},{"pos":"n.","meaning":"色度；色调","definition":"A particular variety or depth of colour.","examples":[{"en":"Choose a lighter shade of blue.","zh":"选一种浅一点的蓝色。"},{"en":"The leaves turned different shades of red.","zh":"树叶变成了深浅不同的红色。"}]},{"pos":"n.","meaning":"细微差别；少许","definition":"A slight difference or small degree.","examples":[{"en":"The translation captures subtle shades of meaning.","zh":"译文捕捉到了细微的意义差别。"},{"en":"His tone carried a shade of doubt.","zh":"他的语气带着一丝怀疑。"}]},{"pos":"v.","meaning":"遮蔽；遮光","definition":"To protect something from direct light.","examples":[{"en":"She shaded her eyes with her hand.","zh":"她用手遮住眼睛挡光。"},{"en":"Trees shade the western wall.","zh":"树木为西墙遮阳。"}]},{"pos":"v.","meaning":"把……涂暗；画阴影","definition":"To darken an area in a drawing.","examples":[{"en":"Shade the lower half of the circle.","zh":"给圆的下半部分涂上阴影。"},{"en":"He shaded the drawing with a soft pencil.","zh":"他用软铅笔给画加阴影。"}]}],"shaft":[{"pos":"n.","meaning":"轴;杆;柄","definition":"a long narrow rod or handle","examples":[{"en":"The motor turns the drive shaft.","zh":"电机转动传动轴。"},{"en":"The spear's wooden shaft broke.","zh":"长矛木杆断了。"}]},{"pos":"n.","meaning":"一束光;一道光线","definition":"a narrow beam of light","examples":[{"en":"A shaft of sunlight entered the cave.","zh":"一束阳光照进洞穴。"},{"en":"Dust glittered in the shaft of light.","zh":"尘埃在光束中闪烁。"}]},{"pos":"n.","meaning":"竖井;升降井","definition":"a deep narrow vertical passage","examples":[{"en":"Miners descended the shaft.","zh":"矿工下到竖井。"},{"en":"The lift shaft runs through the building.","zh":"电梯井贯穿大楼。"}]}],"shallow":[{"pos":"adj.","meaning":"浅的","definition":"not deep","examples":[{"en":"The children played in shallow water.","zh":"孩子们在浅水中玩耍。"},{"en":"Use a shallow dish for the mixture.","zh":"用浅盘装混合物。"}]},{"pos":"adj.","meaning":"肤浅的；浅薄的","definition":"lacking serious thought or depth","examples":[{"en":"The article offers a shallow analysis.","zh":"文章的分析很肤浅。"},{"en":"She disliked his shallow judgments.","zh":"她不喜欢他浅薄的判断。"}]}],"shareholder":[{"pos":"n.","meaning":"股东；股票持有人","definition":"A person or organisation owning shares in a company.","examples":[{"en":"Shareholders voted on the proposal.","zh":"股东就提案进行了投票。"},{"en":"The annual report was sent to every shareholder.","zh":"年报发送给了每位股东。"}]}],"shark":[{"pos":"n.","meaning":"鲨鱼","definition":"a large fish with a cartilaginous skeleton and sharp teeth","examples":[{"en":"A shark swam beneath the boat.","zh":"一条鲨鱼在船下游过。"},{"en":"Researchers tagged the shark to track its movements.","zh":"研究人员给鲨鱼加标签追踪活动。"}]},{"pos":"n.","meaning":"诈骗者;盘剥者","definition":"a dishonest person exploiting others","examples":[{"en":"The borrowers fell victim to a loan shark.","zh":"借款人落入高利贷者之手。"},{"en":"The inexperienced buyer was cheated by a shark.","zh":"没经验的买家被骗子骗了。"}]}],"sharpen":[{"pos":"v.","meaning":"削尖；磨快","definition":"to make an edge or point sharp","examples":[{"en":"He sharpened the pencil.","zh":"他削尖了铅笔。"},{"en":"The cook sharpened the knife.","zh":"厨师磨快了刀。"}]},{"pos":"v.","meaning":"使敏锐；增强","definition":"to make a skill or quality more effective","examples":[{"en":"The debate sharpened her thinking.","zh":"辩论使她的思维更敏锐。"},{"en":"Practice sharpened his observation skills.","zh":"练习增强了他的观察力。"}]}],"shatter":[{"pos":"v.","meaning":"使破碎；碎裂","definition":"To break suddenly into many pieces.","examples":[{"en":"The glass shattered on the floor.","zh":"玻璃掉在地上碎裂了。"},{"en":"The impact shattered the window.","zh":"撞击震碎了窗户。"}]},{"pos":"v.","meaning":"使极度震惊；粉碎希望；给予沉重打击","definition":"To seriously damage someone's hopes, confidence, or emotional state.","examples":[{"en":"The rejection shattered his confidence.","zh":"这次拒绝严重打击了他的信心。"},{"en":"The news shattered the family's hopes.","zh":"这个消息粉碎了这家人的希望。"}]}],"shave":[{"pos":"v.","meaning":"剃须;刮除毛发","definition":"to remove hair with a razor","examples":[{"en":"He shaves every morning.","zh":"他每天早晨刮胡子。"},{"en":"She shaved her legs before swimming.","zh":"她游泳前剃了腿毛。"}]},{"pos":"n.","meaning":"剃须;刮毛","definition":"an act of shaving","examples":[{"en":"He needs a shave before the interview.","zh":"面试前他需要刮胡子。"},{"en":"The barber gave him a close shave.","zh":"理发师给他刮得很干净。"}]}],"sheer":[{"pos":"adj.","meaning":"纯粹的；十足的","definition":"used to emphasise the degree or completeness of something","examples":[{"en":"She succeeded through sheer determination.","zh":"她完全凭毅力取得成功。"},{"en":"The sheer size of the building amazed us.","zh":"仅建筑的体量就让我们惊叹。"}]},{"pos":"adj.","meaning":"陡峭的；近乎垂直的","definition":"very steep","examples":[{"en":"A sheer cliff rose above the beach.","zh":"陡峭悬崖耸立在海滩上方。"},{"en":"The path ends at a sheer drop.","zh":"小路尽头是垂直落差。"}]}],"shell":[{"pos":"n.","meaning":"壳；外壳","definition":"A hard outer covering.","examples":[{"en":"The crab's shell protects its body.","zh":"螃蟹的壳保护着身体。"},{"en":"She collected empty shells on the beach.","zh":"她在海滩上捡空贝壳。"}]},{"pos":"n.","meaning":"炮弹","definition":"An explosive projectile fired from a large gun.","examples":[{"en":"An unexploded shell was found near the field.","zh":"田野附近发现了一枚未爆炮弹。"},{"en":"The museum displays shells from the old fort.","zh":"博物馆展出了来自旧堡垒的炮弹。"}]},{"pos":"v.","meaning":"剥壳；去壳","definition":"To remove the outer covering from food.","examples":[{"en":"She shelled the peas into a bowl.","zh":"她把豌豆剥进碗里。"},{"en":"We shelled the nuts before baking.","zh":"烘焙前，我们剥掉了坚果壳。"}]},{"pos":"v.","meaning":"炮击","definition":"To attack with explosive shells.","examples":[{"en":"The army shelled the abandoned fort.","zh":"军队炮击了废弃堡垒。"},{"en":"Several buildings were damaged when the area was shelled.","zh":"该地区遭炮击时，几栋建筑受损。"}]}],"shelter":[{"pos":"n.","meaning":"庇护;遮蔽;住所","definition":"protection from danger or weather or a place providing it","examples":[{"en":"We found shelter beneath a bridge.","zh":"我们在桥下找到避雨处。"},{"en":"The charity provides food and shelter.","zh":"慈善机构提供食物和住所。"}]},{"pos":"v.","meaning":"庇护;躲避;遮挡","definition":"to protect or take refuge","examples":[{"en":"We sheltered from the rain in a doorway.","zh":"我们在门口躲雨。"},{"en":"The barn sheltered the animals from snow.","zh":"谷仓为动物挡住风雪。"}]}],"shift":[{"pos":"n.","meaning":"轮班；班次","definition":"a scheduled period of work","examples":[{"en":"My night shift starts at ten.","zh":"我的夜班十点开始。"},{"en":"Can you cover my shift on Saturday?","zh":"周六你能替我值班吗？"},{"en":"Each shift lasts eight hours.","zh":"每个班次持续八小时。"}]},{"pos":"v.","meaning":"转变；转移","definition":"to move or change position or direction","examples":[{"en":"We need to shift our attention to prevention.","zh":"我们需要把注意力转向预防。"},{"en":"Consumers may shift from cars to public transport.","zh":"消费者可能从汽车转向公共交通。"},{"en":"The policy could shift investment towards renewable energy.","zh":"该政策可能使投资转向可再生能源。"}]},{"pos":"n.","meaning":"转变；变化","definition":"a change in position or approach","examples":[{"en":"The survey reveals a shift in opinion.","zh":"调查显示意见发生了转变。"},{"en":"There has been a shift towards renewable energy.","zh":"人们已转向可再生能源。"}]},{"pos":"v.","meaning":"移动；挪动位置","definition":"to move something or oneself to another position","examples":[{"en":"We shifted the sofa closer to the window.","zh":"我们把沙发移得更靠近窗户。"},{"en":"He shifted his weight from one foot to the other.","zh":"他把身体重心从一只脚移到另一只脚上。"}]}],"shilling":[{"pos":"n.","meaning":"先令","definition":"A monetary unit used in some countries and formerly in Britain.","examples":[{"en":"The old ticket cost one shilling.","zh":"这张旧票的价格是一先令。"},{"en":"The collection contains a silver shilling.","zh":"藏品中有一枚银先令。"}]}],"shin":[{"pos":"n.","meaning":"胫;小腿前部;胫骨部位","definition":"the front of the lower leg","examples":[{"en":"He bruised his shin on the bench.","zh":"他的小腿前部撞在长凳上瘀青了。"},{"en":"Footballers wear guards to protect their shins.","zh":"足球运动员戴护腿板保护胫部。"}]},{"pos":"v.","meaning":"手脚并用攀爬","definition":"to climb using arms and legs","examples":[{"en":"The boy shinned up the tree.","zh":"男孩手脚并用爬上树。"},{"en":"She shinned down the rope.","zh":"她沿绳子手脚并用滑爬下来。"}]}],"shipment":[{"pos":"n.","meaning":"装运；运输","definition":"the act of sending goods","examples":[{"en":"The goods are ready for shipment.","zh":"货物已可装运。"},{"en":"Shipment was delayed by bad weather.","zh":"装运因坏天气延误。"}]},{"pos":"n.","meaning":"一批运输的货物","definition":"a quantity of goods sent together","examples":[{"en":"A shipment of books arrived today.","zh":"一批图书今天到达。"},{"en":"The warehouse inspected the new shipment.","zh":"仓库检查了新到的货物。"}]}],"shore":[{"pos":"n.","meaning":"岸；滨；海岸","definition":"The land along the edge of a sea or lake.","examples":[{"en":"We walked along the shore.","zh":"我们沿着岸边散步。"},{"en":"The boat reached shore before the storm.","zh":"暴风雨来临前，船抵达了岸边。"}]}],"short-term":[{"pos":"adj.","meaning":"短期的","definition":"lasting for a brief period","examples":[{"en":"We need a short-term solution.","zh":"我们需要短期解决方案。"},{"en":"The position offers a short-term contract.","zh":"这个岗位提供短期合同。"}]}],"shortage":[{"pos":"n.","meaning":"短缺；不足","definition":"a lack of enough of something","examples":[{"en":"The town faces a water shortage.","zh":"小镇面临缺水。"},{"en":"A shortage of staff slowed the work.","zh":"人员不足减缓了工作。"}]}],"shorthand":[{"pos":"n.","meaning":"速记法；速记","definition":"A system of rapid writing using symbols and abbreviations.","examples":[{"en":"The secretary took notes in shorthand.","zh":"秘书用速记法记笔记。"},{"en":"She learned shorthand for her first office job.","zh":"为了第一份办公室工作，她学习了速记。"}]}],"shrewd":[{"pos":"adj.","meaning":"精明的;敏锐的","definition":"showing good practical judgement","examples":[{"en":"She made a shrewd investment.","zh":"她作出精明投资。"},{"en":"His shrewd questions exposed the weakness.","zh":"他敏锐的提问揭露了薄弱之处。"}]}],"shrink":[{"pos":"v.","meaning":"缩小；收缩；萎缩","definition":"to become or make smaller","examples":[{"en":"The jumper shrank in the wash.","zh":"毛衣洗后缩水了。"},{"en":"The market has shrunk considerably.","zh":"市场已大幅萎缩。"}]}],"shrub":[{"pos":"n.","meaning":"灌木","definition":"A woody plant smaller than a tree with several stems.","examples":[{"en":"A flowering shrub grows beside the gate.","zh":"门旁长着一株开花灌木。"},{"en":"They planted shrubs along the fence.","zh":"他们沿着围栏种了灌木。"}]}],"shrug":[{"pos":"v.","meaning":"耸肩","definition":"to raise the shoulders to show uncertainty or indifference","examples":[{"en":"He shrugged when asked where it was.","zh":"问到它在哪里时，他耸了耸肩。"},{"en":"She shrugged and changed the subject.","zh":"她耸耸肩，换了话题。"}]},{"pos":"n.","meaning":"耸肩","definition":"a movement of the shoulders showing uncertainty or indifference","examples":[{"en":"Her only answer was a shrug.","zh":"她只是耸肩作答。"},{"en":"He dismissed the complaint with a shrug.","zh":"他耸肩对投诉不予理会。"}]}],"shutter":[{"pos":"n.","meaning":"百叶窗；遮窗板","definition":"a hinged cover for a window","examples":[{"en":"They closed the shutters before the storm.","zh":"他们在风暴前关上了遮窗板。"},{"en":"Sunlight filtered through the shutters.","zh":"阳光透过百叶窗。"}]},{"pos":"n.","meaning":"相机快门","definition":"the mechanism controlling light exposure in a camera","examples":[{"en":"The shutter clicked quietly.","zh":"快门轻轻响了一声。"},{"en":"A fast shutter captured the moving bird.","zh":"快速快门捕捉到了飞鸟。"}]}],"shuttle":[{"pos":"n.","meaning":"航天飞机","definition":"A reusable spacecraft designed to travel between Earth and space.","examples":[{"en":"The shuttle carried equipment into orbit.","zh":"航天飞机把设备送入轨道。"},{"en":"The museum displays a model of the space shuttle.","zh":"博物馆展出了一架航天飞机模型。"}]}],"siesta":[{"pos":"n.","meaning":"午睡;午休","definition":"a rest or sleep in the early afternoon","examples":[{"en":"They took a siesta after lunch.","zh":"他们午饭后小睡。"},{"en":"The village grew quiet during siesta time.","zh":"村庄午休时变得安静。"}]}],"sift":[{"pos":"v.","meaning":"筛；筛分","definition":"to separate particles using a sieve","examples":[{"en":"Sift the flour into a bowl.","zh":"把面粉筛进碗里。"},{"en":"Workers sifted sand to remove stones.","zh":"工人筛沙去除石子。"}]},{"pos":"v.","meaning":"仔细检查；筛选","definition":"to examine carefully to find useful material","examples":[{"en":"She sifted through the old letters.","zh":"她仔细翻查旧信。"},{"en":"The team sifted the evidence for clues.","zh":"团队仔细审查证据寻找线索。"}]}],"signal":[{"pos":"n.","meaning":"信号；暗号；标志","definition":"A sign or message conveying information.","examples":[{"en":"A red light is a signal to stop.","zh":"红灯是停止的信号。"},{"en":"The agreement sent a signal of cooperation.","zh":"协议传递了合作的信号。"}]},{"pos":"v.","meaning":"发信号；示意","definition":"To communicate with a gesture or device.","examples":[{"en":"She signalled for the driver to stop.","zh":"她示意司机停车。"},{"en":"Signal before changing lanes.","zh":"变道前要打转向灯。"}]},{"pos":"v.","meaning":"标志；表明","definition":"To show that something is happening or likely.","examples":[{"en":"The new policy signals a change in priorities.","zh":"新政策标志着优先事项发生变化。"},{"en":"Falling demand may signal a slowdown.","zh":"需求下降可能表明经济放缓。"}]}],"signature":[{"pos":"n.","meaning":"签名;签字","definition":"a person's name written as confirmation","examples":[{"en":"Your signature is required here.","zh":"这里需要你的签名。"},{"en":"The collector recognised the artist's signature.","zh":"收藏家认出了艺术家的签名。"}]}],"significance":[{"pos":"n.","meaning":"重要性；意义","definition":"importance or meaning","examples":[{"en":"The discovery has great significance.","zh":"发现意义重大。"},{"en":"I did not understand the significance of her remark.","zh":"我不理解她那句话的含义。"}]}],"significant":[{"pos":"adj.","meaning":"显著的；重要的","definition":"important or large enough to matter","examples":[{"en":"The policy had a significant effect on travel costs.","zh":"该政策对出行费用产生了显著影响。"},{"en":"There is a significant difference between the two proposals.","zh":"这两项提议存在明显差异。"},{"en":"Education plays a significant role in social mobility.","zh":"教育在社会流动中发挥重要作用。"}]}],"signpost":[{"pos":"n.","meaning":"路标;指引标志","definition":"a sign giving directions","examples":[{"en":"The signpost points toward the station.","zh":"路标指向车站。"},{"en":"A fallen branch hid the signpost.","zh":"掉落树枝遮住了路标。"}]},{"pos":"v.","meaning":"设置路标;标明方向","definition":"to mark a route or indicate clearly","examples":[{"en":"The path is clearly signposted.","zh":"小路的路标很清楚。"},{"en":"The introduction signposts the argument's main stages.","zh":"导言标明了论证的主要步骤。"}]}],"silicon":[{"pos":"n.","meaning":"硅","definition":"a chemical element used in many electronic components","examples":[{"en":"The chip is made from silicon.","zh":"芯片由硅制成。"},{"en":"Silicon is present in many minerals.","zh":"许多矿物中含有硅。"}]}],"silt":[{"pos":"n.","meaning":"淤泥；粉砂；泥沙沉积物","definition":"Fine material carried and deposited by water.","examples":[{"en":"The flood left a layer of silt.","zh":"洪水留下一层淤泥。"},{"en":"Silt collected at the mouth of the river.","zh":"泥沙在河口聚集。"}]},{"pos":"v.","meaning":"淤塞；使淤积","definition":"To fill or become blocked with silt.","examples":[{"en":"The channel gradually silted up.","zh":"水道逐渐淤塞。"},{"en":"Sediment from the hills silted the reservoir.","zh":"山上的沉积物使水库淤积。"}]}],"similarly":[{"pos":"adv.","meaning":"同样地;类似地","definition":"in a similar way","examples":[{"en":"The two machines operate similarly.","zh":"两台机器的运转方式相似。"},{"en":"She was tired; similarly, her companions needed rest.","zh":"她很累，同样地，同伴也需要休息。"}]}],"simplicity":[{"pos":"n.","meaning":"简单；简易","definition":"the quality of being easy to understand or use","examples":[{"en":"The design's simplicity makes it effective.","zh":"设计的简单使它有效。"},{"en":"We chose the method for its simplicity.","zh":"我们因其简便而选用这个方法。"}]},{"pos":"n.","meaning":"朴素；不加修饰","definition":"the absence of unnecessary decoration","examples":[{"en":"She admired the room's simplicity.","zh":"她欣赏房间的朴素。"},{"en":"The ceremony was marked by simplicity.","zh":"仪式以简朴为特色。"}]},{"pos":"n.","meaning":"单纯；直率","definition":"an uncomplicated and sincere manner","examples":[{"en":"His simplicity put the guests at ease.","zh":"他的淳朴使客人放松。"},{"en":"She spoke with touching simplicity.","zh":"她说话单纯坦率，令人感动。"}]}],"simplify":[{"pos":"v.","meaning":"简化；使容易理解","definition":"To make something less complicated.","examples":[{"en":"The chart simplifies a complex process.","zh":"图表简化了复杂过程。"},{"en":"We simplified the application form.","zh":"我们简化了申请表。"}]}],"simplistic":[{"pos":"adj.","meaning":"过分简单化的","definition":"ignoring important complexity","examples":[{"en":"That is a simplistic explanation of poverty.","zh":"那是对贫困的过分简化解释。"},{"en":"The proposal offers simplistic answers to complex problems.","zh":"提案对复杂问题给出了过于简单的答案。"}]}],"simulate":[{"pos":"v.","meaning":"模拟；模仿","definition":"to reproduce conditions for testing or training","examples":[{"en":"The model simulates traffic flow.","zh":"模型模拟交通流量。"},{"en":"Pilots train in equipment that simulates flight.","zh":"飞行员在模拟飞行的设备中训练。"}]},{"pos":"v.","meaning":"假装；伪装","definition":"to pretend to have a feeling or condition","examples":[{"en":"He tried to simulate surprise.","zh":"他试图假装惊讶。"},{"en":"The actor simulated exhaustion convincingly.","zh":"演员逼真地表现了筋疲力尽。"}]}],"simulation":[{"pos":"n.","meaning":"模拟；仿真","definition":"A model or imitation used to study or practise a real situation.","examples":[{"en":"Pilots trained in a flight simulation.","zh":"飞行员在飞行模拟中训练。"},{"en":"The computer simulation predicted the water flow.","zh":"计算机模拟预测了水流情况。"}]},{"pos":"n.","meaning":"假装；伪装","definition":"The act of pretending to have a feeling or condition.","examples":[{"en":"His simulation of surprise convinced nobody.","zh":"他假装惊讶，却没骗过任何人。"},{"en":"The scene required a convincing simulation of fear.","zh":"这场戏要求逼真地表现出恐惧。"}]}],"simultaneous":[{"pos":"adj.","meaning":"同时发生的;同步的","definition":"happening at the same time","examples":[{"en":"Simultaneous translation helped the delegates communicate.","zh":"同声传译帮助代表交流。"},{"en":"The system handles simultaneous requests.","zh":"系统处理同时发来的请求。"}]}],"simultaneously":[{"pos":"adv.","meaning":"同时地","definition":"at the same time","examples":[{"en":"The two tests ran simultaneously.","zh":"两项测试同时进行。"},{"en":"The programme broadcasts simultaneously in three languages.","zh":"节目同时以三种语言播出。"}]}],"sincere":[{"pos":"adj.","meaning":"真诚的；诚挚的；诚恳的","definition":"Honest in feelings or intentions.","examples":[{"en":"Please accept my sincere thanks.","zh":"请接受我诚挚的感谢。"},{"en":"She seemed sincere in her wish to help.","zh":"她想提供帮助的愿望似乎很真诚。"}]}],"sinew":[{"pos":"n.","meaning":"肌腱","definition":"a tough band connecting muscle to bone","examples":[{"en":"The diagram shows the sinews of the hand.","zh":"图示展示手部肌腱。"},{"en":"The injury damaged a sinew near his ankle.","zh":"伤势损伤了脚踝附近的肌腱。"}]},{"pos":"n.","meaning":"力量来源;支柱","definition":"a source of strength","examples":[{"en":"Trade supplied the sinews of the growing city.","zh":"贸易为成长中的城市提供力量源泉。"},{"en":"The treasury provided the sinews of war.","zh":"国库提供了战争所需的财力。"}]}],"sinister":[{"pos":"adj.","meaning":"不祥的；险恶的","definition":"suggesting danger or evil","examples":[{"en":"The empty house had a sinister atmosphere.","zh":"空房子气氛阴森。"},{"en":"The novel reveals a sinister plot.","zh":"小说揭露了险恶的阴谋。"}]}],"sip":[{"pos":"v.","meaning":"小口喝；抿","definition":"To drink in small amounts.","examples":[{"en":"She sipped her tea slowly.","zh":"她慢慢抿着茶。"},{"en":"We sipped water during the long meeting.","zh":"漫长会议期间，我们小口喝水。"}]}],"situated":[{"pos":"adj.","meaning":"位于……的","definition":"located in a particular place","examples":[{"en":"The hotel is situated beside the river.","zh":"酒店位于河边。"},{"en":"The school is conveniently situated near the station.","zh":"学校靠近车站，位置便利。"}]},{"pos":"adj.","meaning":"处于某种境况的","definition":"placed in particular circumstances","examples":[{"en":"They are well situated to benefit from the change.","zh":"他们处境有利，能够从变化中获益。"},{"en":"Families similarly situated received equal assistance.","zh":"处境相同的家庭获得同等帮助。"}]}],"sizeable":[{"pos":"adj.","meaning":"相当大的","definition":"fairly large","examples":[{"en":"The project needs a sizeable budget.","zh":"项目需要相当大的预算。"},{"en":"A sizeable crowd attended.","zh":"相当多的人到场。"}]}],"sketch":[{"pos":"v.","meaning":"画素描；画速写","definition":"To make a quick or simple drawing.","examples":[{"en":"He sketched the harbour in his notebook.","zh":"他在笔记本里速写了港口。"},{"en":"She sketched a possible design on a napkin.","zh":"她在餐巾纸上勾画了一个可能的设计。"}]},{"pos":"v.","meaning":"概述；简述","definition":"To describe the main points briefly.","examples":[{"en":"The speaker sketched the history of the movement.","zh":"演讲者简述了这场运动的历史。"},{"en":"She sketched out a plan for the next year.","zh":"她概述了下一年的计划。"}]},{"pos":"n.","meaning":"素描；速写；草图","definition":"A quick drawing showing the main features.","examples":[{"en":"The artist made a pencil sketch.","zh":"画家画了一幅铅笔素描。"},{"en":"The sketch shows the proposed layout.","zh":"草图显示了拟议中的布局。"}]}],"skew":[{"pos":"v.","meaning":"使偏离;歪曲","definition":"to distort or make unbalanced","examples":[{"en":"The small sample skewed the results.","zh":"样本太小导致结果偏差。"},{"en":"Personal bias can skew judgement.","zh":"个人偏见会扭曲判断。"}]},{"pos":"adj.","meaning":"歪斜的;斜交的","definition":"set at an angle rather than straight","examples":[{"en":"A skew line crosses the rectangular pattern.","zh":"斜线穿过矩形图案。"},{"en":"The skew bridge crosses the road diagonally.","zh":"斜交桥斜着跨越道路。"}]}],"skim":[{"pos":"v.","meaning":"撇去表面浮物","definition":"to remove material from a liquid's surface","examples":[{"en":"Skim the foam from the soup.","zh":"撇去汤上的浮沫。"},{"en":"The machine skims oil from water.","zh":"机器从水面撇去油。"}]},{"pos":"v.","meaning":"掠过；擦过","definition":"to move lightly just above or across a surface","examples":[{"en":"Swallows skimmed the lake.","zh":"燕子掠过湖面。"},{"en":"The stone skimmed across the water.","zh":"石头擦着水面跳过。"}]},{"pos":"v.","meaning":"略读；浏览","definition":"to read quickly for main points","examples":[{"en":"She skimmed the report before the meeting.","zh":"她在会前浏览了报告。"},{"en":"I skimmed the headlines.","zh":"我扫了一眼标题。"}]}],"skip":[{"pos":"v.","meaning":"蹦跳；跳跃前进","definition":"To move with light jumping steps.","examples":[{"en":"The children skipped down the path.","zh":"孩子们沿着小路蹦跳前进。"},{"en":"She skipped happily across the playground.","zh":"她开心地蹦跳着穿过操场。"}]},{"pos":"v.","meaning":"跳过；漏过；不参加；逃课","definition":"To omit something or fail to attend.","examples":[{"en":"Do not skip the safety instructions.","zh":"不要跳过安全说明。"},{"en":"He skipped school to go fishing.","zh":"他逃课去钓鱼。"}]}],"skull":[{"pos":"n.","meaning":"颅骨;头骨;脑袋","definition":"the bony structure enclosing the brain","examples":[{"en":"The skull protects the brain.","zh":"颅骨保护大脑。"},{"en":"Archaeologists examined the ancient skull.","zh":"考古学家检查了古代头骨。"}]}],"skyscraper":[{"pos":"n.","meaning":"摩天大楼","definition":"a very tall building","examples":[{"en":"A new skyscraper changed the skyline.","zh":"新摩天楼改变了天际线。"},{"en":"The skyscraper contains offices and apartments.","zh":"摩天楼包含办公室和公寓。"}]}],"slacken":[{"pos":"v.","meaning":"松弛；放松","definition":"To become or make less tight.","examples":[{"en":"Slacken the rope before untying the knot.","zh":"解结前先把绳子放松。"},{"en":"The sail slackened as the wind dropped.","zh":"风减弱时，帆松弛下来。"}]},{"pos":"v.","meaning":"减缓；放慢；减弱","definition":"To become or make slower or less active.","examples":[{"en":"Demand slackened after the holidays.","zh":"假期后需求减弱了。"},{"en":"She slackened her pace on the steep hill.","zh":"在陡坡上，她放慢了脚步。"}]}],"slander":[{"pos":"n.","meaning":"口头诽谤;中伤","definition":"a false spoken statement damaging reputation","examples":[{"en":"She accused him of slander.","zh":"她指控他诽谤。"},{"en":"The rumour amounted to malicious slander.","zh":"谣言构成恶意中伤。"}]},{"pos":"v.","meaning":"诽谤;中伤","definition":"to damage someone's reputation with false spoken claims","examples":[{"en":"He denied slandering his former colleague.","zh":"他否认诽谤前同事。"},{"en":"The speaker slandered the innocent shopkeeper.","zh":"发言者中伤了无辜店主。"}]}],"slash":[{"pos":"n.","meaning":"割痕；砍伤","definition":"a long cut made by a sharp object","examples":[{"en":"A slash marked the canvas.","zh":"帆布上有一道割痕。"},{"en":"The jacket had a deep slash in one sleeve.","zh":"夹克的一只袖子上有一道深裂口。"}]},{"pos":"n.","meaning":"斜线号","definition":"the punctuation mark /","examples":[{"en":"Separate the alternatives with a slash.","zh":"用斜线号分隔选项。"},{"en":"The date was written with slashes.","zh":"日期用斜线分隔书写。"}]},{"pos":"v.","meaning":"猛砍；划破","definition":"to cut with a strong sweeping movement","examples":[{"en":"They slashed through the thick undergrowth.","zh":"他们砍开浓密的灌木丛。"},{"en":"A sharp edge slashed the bag.","zh":"锋利的边缘划破了包。"}]},{"pos":"v.","meaning":"大幅削减","definition":"to reduce greatly","examples":[{"en":"The shop slashed its prices.","zh":"商店大幅降价。"},{"en":"The budget was slashed by a third.","zh":"预算被削减了三分之一。"}]}],"slat":[{"pos":"n.","meaning":"板条；狭板","definition":"A thin narrow strip of wood or other material.","examples":[{"en":"One slat in the blind was broken.","zh":"百叶窗的一根板条断了。"},{"en":"The bench is made from wooden slats.","zh":"长凳由木条制成。"}]},{"pos":"v.","meaning":"用板条制作；给……装板条","definition":"To construct or cover something with narrow strips.","examples":[{"en":"The carpenter slatted the sides of the crate.","zh":"木匠用板条制作了箱子的侧面。"},{"en":"They slatted the frame to form a ventilated screen.","zh":"他们给框架装上板条，做成通风屏障。"}]}],"sledge":[{"pos":"n.","meaning":"雪橇","definition":"a vehicle that slides over snow","examples":[{"en":"The children pulled their sledge up the snowy hill.","zh":"孩子们把雪橇拉上了雪坡。"},{"en":"We carried the supplies on a wooden sledge.","zh":"我们用一架木雪橇运送物资。"}]},{"pos":"v.","meaning":"乘雪橇","definition":"to travel over snow on a sledge","examples":[{"en":"We used to sledge down this slope every winter.","zh":"我们以前每年冬天都会乘雪橇滑下这个坡。"},{"en":"They spent the afternoon sledging near the cottage.","zh":"他们整个下午都在小屋附近滑雪橇。"}]}],"sleek":[{"pos":"adj.","meaning":"光滑有光泽的","definition":"smooth and shiny","examples":[{"en":"The horse had a sleek coat.","zh":"马的皮毛光滑发亮。"},{"en":"Her sleek hair was tied back.","zh":"她光滑的头发束在脑后。"}]},{"pos":"adj.","meaning":"时髦流畅的；精致豪华的","definition":"stylish and smoothly designed","examples":[{"en":"The car has a sleek modern shape.","zh":"汽车有时髦流畅的现代造型。"},{"en":"The hotel features sleek interiors.","zh":"酒店内部装饰精致现代。"}]},{"pos":"v.","meaning":"使光滑；把毛发梳平","definition":"to make hair smooth and glossy","examples":[{"en":"She sleeked her hair back.","zh":"她把头发向后梳平。"},{"en":"He sleeked the horse's coat with a brush.","zh":"他用刷子把马毛刷得光滑。"}]}],"slender":[{"pos":"adj.","meaning":"修长的；苗条的；细长的","definition":"Thin and graceful.","examples":[{"en":"The dancer has slender arms.","zh":"舞者的手臂修长。"},{"en":"A slender bridge crosses the stream.","zh":"一座纤细的小桥横跨溪流。"}]},{"pos":"adj.","meaning":"微薄的；微小的；不足的","definition":"Very small in amount or strength.","examples":[{"en":"They won by a slender margin.","zh":"他们以微弱优势获胜。"},{"en":"The claim rests on slender evidence.","zh":"这个主张的证据很薄弱。"}]}],"slice":[{"pos":"v.","meaning":"切成薄片","definition":"to cut food or another material into thin pieces","examples":[{"en":"Slice the cucumber before adding it to the salad.","zh":"把黄瓜切成薄片后再加入沙拉。"},{"en":"She sliced the bread while the soup was heating.","zh":"汤在加热时，她把面包切成了片。"}]},{"pos":"n.","meaning":"薄片；切片","definition":"a flat piece cut from something larger","examples":[{"en":"He put a slice of lemon in his tea.","zh":"他在茶里放了一片柠檬。"},{"en":"Each guest received two slices of cake.","zh":"每位客人分到了两片蛋糕。"}]},{"pos":"n.","meaning":"份额；部分","definition":"a share of an amount or activity","examples":[{"en":"Housing takes a large slice of our monthly budget.","zh":"住房占了我们每月预算的很大一部分。"},{"en":"Small firms want a bigger slice of the market.","zh":"小公司希望获得更大的市场份额。"}]}],"slide":[{"pos":"v.","meaning":"滑动；下滑","definition":"to move smoothly over a surface","examples":[{"en":"The box slid across the floor.","zh":"箱子滑过地板。"},{"en":"Prices continued to slide.","zh":"价格继续下滑。"}]},{"pos":"v.","meaning":"悄悄移动；轻轻放入","definition":"to move quietly or unobtrusively","examples":[{"en":"She slid the note under the door.","zh":"她把纸条轻轻塞到门下。"},{"en":"He slid into an empty seat.","zh":"他悄悄坐进空座位。"}]},{"pos":"n.","meaning":"滑动；下滑","definition":"a smooth movement or gradual decrease","examples":[{"en":"The car went into a slide.","zh":"汽车开始滑行失控。"},{"en":"The figures show a slide in demand.","zh":"数字显示需求下滑。"}]},{"pos":"n.","meaning":"滑梯；滑道","definition":"a smooth sloping structure for sliding down","examples":[{"en":"The children queued for the slide.","zh":"孩子们排队玩滑梯。"},{"en":"A steep slide leads into the pool.","zh":"陡滑道通向水池。"}]},{"pos":"n.","meaning":"幻灯片","definition":"one image in a projected or digital presentation","examples":[{"en":"The first slide shows the research question.","zh":"第一张幻灯片展示研究问题。"},{"en":"She added a photograph to the slide.","zh":"她在幻灯片上加了一张照片。"}]},{"pos":"n.","meaning":"滑坡；崩落","definition":"a mass of earth or rock moving down a slope","examples":[{"en":"The road was blocked by a mud slide.","zh":"公路被泥石滑坡堵塞。"},{"en":"Heavy rain triggered a rock slide.","zh":"暴雨引发岩石崩滑。"}]}],"slight":[{"pos":"adj.","meaning":"轻微的；微小的；不足道的","definition":"Small in amount or importance.","examples":[{"en":"There was a slight delay.","zh":"出现了轻微延误。"},{"en":"She noticed a slight change in his tone.","zh":"她注意到他的语气有一丝变化。"}]},{"pos":"adj.","meaning":"纤细的；瘦小的","definition":"Thin and lightly built.","examples":[{"en":"He was a slight child with narrow shoulders.","zh":"他是个肩膀窄、身材瘦小的孩子。"},{"en":"Her slight frame concealed considerable strength.","zh":"她纤细的身躯蕴藏着相当大的力量。"}]},{"pos":"v.","meaning":"轻视；怠慢","definition":"To treat someone as unimportant.","examples":[{"en":"She felt slighted when nobody introduced her.","zh":"没人介绍她，她觉得受了怠慢。"},{"en":"The committee slighted his contribution.","zh":"委员会轻视了他的贡献。"}]},{"pos":"n.","meaning":"轻蔑；怠慢；冒犯","definition":"An act that shows disrespect.","examples":[{"en":"He took the omission as a personal slight.","zh":"他把遗漏视为对个人的轻蔑。"},{"en":"She ignored the slight and continued speaking.","zh":"她不理会这种怠慢，继续发言。"}]}],"slim":[{"pos":"adj.","meaning":"苗条的","definition":"having a slender body","examples":[{"en":"The dancer was tall and slim.","zh":"那位舞者身材高挑苗条。"},{"en":"This jacket was designed for people with a slim build.","zh":"这件夹克是为身材苗条的人设计的。"}]},{"pos":"adj.","meaning":"薄的；纤细的","definition":"having little thickness or width","examples":[{"en":"A slim notebook fitted into her coat pocket.","zh":"一本薄笔记本装进了她的大衣口袋。"},{"en":"The lamp has a slim metal base.","zh":"这盏灯有一个纤细的金属底座。"}]},{"pos":"adj.","meaning":"微小的；渺茫的","definition":"very small in amount or likelihood","examples":[{"en":"There is only a slim chance of finding a seat.","zh":"找到座位的机会很渺茫。"},{"en":"The proposal passed by a slim majority.","zh":"这项提议以微弱多数通过。"}]},{"pos":"v.","meaning":"减肥；变苗条","definition":"to reduce body weight","examples":[{"en":"She is trying to slim down through regular exercise.","zh":"她正尝试通过规律运动减肥。"},{"en":"He began slimming after finding an activity he enjoyed.","zh":"找到喜欢的运动后，他开始减肥。"}]}],"slip":[{"pos":"v.","meaning":"滑倒；滑落","definition":"to slide accidentally or lose footing","examples":[{"en":"She slipped on the wet floor.","zh":"她在湿地板上滑倒了。"},{"en":"The cup slipped from his hand.","zh":"杯子从他手中滑落。"}]},{"pos":"v.","meaning":"减退；下降","definition":"to become worse or lower","examples":[{"en":"His concentration began to slip.","zh":"他的注意力开始下降。"},{"en":"Standards slipped during the busy period.","zh":"忙碌期间标准有所降低。"}]},{"pos":"v.","meaning":"悄悄避开；摆脱","definition":"to escape or move away quietly","examples":[{"en":"The dog slipped its collar.","zh":"狗挣脱了项圈。"},{"en":"She slipped away before the speech.","zh":"她在演讲前悄悄离开。"}]},{"pos":"v.","meaning":"悄悄塞入；迅速放入","definition":"to put something somewhere quickly or discreetly","examples":[{"en":"He slipped the key into his pocket.","zh":"他迅速把钥匙塞进口袋。"},{"en":"She slipped a note under the plate.","zh":"她悄悄把纸条塞在盘子下面。"}]},{"pos":"n.","meaning":"差错；疏漏","definition":"a small accidental mistake","examples":[{"en":"The error was a simple slip.","zh":"错误只是一个小疏漏。"},{"en":"A slip of the tongue revealed the plan.","zh":"一时口误泄露了计划。"}]},{"pos":"n.","meaning":"滑倒；滑动","definition":"an accidental slide or loss of footing","examples":[{"en":"A slip on the steps hurt his ankle.","zh":"台阶上滑了一跤使他脚踝受伤。"},{"en":"The rope prevented a dangerous slip.","zh":"绳索防止了一次危险的滑落。"}]},{"pos":"n.","meaning":"纸片；单据","definition":"a small piece of paper","examples":[{"en":"Write your name on the slip.","zh":"在纸条上写姓名。"},{"en":"Keep the payment slip.","zh":"保留付款单。"}]}],"slippery":[{"pos":"adj.","meaning":"滑的；滑溜的","definition":"Difficult to grip or stand on because of smoothness or moisture.","examples":[{"en":"The steps are slippery after rain.","zh":"台阶雨后很滑。"},{"en":"Wet soap is slippery to hold.","zh":"湿肥皂很滑，难以握住。"}]},{"pos":"adj.","meaning":"狡猾的；油滑的","definition":"Difficult to trust or pin down.","examples":[{"en":"The slippery salesman avoided every direct question.","zh":"这个油滑的推销员回避了每个直接问题。"},{"en":"He proved a slippery opponent in the debate.","zh":"他在辩论中是个狡猾的对手。"}]},{"pos":"adj.","meaning":"难以把握的；棘手的","definition":"Difficult to define or deal with clearly.","examples":[{"en":"The distinction between the two concepts is slippery.","zh":"这两个概念之间的区别难以把握。"},{"en":"The discussion entered the slippery area of personal responsibility.","zh":"讨论进入了个人责任这一棘手领域。"}]}],"sliver":[{"pos":"n.","meaning":"薄片；细片","definition":"a very narrow piece of material","ipa":"/ˈslɪvə(r)/","examples":[{"en":"A sliver of wood had broken off the shelf.","zh":"架子上掉下了一小条木片。"},{"en":"Only a sliver of light entered through the curtain.","zh":"只有一线光从窗帘间透了进来。"}]}],"slogan":[{"pos":"n.","meaning":"标语；口号","definition":"a short memorable phrase expressing an aim","examples":[{"en":"The campaign adopted a new slogan.","zh":"活动采用了新口号。"},{"en":"The slogan appeared on every poster.","zh":"每张海报上都有这个标语。"}]}],"slope":[{"pos":"n.","meaning":"斜坡；坡度；倾斜","definition":"A surface at an angle or the degree of its incline.","examples":[{"en":"The house stands on a gentle slope.","zh":"房子坐落在缓坡上。"},{"en":"The roof has a steep slope.","zh":"屋顶坡度很陡。"}]},{"pos":"v.","meaning":"倾斜；有坡度","definition":"To rise or fall at an angle.","examples":[{"en":"The garden slopes towards the river.","zh":"花园向河边倾斜。"},{"en":"The path slopes gently upwards.","zh":"小路缓缓向上延伸。"}]}],"slothful":[{"pos":"adj.","meaning":"懒惰的；怠惰的","definition":"unwilling to make an effort","examples":[{"en":"The fable contrasts a slothful character with a diligent one.","zh":"这则寓言把一个懒惰的人物与一个勤奋的人物作对比。"},{"en":"A slothful approach left the repairs unfinished for months.","zh":"懒散的态度使维修工作拖了几个月仍未完成。"}]}],"slouch":[{"pos":"v.","meaning":"懒散地站坐走；垂头耷肩","definition":"to sit, stand, or walk with drooping posture","examples":[{"en":"He slouched in the chair.","zh":"他懒散地坐在椅子上。"},{"en":"The students slouched along the corridor.","zh":"学生们耷拉着肩走过走廊。"}]}],"slum":[{"pos":"n.","meaning":"贫民窟；贫民区","definition":"A crowded urban area with poor housing and living conditions.","examples":[{"en":"The project improves sanitation in the slum.","zh":"项目改善贫民区的卫生设施。"},{"en":"Many families moved from the slums into new housing.","zh":"许多家庭从贫民窟搬进了新住房。"}]}],"slumber":[{"pos":"v.","meaning":"熟睡；安睡","definition":"to sleep peacefully, especially in literary language","examples":[{"en":"The baby slumbered beside the open window.","zh":"婴儿在敞开的窗户旁安睡。"},{"en":"The exhausted travellers slumbered until noon.","zh":"疲惫的旅人一直睡到中午。"}]},{"pos":"n.","meaning":"睡眠；安睡","definition":"a period or state of sleep","examples":[{"en":"A ringing phone interrupted his slumber.","zh":"电话铃声打断了他的睡眠。"},{"en":"She fell into a deep slumber after the journey.","zh":"旅途结束后，她进入了沉睡。"}]}],"slump":[{"pos":"v.","meaning":"骤降；暴跌","definition":"to fall sharply in value or amount","examples":[{"en":"Sales slumped after the closure.","zh":"关闭之后销售暴跌。"},{"en":"The currency slumped overnight.","zh":"货币一夜间大跌。"}]},{"pos":"v.","meaning":"瘫坐；猛然倒下","definition":"to fall or sink heavily","examples":[{"en":"She slumped into the armchair.","zh":"她一下瘫坐在扶手椅里。"},{"en":"The damaged roof slumped inward.","zh":"受损屋顶向内塌陷。"}]},{"pos":"n.","meaning":"萧条；低迷期","definition":"a period of poor performance or economic decline","examples":[{"en":"The industry entered a slump.","zh":"行业进入萧条期。"},{"en":"The team finally ended its losing slump.","zh":"球队终于结束了失利低谷。"}]}],"slurry":[{"pos":"n.","meaning":"泥浆；浆状混合物","definition":"A liquid mixture containing suspended solid particles.","examples":[{"en":"The pump moved the slurry through a pipe.","zh":"泵把泥浆输送过管道。"},{"en":"Water was added to the powder to form a slurry.","zh":"粉末中加入水后形成了浆液。"}]}],"sluttish":[{"pos":"adj.","meaning":"邋遢的；不整洁的（旧式贬义）","definition":"untidy or dirty, in dated disapproving language","examples":[{"en":"The old novel describes the kitchen as sluttish and neglected.","zh":"这部老小说把厨房描写得邋遢且无人打理。"},{"en":"The narrator criticises the household's sluttish habits.","zh":"叙述者批评了这家人邋遢的生活习惯。"}]},{"pos":"adj.","meaning":"放荡的（冒犯性贬称）","definition":"an insulting description suggesting sexual promiscuity","examples":[{"en":"She objected when a neighbour called her sluttish simply for having several boyfriends.","zh":"她反对邻居仅因她交往过几个男友就用“放荡”辱骂她。"},{"en":"The novel shows how a woman's private relationships were used to brand her sluttish.","zh":"小说展示了一个女人的私人关系如何被用来给她贴上“放荡”的标签。"}]}],"smart":[{"pos":"adj.","meaning":"整洁漂亮的；时髦的","definition":"stylish and neat","examples":[{"en":"She wore a smart suit.","zh":"她穿着漂亮整洁的套装。"},{"en":"The lobby looks smart after renovation.","zh":"翻新后门厅看起来很时髦。"}]},{"pos":"adj.","meaning":"聪明的；高明的","definition":"intelligent or showing good judgment","examples":[{"en":"That was a smart decision.","zh":"那是一个明智决定。"},{"en":"The smart student spotted the pattern.","zh":"聪明的学生发现了规律。"}]}],"smear":[{"pos":"v.","meaning":"涂抹；弄脏；抹花","definition":"To spread a substance unevenly or blur a surface.","examples":[{"en":"He smeared butter over the bread.","zh":"他把黄油涂在面包上。"},{"en":"Rain smeared the ink on the page.","zh":"雨水把纸上的墨迹弄模糊了。"}]},{"pos":"v.","meaning":"诽谤；诋毁","definition":"To damage someone's reputation with unfair claims.","examples":[{"en":"The article tried to smear her reputation.","zh":"这篇文章试图诋毁她的名誉。"},{"en":"He accused his rivals of smearing him.","zh":"他指责对手诽谤自己。"}]},{"pos":"n.","meaning":"污迹；涂抹痕迹","definition":"A mark made by spreading or rubbing a substance.","examples":[{"en":"A smear of grease covered the handle.","zh":"把手上有一道油污。"},{"en":"She wiped a smear from the window.","zh":"她擦掉了窗户上的污迹。"}]},{"pos":"n.","meaning":"涂片","definition":"A thin sample spread on a slide for examination.","examples":[{"en":"The technician examined the blood smear.","zh":"技术人员检查了血液涂片。"},{"en":"The smear was stained before microscopy.","zh":"涂片在显微镜检查前进行了染色。"}]},{"pos":"n.","meaning":"诽谤；诋毁","definition":"An unfair statement intended to harm someone's reputation.","examples":[{"en":"The newspaper withdrew the smear.","zh":"报纸撤回了诽谤性言论。"},{"en":"The accusation was dismissed as a political smear.","zh":"这项指控被认定为政治诋毁而遭到驳斥。"}]}],"smell":[{"pos":"v.","meaning":"闻到；嗅","definition":"to detect something through the nose","examples":[{"en":"I can smell fresh bread from the bakery.","zh":"我能闻到面包店里新鲜面包的香味。"},{"en":"The dog smelled the bag before walking away.","zh":"狗闻了闻袋子，然后走开了。"}]},{"pos":"v.","meaning":"散发气味；有某种气味","definition":"to have or produce a particular odour","examples":[{"en":"The towels smell damp after being left in the bag.","zh":"毛巾放在袋子里后有一股潮湿的气味。"},{"en":"The garden smells wonderful after the rain.","zh":"雨后的花园气味芬芳。"}]},{"pos":"n.","meaning":"气味","definition":"an odour detected through the nose","examples":[{"en":"The smell of coffee filled the room.","zh":"咖啡的香味弥漫了房间。"},{"en":"The room had a pleasant smell of fresh flowers.","zh":"房间里有一股鲜花的怡人香味。"}]},{"pos":"n.","meaning":"嗅觉","definition":"the ability to detect odours","examples":[{"en":"The animal relies on its sense of smell to find food.","zh":"这种动物依靠嗅觉寻找食物。"},{"en":"The experiment tested the animals' sense of smell.","zh":"这项实验测试了动物的嗅觉。"}]}],"smooth":[{"pos":"adj.","meaning":"顺利的；流畅的；协调的","definition":"happening evenly without difficulty or interruption","examples":[{"en":"The transfer was smooth.","zh":"交接很顺利。"},{"en":"The dancer's movements were smooth.","zh":"舞者的动作流畅。"}]}],"smother":[{"pos":"v.","meaning":"厚厚覆盖；笼罩","definition":"To cover completely or generously.","examples":[{"en":"She smothered the toast in jam.","zh":"她在吐司上涂了厚厚一层果酱。"},{"en":"Snow smothered the low plants.","zh":"积雪覆盖了矮小植物。"}]},{"pos":"v.","meaning":"使窒息；闷熄","definition":"To prevent breathing or put out fire by blocking air.","examples":[{"en":"The thick smoke threatened to smother the trapped workers.","zh":"浓烟险些使被困工人窒息。"},{"en":"He smothered the small fire with a blanket.","zh":"他用毯子把小火闷灭了。"}]}],"snack":[{"pos":"n.","meaning":"小吃；点心","definition":"a small amount of food eaten between meals","examples":[{"en":"She packed a snack for the train journey.","zh":"她为火车旅程装了一份点心。"},{"en":"Fruit makes a convenient afternoon snack.","zh":"水果是方便的下午小吃。"}]},{"pos":"v.","meaning":"吃零食","definition":"to eat small amounts between meals","examples":[{"en":"They snacked on nuts during the walk.","zh":"他们散步时吃了些坚果。"},{"en":"I tend to snack when I work late.","zh":"工作到很晚时，我常会吃零食。"}]}],"snap":[{"pos":"v.","meaning":"咔嚓折断；绷断","definition":"to break suddenly with a sharp sound","examples":[{"en":"The branch snapped under his weight.","zh":"树枝在他的重量下咔嚓断了。"},{"en":"The rope snapped in the wind.","zh":"绳子在风中绷断了。"}]},{"pos":"v.","meaning":"啪地打开或关上","definition":"to move quickly with a sharp sound","examples":[{"en":"She snapped the case shut.","zh":"她啪地关上了盒子。"},{"en":"The umbrella snapped open.","zh":"伞啪地打开了。"}]},{"pos":"v.","meaning":"猛咬；咬向","definition":"to bite or try to bite suddenly","examples":[{"en":"The dog snapped at his hand.","zh":"狗突然咬向他的手。"},{"en":"The fish snapped at the bait.","zh":"鱼猛地咬向鱼饵。"}]},{"pos":"v.","meaning":"厉声说；怒声斥责","definition":"to speak sharply in anger","examples":[{"en":"He snapped that he was busy.","zh":"他厉声说自己很忙。"},{"en":"She snapped at the interruption.","zh":"被打断后她生气地斥责。"}]},{"pos":"n.","meaning":"咔嚓声；啪声","definition":"a sudden sharp cracking sound","examples":[{"en":"We heard a snap behind us.","zh":"我们听见身后咔嚓一声。"},{"en":"The lid closed with a snap.","zh":"盖子啪地关上了。"}]},{"pos":"adj.","meaning":"突然的；仓促的","definition":"made or called without warning","examples":[{"en":"They called a snap election.","zh":"他们突然宣布提前举行选举。"},{"en":"Avoid making a snap judgment.","zh":"避免仓促下判断。"}]}],"snap up":[{"pos":"v.","meaning":"抢购；迅速买下；抢先获得","definition":"To buy or take something quickly before others can.","examples":[{"en":"Fans snapped up the tickets within minutes.","zh":"歌迷几分钟内就抢光了票。"},{"en":"A publisher snapped up her first novel.","zh":"一家出版社迅速买下了她第一部小说的版权。"}]}],"snobbish":[{"pos":"adj.","meaning":"势利的；自命不凡的","definition":"looking down on people considered lower in status","examples":[{"en":"His snobbish remarks made the new guests uncomfortable.","zh":"他势利的言论让新来的客人感到不自在。"},{"en":"The club was criticised for its snobbish attitude towards local residents.","zh":"这家俱乐部因对当地居民态度势利而受到批评。"}]}],"soak":[{"pos":"v.","meaning":"浸泡；浸透","definition":"to leave in liquid or make completely wet","examples":[{"en":"Soak the beans overnight.","zh":"把豆子浸泡一夜。"},{"en":"The rain soaked our clothes.","zh":"雨浸透了我们的衣服。"}]}],"sociable":[{"pos":"adj.","meaning":"好交际的；合群的；友善的","definition":"Enjoying friendly company and conversation.","examples":[{"en":"She is sociable and easily makes friends.","zh":"她很合群，容易交到朋友。"},{"en":"The shared kitchen creates a sociable atmosphere.","zh":"共用厨房营造了友好的社交氛围。"}]}],"socialise":[{"pos":"v.","meaning":"交往；交际","definition":"to spend friendly time with other people","examples":[{"en":"The course gives newcomers a chance to socialise.","zh":"这门课程给新来的人提供了交际的机会。"},{"en":"She prefers to socialise in small groups.","zh":"她更喜欢参加小范围的社交活动。"}]},{"pos":"v.","meaning":"使适应社会生活","definition":"to teach the behaviours expected in a community","examples":[{"en":"Children are socialised through family and school life.","zh":"孩子通过家庭和学校生活学习适应社会。"},{"en":"The shelter socialises young dogs so that they remain calm around people.","zh":"收容所对幼犬进行社会化训练，让它们在人周围保持镇定。"}]}],"sociology":[{"pos":"n.","meaning":"社会学","definition":"the study of human society and social behaviour","examples":[{"en":"She studies sociology.","zh":"她学习社会学。"},{"en":"The research draws on sociology and history.","zh":"研究借鉴社会学与历史学。"}]}],"solar":[{"pos":"adj.","meaning":"太阳的；太阳能的","definition":"Relating to the Sun or using its energy.","examples":[{"en":"Solar panels cover the roof.","zh":"太阳能板铺满了屋顶。"},{"en":"The lesson explained a solar eclipse.","zh":"这堂课解释了日食。"}]}],"solar-powered":[{"pos":"adj.","meaning":"太阳能驱动的","definition":"using energy collected from sunlight","examples":[{"en":"Solar-powered lights mark the garden path.","zh":"太阳能灯照亮了花园的小路。"},{"en":"The village installed a solar-powered water pump.","zh":"村里安装了一台太阳能水泵。"}]}],"sole":[{"pos":"adj.","meaning":"唯一的；独有的","definition":"the only one","examples":[{"en":"She was the sole witness.","zh":"她是唯一证人。"},{"en":"He has sole responsibility for the budget.","zh":"他独自负责预算。"}]},{"pos":"n.","meaning":"鞋底；袜底","definition":"the bottom part of a shoe or sock","examples":[{"en":"The shoe's sole was worn thin.","zh":"鞋底磨薄了。"},{"en":"The sock has a reinforced sole.","zh":"袜子有加固的底部。"}]},{"pos":"n.","meaning":"脚底","definition":"the underside of a foot","examples":[{"en":"The sand warmed the soles of her feet.","zh":"沙子暖着她的脚底。"},{"en":"He had a blister on his sole.","zh":"他脚底起了水泡。"}]}],"solemn":[{"pos":"adj.","meaning":"庄严的；隆重的","definition":"Formal and dignified.","examples":[{"en":"The ceremony was a solemn occasion.","zh":"典礼是一个庄严的场合。"},{"en":"They made a solemn promise to protect the site.","zh":"他们郑重承诺保护这个地点。"}]},{"pos":"adj.","meaning":"严肃的；认真的","definition":"Serious in manner or feeling.","examples":[{"en":"The children listened with solemn faces.","zh":"孩子们表情严肃地听着。"},{"en":"He became solemn when the conversation turned to the accident.","zh":"谈到事故时，他变得严肃起来。"}]}],"solicitor":[{"pos":"n.","meaning":"事务律师","definition":"a lawyer who advises clients and prepares legal work, especially in Britain","examples":[{"en":"She asked a solicitor to explain the contract.","zh":"她请一位事务律师解释这份合同。"},{"en":"The solicitor arranged a meeting with both clients.","zh":"这位事务律师安排了与两位客户的会面。"}]},{"pos":"n.","meaning":"政府法务官；市政法律顾问（美国用法）","definition":"a lawyer serving a local government or public department in the United States","examples":[{"en":"The city solicitor reviewed the proposed bylaw.","zh":"市法务官审查了拟议的地方法规。"},{"en":"The department's solicitor advised officials on the contract.","zh":"该部门的法务官就合同向官员提供了建议。"}]}],"solidarity":[{"pos":"n.","meaning":"团结；一致支持","definition":"unity based on shared interests or support","examples":[{"en":"The workers showed solidarity.","zh":"工人们表现出团结。"},{"en":"The event expressed solidarity with affected families.","zh":"活动表达了对受影响家庭的支持。"}]}],"solidify":[{"pos":"v.","meaning":"凝固；使固化","definition":"To become or make solid.","examples":[{"en":"The wax solidified as it cooled.","zh":"蜡冷却后凝固了。"},{"en":"The mixture must solidify before it is removed from the mould.","zh":"混合物必须凝固后才能从模具中取出。"}]},{"pos":"v.","meaning":"巩固；使团结；使稳固","definition":"To become or make stronger and more established.","examples":[{"en":"The victory solidified her position as leader.","zh":"胜利巩固了她的领导地位。"},{"en":"The shared task solidified the group's unity.","zh":"共同任务增强了团队的团结。"}]}],"soluble":[{"pos":"adj.","meaning":"可溶的","definition":"able to dissolve in a liquid","examples":[{"en":"The powder is soluble in warm water.","zh":"这种粉末可以溶于温水。"},{"en":"The experiment compares soluble and insoluble materials.","zh":"这个实验比较可溶物和不溶物。"}]},{"pos":"adj.","meaning":"可解决的","definition":"capable of being solved","examples":[{"en":"The team believes the scheduling problem is soluble.","zh":"团队认为排期问题是可以解决的。"},{"en":"What seemed impossible proved soluble after further analysis.","zh":"进一步分析后，看似不可能的问题被证明可以解决。"}]}],"solution":[{"pos":"n.","meaning":"解决办法；解答","definition":"an answer to a problem","examples":[{"en":"We need a practical solution.","zh":"我们需要实际可行的解决办法。"},{"en":"Her solution to the equation was correct.","zh":"她对方程的解答是正确的。"}]},{"pos":"n.","meaning":"溶液；溶解状态","definition":"a homogeneous mixture or the state of being dissolved","examples":[{"en":"Stir the salt solution gently.","zh":"轻轻搅拌盐溶液。"},{"en":"The mineral remained in solution.","zh":"矿物保持溶解状态。"}]}],"solve":[{"pos":"v.","meaning":"解决；解答","definition":"To find an answer or a way to deal with a problem.","examples":[{"en":"We solved the puzzle together.","zh":"我们一起解出了谜题。"},{"en":"The new bridge solved the access problem.","zh":"新桥解决了通行问题。"}]}],"sophisticate":[{"pos":"n.","meaning":"老于世故的人；见多识广的人","definition":"a person with wide experience of culture or social life","examples":[{"en":"The young designer wanted to impress the city's sophisticates.","zh":"这位年轻设计师想给城里的时尚通留下好印象。"},{"en":"Even an experienced sophisticate can feel lost in a new culture.","zh":"即使见多识广的人也会在陌生文化中感到无所适从。"}]}],"sophisticated":[{"pos":"adj.","meaning":"先进复杂的；精密的","definition":"technically advanced and complex","examples":[{"en":"The laboratory uses sophisticated instruments.","zh":"实验室使用精密仪器。"},{"en":"The model requires sophisticated calculations.","zh":"模型需要复杂计算。"}]},{"pos":"adj.","meaning":"老练的；有教养的；高雅的","definition":"experienced and having refined tastes","examples":[{"en":"She is a sophisticated traveller.","zh":"她是经验丰富的旅行者。"},{"en":"The restaurant attracts a sophisticated clientele.","zh":"餐馆吸引品位高雅的顾客。"}]}],"sore":[{"pos":"adj.","meaning":"疼痛的；酸痛的","definition":"Physically painful or tender.","examples":[{"en":"My feet were sore after the long walk.","zh":"长途步行后，我的脚很痛。"},{"en":"She woke with a sore throat.","zh":"她醒来时喉咙痛。"}]},{"pos":"adj.","meaning":"恼火的；不快的","definition":"Upset or resentful about something.","examples":[{"en":"He was still sore about losing the match.","zh":"他仍因输了比赛而恼火。"},{"en":"She felt sore at being left out.","zh":"她因被排除在外而感到不快。"}]},{"pos":"adj.","meaning":"严重的；迫切的（较正式用法）","definition":"Severe or deeply felt.","examples":[{"en":"The village was in sore need of clean water.","zh":"村庄迫切需要干净饮水。"},{"en":"The loss was a sore trial for the family.","zh":"这次损失对家庭是一次严峻考验。"}]},{"pos":"n.","meaning":"疮；疼痛的伤口","definition":"A painful or damaged area of skin.","examples":[{"en":"The nurse examined the sore on his ankle.","zh":"护士检查了他脚踝上的疮。"},{"en":"The rough strap had left a sore on her shoulder.","zh":"粗糙肩带在她肩上磨出了伤口。"}]}],"sorrow":[{"pos":"n.","meaning":"悲伤；悲痛","definition":"a feeling of deep sadness","examples":[{"en":"Her voice was full of sorrow when she spoke about the loss.","zh":"谈及这次失去时，她的声音充满悲痛。"},{"en":"The letter brought sorrow to the whole family.","zh":"这封信让全家感到悲伤。"}]},{"pos":"n.","meaning":"伤心事；不幸","definition":"an experience that causes sadness","examples":[{"en":"They shared their joys and sorrows over many years.","zh":"多年来，他们共同经历了欢乐与悲伤。"},{"en":"The diary records the small sorrows of everyday life.","zh":"这本日记记录了日常生活中的小小伤心事。"}]}],"source":[{"pos":"n.","meaning":"来源；出处；根源","definition":"a place, person, or cause from which something comes","examples":[{"en":"Always identify the source of a quotation.","zh":"务必注明引文出处。"},{"en":"The river is a source of drinking water.","zh":"河流是饮用水来源。"}]},{"pos":"n.","meaning":"河源；源头","definition":"the place where a river begins","examples":[{"en":"The expedition reached the river's source.","zh":"探险队到达河流源头。"},{"en":"The stream's source lies in the hills.","zh":"溪流发源于山中。"}]}],"souvenir":[{"pos":"n.","meaning":"纪念品；纪念物","definition":"An object kept to remember a place or event.","examples":[{"en":"She bought a small bowl as a souvenir.","zh":"她买了一只小碗作纪念品。"},{"en":"The ticket became a souvenir of their first trip.","zh":"这张票成了他们首次旅行的纪念物。"}]}],"spacecraft":[{"pos":"n.","meaning":"航天器；宇宙飞船","definition":"a vehicle designed to travel in space","examples":[{"en":"The spacecraft sent images back to Earth.","zh":"航天器将图像传回了地球。"},{"en":"Engineers checked the spacecraft before launch.","zh":"工程师在发射前检查了宇宙飞船。"}]}],"spacious":[{"pos":"adj.","meaning":"宽敞的","definition":"having plenty of space","examples":[{"en":"The kitchen is spacious enough for a dining table.","zh":"厨房足够宽敞，可以放一张餐桌。"},{"en":"They moved into a spacious house with a garden.","zh":"他们搬进了一所有花园的宽敞房子。"},{"en":"The new library has a spacious reading room.","zh":"新图书馆有一个宽敞的阅览室。"}]}],"spade":[{"pos":"n.","meaning":"铁锹；铲","definition":"A tool with a flat blade used for digging.","examples":[{"en":"He dug the hole with a spade.","zh":"他用铁锹挖了坑。"},{"en":"The gardener leaned the spade against the shed.","zh":"园丁把铁锹靠在棚屋旁。"}]}],"span":[{"pos":"n.","meaning":"跨度；跨距","definition":"the distance between two ends or supports","examples":[{"en":"The bridge has a central span of two hundred metres.","zh":"这座桥的主跨跨度为两百米。"},{"en":"Engineers measured the span between the columns.","zh":"工程师测量了柱子之间的跨距。"}]},{"pos":"n.","meaning":"一段时间","definition":"a period during which something happens","examples":[{"en":"Her teaching career covered a span of thirty years.","zh":"她的教学生涯持续了三十年。"},{"en":"The changes occurred within a short span of time.","zh":"这些变化在很短的一段时间内发生。"}]},{"pos":"v.","meaning":"横跨","definition":"to extend across a space","examples":[{"en":"A wooden bridge spans the narrow stream.","zh":"一座木桥横跨狭窄的小溪。"},{"en":"The roof spans the entire courtyard.","zh":"屋顶覆盖了整个庭院。"}]},{"pos":"v.","meaning":"持续；涵盖","definition":"to cover a period or range","examples":[{"en":"His research spans several decades.","zh":"他的研究跨越了数十年。"},{"en":"The collection spans many styles of modern art.","zh":"这套藏品涵盖了多种现代艺术风格。"}]}],"spare":[{"pos":"adj.","meaning":"备用的；多余的","definition":"available in addition to what is needed","examples":[{"en":"Keep a spare key outside the house.","zh":"在屋外备一把备用钥匙。"},{"en":"We have a spare room.","zh":"我们有一间空房。"}]},{"pos":"adj.","meaning":"空闲的","definition":"not occupied by duties","examples":[{"en":"She reads in her spare time.","zh":"她在空闲时间读书。"},{"en":"Do you have a spare moment?","zh":"你有空吗？"}]},{"pos":"v.","meaning":"抽出；腾出","definition":"to make time or resources available","examples":[{"en":"Can you spare an hour?","zh":"你能抽出一小时吗？"},{"en":"The office could spare two computers.","zh":"办公室能腾出两台电脑。"}]},{"pos":"v.","meaning":"饶恕；使免受","definition":"to avoid harming or causing difficulty","examples":[{"en":"The storm spared the village.","zh":"风暴没有伤及村庄。"},{"en":"Please spare her the unnecessary details.","zh":"请别让她听那些不必要的细节。"}]},{"pos":"v.","meaning":"节省；吝惜（常用于否定）","definition":"to limit the use of effort or money","examples":[{"en":"They spared no expense on the restoration.","zh":"他们不惜费用进行修复。"},{"en":"She spared no effort to help.","zh":"她不遗余力地提供帮助。"}]},{"pos":"n.","meaning":"备用品；备件","definition":"an extra item kept for replacement","examples":[{"en":"The tyre was flat, so we used the spare.","zh":"轮胎没气了，我们用了备胎。"},{"en":"The workshop stocks engine spares.","zh":"车间备有发动机配件。"}]}],"spark":[{"pos":"n.","meaning":"火花；火星","definition":"A tiny glowing particle produced by fire or friction.","examples":[{"en":"A spark flew from the fire.","zh":"一颗火星从火中飞出。"},{"en":"The metal wheel produced sparks against the rail.","zh":"金属轮与轨道摩擦产生火花。"}]}],"spasm":[{"pos":"n.","meaning":"痉挛；抽搐","definition":"a sudden involuntary tightening of a muscle","examples":[{"en":"A muscle spasm forced the runner to stop.","zh":"肌肉痉挛迫使跑步者停了下来。"},{"en":"The patient described repeated spasms in her leg.","zh":"患者描述了腿部反复痉挛的情况。"}]},{"pos":"n.","meaning":"一阵突发的活动或情绪","definition":"a sudden brief burst of feeling or activity","examples":[{"en":"A spasm of laughter interrupted the meeting.","zh":"一阵突如其来的笑声打断了会议。"},{"en":"He felt a spasm of anxiety when the lights went out.","zh":"灯熄灭时，他感到一阵焦虑。"}]}],"spasmodic":[{"pos":"adj.","meaning":"痉挛性的","definition":"involving sudden involuntary muscle movements","examples":[{"en":"The report described spasmodic movements.","zh":"报告描述了痉挛性动作。"},{"en":"The patient experienced spasmodic contractions.","zh":"患者出现阵发性收缩。"}]},{"pos":"adj.","meaning":"断续的；间歇性的","definition":"happening irregularly rather than continuously","examples":[{"en":"Progress was spasmodic.","zh":"进展时断时续。"},{"en":"We received only spasmodic updates.","zh":"我们只收到零星更新。"}]}],"specialise":[{"pos":"v.","meaning":"专攻；专门从事","definition":"To concentrate on a particular subject or activity.","examples":[{"en":"She specialises in marine biology.","zh":"她专攻海洋生物学。"},{"en":"The shop specialises in rare books.","zh":"这家商店专营珍本书。"}]},{"pos":"v.","meaning":"使适应特殊用途；使专门化","definition":"To adapt something for a particular function.","examples":[{"en":"Evolution has specialised the limb for swimming.","zh":"进化使这种肢体适应了游泳。"},{"en":"The workshop specialised its machinery for delicate components.","zh":"车间改造机械，使其专用于精细部件。"}]}],"specialist":[{"pos":"n.","meaning":"专家","definition":"a person with detailed knowledge of one area","examples":[{"en":"The museum consulted a specialist in ancient coins.","zh":"博物馆咨询了一位古钱币专家。"},{"en":"A language specialist helped design the course.","zh":"一位语言专家帮助设计了这门课程。"}]},{"pos":"n.","meaning":"专科医生","definition":"a doctor trained in a particular field","examples":[{"en":"The clinic referred him to a heart specialist.","zh":"诊所把他转诊给了一位心脏专科医生。"},{"en":"She has an appointment with a specialist next week.","zh":"她预约了下周的专科门诊。"}]}],"specialty":[{"pos":"n.","meaning":"特产；特色菜","definition":"a product or food a place is known for","examples":[{"en":"Seafood soup is the restaurant's specialty.","zh":"海鲜汤是餐馆特色菜。"},{"en":"The market sells regional specialties.","zh":"市场销售地方特产。"}]},{"pos":"n.","meaning":"特长；专长领域","definition":"a subject or skill someone knows especially well","examples":[{"en":"Her specialty is medieval history.","zh":"她的专长是中世纪史。"},{"en":"Repairing old clocks is his specialty.","zh":"修理古钟是他的特长。"}]}],"species":[{"pos":"n.","meaning":"物种；种","definition":"A group of organisms classified as a distinct biological kind.","examples":[{"en":"Several bird species nest on the island.","zh":"岛上有几种鸟筑巢。"},{"en":"The reserve protects an endangered species.","zh":"保护区保护着一个濒危物种。"}]}],"specific":[{"pos":"adj.","meaning":"特定的","definition":"relating to one particular person, thing, or situation","examples":[{"en":"The grant is intended for a specific research project.","zh":"这笔资助用于一个特定的研究项目。"},{"en":"Each key opens a specific cupboard.","zh":"每把钥匙对应一个特定的柜子。"}]},{"pos":"adj.","meaning":"明确的；具体的","definition":"giving precise details","examples":[{"en":"Please give a specific example of the problem.","zh":"请举一个具体的问题实例。"},{"en":"The instructions were not specific enough to follow.","zh":"这些说明不够明确，无法照着操作。"}]}],"specification":[{"pos":"n.","meaning":"规格；规范；详细说明","definition":"a precise description of requirements or features","examples":[{"en":"The engineer checked the technical specifications.","zh":"工程师检查了技术规格。"},{"en":"The contract includes a detailed specification of materials.","zh":"合同包含材料的详细说明。"}]}],"specify":[{"pos":"v.","meaning":"明确说明；指定；详细规定","definition":"To state something precisely.","examples":[{"en":"Please specify the delivery date.","zh":"请明确说明送货日期。"},{"en":"The instructions specify which tools are required.","zh":"说明书详细列出了所需工具。"}]}],"specimen":[{"pos":"n.","meaning":"样本；标本","definition":"a piece or example collected for study","examples":[{"en":"The laboratory received a soil specimen from the farm.","zh":"实验室收到了农场送来的土壤样本。"},{"en":"Each insect specimen carries a label with its collection date.","zh":"每个昆虫标本都附有采集日期标签。"}]},{"pos":"n.","meaning":"范例；代表性实例","definition":"an individual example of a type","examples":[{"en":"This building is a fine specimen of early industrial architecture.","zh":"这栋建筑是早期工业建筑的优秀范例。"},{"en":"The garden contains a mature specimen of the rare tree.","zh":"花园里有一棵这种稀有树木的成熟植株。"}]}],"spectacular":[{"pos":"adj.","meaning":"壮观的；惊人的","definition":"very impressive to see or experience","examples":[{"en":"The mountain view was spectacular.","zh":"山景壮观。"},{"en":"The team achieved a spectacular success.","zh":"团队取得了惊人的成功。"}]},{"pos":"n.","meaning":"精彩盛大的表演","definition":"a large impressive show","examples":[{"en":"The festival ended with a fireworks spectacular.","zh":"节庆以壮观的烟花表演结束。"},{"en":"The theatre staged a musical spectacular.","zh":"剧院上演了盛大的音乐演出。"}]}],"spectator":[{"pos":"n.","meaning":"观众；旁观者","definition":"Someone watching an event, especially a sport.","examples":[{"en":"Spectators filled the stadium.","zh":"观众坐满了体育场。"},{"en":"A spectator helped retrieve the ball.","zh":"一位观众帮忙捡回了球。"}]}],"spectrum":[{"pos":"n.","meaning":"光谱；频谱","definition":"the range of frequencies or colours in radiation","examples":[{"en":"A prism separates white light into a spectrum.","zh":"棱镜把白光分解成光谱。"},{"en":"The device measures the spectrum of the signal.","zh":"这台设备测量信号的频谱。"}]},{"pos":"n.","meaning":"范围；系列","definition":"a broad range of related possibilities","examples":[{"en":"The survey represents a wide spectrum of opinions.","zh":"这项调查反映了广泛的观点。"},{"en":"The festival offers music across the cultural spectrum.","zh":"这个节日展示了多种文化的音乐。"}]}],"speculate":[{"pos":"v.","meaning":"推测；猜测","definition":"to form ideas without enough evidence","examples":[{"en":"Experts speculated about the cause.","zh":"专家推测原因。"},{"en":"We can only speculate on the outcome.","zh":"我们只能猜测结果。"}]},{"pos":"v.","meaning":"投机","definition":"to buy assets hoping to profit from price changes","examples":[{"en":"He lost money speculating in property.","zh":"他投资房地产投机亏了钱。"},{"en":"The article describes traders speculating on currencies.","zh":"文章描述交易员进行货币投机。"}]}],"speculation":[{"pos":"n.","meaning":"推测；猜测；思索","definition":"Thought or discussion without definite evidence.","examples":[{"en":"The announcement ended weeks of speculation.","zh":"公告结束了持续数周的猜测。"},{"en":"There is much speculation about the building's original purpose.","zh":"人们对建筑的原始用途有很多推测。"}]},{"pos":"n.","meaning":"投机；投机买卖","definition":"Buying or selling assets in the hope of profiting from price changes.","examples":[{"en":"Speculation drove up land prices.","zh":"投机推高了地价。"},{"en":"The company suffered losses from currency speculation.","zh":"公司因货币投机遭受损失。"}]}],"sphere":[{"pos":"n.","meaning":"球体","definition":"a completely round solid shape","examples":[{"en":"The model shows Earth as a blue sphere.","zh":"模型把地球表现为一个蓝色球体。"},{"en":"She moulded the clay into a sphere.","zh":"她把黏土塑成了球形。"}]},{"pos":"n.","meaning":"领域；范围","definition":"an area of activity or influence","examples":[{"en":"The issue falls outside my sphere of responsibility.","zh":"这个问题不属于我的职责范围。"},{"en":"Digital tools have changed the sphere of education.","zh":"数字工具改变了教育领域。"}]}],"spice":[{"pos":"n.","meaning":"香料；调味品","definition":"a substance used to add flavour to food","examples":[{"en":"The market smells of spices.","zh":"市场散发着香料味。"},{"en":"Cinnamon is a popular spice.","zh":"肉桂是一种常用香料。"}]},{"pos":"v.","meaning":"给……加香料","definition":"to add flavour with spices","examples":[{"en":"She spiced the soup with pepper.","zh":"她用胡椒给汤调味。"},{"en":"The rice was lightly spiced.","zh":"米饭加了少量香料。"}]},{"pos":"v.","meaning":"增添趣味（常与 up 连用）","definition":"to make something more interesting","examples":[{"en":"The stories spiced up the lecture.","zh":"故事使讲座更有趣。"},{"en":"They added games to spice up the lesson.","zh":"他们增加游戏来活跃课堂。"}]}],"spill":[{"pos":"v.","meaning":"洒出；溢出；涌出","definition":"To flow or fall out of a container or crowded place.","examples":[{"en":"She spilled coffee on the table.","zh":"她把咖啡洒在桌上。"},{"en":"Crowds spilled into the street after the concert.","zh":"音乐会后，人群涌上街道。"}]}],"spin":[{"pos":"v.","meaning":"旋转；使旋转","definition":"to turn quickly around a central point","examples":[{"en":"The wheel continued to spin after he let go.","zh":"他松手后，轮子仍在旋转。"},{"en":"She spun the globe to find the island.","zh":"她转动地球仪寻找那座岛。"}]},{"pos":"n.","meaning":"旋转","definition":"a turning movement","examples":[{"en":"The toy came to rest after one final spin.","zh":"玩具最后转了一圈后停了下来。"},{"en":"The skater ended the routine with a fast spin.","zh":"滑冰者用一个快速旋转结束了表演。"}]}],"spine":[{"pos":"n.","meaning":"脊柱；脊椎","definition":"the line of bones supporting the back","examples":[{"en":"The diagram shows the spine.","zh":"图中展示脊柱。"},{"en":"The chair supports the natural curve of the spine.","zh":"椅子支撑脊柱的自然曲线。"}]},{"pos":"n.","meaning":"刺；棘","definition":"a sharp pointed growth on an animal or plant","examples":[{"en":"The cactus has long spines.","zh":"仙人掌有长刺。"},{"en":"The fish raised its defensive spines.","zh":"鱼竖起防御用的棘。"}]},{"pos":"n.","meaning":"书脊","definition":"the edge joining a book's covers","examples":[{"en":"The title is printed on the spine.","zh":"书名印在书脊上。"},{"en":"The book's spine was damaged.","zh":"书脊损坏了。"}]},{"pos":"n.","meaning":"中轴；核心支撑","definition":"the central supporting part of a structure","examples":[{"en":"The railway forms the spine of the network.","zh":"铁路构成网络的主干。"},{"en":"A central corridor is the building's spine.","zh":"中央走廊是建筑的中轴。"}]}],"spiral":[{"pos":"adj.","meaning":"螺旋形的；盘旋的","definition":"Curving around a central point while moving closer or farther away.","examples":[{"en":"A spiral staircase leads to the tower.","zh":"螺旋楼梯通向塔楼。"},{"en":"The shell has a spiral pattern.","zh":"贝壳上有螺旋纹样。"}]},{"pos":"v.","meaning":"盘旋上升或下降；螺旋运动","definition":"To move in a winding circular path or change rapidly.","examples":[{"en":"The bird spiralled upwards on the warm air.","zh":"鸟借暖气流盘旋上升。"},{"en":"Costs spiralled beyond the original budget.","zh":"费用急剧上涨，超出了最初预算。"}]}],"spiritual":[{"pos":"adj.","meaning":"精神的；心灵的","definition":"connected with inner beliefs and feelings beyond material needs","examples":[{"en":"The journey had a deep spiritual meaning for her.","zh":"这段旅程对她具有深刻的精神意义。"},{"en":"Music can provide spiritual comfort during difficult times.","zh":"音乐能在人生困难时期带来心灵慰藉。"}]},{"pos":"adj.","meaning":"宗教的","definition":"connected with religion or religious life","examples":[{"en":"The building serves as a spiritual centre for the community.","zh":"这座建筑是社区的宗教中心。"},{"en":"He sought guidance from a spiritual leader.","zh":"他向一位宗教领袖寻求指引。"}]}],"spit":[{"pos":"v.","meaning":"吐唾沫；吐出","definition":"to force saliva or something else from the mouth","examples":[{"en":"The child spat out the bitter food.","zh":"孩子吐出了苦味食物。"},{"en":"Please do not spit on the pavement.","zh":"请勿在人行道上吐痰。"}]},{"pos":"v.","meaning":"喷出；迸出","definition":"to eject small amounts sharply","examples":[{"en":"The fire spat sparks.","zh":"火迸出火星。"},{"en":"The faulty tap spat water.","zh":"坏水龙头喷溅着水。"}]},{"pos":"n.","meaning":"唾液；唾沫","definition":"saliva from the mouth","examples":[{"en":"A little spit landed on the cloth.","zh":"一点唾沫落在布上。"},{"en":"The sample contained spit rather than water.","zh":"样本里是唾液而不是水。"}]}],"spite":[{"pos":"n.","meaning":"恶意；怨恨","definition":"A desire to hurt or upset someone.","examples":[{"en":"He broke the toy out of spite.","zh":"他出于恶意弄坏了玩具。"},{"en":"Her words were full of spite.","zh":"她的话充满怨恨。"}]}],"splash":[{"pos":"v.","meaning":"溅；泼","definition":"to scatter liquid or cause it to scatter","examples":[{"en":"Water splashed onto the floor when the bucket fell.","zh":"水桶倒下时，水溅到了地板上。"},{"en":"The children splashed each other in the shallow pool.","zh":"孩子们在浅水池里互相泼水。"}]},{"pos":"n.","meaning":"泼溅；泼溅声","definition":"a sudden movement or sound of liquid scattering","examples":[{"en":"We heard a splash as the stone hit the pond.","zh":"石头落入池塘时，我们听到了一声水响。"},{"en":"A splash of paint landed on his sleeve.","zh":"一小片油漆溅到了他的袖子上。"}]}],"splendid":[{"pos":"adj.","meaning":"壮丽的；豪华的；极好的","definition":"very impressive, beautiful, or excellent","examples":[{"en":"The palace has splendid halls.","zh":"宫殿有壮丽的大厅。"},{"en":"You have done a splendid job.","zh":"你干得非常好。"}]}],"splint":[{"pos":"n.","meaning":"夹板","definition":"A rigid support used to keep an injured body part still.","examples":[{"en":"The nurse fitted a splint to the injured wrist.","zh":"护士给受伤手腕装上夹板。"},{"en":"A splint kept the finger straight.","zh":"夹板使手指保持伸直。"}]},{"pos":"n.","meaning":"细木条；木梗","definition":"A thin narrow strip of wood.","examples":[{"en":"The chemist lit a wooden splint.","zh":"化学工作者点燃了一根细木条。"},{"en":"The basket was woven from thin splints.","zh":"篮子由细木条编成。"}]},{"pos":"v.","meaning":"用夹板固定","definition":"To support an injured body part with a rigid strip.","examples":[{"en":"The medic splinted the broken leg.","zh":"医护人员用夹板固定了骨折的腿。"},{"en":"Her wrist was splinted before she was moved.","zh":"搬动她之前，手腕已用夹板固定。"}]}],"split":[{"pos":"v.","meaning":"分裂；裂开；劈开","definition":"to divide or break into separate parts","examples":[{"en":"The wood split along a natural line.","zh":"木头沿着天然纹路裂开了。"},{"en":"The disagreement split the committee into two groups.","zh":"分歧使委员会分成了两派。"}]},{"pos":"v.","meaning":"分担；分享","definition":"to divide something among people","examples":[{"en":"We agreed to split the travel costs.","zh":"我们同意分担旅费。"},{"en":"The sisters split the last piece of cake.","zh":"姐妹俩分吃了最后一块蛋糕。"}]},{"pos":"n.","meaning":"裂口；裂缝","definition":"an opening caused by something breaking apart","examples":[{"en":"There is a split in the leather seat.","zh":"皮革座椅上有一道裂口。"},{"en":"Water entered through a split in the pipe.","zh":"水从管道的一道裂缝进入。"}]},{"pos":"n.","meaning":"分裂；分歧","definition":"a separation between people or groups","examples":[{"en":"The vote revealed a split within the organisation.","zh":"投票暴露了组织内部的分歧。"},{"en":"The party struggled to recover from the split.","zh":"这个政党很难从分裂中恢复过来。"}]}],"spoil":[{"pos":"v.","meaning":"破坏；糟蹋","definition":"to damage enjoyment or quality","examples":[{"en":"Rain spoiled the picnic.","zh":"雨破坏了野餐。"},{"en":"One mistake should not spoil the whole day.","zh":"一个错误不该毁了一整天的心情。"}]},{"pos":"v.","meaning":"宠坏；溺爱","definition":"to harm someone's character through excessive indulgence","examples":[{"en":"They worried about spoiling the child.","zh":"他们担心宠坏孩子。"},{"en":"The story portrays a boy spoiled by attention.","zh":"故事描绘了一个被过度关注宠坏的男孩。"}]},{"pos":"v.","meaning":"变质；腐坏","definition":"to become unfit to eat","examples":[{"en":"The milk spoiled in the heat.","zh":"牛奶在高温中变质了。"},{"en":"Refrigeration keeps food from spoiling quickly.","zh":"冷藏防止食物迅速腐坏。"}]},{"pos":"n.","meaning":"战利品；掠夺物（常用复数）","definition":"goods taken from a defeated enemy","examples":[{"en":"The soldiers divided the spoils.","zh":"士兵分配了战利品。"},{"en":"The museum displays objects once taken as spoils.","zh":"博物馆展示曾被作为战利品掠走的物品。"}]}],"spoilage":[{"pos":"n.","meaning":"变质；损坏","definition":"The process of becoming unfit for use or consumption.","examples":[{"en":"Refrigeration reduces food spoilage.","zh":"冷藏减少食物变质。"},{"en":"Poor storage caused significant spoilage of the crop.","zh":"储存不当使收获物严重损坏。"}]}],"sponge":[{"pos":"n.","meaning":"海绵","definition":"a soft material or sea animal with many small holes","examples":[{"en":"Use a damp sponge to clean the tiles.","zh":"用湿海绵擦洗瓷砖。"},{"en":"A sponge absorbs water through its tiny spaces.","zh":"海绵通过细小空隙吸水。"}]},{"pos":"v.","meaning":"用湿海绵擦","definition":"to wipe or clean with a damp sponge","examples":[{"en":"She sponged the mark off the table.","zh":"她用湿海绵擦掉了桌上的污迹。"},{"en":"He gently sponged his face with cool water.","zh":"他用蘸了凉水的海绵轻轻擦脸。"}]}],"sponsor":[{"pos":"n.","meaning":"赞助者；主办者；发起人","definition":"a person or organisation providing support for an activity","examples":[{"en":"The event needs a sponsor.","zh":"活动需要赞助者。"},{"en":"The bill's sponsor explained its purpose.","zh":"法案发起人解释了其目的。"}]},{"pos":"v.","meaning":"赞助；资助；发起；主办","definition":"to support financially or formally initiate something","examples":[{"en":"A local company sponsored the race.","zh":"一家本地公司赞助了比赛。"},{"en":"The university sponsored a public lecture.","zh":"大学主办了一场公开讲座。"}]}],"sporadically":[{"pos":"adv.","meaning":"偶尔地；零星地；不定期地","definition":"At irregular and infrequent intervals.","examples":[{"en":"Rain fell sporadically during the afternoon.","zh":"下午零星地下了几阵雨。"},{"en":"He attended the meetings only sporadically.","zh":"他只是偶尔参加会议。"}]}],"spot":[{"pos":"v.","meaning":"发现；认出","definition":"to notice or identify something","examples":[{"en":"She spotted a spelling mistake in the title.","zh":"她发现标题中有一处拼写错误。"},{"en":"We spotted our guide near the entrance.","zh":"我们在入口附近认出了导游。"}]},{"pos":"n.","meaning":"地点；处所","definition":"a particular place","examples":[{"en":"This is a quiet spot for a picnic.","zh":"这里是野餐的安静地点。"},{"en":"Mark the spot where the sample was collected.","zh":"标出采集样本的位置。"}]},{"pos":"n.","meaning":"斑点；污点","definition":"a small mark with a different colour","examples":[{"en":"The shirt has a spot of ink on the collar.","zh":"衬衫领口上有一个墨点。"},{"en":"The bird has white spots on its wings.","zh":"这只鸟的翅膀上有白色斑点。"}]},{"pos":"n.","meaning":"少量；一点（口语）","definition":"a small amount of something","examples":[{"en":"We stopped for a spot of lunch.","zh":"我们停下来吃了点午餐。"},{"en":"A spot of rain will help the dry garden.","zh":"下一点雨对干燥的花园会有帮助。"}]}],"spot on":[{"pos":"adj.","meaning":"完全准确的；恰到好处的","definition":"exactly correct","examples":[{"en":"Your estimate was spot on.","zh":"你的估计完全准确。"},{"en":"Her description was spot on.","zh":"她的描述十分准确。"}]},{"pos":"adv.","meaning":"准确地；恰好地","definition":"exactly or accurately","examples":[{"en":"He guessed the answer spot on.","zh":"他把答案猜得准确无误。"},{"en":"The clock struck twelve spot on.","zh":"钟恰好在十二点敲响。"}]}],"spouse":[{"pos":"n.","meaning":"配偶","definition":"A person's husband or wife.","examples":[{"en":"Employees may bring their spouses to the dinner.","zh":"员工可以携配偶参加晚宴。"},{"en":"The form asks for the name of your spouse.","zh":"表格要求填写配偶姓名。"}]}],"sprawl":[{"pos":"v.","meaning":"四肢伸开地坐卧","definition":"to sit or lie with the limbs spread out","examples":[{"en":"He sprawled on the sofa after work.","zh":"下班后，他四肢伸开躺在沙发上。"},{"en":"The dog was sprawling across the doorway.","zh":"狗伸开四肢躺在门口。"}]},{"pos":"v.","meaning":"杂乱扩展；蔓延","definition":"to spread over a large area without clear organisation","examples":[{"en":"New buildings sprawl across the valley.","zh":"新建筑杂乱地延伸到了整个山谷。"},{"en":"The city has sprawled far beyond its old boundary.","zh":"城市已经无序扩展到远超旧边界的地方。"}]},{"pos":"n.","meaning":"四肢伸开的姿势","definition":"a position in which the limbs are spread out","examples":[{"en":"The child landed in a sprawl on the grass.","zh":"孩子四肢摊开地跌坐在草地上。"},{"en":"He settled into a relaxed sprawl in the armchair.","zh":"他放松地伸展四肢坐进扶手椅。"}]},{"pos":"n.","meaning":"无计划的城市扩张","definition":"unplanned growth over a wide urban area","examples":[{"en":"Urban sprawl has replaced many local fields.","zh":"城市的无序扩张占用了当地许多农田。"},{"en":"The plan aims to limit sprawl around the station.","zh":"这项计划旨在限制车站周围的无序扩建。"}]}],"spray":[{"pos":"n.","meaning":"喷雾；飞沫；浪花","definition":"fine drops scattered through the air","examples":[{"en":"Sea spray covered the windows.","zh":"海水飞沫覆盖了窗户。"},{"en":"The nozzle produces a fine spray.","zh":"喷嘴产生细雾。"}]},{"pos":"v.","meaning":"喷洒；喷射","definition":"to scatter liquid in fine drops","examples":[{"en":"She sprayed water on the leaves.","zh":"她向叶子喷水。"},{"en":"The waves sprayed the deck.","zh":"海浪把水溅洒到甲板上。"}]}],"spring":[{"pos":"n.","meaning":"春天；春季","definition":"The season between winter and summer.","examples":[{"en":"The garden is full of colour in spring.","zh":"春天花园色彩缤纷。"},{"en":"They plan to move next spring.","zh":"他们计划明年春天搬家。"}]},{"pos":"n.","meaning":"弹簧；发条","definition":"A flexible device that returns to its shape after pressure.","examples":[{"en":"A spring inside the latch had broken.","zh":"门闩内部的弹簧断了。"},{"en":"The clock is powered by a wound spring.","zh":"这只钟由上紧的发条驱动。"}]},{"pos":"n.","meaning":"弹性；弹力","definition":"The ability to bounce back or move lightly.","examples":[{"en":"The mattress has lost its spring.","zh":"床垫失去了弹性。"},{"en":"There was a spring in her step after the good news.","zh":"听到好消息后，她的脚步变得轻快。"}]},{"pos":"n.","meaning":"泉；泉水源头","definition":"A place where water flows naturally from the ground.","examples":[{"en":"A clear spring feeds the stream.","zh":"一眼清泉为小溪供水。"},{"en":"The village grew around a natural spring.","zh":"村庄围绕一处天然泉眼发展起来。"}]},{"pos":"n.","meaning":"跳跃；跃起","definition":"A sudden leap.","examples":[{"en":"The cat reached the wall with one spring.","zh":"猫一跃上了墙。"},{"en":"She crossed the ditch with a quick spring.","zh":"她迅速一跳越过沟渠。"}]},{"pos":"v.","meaning":"跳起；跃起","definition":"To move suddenly with a jump.","examples":[{"en":"He sprang out of bed.","zh":"他从床上一跃而起。"},{"en":"The deer sprang over the fence.","zh":"鹿跃过了围栏。"}]},{"pos":"v.","meaning":"涌现；突然出现；源于","definition":"To appear or arise, often suddenly.","examples":[{"en":"New shops sprang up near the station.","zh":"车站附近涌现出新商店。"},{"en":"Her interest sprang from a childhood visit.","zh":"她的兴趣源于童年的一次参观。"}]},{"pos":"v.","meaning":"突然提出；出其不意地告知","definition":"To reveal something unexpectedly, often with on.","examples":[{"en":"He sprang the news on us at dinner.","zh":"他在晚餐时突然把消息告诉了我们。"},{"en":"Do not spring difficult questions on an unprepared speaker.","zh":"不要突然向毫无准备的演讲者抛出难题。"}]}],"spur":[{"pos":"n.","meaning":"激励；推动因素","definition":"something that encourages action","examples":[{"en":"The prize provided a spur to further research.","zh":"这项奖励推动了进一步研究。"},{"en":"Competition can be a spur to better service.","zh":"竞争可以促进服务改善。"}]},{"pos":"n.","meaning":"马刺","definition":"a small pointed device on a rider's heel","examples":[{"en":"The museum displayed a pair of old riding spurs.","zh":"博物馆展出了一副旧马刺。"},{"en":"A metal spur was attached to the rider's boot.","zh":"骑手的靴子上装着一只金属马刺。"}]},{"pos":"v.","meaning":"激励；促进","definition":"to encourage someone to act or develop","examples":[{"en":"The success spurred her to attempt a harder task.","zh":"这次成功激励她尝试更难的任务。"},{"en":"New funding has spurred local research.","zh":"新的资金促进了当地的研究。"}]},{"pos":"v.","meaning":"用马刺策马","definition":"to urge a horse forward with spurs","examples":[{"en":"The rider spurred his horse towards the gate.","zh":"骑手用马刺催马奔向大门。"},{"en":"In the story, the messenger spurs his horse up the hill.","zh":"故事中，信使用马刺催马跑上山坡。"}]}],"squash":[{"pos":"n.","meaning":"壁球","definition":"a racket sport played in an enclosed court","examples":[{"en":"She plays squash every weekend.","zh":"她每周末打壁球。"},{"en":"The club has two squash courts.","zh":"俱乐部有两个壁球场。"}]},{"pos":"v.","meaning":"压扁；挤压；塞入","definition":"to crush or squeeze into a small space","examples":[{"en":"The heavy box squashed the tomatoes.","zh":"重箱子压扁了番茄。"},{"en":"We squashed into the small car.","zh":"我们挤进了小汽车。"}]},{"pos":"v.","meaning":"压制；制止","definition":"to stop something firmly","examples":[{"en":"The manager squashed the rumour.","zh":"经理制止了谣言。"},{"en":"She quickly squashed their objections.","zh":"她迅速压下了他们的反对意见。"}]}],"squeeze":[{"pos":"v.","meaning":"挤压；捏；榨取","definition":"To press something firmly, often to force out liquid.","examples":[{"en":"Squeeze the lemon into the bowl.","zh":"把柠檬汁挤进碗里。"},{"en":"She squeezed his hand reassuringly.","zh":"她握紧他的手，安慰他。"}]},{"pos":"v.","meaning":"挤入；挤过","definition":"To move through or fit into a narrow space.","examples":[{"en":"We squeezed through the crowded doorway.","zh":"我们挤过了拥挤的门口。"},{"en":"Can you squeeze another chair around the table?","zh":"你能在桌边再挤下一把椅子吗？"}]},{"pos":"v.","meaning":"敲诈；榨取钱财","definition":"To pressure someone into giving money or resources.","examples":[{"en":"The gang squeezed money from local traders.","zh":"团伙向当地商贩勒索钱财。"},{"en":"The supplier tried to squeeze extra fees out of the client.","zh":"供应商试图从客户那里榨取额外费用。"}]},{"pos":"n.","meaning":"挤压；紧握","definition":"An act of pressing tightly.","examples":[{"en":"Give the tube a gentle squeeze.","zh":"轻轻挤一下管子。"},{"en":"She gave his arm a friendly squeeze.","zh":"她友好地握了一下他的胳膊。"}]},{"pos":"n.","meaning":"紧缺；拮据；削减；紧缩","definition":"Pressure caused by reduced money, space, or resources.","examples":[{"en":"The budget squeeze forced the centre to cut hours.","zh":"预算紧缩迫使中心缩短开放时间。"},{"en":"Rising rents put a squeeze on household finances.","zh":"租金上涨使家庭财务吃紧。"}]}],"stab":[{"pos":"v.","meaning":"刺；戳","definition":"to push a pointed object sharply into something","examples":[{"en":"She stabbed a potato with a fork to test it.","zh":"她用叉子戳了戳土豆，看看熟了没有。"},{"en":"He stabbed the soil with a garden tool.","zh":"他用园艺工具刺入土壤。"}]},{"pos":"n.","meaning":"刺；戳","definition":"a sharp pushing movement with a pointed object","examples":[{"en":"One stab of the fork broke the pastry.","zh":"叉子一戳就弄破了酥皮。"},{"en":"He made a quick stab at the hard soil with the spade.","zh":"他用铲子快速戳了一下坚硬的土壤。"}]}],"stabilise":[{"pos":"v.","meaning":"稳定；使稳固","definition":"to become or make steady","examples":[{"en":"The repairs stabilised the wall.","zh":"维修使墙体稳固。"},{"en":"Prices began to stabilise.","zh":"价格开始稳定。"}]}],"stable":[{"pos":"adj.","meaning":"稳定的；稳固的；安定的","definition":"Firm and unlikely to change suddenly.","examples":[{"en":"The ladder is stable on this surface.","zh":"梯子在这个表面上很稳。"},{"en":"Prices remained stable throughout the year.","zh":"价格全年保持稳定。"}]},{"pos":"adj.","meaning":"沉稳的；情绪稳定的","definition":"Calm and reliable in mood or behaviour.","examples":[{"en":"She provides a stable presence in a busy team.","zh":"她为忙碌的团队带来沉稳可靠的支持。"},{"en":"The children benefited from a stable home environment.","zh":"稳定的家庭环境让孩子们受益。"}]},{"pos":"n.","meaning":"马厩","definition":"A building where horses are kept.","examples":[{"en":"The horses returned to the stable.","zh":"马回到了马厩。"},{"en":"He cleaned the stable before breakfast.","zh":"他在早饭前打扫了马厩。"}]}],"stack":[{"pos":"n.","meaning":"一叠；一摞","definition":"a neat pile of objects placed on one another","examples":[{"en":"A stack of clean towels stood by the sink.","zh":"洗手池旁放着一摞干净毛巾。"},{"en":"She took a book from the top of the stack.","zh":"她从书堆顶部取下一本书。"}]},{"pos":"v.","meaning":"堆放；叠放","definition":"to place objects in a pile","examples":[{"en":"Please stack the chairs against the wall.","zh":"请把椅子叠放在墙边。"},{"en":"They stacked the boxes carefully in the van.","zh":"他们把箱子小心地堆放在货车里。"}]}],"staff":[{"pos":"n.","meaning":"全体员工；工作人员","definition":"the people employed by an organisation","examples":[{"en":"The staff welcomed the new manager.","zh":"员工欢迎了新经理。"},{"en":"Hospital staff worked through the night.","zh":"医院工作人员彻夜工作。"}]},{"pos":"n.","meaning":"棍；手杖","definition":"a long stick used for support or as a symbol","examples":[{"en":"The traveller leaned on a wooden staff.","zh":"旅行者倚着一根木杖。"},{"en":"The portrait shows a ceremonial staff.","zh":"肖像中有一根礼仪权杖。"}]},{"pos":"n.","meaning":"参谋人员；幕僚","definition":"officers assisting a military commander","examples":[{"en":"The general consulted his staff.","zh":"将军向参谋人员征询意见。"},{"en":"The staff prepared detailed maps.","zh":"参谋人员准备了详细地图。"}]},{"pos":"v.","meaning":"为……配备人员；在……任职","definition":"to provide or serve as workers","examples":[{"en":"Volunteers staff the information desk.","zh":"志愿者在咨询台服务。"},{"en":"The centre is staffed around the clock.","zh":"中心全天有人值守。"}]}],"stage":[{"pos":"n.","meaning":"舞台","definition":"A raised area where people perform.","examples":[{"en":"The actors stepped onto the stage.","zh":"演员走上舞台。"},{"en":"A single spotlight lit the stage.","zh":"一盏聚光灯照亮了舞台。"}]},{"pos":"n.","meaning":"戏剧；戏剧界","definition":"The theatre as a profession or art.","examples":[{"en":"She spent her life on the stage.","zh":"她把一生奉献给了舞台艺术。"},{"en":"The novel was adapted for the stage.","zh":"这部小说被改编成戏剧。"}]},{"pos":"n.","meaning":"阶段；时期","definition":"A particular part of a process.","examples":[{"en":"The project is in its final stage.","zh":"项目处于最后阶段。"},{"en":"Children develop at different stages.","zh":"儿童处于不同的发展阶段。"}]}],"stagnate":[{"pos":"v.","meaning":"停滞；不发展","definition":"to stop developing or making progress","examples":[{"en":"Wages began to stagnate after several years of growth.","zh":"工资增长数年后开始停滞。"},{"en":"Without fresh ideas, the project may stagnate.","zh":"如果没有新思路，项目可能停滞不前。"}]},{"pos":"v.","meaning":"水流停滞；变污浊","definition":"to remain still rather than flow freely","examples":[{"en":"Water stagnated in the blocked drain.","zh":"水在堵塞的排水管中停滞不流。"},{"en":"The small pond can stagnate during long dry periods.","zh":"长期干旱时，小池塘的水可能变成死水。"}]}],"stain":[{"pos":"v.","meaning":"弄污；留下污痕","definition":"to leave a coloured mark","examples":[{"en":"The juice stained the tablecloth.","zh":"果汁弄脏了桌布。"},{"en":"Ink had stained his fingers.","zh":"墨水染污了他的手指。"}]},{"pos":"v.","meaning":"染色；着色","definition":"to colour a material with a dye","examples":[{"en":"They stained the wood dark brown.","zh":"他们把木头染成深棕色。"},{"en":"The cells were stained for examination.","zh":"细胞被染色以便检查。"}]},{"pos":"n.","meaning":"污点；污渍","definition":"a coloured mark that is difficult to remove","examples":[{"en":"There is a coffee stain on the page.","zh":"书页上有咖啡渍。"},{"en":"The scandal left a stain on his reputation.","zh":"丑闻给他的名声留下污点。"}]}],"stainless":[{"pos":"adj.","meaning":"不锈的；耐腐蚀的","definition":"Resistant to rust or staining.","examples":[{"en":"The sink is made from stainless steel.","zh":"水槽由不锈钢制成。"},{"en":"Use stainless utensils for the preparation.","zh":"准备时请使用不锈钢器具。"}]},{"pos":"adj.","meaning":"无污点的；无瑕疵的","definition":"Free from marks or moral blame.","examples":[{"en":"The story portrays a hero of stainless honour.","zh":"故事描绘了一位荣誉无瑕的英雄。"},{"en":"She maintained a stainless reputation throughout her career.","zh":"她整个职业生涯保持了清白声誉。"}]}],"staircase":[{"pos":"n.","meaning":"楼梯","definition":"a set of stairs with its supporting structure","examples":[{"en":"A narrow staircase leads to the attic.","zh":"一道狭窄的楼梯通往阁楼。"},{"en":"The hotel restored its wooden staircase.","zh":"这家酒店修复了木楼梯。"}]}],"stake":[{"pos":"n.","meaning":"桩；木桩","definition":"a pointed post driven into the ground","examples":[{"en":"Tie the young tree to a stake.","zh":"把幼树绑在木桩上。"},{"en":"Stakes mark the edge of the plot.","zh":"木桩标出地块边界。"}]},{"pos":"n.","meaning":"火刑柱（历史用语）","definition":"a post to which a person was tied for execution by burning","examples":[{"en":"The history describes prisoners condemned to the stake.","zh":"历史记述描述了被判火刑的囚犯。"},{"en":"The painting depicts a figure bound to a stake.","zh":"画中人物被绑在火刑柱上。"}]},{"pos":"n.","meaning":"利益关系；股份","definition":"an interest or share in something","examples":[{"en":"Employees have a stake in the company's success.","zh":"员工与公司的成功有利益关系。"},{"en":"She bought a small stake in the business.","zh":"她买入企业的一小部分股份。"}]},{"pos":"n.","meaning":"赌注；风险中的利益","definition":"money or something valuable risked on an outcome","examples":[{"en":"The player increased his stake.","zh":"玩家增加了赌注。"},{"en":"The stakes were high in the negotiations.","zh":"谈判中利害重大。"}]},{"pos":"v.","meaning":"押上；拿……冒险","definition":"to risk something on an outcome","examples":[{"en":"He staked his savings on the venture.","zh":"他把积蓄押在这项事业上。"},{"en":"She staked her reputation on the result.","zh":"她拿名誉为结果作担保。"}]}],"stale":[{"pos":"adj.","meaning":"不新鲜的；变味的","definition":"No longer fresh.","examples":[{"en":"The bread had become stale.","zh":"面包已经不新鲜了。"},{"en":"We opened the windows to let out the stale air.","zh":"我们打开窗户，排出不新鲜的空气。"}]},{"pos":"adj.","meaning":"陈腐的；缺乏新意的","definition":"No longer interesting because of repetition.","examples":[{"en":"The comedian relied on stale jokes.","zh":"喜剧演员靠陈旧笑话撑场。"},{"en":"The debate repeated stale arguments.","zh":"辩论重复着陈词滥调。"}]}],"stall":[{"pos":"n.","meaning":"货摊；摊位","definition":"a small place where goods are sold","examples":[{"en":"We bought vegetables from a market stall.","zh":"我们从市场摊位上买了蔬菜。"},{"en":"Her stall sells handmade bags.","zh":"她的摊位出售手工包。"}]},{"pos":"n.","meaning":"小隔间；畜栏","definition":"a small enclosed space for one person or animal","examples":[{"en":"The horse returned to its stall.","zh":"马回到了自己的马厩隔间。"},{"en":"The changing area has six separate stalls.","zh":"更衣区有六个独立隔间。"}]},{"pos":"v.","meaning":"熄火；停止运转","definition":"to stop running unexpectedly","examples":[{"en":"The engine stalled at the traffic lights.","zh":"发动机在红绿灯处熄火了。"},{"en":"The car kept stalling on the steep road.","zh":"汽车在陡路上不断熄火。"}]},{"pos":"v.","meaning":"拖延；停滞","definition":"to delay progress or stop moving forward","examples":[{"en":"The talks stalled over the final clause.","zh":"谈判因最后一项条款而陷入停滞。"},{"en":"He asked more questions to stall for time.","zh":"他多问了几个问题来拖延时间。"}]}],"stammer":[{"pos":"n.","meaning":"口吃","definition":"a speech difficulty involving repeated or blocked sounds","examples":[{"en":"He spoke with a slight stammer.","zh":"他说话略有口吃。"},{"en":"Her stammer became more noticeable when tired.","zh":"疲劳时，她的口吃更明显。"}]},{"pos":"v.","meaning":"结巴地说；口吃","definition":"to speak with difficulty repeating or blocking sounds","examples":[{"en":"He stammered an apology.","zh":"他结结巴巴地道歉。"},{"en":"She began to stammer during the introduction.","zh":"介绍时她开始口吃。"}]}],"stamp":[{"pos":"v.","meaning":"跺脚；重踏；重步走","definition":"To bring a foot down hard or walk noisily.","examples":[{"en":"He stamped his feet to keep warm.","zh":"他跺脚取暖。"},{"en":"She stamped angrily out of the room.","zh":"她气冲冲地重步走出房间。"}]},{"pos":"v.","meaning":"盖章；印上标记","definition":"To mark something with an official sign or pattern.","examples":[{"en":"The clerk stamped my passport.","zh":"办事员在我的护照上盖了章。"},{"en":"Each part is stamped with a serial number.","zh":"每个部件都印有序列号。"}]},{"pos":"n.","meaning":"邮票；印花税票","definition":"A small official label showing that postage or a tax has been paid.","examples":[{"en":"Put a stamp on the envelope.","zh":"在信封上贴一张邮票。"},{"en":"The document required a revenue stamp.","zh":"文件需要贴印花税票。"}]},{"pos":"n.","meaning":"图章；印章；印记","definition":"A device or mark used to show approval, identity, or character.","examples":[{"en":"The letter bears the official stamp.","zh":"信上盖有公章。"},{"en":"The building carries the unmistakable stamp of its architect.","zh":"这栋建筑带有建筑师鲜明的风格印记。"}]},{"pos":"n.","meaning":"跺脚；重踏","definition":"An act of bringing a foot down forcefully.","examples":[{"en":"A stamp of her foot showed her impatience.","zh":"她跺了一下脚，显出不耐烦。"},{"en":"We heard a loud stamp from the room above.","zh":"我们听到楼上房间里一声响亮的跺脚。"}]}],"stance":[{"pos":"n.","meaning":"站姿；姿势","definition":"the way someone stands, especially for an activity","examples":[{"en":"The coach adjusted the player's stance.","zh":"教练调整了运动员的站姿。"},{"en":"A wider stance helped her keep her balance.","zh":"双脚站得更开帮助她保持平衡。"}]},{"pos":"n.","meaning":"立场；观点","definition":"a position taken on an issue","examples":[{"en":"The group adopted a firm stance on pollution.","zh":"这个团体在污染问题上采取了坚定立场。"},{"en":"She explained her stance during the discussion.","zh":"她在讨论中解释了自己的立场。"}]}],"standard":[{"pos":"n.","meaning":"标准；水平","definition":"a measure of acceptable quality or achievement","examples":[{"en":"The work meets the required standard.","zh":"工作达到所需标准。"},{"en":"The school maintains high standards.","zh":"学校保持高标准。"}]},{"pos":"adj.","meaning":"标准的；通常的","definition":"accepted as normal or usual","examples":[{"en":"Use the standard form.","zh":"使用标准表格。"},{"en":"The room includes standard equipment.","zh":"房间配有常规设备。"}]}],"standpoint":[{"pos":"n.","meaning":"立场；观点；角度","definition":"A particular position from which something is considered.","examples":[{"en":"From a practical standpoint, the plan is sound.","zh":"从实用角度看，这个计划可行。"},{"en":"She explained the issue from the tenant's standpoint.","zh":"她从租户的立场解释了问题。"}]}],"starchy":[{"pos":"adj.","meaning":"含淀粉的","definition":"containing a large amount of starch","examples":[{"en":"Rice and potatoes are common starchy foods.","zh":"米饭和土豆是常见的淀粉类食物。"},{"en":"The soup became thick after the starchy vegetables were added.","zh":"加入富含淀粉的蔬菜后，汤变稠了。"}]}],"stare":[{"pos":"v.","meaning":"盯着看；凝视","definition":"to look fixedly for a long time","examples":[{"en":"She stared at the unfamiliar object.","zh":"她盯着陌生物品看。"},{"en":"He stared out of the window.","zh":"他凝视窗外。"}]},{"pos":"n.","meaning":"凝视；直盯着的目光","definition":"a long fixed look","examples":[{"en":"His stare made her uncomfortable.","zh":"他的凝视让她不自在。"},{"en":"She returned his curious stare.","zh":"她回望他好奇的目光。"}]}],"stark":[{"pos":"adj.","meaning":"光秃的；荒凉的；冷峻的","definition":"Bare and severe in appearance.","examples":[{"en":"The room was stark, with only a bed and chair.","zh":"房间空荡荡的，只有一张床和一把椅子。"},{"en":"Bare trees stood against the stark winter landscape.","zh":"光秃的树木矗立在荒凉的冬日景色中。"}]},{"pos":"adj.","meaning":"鲜明的；完全的；毫不掩饰的","definition":"Complete or extremely clear and striking.","examples":[{"en":"There is a stark contrast between the two neighbourhoods.","zh":"两个社区之间存在鲜明对比。"},{"en":"The report revealed the stark reality of the shortage.","zh":"报告揭示了短缺的严酷现实。"}]}],"starve":[{"pos":"v.","meaning":"挨饿；饿死；使挨饿","definition":"to suffer or die from a severe lack of food","examples":[{"en":"Animals may starve when their habitat is destroyed.","zh":"栖息地遭到破坏时，动物可能挨饿。"},{"en":"The rescue team brought food to the starving villagers.","zh":"救援队给饥饿的村民送来了食物。"}]},{"pos":"v.","meaning":"使严重缺乏","definition":"to deprive someone or something of an essential resource","examples":[{"en":"The service has been starved of investment.","zh":"这项服务长期缺乏投资。"},{"en":"Plants starved of light grew weak and pale.","zh":"缺乏光照的植物长得瘦弱苍白。"}]}],"stash":[{"pos":"v.","meaning":"藏匿；储藏","definition":"to hide or store something","examples":[{"en":"She stashed the letters in a drawer.","zh":"她把信藏进抽屉。"},{"en":"They stashed supplies near the campsite.","zh":"他们在营地附近储藏了物资。"}]}],"statement":[{"pos":"n.","meaning":"陈述；声明","definition":"Something said or written to express information or a position.","examples":[{"en":"The witness gave a written statement.","zh":"证人提交了书面陈述。"},{"en":"The company issued a statement about the closure.","zh":"公司就关闭一事发表了声明。"}]},{"pos":"n.","meaning":"报表；结算单","definition":"A formal record of financial activity.","examples":[{"en":"Check your bank statement for errors.","zh":"检查银行对账单是否有错误。"},{"en":"The annual statement lists income and expenses.","zh":"年度报表列出了收入和支出。"}]}],"static":[{"pos":"adj.","meaning":"静止的；不变的","definition":"remaining still or unchanged","examples":[{"en":"The display shows a static image of the map.","zh":"屏幕显示了一张静态地图。"},{"en":"The population remained static for several years.","zh":"人口数年间没有变化。"}]},{"pos":"n.","meaning":"静电","definition":"electric charge that builds up on a surface","examples":[{"en":"Static made the fabric cling to her coat.","zh":"静电使布料贴在她的大衣上。"},{"en":"The packaging helps protect components from static.","zh":"这种包装有助于保护元件免受静电影响。"}]},{"pos":"n.","meaning":"静电噪声；杂音","definition":"crackling noise that interferes with a signal","examples":[{"en":"Static drowned out part of the radio message.","zh":"杂音淹没了部分无线电消息。"},{"en":"The speakers produced a burst of static.","zh":"扬声器发出了一阵刺啦声。"}]}],"stationary":[{"pos":"adj.","meaning":"静止的；固定的","definition":"not moving","examples":[{"en":"The car remained stationary.","zh":"汽车静止不动。"},{"en":"A stationary camera recorded the scene.","zh":"固定摄像机记录了场景。"}]},{"pos":"adj.","meaning":"稳定不变的","definition":"not changing in level or condition","examples":[{"en":"The population remained stationary for years.","zh":"人口多年保持不变。"},{"en":"The model assumes stationary conditions.","zh":"模型假定条件稳定不变。"}]}],"stationery":[{"pos":"n.","meaning":"文具；办公用品","definition":"Materials used for writing and office work.","examples":[{"en":"The cupboard contains spare stationery.","zh":"柜子里放着备用文具。"},{"en":"She ordered envelopes from the stationery shop.","zh":"她从文具店订购了信封。"}]}],"statistic":[{"pos":"n.","meaning":"统计数值","definition":"one numerical fact obtained from data","examples":[{"en":"One statistic cannot describe the whole community.","zh":"一个统计数值无法描述整个社区。"},{"en":"The report includes a statistic on average travel time.","zh":"报告中包含一项关于平均出行时间的统计数据。"}]}],"statistically":[{"pos":"adv.","meaning":"在统计上；从统计角度","definition":"according to statistical methods","examples":[{"en":"The difference was statistically significant.","zh":"差异在统计上显著。"},{"en":"The two groups were statistically comparable.","zh":"两组在统计上具有可比性。"}]}],"statistically significant":[{"pos":"adj.","meaning":"统计上显著的","definition":"meeting a chosen statistical threshold for evidence against a specified null hypothesis","examples":[{"en":"The researchers reported a statistically significant difference between the groups.","zh":"研究人员报告称两组之间存在统计上显著的差异。"},{"en":"A statistically significant result may still have only a small practical effect.","zh":"统计上显著的结果在实际应用中仍可能只有很小的影响。"}]}],"statistics":[{"pos":"n.","meaning":"统计数字；统计资料","definition":"Numerical information collected about a subject.","examples":[{"en":"The statistics show a fall in unemployment.","zh":"统计数字显示失业率下降。"},{"en":"Reliable statistics are essential for planning.","zh":"可靠的统计资料对于规划必不可少。"}]},{"pos":"n.","meaning":"统计学","definition":"The study of collecting, analysing, and interpreting numerical data.","examples":[{"en":"She studies statistics at university.","zh":"她在大学学习统计学。"},{"en":"A basic knowledge of statistics helps researchers evaluate evidence.","zh":"基本统计学知识有助于研究人员评估证据。"}]}],"statue":[{"pos":"n.","meaning":"雕像；塑像","definition":"a three-dimensional figure made to represent someone or something","examples":[{"en":"A bronze statue stands outside the library.","zh":"图书馆外立着一尊铜像。"},{"en":"The artist carved a statue from local stone.","zh":"艺术家用当地石材雕刻了一尊雕像。"}]}],"status":[{"pos":"n.","meaning":"地位；身份","definition":"a person's position in a social or legal system","examples":[{"en":"Education can affect social status.","zh":"教育可能影响社会地位。"},{"en":"The form asks for employment status.","zh":"表格询问就业身份。"}]},{"pos":"n.","meaning":"状态；状况","definition":"the current condition of something","examples":[{"en":"Check the status of your application.","zh":"查看申请状态。"},{"en":"The report updates the project's status.","zh":"报告更新了项目状况。"}]}],"steady":[{"pos":"adj.","meaning":"稳定的；平稳的；持续的","definition":"Firm, regular, and not changing suddenly.","examples":[{"en":"Keep the camera steady.","zh":"保持相机稳定。"},{"en":"The business has shown steady growth.","zh":"企业一直稳步增长。"}]},{"pos":"v.","meaning":"使稳定；稳住；使镇定","definition":"To make or become stable or calm.","examples":[{"en":"He steadied the ladder with both hands.","zh":"他用双手稳住梯子。"},{"en":"She took a breath to steady her nerves.","zh":"她吸了一口气来稳定情绪。"}]}],"steam":[{"pos":"n.","meaning":"蒸汽；水汽","definition":"water in its heated gaseous form or visible mist","examples":[{"en":"Steam rose from the pot of rice.","zh":"蒸汽从饭锅里冒了出来。"},{"en":"The mirror was covered with steam after the shower.","zh":"淋浴后，镜子上蒙了一层水汽。"}]},{"pos":"v.","meaning":"冒蒸汽","definition":"to give off steam","examples":[{"en":"The wet pavement steamed in the sunshine.","zh":"湿路面在阳光下冒着水汽。"},{"en":"A hot bowl of noodles was steaming on the table.","zh":"桌上的一碗热面正冒着蒸汽。"}]},{"pos":"v.","meaning":"蒸煮","definition":"to cook food using steam","examples":[{"en":"Steam the vegetables until they are tender.","zh":"把蔬菜蒸到软嫩。"},{"en":"The restaurant steams its dumplings in bamboo baskets.","zh":"这家餐馆用竹笼蒸饺子。"}]},{"pos":"v.","meaning":"乘蒸汽动力前进","definition":"to travel using steam power","examples":[{"en":"The old train steamed through the valley.","zh":"那列老式蒸汽火车驶过山谷。"},{"en":"The ship steamed slowly out of the harbour.","zh":"轮船以蒸汽动力缓缓驶出港口。"}]}],"steep":[{"pos":"adj.","meaning":"陡峭的","definition":"rising or falling sharply","examples":[{"en":"The path climbs a steep hill.","zh":"小路爬上一座陡山。"},{"en":"The roof has a steep slope.","zh":"屋顶坡度很大。"}]},{"pos":"adj.","meaning":"过高的；急剧的","definition":"very high in price or sharp in change","examples":[{"en":"The entrance fee seemed steep.","zh":"入场费似乎很高。"},{"en":"There was a steep rise in demand.","zh":"需求急剧上升。"}]}],"steer":[{"pos":"v.","meaning":"驾驶；掌舵；操纵方向","definition":"To control the direction of a vehicle.","examples":[{"en":"She steered the boat towards the shore.","zh":"她驾驶船只驶向岸边。"},{"en":"He steered carefully around the fallen branch.","zh":"他小心驾驶，绕过断枝。"}]},{"pos":"v.","meaning":"引导；指导","definition":"To guide an activity or person in a particular direction.","examples":[{"en":"The tutor steered the discussion back to the topic.","zh":"导师把讨论引回主题。"},{"en":"Her advice steered me towards a different career.","zh":"她的建议引导我走向另一种职业。"}]}],"stem":[{"pos":"n.","meaning":"茎；植物主干","definition":"the main supporting part of a plant","examples":[{"en":"The flower has a long green stem.","zh":"这朵花有一根长长的绿色茎。"},{"en":"Cut the stem just below a leaf.","zh":"在叶片下方剪断茎。"}]},{"pos":"n.","meaning":"词干","definition":"the part of a word to which endings can be added","examples":[{"en":"The exercise asks students to identify the verb stem.","zh":"练习要求学生找出动词词干。"},{"en":"Different endings can attach to the same stem.","zh":"不同的词尾可以接在同一个词干后。"}]},{"pos":"v.","meaning":"阻止；抑制；堵住","definition":"to stop or reduce a flow or increase","examples":[{"en":"The measures aim to stem the loss of skilled workers.","zh":"这些措施旨在遏制技术工人的流失。"},{"en":"Workers built a barrier to stem the flow of water.","zh":"工人修建了一道屏障来阻挡水流。"}]},{"pos":"v.","meaning":"起源于；源自（stem from）","definition":"to arise from a particular cause","examples":[{"en":"Most complaints stem from unclear instructions.","zh":"大多数投诉源于说明不清。"},{"en":"Her interest in design stems from childhood visits to museums.","zh":"她对设计的兴趣源于童年时参观博物馆的经历。"}]}],"stereo":[{"pos":"adj.","meaning":"立体声的","definition":"using separate sound channels","examples":[{"en":"The recording has excellent stereo sound.","zh":"录音有出色的立体声效果。"},{"en":"She connected two stereo speakers.","zh":"她连接了两个立体声扬声器。"}]},{"pos":"n.","meaning":"立体声；立体声音响设备","definition":"sound with separate channels or equipment producing it","examples":[{"en":"The programme was broadcast in stereo.","zh":"节目以立体声播出。"},{"en":"He turned down the stereo.","zh":"他调低了音响音量。"}]}],"stereoscopic":[{"pos":"adj.","meaning":"立体视觉的；有立体效果的","definition":"Producing or involving a three-dimensional view from two slightly different images.","examples":[{"en":"The viewers examined stereoscopic photographs through special glasses.","zh":"观众通过特殊眼镜观看立体照片。"},{"en":"The device creates a stereoscopic image of the landscape.","zh":"这个装置生成景观的立体图像。"}]}],"stick":[{"pos":"v.","meaning":"刺入；插入","definition":"to push something pointed into another thing","examples":[{"en":"Stick the label holder into the soil.","zh":"把标签架插进土壤里。"},{"en":"She stuck a pin through the fabric.","zh":"她把一根别针穿过布料。"}]},{"pos":"v.","meaning":"黏贴；黏住","definition":"to attach using a sticky substance","examples":[{"en":"Stick the photograph onto the first page.","zh":"把照片贴在第一页上。"},{"en":"The wet paper stuck to the glass.","zh":"湿纸黏在了玻璃上。"}]},{"pos":"v.","meaning":"卡住；陷住","definition":"to become unable to move freely","examples":[{"en":"The drawer sticks when the weather is damp.","zh":"天气潮湿时，抽屉会卡住。"},{"en":"Our boots stuck in the thick mud.","zh":"我们的靴子陷在了厚厚的泥里。"}]},{"pos":"n.","meaning":"棍；枝条","definition":"a long thin piece of wood","examples":[{"en":"He used a stick to draw a line in the sand.","zh":"他用一根棍子在沙地上画线。"},{"en":"The dog carried a small stick in its mouth.","zh":"狗嘴里叼着一根小树枝。"}]}],"sticky":[{"pos":"adj.","meaning":"黏的；黏性的","definition":"able to stick to surfaces","examples":[{"en":"The glue left a sticky patch.","zh":"胶留下了一块黏黏的痕迹。"},{"en":"Her fingers were sticky with honey.","zh":"她的手指沾满蜂蜜，黏糊糊的。"}]},{"pos":"adj.","meaning":"湿热的","definition":"uncomfortably hot and humid","examples":[{"en":"It was a sticky summer evening.","zh":"那是一个湿热的夏夜。"},{"en":"The room felt sticky despite the fan.","zh":"尽管开着风扇，房间仍然湿热。"}]}],"stiff":[{"pos":"adj.","meaning":"坚硬的；僵硬的；不易弯曲的","definition":"Rigid or difficult to bend or move.","examples":[{"en":"The new boots are still stiff.","zh":"新靴子还是很硬。"},{"en":"My shoulders felt stiff after the long drive.","zh":"长途驾驶后，我的肩膀很僵硬。"}]},{"pos":"adv.","meaning":"极其；非常","definition":"To an extreme degree, used after certain adjectives.","examples":[{"en":"She was scared stiff by the sudden noise.","zh":"突如其来的声音把她吓坏了。"},{"en":"We were bored stiff during the endless speech.","zh":"冗长演讲让我们无聊透顶。"}]}],"stimulate":[{"pos":"v.","meaning":"刺激；促进活动","definition":"to cause an organ or process to become more active","examples":[{"en":"Bright light can stimulate growth in these plants.","zh":"明亮的光线可以促进这些植物生长。"},{"en":"The exercise stimulates blood flow to the muscles.","zh":"这项运动促进血液流向肌肉。"}]},{"pos":"v.","meaning":"激发；激励","definition":"to encourage interest, thought, or action","examples":[{"en":"The question stimulated a lively discussion.","zh":"这个问题引发了热烈讨论。"},{"en":"The exhibition aims to stimulate children's curiosity.","zh":"这个展览旨在激发孩子的好奇心。"}]}],"stimulus":[{"pos":"n.","meaning":"刺激物；促进因素","definition":"something causing a response or encouraging activity","examples":[{"en":"Light acts as a stimulus for the response.","zh":"光是引发反应的刺激物。"},{"en":"The grant provided a stimulus to research.","zh":"资助推动了研究。"}]}],"stint":[{"pos":"n.","meaning":"规定的工作量；一段工作时间","definition":"An allotted amount or period of work.","examples":[{"en":"She completed a six-month stint at the hospital.","zh":"她在医院完成了为期六个月的工作。"},{"en":"After his morning stint in the garden, he rested.","zh":"完成早晨的园艺工作后，他休息了。"}]},{"pos":"n.","meaning":"限额；限制","definition":"A limit on effort, spending, or supply.","examples":[{"en":"The volunteers gave their time without stint.","zh":"志愿者毫不吝惜自己的时间。"},{"en":"Their hosts provided food without stint.","zh":"主人毫无限制地供应食物。"}]}],"stipulate":[{"pos":"v.","meaning":"规定；明确要求","definition":"to state a condition that must be met","examples":[{"en":"The contract stipulates a payment date.","zh":"合同规定了付款日期。"},{"en":"The rules stipulate that all visitors must sign in.","zh":"规则明确要求所有访客登记。"}]}],"stir":[{"pos":"v.","meaning":"搅动；搅拌","definition":"to move a liquid around","examples":[{"en":"Stir the soup gently.","zh":"轻轻搅拌汤。"},{"en":"She stirred sugar into the tea.","zh":"她把糖搅进茶里。"}]},{"pos":"v.","meaning":"轻微移动；摇动","definition":"to move slightly","examples":[{"en":"The leaves barely stirred.","zh":"叶子几乎没有动。"},{"en":"The sleeping child stirred.","zh":"睡着的孩子动了一下。"}]},{"pos":"v.","meaning":"激起；打动","definition":"to cause a feeling or reaction","examples":[{"en":"The speech stirred their enthusiasm.","zh":"演讲激起了他们的热情。"},{"en":"The music stirred old memories.","zh":"音乐唤起了旧日回忆。"}]},{"pos":"n.","meaning":"搅拌；轻微移动","definition":"a mixing action or small movement","examples":[{"en":"Give the sauce a stir.","zh":"搅一下酱汁。"},{"en":"A stir in the bushes caught her attention.","zh":"灌木丛中的轻微动静吸引了她。"}]},{"pos":"n.","meaning":"轰动；激动","definition":"excitement or public reaction","examples":[{"en":"The discovery caused a stir.","zh":"发现引起轰动。"},{"en":"Her arrival created a stir in the room.","zh":"她的到来在房间里引起一阵骚动。"}]}],"stitch":[{"pos":"v.","meaning":"缝；缝合","definition":"To join material with thread or close a wound with stitches.","examples":[{"en":"She stitched a patch onto the jacket.","zh":"她给夹克缝上一块补丁。"},{"en":"The doctor stitched the cut.","zh":"医生缝合了伤口。"}]},{"pos":"n.","meaning":"一针；针脚","definition":"A single loop of thread made in sewing.","examples":[{"en":"The stitches are small and even.","zh":"针脚细小而均匀。"},{"en":"One loose stitch made the seam unravel.","zh":"一个松针脚让接缝散开了。"}]}],"stock":[{"pos":"n.","meaning":"存货；储备","definition":"goods or supplies kept for use or sale","examples":[{"en":"The shop keeps a large stock of spare parts.","zh":"这家店储备了大量零部件。"},{"en":"Our emergency stock of water lasted three days.","zh":"我们的应急储水维持了三天。"}]},{"pos":"n.","meaning":"股票；股份","definition":"ownership shares in a company","examples":[{"en":"She inherited a small amount of company stock.","zh":"她继承了少量公司股票。"},{"en":"The report compares several technology stocks.","zh":"报告比较了几只科技股。"}]},{"pos":"n.","meaning":"家畜；牲畜","definition":"farm animals kept for breeding or production","examples":[{"en":"The farmer moved the stock into a sheltered field.","zh":"农民把牲畜赶进了一块避风的田地。"},{"en":"Healthy breeding stock is essential to the farm.","zh":"健康的种畜对农场至关重要。"}]},{"pos":"v.","meaning":"储备；备有","definition":"to keep a supply of goods","examples":[{"en":"The store stocks several types of batteries.","zh":"这家商店备有几种电池。"},{"en":"We stocked the cupboard with basic ingredients.","zh":"我们在橱柜里备好了基本食材。"}]},{"pos":"adj.","meaning":"常备的；惯用的","definition":"regularly kept or routinely used","examples":[{"en":"The manager gave his stock answer to the question.","zh":"经理对这个问题给出了惯常的回答。"},{"en":"These are stock items that can be delivered immediately.","zh":"这些是可以立即交付的常备货品。"}]}],"stockpile":[{"pos":"n.","meaning":"储备物资","definition":"a large reserve of goods","examples":[{"en":"The town maintained a stockpile of fuel.","zh":"小镇储备了一批燃料。"},{"en":"The emergency stockpile included blankets.","zh":"应急储备物资包括毯子。"}]},{"pos":"v.","meaning":"大量储备；囤积","definition":"to collect and store large quantities","examples":[{"en":"They stockpiled food before winter.","zh":"他们在冬前储备了大量食品。"},{"en":"The warehouse stockpiles spare parts.","zh":"仓库大量储备零件。"}]}],"storey":[{"pos":"n.","meaning":"楼层","definition":"A level of a building.","examples":[{"en":"The house has three storeys.","zh":"这栋房子有三层。"},{"en":"Smoke rose from an upper storey.","zh":"烟从较高楼层升起。"}]}],"storyline":[{"pos":"n.","meaning":"故事情节","definition":"the sequence of events in a story","examples":[{"en":"The film has a simple but engaging storyline.","zh":"这部电影的情节简单却引人入胜。"},{"en":"Several minor characters disappear from the storyline.","zh":"几个次要人物从故事情节中消失了。"}]}],"stout":[{"pos":"adj.","meaning":"粗壮的；肥壮的","definition":"thick-bodied or rather fat","examples":[{"en":"A stout man opened the door.","zh":"一个身材肥壮的男人开了门。"},{"en":"The pony was short and stout.","zh":"小马矮而壮实。"}]},{"pos":"adj.","meaning":"结实的；坚固的","definition":"strong and firmly made","examples":[{"en":"Wear stout boots on the trail.","zh":"走山路要穿结实的靴子。"},{"en":"A stout rope held the load.","zh":"结实的绳子固定住了货物。"}]},{"pos":"adj.","meaning":"坚定的；顽强的","definition":"brave and determined","examples":[{"en":"They mounted a stout defence.","zh":"他们进行了顽强防守。"},{"en":"She remained a stout supporter of the project.","zh":"她一直坚定支持这个项目。"}]}],"stove":[{"pos":"n.","meaning":"炉；火炉；炉灶","definition":"A device for cooking or heating.","examples":[{"en":"A pot of soup simmered on the stove.","zh":"一锅汤在炉子上炖着。"},{"en":"The wood stove warmed the cabin.","zh":"烧木柴的炉子使小屋暖和起来。"}]}],"strain":[{"pos":"v.","meaning":"拉紧；绷紧","definition":"to stretch something under force","examples":[{"en":"The heavy load strained the rope.","zh":"沉重的负荷把绳子绷紧了。"},{"en":"The dog strained against its lead.","zh":"狗使劲拉扯牵引绳。"}]},{"pos":"v.","meaning":"拉伤；使过劳","definition":"to injure or overwork a muscle or ability","examples":[{"en":"He strained his shoulder while lifting a box.","zh":"他搬箱子时拉伤了肩膀。"},{"en":"Reading tiny print can strain your eyes.","zh":"阅读细小的文字会使眼睛疲劳。"}]},{"pos":"n.","meaning":"拉力；张力","definition":"pressure caused by a pulling force","examples":[{"en":"The cable broke under the strain.","zh":"电缆在拉力作用下断裂了。"},{"en":"The extra weight placed strain on the supports.","zh":"额外重量给支架增加了受力。"}]},{"pos":"n.","meaning":"拉伤","definition":"an injury caused by overstretching a muscle","examples":[{"en":"She missed the match because of a muscle strain.","zh":"她因肌肉拉伤错过了比赛。"},{"en":"The report described a minor strain in his calf.","zh":"报告描述了他小腿的轻微拉伤。"}]},{"pos":"n.","meaning":"压力；紧张","definition":"mental pressure or excessive demand","examples":[{"en":"The long journey put a strain on the family.","zh":"漫长的旅途给这家人带来了压力。"},{"en":"There were signs of strain in her voice.","zh":"她的声音显露出紧张。"}]}],"strand":[{"pos":"n.","meaning":"股；缕；细线","definition":"a single thin length of something","examples":[{"en":"A strand of hair fell across her face.","zh":"一缕头发垂在她脸上。"},{"en":"The rope consists of twisted strands.","zh":"绳子由多股绞合而成。"}]},{"pos":"n.","meaning":"部分；方面；线索","definition":"one component of a larger whole","examples":[{"en":"The course combines several strands of research.","zh":"课程结合了几条研究脉络。"},{"en":"Education is one strand of the wider policy.","zh":"教育是更广泛政策的一个方面。"}]}],"strap":[{"pos":"n.","meaning":"带子；皮带；绑带","definition":"A narrow strip used to fasten, carry, or hold something.","examples":[{"en":"The bag has an adjustable strap.","zh":"这个包有一条可调节背带。"},{"en":"Tighten the helmet strap under your chin.","zh":"把头盔带在下巴下面收紧。"}]},{"pos":"v.","meaning":"用带捆紧；绑住；用绷带包扎","definition":"To fasten or support with a strap or bandage.","examples":[{"en":"They strapped the boxes to the roof rack.","zh":"他们把箱子绑在车顶行李架上。"},{"en":"The nurse strapped his injured ankle.","zh":"护士用绷带包扎了他受伤的脚踝。"}]}],"strategist":[{"pos":"n.","meaning":"战略家；策略制定者","definition":"a person skilled at planning long-term actions","examples":[{"en":"The team hired a strategist to plan its expansion.","zh":"团队聘请了一位策略师来规划扩张。"},{"en":"A good strategist considers several possible outcomes.","zh":"优秀的战略家会考虑多种可能结果。"}]}],"strategy":[{"pos":"n.","meaning":"战略；策略","definition":"a planned approach to achieving a goal","examples":[{"en":"The team developed a clear strategy.","zh":"团队制定了明确策略。"},{"en":"Their strategy focused on reducing waste.","zh":"他们的策略集中于减少浪费。"}]}],"straw":[{"pos":"n.","meaning":"稻草；麦秆；秸秆","definition":"Dried stems of grain plants.","examples":[{"en":"The animals slept on clean straw.","zh":"动物睡在干净稻草上。"},{"en":"Farmers spread straw over the soil.","zh":"农民把秸秆铺在土壤上。"}]},{"pos":"n.","meaning":"吸管","definition":"A thin tube used for drinking.","examples":[{"en":"She drank the juice through a straw.","zh":"她用吸管喝果汁。"},{"en":"The café replaced plastic straws with paper ones.","zh":"咖啡馆用纸吸管代替了塑料吸管。"}]}],"stream":[{"pos":"n.","meaning":"溪流","definition":"a small flowing body of water","examples":[{"en":"A clear stream runs behind the village.","zh":"一条清澈的小溪流过村后。"},{"en":"We crossed the stream on stepping stones.","zh":"我们踩着踏脚石过了小溪。"}]},{"pos":"n.","meaning":"一股；连续不断的流","definition":"a continuous movement of people, things, or events","examples":[{"en":"A stream of visitors entered the museum.","zh":"参观者源源不断地走进博物馆。"},{"en":"The office received a steady stream of calls.","zh":"办公室不断接到电话。"}]},{"pos":"v.","meaning":"流动；流出","definition":"to move continuously in a steady flow","examples":[{"en":"Sunlight streamed through the high windows.","zh":"阳光从高处的窗户照射进来。"},{"en":"People streamed out of the station.","zh":"人们从车站涌了出来。"}]}],"strengthen":[{"pos":"v.","meaning":"加强；巩固","definition":"to become or make stronger","examples":[{"en":"The changes strengthened the structure.","zh":"改动加固了结构。"},{"en":"The visit strengthened their partnership.","zh":"访问巩固了合作关系。"}]}],"stress":[{"pos":"n.","meaning":"压力；紧张","definition":"Mental strain or physical force on something.","examples":[{"en":"The deadline caused considerable stress.","zh":"截止期限带来了很大压力。"},{"en":"The bridge was tested under heavy stress.","zh":"桥梁接受了重压测试。"}]},{"pos":"n.","meaning":"重音","definition":"Emphasis placed on a syllable when speaking.","examples":[{"en":"The stress falls on the first syllable.","zh":"重音落在第一个音节上。"},{"en":"Changing the stress can change the meaning.","zh":"改变重音可能改变意思。"}]},{"pos":"n.","meaning":"强调；重点","definition":"Special importance placed on something.","examples":[{"en":"The course places stress on practical skills.","zh":"课程注重实际技能。"},{"en":"The report puts particular stress on safety.","zh":"报告特别强调安全。"}]},{"pos":"v.","meaning":"强调；着重指出","definition":"To give special importance to something.","examples":[{"en":"The teacher stressed the need for clear evidence.","zh":"老师强调需要明确证据。"},{"en":"She stressed that participation was voluntary.","zh":"她强调参加是自愿的。"}]},{"pos":"v.","meaning":"重读","definition":"To pronounce a syllable or word with extra force.","examples":[{"en":"Stress the second syllable in this example.","zh":"在这个例子中重读第二个音节。"},{"en":"He stressed the final word to show contrast.","zh":"他重读最后一个词以表示对比。"}]}],"stretch":[{"pos":"v.","meaning":"伸展；拉长","definition":"to extend the body or lengthen something","examples":[{"en":"She stretched her arms above her head.","zh":"她把双臂伸到头顶上方。"},{"en":"The fabric stretches without tearing.","zh":"这种布料能够拉伸而不撕裂。"}]},{"pos":"v.","meaning":"延伸；延续","definition":"to reach across a distance or period","examples":[{"en":"The beach stretches for several kilometres.","zh":"海滩延绵数公里。"},{"en":"Their friendship stretches back to childhood.","zh":"他们的友谊可以追溯到童年。"}]},{"pos":"v.","meaning":"使竭尽全力；使紧张","definition":"to demand almost all available ability or resources","examples":[{"en":"The repairs stretched our budget to its limit.","zh":"维修费用使我们的预算捉襟见肘。"},{"en":"The advanced course will stretch even experienced students.","zh":"即使有经验的学生也需要全力应对这门高级课程。"}]},{"pos":"n.","meaning":"一段距离；一段时间","definition":"a continuous length of place or time","examples":[{"en":"This stretch of road is closed for repairs.","zh":"这段道路因维修而关闭。"},{"en":"He worked for a three-hour stretch without a break.","zh":"他一连工作了三个小时，没有休息。"}]},{"pos":"n.","meaning":"伸展；拉伸","definition":"an action or degree of extending something","examples":[{"en":"A gentle stretch helped her relax after the drive.","zh":"轻柔的伸展帮助她在开车后放松下来。"},{"en":"This material has enough stretch for sports clothing.","zh":"这种材料的弹性足以用于运动服。"}]}],"strike":[{"pos":"v.","meaning":"击打；撞击","definition":"to hit forcefully","examples":[{"en":"The ball struck the window.","zh":"球击中了窗户。"},{"en":"Lightning struck a tree.","zh":"闪电击中一棵树。"}]},{"pos":"v.","meaning":"侵袭；使遭受打击","definition":"to affect suddenly with harm","examples":[{"en":"Disaster struck without warning.","zh":"灾难毫无预兆地发生。"},{"en":"The illness struck several members of the team.","zh":"疾病侵袭了几位队员。"}]},{"pos":"n.","meaning":"罢工","definition":"a refusal to work as a form of protest","examples":[{"en":"The workers called a strike.","zh":"工人宣布罢工。"},{"en":"The strike ended after negotiations.","zh":"罢工在谈判后结束。"}]}],"striking":[{"pos":"adj.","meaning":"显著的；引人注目的","definition":"Very noticeable or impressive.","examples":[{"en":"The photographs reveal a striking difference.","zh":"照片显示出显著差异。"},{"en":"Her striking red coat stood out in the crowd.","zh":"她醒目的红外套在人群中格外显眼。"}]}],"string":[{"pos":"n.","meaning":"细绳；线","definition":"a thin cord used for tying things","examples":[{"en":"Tie the parcel with a piece of string.","zh":"用一根细绳把包裹绑好。"},{"en":"A ball of string rolled off the desk.","zh":"一团绳子滚下了书桌。"}]},{"pos":"n.","meaning":"琴弦","definition":"a stretched wire or cord that produces musical sound","examples":[{"en":"One guitar string snapped during rehearsal.","zh":"排练时，一根吉他弦断了。"},{"en":"She adjusted the strings before playing.","zh":"她演奏前调好了琴弦。"}]},{"pos":"n.","meaning":"一串；一系列","definition":"a connected series of things","examples":[{"en":"A string of lights decorated the doorway.","zh":"一串灯装饰着门口。"},{"en":"The firm faced a string of unexpected delays.","zh":"这家公司接连遭遇意外延误。"}]},{"pos":"v.","meaning":"用线串起；悬挂","definition":"to thread things on a cord or hang them in a line","examples":[{"en":"The children strung beads to make necklaces.","zh":"孩子们把珠子串成项链。"},{"en":"They strung lanterns across the courtyard.","zh":"他们在庭院上方挂起一排灯笼。"}]}],"stringent":[{"pos":"adj.","meaning":"严格的；苛刻的","definition":"very strict and demanding","examples":[{"en":"The laboratory follows stringent safety rules.","zh":"实验室遵循严格安全规则。"},{"en":"Applicants face stringent requirements.","zh":"申请者面临严格要求。"}]},{"pos":"adj.","meaning":"资金紧张的；紧缩的","definition":"involving a severe shortage of money or credit","examples":[{"en":"The project faced stringent financial conditions.","zh":"项目面临紧张的财务状况。"},{"en":"Stringent credit conditions limited expansion.","zh":"信贷紧缩限制了扩张。"}]},{"pos":"adj.","meaning":"迫切的；强制性的（正式）","definition":"urgently demanding action","examples":[{"en":"They faced a stringent need for immediate repairs.","zh":"他们迫切需要立即维修。"},{"en":"The circumstances imposed stringent demands on the team.","zh":"情况对团队提出了迫切而严苛的要求。"}]}],"strip":[{"pos":"v.","meaning":"剥去；除去；使空无一物","definition":"To remove a covering or all the contents of something.","examples":[{"en":"They stripped the old paint from the door.","zh":"他们剥去了门上的旧漆。"},{"en":"The room had been stripped of furniture.","zh":"房间里的家具已被搬空。"}]},{"pos":"v.","meaning":"剥夺；夺去","definition":"To take away a right, title, or possession.","examples":[{"en":"The official was stripped of his title.","zh":"官员被剥夺了头衔。"},{"en":"The new rule stripped the committee of its authority.","zh":"新规定剥夺了委员会的权力。"}]},{"pos":"v.","meaning":"拆卸；拆开","definition":"To take a machine apart.","examples":[{"en":"The mechanic stripped the engine for inspection.","zh":"机械师拆开发动机进行检查。"},{"en":"The instrument was stripped down and cleaned.","zh":"仪器被拆开并清洗了。"}]},{"pos":"n.","meaning":"条；带状物；狭长地带","definition":"A long narrow piece or area.","examples":[{"en":"Cut the paper into thin strips.","zh":"把纸剪成细条。"},{"en":"A narrow strip of land separates the lakes.","zh":"一条狭长陆地把两片湖分开。"}]}],"stripe":[{"pos":"n.","meaning":"条纹","definition":"a long narrow band of a different colour","examples":[{"en":"The shirt has a blue stripe across the chest.","zh":"这件衬衫胸前有一道蓝色条纹。"},{"en":"The zebra's stripes make it easy to recognise.","zh":"斑马的条纹使它很容易辨认。"}]}],"stroke":[{"pos":"n.","meaning":"击打；一下；击球","definition":"a single hit or movement of a tool","examples":[{"en":"One stroke of the axe split the wood.","zh":"斧头一下劈开了木头。"},{"en":"Her final stroke won the tennis point.","zh":"她最后一击赢得了网球这一分。"}]},{"pos":"n.","meaning":"中风；脑卒中","definition":"a sudden condition caused by disrupted blood flow in the brain","examples":[{"en":"The report studied recovery after stroke.","zh":"报告研究了中风后的恢复。"},{"en":"His grandfather had a stroke last year.","zh":"他祖父去年中风了。"}]},{"pos":"n.","meaning":"笔画；笔触","definition":"one movement of a pen or brush","examples":[{"en":"Write the character with five strokes.","zh":"这个字写五笔。"},{"en":"The artist used broad brush strokes.","zh":"艺术家用了宽阔笔触。"}]},{"pos":"n.","meaning":"划水动作；泳姿；划桨","definition":"a repeated movement in swimming or rowing","examples":[{"en":"She improved her swimming stroke.","zh":"她改进了游泳动作。"},{"en":"The rowers kept their strokes even.","zh":"划船手保持划桨动作均匀。"}]},{"pos":"n.","meaning":"钟声的一响","definition":"one sound made by a striking clock","examples":[{"en":"The final stroke of midnight faded.","zh":"午夜最后一下钟声渐渐消失。"},{"en":"We left on the stroke of six.","zh":"我们在六点钟响时离开。"}]},{"pos":"n.","meaning":"轻抚","definition":"a gentle movement of the hand over something","examples":[{"en":"The cat welcomed a gentle stroke.","zh":"猫很喜欢轻柔的抚摸。"},{"en":"She calmed the horse with slow strokes.","zh":"她慢慢抚摸使马安静。"}]},{"pos":"v.","meaning":"抚摸","definition":"to move a hand gently over a surface","examples":[{"en":"He stroked the dog's head.","zh":"他抚摸狗的头。"},{"en":"She stroked the soft fabric.","zh":"她轻抚柔软的布料。"}]}],"structure":[{"pos":"n.","meaning":"结构；构造","definition":"The way parts are arranged together.","examples":[{"en":"The report examines the structure of the economy.","zh":"报告考察经济结构。"},{"en":"The molecule has a complex structure.","zh":"这种分子结构复杂。"}]},{"pos":"n.","meaning":"建筑物；构筑物","definition":"Something built from connected parts.","examples":[{"en":"The bridge is an impressive steel structure.","zh":"这座桥是一座宏伟的钢结构建筑。"},{"en":"The old structure was unsafe.","zh":"这座旧建筑不安全。"}]},{"pos":"v.","meaning":"组织；安排；使有系统","definition":"To arrange something according to a clear plan.","examples":[{"en":"Structure the essay around three main points.","zh":"围绕三个要点组织文章。"},{"en":"The day was carefully structured to include breaks.","zh":"这一天经过精心安排，包含休息时间。"}]}],"studio":[{"pos":"n.","meaning":"工作室；摄影室；练习室","definition":"a room equipped for artistic, photographic, or recording work","examples":[{"en":"The artist rents a studio near the river.","zh":"这位艺术家在河边租了一间工作室。"},{"en":"We recorded the interview in a small studio.","zh":"我们在一间小录音室里录制了采访。"}]}],"studious":[{"pos":"adj.","meaning":"勤奋好学的","definition":"spending much time studying","examples":[{"en":"She was a quiet, studious child.","zh":"她是个安静好学的孩子。"},{"en":"The library attracted studious pupils.","zh":"图书馆吸引了勤奋的学生。"}]},{"pos":"adj.","meaning":"认真谨慎的；刻意用心的","definition":"done with careful and deliberate attention","examples":[{"en":"He maintained a studious silence.","zh":"他刻意保持沉默。"},{"en":"She treated the evidence with studious care.","zh":"她认真谨慎地对待证据。"}]}],"stuff":[{"pos":"n.","meaning":"东西；材料；原料","definition":"Material, things, or possessions referred to generally.","examples":[{"en":"What is this soft stuff made of?","zh":"这种柔软材料是什么做的？"},{"en":"Put your camping stuff in the car.","zh":"把露营用品放进车里。"}]},{"pos":"v.","meaning":"塞入；填满；填充","definition":"To fill something tightly with material.","examples":[{"en":"She stuffed the clothes into a suitcase.","zh":"她把衣服塞进行李箱。"},{"en":"The cushions are stuffed with feathers.","zh":"靠垫填充着羽毛。"}]},{"pos":"v.","meaning":"使吃饱；使吃得过多","definition":"To feed heavily or eat too much.","examples":[{"en":"The children stuffed themselves with cake.","zh":"孩子们吃蛋糕吃得饱饱的。"},{"en":"Our hosts kept stuffing us with homemade food.","zh":"主人不停地让我们吃自制食物，吃得很饱。"}]}],"stuffy":[{"pos":"adj.","meaning":"闷热的；不通风的","definition":"having too little fresh air","examples":[{"en":"The room felt stuffy with all the windows closed.","zh":"所有窗户都关着，房间显得很闷。"},{"en":"We went outside to escape the stuffy office.","zh":"我们走到外面，避开闷热的办公室。"}]},{"pos":"adj.","meaning":"古板的；拘谨的；乏味的","definition":"too formal or unwilling to accept new ideas","examples":[{"en":"The new director wants to change the institution's stuffy image.","zh":"新主任想改变这家机构古板的形象。"},{"en":"He found the dinner too stuffy to enjoy.","zh":"他觉得这顿晚餐气氛过于拘谨，难以尽兴。"}]}],"stylish":[{"pos":"adj.","meaning":"时髦的；漂亮雅致的","definition":"fashionable and attractive","examples":[{"en":"The apartment has a stylish interior.","zh":"公寓内部时髦雅致。"},{"en":"She wore a stylish coat.","zh":"她穿着漂亮时髦的大衣。"}]}],"subject":[{"pos":"n.","meaning":"题目；主题；话题","definition":"The matter being discussed or studied.","examples":[{"en":"We changed the subject when she arrived.","zh":"她到来时，我们换了话题。"},{"en":"The subject of the lecture is urban wildlife.","zh":"讲座的主题是城市野生动物。"}],"ipa":"/ˈsʌbdʒekt/"},{"pos":"n.","meaning":"学科；课程","definition":"An area of study.","examples":[{"en":"History was her favourite subject.","zh":"历史是她最喜欢的学科。"},{"en":"Students choose two optional subjects.","zh":"学生选择两门选修课。"}],"ipa":"/ˈsʌbdʒekt/"},{"pos":"n.","meaning":"主语","definition":"The grammatical part of a sentence that usually performs the action.","examples":[{"en":"The subject of this sentence is plural.","zh":"这句话的主语是复数。"},{"en":"Underline the subject in each example.","zh":"给每个例子中的主语画下划线。"}],"ipa":"/ˈsʌbdʒekt/"},{"pos":"adj.","meaning":"受……支配的；取决于……的","definition":"Dependent on a condition or under a particular authority.","examples":[{"en":"The offer is subject to approval.","zh":"这项报价须经批准。"},{"en":"All visitors are subject to the same rules.","zh":"所有访客都受同样规则约束。"}],"ipa":"/ˈsʌbdʒekt/"},{"pos":"adj.","meaning":"易遭受……的；容易……的","definition":"Likely to experience something unpleasant.","examples":[{"en":"The coast is subject to sudden storms.","zh":"这段海岸容易遭遇突发风暴。"},{"en":"The old system was subject to frequent failures.","zh":"旧系统容易频繁出故障。"}],"ipa":"/ˈsʌbdʒekt/"}],"subjective":[{"pos":"adj.","meaning":"主观的","definition":"based on personal feelings or viewpoints","examples":[{"en":"Beauty is often a subjective judgement.","zh":"美往往是一种主观判断。"},{"en":"The report separates measured facts from subjective impressions.","zh":"这份报告把测得的事实与主观印象区分开来。"}]}],"subliminal":[{"pos":"adj.","meaning":"阈下的；未被意识觉察的","definition":"below the level of conscious awareness","examples":[{"en":"The experiment tested subliminal visual cues.","zh":"实验测试阈下视觉线索。"},{"en":"The film uses subtle, almost subliminal sound effects.","zh":"影片使用微妙得近乎不易察觉的音效。"}]}],"submarine":[{"pos":"n.","meaning":"潜水艇","definition":"A vessel designed to travel underwater.","examples":[{"en":"The submarine disappeared beneath the surface.","zh":"潜水艇消失在水面下。"},{"en":"The museum offers tours inside a retired submarine.","zh":"博物馆提供退役潜艇内部参观。"}]},{"pos":"adj.","meaning":"海底的；水下的","definition":"Located or operating beneath the sea.","examples":[{"en":"A submarine cable connects the islands.","zh":"一条海底电缆连接着这些岛屿。"},{"en":"Scientists mapped a submarine volcano.","zh":"科学家绘制了一座海底火山的地图。"}]}],"submerge":[{"pos":"v.","meaning":"浸没；潜入水中","definition":"to put or go below the surface of water","examples":[{"en":"The flood submerged the lower floor.","zh":"洪水淹没了底层。"},{"en":"The submarine submerged before reaching the bay.","zh":"潜艇在到达海湾前潜入了水中。"}]}],"submit":[{"pos":"v.","meaning":"提交；呈递","definition":"to formally send something for consideration","examples":[{"en":"Submit your application by Friday.","zh":"星期五前提交申请。"},{"en":"She submitted the report online.","zh":"她在网上提交了报告。"}]},{"pos":"v.","meaning":"服从；屈从","definition":"to accept another's authority","examples":[{"en":"They refused to submit to pressure.","zh":"他们拒绝屈从压力。"},{"en":"The contestants submitted to the judge's decision.","zh":"选手服从裁判的决定。"}]}],"subordinate":[{"pos":"n.","meaning":"下属；部属","definition":"A person lower in rank or authority.","examples":[{"en":"The manager listened to her subordinates.","zh":"经理听取了下属的意见。"},{"en":"He delegated routine work to a subordinate.","zh":"他把日常工作交给一名下属。"}],"ipa":"/səˈbɔːdɪnət/"},{"pos":"adj.","meaning":"下级的；次要的；从属的","definition":"Lower in importance or rank.","examples":[{"en":"The office has a subordinate role in the organisation.","zh":"该办公室在组织中处于从属地位。"},{"en":"A subordinate clause cannot always stand alone.","zh":"从句通常不能独立成句。"}],"ipa":"/səˈbɔːdɪnət/"},{"pos":"v.","meaning":"使居次要地位；使服从","definition":"To treat something as less important or place it under another.","examples":[{"en":"They subordinated personal interests to the common goal.","zh":"他们让个人利益服从共同目标。"},{"en":"The committee was subordinated to the central board.","zh":"委员会隶属于中央理事会。"}],"ipa":"/səˈbɔːdɪneɪt/"}],"subscribe":[{"pos":"v.","meaning":"订阅；订购","definition":"to arrange to receive something regularly","examples":[{"en":"I subscribe to a monthly science magazine.","zh":"我订阅了一本科学月刊。"},{"en":"Students can subscribe to the online journal at a reduced price.","zh":"学生可以优惠价格订阅这份在线期刊。"}]},{"pos":"v.","meaning":"认购；申请加入","definition":"to agree to obtain shares or join a service","examples":[{"en":"Local residents were invited to subscribe for shares in the project.","zh":"当地居民获邀认购这个项目的股份。"},{"en":"New users can subscribe to the service through its website.","zh":"新用户可以通过网站申请使用这项服务。"}]},{"pos":"v.","meaning":"赞同；支持（subscribe to）","definition":"to agree with a belief or idea","examples":[{"en":"I do not subscribe to the view that speed always matters most.","zh":"我不赞同速度始终最重要的看法。"},{"en":"Both authors subscribe to the same theory of learning.","zh":"两位作者都支持同一种学习理论。"}]}],"subscription":[{"pos":"n.","meaning":"订阅；订阅费；会员费","definition":"an arrangement or payment for regular access","examples":[{"en":"My magazine subscription expires soon.","zh":"我的杂志订阅即将到期。"},{"en":"The annual subscription includes online access.","zh":"年费包含在线访问权限。"}]},{"pos":"n.","meaning":"捐款；认捐","definition":"money contributed or promised to a cause","examples":[{"en":"The hall was built by public subscription.","zh":"大厅由公众捐款建成。"},{"en":"The committee collected subscriptions for the memorial.","zh":"委员会为纪念碑募集捐款。"}]},{"pos":"n.","meaning":"签字；签署（正式或旧用）","definition":"the act of signing a document","examples":[{"en":"The document bears the witness's subscription.","zh":"文件上有证人的签名。"},{"en":"The charter required subscription by all members.","zh":"章程要求所有成员签署。"}]}],"subsequent":[{"pos":"adj.","meaning":"随后的；后来的","definition":"Happening after something else.","examples":[{"en":"Subsequent tests confirmed the result.","zh":"后续测试证实了结果。"},{"en":"The building changed greatly in subsequent years.","zh":"这栋建筑在随后几年中变化很大。"}]}],"subsidiary":[{"pos":"n.","meaning":"子公司；附属机构","definition":"an organisation controlled by a larger one","examples":[{"en":"The company opened a subsidiary in another country.","zh":"公司在另一个国家设立了子公司。"},{"en":"Each subsidiary prepares its own annual report.","zh":"每家子公司都编制自己的年度报告。"}]},{"pos":"adj.","meaning":"次要的；辅助的","definition":"less important than or supporting a main part","examples":[{"en":"The report places these details in a subsidiary section.","zh":"报告把这些细节放在一个附属章节中。"},{"en":"Transport costs were a subsidiary concern during the discussion.","zh":"运输成本在讨论中是次要问题。"}]}],"subsidise":[{"pos":"v.","meaning":"资助；补贴","definition":"to provide money to reduce costs","examples":[{"en":"The council subsidises bus services.","zh":"议会补贴公交服务。"},{"en":"The grant subsidised the students' travel.","zh":"资助补贴了学生的旅费。"}]}],"subsidy":[{"pos":"n.","meaning":"补贴","definition":"money provided to support an activity","examples":[{"en":"The subsidy helps low-income families pay for childcare.","zh":"这项补贴帮助低收入家庭支付托育费用。"},{"en":"Farmers can apply for a subsidy to improve water efficiency.","zh":"农民可以申请补贴提高用水效率。"},{"en":"Without a subsidy, the rural bus service may close.","zh":"没有补贴，这条农村公交线路可能停运。"}]}],"subsoil":[{"pos":"n.","meaning":"底土；下层土","definition":"the layer of earth below the surface soil","examples":[{"en":"The roots reached into the clay subsoil.","zh":"树根伸入了黏土底层。"},{"en":"Builders tested the subsoil before laying the foundations.","zh":"施工人员铺设地基前检查了下层土。"}]}],"substance":[{"pos":"n.","meaning":"物质","definition":"a material with particular properties","examples":[{"en":"The substance dissolves in water.","zh":"这种物质溶于水。"},{"en":"The laboratory identified an unknown substance.","zh":"实验室鉴定了一种未知物质。"}]},{"pos":"n.","meaning":"实质；要旨；根据","definition":"the main meaningful content or solid basis","examples":[{"en":"The speech lacked substance.","zh":"讲话缺乏实质内容。"},{"en":"There is substance to her argument.","zh":"她的论点有根据。"}]}],"substantial":[{"pos":"adj.","meaning":"大量的；可观的；重大的","definition":"Large in amount, size, or importance.","examples":[{"en":"The project requires substantial investment.","zh":"项目需要大量投资。"},{"en":"She made a substantial contribution to the research.","zh":"她对研究作出了重大贡献。"}]},{"pos":"adj.","meaning":"坚固的；结实的","definition":"Solid and strongly built.","examples":[{"en":"A substantial stone wall surrounds the garden.","zh":"坚固石墙环绕花园。"},{"en":"They chose a substantial table that would last for years.","zh":"他们选了一张结实耐用的桌子。"}]},{"pos":"adj.","meaning":"实质性的；大体上的","definition":"Relating to what is real or important, or largely complete.","examples":[{"en":"The evidence showed substantial agreement between the witnesses.","zh":"证据显示证人的说法大体一致。"},{"en":"The proposal needs substantial changes rather than new wording.","zh":"提案需要实质修改，而不仅是换个措辞。"}]}],"substitute":[{"pos":"v.","meaning":"代替；替换","definition":"to use someone or something in place of another","examples":[{"en":"You can substitute yogurt for cream in this recipe.","zh":"在这个食谱中，可以用酸奶替代奶油。"},{"en":"The teacher substituted a short discussion for the final exercise.","zh":"老师用简短讨论替换了最后一项练习。"}]},{"pos":"n.","meaning":"代替者；代用品","definition":"a person or thing used instead of another","examples":[{"en":"The school arranged for a substitute during her absence.","zh":"学校在她缺席期间安排了代课教师。"},{"en":"This material is a cheaper substitute for leather.","zh":"这种材料是比皮革便宜的替代品。"}]}],"substitution":[{"pos":"n.","meaning":"替代；置换","definition":"the act of replacing one thing with another","examples":[{"en":"The recipe allows substitution of olive oil for butter.","zh":"配方允许用橄榄油代替黄油。"},{"en":"The coach made a late substitution.","zh":"教练在最后阶段作了换人。"}]},{"pos":"n.","meaning":"代入；代入法（数学）","definition":"replacing a variable with a value or expression","examples":[{"en":"Solve the equations by substitution.","zh":"用代入法解方程。"},{"en":"Substitution of this value gives the final answer.","zh":"代入这个值得到最终答案。"}]}],"subtle":[{"pos":"adj.","meaning":"细微的；微妙的；隐约的","definition":"Not obvious and requiring careful attention to notice.","examples":[{"en":"There is a subtle difference in colour.","zh":"颜色有细微差别。"},{"en":"The sauce has a subtle flavour of ginger.","zh":"酱汁带有淡淡的姜味。"}]},{"pos":"adj.","meaning":"巧妙的；精巧的；含蓄的","definition":"Cleverly designed or indirect in effect.","examples":[{"en":"The novel uses subtle humour.","zh":"小说使用了含蓄的幽默。"},{"en":"She found a subtle way to influence the decision.","zh":"她找到了巧妙影响决策的办法。"}]},{"pos":"adj.","meaning":"诡秘的；狡猾的","definition":"Clever at acting indirectly to deceive or manipulate.","examples":[{"en":"The subtle schemer concealed his real aim.","zh":"这个狡猾的谋划者隐藏了真实目的。"},{"en":"The fraud relied on a subtle manipulation of the figures.","zh":"这起欺诈依赖对数字的隐蔽操纵。"}]}],"subtract":[{"pos":"v.","meaning":"减去；去掉","definition":"to take one amount away from another","examples":[{"en":"Subtract five from the total.","zh":"从总数中减去五。"},{"en":"We subtracted the cost of transport from the budget.","zh":"我们从预算中扣除了运输费用。"}]}],"subtropical":[{"pos":"adj.","meaning":"亚热带的","definition":"relating to regions near the tropics","examples":[{"en":"The island has a subtropical climate.","zh":"岛上属于亚热带气候。"},{"en":"Subtropical plants grow in the sheltered garden.","zh":"亚热带植物生长在避风花园中。"}]}],"suburb":[{"pos":"n.","meaning":"郊区；城郊住宅区","definition":"A residential area outside a city centre.","examples":[{"en":"They live in a quiet suburb.","zh":"他们住在安静的郊区。"},{"en":"The railway connects the suburbs to the centre.","zh":"铁路把郊区与市中心连接起来。"}]}],"succeed":[{"pos":"v.","meaning":"成功","definition":"to achieve an intended result","examples":[{"en":"She succeeded in passing the entrance test.","zh":"她成功通过了入学测试。"},{"en":"The experiment succeeded on the third attempt.","zh":"实验在第三次尝试时成功了。"}]},{"pos":"v.","meaning":"接替；继任","definition":"to take a position after someone else","examples":[{"en":"A new director will succeed him next spring.","zh":"新主任将在明年春天接替他。"},{"en":"She succeeded her mentor as head of the department.","zh":"她接替导师担任系主任。"}]},{"pos":"v.","meaning":"接着发生；接续","definition":"to come after something in a sequence","examples":[{"en":"A period of calm succeeded the storm.","zh":"暴风雨过后是一段平静时期。"},{"en":"One difficulty succeeded another during the journey.","zh":"旅途中，困难接踵而至。"}]}],"succession":[{"pos":"n.","meaning":"连续；接连","definition":"a series of things following one another","examples":[{"en":"A succession of storms hit the coast.","zh":"一连串风暴袭击海岸。"},{"en":"They won three games in succession.","zh":"他们连赢三场。"}]},{"pos":"n.","meaning":"继承；接替","definition":"the process of taking over a position or property","examples":[{"en":"The company planned for leadership succession.","zh":"公司为领导层接替作了安排。"},{"en":"The law governed succession to the estate.","zh":"法律规定了遗产继承。"}]}],"successive":[{"pos":"adj.","meaning":"连续的；接连的","definition":"Following one after another without interruption.","examples":[{"en":"The team won three successive matches.","zh":"球队连续赢了三场比赛。"},{"en":"Successive winters damaged the road.","zh":"接连几个冬季损坏了道路。"}]}],"succumb":[{"pos":"v.","meaning":"屈服；屈从","definition":"to stop resisting pressure or temptation","examples":[{"en":"He finally succumbed to pressure and changed the plan.","zh":"他最终屈服于压力，改变了计划。"},{"en":"She resisted the urge to buy more, but eventually succumbed.","zh":"她克制着再买东西的冲动，但最终没能坚持住。"}]},{"pos":"v.","meaning":"因病或伤死亡","definition":"to die as a result of an illness or injury","examples":[{"en":"The historical account describes villagers who succumbed to fever.","zh":"这份历史记载描述了因发热疾病而去世的村民。"},{"en":"Several trees succumbed to disease during the drought.","zh":"干旱期间，几棵树因病害死亡。"}]}],"sucker":[{"pos":"n.","meaning":"吸盘","definition":"a structure that attaches by suction","examples":[{"en":"The octopus uses its suckers to grip.","zh":"章鱼用吸盘抓握。"},{"en":"A rubber sucker held the sign to the glass.","zh":"橡胶吸盘把标牌固定在玻璃上。"}]},{"pos":"n.","meaning":"根蘖；根出条","definition":"a new plant shoot growing from roots or a lower stem","examples":[{"en":"The tree produced several suckers near its base.","zh":"树基部附近长出几条根蘖。"},{"en":"The gardener removed unwanted suckers.","zh":"园丁去除了不需要的根出条。"}]}],"suffer":[{"pos":"v.","meaning":"遭受；忍受；患有","definition":"To experience pain, difficulty, or illness.","examples":[{"en":"The town suffered serious flood damage.","zh":"小镇遭受严重洪灾损失。"},{"en":"She suffers from frequent headaches.","zh":"她经常头痛。"}]},{"pos":"v.","meaning":"受损；变差","definition":"To be harmed or become worse.","examples":[{"en":"The service suffered after funding was cut.","zh":"资金削减后，服务质量下降了。"},{"en":"His studies suffered because he worked long hours.","zh":"长时间工作影响了他的学业。"}]},{"pos":"v.","meaning":"容许；忍耐（较旧或固定用法）","definition":"To tolerate or allow something.","examples":[{"en":"She does not suffer fools gladly.","zh":"她无法容忍愚蠢的人。"},{"en":"The old ruler would suffer no challenge to his authority.","zh":"这位年老统治者不容许任何人挑战其权威。"}]}],"suffice":[{"pos":"v.","meaning":"足够；满足需要","definition":"to be enough for a particular purpose","examples":[{"en":"A short email will suffice for now.","zh":"目前一封简短邮件就足够了。"},{"en":"Two examples should suffice to explain the rule.","zh":"两个例子应该足以解释这条规则。"}]}],"sufficient":[{"pos":"adj.","meaning":"足够的","definition":"enough for a purpose","examples":[{"en":"There is not sufficient evidence to support the claim.","zh":"没有足够证据支持这一说法。"},{"en":"The school needs sufficient funding for repairs.","zh":"学校需要足够资金进行维修。"},{"en":"Two weeks should be sufficient to complete the survey.","zh":"两周应该足够完成调查。"}]}],"suggest":[{"pos":"v.","meaning":"建议；提出","definition":"To put forward an idea for consideration.","examples":[{"en":"She suggested meeting earlier.","zh":"她建议早点见面。"},{"en":"Can you suggest a suitable title?","zh":"你能提出一个合适标题吗？"}]},{"pos":"v.","meaning":"暗示；表明","definition":"To indicate something indirectly.","examples":[{"en":"The evidence suggests that the building is older than expected.","zh":"证据表明建筑比预期更古老。"},{"en":"His silence suggested disagreement.","zh":"他的沉默暗示他不同意。"}]}],"suicidal":[{"pos":"adj.","meaning":"有自杀倾向的；与自杀有关的","definition":"relating to wanting or attempting to end one's own life","examples":[{"en":"The novel describes a character experiencing suicidal thoughts.","zh":"这部小说描写了一个出现自杀念头的人物。"},{"en":"The training explains how staff can recognise suicidal distress.","zh":"培训讲解了工作人员如何识别伴有自杀风险的痛苦状态。"}]},{"pos":"adj.","meaning":"极其危险的；自毁的（比喻）","definition":"so risky that it is likely to cause serious failure","examples":[{"en":"Critics called the business decision financially suicidal.","zh":"批评者称这个商业决定在财务上无异于自毁。"},{"en":"Crossing the flooded bridge would have been suicidal.","zh":"穿越被洪水淹没的桥会极其危险。"}]}],"suitable":[{"pos":"adj.","meaning":"合适的；适宜的","definition":"right for a particular purpose","examples":[{"en":"This room is suitable for meetings.","zh":"这个房间适合开会。"},{"en":"Wear shoes suitable for walking.","zh":"穿适合走路的鞋。"}]}],"suitably":[{"pos":"adv.","meaning":"适当地；合适地；相称地","definition":"In a way appropriate to the circumstances.","examples":[{"en":"Dress suitably for the weather.","zh":"穿着要适合天气。"},{"en":"The laboratory must be suitably equipped.","zh":"实验室必须配备适当设备。"}]}],"suitcase":[{"pos":"n.","meaning":"手提箱；旅行箱","definition":"a case used to carry clothes while travelling","examples":[{"en":"Her suitcase was too large for the overhead shelf.","zh":"她的旅行箱太大，放不进行李架。"},{"en":"He packed a small suitcase for the weekend.","zh":"他为周末行程收拾了一个小旅行箱。"}]}],"sulphuric acid":[{"pos":"n.","meaning":"硫酸","definition":"a strong acid with the formula H2SO4","examples":[{"en":"The laboratory stores sulphuric acid in labelled containers.","zh":"实验室把硫酸存放在有标签的容器中。"},{"en":"The diagram identifies sulphuric acid as a reactant.","zh":"图中标明硫酸是一种反应物。"}]}],"summarise":[{"pos":"v.","meaning":"总结；概括","definition":"To give the main points briefly.","examples":[{"en":"Please summarise the article in one paragraph.","zh":"请用一段话概括文章。"},{"en":"The chair summarised the discussion.","zh":"主席总结了讨论内容。"}]}],"summary":[{"pos":"n.","meaning":"摘要；概要","definition":"a short account of the main points","examples":[{"en":"Write a brief summary of the lecture.","zh":"写一份讲座的简短摘要。"},{"en":"The report begins with a summary of the findings.","zh":"报告以研究结果概要开篇。"}]},{"pos":"adj.","meaning":"概括的；简略的","definition":"presenting only the main points","examples":[{"en":"A summary table appears at the end of the chapter.","zh":"本章末尾有一张汇总表。"},{"en":"The manager gave a summary account of the changes.","zh":"经理简要介绍了这些变化。"}]}],"summit":[{"pos":"n.","meaning":"山顶；最高点","definition":"the highest point of a mountain","examples":[{"en":"They reached the summit at noon.","zh":"他们中午到达山顶。"},{"en":"Clouds hid the summit.","zh":"云遮住了山顶。"}]}],"sundial":[{"pos":"n.","meaning":"日晷；日规","definition":"An instrument showing time by the position of a shadow cast by the Sun.","examples":[{"en":"A stone sundial stands in the garden.","zh":"花园里立着一座石制日晷。"},{"en":"The sundial's shadow moved across the markings.","zh":"日晷的影子移过刻度。"}]}],"superb":[{"pos":"adj.","meaning":"极好的；出色的","definition":"of exceptionally high quality","examples":[{"en":"The hotel offers a superb view of the mountains.","zh":"这家酒店能欣赏到极佳的山景。"},{"en":"Her superb performance impressed the audience.","zh":"她出色的表演给观众留下了深刻印象。"}]}],"superficial":[{"pos":"adj.","meaning":"表面的；浅表的","definition":"affecting only the surface","examples":[{"en":"The damage was superficial.","zh":"损坏仅在表面。"},{"en":"The scratch left a superficial mark.","zh":"划伤留下浅表痕迹。"}]},{"pos":"adj.","meaning":"肤浅的；不深入的","definition":"lacking depth or careful understanding","examples":[{"en":"The report offers only a superficial analysis.","zh":"报告仅有肤浅分析。"},{"en":"He had a superficial knowledge of the subject.","zh":"他对这门学科了解不深。"}]}],"superior":[{"pos":"adj.","meaning":"上级的；地位较高的","definition":"Higher in rank or authority.","examples":[{"en":"The decision required approval from a superior officer.","zh":"这个决定需要上级军官批准。"},{"en":"The case was referred to a superior court.","zh":"案件被提交给上级法院。"}]},{"pos":"adj.","meaning":"更优的；优良的；较好的","definition":"Better in quality or ability.","examples":[{"en":"This material offers superior insulation.","zh":"这种材料具有更好的隔热性能。"},{"en":"Their knowledge of the terrain was superior to ours.","zh":"他们对地形的了解比我们更充分。"}]},{"pos":"adj.","meaning":"高傲的；有优越感的","definition":"Behaving as though one is better than others.","examples":[{"en":"His superior tone irritated the group.","zh":"他傲慢的语气让大家不快。"},{"en":"She gave a superior smile and dismissed the suggestion.","zh":"她露出高傲的笑容，否定了建议。"}]},{"pos":"n.","meaning":"上级；长官","definition":"A person higher in rank or authority.","examples":[{"en":"Report the problem to your superior.","zh":"向你的上级报告问题。"},{"en":"Her superiors praised the quality of her work.","zh":"她的上级赞扬了她的工作质量。"}]}],"supersede":[{"pos":"v.","meaning":"取代；代替","definition":"to replace something that is no longer preferred or current","examples":[{"en":"The new system supersedes the paper records.","zh":"新系统取代了纸质记录。"},{"en":"This edition supersedes the previous guide.","zh":"这个版本取代了上一版指南。"}]}],"superstitious":[{"pos":"adj.","meaning":"迷信的","definition":"believing in supernatural luck or omens","examples":[{"en":"She is superstitious about certain numbers.","zh":"她迷信某些数字。"},{"en":"The tale reflects old superstitious beliefs.","zh":"故事反映了古老的迷信观念。"}]}],"supervise":[{"pos":"v.","meaning":"监督；管理；指导","definition":"To oversee work and ensure it is done correctly.","examples":[{"en":"A teacher supervised the experiment.","zh":"一位教师监督了实验。"},{"en":"She supervises a team of ten researchers.","zh":"她管理一个十人的研究团队。"}]}],"supervision":[{"pos":"n.","meaning":"监督；管理；指导","definition":"the activity of watching and guiding work or behaviour","ipa":"/ˌsuːpəˈvɪʒən/","examples":[{"en":"The students worked under close supervision.","zh":"学生在严密指导下开展工作。"},{"en":"Young children need supervision near water.","zh":"幼儿在水边需要有人看护。"}]}],"supervisor":[{"pos":"n.","meaning":"主管；监督者","definition":"a person who oversees other people's work","examples":[{"en":"Ask your supervisor before changing your shift.","zh":"换班前请先征求主管同意。"},{"en":"The supervisor checks the equipment every morning.","zh":"主管每天早晨检查设备。"},{"en":"Report any safety concerns to your supervisor.","zh":"请向主管报告任何安全隐患。"}]},{"pos":"n.","meaning":"导师；研究指导者","definition":"an academic who guides a student's research","examples":[{"en":"My supervisor suggested a narrower research question.","zh":"我的导师建议缩小研究问题的范围。"},{"en":"She meets her thesis supervisor every fortnight.","zh":"她每两周与论文导师见面一次。"}]}],"supplement":[{"pos":"v.","meaning":"补充；增补","definition":"To add something that improves or completes another thing.","examples":[{"en":"She supplements her income by tutoring.","zh":"她通过辅导学生增加收入。"},{"en":"The lecture was supplemented with a reading list.","zh":"讲座补充提供了一份阅读书目。"}],"ipa":"/ˈsʌplɪment/"},{"pos":"n.","meaning":"补充物；补充资料","definition":"Something added to complete or improve something else.","examples":[{"en":"The handbook is a useful supplement to the course.","zh":"手册是课程的有益补充。"},{"en":"The report includes a supplement with detailed tables.","zh":"报告附有包含详细表格的补充资料。"}],"ipa":"/ˈsʌplɪmənt/"},{"pos":"n.","meaning":"增刊；副刊；补遗","definition":"An extra section published with a book or newspaper.","examples":[{"en":"The newspaper has a weekly arts supplement.","zh":"这家报纸每周有一份艺术副刊。"},{"en":"A supplement corrected errors in the first edition.","zh":"补遗纠正了第一版中的错误。"}],"ipa":"/ˈsʌplɪmənt/"}],"supplementary":[{"pos":"adj.","meaning":"补充的；增补的","definition":"added to provide further information or support","examples":[{"en":"The course includes supplementary reading materials.","zh":"这门课程包含补充阅读材料。"},{"en":"A supplementary report explains the survey methods.","zh":"一份补充报告解释了调查方法。"}]}],"supply":[{"pos":"n.","meaning":"供应；供应量","definition":"the provision or available amount of something","examples":[{"en":"The village has a reliable water supply.","zh":"村庄有可靠的供水。"},{"en":"Demand exceeded supply.","zh":"需求超过供应。"}]},{"pos":"n.","meaning":"物资；存货（常用复数）","definition":"necessary goods kept available","examples":[{"en":"The ship carried medical supplies.","zh":"船运载医疗物资。"},{"en":"Our food supplies were running low.","zh":"我们的食物储备所剩不多。"}]},{"pos":"v.","meaning":"供应；提供","definition":"to provide something needed","examples":[{"en":"The farm supplies vegetables to schools.","zh":"农场给学校供应蔬菜。"},{"en":"The report supplied the missing information.","zh":"报告补充了缺失信息。"}]}],"supportive":[{"pos":"adj.","meaning":"支持的；鼓励的；关心帮助的","definition":"Giving help, encouragement, or sympathy.","examples":[{"en":"Her family was supportive of her decision.","zh":"家人支持她的决定。"},{"en":"The school provides a supportive environment.","zh":"学校提供了充满支持的环境。"}]}],"suppose":[{"pos":"v.","meaning":"猜想；认为","definition":"to think something is likely without being certain","examples":[{"en":"I suppose the train will be busy this evening.","zh":"我猜今晚火车上会很拥挤。"},{"en":"She supposed that the meeting had been cancelled.","zh":"她以为会议已经取消了。"}]},{"pos":"v.","meaning":"假定；假设","definition":"to imagine a situation for discussion","examples":[{"en":"Suppose the price doubled; what would you buy instead?","zh":"假设价格翻倍，你会改买什么？"},{"en":"Let us suppose that every student has access to a library.","zh":"我们假设每个学生都能使用图书馆。"}]},{"pos":"v.","meaning":"应该；被要求（be supposed to）","definition":"to be expected or required to do something","examples":[{"en":"You are supposed to return the key before noon.","zh":"你应该在中午前归还钥匙。"},{"en":"The exhibition is supposed to open on Friday.","zh":"展览按计划应该周五开幕。"}]}],"suppress":[{"pos":"v.","meaning":"镇压；压制","definition":"to stop by force or authority","examples":[{"en":"The regime suppressed the protest.","zh":"当局镇压了抗议。"},{"en":"The policy suppressed open debate.","zh":"政策压制了公开辩论。"}]},{"pos":"v.","meaning":"禁止发表；隐瞒","definition":"to prevent information from becoming known","examples":[{"en":"The report was suppressed for years.","zh":"报告被压下多年。"},{"en":"They tried to suppress the evidence.","zh":"他们试图隐瞒证据。"}]},{"pos":"v.","meaning":"抑制；忍住；阻止发展","definition":"to hold back a feeling or reduce growth","examples":[{"en":"She suppressed a laugh.","zh":"她忍住了笑。"},{"en":"The covering suppresses weed growth.","zh":"覆盖物抑制杂草生长。"}]}],"suppression":[{"pos":"n.","meaning":"镇压；压制；抑制","definition":"The act of forcibly preventing expression, activity, or growth.","examples":[{"en":"The book describes the suppression of dissent.","zh":"书中描述了对异议的压制。"},{"en":"The experiment studied the suppression of bacterial growth.","zh":"实验研究了对细菌生长的抑制。"}]},{"pos":"n.","meaning":"扑灭；控制","definition":"The act of stopping a fire or another harmful process.","examples":[{"en":"The building has an automatic fire suppression system.","zh":"大楼配有自动灭火系统。"},{"en":"Smoke suppression was a priority in the design.","zh":"抑制烟雾是设计中的重点。"}]}],"surf":[{"pos":"v.","meaning":"冲浪","definition":"to ride ocean waves on a board","examples":[{"en":"They learned to surf on the south coast.","zh":"他们在南海岸学会了冲浪。"},{"en":"She surfs whenever the weather allows.","zh":"天气允许时，她就去冲浪。"}]},{"pos":"v.","meaning":"浏览网络","definition":"to move among websites looking for information","examples":[{"en":"He surfed the internet for train schedules.","zh":"他上网浏览火车时刻表。"},{"en":"Students were surfing the web during the break.","zh":"休息时，学生们在浏览网页。"}]}],"surface":[{"pos":"n.","meaning":"表面；外表","definition":"the outside or top layer","examples":[{"en":"The surface feels rough.","zh":"表面摸起来粗糙。"},{"en":"On the surface, everything seemed normal.","zh":"表面上看，一切似乎正常。"}]},{"pos":"v.","meaning":"浮出水面；显露","definition":"to rise to the top or become known","examples":[{"en":"The diver surfaced near the boat.","zh":"潜水员在船旁浮出水面。"},{"en":"New evidence surfaced during the inquiry.","zh":"调查中出现了新证据。"}]},{"pos":"v.","meaning":"给……铺面","definition":"to cover with a top layer","examples":[{"en":"The road was surfaced with asphalt.","zh":"道路铺了沥青。"},{"en":"They surfaced the path with gravel.","zh":"他们给小路铺上碎石。"}]}],"surge":[{"pos":"v.","meaning":"涌动；蜂拥；猛增","definition":"To move forward or rise suddenly and strongly.","examples":[{"en":"The crowd surged towards the doors.","zh":"人群涌向大门。"},{"en":"Demand surged after the announcement.","zh":"公告发布后，需求猛增。"}]},{"pos":"n.","meaning":"猛增；涌起；强烈感情","definition":"A sudden increase or powerful movement or feeling.","examples":[{"en":"A surge in visitors strained local services.","zh":"游客激增给当地服务带来压力。"},{"en":"She felt a surge of relief.","zh":"她感到一阵强烈的宽慰。"}]}],"surgeon":[{"pos":"n.","meaning":"外科医生","definition":"a doctor who performs operations","examples":[{"en":"The surgeon explained the procedure to the patient.","zh":"外科医生向患者解释了手术过程。"},{"en":"A visiting surgeon spoke to the medical students.","zh":"一位来访的外科医生向医学生作了讲话。"}]}],"surgery":[{"pos":"n.","meaning":"外科手术；外科学","definition":"medical treatment involving an operation","examples":[{"en":"She recovered after surgery.","zh":"她手术后恢复了。"},{"en":"He specialised in heart surgery.","zh":"他专攻心脏外科。"}]},{"pos":"n.","meaning":"诊室；诊所（英式）","definition":"a place where a doctor or dentist sees patients","examples":[{"en":"The surgery opens at eight.","zh":"诊所八点开门。"},{"en":"She waited in the doctor's surgery.","zh":"她在医生诊室里等待。"}]}],"surpass":[{"pos":"v.","meaning":"超过；胜过；超出","definition":"To do better than or go beyond a limit.","examples":[{"en":"Sales surpassed our expectations.","zh":"销售额超出了我们的预期。"},{"en":"Her skill soon surpassed that of her teacher.","zh":"她的技艺很快超过了老师。"}]}],"surround":[{"pos":"v.","meaning":"围绕；包围","definition":"to be or move all around someone or something","examples":[{"en":"Tall trees surround the house.","zh":"高大的树木环绕着房屋。"},{"en":"The visitors surrounded the guide to hear the explanation.","zh":"游客围住导游听讲解。"}]}],"surroundings":[{"pos":"n.","meaning":"周围环境；周围事物","definition":"everything around a place or person","examples":[{"en":"The hotel has peaceful surroundings.","zh":"酒店周围环境安静。"},{"en":"Take time to become familiar with your surroundings.","zh":"花些时间熟悉周围环境。"}]}],"surveillance":[{"pos":"n.","meaning":"监视；监控；盯梢","definition":"Close observation of people or places.","examples":[{"en":"The building is under constant surveillance.","zh":"大楼处于持续监控之下。"},{"en":"Police placed the suspect under surveillance.","zh":"警方对嫌疑人进行了监视。"}]}],"survey":[{"pos":"n.","meaning":"调查","definition":"a study that gathers people's answers or observations","examples":[{"en":"The survey asked residents about public transport.","zh":"这项调查询问居民对公共交通的看法。"},{"en":"More than five hundred people completed the survey.","zh":"五百多人完成了调查。"},{"en":"The survey results may not represent the whole population.","zh":"调查结果可能无法代表全部人口。"}],"ipa":"/ˈsɜːveɪ/"},{"pos":"n.","meaning":"测量;勘测;勘察","definition":"an examination or measurement of land or buildings","examples":[{"en":"The survey revealed cracks in the foundations.","zh":"勘察发现地基裂缝。"},{"en":"A land survey established the boundary.","zh":"土地测量确定了边界。"}],"ipa":"/ˈsɜːveɪ/"},{"pos":"n.","meaning":"审视;概览;综述","definition":"a broad examination or overview","examples":[{"en":"The book offers a survey of modern architecture.","zh":"本书概述现代建筑。"},{"en":"A quick survey of the room revealed no damage.","zh":"快速查看房间后发现没有损坏。"}],"ipa":"/ˈsɜːveɪ/"},{"pos":"v.","meaning":"调查;检视","definition":"to collect information or examine systematically","examples":[{"en":"The researchers surveyed five hundred households.","zh":"研究人员调查了五百户家庭。"},{"en":"An engineer surveyed the damaged bridge.","zh":"工程师检查了受损桥梁。"}],"ipa":"/səˈveɪ/"},{"pos":"v.","meaning":"测量;勘测","definition":"to measure and map an area","examples":[{"en":"The team surveyed the proposed railway route.","zh":"团队勘测了拟建铁路路线。"},{"en":"They surveyed the land before construction.","zh":"他们施工前测量了土地。"}],"ipa":"/səˈveɪ/"},{"pos":"v.","meaning":"俯瞰;眺望;审视","definition":"to look carefully over an area","examples":[{"en":"From the ridge, we surveyed the valley.","zh":"我们从山脊眺望山谷。"},{"en":"She surveyed the crowded hall before speaking.","zh":"她发言前扫视了拥挤大厅。"}],"ipa":"/səˈveɪ/"}],"survive":[{"pos":"v.","meaning":"生存；幸免于难","definition":"to remain alive or continue to exist","examples":[{"en":"The plants survived the winter.","zh":"植物熬过了冬天。"},{"en":"Only part of the wall survives.","zh":"只有部分墙体留存。"}]},{"pos":"v.","meaning":"比……活得长","definition":"to live longer than someone","examples":[{"en":"She survived her husband by ten years.","zh":"她比丈夫多活了十年。"},{"en":"He was survived by two children.","zh":"他去世后留下两个子女。"}]}],"susceptible":[{"pos":"adj.","meaning":"易受影响的；易受感染的；敏感的","definition":"Likely to be affected, harmed, or persuaded.","examples":[{"en":"Young plants are susceptible to frost.","zh":"幼苗容易受到霜冻伤害。"},{"en":"He is susceptible to flattery.","zh":"他容易受奉承话影响。"}]},{"pos":"adj.","meaning":"能接受……的；可作……处理的","definition":"Capable of being subjected to a particular process or interpretation.","examples":[{"en":"The claim is susceptible to several interpretations.","zh":"这个说法可以有几种解释。"},{"en":"The material is susceptible to chemical analysis.","zh":"这种材料可以进行化学分析。"}]}],"suspect":[{"pos":"v.","meaning":"猜想；怀疑","definition":"to think something may be true without proof","ipa":"/səˈspekt/","examples":[{"en":"I suspect the figures contain an error.","zh":"我怀疑这些数字有误。"},{"en":"She suspected that the package had gone to the wrong address.","zh":"她怀疑包裹被送到了错误的地址。"}]},{"pos":"v.","meaning":"怀疑某人有过错","definition":"to think someone may be responsible for wrongdoing","ipa":"/səˈspekt/","examples":[{"en":"The manager suspected someone of changing the records.","zh":"经理怀疑有人改动了记录。"},{"en":"Nobody suspected the quiet assistant at first.","zh":"起初没人怀疑那位沉默的助理。"}]},{"pos":"n.","meaning":"嫌疑人","definition":"a person thought possibly responsible for a crime","ipa":"/ˈsʌspekt/","examples":[{"en":"The detective interviewed a suspect that afternoon.","zh":"侦探那天下午询问了一名嫌疑人。"},{"en":"The suspect denied being near the warehouse.","zh":"嫌疑人否认去过仓库附近。"}]},{"pos":"adj.","meaning":"可疑的；不可靠的","definition":"not fully trusted or considered reliable","ipa":"/ˈsʌspekt/","examples":[{"en":"The source of the information was suspect.","zh":"这条消息的来源不可靠。"},{"en":"The inspector set aside the suspect batch.","zh":"检查员把可疑的那一批产品单独放置。"}]}],"suspend":[{"pos":"v.","meaning":"悬挂；吊","definition":"to hang something from above","examples":[{"en":"The lamp is suspended from the ceiling.","zh":"灯悬挂在天花板上。"},{"en":"Cables suspend the platform.","zh":"缆索吊着平台。"}]},{"pos":"v.","meaning":"暂停；中止；延期","definition":"to stop temporarily or postpone","examples":[{"en":"The service was suspended during repairs.","zh":"服务在维修期间暂停。"},{"en":"They suspended the decision pending further evidence.","zh":"他们暂缓决定，等待更多证据。"}]}],"sustain":[{"pos":"v.","meaning":"支撑；承受","definition":"To support weight or pressure.","examples":[{"en":"The beams sustain the weight of the roof.","zh":"横梁支撑屋顶的重量。"},{"en":"The bridge can sustain heavy traffic.","zh":"这座桥能承受繁重车流。"}]},{"pos":"v.","meaning":"维持；保持；使持续","definition":"To keep something going or provide what is needed.","examples":[{"en":"The income sustains the small charity.","zh":"这笔收入维持着这个小慈善机构。"},{"en":"It was difficult to sustain interest throughout the long lecture.","zh":"长时间讲座中很难始终保持兴趣。"}]},{"pos":"v.","meaning":"遭受；蒙受","definition":"To experience an injury, loss, or damage.","examples":[{"en":"The vehicle sustained minor damage.","zh":"车辆受到轻微损坏。"},{"en":"Several players sustained injuries.","zh":"几名球员受了伤。"}]}],"sustainable":[{"pos":"adj.","meaning":"可持续的","definition":"able to continue without exhausting resources","examples":[{"en":"Cities need a sustainable approach to transport.","zh":"城市需要可持续的交通方式。"},{"en":"Sustainable farming protects soil for future generations.","zh":"可持续农业为后代保护土壤。"},{"en":"The project promotes sustainable use of water.","zh":"该项目促进水资源的可持续利用。"}]},{"pos":"adj.","meaning":"能维持的;可承受的;养得起的","definition":"able to be supported or continued over time","examples":[{"en":"The current workload is not sustainable.","zh":"目前的工作量无法长期承受。"},{"en":"They developed a financially sustainable business plan.","zh":"他们制定了财务上可持续维持的商业计划。"}]}],"swallow":[{"pos":"v.","meaning":"吞咽；吞下","definition":"to make food or liquid pass down the throat","examples":[{"en":"She swallowed a mouthful of water.","zh":"她咽下一口水。"},{"en":"The bird swallowed the fish whole.","zh":"鸟把鱼整个吞下了。"}]},{"pos":"v.","meaning":"忍受；勉强接受","definition":"to accept something unpleasant without protest","examples":[{"en":"He swallowed his disappointment.","zh":"他忍下了失望。"},{"en":"She found the criticism hard to swallow.","zh":"她觉得这些批评难以接受。"}]},{"pos":"n.","meaning":"燕子","definition":"a small bird with long wings and a forked tail","examples":[{"en":"A swallow skimmed the pond.","zh":"一只燕子掠过池塘。"},{"en":"Swallows nested under the roof.","zh":"燕子在屋檐下筑巢。"}]}],"swamp":[{"pos":"n.","meaning":"沼泽；湿地","definition":"An area of very wet land.","examples":[{"en":"The path skirts the swamp.","zh":"小路绕过沼泽。"},{"en":"Tall grasses grew in the swamp.","zh":"沼泽里长着高草。"}]},{"pos":"v.","meaning":"淹没；浸没","definition":"To cover or fill with water.","examples":[{"en":"A wave swamped the small boat.","zh":"一波海浪淹没了小船。"},{"en":"Heavy rain swamped the fields.","zh":"大雨淹没了田野。"}]},{"pos":"v.","meaning":"使应接不暇；压倒","definition":"To overwhelm with too much work or too many things.","examples":[{"en":"The office was swamped with calls.","zh":"办公室接到大量来电，应接不暇。"},{"en":"We were swamped by applications.","zh":"申请太多，让我们难以招架。"}]}],"swap":[{"pos":"v.","meaning":"交换","definition":"to give one thing in return for another","examples":[{"en":"We swapped seats so that she could sit by the window.","zh":"我们交换了座位，让她坐在窗边。"},{"en":"The students swapped ideas after the presentation.","zh":"展示结束后，学生们交流了想法。"}]},{"pos":"n.","meaning":"交换","definition":"an exchange of one thing for another","examples":[{"en":"The book swap attracted many local readers.","zh":"图书交换活动吸引了许多当地读者。"},{"en":"They arranged a swap of weekend shifts.","zh":"他们安排交换周末的班次。"}]}],"swear":[{"pos":"v.","meaning":"发誓；宣誓","definition":"to make a solemn promise or statement","examples":[{"en":"She swore to tell the truth.","zh":"她发誓说实话。"},{"en":"The witnesses were sworn in.","zh":"证人宣誓作证。"}]},{"pos":"v.","meaning":"咒骂；说脏话","definition":"to use offensive language","examples":[{"en":"He swore when the tool broke.","zh":"工具坏了，他骂了一句。"},{"en":"The teacher asked them not to swear.","zh":"老师要求他们不要说脏话。"}]}],"swell":[{"pos":"v.","meaning":"肿胀；膨胀；增大","definition":"To become larger or fuller.","examples":[{"en":"His ankle began to swell.","zh":"他的脚踝开始肿起来。"},{"en":"The sails swelled in the wind.","zh":"船帆被风鼓起。"}]},{"pos":"v.","meaning":"增加；增强；高涨","definition":"To grow in amount, strength, or emotion.","examples":[{"en":"The crowd swelled as more people arrived.","zh":"随着更多人到来，人群不断扩大。"},{"en":"The music swelled towards its climax.","zh":"音乐逐渐增强，进入高潮。"}]}],"swift":[{"pos":"adj.","meaning":"迅速的；敏捷的","definition":"happening or moving very quickly","examples":[{"en":"The team made a swift response to the problem.","zh":"团队迅速回应了这个问题。"},{"en":"A swift movement caught her attention.","zh":"一个敏捷的动作引起了她的注意。"}]}],"swing":[{"pos":"v.","meaning":"摆动；摇摆","definition":"to move back and forth","examples":[{"en":"The lamp swung in the wind.","zh":"灯在风中摆动。"},{"en":"She swung her legs beneath the chair.","zh":"她在椅下晃动双腿。"}]},{"pos":"v.","meaning":"突然转向；转变","definition":"to turn or change direction","examples":[{"en":"The door swung open.","zh":"门一下打开了。"},{"en":"Opinion swung in favour of the plan.","zh":"舆论转而支持计划。"}]},{"pos":"n.","meaning":"摆动；摇摆","definition":"a back-and-forth movement","examples":[{"en":"The pendulum's swing became slower.","zh":"钟摆摆动变慢了。"},{"en":"A swing of the bat sent the ball flying.","zh":"球棒一挥把球击飞。"}]},{"pos":"n.","meaning":"秋千","definition":"a suspended seat that moves back and forth","examples":[{"en":"The child sat on the swing.","zh":"孩子坐在秋千上。"},{"en":"The park has two swings.","zh":"公园里有两个秋千。"}]}],"switch":[{"pos":"n.","meaning":"开关","definition":"A device that starts or stops a circuit or machine.","examples":[{"en":"The light switch is beside the door.","zh":"电灯开关在门旁。"},{"en":"Turn the main switch off before cleaning.","zh":"清洁前关掉总开关。"}]},{"pos":"n.","meaning":"转换；改变；调换","definition":"A change from one thing to another.","examples":[{"en":"The switch to renewable energy took several years.","zh":"转用可再生能源花了几年。"},{"en":"A sudden switch in plans confused everyone.","zh":"计划突然改变，让大家困惑。"}]},{"pos":"v.","meaning":"转换；改变；对调","definition":"To change to something else or exchange positions.","examples":[{"en":"She switched to a different course.","zh":"她换了一门课程。"},{"en":"We switched seats so that I could see better.","zh":"我们换了座位，让我看得更清楚。"}]}],"swivel":[{"pos":"v.","meaning":"旋转；转动","definition":"to turn around a fixed point","examples":[{"en":"She swivelled her chair towards the screen.","zh":"她转动椅子面向屏幕。"},{"en":"The camera can swivel to follow movement.","zh":"摄像机可以旋转以跟踪移动。"}]},{"pos":"n.","meaning":"转环；旋转接头","definition":"a joint that allows connected parts to turn","examples":[{"en":"The lamp is attached to a swivel.","zh":"灯装在一个旋转接头上。"},{"en":"A small swivel keeps the rope from twisting.","zh":"一个小转环可以防止绳子缠扭。"}]}],"syllabus":[{"pos":"n.","meaning":"教学大纲；课程纲要","definition":"an outline of the subjects and requirements of a course","examples":[{"en":"The teacher explained the syllabus during the first lesson.","zh":"老师在第一堂课介绍了教学大纲。"},{"en":"Climate change has been added to the geography syllabus.","zh":"气候变化已被加入地理课程大纲。"}]}],"symbol":[{"pos":"n.","meaning":"象征","definition":"something representing an idea","examples":[{"en":"The dove is a symbol of peace.","zh":"鸽子是和平的象征。"},{"en":"The bridge became a symbol of cooperation.","zh":"大桥成为合作的象征。"}]},{"pos":"n.","meaning":"符号","definition":"a mark used to represent something","examples":[{"en":"The map uses symbols for campsites.","zh":"地图用符号表示营地。"},{"en":"Write the correct chemical symbol.","zh":"写出正确的化学符号。"}]}],"symbolism":[{"pos":"n.","meaning":"象征手法；象征主义；符号运用","definition":"The use of symbols to represent ideas.","examples":[{"en":"The poem's symbolism connects winter with isolation.","zh":"诗中的象征手法把冬天与孤独联系起来。"},{"en":"The course explores symbolism in modern painting.","zh":"课程探讨现代绘画中的象征主义。"}]}],"sympathetic":[{"pos":"adj.","meaning":"同情的；体谅的","definition":"showing understanding of another person's difficulties","examples":[{"en":"Her teacher was sympathetic when she explained the problem.","zh":"她解释困难时，老师很体谅她。"},{"en":"A sympathetic listener can make a difficult day easier.","zh":"一个有同情心的倾听者能让艰难的一天好过些。"}]},{"pos":"adj.","meaning":"赞同的；支持的","definition":"favouring an idea or proposal","examples":[{"en":"The council is sympathetic to the proposal.","zh":"市政委员会支持这项提议。"},{"en":"He found an audience sympathetic to his argument.","zh":"他找到了赞同自己论点的听众。"}]},{"pos":"adj.","meaning":"协调的；相宜的","definition":"suited to the character or style of something","examples":[{"en":"The extension uses materials sympathetic to the old building.","zh":"扩建部分使用了与旧建筑相协调的材料。"},{"en":"The restoration was sympathetic to the original design.","zh":"这次修复与原设计相吻合。"}]}],"sympathise":[{"pos":"v.","meaning":"同情；理解","definition":"to understand and share someone's distress","examples":[{"en":"I sympathise with your disappointment.","zh":"我理解你的失望。"},{"en":"Neighbours sympathised with the family.","zh":"邻居们同情这家人。"}]},{"pos":"v.","meaning":"赞同；支持","definition":"to share someone's views or position","examples":[{"en":"She sympathised with their aims.","zh":"她赞同他们的目标。"},{"en":"Many residents sympathise with the campaign.","zh":"许多居民支持这场活动。"}]}],"sympathy":[{"pos":"n.","meaning":"同情；怜悯；体谅","definition":"Understanding and concern for someone else's suffering.","examples":[{"en":"She expressed sympathy for the injured workers.","zh":"她对受伤工人表示同情。"},{"en":"His colleagues treated him with sympathy.","zh":"同事们体谅他。"}]},{"pos":"n.","meaning":"赞同；支持；共鸣","definition":"Agreement with or support for a person or cause.","examples":[{"en":"I have some sympathy with their argument.","zh":"我对他们的论点有些认同。"},{"en":"The campaign gained public sympathy.","zh":"这场活动获得了公众支持。"}]}],"symphony":[{"pos":"n.","meaning":"交响乐；交响曲","definition":"a large musical work usually written for an orchestra","examples":[{"en":"A student orchestra rehearsed the symphony for its winter concert.","zh":"一支学生管弦乐队为冬季音乐会排练了这首交响曲。"},{"en":"The final movement of the symphony was especially powerful.","zh":"这首交响曲的最后一个乐章格外有力。"}]}],"symptom":[{"pos":"n.","meaning":"症状","definition":"a sign of an illness","examples":[{"en":"A persistent cough can be a symptom of illness.","zh":"持续咳嗽可能是疾病的症状。"},{"en":"Tell the nurse about any unusual symptom.","zh":"如有任何异常症状，请告诉护士。"},{"en":"A fever is a common symptom of this infection.","zh":"发烧是这种感染的常见症状。"}]},{"pos":"n.","meaning":"征兆；表现","definition":"a sign of an underlying problem","examples":[{"en":"The delay is a symptom of poor planning.","zh":"延误是规划不善的表现。"},{"en":"Falling attendance was a symptom of wider dissatisfaction.","zh":"出席人数减少是更广泛不满的征兆。"}]}],"synchronise":[{"pos":"v.","meaning":"使同步；使同时发生","definition":"To make activities happen at the same time or rate.","examples":[{"en":"The dancers synchronised their movements.","zh":"舞者同步动作。"},{"en":"Synchronise the clocks before the experiment.","zh":"实验前把时钟同步。"}]}],"synthesis":[{"pos":"n.","meaning":"综合；融合","definition":"the combination of separate ideas into a coherent whole","examples":[{"en":"The essay offers a synthesis of several theories.","zh":"这篇文章综合了几种理论。"},{"en":"Her design is a synthesis of traditional and modern styles.","zh":"她的设计融合了传统与现代风格。"}]},{"pos":"n.","meaning":"合成","definition":"the production of a substance from simpler components","examples":[{"en":"The laboratory studies the synthesis of new materials.","zh":"这间实验室研究新材料的合成。"},{"en":"Light provides energy for the synthesis of sugars in plants.","zh":"光为植物合成糖提供能量。"}]}],"synthetic":[{"pos":"adj.","meaning":"合成的；人造的","definition":"made artificially through chemical processes","examples":[{"en":"The jacket contains synthetic fibres.","zh":"夹克含合成纤维。"},{"en":"The laboratory developed a synthetic material.","zh":"实验室开发了合成材料。"}]},{"pos":"adj.","meaning":"综合的；合成性的","definition":"combining separate parts into a whole","examples":[{"en":"The essay offers a synthetic view of several theories.","zh":"文章综合呈现了几种理论。"},{"en":"The method moves from analysis to synthetic reconstruction.","zh":"方法从分析推进到综合重构。"}]},{"pos":"n.","meaning":"合成材料；合成纤维织物","definition":"an artificially produced material or fabric","examples":[{"en":"The fabric is a durable synthetic.","zh":"面料是一种耐用合成织物。"},{"en":"The shop sells wool and synthetics.","zh":"商店销售羊毛与合成织物。"}]}],"systematic":[{"pos":"adj.","meaning":"系统的；有条理的；按体系进行的","definition":"Following an organised method or plan.","examples":[{"en":"The team carried out a systematic search.","zh":"团队进行了系统搜索。"},{"en":"A systematic approach helped her organise the data.","zh":"有条理的方法帮助她整理数据。"}]}],"tab":[{"pos":"n.","meaning":"标签；页签","definition":"a small labelled part used to identify or open a section","examples":[{"en":"Click the tab marked History.","zh":"点击标有“历史记录”的页签。"},{"en":"Each folder has a coloured tab.","zh":"每个文件夹都有一个彩色标签。"}]},{"pos":"n.","meaning":"账单（口语）","definition":"a bill for food, drink, or other expenses","examples":[{"en":"The host offered to pick up the tab.","zh":"主人提出支付账单。"},{"en":"The company paid the tab for the team dinner.","zh":"公司支付了团队晚餐的费用。"}]}],"tablet":[{"pos":"n.","meaning":"药片","definition":"a small solid dose of medicine","examples":[{"en":"The packet contained white tablets.","zh":"包装里装着白色药片。"},{"en":"The pharmacist checked the tablet label.","zh":"药剂师检查了药片标签。"}]}],"tackle":[{"pos":"v.","meaning":"处理；应对；着手解决","definition":"To make an effort to deal with a problem.","examples":[{"en":"The city must tackle traffic congestion.","zh":"城市必须解决交通拥堵。"},{"en":"We tackled the hardest task first.","zh":"我们先处理了最困难的任务。"}]},{"pos":"v.","meaning":"向某人提出难题；与某人交涉","definition":"To confront someone about a difficult matter.","examples":[{"en":"She tackled the manager about unpaid overtime.","zh":"她就未支付的加班费与经理交涉。"},{"en":"We need to tackle him on the missing records.","zh":"我们需要向他询问丢失记录的问题。"}]},{"pos":"v.","meaning":"抢截；抢球；擒抱","definition":"To try to stop an opponent or take the ball in sport.","examples":[{"en":"The defender tackled the striker cleanly.","zh":"后卫干净利落地抢断了前锋。"},{"en":"She tackled the runner before the line.","zh":"她在终点线前擒抱了持球跑动者。"}]}],"tag":[{"pos":"n.","meaning":"标签","definition":"a label attached to an object","examples":[{"en":"The price tag was missing from the jacket.","zh":"这件夹克上的价格标签不见了。"},{"en":"Put your name on the luggage tag.","zh":"在行李标签上写下姓名。"}]},{"pos":"n.","meaning":"附加语；附加问句","definition":"a short expression added at the end of a sentence","examples":[{"en":"The teacher explained the question tag at the end of the sentence.","zh":"老师解释了句末的附加疑问部分。"},{"en":"Add a suitable tag to turn the statement into a question.","zh":"加上适当的附加语，把陈述句变成问句。"}]},{"pos":"v.","meaning":"贴标签；标记","definition":"to attach a label or identifying mark","examples":[{"en":"The researchers tagged each sample with a number.","zh":"研究人员给每个样本贴上了编号。"},{"en":"Please tag the photograph with the correct location.","zh":"请给这张照片标记正确地点。"}]},{"pos":"v.","meaning":"跟随（tag along）","definition":"to go with others without taking the leading role","examples":[{"en":"My younger brother wanted to tag along on the trip.","zh":"弟弟想跟着我们一起去旅行。"},{"en":"She tagged along with the group to the museum.","zh":"她跟着一行人去了博物馆。"}]},{"pos":"v.","meaning":"附加（tag on）","definition":"to add something at the end","examples":[{"en":"He tagged a short note onto the email.","zh":"他在邮件末尾附上了一条简短说明。"},{"en":"The organiser tagged on an extra session.","zh":"组织者又增加了一节活动。"}]}],"tan":[{"pos":"n.","meaning":"棕褐色","definition":"a light brown colour","examples":[{"en":"She chose a pale tan for the walls.","zh":"她选择浅棕褐色刷墙。"},{"en":"The bag comes in black and tan.","zh":"这款包有黑色和棕褐色。"}]},{"pos":"n.","meaning":"晒黑的肤色","definition":"a brown colour of skin after sun exposure","examples":[{"en":"His tan faded during winter.","zh":"他晒黑的肤色在冬季褪去。"},{"en":"She returned from holiday with a tan.","zh":"她度假回来皮肤晒黑了。"}]},{"pos":"v.","meaning":"晒黑；晒成棕褐色","definition":"to become or make skin browner in the sun","examples":[{"en":"His arms tanned during the outdoor work.","zh":"户外工作使他的手臂晒黑了。"},{"en":"She tans easily in summer.","zh":"她夏天容易晒黑。"}]},{"pos":"v.","meaning":"鞣制皮革","definition":"to treat animal skin to make leather","examples":[{"en":"The workshop tans hides using traditional methods.","zh":"作坊用传统方法鞣制兽皮。"},{"en":"The leather was carefully tanned.","zh":"皮革经过仔细鞣制。"}]}],"tangibly":[{"pos":"adv.","meaning":"可感知地；切实地；有形地","definition":"In a clear, real, or measurable way.","examples":[{"en":"The repairs tangibly improved living conditions.","zh":"维修切实改善了居住条件。"},{"en":"The tension was tangibly present in the room.","zh":"房间里的紧张气氛清晰可感。"}]}],"tanker":[{"pos":"n.","meaning":"油轮；液体运输船","definition":"a ship designed to carry liquid in large quantities","examples":[{"en":"The tanker waited outside the harbour.","zh":"油轮在港口外等待。"},{"en":"Workers inspected the tanker's cargo tanks.","zh":"工人检查了油轮的货舱。"}]},{"pos":"n.","meaning":"油罐车；罐车","definition":"a road vehicle that carries liquid in a large tank","examples":[{"en":"A milk tanker arrived at the dairy.","zh":"一辆牛奶罐车到达乳品厂。"},{"en":"The tanker delivered water to the remote village.","zh":"罐车把水运到了偏远村庄。"}]},{"pos":"n.","meaning":"空中加油机","definition":"an aircraft equipped to refuel other aircraft","examples":[{"en":"The tanker met the aircraft above the ocean.","zh":"加油机在海洋上空与飞机会合。"},{"en":"The museum displayed a model of an aerial tanker.","zh":"博物馆展出了一架空中加油机模型。"}]}],"tap":[{"pos":"v.","meaning":"轻拍；轻敲","definition":"to hit lightly","examples":[{"en":"She tapped the door twice.","zh":"她轻敲门两下。"},{"en":"He tapped my shoulder.","zh":"他轻拍我的肩膀。"}]},{"pos":"v.","meaning":"利用；开发资源","definition":"to make use of a source","examples":[{"en":"The project taps local knowledge.","zh":"项目利用当地知识。"},{"en":"They hope to tap a new market.","zh":"他们希望开发新市场。"}]}],"target":[{"pos":"n.","meaning":"目标；指标","definition":"A result that someone aims to achieve.","examples":[{"en":"The team met its monthly target.","zh":"团队达成了月度目标。"},{"en":"Set a realistic target for your study time.","zh":"为学习时间设定一个现实目标。"}]},{"pos":"n.","meaning":"靶子；攻击或关注对象","definition":"A person or thing aimed at.","examples":[{"en":"The arrow struck the target.","zh":"箭击中了靶子。"},{"en":"The building became a target for vandals.","zh":"建筑成了破坏者的目标。"}]},{"pos":"v.","meaning":"瞄准；面向；针对","definition":"To direct action or attention towards something.","examples":[{"en":"The campaign targets young readers.","zh":"这场活动面向年轻读者。"},{"en":"The programme targets areas with poor transport.","zh":"计划重点针对交通不便地区。"}]}],"tariff":[{"pos":"n.","meaning":"关税；关税税率","definition":"a tax charged on goods crossing a national border","examples":[{"en":"The report compares tariffs on imported goods.","zh":"报告比较了进口商品的关税。"},{"en":"A higher tariff increased the cost of the shipment.","zh":"较高的关税增加了这批货物的成本。"}]},{"pos":"n.","meaning":"价目表；收费标准","definition":"a published set of prices or charges","examples":[{"en":"The hotel tariff includes breakfast.","zh":"酒店收费标准包含早餐。"},{"en":"Customers can compare the two electricity tariffs.","zh":"顾客可以比较两种电价方案。"}]}],"taunt":[{"pos":"v.","meaning":"嘲笑；讥讽","definition":"to mock someone cruelly","examples":[{"en":"The spectators taunted the losing team.","zh":"观众嘲讽了落后的球队。"},{"en":"She refused to taunt her opponent.","zh":"她拒绝嘲笑对手。"}]},{"pos":"n.","meaning":"嘲弄的话；讥讽","definition":"a mocking or insulting remark","examples":[{"en":"He ignored the taunts.","zh":"他不理会讥讽。"},{"en":"The remark sounded like a taunt.","zh":"那番话听起来像嘲弄。"}]}],"taxation":[{"pos":"n.","meaning":"征税；税收制度","definition":"the system of collecting taxes","examples":[{"en":"Public services are funded through taxation.","zh":"公共服务通过税收获得资金。"},{"en":"Higher taxation may affect consumer spending.","zh":"加税可能影响消费者支出。"},{"en":"The report compares different systems of taxation.","zh":"这份报告比较不同税收制度。"}]}],"teamwork":[{"pos":"n.","meaning":"团队合作；协作","definition":"people working together towards a shared result","examples":[{"en":"The task requires patience and teamwork.","zh":"这项任务需要耐心和团队合作。"},{"en":"Good teamwork helped them finish before the deadline.","zh":"良好的协作帮助他们在截止日期前完成工作。"}]}],"tease":[{"pos":"v.","meaning":"逗弄；取笑","definition":"to make fun of someone playfully or unkindly","examples":[{"en":"His friends teased him about his hat.","zh":"朋友们拿他的帽子开玩笑。"},{"en":"She gently teased her brother.","zh":"她轻轻逗弄弟弟。"}]},{"pos":"v.","meaning":"缠着索要；强求（较少用）","definition":"to persistently ask or bother someone for something","examples":[{"en":"The children teased their parents for another story.","zh":"孩子们缠着父母再讲一个故事。"},{"en":"He teased her to reveal the surprise.","zh":"他缠着她说出惊喜内容。"}]},{"pos":"n.","meaning":"逗弄者；爱取笑的人","definition":"a person who enjoys teasing others","examples":[{"en":"Her brother is a terrible tease.","zh":"她哥哥特别爱逗人。"},{"en":"Everyone knew he was only a tease.","zh":"大家知道他只是爱开玩笑的人。"}]},{"pos":"n.","meaning":"逗弄；取笑","definition":"an act of playful provocation","examples":[{"en":"Her comment was meant as a tease.","zh":"她的评论本意是逗着玩。"},{"en":"The exchange ended with a friendly tease.","zh":"交谈以一句友善的玩笑结束。"}]}],"technical":[{"pos":"adj.","meaning":"技术的；工艺的；专业技术性的","definition":"Relating to practical skills, machinery, or specialist methods.","examples":[{"en":"The team solved a technical problem.","zh":"团队解决了一个技术问题。"},{"en":"The manual contains technical drawings.","zh":"手册包含技术图纸。"}]}],"technician":[{"pos":"n.","meaning":"技术员；技师","definition":"a worker trained to operate or repair specialist equipment","examples":[{"en":"A technician checked the laboratory equipment.","zh":"一位技术员检查了实验室设备。"},{"en":"The theatre technician adjusted the lights.","zh":"剧院技术员调好了灯光。"}]}],"technique":[{"pos":"n.","meaning":"技术；技巧；技法","definition":"a method or skill used for a task","examples":[{"en":"The course teaches basic painting techniques.","zh":"课程教授基本绘画技法。"},{"en":"Her technique improved with practice.","zh":"她的技术通过练习提高了。"}]}],"tedious":[{"pos":"adj.","meaning":"冗长乏味的；单调的","definition":"Boring because of length or repetition.","examples":[{"en":"Checking every entry was tedious work.","zh":"检查每个条目是项乏味工作。"},{"en":"The meeting became tedious after the third hour.","zh":"会议开到第三个小时后变得令人厌倦。"}]}],"teem":[{"pos":"v.","meaning":"充满；遍布（teem with）","definition":"to contain very large numbers of something","examples":[{"en":"The pond teems with insect life.","zh":"池塘里有大量昆虫。"},{"en":"The square was teeming with visitors.","zh":"广场上挤满了游客。"}]},{"pos":"v.","meaning":"下大雨；倾泻（teem down）","definition":"to fall heavily, especially of rain","examples":[{"en":"Rain teemed down throughout the afternoon.","zh":"整个下午都下着倾盆大雨。"},{"en":"It was teeming outside when we left the station.","zh":"我们离开车站时，外面大雨倾盆。"}]}],"telegraph":[{"pos":"n.","meaning":"电报机；电报系统","definition":"a system sending coded messages over distance","examples":[{"en":"The telegraph transformed long-distance communication.","zh":"电报改变了远距离通信。"},{"en":"The museum displays an early telegraph.","zh":"博物馆展出一台早期电报机。"}]},{"pos":"v.","meaning":"发电报","definition":"to send a message by telegraph","examples":[{"en":"They telegraphed the news to headquarters.","zh":"他们向总部发电报报告消息。"},{"en":"She telegraphed home after arriving.","zh":"她到达后向家里发了电报。"}]},{"pos":"v.","meaning":"无意中透露；预示","definition":"to reveal an intention before acting","examples":[{"en":"His glance telegraphed his next move.","zh":"他的目光泄露了下一步行动。"},{"en":"The opening scene telegraphs the ending.","zh":"开场暗示了结局。"}]}],"telescope":[{"pos":"n.","meaning":"望远镜","definition":"An instrument that makes distant objects appear larger.","examples":[{"en":"We viewed the Moon through a telescope.","zh":"我们用望远镜观测月球。"},{"en":"The telescope stands on a stable tripod.","zh":"望远镜架在稳固三脚架上。"}]}],"temper":[{"pos":"n.","meaning":"脾气；情绪","definition":"a person's usual mood or tendency to become angry","examples":[{"en":"He has a calm temper even under pressure.","zh":"即使有压力，他的脾气也很平和。"},{"en":"She lost her temper when the machine failed again.","zh":"机器再次出故障时，她发了脾气。"}]},{"pos":"v.","meaning":"缓和；调节","definition":"to reduce the strength or harshness of something","examples":[{"en":"Her criticism was tempered with kindness.","zh":"她的批评因语气友善而缓和了。"},{"en":"The sea breeze tempers the afternoon heat.","zh":"海风缓解了午后的炎热。"}]}],"temporary":[{"pos":"adj.","meaning":"临时的；暂时的","definition":"lasting for a limited time","examples":[{"en":"The office moved to temporary premises.","zh":"办公室搬到了临时场所。"},{"en":"The closure is temporary.","zh":"关闭是暂时的。"}]}],"tempt":[{"pos":"v.","meaning":"引诱；诱使；吸引","definition":"To make someone want something or want to do something.","examples":[{"en":"The low price tempted me to buy the jacket.","zh":"低价吸引我买这件夹克。"},{"en":"The smell of coffee tempted us inside.","zh":"咖啡香气吸引我们走进去。"}]}],"tenable":[{"pos":"adj.","meaning":"站得住脚的；可维持的","definition":"able to be supported by reasoning or evidence","examples":[{"en":"The new evidence made that argument less tenable.","zh":"新证据使那个论点不那么站得住脚了。"},{"en":"They proposed a tenable explanation for the result.","zh":"他们对结果提出了一个合理可信的解释。"}]},{"pos":"adj.","meaning":"可防守的","definition":"capable of being held against attack","examples":[{"en":"The soldiers searched for a tenable position on higher ground.","zh":"士兵们在高地寻找可防守的阵地。"},{"en":"The ruined walls no longer offered a tenable defence.","zh":"破败的城墙已无法提供可维持的防御。"}]}],"tenant":[{"pos":"n.","meaning":"承租人；租户；房客","definition":"a person who pays rent to use a home or building","examples":[{"en":"The tenant must pay rent on the first day of each month.","zh":"租户必须在每月第一天付租金。"},{"en":"Each tenant has a key to the main entrance.","zh":"每位租户都有大门钥匙。"},{"en":"The landlord gave the tenant a copy of the agreement.","zh":"房东给了租户一份协议副本。"}]},{"pos":"n.","meaning":"佃户；土地承租人","definition":"a person who rents land to farm","examples":[{"en":"The tenant paid the landowner after the harvest.","zh":"佃户在收获后向地主支付租金。"},{"en":"Several tenants cultivated small plots on the estate.","zh":"几位佃户在庄园里耕种小块土地。"}]}],"tend":[{"pos":"v.","meaning":"倾向于；往往；趋于","definition":"To be likely to behave or develop in a particular way.","examples":[{"en":"Prices tend to rise during the holiday season.","zh":"假日期间价格往往上涨。"},{"en":"She tends to speak quietly.","zh":"她通常说话很轻。"}]},{"pos":"v.","meaning":"照料；照顾；招待","definition":"To look after someone or something.","examples":[{"en":"He tends the garden every morning.","zh":"他每天早晨照料花园。"},{"en":"The nurse tended the injured child.","zh":"护士照顾受伤的孩子。"}]}],"tendency":[{"pos":"n.","meaning":"倾向；趋势","definition":"a likelihood of behaving or developing in a particular way","examples":[{"en":"The material has a tendency to shrink when washed.","zh":"这种材料水洗时容易缩水。"},{"en":"The figures show a tendency towards longer journeys.","zh":"这些数字显示出出行距离变长的趋势。"}]}],"tender":[{"pos":"adj.","meaning":"嫩的；柔软的","definition":"soft and easy to cut or chew","examples":[{"en":"Cook until the vegetables are tender.","zh":"煮到蔬菜软嫩。"},{"en":"The meat was tender.","zh":"肉很嫩。"}]},{"pos":"adj.","meaning":"脆弱敏感的；触痛的","definition":"delicate or painful when touched","examples":[{"en":"The bruised area was still tender.","zh":"淤伤部位触碰时仍疼。"},{"en":"Protect the tender young shoots.","zh":"保护娇嫩的幼芽。"}]},{"pos":"adj.","meaning":"温柔的；慈爱的","definition":"gentle and caring","examples":[{"en":"She gave the child a tender smile.","zh":"她给孩子一个温柔的微笑。"},{"en":"The letter expresses tender affection.","zh":"信中表达了温柔的爱意。"}]}],"tense":[{"pos":"adj.","meaning":"拉紧的；紧绷的；紧张的","definition":"Tight or showing mental strain.","examples":[{"en":"Her shoulders were tense.","zh":"她的肩膀紧绷。"},{"en":"The room fell silent during a tense discussion.","zh":"紧张讨论中，房间安静了下来。"}]},{"pos":"v.","meaning":"拉紧；绷紧","definition":"To make or become tight.","examples":[{"en":"He tensed his muscles before lifting.","zh":"搬举前，他绷紧了肌肉。"},{"en":"She tensed when she heard the noise.","zh":"听到响声，她浑身绷紧。"}]}],"tensile":[{"pos":"adj.","meaning":"拉力的；张力的","definition":"relating to a force that stretches a material","examples":[{"en":"The test measures the cable's tensile strength.","zh":"这项测试测量电缆的抗拉强度。"},{"en":"Engineers calculated the tensile stress in the rod.","zh":"工程师计算了杆件中的拉应力。"}]},{"pos":"adj.","meaning":"可拉伸的；有延展性的","definition":"able to be stretched or drawn out","examples":[{"en":"The designer chose a tensile fabric for the curved frame.","zh":"设计师为弧形框架选择了可拉伸的织物。"},{"en":"A thin tensile layer allowed the cover to expand.","zh":"一层薄薄的可延展材料让覆盖物能够伸展。"}]}],"terminal":[{"pos":"n.","meaning":"终点站；航站楼","definition":"a station at the end of a route or an airport building","examples":[{"en":"Passengers waited in the terminal.","zh":"乘客在航站楼等候。"},{"en":"The bus terminal is near the river.","zh":"汽车总站在河边。"}]},{"pos":"n.","meaning":"终端；接线端","definition":"an endpoint in a computer or electrical system","examples":[{"en":"She entered the data at a terminal.","zh":"她在终端输入数据。"},{"en":"Connect the wire to the correct terminal.","zh":"把电线连接到正确接线端。"}]},{"pos":"adj.","meaning":"末端的；终点的","definition":"at the end of something","examples":[{"en":"The diagram shows the terminal branch.","zh":"图中展示末端分支。"},{"en":"The terminal section of the route is closed.","zh":"路线的末段关闭了。"}]}],"terminology":[{"pos":"n.","meaning":"术语；专门用语","definition":"The specialised vocabulary of a subject.","examples":[{"en":"The guide explains basic medical terminology.","zh":"指南解释了基本医学术语。"},{"en":"Avoid unfamiliar terminology when addressing beginners.","zh":"向初学者讲话时，避免使用陌生术语。"}]}],"terrace":[{"pos":"n.","meaning":"露台；平台","definition":"a flat open area beside a building","examples":[{"en":"We ate breakfast on the terrace.","zh":"我们在露台上吃早餐。"},{"en":"The terrace overlooks the garden.","zh":"露台俯瞰着花园。"}]},{"pos":"n.","meaning":"梯田；台地","definition":"a level step cut into sloping land","examples":[{"en":"Farmers grow rice on terraces along the hillside.","zh":"农民在山坡的梯田里种水稻。"},{"en":"Each terrace holds water for the crops.","zh":"每一层梯田都蓄水供作物使用。"}]},{"pos":"n.","meaning":"排屋；一排相连房屋","definition":"a row of houses joined along their sides","examples":[{"en":"They live in a Victorian terrace near the park.","zh":"他们住在公园附近的一排维多利亚式住宅中。"},{"en":"The terrace contains six narrow houses.","zh":"这排建筑包含六栋狭长的房子。"}]}],"terrain":[{"pos":"n.","meaning":"地形；地势","definition":"the physical features of an area of land","examples":[{"en":"The vehicle handles rough terrain.","zh":"车辆能应对崎岖地形。"},{"en":"The map shows the mountainous terrain.","zh":"地图显示了山地地形。"}]}],"terrestrial":[{"pos":"adj.","meaning":"陆地的；陆生的","definition":"Living or occurring on land.","examples":[{"en":"The reserve protects terrestrial and aquatic habitats.","zh":"保护区保护陆地和水生栖息地。"},{"en":"Some animals moved from aquatic to terrestrial life.","zh":"有些动物从水生转为陆生。"}]},{"pos":"adj.","meaning":"地球的","definition":"Relating to the planet Earth.","examples":[{"en":"The instrument measures terrestrial radiation.","zh":"仪器测量地球辐射。"},{"en":"The study compares terrestrial rocks with lunar samples.","zh":"研究比较了地球岩石与月球样本。"}]}],"terrify":[{"pos":"v.","meaning":"使恐惧；使惊吓","definition":"to frighten someone very strongly","examples":[{"en":"The sudden noise terrified the child.","zh":"突如其来的声响吓坏了孩子。"},{"en":"The thought of speaking on stage used to terrify her.","zh":"她过去一想到上台讲话就十分害怕。"}]}],"territory":[{"pos":"n.","meaning":"领土；地域","definition":"land controlled by a country or group","examples":[{"en":"The river forms the edge of the territory.","zh":"这条河构成了这片领土的边界。"},{"en":"The map shows the island's surrounding territory.","zh":"地图显示了岛屿周边的地域。"}]},{"pos":"n.","meaning":"领域；范围","definition":"an area of knowledge, experience, or activity","examples":[{"en":"Online teaching was new territory for him.","zh":"在线教学对他来说是一个新领域。"},{"en":"The discussion moved into unfamiliar territory.","zh":"讨论进入了一个陌生领域。"}]}],"textile":[{"pos":"n.","meaning":"纺织品；织物","definition":"Cloth made by weaving or other methods.","examples":[{"en":"The museum displays traditional textiles.","zh":"博物馆展出传统纺织品。"},{"en":"The factory exports textiles to several countries.","zh":"工厂向几个国家出口纺织品。"}]}],"texture":[{"pos":"n.","meaning":"质地；纹理","definition":"the surface structure or feel of a material","examples":[{"en":"The fabric has a rough texture.","zh":"这种织物质地粗糙。"},{"en":"The photograph captures the texture of the stone.","zh":"这张照片呈现了石头的纹理。"}]},{"pos":"n.","meaning":"口感","definition":"the way food feels in the mouth","examples":[{"en":"The soup has a smooth texture.","zh":"这道汤口感细腻。"},{"en":"Nuts add texture to the soft cake.","zh":"坚果为柔软的蛋糕增加了口感层次。"}]}],"theoretical":[{"pos":"adj.","meaning":"理论的","definition":"relating to ideas that explain how something works","examples":[{"en":"The course provides a theoretical foundation for later practice.","zh":"这门课程为后续实践提供理论基础。"},{"en":"Her research challenges the theoretical model.","zh":"她的研究对这个理论模型提出了质疑。"}]},{"pos":"adj.","meaning":"理论上的；假设的","definition":"possible in principle but not necessarily in practice","examples":[{"en":"The estimate represents the theoretical maximum.","zh":"这个估计代表理论上的最大值。"},{"en":"We discussed a theoretical situation in which all roads were closed.","zh":"我们讨论了所有道路都关闭的假设情况。"}]}],"theory":[{"pos":"n.","meaning":"理论；学说；原理","definition":"A system of ideas explaining facts or phenomena.","examples":[{"en":"The results support the theory.","zh":"结果支持该理论。"},{"en":"The course links theory with practical work.","zh":"课程把理论与实践相结合。"}]},{"pos":"n.","meaning":"看法；推测；假说","definition":"An explanation proposed without full proof.","examples":[{"en":"My theory is that the key fell behind the desk.","zh":"我的推测是钥匙掉到了书桌后面。"},{"en":"The police tested several theories about the disappearance.","zh":"警方检验了关于失踪的几种假说。"}]}],"therapy":[{"pos":"n.","meaning":"治疗；疗法","definition":"a method or process intended to improve a health condition","examples":[{"en":"The clinic offers several forms of therapy.","zh":"这家诊所提供几种治疗方式。"},{"en":"Her recovery involved months of physical therapy.","zh":"她的康复过程包括数月的物理治疗。"}]}],"thereby":[{"pos":"adv.","meaning":"从而；因此","definition":"as a result of the action just described","examples":[{"en":"The new route avoids the hill, thereby saving time.","zh":"新路线绕开了山坡，从而节省了时间。"},{"en":"She labelled each box, thereby making unpacking easier.","zh":"她给每个箱子贴上标签，从而使拆箱更方便。"}]}],"therefore":[{"pos":"adv.","meaning":"因此；所以","definition":"For that reason.","examples":[{"en":"The road was closed; therefore, we took another route.","zh":"道路关闭了，因此我们改走另一条路。"},{"en":"The sample is small and therefore may not be representative.","zh":"样本较小，因此可能不具代表性。"}]}],"thermal":[{"pos":"adj.","meaning":"热的；保温的","definition":"relating to heat or the retention of heat","examples":[{"en":"Thermal insulation reduces heat loss.","zh":"保温材料减少热量流失。"},{"en":"The camera detects thermal differences on the surface.","zh":"这台摄像机能检测表面的温度差异。"}]},{"pos":"n.","meaning":"上升热气流","definition":"a rising current of warm air","examples":[{"en":"The glider circled inside a thermal.","zh":"滑翔机在一股上升热气流中盘旋。"},{"en":"Large birds use thermals to gain height.","zh":"大型鸟类利用上升热气流提高飞行高度。"}]}],"thesis":[{"pos":"n.","meaning":"学位论文；论文","definition":"a long research document written for a degree","examples":[{"en":"She is writing a thesis on urban transport.","zh":"她正在写一篇关于城市交通的学位论文。"},{"en":"His thesis includes interviews with local residents.","zh":"他的论文包含对当地居民的访谈。"}]},{"pos":"n.","meaning":"论点；命题","definition":"a central proposition supported by argument","examples":[{"en":"The author develops the thesis that design affects behaviour.","zh":"作者论证了设计影响行为这一观点。"},{"en":"The final chapter returns to the book's main thesis.","zh":"最后一章回到了全书的核心论点。"}]}],"thigh":[{"pos":"n.","meaning":"大腿","definition":"The part of the leg between the hip and knee.","examples":[{"en":"The runner felt pain in her thigh.","zh":"跑步者感到大腿疼痛。"},{"en":"The shorts reach halfway down his thigh.","zh":"短裤长到他的大腿中部。"}]}],"thirsty":[{"pos":"adj.","meaning":"口渴的","definition":"feeling a need to drink","examples":[{"en":"We were thirsty after the long walk.","zh":"长途步行后，我们很渴。"},{"en":"The thirsty dog drank from its bowl.","zh":"口渴的狗喝起了碗里的水。"}]},{"pos":"adj.","meaning":"渴望的","definition":"strongly wanting something","examples":[{"en":"The students were thirsty for new ideas.","zh":"学生们渴望新思想。"},{"en":"She remained thirsty for knowledge throughout her life.","zh":"她一生都渴求知识。"}]}],"thorny":[{"pos":"adj.","meaning":"多刺的","definition":"having sharp thorns","examples":[{"en":"A thorny hedge surrounded the garden.","zh":"一道多刺的树篱环绕着花园。"},{"en":"She wore gloves to handle the thorny branches.","zh":"她戴着手套处理带刺的枝条。"}]},{"pos":"adj.","meaning":"棘手的；难处理的","definition":"involving difficult problems or disagreement","examples":[{"en":"The committee faced a thorny question about funding.","zh":"委员会面临一个棘手的经费问题。"},{"en":"They postponed the thorny issue until the next meeting.","zh":"他们把这个难题推迟到下次会议讨论。"}]}],"thoughtful":[{"pos":"adj.","meaning":"沉思的；认真思考的","definition":"Thinking carefully or showing careful consideration.","examples":[{"en":"He grew thoughtful after reading the letter.","zh":"读信后，他沉思起来。"},{"en":"She gave a thoughtful answer.","zh":"她给出了深思熟虑的回答。"}]},{"pos":"adj.","meaning":"体贴的；关心他人的","definition":"Showing consideration for other people's needs.","examples":[{"en":"It was thoughtful of you to bring an umbrella for me.","zh":"你为我带伞，真体贴。"},{"en":"Her thoughtful gift cheered him up.","zh":"她贴心的礼物让他高兴起来。"}]}],"threaten":[{"pos":"v.","meaning":"威胁；恐吓","definition":"to say or suggest that harm will be caused","examples":[{"en":"The letter threatened further action unless the problem was solved.","zh":"信中威胁说，如果问题得不到解决，将采取进一步行动。"},{"en":"He threatened to cancel the booking.","zh":"他威胁要取消预订。"}]},{"pos":"v.","meaning":"危及；预示危险","definition":"to put something at risk or indicate possible harm","examples":[{"en":"Rising water levels threaten the coastal road.","zh":"不断上升的水位威胁着沿海公路。"},{"en":"Dark clouds threatened rain during the ceremony.","zh":"典礼期间乌云密布，预示着可能下雨。"}]}],"threshold":[{"pos":"n.","meaning":"门槛；入口","definition":"the lower part of a doorway or the entrance itself","examples":[{"en":"He paused on the threshold before entering.","zh":"他进门前在门槛处停了一下。"},{"en":"Rainwater gathered outside the threshold.","zh":"雨水积在门槛外。"}]},{"pos":"n.","meaning":"阈值；界限","definition":"a level at which something begins or changes","examples":[{"en":"The alarm sounds when the temperature passes a threshold.","zh":"温度超过某个阈值时，警报就会响。"},{"en":"The study measured the threshold of hearing.","zh":"这项研究测量了听觉阈限。"}]},{"pos":"n.","meaning":"开端；起点","definition":"the beginning of a new stage or experience","examples":[{"en":"The town stood on the threshold of major change.","zh":"这座城镇正处于重大变革的开端。"},{"en":"She was on the threshold of a new career.","zh":"她即将开始新的职业生涯。"}]}],"thrifty":[{"pos":"adj.","meaning":"节俭的；节约的","definition":"Careful not to waste money or resources.","examples":[{"en":"Her thrifty habits helped her save for college.","zh":"节俭习惯帮助她攒下大学学费。"},{"en":"A thrifty cook makes use of leftovers.","zh":"节俭的厨师会利用剩菜。"}]}],"thrill":[{"pos":"v.","meaning":"使激动；使兴奋","definition":"to cause intense pleasure or excitement","examples":[{"en":"The chance to perform thrilled the young musicians.","zh":"演出的机会让年轻音乐家们十分兴奋。"},{"en":"The final goal thrilled the crowd.","zh":"最后一个进球令观众激动不已。"}]},{"pos":"v.","meaning":"因激动而颤动（thrill with/to）","definition":"to feel a sudden wave of strong emotion","examples":[{"en":"Her voice thrilled with excitement as she read the letter.","zh":"读信时，她的声音因激动而颤动。"},{"en":"He thrilled to the sound of the orchestra.","zh":"管弦乐队的声音令他心潮澎湃。"}]},{"pos":"n.","meaning":"激动；兴奋感","definition":"a sudden strong feeling of pleasure or excitement","examples":[{"en":"Winning the prize gave her a real thrill.","zh":"获奖让她真切地感到兴奋。"},{"en":"He still remembers the thrill of his first flight.","zh":"他仍记得第一次坐飞机的激动感。"}]}],"thrive":[{"pos":"v.","meaning":"茁壮成长；兴旺","definition":"to grow or develop successfully","examples":[{"en":"These plants thrive in moist soil.","zh":"这些植物在湿润土壤中茁壮成长。"},{"en":"Small businesses thrived after the station opened.","zh":"车站开通后，小企业蓬勃发展。"}]}],"throughout":[{"pos":"prep.","meaning":"遍及；在整个……期间","definition":"In every part of a place or during the whole of a period.","examples":[{"en":"The news spread throughout the country.","zh":"消息传遍全国。"},{"en":"She remained calm throughout the interview.","zh":"她在整个面试中保持冷静。"}]},{"pos":"adv.","meaning":"自始至终；到处","definition":"During the whole period or in every part.","examples":[{"en":"The team played well throughout.","zh":"球队全程表现出色。"},{"en":"The house has been renovated throughout.","zh":"房子各处都已翻修。"}]}],"thunder":[{"pos":"n.","meaning":"雷；雷声","definition":"the loud sound associated with lightning","examples":[{"en":"We heard thunder in the distance.","zh":"我们听到远处传来雷声。"},{"en":"A crash of thunder woke the baby.","zh":"一声巨雷惊醒了婴儿。"}]},{"pos":"v.","meaning":"打雷","definition":"to produce the sound of thunder","examples":[{"en":"It thundered all night over the hills.","zh":"山上一整夜都在打雷。"},{"en":"The sky darkened and began to thunder.","zh":"天空暗了下来，开始响雷。"}]},{"pos":"v.","meaning":"轰隆作响","definition":"to move or sound very loudly","examples":[{"en":"Heavy lorries thundered past the house.","zh":"重型卡车从房前轰隆驶过。"},{"en":"The waterfall thundered below the bridge.","zh":"瀑布在桥下轰鸣。"}]}],"tick off":[{"pos":"phr.v.","meaning":"勾选；打核对号","definition":"to mark items on a list as checked or completed","examples":[{"en":"Tick off each task when you finish it.","zh":"完成一项任务就打一个勾。"},{"en":"She ticked off the names as the guests arrived.","zh":"客人到达时，她逐一勾选名字。"}]},{"pos":"phr.v.","meaning":"责备；训斥（英式口语）","definition":"to tell someone that their behaviour was wrong","examples":[{"en":"The coach ticked him off for arriving late.","zh":"教练因他迟到而训斥了他。"},{"en":"She was ticked off for ignoring the instructions.","zh":"她因不听指示而受到了责备。"}]},{"pos":"phr.v.","meaning":"使生气（美式口语）","definition":"to annoy someone","examples":[{"en":"The repeated interruptions really ticked her off.","zh":"接二连三的打断让她很生气。"},{"en":"It ticks me off when people leave rubbish here.","zh":"有人把垃圾留在这里，这让我生气。"}]}],"tickle":[{"pos":"v.","meaning":"使发痒；挠痒","definition":"To touch lightly in a way that causes itching or laughter.","examples":[{"en":"The grass tickled her ankles.","zh":"草挠得她脚踝发痒。"},{"en":"He tickled the baby's feet.","zh":"他挠婴儿的脚逗乐。"}]},{"pos":"v.","meaning":"使高兴；逗乐","definition":"To amuse or please someone.","examples":[{"en":"The idea tickled his imagination.","zh":"这个想法激发了他的想象，令他开心。"},{"en":"She was tickled by the unexpected compliment.","zh":"意外的赞美让她很高兴。"}]},{"pos":"n.","meaning":"痒；挠痒","definition":"A light irritating feeling or touch.","examples":[{"en":"I felt a tickle in my throat.","zh":"我觉得喉咙发痒。"},{"en":"A tickle under the chin made the child giggle.","zh":"下巴被挠了一下，孩子咯咯笑起来。"}]}],"tighten":[{"pos":"v.","meaning":"拧紧；绷紧","definition":"to make something firmer or less loose","examples":[{"en":"Tighten the screws before using the chair.","zh":"使用椅子前先拧紧螺丝。"},{"en":"The rope tightened as the load was lifted.","zh":"负重升起时，绳子绷紧了。"}]},{"pos":"v.","meaning":"加强；使更严格","definition":"to make rules or control more restrictive","examples":[{"en":"The library tightened its borrowing rules.","zh":"图书馆收紧了借阅规定。"},{"en":"The manager wants to tighten control over spending.","zh":"经理希望加强支出控制。"}]}],"tillable":[{"pos":"adj.","meaning":"可耕种的","definition":"suitable for being worked and used to grow crops","examples":[{"en":"Only a small part of the island is tillable.","zh":"岛上只有一小部分土地可以耕种。"},{"en":"The survey identified more tillable land near the river.","zh":"调查发现河边有更多可耕地。"}]}],"tilt":[{"pos":"v.","meaning":"倾斜；使倾侧","definition":"To move into a sloping position.","examples":[{"en":"Tilt the bottle slowly.","zh":"慢慢倾斜瓶子。"},{"en":"She tilted her head to listen.","zh":"她歪着头倾听。"}]},{"pos":"v.","meaning":"使倾向；偏向","definition":"To shift a balance or preference.","examples":[{"en":"The evidence tilted opinion in her favour.","zh":"证据使舆论转而支持她。"},{"en":"The rules tilt the competition towards larger firms.","zh":"规则使竞争偏向大公司。"}]},{"pos":"n.","meaning":"倾斜；倾侧；偏向","definition":"A sloping position or change of balance.","examples":[{"en":"The shelf has a slight tilt.","zh":"搁板有点倾斜。"},{"en":"The poll suggests a tilt towards the younger candidate.","zh":"民调显示选民倾向于较年轻的候选人。"}]}],"timber":[{"pos":"n.","meaning":"木材；木料","definition":"wood prepared for building or other uses","examples":[{"en":"The house was built from locally grown timber.","zh":"这栋房子使用当地木材建造。"},{"en":"The company buys timber from managed forests.","zh":"这家公司从受管理的森林采购木材。"}]},{"pos":"n.","meaning":"大梁；栋木","definition":"a large wooden beam used in a structure","examples":[{"en":"The old roof timbers needed repair.","zh":"旧屋顶的大梁需要维修。"},{"en":"Builders replaced a damaged timber above the doorway.","zh":"施工人员更换了门口上方一根损坏的木梁。"}]}],"timid":[{"pos":"adj.","meaning":"胆小的；羞怯的","definition":"lacking confidence or easily frightened","examples":[{"en":"The timid child spoke in a quiet voice.","zh":"这个羞怯的孩子说话声音很轻。"},{"en":"A timid deer emerged from the trees.","zh":"一只胆小的鹿从树林中走了出来。"}]}],"tolerate":[{"pos":"v.","meaning":"容忍；容许；耐受","definition":"To allow or endure something without preventing it.","examples":[{"en":"The school will not tolerate bullying.","zh":"学校不会容忍霸凌。"},{"en":"These plants tolerate dry conditions.","zh":"这些植物能耐受干旱条件。"}]}],"tome":[{"pos":"n.","meaning":"大部头书；巨著","definition":"a large, often scholarly book","examples":[{"en":"The historian placed a heavy tome on the desk.","zh":"历史学家把一部厚重的著作放在书桌上。"},{"en":"She spent the weekend reading a tome on architecture.","zh":"她整个周末都在读一部建筑学巨著。"}]}],"topple":[{"pos":"v.","meaning":"倒下；推倒","definition":"to fall or cause something to fall from an upright position","examples":[{"en":"The strong wind toppled the empty bins.","zh":"大风吹倒了空垃圾桶。"},{"en":"The tower of blocks began to topple.","zh":"积木塔开始倒塌。"}]},{"pos":"v.","meaning":"推翻；使失去权力","definition":"to remove a person or group from power","examples":[{"en":"The vote toppled the unpopular leadership.","zh":"投票使不受欢迎的领导层下台。"},{"en":"The scandal threatened to topple the administration.","zh":"这起丑闻可能使政府倒台。"}]}],"topsoil":[{"pos":"n.","meaning":"表层土；表土","definition":"The upper layer of soil where plants commonly grow.","examples":[{"en":"Heavy rain washed away the topsoil.","zh":"大雨冲走了表土。"},{"en":"The gardeners added fresh topsoil to the beds.","zh":"园丁给种植畦添加了新表土。"}]}],"torment":[{"pos":"n.","meaning":"折磨；痛苦","definition":"severe physical or mental suffering","ipa":"/ˈtɔːment/","examples":[{"en":"Waiting for the missing letter was a torment.","zh":"等待那封不见的信令人备受煎熬。"},{"en":"The character's inner torment drives the story.","zh":"人物内心的痛苦推动着故事发展。"}]},{"pos":"v.","meaning":"使痛苦；折磨","definition":"to cause continuing distress","ipa":"/tɔːˈment/","examples":[{"en":"Regret tormented him for years.","zh":"懊悔折磨了他多年。"},{"en":"The unanswered question continued to torment her.","zh":"那个没有答案的问题一直困扰着她。"}]},{"pos":"v.","meaning":"烦扰；戏弄；纠缠","definition":"to repeatedly annoy or tease someone","ipa":"/tɔːˈment/","examples":[{"en":"The older children tormented him with constant teasing.","zh":"大孩子们不断取笑他，让他烦恼。"},{"en":"Mosquitoes tormented the campers all evening.","zh":"蚊子整个晚上都在骚扰露营者。"}]}],"torrent":[{"pos":"n.","meaning":"急流；洪流","definition":"a powerful fast-moving flow of water","examples":[{"en":"Heavy rain turned the stream into a torrent.","zh":"大雨把小溪变成了急流。"},{"en":"A torrent rushed down the narrow valley.","zh":"一股洪流冲下狭窄的山谷。"}]},{"pos":"n.","meaning":"大量涌现；连发","definition":"a sudden large flow of words or reactions","examples":[{"en":"The announcement produced a torrent of questions.","zh":"这项公告引来了一连串问题。"},{"en":"She faced a torrent of criticism after the decision.","zh":"决定作出后，她面临大量批评。"}]}],"tortoise":[{"pos":"n.","meaning":"陆龟；龟","definition":"A land reptile with a hard shell.","examples":[{"en":"The tortoise moved slowly across the path.","zh":"陆龟慢慢爬过小路。"},{"en":"A tortoise can withdraw its head into its shell.","zh":"陆龟能把头缩进壳里。"}]},{"pos":"n.","meaning":"行动迟缓的人（比喻）","definition":"Someone who moves or works slowly.","examples":[{"en":"He was the tortoise of the group, arriving last on every walk.","zh":"他是队伍中的慢性子，每次步行都最后到。"},{"en":"The faster workers jokingly called him a tortoise.","zh":"动作快的工人开玩笑叫他慢乌龟。"}]}],"tough":[{"pos":"adj.","meaning":"棘手的；难办的","definition":"difficult to deal with or accomplish","examples":[{"en":"Choosing between the offers was a tough decision.","zh":"在几个录用机会之间选择是个艰难决定。"},{"en":"The team faced a tough challenge.","zh":"团队面临一个棘手的挑战。"}]},{"pos":"adj.","meaning":"坚韧的；强壮的","definition":"strong enough to resist difficulty or damage","examples":[{"en":"The bag is made from tough fabric.","zh":"这个包用结实耐用的布料制成。"},{"en":"These tough plants survive cold winters.","zh":"这些生命力强的植物能熬过寒冬。"}]},{"pos":"adj.","meaning":"嚼不烂的；老的","definition":"difficult to cut or chew, especially of food","examples":[{"en":"The meat was too tough to enjoy.","zh":"肉太老，吃起来不舒服。"},{"en":"Long cooking made the vegetables tough and dry.","zh":"长时间烹煮使蔬菜变得干韧。"}]}],"townscape":[{"pos":"n.","meaning":"市镇景观；市镇风貌","definition":"the visual appearance of a town and its buildings","examples":[{"en":"The church tower dominates the townscape.","zh":"教堂塔楼是市镇景观中的显著建筑。"},{"en":"The proposal aims to preserve the historic townscape.","zh":"提案旨在保护历史悠久的市镇风貌。"}]}],"toxic":[{"pos":"adj.","meaning":"中毒的；毒素引起的","definition":"Affected by or caused by a poison or toxin.","examples":[{"en":"The study examined toxic damage to liver cells.","zh":"研究检查了毒素引起的肝细胞损伤。"},{"en":"The physician investigated a suspected toxic reaction.","zh":"医生调查了一起疑似中毒反应。"}]},{"pos":"adj.","meaning":"有毒的；毒性的","definition":"Poisonous or capable of causing harm.","examples":[{"en":"The factory safely stores toxic chemicals.","zh":"工厂安全储存有毒化学品。"},{"en":"The investigation measured toxic substances in the water.","zh":"调查测量了水中的有毒物质。"}]}],"toxin":[{"pos":"n.","meaning":"毒素","definition":"a poisonous substance produced by a living organism","examples":[{"en":"The laboratory tested the water for a bacterial toxin.","zh":"实验室检测水中是否存在一种细菌毒素。"},{"en":"Some plants produce toxins that discourage insects.","zh":"一些植物会产生毒素以阻止昆虫取食。"}]}],"trace":[{"pos":"v.","meaning":"追踪；查出","definition":"to find someone or something by following evidence","examples":[{"en":"The team traced the fault to a damaged cable.","zh":"团队查出故障源于一根受损电缆。"},{"en":"They traced the missing package to a regional depot.","zh":"他们追踪到丢失包裹在一个地区仓库中。"}]},{"pos":"v.","meaning":"追溯","definition":"to follow the origin or development of something","examples":[{"en":"The book traces the history of public libraries.","zh":"这本书追溯了公共图书馆的历史。"},{"en":"She traced her family roots to a coastal village.","zh":"她追溯到家族起源于一个沿海村庄。"}]},{"pos":"v.","meaning":"描摹；沿线描画","definition":"to copy or follow the outline of a shape","examples":[{"en":"Place thin paper over the map and trace the river.","zh":"把薄纸放在地图上，描出河流。"},{"en":"He traced a circle in the dust with his finger.","zh":"他用手指在灰尘中画了一个圆。"}]},{"pos":"n.","meaning":"痕迹；踪迹","definition":"a sign that something existed or happened","examples":[{"en":"The storm left little trace on the stone walls.","zh":"暴风雨几乎没在石墙上留下痕迹。"},{"en":"No trace of the missing document was found.","zh":"没有找到那份丢失文件的踪迹。"}]},{"pos":"n.","meaning":"微量；少许","definition":"a very small amount","examples":[{"en":"The test detected a trace of salt.","zh":"检测发现了微量盐分。"},{"en":"There was a trace of sadness in her voice.","zh":"她的声音里有一丝悲伤。"}]}],"track":[{"pos":"n.","meaning":"小路；车辙道","definition":"A narrow path or rough road.","examples":[{"en":"A muddy track leads to the farm.","zh":"一条泥泞小路通向农场。"},{"en":"We followed the forest track.","zh":"我们沿着林间小路行走。"}]},{"pos":"n.","meaning":"跑道；轨道","definition":"A prepared route for racing or rails for trains.","examples":[{"en":"The athletes trained on the track.","zh":"运动员在跑道上训练。"},{"en":"Workers repaired the railway track.","zh":"工人修复了铁轨。"}]},{"pos":"v.","meaning":"跟踪；追踪","definition":"To follow movement or progress.","examples":[{"en":"Researchers tracked the birds with small devices.","zh":"研究人员用小型装置追踪鸟类。"},{"en":"The app tracks your daily spending.","zh":"应用记录你的每日支出。"}]}],"track and field":[{"pos":"n.","meaning":"田径","definition":"sports involving running, jumping, and throwing","examples":[{"en":"She joined the school track and field team.","zh":"她加入了学校田径队。"},{"en":"The stadium hosts track and field events each summer.","zh":"这个体育场每年夏天举办田径比赛。"}]}],"tradition":[{"pos":"n.","meaning":"传统；惯例","definition":"a custom passed from one generation to another","examples":[{"en":"Cooking together is an important family tradition.","zh":"一起做饭是一项重要的家庭传统。"},{"en":"This tradition has continued for generations.","zh":"这项传统已延续数代。"},{"en":"Modern lifestyles can make it harder to maintain tradition.","zh":"现代生活方式可能使保持传统更加困难。"}]}],"traditional":[{"pos":"adj.","meaning":"传统的；惯例的","definition":"Based on established customs or long-standing practices.","examples":[{"en":"The festival includes traditional dancing.","zh":"节日包含传统舞蹈。"},{"en":"They restored the roof using traditional methods.","zh":"他们用传统方法修复屋顶。"}]},{"pos":"adj.","meaning":"口传的；代代相传的","definition":"Passed down through generations, especially by oral transmission.","examples":[{"en":"She collected traditional tales from village elders.","zh":"她向村中长者搜集口传故事。"},{"en":"The melody belongs to a traditional song.","zh":"这段旋律属于一首世代相传的歌曲。"}]}],"tragic":[{"pos":"adj.","meaning":"悲惨的","definition":"causing great sadness, often through loss or suffering","examples":[{"en":"The accident had tragic consequences for the village.","zh":"这场事故给村庄带来了悲惨后果。"},{"en":"The documentary tells a tragic story of displacement.","zh":"这部纪录片讲述了一个流离失所的悲惨故事。"}]},{"pos":"adj.","meaning":"悲剧的","definition":"belonging to the dramatic form of tragedy","examples":[{"en":"The play centres on a tragic hero.","zh":"这出戏以一位悲剧英雄为中心。"},{"en":"The final scene completes the tragic structure of the drama.","zh":"最后一幕完成了这部戏的悲剧结构。"}]}],"training":[{"pos":"n.","meaning":"培训","definition":"practice and instruction to develop skills","examples":[{"en":"All new staff receive safety training.","zh":"所有新员工都接受安全培训。"},{"en":"The training takes place in the conference room.","zh":"培训在会议室举行。"},{"en":"Practical training helps employees use the software confidently.","zh":"实操培训帮助员工熟练使用软件。"}]}],"tram":[{"pos":"n.","meaning":"有轨电车","definition":"A public passenger vehicle running on rails in streets.","examples":[{"en":"The tram stops outside the museum.","zh":"电车停在博物馆外面。"},{"en":"We took a tram across the city.","zh":"我们乘电车穿过城市。"}]},{"pos":"n.","meaning":"电车轨道；矿车轨道","definition":"A track on which trams or small industrial vehicles run.","examples":[{"en":"The old tram ran from the quarry to the wharf.","zh":"旧矿车轨道从采石场通往码头。"},{"en":"Sections of the disused tram remain beside the mine.","zh":"废弃轨道的部分路段仍留在矿井旁。"}]},{"pos":"v.","meaning":"乘电车；用轨道车辆运送","definition":"To travel by tram or move goods on a tramway.","examples":[{"en":"We trammed into the town centre.","zh":"我们乘电车进了市中心。"},{"en":"Workers trammed the ore to the loading area.","zh":"工人用轨道车辆把矿石运到装载区。"}]}],"tramp":[{"pos":"v.","meaning":"跋涉；沉重地步行","definition":"to walk for a long distance with heavy steps","examples":[{"en":"We tramped through the forest until sunset.","zh":"我们在森林中跋涉到日落。"},{"en":"The hikers tramped along the muddy path.","zh":"徒步者沉重地走在泥泞的小路上。"}]},{"pos":"v.","meaning":"踩踏","definition":"to step heavily on something","examples":[{"en":"Visitors had tramped down the grass near the gate.","zh":"游客踩倒了大门附近的草。"},{"en":"Workers tramped the loose soil flat.","zh":"工人把松土踩平了。"}]},{"pos":"n.","meaning":"长途步行；跋涉","definition":"a long walk, often over difficult ground","examples":[{"en":"The cabin was a two-hour tramp from the road.","zh":"从公路到小木屋需要跋涉两小时。"},{"en":"We enjoyed a long tramp across the moor.","zh":"我们在荒原上长途步行，十分尽兴。"}]},{"pos":"n.","meaning":"流浪者（旧式称呼）","definition":"a person without a fixed home who travels on foot","examples":[{"en":"The old story follows a tramp looking for work.","zh":"这个老故事讲述了一个寻找工作的流浪者。"},{"en":"The novel portrays the tramp with sympathy.","zh":"小说对这位流浪者作了富有同情心的描写。"}]}],"tranquility":[{"pos":"n.","meaning":"宁静；安宁","definition":"a calm and peaceful state","examples":[{"en":"We enjoyed the tranquility of the empty beach.","zh":"我们享受着无人海滩的宁静。"},{"en":"The garden offers a place of tranquility in the busy city.","zh":"花园在繁忙城市中提供了一处安宁之地。"}]}],"transaction":[{"pos":"n.","meaning":"交易；业务","definition":"An exchange or business deal.","examples":[{"en":"The bank recorded the transaction.","zh":"银行记录了这笔交易。"},{"en":"Both parties signed documents to complete the transaction.","zh":"双方签署文件，完成交易。"}]},{"pos":"n.","meaning":"办理；处理","definition":"The carrying out of business or an activity.","examples":[{"en":"The office handles the transaction of official business.","zh":"这个办公室办理公务。"},{"en":"Clear procedures speed the transaction of routine matters.","zh":"明确程序加快了日常事务的处理。"}]},{"pos":"n.","meaning":"学报；会报（通常用transactions）","definition":"Published records or papers of a learned society.","examples":[{"en":"The paper appeared in the society's transactions.","zh":"论文发表于该学会的学报。"},{"en":"The library holds a complete set of the association's transactions.","zh":"图书馆收藏了该协会会报的全套资料。"}]}],"transcend":[{"pos":"v.","meaning":"超越；胜过","definition":"to go beyond a limit or usual category","examples":[{"en":"The music transcends language barriers.","zh":"这段音乐超越了语言障碍。"},{"en":"Their friendship transcended political differences.","zh":"他们的友谊超越了政治分歧。"}]}],"transcribe":[{"pos":"v.","meaning":"转写；抄录","definition":"to produce a written copy of speech or another text","examples":[{"en":"She transcribed the interview from the recording.","zh":"她根据录音转写了采访内容。"},{"en":"The students transcribed the old handwritten letters.","zh":"学生们抄录了那些古老的手写信件。"}]},{"pos":"v.","meaning":"改编乐曲","definition":"to arrange music for a different instrument or form","examples":[{"en":"He transcribed the melody for solo guitar.","zh":"他把这段旋律改编为吉他独奏曲。"},{"en":"The pianist transcribed several folk songs.","zh":"钢琴家改编了几首民歌。"}]}],"transcript":[{"pos":"n.","meaning":"文字记录；抄本；副本","definition":"A written record or copy of spoken or written material.","examples":[{"en":"The interview transcript was checked for errors.","zh":"访谈文字记录经过了错误检查。"},{"en":"She requested a transcript of the hearing.","zh":"她申请了听证会的文字记录。"}]}],"transcription":[{"pos":"n.","meaning":"抄写；转写","definition":"the process of turning speech or writing into a written copy","examples":[{"en":"The interview required careful transcription.","zh":"这次采访需要仔细转写。"},{"en":"Errors occurred during the transcription of the handwritten notes.","zh":"抄写手写笔记的过程中出现了错误。"}]},{"pos":"n.","meaning":"抄本；转写文本","definition":"a written copy of recorded speech or another text","examples":[{"en":"She checked the transcription against the recording.","zh":"她对照录音检查了转写文本。"},{"en":"A full transcription of the speech is available online.","zh":"演讲的完整转写稿可以在线查阅。"}]},{"pos":"n.","meaning":"乐曲改编","definition":"an arrangement of music for different instruments or voices","examples":[{"en":"The concert included a piano transcription of the song.","zh":"音乐会演奏了这首歌的钢琴改编曲。"},{"en":"He prepared a transcription for a smaller orchestra.","zh":"他为一个较小的管弦乐队编写了改编谱。"}]}],"transfer":[{"pos":"v.","meaning":"转账；汇款","definition":"to move money from one account to another","examples":[{"en":"You can transfer money using the banking app.","zh":"你可以通过银行应用转账。"},{"en":"Please transfer the payment to the account shown below.","zh":"请将款项转入下方列出的账户。"}],"ipa":"/trænsˈfɜː/"},{"pos":"v.","meaning":"搬移；转移（物品、人员或数据）","definition":"to move something or someone from one place to another","examples":[{"en":"We need to transfer the files to a secure server.","zh":"我们需要把文件转移到安全服务器。"},{"en":"The patient was transferred to a larger hospital.","zh":"病人被转往一家更大的医院。"}],"ipa":"/trænsˈfɜː/"},{"pos":"v.","meaning":"调动；转学；转会","definition":"to change or move someone to a different organisation or position","examples":[{"en":"She transferred to a school nearer her home.","zh":"她转学到了一所离家更近的学校。"},{"en":"The company transferred him to its northern office.","zh":"公司把他调到北部办事处。"}],"ipa":"/trænsˈfɜː/"},{"pos":"v.","meaning":"转让；过户","definition":"to give ownership or a right to another person","examples":[{"en":"They transferred ownership of the house to their daughter.","zh":"他们将房屋所有权转让给女儿。"},{"en":"This licence cannot be transferred to another company.","zh":"这项许可证不能转让给另一家公司。"}],"ipa":"/trænsˈfɜː/"},{"pos":"v.","meaning":"转车；换乘","definition":"to change from one vehicle or service to another","examples":[{"en":"You need to transfer to the green line at Central Station.","zh":"你需要在中央车站换乘绿线。"},{"en":"We transferred from the train to a local bus.","zh":"我们从火车换乘了当地公交车。"}],"ipa":"/trænsˈfɜː/"},{"pos":"n.","meaning":"转移；运送","definition":"the movement of people, things or information to another place","examples":[{"en":"The transfer of the archives took three days.","zh":"档案的转移花了三天。"},{"en":"The package includes a transfer from the airport to the hotel.","zh":"套餐包括从机场到酒店的接送服务。"}],"ipa":"/ˈtrænsfɜː/"},{"pos":"n.","meaning":"转账；汇款","definition":"a payment moved between bank accounts","examples":[{"en":"The bank confirmed the transfer this morning.","zh":"银行今天上午确认了这笔转账。"},{"en":"An international transfer may take several working days.","zh":"国际汇款可能需要几个工作日。"}],"ipa":"/ˈtrænsfɜː/"},{"pos":"n.","meaning":"调动；转学；转会","definition":"a change to a different workplace, school or team","examples":[{"en":"He requested a transfer to the sales department.","zh":"他申请调到销售部。"},{"en":"Her transfer to another university was approved.","zh":"她转入另一所大学的申请获批了。"}],"ipa":"/ˈtrænsfɜː/"},{"pos":"n.","meaning":"转让；过户","definition":"a change in legal ownership or rights","examples":[{"en":"The transfer of ownership was recorded in writing.","zh":"所有权转让以书面形式记录下来。"},{"en":"The lawyer prepared the documents for the property transfer.","zh":"律师准备了房产过户文件。"}],"ipa":"/ˈtrænsfɜː/"},{"pos":"n.","meaning":"换乘；转车","definition":"a change between transport services during a journey","examples":[{"en":"The journey requires one transfer in Bristol.","zh":"这趟行程需要在布里斯托尔换乘一次。"},{"en":"Allow enough time for your transfer between trains.","zh":"为火车之间的换乘留出足够时间。"}],"ipa":"/ˈtrænsfɜː/"}],"transform":[{"pos":"v.","meaning":"改变；改造；使转换","definition":"To change greatly in form, appearance, or character.","examples":[{"en":"The renovation transformed the old warehouse.","zh":"翻修彻底改变了旧仓库。"},{"en":"The device transforms light into electrical energy.","zh":"装置把光转化成电能。"}]}],"transient":[{"pos":"adj.","meaning":"短暂的；转瞬即逝的","definition":"lasting only a short time","examples":[{"en":"The interruption was a transient problem.","zh":"这次中断是一个短暂的问题。"},{"en":"The poem describes the transient beauty of snow.","zh":"这首诗描写了雪转瞬即逝的美。"}]},{"pos":"n.","meaning":"短期停留者","definition":"a person staying somewhere for only a short period","examples":[{"en":"The hostel provided rooms for transients.","zh":"这家旅舍为短期停留者提供房间。"},{"en":"The town's population included many seasonal transients.","zh":"镇上的人口中包括许多季节性短住者。"}]}],"transit":[{"pos":"n.","meaning":"运输；转运","definition":"the movement of people or goods from one place to another","examples":[{"en":"The parcel was damaged in transit.","zh":"包裹在运输途中受损。"},{"en":"The city is expanding its public transit network.","zh":"这座城市正在扩大公共交通网络。"}]},{"pos":"v.","meaning":"经过；通过；中转","definition":"to pass through an area or point","examples":[{"en":"The ship transited the canal at dawn.","zh":"船在黎明时通过了运河。"},{"en":"Many passengers transit through this airport.","zh":"许多乘客经这个机场中转。"}]}],"transition":[{"pos":"n.","meaning":"过渡；转变；过渡时期","definition":"A change from one state or stage to another.","examples":[{"en":"The school helps pupils make the transition to secondary education.","zh":"学校帮助学生过渡到中等教育。"},{"en":"The region is undergoing a transition to cleaner energy.","zh":"该地区正向更清洁能源转型。"}]}],"translate":[{"pos":"v.","meaning":"翻译","definition":"to express the meaning of one language in another","examples":[{"en":"She translated the instructions into Chinese.","zh":"她把说明翻译成了中文。"},{"en":"The novel has been translated into several languages.","zh":"这部小说已被译成多种语言。"}]},{"pos":"v.","meaning":"转化；体现（translate into）","definition":"to turn an idea or advantage into a practical result","examples":[{"en":"The team translated the idea into a working model.","zh":"团队把这个想法转化成了可运行的模型。"},{"en":"Higher attendance did not translate into higher sales.","zh":"更多的到场人数并未转化为更高销量。"}]}],"transmit":[{"pos":"v.","meaning":"传送；发射","definition":"to send information, signals, or energy","examples":[{"en":"The sensor transmits data every minute.","zh":"传感器每分钟传送一次数据。"},{"en":"The antenna transmits a weak radio signal.","zh":"天线发射一个微弱的无线电信号。"}]},{"pos":"v.","meaning":"传播；传染","definition":"to pass a disease or quality from one individual to another","examples":[{"en":"Some insects transmit disease between plants.","zh":"一些昆虫在植物之间传播病害。"},{"en":"The infection can be transmitted through close contact.","zh":"这种感染可以通过密切接触传播。"}]}],"transmute":[{"pos":"v.","meaning":"使变化；转化；改变性质","definition":"To change into a different form or substance.","examples":[{"en":"The artist transmuted personal grief into powerful paintings.","zh":"艺术家把个人悲痛转化为有感染力的画作。"},{"en":"The experiment transmuted one element into another.","zh":"实验把一种元素转变成另一种元素。"}]}],"transparent":[{"pos":"adj.","meaning":"透明的；清澈的","definition":"allowing objects to be seen clearly through it","examples":[{"en":"The container has a transparent lid.","zh":"这个容器有一个透明盖子。"},{"en":"We could see the stones through the transparent water.","zh":"透过清澈的水，我们能看到石头。"}]},{"pos":"adj.","meaning":"明显的；易看穿的","definition":"easy to recognise as what it really is","examples":[{"en":"His excuse was a transparent attempt to avoid the task.","zh":"他的借口显然是为了逃避任务。"},{"en":"The story makes the character's motives transparent.","zh":"故事把人物的动机表现得很明显。"}]},{"pos":"adj.","meaning":"清楚易懂的；公开透明的","definition":"open and easy to understand","examples":[{"en":"The selection process must be transparent.","zh":"选拔过程必须公开透明。"},{"en":"The report gives a transparent explanation of the fees.","zh":"报告清楚说明了各项费用。"}]}],"transplant":[{"pos":"v.","meaning":"移栽","definition":"to move a plant to a new growing place","ipa":"/trænsˈplɑːnt/","examples":[{"en":"We transplanted the seedlings into larger pots.","zh":"我们把幼苗移栽到了更大的花盆中。"},{"en":"The gardener will transplant the young tree in autumn.","zh":"园丁将在秋天移栽这棵小树。"}]},{"pos":"v.","meaning":"移植器官或组织","definition":"to transfer an organ or tissue to another location or body","ipa":"/trænsˈplɑːnt/","examples":[{"en":"The surgeons transplanted a kidney during the operation.","zh":"外科医生在手术中移植了一个肾脏。"},{"en":"The team studies how transplanted tissue heals.","zh":"团队研究移植组织如何愈合。"}]},{"pos":"v.","meaning":"使迁移；移居","definition":"to move people or practices into a new setting","ipa":"/trænsˈplɑːnt/","examples":[{"en":"The family transplanted its traditions to a new country.","zh":"这个家庭把自己的传统带到了新的国家。"},{"en":"The company transplanted the whole department to another city.","zh":"公司把整个部门搬到了另一个城市。"}]},{"pos":"n.","meaning":"器官移植","definition":"an operation that transfers an organ or tissue","ipa":"/ˈtrænsplɑːnt/","examples":[{"en":"She returned to work after the transplant.","zh":"移植手术后，她回去工作了。"},{"en":"The transplant took several hours to complete.","zh":"这次移植手术花了几个小时才完成。"}]},{"pos":"n.","meaning":"移植物；移植器官","definition":"an organ or tissue transferred to another body or place","ipa":"/ˈtrænsplɑːnt/","examples":[{"en":"The hospital monitors the transplant closely.","zh":"医院密切监测着移植物的情况。"},{"en":"The report describes how the transplant began to function.","zh":"报告描述了移植器官如何开始发挥功能。"}]}],"transport":[{"pos":"n.","meaning":"运输；交通系统；交通工具","definition":"The movement of people or goods and the means used.","examples":[{"en":"Public transport is reliable here.","zh":"这里的公共交通很可靠。"},{"en":"The cost of transport increased.","zh":"运输成本增加了。"}],"ipa":"/ˈtrænspɔːt/"},{"pos":"v.","meaning":"运输；运送；搬运","definition":"To carry people or goods between places.","examples":[{"en":"Trucks transport the produce to market.","zh":"卡车把农产品运往市场。"},{"en":"The patient was transported by helicopter.","zh":"患者由直升机运送。"}],"ipa":"/trænˈspɔːt/"}],"transportation":[{"pos":"n.","meaning":"运输；交通运输系统","definition":"the movement of people or goods and the means used for it","examples":[{"en":"Public transportation connects the suburbs to the centre.","zh":"公共交通连接着郊区和市中心。"},{"en":"Transportation costs are included in the final price.","zh":"最终价格中包含运输费用。"}]}],"trap":[{"pos":"n.","meaning":"陷阱；捕捉器","definition":"a device used to catch an animal or object","examples":[{"en":"The researchers checked the animal trap each morning.","zh":"研究人员每天早晨检查动物捕捉器。"},{"en":"The empty trap was checked and reset.","zh":"空捕捉器经检查后被重新设置。"}]},{"pos":"v.","meaning":"诱捕；使中圈套","definition":"to catch using a device or deceptive plan","examples":[{"en":"The net trapped several fish.","zh":"网捕住了几条鱼。"},{"en":"The misleading question trapped him into contradicting himself.","zh":"这个误导性问题诱使他自相矛盾。"}]},{"pos":"v.","meaning":"困住；使陷入困境","definition":"to prevent someone or something from escaping","examples":[{"en":"Snow trapped the travellers in the village.","zh":"大雪把旅人困在村里。"},{"en":"Warm air became trapped under the roof.","zh":"暖空气被困在屋顶下方。"}]},{"pos":"n.","meaning":"圈套；诡计","definition":"a deceptive plan intended to catch someone out","examples":[{"en":"The question was a trap designed to expose his mistake.","zh":"这个问题是为揭露他的错误而设的圈套。"},{"en":"She realised that the invitation was a trap.","zh":"她意识到那份邀请是一个圈套。"}]}],"trapeze":[{"pos":"n.","meaning":"高空秋千；吊架","definition":"A horizontal bar suspended by ropes for acrobatic performance.","examples":[{"en":"The acrobat swung from a trapeze.","zh":"杂技演员在高空秋千上摆荡。"},{"en":"The trapeze hung high above the safety net.","zh":"高空秋千悬在安全网上方很高处。"}]}],"treadmill":[{"pos":"n.","meaning":"跑步机","definition":"an exercise machine with a moving belt for walking or running","examples":[{"en":"She walked on the treadmill for twenty minutes.","zh":"她在跑步机上走了二十分钟。"},{"en":"The gym replaced its oldest treadmill.","zh":"健身房更换了最旧的跑步机。"}]},{"pos":"n.","meaning":"踏车；踏轮","definition":"a machine powered by people or animals walking on a moving surface","examples":[{"en":"The museum displays an old animal-powered treadmill.","zh":"博物馆展出了一台旧式畜力踏车。"},{"en":"The treadmill once supplied power to the mill.","zh":"这台踏车曾经为磨坊提供动力。"}]},{"pos":"n.","meaning":"单调繁重的工作","definition":"a tiring routine that seems endless","examples":[{"en":"She wanted to escape the treadmill of constant meetings.","zh":"她想摆脱无休止开会的单调劳累。"},{"en":"Daily paperwork had become a treadmill for the team.","zh":"每天处理文书成了团队单调繁重的工作。"}]}],"treatise":[{"pos":"n.","meaning":"专著；专题论文","definition":"a detailed formal written study of a subject","examples":[{"en":"The library owns an early treatise on astronomy.","zh":"图书馆藏有一部早期天文学专著。"},{"en":"Her treatise examines the development of public education.","zh":"她的专题论文探讨了公共教育的发展。"}]}],"treatment":[{"pos":"n.","meaning":"治疗","definition":"medical care given to help someone get better","examples":[{"en":"Early treatment can prevent serious complications.","zh":"早期治疗可以防止严重并发症。"},{"en":"The hospital offers treatment for sports injuries.","zh":"这家医院提供运动损伤治疗。"},{"en":"The patient responded well to treatment.","zh":"患者对治疗反应良好。"}]},{"pos":"n.","meaning":"对待；待遇","definition":"The way someone or something is dealt with.","examples":[{"en":"Workers demanded fair treatment.","zh":"工人要求公平待遇。"},{"en":"The report criticises the treatment of animals.","zh":"报告批评了对动物的对待方式。"}]}],"trek":[{"pos":"v.","meaning":"长途跋涉","definition":"to travel a long distance over difficult ground","examples":[{"en":"They trekked across the mountains for a week.","zh":"他们在山间跋涉了一周。"},{"en":"We trekked through deep snow to reach the cabin.","zh":"我们穿过深雪跋涉到达小屋。"}]},{"pos":"n.","meaning":"艰苦旅程；长途跋涉","definition":"a long and often demanding journey","examples":[{"en":"The lake is a full day's trek from the village.","zh":"从村庄到湖边需要跋涉一整天。"},{"en":"The diary describes the family's trek by ox wagon.","zh":"日记描述了这家人乘牛车进行的长途迁移。"}]}],"tremendous":[{"pos":"adj.","meaning":"巨大的；极大的","definition":"very large in amount or degree","examples":[{"en":"The project required a tremendous amount of effort.","zh":"这个项目需要付出巨大的努力。"},{"en":"The storm caused tremendous damage.","zh":"暴风雨造成了巨大的破坏。"}]},{"pos":"adj.","meaning":"极好的；惊人的","definition":"extremely good or impressive","examples":[{"en":"The concert was a tremendous success.","zh":"这场音乐会取得了巨大成功。"},{"en":"You have made tremendous progress this term.","zh":"你这学期取得了惊人的进步。"}]}],"trench":[{"pos":"n.","meaning":"沟；壕沟","definition":"A long narrow hole dug in the ground.","examples":[{"en":"Workers dug a trench for the pipe.","zh":"工人为管道挖了一条沟。"},{"en":"The soldiers sheltered in a trench.","zh":"士兵在壕沟中躲避。"}]},{"pos":"v.","meaning":"挖沟；开壕沟","definition":"To dig a long narrow channel.","examples":[{"en":"They trenched the field to improve drainage.","zh":"他们在田里挖沟以改善排水。"},{"en":"The crew trenched along the road for new cables.","zh":"施工队沿路开沟铺设新电缆。"}]}],"trend":[{"pos":"n.","meaning":"趋势","definition":"a general direction of change","examples":[{"en":"The survey shows a trend towards remote working.","zh":"调查显示了远程工作的发展趋势。"},{"en":"It is too early to know whether this trend will continue.","zh":"现在判断这一趋势是否会持续还为时过早。"},{"en":"The long-term trend is more useful than a single year's figure.","zh":"长期趋势比单一年度的数据更有参考价值。"}]},{"pos":"v.","meaning":"呈某种趋势;趋向","definition":"to develop in a particular direction","examples":[{"en":"Prices have been trending upward.","zh":"价格一直呈上升趋势。"},{"en":"The discussion trended toward practical solutions.","zh":"讨论趋向实际解决方案。"}]},{"pos":"v.","meaning":"伸向;延伸","definition":"to extend in a general direction","examples":[{"en":"The coastline trends northeast.","zh":"海岸线向东北延伸。"},{"en":"The ridge trends toward the distant plateau.","zh":"山脊延伸向远处高原。"}]},{"pos":"n.","meaning":"时尚;风尚","definition":"a currently popular style or behaviour","examples":[{"en":"The exhibition traces trends in clothing.","zh":"展览追溯服装风尚。"},{"en":"She prefers classic designs to passing trends.","zh":"比起短暂时尚，她更喜欢经典设计。"}]}],"trespass":[{"pos":"v.","meaning":"擅闯；非法进入","definition":"to enter another person's land without permission","examples":[{"en":"Visitors must not trespass on the neighbouring farm.","zh":"游客不得擅自进入邻近的农场。"},{"en":"The fence discourages people from trespassing.","zh":"篱笆可以阻止人们擅闯。"}]},{"pos":"v.","meaning":"侵占；滥用他人好意","definition":"to make excessive use of someone's time or kindness","examples":[{"en":"I do not want to trespass on your hospitality.","zh":"我不想过分占用你的好意招待。"},{"en":"The long visit began to trespass on her limited free time.","zh":"这次漫长的拜访开始侵占她有限的空闲时间。"}]},{"pos":"n.","meaning":"擅自进入；侵犯","definition":"an act of entering property or infringing a right","examples":[{"en":"The notice warns against trespass.","zh":"告示警告不得擅闯。"},{"en":"They regarded the intrusion as a trespass on their privacy.","zh":"他们把这次闯入视为对隐私的侵犯。"}]},{"pos":"v.","meaning":"冒犯；犯过（正式或旧式用法）","definition":"to commit an offence against a moral rule or another person","examples":[{"en":"The old prayer asks forgiveness for those who trespass against others.","zh":"这篇古老的祷文请求宽恕那些冒犯他人的人。"},{"en":"He believed that he had trespassed against the community's moral code.","zh":"他认为自己违背了社区的道德准则。"}]}],"trial":[{"pos":"n.","meaning":"审判；审讯","definition":"A formal examination of evidence in court.","examples":[{"en":"The trial lasted three weeks.","zh":"审判持续了三周。"},{"en":"A witness testified during the trial.","zh":"一名证人在审判期间作证。"}]},{"pos":"n.","meaning":"试验；试用","definition":"A test to see whether something works.","examples":[{"en":"The new bus service is operating on a trial basis.","zh":"新公交服务正在试运行。"},{"en":"The laboratory conducted several trials.","zh":"实验室进行了几次试验。"}]},{"pos":"adj.","meaning":"试验性的；试用的","definition":"Used for a limited period to test suitability.","examples":[{"en":"The software includes a trial version.","zh":"软件提供试用版。"},{"en":"They introduced the system on a trial basis.","zh":"他们以试验方式引入了这个系统。"}]}],"triangle":[{"pos":"n.","meaning":"三角形；三角形物体","definition":"a shape with three straight sides and three angles","examples":[{"en":"Draw a triangle inside the circle.","zh":"在圆内画一个三角形。"},{"en":"The three villages form a triangle on the map.","zh":"三个村庄在地图上构成一个三角形。"}]}],"tribal":[{"pos":"adj.","meaning":"部落的；部族的","definition":"relating to a tribe or its way of life","examples":[{"en":"The exhibition includes tribal textiles.","zh":"展览包括部落纺织品。"},{"en":"The researcher studied tribal traditions in the region.","zh":"研究者考察了该地区的部落传统。"}]},{"pos":"adj.","meaning":"集团意识强的；派别鲜明的","definition":"showing strong loyalty to a particular group","examples":[{"en":"The debate became increasingly tribal.","zh":"这场辩论越来越表现出强烈的派别对立。"},{"en":"Tribal loyalties made compromise difficult.","zh":"强烈的集团忠诚使妥协变得困难。"}]}],"tribute":[{"pos":"n.","meaning":"贡品；贡金","definition":"A payment made by a subordinate ruler or people.","examples":[{"en":"The kingdom sent annual tribute to the emperor.","zh":"王国每年向皇帝进贡。"},{"en":"Gold was collected as tribute.","zh":"黄金被征收作贡品。"}]},{"pos":"n.","meaning":"赞颂；敬意；致敬的礼物","definition":"Words, actions, or gifts showing respect.","examples":[{"en":"The concert was a tribute to the composer.","zh":"音乐会向这位作曲家致敬。"},{"en":"Former students paid tribute to their teacher.","zh":"往届学生向老师表达了敬意。"}]}],"trick":[{"pos":"n.","meaning":"诡计；骗局","definition":"an action intended to deceive someone","examples":[{"en":"The offer turned out to be a trick.","zh":"这个提议原来是一个骗局。"},{"en":"She saw through his trick immediately.","zh":"她立刻识破了他的诡计。"}]},{"pos":"n.","meaning":"技巧；戏法","definition":"a clever method or skilful performance","examples":[{"en":"He showed us a simple card trick.","zh":"他向我们表演了一个简单的纸牌戏法。"},{"en":"The trick is to keep the camera steady.","zh":"诀窍是保持相机稳定。"}]},{"pos":"v.","meaning":"欺骗；哄骗","definition":"to deceive someone into believing or doing something","examples":[{"en":"The misleading label tricked customers into paying more.","zh":"误导性的标签骗顾客多花了钱。"},{"en":"They were tricked into giving away the answer.","zh":"他们受骗泄露了答案。"}]}],"trigger":[{"pos":"v.","meaning":"引发；导致","definition":"to cause a process or reaction to begin","examples":[{"en":"The news triggered a lively debate.","zh":"这条消息引发了一场热烈辩论。"},{"en":"A sudden movement triggered the alarm.","zh":"一个突然的动作触发了警报。"}]},{"pos":"n.","meaning":"扳机","definition":"a part pressed to activate a gun or mechanism","examples":[{"en":"The museum label identifies the trigger on the old pistol.","zh":"博物馆标签指出了旧手枪上的扳机。"},{"en":"The tool stops when the operator releases the trigger.","zh":"操作员松开扳机时，工具就停止运行。"}]},{"pos":"n.","meaning":"诱因；触发因素","definition":"something that starts a reaction or event","examples":[{"en":"The price increase was the trigger for the dispute.","zh":"价格上涨是争议的导火索。"},{"en":"The study looked for a common trigger in the reported incidents.","zh":"研究寻找这些事件中的共同诱因。"}]}],"trim":[{"pos":"v.","meaning":"修剪；修整","definition":"To make neat or smaller by cutting.","examples":[{"en":"Trim the hedge before it blocks the path.","zh":"在树篱挡住小路前修剪它。"},{"en":"She trimmed the photograph to fit the frame.","zh":"她修剪照片，使其适合相框。"}]},{"pos":"n.","meaning":"修剪；整理","definition":"An act of cutting something to make it neat.","examples":[{"en":"The lawn needs a trim.","zh":"草坪需要修剪。"},{"en":"He went to the barber for a quick trim.","zh":"他去理发店简单修了头发。"}]},{"pos":"adj.","meaning":"整洁的；苗条的；利落的","definition":"Neat in appearance or slim and fit.","examples":[{"en":"The cottage has a trim little garden.","zh":"小屋有一座整洁小花园。"},{"en":"Regular walking keeps her trim.","zh":"经常步行使她保持苗条。"}]}],"trimester":[{"pos":"n.","meaning":"三个月期","definition":"a period of three months, especially in pregnancy","examples":[{"en":"The chart divides pregnancy into three trimesters.","zh":"这张图把孕期分为三个三个月期。"},{"en":"The booklet describes changes during the first trimester.","zh":"这本小册子描述了孕早期的变化。"}]},{"pos":"n.","meaning":"三学期制中的一个学期","definition":"one of three teaching periods in an academic year","examples":[{"en":"The project is due at the end of the trimester.","zh":"这个项目在本学期末到期。"},{"en":"Students choose new courses each trimester.","zh":"学生每个学期选择新课程。"}]}],"trinket":[{"pos":"n.","meaning":"小饰品；廉价珠宝","definition":"a small inexpensive ornament or piece of jewellery","examples":[{"en":"She kept a few childhood trinkets in a box.","zh":"她在盒子里保存了一些童年的小饰品。"},{"en":"The stall sells colourful trinkets to visitors.","zh":"摊位向游客出售彩色小饰品。"}]}],"triple":[{"pos":"adj.","meaning":"三倍的；三部分的","definition":"Three times as much or consisting of three parts.","examples":[{"en":"The building has a triple layer of insulation.","zh":"建筑有三层隔热材料。"},{"en":"They received triple pay for the extra shift.","zh":"他们因额外班次获得三倍工资。"}]},{"pos":"v.","meaning":"使增至三倍；增至三倍","definition":"To become or make three times as much.","examples":[{"en":"The town's population tripled.","zh":"小镇人口增至三倍。"},{"en":"The company tripled its research budget.","zh":"公司把研究预算增至三倍。"}]}],"triumphant":[{"pos":"adj.","meaning":"获胜的；得意的","definition":"successful and showing pride or joy in success","examples":[{"en":"The triumphant team returned to cheering fans.","zh":"获胜的球队回到了欢呼的球迷中。"},{"en":"She gave a triumphant smile when the experiment worked.","zh":"实验成功时，她露出了得意的微笑。"}]}],"trivial":[{"pos":"adj.","meaning":"琐碎的；无关紧要的","definition":"too small or ordinary to be important","examples":[{"en":"We should not waste time on trivial details.","zh":"我们不该在琐碎细节上浪费时间。"},{"en":"The error seemed trivial but affected the total.","zh":"这个错误看似微小，却影响了总数。"}]}],"trivialize":[{"pos":"v.","meaning":"轻视；淡化；使显得不重要","definition":"To make something seem less serious or important.","examples":[{"en":"The joke trivialized their concerns.","zh":"这个笑话淡化了他们的担忧。"},{"en":"The film was criticised for trivializing a serious issue.","zh":"电影因轻描淡写地处理严肃议题而受到批评。"}]}],"tropical":[{"pos":"adj.","meaning":"热带的","definition":"relating to the warm regions near the equator","examples":[{"en":"The island has a tropical climate.","zh":"这个岛屿属于热带气候。"},{"en":"Many tropical plants need warm conditions throughout the year.","zh":"许多热带植物全年都需要温暖的环境。"}]},{"pos":"adj.","meaning":"酷热的；热带般的","definition":"very hot and humid like the tropics","examples":[{"en":"The greenhouse felt tropical even in winter.","zh":"即使在冬天，温室也像热带一样炎热。"},{"en":"We endured tropical heat during the afternoon walk.","zh":"下午散步时，我们忍受着热带般的酷热。"}]}],"tropospheric":[{"pos":"adj.","meaning":"对流层的","definition":"relating to the lowest layer of the atmosphere","examples":[{"en":"The study examines tropospheric temperature changes.","zh":"这项研究考察对流层温度变化。"},{"en":"Tropospheric clouds affect how much sunlight reaches the surface.","zh":"对流层中的云影响到达地表的阳光量。"}]}],"troupe":[{"pos":"n.","meaning":"演出团；剧团；马戏团","definition":"A group of performers who work together.","examples":[{"en":"A travelling troupe visited the town.","zh":"一个巡回演出团来到镇上。"},{"en":"The dance troupe rehearsed all afternoon.","zh":"舞团排练了整个下午。"}]}],"truant":[{"pos":"n.","meaning":"逃学者","definition":"a student who is absent without permission","examples":[{"en":"The school contacted the truant's parents.","zh":"学校联系了逃学学生的家长。"},{"en":"The story follows two truants who spend a day in the city.","zh":"故事讲述了两个逃学学生在城里度过一天的经历。"}]},{"pos":"v.","meaning":"逃学；擅离职责（英式）","definition":"to stay away from school or duties without permission","examples":[{"en":"He began to truant after moving to a new school.","zh":"转学后，他开始逃学。"},{"en":"The report examines why some pupils truant regularly.","zh":"报告探讨了一些学生为什么经常旷课。"}]}],"truce":[{"pos":"n.","meaning":"休战；停战协定","definition":"an agreement to stop fighting for a period","examples":[{"en":"The two sides agreed to a temporary truce.","zh":"双方同意暂时休战。"},{"en":"The truce allowed supplies to reach the town.","zh":"停战使物资得以运抵城镇。"}]}],"trunk":[{"pos":"n.","meaning":"树干；躯干","definition":"The main central part of a tree or body.","examples":[{"en":"The tree's trunk was hollow.","zh":"树干是空心的。"},{"en":"The exercise strengthens the muscles of the trunk.","zh":"这项运动增强躯干肌肉。"}]},{"pos":"n.","meaning":"大箱子；旅行箱","definition":"A large strong box for storing or transporting belongings.","examples":[{"en":"She found letters in an old trunk.","zh":"她在旧大箱子里发现了信件。"},{"en":"The porter carried the trunk upstairs.","zh":"搬运工把旅行箱搬上楼。"}]},{"pos":"n.","meaning":"象鼻","definition":"The long flexible nose of an elephant.","examples":[{"en":"The elephant lifted water with its trunk.","zh":"大象用鼻子吸起水。"},{"en":"Its trunk reached towards the fruit.","zh":"它的鼻子伸向水果。"}]}],"trustworthy":[{"pos":"adj.","meaning":"值得信赖的；可靠的","definition":"deserving confidence and trust","examples":[{"en":"We need a trustworthy person to keep the keys.","zh":"我们需要一个可靠的人保管钥匙。"},{"en":"The guide recommends checking whether a source is trustworthy.","zh":"这份指南建议检查信息来源是否可信。"}]}],"tube":[{"pos":"n.","meaning":"管；管状容器","definition":"a hollow cylinder or a container shaped like one","examples":[{"en":"The liquid flows through a narrow tube.","zh":"液体流过一根细管。"},{"en":"Put the sample into a clean test tube.","zh":"把样本放进干净的试管。"}]},{"pos":"n.","meaning":"地铁（英式）","definition":"the underground railway, especially in London","examples":[{"en":"We took the Tube across London.","zh":"我们乘地铁穿过伦敦。"},{"en":"The nearest Tube station is five minutes away.","zh":"最近的地铁站在五分钟路程外。"}]}],"tug":[{"pos":"v.","meaning":"用力拉；拖拽","definition":"To pull something firmly or repeatedly.","examples":[{"en":"The child tugged at her sleeve.","zh":"孩子拉了拉她的袖子。"},{"en":"They tugged the rope until the boat moved.","zh":"他们用力拉绳，直到船移动。"}]}],"tuition":[{"pos":"n.","meaning":"教学；辅导","definition":"teaching or instruction","examples":[{"en":"The centre offers private tuition in mathematics.","zh":"这个中心提供数学私人辅导。"},{"en":"She receives extra tuition after school.","zh":"她放学后接受额外辅导。"},{"en":"Individual tuition can be expensive.","zh":"一对一辅导可能很贵。"}]},{"pos":"n.","meaning":"学费（尤美式用法）","definition":"fees paid for instruction","examples":[{"en":"The scholarship covers tuition and accommodation.","zh":"奖学金涵盖学费和住宿费。"},{"en":"She worked part-time to pay her tuition.","zh":"她兼职工作支付学费。"}]}],"tuition fees":[{"pos":"n.","meaning":"学费","definition":"money paid for teaching at an educational institution","examples":[{"en":"Her scholarship covers the full cost of her tuition fees.","zh":"她的奖学金足以支付全部学费。"},{"en":"Students may pay their tuition fees in three instalments.","zh":"学生可以分三期支付学费。"}]}],"tune":[{"pos":"v.","meaning":"调音","definition":"to adjust an instrument to the correct pitch","examples":[{"en":"The musician tuned the violin before the concert.","zh":"音乐家在音乐会前给小提琴调音。"},{"en":"This piano needs to be tuned.","zh":"这架钢琴需要调音。"}]},{"pos":"v.","meaning":"调节；调整","definition":"to adjust equipment for the best performance or reception","examples":[{"en":"The mechanic tuned the engine.","zh":"机械师调校了发动机。"},{"en":"She tuned the radio to a local station.","zh":"她把收音机调到当地电台。"}]},{"pos":"n.","meaning":"曲调；旋律","definition":"a sequence of musical notes forming a melody","examples":[{"en":"He hummed a familiar tune while cooking.","zh":"他做饭时哼着熟悉的曲调。"},{"en":"The song has a cheerful tune.","zh":"这首歌的旋律很欢快。"}]},{"pos":"n.","meaning":"协调；和谐；合调（in tune）","definition":"a state of musical or wider agreement","examples":[{"en":"The singers were perfectly in tune.","zh":"歌手们唱得十分合调。"},{"en":"The design is in tune with the local landscape.","zh":"这个设计与当地景观相协调。"}]}],"tunnel":[{"pos":"n.","meaning":"隧道；地道","definition":"An underground or enclosed passage.","examples":[{"en":"The train entered the tunnel.","zh":"火车驶入隧道。"},{"en":"The tunnel connects the two valleys.","zh":"隧道连接着两个山谷。"}]},{"pos":"v.","meaning":"挖隧道；掘地道","definition":"To make a passage through or under something.","examples":[{"en":"Engineers tunnelled through the hill.","zh":"工程师凿穿山丘修建隧道。"},{"en":"The animal tunnelled beneath the fence.","zh":"动物在围栏下面挖了地道。"}]}],"turbid":[{"pos":"adj.","meaning":"浑浊的","definition":"cloudy because small particles are mixed into a liquid","examples":[{"en":"The river became turbid after the storm.","zh":"暴风雨后，河水变得浑浊。"},{"en":"The sample was too turbid to see through.","zh":"这份样本太浑浊，无法透视。"}]},{"pos":"adj.","meaning":"混乱的；晦涩的（比喻）","definition":"confused or difficult to understand","examples":[{"en":"The essay's turbid reasoning obscures its main point.","zh":"文章混乱的推理掩盖了中心观点。"},{"en":"His turbid memories emerged in disconnected fragments.","zh":"他模糊混乱的记忆以零散片段浮现。"}]}],"turbine":[{"pos":"n.","meaning":"涡轮机；汽轮机","definition":"a machine driven by fluid moving over blades","examples":[{"en":"Wind turns the blades of the turbine.","zh":"风带动涡轮机的叶片转动。"},{"en":"The power station uses a steam turbine.","zh":"这座发电站使用汽轮机。"}]}],"turnover":[{"pos":"n.","meaning":"营业额","definition":"The total value of sales during a period.","examples":[{"en":"Annual turnover exceeded a million pounds.","zh":"年营业额超过一百万英镑。"},{"en":"The shop's turnover rises in summer.","zh":"商店营业额在夏季上升。"}]},{"pos":"n.","meaning":"人员流动率；更替率","definition":"The rate at which staff leave and are replaced.","examples":[{"en":"High staff turnover increased training costs.","zh":"人员高流动率增加了培训成本。"},{"en":"Better conditions reduced employee turnover.","zh":"更好的条件降低了员工流失率。"}]},{"pos":"n.","meaning":"货物周转率；存货周转","definition":"The rate at which stock is sold and replaced.","examples":[{"en":"The store maintains rapid stock turnover.","zh":"商店保持快速存货周转。"},{"en":"Slow turnover left too much money tied up in inventory.","zh":"周转缓慢使过多资金积压在库存中。"}]}],"turret":[{"pos":"n.","meaning":"塔楼；角楼","definition":"a small tower rising from a larger building","examples":[{"en":"A narrow staircase leads to the castle turret.","zh":"一道狭窄的楼梯通往城堡角楼。"},{"en":"The roof of the turret was covered in red tiles.","zh":"塔楼屋顶铺着红瓦。"}]},{"pos":"n.","meaning":"炮塔；旋转塔座","definition":"a rotating structure holding a gun or equipment","examples":[{"en":"The museum vehicle has a rotating turret.","zh":"博物馆中的车辆装有一个旋转炮塔。"},{"en":"The technician inspected the turret mechanism.","zh":"技术员检查了旋转塔座的机械装置。"}]}],"tutor":[{"pos":"n.","meaning":"导师；辅导教师","definition":"a teacher who guides students individually or in small groups","examples":[{"en":"Her tutor helped her choose a research topic.","zh":"导师帮助她选择了研究课题。"},{"en":"The college assigns a tutor to every new student.","zh":"学院为每位新生安排一位导师。"}]},{"pos":"n.","meaning":"家庭教师；私人教师","definition":"a teacher hired to give private lessons","examples":[{"en":"They hired a tutor to help with mathematics.","zh":"他们请了一位家庭教师辅导数学。"},{"en":"The tutor visits the family twice a week.","zh":"家庭教师每周到这家两次。"}]},{"pos":"v.","meaning":"辅导；当家庭教师","definition":"to teach someone individually or in a small group","examples":[{"en":"She tutors younger students after school.","zh":"她放学后辅导低年级学生。"},{"en":"He was tutored at home for several months.","zh":"他在家接受了几个月的私人辅导。"}]}],"tutorial":[{"pos":"n.","meaning":"辅导课；教程；指南","definition":"A lesson with individual guidance or instructions for learning a task.","examples":[{"en":"We discussed the essay in a tutorial.","zh":"我们在辅导课上讨论了文章。"},{"en":"The online tutorial explains how to edit photographs.","zh":"在线教程解释了如何编辑照片。"}]},{"pos":"adj.","meaning":"辅导的；导师的","definition":"Relating to teaching through individual or small-group guidance.","examples":[{"en":"Students receive tutorial support.","zh":"学生获得辅导支持。"},{"en":"The department increased its tutorial hours.","zh":"该系增加了辅导课时。"}]}],"twist":[{"pos":"v.","meaning":"扭转；拧；捻","definition":"to turn something around itself","examples":[{"en":"Twist the lid to open the jar.","zh":"拧动盖子打开罐子。"},{"en":"She twisted the threads into a stronger cord.","zh":"她把线捻成了一根更结实的绳。"}]},{"pos":"v.","meaning":"缠绕；蜿蜒","definition":"to wind around something or follow a winding course","examples":[{"en":"Vines twisted around the fence.","zh":"藤蔓缠绕着篱笆。"},{"en":"The path twists between the trees.","zh":"小路在树木之间蜿蜒。"}]},{"pos":"v.","meaning":"歪曲","definition":"to change the meaning of information unfairly","examples":[{"en":"The headline twisted the meaning of her words.","zh":"标题歪曲了她的话的意思。"},{"en":"He accused the report of twisting the facts.","zh":"他指责这份报告歪曲事实。"}]},{"pos":"n.","meaning":"弯曲；扭转","definition":"a bend or turning movement","examples":[{"en":"Give the handle a gentle twist.","zh":"轻轻转动一下把手。"},{"en":"A sudden twist in the road surprised the driver.","zh":"道路上突然出现的弯道让司机吃了一惊。"}]},{"pos":"n.","meaning":"意外转折","definition":"an unexpected change in a story or situation","examples":[{"en":"The film ends with a surprising twist.","zh":"这部电影以一个出人意料的转折结束。"},{"en":"A late discovery added a new twist to the investigation.","zh":"后来的发现使调查出现了新的转折。"}]}],"twofold":[{"pos":"adj.","meaning":"双重的；有两部分的","definition":"having two aspects or parts","examples":[{"en":"The purpose of the visit was twofold.","zh":"这次访问有双重目的。"},{"en":"The report proposes a twofold strategy.","zh":"报告提出了一个包含两部分的策略。"}]},{"pos":"adj.","meaning":"两倍的","definition":"twice as large in amount or degree","examples":[{"en":"The experiment produced a twofold increase in output.","zh":"实验使产出增加到原来的两倍。"},{"en":"The new process offers a twofold advantage in speed.","zh":"新工艺在速度方面有两倍的优势。"}]},{"pos":"adv.","meaning":"两倍地","definition":"by a factor of two","examples":[{"en":"Demand has increased twofold since last year.","zh":"需求自去年以来增长到了原来的两倍。"},{"en":"The number of visitors rose twofold after the renovation.","zh":"翻新后，访客人数增至原来的两倍。"}]}],"typhoon":[{"pos":"n.","meaning":"台风","definition":"A powerful tropical storm in the northwestern Pacific.","examples":[{"en":"The typhoon damaged coastal homes.","zh":"台风损坏了沿海房屋。"},{"en":"Ferries were cancelled before the typhoon arrived.","zh":"台风来临前，渡轮停航了。"}]}],"typical":[{"pos":"adj.","meaning":"典型的；有代表性的","definition":"showing the usual features of a person or type","examples":[{"en":"This is a typical example of her work.","zh":"这是她作品的典型例子。"},{"en":"A typical day begins with a short meeting.","zh":"通常一天从简短会议开始。"}]}],"ulterior":[{"pos":"adj.","meaning":"隐秘的；别有用心的","definition":"hidden behind the stated reason for an action","examples":[{"en":"She wondered whether the offer had an ulterior motive.","zh":"她怀疑这个提议是否别有用心。"},{"en":"He helped without any ulterior purpose.","zh":"他提供帮助并无隐藏目的。"}]},{"pos":"adj.","meaning":"较远的；后来的（少见用法）","definition":"further away or occurring at a later stage","examples":[{"en":"The old account describes an ulterior region beyond the hills.","zh":"旧记载描述了群山之外更远的地区。"},{"en":"The agreement left ulterior arrangements for another meeting.","zh":"协议把后续安排留待另一次会议讨论。"}]}],"ultimate":[{"pos":"adj.","meaning":"最终的；最后的；根本的","definition":"Final or most basic in a process or purpose.","examples":[{"en":"Our ultimate goal is to reduce waste.","zh":"我们的最终目标是减少浪费。"},{"en":"The director has ultimate responsibility.","zh":"主管负有最终责任。"}]},{"pos":"n.","meaning":"最高典范；极品；极致","definition":"The best or most extreme example of something.","examples":[{"en":"The suite offers the ultimate in comfort.","zh":"这间套房提供极致舒适。"},{"en":"For her, the quiet cabin was the ultimate in luxury.","zh":"对她来说，安静小屋就是最奢华的享受。"}]}],"ultimately":[{"pos":"adv.","meaning":"最终；归根结底","definition":"in the end or at the most fundamental level","examples":[{"en":"The decision ultimately belongs to the owner.","zh":"决定权最终属于所有者。"},{"en":"Their early mistakes ultimately led to a better design.","zh":"他们早期的失误最终促成了更好的设计。"}]}],"ultraclean":[{"pos":"adj.","meaning":"超洁净的","definition":"having an exceptionally low level of contamination","examples":[{"en":"The samples were prepared in an ultraclean room.","zh":"样本在超洁净室中制备。"},{"en":"The factory uses ultraclean water for delicate components.","zh":"工厂用超纯净水处理精密元件。"}]}],"unanimous":[{"pos":"adj.","meaning":"一致同意的；全体通过的","definition":"Agreed upon by everyone involved.","examples":[{"en":"The committee reached a unanimous decision.","zh":"委员会达成一致决定。"},{"en":"The judges were unanimous in their praise.","zh":"评委一致赞扬。"}]}],"unaware":[{"pos":"adj.","meaning":"未意识到的；不知道的","definition":"not knowing about something","examples":[{"en":"She was unaware of the change in schedule.","zh":"她不知道日程已经改变。"},{"en":"Many visitors remain unaware that the museum is free.","zh":"许多游客仍不知道这家博物馆免费开放。"}]}],"unbeatable":[{"pos":"adj.","meaning":"不可战胜的","definition":"impossible or very difficult to defeat","examples":[{"en":"The team seemed unbeatable that season.","zh":"那支队伍在那个赛季似乎不可战胜。"},{"en":"Her final score was unbeatable.","zh":"她最后的成绩无人能够超越。"}]},{"pos":"adj.","meaning":"无与伦比的；极好的","definition":"better than competing alternatives","examples":[{"en":"The shop offers unbeatable value.","zh":"这家店提供的商品物超所值。"},{"en":"The balcony gives an unbeatable view of the harbour.","zh":"阳台可以欣赏到无与伦比的海港景色。"}]}],"unbiased":[{"pos":"adj.","meaning":"公正的；无偏见的","definition":"Not favouring one side unfairly.","examples":[{"en":"We need an unbiased assessment.","zh":"我们需要公正的评估。"},{"en":"The article presents an unbiased account of the debate.","zh":"文章公正地叙述了辩论经过。"}]}],"unblemished":[{"pos":"adj.","meaning":"无瑕疵的；完好的","definition":"without marks, damage, or faults","examples":[{"en":"The vase was old but unblemished.","zh":"花瓶虽旧，却完好无损。"},{"en":"He had an unblemished record of public service.","zh":"他的公共服务履历没有污点。"}]}],"uncertainty":[{"pos":"n.","meaning":"不确定性；未知状态","definition":"a lack of definite knowledge about what will happen","examples":[{"en":"Uncertainty about the weather delayed the trip.","zh":"天气的不确定性使旅行推迟了。"},{"en":"The estimate includes a measure of uncertainty.","zh":"这个估计包含一个不确定程度指标。"}]},{"pos":"n.","meaning":"犹豫；迟疑；疑虑","definition":"a feeling of being unsure","examples":[{"en":"There was uncertainty in his voice.","zh":"他的声音里带着迟疑。"},{"en":"She described her uncertainty about choosing a career.","zh":"她描述了自己在职业选择上的犹豫。"}]}],"unconcerned":[{"pos":"adj.","meaning":"漠不关心的；不在意的","definition":"Not interested or worried about something.","examples":[{"en":"He seemed unconcerned by the delay.","zh":"他似乎不在意延误。"},{"en":"The company remained unconcerned about residents' complaints.","zh":"公司对居民投诉仍漠不关心。"}]}],"unconquerable":[{"pos":"adj.","meaning":"不可征服的；不可战胜的","definition":"unable to be defeated or overcome","examples":[{"en":"The memoir celebrates her unconquerable spirit.","zh":"这本回忆录赞颂了她不可战胜的精神。"},{"en":"The explorers faced what seemed an unconquerable challenge.","zh":"探险者面对着一个似乎无法战胜的挑战。"}]}],"underestimate":[{"pos":"v.","meaning":"低估","definition":"to judge an amount, ability, or difficulty as smaller than it is","ipa":"/ˌʌndərˈestɪmeɪt/","examples":[{"en":"We underestimated the time needed for the repairs.","zh":"我们低估了维修所需的时间。"},{"en":"Do not underestimate her ability to solve the problem.","zh":"不要低估她解决这个问题的能力。"}]},{"pos":"n.","meaning":"低估；过低的估计","definition":"an estimate that is below the true amount","ipa":"/ˌʌndərˈestɪmət/","examples":[{"en":"The initial cost figure was an underestimate.","zh":"最初的成本数字低估了实际费用。"},{"en":"Even this large number may be an underestimate.","zh":"即使这个数字很大，也可能仍低于实际数量。"}]}],"undergraduate":[{"pos":"n.","meaning":"大学本科生","definition":"A student studying for a first university degree.","examples":[{"en":"The course is open to all undergraduates.","zh":"这门课面向所有本科生。"},{"en":"She was an undergraduate when she began the project.","zh":"她开始这个项目时还是本科生。"}]}],"underground":[{"pos":"adj.","meaning":"地下的","definition":"located below the surface of the ground","ipa":"/ˈʌndəɡraʊnd/","examples":[{"en":"The building has an underground car park.","zh":"这栋建筑有地下停车场。"},{"en":"Water flows through underground channels.","zh":"水流经地下通道。"}]},{"pos":"n.","meaning":"地铁（英式）","definition":"an urban railway running mainly below ground","ipa":"/ˈʌndəɡraʊnd/","examples":[{"en":"We took the underground to the museum.","zh":"我们乘地铁去了博物馆。"},{"en":"The underground was crowded during the morning rush.","zh":"早高峰时地铁很拥挤。"}]},{"pos":"adv.","meaning":"在地下；向地下","definition":"below the surface of the ground","ipa":"/ˌʌndəˈɡraʊnd/","examples":[{"en":"The cable runs underground.","zh":"电缆铺设在地下。"},{"en":"The animals spend much of the winter underground.","zh":"这些动物在地下度过冬天的大部分时间。"}]}],"underline":[{"pos":"v.","meaning":"在下面画线","definition":"to draw a line beneath a word or passage","examples":[{"en":"Underline the main verb in each sentence.","zh":"在每句的主要动词下面画线。"},{"en":"She underlined the deadline in red.","zh":"她用红色在截止日期下面画了线。"}]},{"pos":"v.","meaning":"强调；突出","definition":"to show the importance of something","examples":[{"en":"The findings underline the need for better data.","zh":"这些发现凸显了改善数据的必要性。"},{"en":"His example underlines the importance of preparation.","zh":"他的例子强调了准备的重要性。"}]}],"underling":[{"pos":"n.","meaning":"下属；部下（常含轻视）","definition":"A person of lower rank who works for someone else.","examples":[{"en":"The arrogant manager blamed an underling for the mistake.","zh":"傲慢的经理把错误归咎于一名下属。"},{"en":"He treated his assistants as underlings rather than colleagues.","zh":"他把助手当作地位低下的部属，而非同事。"}]}],"underlying":[{"pos":"adj.","meaning":"下面的；下层的","definition":"lying beneath another layer","examples":[{"en":"The scan revealed damage to the underlying tissue.","zh":"扫描发现了下层组织的损伤。"},{"en":"Rain exposed the underlying rock.","zh":"雨水冲刷露出了下面的岩石。"}]},{"pos":"adj.","meaning":"根本的；潜在的；隐含的","definition":"forming the basic but not always obvious cause or principle","examples":[{"en":"We need to understand the underlying problem.","zh":"我们需要理解根本问题。"},{"en":"The two proposals share an underlying assumption.","zh":"这两项提案有一个共同的隐含假设。"}]}],"undermine":[{"pos":"v.","meaning":"削弱；损害","definition":"to weaken something gradually","examples":[{"en":"False information can undermine public trust.","zh":"虚假信息可能削弱公众信任。"},{"en":"Unfair treatment may undermine employee motivation.","zh":"不公平待遇可能削弱员工积极性。"},{"en":"Poor maintenance can undermine the safety of a building.","zh":"维护不善可能损害建筑安全。"}]}],"underneath":[{"pos":"prep.","meaning":"在……下面；在……底下","definition":"Directly below or covered by something.","examples":[{"en":"The cat slept underneath the table.","zh":"猫睡在桌子下面。"},{"en":"A tunnel passes underneath the river.","zh":"一条隧道从河底穿过。"}]},{"pos":"adv.","meaning":"在下面；在底下","definition":"In a lower position without a following noun.","examples":[{"en":"Lift the cloth and look underneath.","zh":"掀起布看看下面。"},{"en":"She wore a coat with a thin sweater underneath.","zh":"她穿着外套，里面是一件薄毛衣。"}]},{"pos":"n.","meaning":"底部；下表面","definition":"The lower part or surface of something.","examples":[{"en":"The underneath of the boat was badly scratched.","zh":"船底被划得很严重。"},{"en":"He painted the underneath of the shelf.","zh":"他给搁板的底面刷了漆。"}]}],"underpin":[{"pos":"v.","meaning":"加固地基","definition":"to strengthen the supports beneath a building","examples":[{"en":"Builders underpinned the wall before repairing it.","zh":"施工人员在修墙前加固了地基。"},{"en":"The old house needed to be underpinned.","zh":"这栋老房子的地基需要加固。"}]},{"pos":"v.","meaning":"支撑；巩固","definition":"to provide an essential basis or support","examples":[{"en":"Reliable data underpin the whole analysis.","zh":"可靠的数据支撑着整个分析。"},{"en":"Mutual trust underpins their partnership.","zh":"相互信任是他们合作关系的基础。"}]}],"understandable":[{"pos":"adj.","meaning":"可以理解的；能懂的","definition":"clear enough to be understood","examples":[{"en":"The guide uses understandable language.","zh":"这份指南使用易懂的语言。"},{"en":"The diagram makes the process more understandable.","zh":"图示使这个过程更容易理解。"}]},{"pos":"adj.","meaning":"情有可原的；可以体谅的","definition":"reasonable or easy to sympathise with","examples":[{"en":"Her disappointment was understandable.","zh":"她的失望是可以理解的。"},{"en":"Their concern about the delay is understandable.","zh":"他们对延误的担忧情有可原。"}]}],"understanding":[{"pos":"n.","meaning":"理解；领会","definition":"Knowledge of how something works or what it means.","examples":[{"en":"The diagram improved my understanding of the process.","zh":"图解加深了我对过程的理解。"},{"en":"She has a deep understanding of local history.","zh":"她对当地历史有深入理解。"}]},{"pos":"n.","meaning":"谅解；默契；非正式协议","definition":"Sympathetic acceptance or an agreement between people.","examples":[{"en":"Thank you for your understanding during the delay.","zh":"感谢你在延误期间给予谅解。"},{"en":"They reached an understanding about sharing expenses.","zh":"他们就分摊费用达成了默契。"}]},{"pos":"adj.","meaning":"体谅的；宽容的","definition":"Showing sympathy and patience.","examples":[{"en":"Her supervisor was understanding about the family emergency.","zh":"主管体谅她家中发生的紧急情况。"},{"en":"We need an understanding listener.","zh":"我们需要一个体谅他人的倾听者。"}]}],"undertake":[{"pos":"v.","meaning":"承担；着手从事","definition":"to take responsibility for a task or start doing it","examples":[{"en":"The team will undertake a detailed survey.","zh":"团队将开展一项详细调查。"},{"en":"She undertook the difficult task of organising the archive.","zh":"她承担了整理档案这项艰巨任务。"}]},{"pos":"v.","meaning":"承诺；答应","definition":"to formally agree to do something","examples":[{"en":"The company undertook to finish the work by June.","zh":"公司承诺在六月前完工。"},{"en":"He undertook to keep the information confidential.","zh":"他答应对这些信息保密。"}]}],"undetected":[{"pos":"adj.","meaning":"未被发现的","definition":"not noticed or discovered","examples":[{"en":"The error remained undetected for several weeks.","zh":"这个错误几周都未被发现。"},{"en":"A small leak went undetected behind the wall.","zh":"墙后的一处小漏水没有被察觉。"}]}],"undisguised":[{"pos":"adj.","meaning":"毫不掩饰的；公开的；坦率流露的","definition":"Openly shown rather than hidden.","examples":[{"en":"She watched with undisguised delight.","zh":"她毫不掩饰喜悦地看着。"},{"en":"His undisguised hostility made the meeting uncomfortable.","zh":"他不加掩饰的敌意使会议气氛尴尬。"}]}],"undoubtedly":[{"pos":"adv.","meaning":"无疑地；确实地","definition":"without reasonable doubt","examples":[{"en":"The new bridge will undoubtedly improve access.","zh":"新桥无疑会改善交通条件。"},{"en":"She is undoubtedly the most experienced member of the team.","zh":"她无疑是团队中经验最丰富的成员。"}]}],"uneasy":[{"pos":"adj.","meaning":"不安的；担忧的","definition":"feeling worried or uncomfortable","examples":[{"en":"She felt uneasy about the sudden change.","zh":"她对突然的变化感到不安。"},{"en":"There was an uneasy silence in the room.","zh":"房间里一片令人不安的沉默。"}]}],"unemployment":[{"pos":"n.","meaning":"失业；失业状况；失业人数","definition":"The condition or extent of people being without paid work.","examples":[{"en":"Unemployment rose after the factory closed.","zh":"工厂关闭后，失业人数增加。"},{"en":"The programme helps people facing long-term unemployment.","zh":"这个项目帮助长期失业者。"}]}],"unexpected":[{"pos":"adj.","meaning":"意外的；未预料到的","definition":"not expected in advance","examples":[{"en":"An unexpected delay changed our plans.","zh":"一次意外延误改变了我们的计划。"},{"en":"She received an unexpected invitation to speak.","zh":"她意外收到了一份演讲邀请。"}]}],"unfortunately":[{"pos":"adv.","meaning":"不幸地；遗憾地","definition":"used to introduce an unhappy or disappointing fact","examples":[{"en":"Unfortunately, the last train had already left.","zh":"遗憾的是，末班火车已经开走了。"},{"en":"The plan was promising but unfortunately too expensive.","zh":"这个计划很有前景，可惜成本太高。"}]}],"uniform":[{"pos":"n.","meaning":"制服","definition":"A standard set of clothes worn by members of a group.","examples":[{"en":"The nurses wore blue uniforms.","zh":"护士穿着蓝色制服。"},{"en":"Students must wear the school uniform.","zh":"学生必须穿校服。"}]},{"pos":"adj.","meaning":"一致的；统一的；相同的","definition":"The same in appearance, amount, or character throughout.","examples":[{"en":"Cut the pieces to a uniform size.","zh":"把这些东西切成统一大小。"},{"en":"The rules should be uniform across all branches.","zh":"各分部的规则应保持一致。"}]}],"union":[{"pos":"n.","meaning":"工会；协会；联盟","definition":"an organisation formed to represent shared interests","examples":[{"en":"The union represents workers at several factories.","zh":"这个工会代表几家工厂的工人。"},{"en":"The student union arranged a welcome event.","zh":"学生会安排了一场迎新活动。"}]},{"pos":"n.","meaning":"联合；结合","definition":"the act or state of joining together","examples":[{"en":"The ceremony celebrated the union of the two families.","zh":"仪式庆祝了两个家庭的结合。"},{"en":"The organisation grew from the union of three smaller groups.","zh":"这个组织由三个较小团体合并而成。"}]}],"unique":[{"pos":"adj.","meaning":"独一无二的；唯一的","definition":"being the only one of its kind","examples":[{"en":"Each handmade bowl has a unique pattern.","zh":"每个手工碗都有独一无二的图案。"},{"en":"The island is home to a unique species of bird.","zh":"这座岛是一个独有鸟种的家园。"}]},{"pos":"adj.","meaning":"极不寻常的；独特的","definition":"remarkably different from what is usual","examples":[{"en":"The course offers a unique learning experience.","zh":"这门课程提供了独特的学习体验。"},{"en":"Her unique approach attracted international attention.","zh":"她独特的方法引起了国际关注。"}]}],"universe":[{"pos":"n.","meaning":"宇宙；天地万物","definition":"All space and everything that exists within it.","examples":[{"en":"The telescope helps scientists study the early universe.","zh":"望远镜帮助科学家研究早期宇宙。"},{"en":"The lecture explored the scale of the universe.","zh":"讲座探讨了宇宙的尺度。"}]},{"pos":"n.","meaning":"世界；领域；全部范围","definition":"A complete field of experience or a self-contained world.","examples":[{"en":"Books opened a new universe of ideas for her.","zh":"书籍为她打开了一个全新的思想世界。"},{"en":"The novel creates its own imaginative universe.","zh":"小说创造了自己的想象世界。"}]}],"unload":[{"pos":"v.","meaning":"卸下；卸货","definition":"to remove goods from a vehicle or container","examples":[{"en":"Workers unloaded the boxes from the van.","zh":"工人从货车上卸下箱子。"},{"en":"The ship will unload its cargo tomorrow.","zh":"船将于明天卸货。"}]},{"pos":"v.","meaning":"摆脱；倾诉负担","definition":"to get rid of a burden or share worries","examples":[{"en":"He unloaded his worries on a trusted friend.","zh":"他向一位可信赖的朋友倾诉烦恼。"},{"en":"The firm wanted to unload its unused equipment.","zh":"这家公司想处理掉闲置设备。"}]}],"unobtrusive":[{"pos":"adj.","meaning":"不显眼的；不张扬的","definition":"not drawing unwanted attention","examples":[{"en":"The hotel staff were helpful but unobtrusive.","zh":"酒店员工乐于助人又不打扰客人。"},{"en":"An unobtrusive sign marks the entrance.","zh":"一个不起眼的标志标出了入口。"}]}],"unparalleled":[{"pos":"adj.","meaning":"无与伦比的；空前的","definition":"Having no equal or previous example.","examples":[{"en":"The project achieved unparalleled accuracy.","zh":"项目实现了前所未有的精度。"},{"en":"The region experienced growth on an unparalleled scale.","zh":"该地区经历了空前规模的增长。"}]}],"unprejudiced":[{"pos":"adj.","meaning":"无偏见的；公正的","definition":"not influenced by unfair opinions","examples":[{"en":"The panel needs an unprejudiced assessment of the evidence.","zh":"评审组需要对证据作公正评估。"},{"en":"She approached the debate with an unprejudiced mind.","zh":"她以不带偏见的态度参与辩论。"}]}],"unquote":[{"pos":"v.","meaning":"结束引语（口头标记）","definition":"to mark the end of words being quoted aloud","examples":[{"en":"He called the plan quote ambitious unquote.","zh":"他称这个计划是“雄心勃勃的”，并用口头引语标记说明。"},{"en":"She described the room as quote cosy unquote, with a doubtful smile.","zh":"她带着怀疑的微笑，口头引用“舒适”来描述房间。"}]}],"unrealistic":[{"pos":"adj.","meaning":"不现实的；不切实际的","definition":"Not based on what is likely or practically possible.","examples":[{"en":"The deadline is unrealistic.","zh":"截止期限不切实际。"},{"en":"It is unrealistic to expect immediate results.","zh":"期待立刻见效是不现实的。"}]}],"unregistered":[{"pos":"adj.","meaning":"未注册的；未登记的","definition":"not officially recorded on a register","examples":[{"en":"Unregistered visitors must report to reception.","zh":"未登记的访客必须到前台报到。"},{"en":"The survey counted several unregistered businesses.","zh":"调查统计了几家未注册的企业。"}]}],"unsanitary":[{"pos":"adj.","meaning":"不卫生的","definition":"dirty or unsafe in ways that may spread illness","examples":[{"en":"The inspection found unsanitary conditions in the kitchen.","zh":"检查发现厨房条件不卫生。"},{"en":"Residents complained about the unsanitary waste area.","zh":"居民投诉垃圾区不卫生。"}]}],"unsatisfactory":[{"pos":"adj.","meaning":"不令人满意的；不合要求的","definition":"Not good enough or failing to meet expectations.","examples":[{"en":"The explanation was unsatisfactory.","zh":"这个解释不能令人满意。"},{"en":"Unsatisfactory repairs meant the roof still leaked.","zh":"维修不达标，屋顶仍然漏水。"}]}],"untrustworthy":[{"pos":"adj.","meaning":"不可信赖的；靠不住的","definition":"not deserving trust","examples":[{"en":"The website was removed because it supplied untrustworthy information.","zh":"该网站因提供不可靠信息而被下架。"},{"en":"He proved an untrustworthy partner.","zh":"他被证明是一个靠不住的伙伴。"}]}],"unveil":[{"pos":"v.","meaning":"揭开覆盖物；揭幕","definition":"to remove a covering so that something can be seen","examples":[{"en":"The mayor unveiled the new statue.","zh":"市长为新雕像揭幕。"},{"en":"She unveiled the painting at the opening ceremony.","zh":"她在开幕式上揭开了画作的覆盖物。"}]},{"pos":"v.","meaning":"公布；首次展示","definition":"to make something known publicly for the first time","examples":[{"en":"The team unveiled its design for the bridge.","zh":"团队首次公布了桥梁设计。"},{"en":"The company will unveil the new product next month.","zh":"公司将在下个月展示新产品。"}]}],"unwrap":[{"pos":"v.","meaning":"拆开包装；打开包裹","definition":"To remove the covering from something.","examples":[{"en":"The children unwrapped their gifts.","zh":"孩子们拆开礼物。"},{"en":"Unwrap the cheese before placing it on the board.","zh":"把奶酪拆开包装后放到板上。"}]}],"unyielding":[{"pos":"adj.","meaning":"坚决的；不屈服的","definition":"refusing to change a decision or attitude","examples":[{"en":"She remained unyielding in her opposition to the plan.","zh":"她坚决反对这个计划，毫不动摇。"},{"en":"The negotiators met an unyielding response.","zh":"谈判者得到了一份毫不让步的答复。"}]},{"pos":"adj.","meaning":"坚硬的；不能弯曲的","definition":"not bending or giving way under pressure","examples":[{"en":"The ground was hard and unyielding after the frost.","zh":"霜冻后，地面坚硬结实。"},{"en":"He leaned against an unyielding stone wall.","zh":"他靠着一堵坚硬的石墙。"}]}],"up-to-date":[{"pos":"adj.","meaning":"最新的；现代的","definition":"containing the latest information or using current methods","examples":[{"en":"The website provides up-to-date travel information.","zh":"网站提供最新的出行信息。"},{"en":"The laboratory needs up-to-date equipment.","zh":"实验室需要现代化设备。"}]}],"upgrade":[{"pos":"v.","meaning":"升级；改进；提高等级","definition":"To improve quality or move to a better level.","examples":[{"en":"The school upgraded its computers.","zh":"学校升级了电脑。"},{"en":"The airline upgraded them to larger seats.","zh":"航空公司给他们升到了更宽敞的座位。"}],"ipa":"/ʌpˈɡreɪd/"},{"pos":"n.","meaning":"升级；改善；改进版","definition":"An improvement or a better version.","examples":[{"en":"The software upgrade fixed several errors.","zh":"软件升级修复了几处错误。"},{"en":"The room upgrade was included in the price.","zh":"房间升级包含在价格中。"}],"ipa":"/ˈʌpɡreɪd/"},{"pos":"n.","meaning":"上坡；向上的斜坡","definition":"An upward slope.","examples":[{"en":"The truck slowed on the steep upgrade.","zh":"卡车在陡上坡上减速了。"},{"en":"The railway faces a long upgrade beyond the station.","zh":"铁路过站后有一段长上坡。"}],"ipa":"/ˈʌpɡreɪd/"}],"uphill":[{"pos":"adv.","meaning":"向山上；上坡","definition":"towards a higher point on a slope","examples":[{"en":"We walked uphill towards the tower.","zh":"我们朝塔的方向走上坡。"},{"en":"Cycling uphill took longer than we expected.","zh":"骑车上坡比我们预计的耗时更长。"}]},{"pos":"adj.","meaning":"上坡的","definition":"rising towards higher ground","examples":[{"en":"The final kilometre is an uphill section.","zh":"最后一公里是一段上坡路。"},{"en":"The uphill path offers a view of the valley.","zh":"上坡的小路可以眺望山谷。"}]},{"pos":"adj.","meaning":"艰难的；费力的","definition":"requiring great effort against difficulties","examples":[{"en":"Winning back public trust will be an uphill struggle.","zh":"重新赢得公众信任将十分艰难。"},{"en":"The small team faced an uphill task.","zh":"这个小团队面临艰巨任务。"}]}],"upper":[{"pos":"adj.","meaning":"上面的；上部的","definition":"located above another part","examples":[{"en":"The books are on the upper shelf.","zh":"书在上层架子上。"},{"en":"The upper floor has three bedrooms.","zh":"楼上有三间卧室。"}]},{"pos":"adj.","meaning":"较高地位的；较高级的","definition":"higher in rank, level, or position","examples":[{"en":"The issue was discussed by upper management.","zh":"高层管理人员讨论了这个问题。"},{"en":"Students in the upper grades take more specialised courses.","zh":"高年级学生修读更多专业化课程。"}]}],"upset":[{"pos":"v.","meaning":"使心烦；使苦恼","definition":"To cause worry or emotional distress.","examples":[{"en":"The criticism upset her.","zh":"批评让她难过。"},{"en":"I did not mean to upset you.","zh":"我不是故意让你心烦的。"}]},{"pos":"v.","meaning":"打乱；推翻；弄翻","definition":"To disturb a plan or balance or turn something over.","examples":[{"en":"The storm upset our travel plans.","zh":"暴风雨打乱了我们的旅行计划。"},{"en":"The child upset a cup of water.","zh":"孩子碰翻了一杯水。"}]},{"pos":"adj.","meaning":"心烦的；难过的","definition":"Worried, unhappy, or distressed.","examples":[{"en":"She was upset about missing the train.","zh":"她因错过火车而心烦。"},{"en":"He looked upset after the phone call.","zh":"接完电话后，他显得很难过。"}]},{"pos":"adj.","meaning":"不适的；不舒服的（尤指胃）","definition":"Temporarily disturbed or unwell, especially in the stomach.","examples":[{"en":"An upset stomach kept him at home.","zh":"胃不舒服使他待在家里。"},{"en":"She complained of an upset stomach after the journey.","zh":"旅程结束后，她说自己胃不舒服。"}]}],"urban":[{"pos":"adj.","meaning":"城市的；都市的","definition":"relating to towns and cities","examples":[{"en":"Urban parks provide valuable open space.","zh":"城市公园提供了宝贵的开放空间。"},{"en":"The study compares urban and rural lifestyles.","zh":"这项研究比较城市与乡村的生活方式。"}]}],"urbanisation":[{"pos":"n.","meaning":"城市化","definition":"the growth of towns and cities","examples":[{"en":"Rapid urbanisation puts pressure on housing.","zh":"快速城市化给住房带来压力。"},{"en":"Urbanisation can create new employment opportunities.","zh":"城市化可以创造新的就业机会。"},{"en":"Careful planning is needed to manage urbanisation.","zh":"需要周密规划来应对城市化。"}]}],"urbanization":[{"pos":"n.","meaning":"城市化；都市化","definition":"The growth of cities and the movement of people into them.","examples":[{"en":"Rapid urbanization increased demand for housing.","zh":"快速城市化增加了住房需求。"},{"en":"The study examines urbanization along the coast.","zh":"研究考察了沿海城市化。"}]}],"urge":[{"pos":"v.","meaning":"敦促；力劝","definition":"to strongly encourage someone to act","examples":[{"en":"The teacher urged us to check our sources.","zh":"老师敦促我们核实信息来源。"},{"en":"She urged him to apply before the deadline.","zh":"她力劝他在截止日期前申请。"}]},{"pos":"v.","meaning":"竭力主张","definition":"to strongly recommend a course of action","examples":[{"en":"The report urges greater investment in public transport.","zh":"报告竭力主张加大公共交通投资。"},{"en":"Residents urged caution before any further development.","zh":"居民强烈建议在进一步开发前谨慎行事。"}]},{"pos":"n.","meaning":"强烈愿望；冲动","definition":"a strong desire to do something","examples":[{"en":"He felt an urge to explore the narrow street.","zh":"他很想探索那条狭窄的街道。"},{"en":"She resisted the urge to interrupt.","zh":"她克制了打断别人的冲动。"}]}],"urgent":[{"pos":"adj.","meaning":"紧急的；紧迫的","definition":"requiring immediate attention or action","examples":[{"en":"The office received an urgent request for assistance.","zh":"办公室收到了紧急求助请求。"},{"en":"Repairs to the roof are becoming urgent.","zh":"屋顶维修变得越来越紧迫。"}]},{"pos":"adj.","meaning":"急切的；催促的","definition":"expressing a strong need for immediate action","examples":[{"en":"There was an urgent knock at the door.","zh":"门外传来急促的敲门声。"},{"en":"Her urgent tone made everyone stop talking.","zh":"她急切的语气让所有人都停止了交谈。"}]}],"utilise":[{"pos":"v.","meaning":"利用；使用；运用","definition":"To make practical use of something.","examples":[{"en":"The system utilises waste heat.","zh":"这个系统利用余热。"},{"en":"We should utilise the available space more effectively.","zh":"我们应更有效地利用现有空间。"}]}],"utility":[{"pos":"n.","meaning":"效用；功用","definition":"the usefulness of something","examples":[{"en":"The design balances beauty and utility.","zh":"这项设计兼顾美观与实用。"},{"en":"The utility of the tool depends on the task.","zh":"这个工具是否有用取决于任务。"}]},{"pos":"n.","meaning":"公用事业；公用事业公司","definition":"a service such as electricity or water supplied to the public","examples":[{"en":"The local utility repaired the damaged power line.","zh":"当地公用事业公司修复了受损电线。"},{"en":"Rent does not include utilities.","zh":"房租不包括水电等公用事业费用。"}]}],"utilization":[{"pos":"n.","meaning":"利用；使用","definition":"the use of something for a practical purpose","examples":[{"en":"The report examines energy utilization in factories.","zh":"报告考察了工厂的能源利用情况。"},{"en":"Better utilization of space made the room more useful.","zh":"更合理地利用空间使房间更实用。"}]}],"utterance":[{"pos":"n.","meaning":"话语；言论","definition":"Something spoken.","examples":[{"en":"The recording contains several unclear utterances.","zh":"录音中有几句不清楚的话。"},{"en":"Her final utterance was a quiet apology.","zh":"她最后说的是一句轻声道歉。"}]},{"pos":"n.","meaning":"说话；表达；发声","definition":"The act of expressing something in speech.","examples":[{"en":"The poem gives utterance to feelings of loss.","zh":"这首诗表达了失落之情。"},{"en":"He struggled with the utterance of the unfamiliar sound.","zh":"他费力地发出那个陌生音。"}]}],"vacancy":[{"pos":"n.","meaning":"职位空缺","definition":"a job that is available","examples":[{"en":"The hotel has a vacancy for a receptionist.","zh":"这家酒店有一个前台接待职位空缺。"},{"en":"The vacancy will be advertised on Monday.","zh":"招聘空缺将于周一公布。"},{"en":"Please contact us if you are interested in this vacancy.","zh":"如果你对这个空缺职位感兴趣，请联系我们。"}]},{"pos":"n.","meaning":"空房;空位;空缺处","definition":"an available unoccupied space","examples":[{"en":"The hotel has no vacancies tonight.","zh":"酒店今晚没有空房。"},{"en":"The sudden departure left a vacancy at the table.","zh":"突然离席在桌边留下一个空位。"}]},{"pos":"n.","meaning":"茫然;空虚;心不在焉","definition":"absence of thought or awareness","examples":[{"en":"An expression of vacancy crossed his face.","zh":"他脸上掠过茫然神情。"},{"en":"Her cheerful voice concealed an inner vacancy.","zh":"她欢快的声音掩盖了内心空虚。"}]}],"vacant":[{"pos":"adj.","meaning":"空的；未被占用的","definition":"available because nobody is occupying it","examples":[{"en":"The flat has been vacant for months.","zh":"这套公寓已空置数月。"},{"en":"Two positions remain vacant in the department.","zh":"部门里仍有两个职位空缺。"}]},{"pos":"adj.","meaning":"茫然的；无神的","definition":"showing little thought or attention","examples":[{"en":"He stared at the screen with a vacant expression.","zh":"他神情茫然地盯着屏幕。"},{"en":"Her vacant look suggested that she had not heard the question.","zh":"她无神的表情表明她没有听到问题。"}]}],"vacation":[{"pos":"n.","meaning":"假期；休假","definition":"A period away from work or study for rest or travel.","examples":[{"en":"We spent our vacation by the sea.","zh":"我们在海边度假。"},{"en":"She has two weeks of vacation remaining.","zh":"她还剩两周假期。"}]}],"vacuum":[{"pos":"n.","meaning":"真空","definition":"a space containing little or no matter","examples":[{"en":"The experiment was performed in a vacuum.","zh":"实验在真空中进行。"},{"en":"The container maintains a partial vacuum.","zh":"容器保持着部分真空状态。"}]},{"pos":"n.","meaning":"真空吸尘器","definition":"a machine that removes dust by suction","examples":[{"en":"The vacuum is stored in the cupboard.","zh":"吸尘器放在橱柜里。"},{"en":"Our old vacuum makes a loud noise.","zh":"我们的旧吸尘器噪声很大。"}]},{"pos":"v.","meaning":"用吸尘器清扫","definition":"to clean using a vacuum cleaner","examples":[{"en":"She vacuumed the carpet before the guests arrived.","zh":"客人到来前，她用吸尘器清扫了地毯。"},{"en":"Please vacuum under the table as well.","zh":"也请用吸尘器清扫桌子下面。"}]}],"vague":[{"pos":"adj.","meaning":"模糊的；含糊的","definition":"not clear, exact, or detailed","examples":[{"en":"The instructions were too vague to follow.","zh":"说明太含糊，无法照着做。"},{"en":"I have a vague memory of visiting that town.","zh":"我模糊记得去过那个镇。"}]}],"valid":[{"pos":"adj.","meaning":"合理的；成立的","definition":"based on sound reasoning or evidence","examples":[{"en":"She raised a valid concern about the cost.","zh":"她对费用提出了合理的担忧。"},{"en":"The conclusion is only valid if the data are accurate.","zh":"只有数据准确，结论才成立。"},{"en":"There are valid reasons for opposing the proposal.","zh":"有合理理由反对该提议。"}]},{"pos":"adj.","meaning":"有效的；有法律效力的","definition":"Legally or officially acceptable and usable.","examples":[{"en":"The ticket is valid for one month.","zh":"这张票有效期为一个月。"},{"en":"Both parties confirmed that the agreement remained valid.","zh":"双方确认协议仍然有效。"}]}],"valuable":[{"pos":"adj.","meaning":"贵重的；值钱的","definition":"worth a substantial amount of money","examples":[{"en":"The museum keeps valuable objects in secure cases.","zh":"博物馆把贵重物品存放在安全展柜中。"},{"en":"The damaged painting was extremely valuable.","zh":"那幅受损的画极其贵重。"}]},{"pos":"adj.","meaning":"有价值的；有用的","definition":"providing important help or benefit","examples":[{"en":"The interview gave us valuable information.","zh":"这次访谈给了我们有价值的信息。"},{"en":"Her experience proved valuable to the team.","zh":"她的经验对团队很有帮助。"}]},{"pos":"n.","meaning":"贵重物品（通常用 valuables）","definition":"a possession worth a lot of money","examples":[{"en":"Keep your valuables with you on the train.","zh":"乘火车时，请随身保管贵重物品。"},{"en":"The hotel provides a safe for valuables.","zh":"酒店提供贵重物品保险箱。"}]}],"van":[{"pos":"n.","meaning":"厢式货车；运货车","definition":"a road vehicle with an enclosed space for carrying goods or people","examples":[{"en":"The delivery van arrived before breakfast.","zh":"送货车在早餐前到达了。"},{"en":"They loaded the equipment into a rented van.","zh":"他们把设备装进一辆租来的货车。"}]}],"vanish":[{"pos":"v.","meaning":"消失；不复存在","definition":"To disappear suddenly or completely.","examples":[{"en":"The boat vanished into the mist.","zh":"船消失在雾中。"},{"en":"Her doubts vanished after the explanation.","zh":"解释之后，她的疑虑消失了。"}]}],"variability":[{"pos":"n.","meaning":"可变性；变异性","definition":"the extent to which something changes or differs","examples":[{"en":"The study measured variability in rainfall.","zh":"这项研究测量了降雨量的变化程度。"},{"en":"Natural variability makes exact prediction difficult.","zh":"自然变异性使精确预测变得困难。"}]}],"variant":[{"pos":"adj.","meaning":"不同的；变异的","definition":"differing from a usual or related form","examples":[{"en":"The dictionary lists several variant spellings.","zh":"词典列出了几种不同拼法。"},{"en":"The two manuscripts contain variant readings of the same line.","zh":"两份手稿对同一句话有不同的文本形式。"}]},{"pos":"n.","meaning":"变体；变种","definition":"a related but different form of something","examples":[{"en":"This song is a regional variant of an older melody.","zh":"这首歌是一个更古老曲调的地方变体。"},{"en":"The software is available in two variants.","zh":"这款软件有两个不同版本。"}]},{"pos":"n.","meaning":"随机变量；变量值（统计学少见用法）","definition":"a statistical variate or one of its numerical values","examples":[{"en":"The old statistics text treats height as a measurable variant.","zh":"这本旧统计学教材把身高视为可测量的变量。"},{"en":"Each observed variant was entered into the frequency table.","zh":"每个观测到的变量值都被填入频数表。"}]}],"variation":[{"pos":"n.","meaning":"变化；差异；变动","definition":"A difference or change in amount, form, or condition.","examples":[{"en":"The data show seasonal variation.","zh":"数据表明存在季节变化。"},{"en":"There is considerable variation between the samples.","zh":"样本之间存在明显差异。"}]},{"pos":"n.","meaning":"变种；变体；变异","definition":"A modified form or biological difference.","examples":[{"en":"This dish is a variation on a traditional recipe.","zh":"这道菜是传统配方的一种变体。"},{"en":"Genetic variation exists within the population.","zh":"群体内部存在遗传变异。"}]},{"pos":"n.","meaning":"变奏","definition":"A changed version of a musical theme.","examples":[{"en":"The pianist played six variations on the theme.","zh":"钢琴家演奏了这个主题的六段变奏。"},{"en":"The final variation introduces a slower rhythm.","zh":"最后一段变奏引入了更慢的节奏。"}]}],"variety":[{"pos":"n.","meaning":"品种；种类","definition":"a particular type within a larger group","examples":[{"en":"This variety of apple keeps well in storage.","zh":"这种苹果品种很耐储存。"},{"en":"The garden contains several varieties of roses.","zh":"花园里有几个品种的玫瑰。"}]},{"pos":"n.","meaning":"多样性；变化","definition":"the presence of different types or experiences","examples":[{"en":"The job offers plenty of variety.","zh":"这份工作的内容丰富多样。"},{"en":"A variety of viewpoints improved the discussion.","zh":"多样的观点使讨论更有成效。"}]}],"various":[{"pos":"adj.","meaning":"各种各样的；不同的","definition":"of several different kinds","examples":[{"en":"The workshop attracted people from various professions.","zh":"研讨会吸引了来自不同职业的人。"},{"en":"We considered various ways to reduce waste.","zh":"我们考虑了减少浪费的多种方法。"}]}],"vary":[{"pos":"v.","meaning":"变化；不同","definition":"To differ or change from one situation to another.","examples":[{"en":"Prices vary between shops.","zh":"各商店价格不同。"},{"en":"The temperature varies throughout the day.","zh":"气温全天变化。"}]},{"pos":"v.","meaning":"改变；使多样化","definition":"To make something different or less repetitive.","examples":[{"en":"Vary the activities to keep students interested.","zh":"变换活动以保持学生兴趣。"},{"en":"She varied the recipe by adding herbs.","zh":"她加入香草，改变了配方。"}]}],"vast":[{"pos":"adj.","meaning":"巨大的；广大的；大量的","definition":"extremely large in size or amount","examples":[{"en":"A vast plain stretched beyond the town.","zh":"城镇外延伸着一片广阔平原。"},{"en":"The archive contains a vast amount of information.","zh":"档案馆保存着大量信息。"}]}],"vegetarian":[{"pos":"n.","meaning":"素食者","definition":"a person who does not eat meat or fish","examples":[{"en":"One guest is a vegetarian, so we prepared a separate dish.","zh":"一位客人是素食者，所以我们另备了一道菜。"},{"en":"The restaurant is popular with vegetarians.","zh":"这家餐厅很受素食者欢迎。"}]},{"pos":"adj.","meaning":"素食的；适合素食者的","definition":"containing no meat or fish","examples":[{"en":"The menu includes several vegetarian options.","zh":"菜单包含几种素食选择。"},{"en":"She made a vegetarian curry for dinner.","zh":"她晚餐做了素食咖喱。"}]}],"vegetation":[{"pos":"n.","meaning":"植被；植物；草木","definition":"Plants growing in an area considered collectively.","examples":[{"en":"Dense vegetation covered the ruins.","zh":"茂密植被覆盖了废墟。"},{"en":"The fire destroyed much of the hillside vegetation.","zh":"大火毁掉了山坡上的大量植被。"}]}],"veil":[{"pos":"n.","meaning":"面纱","definition":"a thin covering worn over the face or head","examples":[{"en":"She lifted the veil from her face.","zh":"她揭开了脸上的面纱。"},{"en":"The portrait shows a woman wearing a blue veil.","zh":"画像上是一位戴蓝色面纱的女子。"}]},{"pos":"n.","meaning":"遮蔽物；掩饰","definition":"something that hides or partly covers another thing","examples":[{"en":"A veil of mist covered the valley.","zh":"一层薄雾笼罩着山谷。"},{"en":"The announcement lifted the veil of secrecy.","zh":"公告揭开了神秘面纱。"}]},{"pos":"v.","meaning":"遮盖；掩饰","definition":"to cover or hide something","examples":[{"en":"Clouds veiled the mountain summit.","zh":"云遮住了山顶。"},{"en":"He tried to veil his disappointment with a smile.","zh":"他试图用微笑掩饰失望。"}]}],"velocity":[{"pos":"n.","meaning":"速度；速率","definition":"the speed of motion, in physics including its direction","examples":[{"en":"The instrument measures the velocity of the moving air.","zh":"仪器测量流动空气的速度。"},{"en":"The ball's velocity changed when it struck the wall.","zh":"球撞墙后速度发生了变化。"}]}],"venomous":[{"pos":"adj.","meaning":"有毒液的；分泌毒液的","definition":"Able to inject a poisonous substance by biting or stinging.","examples":[{"en":"The guide pointed out a venomous snake.","zh":"向导指出了一条毒蛇。"},{"en":"The spider was identified as venomous.","zh":"这只蜘蛛被认定为有毒液的。"}]},{"pos":"adj.","meaning":"恶毒的；充满恶意的","definition":"Expressing bitter hatred or malice.","examples":[{"en":"She received a venomous letter.","zh":"她收到了一封恶毒的信。"},{"en":"His venomous remarks shocked the audience.","zh":"他的恶毒言论让观众震惊。"}]}],"ventilation":[{"pos":"n.","meaning":"通风；空气流通","definition":"the movement of fresh air through an enclosed space","examples":[{"en":"Good ventilation keeps the room comfortable.","zh":"良好的通风使房间保持舒适。"},{"en":"Open windows improved ventilation in the hall.","zh":"打开窗户改善了大厅的空气流通。"}]},{"pos":"n.","meaning":"通风系统；通风设备","definition":"equipment that circulates fresh air","examples":[{"en":"The building's ventilation needs regular maintenance.","zh":"建筑的通风系统需要定期维护。"},{"en":"The new ventilation removes air from the kitchen.","zh":"新的通风设备把空气从厨房排出。"}]}],"venture":[{"pos":"v.","meaning":"冒险前往","definition":"to go somewhere despite risk or uncertainty","examples":[{"en":"Few visitors venture beyond the marked path.","zh":"很少有游客冒险走出标记好的小路。"},{"en":"We ventured into the forest at dawn.","zh":"我们在黎明时冒险进入森林。"}]},{"pos":"v.","meaning":"敢于提出","definition":"to say something cautiously despite possible disagreement","examples":[{"en":"She ventured an opinion during the meeting.","zh":"她在会上试探着提出了意见。"},{"en":"May I venture a suggestion about the layout?","zh":"我可以试着对布局提个建议吗？"}]},{"pos":"v.","meaning":"拿来冒险；冒险投入","definition":"to risk money or something valuable","examples":[{"en":"He ventured his savings on a small business.","zh":"他冒险把积蓄投进了一家小企业。"},{"en":"The team was unwilling to venture more time on the untested idea.","zh":"团队不愿再冒险把时间投入未经验证的想法。"}]},{"pos":"n.","meaning":"冒险事业；风险项目","definition":"an activity or business involving uncertainty","examples":[{"en":"The café was their first business venture.","zh":"这家咖啡馆是他们第一次创业尝试。"},{"en":"The joint venture brought together two local firms.","zh":"这项合资事业使两家当地公司联合起来。"}]}],"venue":[{"pos":"n.","meaning":"场所；举办地点","definition":"The place where an event is held.","examples":[{"en":"The venue can hold three hundred people.","zh":"场地可容纳三百人。"},{"en":"They chose a new venue for the exhibition.","zh":"他们为展览选了新场地。"}]}],"verbal":[{"pos":"adj.","meaning":"口头的","definition":"spoken rather than written","examples":[{"en":"They reached a verbal agreement at the meeting.","zh":"他们在会上达成了口头协议。"},{"en":"The tutor gave verbal feedback after the presentation.","zh":"展示结束后，导师给了口头反馈。"}]},{"pos":"adj.","meaning":"言语的；文字的","definition":"relating to words and language","examples":[{"en":"The test measures verbal ability.","zh":"这项测试衡量语言能力。"},{"en":"Gestures can reinforce a verbal message.","zh":"手势可以强化语言信息。"}]},{"pos":"adj.","meaning":"动词的","definition":"relating to verbs in grammar","examples":[{"en":"The lesson covers several verbal forms.","zh":"这节课讲解几种动词形式。"},{"en":"The suffix changes the word's verbal meaning.","zh":"这个后缀改变了该词的动词意义。"}]}],"verdict":[{"pos":"n.","meaning":"裁决；判决","definition":"a formal decision reached in a legal case","examples":[{"en":"The jury returned its verdict after a long discussion.","zh":"陪审团长时间讨论后作出了裁决。"},{"en":"The family waited quietly for the verdict.","zh":"这家人静静等待判决。"}]},{"pos":"n.","meaning":"判断；定论；意见","definition":"a considered opinion about something","examples":[{"en":"What is your verdict on the new design?","zh":"你对新设计有什么看法？"},{"en":"The critics' verdict was largely positive.","zh":"评论家的评价大体积极。"}]}],"verification":[{"pos":"n.","meaning":"核实；查证；确认","definition":"The process of checking that something is true or accurate.","examples":[{"en":"The payment requires identity verification.","zh":"付款需要身份核验。"},{"en":"Independent verification confirmed the result.","zh":"独立核实证实了结果。"}]}],"verify":[{"pos":"v.","meaning":"核实；证实","definition":"to check that something is true or accurate","examples":[{"en":"Please verify the address before sending the parcel.","zh":"寄包裹前请核实地址。"},{"en":"Independent researchers verified the result.","zh":"独立研究人员证实了这个结果。"}]}],"vernacular":[{"pos":"n.","meaning":"本地语言；日常用语","definition":"the language used in everyday life by a community","examples":[{"en":"The guide spoke to the residents in the local vernacular.","zh":"导游用当地话与居民交谈。"},{"en":"The poet chose the vernacular rather than formal language.","zh":"诗人选择了日常用语而非正式语言。"}]},{"pos":"n.","meaning":"地方建筑风格","definition":"a traditional style shaped by local materials and practices","examples":[{"en":"The new houses draw on the regional vernacular.","zh":"这些新房借鉴了当地传统建筑风格。"},{"en":"Stone walls are central to the area's architectural vernacular.","zh":"石墙是该地区民间建筑风格的重要组成部分。"}]},{"pos":"adj.","meaning":"本地语言的；日常语言的","definition":"using the ordinary language of a community","examples":[{"en":"The library preserves vernacular literature.","zh":"图书馆保存着本土语言文学作品。"},{"en":"The translation uses familiar vernacular expressions.","zh":"译文使用熟悉的日常表达。"}]}],"versatile":[{"pos":"adj.","meaning":"多才多艺的；能适应多种工作的","definition":"Able to do many different things well.","examples":[{"en":"She is a versatile musician who plays several instruments.","zh":"她是一位多才多艺的音乐家，会演奏几种乐器。"},{"en":"The versatile actor moved easily between comedy and drama.","zh":"这位多才多艺的演员能自如驾驭喜剧和正剧。"}]},{"pos":"adj.","meaning":"多用途的；通用的","definition":"Useful for many different purposes.","examples":[{"en":"This versatile tool can cut and polish.","zh":"这个多功能工具可以切割和抛光。"},{"en":"The hall is a versatile space for meetings and performances.","zh":"礼堂是可供会议和演出的多用途空间。"}]}],"version":[{"pos":"n.","meaning":"版本；样式；型号","definition":"a particular form or edition of something","examples":[{"en":"The updated version fixes several errors.","zh":"更新版本修正了几个错误。"},{"en":"A smaller version of the device is now available.","zh":"现在可以买到这种设备的小型版本。"}]},{"pos":"n.","meaning":"说法；描述","definition":"a person's account of an event","examples":[{"en":"We heard two different versions of the incident.","zh":"我们听到了关于这件事的两种不同说法。"},{"en":"Her version includes details missing from the report.","zh":"她的描述包含了报告遗漏的细节。"}]},{"pos":"n.","meaning":"译本；改编本","definition":"a rendering of a text or work into another language or form","examples":[{"en":"I read the Chinese version of the novel.","zh":"我读了这部小说的中文译本。"},{"en":"The stage version is shorter than the original book.","zh":"舞台改编版比原著短。"}]}],"versus":[{"pos":"prep.","meaning":"对抗；与……相比","definition":"used to show opposition or comparison","examples":[{"en":"The final is North College versus South College.","zh":"决赛由北学院对阵南学院。"},{"en":"The essay compares public versus private transport.","zh":"这篇文章比较了公共交通与私人交通。"}]}],"vertebrate":[{"pos":"n.","meaning":"脊椎动物","definition":"An animal with a backbone.","examples":[{"en":"A frog is a vertebrate.","zh":"青蛙是脊椎动物。"},{"en":"The exhibition compares vertebrates with animals lacking backbones.","zh":"展览比较了脊椎动物与没有脊椎的动物。"}]},{"pos":"adj.","meaning":"有脊椎的；脊椎动物的","definition":"Having a backbone or relating to animals with one.","examples":[{"en":"The course covers vertebrate anatomy.","zh":"课程涵盖脊椎动物解剖学。"},{"en":"Vertebrate species occupy many different habitats.","zh":"脊椎动物物种栖息于许多不同环境。"}]}],"vertical":[{"pos":"adj.","meaning":"垂直的；竖直的","definition":"running straight up and down","examples":[{"en":"Draw a vertical line through the centre.","zh":"画一条穿过中心的竖线。"},{"en":"The climber faced a nearly vertical wall of rock.","zh":"攀登者面对一面几乎垂直的岩壁。"}]},{"pos":"n.","meaning":"垂线；竖直位置","definition":"a vertical line or direction","examples":[{"en":"The pole leans slightly away from the vertical.","zh":"这根杆子略微偏离竖直方向。"},{"en":"The diagram uses two verticals to mark the boundary.","zh":"图中用两条垂线标出边界。"}]}],"vessel":[{"pos":"n.","meaning":"船；船只","definition":"a large craft used on water","examples":[{"en":"The vessel entered the harbour at sunrise.","zh":"船在日出时驶入港口。"},{"en":"A research vessel collected samples offshore.","zh":"一艘科考船在近海采集样本。"}]},{"pos":"n.","meaning":"容器；器皿","definition":"a hollow object used to hold liquid or other material","examples":[{"en":"The liquid was heated in a glass vessel.","zh":"液体在玻璃容器中加热。"},{"en":"Archaeologists found a clay vessel near the wall.","zh":"考古学家在墙边发现了一个陶制器皿。"}]},{"pos":"n.","meaning":"血管；导管","definition":"a tube carrying fluid within a living organism","examples":[{"en":"The diagram shows the major blood vessels.","zh":"图示显示了主要血管。"},{"en":"Water moves through vessels in the plant stem.","zh":"水通过植物茎中的导管流动。"}]}],"vested":[{"pos":"adj.","meaning":"既定的；依法享有的","definition":"Established and secured as a right or interest.","examples":[{"en":"The agreement protects employees' vested rights.","zh":"协议保护员工既得权利。"},{"en":"The trustees exercised the authority vested in them.","zh":"受托人行使了赋予他们的权力。"}]}],"vet":[{"pos":"v.","meaning":"审查；仔细检查","definition":"to examine carefully before approval","examples":[{"en":"The committee vets every application.","zh":"委员会仔细审查每份申请。"},{"en":"All volunteers are vetted before joining the programme.","zh":"所有志愿者参加项目前都要接受审查。"}]},{"pos":"n.","meaning":"兽医","definition":"a doctor who treats animals","examples":[{"en":"The vet examined the injured bird.","zh":"兽医检查了受伤的小鸟。"},{"en":"We took the cat to the vet for a check-up.","zh":"我们带猫去兽医那里做检查。"}]}],"veterinarian":[{"pos":"n.","meaning":"兽医","definition":"a professional trained to treat animal illnesses and injuries","examples":[{"en":"The veterinarian examined the horse's leg.","zh":"兽医检查了马的腿。"},{"en":"She hopes to become a veterinarian after university.","zh":"她希望大学毕业后成为兽医。"}]}],"veterinary":[{"pos":"adj.","meaning":"兽医的；动物医疗的","definition":"Relating to medical care for animals.","examples":[{"en":"She applied to veterinary school.","zh":"她申请了兽医学院。"},{"en":"The shelter provides basic veterinary care.","zh":"收容所提供基本兽医护理。"}]}],"viable":[{"pos":"adj.","meaning":"可行的；能实施的","definition":"able to work successfully in practice","examples":[{"en":"The team proposed a viable alternative.","zh":"团队提出了一个可行的替代方案。"},{"en":"The business needs a viable plan for growth.","zh":"这家企业需要一个切实可行的发展计划。"}]},{"pos":"adj.","meaning":"能存活的；能发育的","definition":"capable of surviving and developing","examples":[{"en":"The test determines whether the seeds are viable.","zh":"这项测试确定种子是否具有发芽能力。"},{"en":"Only viable cells were counted in the experiment.","zh":"实验中只统计了活细胞。"}]}],"vibrant":[{"pos":"adj.","meaning":"充满活力的；生气勃勃的","definition":"full of energy and activity","examples":[{"en":"The neighbourhood has a vibrant arts scene.","zh":"这个街区的艺术活动充满活力。"},{"en":"Her vibrant personality made visitors feel welcome.","zh":"她充满朝气的个性让访客感到亲切。"}]},{"pos":"adj.","meaning":"鲜艳的；明亮的","definition":"strong and bright in colour","examples":[{"en":"The painting uses vibrant reds and oranges.","zh":"这幅画使用了鲜艳的红色和橙色。"},{"en":"Vibrant flowers filled the garden.","zh":"鲜艳的花朵开满了花园。"}]},{"pos":"adj.","meaning":"振动的；洪亮的","definition":"resonating with a strong or lively sound","examples":[{"en":"The singer's vibrant voice filled the hall.","zh":"歌手洪亮的声音响彻大厅。"},{"en":"The instrument produced a vibrant tone.","zh":"乐器发出了富有共鸣的音调。"}]}],"vibrate":[{"pos":"v.","meaning":"振动；颤动","definition":"To move quickly backwards and forwards.","examples":[{"en":"The phone vibrated in my pocket.","zh":"手机在我口袋里振动。"},{"en":"The windows vibrated as the train passed.","zh":"火车经过时，窗户震动起来。"}]}],"vice versa":[{"pos":"adv.","meaning":"反之亦然","definition":"with the order or relationship reversed","examples":[{"en":"She translates from Chinese into English, and vice versa.","zh":"她把中文翻译成英文，也把英文翻译成中文。"},{"en":"The software converts text to speech and vice versa.","zh":"这款软件把文字转为语音，也能反向转换。"}]}],"vicious":[{"pos":"adj.","meaning":"凶猛的；凶狠的","definition":"likely to attack or cause serious physical harm","examples":[{"en":"The sign warned visitors about a vicious dog.","zh":"告示提醒访客当心凶犬。"},{"en":"The character survived a vicious attack.","zh":"这个人物在一次凶狠袭击中幸存。"}]},{"pos":"adj.","meaning":"恶毒的；残忍的","definition":"deliberately cruel or malicious","examples":[{"en":"The review contained vicious personal remarks.","zh":"评论包含恶毒的人身攻击。"},{"en":"She refused to repeat the vicious rumour.","zh":"她拒绝传播那个恶毒的谣言。"}]},{"pos":"adj.","meaning":"恶性的；有害的","definition":"causing a harmful process to become worse","examples":[{"en":"The family was caught in a vicious cycle of debt.","zh":"这家人陷入了债务的恶性循环。"},{"en":"Poor sleep and worry created a vicious circle.","zh":"睡眠不足与担忧形成了恶性循环。"}]}],"victim":[{"pos":"n.","meaning":"受害者；遇难者；牺牲者","definition":"Someone harmed by an event, crime, or circumstance.","examples":[{"en":"Volunteers helped flood victims.","zh":"志愿者帮助洪灾受害者。"},{"en":"She became a victim of identity theft.","zh":"她成为身份盗用的受害者。"}]}],"victimise":[{"pos":"v.","meaning":"欺凌；迫害；使受害","definition":"to treat someone unfairly or cause them to suffer","examples":[{"en":"The policy protects workers who are victimised for raising concerns.","zh":"这项政策保护因提出疑虑而受打击报复的员工。"},{"en":"The story describes a child victimised by older pupils.","zh":"故事描述了一个遭到高年级学生欺负的孩子。"}]}],"viewpoint":[{"pos":"n.","meaning":"观点；看法","definition":"a particular way of considering an issue","examples":[{"en":"The discussion included several different viewpoints.","zh":"讨论包含了几种不同的观点。"},{"en":"Try to understand the problem from her viewpoint.","zh":"试着从她的角度理解问题。"}]},{"pos":"n.","meaning":"观景点","definition":"a place offering a good view","examples":[{"en":"We stopped at a viewpoint above the valley.","zh":"我们在山谷上方的观景点停了下来。"},{"en":"The path leads to a coastal viewpoint.","zh":"小路通向一处海岸观景点。"}]}],"vigorous":[{"pos":"adj.","meaning":"精力充沛的；有力的；强劲的","definition":"Full of energy, strength, or force.","examples":[{"en":"The proposal sparked vigorous debate.","zh":"提案引发了激烈辩论。"},{"en":"The plants showed vigorous growth.","zh":"植物长势旺盛。"}]}],"vile":[{"pos":"adj.","meaning":"糟糕透顶的；令人厌恶的","definition":"extremely unpleasant","examples":[{"en":"A vile smell came from the blocked drain.","zh":"堵塞的排水管里传来一股恶臭。"},{"en":"The weather was vile throughout the trip.","zh":"旅途中天气一直糟糕透顶。"}]},{"pos":"adj.","meaning":"卑鄙的；恶劣的","definition":"morally disgusting or wicked","examples":[{"en":"The villain's vile behaviour shocked the audience.","zh":"反派卑鄙的行为震惊了观众。"},{"en":"She condemned the vile abuse directed at the volunteers.","zh":"她谴责了针对志愿者的恶劣辱骂。"}]}],"violate":[{"pos":"v.","meaning":"违反；违背","definition":"to act against a rule, agreement, or principle","examples":[{"en":"The decision violates the agreement.","zh":"这个决定违反了协议。"},{"en":"Drivers who violate the parking rules may receive a notice.","zh":"违反停车规则的司机可能收到通知。"}]},{"pos":"v.","meaning":"侵犯；侵害","definition":"to interfere with someone's rights or protected space","examples":[{"en":"Publishing the private letters would violate her privacy.","zh":"公布私人信件会侵犯她的隐私。"},{"en":"The policy was criticised for violating basic rights.","zh":"这项政策因侵犯基本权利而受到批评。"}]},{"pos":"v.","meaning":"亵渎；扰乱神圣或安宁之物","definition":"to treat something sacred or protected with disrespect","examples":[{"en":"The vandals violated the sanctity of the shrine.","zh":"破坏者亵渎了神殿的神圣性。"},{"en":"Loud machinery violated the silence of the old cemetery.","zh":"喧闹的机器声打破了旧墓地的宁静。"}]}],"violence":[{"pos":"n.","meaning":"暴力；暴力行为","definition":"Physical force used to hurt or damage.","examples":[{"en":"The organisation campaigns against violence.","zh":"这个组织开展反暴力运动。"},{"en":"The protest ended without violence.","zh":"抗议活动在没有暴力的情况下结束。"}]},{"pos":"n.","meaning":"猛烈；剧烈；强烈","definition":"Extreme force or intensity.","examples":[{"en":"The violence of the storm damaged the pier.","zh":"暴风雨的猛烈冲击损坏了码头。"},{"en":"She was startled by the violence of his reaction.","zh":"他反应之激烈让她吃惊。"}]}],"violent":[{"pos":"adj.","meaning":"暴力的","definition":"using physical force to hurt or damage","examples":[{"en":"The protest became violent after sunset.","zh":"日落后，抗议演变为暴力冲突。"},{"en":"The school has rules against violent behaviour.","zh":"学校有禁止暴力行为的规定。"}]},{"pos":"adj.","meaning":"猛烈的；强烈的","definition":"extremely forceful or intense","examples":[{"en":"A violent storm damaged the harbour.","zh":"一场猛烈的暴风雨破坏了港口。"},{"en":"The announcement provoked a violent emotional reaction.","zh":"这项公告引发了强烈的情绪反应。"}]}],"virtual":[{"pos":"adj.","meaning":"虚拟的；在线模拟的","definition":"created or experienced through computer systems","examples":[{"en":"The museum offers a virtual tour of its galleries.","zh":"博物馆提供展厅的虚拟导览。"},{"en":"A virtual classroom connects learners in different countries.","zh":"虚拟课堂连接不同国家的学习者。"},{"en":"Virtual reality can support practical training.","zh":"虚拟现实可以辅助实操培训。"}]}],"virtually":[{"pos":"adv.","meaning":"几乎；差不多","definition":"Almost entirely.","examples":[{"en":"The two designs are virtually identical.","zh":"这两种设计几乎一样。"},{"en":"The street was virtually empty.","zh":"街道上几乎空无一人。"}]},{"pos":"adv.","meaning":"实际上；实质上","definition":"In effect, even if not formally so.","examples":[{"en":"The change virtually guarantees a longer journey.","zh":"这项变动实际上意味着旅程一定更长。"},{"en":"By refusing access, they virtually ended the project.","zh":"他们拒绝提供使用权，实际上结束了项目。"}]}],"virtue":[{"pos":"n.","meaning":"美德；德行","definition":"a good moral quality","examples":[{"en":"Patience is a useful virtue when teaching beginners.","zh":"教初学者时，耐心是一种有益的美德。"},{"en":"The story celebrates the virtue of honesty.","zh":"这个故事赞颂了诚实的美德。"}]},{"pos":"n.","meaning":"优点；长处","definition":"an advantage or useful quality","examples":[{"en":"Simplicity is the main virtue of this design.","zh":"简洁是这项设计的主要优点。"},{"en":"The plan has the virtue of being easy to explain.","zh":"这个计划的优点是容易解释。"}]}],"virtuous":[{"pos":"adj.","meaning":"有道德的；品行端正的","definition":"showing good moral principles","examples":[{"en":"The tale rewards the honest and virtuous hero.","zh":"故事让诚实正直的主人公获得了回报。"},{"en":"She tried to live a virtuous life.","zh":"她努力过一种有道德的生活。"}]},{"pos":"adj.","meaning":"自命清高的；自以为高尚的（贬义）","definition":"feeling or displaying excessive moral superiority","examples":[{"en":"He gave a virtuous smile after pointing out everyone else's faults.","zh":"指出别人的过错后，他露出自以为高尚的微笑。"},{"en":"Her virtuous tone annoyed colleagues who had also worked hard.","zh":"她自命清高的语气惹恼了同样努力工作的同事。"}]},{"pos":"adj.","meaning":"贞洁的（旧式用法）","definition":"sexually chaste, in traditional moral descriptions","examples":[{"en":"The old novel presents its heroine as virtuous and unmarried.","zh":"这部旧小说把女主人公描写为贞洁的未婚女子。"},{"en":"The historian examines how women were labelled virtuous in those texts.","zh":"历史学家探讨了那些文本如何给女性贴上贞洁标签。"}]}],"virus":[{"pos":"n.","meaning":"病毒","definition":"A tiny infectious agent that reproduces inside living cells.","examples":[{"en":"Researchers studied how the virus enters cells.","zh":"研究人员研究病毒如何进入细胞。"},{"en":"The laboratory tested the sample for viruses.","zh":"实验室检测了样本中的病毒。"}]},{"pos":"n.","meaning":"计算机病毒","definition":"Malicious code that can spread between computer files or systems.","examples":[{"en":"A virus corrupted several files.","zh":"病毒损坏了几个文件。"},{"en":"The scanner detected a computer virus.","zh":"扫描程序检测到一个电脑病毒。"}]}],"visa":[{"pos":"n.","meaning":"签证","definition":"official permission to enter or stay in a country","examples":[{"en":"She applied for a student visa.","zh":"她申请了学生签证。"},{"en":"His passport contained several old visas.","zh":"他的护照里有几张旧签证。"}]}],"viscous":[{"pos":"adj.","meaning":"黏稠的；黏滞的","definition":"thick and slow to flow","examples":[{"en":"The viscous liquid moved slowly through the tube.","zh":"黏稠的液体缓慢流过管子。"},{"en":"The mixture became more viscous as it cooled.","zh":"混合物冷却后变得更黏稠。"}]}],"visible":[{"pos":"adj.","meaning":"可见的；看得见的；明显的","definition":"Able to be seen or easily noticed.","examples":[{"en":"The island is visible from the coast.","zh":"从海岸能看见这座岛。"},{"en":"There was a visible improvement in her confidence.","zh":"她的自信有了明显改善。"}]}],"vision":[{"pos":"n.","meaning":"视力；视觉","definition":"the ability to see","examples":[{"en":"The fog reduced our vision to a few metres.","zh":"雾使我们的视野缩小到几米。"},{"en":"The examination checks colour vision.","zh":"这项检查测试色觉。"}]},{"pos":"n.","meaning":"远见；想象力；愿景","definition":"the ability to imagine a future state or a clear idea of it","examples":[{"en":"The architect shared her vision for the new library.","zh":"建筑师分享了她对新图书馆的构想。"},{"en":"A leader needs vision as well as practical skills.","zh":"领导者既需要远见，也需要实践能力。"}]},{"pos":"n.","meaning":"幻象；梦幻","definition":"an imagined image or experience that seems real","examples":[{"en":"The character sees a vision of his childhood home.","zh":"这个人物眼前浮现出童年故居的幻象。"},{"en":"The poem describes a strange vision in the night.","zh":"这首诗描写了夜间的一种奇异幻象。"}]}],"visual":[{"pos":"adj.","meaning":"视觉的；用于视觉的","definition":"relating to seeing or to what can be seen","examples":[{"en":"The teacher used visual aids to explain the process.","zh":"老师用视觉辅助材料解释了这个过程。"},{"en":"The report includes a visual comparison of the two designs.","zh":"报告对两种设计进行了直观比较。"}]}],"vital":[{"pos":"adj.","meaning":"极其重要的；生死攸关的","definition":"Essential or necessary for survival or success.","examples":[{"en":"Clean water is vital to health.","zh":"干净饮水对健康至关重要。"},{"en":"The witness provided vital evidence.","zh":"证人提供了关键证据。"}]},{"pos":"adj.","meaning":"有生命力的；充满活力的","definition":"Full of life and energy.","examples":[{"en":"She remained a vital presence in the community.","zh":"她一直是社区里充满活力的一员。"},{"en":"The performance felt fresh and vital.","zh":"表演让人觉得新鲜而有活力。"}]}],"vitality":[{"pos":"n.","meaning":"活力；生命力","definition":"energy and strength in living or activity","examples":[{"en":"The children brought vitality to the quiet house.","zh":"孩子们给安静的屋子带来了活力。"},{"en":"The festival reflects the vitality of local culture.","zh":"这个节日反映了当地文化的生命力。"}]}],"vivid":[{"pos":"adj.","meaning":"鲜艳的；明亮的","definition":"strong and clear in colour","examples":[{"en":"The curtains were a vivid shade of green.","zh":"窗帘呈鲜艳的绿色。"},{"en":"A vivid orange sunset lit the sky.","zh":"明亮的橙色晚霞照亮了天空。"}]},{"pos":"adj.","meaning":"生动的；清晰的","definition":"producing a strong and detailed mental image","examples":[{"en":"She gave a vivid account of the journey.","zh":"她生动地描述了旅程。"},{"en":"He still has vivid memories of his first school.","zh":"他仍清楚地记得第一所学校。"}]}],"vocational":[{"pos":"adj.","meaning":"职业技能的","definition":"relating to skills needed for a job","examples":[{"en":"Vocational courses prepare students for specific jobs.","zh":"职业技能课程让学生为特定工作做好准备。"},{"en":"The college provides vocational training in plumbing.","zh":"学院提供水管安装方面的职业培训。"},{"en":"Vocational education should receive adequate funding.","zh":"职业教育应获得充足经费。"}]}],"volcano":[{"pos":"n.","meaning":"火山","definition":"an opening in the Earth's crust through which hot material can erupt","examples":[{"en":"The village lies below an inactive volcano.","zh":"村庄位于一座休眠火山下方。"},{"en":"Scientists monitor gases released by the volcano.","zh":"科学家监测火山释放的气体。"}]}],"volt":[{"pos":"n.","meaning":"伏特","definition":"the unit of electric potential difference","examples":[{"en":"The label states that the battery supplies twelve volts.","zh":"标签说明电池提供十二伏电压。"},{"en":"The meter displayed a reading of five volts.","zh":"仪表显示读数为五伏。"}]}],"voltage":[{"pos":"n.","meaning":"电压","definition":"The difference in electrical potential between two points.","examples":[{"en":"The technician measured the voltage.","zh":"技术人员测量了电压。"},{"en":"The device operates at a low voltage.","zh":"装置在低电压下运行。"}]}],"volume":[{"pos":"n.","meaning":"卷；册","definition":"one book, especially as part of a set","examples":[{"en":"The history is published in three volumes.","zh":"这部历史著作分三卷出版。"},{"en":"She found the quotation in the second volume.","zh":"她在第二卷中找到了那句话。"}]},{"pos":"n.","meaning":"体积；容积","definition":"the amount of space occupied by something","examples":[{"en":"We measured the volume of water in the tank.","zh":"我们测量了水箱中水的体积。"},{"en":"The box has twice the volume of the smaller one.","zh":"这个箱子的容积是小箱子的两倍。"}]},{"pos":"n.","meaning":"音量","definition":"the loudness of a sound","examples":[{"en":"Please lower the volume of the television.","zh":"请把电视音量调低。"},{"en":"The speaker volume was too high for the small room.","zh":"对于这个小房间来说，扬声器音量太大了。"}]},{"pos":"n.","meaning":"数量；总量","definition":"the total amount of something","examples":[{"en":"The office handles a large volume of mail.","zh":"办公室处理大量邮件。"},{"en":"Traffic volume increases during the holiday.","zh":"假日期间交通流量增加。"}]}],"voluntary":[{"pos":"adj.","meaning":"自愿的；志愿的","definition":"done by free choice rather than compulsion","examples":[{"en":"Participation in the survey is voluntary.","zh":"参加调查是自愿的。"},{"en":"She does voluntary work at the community centre.","zh":"她在社区中心做志愿工作。"}]},{"pos":"adj.","meaning":"随意的；受意志控制的","definition":"controlled consciously, especially of body movement","examples":[{"en":"The lesson distinguishes voluntary movement from reflex action.","zh":"这节课区分随意运动与反射动作。"},{"en":"Raising your hand is a voluntary action.","zh":"举手是一个受意志控制的动作。"}]}],"volunteer":[{"pos":"n.","meaning":"志愿者","definition":"a person who offers to help without being paid","examples":[{"en":"A volunteer showed us around the centre.","zh":"一位志愿者带我们参观了中心。"},{"en":"Each volunteer receives basic first-aid training.","zh":"每位志愿者都会接受基础急救培训。"},{"en":"She works as a volunteer at the local library.","zh":"她在当地图书馆做志愿者。"}]},{"pos":"v.","meaning":"自愿做；无偿提供","definition":"To offer freely to do something or provide information.","examples":[{"en":"She volunteered to organise the event.","zh":"她自愿组织活动。"},{"en":"He volunteered his time at the shelter.","zh":"他在收容所无偿付出自己的时间。"}]},{"pos":"adj.","meaning":"志愿的；义务的；无偿的","definition":"Working or provided willingly without being required or paid.","examples":[{"en":"Volunteer guides lead the tours.","zh":"志愿导游带领参观。"},{"en":"The village relies on a volunteer fire service.","zh":"村庄依靠志愿消防服务。"}]}],"vomit":[{"pos":"v.","meaning":"呕吐","definition":"to bring stomach contents back through the mouth","examples":[{"en":"The passenger vomited during the rough crossing.","zh":"渡海时风浪很大，那位乘客吐了。"},{"en":"The nurse asked whether the patient had vomited.","zh":"护士询问患者是否吐过。"}]},{"pos":"v.","meaning":"喷出；吐出（比喻）","definition":"to eject material forcefully","examples":[{"en":"The damaged pipe vomited dirty water into the street.","zh":"破裂的管道把污水喷到街上。"},{"en":"The old chimney vomited smoke into the sky.","zh":"旧烟囱向天空喷出浓烟。"}]},{"pos":"n.","meaning":"呕吐物","definition":"material brought up from the stomach","examples":[{"en":"The cleaner found vomit beside the seat.","zh":"清洁工发现座位旁有呕吐物。"},{"en":"The sample contained traces of vomit.","zh":"样本中含有呕吐物痕迹。"}]},{"pos":"n.","meaning":"催吐剂（罕见旧用法）","definition":"a substance used to cause vomiting, in old usage","examples":[{"en":"The historical ledger lists a vomit among the remedies.","zh":"这份历史账簿在药品中列出了一种催吐剂。"},{"en":"The old account records payment for a vomit supplied by an apothecary.","zh":"旧账目记载了购买药剂师所供催吐剂的付款。"}]}],"voyage":[{"pos":"n.","meaning":"航行；航海旅行","definition":"a long journey, especially by sea or in space","examples":[{"en":"The voyage across the ocean lasted several weeks.","zh":"横跨大洋的航程持续了几周。"},{"en":"The diary describes the ship's first voyage.","zh":"日记描述了船的第一次航行。"}]},{"pos":"v.","meaning":"航行；远航","definition":"to travel on a long journey by sea or in space","examples":[{"en":"They voyaged along the coast in a small boat.","zh":"他们乘小船沿海岸航行。"},{"en":"The explorers voyaged far beyond familiar waters.","zh":"探险者远航到远离熟悉水域的地方。"}]}],"vulgar":[{"pos":"adj.","meaning":"粗俗的；庸俗的；下流的","definition":"Lacking good taste or using offensive language.","examples":[{"en":"His vulgar jokes offended the guests.","zh":"他的粗俗笑话冒犯了客人。"},{"en":"She thought the extravagant display was vulgar.","zh":"她认为那种奢华炫耀很庸俗。"}]},{"pos":"adj.","meaning":"民众的；通俗的（旧用法）","definition":"Relating to ordinary people or their everyday language.","examples":[{"en":"The text was translated from Latin into the vulgar tongue.","zh":"文本从拉丁语翻译成了民间通俗语言。"},{"en":"The historian studied the vulgar beliefs of the period.","zh":"历史学家研究了那个时期的民间观念。"}]}],"vulnerable":[{"pos":"adj.","meaning":"易受伤害的；脆弱的","definition":"easily harmed or affected by danger","examples":[{"en":"Young plants are vulnerable to frost.","zh":"幼苗容易遭受霜冻。"},{"en":"The report identifies groups vulnerable to sudden price rises.","zh":"报告识别了容易受到价格骤涨影响的群体。"}]}],"wage":[{"pos":"n.","meaning":"工资；报酬","definition":"money paid to a worker for their labour","examples":[{"en":"The workers received their wages on Friday.","zh":"工人们在星期五领到了工资。"},{"en":"She earns a fair wage for skilled work.","zh":"她凭技术工作获得合理报酬。"}]},{"pos":"v.","meaning":"开展；发动（运动或斗争）","definition":"to carry on a campaign or struggle","examples":[{"en":"The group waged a campaign to protect the park.","zh":"这个团体开展了一场保护公园的运动。"},{"en":"The company waged a long battle against counterfeit goods.","zh":"公司长期打击假冒产品。"}]}],"wagon":[{"pos":"n.","meaning":"四轮运货马车；大篷车；货车","definition":"A vehicle used for carrying goods, especially a four-wheeled cart.","examples":[{"en":"The horse pulled a wagon loaded with hay.","zh":"马拉着一辆装满干草的四轮车。"},{"en":"The family travelled west in a covered wagon.","zh":"这家人乘大篷车向西旅行。"}]}],"waist":[{"pos":"n.","meaning":"腰；腰部","definition":"the part of the body between the ribs and hips","examples":[{"en":"The jacket fits closely around the waist.","zh":"这件夹克在腰部很贴身。"},{"en":"She tied a belt around her waist.","zh":"她在腰间系了一条腰带。"}]}],"wander":[{"pos":"v.","meaning":"漫步；闲逛","definition":"to walk without a fixed route or purpose","examples":[{"en":"We wandered through the old market.","zh":"我们在老市场里闲逛。"},{"en":"She likes to wander along the river after work.","zh":"她喜欢下班后沿河漫步。"}]},{"pos":"v.","meaning":"偏离；离开原路线","definition":"to move away from the intended path or subject","examples":[{"en":"The discussion wandered away from the main issue.","zh":"讨论偏离了主要议题。"},{"en":"The sheep wandered out of the field.","zh":"羊走出了田地。"}]},{"pos":"v.","meaning":"走神；思绪游移","definition":"to lose concentration and think of other things","examples":[{"en":"My mind began to wander during the long speech.","zh":"冗长的讲话让我开始走神。"},{"en":"His attention wandered towards the open window.","zh":"他的注意力转向了敞开的窗户。"}]}],"warrant":[{"pos":"v.","meaning":"使有正当理由；值得","definition":"To justify or make something necessary.","examples":[{"en":"The damage warrants further investigation.","zh":"损坏情况值得进一步调查。"},{"en":"The results do not warrant such a strong conclusion.","zh":"结果不足以支持如此强烈的结论。"}]},{"pos":"v.","meaning":"保证；担保","definition":"To assure that something is true or meets a condition.","examples":[{"en":"The seller warrants that the goods are new.","zh":"卖方保证货物为新品。"},{"en":"The manufacturer warrants the device against defects.","zh":"制造商保证设备没有缺陷。"}]},{"pos":"n.","meaning":"授权令；许可证；搜查令或逮捕令","definition":"An official document authorising an action.","examples":[{"en":"The police obtained a search warrant.","zh":"警方取得了搜查令。"},{"en":"The officer checked the warrant before entering.","zh":"警官进入前检查了授权令。"}]}],"warranty":[{"pos":"n.","meaning":"保修承诺；保修期","definition":"a promise to repair or replace a product if it fails","examples":[{"en":"The washing machine comes with a two-year warranty.","zh":"这台洗衣机附带两年保修。"},{"en":"Damage caused by misuse is not covered by the warranty.","zh":"误用造成的损坏不在保修范围内。"},{"en":"Check whether the warranty includes repair costs.","zh":"请核实保修是否包含维修费。"}]}],"wastage":[{"pos":"n.","meaning":"浪费；损耗量","definition":"material or resources lost without useful result","examples":[{"en":"Careful planning reduced food wastage.","zh":"周密计划减少了食物浪费。"},{"en":"The factory measures wastage at each production stage.","zh":"工厂测量每个生产阶段的损耗量。"}]},{"pos":"n.","meaning":"自然减员；人员流失","definition":"a reduction in staff as people leave and are not replaced","examples":[{"en":"The firm reduced staff through natural wastage.","zh":"公司通过自然减员减少了员工数量。"},{"en":"High wastage among new recruits worried the manager.","zh":"新员工的大量流失让经理担忧。"}]}],"water-borne":[{"pos":"adj.","meaning":"水传播的；经饮水传播的","definition":"Carried or spread by water.","examples":[{"en":"The project aims to reduce water-borne disease.","zh":"项目旨在减少水传播疾病。"},{"en":"Tests detected water-borne contaminants.","zh":"检测发现了水传播的污染物。"}]},{"pos":"adj.","meaning":"水运的；水上运载的","definition":"Transported on water.","examples":[{"en":"The canal carries water-borne freight.","zh":"运河承运水上货物。"},{"en":"Water-borne trade helped the port expand.","zh":"水运贸易帮助港口扩张。"}]}],"waterfront":[{"pos":"n.","meaning":"滨水区；码头区","definition":"the part of a town beside a river, lake, or sea","examples":[{"en":"Restaurants line the waterfront.","zh":"餐馆沿着滨水区排列。"},{"en":"The city plans to improve access to the waterfront.","zh":"这座城市计划改善通往滨水区的交通。"}]}],"waterproof":[{"pos":"adj.","meaning":"防水的；不透水的","definition":"preventing water from passing through","examples":[{"en":"Wear a waterproof jacket on the hike.","zh":"徒步时穿一件防水夹克。"},{"en":"The documents were kept in a waterproof bag.","zh":"文件放在一个防水袋里。"}]},{"pos":"v.","meaning":"使防水","definition":"to treat a material so water cannot pass through it","examples":[{"en":"The builders waterproofed the roof.","zh":"施工人员给屋顶做了防水处理。"},{"en":"This coating helps waterproof the fabric.","zh":"这种涂层有助于使布料防水。"}]}],"wax":[{"pos":"n.","meaning":"蜡；蜂蜡","definition":"A substance that softens with heat and is used for candles or polishing.","examples":[{"en":"The candle dripped wax onto the table.","zh":"蜡烛把蜡滴到了桌上。"},{"en":"She sealed the envelope with wax.","zh":"她用蜡封住信封。"}]},{"pos":"v.","meaning":"给……打蜡；上蜡","definition":"To apply a coating of wax.","examples":[{"en":"He waxed the wooden floor.","zh":"他给木地板打了蜡。"},{"en":"The skis were waxed before the race.","zh":"比赛前给滑雪板上了蜡。"}]},{"pos":"v.","meaning":"渐圆；渐满（指月亮）","definition":"To show an increasing illuminated area.","examples":[{"en":"The Moon waxes between the new and full phases.","zh":"月亮在新月与满月之间渐渐变圆。"},{"en":"We watched the waxing moon over several evenings.","zh":"我们连续几个晚上观察渐圆的月亮。"}]}],"weaken":[{"pos":"v.","meaning":"削弱；变弱","definition":"to make or become less strong","examples":[{"en":"The long drought weakened the trees.","zh":"长期干旱使树木变弱。"},{"en":"The new evidence weakened his argument.","zh":"新证据削弱了他的论点。"}]}],"weakness":[{"pos":"n.","meaning":"虚弱；无力","definition":"a lack of physical strength or energy","examples":[{"en":"She felt weakness in her legs after the climb.","zh":"爬山后，她感到双腿无力。"},{"en":"The patient described a period of unusual weakness.","zh":"患者描述了一段异常虚弱的时期。"}]},{"pos":"n.","meaning":"缺点；弱点","definition":"a fault or limitation","examples":[{"en":"The report identifies a weakness in the design.","zh":"报告指出了设计中的一个弱点。"},{"en":"Every method has strengths and weaknesses.","zh":"每种方法都有优点和缺点。"}]},{"pos":"n.","meaning":"偏爱；嗜好","definition":"a strong liking that is difficult to resist","examples":[{"en":"He has a weakness for old maps.","zh":"他对旧地图格外着迷。"},{"en":"Chocolate is her one weakness.","zh":"巧克力是她难以抗拒的偏爱。"}]}],"wealthy":[{"pos":"adj.","meaning":"富裕的；有钱的；丰富的","definition":"Having a great amount of money or resources.","examples":[{"en":"A wealthy donor funded the library.","zh":"一位富裕捐助者资助了图书馆。"},{"en":"The region is wealthy in natural resources.","zh":"这个地区自然资源丰富。"}]}],"wean":[{"pos":"v.","meaning":"断奶","definition":"to gradually stop feeding milk as the main food","examples":[{"en":"The young animals were weaned during spring.","zh":"这些幼崽在春季断奶。"},{"en":"The farm keeps recently weaned calves in a separate area.","zh":"农场把刚断奶的小牛放在单独区域。"}]},{"pos":"v.","meaning":"使戒掉；使摆脱依赖（wean off）","definition":"to gradually reduce dependence on something","examples":[{"en":"The programme aims to wean students off constant translation.","zh":"这个项目旨在让学生逐渐摆脱对不断翻译的依赖。"},{"en":"The company is trying to wean itself off paper records.","zh":"公司正努力逐步摆脱对纸质记录的依赖。"}]}],"weapon":[{"pos":"n.","meaning":"武器；兵器","definition":"an object used to attack or defend","examples":[{"en":"The museum displays ancient weapons behind glass.","zh":"博物馆在玻璃后陈列古代武器。"},{"en":"The guard asked visitors to leave any weapons outside.","zh":"警卫要求访客把任何武器留在外面。"}]},{"pos":"n.","meaning":"有力手段；工具（比喻）","definition":"something used to gain an advantage in a struggle","examples":[{"en":"Accurate information is a useful weapon against rumours.","zh":"准确信息是对抗谣言的有力工具。"},{"en":"Humour became her strongest weapon in the debate.","zh":"幽默成了她在辩论中最有力的手段。"}]}],"wedge":[{"pos":"n.","meaning":"楔子；楔形物","definition":"A piece thick at one end and tapering to a thin edge.","examples":[{"en":"He placed a wedge under the door.","zh":"他在门下放了楔子。"},{"en":"She cut a wedge of cheese.","zh":"她切了一块楔形奶酪。"}]},{"pos":"v.","meaning":"楔入；塞入；卡住","definition":"To force something into a narrow space or secure it tightly.","examples":[{"en":"The box was wedged between two chairs.","zh":"箱子卡在两把椅子之间。"},{"en":"She wedged the door open with a stone.","zh":"她用石头卡住门，使它保持打开。"}]}],"weed":[{"pos":"n.","meaning":"杂草","definition":"a plant growing where it is not wanted","examples":[{"en":"Weeds grew between the paving stones.","zh":"铺路石之间长出了杂草。"},{"en":"The gardener removed a weed from the flower bed.","zh":"园丁从花坛里拔出一株杂草。"}]},{"pos":"v.","meaning":"除草","definition":"to remove unwanted plants","examples":[{"en":"We weed the vegetable beds every weekend.","zh":"我们每个周末都给菜畦除草。"},{"en":"She spent the morning weeding around the young trees.","zh":"她整个上午都在幼树周围除草。"}]}],"weigh":[{"pos":"v.","meaning":"称重","definition":"to measure how heavy something is","examples":[{"en":"The assistant weighed the parcel before posting it.","zh":"助理寄包裹前称了重量。"},{"en":"Weigh the flour before adding it to the bowl.","zh":"先称好面粉，再加入碗中。"}]},{"pos":"v.","meaning":"重达","definition":"to have a particular weight","examples":[{"en":"The suitcase weighs eighteen kilograms.","zh":"这个旅行箱重十八公斤。"},{"en":"The newborn calf weighed more than expected.","zh":"这头新生小牛比预期更重。"}]},{"pos":"v.","meaning":"权衡；认真考虑","definition":"to consider the relative importance of different factors","examples":[{"en":"We weighed the benefits against the costs.","zh":"我们权衡了收益与成本。"},{"en":"She is weighing whether to accept the offer.","zh":"她正认真考虑是否接受邀请。"}]}],"welfare":[{"pos":"n.","meaning":"福利；福祉","definition":"people's wellbeing or support provided for those in need","examples":[{"en":"The government should protect children's welfare.","zh":"政府应保护儿童福祉。"},{"en":"Social welfare provides support during unemployment.","zh":"社会福利在失业期间提供支持。"},{"en":"Animal welfare is an important concern on farms.","zh":"动物福利是农场的一项重要关切。"}]}],"well-being":[{"pos":"n.","meaning":"健康幸福；福祉","definition":"a state of being healthy, comfortable, and content","examples":[{"en":"The school places importance on student well-being.","zh":"学校重视学生的身心健康。"},{"en":"Green spaces can contribute to community well-being.","zh":"绿地有助于增进社区福祉。"}]}],"whaling":[{"pos":"n.","meaning":"捕鲸","definition":"the practice or industry of hunting whales","examples":[{"en":"The museum examines the history of whaling.","zh":"博物馆介绍捕鲸业的历史。"},{"en":"The documentary explores the effects of commercial whaling.","zh":"纪录片探讨了商业捕鲸的影响。"}]}],"wheelchair":[{"pos":"n.","meaning":"轮椅","definition":"A wheeled chair for someone who has difficulty walking.","examples":[{"en":"The entrance has a ramp for wheelchairs.","zh":"入口有轮椅坡道。"},{"en":"She moved her wheelchair closer to the table.","zh":"她把轮椅移到更靠近桌子的地方。"}]}],"whereas":[{"pos":"conj.","meaning":"然而；而","definition":"used to contrast two facts","examples":[{"en":"Urban residents have frequent buses, whereas rural residents may not.","zh":"城市居民有频繁的公交班次，而农村居民可能没有。"},{"en":"The first option is cheap, whereas the second is more convenient.","zh":"第一种选择便宜，而第二种更方便。"},{"en":"Some people prefer working alone, whereas others enjoy teamwork.","zh":"有些人喜欢独自工作，而另一些人喜欢团队合作。"}]}],"while":[{"pos":"conj.","meaning":"当……时；在……期间","definition":"during the time that something else is happening","examples":[{"en":"Please keep quiet while the recording is playing.","zh":"播放录音时请保持安静。"},{"en":"I listened to the news while I was cooking dinner.","zh":"我做晚饭时听了新闻。"}]},{"pos":"conj.","meaning":"而；然而","definition":"used to contrast two different facts or situations","examples":[{"en":"Some students prefer studying alone, while others work better in groups.","zh":"有些学生喜欢独自学习，而另一些学生小组学习效果更好。"},{"en":"The first route is shorter, while the second is much quieter.","zh":"第一条路线较短，而第二条安静得多。"}]},{"pos":"conj.","meaning":"虽然；尽管","definition":"used to introduce a fact that does not prevent the main statement being true","examples":[{"en":"While the plan is promising, it still needs more funding.","zh":"虽然这个计划很有前景，但仍需要更多资金。"},{"en":"While I understand your concern, I disagree with your conclusion.","zh":"尽管我理解你的担忧，但我不同意你的结论。"}]},{"pos":"n.","meaning":"一会儿；一段时间","definition":"a period of time","examples":[{"en":"Please wait here for a while.","zh":"请在这里等一会儿。"},{"en":"It took a while to get used to the new timetable.","zh":"适应新的时间表花了一段时间。"}]},{"pos":"v.","meaning":"消磨时光","definition":"to spend time pleasantly, usually followed by away","examples":[{"en":"We while away the afternoon reading beside the river.","zh":"我们在河边读书，悠闲地度过了下午。"},{"en":"Visitors can while away an hour in the small garden.","zh":"游客可以在小花园里悠闲地消磨一个小时。"}]}],"whisper":[{"pos":"v.","meaning":"低语；耳语","definition":"to speak very quietly","examples":[{"en":"She whispered the answer to her friend.","zh":"她低声告诉朋友答案。"},{"en":"Please do not whisper during the performance.","zh":"演出时请不要交头接耳。"}]},{"pos":"n.","meaning":"低语；耳语","definition":"very quiet speech","examples":[{"en":"His voice dropped to a whisper.","zh":"他的声音压低成了耳语。"},{"en":"I could hear a whisper from the next room.","zh":"我能听到隔壁房间的低语声。"}]}],"whistle":[{"pos":"v.","meaning":"吹口哨；发出哨声；呼啸","definition":"To produce a high sound by blowing or moving rapidly through air.","examples":[{"en":"He whistled a familiar tune.","zh":"他用口哨吹着熟悉的曲调。"},{"en":"The wind whistled through the broken window.","zh":"风穿过破窗呼啸作响。"}]},{"pos":"n.","meaning":"口哨；哨子；呼啸声","definition":"A high sound or a small instrument used to produce it.","examples":[{"en":"The referee blew the whistle.","zh":"裁判吹响了哨子。"},{"en":"We heard the whistle of a distant train.","zh":"我们听到远处火车的汽笛声。"}]}],"widespread":[{"pos":"adj.","meaning":"广泛的；普遍的","definition":"existing or happening over a large area or among many people","examples":[{"en":"The change received widespread support.","zh":"这项变革获得了广泛支持。"},{"en":"Flooding caused widespread damage to roads.","zh":"洪水对道路造成了大面积破坏。"}]}],"wildlife":[{"pos":"n.","meaning":"野生生物","definition":"animals and plants living in natural conditions","examples":[{"en":"The wetland supports a wide variety of wildlife.","zh":"湿地养育了多种野生生物。"},{"en":"Visitors should avoid disturbing the wildlife.","zh":"游客应避免惊扰野生生物。"}]}],"willing":[{"pos":"adj.","meaning":"愿意的；乐意的；积极配合的","definition":"Ready and happy to do something.","examples":[{"en":"She is willing to help with the move.","zh":"她愿意帮忙搬家。"},{"en":"We need willing volunteers for Saturday.","zh":"我们需要自愿在周六帮忙的志愿者。"}]}],"windscreen":[{"pos":"n.","meaning":"挡风玻璃","definition":"the front glass of a motor vehicle","examples":[{"en":"Rain covered the windscreen.","zh":"雨水布满了挡风玻璃。"},{"en":"A small stone cracked the windscreen.","zh":"一颗小石子把挡风玻璃砸裂了。"}]}],"wire":[{"pos":"n.","meaning":"金属丝","definition":"metal drawn into a long thin flexible strand","examples":[{"en":"She bent the wire into a small loop.","zh":"她把金属丝弯成了一个小环。"},{"en":"The fence is made of strong steel wire.","zh":"篱笆由结实的钢丝制成。"}]},{"pos":"n.","meaning":"电线","definition":"a metal conductor carrying electric current or signals","examples":[{"en":"A loose wire caused the lamp to flicker.","zh":"一根松动电线使灯闪烁。"},{"en":"The electrician replaced the damaged wire.","zh":"电工更换了损坏的电线。"}]},{"pos":"v.","meaning":"给……接电线","definition":"to connect equipment or a building with electrical wiring","examples":[{"en":"The house was wired before the walls were finished.","zh":"房屋在墙面完工前铺好了电线。"},{"en":"The technician wired the sensor to the control unit.","zh":"技术员把传感器接到了控制单元上。"}]}],"withdraw":[{"pos":"v.","meaning":"提取款项","definition":"to take money out of an account","examples":[{"en":"I need to withdraw some cash before the trip.","zh":"旅行前我需要取些现金。"},{"en":"You can withdraw money from this machine.","zh":"你可以在这台机器上取款。"},{"en":"Customers may withdraw up to three hundred pounds daily.","zh":"顾客每天最多可提取三百英镑。"}]},{"pos":"v.","meaning":"撤回；收回；撤销","definition":"To take something back or remove it from use.","examples":[{"en":"She withdrew her application.","zh":"她撤回了申请。"},{"en":"The company withdrew the unsafe product.","zh":"公司撤回了不安全产品。"}]},{"pos":"v.","meaning":"撤退；退出；离开","definition":"To move away or stop participating.","examples":[{"en":"The troops withdrew from the valley.","zh":"部队撤出了山谷。"},{"en":"He withdrew from the competition after an injury.","zh":"受伤后，他退出了比赛。"}]},{"pos":"v.","meaning":"缩回；抽出","definition":"To pull a body part or object back.","examples":[{"en":"She withdrew her hand from the hot surface.","zh":"她把手从烫的表面缩了回来。"},{"en":"The technician withdrew the probe slowly.","zh":"技术人员慢慢抽出了探针。"}]}],"withstand":[{"pos":"v.","meaning":"抵挡；承受住","definition":"to remain strong despite a force or difficulty","examples":[{"en":"The roof is designed to withstand heavy snow.","zh":"这个屋顶的设计能够承受厚重积雪。"},{"en":"The explanation did not withstand close examination.","zh":"这个解释经不起仔细推敲。"}]}],"witness":[{"pos":"n.","meaning":"目击者；证人","definition":"a person who sees an event or gives evidence about it","examples":[{"en":"A witness described the vehicle to the police.","zh":"一位目击者向警方描述了那辆车。"},{"en":"The witness answered questions clearly.","zh":"证人清楚地回答了问题。"}]},{"pos":"n.","meaning":"证据；见证","definition":"evidence showing that something happened or is true","examples":[{"en":"The old walls bear witness to centuries of change.","zh":"这些古墙见证了数百年的变迁。"},{"en":"The photographs stand as witness to the village's past.","zh":"这些照片是村庄过去的见证。"}]},{"pos":"v.","meaning":"目击；见证","definition":"to see an event happen","examples":[{"en":"Several passengers witnessed the accident.","zh":"几位乘客目击了事故。"},{"en":"The town has witnessed rapid growth.","zh":"这座城镇经历了迅速发展。"}]},{"pos":"v.","meaning":"为……作证；见证签署","definition":"to confirm an event or signature as an observer","examples":[{"en":"Two people witnessed the signing of the agreement.","zh":"两人见证了协议签署。"},{"en":"She was asked to witness his signature.","zh":"她被请来为他的签名作证。"}]}],"womb":[{"pos":"n.","meaning":"子宫","definition":"The organ in which a baby develops before birth.","examples":[{"en":"The scan showed the baby inside the womb.","zh":"扫描显示了子宫内的胎儿。"},{"en":"The lesson explains development in the womb.","zh":"课程讲解胎儿在子宫中的发育。"}]},{"pos":"n.","meaning":"发源地；孕育之地（比喻）","definition":"A place where something originates or develops.","examples":[{"en":"The valley became the womb of a new civilisation.","zh":"这个山谷成了新文明的孕育之地。"},{"en":"The movement emerged from the womb of the university.","zh":"这场运动从大学这一发源地兴起。"}]}],"wonder":[{"pos":"v.","meaning":"想知道；纳闷","definition":"to think about something with curiosity or uncertainty","examples":[{"en":"I wonder why the shop is closed.","zh":"我想知道商店为什么关门了。"},{"en":"She wondered whether the message had arrived.","zh":"她纳闷消息是否已经送达。"}]},{"pos":"v.","meaning":"感到惊奇（wonder at）","definition":"to feel surprised or amazed by something","examples":[{"en":"We wondered at the skill of the young musicians.","zh":"我们对年轻音乐家们的技艺感到惊叹。"},{"en":"Visitors wonder at the size of the ancient stones.","zh":"游客惊叹于这些古代巨石的体量。"}]},{"pos":"n.","meaning":"惊奇；惊叹","definition":"a feeling of amazement","examples":[{"en":"The children watched the fireworks in wonder.","zh":"孩子们惊叹地看着烟花。"},{"en":"Her voice was filled with wonder at the discovery.","zh":"这次发现使她的声音充满惊喜。"}]},{"pos":"n.","meaning":"奇迹；奇观","definition":"something remarkable that causes amazement","examples":[{"en":"The cave is a natural wonder.","zh":"这个洞穴是一处自然奇观。"},{"en":"It is a wonder that the fragile vase survived.","zh":"这只易碎花瓶能够保存下来，真是奇迹。"}]}],"workaholic":[{"pos":"n.","meaning":"工作狂","definition":"a person who works excessively and finds it hard to stop","examples":[{"en":"His friends worry that he has become a workaholic.","zh":"朋友们担心他已经成了工作狂。"},{"en":"The novel follows a workaholic learning to make time for family.","zh":"小说讲述了一个工作狂学着为家人留出时间的故事。"}]}],"workforce":[{"pos":"n.","meaning":"全体员工；劳动力；劳动人口","definition":"The people employed by an organisation or available for work.","examples":[{"en":"The company doubled its workforce.","zh":"公司员工人数翻了一番。"},{"en":"The report examines changes in the national workforce.","zh":"报告考察全国劳动力的变化。"}]}],"world-wide":[{"pos":"adj.","meaning":"全球的；世界范围的","definition":"extending across the world","examples":[{"en":"The exhibition attracted world-wide interest.","zh":"这场展览引起了全球关注。"},{"en":"The organisation has a world-wide network of volunteers.","zh":"这个组织拥有遍布全球的志愿者网络。"}]},{"pos":"adv.","meaning":"在全世界；遍及全球","definition":"throughout the world","examples":[{"en":"The book is sold world-wide.","zh":"这本书在全世界销售。"},{"en":"The announcement was broadcast world-wide.","zh":"这项公告向全球播出。"}]}],"worm":[{"pos":"n.","meaning":"蠕虫；虫","definition":"a small animal with a long soft body and no legs","examples":[{"en":"A worm moved through the damp soil.","zh":"一条蠕虫在潮湿土壤里蠕动。"},{"en":"The bird pulled a worm from the lawn.","zh":"鸟从草坪中叼出一条虫。"}]},{"pos":"n.","meaning":"蜗杆","definition":"a screw-like mechanical part that drives a gear","examples":[{"en":"The worm turns the gear at a reduced speed.","zh":"蜗杆以较低速度带动齿轮。"},{"en":"The mechanic inspected the worm for wear.","zh":"机械师检查了蜗杆的磨损情况。"}]}],"worthwhile":[{"pos":"adj.","meaning":"值得花时间或金钱的；值得做的","definition":"Valuable enough to justify the effort or expense.","examples":[{"en":"The training was a worthwhile investment.","zh":"培训是一项值得的投资。"},{"en":"The climb was difficult but worthwhile.","zh":"攀登很困难，但值得。"}]}],"worthy":[{"pos":"adj.","meaning":"值得的；配得上的","definition":"deserving a particular response or treatment","examples":[{"en":"Her efforts are worthy of recognition.","zh":"她的努力值得肯定。"},{"en":"The proposal is worthy of serious consideration.","zh":"这项提议值得认真考虑。"}]},{"pos":"adj.","meaning":"有价值的；可敬的","definition":"having good qualities or serving a worthwhile purpose","examples":[{"en":"They raised money for a worthy cause.","zh":"他们为一项有价值的事业筹款。"},{"en":"The committee chose a worthy candidate.","zh":"委员会选出了一位可敬的候选人。"}]}],"wrap":[{"pos":"v.","meaning":"包裹；缠绕","definition":"to cover or wind material around something","examples":[{"en":"Wrap the glass carefully before packing it.","zh":"装箱前把玻璃杯仔细包好。"},{"en":"She wrapped a scarf around her neck.","zh":"她把围巾围在脖子上。"}]},{"pos":"n.","meaning":"披肩；裹身外衣","definition":"a piece of clothing worn loosely around the shoulders","examples":[{"en":"She brought a light wrap for the cool evening.","zh":"她带了一条薄披肩应对凉爽的夜晚。"},{"en":"The woollen wrap kept her warm on the terrace.","zh":"羊毛披肩让她在露台上保持温暖。"}]}],"wrestle":[{"pos":"v.","meaning":"摔跤；扭打","definition":"To struggle physically with another person by grappling.","examples":[{"en":"The athletes wrestled on the mat.","zh":"运动员在垫子上摔跤。"},{"en":"The brothers wrestled playfully on the grass.","zh":"兄弟俩在草地上嬉戏扭打。"}]},{"pos":"v.","meaning":"努力应对；费力处理","definition":"To struggle with a difficult problem or object.","examples":[{"en":"She wrestled with the decision for days.","zh":"她为这个决定纠结了数日。"},{"en":"He wrestled the heavy suitcase into the car.","zh":"他费力地把沉重行李箱塞进车里。"}]}],"wretch":[{"pos":"n.","meaning":"不幸的人；可怜的人（文学用语）","definition":"a person deserving pity because of suffering","examples":[{"en":"The traveller gave the poor wretch a warm coat.","zh":"旅人给了那个可怜人一件暖和的大衣。"},{"en":"The novel follows a lonely wretch searching for shelter.","zh":"小说讲述了一个孤苦的人寻找栖身处的故事。"}]},{"pos":"n.","meaning":"可恶的人；坏蛋（文学贬称）","definition":"a person regarded with strong disapproval","examples":[{"en":"The villain is portrayed as a selfish wretch.","zh":"这个反派被描绘成一个自私的坏蛋。"},{"en":"The narrator calls the thief a dishonest wretch.","zh":"叙述者把小偷称作一个不诚实的恶棍。"}]}],"wrinkle":[{"pos":"n.","meaning":"皱纹；褶皱","definition":"a small line or fold in skin or material","examples":[{"en":"Fine wrinkles appeared around his eyes.","zh":"他的眼周出现了细纹。"},{"en":"There was a wrinkle in the freshly folded shirt.","zh":"刚叠好的衬衫上有一道褶皱。"}]},{"pos":"v.","meaning":"起皱；使起皱","definition":"to form or cause small folds","examples":[{"en":"The fabric wrinkles easily in a suitcase.","zh":"这种布料放在旅行箱里容易起皱。"},{"en":"She wrinkled her nose at the strange smell.","zh":"闻到奇怪气味时，她皱起了鼻子。"}]}],"yield":[{"pos":"n.","meaning":"产量；收成；收益","definition":"The amount produced or returned.","examples":[{"en":"The crop produced a high yield.","zh":"作物产量很高。"},{"en":"The new method increased the yield of usable material.","zh":"新方法提高了可用材料的产出率。"}]},{"pos":"v.","meaning":"出产；产生；带来","definition":"To produce a result or amount.","examples":[{"en":"The experiment yielded useful data.","zh":"实验产生了有用数据。"},{"en":"These trees yield fruit every summer.","zh":"这些树每年夏天结果。"}]},{"pos":"v.","meaning":"让步；放弃；交出","definition":"To give way or surrender something.","examples":[{"en":"The driver yielded to approaching traffic.","zh":"司机给驶来的车辆让行。"},{"en":"She refused to yield control of the project.","zh":"她拒绝交出项目控制权。"}]}],"zone":[{"pos":"n.","meaning":"地区；区域；地带","definition":"an area with a particular purpose or characteristic","examples":[{"en":"The school lies inside a quiet residential zone.","zh":"学校位于一个安静的住宅区内。"},{"en":"This zone is reserved for pedestrians.","zh":"这个区域专供行人使用。"}]},{"pos":"v.","meaning":"划区；按用途分区","definition":"to divide land into areas for particular uses","examples":[{"en":"The council zoned the land for housing.","zh":"市政委员会把这块地划为住宅用地。"},{"en":"The site is zoned for industrial development.","zh":"这片土地被划定用于工业开发。"}]}],"zoological":[{"pos":"adj.","meaning":"动物学的","definition":"relating to the scientific study of animals","examples":[{"en":"The museum houses a large zoological collection.","zh":"博物馆收藏了大量动物学标本。"},{"en":"The expedition gathered zoological data from the island.","zh":"考察队从岛上收集了动物学数据。"}]}]};
